_DB_POOL: psycopg2.pool.ThreadedConnectionPool | None = None
_DB_POOL_LOCK = threading.Lock()
_RUNTIME_BINDING: _runtime_environment.RuntimeBinding | None = None
_RUNTIME_IDENTITY: _runtime_environment.RuntimeIdentity | None = None
_RUNTIME_BINDING_LOCK = threading.Lock()


def assert_runtime_environment_binding() -> _runtime_environment.RuntimeIdentity:
    """Validate one immutable app-environment/database identity per process."""
    global _RUNTIME_BINDING, _RUNTIME_IDENTITY
    if _RUNTIME_IDENTITY is not None:
        return _RUNTIME_IDENTITY
    with _RUNTIME_BINDING_LOCK:
        if _RUNTIME_IDENTITY is not None:
            return _RUNTIME_IDENTITY
        binding = _runtime_environment.resolve_runtime_binding(os.environ)
        conn = psycopg2.connect(
            binding.database_url,
            cursor_factory=RealDictCursor,
            application_name=f"wathefni_{binding.application_environment}_identity_check",
        )
        try:
            conn.set_session(readonly=True, autocommit=True)
            identity = _runtime_environment.validate_database_identity(conn, binding)
        finally:
            conn.close()
        _RUNTIME_BINDING = binding
        _RUNTIME_IDENTITY = identity
        return identity


def runtime_environment_readiness() -> dict[str, Any]:
    identity = assert_runtime_environment_binding()
    return identity.public()


def runtime_binding() -> _runtime_environment.RuntimeBinding:
    assert_runtime_environment_binding()
    if _RUNTIME_BINDING is None:  # pragma: no cover - guarded above
        raise RuntimeError("runtime_environment_binding_unavailable")
    return _RUNTIME_BINDING


def _get_db_pool() -> psycopg2.pool.ThreadedConnectionPool:
    global _DB_POOL
    if _DB_POOL is None:
        with _DB_POOL_LOCK:
            if _DB_POOL is None:
                binding = runtime_binding()
                min_conn = int(os.environ.get("WATHEFNI_DB_POOL_MIN", "1") or "1")
                max_conn = int(os.environ.get("WATHEFNI_DB_POOL_MAX", "16") or "16")
                _DB_POOL = psycopg2.pool.ThreadedConnectionPool(
                    min_conn,
                    max(min_conn, max_conn),
                    binding.database_url,
                    cursor_factory=RealDictCursor,
                    application_name=f"wathefni_{binding.application_environment}",
                )
    return _DB_POOL


class _DbConnection:
    """Context manager that reuses pooled connections and commits/rolls back like
    psycopg2's native ``with connection`` block. Connections are returned to the
    validated pool on exit; there is no unvalidated direct-connect fallback."""

    def __init__(self) -> None:
        self._conn = None
        self._from_pool = False

    def __enter__(self):
        self._conn = _get_db_pool().getconn()
        self._from_pool = True
        return self._conn

    def __exit__(self, exc_type, exc, tb):
        conn = self._conn
        self._conn = None
        if conn is None:
            return False
        try:
            if exc_type is not None:
                conn.rollback()
            else:
                conn.commit()
        except Exception:
            pass
        if self._from_pool:
            try:
                _get_db_pool().putconn(conn, close=exc_type is not None)
            except Exception:
                try:
                    conn.close()
                except Exception:
                    pass
        else:
            try:
                conn.close()
            except Exception:
                pass
        return False


def db_connect() -> _DbConnection:
    return _DbConnection()


# --- Per-turn tenant scope -------------------------------------------------
# Many AI/WhatsApp helper reads (name/position/candidate resolution) historically
# searched globally across all companies. To enforce tenant isolation without
# rewriting every call site, the active company is set once per turn at the
# request entrypoints and the scoped helpers read it (and fail closed if unset).
_active_company_code: contextvars.ContextVar[str | None] = contextvars.ContextVar(
    "wathefni_active_company_code", default=None
)


def normalize_company_code(value: str | None) -> str | None:
    company = str(value or "").strip().upper()
    return company or None


def require_company_code(company_code: str | None, *, source: str = "") -> str:
    """Fail closed. Missing tenant context never becomes the Wathefni canary tenant."""
    try:
        return _data_safety.require_company_code(company_code, source=source)
    except _data_safety.MissingCompanyCode as exc:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "company_required",
                "message": "Company context is required.",
                "source": exc.source or source or None,
            },
        ) from exc


def set_active_company_code(value: str | None):
    return _active_company_code.set(normalize_company_code(value))


def reset_active_company_code(token) -> None:
    try:
        _active_company_code.reset(token)
    except Exception:
        pass


def active_company_code() -> str | None:
    return _active_company_code.get()


def resolved_company_scope(explicit: str | None = None) -> str | None:
    """Return the company a tenant-scoped read must use: explicit argument first,
    else the active per-turn company. Returns None when neither is available so
    callers can fail closed instead of reading across every company."""
    return normalize_company_code(explicit) or active_company_code()


