def onboarding_hr_mutate_companies() -> set[str]:
    """Optional company allowlist. Empty = all companies when HR_MUTATE is on.
    Wave 4: set WATHEFNI_ONBOARDING_HR_MUTATE_COMPANIES=WATHEFNI for WATHEFNI-only."""
    raw = str(os.environ.get("WATHEFNI_ONBOARDING_HR_MUTATE_COMPANIES") or "").strip()
    if not raw:
        return set()
    return {part.strip().upper() for part in raw.split(",") if part.strip()}


def onboarding_hr_mutate_enabled_for_company(company_code: str | None) -> bool:
    if not onboarding_hr_mutate_enabled():
        return False
    allowed = onboarding_hr_mutate_companies()
    if not allowed:
        return True
    return str(company_code or "").strip().upper() in allowed


