# --- Outbound candidate email (provider-agnostic transactional sender) ------
# Candidate-facing emails (interview invites, assessment links, notifications) go
# through ONE sender abstraction (send_email -> dispatch_outbound_email). Postmark
# is the strategic target for reliable transactional delivery + a clean Wathefni
# sender identity; the existing gog/Gmail path stays as a fallback during cutover.
# Selected by WATHEFNI_OUTBOUND_EMAIL_PROVIDER=postmark|gmail.
#
# Safe-by-default: this resolves to 'gmail' (today's behaviour) unless ops BOTH set
# the flag to postmark AND configure a Postmark server token + From address — so a
# deploy never silently changes how candidate mail is sent. Google Calendar/Meet is
# a SEPARATE integration (gog calendar) and is never touched by this layer.
OUTBOUND_EMAIL_API = "https://api.postmarkapp.com/email"
DEFAULT_OUTBOUND_FROM = "no-reply@octo-hr.com"
DEFAULT_OUTBOUND_REPLY_TO = "support@octo-hr.com"
DEFAULT_OUTBOUND_DISPLAY_NAME = "OctoHR"


def outbound_postmark_config() -> dict[str, str]:
    return {
        "server_token": (os.environ.get("WATHEFNI_POSTMARK_SERVER_TOKEN") or "").strip(),
        "from_address": (os.environ.get("WATHEFNI_OUTBOUND_FROM") or DEFAULT_OUTBOUND_FROM).strip(),
        "reply_to": (os.environ.get("WATHEFNI_OUTBOUND_REPLY_TO") or DEFAULT_OUTBOUND_REPLY_TO).strip(),
        "display_name": (os.environ.get("WATHEFNI_OUTBOUND_DISPLAY_NAME") or DEFAULT_OUTBOUND_DISPLAY_NAME).strip(),
        "message_stream": (os.environ.get("WATHEFNI_POSTMARK_MESSAGE_STREAM") or "outbound").strip(),
    }


def outbound_postmark_available() -> bool:
    cfg = outbound_postmark_config()
    return bool(cfg["server_token"] and cfg["from_address"])


def outbound_email_provider() -> str:
    """Resolve the active outbound email transport ('postmark' | 'gmail').

    Falls back to gmail when postmark is requested but not configured, so candidate
    mail is never silently dropped during the cutover.
    """
    requested = (os.environ.get("WATHEFNI_OUTBOUND_EMAIL_PROVIDER") or "gmail").strip().lower()
    if requested not in {"postmark", "gmail"}:
        requested = "gmail"
    if requested == "postmark" and not outbound_postmark_available():
        return "gmail"
    return requested


