def company_root(company_code: str | None) -> Path:
    return WORKSPACE / "data" / "companies" / require_company_code(company_code)


def modules_from_payload(payload: Any) -> set[str]:
    modules: set[str] = set()
    if not isinstance(payload, dict):
        return modules
    for key in ("modules", "enabled_modules"):
        value = payload.get(key)
        if isinstance(value, list):
            modules.update(normalize_module_key(str(item)) for item in value if str(item).strip())
        elif isinstance(value, str):
            modules.update(normalize_module_key(item) for item in value.split(",") if item.strip())
    return {module for module in modules if module}


def workspace_company_config(company_code: str | None) -> dict[str, Any]:
    return read_json(company_root(company_code) / "company.json", {})


def _is_transient_db_error(exc: BaseException) -> bool:
    """Pool/connection failures must not be treated as empty entitlements."""
    name = type(exc).__name__
    if name in {"PoolError", "OperationalError", "InterfaceError", "DatabaseError"}:
        return True
    msg = str(exc).lower()
    return (
        "connection pool exhausted" in msg
        or "too many connections" in msg
        or "could not connect" in msg
        or "server closed the connection" in msg
    )


def configured_company_modules(company_code: str | None) -> set[str]:
    company = require_company_code(company_code)
    modules: set[str] = set()
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT module_key, enabled FROM company_modules WHERE company_code=%s",
                    (company,),
                )
                registry_rows = [dict(row) for row in cur.fetchall()]
                # Once a company has any canonical registry row, the registry is
                # authoritative even when every module is explicitly disabled.
                # Legacy metadata/files are seed-only and must never resurrect a
                # module after an operator turns it off.
                if registry_rows:
                    return {
                        str(row["module_key"])
                        for row in registry_rows
                        if bool(row.get("enabled"))
                    }
                cur.execute("SELECT metadata, raw_json FROM companies WHERE company_code=%s LIMIT 1", (company,))
                row = cur.fetchone()
                if row:
                    modules.update(modules_from_payload(row.get("metadata")))
                    modules.update(modules_from_payload(row.get("raw_json")))
    except Exception as exc:
        # Swallowing pool exhaustion previously fell through to legacy file config
        # without employee_app → false employee_app_not_enabled_for_company (403).
        if _is_transient_db_error(exc):
            raise
        pass
    modules.update(modules_from_payload(workspace_company_config(company)))
    # Seed-only sources predate later module carve-outs (see LEGACY_IMPLIED_MODULES).
    # The registry path above returns before this and stays authoritative.
    return apply_legacy_module_implications(modules)


def module_platform_available(module_key: str) -> bool:
    """Whether the platform-wide runtime gate for a catalog module is open.

    Most modules have no master gate and are always available once entitled.
    Employee App deliberately retains its independent platform kill switch.
    """
    definition = MODULE_BY_KEY.get(normalize_module_key(module_key))
    if not definition or not definition.master_flag:
        return True
    return (os.environ.get(definition.master_flag) or "").strip().lower() in _OUTBOUND_ON_VALUES


def effective_company_modules(company_code: str | None) -> set[str]:
    """Configured tenant entitlements that are currently usable platform-wide."""
    company = require_company_code(company_code)
    base = {
        module
        for module in configured_company_modules(company_code)
        if module in MODULE_BY_KEY and module_platform_available(module)
    }
    # Wave 2: drop modules that are authoritatively denied (canary pause etc.).
    if not _tenant_decision.decision_enabled():
        return base
    filtered: set[str] = set()
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                for module in sorted(base):
                    result = _tenant_decision.evaluate_decision(
                        cur,
                        company_code=company,
                        surface="navigation",
                        module_key=module,
                        legacy_allow=True,
                        persist=False,
                    )
                    if result.mode == "authoritative" and not result.detail.get("canonical_allow", True):
                        continue
                    if result.mode == "authoritative" and not result.allow:
                        continue
                    # Also hide when canonical says paused even in shadow if we want nav preview?
                    # Requirement: canary pause disappears from navigation — requires authority.
                    filtered.add(module)
            conn.rollback()
    except Exception:
        return base
    return filtered


def dashboard_module_catalog_payload(company_code: str | None) -> list[dict[str, Any]]:
    configured = configured_company_modules(company_code)
    payload: list[dict[str, Any]] = []
    for item in module_catalog_payload():
        key = str(item["key"])
        available = module_platform_available(key)
        payload.append(
            {
                **item,
                "configured": key in configured,
                "platform_available": available,
                "effective": key in configured and available,
                "depends_on_labels": [MODULE_DISPLAY_NAMES.get(dep, dep) for dep in (item.get("depends_on") or ())],
                "recommended_with_labels": [MODULE_DISPLAY_NAMES.get(dep, dep) for dep in (item.get("recommended_with") or ())],
            }
        )
    return payload


def _setup_http_namespace_registered(namespace: str) -> bool:
    prefix = str(namespace or "").rstrip("/")
    if not prefix:
        return False
    for route in app.routes:
        path = str(getattr(route, "path", "") or "")
        if path == prefix or path.startswith(prefix + "/") or path.startswith(prefix + "{"):
            return True
    return False


def setup_module_http_registered(module_key: str) -> bool | None:
    import capability_readiness as _cap_ready

    cap = _cap_ready.capability_for_setup_module_key(module_key)
    spec = _cap_ready.spec_for(cap) if cap else None
    if spec is None or not spec.http_namespaces:
        return None
    return any(_setup_http_namespace_registered(ns) for ns in spec.http_namespaces)


def setup_company_principal_permits_module(company_code: str, module_key: str, users: list[dict[str, Any]] | None) -> bool | None:
    import setup_console_effective_state as _eff

    permission = _eff.MODULE_READ_PERMISSIONS.get(normalize_module_key(module_key) or str(module_key or "").strip().lower())
    if not permission:
        return None
    active: list[dict[str, Any]] = []
    for user in users or []:
        if not isinstance(user, dict):
            continue
        status = str(user.get("status") or "active").strip().lower()
        if status in {"inactive", "deactivated", "disabled", "removed", "blocked", "invited"}:
            continue
        active.append(user)
    if not active:
        return None
    for user in active:
        perms = {str(item) for item in (user.get("permissions") or []) if str(item).strip()}
        if not perms:
            perms = set(
                dashboard_effective_permissions_for_user(
                    {
                        "role": user.get("role"),
                        "company_code": str(company_code or "").strip().upper(),
                        "user_id": str(user.get("user_id") or "").strip(),
                    }
                )
            )
        if permission in perms or "*" in perms:
            return True
    return False


def setup_console_module_guidance(company_code: str | None, selected_modules: list[str] | None = None) -> dict[str, Any]:
    selected = list(selected_modules) if selected_modules is not None else sorted(configured_company_modules(company_code))
    return {
        "bundles": module_bundles_payload(),
        "app_surfaces": app_surfaces_for_modules(selected),
        "missing_dependencies": missing_module_dependencies(selected),
        "expanded_modules": expand_module_dependencies(selected),
    }


def company_has_module(company_code: str | None, module_key: str) -> bool:
    module = normalize_module_key(module_key)
    modules = configured_company_modules(company_code)
    legacy_allow = module in modules
    company = require_company_code(company_code)
    # Wave 2: shadow-observe; authoritative only for allowlisted canary capabilities.
    if _tenant_decision.decision_enabled():
        try:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    result = _tenant_surfaces.observe_or_enforce(
                        cur,
                        company_code=company,
                        surface="module_check",
                        module_key=module,
                        legacy_allow=legacy_allow,
                        record_block=False,
                    )
                # Do not commit decision-audit noise for high-frequency checks unless
                # authoritative mode actually changed the outcome.
                if result.mode == "authoritative":
                    conn.commit()
                    return bool(result.allow)
                conn.rollback()
        except Exception:
            pass
    return legacy_allow


def company_module_settings(company_code: str | None, module_key: str) -> dict[str, Any]:
    company = require_company_code(company_code)
    module = normalize_module_key(module_key)
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT enabled, settings FROM company_modules WHERE company_code=%s AND module_key=%s LIMIT 1",
                    (company, module),
                )
                row = cur.fetchone()
        if not row:
            return {}
        settings = row.get("settings") if isinstance(row.get("settings"), dict) else {}
        return {"enabled": bool(row.get("enabled")), **settings}
    except Exception:
        return {}


def get_company_settings(company_code: str | None) -> dict[str, Any]:
    """Return the free-form per-company settings blob (company_settings.settings)."""
    return dict(get_company_settings_row(company_code).get("settings") or {})


def get_company_settings_row(company_code: str | None) -> dict[str, Any]:
    """Return settings blob plus Wave 5 concurrency metadata."""
    import concurrency_safety as _cs

    company = require_company_code(company_code)
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                _cs.ensure_company_settings_concurrency_schema(cur)
                cur.execute(
                    """
                    SELECT settings, version, updated_at, updated_by_user_id, updated_by_name, updated_by_email
                    FROM company_settings
                    WHERE company_code=%s
                    LIMIT 1
                    """,
                    (company,),
                )
                row = cur.fetchone()
            conn.commit()
        if not row:
            return {"settings": {}, **_cs.settings_concurrency_meta({"version": 1})}
        data = dict(row)
        settings = data.get("settings") if isinstance(data.get("settings"), dict) else {}
        return {"settings": settings, **_cs.settings_concurrency_meta(data)}
    except Exception:
        return {"settings": {}, "version": 1, "updated_at": None, "last_updated_by": None}


# Keys in company_settings.settings that are OWNED BY THE OPERATOR (set via the
# Setup Console / dashboard), not by the workspace company.json profile. The DB is
# the source of truth for these; the company.json registry sync must preserve them
# (otherwise a restart/deploy silently reverts operator changes). Keep this list in
# sync with every set_company_setting(...) call site:
#   - timezone                    -> PATCH /superadmin/setup/companies/{c}/settings
#   - notification_preset         -> PATCH /superadmin/setup/companies/{c}/settings
#   - intake_auto_admit_explicit  -> PUT  /dashboard/prehire/import/settings
OPERATOR_MANAGED_SETTING_KEYS: tuple[str, ...] = (
    "timezone",
    "currency",
    "notification_preset",
    "channel_policy_reviewed",
    "intake_auto_admit_explicit",
    "inbound_forwarding_enabled",
    "inbound_quotas",
    "prehire_visibility_policy",
    "communication_policy",
    "calendar_policy",
)


def set_company_setting(
    company_code: str | None,
    key: str,
    value: Any,
    *,
    expected_version: int | None = None,
    expected_updated_at: str | None = None,
    require_expected: bool = False,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Merge a single key into company_settings.settings (idempotent upsert).

    Wave 2 integrity: refuse creating settings rows for unknown companies so new
    orphan company_settings cannot be introduced. Existing orphans are retained.
    Wave 5: when require_expected=True (dashboard shared edits), mutations must
    send expected_version / expected_updated_at and never silently overwrite.
    """
    import concurrency_safety as _cs

    company = require_company_code(company_code)
    actor_data = actor if isinstance(actor, dict) else {}
    with db_connect() as conn:
        with conn.cursor() as cur:
            _cs.ensure_company_settings_concurrency_schema(cur)
            cur.execute("SELECT 1 FROM companies WHERE company_code=%s LIMIT 1", (company,))
            if not cur.fetchone():
                raise HTTPException(
                    status_code=404,
                    detail={
                        "error": "company_not_found",
                        "message": "Cannot write company settings for an unknown company.",
                        "company_code": company,
                    },
                )
            cur.execute(
                """
                SELECT settings, version, updated_at, updated_by_user_id, updated_by_name, updated_by_email
                FROM company_settings
                WHERE company_code=%s
                FOR UPDATE
                """,
                (company,),
            )
            existing = cur.fetchone()
            if existing:
                row = dict(existing)
                try:
                    _cs.assert_fresh(
                        current_version=row.get("version") or 1,
                        expected_version=expected_version,
                        current_updated_at=row.get("updated_at"),
                        expected_updated_at=expected_updated_at,
                        last_changed_by={
                            "user_id": row.get("updated_by_user_id"),
                            "name": row.get("updated_by_name"),
                            "email": row.get("updated_by_email"),
                        },
                        entity_type="company_settings",
                        entity_id=company,
                        code_version="stale_settings_version",
                        code_updated_at="stale_settings_update",
                        require_token=require_expected,
                    )
                except _cs.ConcurrencyError as exc:
                    raise HTTPException(status_code=exc.http_status, detail=exc.as_detail()) from exc
                cur.execute(
                    """
                    UPDATE company_settings
                    SET settings = settings || %s,
                        version = COALESCE(version, 1) + 1,
                        updated_at = now(),
                        updated_by_user_id = COALESCE(%s, updated_by_user_id),
                        updated_by_name = COALESCE(%s, updated_by_name),
                        updated_by_email = COALESCE(%s, updated_by_email)
                    WHERE company_code=%s
                    RETURNING settings, version, updated_at, updated_by_user_id, updated_by_name, updated_by_email
                    """,
                    (
                        Json({key: value}),
                        str(actor_data.get("user_id") or actor_data.get("actor_user_id") or "") or None,
                        str(actor_data.get("name") or actor_data.get("actor_name") or "") or None,
                        str(actor_data.get("email") or actor_data.get("actor_email") or "") or None,
                        company,
                    ),
                )
            else:
                if require_expected:
                    # First create: still accept optional tokens but do not require a prior version.
                    pass
                cur.execute(
                    """
                    INSERT INTO company_settings (
                      company_code, settings, version, updated_by_user_id, updated_by_name, updated_by_email
                    )
                    VALUES (%s, %s, 1, %s, %s, %s)
                    RETURNING settings, version, updated_at, updated_by_user_id, updated_by_name, updated_by_email
                    """,
                    (
                        company,
                        Json({key: value}),
                        str(actor_data.get("user_id") or actor_data.get("actor_user_id") or "") or None,
                        str(actor_data.get("name") or actor_data.get("actor_name") or "") or None,
                        str(actor_data.get("email") or actor_data.get("actor_email") or "") or None,
                    ),
                )
            updated = dict(cur.fetchone() or {})
        conn.commit()
    settings = updated.get("settings") if isinstance(updated.get("settings"), dict) else {}
    return {"settings": settings, **_cs.settings_concurrency_meta(updated)}


def company_prehire_visibility_policy(company_code: str | None) -> str:
    import prehire_visibility as _pv

    return _pv.prehire_visibility_policy_from_settings(get_company_settings(company_code))


def prehire_visibility_plan_for_context(context: dict[str, Any] | None, *, surface: str) -> dict[str, Any]:
    import prehire_visibility as _pv

    data = context if isinstance(context, dict) else {}
    company = str(data.get("company_code") or "").strip().upper()
    role = dashboard_context_role_key(data) if data else "viewer"
    policy = company_prehire_visibility_policy(company) if company else _pv.PREHIRE_VISIBILITY_DEFAULT
    return _pv.resolve_visibility_plan(policy=policy, role=role, surface=surface)


def prehire_visibility_assignment_sql(
    context: dict[str, Any] | None,
    *,
    surface: str,
    kind: str,
) -> tuple[str, list[Any]]:
    """Return (sql, params) to AND into queries. Empty when no assignment scope."""
    import prehire_visibility as _pv

    plan = prehire_visibility_plan_for_context(context, surface=surface)
    if not plan.get("apply_assignment_scope"):
        return "", []
    actor = str(
        (context or {}).get("actor_user_id")
        or ((context or {}).get("hr_user") or {}).get("user_id")
        or ""
    ).strip()
    if not actor:
        # Fail closed for scoped roles without identity.
        return "FALSE", []
    role = plan.get("role") or dashboard_context_role_key(context)
    if kind == "jobs":
        sql, placeholders = _pv.jobs_assignment_sql(role, alias="")
    elif kind == "applications":
        sql, placeholders = _pv.applications_assignment_sql(role, applications_alias="a")
    elif kind == "interviews":
        # Interviews inherit application/job ownership for recruiter/HM.
        app_sql, placeholders = _pv.applications_assignment_sql(role, applications_alias="a")
        sql = (
            "EXISTS ("
            "SELECT 1 FROM applications a "
            "WHERE a.company_code=ci.company_code AND a.app_key=ci.app_key "
            f"AND {app_sql}"
            ")"
        )
    elif kind == "assessments":
        app_sql, placeholders = _pv.applications_assignment_sql(role, applications_alias="a")
        sql = f"({app_sql})"
    else:
        return "", []
    return sql, _pv.bind_actor_params(placeholders, actor)


def require_prehire_application_visibility(context: dict[str, Any], application: dict[str, Any]) -> None:
    """404 when the actor cannot see this application under the tenant policy."""
    import prehire_visibility as _pv

    plan = prehire_visibility_plan_for_context(context, surface="detail")
    if not plan.get("apply_assignment_scope"):
        return
    actor = str(context.get("actor_user_id") or (context.get("hr_user") or {}).get("user_id") or "").strip()
    role = plan.get("role") or dashboard_context_role_key(context)
    with db_connect() as conn:
        with conn.cursor() as cur:
            ok = _pv.application_visible_to_actor(
                application=application,
                role=role,
                actor_user_id=actor,
                cur=cur,
            )
    if ok:
        return
    raise HTTPException(
        status_code=404,
        detail={"error": "application_not_found", "message": "Application not found."},
    )


def require_prehire_job_visibility(context: dict[str, Any], job: dict[str, Any] | None) -> None:
    import prehire_visibility as _pv

    plan = prehire_visibility_plan_for_context(context, surface="detail")
    if not plan.get("apply_assignment_scope"):
        return
    actor = str(context.get("actor_user_id") or (context.get("hr_user") or {}).get("user_id") or "").strip()
    role = plan.get("role") or dashboard_context_role_key(context)
    if _pv.job_visible_to_actor(job=job, role=role, actor_user_id=actor):
        return
    raise HTTPException(
        status_code=404,
        detail={"error": "job_not_found", "message": "Job not found."},
    )


def company_profile_payload(company_code: str | None) -> dict[str, Any]:
    company = (company_code or "").strip().upper()
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT company_code, name, country FROM companies WHERE company_code=%s LIMIT 1", (company,))
            row = cur.fetchone()
    if not row:
        return {}
    settings = get_company_settings(company)
    country = str(row.get("country") or _company_setup.DEFAULT_COUNTRY).upper()
    timezone_value = ""
    currency = ""
    if settings.get("timezone"):
        try:
            timezone_value = _company_setup.normalize_timezone(settings.get("timezone"), country=country)
        except ValueError:
            timezone_value = ""
    elif country in _company_setup.GCC_PROFILE_DEFAULTS:
        timezone_value = _company_setup.default_timezone_for_country(country)
    if settings.get("currency"):
        try:
            currency = _company_setup.normalize_currency(settings.get("currency"), country=country)
        except ValueError:
            currency = ""
    elif country in _company_setup.GCC_PROFILE_DEFAULTS:
        currency = _company_setup.default_currency_for_country(country)
    return {
        "company_code": company,
        "name": str(row.get("name") or company),
        "country": country,
        "timezone": timezone_value,
        "currency": currency,
    }


def company_currency(company_code: str | None) -> str:
    return str(company_profile_payload(company_code).get("currency") or _company_setup.DEFAULT_CURRENCY)


def company_auto_admit_imports(company_code: str | None) -> bool:
    """Whether explicit-role imports auto-admit into Candidates.

    Fail closed when the company policy is unset. Auto-admit requires an
    explicit True setting plus a position and non-governed identity path.
    """
    val = get_company_settings(company_code).get("intake_auto_admit_explicit")
    if val is None:
        return False
    return bool(val)


def company_module_automation_enabled(company_code: str | None, module_key: str, *, default: bool = True) -> bool:
    """Return whether background automation may run for a company module.

    `company_has_module` controls product availability. This controls scheduled
    side effects such as WhatsApp reminders, compliance alerts, and scans.
    """

    if not company_has_module(company_code, module_key):
        return False
    settings = company_module_settings(company_code, module_key)
    for key in ("automation_enabled", "background_automation_enabled", "scheduled_automation_enabled"):
        if key in settings:
            return bool(settings.get(key))
    return default


def company_module_alerts_enabled(company_code: str | None, module_key: str, *, default: bool = True) -> bool:
    """Return whether a module should contribute dashboard action alerts."""

    if not company_has_module(company_code, module_key):
        return False
    settings = company_module_settings(company_code, module_key)
    for key in ("dashboard_alerts_enabled", "notifications_enabled", "alerts_enabled"):
        if key in settings:
            return bool(settings.get(key))
    if "automation_enabled" in settings:
        return bool(settings.get("automation_enabled"))
    return default


def notification_enabled_modules(company_code: str | None) -> set[str]:
    return {
        module
        for module in configured_company_modules(company_code)
        if company_module_alerts_enabled(company_code, module)
    }


def any_company_module_automation_enabled(module_keys: list[str], *, default: bool = True) -> bool:
    modules = [normalize_module_key(module) for module in module_keys]
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT company_code, module_key
                    FROM company_modules
                    WHERE enabled IS TRUE AND module_key = ANY(%s)
                    """,
                    (modules,),
                )
                rows = [dict(row) for row in cur.fetchall()]
        return any(company_module_automation_enabled(row.get("company_code"), row.get("module_key"), default=default) for row in rows)
    except Exception:
        return default


def module_disabled_reply(company_code: str | None, module_key: str) -> str:
    name = MODULE_DISPLAY_NAMES.get(normalize_module_key(module_key), module_key.replace("_", " ").title())
    company = (company_code or "this company").upper()
    return f"{name} is not enabled for {company}. I can only use modules included in this company instance."


def candidate_safe_module_unavailable_reply() -> str:
    return "Applications are not available on this channel right now. Please contact the hiring team."


def sync_company_module_registry() -> None:
    try:
        rows: list[dict[str, Any]] = []
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT company_code, metadata, raw_json FROM companies")
                rows = [dict(row) for row in cur.fetchall()]
                for row in rows:
                    company = str(row.get("company_code") or "").upper()
                    if not company:
                        continue
                    modules = set()
                    modules.update(modules_from_payload(row.get("metadata")))
                    modules.update(modules_from_payload(row.get("raw_json")))
                    modules.update(modules_from_payload(workspace_company_config(company)))
                    for module in sorted(modules):
                        settings = {"timezone": "Asia/Kuwait", "reminder_hours_before": 2} if module == "shifts" else {}
                        cur.execute(
                            """
                            INSERT INTO company_modules (company_code, module_key, enabled, source, settings, updated_at)
                            VALUES (%s,%s,true,'company_config',%s,now())
                            ON CONFLICT (company_code, module_key)
                            DO UPDATE SET source=CASE
                                            WHEN company_modules.source='company_config' THEN EXCLUDED.source
                                            ELSE company_modules.source
                                          END,
                                          settings=CASE
                                            WHEN company_modules.settings = '{}'::jsonb THEN EXCLUDED.settings
                                            ELSE company_modules.settings
                                          END,
                                          updated_at=now()
                            """,
                            (company, module, Json(settings)),
                        )
                    settings = workspace_company_config(company)
                    # Refresh profile fields from company.json, but PRESERVE operator-
                    # managed keys already in the DB so a restart/deploy never silently
                    # reverts a Setup Console change. DB operator keys win (right side of
                    # ||); jsonb_strip_nulls drops keys not yet set so company.json can
                    # still seed an initial default for them.
                    preserve_obj = ", ".join(f"'{k}', company_settings.settings->'{k}'" for k in OPERATOR_MANAGED_SETTING_KEYS)
                    cur.execute(
                        f"""
                        INSERT INTO company_settings (company_code, settings, raw_json, updated_at)
                        VALUES (%s,%s,%s,now())
                        ON CONFLICT (company_code)
                        DO UPDATE SET
                          settings = EXCLUDED.settings || jsonb_strip_nulls(jsonb_build_object({preserve_obj})),
                          raw_json = EXCLUDED.raw_json,
                          updated_at = now()
                        """,
                        (company, Json(settings), Json({"source": "workspace_company_json", "path": str(company_root(company) / "company.json")})),
                    )
            conn.commit()
    except Exception:
        return


def org_key(company: str, prefix: str, value: str | None) -> str:
    raw = normalize_text(value or prefix).replace(" ", "_")
    raw = re.sub(r"[^a-z0-9_]+", "", raw) or prefix
    return f"{company.lower()}_{prefix}_{raw}"[:96]


def sync_company_org_registry() -> None:
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT company_code FROM companies")
                companies = [str(row.get("company_code") or "").upper() for row in cur.fetchall()]
                for company in companies:
                    if not company:
                        continue
                    config = workspace_company_config(company)
                    org = config.get("org_structure") if isinstance(config.get("org_structure"), dict) else {}
                    branches = org.get("branches") if isinstance(org.get("branches"), list) else []
                    teams = org.get("teams") if isinstance(org.get("teams"), list) else []
                    managers = org.get("managers") if isinstance(org.get("managers"), list) else []
                    employee_assignments = org.get("employee_assignments") if isinstance(org.get("employee_assignments"), list) else []
                    branch_name_to_key: dict[str, str] = {}
                    team_name_to_key: dict[str, str] = {}
                    for branch in branches:
                        if not isinstance(branch, dict):
                            continue
                        name = str(branch.get("name") or branch.get("branch_name") or "").strip()
                        if not name:
                            continue
                        branch_key = str(branch.get("branch_key") or branch.get("key") or org_key(company, "branch", name))
                        branch_name_to_key[normalize_text(name)] = branch_key
                        cur.execute(
                            """
                            INSERT INTO company_branches (branch_key, company_code, branch_name, aliases, metadata, is_active, updated_at)
                            VALUES (%s,%s,%s,%s,%s,%s,now())
                            ON CONFLICT (branch_key)
                            DO UPDATE SET branch_name=EXCLUDED.branch_name,
                                          aliases=EXCLUDED.aliases,
                                          metadata=company_branches.metadata || EXCLUDED.metadata,
                                          is_active=EXCLUDED.is_active,
                                          updated_at=now()
                            """,
                            (
                                branch_key,
                                company,
                                name,
                                Json(branch.get("aliases") if isinstance(branch.get("aliases"), list) else []),
                                Json(json_safe(branch)),
                                bool(branch.get("is_active", True)),
                            ),
                        )
                    for team in teams:
                        if not isinstance(team, dict):
                            continue
                        name = str(team.get("name") or team.get("team_name") or "").strip()
                        if not name:
                            continue
                        branch_ref = normalize_text(str(team.get("branch") or team.get("branch_name") or ""))
                        branch_key = str(team.get("branch_key") or branch_name_to_key.get(branch_ref) or "") or None
                        team_key = str(team.get("team_key") or team.get("key") or org_key(company, "team", name))
                        team_name_to_key[normalize_text(name)] = team_key
                        cur.execute(
                            """
                            INSERT INTO company_teams (team_key, company_code, team_name, branch_key, aliases, metadata, is_active, updated_at)
                            VALUES (%s,%s,%s,%s,%s,%s,%s,now())
                            ON CONFLICT (team_key)
                            DO UPDATE SET team_name=EXCLUDED.team_name,
                                          branch_key=EXCLUDED.branch_key,
                                          aliases=EXCLUDED.aliases,
                                          metadata=company_teams.metadata || EXCLUDED.metadata,
                                          is_active=EXCLUDED.is_active,
                                          updated_at=now()
                            """,
                            (
                                team_key,
                                company,
                                name,
                                branch_key,
                                Json(team.get("aliases") if isinstance(team.get("aliases"), list) else []),
                                Json(json_safe(team)),
                                bool(team.get("is_active", True)),
                            ),
                        )
                    for assignment in employee_assignments:
                        if not isinstance(assignment, dict):
                            continue
                        employee_key = str(assignment.get("employee_key") or "").strip()
                        phone = digits(assignment.get("phone") or assignment.get("employee_phone"))
                        if not employee_key and phone:
                            cur.execute(
                                "SELECT employee_key FROM employees WHERE company_code=%s AND phone=%s ORDER BY updated_at DESC LIMIT 1",
                                (company, phone),
                            )
                            employee_row = cur.fetchone()
                            employee_key = str((employee_row or {}).get("employee_key") or "").strip()
                        if not employee_key:
                            continue
                        branch_ref = normalize_text(str(assignment.get("branch") or assignment.get("branch_name") or ""))
                        team_ref = normalize_text(str(assignment.get("team") or assignment.get("team_name") or ""))
                        branch_key = str(assignment.get("branch_key") or branch_name_to_key.get(branch_ref) or "") or None
                        team_key = str(assignment.get("team_key") or team_name_to_key.get(team_ref) or "") or None
                        if not branch_key and not team_key:
                            continue
                        cur.execute(
                            """
                            INSERT INTO employee_org_assignments (company_code, employee_key, branch_key, team_key, role, is_primary, metadata, updated_at)
                            SELECT %s,%s,%s,%s,%s,%s,%s,now()
                            WHERE NOT EXISTS (
                              SELECT 1
                              FROM employee_org_assignments
                              WHERE company_code=%s
                                AND employee_key=%s
                                AND COALESCE(branch_key,'')=COALESCE(%s,'')
                                AND COALESCE(team_key,'')=COALESCE(%s,'')
                            )
                            """,
                            (
                                company,
                                employee_key,
                                branch_key,
                                team_key,
                                str(assignment.get("role") or "").strip() or None,
                                bool(assignment.get("is_primary", True)),
                                Json(json_safe(assignment)),
                                company,
                                employee_key,
                                branch_key,
                                team_key,
                            ),
                        )
                    if branch_name_to_key or team_name_to_key:
                        cur.execute("SELECT * FROM employees WHERE company_code=%s LIMIT 5000", (company,))
                        for employee in [dict(row) for row in cur.fetchall()]:
                            raw_json = employee.get("raw_json") if isinstance(employee.get("raw_json"), dict) else {}
                            profile = employee.get("profile") if isinstance(employee.get("profile"), dict) else {}
                            branch_ref = normalize_text(str(employee.get("branch") or employee.get("location") or profile.get("branch") or profile.get("location") or raw_json.get("branch") or raw_json.get("location") or ""))
                            team_ref = normalize_text(str(employee.get("team") or employee.get("department") or profile.get("team") or profile.get("department") or raw_json.get("team") or raw_json.get("department") or ""))
                            branch_key = str(employee.get("branch_key") or profile.get("branch_key") or raw_json.get("branch_key") or branch_name_to_key.get(branch_ref) or "") or None
                            team_key = str(employee.get("team_key") or profile.get("team_key") or raw_json.get("team_key") or team_name_to_key.get(team_ref) or "") or None
                            if not (employee.get("employee_key") and (branch_key or team_key)):
                                continue
                            cur.execute(
                                """
                                INSERT INTO employee_org_assignments (company_code, employee_key, branch_key, team_key, role, is_primary, metadata, updated_at)
                                SELECT %s,%s,%s,%s,%s,true,%s,now()
                                WHERE NOT EXISTS (
                                  SELECT 1
                                  FROM employee_org_assignments
                                  WHERE company_code=%s
                                    AND employee_key=%s
                                    AND COALESCE(branch_key,'')=COALESCE(%s,'')
                                    AND COALESCE(team_key,'')=COALESCE(%s,'')
                                )
                                """,
                                (
                                    company,
                                    employee.get("employee_key"),
                                    branch_key,
                                    team_key,
                                    str(employee.get("role") or employee.get("position_title") or "").strip() or None,
                                    Json({"source": "employee_profile"}),
                                    company,
                                    employee.get("employee_key"),
                                    branch_key,
                                    team_key,
                                ),
                            )
                    for manager in managers:
                        if not isinstance(manager, dict):
                            continue
                        phone = digits(manager.get("phone"))
                        if not phone:
                            continue
                        scope_type = str(manager.get("scope_type") or "branch").strip().lower()
                        branch_ref = normalize_text(str(manager.get("branch") or manager.get("branch_name") or ""))
                        branch_key = str(manager.get("branch_key") or branch_name_to_key.get(branch_ref) or "") or None
                        team_key = str(manager.get("team_key") or "") or None
                        if scope_type != "company" and not (branch_key or team_key):
                            continue
                        cur.execute(
                            """
                            INSERT INTO manager_scopes (company_code, manager_phone, scope_type, branch_key, team_key, role, permissions, metadata, is_active, updated_at)
                            SELECT %s,%s,%s,%s,%s,%s,%s,%s,%s,now()
                            WHERE NOT EXISTS (
                              SELECT 1
                              FROM manager_scopes
                              WHERE company_code=%s
                                AND manager_phone=%s
                                AND scope_type=%s
                                AND COALESCE(branch_key,'')=COALESCE(%s,'')
                                AND COALESCE(team_key,'')=COALESCE(%s,'')
                                AND is_active IS TRUE
                            )
                            """,
                            (
                                company,
                                phone,
                                scope_type,
                                branch_key,
                                team_key,
                                str(manager.get("role") or "manager"),
                                Json(manager.get("permissions") if isinstance(manager.get("permissions"), list) else []),
                                Json(json_safe(manager)),
                                bool(manager.get("is_active", True)),
                                company,
                                phone,
                                scope_type,
                                branch_key,
                                team_key,
                            ),
                        )
            conn.commit()
    except Exception:
        return


class WhatsAppTurnRequest(BaseModel):
    account_id: str | None = None
    conversation_id: str | None = None
    sender_phone: str
    sender_role: str | None = None
    raw_text: str = ""
    media: dict[str, Any] | None = None
    metadata: dict[str, Any] | None = None


def candidate_message_payload(
    template_key: str,
    *,
    request: WhatsAppTurnRequest | None = None,
    application: dict[str, Any] | None = None,
    locale: str | None = None,
    **values: Any,
) -> dict[str, str]:
    preferred = locale
    if not preferred and request and isinstance(request.metadata, dict):
        preferred = str(request.metadata.get("locale") or request.metadata.get("language") or "")
    if not preferred and isinstance(application, dict):
        raw = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
        communication = raw.get("candidate_communication") if isinstance(raw.get("candidate_communication"), dict) else {}
        preferred = str(
            raw.get("candidate_locale")
            or raw.get("locale")
            or communication.get("locale")
            or ""
        )
    loc = _candidate_messages.infer_locale(
        request.raw_text if request else "",
        preferred=preferred,
    )
    return _candidate_messages.render(template_key, loc, **values)


def candidate_message_result(
    template_key: str,
    *,
    request: WhatsAppTurnRequest | None = None,
    application: dict[str, Any] | None = None,
    locale: str | None = None,
    **values: Any,
) -> dict[str, Any]:
    template = candidate_message_payload(
        template_key,
        request=request,
        application=application,
        locale=locale,
        **values,
    )
    return {"reply": template["text"], "candidate_template": template}


def _whatsapp_provider_message_id(request: WhatsAppTurnRequest) -> str | None:
    metadata = request.metadata if isinstance(request.metadata, dict) else {}
    for key in ("provider_message_id", "message_id", "wamid", "external_message_id"):
        value = str(metadata.get(key) or "").strip()
        if value:
            return value[:500]
    # Defense in depth: Octopus may nest the WhatsApp id inside provider_payload.
    payload = metadata.get("provider_payload") if isinstance(metadata.get("provider_payload"), dict) else {}
    nested_candidates = [
        payload.get("message_id"),
        payload.get("messageId"),
        ((payload.get("messages") or [{}])[0] or {}).get("id") if isinstance(payload.get("messages"), list) else None,
    ]
    for candidate in nested_candidates:
        value = str(candidate or "").strip()
        if value:
            return value[:500]
    return None


def _whatsapp_inbound_identity(request: WhatsAppTurnRequest) -> dict[str, str] | None:
    provider_message_id = _whatsapp_provider_message_id(request)
    if not provider_message_id:
        return None
    metadata = request.metadata if isinstance(request.metadata, dict) else {}
    provider = str(metadata.get("provider") or "octopus").strip().lower() or "octopus"
    account_id = str(request.account_id or metadata.get("account_id") or "default").strip() or "default"
    payload = {
        "sender_phone": digits(request.sender_phone),
        "conversation_id": str(request.conversation_id or ""),
        "raw_text": str(request.raw_text or ""),
        "media": request.media or {},
    }
    return {
        "provider": provider,
        "account_id": account_id,
        "provider_message_id": provider_message_id,
        "sender_phone": digits(request.sender_phone),
        "conversation_id": str(request.conversation_id or ""),
        "payload_sha256": hashlib.sha256(
            json.dumps(json_safe(payload), ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest(),
    }


def claim_whatsapp_inbound(request: WhatsAppTurnRequest) -> dict[str, Any]:
    identity = _whatsapp_inbound_identity(request)
    if not identity:
        return {"claimed": False, "dedupe_available": False, "reason": "provider_message_id_missing"}
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO whatsapp_inbound_messages
                  (provider, account_id, provider_message_id, sender_phone,
                   conversation_id, company_code, payload_sha256, status)
                VALUES (%s,%s,%s,%s,%s,%s,%s,'processing')
                ON CONFLICT (provider, account_id, provider_message_id) DO NOTHING
                RETURNING inbound_id::text
                """,
                (
                    identity["provider"],
                    identity["account_id"],
                    identity["provider_message_id"],
                    identity["sender_phone"],
                    identity["conversation_id"] or None,
                    request_company_code(request),
                    identity["payload_sha256"],
                ),
            )
            inserted = cur.fetchone()
            if inserted:
                conn.commit()
                return {
                    "claimed": True,
                    "dedupe_available": True,
                    "inbound_id": inserted["inbound_id"],
                    "identity": identity,
                }
            cur.execute(
                """
                SELECT inbound_id::text, sender_phone, conversation_id,
                       payload_sha256, status, response_json, error
                FROM whatsapp_inbound_messages
                WHERE provider=%s AND account_id=%s AND provider_message_id=%s
                LIMIT 1
                """,
                (identity["provider"], identity["account_id"], identity["provider_message_id"]),
            )
            existing = dict(cur.fetchone() or {})
        conn.commit()
    identity_match = (
        digits(existing.get("sender_phone")) == identity["sender_phone"]
        and str(existing.get("conversation_id") or "") == identity["conversation_id"]
        and str(existing.get("payload_sha256") or "") == identity["payload_sha256"]
    )
    return {
        "claimed": False,
        "dedupe_available": True,
        "duplicate": True,
        "identity_match": identity_match,
        "identity": identity,
        "existing": json_safe(existing),
    }


def complete_whatsapp_inbound(claim: dict[str, Any], response: OrchestratorResponse | dict[str, Any], *, error: str | None = None) -> None:
    inbound_id = str(claim.get("inbound_id") or "")
    if not inbound_id:
        return
    if isinstance(response, BaseModel):
        payload = response.model_dump() if hasattr(response, "model_dump") else response.dict()
    else:
        payload = dict(response or {})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE whatsapp_inbound_messages
                SET status=%s,
                    response_json=%s,
                    error=%s,
                    completed_at=now(),
                    updated_at=now()
                WHERE inbound_id=%s
                """,
                (
                    "failed" if error else "completed",
                    Json(json_safe(payload)),
                    str(error or "")[:1000] or None,
                    inbound_id,
                ),
            )
        conn.commit()


