EMPLOYEE_REPLY_TOOL_DEFINITIONS: list[dict[str, Any]] = [
    {
        "type": "function",
        "function": {
            "name": "classify_employee_onboarding_reply",
            "description": "Classify an employee onboarding WhatsApp reply. Extract whether it is a full name, bank/IBAN details, Civil ID, passport, personal photo, or unknown. Prefer the current pending item only when the current message contains real answer evidence. Do not classify copied instructions or quoted checklist text as received documents.",
            "parameters": {
                "type": "object",
                "properties": {
                    "reply_type": {
                        "type": "string",
                        "enum": ["name", "onboarding_item", "unknown"],
                        "description": "The kind of reply."
                    },
                    "item_id": {
                        "type": "string",
                        "enum": ["bank_details", "civil_id", "passport", "personal_photo", "medical", "education_cert", "unknown"],
                        "description": "Onboarding item if reply_type is onboarding_item."
                    },
                    "value": {
                        "type": "string",
                        "description": "The extracted value to store, such as full name, IBAN text, or a short description."
                    },
                    "confidence": {
                        "type": "number",
                        "description": "Confidence from 0 to 1."
                    },
                    "reason": {
                        "type": "string",
                        "description": "Short reason for the classification."
                    }
                },
                "required": ["reply_type", "item_id", "value", "confidence", "reason"],
                "additionalProperties": False,
            },
        },
    }
]


