def plan_hr_turn(raw_text: str, company_code: str | None = "WATHEFNI") -> tuple[dict[str, Any] | None, dict[str, Any]]:
    context = latest_planner_context()
    enabled_modules = sorted(configured_company_modules(company_code))
    context["company_code"] = company_code
    context["enabled_modules"] = enabled_modules
    planner_tools = planner_tool_definitions_for_company(company_code)
    tool_call_tools = tool_call_definitions_for_company(company_code)
    provider = planner_provider_config()
    raw_plan = call_llm_planner(
        raw_text,
        context,
        planner_tools=planner_tools,
        tool_call_tools=tool_call_tools,
    )
    normalized = normalize_planner_plan(raw_text, raw_plan)
    return normalized, {
        "enabled": bool(provider),
        "mode": "tool_calling_agent",
        "provider": provider.get("provider") if provider else None,
        "api": provider.get("api") if provider else None,
        "model": provider.get("model") if provider else None,
        "company_code": company_code,
        "enabled_modules": enabled_modules,
        "planner_tools": [tool.get("name") for tool in planner_tools],
        "tool_call_tools": [(tool.get("function") or {}).get("name") for tool in tool_call_tools],
        "raw_plan": raw_plan,
        "normalized_plan": normalized,
    }


def pydantic_model_dict(value: Any) -> dict[str, Any]:
    if hasattr(value, "model_dump"):
        return value.model_dump(exclude_none=True)
    if hasattr(value, "dict"):
        return value.dict(exclude_none=True)
    return dict(value or {}) if isinstance(value, dict) else {}


def capability_registry_payload() -> dict[str, Any]:
    return {name: pydantic_model_dict(spec) for name, spec in CAPABILITY_REGISTRY.items()}


def normalize_capability_name(value: Any) -> str:
    return normalize_text(str(value or "")).replace(" ", "_").replace("-", "_")


def normalized_capability_proposal(raw: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(raw, dict):
        return None
    payload = raw.get("proposal") if isinstance(raw.get("proposal"), dict) else raw
    if not isinstance(payload, dict):
        return None
    capability = normalize_capability_name(payload.get("capability") or payload.get("intent"))
    if capability in {"", "null", "none", "no_action"}:
        return None
    if capability not in CAPABILITY_REGISTRY:
        return None
    data = dict(payload)
    data["capability"] = capability
    data["entity_type"] = normalize_capability_name(data.get("entity_type") or data.get("entity"))
    data["target_ref"] = normalize_capability_name(data.get("target_ref") or data.get("target"))
    if data.get("channel"):
        data["channel"] = normalize_capability_name(data.get("channel"))
    if data.get("field"):
        data["field"] = normalize_capability_name(data.get("field"))
    if data.get("purpose"):
        data["purpose"] = normalize_capability_name(data.get("purpose"))
    if data.get("new_stage"):
        data["new_stage"] = normalize_capability_name(data.get("new_stage"))
    if data.get("operation"):
        data["operation"] = normalize_capability_name(data.get("operation"))
    filters = data.get("filters") if isinstance(data.get("filters"), dict) else {}
    data["filters"] = filters
    targets = data.get("targets") if isinstance(data.get("targets"), list) else []
    data["targets"] = [item for item in targets if isinstance(item, dict)]
    try:
        proposal = CapabilityProposal(**data)
    except Exception:
        return None
    normalized = pydantic_model_dict(proposal)
    normalized["confidence"] = planner_confidence(normalized.get("confidence"))
    return normalized


def dialog_intent_from_capability_proposal(proposal: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(proposal, dict):
        return None
    capability = normalize_capability_name(proposal.get("capability"))
    if not capability:
        return None
    if capability == "small_talk":
        intent = "small_talk"
    elif capability == "filter_refine":
        intent = "analytical_refinement"
    elif capability == "retry_repair":
        intent = "correction_objection"
    elif capability == "explain_history":
        intent = "correction_objection"
    else:
        intent = "capability_request"
    try:
        dialog = DialogIntent(
            intent=intent,
            capability=capability,
            target_refs=proposal.get("targets") if isinstance(proposal.get("targets"), list) else [],
            filters=proposal.get("filters") if isinstance(proposal.get("filters"), dict) else {},
            clarification_ref=proposal.get("clarification_ref"),
            proposal=json_safe(proposal),
            confidence=planner_confidence(proposal.get("confidence")),
            reason=proposal.get("reason"),
        )
    except Exception:
        return None
    return pydantic_model_dict(dialog)


def call_dialog_interpreter(
    *,
    text: str,
    request: WhatsAppTurnRequest,
    context: dict[str, Any] | None,
    turn_id: str | None = None,
) -> dict[str, Any] | None:
    proposal = call_capability_planner(text=text, request=request, context=context, turn_id=turn_id)
    return dialog_intent_from_capability_proposal(proposal)


def dialog_intent_proposal(dialog_intent: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(dialog_intent, dict):
        return None
    proposal = dialog_intent.get("proposal") if isinstance(dialog_intent.get("proposal"), dict) else None
    if proposal:
        return normalized_capability_proposal(proposal)
    capability = normalize_capability_name(dialog_intent.get("capability"))
    if not capability:
        return None
    return normalized_capability_proposal(
        {
            "capability": capability,
            "targets": dialog_intent.get("target_refs") if isinstance(dialog_intent.get("target_refs"), list) else [],
            "filters": dialog_intent.get("filters") if isinstance(dialog_intent.get("filters"), dict) else {},
            "confidence": dialog_intent.get("confidence"),
            "reason": dialog_intent.get("reason"),
        }
    )


def capability_planner_context(request: WhatsAppTurnRequest, context: dict[str, Any] | None) -> dict[str, Any]:
    current = persistent_context_pruned(context)
    focus = current.get("focus") if isinstance(current.get("focus"), dict) else {}
    return {
        "company_code": request_company_code(request),
        "sender_role": request.sender_role,
        "current_candidate": json_safe(candidate_focus_for_context(current)),
        "primary_entity": json_safe(focus.get("primary_entity") if isinstance(focus, dict) else None),
        "last_successful_action": json_safe(current.get("last_successful_action")),
        "last_failed_action": json_safe(current.get("last_failed_action")),
        "enabled_modules": sorted(configured_company_modules(request_company_code(request))),
        "allowed_capabilities": capability_registry_payload(),
    }


def call_capability_planner(
    *,
    text: str,
    request: WhatsAppTurnRequest,
    context: dict[str, Any] | None,
    turn_id: str | None = None,
    timeout: int = 8,
) -> dict[str, Any] | None:
    provider = planner_provider_config()
    if not provider:
        return None
    system = openclaw_augmented_system_prompt(CAPABILITY_PLANNER_BASE_SYSTEM, prompt_name="capability_planner", context_mode="concise")
    payload = {
        "latest_user_message": text,
        "context": capability_planner_context(request, context),
        "required_shape": {
            "capability": "small_talk | read_check | compare_evaluate | filter_refine | update_record | send_message | change_stage | explain_history | retry_repair | none",
            "entity_type": "candidate | optional",
            "target_ref": "current_candidate | explicit | optional",
            "target_text": "explicit target phrase if present",
            "operation": "for compare_evaluate: compare | evaluate | rank",
            "targets": [
                {"ref": "him", "resolution_hint": "current_candidate", "type": "pronoun"},
                {"ref": "candidate name or alias", "type": "candidate_name"}
            ],
            "field": "for update_record, e.g. notes",
            "value": "exact user-provided value for update_record",
            "channel": "for send_message, e.g. email",
            "purpose": "for send_message, e.g. onboarding_compliance",
            "new_stage": "for change_stage, e.g. shortlisted",
            "filters": "object for filter_refine",
            "confidence": "0.0-1.0",
            "reason": "brief interpretation reason",
        },
    }
    if provider.get("api") == "openai-responses":
        body = {
            "model": provider["model"],
            "temperature": 0,
            "input": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    else:
        body = {
            "model": provider["model"],
            "temperature": 0,
            "response_format": {"type": "json_object"},
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    start = time_module.monotonic()
    estimated_tokens = estimate_tokens_from_payload(body)
    prompt_hash = stable_text_hash(system)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception as exc:
        record_llm_call(
            turn_id=turn_id,
            call_name="capability_planner",
            provider=provider,
            prompt_mode="concise",
            prompt_docs_loaded=True,
            prompt_hash=prompt_hash,
            estimated_input_tokens=estimated_tokens,
            latency_ms=int((time_module.monotonic() - start) * 1000),
            status="error",
            error=str(exc),
            metadata={"message_chars": len(text or "")},
        )
        return None
    record_llm_call(
        turn_id=turn_id,
        call_name="capability_planner",
        provider=provider,
        prompt_mode="concise",
        prompt_docs_loaded=True,
        prompt_hash=prompt_hash,
        estimated_input_tokens=estimated_tokens,
        latency_ms=int((time_module.monotonic() - start) * 1000),
        status="ok",
        parsed=parsed,
        metadata={"message_chars": len(text or "")},
    )
    result = extract_json_object(extract_model_text(parsed))
    return normalized_capability_proposal(result)


def note_value_from_text(text: str) -> str:
    raw = re.sub(r"\s+", " ", str(text or "").replace("…", " ")).strip()
    for pattern in (
        r"\bwrite\s+(.+)$",
        r"\b(?:note|notes)\s+(?:that|as)\s+(.+)$",
        r"\b(?:add|update|set)\s+(?:a\s+)?notes?(?:\s+about\s+.+?)?\s*(?:to|as|:|-)\s+(.+)$",
    ):
        match = re.search(pattern, raw, flags=re.IGNORECASE)
        if match:
            return match.group(1).strip(" .")
    return ""


def capability_purpose_from_text(text: str) -> str:
    normalized = normalize_text(text)
    if re.search(r"\b(onboarding|compliance|requirements?|civil id|passport|iban|documents?)\b", normalized):
        return "onboarding_compliance"
    if re.search(r"\b(assessment|test|exam)\b", normalized) and re.search(r"\b(remind|reminder|follow up|follow-up)\b", normalized):
        return "assessment_reminder"
    if re.search(r"\b(assessment|test|exam)\b", normalized):
        return "assessment"
    if re.search(r"\b(interview|meeting)\b", normalized):
        return "interview"
    return "general"


def rule_based_capability_proposal(text: str) -> dict[str, Any] | None:
    normalized = normalize_text(text)
    if not normalized or len(normalized) > 260:
        return None
    if re.search(r"\b(compare|versus|vs|against|better|which)\b", normalized):
        targets = [{"ref": ref, "type": "candidate_name"} for ref in compare_target_refs_from_message(text)]
        return {
            "capability": "compare_evaluate",
            "entity_type": "candidate",
            "operation": "compare",
            "targets": targets,
            "confidence": 0.84 if targets else 0.72,
            "reason": "rule_based_compare_targets",
        }
    if re.search(r"\b(note|notes)\b", normalized) and re.search(r"\b(add|update|set|write|save)\b", normalized):
        return {
            "capability": "update_record",
            "entity_type": "candidate" if re.search(r"\b(candidate|him|her|them|talal|applicant)\b", normalized) else "",
            "target_ref": "current_candidate" if followup_reference_in_text(text) else "",
            "field": "notes",
            "value": note_value_from_text(text),
            "confidence": 0.86,
            "reason": "rule_based_candidate_notes_update",
        }
    mutation_action = candidate_mutation_action_type_from_text(text)
    if mutation_action in {"shortlist_candidate", "hire_candidate", "reject_candidate"}:
        stage = {"shortlist_candidate": "shortlisted", "hire_candidate": "hired", "reject_candidate": "rejected"}[mutation_action]
        return {
            "capability": "change_stage",
            "entity_type": "candidate",
            "target_ref": "current_candidate" if followup_reference_in_text(text) else "explicit",
            "target_text": text,
            "new_stage": stage,
            "confidence": 0.84,
            "reason": "rule_based_candidate_stage_change",
        }
    if re.search(r"\bemail\b", normalized) and re.search(r"\b(send|email|message)\b", normalized):
        return {
            "capability": "send_message",
            "entity_type": "candidate",
            "target_ref": "current_candidate" if followup_reference_in_text(text) else "explicit",
            "target_text": text,
            "channel": "email",
            "purpose": capability_purpose_from_text(text),
            "confidence": 0.82,
            "reason": "rule_based_candidate_email",
        }
    return None


def is_hr_phone(phone: str) -> bool:
    targets = phone_identity_candidates(phone)
    if not targets:
        return False
    companies_root = WORKSPACE / "data" / "companies"
    for path in companies_root.glob("*/hr-users.json"):
        users = read_json(path, {}).get("users") or []
        for user in users:
            candidate = user.get("phone") if isinstance(user, dict) else user
            if phone_identity_candidates(str(candidate)) & targets:
                return True
    return False


def hr_admin_users(company_code: str | None = None) -> list[dict[str, str]]:
    company = (company_code or "").upper()
    roots = [WORKSPACE / "data" / "companies" / company / "hr-users.json"] if company else list((WORKSPACE / "data" / "companies").glob("*/hr-users.json"))
    users_out: list[dict[str, str]] = []
    seen: set[str] = set()
    for path in roots:
        payload = read_json(path, {})
        resolved_company = str(payload.get("company_code") or path.parent.name).upper()
        for user in payload.get("users") or []:
            if isinstance(user, dict):
                phone = digits(user.get("phone"))
                name = str(user.get("name") or "").strip()
                email = normalize_email(user.get("email"))
                role = str(user.get("role") or "admin").strip()
                active = user.get("active", user.get("is_active", True))
                status = str(user.get("status") or "").strip().lower()
            else:
                phone = digits(str(user))
                name = ""
                email = ""
                role = "admin"
                active = True
                status = ""
            if not phone or phone in seen:
                continue
            seen.add(phone)
            users_out.append({"phone": phone, "name": name, "email": email, "role": role, "company_code": resolved_company, "active": active, "status": status})
    return users_out


