def candidate_name_from_row(row: dict[str, Any]) -> str:
    raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
    candidate_raw = row.get("candidate_raw_json") if isinstance(row.get("candidate_raw_json"), dict) else {}
    return (
        str(row.get("candidate_name") or "").strip()
        or str(candidate_raw.get("name") or "").strip()
        or str(raw_json.get("candidate_name") or raw_json.get("name") or "").strip()
        or str(row.get("phone") or "Unknown").strip()
    )


def normalized_search_terms(*values: str | None) -> list[str]:
    stopwords = {
        "show", "list", "find", "rank", "best", "top", "candidate", "candidates", "applicant", "applicants",
        "cv", "cvs", "profile", "profiles", "for", "the", "a", "an", "me", "who", "should", "we", "review",
        "compare", "recommend", "give", "get", "all", "please", "pls",
    }
    joined = normalize_text(" ".join(value or "" for value in values))
    terms = []
    for token in re.findall(r"[a-z0-9\u0600-\u06FF]+", joined):
        if len(token) < 2 or token in stopwords or token.isdigit():
            continue
        terms.append(token)
    seen: set[str] = set()
    unique = []
    for term in terms:
        if term not in seen:
            unique.append(term)
            seen.add(term)
    return unique[:12]


def role_profile_for_position(position: str | None, position_title: str | None = None) -> dict[str, Any]:
    haystack = normalize_text(f"{position or ''} {position_title or ''}".replace("_", " "))
    if not haystack:
        return json_safe(ROLE_EVALUATION_PROFILES[-1])
    best: tuple[int, dict[str, Any]] | None = None
    for profile in ROLE_EVALUATION_PROFILES:
        if profile.get("key") == "general":
            continue
        score = 0
        for term in profile.get("match_terms") or []:
            normalized = normalize_text(str(term))
            if normalized and normalized in haystack:
                score += 2 if " " in normalized else 1
        for criterion in profile.get("criteria") or []:
            for keyword in criterion.get("keywords") or []:
                normalized = normalize_text(str(keyword))
                if normalized and normalized in haystack:
                    score += 1
        if score and (best is None or score > best[0]):
            best = (score, profile)
    return json_safe((best[1] if best else ROLE_EVALUATION_PROFILES[-1]))


def role_profile_keywords(profile: dict[str, Any]) -> list[str]:
    out: list[str] = []
    for criterion in profile.get("criteria") or []:
        if isinstance(criterion, dict):
            out.extend(str(item) for item in criterion.get("keywords") or [] if item)
    seen: set[str] = set()
    unique: list[str] = []
    for item in out:
        normalized = normalize_text(item)
        if normalized and normalized not in seen:
            unique.append(normalized)
            seen.add(normalized)
    return unique


def bounded_ratio_score(hit_count: int, total_count: int, maximum: float) -> float:
    if total_count <= 0:
        return 0.0
    return bounded_score((hit_count / total_count) * maximum, maximum)


def embedding_provider_config() -> dict[str, str] | None:
    values = planner_env()
    provider = (values.get("WATHEFNI_EMBEDDING_PROVIDER") or "voyage").strip().lower()
    model = (values.get("WATHEFNI_EMBEDDING_MODEL") or "voyage-4-large").strip()
    if provider != "voyage":
        return None
    voyage_env = read_env_file(values.get("WATHEFNI_VOYAGE_ENV"))
    api_key = (
        values.get("VOYAGE_API_KEY")
        or values.get("WATHEFNI_VOYAGE_API_KEY")
        or voyage_env.get("VOYAGE_API_KEY")
        or voyage_env.get("WATHEFNI_VOYAGE_API_KEY")
    )
    if not api_key:
        return None
    return {"provider": provider, "model": model, "api_key": api_key, "url": "https://api.voyageai.com/v1/embeddings"}


def embed_rank_query(text: str) -> list[float] | None:
    query = (text or "").strip()
    if not query:
        return None
    cfg = embedding_provider_config()
    if not cfg:
        return None
    body = {"input": [query], "model": cfg["model"], "input_type": "query"}
    req = urllib.request.Request(
        cfg["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {cfg['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=12) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception:
        return None
    data = parsed.get("data") if isinstance(parsed, dict) else None
    if not isinstance(data, list) or not data:
        return None
    embedding = data[0].get("embedding") if isinstance(data[0], dict) else None
    if not isinstance(embedding, list):
        return None
    vector: list[float] = []
    for value in embedding:
        try:
            vector.append(float(value))
        except Exception:
            return None
    return vector or None


def pgvector_literal(vector: list[float]) -> str:
    return "[" + ",".join(f"{value:.8f}" for value in vector) + "]"


def status_rank_score(status: str | None) -> float:
    normalized = str(status or "").strip().lower()
    return {
        "screening_complete": 45,
        "review_pending": 40,
        "shortlisted": 38,
        "screening": 30,
        "cv_received": 24,
        "awaiting_cv": 8,
        "hired": 4,
        "rejected": -20,
    }.get(normalized, 18)


def bounded_score(value: float, maximum: float) -> float:
    return max(0.0, min(maximum, value))


def candidate_ranking_text(row: dict[str, Any]) -> str:
    raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
    candidate_raw = row.get("candidate_raw_json") if isinstance(row.get("candidate_raw_json"), dict) else {}
    candidate_profile = row.get("candidate_profile") if isinstance(row.get("candidate_profile"), dict) else {}
    assessment_report = row.get("assessment_report_json") if isinstance(row.get("assessment_report_json"), dict) else {}
    interview_summary = row.get("interview_ai_summary") if isinstance(row.get("interview_ai_summary"), dict) else {}
    return normalize_text(
        " ".join(
            [
                str(row.get("position_code") or ""),
                str(row.get("position_title") or ""),
                str(row.get("status") or ""),
                candidate_name_from_row(row),
                str(row.get("candidate_email") or ""),
                json.dumps(candidate_profile, ensure_ascii=False),
                json.dumps(candidate_raw, ensure_ascii=False),
                json.dumps(raw_json, ensure_ascii=False),
                json.dumps(assessment_report, ensure_ascii=False),
                json.dumps(interview_summary, ensure_ascii=False),
                str(row.get("interview_notes") or ""),
                str(row.get("semantic_content") or ""),
            ]
        )
    )


def row_assessment_signal(row: dict[str, Any]) -> dict[str, Any]:
    percent = first_present(row.get("assessment_percent"), row.get("assessment_report_job_match_percent"), missing=None)
    try:
        numeric_percent = float(percent) if percent is not None else None
    except Exception:
        numeric_percent = None
    status = str(row.get("assessment_status") or "").lower()
    has_completed_evidence = status == "completed" and numeric_percent is not None
    if has_completed_evidence:
        score = bounded_score((numeric_percent / 100) * 10, 10)
        label = f"Assessment score is {numeric_percent:.0f}%."
    elif status == "completed":
        score = 0
        numeric_percent = None
        label = "Assessment is complete, but usable numeric evidence is missing."
    elif status in {"in_progress", "pending", "cancelled", "expired"}:
        score = 0
        numeric_percent = None
        label = f"Assessment is {status.replace('_', ' ')} and does not contribute ranking evidence."
    else:
        score = 0
        numeric_percent = None
        label = "Assessment result is missing."
    return {
        "score": score,
        "label": label,
        "percent": numeric_percent,
        "status": status or None,
        "has_completed_evidence": has_completed_evidence,
    }


def row_interview_signal(row: dict[str, Any]) -> dict[str, Any]:
    status = str(row.get("interview_status") or "").lower()
    feedback = str(row.get("interview_feedback_status") or "").lower()
    has_summary = isinstance(row.get("interview_ai_summary"), dict) and bool(row.get("interview_ai_summary"))
    has_notes = bool(str(row.get("interview_notes") or "").strip())
    score = 0.0
    if status == "completed":
        score += 3
    elif status in {"scheduled", "rescheduled"}:
        score += 1.5
    elif status in {"no_show", "cancelled"}:
        score -= 2
    if feedback == "feedback_complete":
        score += 2
    if has_summary:
        score += 2
    elif has_notes:
        score += 1
    score = bounded_score(score, 8)
    if status or feedback or has_summary or has_notes:
        label = f"Interview is {stage_word(status or 'not scheduled')} with {stage_word(feedback or 'notes pending')}."
    else:
        label = "No interview feedback is stored yet."
    return {"score": score, "label": label, "status": status or None, "feedback_status": feedback or None, "has_summary": has_summary}


def stage_word(value: str | None) -> str:
    return str(value or "").replace("_", " ")


def confidence_label(score: float) -> str:
    if score >= 7:
        return "high"
    if score >= 4:
        return "medium"
    return "low"


def rank_candidate_row(
    row: dict[str, Any],
    *,
    query: str,
    position: str | None,
    terms: list[str],
    role_profile: dict[str, Any],
) -> tuple[float, dict[str, float], list[str], str, list[str]]:
    raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
    candidate_raw = row.get("candidate_raw_json") if isinstance(row.get("candidate_raw_json"), dict) else {}
    candidate_profile = row.get("candidate_profile") if isinstance(row.get("candidate_profile"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    cv = raw_json.get("cv") if isinstance(raw_json.get("cv"), dict) else {}
    text_blob = candidate_ranking_text(row)
    evidence: list[str] = []
    status = str(row.get("status") or "").replace("_", " ")
    if status:
        evidence.append(f"Current stage is {status}.")

    role_fit = 0.0
    if position:
        position_norm = normalize_text(position.replace("_", " "))
        position_text = normalize_text(f"{row.get('position_code') or ''} {row.get('position_title') or ''}".replace("_", " "))
        if position_norm and position_norm in position_text:
            role_fit += 8
            evidence.append(f"Application is for {row.get('position_title') or row.get('position_code')}.")
        elif any(token in position_text for token in position_norm.split() if len(token) >= 2):
            role_fit += 5
            evidence.append(f"Application is related to {row.get('position_title') or row.get('position_code')}.")

    semantic_similarity = row.get("semantic_similarity")
    try:
        semantic_score = float(semantic_similarity) if semantic_similarity is not None else None
    except Exception:
        semantic_score = None
    if semantic_score is not None:
        role_fit += bounded_score(max(0.0, semantic_score) * 8, 8)
        if semantic_score >= 0.55:
            evidence.append(f"Profile content semantically matches this role ({semantic_score:.2f}).")

    matched_terms = [term for term in terms if term in text_blob]
    if matched_terms:
        role_fit += min(4, len(matched_terms))
        evidence.append("Candidate data matches " + ", ".join(matched_terms[:4]) + ".")
    role_fit = bounded_score(role_fit, 20)

    role_keywords = role_profile_keywords(role_profile)
    role_keyword_hits = [keyword for keyword in role_keywords if keyword in text_blob]
    skill_match = bounded_ratio_score(len(role_keyword_hits), max(4, min(len(role_keywords), 12)), 20)
    criterion_notes: list[str] = []
    for criterion in role_profile.get("criteria") or []:
        if not isinstance(criterion, dict):
            continue
        hits = [str(keyword) for keyword in criterion.get("keywords") or [] if normalize_text(str(keyword)) in text_blob]
        if hits:
            criterion_notes.append(f"{criterion.get('label')}: {', '.join(hits[:3])}")
    if role_keyword_hits:
        evidence.append(f"Role-specific evidence for {role_profile.get('label')}: " + ", ".join(role_keyword_hits[:5]) + ".")

    experience_markers = [
        "experience", "years", "worked", "manager", "managed", "led", "lead", "specialist", "campaign",
        "sales", "social", "media", "marketing", "hr", "recruit", "operations", "customer", "portfolio",
        "kuwait", "arabic", "english",
    ]
    experience_hits = [marker for marker in [*experience_markers, *role_keyword_hits[:8]] if marker in text_blob]
    experience = bounded_score(3 + min(12, len(set(experience_hits)) * 1.5), 15) if (candidate_profile or candidate_raw or raw_json or text_blob) else 0
    if experience_hits:
        evidence.append("Experience signals include " + ", ".join(experience_hits[:4]) + ".")

    cv_evidence_markers = [
        "achieved", "increased", "improved", "built", "launched", "created", "grew", "reduced", "award",
        "certified", "certificate", "portfolio", "project", "campaign", "roi", "%", "percent", "education",
        "degree", "skills", "summary",
    ]
    cv_evidence = 0.0
    if row.get("cv_received") is True or isinstance(raw_json.get("cv"), dict):
        cv_evidence += 4
        evidence.append("CV is received.")
    cv_evidence_hits = [marker for marker in cv_evidence_markers if marker in text_blob]
    cv_evidence += bounded_score(len(cv_evidence_hits) * 1.5, 6)
    cv_evidence = bounded_score(cv_evidence, 10)
    if cv_evidence_hits:
        evidence.append("CV evidence includes " + ", ".join(cv_evidence_hits[:4]) + ".")

    screening_quality = 0.0
    if str(screening.get("status") or row.get("screening_status") or "").lower() == "complete":
        screening_quality += 8
        evidence.append("Screening is complete.")
    elif screening or row.get("screening_status"):
        screening_quality += 5
        evidence.append("Screening has candidate data.")
    if isinstance(screening.get("answers"), (dict, list)) or isinstance(screening.get("responses"), (dict, list)):
        screening_quality += 2
    screening_quality = bounded_score(screening_quality, 10)

    assessment_signal = row_assessment_signal(row)
    assessment_score = bounded_score(float(assessment_signal.get("score") or 0), 10)
    if assessment_score:
        evidence.append(str(assessment_signal["label"]))

    interview_signal = row_interview_signal(row)
    interview_score = bounded_score(float(interview_signal.get("score") or 0), 8)
    if interview_score or interview_signal.get("status"):
        evidence.append(str(interview_signal["label"]))

    readiness = bounded_score((status_rank_score(row.get("status")) / 45) * 4, 4)
    if row.get("phone"):
        readiness += 1
    readiness = bounded_score(readiness, 5)

    confidence_score = 0.0
    if candidate_profile:
        confidence_score += 2
    if candidate_raw:
        confidence_score += 1
    if raw_json:
        confidence_score += 2
    if cv:
        confidence_score += 2
    if screening:
        confidence_score += 2
    if row.get("semantic_content") or semantic_score is not None:
        confidence_score += 1
    if assessment_signal.get("has_completed_evidence"):
        confidence_score += 1
    if interview_signal.get("status") or interview_signal.get("has_summary"):
        confidence_score += 1
    confidence_score = bounded_score(confidence_score, 10)
    if confidence_score < 4:
        evidence.append("Low confidence: limited candidate evidence is available.")

    breakdown = {
        "role_fit": round(role_fit, 1),
        "skill_match": round(skill_match, 1),
        "experience": round(experience, 1),
        "cv_evidence": round(cv_evidence, 1),
        "screening": round(screening_quality, 1),
        "assessment": round(assessment_score, 1),
        "interview": round(interview_score, 1),
        "readiness": round(readiness, 1),
        "confidence": round((confidence_score / 10) * 2, 1),
    }
    score = sum(breakdown.values())
    evidence.extend(criterion_notes[:2])
    if not evidence:
        evidence.append("Ranked from available application status and candidate data.")
    return score, breakdown, evidence[:6], confidence_label(confidence_score), matched_terms[:6]


def compact_for_rank_evaluation(value: Any, *, max_chars: int = RANKING_EVIDENCE_TEXT_LIMIT) -> Any:
    safe = json_safe(value)
    if isinstance(safe, str):
        return safe[:max_chars]
    if isinstance(safe, (dict, list)):
        text = json.dumps(safe, ensure_ascii=False)
        if len(text) <= max_chars:
            return safe
        return text[:max_chars]
    return safe


def ranking_evidence_digest(candidate: dict[str, Any], role_profile: dict[str, Any]) -> str:
    payload = {
        "app_key": candidate.get("app_key"),
        "score": candidate.get("score"),
        "breakdown": candidate.get("score_breakdown"),
        "role_profile_key": role_profile.get("key"),
        "evidence": candidate.get("evidence") or candidate.get("reasons"),
        "application": compact_for_rank_evaluation(candidate.get("application"), max_chars=1200),
    }
    return hashlib.sha256(json.dumps(json_safe(payload), sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()


def deterministic_rank_evaluation(candidate: dict[str, Any], role_profile: dict[str, Any]) -> dict[str, Any]:
    reasons = [str(item) for item in (candidate.get("evidence") or candidate.get("reasons") or [])[:4]]
    missing: list[str] = []
    application = candidate.get("application") if isinstance(candidate.get("application"), dict) else {}
    if not (application.get("cv") or {}).get("received"):
        missing.append("CV evidence is missing or not parsed yet.")
    if not application.get("assessment"):
        missing.append("Assessment result is missing.")
    if not application.get("interview"):
        missing.append("Interview feedback is missing.")
    return {
        "source": "deterministic_fallback",
        "fit_summary": f"{candidate.get('name') or 'This candidate'} is ranked from stored evidence for {role_profile.get('label') or 'this role'}.",
        "strengths": reasons[:3] or ["Stored application evidence is available."],
        "gaps": missing[:3] or ["No major evidence gaps detected from stored fields."],
        "risks": ["Human review is still required before a hiring decision."],
        "recommended_next_step": "Review the candidate profile and verify the strongest evidence before taking action.",
        "confidence": candidate.get("confidence") or "medium",
        "criterion_notes": reasons[:4],
    }


def sanitize_rank_evaluation(value: Any, candidate: dict[str, Any], role_profile: dict[str, Any]) -> dict[str, Any]:
    fallback = deterministic_rank_evaluation(candidate, role_profile)
    if not isinstance(value, dict):
        return fallback
    out = dict(fallback)
    for key in ("fit_summary", "recommended_next_step", "confidence", "source"):
        if isinstance(value.get(key), str) and value[key].strip():
            out[key] = value[key].strip()[:1200]
    for key in ("strengths", "gaps", "risks", "criterion_notes"):
        items = value.get(key)
        if isinstance(items, list):
            cleaned = [str(item).strip()[:500] for item in items if str(item).strip()]
            if cleaned:
                out[key] = cleaned[:6]
    out["source"] = str(out.get("source") or "gpt_structured")
    return out


def gpt_rank_evaluation_payload(candidates: list[dict[str, Any]], role_profile: dict[str, Any], query: str) -> dict[str, Any]:
    packed_candidates = []
    for candidate in candidates:
        application = candidate.get("application") if isinstance(candidate.get("application"), dict) else {}
        packed_candidates.append(
            {
                "app_key": candidate.get("app_key"),
                "name": candidate.get("name"),
                "position": candidate.get("position_title") or candidate.get("position_code"),
                "status": candidate.get("status"),
                "deterministic_score": candidate.get("score"),
                "score_breakdown": candidate.get("score_breakdown"),
                "stored_evidence": candidate.get("evidence") or candidate.get("reasons") or [],
                "matched_terms": candidate.get("matched_terms") or [],
                "candidate_profile": compact_for_rank_evaluation((application.get("candidate") or {}).get("profile"), max_chars=900),
                "application_raw": compact_for_rank_evaluation(application.get("raw_json"), max_chars=1400),
                "assessment": compact_for_rank_evaluation(application.get("assessment"), max_chars=900),
                "interview": compact_for_rank_evaluation(application.get("interview"), max_chars=900),
                "assessment_signal": compact_for_rank_evaluation(candidate.get("assessment_signal"), max_chars=600),
                "interview_signal": compact_for_rank_evaluation(candidate.get("interview_signal"), max_chars=600),
                "assessment_report": compact_for_rank_evaluation(candidate.get("assessment_report"), max_chars=1000),
            }
        )
    return {
        "task": "Evaluate candidate fit for ranking. Return JSON only. Do not invent missing evidence.",
        "query": query,
        "role_profile": role_profile,
        "candidates": packed_candidates,
        "required_output": {
            "evaluations": [
                {
                    "app_key": "candidate app key",
                    "fit_summary": "short recruiter-style explanation grounded in evidence",
                    "strengths": ["specific strengths"],
                    "gaps": ["missing or weak evidence"],
                    "risks": ["risks HR should verify"],
                    "recommended_next_step": "safe next action for HR",
                    "confidence": "low|medium|high",
                    "criterion_notes": ["role-specific criterion notes"],
                }
            ]
        },
        "rules": [
            "Use the role_profile criteria as the evaluation lens.",
            "Mention missing assessment, CV, screening, or interview evidence as gaps.",
            "Do not change or create numeric scores.",
            "HR remains the final decision-maker.",
        ],
    }


def call_gpt_rank_evaluator(candidates: list[dict[str, Any]], role_profile: dict[str, Any], query: str) -> tuple[dict[str, dict[str, Any]], dict[str, Any]]:
    provider = planner_provider_config()
    if not provider or not candidates:
        return {}, {"used": False, "reason": "provider_unavailable"}
    env_values = planner_env()
    model = env_values.get("WATHEFNI_RANKING_EVALUATOR_MODEL") or provider["model"]
    provider = {**provider, "model": model}
    system = (
        "You are OctoHR's structured recruiting evaluator. Evaluate candidate fit only from provided evidence. "
        "Return valid JSON with an evaluations array. Do not invent facts, do not make hiring decisions, and do not alter numeric scores."
    )
    user_payload = gpt_rank_evaluation_payload(candidates, role_profile, query)
    if provider.get("api") == "openai-responses":
        body = {
            "model": model,
            "temperature": 0,
            "input": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(user_payload, ensure_ascii=False)},
            ],
        }
    else:
        body = {
            "model": model,
            "temperature": 0,
            "response_format": {"type": "json_object"},
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(user_payload, ensure_ascii=False)},
            ],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    start = time_module.monotonic()
    estimated_tokens = estimate_tokens_from_payload(body)
    prompt_hash = stable_text_hash(system)
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception as exc:
        record_llm_call(
            call_name="rank_evaluator",
            provider=provider,
            prompt_mode="structured_json",
            prompt_docs_loaded=False,
            prompt_hash=prompt_hash,
            estimated_input_tokens=estimated_tokens,
            latency_ms=int((time_module.monotonic() - start) * 1000),
            status="error",
            error=str(exc),
            metadata={"candidate_count": len(candidates), "role_profile_key": role_profile.get("key")},
        )
        return {}, {"used": False, "reason": "llm_error", "model": model}
    record_llm_call(
        call_name="rank_evaluator",
        provider=provider,
        prompt_mode="structured_json",
        prompt_docs_loaded=False,
        prompt_hash=prompt_hash,
        estimated_input_tokens=estimated_tokens,
        latency_ms=int((time_module.monotonic() - start) * 1000),
        status="ok",
        parsed=parsed,
        metadata={"candidate_count": len(candidates), "role_profile_key": role_profile.get("key")},
    )
    content = extract_model_text(parsed)
    extracted = extract_json_object(content) or {}
    evaluations = extracted.get("evaluations") if isinstance(extracted.get("evaluations"), list) else []
    by_app_key: dict[str, dict[str, Any]] = {}
    for item in evaluations:
        if isinstance(item, dict) and item.get("app_key"):
            by_app_key[str(item["app_key"])] = item
    return by_app_key, {"used": bool(by_app_key), "model": model, "provider": provider.get("provider"), "evaluation_count": len(by_app_key)}


def store_rank_evaluation(candidate: dict[str, Any], role_profile: dict[str, Any], company_code: str, metadata: dict[str, Any], *, source: str | None = None) -> None:
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO candidate_rank_evaluations (
                      company_code, app_key, position_code, position_title, role_profile_key, role_profile,
                      deterministic_score, score_breakdown, gpt_evaluation, evidence_digest, model, source
                    )
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    """,
                    (
                        company_code,
                        candidate.get("app_key"),
                        candidate.get("position_code"),
                        candidate.get("position_title"),
                        role_profile.get("key"),
                        Json(json_safe(role_profile)),
                        float(candidate.get("score") or 0),
                        Json(json_safe(candidate.get("score_breakdown") or {})),
                        Json(json_safe(candidate.get("gpt_evaluation") or {})),
                        candidate.get("evidence_digest"),
                        metadata.get("model"),
                        source or str((candidate.get("gpt_evaluation") or {}).get("source") or "ranking"),
                    ),
                )
            conn.commit()
    except Exception:
        return


def rank_evaluation_payload(row: dict[str, Any] | None) -> dict[str, Any] | None:
    if not row:
        return None
    try:
        score = float(row.get("deterministic_score") or 0)
    except Exception:
        score = 0.0
    return {
        "score": round(score, 2),
        "score_breakdown": json_safe(row.get("score_breakdown") if isinstance(row.get("score_breakdown"), dict) else {}),
        "role_profile": json_safe(row.get("role_profile") if isinstance(row.get("role_profile"), dict) else {}),
        "gpt_evaluation": json_safe(row.get("gpt_evaluation") if isinstance(row.get("gpt_evaluation"), dict) else {}),
        "evidence_digest": row.get("evidence_digest"),
        "evaluation_audit": {
            "model": row.get("model"),
            "source": row.get("source"),
            "created_at": json_safe(row.get("created_at")),
        },
    }


def latest_application_rank_evaluation(company_code: str, app_key: str) -> dict[str, Any] | None:
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT *
                    FROM candidate_rank_evaluations
                    WHERE company_code=%s AND app_key=%s
                    ORDER BY
                      CASE source WHEN 'profile_evaluation' THEN 0 ELSE 1 END,
                      created_at DESC
                    LIMIT 1
                    """,
                    (company_code, app_key),
                )
                row = cur.fetchone()
    except Exception:
        return None
    return rank_evaluation_payload(dict(row)) if row else None


def cached_rank_evaluations(candidates: list[dict[str, Any]], company_code: str) -> dict[str, dict[str, Any]]:
    cached: dict[str, dict[str, Any]] = {}
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                for candidate in candidates:
                    app_key = str(candidate.get("app_key") or "")
                    digest = str(candidate.get("evidence_digest") or "")
                    if not app_key or not digest:
                        continue
                    cur.execute(
                        """
                        SELECT gpt_evaluation, model, created_at
                        FROM candidate_rank_evaluations
                        WHERE company_code=%s
                          AND app_key=%s
                          AND evidence_digest=%s
                          AND source='gpt_structured'
                        ORDER BY created_at DESC
                        LIMIT 1
                        """,
                        (company_code, app_key, digest),
                    )
                    row = cur.fetchone()
                    if row and isinstance(row.get("gpt_evaluation"), dict):
                        cached[app_key] = {
                            "gpt_evaluation": row["gpt_evaluation"],
                            "model": row.get("model"),
                            "created_at": row.get("created_at"),
                        }
    except Exception:
        return {}
    return cached


def attach_gpt_rank_evaluations(candidates: list[dict[str, Any]], *, role_profile: dict[str, Any], query: str, company_code: str) -> None:
    for candidate in candidates:
        candidate_role_profile = candidate.get("role_profile") if isinstance(candidate.get("role_profile"), dict) else role_profile
        candidate["evidence_digest"] = ranking_evidence_digest(candidate, candidate_role_profile)
    cached = cached_rank_evaluations(candidates, company_code)
    missing = [candidate for candidate in candidates if str(candidate.get("app_key") or "") not in cached]
    evaluations, metadata = call_gpt_rank_evaluator(missing, role_profile, query)
    for candidate in candidates:
        candidate_role_profile = candidate.get("role_profile") if isinstance(candidate.get("role_profile"), dict) else role_profile
        app_key = str(candidate.get("app_key") or "")
        cached_eval = cached.get(app_key)
        if cached_eval:
            candidate["gpt_evaluation"] = sanitize_rank_evaluation(cached_eval.get("gpt_evaluation"), candidate, candidate_role_profile)
            candidate["gpt_evaluation"]["source"] = "gpt_structured"
            candidate["evaluation_audit"] = {"used": True, "cached": True, "model": cached_eval.get("model"), "created_at": cached_eval.get("created_at")}
            continue
        raw_eval = evaluations.get(app_key)
        candidate["gpt_evaluation"] = sanitize_rank_evaluation(raw_eval, candidate, candidate_role_profile)
        if raw_eval:
            candidate["gpt_evaluation"]["source"] = "gpt_structured"
        candidate["evaluation_audit"] = json_safe(metadata)
        store_rank_evaluation(candidate, candidate_role_profile, company_code, metadata)


def application_rank_row(app_key: str, company_code: str) -> dict[str, Any] | None:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT a.*, c.name AS candidate_name, c.email AS candidate_email,
                       c.profile AS candidate_profile, c.raw_json AS candidate_raw_json,
                       latest_assessment.assessment_status,
                       latest_assessment.assessment_percent,
                       latest_assessment.assessment_report_json,
                       latest_interview.interview_status,
                       latest_interview.interview_feedback_status,
                       latest_interview.interview_notes,
                       latest_interview.interview_ai_summary,
                       latest_interview.interview_json,
                       sd.content AS semantic_content,
                       NULL::double precision AS semantic_similarity
                FROM applications a
                LEFT JOIN candidates c ON c.phone=a.phone
                LEFT JOIN semantic_documents sd ON sd.entity_type='application' AND sd.entity_key=a.app_key
                LEFT JOIN LATERAL (
                  SELECT aa.status AS assessment_status,
                         s.percent AS assessment_percent,
                         r.report_json AS assessment_report_json
                  FROM assessment_attempts aa
                  LEFT JOIN assessment_scores s ON s.attempt_id=aa.attempt_id
                  LEFT JOIN assessment_reports r ON r.attempt_id=aa.attempt_id
                  WHERE aa.company_code=a.company_code AND aa.app_key=a.app_key
                  ORDER BY aa.updated_at DESC, aa.created_at DESC
                  LIMIT 1
                ) latest_assessment ON TRUE
                LEFT JOIN LATERAL (
                  SELECT ci.status AS interview_status,
                         ci.feedback_status AS interview_feedback_status,
                         ci.notes AS interview_notes,
                         ci.ai_summary AS interview_ai_summary,
                         to_jsonb(ci.*) AS interview_json
                  FROM candidate_interviews ci
                  WHERE ci.company_code=a.company_code AND ci.app_key=a.app_key
                  ORDER BY ci.scheduled_start DESC NULLS LAST, ci.updated_at DESC
                  LIMIT 1
                ) latest_interview ON TRUE
                WHERE a.company_code=%s AND a.app_key=%s
                LIMIT 1
                """,
                (company_code, app_key),
            )
            row = cur.fetchone()
    return dict(row) if row else None


def scored_profile_candidate(row: dict[str, Any]) -> dict[str, Any]:
    row_role_profile = role_profile_for_position(row.get("position_code"), row.get("position_title"))
    query = str(row.get("position_title") or row.get("position_code") or "candidate profile evaluation")
    terms = normalized_search_terms(query, row.get("position_code"))
    score, breakdown, evidence, confidence, matched_terms = rank_candidate_row(
        row,
        query=query,
        position=row.get("position_code"),
        terms=terms,
        role_profile=row_role_profile,
    )
    raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    candidate = {
        "score": round(score, 2),
        "score_breakdown": breakdown,
        "confidence": confidence,
        "role_profile": row_role_profile,
        "assessment_signal": row_assessment_signal(row),
        "interview_signal": row_interview_signal(row),
        "assessment_report": json_safe(row.get("assessment_report_json") if isinstance(row.get("assessment_report_json"), dict) else {}),
        "evidence": evidence,
        "app_key": row.get("app_key"),
        "phone": row.get("phone"),
        "name": candidate_name_from_row(row),
        "position_code": row.get("position_code"),
        "position_title": row.get("position_title"),
        "status": row.get("status"),
        "screening_status": row.get("screening_status") or screening.get("status"),
        "matched_terms": matched_terms,
        "reasons": evidence[:4],
        "application": prehire_application_summary(row, include_raw=True, include_assessment=company_has_module(row.get("company_code"), "assessments")),
    }
    candidate["evidence_digest"] = ranking_evidence_digest(candidate, row_role_profile)
    return candidate


def generate_application_profile_evaluation(app_key: str, company_code: str, *, force: bool = False) -> dict[str, Any]:
    row = application_rank_row(app_key, company_code)
    if not row:
        raise HTTPException(status_code=404, detail={"error": "application_not_found"})
    candidate = scored_profile_candidate(row)
    role_profile = candidate.get("role_profile") if isinstance(candidate.get("role_profile"), dict) else role_profile_for_position(row.get("position_code"), row.get("position_title"))
    if not force:
        try:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT *
                        FROM candidate_rank_evaluations
                        WHERE company_code=%s
                          AND app_key=%s
                          AND evidence_digest=%s
                          AND source='profile_evaluation'
                        ORDER BY created_at DESC
                        LIMIT 1
                        """,
                        (company_code, app_key, candidate.get("evidence_digest")),
                    )
                    cached_row = cur.fetchone()
            if cached_row:
                cached_payload = rank_evaluation_payload(dict(cached_row)) or {}
                candidate["gpt_evaluation"] = sanitize_rank_evaluation(cached_payload.get("gpt_evaluation"), candidate, role_profile)
                candidate["gpt_evaluation"]["source"] = "profile_evaluation"
                candidate["evaluation_audit"] = {**(cached_payload.get("evaluation_audit") or {}), "used": True, "cached": True}
                return candidate
        except Exception:
            pass
    evaluations, metadata = call_gpt_rank_evaluator(
        [candidate],
        role_profile,
        f"Individual application fit evaluation for {candidate.get('position_title') or candidate.get('position_code')}",
    )
    raw_eval = evaluations.get(str(candidate.get("app_key") or ""))
    candidate["gpt_evaluation"] = sanitize_rank_evaluation(raw_eval, candidate, role_profile)
    if raw_eval:
        candidate["gpt_evaluation"]["source"] = "profile_evaluation"
    candidate["evaluation_audit"] = json_safe(metadata)
    store_rank_evaluation(candidate, role_profile, company_code, metadata, source="profile_evaluation")
    return candidate


def rank_candidates(action: dict[str, Any], *, company_code: str | None = None) -> dict[str, Any]:
    """Canonical Ranking entrypoint (R0–R3).

    Delegates to ``candidate_ranking`` so dashboard, mobile, and Admin Assistant
    share one job-scoped authority. Requires an exact position/job.
    """
    try:
        result = _candidate_ranking.rank_candidates_compat(sys.modules[__name__], action, company_code=company_code)
        return _ranking_presentation.attach_presentations(
            result,
            locale=str(action.get("locale") or "en"),
            orch=sys.modules[__name__],
            company_code=company_code or result.get("company_code"),
        )
    except _candidate_ranking.RankingError as exc:
        return {"ok": False, "error": exc.code, "message": str(exc), "details": exc.details, "action": action}



def format_rank_candidates_reply(result: dict[str, Any]) -> str:
    if result.get("ok") is False:
        return str(result.get("message") or result.get("error") or "Ranking failed.")
    locale = str((result.get("presentation_contract") or {}).get("locale") or "en")
    return _ranking_presentation.format_assistant_result(result, locale=locale)


def candidate_cv_evaluation(action: dict[str, Any], *, company_code: str | None = None) -> dict[str, Any]:
    company = str(company_code or "").strip().upper()
    if not company:
        return {"ok": False, "error": "tenant_scope_required", "action": action}
    app_key = str(action.get("app_key") or action.get("subject_key") or "").strip()
    if app_key:
        app = find_application_by_key(app_key, company_code=company)
        if not app:
            return {"ok": False, "error": "candidate_not_found", "action": action}
        item = compare_candidate_item({"app_key": app_key}, company_code=company)
        strengths, gaps = candidate_strengths_and_gaps(item)
        evaluated = [{
            "app_key": item.get("app_key"),
            "name": item.get("name"),
            "job": item.get("job"),
            "stage": item.get("stage"),
            "cv_status": item.get("cv_status"),
            "assessment_status": item.get("assessment_status"),
            "assessment_score": item.get("assessment_score"),
            "stored_data_score": item.get("ranking_score"),
            "confidence": "single_candidate",
            "stored_evidence": strengths,
            "accomplishment_evidence": [],
            "gaps": gaps,
        }]
        return {
            "ok": True,
            "query": action.get("query") or action.get("prompt_text"),
            "candidates": evaluated,
            "recommended_next_action": f"Review {item.get('name')} from the stored candidate record before making a decision.",
            "data_policy": "Evaluated only stored application, CV, assessment, ranking, and screening fields. Missing data is shown as missing.",
            "selected_application": candidate_lookup_match_payload(app),
            "action": action,
        }
    ranking = rank_candidates(
        {
            **action,
            "top_n": action.get("top_n") or 5,
            "query": action.get("query") or action.get("prompt_text") or "candidate CV evaluation",
        },
        company_code=company,
    )
    if not ranking.get("ok"):
        return {**ranking, "ok": False, "action": action}
    candidates = ranking.get("candidates") if isinstance(ranking.get("candidates"), list) else []
    evaluated: list[dict[str, Any]] = []
    for candidate in candidates:
        application = candidate.get("application") if isinstance(candidate.get("application"), dict) else {}
        cv = application.get("cv") if isinstance(application.get("cv"), dict) else {}
        assessment = application.get("assessment") if isinstance(application.get("assessment"), dict) else {}
        reasons = candidate.get("reasons") if isinstance(candidate.get("reasons"), list) else []
        accomplishment_reasons = [str(reason) for reason in reasons if "Accomplishment signals" in str(reason)]
        gaps: list[str] = []
        if not cv.get("received"):
            gaps.append("CV content/status is missing")
        if not assessment:
            gaps.append("Assessment result is missing")
        if not accomplishment_reasons:
            gaps.append("No explicit accomplishment markers are stored")
        evaluated.append(
            {
                "app_key": candidate.get("app_key"),
                "name": candidate.get("name"),
                "job": candidate.get("position_title") or candidate.get("position_code"),
                "stage": candidate.get("status"),
                "cv_status": "received" if cv.get("received") else "missing",
                "assessment_status": assessment.get("status") if isinstance(assessment, dict) else "missing",
                "assessment_score": first_present(
                    assessment.get("score") if isinstance(assessment, dict) else None,
                    assessment.get("percent") if isinstance(assessment, dict) else None,
                    missing="missing",
                ),
                "stored_data_score": candidate.get("score"),
                "confidence": candidate.get("confidence"),
                "stored_evidence": [str(reason) for reason in reasons[:4]],
                "accomplishment_evidence": accomplishment_reasons,
                "gaps": gaps or ["No stored-data gaps identified"],
            }
        )
    recommended = evaluated[0] if evaluated else None
    return {
        "ok": bool(evaluated),
        "query": action.get("query") or action.get("prompt_text"),
        "candidates": evaluated,
        "recommended_next_action": (
            f"Review {recommended.get('name')} first because this candidate has the highest deterministic score from stored CV/application data."
            if recommended
            else "No grounded recommendation is available because I could not find stored candidate/CV records."
        ),
        "data_policy": "Evaluated only stored application, CV, assessment, ranking, and screening fields. Missing data is shown as missing.",
        "ranking_result": json_safe(ranking),
    }


def format_candidate_cv_evaluation_reply(result: dict[str, Any]) -> str:
    candidates = result.get("candidates") if isinstance(result.get("candidates"), list) else []
    if not candidates:
        return "I could not evaluate candidates from CVs because I do not have stored candidate/CV records for that request."
    lines = ["Candidate/CV evaluation (stored data only):"]
    for idx, candidate in enumerate(candidates[:5], 1):
        evidence = candidate.get("stored_evidence") if isinstance(candidate.get("stored_evidence"), list) else []
        gaps = candidate.get("gaps") if isinstance(candidate.get("gaps"), list) else []
        evidence_text = format_inline_list([str(item) for item in evidence]) if evidence else "No stored evidence beyond basic application fields"
        gap_text = format_inline_list([str(item) for item in gaps]) if gaps else "No stored gaps identified"
        lines.append(
            f"{idx}. {candidate.get('name') or 'Candidate'} — {candidate.get('job') or 'job missing'} | "
            f"stage: {candidate.get('stage') or 'missing'} | CV: {candidate.get('cv_status')} | "
            f"assessment: {candidate.get('assessment_status')} / score {candidate.get('assessment_score')} | "
            f"stored-data score: {candidate.get('stored_data_score')} ({candidate.get('confidence')})\n"
            f"   Evidence: {evidence_text}\n"
            f"   Missing/gaps: {gap_text}"
        )
    lines.append(f"\nRecommended next action: {result.get('recommended_next_action')}")
    lines.append("I did not infer qualifications or accomplishments that are not present in stored records.")
    return "\n".join(lines)


def first_present(*values: Any, missing: str = "missing") -> Any:
    for value in values:
        if value not in (None, "", [], {}):
            return value
    return missing


def candidate_assessment_summary(summary: dict[str, Any], raw_json: dict[str, Any], source_item: dict[str, Any]) -> dict[str, Any]:
    assessment = summary.get("assessment") if isinstance(summary.get("assessment"), dict) else {}
    raw_assessment = raw_json.get("assessment") if isinstance(raw_json.get("assessment"), dict) else {}
    source_assessment = source_item.get("assessment") if isinstance(source_item.get("assessment"), dict) else {}
    score = first_present(
        source_item.get("assessment_score"),
        source_assessment.get("score"),
        assessment.get("score"),
        raw_assessment.get("score"),
        raw_assessment.get("percent"),
        missing=None,
    )
    return {
        "status": first_present(source_assessment.get("status"), assessment.get("status"), raw_assessment.get("status")),
        "score": score if score is not None else "missing",
    }


def compare_candidate_item(source_item: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    app_key = source_item.get("app_key") or source_item.get("key")
    row = find_application_by_key(str(app_key), company_code=company_code) if app_key else None
    summary = prehire_application_summary(
        row,
        include_raw=True,
        include_assessment=company_has_module(company_code, "assessments"),
    ) if row else {}
    raw_json = summary.get("raw_json") if isinstance(summary.get("raw_json"), dict) else {}
    candidate = summary.get("candidate") if isinstance(summary.get("candidate"), dict) else {}
    position = summary.get("position") if isinstance(summary.get("position"), dict) else {}
    cv = summary.get("cv") if isinstance(summary.get("cv"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    notes = first_present(
        source_item.get("notes"),
        source_item.get("note"),
        raw_json.get("notes"),
        raw_json.get("ai_notes"),
        screening.get("notes"),
        missing="missing",
    )
    ranking_score = first_present(source_item.get("score"), source_item.get("ranking_score"), raw_json.get("ranking_score"), missing="missing")
    assessment = candidate_assessment_summary(summary, raw_json, source_item)
    return {
        "app_key": first_present(summary.get("app_key"), app_key),
        "name": first_present(source_item.get("candidate_name"), source_item.get("name"), candidate.get("name")),
        "job": first_present(source_item.get("position_title"), position.get("title"), source_item.get("position_code"), position.get("code")),
        "stage": first_present(source_item.get("status"), summary.get("status")),
        "current_step": first_present(summary.get("current_step"), raw_json.get("current_step")),
        "cv_status": "received" if cv.get("received") else "missing" if cv else first_present(source_item.get("cv_status"), missing="missing"),
        "assessment_status": assessment.get("status"),
        "assessment_score": assessment.get("score"),
        "ranking_score": ranking_score,
        "notes": notes,
        "last_activity": first_present(summary.get("updated_at"), summary.get("ingested_at"), source_item.get("last_activity"), source_item.get("updated_at")),
    }


def candidate_strengths_and_gaps(candidate: dict[str, Any]) -> tuple[list[str], list[str]]:
    strengths: list[str] = []
    gaps: list[str] = []
    if candidate.get("cv_status") == "received":
        strengths.append("CV is received")
    else:
        gaps.append("CV status is missing")
    if candidate.get("assessment_score") != "missing":
        strengths.append(f"Assessment score stored: {candidate.get('assessment_score')}")
    elif candidate.get("assessment_status") != "missing":
        strengths.append(f"Assessment status stored: {candidate.get('assessment_status')}")
    else:
        gaps.append("Assessment result is missing")
    if candidate.get("ranking_score") != "missing":
        strengths.append(f"Ranking score stored: {candidate.get('ranking_score')}")
    else:
        gaps.append("Ranking score is missing")
    if candidate.get("notes") != "missing":
        strengths.append("Stored notes are available")
    else:
        gaps.append("Stored notes are missing")
    return strengths or ["No stored strengths beyond basic profile fields"], gaps or ["No stored gaps identified"]


def compare_candidates(action: dict[str, Any], *, company_code: str | None = None) -> dict[str, Any]:
    company = str(company_code or "").strip().upper()
    if not company:
        return {"ok": False, "error": "tenant_scope_required", "action": action}
    source_items = action.get("candidates") if isinstance(action.get("candidates"), list) else []
    if not source_items:
        ids = action.get("candidate_ids") if isinstance(action.get("candidate_ids"), list) else []
        source_items = [{"app_key": item} for item in ids if item]
    candidates = [compare_candidate_item(item, company_code=company) for item in source_items if isinstance(item, dict)]
    candidates = [item for item in candidates if item.get("app_key") != "missing" or item.get("name") != "missing"]
    if len(candidates) < 2:
        return {"ok": False, "error": "not_enough_candidates", "candidates": candidates, "action": action}
    enriched = []
    for candidate in candidates[:5]:
        strengths, gaps = candidate_strengths_and_gaps(candidate)
        enriched.append({**candidate, "strengths": strengths, "gaps": gaps})
    recommendable = [item for item in enriched if item.get("ranking_score") != "missing"]
    recommended = None
    if recommendable:
        recommended = max(recommendable, key=lambda item: float(item.get("ranking_score") or 0) if str(item.get("ranking_score")).replace(".", "", 1).isdigit() else -1)
    next_action = (
        f"Review {recommended.get('name')} first because that candidate has the highest stored ranking score."
        if recommended
        else "No grounded recommendation is available because stored ranking scores are missing. Review the missing assessment/ranking data before deciding."
    )
    return {
        "ok": True,
        "candidates": enriched,
        "recommended_next_action": next_action,
        "data_policy": "Compared only stored application, CV, assessment, ranking, notes, and activity fields. Missing data is marked as missing.",
    }


def format_compare_candidates_reply(result: dict[str, Any]) -> str:
    candidates = result.get("candidates") if isinstance(result.get("candidates"), list) else []
    if not candidates:
        return "I could not compare those candidates because I do not have two stored candidate records."
    lines = ["Grounded candidate comparison (stored data only):"]
    for candidate in candidates:
        lines.append(
            "\n"
            f"{candidate.get('name')} — {candidate.get('job')}\n"
            f"- Stage: {candidate.get('stage')}; current step: {candidate.get('current_step')}\n"
            f"- CV: {candidate.get('cv_status')}; assessment: {candidate.get('assessment_status')} / score {candidate.get('assessment_score')}\n"
            f"- Ranking score: {candidate.get('ranking_score')}; last activity: {candidate.get('last_activity')}\n"
            f"- Stored strengths: {format_inline_list([str(item) for item in candidate.get('strengths', [])])}\n"
            f"- Stored gaps: {format_inline_list([str(item) for item in candidate.get('gaps', [])])}\n"
            f"- Notes: {candidate.get('notes')}"
        )
    lines.append(f"\nRecommended next action: {result.get('recommended_next_action')}")
    lines.append("I did not infer missing qualifications; missing fields are shown as missing.")
    return "\n".join(lines)


KUWAIT_TZ = timezone(timedelta(hours=3))
SHIFT_WEEKDAYS = {
    "monday": 0,
    "mon": 0,
    "tuesday": 1,
    "tue": 1,
    "tues": 1,
    "wednesday": 2,
    "wed": 2,
    "thursday": 3,
    "thu": 3,
    "thur": 3,
    "thurs": 3,
    "friday": 4,
    "fri": 4,
    "saturday": 5,
    "sat": 5,
    "sunday": 6,
    "sun": 6,
}


def kuwait_today() -> date:
    return datetime.now(KUWAIT_TZ).date()


def parse_shift_date_value(value: Any) -> date | None:
    parsed = parse_iso_date(value)
    return parsed


def parse_shift_time_value(value: Any, *, assume_pm: bool = False) -> Any | None:
    raw = str(value or "").strip().lower()
    if not raw:
        return None
    match = re.search(r"\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b", raw)
    if not match:
        return None
    hour = int(match.group(1))
    minute = int(match.group(2) or 0)
    meridiem = match.group(3)
    if meridiem == "pm" and hour < 12:
        hour += 12
    elif meridiem == "am" and hour == 12:
        hour = 0
    elif not meridiem and assume_pm and hour < 12:
        hour += 12
    if hour > 23 or minute > 59:
        return None
    return datetime.strptime(f"{hour:02d}:{minute:02d}", "%H:%M").time()


def extract_shift_time_range(action: dict[str, Any]) -> tuple[Any | None, Any | None, str | None]:
    start_raw = action.get("start_time") or action.get("start") or action.get("from")
    end_raw = action.get("end_time") or action.get("end") or action.get("to")
    text = str(action.get("prompt_text") or action.get("query") or "")
    if not (start_raw and end_raw):
        match = re.search(
            r"\b(\d{1,2}(?::\d{2})?\s*(?:am|pm)?)\s*(?:to|-|until)\s*(\d{1,2}(?::\d{2})?\s*(?:am|pm)?)\b",
            text,
            re.I,
        )
        if match:
            start_raw, end_raw = match.group(1), match.group(2)
    start_time = parse_shift_time_value(start_raw)
    end_time = parse_shift_time_value(end_raw)
    if start_time and end_time and end_time <= start_time and not re.search(r"\b(am|pm)\b", str(end_raw), re.I):
        end_time = parse_shift_time_value(end_raw, assume_pm=True)
    if not start_time or not end_time:
        return None, None, "missing_shift_time"
    if end_time <= start_time:
        # Wave 1: overnight when end <= start (Attendance shift_window contract).
        if _shifts_authority.shifts_wave1_enabled() and _shifts_authority.allow_overnight():
            return start_time, end_time, None
        return start_time, end_time, "invalid_shift_time_range"
    return start_time, end_time, None


def next_weekday_on_or_after(base: date, weekday: int) -> date:
    return base + timedelta(days=(weekday - base.weekday()) % 7)


def text_has_explicit_iso_date(text: str) -> bool:
    return bool(re.search(r"\b\d{4}-\d{2}-\d{2}\b", text or ""))


def text_uses_relative_date(text: str) -> bool:
    normalized = normalize_text(text)
    return bool(re.search(r"\b(today|tomorrow|this week|next week)\b", normalized))


def shift_dates_from_text(action: dict[str, Any]) -> list[date]:
    text = normalize_text(str(action.get("prompt_text") or action.get("query") or ""))
    today = kuwait_today()
    explicit_dates: list[date] = []
    for key in ("date", "shift_date"):
        parsed = parse_shift_date_value(action.get(key))
        if parsed:
            explicit_dates.append(parsed)
    start_date = parse_shift_date_value(action.get("start_date"))
    end_date = parse_shift_date_value(action.get("end_date"))
    if text_uses_relative_date(text) and not text_has_explicit_iso_date(text):
        if "tomorrow" in text:
            return [today + timedelta(days=1)]
        if "today" in text:
            return [today]
        if "next week" in text:
            start = next_weekday_on_or_after(today + timedelta(days=1), SHIFT_WEEKDAYS["sunday"])
            return [start + timedelta(days=i) for i in range(7)]
        if "this week" in text:
            return [today + timedelta(days=i) for i in range(7)]
    if start_date and end_date and end_date >= start_date:
        return [start_date + timedelta(days=i) for i in range((end_date - start_date).days + 1)][:31]
    if explicit_dates:
        return explicit_dates[:14]
    if "tomorrow" in text:
        return [today + timedelta(days=1)]
    if "today" in text:
        return [today]
    if "next week" in text:
        start = next_weekday_on_or_after(today + timedelta(days=1), SHIFT_WEEKDAYS["sunday"])
        return [start + timedelta(days=i) for i in range(7)]
    if "this week" in text:
        start = today
        return [start + timedelta(days=i) for i in range(7)]
    range_match = re.search(r"\b(" + "|".join(SHIFT_WEEKDAYS) + r")\s*(?:to|-|until)\s*(" + "|".join(SHIFT_WEEKDAYS) + r")\b", text)
    if range_match:
        start_weekday = SHIFT_WEEKDAYS[range_match.group(1)]
        end_weekday = SHIFT_WEEKDAYS[range_match.group(2)]
        current = next_weekday_on_or_after(today, start_weekday)
        dates = [current]
        while current.weekday() != end_weekday and len(dates) < 7:
            current += timedelta(days=1)
            dates.append(current)
        return dates
    for name, weekday in SHIFT_WEEKDAYS.items():
        if re.search(rf"\b{name}\b", text):
            return [next_weekday_on_or_after(today, weekday)]
    return [today]


def shift_query_window(action: dict[str, Any]) -> tuple[date, date]:
    text = normalize_text(str(action.get("prompt_text") or action.get("query") or ""))
    today = kuwait_today()
    if text_uses_relative_date(text) and not text_has_explicit_iso_date(text):
        if "tomorrow" in text:
            day = today + timedelta(days=1)
            return day, day
        if "next week" in text:
            start = next_weekday_on_or_after(today + timedelta(days=1), SHIFT_WEEKDAYS["sunday"])
            return start, start + timedelta(days=6)
        if "this week" in text or "week" in text:
            return today, today + timedelta(days=6)
        if "today" in text:
            return today, today
    explicit = parse_shift_date_value(action.get("date") or action.get("shift_date"))
    if explicit:
        return explicit, explicit
    start_date = parse_shift_date_value(action.get("start_date"))
    end_date = parse_shift_date_value(action.get("end_date"))
    if start_date and end_date and end_date >= start_date:
        return start_date, min(end_date, start_date + timedelta(days=31))
    if "tomorrow" in text:
        day = today + timedelta(days=1)
        return day, day
    if "next week" in text:
        start = next_weekday_on_or_after(today + timedelta(days=1), SHIFT_WEEKDAYS["sunday"])
        return start, start + timedelta(days=6)
    if "this week" in text or "week" in text:
        return today, today + timedelta(days=6)
    if "today" in text:
        return today, today
    dates = shift_dates_from_text(action)
    return min(dates), max(dates)


def resolve_shift_employee(action: dict[str, Any], *, required: bool = True, company_code: str | None = None) -> dict[str, Any] | None:
    """Resolve one employee for shift/attendance/leave/payroll mutations.

    Uses typed company-scoped identity only. Never selects by update time.
    Ambiguous matches are stashed on the action for clarification replies.
    """
    company = resolved_company_scope(company_code or action.get("company_code"))
    typed = resolve_employee_typed(
        employee_key=action.get("employee_key"),
        employee_phone=action.get("subject_phone") or action.get("employee_phone"),
        employee_name=action.get("subject_name") or action.get("employee_name"),
        company_code=company,
    )
    action["_employee_resolution"] = {
        "status": typed.get("status"),
        "choices": typed.get("choices") or [],
        "searched": typed.get("searched") or {},
    }
    if typed.get("status") == "resolved":
        return typed.get("employee")
    if not required:
        return None
    # Explicit typed identifiers only — never fuzzy-guess from free text.
    return None


def company_employees(company_code: str | None) -> list[dict[str, Any]]:
    # The employee hub is the source of truth for mention-resolution ("message all
    # staff"), roster/analytics roll-ups and onboarding cards — every one of those
    # needs the COMPLETE workforce, so this read is intentionally uncapped. A LIMIT
    # here silently dropped every employee past the arbitrary cutoff (e.g. a 1,200
    # person company would lose 200 people from "all staff" with no error). The
    # result is bounded naturally by one company's headcount. For paged DISPLAY of
    # the directory, use list_employees_page instead.
    company = require_company_code(company_code)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM employees
                WHERE company_code=%s
                ORDER BY name NULLS LAST, phone, employee_key
                """,
                (company,),
            )
            return [dict(row) for row in cur.fetchall()]


def _ilike_escape(term: str) -> str:
    """Escape LIKE/ILIKE wildcards so a user's raw search text is matched
    literally (a '%' the user typed shouldn't act as a wildcard). Backslash is
    the default ILIKE escape character in Postgres."""
    return term.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")


def _employee_scope_where(
    company_code: str | None,
    viewer_phone: str | None,
    *,
    dashboard_user_id: str | None = None,
    actor_role: str | None = None,
) -> tuple[str, list[Any]]:
    """Shared WHERE fragment (aliased `e`) for scoped reads over `employees`:
    company match + the manager scope clause. Returns the SQL string (already
    joined with AND) and its params, so every directory-style read (employees,
    onboarding, stats) narrows to the SAME rows a scoped manager may see."""
    company = require_company_code(company_code)
    scope = manager_scope_context(
        viewer_phone,
        company,
        dashboard_user_id=dashboard_user_id,
        actor_role=actor_role,
    )
    where = ["e.company_code=%s"]
    params: list[Any] = [company]
    scope_clause, scope_params = employee_scope_sql("e", scope)
    if scope_clause:
        where.append(scope_clause.removeprefix("AND "))
        params.extend(scope_params)
    return " AND ".join(where), params


def _employee_search_clause(term: str | None) -> tuple[str, list[Any]]:
    """Shared ILIKE search fragment (aliased `e`) across name/phone/email/title
    and the department/team stored in profile/raw_json JSON. Returns ('', []) when
    there is no term so callers can conditionally AND it in."""
    cleaned = (term or "").strip()
    if not cleaned:
        return "", []
    like = f"%{_ilike_escape(cleaned)}%"
    clause = (
        "(e.name ILIKE %s OR e.phone ILIKE %s OR e.email ILIKE %s "
        "OR e.position_title ILIKE %s "
        "OR e.profile->>'department' ILIKE %s OR e.profile->>'team' ILIKE %s "
        "OR e.raw_json->>'department' ILIKE %s OR e.raw_json->>'team' ILIKE %s)"
    )
    return clause, [like] * 8


def list_employees_page(
    company_code: str | None,
    *,
    viewer_phone: str | None = None,
    dashboard_user_id: str | None = None,
    actor_role: str | None = None,
    search: str | None = None,
    limit: int,
    offset: int,
) -> dict[str, Any]:
    """Paged employee directory read for dashboard list surfaces.

    Applies manager scope IN SQL (via employee_scope_sql) so page counts and
    total_count are correct for restricted managers, not just filtered after the
    fact. Returns rows plus total_count/has_more so the UI can page through the
    entire workforce without ever silently truncating. The employee_key tiebreaker
    makes the sort a total order so OFFSET paging is stable.

    An optional `search` term filters IN SQL across name/phone/email/title and the
    department/team stored in the profile JSON, so search reaches the WHOLE
    workforce (not just the pages already loaded in the browser) and total_count
    reflects the filtered set for correct paging.
    """
    where_sql, params = _employee_scope_where(
        company_code,
        viewer_phone,
        dashboard_user_id=dashboard_user_id,
        actor_role=actor_role,
    )
    search_clause, search_params = _employee_search_clause(search)
    if search_clause:
        where_sql = f"{where_sql} AND {search_clause}"
        params.extend(search_params)
    params.extend([limit, offset])
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT e.*, COUNT(*) OVER() AS _total_count
                FROM employees e
                WHERE {where_sql}
                ORDER BY e.name NULLS LAST, e.phone, e.employee_key
                LIMIT %s OFFSET %s
                """,
                params,
            )
            rows = [dict(row) for row in cur.fetchall()]
    total_count = int(rows[0]["_total_count"]) if rows else 0
    for row in rows:
        row.pop("_total_count", None)
    has_more = (offset + len(rows)) < total_count
    return {"rows": rows, "total_count": total_count, "limit": limit, "offset": offset, "has_more": has_more}


def employee_directory_stats(
    company_code: str | None,
    *,
    viewer_phone: str | None = None,
    dashboard_user_id: str | None = None,
    actor_role: str | None = None,
) -> dict[str, Any]:
    """Scope-aware directory headline counts computed in SQL over the WHOLE
    workforce, so the stat cards stay correct no matter how many pages of the
    directory are loaded in the UI. Uses the same manager scope as the paged read.
    """
    where_sql, params = _employee_scope_where(
        company_code,
        viewer_phone,
        dashboard_user_id=dashboard_user_id,
        actor_role=actor_role,
    )
    # Active headcount = truly active only. pending_start is joining/future — never
    # counted as active (pending_start P2/P3). Legacy null/blank still means active.
    is_active = "lower(coalesce(nullif(btrim(e.employment_status), ''), 'active')) = 'active'"
    is_left = "lower(coalesce(e.employment_status,'')) = 'left'"
    is_joining = "lower(coalesce(e.employment_status,'')) IN ('pending_start','joining','future_start')"
    onboarding_done = "lower(coalesce(e.onboarding_status,'')) IN ('complete','completed','done')"
    # `department` is not a column — it lives in the profile/raw_json JSON, mirroring
    # the fallback chain posthire_employee_card uses, so the count matches the UI.
    dept_expr = (
        "NULLIF(btrim(coalesce("
        "e.profile->>'department', e.profile->>'team', "
        "e.raw_json->>'department', e.raw_json->>'team', '')), '')"
    )
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                  count(*) AS total,
                  count(*) FILTER (WHERE {is_active}) AS active,
                  count(*) FILTER (WHERE {is_left}) AS left_count,
                  count(*) FILTER (WHERE {is_joining}) AS pending_start_count,
                  count(*) FILTER (WHERE {is_active} AND NOT ({onboarding_done})) AS onboarding_in_progress,
                  count(DISTINCT {dept_expr}) FILTER (WHERE {is_active}) AS departments
                FROM employees e
                WHERE {where_sql}
                """,
                params,
            )
            row = dict(cur.fetchone() or {})
    return {
        "total_count": int(row.get("total") or 0),
        "active_count": int(row.get("active") or 0),
        "left_count": int(row.get("left_count") or 0),
        "pending_start_count": int(row.get("pending_start_count") or 0),
        "onboarding_count": int(row.get("onboarding_in_progress") or 0),
        "department_count": int(row.get("departments") or 0),
    }


# Post-hire child tables that hang off an employee via (company_code, employee_key).
# `employees` is the conceptual hub; these orbit it without a hard FK so the soft hub
# stays flexible. The integrity scan reports rows whose employee_key no longer resolves
# to a real employee in the same company, so HR/ops can catch silent drift without
# introducing risky foreign-key constraints.
#
# Wave 1 expands coverage beyond the original attendance/leave/shift/payroll set to
# every employee-linked table that can silently orphan after hub edits.
INTEGRITY_CHILD_TABLES: tuple[str, ...] = (
    "attendance_records",
    "leave_requests",
    "shift_assignments",
    "payroll_timesheets",
    "employee_availability_requests",
    "compliance_documents",
    "employee_messages",
    "employee_sessions",
    "employee_app_invites",
    "employee_status_changes",
    "employee_org_assignments",
    "hr_tasks",
    "document_storage_operations",
)

# Specs for tables that need a non-default join (file_registry subject_key,
# onboarding_items / employee_documents without a reliable company_code join).
INTEGRITY_SCAN_SPECS: tuple[dict[str, Any], ...] = tuple(
    {"table": name, "mode": "company_employee"} for name in INTEGRITY_CHILD_TABLES
) + (
    {"table": "file_registry", "mode": "file_registry_employee"},
    {"table": "onboarding_items", "mode": "employee_key_join"},
    {"table": "employee_documents", "mode": "employee_key_join"},
)


def workspace_integrity_scan(company_code: str | None = None) -> dict[str, Any]:
    """Read-only orphan scan across the employee hub's post-hire child tables.

    Counts rows whose (company_code, employee_key) does not resolve to a live
    `employees` row. When `company_code` is given the scan is tenant-scoped;
    otherwise it scans every company. Never mutates data — safe to run nightly.
    """
    company = (company_code or "").upper() or None
    tables: dict[str, dict[str, Any]] = {}
    total_orphans = 0
    with db_connect() as conn:
        with conn.cursor() as cur:
            for spec in INTEGRITY_SCAN_SPECS:
                table = str(spec["table"])
                mode = str(spec.get("mode") or "company_employee")
                cur.execute("SELECT to_regclass(%s) AS reg", (f"public.{table}",))
                if not (cur.fetchone() or {}).get("reg"):
                    tables[table] = {"present": False, "orphans": 0, "samples": [], "mode": mode}
                    continue
                params: list[Any] = []
                if mode == "company_employee":
                    where = [
                        "t.employee_key IS NOT NULL",
                        "t.employee_key <> ''",
                        "e.employee_key IS NULL",
                    ]
                    if company is not None:
                        where.append("t.company_code = %s")
                        params.append(company)
                    clause = " AND ".join(where)
                    count_sql = f"""
                        SELECT count(*)::bigint AS orphans
                        FROM {table} t
                        LEFT JOIN employees e
                          ON e.employee_key = t.employee_key
                         AND e.company_code = t.company_code
                        WHERE {clause}
                    """
                    sample_sql = f"""
                        SELECT DISTINCT t.company_code, t.employee_key
                        FROM {table} t
                        LEFT JOIN employees e
                          ON e.employee_key = t.employee_key
                         AND e.company_code = t.company_code
                        WHERE {clause}
                        LIMIT 5
                    """
                elif mode == "file_registry_employee":
                    where = [
                        "t.subject_type = 'employee'",
                        "t.subject_key IS NOT NULL",
                        "t.subject_key <> ''",
                        "e.employee_key IS NULL",
                    ]
                    if company is not None:
                        where.append("t.company_code = %s")
                        params.append(company)
                    clause = " AND ".join(where)
                    count_sql = f"""
                        SELECT count(*)::bigint AS orphans
                        FROM {table} t
                        LEFT JOIN employees e
                          ON e.employee_key = t.subject_key
                         AND e.company_code = t.company_code
                        WHERE {clause}
                    """
                    sample_sql = f"""
                        SELECT DISTINCT t.company_code, t.subject_key AS employee_key
                        FROM {table} t
                        LEFT JOIN employees e
                          ON e.employee_key = t.subject_key
                         AND e.company_code = t.company_code
                        WHERE {clause}
                        LIMIT 5
                    """
                else:  # employee_key_join — tables that hang only on employee_key
                    where = [
                        "t.employee_key IS NOT NULL",
                        "t.employee_key <> ''",
                        "e.employee_key IS NULL",
                    ]
                    if company is not None:
                        # Prefer key-prefix filter when the child table has no
                        # company_code column (onboarding_items) or when joins
                        # alone cannot tenant-scope orphan rows.
                        where.append("t.employee_key LIKE %s")
                        params.append(f"{company}-%")
                    clause = " AND ".join(where)
                    count_sql = f"""
                        SELECT count(*)::bigint AS orphans
                        FROM {table} t
                        LEFT JOIN employees e ON e.employee_key = t.employee_key
                        WHERE {clause}
                    """
                    sample_sql = f"""
                        SELECT DISTINCT COALESCE(e.company_code, split_part(t.employee_key, '-', 1)) AS company_code,
                               t.employee_key
                        FROM {table} t
                        LEFT JOIN employees e ON e.employee_key = t.employee_key
                        WHERE {clause}
                        LIMIT 5
                    """
                cur.execute(count_sql, tuple(params))
                orphans = int((cur.fetchone() or {}).get("orphans") or 0)
                samples: list[dict[str, Any]] = []
                if orphans:
                    cur.execute(sample_sql, tuple(params))
                    samples = [
                        {"company_code": row.get("company_code"), "employee_key": row.get("employee_key")}
                        for row in cur.fetchall()
                    ]
                tables[table] = {"present": True, "orphans": orphans, "samples": samples, "mode": mode}
                total_orphans += orphans
    return {
        "company_code": company,
        "scanned_at": now_iso(),
        "total_orphans": total_orphans,
        "ok": total_orphans == 0,
        "tables": tables,
    }


def employee_is_mentioned(text: str, employee: dict[str, Any]) -> bool:
    normalized = normalize_text(text)
    compact_digits = digits(text)
    phone = digits(employee.get("phone"))
    if phone and phone in compact_digits:
        return True
    name = str(employee.get("name") or "").strip()
    if not name:
        return False
    normalized_name = normalize_text(name)
    if normalized_name and re.search(rf"\b{re.escape(normalized_name)}\b", normalized):
        return True
    text_tokens = text_name_tokens(text)
    name_tokens = [token for token in text_name_tokens(name) if normalize_text(token) not in {"al", "bin", "bint"}]
    if not text_tokens or not name_tokens:
        return False
    strong_matches = 0
    matched_name_tokens: list[str] = []
    for name_token in name_tokens:
        if any(name_similarity(name_token, text_token) >= 0.84 for text_token in text_tokens):
            strong_matches += 1
            matched_name_tokens.append(comparable_name(name_token))
    if len(name_tokens) == 1:
        return strong_matches == 1
    if strong_matches >= min(2, len(name_tokens)):
        return True
    # HR usually uses first names in WhatsApp. Accept a single distinctive token
    # so "Fouad and Mohammad" resolves both employees without requiring surnames.
    return any(len(token) >= 4 for token in matched_name_tokens)


def employees_mentioned_in_text(text: str, company_code: str | None) -> list[dict[str, Any]]:
    normalized = normalize_text(text)
    employees = company_employees(company_code)
    if re.search(r"\b(all employees|all staff|everyone|the team|all workers)\b", normalized):
        return employees
    matched = [employee for employee in employees if employee_is_mentioned(text, employee)]
    seen: set[str] = set()
    out: list[dict[str, Any]] = []
    for employee in matched:
        key = str(employee.get("employee_key") or employee.get("phone") or "")
        if key and key not in seen:
            seen.add(key)
            out.append(employee)
    return out


def employee_specs_from_action(action: dict[str, Any]) -> list[Any]:
    specs: list[Any] = []
    for key in ("employees", "subject_names", "subjects"):
        value = action.get(key)
        if isinstance(value, list):
            specs.extend(value)
    if action.get("subject_name"):
        specs.append(action.get("subject_name"))
    if action.get("subject_phone"):
        specs.append({"subject_phone": action.get("subject_phone"), "subject_name": action.get("subject_name")})
    return specs


def resolve_shift_employees(action: dict[str, Any], *, company_code: str | None, required: bool = True) -> list[dict[str, Any]]:
    company = resolved_company_scope(company_code)
    if not company:
        action["_employee_resolution"] = {"status": "employee_not_found", "choices": [], "error": "company_required"}
        return []
    company = str(company).upper()
    resolved: list[dict[str, Any]] = []
    seen: set[str] = set()
    ambiguous_choices: list[dict[str, Any]] = []

    def add(employee: dict[str, Any] | None) -> None:
        if not employee:
            return
        if str(employee.get("company_code") or company).upper() != company:
            return
        if action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
            return
        key = str(employee.get("employee_key") or employee.get("phone") or "")
        if key and key not in seen:
            seen.add(key)
            resolved.append(employee)

    for spec in employee_specs_from_action(action):
        if isinstance(spec, dict):
            typed = resolve_employee_typed(
                employee_key=spec.get("employee_key"),
                employee_phone=spec.get("subject_phone") or spec.get("phone"),
                employee_name=spec.get("subject_name") or spec.get("name"),
                company_code=company,
            )
        elif isinstance(spec, str):
            typed = resolve_employee_typed(employee_name=spec, company_code=company)
        else:
            continue
        if typed.get("status") == "resolved":
            add(typed.get("employee"))
        elif typed.get("status") == "ambiguous":
            ambiguous_choices.extend(typed.get("choices") or [])

    # Bulk "all staff" remains an explicit roster read, not identity guessing.
    prompt = str(action.get("prompt_text") or action.get("query") or "")
    if re.search(r"\b(all employees|all staff|everyone|the team|all workers)\b", normalize_text(prompt)):
        for employee in company_employees(company):
            add(employee)

    if not resolved and required:
        add(resolve_shift_employee(action, required=True, company_code=company))
    if not resolved and ambiguous_choices:
        action["_employee_resolution"] = {"status": "ambiguous", "choices": ambiguous_choices[:5]}
    elif resolved:
        action["_employee_resolution"] = {"status": "resolved", "choices": []}
    return resolved


def assignment_actions_from_bulk(action: dict[str, Any]) -> list[dict[str, Any]]:
    assignments = action.get("assignments")
    if not isinstance(assignments, list) or not assignments:
        return [action]
    out: list[dict[str, Any]] = []
    for item in assignments[:50]:
        if not isinstance(item, dict):
            continue
        merged = dict(action)
        merged.pop("assignments", None)
        for key, value in item.items():
            if value not in (None, "", []):
                merged[key] = value
        if not merged.get("prompt_text"):
            merged["prompt_text"] = action.get("prompt_text") or action.get("query") or ""
        out.append(merged)
    return out or [action]


def record_shift_event(cur: Any, *, shift: dict[str, Any] | None, company_code: str, event_type: str, payload: dict[str, Any], created_by_phone: str | None) -> None:
    cur.execute(
        """
        INSERT INTO shift_events (shift_id, company_code, employee_key, event_type, payload, created_by_phone)
        VALUES (%s,%s,%s,%s,%s,%s)
        """,
        (
            shift.get("shift_id") if shift else None,
            company_code,
            shift.get("employee_key") if shift else payload.get("employee_key"),
            event_type,
            Json(json_safe(payload)),
            digits(created_by_phone),
        ),
    )


def shift_conflicts(
    cur: Any,
    *,
    company_code: str,
    employee_key: str,
    shift_date: date,
    start_time: Any,
    end_time: Any,
    exclude_shift_id: str | None = None,
    ends_next_day: bool | None = None,
) -> list[dict[str, Any]]:
    """Canonical tenant-scoped overlap check for create/reschedule/swap/bulk.

    Wave 1 uses overnight-aware interval overlap (same-day, split, cross-midnight).
    Legacy path keeps same-date SQL when Wave 1 is disabled.
    """
    company = str(company_code or "").upper().strip()
    if not company or not employee_key or not shift_date:
        return []
    if _shifts_authority.shifts_wave1_enabled():
        overnight = (
            bool(ends_next_day)
            if ends_next_day is not None
            else _shifts_authority.ends_next_day_for(start_time, end_time)
        )
        return _shifts_authority.find_overlapping_shifts(
            cur,
            company_code=company,
            employee_key=str(employee_key),
            shift_date=shift_date if isinstance(shift_date, date) else parse_shift_date_value(shift_date),
            start_time=start_time,
            end_time=end_time,
            ends_next_day=overnight,
            exclude_shift_id=exclude_shift_id,
        )
    params: list[Any] = [company, employee_key, shift_date, end_time, start_time]
    exclude_clause = ""
    if exclude_shift_id:
        exclude_clause = "AND shift_id <> %s"
        params.append(str(exclude_shift_id))
    cur.execute(
        f"""
        SELECT *
        FROM shift_assignments
        WHERE company_code=%s
          AND employee_key=%s
          AND shift_date=%s
          AND status='scheduled'
          AND start_time < %s
          AND end_time > %s
          {exclude_clause}
        ORDER BY start_time
        """,
        params,
    )
    return [dict(row) for row in cur.fetchall()]


def shift_sheet_cell(value: Any) -> str:
    if value is None:
        return ""
    if hasattr(value, "isoformat"):
        return value.isoformat()
    return str(value)


def display_status(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    return " ".join(part for part in text.replace("-", "_").split("_") if part).capitalize()


def employee_employment_status(employee: dict[str, Any]) -> str:
    raw = employee.get("employment_status") or employee.get("status")
    if raw:
        return display_status(raw)
    if employee.get("hire_date") or employee.get("hired_date"):
        return "Hired"
    return "Active"


def availability_time_window(row: dict[str, Any]) -> str:
    if row.get("start_time") and row.get("end_time"):
        return f"{format_shift_time(row.get('start_time'))}-{format_shift_time(row.get('end_time'))}"
    if row.get("start_time"):
        return f"from {format_shift_time(row.get('start_time'))}"
    if row.get("end_time"):
        return f"until {format_shift_time(row.get('end_time'))}"
    return "All day"


def attendance_date_from_action(action: dict[str, Any]) -> date:
    parsed = parse_shift_date_value(action.get("date") or action.get("attendance_date"))
    if parsed:
        return parsed
    return shift_query_window(action)[0]


def attendance_timestamp_from_action(action: dict[str, Any], attendance_date: date) -> datetime:
    raw_time = action.get("time") or action.get("check_time") or action.get("check_in_time") or action.get("check_out_time")
    parsed_time = parse_shift_time_value(raw_time)
    if parsed_time:
        return datetime.combine(attendance_date, parsed_time, tzinfo=KUWAIT_TZ)
    return datetime.now(KUWAIT_TZ)


def attendance_shift_datetime(shift_date: Any, shift_time: Any) -> datetime | None:
    parsed_date = parse_shift_date_value(shift_date)
    parsed_time = parse_shift_time_value(shift_time) if isinstance(shift_time, str) else shift_time
    if not parsed_date or not parsed_time:
        return None
    return datetime.combine(parsed_date, parsed_time, tzinfo=KUWAIT_TZ)


def attendance_minutes_late(check_in_at: Any, shift: dict[str, Any] | None) -> int:
    if not check_in_at or not shift:
        return 0
    start_dt = attendance_shift_datetime(shift.get("shift_date"), shift.get("start_time"))
    if not start_dt:
        return 0
    check_dt = check_in_at if isinstance(check_in_at, datetime) else datetime.fromisoformat(str(check_in_at).replace("Z", "+00:00"))
    if check_dt.tzinfo is None:
        check_dt = check_dt.replace(tzinfo=KUWAIT_TZ)
    return max(0, int((check_dt.astimezone(KUWAIT_TZ) - start_dt).total_seconds() // 60))


def attendance_minutes_early_leave(check_out_at: Any, shift: dict[str, Any] | None) -> int:
    if not check_out_at or not shift:
        return 0
    end_dt = attendance_shift_datetime(shift.get("shift_date"), shift.get("end_time"))
    if not end_dt:
        return 0
    check_dt = check_out_at if isinstance(check_out_at, datetime) else datetime.fromisoformat(str(check_out_at).replace("Z", "+00:00"))
    if check_dt.tzinfo is None:
        check_dt = check_dt.replace(tzinfo=KUWAIT_TZ)
    return max(0, int((end_dt - check_dt.astimezone(KUWAIT_TZ)).total_seconds() // 60))


def resolve_attendance_employee(action: dict[str, Any], *, company_code: str | None, required: bool = True) -> dict[str, Any] | None:
    employees = resolve_shift_employees(action, company_code=company_code, required=False)
    if len(employees) == 1:
        return employees[0]
    if len(employees) > 1:
        action["_employee_resolution"] = {
            "status": "ambiguous",
            "choices": [
                {
                    "employee_key": row.get("employee_key"),
                    "employee_name": row.get("name"),
                    "employee_phone": row.get("phone"),
                    "role_title": row.get("role_title") or row.get("position_title"),
                }
                for row in employees[:5]
            ],
        }
        return None
    return resolve_shift_employee(action, required=required, company_code=company_code)


def active_shift_for_attendance(
    cur: Any,
    *,
    company_code: str,
    employee_key: str,
    attendance_date: date,
    shift_id: str | None = None,
    at_time: Any | None = None,
) -> dict[str, Any] | None:
    company = str(company_code or "").upper().strip()
    if not company or not employee_key:
        return None
    if _shifts_w2.shifts_wave2_enabled_for_company(company):
        clock = None
        if at_time is not None:
            clock = at_time if isinstance(at_time, time) else parse_shift_time_value(at_time)
        matched = _shifts_w2.match_shift_for_attendance(
            cur,
            company_code=company,
            employee_key=str(employee_key),
            attendance_date=attendance_date,
            at_time=clock,
            shift_id=str(shift_id) if shift_id else None,
        )
        if not matched.get("ok"):
            return None
        return matched.get("shift")
    if shift_id:
        cur.execute(
            """
            SELECT *
            FROM shift_assignments
            WHERE shift_id=%s
              AND company_code=%s
              AND employee_key=%s
              AND status='scheduled'
            LIMIT 1
            """,
            (shift_id, company, employee_key),
        )
    else:
        cur.execute(
            """
            SELECT *
            FROM shift_assignments
            WHERE company_code=%s
              AND employee_key=%s
              AND shift_date=%s
              AND status='scheduled'
            ORDER BY start_time
            LIMIT 1
            """,
            (company, employee_key, attendance_date),
        )
    row = cur.fetchone()
    return dict(row) if row else None


def record_attendance_event(cur: Any, *, attendance: dict[str, Any] | None, company_code: str, event_type: str, payload: dict[str, Any], created_by_phone: str | None) -> None:
    cur.execute(
        """
        INSERT INTO attendance_events (attendance_id, shift_id, company_code, employee_key, event_type, payload, created_by_phone)
        VALUES (%s,%s,%s,%s,%s,%s,%s)
        """,
        (
            attendance.get("attendance_id") if attendance else None,
            attendance.get("shift_id") if attendance else payload.get("shift_id"),
            company_code,
            attendance.get("employee_key") if attendance else payload.get("employee_key"),
            event_type,
            Json(json_safe(payload)),
            digits(created_by_phone),
        ),
    )


def leave_date_window(action: dict[str, Any]) -> tuple[date, date]:
    start_date, end_date = shift_query_window(action)
    if end_date < start_date:
        return start_date, start_date
    return start_date, end_date


def infer_leave_type(text: str | None, explicit: str | None = None) -> str:
    raw = normalize_text(explicit or "")
    if raw:
        return _leave_authority.canonicalize_leave_type(raw.replace(" ", "_"))
    normalized = normalize_text(text)
    if re.search(r"\b(sick|ill|medical)\b", normalized):
        return "sick"
    if re.search(r"\b(vacation|holiday|annual)\b", normalized):
        return "annual"
    if re.search(r"\b(unpaid)\b", normalized):
        return "unpaid"
    # Legacy free-text "time off" maps to canonical annual (not time_off)
    return _leave_authority.canonicalize_leave_type("time_off")


def resolve_leave_employee(action: dict[str, Any], *, company_code: str | None, required: bool = True) -> dict[str, Any] | None:
    return resolve_attendance_employee(action, company_code=company_code, required=required)


def record_leave_event(cur: Any, *, leave: dict[str, Any] | None, company_code: str, event_type: str, payload: dict[str, Any], created_by_phone: str | None) -> None:
    cur.execute(
        """
        INSERT INTO leave_events (leave_id, company_code, employee_key, event_type, payload, created_by_phone)
        VALUES (%s,%s,%s,%s,%s,%s)
        """,
        (
            leave.get("leave_id") if leave else payload.get("leave_id"),
            company_code,
            leave.get("employee_key") if leave else payload.get("employee_key"),
            event_type,
            Json(json_safe(payload)),
            digits(created_by_phone),
        ),
    )


def leave_shift_conflicts(cur: Any, *, company: str, employee_key: str, start_date: date, end_date: date) -> list[dict[str, Any]]:
    cur.execute(
        """
        SELECT *
        FROM shift_assignments
        WHERE company_code=%s
          AND employee_key=%s
          AND shift_date BETWEEN %s AND %s
          AND status='scheduled'
        ORDER BY shift_date, start_time
        LIMIT 100
        """,
        (company, employee_key, start_date, end_date),
    )
    return [dict(row) for row in cur.fetchall()]


def leave_request_by_id(leave_id: str | None, *, company_code: str | None = None) -> dict[str, Any] | None:
    if not leave_id:
        return None
    # Tenant isolation: when a company is known, a leave row from another company
    # must never resolve — otherwise a guessed/leaked UUID could be acted on
    # cross-tenant. Callers without a company (legacy smoke/soak harnesses) keep
    # the unscoped behaviour.
    with db_connect() as conn:
        with conn.cursor() as cur:
            if company_code:
                cur.execute(
                    "SELECT * FROM leave_requests WHERE leave_id=%s AND company_code=%s LIMIT 1",
                    (leave_id, str(company_code).upper()),
                )
            else:
                cur.execute("SELECT * FROM leave_requests WHERE leave_id=%s LIMIT 1", (leave_id,))
            row = cur.fetchone()
            return dict(row) if row else None


def resolve_leave_request(action: dict[str, Any], *, company_code: str | None, statuses: tuple[str, ...] = ("requested",)) -> dict[str, Any] | None:
    company = require_company_code(company_code)
    explicit = leave_request_by_id(str(action.get("leave_id") or "").strip(), company_code=company)
    if explicit:
        employee = find_employee_by_phone(explicit.get("employee_phone"))
        if action.get("viewer_phone") and not manager_scope_allows_employee(employee or {"employee_key": explicit.get("employee_key"), "company_code": company}, company_code=company, viewer_phone=action.get("viewer_phone")):
            return None
        return explicit
    employee = resolve_leave_employee(action, company_code=company, required=False)
    start_date, end_date = leave_date_window(action)
    scope = org_scope_for_action(action, company)
    params: list[Any] = [company]
    where = ["lr.company_code=%s"]
    if statuses:
        where.append("lr.status = ANY(%s)")
        params.append(list(statuses))
    if employee:
        where.append("lr.employee_key=%s")
        params.append(employee.get("employee_key"))
    if action.get("date") or action.get("start_date") or action.get("end_date") or re.search(r"\b(today|tomorrow|week|sunday|monday|tuesday|wednesday|thursday|friday|saturday)\b", normalize_text(action.get("prompt_text") or action.get("query") or "")):
        where.append("lr.start_date <= %s AND lr.end_date >= %s")
        params.extend([end_date, start_date])
    scope_clause, scope_params = employee_scope_sql("lr", scope)
    if scope_clause:
        where.append(scope_clause.removeprefix("AND "))
        params.extend(scope_params)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT lr.*
                FROM leave_requests lr
                WHERE {' AND '.join(where)}
                ORDER BY lr.requested_at DESC
                LIMIT 2
                """,
                params,
            )
            rows = [dict(row) for row in cur.fetchall()]
    return rows[0] if len(rows) == 1 else None


def decimal_hours(minutes: int | float | None) -> str:
    value = float(minutes or 0) / 60.0
    return f"{value:.2f}"


def minutes_between_times(start_value: Any, end_value: Any) -> int:
    start = parse_shift_time_value(start_value) if isinstance(start_value, str) else start_value
    end = parse_shift_time_value(end_value) if isinstance(end_value, str) else end_value
    if not start or not end:
        return 0
    start_dt = datetime.combine(date(2000, 1, 1), start)
    end_dt = datetime.combine(date(2000, 1, 1), end)
    if end_dt <= start_dt:
        return 0
    return int((end_dt - start_dt).total_seconds() // 60)


def minutes_between_datetimes(start_value: Any, end_value: Any) -> int:
    if not start_value or not end_value:
        return 0
    try:
        start = start_value if isinstance(start_value, datetime) else datetime.fromisoformat(str(start_value).replace("Z", "+00:00"))
        end = end_value if isinstance(end_value, datetime) else datetime.fromisoformat(str(end_value).replace("Z", "+00:00"))
    except Exception:
        return 0
    if start.tzinfo is None:
        start = start.replace(tzinfo=KUWAIT_TZ)
    if end.tzinfo is None:
        end = end.replace(tzinfo=KUWAIT_TZ)
    diff = int((end.astimezone(KUWAIT_TZ) - start.astimezone(KUWAIT_TZ)).total_seconds() // 60)
    return max(0, diff)


def payroll_period_from_action(action: dict[str, Any]) -> tuple[date, date]:
    text = normalize_text(action.get("prompt_text") or action.get("query") or "")
    explicit = parse_shift_date_value(action.get("date"))
    if explicit:
        return explicit, explicit
    start = parse_shift_date_value(action.get("start_date"))
    end = parse_shift_date_value(action.get("end_date"))
    if start and end and end >= start:
        return start, min(end, start + timedelta(days=62))
    today = kuwait_today()
    if "this month" in text or "month" in text:
        start = today.replace(day=1)
        next_month = (start.replace(day=28) + timedelta(days=4)).replace(day=1)
        return start, next_month - timedelta(days=1)
    if "last week" in text:
        start = today - timedelta(days=today.weekday() + 7)
        return start, start + timedelta(days=6)
    if "this week" in text or "week" in text:
        start = today - timedelta(days=today.weekday())
        return start, start + timedelta(days=6)
    return shift_query_window(action)


def list_payroll_hours(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    start_date, end_date = payroll_period_from_action(action)
    scope = org_scope_for_action(action, company)
    employee = resolve_attendance_employee(action, company_code=company, required=False)
    if employee and action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "action": action, "start_date": start_date.isoformat(), "end_date": end_date.isoformat(), "scope": json_safe(scope)}
    if (action.get("subject_name") or action.get("subject_phone")) and not employee:
        return {"ok": False, "error": "employee_not_found", "action": action, "start_date": start_date.isoformat(), "end_date": end_date.isoformat()}

    # Wave 1 authority: Payroll consumes approved attendance snapshots only.
    if attendance_authority_enabled_for_company(company):
        params: list[Any] = [company, start_date, end_date]
        employee_clause = ""
        if employee:
            employee_clause = "AND {alias}.employee_key=%s"
            params.append(employee.get("employee_key"))
        leave_params: list[Any] = [company, end_date, start_date]
        if employee:
            leave_params.append(employee.get("employee_key"))
        scope_clause_shifts, scope_params_shifts = employee_scope_sql("s", scope)
        scope_clause_leave, scope_params_leave = employee_scope_sql("lr", scope)
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    SELECT s.*
                    FROM shift_assignments s
                    WHERE s.company_code=%s
                      AND s.shift_date BETWEEN %s AND %s
                      AND status='scheduled'
                      {employee_clause.format(alias='s') if employee_clause else ''}
                      {scope_clause_shifts}
                    ORDER BY s.employee_name NULLS LAST, s.shift_date, s.start_time
                    """,
                    [*params, *scope_params_shifts],
                )
                shifts = [dict(row) for row in cur.fetchall()]
                cur.execute(
                    f"""
                    SELECT lr.*
                    FROM leave_requests lr
                    WHERE lr.company_code=%s
                      AND lr.status='approved'
                      AND lr.start_date <= %s
                      AND lr.end_date >= %s
                      {employee_clause.format(alias='lr') if employee_clause else ''}
                      {scope_clause_leave}
                    ORDER BY lr.employee_name NULLS LAST, lr.start_date
                    """,
                    [*leave_params, *scope_params_leave],
                )
                leaves = [dict(row) for row in cur.fetchall()]
        svc = _attendance_authority.get_authority_service(company)
        scoped_keys = None
        if scope and scope.get("mode") not in {None, "company", "all"}:
            # Narrow to manager-visible employees when scope SQL cannot be applied to in-memory snaps.
            scoped_keys = {str(s.get("employee_key")) for s in shifts if s.get("employee_key")}
            scoped_keys |= {str(l.get("employee_key")) for l in leaves if l.get("employee_key")}
        result = svc.list_payroll_hours_from_snapshots(
            company_code=company,
            start_date=start_date,
            end_date=end_date,
            employee_key=str(employee.get("employee_key")) if employee else None,
            employee_keys=scoped_keys,
            shifts=shifts,
            leaves=leaves,
        )
        result["employee"] = json_safe(employee) if employee else None
        result["scope"] = json_safe(scope)
        result["action"] = action
        return result

    params: list[Any] = [company, start_date, end_date]
    employee_clause = ""
    if employee:
        employee_clause = "AND {alias}.employee_key=%s"
        params.append(employee.get("employee_key"))
    leave_params: list[Any] = [company, end_date, start_date]
    if employee:
        leave_params.append(employee.get("employee_key"))
    scope_clause_shifts, scope_params_shifts = employee_scope_sql("s", scope)
    scope_clause_attendance, scope_params_attendance = employee_scope_sql("ar", scope)
    scope_clause_leave, scope_params_leave = employee_scope_sql("lr", scope)
    # These three reads are the SOURCE data for payroll hour aggregation (and the
    # draft timesheets generated from it). They are intentionally UNCAPPED and
    # bounded only by the pay period + company (+ optional employee/scope): a hard
    # LIMIT here would silently drop employees from the money path once a company
    # has enough shifts/attendance/leave in a period, producing wrong pay. Rows
    # are grouped per-employee below, so the working set stays one pay period wide.
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT s.*
                FROM shift_assignments s
                WHERE s.company_code=%s
                  AND s.shift_date BETWEEN %s AND %s
                  AND status='scheduled'
                  {employee_clause.format(alias='s') if employee_clause else ''}
                  {scope_clause_shifts}
                ORDER BY s.employee_name NULLS LAST, s.shift_date, s.start_time
                """,
                [*params, *scope_params_shifts],
            )
            shifts = [dict(row) for row in cur.fetchall()]
            cur.execute(
                f"""
                SELECT ar.*
                FROM attendance_records ar
                WHERE ar.company_code=%s
                  AND ar.attendance_date BETWEEN %s AND %s
                  {employee_clause.format(alias='ar') if employee_clause else ''}
                  {scope_clause_attendance}
                ORDER BY ar.employee_name NULLS LAST, ar.attendance_date
                """,
                [*params, *scope_params_attendance],
            )
            attendance_rows = [dict(row) for row in cur.fetchall()]
            cur.execute(
                f"""
                SELECT lr.*
                FROM leave_requests lr
                WHERE lr.company_code=%s
                  AND lr.status='approved'
                  AND lr.start_date <= %s
                  AND lr.end_date >= %s
                  {employee_clause.format(alias='lr') if employee_clause else ''}
                  {scope_clause_leave}
                ORDER BY lr.employee_name NULLS LAST, lr.start_date
                """,
                [*leave_params, *scope_params_leave],
            )
            leaves = [dict(row) for row in cur.fetchall()]
    summaries: dict[str, dict[str, Any]] = {}

    def ensure_summary(key: str, *, name: str | None = None, phone: str | None = None) -> dict[str, Any]:
        summary = summaries.setdefault(
            key,
            {
                "employee_key": key,
                "employee_name": name or "",
                "employee_phone": digits(phone),
                "period": format_shift_date_range(start_date, end_date),
                "scheduled_minutes": 0,
                "worked_minutes": 0,
                "approved_leave_minutes": 0,
                "absent_minutes": 0,
                "late_minutes": 0,
                "early_leave_minutes": 0,
                "overtime_minutes": 0,
                "shift_count": 0,
                "attendance_count": 0,
                "approved_leave_days": 0,
            },
        )
        if name and not summary.get("employee_name"):
            summary["employee_name"] = name
        if phone and not summary.get("employee_phone"):
            summary["employee_phone"] = digits(phone)
        return summary

    approved_leave_by_employee: dict[str, list[dict[str, Any]]] = {}
    for leave in leaves:
        key = str(leave.get("employee_key") or "")
        if not key:
            continue
        approved_leave_by_employee.setdefault(key, []).append(leave)
        ensure_summary(key, name=leave.get("employee_name"), phone=leave.get("employee_phone"))

    for shift in shifts:
        key = str(shift.get("employee_key") or "")
        if not key:
            continue
        summary = ensure_summary(key, name=shift.get("employee_name"), phone=shift.get("employee_phone"))
        scheduled = minutes_between_times(shift.get("start_time"), shift.get("end_time"))
        summary["scheduled_minutes"] += scheduled
        if str(shift.get("status") or "scheduled") == "scheduled":
            summary["shift_count"] += 1
        shift_date = parse_shift_date_value(shift.get("shift_date"))
        if shift_date:
            on_leave = any(parse_shift_date_value(leave.get("start_date")) <= shift_date <= parse_shift_date_value(leave.get("end_date")) for leave in approved_leave_by_employee.get(key, []) if parse_shift_date_value(leave.get("start_date")) and parse_shift_date_value(leave.get("end_date")))
            if on_leave:
                summary["approved_leave_minutes"] += scheduled

    for row in attendance_rows:
        key = str(row.get("employee_key") or "")
        if not key:
            continue
        summary = ensure_summary(key, name=row.get("employee_name"), phone=row.get("employee_phone"))
        status = str(row.get("status") or "")
        summary["attendance_count"] += 1
        summary["late_minutes"] += int(row.get("late_minutes") or 0)
        summary["early_leave_minutes"] += int(row.get("early_leave_minutes") or 0)
        worked = minutes_between_datetimes(row.get("check_in_at"), row.get("check_out_at"))
        summary["worked_minutes"] += worked
        scheduled = minutes_between_times(row.get("scheduled_start"), row.get("scheduled_end"))
        if status == "absent":
            summary["absent_minutes"] += scheduled
        elif status == "approved_leave" and scheduled:
            if not approved_leave_by_employee.get(key):
                summary["approved_leave_minutes"] += scheduled

    for summary in summaries.values():
        summary["overtime_minutes"] = max(0, int(summary.get("worked_minutes") or 0) - int(summary.get("scheduled_minutes") or 0))
        if int(summary.get("absent_minutes") or 0):
            summary["payroll_status"] = "Needs review"
        elif int(summary.get("late_minutes") or 0) or int(summary.get("early_leave_minutes") or 0):
            summary["payroll_status"] = "Review exceptions"
        else:
            summary["payroll_status"] = "Ready"

    out = sorted(summaries.values(), key=lambda item: (str(item.get("employee_name") or "").lower(), str(item.get("employee_key") or "")))
    result = {
        "ok": True,
        "company_code": company,
        "start_date": start_date.isoformat(),
        "end_date": end_date.isoformat(),
        "employee": json_safe(employee) if employee else None,
        "summaries": json_safe(out),
        "count": len(out),
        "source_counts": {"shifts": len(shifts), "attendance": len(attendance_rows), "approved_leave": len(leaves)},
        "scope": json_safe(scope),
        # Live calculated hours are provisional until an approved timesheet exists.
        "authority": "provisional",
        "label": "provisional",
        "money_authority": "approved_timesheets",
    }
    return result


def analytics_insight(metric: str, subject: str, value: Any, detail: str) -> dict[str, Any]:
    return {
        "metric": metric,
        "subject": subject,
        "value": value,
        "detail": detail,
    }


def analytics_summary_counts(action: dict[str, Any], *, company: str, start_date: date, end_date: date, scope: dict[str, Any]) -> dict[str, int]:
    scope_shift_clause, scope_shift_params = employee_scope_sql("s", scope)
    scope_attendance_clause, scope_attendance_params = employee_scope_sql("ar", scope)
    scope_leave_clause, scope_leave_params = employee_scope_sql("lr", scope)
    scope_availability_clause, scope_availability_params = employee_scope_sql("av", scope)
    scope_swap_clause, scope_swap_params = employee_scope_sql("ss", scope)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                  COUNT(*) FILTER (WHERE s.status='scheduled') AS scheduled_shifts,
                  COUNT(*) FILTER (WHERE s.status='cancelled') AS cancelled_shifts
                FROM shift_assignments s
                WHERE s.company_code=%s
                  AND s.shift_date BETWEEN %s AND %s
                  {scope_shift_clause}
                """,
                [company, start_date, end_date, *scope_shift_params],
            )
            shift_counts = dict(cur.fetchone() or {})
            cur.execute(
                f"""
                SELECT
                  COUNT(*) FILTER (WHERE ar.status='absent') AS absent_records,
                  COUNT(*) FILTER (WHERE COALESCE(ar.late_minutes, 0) > 0 OR ar.status='late') AS late_records,
                  COALESCE(SUM(ar.late_minutes), 0) AS late_minutes
                FROM attendance_records ar
                WHERE ar.company_code=%s
                  AND ar.attendance_date BETWEEN %s AND %s
                  {scope_attendance_clause}
                """,
                [company, start_date, end_date, *scope_attendance_params],
            )
            attendance_counts = dict(cur.fetchone() or {})
            cur.execute(
                f"""
                SELECT
                  COUNT(*) FILTER (WHERE lr.status='requested') AS pending_leave,
                  COUNT(*) FILTER (WHERE lr.status='approved') AS approved_leave
                FROM leave_requests lr
                WHERE lr.company_code=%s
                  AND lr.start_date <= %s
                  AND lr.end_date >= %s
                  {scope_leave_clause}
                """,
                [company, end_date, start_date, *scope_leave_params],
            )
            leave_counts = dict(cur.fetchone() or {})
            cur.execute(
                f"""
                SELECT
                  COUNT(*) FILTER (WHERE av.status='requested') AS pending_availability,
                  COUNT(*) FILTER (WHERE av.availability_type='unavailable' AND av.status IN ('requested','approved')) AS unavailable_records
                FROM employee_availability_requests av
                WHERE av.company_code=%s
                  AND av.start_date <= %s
                  AND av.end_date >= %s
                  {scope_availability_clause}
                """,
                [company, end_date, start_date, *scope_availability_params],
            )
            availability_counts = dict(cur.fetchone() or {})
            cur.execute(
                f"""
                SELECT COUNT(*) FILTER (WHERE ss.status='requested') AS pending_swaps
                FROM shift_swap_requests ss
                WHERE ss.company_code=%s
                  AND (ss.shift_date BETWEEN %s AND %s OR ss.shift_date IS NULL)
                  {scope_swap_clause.replace('ss.employee_key', 'ss.requester_employee_key') if scope_swap_clause else ''}
                """,
                [company, start_date, end_date, *scope_swap_params],
            )
            swap_counts = dict(cur.fetchone() or {})
    combined = {**shift_counts, **attendance_counts, **leave_counts, **availability_counts, **swap_counts}
    return {key: int(value or 0) for key, value in combined.items()}


def analytics_branch_absences(*, company: str, start_date: date, end_date: date, scope: dict[str, Any]) -> list[dict[str, Any]]:
    scope_clause, scope_params = employee_scope_sql("ar", scope)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                  COALESCE(cb.branch_name, oa.branch_key, 'Unassigned') AS branch_name,
                  COUNT(*) AS absent_count
                FROM attendance_records ar
                LEFT JOIN employee_org_assignments oa
                  ON oa.company_code=ar.company_code
                 AND oa.employee_key=ar.employee_key
                 AND oa.is_primary IS TRUE
                LEFT JOIN company_branches cb ON cb.branch_key=oa.branch_key
                WHERE ar.company_code=%s
                  AND ar.attendance_date BETWEEN %s AND %s
                  AND ar.status='absent'
                  {scope_clause}
                GROUP BY COALESCE(cb.branch_name, oa.branch_key, 'Unassigned')
                ORDER BY absent_count DESC, branch_name
                LIMIT 10
                """,
                [company, start_date, end_date, *scope_params],
            )
            return [dict(row) for row in cur.fetchall()]


def workforce_analytics(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    """Wave 1 Attention Contract: scoped read projection with ranked attention.

    Analytics is never money authority. Frozen modules remain systems of action.
    """
    import analytics_attention_wave1 as _analytics_w1

    company = require_company_code(company_code)
    start_date, end_date = payroll_period_from_action(action)
    scope = org_scope_for_action(action, company)
    if scope.get("blocked"):
        return {"ok": False, "error": "employee_outside_manager_scope", "action": action, "scope": json_safe(scope)}
    metric = analytics_metric_from_text(action.get("metric") or action.get("prompt_text") or action.get("query") or "")
    as_of = datetime.now(KUWAIT_TZ).isoformat()

    enabled_modules = set(configured_company_modules(company) or [])
    # Prefer live entitlement checks when available (pause/disable aware).
    for key in ("attendance", "leave", "shifts", "payroll", "employees", "onboarding", "compliance", "analytics"):
        try:
            if company_has_module(company, key):
                enabled_modules.add(key)
            else:
                enabled_modules.discard(key)
        except Exception:
            pass
    source_pack = _analytics_w1.analytics_source_availability(enabled_modules)

    summaries: list[dict[str, Any]] = []
    payroll: dict[str, Any] = {"ok": True, "summaries": [], "source_counts": {}}
    hours_error: str | None = None
    if source_pack["sources"].get("hours_summary", {}).get("available"):
        payroll = list_payroll_hours(
            {**action, "start_date": start_date.isoformat(), "end_date": end_date.isoformat()},
            company_code=company,
        )
        if not payroll.get("ok"):
            # Scope blocks remain hard failures; other hours failures degrade gracefully.
            if payroll.get("error") == "employee_outside_manager_scope":
                return payroll
            hours_error = str(payroll.get("error") or "hours_summary_unavailable")
            source_pack["sources"]["hours_summary"] = {
                **source_pack["sources"]["hours_summary"],
                "available": False,
                "status": "error",
                "note_en": "Hours summary could not be refreshed for this period.",
                "note_ar": "تعذر تحديث ملخص الساعات لهذه الفترة.",
                "error": hours_error,
            }
            source_pack["unavailable_source_keys"] = [
                key for key, row in source_pack["sources"].items() if not row.get("available")
            ]
            source_pack["partial"] = True
            payroll = {"ok": True, "summaries": [], "source_counts": {}}
        else:
            summaries = payroll.get("summaries") if isinstance(payroll.get("summaries"), list) else []

    # Counts always run against available operational tables; SQL is scoped.
    # When a producing module is disabled, UI discloses via sources — counts may
    # still be zero from empty tables without inventing authority.
    counts = analytics_summary_counts(action, company=company, start_date=start_date, end_date=end_date, scope=scope)
    # Disclose-only: hide counts from disabled producing modules so partial tenants
    # do not see silent rollups from tables they are not entitled to operate.
    src_map = source_pack.get("sources") if isinstance(source_pack.get("sources"), dict) else {}
    if not src_map.get("attendance", {}).get("available"):
        counts["absent_records"] = 0
        counts["late_records"] = 0
        counts["late_minutes"] = 0
    if not src_map.get("leave", {}).get("available"):
        counts["pending_leave"] = 0
        counts["approved_leave"] = 0
    if not src_map.get("shifts", {}).get("available"):
        counts["scheduled_shifts"] = 0
        counts["cancelled_shifts"] = 0
        counts["pending_swaps"] = 0
        counts["pending_availability"] = 0
        counts["unavailable_records"] = 0
    branch_rows = (
        analytics_branch_absences(company=company, start_date=start_date, end_date=end_date, scope=scope)
        if src_map.get("attendance", {}).get("available")
        else []
    )

    attention = _analytics_w1.build_analytics_attention(
        counts=counts,
        summaries=summaries,
        branch_rows=branch_rows,
        sources=source_pack,
        employees_deep_link_ok=True,
    )
    insights = _analytics_w1.build_analytics_pattern_insights(
        counts=counts,
        summaries=summaries,
        branch_rows=branch_rows,
        sources=source_pack,
        decimal_hours_fn=decimal_hours,
    )
    headlines = _analytics_w1.attention_headline_stats(counts, source_pack)
    definitions = _analytics_w1.analytics_metric_definitions()

    result = {
        "ok": True,
        "company_code": company,
        "start_date": start_date.isoformat(),
        "end_date": end_date.isoformat(),
        "as_of": as_of,
        "timezone": "Asia/Kuwait",
        "window": {
            "kind": "month_to_date",
            "label_en": "Kuwait month-to-date",
            "label_ar": "من بداية الشهر حتى اليوم (الكويت)",
            "start_date": start_date.isoformat(),
            "end_date": end_date.isoformat(),
        },
        "metric": metric,
        "counts": counts,
        "headlines": json_safe(headlines),
        "attention": json_safe(attention),
        "insights": json_safe(insights),
        "definitions": json_safe(definitions),
        "sources": json_safe(source_pack),
        "branch_absences": json_safe(branch_rows),
        "freshness": {
            "as_of": as_of,
            "max_age_seconds": 300,
            "stale_after_seconds": 300,
        },
        "authority": {
            "read_only": True,
            "money_authority": False,
            "systems_of_action": ["attendance", "leave", "shifts", "employees"],
            "hiring_reports_separate": True,
            "alerts_delivery_owns_communication": True,
            **(
                {
                    "wave1_enabled": _analytics_w1.analytics_wave1_enabled_for_company(company),
                    "synthetic_only": _analytics_w1.analytics_wave1_synthetic_only(),
                    "honesty": _analytics_w1.honesty_payload(),
                }
                if True
                else {}
            ),
        },
        "source_counts": {
            **(payroll.get("source_counts") if isinstance(payroll.get("source_counts"), dict) else {}),
            "analytics_insights": len(insights),
            "analytics_attention": len(attention),
        },
        "scope": json_safe(scope),
        "contract": _analytics_w1.ANALYTICS_WAVE1_CONTRACT,
        "contract_version": _analytics_w1.ANALYTICS_WAVE1_VERSION,
    }
    if hours_error:
        result["hours_summary_error"] = hours_error
    return result


def record_timesheet_event(cur: Any, *, timesheet: dict[str, Any] | None, company_code: str, event_type: str, payload: dict[str, Any], created_by_phone: str | None) -> None:
    cur.execute(
        """
        INSERT INTO payroll_timesheet_events (timesheet_id, company_code, employee_key, event_type, payload, created_by_phone)
        VALUES (%s,%s,%s,%s,%s,%s)
        """,
        (
            timesheet.get("timesheet_id") if timesheet else payload.get("timesheet_id"),
            company_code,
            timesheet.get("employee_key") if timesheet else payload.get("employee_key"),
            event_type,
            Json(json_safe(payload)),
            digits(created_by_phone),
        ),
    )


def invalidate_provisional_timesheets(
    cur: Any,
    *,
    company_code: str,
    employee_key: str | None,
    start_date: date,
    end_date: date,
    reason: str,
    created_by_phone: str | None = None,
    leave_id: str | None = None,
) -> list[dict[str, Any]]:
    """Mark overlapping non-approved timesheets dirty so payroll must regenerate.

    Approved timesheets remain money authority and are never modified here.
    """
    company = str(company_code or "").upper()
    if not company or not employee_key or not start_date or not end_date:
        return []
    cur.execute(
        """
        UPDATE payroll_timesheets
        SET status='draft',
            payroll_status='recalculation_required',
            decided_by_phone=NULL,
            decision_note=NULL,
            approved_at=NULL,
            rejected_at=NULL,
            snapshot=COALESCE(snapshot, '{}'::jsonb) || %s,
            updated_at=now()
        WHERE company_code=%s
          AND employee_key=%s
          AND status IN ('draft', 'rejected')
          AND period_start <= %s
          AND period_end >= %s
        RETURNING *
        """,
        (
            Json(
                {
                    "provisional": True,
                    "recalculation_required": True,
                    "invalidation_reason": reason,
                    "leave_id": leave_id,
                    "invalidated_at": now_iso(),
                }
            ),
            company,
            employee_key,
            end_date,
            start_date,
        ),
    )
    rows = [dict(row) for row in cur.fetchall()]
    for row in rows:
        record_timesheet_event(
            cur,
            timesheet=row,
            company_code=company,
            event_type="recalculation_required",
            payload={"timesheet": row, "reason": reason, "leave_id": leave_id},
            created_by_phone=created_by_phone,
        )
    return rows


def apply_leave_attendance_effect(
    cur: Any,
    *,
    company: str,
    leave: dict[str, Any],
    created_by_phone: str | None = None,
) -> list[dict[str, Any]]:
    """Derive attendance rows from an approved leave and stamp leave provenance."""
    leave_id = str(leave.get("leave_id") or "")
    employee_key = str(leave.get("employee_key") or "")
    start_date = parse_shift_date_value(leave.get("start_date"))
    end_date = parse_shift_date_value(leave.get("end_date"))
    if not leave_id or not employee_key or not start_date or not end_date:
        return []
    employee = {
        "employee_key": employee_key,
        "phone": leave.get("employee_phone"),
        "name": leave.get("employee_name"),
        "company_code": company,
    }
    if attendance_authority_enabled_for_company(company):
        svc = _attendance_authority.get_authority_service(company)
        updated: list[dict[str, Any]] = []
        day = start_date
        while day <= end_date:
            cur.execute(
                """
                SELECT *
                FROM shift_assignments
                WHERE company_code=%s AND employee_key=%s AND shift_date=%s AND status='scheduled'
                ORDER BY start_time
                """,
                (company, employee_key, day),
            )
            shifts = [dict(row) for row in cur.fetchall()]
            if not shifts:
                shifts = [None]
            for shift in shifts:
                authority = svc.apply_leave(
                    company_code=company,
                    employee=employee,
                    work_date=day,
                    leave_id=leave_id,
                    shift=shift,
                    created_by_phone=created_by_phone,
                )
                compat = authority.get("compat") or {}
                attendance = _mirror_authority_compat_to_records(
                    cur,
                    company=company,
                    employee=employee,
                    shift=shift,
                    attendance_date=day,
                    compat=compat,
                    created_by_phone=created_by_phone,
                    action={"action_type": "leave_approval_attendance", "leave_id": leave_id, "derived_from_leave": True},
                )
                cur.execute(
                    """
                    UPDATE attendance_records
                    SET status='approved_leave',
                        notes=COALESCE(NULLIF(notes,''), 'Approved leave'),
                        metadata=metadata || %s,
                        updated_at=now()
                    WHERE attendance_id=%s AND company_code=%s
                    RETURNING *
                    """,
                    (
                        Json({"leave_id": leave_id, "derived_from_leave": True, "source": "leave_approval", "authority": _attendance_authority.AUTHORITY_VERSION}),
                        attendance.get("attendance_id"),
                        company,
                    ),
                )
                stamped = cur.fetchone()
                if stamped:
                    updated.append(dict(stamped))
                    record_attendance_event(
                        cur,
                        attendance=dict(stamped),
                        company_code=company,
                        event_type="approved_leave",
                        payload={"attendance": dict(stamped), "leave_id": leave_id, "shift": shift, "authority": authority},
                        created_by_phone=created_by_phone,
                    )
            day += timedelta(days=1)
        return updated
    # Convert any existing absences in the leave window.
    cur.execute(
        """
        UPDATE attendance_records
        SET status='approved_leave',
            notes=COALESCE(NULLIF(notes,''), 'Approved leave'),
            metadata=metadata || %s,
            updated_at=now()
        WHERE company_code=%s
          AND employee_key=%s
          AND attendance_date BETWEEN %s AND %s
          AND status='absent'
        RETURNING *
        """,
        (
            Json({"leave_id": leave_id, "derived_from_leave": True, "source": "leave_approval"}),
            company,
            employee_key,
            start_date,
            end_date,
        ),
    )
    updated = [dict(row) for row in cur.fetchall()]
    # Create leave-derived attendance for scheduled shifts that have no attendance yet.
    cur.execute(
        """
        SELECT s.*
        FROM shift_assignments s
        LEFT JOIN attendance_records ar
          ON ar.company_code=s.company_code
         AND ar.employee_key=s.employee_key
         AND ar.shift_id=s.shift_id
        WHERE s.company_code=%s
          AND s.employee_key=%s
          AND s.status='scheduled'
          AND s.shift_date BETWEEN %s AND %s
          AND ar.attendance_id IS NULL
        ORDER BY s.shift_date, s.start_time
        """,
        (company, employee_key, start_date, end_date),
    )
    shifts = [dict(row) for row in cur.fetchall()]
    for shift in shifts:
        attendance = upsert_attendance_record(
            cur,
            company=company,
            employee=employee,
            shift=shift,
            attendance_date=parse_shift_date_value(shift.get("shift_date")) or start_date,
            status="approved_leave",
            notes="Approved leave",
            source_text="leave_approval",
            created_by_phone=created_by_phone,
            action={"action_type": "leave_approval_attendance", "leave_id": leave_id, "derived_from_leave": True},
        )
        # Ensure leave provenance is explicit even if upsert merged metadata.
        cur.execute(
            """
            UPDATE attendance_records
            SET metadata=metadata || %s, updated_at=now()
            WHERE attendance_id=%s AND company_code=%s
            RETURNING *
            """,
            (
                Json({"leave_id": leave_id, "derived_from_leave": True, "source": "leave_approval"}),
                attendance.get("attendance_id"),
                company,
            ),
        )
        stamped = cur.fetchone()
        if stamped:
            updated.append(dict(stamped))
            record_attendance_event(
                cur,
                attendance=dict(stamped),
                company_code=company,
                event_type="approved_leave",
                payload={"attendance": dict(stamped), "leave_id": leave_id, "shift": shift},
                created_by_phone=created_by_phone,
            )
    return updated


def reverse_leave_derived_attendance(
    cur: Any,
    *,
    company: str,
    leave: dict[str, Any],
    created_by_phone: str | None = None,
) -> list[dict[str, Any]]:
    """Reverse only attendance records derived from this leave; preserve manual edits."""
    leave_id = str(leave.get("leave_id") or "")
    employee_key = str(leave.get("employee_key") or "")
    start_date = parse_shift_date_value(leave.get("start_date"))
    end_date = parse_shift_date_value(leave.get("end_date"))
    if not leave_id or not employee_key or not start_date or not end_date:
        return []
    if attendance_authority_enabled_for_company(company):
        employee = {
            "employee_key": employee_key,
            "phone": leave.get("employee_phone"),
            "name": leave.get("employee_name"),
            "company_code": company,
        }
        svc = _attendance_authority.get_authority_service(company)
        preserved: list[dict[str, Any]] = []
        day = start_date
        while day <= end_date:
            cur.execute(
                """
                SELECT *
                FROM shift_assignments
                WHERE company_code=%s AND employee_key=%s AND shift_date=%s AND status='scheduled'
                ORDER BY start_time
                """,
                (company, employee_key, day),
            )
            shifts = [dict(row) for row in cur.fetchall()] or [None]
            for shift in shifts:
                result = svc.reverse_leave(
                    company_code=company,
                    employee=employee,
                    work_date=day,
                    leave_id=leave_id,
                    shift=shift,
                    created_by_phone=created_by_phone,
                )
                if result.get("reason") == "manual_correction_preserved":
                    preserved.append(result.get("projection") or {})
                elif result.get("projection") or result.get("ok"):
                    # Mirror void/reprojected day into compatibility read model when present.
                    proj = result.get("projection")
                    if proj and shift is not None:
                        compat = _attendance_authority.projection_to_compat_record(proj)
                        if proj.get("status") in {"incomplete", None} and not proj.get("check_in_at"):
                            # Remove leave-derived legacy mirror only when no punches remain.
                            cur.execute(
                                """
                                DELETE FROM attendance_records
                                WHERE company_code=%s
                                  AND employee_key=%s
                                  AND attendance_date=%s
                                  AND ((shift_id IS NULL AND %s IS NULL) OR shift_id=%s)
                                  AND status='approved_leave'
                                  AND (
                                    metadata->>'leave_id' = %s
                                    OR COALESCE(notes, '') = 'Approved leave'
                                  )
                                  AND COALESCE(metadata->>'manual_edit', 'false') <> 'true'
                                  AND COALESCE(metadata->>'authority', '') = %s
                                RETURNING *
                                """,
                                (
                                    company,
                                    employee_key,
                                    day,
                                    shift.get("shift_id") if shift else None,
                                    shift.get("shift_id") if shift else None,
                                    leave_id,
                                    _attendance_authority.AUTHORITY_VERSION,
                                ),
                            )
                            preserved.extend([dict(r) for r in cur.fetchall()])
                        else:
                            mirrored = _mirror_authority_compat_to_records(
                                cur,
                                company=company,
                                employee=employee,
                                shift=shift,
                                attendance_date=day,
                                compat=compat,
                                created_by_phone=created_by_phone,
                                action={"action_type": "leave_reversal", "leave_id": leave_id},
                            )
                            preserved.append(mirrored)
            day += timedelta(days=1)
        return preserved
    cur.execute(
        """
        SELECT *
        FROM attendance_records
        WHERE company_code=%s
          AND employee_key=%s
          AND attendance_date BETWEEN %s AND %s
          AND status='approved_leave'
          AND (
            metadata->>'leave_id' = %s
            OR (
              COALESCE(metadata->>'leave_id', '') = ''
              AND COALESCE(notes, '') = 'Approved leave'
            )
          )
          AND COALESCE(metadata->>'manual_edit', 'false') <> 'true'
        """,
        (company, employee_key, start_date, end_date, leave_id),
    )
    to_reverse = [dict(row) for row in cur.fetchall()]
    for row in to_reverse:
        record_attendance_event(
            cur,
            attendance=row,
            company_code=company,
            event_type="leave_derived_reversed",
            payload={"attendance": row, "leave_id": leave_id},
            created_by_phone=created_by_phone,
        )
    if not to_reverse:
        return []
    ids = [r.get("attendance_id") for r in to_reverse if r.get("attendance_id")]
    cur.execute(
        """
        DELETE FROM attendance_records
        WHERE company_code=%s
          AND attendance_id = ANY(%s::uuid[])
        RETURNING *
        """,
        (company, ids),
    )
    return [dict(row) for row in cur.fetchall()]


def create_timesheet_review(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    payroll = list_payroll_hours(action, company_code=company)
    if not payroll.get("ok"):
        return payroll
    summaries = payroll.get("summaries") if isinstance(payroll.get("summaries"), list) else []
    start_date = parse_shift_date_value(payroll.get("start_date"))
    end_date = parse_shift_date_value(payroll.get("end_date"))
    if not start_date or not end_date:
        return {"ok": False, "error": "invalid_period", "payroll": payroll, "action": action}
    created_or_updated: list[dict[str, Any]] = []
    skipped_approved: list[dict[str, Any]] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            for summary in summaries:
                employee_key = str(summary.get("employee_key") or "")
                if not employee_key:
                    continue
                cur.execute(
                    """
                    SELECT *
                    FROM payroll_timesheets
                    WHERE company_code=%s AND employee_key=%s AND period_start=%s AND period_end=%s
                    LIMIT 1
                    """,
                    (company, employee_key, start_date, end_date),
                )
                existing = cur.fetchone()
                if existing and str(existing.get("status") or "") == "approved":
                    skipped_approved.append(dict(existing))
                    continue
                cur.execute(
                    """
                    INSERT INTO payroll_timesheets (
                      company_code, employee_key, employee_phone, employee_name,
                      period_start, period_end, status, scheduled_minutes, worked_minutes,
                      approved_leave_minutes, absent_minutes, late_minutes, early_leave_minutes,
                      overtime_minutes, payroll_status, snapshot, source_counts, created_by_phone, updated_at
                    )
                    VALUES (%s,%s,%s,%s,%s,%s,'draft',%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,now())
                    ON CONFLICT (company_code, employee_key, period_start, period_end) DO UPDATE SET
                      employee_phone=EXCLUDED.employee_phone,
                      employee_name=EXCLUDED.employee_name,
                      status='draft',
                      scheduled_minutes=EXCLUDED.scheduled_minutes,
                      worked_minutes=EXCLUDED.worked_minutes,
                      approved_leave_minutes=EXCLUDED.approved_leave_minutes,
                      absent_minutes=EXCLUDED.absent_minutes,
                      late_minutes=EXCLUDED.late_minutes,
                      early_leave_minutes=EXCLUDED.early_leave_minutes,
                      overtime_minutes=EXCLUDED.overtime_minutes,
                      payroll_status=EXCLUDED.payroll_status,
                      snapshot=EXCLUDED.snapshot,
                      source_counts=EXCLUDED.source_counts,
                      created_by_phone=COALESCE(payroll_timesheets.created_by_phone, EXCLUDED.created_by_phone),
                      decided_by_phone=NULL,
                      decision_note=NULL,
                      approved_at=NULL,
                      rejected_at=NULL,
                      updated_at=now()
                    RETURNING *
                    """,
                    (
                        company,
                        employee_key,
                        digits(summary.get("employee_phone")),
                        summary.get("employee_name"),
                        start_date,
                        end_date,
                        int(summary.get("scheduled_minutes") or 0),
                        int(summary.get("worked_minutes") or 0),
                        int(summary.get("approved_leave_minutes") or 0),
                        int(summary.get("absent_minutes") or 0),
                        int(summary.get("late_minutes") or 0),
                        int(summary.get("early_leave_minutes") or 0),
                        int(summary.get("overtime_minutes") or 0),
                        summary.get("payroll_status"),
                        Json(json_safe({**summary, "provisional": True, "recalculation_required": False, "authority": "provisional"})),
                        Json(json_safe(payroll.get("source_counts") or {})),
                        digits(created_by_phone),
                    ),
                )
                row = dict(cur.fetchone())
                created_or_updated.append(row)
                record_timesheet_event(cur, timesheet=row, company_code=company, event_type="draft_refreshed", payload={"timesheet": row, "summary": summary, "action": action}, created_by_phone=created_by_phone)
        conn.commit()
    return {
        "ok": True,
        "company_code": company,
        "start_date": start_date.isoformat(),
        "end_date": end_date.isoformat(),
        "timesheets": json_safe(created_or_updated),
        "skipped_approved": json_safe(skipped_approved),
        "count": len(created_or_updated),
        "payroll": {key: payroll.get(key) for key in ("source_counts", "count")},
        "action": action,
    }


def timesheet_by_id(timesheet_id: str | None, *, company_code: str | None = None) -> dict[str, Any] | None:
    if not timesheet_id:
        return None
    # Tenant isolation on a money-adjacent lookup: when a company is known, a
    # timesheet from another company must never resolve — a guessed/leaked UUID
    # could otherwise be approved/rejected cross-tenant.
    with db_connect() as conn:
        with conn.cursor() as cur:
            if company_code:
                cur.execute(
                    "SELECT * FROM payroll_timesheets WHERE timesheet_id=%s AND company_code=%s LIMIT 1",
                    (timesheet_id, str(company_code).upper()),
                )
            else:
                cur.execute("SELECT * FROM payroll_timesheets WHERE timesheet_id=%s LIMIT 1", (timesheet_id,))
            row = cur.fetchone()
            return dict(row) if row else None


def resolve_timesheets(action: dict[str, Any], *, company_code: str | None, statuses: tuple[str, ...] = ("draft",)) -> list[dict[str, Any]]:
    company = require_company_code(company_code)
    explicit = timesheet_by_id(str(action.get("timesheet_id") or "").strip(), company_code=company)
    if explicit:
        employee_ref = {"employee_key": explicit.get("employee_key"), "company_code": company}
        if action.get("viewer_phone") and not manager_scope_allows_employee(employee_ref, company_code=company, viewer_phone=action.get("viewer_phone")):
            return []
        return [explicit] if (not statuses or str(explicit.get("status") or "") in statuses) else []
    employee = resolve_attendance_employee(action, company_code=company, required=False)
    start_date, end_date = payroll_period_from_action(action)
    scope = org_scope_for_action(action, company)
    params: list[Any] = [company, start_date, end_date]
    where = ["pt.company_code=%s", "pt.period_start=%s", "pt.period_end=%s"]
    if employee:
        where.append("pt.employee_key=%s")
        params.append(employee.get("employee_key"))
    if statuses:
        where.append("pt.status = ANY(%s)")
        params.append(list(statuses))
    scope_clause, scope_params = employee_scope_sql("pt", scope)
    if scope_clause:
        where.append(scope_clause.removeprefix("AND "))
        params.extend(scope_params)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT pt.*
                FROM payroll_timesheets pt
                WHERE {' AND '.join(where)}
                ORDER BY pt.employee_name NULLS LAST, pt.updated_at DESC
                LIMIT 200
                """,
                params,
            )
            return [dict(row) for row in cur.fetchall()]


def decide_timesheets(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None, decision: str) -> dict[str, Any]:
    company = require_company_code(company_code)
    if not action.get("timesheet_id") and not text_has_period_signal(str(action.get("prompt_text") or action.get("query") or "")) and not (action.get("start_date") and action.get("end_date")):
        return {"ok": False, "error": "missing_period", "needs_clarification": True, "action": action}
    target_rows = resolve_timesheets(action, company_code=company, statuses=("draft",))
    if not target_rows:
        return {"ok": False, "error": "timesheet_not_found", "action": action}
    dirty = [
        row
        for row in target_rows
        if str(row.get("payroll_status") or "") == "recalculation_required"
        or bool((row.get("snapshot") or {}).get("recalculation_required") if isinstance(row.get("snapshot"), dict) else False)
    ]
    if decision == "approved" and dirty:
        return {
            "ok": False,
            "error": "recalculation_required",
            "needs_clarification": True,
            "message": "Regenerate provisional timesheets before approval or export.",
            "timesheets": json_safe(dirty),
            "action": action,
        }
    wave1 = _payroll_w1.payroll_wave1_enabled_for_company(company)
    decision_note = str(action.get("decision_note") or action.get("audit_reason") or action.get("query") or action.get("prompt_text") or "").strip() or None
    if wave1:
        reason_denied = _payroll_w1.require_audit_reason(decision_note)
        if reason_denied:
            return {**reason_denied, "action": action}
        quarantined = [
            row
            for row in target_rows
            if str(row.get("quarantine_status") or "").strip()
            or str(row.get("payroll_status") or "") == "quarantined"
        ]
        if quarantined:
            return {
                "ok": False,
                "error": "timesheet_quarantined",
                "message": "Quarantined timesheets cannot be approved or rejected.",
                "timesheets": json_safe(quarantined),
                "action": action,
            }
        actor_pre = digits(created_by_phone)
        viewer = action.get("viewer_phone") or actor_pre
        for row in target_rows:
            subject_phone = digits(
                row.get("employee_phone")
                or action.get("subject_phone")
                or str(row.get("employee_key") or "").rsplit("-", 1)[-1]
            )
            self_ban = _payroll_w1.self_decision_denied(
                subject_phone=subject_phone,
                actor_phone=actor_pre,
                action=f"timesheet_{decision}",
            )
            if self_ban:
                return {**self_ban, "action": action, "timesheet_id": row.get("timesheet_id")}
            creator_ban = _payroll_w1.creator_self_approve_denied(
                created_by_phone=row.get("created_by_phone"),
                actor_phone=actor_pre,
                action=f"timesheet_{decision}",
            )
            if creator_ban:
                return {**creator_ban, "action": action, "timesheet_id": row.get("timesheet_id")}
            emp = {
                "employee_key": row.get("employee_key"),
                "employee_phone": subject_phone,
                "phone": subject_phone,
            }
            if viewer and not manager_scope_allows_employee(emp, company_code=company, viewer_phone=viewer):
                return {
                    "ok": False,
                    "error": "employee_outside_manager_scope",
                    "timesheet_id": row.get("timesheet_id"),
                    "action": action,
                }
    updated_rows: list[dict[str, Any]] = []
    status_value = "approved" if decision == "approved" else "rejected"
    timestamp_col = "approved_at" if decision == "approved" else "rejected_at"
    actor = digits(created_by_phone)
    with db_connect() as conn:
        with conn.cursor() as cur:
            if wave1:
                _payroll_w1.ensure_payroll_wave1_schema(cur)
            for row in target_rows:
                if wave1:
                    expected_rv = action.get("expected_row_version")
                    if expected_rv is None and len(target_rows) == 1:
                        expected_rv = row.get("row_version", 1)
                    conc = _payroll_w1.require_concurrency(
                        expected_row_version=expected_rv,
                        actual_row_version=row.get("row_version", 1),
                    )
                    if conc:
                        return {**conc, "action": action, "timesheet_id": row.get("timesheet_id")}
                    cur.execute(
                        f"""
                        UPDATE payroll_timesheets
                        SET status=%s, decided_by_phone=%s, decision_note=%s, {timestamp_col}=now(),
                            updated_at=now(), row_version=COALESCE(row_version,1)+1
                        WHERE timesheet_id=%s AND company_code=%s AND status='draft'
                          AND COALESCE(payroll_status, '') <> 'recalculation_required'
                          AND COALESCE(quarantine_status, '') = ''
                          AND COALESCE(row_version,1)=%s
                        RETURNING *
                        """,
                        (
                            status_value,
                            actor,
                            decision_note,
                            row.get("timesheet_id"),
                            company,
                            int(expected_rv),
                        ),
                    )
                else:
                    cur.execute(
                        f"""
                        UPDATE payroll_timesheets
                        SET status=%s, decided_by_phone=%s, decision_note=%s, {timestamp_col}=now(), updated_at=now()
                        WHERE timesheet_id=%s AND company_code=%s AND status='draft'
                          AND COALESCE(payroll_status, '') <> 'recalculation_required'
                        RETURNING *
                        """,
                        (status_value, actor, decision_note, row.get("timesheet_id"), company),
                    )
                updated = cur.fetchone()
                if not updated:
                    continue
                updated_dict = dict(updated)
                updated_rows.append(updated_dict)
                record_timesheet_event(cur, timesheet=updated_dict, company_code=company, event_type=status_value, payload={"timesheet": updated_dict, "action": action}, created_by_phone=created_by_phone)
        conn.commit()
    if decision == "approved" and not updated_rows:
        return {"ok": False, "error": "recalculation_required" if not wave1 else "timesheet_decision_failed", "action": action}
    return {"ok": True, "company_code": company, "decision": status_value, "timesheets": json_safe(updated_rows), "count": len(updated_rows), "action": action, **(_payroll_w1.honesty_payload() if wave1 else {})}


def approve_timesheet(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    return decide_timesheets(action, company_code=company_code, created_by_phone=created_by_phone, decision="approved")


def reject_timesheet(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    return decide_timesheets(action, company_code=company_code, created_by_phone=created_by_phone, decision="rejected")


def list_timesheets(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    start_date, end_date = payroll_period_from_action(action)
    scope = org_scope_for_action(action, company)
    employee = resolve_attendance_employee(action, company_code=company, required=False)
    if employee and action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "action": action, "scope": json_safe(scope)}
    if (action.get("subject_name") or action.get("subject_phone")) and not employee:
        return {"ok": False, "error": "employee_not_found", "action": action}
    status_filter = normalize_text(action.get("status") or "")
    allowed_statuses = {"draft", "approved", "rejected"}
    params: list[Any] = [company, start_date, end_date]
    where = ["pt.company_code=%s", "pt.period_start=%s", "pt.period_end=%s"]
    if employee:
        where.append("pt.employee_key=%s")
        params.append(employee.get("employee_key"))
    if status_filter in allowed_statuses:
        where.append("pt.status=%s")
        params.append(status_filter)
    scope_clause, scope_params = employee_scope_sql("pt", scope)
    if scope_clause:
        where.append(scope_clause.removeprefix("AND "))
        params.extend(scope_params)
    # Pagination. Default limit=200 keeps every existing caller identical; the
    # dashboard passes limit/offset to page through a period with >200 timesheets
    # (a company with >200 employees) instead of silently dropping the rest. The
    # PK tiebreaker makes the sort a total order so OFFSET paging is stable, and
    # COUNT(*) OVER() rides the same scan for an accurate total + has_more.
    row_limit, offset = _paginate_params(action, default_limit=200, max_limit=500)
    params.extend([row_limit, offset])
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT pt.*,
                       COUNT(*) OVER() AS _total_count,
                       COUNT(*) FILTER (WHERE pt.status='draft') OVER() AS _draft_count
                FROM payroll_timesheets pt
                WHERE {' AND '.join(where)}
                ORDER BY pt.employee_name NULLS LAST, pt.updated_at DESC, pt.timesheet_id
                LIMIT %s OFFSET %s
                """,
                params,
            )
            rows = [dict(row) for row in cur.fetchall()]
    total_count = int(rows[0]["_total_count"]) if rows else 0
    # True count of draft (awaiting-review) timesheets across the WHOLE filtered
    # period, not just the loaded page — the "N timesheets need review" banner must
    # not shrink to a page length once a period has >200 employees.
    draft_count = int(rows[0]["_draft_count"]) if rows else 0
    for row in rows:
        row.pop("_total_count", None)
        row.pop("_draft_count", None)
    has_more = (offset + len(rows)) < total_count
    return {
        "ok": True,
        "company_code": company,
        "start_date": start_date.isoformat(),
        "end_date": end_date.isoformat(),
        "status_filter": status_filter if status_filter in allowed_statuses else "",
        "timesheets": json_safe(rows),
        "count": len(rows),
        "draft_count": draft_count,
        "employee": json_safe(employee) if employee else None,
        "scope": json_safe(scope),
        "action": action,
        "total_count": total_count,
        "limit": row_limit,
        "offset": offset,
        "has_more": has_more,
    }


def default_payroll_policy(company_code: str | None = None) -> dict[str, Any]:
    return {
        "employee_pay_type": "monthly",
        "leave_policy": "paid",
        "overtime_policy": "review_only",
        "overtime_cap_minutes": 0,
        "absence_deduction_enabled": True,
        "late_deduction_enabled": False,
        "early_leave_deduction_enabled": False,
        "default_hourly_rate_kwd": None,
        "currency": company_currency(company_code) if company_code else _company_setup.DEFAULT_CURRENCY,
        "payment_processing": "disabled",
    }


def normalized_policy_value(value: Any) -> str:
    return normalize_text(str(value or "")).replace("-", "_").replace(" ", "_")


def coerce_policy_bool(value: Any) -> bool | None:
    if isinstance(value, bool):
        return value
    raw = normalize_text(str(value or ""))
    if raw in {"true", "yes", "on", "enable", "enabled", "1"}:
        return True
    if raw in {"false", "no", "off", "disable", "disabled", "0"}:
        return False
    return None


def clean_payroll_policy(settings: dict[str, Any] | None, *, company_code: str | None = None) -> dict[str, Any]:
    policy = default_payroll_policy(company_code)
    incoming = settings if isinstance(settings, dict) else {}
    employee_pay_type = normalized_policy_value(incoming.get("employee_pay_type"))
    if employee_pay_type in {"monthly", "hourly", "mixed"}:
        policy["employee_pay_type"] = employee_pay_type
    leave_policy = normalized_policy_value(incoming.get("leave_policy"))
    if leave_policy in {"paid", "unpaid", "review_only"}:
        policy["leave_policy"] = leave_policy
    overtime_policy = normalized_policy_value(incoming.get("overtime_policy"))
    if overtime_policy in {"review_only", "paid", "ignored", "capped"}:
        policy["overtime_policy"] = overtime_policy
    try:
        policy["overtime_cap_minutes"] = max(0, int(float(incoming.get("overtime_cap_minutes") or 0)))
    except Exception:
        pass
    for key in ("absence_deduction_enabled", "late_deduction_enabled", "early_leave_deduction_enabled"):
        coerced = coerce_policy_bool(incoming.get(key))
        if coerced is not None:
            policy[key] = coerced
    try:
        rate = incoming.get("default_hourly_rate_kwd")
        policy["default_hourly_rate_kwd"] = None if rate in (None, "", "null") else max(0.0, float(rate))
    except Exception:
        policy["default_hourly_rate_kwd"] = None
    policy["currency"] = str(
        incoming.get("currency")
        or (company_currency(company_code) if company_code else _company_setup.DEFAULT_CURRENCY)
    ).upper()[:8]
    policy["payment_processing"] = "disabled"
    return policy


def payroll_policy_for_company(company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    settings: dict[str, Any] = {}
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT settings FROM payroll_policies WHERE company_code=%s LIMIT 1", (company,))
            row = cur.fetchone()
            if row and isinstance(row.get("settings"), dict):
                settings.update(row.get("settings") or {})
            cur.execute("SELECT settings FROM company_modules WHERE company_code=%s AND module_key='payroll' LIMIT 1", (company,))
            module_row = cur.fetchone()
            module_settings = module_row.get("settings") if module_row and isinstance(module_row.get("settings"), dict) else {}
            if isinstance(module_settings.get("policy"), dict):
                settings = {**module_settings.get("policy"), **settings}
    return clean_payroll_policy(settings, company_code=company)


def payroll_policy_updates_from_action(action: dict[str, Any]) -> dict[str, Any]:
    updates: dict[str, Any] = {}
    # Structured path (dashboard policy editor): take explicit fields directly,
    # without requiring the free-text NLP triggers the WhatsApp path relies on.
    # Values are still validated/clamped by clean_payroll_policy downstream.
    if action.get("structured_policy"):
        for key in ("employee_pay_type", "leave_policy", "overtime_policy"):
            value = normalized_policy_value(action.get(key))
            if value:
                updates[key] = value
        cap_hours = action.get("overtime_cap_hours")
        if cap_hours not in (None, ""):
            try:
                updates["overtime_cap_minutes"] = max(0, int(float(cap_hours) * 60))
            except Exception:
                pass
        for key in ("absence_deduction_enabled", "late_deduction_enabled", "early_leave_deduction_enabled"):
            coerced = coerce_policy_bool(action.get(key))
            if coerced is not None:
                updates[key] = coerced
        rate = action.get("default_hourly_rate_kwd")
        if rate not in (None, ""):
            try:
                updates["default_hourly_rate_kwd"] = max(0.0, float(rate))
            except Exception:
                pass
        if action.get("currency"):
            updates["currency"] = str(action.get("currency")).upper()[:8]
        return updates
    text = normalize_text(action.get("prompt_text") or action.get("query") or "")
    employee_pay_type = normalized_policy_value(action.get("employee_pay_type"))
    if employee_pay_type in {"monthly", "hourly", "mixed"} and re.search(r"\b(pay type|payroll type|employee type|hourly|monthly)\b", text):
        updates["employee_pay_type"] = employee_pay_type
    elif re.search(r"\bhourly\b", text):
        updates["employee_pay_type"] = "hourly"
    elif re.search(r"\bmonthly\b", text):
        updates["employee_pay_type"] = "monthly"

    overtime_policy = normalized_policy_value(action.get("overtime_policy"))
    if overtime_policy in {"review_only", "paid", "ignored", "capped"} and "overtime" in text:
        updates["overtime_policy"] = overtime_policy
    elif re.search(r"\bovertime\b", text):
        if re.search(r"\breview only|review-only|manual review\b", text):
            updates["overtime_policy"] = "review_only"
        elif re.search(r"\b(ignore|ignored|unpaid|do not pay|don't pay)\b", text):
            updates["overtime_policy"] = "ignored"
        elif re.search(r"\bcap|capped\b", text):
            updates["overtime_policy"] = "capped"
        elif re.search(r"\bpaid|pay\b", text):
            updates["overtime_policy"] = "paid"
    cap_hours = action.get("overtime_cap_hours")
    cap_match = re.search(r"\bovertime\b[\s\S]{0,80}\bcap(?:ped)?\b[\s\S]{0,40}\b(\d+(?:\.\d+)?)\s*(?:h|hr|hrs|hour|hours)\b", text)
    if cap_hours not in (None, "") and re.search(r"\bovertime\b[\s\S]{0,80}\bcap", text):
        try:
            updates["overtime_cap_minutes"] = int(float(cap_hours) * 60)
        except Exception:
            pass
    elif cap_match:
        updates["overtime_cap_minutes"] = int(float(cap_match.group(1)) * 60)

    leave_policy = normalized_policy_value(action.get("leave_policy"))
    if leave_policy in {"paid", "unpaid", "review_only"} and "leave" in text:
        updates["leave_policy"] = leave_policy
    elif re.search(r"\b(leave policy|paid leave|unpaid leave|leave)\b", text):
        if re.search(r"\bunpaid leave|leave unpaid|deduct leave\b", text):
            updates["leave_policy"] = "unpaid"
        elif re.search(r"\bpaid leave|leave paid|pay leave\b", text):
            updates["leave_policy"] = "paid"
        elif re.search(r"\breview\b", text):
            updates["leave_policy"] = "review_only"

    bool_fields = {
        "absence_deduction_enabled": ["absence", "absent"],
        "late_deduction_enabled": ["late"],
        "early_leave_deduction_enabled": ["early leave", "leaving early"],
    }
    for key, terms in bool_fields.items():
        coerced = coerce_policy_bool(action.get(key))
        if coerced is not None and any(term in text for term in terms) and "deduct" in text:
            updates[key] = coerced
            continue
        if any(term in text for term in terms) and "deduct" in text:
            updates[key] = not bool(re.search(r"\b(disable|off|do not|don't|no)\b", text))

    rate = action.get("default_hourly_rate_kwd")
    rate_match = re.search(r"\b(?:hourly rate|rate)\b[\s\S]{0,30}\b(\d+(?:\.\d+)?)\b", text)
    if rate not in (None, "") and re.search(r"\b(hourly rate|rate)\b", text):
        try:
            updates["default_hourly_rate_kwd"] = float(rate)
        except Exception:
            pass
    elif rate_match:
        updates["default_hourly_rate_kwd"] = float(rate_match.group(1))
    return updates


def show_payroll_policy(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    return {"ok": True, "company_code": company, "policy": payroll_policy_for_company(company)}


def set_payroll_policy(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    updates = payroll_policy_updates_from_action(action)
    current = payroll_policy_for_company(company)
    meaningful = {key: value for key, value in updates.items() if key in default_payroll_policy() and current.get(key) != value}
    if not meaningful:
        return {"ok": False, "error": "no_policy_updates", "needs_clarification": True, "action": action, "policy": current}
    new_policy = clean_payroll_policy({**current, **meaningful})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO payroll_policies (company_code, settings, updated_by_phone, updated_at)
                VALUES (%s,%s,%s,now())
                ON CONFLICT (company_code) DO UPDATE SET
                  settings=EXCLUDED.settings,
                  updated_by_phone=EXCLUDED.updated_by_phone,
                  updated_at=now()
                RETURNING *
                """,
                (company, Json(json_safe(new_policy)), digits(created_by_phone)),
            )
            row = dict(cur.fetchone())
            cur.execute(
                """
                INSERT INTO payroll_policy_events (company_code, event_type, payload, created_by_phone)
                VALUES (%s,'policy_updated',%s,%s)
                """,
                (company, Json({"previous": current, "updates": meaningful, "policy": new_policy, "action": action}), digits(created_by_phone)),
            )
        conn.commit()
    return {"ok": True, "company_code": company, "policy": json_safe(new_policy), "updates": json_safe(meaningful), "row": json_safe(row)}


def payroll_preview_totals(preview_rows: list[dict[str, Any]]) -> dict[str, Any]:
    amount_values = [row.get("estimated_amount_kwd") for row in preview_rows if row.get("estimated_amount_kwd") is not None]
    status_values = sorted({str(row.get("amount_status") or "") for row in preview_rows if row.get("amount_status")})
    return {
        "row_count": len(preview_rows),
        "payable_minutes": sum(int(row.get("payable_minutes") or 0) for row in preview_rows),
        "deduction_minutes": sum(int(row.get("deduction_minutes") or 0) for row in preview_rows),
        "overtime_review_minutes": sum(int(row.get("overtime_review_minutes") or 0) for row in preview_rows),
        "estimated_amount_kwd": round(sum(float(value) for value in amount_values), 3) if amount_values else None,
        "amount_statuses": status_values,
        "payment_processing": "disabled",
    }


def payroll_preview_from_timesheet(row: dict[str, Any], policy: dict[str, Any]) -> dict[str, Any]:
    worked = int(row.get("worked_minutes") or 0)
    approved_leave = int(row.get("approved_leave_minutes") or 0)
    absent = int(row.get("absent_minutes") or 0)
    late = int(row.get("late_minutes") or 0)
    early = int(row.get("early_leave_minutes") or 0)
    overtime = int(row.get("overtime_minutes") or 0)
    paid_leave = approved_leave if policy.get("leave_policy") == "paid" else 0
    deduction = 0
    flags: list[str] = []
    if policy.get("leave_policy") == "unpaid":
        deduction += approved_leave
        flags.append("unpaid_leave")
    elif policy.get("leave_policy") == "review_only" and approved_leave:
        flags.append("leave_review")
    if policy.get("absence_deduction_enabled"):
        deduction += absent
    elif absent:
        flags.append("absence_no_deduction")
    if policy.get("late_deduction_enabled"):
        deduction += late
    elif late:
        flags.append("late_review")
    if policy.get("early_leave_deduction_enabled"):
        deduction += early
    elif early:
        flags.append("early_leave_review")
    overtime_review = 0
    overtime_capped_minutes = 0
    if policy.get("overtime_policy") == "review_only" and overtime:
        overtime_review = overtime
        flags.append("overtime_review")
    elif policy.get("overtime_policy") == "ignored" and overtime:
        flags.append("overtime_ignored")
    elif policy.get("overtime_policy") == "capped" and overtime:
        cap = int(policy.get("overtime_cap_minutes") or 0)
        if cap and overtime > cap:
            # Pay overtime only up to the cap: the excess must actually be removed
            # from payable minutes, not merely flagged. Before, a "capped" policy
            # still paid every overtime minute -- the cap was cosmetic and money
            # went out uncapped.
            overtime_capped_minutes = overtime - cap
            flags.append("overtime_capped")
    payable = max(0, worked + paid_leave - deduction - overtime_capped_minutes)
    amount = None
    amount_status = "rate_not_configured"
    rate = policy.get("default_hourly_rate_kwd")
    if policy.get("employee_pay_type") == "hourly" and rate is not None:
        amount = round((payable / 60.0) * float(rate), 3)
        amount_status = "estimated"
    elif policy.get("employee_pay_type") == "monthly":
        amount_status = "monthly_salary_not_configured"
    return {
        "timesheet_id": str(row.get("timesheet_id") or ""),
        "employee_key": row.get("employee_key"),
        "employee_name": row.get("employee_name"),
        "employee_phone": row.get("employee_phone"),
        "period": format_shift_date_range(row.get("period_start"), row.get("period_end")),
        "period_start": shift_sheet_cell(row.get("period_start")),
        "period_end": shift_sheet_cell(row.get("period_end")),
        "employee_pay_type": policy.get("employee_pay_type"),
        "scheduled_minutes": int(row.get("scheduled_minutes") or 0),
        "worked_minutes": worked,
        "paid_leave_minutes": paid_leave,
        "deduction_minutes": deduction,
        "payable_minutes": payable,
        "overtime_review_minutes": overtime_review,
        "overtime_capped_minutes": overtime_capped_minutes,
        "estimated_amount_kwd": amount,
        "amount_status": amount_status,
        "policy_flags": flags or ["ready"],
    }


def preview_payroll(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    start_date, end_date = payroll_period_from_action(action)
    scope = org_scope_for_action(action, company)
    employee = resolve_attendance_employee(action, company_code=company, required=False)
    if employee and action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "action": action, "scope": json_safe(scope)}
    if (action.get("subject_name") or action.get("subject_phone")) and not employee:
        return {"ok": False, "error": "employee_not_found", "action": action}
    params: list[Any] = [company, start_date, end_date]
    where = ["pt.company_code=%s", "pt.period_start=%s", "pt.period_end=%s", "pt.status='approved'"]
    if employee:
        where.append("pt.employee_key=%s")
        params.append(employee.get("employee_key"))
    scope_clause, scope_params = employee_scope_sql("pt", scope)
    if scope_clause:
        where.append(scope_clause.removeprefix("AND "))
        params.extend(scope_params)
    with db_connect() as conn:
        with conn.cursor() as cur:
            # Payroll is a money path: it MUST include every approved timesheet for
            # the period, so this read is intentionally uncapped (bounded already by
            # company + period + status='approved', i.e. one row per paid employee).
            # A LIMIT here would silently underpay a large company. The PK tiebreaker
            # keeps ordering deterministic for stable export snapshots.
            cur.execute(
                f"""
                SELECT pt.*
                FROM payroll_timesheets pt
                WHERE {' AND '.join(where)}
                ORDER BY pt.employee_name NULLS LAST, pt.timesheet_id
                """,
                params,
            )
            rows = [dict(row) for row in cur.fetchall()]
    policy = payroll_policy_for_company(company)
    preview_rows = [payroll_preview_from_timesheet(row, policy) for row in rows]
    result = {
        "ok": True,
        "company_code": company,
        "start_date": start_date.isoformat(),
        "end_date": end_date.isoformat(),
        "policy": json_safe(policy),
        "timesheet_count": len(rows),
        "preview_rows": json_safe(preview_rows),
        "employee": json_safe(employee) if employee else None,
        "scope": json_safe(scope),
        "action": action,
    }
    return result


def export_payroll(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    raw_text = str(action.get("prompt_text") or action.get("query") or "")
    if not (action.get("date") or (action.get("start_date") and action.get("end_date")) or text_has_period_signal(raw_text)):
        return {"ok": False, "error": "missing_period", "needs_clarification": True, "action": action}
    preview = preview_payroll(action, company_code=company)
    if not preview.get("ok"):
        return {**preview, "action": action}
    preview_rows = preview.get("preview_rows") if isinstance(preview.get("preview_rows"), list) else []
    if not preview_rows:
        return {
            "ok": False,
            "error": "no_approved_timesheets",
            "needs_clarification": True,
            "company_code": company,
            "start_date": preview.get("start_date"),
            "end_date": preview.get("end_date"),
            "action": action,
        }
    totals = payroll_preview_totals([row for row in preview_rows if isinstance(row, dict)])
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO payroll_exports (
                    company_code, period_start, period_end, status, export_kind, row_count,
                    totals, policy_snapshot, preview_snapshot, source_payload, created_by_phone
                )
                VALUES (%s,%s,%s,'exported','payroll_preview',%s,%s,%s,%s,%s,%s)
                RETURNING *
                """,
                (
                    company,
                    preview.get("start_date"),
                    preview.get("end_date"),
                    int(totals.get("row_count") or 0),
                    Json(json_safe(totals)),
                    Json(json_safe(preview.get("policy") if isinstance(preview.get("policy"), dict) else {})),
                    Json(json_safe(preview_rows)),
                    Json(json_safe({"action": action, "preview": preview})),
                    digits(created_by_phone),
                ),
            )
            export_row = dict(cur.fetchone())
            cur.execute(
                """
                INSERT INTO payroll_export_events (export_id, company_code, event_type, payload, created_by_phone)
                VALUES (%s,%s,'export_created',%s,%s)
                """,
                (export_row.get("export_id"), company, Json(json_safe({"export": export_row, "totals": totals, "action": action})), digits(created_by_phone)),
            )
        conn.commit()
    return {
        "ok": True,
        "company_code": company,
        "export": json_safe(export_row),
        "export_id": str(export_row.get("export_id") or ""),
        "start_date": preview.get("start_date"),
        "end_date": preview.get("end_date"),
        "row_count": int(totals.get("row_count") or 0),
        "totals": json_safe(totals),
        "preview_rows": json_safe(preview_rows),
        "policy": json_safe(preview.get("policy") if isinstance(preview.get("policy"), dict) else {}),
        "action": action,
    }


def list_payroll_exports(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    raw_text = str(action.get("prompt_text") or action.get("query") or "")
    params: list[Any] = [company]
    where = ["company_code=%s"]
    if action.get("date") or (action.get("start_date") and action.get("end_date")) or text_has_period_signal(raw_text):
        start_date, end_date = payroll_period_from_action(action)
        where.append("period_start=%s AND period_end=%s")
        params.extend([start_date, end_date])
    else:
        start_date = end_date = None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT *
                FROM payroll_exports
                WHERE {' AND '.join(where)}
                ORDER BY created_at DESC
                LIMIT 20
                """,
                params,
            )
            rows = [dict(row) for row in cur.fetchall()]
    return {
        "ok": True,
        "company_code": company,
        "start_date": start_date.isoformat() if start_date else "",
        "end_date": end_date.isoformat() if end_date else "",
        "exports": json_safe(rows),
        "count": len(rows),
        "action": action,
    }


LEAVE_ORIGIN_SURFACES = {"whatsapp", "employee_app", "hr_web", "hr_mobile", "assistant", "system"}


def normalize_origin_surface(value: Any, *, default: str = "whatsapp") -> str:
    """Canonical name for the surface a request actually came from.

    Provenance is business truth: a leave request typed into the Employee App
    must not claim it arrived over WhatsApp.
    """
    surface = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "app": "employee_app",
        "employee": "employee_app",
        "employee_mobile": "employee_app",
        "mobile": "employee_app",
        "dashboard": "hr_web",
        "web": "hr_web",
        "operator_mobile": "hr_mobile",
        "hr_app": "hr_mobile",
        "wa": "whatsapp",
    }
    surface = aliases.get(surface, surface)
    return surface if surface in LEAVE_ORIGIN_SURFACES else default


def request_leave(
    action: dict[str, Any],
    *,
    company_code: str | None,
    created_by_phone: str | None,
    origin_surface: str | None = None,
) -> dict[str, Any]:
    company = require_company_code(company_code)
    # Default stays whatsapp so untouched legacy callers keep their existing
    # provenance; every real surface now passes its own value.
    surface = normalize_origin_surface(origin_surface or action.get("origin_surface") or action.get("surface"))
    employee = resolve_leave_employee(action, company_code=company, required=True)
    if not employee:
        return {"ok": False, "error": "employee_not_found", "action": action}
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "employee": json_safe(employee), "action": action}
    if str(employee.get("company_code") or company).upper() != company:
        return {"ok": False, "error": "employee_company_mismatch", "employee": json_safe(employee), "company_code": company}
    start_date, end_date = leave_date_window(action)
    leave_type = _leave_authority.canonicalize_leave_type(
        infer_leave_type(action.get("prompt_text") or action.get("query"), action.get("leave_type"))
    )
    reason = str(action.get("reason") or action.get("prompt_text") or action.get("query") or "").strip()
    wave3 = _leave_w3.leave_workflow_wave3_enabled()
    duration = _leave_w3.parse_duration_from_action(action) if wave3 else {"duration_unit": _leave_w3.DURATION_FULL_DAY}
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_authority.ensure_leave_authority_wave1_schema(cur)
            if wave3:
                _leave_w3.ensure_leave_workflow_wave3_schema(cur)
            settings = _leave_authority.get_leave_authority_settings(cur, company)
            if _leave_authority.leave_authority_applies_to(company, employee):
                life = _leave_authority.resolve_employee_lifecycle_label(
                    cur, company_code=company, employee=employee, as_of=kuwait_today()
                )
                blocked = _leave_authority.lifecycle_gate(label=life, settings=settings, operation="request")
                if blocked:
                    return {**blocked, "employee": json_safe(employee), "action": action}
            else:
                life = "active"

            chargeable_days = Decimal("0")
            chargeable_hours = Decimal("0")
            shift_id = None
            half_portion = None
            start_time = None
            end_time = None
            sensitive_category = str(action.get("sensitive_category") or "").strip() or None
            payroll_handoff: dict[str, Any] = {}
            shift_validation: dict[str, Any] = {}

            if wave3:
                if duration["duration_unit"] != _leave_w3.DURATION_FULL_DAY and start_date != end_date:
                    return {"ok": False, "error": "partial_day_must_be_single_date", "action": action}
                shifts = _leave_w3.effective_shifts_for_day(
                    cur,
                    company_code=company,
                    employee_key=str(employee.get("employee_key")),
                    on_date=start_date,
                    shift_id=str(duration.get("shift_id") or "") or None,
                )
                shift_validation = _leave_w3.validate_partial_against_shifts(
                    duration=duration, shifts=shifts, on_date=start_date
                )
                if not shift_validation.get("ok"):
                    return {
                        "ok": False,
                        "error": shift_validation.get("error") or "shift_validation_failed",
                        "shift_validation": json_safe(shift_validation),
                        "employee": json_safe(employee),
                        "action": action,
                    }
                policy_preview = get_leave_policy(company, leave_type) or {}
                if leave_type == "unpaid":
                    policy_preview = {**policy_preview, "payroll_boundary": True, "weekend_days": policy_preview.get("weekend_days") or ["fri", "sat"]}
                holidays = set()
                if policy_preview.get("exclude_public_holidays", True) and _leave_policy_w2.leave_policy_wave2_enabled():
                    try:
                        holidays = _leave_policy_w2.holiday_dates_for_range(cur, company, start_date, end_date)
                    except Exception:
                        holidays = set()
                charged = _leave_w3.compute_chargeable(
                    start_date=start_date,
                    end_date=end_date,
                    duration=duration,
                    weekend_days=policy_preview.get("weekend_days") or ["fri", "sat"],
                    holiday_dates=holidays,
                    shift_hours=shift_validation.get("shift_hours"),
                    chargeable_hours=shift_validation.get("chargeable_hours"),
                )
                if charged.get("ok") is False:
                    return {"ok": False, "error": charged.get("error"), "employee": json_safe(employee), "action": action}
                chargeable_days = Decimal(str(charged.get("chargeable_days") or 0))
                chargeable_hours = Decimal(str(charged.get("chargeable_hours") or 0))
                shift_id = shift_validation.get("shift_id")
                half_portion = shift_validation.get("half_portion") or duration.get("half_portion")
                start_time = duration.get("start_time")
                end_time = duration.get("end_time")
                overlaps = _leave_w3.find_overlapping_leaves(
                    cur,
                    company_code=company,
                    employee_key=str(employee.get("employee_key")),
                    start_date=start_date,
                    end_date=end_date,
                    duration=duration,
                )
            else:
                cur.execute(
                    """
                    SELECT *
                    FROM leave_requests
                    WHERE company_code=%s
                      AND employee_key=%s
                      AND status IN ('requested','approved','needs_review')
                      AND start_date <= %s
                      AND end_date >= %s
                    ORDER BY requested_at DESC
                    LIMIT 5
                    """,
                    (company, employee.get("employee_key"), end_date, start_date),
                )
                overlaps = [dict(row) for row in cur.fetchall()]
            if overlaps:
                return {"ok": False, "error": "overlapping_leave_exists", "employee": json_safe(employee), "overlaps": json_safe(overlaps)}
            conflicts = leave_shift_conflicts(cur, company=company, employee_key=str(employee.get("employee_key")), start_date=start_date, end_date=end_date)
            if wave3:
                cur.execute(
                    """
                    INSERT INTO leave_requests (
                        company_code, employee_key, employee_phone, employee_name,
                        start_date, end_date, leave_type, status, reason, source_text,
                        requested_by_phone, metadata, row_version,
                        duration_unit, half_portion, start_time, end_time, shift_id,
                        chargeable_days, chargeable_hours, sensitive_category, payroll_handoff
                    )
                    VALUES (%s,%s,%s,%s,%s,%s,%s,'requested',%s,%s,%s,%s,1,
                            %s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb)
                    RETURNING *
                    """,
                    (
                        company,
                        employee.get("employee_key"),
                        digits(employee.get("phone")),
                        employee.get("name"),
                        start_date,
                        end_date,
                        leave_type,
                        reason or None,
                        str(action.get("prompt_text") or action.get("query") or ""),
                        digits(created_by_phone) or digits(employee.get("phone")),
                        Json({
                            "source": surface,
                            "origin_surface": surface,
                            "action": json_safe(action),
                            "shift_conflicts": json_safe(conflicts),
                            "leave_type_canonical": leave_type,
                            "lifecycle_at_request": life,
                            "wave3": True,
                            "shift_validation": json_safe(shift_validation),
                        }),
                        duration["duration_unit"],
                        half_portion,
                        start_time,
                        end_time,
                        shift_id,
                        chargeable_days,
                        chargeable_hours,
                        sensitive_category,
                        Json({}),
                    ),
                )
            else:
                cur.execute(
                    """
                    INSERT INTO leave_requests (
                        company_code, employee_key, employee_phone, employee_name,
                        start_date, end_date, leave_type, status, reason, source_text,
                        requested_by_phone, metadata, row_version
                    )
                    VALUES (%s,%s,%s,%s,%s,%s,%s,'requested',%s,%s,%s,%s,1)
                    RETURNING *
                    """,
                    (
                        company,
                        employee.get("employee_key"),
                        digits(employee.get("phone")),
                        employee.get("name"),
                        start_date,
                        end_date,
                        leave_type,
                        reason or None,
                        str(action.get("prompt_text") or action.get("query") or ""),
                        digits(created_by_phone) or digits(employee.get("phone")),
                        Json({
                            "source": surface,
                            "origin_surface": surface,
                            "action": json_safe(action),
                            "shift_conflicts": json_safe(conflicts),
                            "leave_type_canonical": leave_type,
                            "lifecycle_at_request": life,
                        }),
                    ),
                )
            leave = dict(cur.fetchone())
            if wave3 and leave_type == "unpaid":
                payroll_handoff = _leave_w3.build_unpaid_payroll_handoff(leave)
                if not _leave_w3.assert_handoff_has_no_money(payroll_handoff):
                    return {"ok": False, "error": "unpaid_handoff_contains_money", "action": action}
                cur.execute(
                    "UPDATE leave_requests SET payroll_handoff=%s::jsonb WHERE leave_id=%s RETURNING *",
                    (Json(payroll_handoff), leave.get("leave_id")),
                )
                leave = dict(cur.fetchone() or leave)
            record_leave_event(cur, leave=leave, company_code=company, event_type="requested", payload={"action": action, "leave": leave, "shift_conflicts": conflicts}, created_by_phone=created_by_phone)
            reservation_result: dict[str, Any] = {}
            if leave_balances_enabled() and _leave_policy_w2.leave_policy_wave2_enabled():
                try:
                    _leave_policy_w2.ensure_leave_policy_wave2_schema(cur)
                    policy = get_leave_policy(company, leave_type) or {}
                    if leave_type == "unpaid":
                        policy = {**policy, "payroll_boundary": True}
                    reservation_result = _leave_policy_w2.reserve_leave_balance(
                        cur, company_code=company, leave=leave, policy=policy, actor_phone=created_by_phone
                    )
                except Exception:
                    logger.warning("wave2 leave reservation failed for %s", leave.get("leave_id"), exc_info=True)
                    reservation_result = {"ok": False, "error": "reservation_failed_observe"}
        conn.commit()
    out = {
        "ok": True,
        "leave": json_safe(leave),
        "employee": json_safe(employee),
        "shift_conflicts": json_safe(conflicts),
        "reservation": json_safe(reservation_result) if reservation_result else None,
        **_leave_authority.honesty_balance_flags(),
    }
    if wave3:
        out["duration"] = json_safe(duration)
        out["chargeable_days"] = float(chargeable_days)
        out["chargeable_hours"] = float(chargeable_hours)
        if leave_type == "unpaid":
            out["payroll_handoff"] = json_safe(payroll_handoff)
            out["payroll_monetary_fields_present"] = False
    return out


# --- Leave balances P1 (dark-launched behind WATHEFNI_LEAVE_BALANCES) ---------
#
# Observe-only: accrual + consumption are tracked so we can validate the math
# against reality, but NOTHING here blocks or alters a leave approval. Every
# legal figure lives in the leave_policies rows (seeded once from the editable
# preset below); the runtime logic reads policies only — no legal number is
# baked into behaviour. Enforcement stays OFF until reviewed with legal.

# Seed-only source of default figures. Used solely to populate the editable
# leave_policy_presets / leave_policies tables; NEVER read by runtime accrual or
# consumption logic. legal_reviewed=false; enforcement deferred to a later phase.
