def seed_leave_policy_presets() -> int:
    """Idempotently seed the reference catalog of leave-policy presets. Inert."""
    inserted = 0
    with db_connect() as conn:
        with conn.cursor() as cur:
            for p in _KUWAIT_LEAVE_PRESETS:
                cur.execute(
                    """
                    INSERT INTO leave_policy_presets
                      (preset_key, leave_type, country, days_per_year, accrual_method, eligibility_months,
                       weekend_days, exclude_public_holidays, allow_negative, tiers, legal_reviewed, notes)
                    VALUES (%s,%s,'KW',%s,%s,%s,%s,%s,%s,%s,false,%s)
                    ON CONFLICT (preset_key, leave_type) DO NOTHING
                    """,
                    (_KUWAIT_PRESET_KEY, p["leave_type"], p["days_per_year"], p["accrual_method"], p["eligibility_months"],
                     p["weekend_days"], p["exclude_public_holidays"], p["allow_negative"], Json(p["tiers"]), p["notes"]),
                )
                inserted += cur.rowcount or 0
        conn.commit()
    return inserted


def seed_company_leave_policies(company_code: str) -> int:
    """Clone the preset into per-company leave_policies for the P1 leave types,
    idempotently. enforced=false / legal_reviewed=false — seeded but inert."""
    company = require_company_code(company_code)
    seeded = 0
    with db_connect() as conn:
        with conn.cursor() as cur:
            for p in _KUWAIT_LEAVE_PRESETS:
                if p["leave_type"] not in _LEAVE_P1_TYPES:
                    continue
                cur.execute("SELECT 1 FROM leave_policies WHERE company_code=%s AND leave_type=%s LIMIT 1", (company, p["leave_type"]))
                if cur.fetchone():
                    continue
                cur.execute(
                    """
                    INSERT INTO leave_policies
                      (company_code, leave_type, preset_key, days_per_year, accrual_method, eligibility_months,
                       weekend_days, exclude_public_holidays, allow_negative, tiers, version, enforced, legal_reviewed)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,1,false,false)
                    """,
                    (company, p["leave_type"], _KUWAIT_PRESET_KEY, p["days_per_year"], p["accrual_method"], p["eligibility_months"],
                     p["weekend_days"], p["exclude_public_holidays"], p["allow_negative"], Json(p["tiers"])),
                )
                seeded += cur.rowcount or 0
        conn.commit()
    return seeded


def get_leave_policy(company_code: str, leave_type: str) -> dict[str, Any] | None:
    company = require_company_code(company_code)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM leave_policies WHERE company_code=%s AND leave_type=%s ORDER BY version DESC LIMIT 1",
                (company, leave_type),
            )
            row = cur.fetchone()
            return dict(row) if row else None


def chargeable_leave_days(start_date: Any, end_date: Any, *, weekend_days: Any, holiday_dates: Any) -> Decimal:
    """Pure: chargeable days in [start,end] inclusive, excluding configured weekend
    rest days and public holidays. No DB. No half-day support."""
    return _leave_policy_w2.chargeable_leave_days_kuwait(
        start_date, end_date, weekend_days=weekend_days, holiday_dates=holiday_dates
    )


def recompute_leave_balance(cur: Any, *, company_code: str, employee_key: str, leave_type: str,
                            period_year: int, entitlement_days: Decimal | None = None,
                            can_take_from: Any = None) -> dict[str, Any]:
    """Rebuild the leave_balances rollup for one (employee, type, year) from the
    append-only ledger. Ledger is the source of truth; balances is materialized."""
    if entitlement_days is None:
        policy = get_leave_policy(company_code, leave_type) or {}
        entitlement_days = Decimal(str(policy.get("days_per_year") or 0))
    if _leave_policy_w2.leave_policy_wave2_enabled():
        return _leave_policy_w2.recompute_balance_with_reservations(
            cur,
            company_code=company_code,
            employee_key=employee_key,
            leave_type=leave_type,
            period_year=period_year,
            entitlement_days=entitlement_days,
            can_take_from=can_take_from,
        )
    cur.execute(
        """
        SELECT
          COALESCE(SUM(days) FILTER (WHERE entry_kind='accrual'),0)   AS accrued,
          COALESCE(SUM(days) FILTER (WHERE entry_kind='consume'),0)   AS consumed,
          COALESCE(SUM(days) FILTER (WHERE entry_kind='reversal'),0)  AS reversed,
          COALESCE(SUM(days) FILTER (WHERE entry_kind='adjustment'),0) AS adjusted,
          COALESCE(SUM(days) FILTER (WHERE entry_kind='carryover'),0) AS carried_in
        FROM leave_ledger
        WHERE company_code=%s AND employee_key=%s AND leave_type=%s
          AND (period IS NULL OR left(period,4)=%s)
        """,
        (company_code, employee_key, leave_type, str(period_year)),
    )
    agg = dict(cur.fetchone() or {})
    accrued = Decimal(str(agg.get("accrued") or 0))
    consumed = Decimal(str(agg.get("consumed") or 0))
    reversed_ = Decimal(str(agg.get("reversed") or 0))
    adjusted = Decimal(str(agg.get("adjusted") or 0))
    carried_in = Decimal(str(agg.get("carried_in") or 0))
    net_consumed = consumed - reversed_
    current_balance = carried_in + accrued + adjusted - net_consumed
    cur.execute(
        """
        INSERT INTO leave_balances
          (company_code, employee_key, leave_type, period_year, entitlement_days,
           accrued_to_date, consumed, adjusted, carried_in, current_balance, can_take_from, as_of)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s, now())
        ON CONFLICT (company_code, employee_key, leave_type, period_year) DO UPDATE SET
          entitlement_days=EXCLUDED.entitlement_days,
          accrued_to_date=EXCLUDED.accrued_to_date,
          consumed=EXCLUDED.consumed,
          adjusted=EXCLUDED.adjusted,
          carried_in=EXCLUDED.carried_in,
          current_balance=EXCLUDED.current_balance,
          can_take_from=COALESCE(EXCLUDED.can_take_from, leave_balances.can_take_from),
          as_of=now()
        """,
        (company_code, employee_key, leave_type, period_year, entitlement_days,
         accrued, net_consumed, adjusted, carried_in, current_balance, can_take_from),
    )
    return {
        "leave_type": leave_type,
        "period_year": period_year,
        "entitlement_days": float(entitlement_days),
        "accrued_to_date": float(accrued),
        "consumed": float(net_consumed),
        "current_balance": float(current_balance),
    }


def _leave_eligibility_date(hired_at: Any, eligibility_months: int):
    if not hired_at:
        return None
    base = hired_at.date() if hasattr(hired_at, "date") else hired_at
    if isinstance(base, str):
        try:
            base = date.fromisoformat(base[:10])
        except ValueError:
            return None
    months = int(eligibility_months or 0)
    y = base.year + (base.month - 1 + months) // 12
    m = (base.month - 1 + months) % 12 + 1
    d = min(base.day, 28)
    return date(y, m, d)


def post_leave_accrual_catchup(cur: Any, *, company_code: str, employee: dict[str, Any], policy: dict[str, Any], as_of: date | None = None) -> int:
    """Idempotently post monthly accrual ledger entries for the current calendar
    year, from max(year-start, hire month) through the current month. Pro-rata for
    the hire month. Calendar-year accrual period; 2-decimal day precision."""
    if str(policy.get("accrual_method")) != "monthly_accrual":
        return 0
    days_per_year = Decimal(str(policy.get("days_per_year") or 0))
    if days_per_year <= 0:
        return 0
    today = as_of or kuwait_today()
    employee_key = str(employee.get("employee_key") or "")
    leave_type = str(policy.get("leave_type"))
    monthly = (days_per_year / Decimal("12")).quantize(Decimal("0.01"))
    hired_at = employee.get("hired_at") or employee.get("start_date") or employee.get("hire_date")
    if isinstance(hired_at, str):
        try:
            hired_at = date.fromisoformat(hired_at[:10])
        except ValueError:
            hired_at = None
    elif hasattr(hired_at, "date"):
        hired_at = hired_at.date()
    posted = 0
    for month in range(1, today.month + 1):
        period = f"{today.year}-{month:02d}"
        month_start = date(today.year, month, 1)
        next_month = date(today.year + (1 if month == 12 else 0), 1 if month == 12 else month + 1, 1)
        days_in_month = (next_month - month_start).days
        days_accrued = monthly
        # Pro-rata if hired during this month; skip months entirely before hire.
        if hired_at:
            if hired_at >= next_month:
                continue
            if month_start <= hired_at < next_month:
                worked = (next_month - hired_at).days
                days_accrued = (monthly * Decimal(worked) / Decimal(days_in_month)).quantize(Decimal("0.01"))
        if days_accrued <= 0:
            continue
        cur.execute(
            """
            INSERT INTO leave_ledger (company_code, employee_key, leave_type, entry_kind, days, period, observe_only, reason)
            VALUES (%s,%s,%s,'accrual',%s,%s,true,'monthly accrual')
            ON CONFLICT (company_code, employee_key, leave_type, period) WHERE entry_kind='accrual' DO NOTHING
            """,
            (company_code, employee_key, leave_type, days_accrued, period),
        )
        posted += cur.rowcount or 0
    can_take = _leave_eligibility_date(hired_at, int(policy.get("eligibility_months") or 0))
    recompute_leave_balance(cur, company_code=company_code, employee_key=employee_key, leave_type=leave_type,
                            period_year=today.year, entitlement_days=days_per_year, can_take_from=can_take)
    return posted


def observe_leave_consumption(cur: Any, *, company_code: str, leave: dict[str, Any], kind: str, actor_phone: str | None = None) -> None:
    """Observe-only: post a consume/reversal ledger entry for an approved (or
    undone) leave and recompute the balance. NEVER blocks; wrapped by callers."""
    leave_type = _leave_authority.canonicalize_leave_type(leave.get("leave_type") or "time_off")
    if leave_type not in _leave_authority.LEAVE_LEDGER_TYPES:
        return
    policy = get_leave_policy(company_code, leave_type)
    if not policy:
        return
    leave = {**leave, "leave_type": leave_type}
    if _leave_policy_w2.leave_policy_wave2_enabled():
        if kind == "consume":
            _leave_policy_w2.consume_from_reservation(
                cur, company_code=company_code, leave=leave, policy=policy, actor_phone=actor_phone
            )
        elif kind == "reversal":
            _leave_policy_w2.reverse_consumption(
                cur, company_code=company_code, leave=leave, policy=policy, actor_phone=actor_phone
            )
        return
    start_date = leave.get("start_date")
    end_date = leave.get("end_date")
    holidays = company_public_holiday_dates(cur, company_code, start_date, end_date) if policy.get("exclude_public_holidays") else set()
    days = chargeable_leave_days(start_date, end_date, weekend_days=policy.get("weekend_days"), holiday_dates=holidays)
    if days <= 0:
        return
    start_d = start_date if isinstance(start_date, date) else date.fromisoformat(str(start_date)[:10])
    period = f"{start_d.year}-{start_d.month:02d}"
    cur.execute(
        """
        INSERT INTO leave_ledger (company_code, employee_key, leave_type, entry_kind, days, period, leave_id, observe_only, reason)
        VALUES (%s,%s,%s,%s,%s,%s,%s,true,%s)
        ON CONFLICT (leave_id, entry_kind) WHERE leave_id IS NOT NULL AND entry_kind IN ('consume','reversal') DO NOTHING
        """,
        (company_code, str(leave.get("employee_key") or ""), leave_type, kind, days, period, leave.get("leave_id"), f"observe-only {kind}"),
    )
    recompute_leave_balance(cur, company_code=company_code, employee_key=str(leave.get("employee_key") or ""),
                            leave_type=leave_type, period_year=start_d.year)


def company_public_holiday_dates(cur: Any, company_code: str, start_date: Any, end_date: Any) -> set:
    cur.execute(
        "SELECT holiday_date FROM public_holidays WHERE company_code=%s AND holiday_date BETWEEN %s AND %s",
        (company_code, start_date, end_date),
    )
    return {r["holiday_date"] for r in cur.fetchall()}


def leave_balances_for_employee(company_code: str, employee_key: str, period_year: int | None = None) -> list[dict[str, Any]]:
    """Read-only balance rows for the P1 leave types (flag-gated by callers)."""
    company = require_company_code(company_code)
    year = period_year or kuwait_today().year
    out: list[dict[str, Any]] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            if _leave_policy_w2.leave_policy_wave2_enabled():
                try:
                    _leave_policy_w2.ensure_leave_policy_wave2_schema(cur)
                    conn.commit()
                except Exception:
                    pass
            try:
                cur.execute(
                    """
                    SELECT lb.leave_type, lb.entitlement_days, lb.accrued_to_date, lb.consumed,
                           lb.current_balance, lb.can_take_from, lb.reserved, lp.enforced, lp.legal_reviewed
                    FROM leave_balances lb
                    LEFT JOIN leave_policies lp ON lp.company_code=lb.company_code AND lp.leave_type=lb.leave_type
                    WHERE lb.company_code=%s AND lb.employee_key=%s AND lb.period_year=%s
                    ORDER BY lb.leave_type
                    """,
                    (company, employee_key, year),
                )
            except Exception:
                cur.execute(
                    """
                    SELECT lb.leave_type, lb.entitlement_days, lb.accrued_to_date, lb.consumed,
                           lb.current_balance, lb.can_take_from, lp.enforced, lp.legal_reviewed
                    FROM leave_balances lb
                    LEFT JOIN leave_policies lp ON lp.company_code=lb.company_code AND lp.leave_type=lb.leave_type
                    WHERE lb.company_code=%s AND lb.employee_key=%s AND lb.period_year=%s
                    ORDER BY lb.leave_type
                    """,
                    (company, employee_key, year),
                )
            for r in cur.fetchall():
                d = dict(r)
                out.append({
                    "leave_type": d.get("leave_type"),
                    "entitlement_days": float(d.get("entitlement_days") or 0),
                    "accrued_to_date": float(d.get("accrued_to_date") or 0),
                    "consumed": float(d.get("consumed") or 0),
                    "current_balance": float(d.get("current_balance") or 0),
                    "can_take_from": (d.get("can_take_from").isoformat() if hasattr(d.get("can_take_from"), "isoformat") else d.get("can_take_from")),
                    "enforced": False,
                    "legal_reviewed": False,
                    "balances_enforced": False,
                    "observe_only": True,
                    "reserved": float(d.get("reserved") or 0) if "reserved" in d else None,
                    "available": (
                        float(d.get("current_balance") or 0) - float(d.get("reserved") or 0)
                        if "reserved" in d
                        else None
                    ),
                })
    return out


def run_leave_accrual_sweep(*, company_code: str | None = None, as_of: date | None = None) -> dict[str, Any]:
    """Post monthly accrual for the current calendar year across employees.
    No-op unless WATHEFNI_LEAVE_BALANCES is on. Idempotent and observe-only —
    accrues into the ledger and recomputes balances; touches nothing user-facing.
    Optionally scoped to one company (used by tests)."""
    if not leave_balances_enabled():
        return {"ok": True, "skipped": True, "reason": "flag_off"}
    today = as_of or kuwait_today()
    companies: list[str] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            if company_code:
                companies = [(company_code or "").upper()]
            else:
                cur.execute("SELECT company_code FROM companies ORDER BY company_code")
                companies = [str(dict(r)["company_code"]) for r in cur.fetchall()]
    summary = {"ok": True, "companies": 0, "employees": 0, "accrual_entries": 0}
    for company in companies:
        if not company_has_module(company, "leave"):
            continue
        try:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    import tenant_control_queue_gate as _tc_qg

                    queued_epoch = _tc_qg.persist_work_epoch(
                        cur,
                        company_code=company,
                        work_kind="leave_accrual",
                        work_ref=f"{company}:{today.isoformat()}",
                        module_key="leave",
                    )
                    allowed, decision = _tc_qg.gate_or_skip(
                        cur,
                        company_code=company,
                        module_key="leave",
                        work_kind="leave_accrual",
                        work_ref=f"{company}:{today.isoformat()}",
                        queued_epoch=queued_epoch,
                        surface="timers",
                    )
                    conn.commit()
                    if not allowed:
                        continue
        except Exception:
            pass
        policies = [get_leave_policy(company, lt) for lt in _LEAVE_P1_TYPES]
        policies = [p for p in policies if p and str(p.get("accrual_method")) == "monthly_accrual"]
        if not policies:
            continue
        summary["companies"] += 1
        employees = company_employees(company)
        with db_connect() as conn:
            with conn.cursor() as cur:
                for emp in employees:
                    summary["employees"] += 1
                    for policy in policies:
                        try:
                            summary["accrual_entries"] += post_leave_accrual_catchup(cur, company_code=company, employee=emp, policy=policy, as_of=today)
                        except Exception:
                            logger.warning("leave accrual failed for %s/%s", emp.get("employee_key"), policy.get("leave_type"), exc_info=True)
            conn.commit()
    return summary


def approve_leave_request(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None, account_id: str | None = None) -> dict[str, Any]:
    company = require_company_code(company_code)
    # Resolve decidable statuses (requested + needs_review after stale handling)
    leave = resolve_leave_request(action, company_code=company, statuses=("requested", "needs_review"))
    if not leave:
        return {"ok": False, "error": "leave_request_not_found", "action": action}
    denied = _leave_authority.self_decision_denied(
        leave=leave, actor_phone=created_by_phone, action="approve", allow_self_cancel=False
    )
    if denied:
        return {**denied, "leave": json_safe(leave), "action": action}
    synth = _leave_authority.is_leave_synthetic_employee(
        leave, employee_key=str(leave.get("employee_key") or ""), phone=str(leave.get("employee_phone") or "")
    )
    real_denied = _leave_w4.real_decision_denied(
        leave=leave, actor_phone=created_by_phone, is_synthetic_subject=synth
    )
    if real_denied:
        return {**real_denied, "leave": json_safe(leave), "action": action}
    employee = find_employee_by_phone(leave.get("employee_phone"), company_code=company) or find_employee_by_key(leave.get("employee_key"), company_code=company)
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee or {"employee_key": leave.get("employee_key"), "company_code": company}, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "leave": json_safe(leave), "action": action}
    expected_version = _leave_authority.parse_expected_row_version(action)
    if expected_version == -1:
        return {"ok": False, "error": "invalid_expected_row_version", "action": action}
    unpaid_handoff_event = None
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_authority.ensure_leave_authority_wave1_schema(cur)
            settings = _leave_authority.get_leave_authority_settings(cur, company)
            subject = employee or leave
            authority_on = _leave_authority.leave_authority_applies_to(
                company,
                subject,
                employee_key=str(leave.get("employee_key") or ""),
                phone=str(leave.get("employee_phone") or ""),
            )
            # Stale pending: resolve deterministically before approve (synthetic/authority subjects only)
            if (
                authority_on
                and str(leave.get("status")) == "requested"
                and parse_shift_date_value(leave.get("start_date"))
                and parse_shift_date_value(leave.get("start_date")) < kuwait_today()
            ):
                stale_rows = _leave_authority.apply_stale_pending(
                    cur,
                    company_code=company,
                    settings=settings,
                    as_of=kuwait_today(),
                    record_event=record_leave_event,
                    actor_phone=created_by_phone,
                    leave_id=str(leave.get("leave_id")),
                )
                if stale_rows:
                    if leave_balances_enabled() and _leave_policy_w2.leave_policy_wave2_enabled():
                        try:
                            for sr in stale_rows:
                                pol = get_leave_policy(company, _leave_authority.canonicalize_leave_type(sr.get("leave_type"))) or {}
                                leave_row = {**sr, "leave_type": _leave_authority.canonicalize_leave_type(sr.get("leave_type"))}
                                _leave_policy_w2.release_leave_reservation(
                                    cur, company_code=company, leave=leave_row, policy=pol, actor_phone=created_by_phone, reason="expired_stale"
                                )
                        except Exception:
                            logger.warning("wave2 reservation release on stale failed", exc_info=True)
                    return {
                        "ok": False,
                        "error": "leave_stale_pending_resolved",
                        "leave": json_safe(stale_rows[0]),
                        "stale_status": stale_rows[0].get("status"),
                        "action": action,
                        **_leave_authority.honesty_balance_flags(settings),
                    }
            if authority_on:
                life = _leave_authority.resolve_employee_lifecycle_label(
                    cur, company_code=company, employee=subject, as_of=kuwait_today()
                )
                blocked = _leave_authority.lifecycle_gate(label=life, settings=settings, operation="approve")
                if blocked:
                    return {**blocked, "leave": json_safe(leave), "action": action}
            if str(leave.get("status")) == "declined_lifecycle":
                return {"ok": False, "error": "leave_status_not_decidable", "leave": json_safe(leave), "action": action}
            conflicts = leave_shift_conflicts(
                cur,
                company=company,
                employee_key=str(leave.get("employee_key")),
                start_date=leave.get("start_date"),
                end_date=leave.get("end_date"),
            )
            if conflicts and not action.get("allow_shift_conflicts"):
                return {"ok": False, "needs_confirmation": True, "error": "leave_shift_conflicts", "leave": json_safe(leave), "shift_conflicts": json_safe(conflicts)}
            cancelled_for_leave: list[dict[str, Any]] = []
            if (
                conflicts
                and action.get("allow_shift_conflicts")
                and _shifts_authority.shifts_wave1_enabled()
                and (
                    str(action.get("cancel_conflicting_shifts") or "").lower() in {"1", "true", "yes"}
                    or str(action.get("leave_conflict_mode") or "").lower() == "cancel_shift"
                )
            ):
                _shifts_authority.ensure_shifts_authority_wave1_schema(cur)
                for conflict in conflicts:
                    cur.execute(
                        """
                        UPDATE shift_assignments
                        SET status='cancelled', updated_at=now(), row_version=COALESCE(row_version,1)+1
                        WHERE shift_id=%s AND company_code=%s AND status='scheduled'
                        RETURNING *
                        """,
                        (conflict.get("shift_id"), company),
                    )
                    cancelled_row = cur.fetchone()
                    if cancelled_row:
                        cancelled_shift = dict(cancelled_row)
                        cancelled_for_leave.append(cancelled_shift)
                        record_shift_event(
                            cur,
                            shift=cancelled_shift,
                            company_code=company,
                            event_type="cancelled_for_leave",
                            payload={"leave": leave, "shift": cancelled_shift},
                            created_by_phone=created_by_phone,
                        )
            ver_sql, ver_params = _leave_authority.concurrency_clause(expected_version)
            cur.execute(
                f"""
                UPDATE leave_requests
                SET status='approved', decision_note=%s, decided_by_phone=%s, decided_at=now(), updated_at=now(),
                    {_leave_authority.bump_row_version_sql()}
                WHERE leave_id=%s AND company_code=%s AND status IN ('requested','needs_review'){ver_sql}
                RETURNING *
                """,
                (str(action.get("decision_note") or "").strip() or None, digits(created_by_phone), leave.get("leave_id"), company, *ver_params),
            )
            updated_row = cur.fetchone()
            if not updated_row:
                return {"ok": False, "error": "stale_row_version" if expected_version is not None else "leave_request_not_found", "action": action}
            updated = dict(updated_row)
            # Map legacy aliases at runtime only — do not rewrite stored leave_type history.
            canonical_type = _leave_authority.canonicalize_leave_type(updated.get("leave_type"))
            cur.execute(
                "UPDATE leave_requests SET metadata = COALESCE(metadata, '{}'::jsonb) || %s WHERE leave_id=%s AND company_code=%s RETURNING *",
                (Json({"leave_type_canonical": canonical_type}), updated.get("leave_id"), company),
            )
            updated = dict(cur.fetchone() or updated)
            record_leave_event(
                cur,
                leave=updated,
                company_code=company,
                event_type="approved",
                payload={
                    "action": action,
                    "leave": updated,
                    "shift_conflicts": conflicts,
                    "cancelled_shifts_for_leave": cancelled_for_leave,
                    "leave_type_canonical": canonical_type,
                },
                created_by_phone=created_by_phone,
            )
            attendance_updates = apply_leave_attendance_effect(cur, company=company, leave=updated, created_by_phone=created_by_phone)
            payroll_invalidated = invalidate_provisional_timesheets(
                cur,
                company_code=company,
                employee_key=str(updated.get("employee_key") or ""),
                start_date=parse_shift_date_value(updated.get("start_date")) or kuwait_today(),
                end_date=parse_shift_date_value(updated.get("end_date")) or kuwait_today(),
                reason="leave_approved",
                created_by_phone=created_by_phone,
                leave_id=str(updated.get("leave_id") or ""),
            )
            if leave_balances_enabled():
                try:
                    observe_leave_consumption(cur, company_code=company, leave=updated, kind="consume", actor_phone=created_by_phone)
                except Exception:
                    logger.warning("observe-only leave consumption failed for %s", updated.get("leave_id"), exc_info=True)
            unpaid_handoff_event = None
            if _leave_w3.leave_workflow_wave3_enabled() and canonical_type == "unpaid":
                _leave_w3.ensure_leave_workflow_wave3_schema(cur)
                handoff = updated.get("payroll_handoff") if isinstance(updated.get("payroll_handoff"), dict) else {}
                if not handoff:
                    handoff = _leave_w3.build_unpaid_payroll_handoff(updated)
                if not _leave_w3.assert_handoff_has_no_money(handoff):
                    return {"ok": False, "error": "unpaid_handoff_contains_money", "leave": json_safe(updated), "action": action}
                unpaid_handoff_event = _leave_w3.record_payroll_handoff(
                    cur, company_code=company, leave=updated, handoff=handoff
                )
                record_leave_event(
                    cur,
                    leave=updated,
                    company_code=company,
                    event_type="payroll_handoff",
                    payload={"handoff": handoff, "monetary_fields_present": False},
                    created_by_phone=created_by_phone,
                )
        conn.commit()
    employee = find_employee_by_phone(updated.get("employee_phone"), company_code=company) or find_employee_by_key(updated.get("employee_key"), company_code=company)
    notification = notify_employee_leave_decision(employee or updated, updated, "approved", account_id=account_id) if employee else {"ok": False, "skipped": True, "reason": "employee_not_found"}
    out = {
        "ok": True,
        "leave": json_safe(updated),
        "shift_conflicts": json_safe(conflicts),
        "attendance_updates": json_safe(attendance_updates),
        "payroll_invalidated": json_safe(payroll_invalidated),
        "payroll_impact": "recalculation_required",
        "employee_notification": json_safe(notification),
        **_leave_authority.honesty_balance_flags(),
    }
    if unpaid_handoff_event is not None:
        out["payroll_handoff"] = json_safe(unpaid_handoff_event.get("classification") if isinstance(unpaid_handoff_event, dict) else unpaid_handoff_event)
        out["payroll_monetary_fields_present"] = bool(
            unpaid_handoff_event.get("monetary_fields_present") if isinstance(unpaid_handoff_event, dict) else False
        )
    return out


def reject_leave_request(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None, account_id: str | None = None) -> dict[str, Any]:
    company = require_company_code(company_code)
    reject_statuses = ("requested", "needs_review", "needs_info") if _leave_w3.leave_workflow_wave3_enabled() else ("requested", "needs_review")
    leave = resolve_leave_request(action, company_code=company, statuses=reject_statuses)
    if not leave:
        return {"ok": False, "error": "leave_request_not_found", "action": action}
    denied = _leave_authority.self_decision_denied(
        leave=leave, actor_phone=created_by_phone, action="reject", allow_self_cancel=False
    )
    if denied:
        return {**denied, "leave": json_safe(leave), "action": action}
    synth = _leave_authority.is_leave_synthetic_employee(
        leave, employee_key=str(leave.get("employee_key") or ""), phone=str(leave.get("employee_phone") or "")
    )
    real_denied = _leave_w4.real_decision_denied(
        leave=leave, actor_phone=created_by_phone, is_synthetic_subject=synth
    )
    if real_denied:
        return {**real_denied, "leave": json_safe(leave), "action": action}
    employee = find_employee_by_phone(leave.get("employee_phone"), company_code=company) or find_employee_by_key(leave.get("employee_key"), company_code=company)
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee or {"employee_key": leave.get("employee_key"), "company_code": company}, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "leave": json_safe(leave), "action": action}
    expected_version = _leave_authority.parse_expected_row_version(action)
    if expected_version == -1:
        return {"ok": False, "error": "invalid_expected_row_version", "action": action}
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_authority.ensure_leave_authority_wave1_schema(cur)
            ver_sql, ver_params = _leave_authority.concurrency_clause(expected_version)
            status_sql = "('requested','needs_review','needs_info')" if _leave_w3.leave_workflow_wave3_enabled() else "('requested','needs_review')"
            cur.execute(
                f"""
                UPDATE leave_requests
                SET status='rejected', decision_note=%s, decided_by_phone=%s, decided_at=now(), updated_at=now(),
                    {_leave_authority.bump_row_version_sql()}
                WHERE leave_id=%s AND company_code=%s AND status IN {status_sql}{ver_sql}
                RETURNING *
                """,
                (str(action.get("decision_note") or "").strip() or None, digits(created_by_phone), leave.get("leave_id"), company, *ver_params),
            )
            updated_row = cur.fetchone()
            if not updated_row:
                return {"ok": False, "error": "stale_row_version" if expected_version is not None else "leave_request_not_found", "action": action}
            updated = dict(updated_row)
            record_leave_event(cur, leave=updated, company_code=company, event_type="rejected", payload={"action": action, "leave": updated}, created_by_phone=created_by_phone)
            if leave_balances_enabled() and _leave_policy_w2.leave_policy_wave2_enabled():
                try:
                    policy = get_leave_policy(company, _leave_authority.canonicalize_leave_type(updated.get("leave_type"))) or {}
                    leave_row = {**updated, "leave_type": _leave_authority.canonicalize_leave_type(updated.get("leave_type"))}
                    _leave_policy_w2.release_leave_reservation(
                        cur, company_code=company, leave=leave_row, policy=policy, actor_phone=created_by_phone, reason="rejected"
                    )
                except Exception:
                    logger.warning("wave2 reservation release on reject failed", exc_info=True)
        conn.commit()
    employee = find_employee_by_phone(updated.get("employee_phone"), company_code=company) or find_employee_by_key(updated.get("employee_key"), company_code=company)
    notification = notify_employee_leave_decision(employee or updated, updated, "rejected", account_id=account_id) if employee else {"ok": False, "skipped": True, "reason": "employee_not_found"}
    return {"ok": True, "leave": json_safe(updated), "employee_notification": json_safe(notification), **_leave_authority.honesty_balance_flags()}


def cancel_leave_request(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None, account_id: str | None = None) -> dict[str, Any]:
    company = require_company_code(company_code)
    cancel_statuses = ("requested", "approved", "needs_review", "needs_info") if _leave_w3.leave_workflow_wave3_enabled() else ("requested", "approved", "needs_review")
    leave = resolve_leave_request(action, company_code=company, statuses=cancel_statuses)
    if not leave:
        return {"ok": False, "error": "leave_request_not_found", "action": action}
    is_self = _leave_authority.actor_is_leave_subject(leave, created_by_phone)
    # Self-cancel allowed; cancel-of-others must not be a disguised self-decision with mismatched phones
    denied = _leave_authority.self_decision_denied(
        leave=leave,
        actor_phone=created_by_phone,
        action="cancel",
        allow_self_cancel=True,
    )
    if denied:
        return {**denied, "leave": json_safe(leave), "action": action}
    employee = find_employee_by_phone(leave.get("employee_phone"), company_code=company) or find_employee_by_key(leave.get("employee_key"), company_code=company)
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee or {"employee_key": leave.get("employee_key"), "company_code": company}, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "leave": json_safe(leave), "action": action}
    # Cancel-of-others: when not self, still ban if actor somehow matches after digit normalize (already handled)
    if not is_self and action.get("forbid_self_cancel_only"):
        pass
    expected_version = _leave_authority.parse_expected_row_version(action)
    if expected_version == -1:
        return {"ok": False, "error": "invalid_expected_row_version", "action": action}
    was_approved = str(leave.get("status") or "") == "approved"
    synth = _leave_authority.is_leave_synthetic_employee(
        leave, employee_key=str(leave.get("employee_key") or ""), phone=str(leave.get("employee_phone") or "")
    )
    cancel_policy = _leave_w4.cancel_policy_projection(
        leave,
        actor_phone=created_by_phone,
        is_self=is_self,
        is_synthetic_subject=synth,
        action_enabled=True,
        allow_cancel_started=bool(action.get("allow_cancel_started")),
        as_of=kuwait_today(),
    )
    temporal = str(cancel_policy.get("temporal_state") or "future")
    blocked = cancel_policy.get("cancel_block_reason")
    if blocked:
        response = {
            "ok": False,
            "error": blocked,
            "temporal_state": temporal,
            "leave": json_safe(leave),
            "action": action,
        }
        if blocked == "leave_already_started":
            response["hint"] = "Set allow_cancel_started=true for explicit HR cancel-after-start with audit + balance reversal"
        return response
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_authority.ensure_leave_authority_wave1_schema(cur)
            ver_sql, ver_params = _leave_authority.concurrency_clause(expected_version)
            status_sql = "('requested', 'approved', 'needs_review', 'needs_info')" if _leave_w3.leave_workflow_wave3_enabled() else "('requested', 'approved', 'needs_review')"
            cur.execute(
                f"""
                UPDATE leave_requests
                SET status='cancelled', decided_by_phone=%s, decided_at=now(), updated_at=now(),
                    {_leave_authority.bump_row_version_sql()}
                WHERE leave_id=%s AND company_code=%s AND status IN {status_sql}{ver_sql}
                RETURNING *
                """,
                (digits(created_by_phone), leave.get("leave_id"), company, *ver_params),
            )
            updated_row = cur.fetchone()
            if not updated_row:
                return {"ok": False, "error": "stale_row_version" if expected_version is not None else "leave_request_not_found", "action": action}
            updated = dict(updated_row)
            event_type = "cancelled_after_start" if temporal == "in_progress" else "cancelled"
            record_leave_event(
                cur,
                leave=updated,
                company_code=company,
                event_type=event_type,
                payload={"action": action, "leave": updated, "was_approved": was_approved, "temporal_state": temporal},
                created_by_phone=created_by_phone,
            )
            attendance_reversed: list[dict[str, Any]] = []
            payroll_invalidated: list[dict[str, Any]] = []
            if was_approved:
                attendance_reversed = reverse_leave_derived_attendance(
                    cur, company=company, leave=updated, created_by_phone=created_by_phone
                )
                payroll_invalidated = invalidate_provisional_timesheets(
                    cur,
                    company_code=company,
                    employee_key=str(updated.get("employee_key") or ""),
                    start_date=parse_shift_date_value(updated.get("start_date")) or kuwait_today(),
                    end_date=parse_shift_date_value(updated.get("end_date")) or kuwait_today(),
                    reason="leave_cancelled",
                    created_by_phone=created_by_phone,
                    leave_id=str(updated.get("leave_id") or ""),
                )
            if leave_balances_enabled() and was_approved:
                try:
                    observe_leave_consumption(cur, company_code=company, leave=updated, kind="reversal", actor_phone=created_by_phone)
                except Exception:
                    logger.warning("observe-only leave reversal failed for %s", updated.get("leave_id"), exc_info=True)
            elif leave_balances_enabled() and _leave_policy_w2.leave_policy_wave2_enabled() and not was_approved:
                try:
                    policy = get_leave_policy(company, _leave_authority.canonicalize_leave_type(updated.get("leave_type"))) or {}
                    leave_row = {**updated, "leave_type": _leave_authority.canonicalize_leave_type(updated.get("leave_type"))}
                    _leave_policy_w2.release_leave_reservation(
                        cur, company_code=company, leave=leave_row, policy=policy, actor_phone=created_by_phone, reason="cancelled"
                    )
                except Exception:
                    logger.warning("wave2 reservation release on cancel failed", exc_info=True)
        conn.commit()
    employee = find_employee_by_phone(updated.get("employee_phone"), company_code=company) or find_employee_by_key(updated.get("employee_key"), company_code=company)
    notification = notify_employee_leave_decision(employee or updated, updated, "cancelled", account_id=account_id) if employee else {"ok": False, "skipped": True, "reason": "employee_not_found"}
    return {
        "ok": True,
        "leave": json_safe(updated),
        "attendance_reversed": json_safe(attendance_reversed),
        "payroll_invalidated": json_safe(payroll_invalidated),
        "payroll_impact": "recalculation_required" if was_approved else None,
        "temporal_state": temporal,
        "employee_notification": json_safe(notification),
        **_leave_authority.honesty_balance_flags(),
    }


def withdraw_leave_request(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    """Wave 3: withdraw before decision (requested/needs_info/needs_review) → withdrawn + release reservation."""
    if not _leave_w3.leave_workflow_wave3_enabled():
        return {"ok": False, "error": "leave_workflow_wave3_disabled"}
    company = require_company_code(company_code)
    leave = resolve_leave_request(action, company_code=company, statuses=("requested", "needs_review", "needs_info"))
    if not leave:
        return {"ok": False, "error": "leave_request_not_found", "action": action}
    if str(leave.get("status")) == "approved":
        return {"ok": False, "error": "cannot_withdraw_approved_use_cancel", "leave": json_safe(leave)}
    expected_version = _leave_authority.parse_expected_row_version(action)
    if expected_version == -1:
        return {"ok": False, "error": "invalid_expected_row_version", "action": action}
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_w3.ensure_leave_workflow_wave3_schema(cur)
            ver_sql, ver_params = _leave_authority.concurrency_clause(expected_version)
            cur.execute(
                f"""
                UPDATE leave_requests
                SET status='withdrawn', decided_by_phone=%s, decided_at=now(), updated_at=now(),
                    {_leave_authority.bump_row_version_sql()}
                WHERE leave_id=%s AND company_code=%s AND status IN ('requested','needs_review','needs_info'){ver_sql}
                RETURNING *
                """,
                (digits(created_by_phone), leave.get("leave_id"), company, *ver_params),
            )
            updated_row = cur.fetchone()
            if not updated_row:
                return {"ok": False, "error": "stale_row_version" if expected_version is not None else "leave_request_not_found", "action": action}
            updated = dict(updated_row)
            record_leave_event(cur, leave=updated, company_code=company, event_type="withdrawn", payload={"action": action}, created_by_phone=created_by_phone)
            if leave_balances_enabled() and _leave_policy_w2.leave_policy_wave2_enabled():
                policy = get_leave_policy(company, _leave_authority.canonicalize_leave_type(updated.get("leave_type"))) or {}
                leave_row = {**updated, "leave_type": _leave_authority.canonicalize_leave_type(updated.get("leave_type"))}
                _leave_policy_w2.release_leave_reservation(
                    cur, company_code=company, leave=leave_row, policy=policy, actor_phone=created_by_phone, reason="withdrawn"
                )
        conn.commit()
    return {"ok": True, "leave": json_safe(updated), **_leave_authority.honesty_balance_flags()}


def return_leave_for_info(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    """Wave 3: HR returns request for information (keeps reservation)."""
    if not _leave_w3.leave_workflow_wave3_enabled():
        return {"ok": False, "error": "leave_workflow_wave3_disabled"}
    company = require_company_code(company_code)
    leave = resolve_leave_request(action, company_code=company, statuses=("requested", "needs_review"))
    if not leave:
        return {"ok": False, "error": "leave_request_not_found", "action": action}
    denied = _leave_authority.self_decision_denied(
        leave=leave, actor_phone=created_by_phone, action="return_for_info", allow_self_cancel=False
    )
    if denied:
        return {**denied, "leave": json_safe(leave), "action": action}
    synth = _leave_authority.is_leave_synthetic_employee(
        leave, employee_key=str(leave.get("employee_key") or ""), phone=str(leave.get("employee_phone") or "")
    )
    real_denied = _leave_w4.real_decision_denied(
        leave=leave, actor_phone=created_by_phone, is_synthetic_subject=synth
    )
    if real_denied:
        return {**real_denied, "leave": json_safe(leave), "action": action}
    note = str(action.get("decision_note") or action.get("info_request") or "").strip() or None
    expected_version = _leave_authority.parse_expected_row_version(action)
    if expected_version == -1:
        return {"ok": False, "error": "invalid_expected_row_version", "action": action}
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_w3.ensure_leave_workflow_wave3_schema(cur)
            ver_sql, ver_params = _leave_authority.concurrency_clause(expected_version)
            cur.execute(
                f"""
                UPDATE leave_requests
                SET status='needs_info', decision_note=%s, decided_by_phone=%s, updated_at=now(),
                    {_leave_authority.bump_row_version_sql()}
                WHERE leave_id=%s AND company_code=%s AND status IN ('requested','needs_review'){ver_sql}
                RETURNING *
                """,
                (note, digits(created_by_phone), leave.get("leave_id"), company, *ver_params),
            )
            updated_row = cur.fetchone()
            if not updated_row:
                return {"ok": False, "error": "stale_row_version" if expected_version is not None else "leave_request_not_found", "action": action}
            updated = dict(updated_row)
            record_leave_event(
                cur, leave=updated, company_code=company, event_type="needs_info", payload={"action": action, "info_request": note}, created_by_phone=created_by_phone
            )
        conn.commit()
    return {"ok": True, "leave": json_safe(updated), **_leave_authority.honesty_balance_flags()}


def resubmit_leave_request(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    """Wave 3: resubmit after needs_info → requested."""
    if not _leave_w3.leave_workflow_wave3_enabled():
        return {"ok": False, "error": "leave_workflow_wave3_disabled"}
    company = require_company_code(company_code)
    leave = resolve_leave_request(action, company_code=company, statuses=("needs_info",))
    if not leave:
        return {"ok": False, "error": "leave_request_not_found", "action": action}
    reason = str(action.get("reason") or "").strip() or leave.get("reason")
    expected_version = _leave_authority.parse_expected_row_version(action)
    if expected_version == -1:
        return {"ok": False, "error": "invalid_expected_row_version", "action": action}
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_w3.ensure_leave_workflow_wave3_schema(cur)
            ver_sql, ver_params = _leave_authority.concurrency_clause(expected_version)
            cur.execute(
                f"""
                UPDATE leave_requests
                SET status='requested', reason=%s, decision_note=NULL, updated_at=now(),
                    {_leave_authority.bump_row_version_sql()}
                WHERE leave_id=%s AND company_code=%s AND status='needs_info'{ver_sql}
                RETURNING *
                """,
                (reason, leave.get("leave_id"), company, *ver_params),
            )
            updated_row = cur.fetchone()
            if not updated_row:
                return {"ok": False, "error": "stale_row_version" if expected_version is not None else "leave_request_not_found", "action": action}
            updated = dict(updated_row)
            record_leave_event(cur, leave=updated, company_code=company, event_type="resubmitted", payload={"action": action}, created_by_phone=created_by_phone)
        conn.commit()
    return {"ok": True, "leave": json_safe(updated), **_leave_authority.honesty_balance_flags()}


def upload_leave_attachment(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    if not _leave_w3.leave_workflow_wave3_enabled():
        return {"ok": False, "error": "leave_workflow_wave3_disabled"}
    company = require_company_code(company_code)
    leave = resolve_leave_request(
        action, company_code=company, statuses=("requested", "needs_review", "needs_info", "approved")
    )
    if not leave:
        return {"ok": False, "error": "leave_request_not_found", "action": action}
    filename = str(action.get("filename") or "").strip()
    storage_ref = str(action.get("storage_ref") or action.get("file_ref") or "").strip()
    if not filename or not storage_ref:
        return {"ok": False, "error": "filename_and_storage_ref_required"}
    category = str(action.get("category") or "supporting").strip() or "supporting"
    sensitive = bool(action.get("sensitive")) or category.lower() in _leave_w3.SENSITIVE_CATEGORIES
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_w3.ensure_leave_workflow_wave3_schema(cur)
            row = _leave_w3.add_leave_attachment(
                cur,
                company_code=company,
                leave_id=str(leave.get("leave_id")),
                filename=filename,
                storage_ref=storage_ref,
                content_type=str(action.get("content_type") or "application/octet-stream"),
                category=category,
                sensitive=sensitive,
                uploaded_by_phone=digits(created_by_phone),
                sha256=action.get("sha256"),
                replaces_attachment_id=action.get("replaces_attachment_id"),
                provenance={"source": "wave3_upload", "actor": digits(created_by_phone)},
            )
            if sensitive and not leave.get("sensitive_category"):
                cur.execute(
                    "UPDATE leave_requests SET sensitive_category=%s WHERE leave_id=%s",
                    (category if category.lower() in _leave_w3.SENSITIVE_CATEGORIES else "sensitive", leave.get("leave_id")),
                )
        conn.commit()
    return {"ok": True, "attachment": json_safe(row), "leave_id": str(leave.get("leave_id"))}


def reject_leave_attachment(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    if not _leave_w3.leave_workflow_wave3_enabled():
        return {"ok": False, "error": "leave_workflow_wave3_disabled"}
    company = require_company_code(company_code)
    attachment_id = str(action.get("attachment_id") or "").strip()
    if not attachment_id:
        return {"ok": False, "error": "attachment_id_required"}
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_w3.ensure_leave_workflow_wave3_schema(cur)
            result = _leave_w3.reject_leave_attachment(
                cur,
                company_code=company,
                attachment_id=attachment_id,
                actor_phone=digits(created_by_phone),
                reason=str(action.get("reason") or "").strip() or None,
            )
        conn.commit()
    return {**result, "attachment": json_safe(result.get("attachment")) if result.get("attachment") else None}


def list_leave_attachments(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None = None) -> dict[str, Any]:
    if not _leave_w3.leave_workflow_wave3_enabled():
        return {"ok": False, "error": "leave_workflow_wave3_disabled"}
    company = require_company_code(company_code)
    leave = resolve_leave_request(
        action, company_code=company, statuses=("requested", "needs_review", "needs_info", "approved", "rejected", "cancelled", "withdrawn")
    )
    if not leave:
        return {"ok": False, "error": "leave_request_not_found", "action": action}
    # Sensitive docs: mask by default. Allow only for explicit HR privilege, named
    # leave-decision allowlist, or a *restricted* manager whose scope includes the employee.
    # Unrestricted (non-scoped) viewers must not see sensitive evidence by accident.
    is_self = _leave_authority.actor_is_leave_subject(leave, created_by_phone)
    viewer = action.get("viewer_phone") or created_by_phone
    employee = find_employee_by_phone(leave.get("employee_phone"), company_code=company) or {
        "employee_key": leave.get("employee_key"),
        "company_code": company,
    }
    scope = manager_scope_context(viewer, company)
    scoped_manager_ok = bool(viewer) and bool(scope.get("restricted")) and manager_scope_allows_employee(
        employee, company_code=company, viewer_phone=viewer
    )
    allowlisted_ok = bool(viewer) and _leave_w4.actor_allowlisted_for_real_decision(str(viewer))
    allow_sensitive = (not is_self) and (
        bool(action.get("hr_privileged")) or allowlisted_ok or scoped_manager_ok
    )
    if action.get("deny_sensitive"):
        allow_sensitive = False
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_w3.ensure_leave_workflow_wave3_schema(cur)
            rows = _leave_w3.list_leave_attachments(
                cur,
                company_code=company,
                leave_id=str(leave.get("leave_id")),
                viewer_allowed_sensitive=allow_sensitive,
            )
        conn.commit()
    return {
        "ok": True,
        "leave_id": str(leave.get("leave_id")),
        "attachments": json_safe(rows),
        "sensitive_access": allow_sensitive,
    }


def initiate_leave_stale_dual_control(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    """Wave 4: first leg — audited dual control to resolve stale real pending leave."""
    if not _leave_w4.leave_wave4_enabled():
        return {"ok": False, "error": "leave_wave4_disabled"}
    company = require_company_code(company_code)
    leave = resolve_leave_request(action, company_code=company, statuses=("requested", "needs_review"))
    if not leave:
        return {"ok": False, "error": "leave_request_not_found", "action": action}
    synth = _leave_authority.is_leave_synthetic_employee(
        leave, employee_key=str(leave.get("employee_key") or ""), phone=str(leave.get("employee_phone") or "")
    )
    real_denied = _leave_w4.real_decision_denied(
        leave=leave, actor_phone=created_by_phone, is_synthetic_subject=synth
    )
    if real_denied:
        return {**real_denied, "leave": json_safe(leave)}
    start = parse_shift_date_value(leave.get("start_date"))
    if not start or start >= kuwait_today():
        return {"ok": False, "error": "leave_not_stale_pending", "leave": json_safe(leave)}
    kind = str(action.get("action_kind") or "expire_stale").strip()
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_w4.ensure_leave_wave4_schema(cur)
            result = _leave_w4.initiate_stale_dual_control(
                cur,
                company_code=company,
                leave=leave,
                actor_phone=created_by_phone,
                action_kind=kind,
                note=str(action.get("decision_note") or "").strip() or None,
            )
            if result.get("ok"):
                record_leave_event(
                    cur,
                    leave=leave,
                    company_code=company,
                    event_type="dual_control_initiated",
                    payload={"dual": result.get("dual_control"), "action": action},
                    created_by_phone=created_by_phone,
                )
        conn.commit()
    return {**result, "leave": json_safe(leave), **_leave_authority.honesty_balance_flags()}


def confirm_leave_stale_dual_control(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    """Wave 4: second leg — different allowlisted actor confirms; applies expire/reject."""
    if not _leave_w4.leave_wave4_enabled():
        return {"ok": False, "error": "leave_wave4_disabled"}
    company = require_company_code(company_code)
    leave_id = str(action.get("leave_id") or "").strip()
    if not leave_id:
        return {"ok": False, "error": "leave_id_required"}
    leave = leave_request_by_id(leave_id, company_code=company)
    if not leave:
        return {"ok": False, "error": "leave_request_not_found"}
    with db_connect() as conn:
        with conn.cursor() as cur:
            _leave_w4.ensure_leave_wave4_schema(cur)
            confirmed = _leave_w4.confirm_stale_dual_control(
                cur,
                company_code=company,
                leave_id=leave_id,
                actor_phone=created_by_phone,
                dual_action_id=str(action.get("dual_action_id") or "") or None,
            )
            if not confirmed.get("ok"):
                conn.commit()
                return {**confirmed, "leave": json_safe(leave)}
            kind = str(confirmed.get("action_kind") or "expire_stale")
            new_status = "expired_stale" if kind == "expire_stale" else "rejected"
            if kind == "cancel_stale":
                new_status = "cancelled"
            cur.execute(
                f"""
                UPDATE leave_requests
                SET status=%s, decision_note=COALESCE(%s, decision_note), decided_by_phone=%s, decided_at=now(), updated_at=now(),
                    {_leave_authority.bump_row_version_sql()}
                WHERE leave_id=%s AND company_code=%s AND status IN ('requested','needs_review')
                RETURNING *
                """,
                (
                    new_status,
                    str(action.get("decision_note") or "").strip() or f"dual_control:{kind}",
                    digits(created_by_phone),
                    leave_id,
                    company,
                ),
            )
            updated_row = cur.fetchone()
            if not updated_row:
                return {"ok": False, "error": "leave_status_not_decidable", "leave": json_safe(leave)}
            updated = dict(updated_row)
            record_leave_event(
                cur,
                leave=updated,
                company_code=company,
                event_type="dual_control_confirmed",
                payload={"dual": confirmed.get("dual_control"), "new_status": new_status},
                created_by_phone=created_by_phone,
            )
            if leave_balances_enabled() and _leave_policy_w2.leave_policy_wave2_enabled():
                policy = get_leave_policy(company, _leave_authority.canonicalize_leave_type(updated.get("leave_type"))) or {}
                leave_row = {**updated, "leave_type": _leave_authority.canonicalize_leave_type(updated.get("leave_type"))}
                _leave_policy_w2.release_leave_reservation(
                    cur, company_code=company, leave=leave_row, policy=policy, actor_phone=created_by_phone, reason=f"dual_control_{kind}"
                )
        conn.commit()
    return {
        "ok": True,
        "leave": json_safe(updated),
        "dual_control": json_safe(confirmed.get("dual_control")),
        **_leave_authority.honesty_balance_flags(),
    }


def list_leave_requests(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    if action.get("history"):
        # History view uses the explicit window verbatim (the shared leave/shift
        # window clamps the span to ~31 days, which would hide older history).
        start_date = parse_shift_date_value(action.get("start_date")) or (kuwait_today() - timedelta(days=180))
        end_date = parse_shift_date_value(action.get("end_date")) or kuwait_today()
        if end_date < start_date:
            start_date, end_date = end_date, start_date
    else:
        start_date, end_date = leave_date_window(action)
    scope = org_scope_for_action(action, company)
    employee = resolve_leave_employee(action, company_code=company, required=False)
    if employee and action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "action": action, "scope": json_safe(scope)}
    status_filter = normalize_text(action.get("status") or "")
    if not status_filter:
        normalized = normalize_text(action.get("prompt_text") or action.get("query") or "")
        if re.search(r"\b(pending|requested|requests?)\b", normalized):
            status_filter = "requested"
        elif "approved" in normalized or "off" in normalized:
            status_filter = "approved"
    # A request awaiting a decision must never be hidden by the default active
    # window: the ~31-day window is meant for the "upcoming approved" view, but a
    # PENDING request whose leave dates fall outside it is still awaiting HR and
    # must stay in the queue -- otherwise a manager sees "nothing to approve"
    # while real requests sit unactioned. So for status='requested' we drop the
    # date-overlap filter UNLESS the caller actually expressed a date intent in
    # their prompt (e.g. "pending leave next week"); the dashboard passes its
    # default window as start/end params, which must NOT be treated as such an
    # intent. History always uses its own explicit window.
    explicit_date_intent = bool(action.get("date")) or bool(
        re.search(
            r"\b(today|tomorrow|week|month|sunday|monday|tuesday|wednesday|thursday|friday|saturday)\b",
            normalize_text(action.get("prompt_text") or action.get("query") or ""),
        )
    )
    # Pending queue includes needs_review (stale-pending) and needs_info (Wave 3 RFI).
    pending_like = status_filter in {"requested", "pending", "needs_review", "needs_info"}
    apply_date_window = bool(action.get("history")) or not pending_like or explicit_date_intent
    params: list[Any] = [company]
    where = ["lr.company_code=%s"]
    if apply_date_window:
        where.extend(["lr.start_date <= %s", "lr.end_date >= %s"])
        params.extend([end_date, start_date])
    if employee:
        where.append("lr.employee_key=%s")
        params.append(employee.get("employee_key"))
    if status_filter in {"requested", "pending"}:
        where.append("lr.status IN ('requested','needs_review','needs_info')")
    elif status_filter:
        where.append("lr.status=%s")
        params.append(status_filter.replace(" ", "_"))
    scope_clause, scope_params = employee_scope_sql("lr", scope)
    if scope_clause:
        where.append(scope_clause.removeprefix("AND "))
        params.extend(scope_params)
    # Optional knobs (default behavior unchanged for existing callers). History
    # needs recent-first + a higher cap so recent rows aren't truncated on a busy
    # company; the operational pending/upcoming reads keep ascending + 50.
    # A stable tiebreaker (the PK) makes the sort a *total* order so LIMIT/OFFSET
    # pagination is deterministic — without it, rows sharing a start_date/name can
    # shuffle between pages and get duplicated or skipped.
    order_sql = "lr.start_date DESC, lr.employee_name NULLS LAST, lr.leave_id" if normalize_text(action.get("order") or "") == "recent" else "lr.start_date, lr.employee_name NULLS LAST, lr.leave_id"
    # Pagination. Default limit=50 keeps every existing caller identical; the
    # dashboard passes limit/offset to page through a busy queue instead of
    # silently dropping requests past the 50th. COUNT(*) OVER() rides the same
    # scan for an accurate total + has_more without a second query.
    row_limit, offset = _paginate_params(action, default_limit=50, max_limit=500)
    params.extend([row_limit, offset])
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT lr.*,
                  (
                    SELECT COUNT(*)
                    FROM shift_assignments s
                    WHERE s.company_code=lr.company_code
                      AND s.employee_key=lr.employee_key
                      AND s.shift_date BETWEEN lr.start_date AND lr.end_date
                      AND s.status='scheduled'
                  ) AS shift_conflict_count,
                  COUNT(*) OVER() AS _total_count
                FROM leave_requests lr
                WHERE {' AND '.join(where)}
                ORDER BY {order_sql}
                LIMIT %s OFFSET %s
                """,
                params,
            )
            rows = [dict(row) for row in cur.fetchall()]
    total_count = int(rows[0]["_total_count"]) if rows else 0
    for row in rows:
        row.pop("_total_count", None)
    has_more = (offset + len(rows)) < total_count
    return {
        "ok": True,
        "leave_requests": json_safe(rows),
        "count": len(rows),
        "start_date": start_date.isoformat(),
        "end_date": end_date.isoformat(),
        "status_filter": status_filter,
        "employee": json_safe(employee) if employee else None,
        "scope": json_safe(scope),
        "total_count": total_count,
        "limit": row_limit,
        "offset": offset,
        "has_more": has_more,
    }


def employee_has_approved_leave(company_code: str | None, employee_key: str | None, attendance_date: date) -> dict[str, Any] | None:
    if not employee_key:
        return None
    company = require_company_code(company_code)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM leave_requests
                WHERE company_code=%s
                  AND employee_key=%s
                  AND status='approved'
                  AND start_date <= %s
                  AND end_date >= %s
                ORDER BY updated_at DESC
                LIMIT 1
                """,
                (company, employee_key, attendance_date, attendance_date),
            )
            row = cur.fetchone()
            return dict(row) if row else None


# --- Reminder frequency caps + send idempotency (flag-gated) ----------------
# Per-EMPLOYEE, per-reminder-template cooldown windows (hours). Only *repeatable
# reminder* templates appear here; EVENT templates (shift_assigned / shift_cancelled
# / shift_rescheduled, leave decisions, onboarding welcome) are never frequency
# capped — they are protected by idempotency/dedupe instead so an accidental
# repeat never double-messages the employee.
#
# shift_reminder is deliberately ABSENT: its unit is per-SHIFT (already enforced by
# shift_assignments.reminder_sent_at), not per-employee. Two different shifts in one
# window must each still get their single reminder, so a per-employee cap would be
# wrong here.
REMINDER_CAP_HOURS = {
    "onboarding_reminder": 24,
    "compliance_document_required": 24,
    "compliance_document_expiring": 24,
    "payroll_timesheet_ready": 72,
    "attendance_missed_checkin": 24,
}
# Accidental rapid re-fires of the SAME content to the SAME employee collapse
# within this window (idempotency, applies to every proactive send incl. critical).
REMINDER_IDEMPOTENCY_MINUTES = 10


def reminder_caps_enabled() -> bool:
    """Frequency caps + send idempotency. Default ON; the flag is the kill switch
    (set WATHEFNI_REMINDER_CAPS=off to restore the pre-cap per-flow behaviour)."""
    val = (os.environ.get("WATHEFNI_REMINDER_CAPS") or "").strip().lower()
    return val not in {"off", "0", "false", "no"}


def channel_presets_enabled() -> bool:
    """Per-company notification presets (downgrade-only channel policy). Default
    OFF: when the flag is off the outbound ladder behaves exactly as before (every
    channel allowed). Set WATHEFNI_CHANNEL_PRESETS=on to enable; off to roll back."""
    val = (os.environ.get("WATHEFNI_CHANNEL_PRESETS") or "").strip().lower()
    return val in {"on", "1", "true", "yes"}


def company_notification_preset(company_code: str | None) -> str:
    """The company's effective notification preset (frontline | office |
    conservative). Defaults to frontline when unset — visible/overridable by the
    operator in Setup Console, never hidden magic."""
    val = str(get_company_settings(company_code).get("notification_preset") or "").strip().lower()
    return val if val in _outbound_delivery.NOTIFICATION_PRESETS else _outbound_delivery.DEFAULT_NOTIFICATION_PRESET


def reminder_cap_window_hours(template_key: str) -> int | None:
    return REMINDER_CAP_HOURS.get(str(template_key or ""))


def _auto_dedupe_key(*, flow: str, template_key: str, employee_key: str | None, text: str, variables: dict[str, Any] | None) -> str:
    """Stable idempotency key for a proactive send when the caller didn't supply
    one. Identical content to the same employee within a short bucket collapses to
    a single send, so an accidentally repeated CRITICAL event never spams."""
    bucket = int(now_utc().timestamp() // (max(1, REMINDER_IDEMPOTENCY_MINUTES) * 60))
    basis = json.dumps({"t": text or "", "v": variables or {}}, sort_keys=True, default=str)
    digest_hex = hashlib.sha1(basis.encode("utf-8")).hexdigest()[:12]
    return f"auto:{flow}:{template_key}:{employee_key or 'noemp'}:{digest_hex}:{bucket}"


def reminder_cap_throttled(company_code: str, employee_key: str, template_key: str, window_hours: int) -> bool:
    """True if a real (non-throttled) send of this reminder template already went
    to this employee within the cooldown window."""
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT 1 FROM employee_messages
                 WHERE company_code=%s AND employee_key=%s AND template_key=%s
                   AND status <> '{_outbound_delivery.STATUS_THROTTLED}'
                   AND created_at > now() - (%s || ' hours')::interval
                 LIMIT 1
                """,
                (str(company_code or "").upper(), str(employee_key), str(template_key), int(window_hours)),
            )
            return cur.fetchone() is not None


def record_throttled_reminder(*, company_code: str, employee_key: str, flow: str, template_key: str, window_hours: int) -> dict[str, Any]:
    """Low-noise audit row: at most ONE throttled row per employee/template/window
    (collapsed via a window-bucketed dedupe key), so Delivery Issues never fills up
    with a row per skipped reminder. Records intent, never sends anything."""
    company = str(company_code or "").upper()
    bucket = int(now_utc().timestamp() // max(1, int(window_hours) * 3600))
    dedupe = f"cap:{template_key}:{employee_key}:{bucket}"
    entry = _outbound_delivery.catalog_entry(template_key)
    label = entry.get("label") or str(template_key or "").replace("_", " ").strip().capitalize()
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM employee_messages WHERE company_code=%s AND dedupe_key=%s LIMIT 1", (company, dedupe))
            if cur.fetchone():
                return {"recorded": False, "deduped": True}
            cur.execute(
                """
                INSERT INTO employee_messages
                  (company_code, employee_key, flow, template_key, criticality, sensitivity, locale,
                   status, body_preview, dedupe_key, metadata)
                VALUES (%s,%s,%s,%s,%s,%s,'en',%s,%s,%s,%s)
                """,
                (
                    company, str(employee_key), str(flow), str(template_key),
                    entry.get("criticality") or _outbound_delivery.CRITICALITY_STANDARD,
                    entry.get("sensitivity") or _outbound_delivery.SENS_PREVIEW,
                    _outbound_delivery.STATUS_THROTTLED, label, dedupe,
                    Json({"reason": "frequency_cap", "window_hours": int(window_hours)}),
                ),
            )
        conn.commit()
    return {"recorded": True}


# Flow → source HCM module. Unmapped flows still send (safe debt); mapped + disabled
# modules never create a new actionable employee notification.
NOTIFICATION_FLOW_SOURCE_MODULE = {
    "leave_decision": "leave",
    "leave": "leave",
    "performance": "performance",
    "talent": "talent",
    "learning": "learning",
    "benefits": "benefits",
    "employee_relations": "employee_relations",
    "engagement": "engagement",
    "compensation_planning": "comp_planning",
    "workforce_planning": "workforce_planning",
    "shift": "shifts",
    "onboarding": "onboarding",
    "compliance": "compliance",
    "bank": "employee_app",
    "app_activation": "employee_app",
    "payroll": "payroll",
    "attendance": "attendance",
}


def source_module_for_notification_flow(flow: str, template_key: str | None = None) -> str | None:
    key = str(flow or "").strip().lower()
    if key in NOTIFICATION_FLOW_SOURCE_MODULE:
        return NOTIFICATION_FLOW_SOURCE_MODULE[key]
    tk = str(template_key or "").strip().lower()
    for prefix, module in (
        ("leave_", "leave"),
        ("performance_", "performance"),
        ("talent_", "talent"),
        ("learning_", "learning"),
        ("benefits_", "benefits"),
        ("er_", "employee_relations"),
        ("employee_relations_", "employee_relations"),
        ("engagement_", "engagement"),
        ("comp_", "comp_planning"),
        ("compensation_", "comp_planning"),
        ("wfp_", "workforce_planning"),
        ("workforce_", "workforce_planning"),
        ("shift_", "shifts"),
        ("onboarding_", "onboarding"),
        ("compliance_", "compliance"),
        ("bank_", "employee_app"),
        ("app_activation", "employee_app"),
        ("payroll_", "payroll"),
        ("attendance_", "attendance"),
    ):
        if tk.startswith(prefix):
            return module
    return None


def notification_source_module_enabled(company_code: str, flow: str, template_key: str | None = None) -> bool:
    module = source_module_for_notification_flow(flow, template_key)
    if not module:
        return True
    return company_has_module(company_code, module)


def deliver_employee_notification(
    employee: dict[str, Any],
    *,
    flow: str,
    template_key: str,
    text: str | None,
    email_subject: str,
    account_id: str | None = None,
    company_code: str | None = None,
    variables: dict[str, Any] | None = None,
    locale: str | None = None,
    subject_key: str | None = None,
    dedupe_key: str | None = None,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Send an employee-facing notification through the shared outbound delivery
    layer and normalize the result into the legacy notification shape (so callers
    and notification_status_text keep working). Used by the flows that have been
    migrated onto the layer (leave / onboarding / compliance)."""
    company = require_company_code(company_code or employee.get("company_code"))
    if not notification_source_module_enabled(company, flow, template_key):
        suppressed = {
            "ok": False,
            "via": "outbound_layer",
            "delivery_status": "module_disabled",
            "suppressed": True,
            "error": "source_module_disabled",
            "source_module": source_module_for_notification_flow(flow, template_key),
            "channel": None,
            "hr_task_id": None,
            "message": text,
            "employee": json_safe(employee),
        }
        if extra:
            suppressed.update(extra)
        return suppressed
    payload_vars = {"employee_name": employee.get("name") or ""}
    if variables:
        payload_vars.update(variables)

    if reminder_caps_enabled():
        emp_key = employee.get("employee_key")
        # Idempotency for EVERY proactive send (incl. critical events): a stable
        # dedupe key so an accidentally repeated event never double-messages.
        if not dedupe_key:
            dedupe_key = _auto_dedupe_key(flow=flow, template_key=template_key, employee_key=emp_key, text=text, variables=variables)
        # Frequency cap — reminder templates only; event/critical templates are not
        # in REMINDER_CAP_HOURS and so are never throttled (idempotency still applies).
        window = reminder_cap_window_hours(template_key)
        if window and emp_key and reminder_cap_throttled(company, str(emp_key), template_key, window):
            record_throttled_reminder(company_code=company, employee_key=str(emp_key), flow=flow, template_key=template_key, window_hours=window)
            throttled = {
                "ok": False,
                "via": "outbound_layer",
                "delivery_status": _outbound_delivery.STATUS_THROTTLED,
                "channel": None,
                "hr_task_id": None,
                "throttled": True,
                "message": text,
                "employee": json_safe(employee),
            }
            if extra:
                throttled.update(extra)
            return throttled

    result = deliver_to_employee(
        company_code=company,
        flow=flow,
        template_key=template_key,
        employee=employee,
        variables=payload_vars,
        text=text,
        email_subject=email_subject,
        account_id=account_id,
        subject_type="employee",
        subject_key=subject_key or employee.get("employee_key"),
        dedupe_key=dedupe_key,
        locale=locale,
    )
    normalized = {
        "ok": bool(result.get("ok")),
        "via": "outbound_layer",
        "delivery_status": result.get("status"),
        "channel": result.get("channel_used"),
        "hr_task_id": result.get("hr_task_id"),
        "message_id": result.get("message_id"),
        "message": text,
        "employee": json_safe(employee),
    }
    if extra:
        normalized.update(extra)
    return normalized


# --- Push notification channel (Expo) ---------------------------------------
# A new rung in the shared outbound ladder for the Employee App. Mirrors the
# Postmark email trio (config / pure-send / layer-facing wrapper) so push is just
# another provider, never load-bearing: if push isn't configured or the employee
# has no active token, the wrapper returns a soft reason and the ladder falls
# through to WhatsApp/email exactly as today.
_EXPO_PUSH_ENDPOINT = "https://exp.host/--/api/v2/push/send"


def outbound_push_config() -> dict[str, str]:
    return {
        "provider": "expo",
        # Optional Expo access token (enhanced push security). Expo accepts pushes
        # to ExponentPushToken recipients without it, so it stays optional.
        "access_token": (os.environ.get("WATHEFNI_EXPO_ACCESS_TOKEN") or "").strip(),
    }


def outbound_push_available() -> bool:
    """Push is 'available' only when the channel flag is on. No mandatory secret
    (Expo's push endpoint accepts ExponentPushToken recipients), so this gates on
    the dark-launch flag alone — the recipient-token check happens per-send."""
    return push_notifications_enabled()


def active_push_tokens_for(company_code: str, employee_key: str) -> list[str]:
    company = require_company_code(company_code)
    out: list[str] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT push_token FROM employee_push_tokens
                WHERE company_code=%s AND employee_key=%s AND active IS TRUE
                ORDER BY last_seen_at DESC NULLS LAST
                """,
                (company, str(employee_key)),
            )
            for row in cur.fetchall():
                tok = str(row.get("push_token") or "").strip()
                if tok:
                    out.append(tok)
    return out


def _deactivate_push_tokens(company_code: str, tokens: list[str], *, reason: str) -> None:
    if not tokens:
        return
    company = require_company_code(company_code)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE employee_push_tokens SET active=FALSE, last_error=%s, updated_at=now() WHERE company_code=%s AND push_token = ANY(%s)",
                (reason[:200], company, tokens),
            )
        conn.commit()


def send_push_via_expo(
    tokens: list[str],
    *,
    title: str,
    body: str,
    data: dict[str, Any] | None = None,
    sound: str | None = "wathefni_default.wav",
    channel_id: str | None = "wathefni_default_v2",
    badge: int | None = None,
    collapse_id: str | None = None,
    interruption_level: str | None = None,
    priority: str | None = None,
) -> dict[str, Any]:
    """Pure HTTP send to Expo's push API. Never raises; returns a normalized result
    including any tokens Expo reports as unregistered so the caller can deactivate
    them. Mirrors send_email_via_postmark's defensive shape."""
    valid = [t for t in tokens if str(t or "").strip()]
    if not valid:
        return {"ok": False, "provider": "expo", "error": "push_token_missing", "invalid_tokens": []}
    cfg = outbound_push_config()
    messages = []
    for t in valid:
        msg: dict[str, Any] = {
            "to": t,
            "title": title,
            "body": body,
            "data": data or {},
        }
        if sound:
            # Custom Wathefni default sound (bundled as wathefni_default.wav).
            # iOS uses the filename with extension; Android 8+ plays the channel sound
            # (channelId wathefni_default_v2 — bumped when WAV content changes).
            msg["sound"] = sound
        if channel_id:
            msg["channelId"] = channel_id
        if badge is not None:
            msg["badge"] = int(badge)
        if collapse_id:
            msg["collapseId"] = str(collapse_id)[:64]
        if interruption_level:
            msg["interruptionLevel"] = interruption_level
        if priority:
            msg["priority"] = priority
        messages.append(msg)
    payload = json.dumps(messages).encode("utf-8")
    headers = {"Content-Type": "application/json", "Accept": "application/json"}
    if cfg.get("access_token"):
        headers["Authorization"] = f"Bearer {cfg['access_token']}"
    try:
        req = urllib.request.Request(_EXPO_PUSH_ENDPOINT, data=payload, headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=15) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
        parsed = json.loads(raw) if raw else {}
    except urllib.error.HTTPError as exc:
        return {"ok": False, "provider": "expo", "error": f"http_{exc.code}", "invalid_tokens": []}
    except Exception as exc:
        return {"ok": False, "provider": "expo", "error": f"push_network_error:{type(exc).__name__}", "invalid_tokens": []}

    receipts = parsed.get("data") if isinstance(parsed, dict) else None
    invalid: list[str] = []
    delivered = 0
    if isinstance(receipts, list):
        for tok, receipt in zip(valid, receipts):
            if not isinstance(receipt, dict):
                continue
            if str(receipt.get("status")) == "ok":
                delivered += 1
            else:
                detail = receipt.get("details") if isinstance(receipt.get("details"), dict) else {}
                if str(detail.get("error")) == "DeviceNotRegistered":
                    invalid.append(tok)
    return {"ok": delivered > 0, "provider": "expo", "delivered": delivered, "invalid_tokens": invalid, "error": None if delivered > 0 else "push_no_delivery"}


# Default in-app paths for known outbound flows. The Employee App resolves these
# through its strict Phase 1 route registry + entitlements — push never invents
# authority; it only hints at a destination the client may open or calmly refuse.
_FLOW_PUSH_DEFAULT_PATHS: dict[str, str] = {
    "payroll": "/payslips",
    "leave": "/(tabs)/leave",
    "leave_decision": "/(tabs)/leave",
    "shift": "/(tabs)/schedule",
    "shifts": "/(tabs)/schedule",
    "attendance": "/(tabs)/schedule",
    "onboarding": "/onboarding",
    "compliance": "/documents",
    "documents": "/documents",
    "bank": "/bank",
}


def build_employee_push_data(
    flow: str,
    *,
    deep_link: dict[str, Any] | None = None,
    variables: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Compose Expo push `data` for Employee App tap follow-through.

    Prefers an explicit deep_link (or deep_link/path/payslip_id in variables), then
    a flow-default path. Paths are hints only — the mobile registry is authoritative.
    """
    data: dict[str, Any] = {"flow": str(flow or "").strip()}
    vars_in = variables if isinstance(variables, dict) else {}
    link = deep_link if isinstance(deep_link, dict) else None
    if link is None and isinstance(vars_in.get("deep_link"), dict):
        link = vars_in.get("deep_link")  # type: ignore[assignment]
    path = ""
    payslip_id = ""
    if isinstance(link, dict):
        path = str(link.get("path") or "").strip()
        payslip_id = str(link.get("payslip_id") or "").strip()
    if not path:
        path = str(vars_in.get("path") or "").strip()
    if not payslip_id:
        payslip_id = str(vars_in.get("payslip_id") or "").strip()
    if not path:
        path = _FLOW_PUSH_DEFAULT_PATHS.get(str(flow or "").strip().lower(), "")
    if path:
        # Only allow plain in-app hints — reject absolute / external URLs at the source.
        if path.startswith("/") and "://" not in path and ".." not in path:
            data["path"] = path
            deep_out: dict[str, Any] = {"path": path}
            if payslip_id and path.startswith("/payslips"):
                deep_out["payslip_id"] = payslip_id
                data["payslip_id"] = payslip_id
            data["deep_link"] = deep_out
        # else: omit path; client falls back to Inbox via flow/registry
    elif payslip_id:
        data["path"] = "/payslips"
        data["payslip_id"] = payslip_id
        data["deep_link"] = {"path": "/payslips", "payslip_id": payslip_id}
    return data


def send_outbound_push(
    *,
    company_code: str,
    employee_key: str | None,
    title: str,
    body: str,
    flow: str,
    subject_type: str | None = None,
    subject_key: str | None = None,
    account_id: str | None = None,
    message_kind: str | None = None,
    deep_link: dict[str, Any] | None = None,
    variables: dict[str, Any] | None = None,
    template_key: str | None = None,
    locale: str | None = None,
    dedupe_key: str | None = None,
    time_sensitive: bool | None = None,
    badge: int | None = None,
) -> dict[str, Any]:
    """Layer-facing push wrapper: dry-run short-circuit, recipient-token lookup,
    invalid-token cleanup, and best-effort delivery-event logging. Never raises and
    never blocks the ladder — returns a soft reason when push can't be used."""
    company = require_company_code(company_code)
    if not outbound_push_available():
        return {"ok": False, "provider": "expo", "channel": "push", "error": "push_not_configured"}
    if not employee_key:
        return {"ok": False, "provider": "expo", "channel": "push", "error": "push_no_employee"}
    try:
        import employee_push_tray as _push_tray
    except Exception:
        _push_tray = None  # type: ignore
    tmpl = str(template_key or message_kind or flow or "").strip()
    if _push_tray is not None and not _push_tray.push_allowed(flow=flow, template_key=tmpl):
        return {"ok": False, "provider": "expo", "channel": "push", "error": "push_inbox_only_policy"}
    if delivery_is_dry_run():
        return {"ok": True, "provider": "expo", "channel": "push", "dry_run": True}
    tokens = active_push_tokens_for(company, str(employee_key))
    if not tokens:
        return {"ok": False, "provider": "expo", "channel": "push", "error": "push_token_missing"}
    push_data = build_employee_push_data(flow, deep_link=deep_link, variables=variables)
    collapse = None
    interrupt = None
    priority = None
    if _push_tray is not None:
        collapse = _push_tray.collapse_id(
            company_code=company,
            flow=str(flow or ""),
            template_key=tmpl,
            subject_key=str(subject_key or employee_key or ""),
            dedupe_key=dedupe_key,
        )
        interrupt = _push_tray.interruption_level(
            tmpl,
            time_sensitive=time_sensitive,
            variables=variables if isinstance(variables, dict) else None,
        )
        if interrupt == "timeSensitive":
            priority = "high"
    result = send_push_via_expo(
        tokens,
        title=title,
        body=body,
        data=push_data,
        badge=badge,
        collapse_id=collapse,
        interruption_level=interrupt,
        priority=priority,
    )
    if result.get("invalid_tokens"):
        try:
            _deactivate_push_tokens(company, list(result.get("invalid_tokens") or []), reason="DeviceNotRegistered")
        except Exception:
            logger.warning("failed to deactivate stale push tokens for %s", employee_key, exc_info=True)
    try:
        record_outbound_delivery_event(
            channel="push",
            account_id=account_id,
            target_phone=None,
            target_conversation_id=None,
            status="sent" if result.get("ok") else "failed",
            subject_type=subject_type,
            subject_key=subject_key or str(employee_key),
            company_code=company,
            message_kind=message_kind or flow,
            message_text="",
            last_error=result.get("error"),
            payload={
                "flow": flow,
                "provider": "expo",
                "delivered": result.get("delivered", 0),
                "path": push_data.get("path"),
            },
        )
    except Exception:
        logger.warning("failed to record push delivery event for %s", employee_key, exc_info=True)
    return {"ok": bool(result.get("ok")), "provider": "expo", "channel": "push", "error": result.get("error")}


def notify_employee_leave_decision(employee: dict[str, Any], leave: dict[str, Any], decision: str, *, account_id: str | None = None) -> dict[str, Any]:
    start_text = shift_sheet_cell(leave.get("start_date"))
    end_text = shift_sheet_cell(leave.get("end_date"))
    date_text = start_text if start_text == end_text else f"{start_text} to {end_text}"
    if decision == "approved":
        message = f"Your leave request for {date_text} has been approved."
    elif decision == "rejected":
        message = f"Your leave request for {date_text} was not approved."
    else:
        message = f"Your leave request for {date_text} has been {decision}."

    # Phase C: route approve/reject through the shared outbound delivery layer
    # when the flow is enabled. The layer adds the WhatsApp-template -> email ->
    # HR-task fallback ladder, so a closed conversation can no longer make a leave
    # decision silently fail. Everything else (and "cancelled") keeps the existing
    # direct-send behaviour until its own flow is wired.
    if decision in {"approved", "rejected"} and outbound_flow_enabled("leave_decision"):
        return deliver_employee_notification(
            employee,
            flow="leave_decision",
            template_key="leave_request_approved" if decision == "approved" else "leave_request_rejected",
            text=message,
            email_subject="Update on your leave request",
            account_id=account_id,
            company_code=require_company_code(leave.get("company_code") or employee.get("company_code")),
            variables={"start_date": start_text, "end_date": end_text, "date_text": date_text},
            dedupe_key=f"leave_decision:{leave.get('leave_id')}:{decision}",
        )

    return send_custom_employee_message(employee, account_id, message)


def notify_employee_bank_correction(
    employee: dict[str, Any],
    *,
    company_code: str | None = None,
    request_id: str | None = None,
    account_id: str | None = None,
) -> dict[str, Any]:
    """Push + Inbox when HR returns bank details for correction. Never includes IBAN."""
    company = require_company_code(company_code or employee.get("company_code"))
    emp_key = str(employee.get("employee_key") or "").strip()
    if not emp_key:
        return {"ok": False, "error": "employee_key_required"}
    dedupe = f"bank_correction:{request_id or emp_key}"
    message = "Your bank details need a correction. Please open Bank in the OctoHR app."
    return deliver_employee_notification(
        employee,
        flow="bank",
        template_key="bank_correction_required",
        text=message,
        email_subject="Bank details need attention",
        account_id=account_id,
        company_code=company,
        variables={"deep_link": {"path": "/bank"}},
        subject_key=emp_key,
        dedupe_key=dedupe,
    )


def create_shift_assignment_for_employee(action: dict[str, Any], *, employee: dict[str, Any], company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    if not employee or not employee.get("employee_key"):
        return {"ok": False, "error": "employee_not_found", "company_code": company}
    if str(employee.get("company_code") or company).upper() != company:
        return {"ok": False, "error": "employee_company_mismatch", "employee": json_safe(employee), "company_code": company}
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "employee": json_safe(employee), "company_code": company}
    synth = _shifts_subject_is_synthetic(employee)
    denied = _shifts_w3.real_mutation_denied(actor_phone=created_by_phone, is_synthetic_subject=synth, company_code=company)
    if denied:
        return denied
    if _shifts_w3.shifts_wave3_enabled_for_company(company) and not synth:
        reason_denied = _shifts_w3.require_audit_reason(action.get("reason") or action.get("reason_note"))
        if reason_denied:
            return reason_denied
    start_time, end_time, time_error = extract_shift_time_range(action)
    if time_error:
        return {"ok": False, "error": time_error, "employee": json_safe(employee)}
    dates = shift_dates_from_text(action)
    if not dates:
        return {"ok": False, "error": "missing_shift_date", "employee": json_safe(employee)}
    created: list[dict[str, Any]] = []
    conflicts: list[dict[str, Any]] = []
    wave2_warnings: list[dict[str, Any]] = []
    role = str(action.get("role") or "").strip() or None
    location = str(action.get("location") or "").strip() or None
    assignment_type_raw = action.get("assignment_type")
    if assignment_type_raw not in (None, "") and _shifts_authority.normalize_assignment_type(
        assignment_type_raw, reject_unknown=True
    ) is None:
        return {"ok": False, "error": "invalid_assignment_type", "employee": json_safe(employee)}
    assignment_type = _shifts_authority.normalize_assignment_type(assignment_type_raw)
    notes = str(action.get("notes") or "").strip() or None
    source_text = str(action.get("prompt_text") or action.get("query") or "").strip()
    idempotency_key = str(action.get("idempotency_key") or "").strip() or None
    break_minutes = action.get("break_minutes")
    try:
        break_minutes_i = int(break_minutes) if break_minutes is not None and str(break_minutes).strip() != "" else None
    except (TypeError, ValueError):
        return {"ok": False, "error": "invalid_break_minutes", "employee": json_safe(employee)}
    site_key = str(action.get("site_key") or "").strip() or None
    branch_key = str(action.get("branch_key") or "").strip() or None
    team_key = str(action.get("team_key") or "").strip() or None
    position_key = str(action.get("position_key") or "").strip() or None
    ends_next = _shifts_authority.ends_next_day_for(start_time, end_time)
    wave1_subject = _shifts_authority.shifts_authority_applies_to(company, employee)
    # Synthetic-only canary: keep legacy overnight rejection for real employees.
    if ends_next and _shifts_authority.shifts_wave1_enabled() and not wave1_subject:
        return {"ok": False, "error": "invalid_shift_time_range", "employee": json_safe(employee)}
    with db_connect() as conn:
        with conn.cursor() as cur:
            if _shifts_authority.shifts_wave1_enabled():
                _shifts_authority.ensure_shifts_authority_wave1_schema(cur)
                settings = _shifts_authority.get_shift_authority_settings(cur, company)
                # Fail closed: employee must exist in hub for this tenant
                cur.execute(
                    "SELECT 1 FROM employees WHERE company_code=%s AND employee_key=%s LIMIT 1",
                    (company, employee.get("employee_key")),
                )
                if not cur.fetchone():
                    return {"ok": False, "error": "unknown_employee", "employee_key": employee.get("employee_key"), "company_code": company}
                if ends_next and not settings.get("allow_overnight", True):
                    return {"ok": False, "error": "overnight_not_allowed", "employee": json_safe(employee)}
                if idempotency_key:
                    cur.execute(
                        """
                        SELECT * FROM shift_assignments
                        WHERE company_code=%s AND idempotency_key=%s
                        LIMIT 1
                        """,
                        (company, idempotency_key),
                    )
                    existing_idem = cur.fetchone()
                    if existing_idem:
                        row = dict(existing_idem)
                        return {
                            "ok": True,
                            "idempotent": True,
                            "employee": json_safe(employee),
                            "created": json_safe([row]),
                            "conflicts": [],
                            "requested_dates": [d.isoformat() for d in dates],
                            **_shifts_authority.honesty_payload(settings),
                        }
            else:
                settings = {"allow_overnight": False, "leave_conflict_mode": "require_ack"}

            for shift_date in dates[:14]:
                if _shifts_authority.shifts_wave1_enabled() and wave1_subject:
                    life_denied = _shifts_authority.evaluate_assignment_lifecycle(
                        cur,
                        company_code=company,
                        employee=employee,
                        settings=settings,
                        shift_date=shift_date,
                        start_time=start_time,
                        end_time=end_time,
                        ends_next_day=ends_next,
                        operation="create",
                        action=action,
                    )
                    if life_denied:
                        return {**life_denied, "employee": json_safe(employee), "shift_date": shift_date.isoformat()}
                    leaves = _shifts_authority.approved_leave_on_date(
                        cur, company_code=company, employee_key=str(employee["employee_key"]), shift_date=shift_date
                    )
                    leave_denied = _shifts_authority.leave_conflict_denied(
                        mode=str(settings.get("leave_conflict_mode") or "require_ack"),
                        leaves=leaves,
                        action=action,
                    )
                    if leave_denied:
                        return {**leave_denied, "employee": json_safe(employee), "shift_date": shift_date.isoformat()}
                if _shifts_w2_applies(company, employee):
                    _shifts_w2.ensure_shifts_integrity_wave2_schema(cur)
                    integ = _shifts_w2.get_integrity_settings(cur, company)
                    avail_hits = _shifts_w2.approved_unavailability_overlaps(
                        cur,
                        company_code=company,
                        employee_key=str(employee["employee_key"]),
                        shift_date=shift_date,
                        start_time=start_time,
                        end_time=end_time,
                        ends_next_day=ends_next,
                    )
                    avail_denied = _shifts_w2.availability_conflict_denied(
                        mode=str(integ.get("availability_conflict_mode") or "require_ack"),
                        conflicts=avail_hits,
                        action=action,
                    )
                    if avail_denied:
                        return {**avail_denied, "employee": json_safe(employee), "shift_date": shift_date.isoformat()}
                    if avail_hits and str(integ.get("availability_conflict_mode") or "") == "warn":
                        wave2_warnings.append({"kind": "availability", "conflicts": json_safe(avail_hits)})
                    seasonal = _shifts_w2.evaluate_seasonal_policies(
                        cur,
                        company_code=company,
                        shift_date=shift_date,
                        start_time=start_time,
                        end_time=end_time,
                        site_key=site_key,
                        branch_key=branch_key,
                        ends_next_day=ends_next,
                    )
                    if seasonal.get("denied"):
                        return {**seasonal["denied"], "employee": json_safe(employee), "shift_date": shift_date.isoformat()}
                    wave2_warnings.extend(json_safe(list(seasonal.get("warnings") or [])))
                existing = shift_conflicts(
                    cur,
                    company_code=company,
                    employee_key=str(employee["employee_key"]),
                    shift_date=shift_date,
                    start_time=start_time,
                    end_time=end_time,
                    ends_next_day=ends_next,
                )
                if existing:
                    conflicts.extend(existing)
                    continue
                if _shifts_authority.shifts_wave1_enabled():
                    cur.execute(
                        """
                        INSERT INTO shift_assignments (
                            company_code, employee_key, employee_phone, employee_name,
                            shift_date, start_time, end_time, timezone, role, location,
                            notes, source_text, metadata, created_by_phone,
                            ends_next_day, break_minutes, site_key, branch_key, team_key,
                            position_key, idempotency_key, row_version, assignment_type
                        )
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,1,%s)
                        RETURNING *
                        """,
                        (
                            company,
                            employee.get("employee_key"),
                            digits(employee.get("phone")),
                            employee.get("name"),
                            shift_date,
                            start_time,
                            end_time,
                            str(action.get("timezone") or "Asia/Kuwait"),
                            role,
                            location,
                            notes,
                            source_text,
                            Json({
                                "source": "hr_whatsapp",
                                "action": json_safe(action),
                                "shifts_wave1": True,
                                "payroll_money": False,
                            }),
                            digits(created_by_phone),
                            ends_next,
                            break_minutes_i,
                            site_key,
                            branch_key,
                            team_key,
                            position_key,
                            idempotency_key if len(dates) == 1 else (f"{idempotency_key}:{shift_date.isoformat()}" if idempotency_key else None),
                            assignment_type,
                        ),
                    )
                else:
                    cur.execute(
                        """
                        INSERT INTO shift_assignments (
                            company_code, employee_key, employee_phone, employee_name,
                            shift_date, start_time, end_time, timezone, role, location,
                            notes, source_text, metadata, created_by_phone
                        )
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                        RETURNING *
                        """,
                        (
                            company,
                            employee.get("employee_key"),
                            digits(employee.get("phone")),
                            employee.get("name"),
                            shift_date,
                            start_time,
                            end_time,
                            str(action.get("timezone") or "Asia/Kuwait"),
                            role,
                            location,
                            notes,
                            source_text,
                            Json({"source": "hr_whatsapp", "action": json_safe(action)}),
                            digits(created_by_phone),
                        ),
                    )
                shift = dict(cur.fetchone())
                if str(action.get("source_kind") or "") == "template_recurrence":
                    _shifts_templates_w4.ensure_shifts_templates_wave4_schema(cur)
                    _shifts_templates_w4._stamp_provenance(
                        cur,
                        company_code=company,
                        shift_id=str(shift.get("shift_id")),
                        template_id=action.get("template_id"),
                        recurrence_id=action.get("recurrence_id"),
                        occurrence_key=str(action.get("occurrence_key") or ""),
                        generated_from_version=str(action.get("generated_from_version") or ""),
                    )
                    cur.execute(
                        "SELECT * FROM shift_assignments WHERE shift_id=%s",
                        (shift.get("shift_id"),),
                    )
                    refreshed = cur.fetchone()
                    if refreshed:
                        shift = dict(refreshed)
                record_shift_event(cur, shift=shift, company_code=company, event_type="created", payload={"action": action, "shift": shift}, created_by_phone=created_by_phone)
                if _shifts_w2_applies(company, employee):
                    _shifts_w2.record_assignment_version(
                        cur,
                        company_code=company,
                        shift=shift,
                        reason_code=str(action.get("reason_code") or "created"),
                        actor_phone=created_by_phone,
                        reason_note=str(action.get("reason_note") or "") or None,
                    )
                    _shifts_w2.enqueue_shift_reminder(cur, company_code=company, shift=shift)
                created.append(shift)
        conn.commit()
    out = {"ok": bool(created), "employee": json_safe(employee), "created": json_safe(created), "conflicts": json_safe(conflicts), "requested_dates": [d.isoformat() for d in dates]}
    if wave2_warnings:
        out["warnings"] = wave2_warnings
    if _shifts_authority.shifts_wave1_enabled():
        out.update(_shifts_authority.honesty_payload(settings if isinstance(settings, dict) else None))
    if _shifts_w2_applies(company, employee):
        out.update(_shifts_w2.honesty_payload())
    return out


def create_shift_assignment(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    work_items: list[tuple[dict[str, Any], dict[str, Any]]] = []
    unresolved: list[dict[str, Any]] = []
    for assignment_action in assignment_actions_from_bulk(action):
        employees = resolve_shift_employees(assignment_action, company_code=company, required=True)
        if not employees:
            resolution = assignment_action.get("_employee_resolution") if isinstance(assignment_action.get("_employee_resolution"), dict) else {}
            if resolution.get("status") == "ambiguous":
                return {
                    "ok": False,
                    "error": "ambiguous_employee",
                    "needs_clarification": True,
                    "choices": resolution.get("choices") or [],
                    "message": "Multiple employees match. Please choose one.",
                    "action": action,
                }
            unresolved.append({"action": json_safe(assignment_action), "error": "employee_not_found"})
            continue
        for employee in employees:
            work_items.append((assignment_action, employee))
    if not work_items:
        resolution = action.get("_employee_resolution") if isinstance(action.get("_employee_resolution"), dict) else {}
        if resolution.get("status") == "ambiguous":
            return {
                "ok": False,
                "error": "ambiguous_employee",
                "needs_clarification": True,
                "choices": resolution.get("choices") or [],
                "message": "Multiple employees match. Please choose one.",
                "action": action,
            }
        return {"ok": False, "error": "employee_not_found", "action": action, "unresolved": unresolved}
    single_shape = len(work_items) == 1 and not action.get("assignments") and len(resolve_shift_employees(action, company_code=company, required=False)) <= 1
    if single_shape:
        return create_shift_assignment_for_employee(work_items[0][0], employee=work_items[0][1], company_code=company, created_by_phone=created_by_phone)

    results: list[dict[str, Any]] = []
    created: list[dict[str, Any]] = []
    conflicts: list[dict[str, Any]] = []
    for item_action, employee in work_items[:100]:
        result = create_shift_assignment_for_employee(item_action, employee=employee, company_code=company, created_by_phone=created_by_phone)
        results.append(result)
        created.extend(result.get("created") if isinstance(result.get("created"), list) else [])
        conflicts.extend(result.get("conflicts") if isinstance(result.get("conflicts"), list) else [])
    return {
        "ok": any(result.get("ok") for result in results),
        "bulk": True,
        "action": json_safe(action),
        "results": json_safe(results),
        "created": json_safe(created),
        "conflicts": json_safe(conflicts),
        "unresolved": json_safe(unresolved),
        "requested_count": len(work_items),
        "completed_count": sum(1 for result in results if result.get("ok")),
    }


def _paginate_params(action: dict[str, Any], *, default_limit: int, max_limit: int) -> tuple[int, int]:
    """Resolve (limit, offset) for a paginated list read.

    Shared by the post-hire list endpoints so every module paginates identically.
    Callers that pass nothing get `default_limit` and offset 0 — this preserves the
    exact pre-pagination behavior for WhatsApp/Assistant tool calls and workers.
    The dashboard passes `limit`/`offset` (or `page`) to walk through large result
    sets instead of silently truncating at the old hardcoded cap. limit is clamped
    to [1, max_limit]; offset is clamped to >= 0.
    """
    try:
        limit = int(action.get("limit") or default_limit)
    except (TypeError, ValueError):
        limit = default_limit
    limit = max(1, min(limit, max_limit))
    offset = action.get("offset")
    if offset is None and action.get("page") is not None:
        try:
            offset = (max(1, int(action.get("page"))) - 1) * limit
        except (TypeError, ValueError):
            offset = 0
    try:
        offset = int(offset or 0)
    except (TypeError, ValueError):
        offset = 0
    offset = max(0, offset)
    return limit, offset


def list_shifts(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    start_date, end_date = shift_query_window(action)
    scope = org_scope_for_action(action, company)
    employee = resolve_shift_employee(action, required=False)
    if employee and action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "action": action, "scope": json_safe(scope)}
    params: list[Any] = [company, start_date, end_date]
    where = ["s.company_code=%s", "s.shift_date BETWEEN %s AND %s", "s.status='scheduled'"]
    if employee:
        where.append("s.employee_key=%s")
        params.append(employee.get("employee_key"))
    scope_clause, scope_params = employee_scope_sql("s", scope)
    if scope_clause:
        where.append(scope_clause.removeprefix("AND "))
        params.extend(scope_params)
    # Pagination. Default limit=100 keeps every existing caller (WhatsApp/Assistant
    # tools) byte-for-byte identical; the dashboard passes limit/offset to page
    # through a full week without silently dropping shifts past the 100th row.
    # COUNT(*) OVER() rides along on the same scan so we return an accurate total
    # (and has_more) without a second query.
    limit, offset = _paginate_params(action, default_limit=100, max_limit=200)
    params.extend([limit, offset])
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT s.*, COUNT(*) OVER() AS _total_count
                FROM shift_assignments s
                WHERE {' AND '.join(where)}
                ORDER BY s.shift_date, s.start_time, s.employee_name NULLS LAST, s.shift_id
                LIMIT %s OFFSET %s
                """,
                params,
            )
            rows = [dict(row) for row in cur.fetchall()]
    total_count = int(rows[0]["_total_count"]) if rows else 0
    for row in rows:
        row.pop("_total_count", None)
    has_more = (offset + len(rows)) < total_count
    return {
        "ok": True,
        "company_code": company,
        "start_date": start_date.isoformat(),
        "end_date": end_date.isoformat(),
        "employee": json_safe(employee),
        "shifts": json_safe(rows),
        "scope": json_safe(scope),
        "total_count": total_count,
        "limit": limit,
        "offset": offset,
        "has_more": has_more,
    }


def cancel_shift_assignment_for_employee(action: dict[str, Any], *, employee: dict[str, Any], company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "employee": json_safe(employee), "company_code": company}
    start_date, end_date = shift_query_window(action)
    shift_id = str(action.get("shift_id") or "").strip() or None
    idempotency_key = str(action.get("idempotency_key") or "").strip() or None
    with db_connect() as conn:
        with conn.cursor() as cur:
            if _shifts_authority.shifts_wave1_enabled():
                _shifts_authority.ensure_shifts_authority_wave1_schema(cur)
            if shift_id:
                cur.execute(
                    """
                    SELECT * FROM shift_assignments
                    WHERE company_code=%s AND shift_id=%s AND employee_key=%s
                    LIMIT 1
                    """,
                    (company, shift_id, employee.get("employee_key")),
                )
                existing = cur.fetchone()
                if existing and str(dict(existing).get("status")) == "cancelled":
                    row = dict(existing)
                    return {
                        "ok": True,
                        "idempotent": True,
                        "employee": json_safe(employee),
                        "cancelled": json_safe([row]),
                        "start_date": start_date.isoformat(),
                        "end_date": end_date.isoformat(),
                    }
                if _shifts_authority.shifts_wave1_enabled():
                    cur.execute(
                        """
                        UPDATE shift_assignments
                        SET status='cancelled', updated_at=now(), row_version=COALESCE(row_version,1)+1
                        WHERE company_code=%s AND shift_id=%s AND employee_key=%s AND status='scheduled'
                        RETURNING *
                        """,
                        (company, shift_id, employee.get("employee_key")),
                    )
                else:
                    cur.execute(
                        """
                        UPDATE shift_assignments
                        SET status='cancelled', updated_at=now()
                        WHERE company_code=%s AND shift_id=%s AND employee_key=%s AND status='scheduled'
                        RETURNING *
                        """,
                        (company, shift_id, employee.get("employee_key")),
                    )
                rows = [dict(row) for row in cur.fetchall()]
            else:
                cur.execute(
                    """
                    UPDATE shift_assignments
                    SET status='cancelled', updated_at=now()
                    WHERE company_code=%s
                      AND employee_key=%s
                      AND shift_date BETWEEN %s AND %s
                      AND status='scheduled'
                    RETURNING *
                    """,
                    (company, employee.get("employee_key"), start_date, end_date),
                )
                rows = [dict(row) for row in cur.fetchall()]
            for shift in rows:
                record_shift_event(
                    cur,
                    shift=shift,
                    company_code=company,
                    event_type="cancelled",
                    payload={"action": action, "shift": shift, "idempotency_key": idempotency_key},
                    created_by_phone=created_by_phone,
                )
                if _shifts_w2_applies(company, shift):
                    _shifts_w2.record_assignment_version(
                        cur,
                        company_code=company,
                        shift=shift,
                        reason_code=str(action.get("reason_code") or "cancelled"),
                        actor_phone=created_by_phone,
                    )
                    _shifts_w2.cancel_pending_reminders_for_shift(cur, company_code=company, shift_id=str(shift.get("shift_id")))
        conn.commit()
    return {"ok": bool(rows), "employee": json_safe(employee), "cancelled": json_safe(rows), "start_date": start_date.isoformat(), "end_date": end_date.isoformat()}


def cancel_shift_assignment(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    work_items: list[tuple[dict[str, Any], dict[str, Any]]] = []
    unresolved: list[dict[str, Any]] = []
    for assignment_action in assignment_actions_from_bulk(action):
        employees = resolve_shift_employees(assignment_action, company_code=company, required=True)
        if not employees:
            unresolved.append({"action": json_safe(assignment_action), "error": "employee_not_found"})
            continue
        for employee in employees:
            work_items.append((assignment_action, employee))
    if not work_items:
        return {"ok": False, "error": "employee_not_found", "action": action, "unresolved": unresolved}
    single_shape = len(work_items) == 1 and not action.get("assignments") and len(resolve_shift_employees(action, company_code=company, required=False)) <= 1
    if single_shape:
        return cancel_shift_assignment_for_employee(work_items[0][0], employee=work_items[0][1], company_code=company, created_by_phone=created_by_phone)

    results: list[dict[str, Any]] = []
    cancelled: list[dict[str, Any]] = []
    for item_action, employee in work_items[:100]:
        result = cancel_shift_assignment_for_employee(item_action, employee=employee, company_code=company, created_by_phone=created_by_phone)
        results.append(result)
        cancelled.extend(result.get("cancelled") if isinstance(result.get("cancelled"), list) else [])
    return {
        "ok": any(result.get("ok") for result in results),
        "bulk": True,
        "action": json_safe(action),
        "results": json_safe(results),
        "cancelled": json_safe(cancelled),
        "unresolved": json_safe(unresolved),
        "requested_count": len(work_items),
        "completed_count": sum(1 for result in results if result.get("ok")),
    }


def availability_type_from_action(action: dict[str, Any]) -> str:
    raw = normalize_text(action.get("availability_type") or action.get("prompt_text") or action.get("query") or "")
    if re.search(r"\b(prefer|preferred|would rather)\b", raw):
        return "preferred"
    if re.search(r"\b(can work|available|free)\b", raw) and not re.search(r"\b(not available|unavailable|cannot|can't|cant|won't|wont)\b", raw):
        return "available"
    return "unavailable"


def availability_times_from_action(action: dict[str, Any]) -> tuple[time | None, time | None]:
    start_time = parse_shift_time_value(action.get("start_time"))
    end_time = parse_shift_time_value(action.get("end_time"))
    if start_time or end_time:
        return start_time, end_time
    start_time, end_time, time_error = extract_shift_time_range(action)
    if time_error:
        return None, None
    return start_time, end_time


def record_availability_event(cur: Any, *, availability: dict[str, Any] | None, company_code: str, event_type: str, payload: dict[str, Any], created_by_phone: str | None) -> None:
    cur.execute(
        """
        INSERT INTO employee_availability_events (availability_id, company_code, employee_key, event_type, payload, created_by_phone)
        VALUES (%s,%s,%s,%s,%s,%s)
        """,
        (
            availability.get("availability_id") if availability else payload.get("availability_id"),
            company_code,
            availability.get("employee_key") if availability else payload.get("employee_key"),
            event_type,
            Json(json_safe(payload)),
            digits(created_by_phone),
        ),
    )


def request_availability(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None, account_id: str | None = None) -> dict[str, Any]:
    company = require_company_code(company_code)
    employee = resolve_shift_employee(action, required=True, company_code=company)
    if not employee:
        return {"ok": False, "error": "employee_not_found", "action": action}
    if str(employee.get("company_code") or company).upper() != company:
        return {"ok": False, "error": "employee_company_mismatch", "employee": json_safe(employee), "company_code": company}
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "employee": json_safe(employee), "action": action}
    start_date, end_date = shift_query_window(action)
    start_time, end_time = availability_times_from_action(action)
    availability_type = availability_type_from_action(action)
    created_by = digits(created_by_phone)
    employee_phone = digits(employee.get("phone"))
    status = "requested" if created_by and created_by == employee_phone else "approved"
    reason = str(action.get("reason") or action.get("prompt_text") or action.get("query") or "").strip()
    with db_connect() as conn:
        with conn.cursor() as cur:
            conflicts = leave_shift_conflicts(cur, company=company, employee_key=str(employee.get("employee_key")), start_date=start_date, end_date=end_date)
            cur.execute(
                """
                INSERT INTO employee_availability_requests (
                    company_code, employee_key, employee_phone, employee_name,
                    start_date, end_date, start_time, end_time, availability_type,
                    status, reason, source_text, requested_by_phone, decided_by_phone,
                    decided_at, metadata
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,CASE WHEN %s='approved' THEN now() ELSE NULL END,%s)
                RETURNING *
                """,
                (
                    company,
                    employee.get("employee_key"),
                    employee_phone,
                    employee.get("name"),
                    start_date,
                    end_date,
                    start_time,
                    end_time,
                    availability_type,
                    status,
                    reason or None,
                    str(action.get("prompt_text") or action.get("query") or ""),
                    created_by or employee_phone,
                    created_by if status == "approved" else None,
                    status,
                    Json({"source": "whatsapp", "action": json_safe(action), "shift_conflicts": json_safe(conflicts)}),
                ),
            )
            availability = dict(cur.fetchone())
            record_availability_event(cur, availability=availability, company_code=company, event_type=status, payload={"action": action, "availability": availability, "shift_conflicts": conflicts}, created_by_phone=created_by_phone)
        conn.commit()
    hr_notification = {"ok": True, "skipped": True, "reason": "created_by_hr_or_manager"}
    if status == "requested":
        hr_notification = notify_hr_admins(
            company_code=company,
            account_id=account_id,
            message=f"{employee.get('name') or employee_phone} submitted {display_status(availability_type).lower()} availability for {format_shift_date_range(start_date, end_date)}.",
            subject_type="availability",
            subject_key=str(availability.get("availability_id")),
        )
    return {"ok": True, "availability": json_safe(availability), "employee": json_safe(employee), "shift_conflicts": json_safe(conflicts), "hr_notification": json_safe(hr_notification)}


def list_availability(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    start_date, end_date = shift_query_window(action)
    scope = org_scope_for_action(action, company)
    employee = resolve_shift_employee(action, required=False)
    if employee and action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "action": action, "scope": json_safe(scope)}
    status_filter = normalize_text(action.get("status") or "")
    availability_type = normalize_text(action.get("availability_type") or "")
    params: list[Any] = [company, end_date, start_date]
    where = ["ar.company_code=%s", "ar.start_date <= %s", "ar.end_date >= %s"]
    if employee:
        where.append("ar.employee_key=%s")
        params.append(employee.get("employee_key"))
    if status_filter in {"requested", "approved", "rejected", "cancelled"}:
        where.append("ar.status=%s")
        params.append(status_filter)
    if availability_type in {"available", "unavailable", "preferred"}:
        where.append("ar.availability_type=%s")
        params.append(availability_type)
    scope_clause, scope_params = employee_scope_sql("ar", scope)
    if scope_clause:
        where.append(scope_clause.removeprefix("AND "))
        params.extend(scope_params)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT ar.*
                FROM employee_availability_requests ar
                WHERE {' AND '.join(where)}
                ORDER BY ar.start_date, ar.employee_name NULLS LAST, ar.updated_at DESC
                LIMIT 100
                """,
                params,
            )
            rows = [dict(row) for row in cur.fetchall()]
    return {"ok": True, "company_code": company, "start_date": start_date.isoformat(), "end_date": end_date.isoformat(), "availability": json_safe(rows), "count": len(rows), "employee": json_safe(employee) if employee else None, "scope": json_safe(scope)}


def decide_availability(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    """Wave 2: approve/reject availability request (idempotent; audited)."""
    company = require_company_code(company_code)
    availability_id = str(action.get("availability_id") or "").strip()
    if not availability_id:
        return {"ok": False, "error": "missing_availability_id", "action": action}
    decision = str(action.get("decision") or action.get("status") or "").strip().lower()
    if decision not in {"approve", "approved", "reject", "rejected"}:
        return {"ok": False, "error": "invalid_availability_decision", "action": action}
    if not _shifts_w2.shifts_wave2_enabled_for_company(company):
        return {"ok": False, "error": "shifts_wave2_disabled"}
    with db_connect() as conn:
        with conn.cursor() as cur:
            result = _shifts_w2.decide_availability(
                cur,
                company_code=company,
                availability_id=availability_id,
                decision=decision,
                actor_phone=created_by_phone,
                decision_note=str(action.get("decision_note") or "").strip() or None,
                record_event=record_availability_event,
            )
            avail = result.get("availability") or {}
            if result.get("ok") and _shifts_w2.shifts_wave2_synthetic_only() and not _shifts_w2.is_wave2_synthetic_employee(avail):
                conn.rollback()
                return {
                    "ok": False,
                    "error": "shifts_wave2_synthetic_only_gate",
                    "message": "Availability decisions under Wave 2 synthetic-only are limited to synthetic subjects.",
                }
        conn.commit()
    if result.get("availability"):
        result = {**result, "availability": json_safe(result.get("availability"))}
    return result


def approve_availability(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    return decide_availability({**action, "decision": "approved"}, company_code=company_code, created_by_phone=created_by_phone)


def reject_availability(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    return decide_availability({**action, "decision": "rejected"}, company_code=company_code, created_by_phone=created_by_phone)


def record_shift_swap_event(cur: Any, *, swap: dict[str, Any] | None, company_code: str, event_type: str, payload: dict[str, Any], created_by_phone: str | None) -> None:
    cur.execute(
        """
        INSERT INTO shift_swap_events (swap_id, company_code, employee_key, event_type, payload, created_by_phone)
        VALUES (%s,%s,%s,%s,%s,%s)
        """,
        (
            swap.get("swap_id") if swap else payload.get("swap_id"),
            company_code,
            swap.get("requester_employee_key") if swap else payload.get("employee_key"),
            event_type,
            Json(json_safe(payload)),
            digits(created_by_phone),
        ),
    )


def shift_by_id(shift_id: str | None, *, company_code: str | None = None) -> dict[str, Any] | None:
    if not shift_id:
        return None
    company = resolved_company_scope(company_code)
    with db_connect() as conn:
        with conn.cursor() as cur:
            if company:
                cur.execute(
                    "SELECT * FROM shift_assignments WHERE shift_id=%s AND company_code=%s LIMIT 1",
                    (shift_id, company),
                )
            else:
                # Fail closed for cross-tenant probes when company is known elsewhere;
                # unscoped reads remain only for legacy harnesses that pass no company.
                cur.execute("SELECT * FROM shift_assignments WHERE shift_id=%s LIMIT 1", (shift_id,))
            row = cur.fetchone()
            return dict(row) if row else None


def active_shift_for_swap(employee: dict[str, Any], action: dict[str, Any], *, company_code: str | None) -> tuple[dict[str, Any] | None, str | None]:
    explicit = shift_by_id(str(action.get("shift_id") or action.get("requester_shift_id") or "").strip())
    company = require_company_code(company_code or employee.get("company_code"))
    if explicit:
        if str(explicit.get("company_code") or "").upper() == company and explicit.get("employee_key") == employee.get("employee_key") and explicit.get("status") == "scheduled":
            return explicit, None
        return None, "shift_not_owned_by_requester"
    start_date, end_date = shift_query_window(action)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM shift_assignments
                WHERE company_code=%s
                  AND employee_key=%s
                  AND shift_date BETWEEN %s AND %s
                  AND status='scheduled'
                ORDER BY shift_date, start_time
                LIMIT 3
                """,
                (company, employee.get("employee_key"), start_date, end_date),
            )
            rows = [dict(row) for row in cur.fetchall()]
    if not rows:
        return None, "no_scheduled_shift"
    if len(rows) > 1 and not action.get("date"):
        return None, "ambiguous_shift"
    return rows[0], None


def request_shift_swap(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None, account_id: str | None = None) -> dict[str, Any]:
    company = require_company_code(company_code)
    requester = resolve_shift_employee(action, required=True, company_code=company)
    if not requester:
        return {"ok": False, "error": "employee_not_found", "action": action}
    if str(requester.get("company_code") or company).upper() != company:
        return {"ok": False, "error": "employee_company_mismatch", "employee": json_safe(requester), "company_code": company}
    if action.get("viewer_phone") and not manager_scope_allows_employee(requester, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "employee": json_safe(requester), "action": action}
    target = resolve_shift_employee(
        {
            "employee_key": action.get("target_employee_key"),
            "subject_name": action.get("target_name"),
            "subject_phone": action.get("target_phone") or action.get("target_employee_phone"),
            "company_code": company,
        },
        required=False,
        company_code=company,
    )
    if target and str(target.get("company_code") or company).upper() != company:
        return {"ok": False, "error": "target_company_mismatch", "employee": json_safe(target), "company_code": company}
    if target and action.get("viewer_phone") and not manager_scope_allows_employee(target, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "employee": json_safe(target), "action": action}
    requester_shift, shift_error = active_shift_for_swap(requester, action, company_code=company)
    if not requester_shift:
        return {"ok": False, "error": shift_error or "no_scheduled_shift", "employee": json_safe(requester), "action": action}
    target_shift = shift_by_id(str(action.get("target_shift_id") or "").strip())
    reason = str(action.get("reason") or action.get("prompt_text") or action.get("query") or "").strip()
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO shift_swap_requests (
                    company_code, requester_employee_key, requester_employee_phone, requester_employee_name,
                    target_employee_key, target_employee_phone, target_employee_name,
                    requester_shift_id, target_shift_id, shift_date, status, reason, source_text,
                    requested_by_phone, metadata
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'requested',%s,%s,%s,%s)
                RETURNING *
                """,
                (
                    company,
                    requester.get("employee_key"),
                    digits(requester.get("phone")),
                    requester.get("name"),
                    target.get("employee_key") if target else None,
                    digits(target.get("phone")) if target else None,
                    target.get("name") if target else None,
                    requester_shift.get("shift_id"),
                    target_shift.get("shift_id") if target_shift else None,
                    requester_shift.get("shift_date"),
                    reason or None,
                    str(action.get("prompt_text") or action.get("query") or ""),
                    digits(created_by_phone) or digits(requester.get("phone")),
                    Json({"source": "whatsapp", "action": json_safe(action), "requester_shift": json_safe(requester_shift), "target_shift": json_safe(target_shift or {})}),
                ),
            )
            swap = dict(cur.fetchone())
            record_shift_swap_event(cur, swap=swap, company_code=company, event_type="requested", payload={"action": action, "swap": swap}, created_by_phone=created_by_phone)
        conn.commit()
    hr_notification = notify_hr_admins(
        company_code=company,
        account_id=account_id,
        message=f"{requester.get('name') or requester.get('phone')} requested a shift swap for {format_shift_date(requester_shift.get('shift_date'))}.",
        subject_type="shift_swap",
        subject_key=str(swap.get("swap_id")),
    )
    return {"ok": True, "swap": json_safe(swap), "requester": json_safe(requester), "target": json_safe(target) if target else None, "requester_shift": json_safe(requester_shift), "hr_notification": json_safe(hr_notification)}


def resolve_shift_swaps(action: dict[str, Any], *, company_code: str | None, statuses: tuple[str, ...] = ("requested",)) -> list[dict[str, Any]]:
    company = require_company_code(company_code)
    swap_id = str(action.get("swap_id") or "").strip()
    params: list[Any] = [company]
    where = ["ss.company_code=%s"]
    if swap_id:
        where.append("ss.swap_id=%s")
        params.append(swap_id)
    else:
        employee = resolve_shift_employee(action, required=False)
        start_date, end_date = shift_query_window(action)
        if employee:
            where.append("(ss.requester_employee_key=%s OR ss.target_employee_key=%s)")
            params.extend([employee.get("employee_key"), employee.get("employee_key")])
        if action.get("date") or action.get("start_date") or action.get("end_date") or text_has_period_signal(str(action.get("prompt_text") or action.get("query") or "")):
            where.append("ss.shift_date BETWEEN %s AND %s")
            params.extend([start_date, end_date])
    if statuses:
        where.append("ss.status = ANY(%s)")
        params.append(list(statuses))
    scope = org_scope_for_action(action, company)
    scope_clause, scope_params = employee_scope_sql("ss", {**scope, "branch_keys": scope.get("branch_keys"), "team_keys": scope.get("team_keys")})
    if scope_clause:
        # Scope requester first; target scope is checked before approval.
        where.append(scope_clause.replace("ss.employee_key", "ss.requester_employee_key").removeprefix("AND "))
        params.extend(scope_params)
    # Default 20 keeps WhatsApp/Assistant replies short; the dashboard passes a
    # higher limit so the actionable pending-swap queue (and the "N swaps to
    # review" banner counted from it) isn't truncated at 20 for a busy company.
    try:
        swap_limit = int(action.get("limit") or 20)
    except (TypeError, ValueError):
        swap_limit = 20
    swap_limit = max(1, min(swap_limit, 500))
    params.append(swap_limit)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT ss.*
                FROM shift_swap_requests ss
                WHERE {' AND '.join(where)}
                ORDER BY ss.requested_at DESC
                LIMIT %s
                """,
                params,
            )
            return [dict(row) for row in cur.fetchall()]


def decide_shift_swap(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None, account_id: str | None, decision: str) -> dict[str, Any]:
    company = require_company_code(company_code)
    status_value = "approved" if decision == "approved" else "rejected"
    matches = resolve_shift_swaps(action, company_code=company, statuses=("requested",))
    if matches:
        probe = matches[0]
        synth = _shifts_subject_is_synthetic(
            employee_key=probe.get("requester_employee_key"),
            phone=probe.get("requester_employee_phone"),
        ) or _shifts_subject_is_synthetic(
            employee_key=probe.get("target_employee_key"),
            phone=probe.get("target_employee_phone"),
        )
        denied = _shifts_w3.real_mutation_denied(actor_phone=created_by_phone, is_synthetic_subject=synth, company_code=company)
        if denied:
            return denied
    if not matches and action.get("swap_id") and _shifts_authority.shifts_wave1_enabled():
        # Idempotent replay: look up already-decided swap by id
        decided = resolve_shift_swaps(action, company_code=company, statuses=("approved", "rejected"))
        if decided:
            row = decided[0]
            if str(row.get("status")) == status_value:
                return {"ok": True, "idempotent": True, "swap": json_safe(row), "updated_shifts": []}
            return {"ok": False, "error": "stale_swap_decision", "swap": json_safe(row), "action": action}
    if not matches:
        return {"ok": False, "error": "shift_swap_not_found", "action": action}
    if len(matches) > 1 and not action.get("swap_id"):
        return {"ok": False, "error": "ambiguous_shift_swap", "matches": json_safe(matches[:5]), "action": action}
    swap = matches[0]
    if _shifts_authority.shifts_wave1_enabled():
        self_denied = _shifts_authority.self_swap_decision_denied(swap=swap, actor_phone=created_by_phone)
        if self_denied:
            return {**self_denied, "swap": json_safe(swap), "action": action}
    requester = {"employee_key": swap.get("requester_employee_key"), "company_code": company, "name": swap.get("requester_employee_name"), "phone": swap.get("requester_employee_phone")}
    target = {"employee_key": swap.get("target_employee_key"), "company_code": company, "name": swap.get("target_employee_name"), "phone": swap.get("target_employee_phone")} if swap.get("target_employee_key") else None
    if action.get("viewer_phone"):
        if not manager_scope_allows_employee(requester, company_code=company, viewer_phone=action.get("viewer_phone")) or (target and not manager_scope_allows_employee(target, company_code=company, viewer_phone=action.get("viewer_phone"))):
            return {"ok": False, "error": "employee_outside_manager_scope", "swap": json_safe(swap), "action": action}
    # Load shifts BEFORE opening the decide transaction — nested db_connect()
    # inside an open pooled connection can exhaust the pool and hang forever.
    requester_shift = None
    target_shift = None
    if decision == "approved":
        requester_shift = shift_by_id(str(swap.get("requester_shift_id") or ""), company_code=company)
        if not requester_shift or requester_shift.get("status") != "scheduled":
            return {"ok": False, "error": "requester_shift_not_active", "swap": json_safe(swap)}
        target_shift = shift_by_id(str(swap.get("target_shift_id") or ""), company_code=company)
        if not target and target_shift:
            target = {
                "employee_key": target_shift.get("employee_key"),
                "company_code": company,
                "name": target_shift.get("employee_name"),
                "phone": target_shift.get("employee_phone"),
            }
        if not target:
            return {"ok": False, "error": "missing_target_employee", "swap": json_safe(swap)}
    updated_shifts: list[dict[str, Any]] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            if _shifts_authority.shifts_wave1_enabled():
                _shifts_authority.ensure_shifts_authority_wave1_schema(cur)
            if decision == "approved":
                # Wave 2: lifecycle + leave gates on reassignment targets
                if _shifts_w2.shifts_wave2_enabled_for_company(company) and _shifts_authority.shifts_wave1_enabled():
                    settings = _shifts_authority.get_shift_authority_settings(cur, company)
                    for emp, sh in ((target, requester_shift), (requester, target_shift)):
                        if not emp or not sh:
                            continue
                        # Under Wave 2 synthetic-only, integrity gates apply only to SHW2B subjects.
                        # Other subjects (e.g. SHW1B) keep Wave 1 overlap checks below.
                        if _shifts_w2.shifts_wave2_synthetic_only() and not _shifts_w2.is_wave2_synthetic_employee(emp):
                            continue
                        life = _shifts_authority.evaluate_assignment_lifecycle(
                            cur,
                            company_code=company,
                            employee=emp,
                            settings=settings,
                            shift_date=sh.get("shift_date"),
                            start_time=sh.get("start_time"),
                            end_time=sh.get("end_time"),
                            ends_next_day=_shifts_authority.ends_next_day_for(sh.get("start_time"), sh.get("end_time")),
                            operation="reschedule",
                            action=action,
                        )
                        if life:
                            return {**life, "error": life.get("error") or "swap_lifecycle_blocked", "swap": json_safe(swap)}
                        leaves = _shifts_authority.approved_leave_on_date(
                            cur, company_code=company, employee_key=str(emp.get("employee_key")), shift_date=sh.get("shift_date")
                        )
                        leave_denied = _shifts_authority.leave_conflict_denied(
                            mode=str(settings.get("leave_conflict_mode") or "require_ack"),
                            leaves=leaves,
                            action=action,
                        )
                        if leave_denied:
                            return {**leave_denied, "error": "swap_leave_conflict", "swap": json_safe(swap)}
                conflicts = shift_conflicts(
                    cur,
                    company_code=company,
                    employee_key=str(target.get("employee_key")),
                    shift_date=requester_shift.get("shift_date"),
                    start_time=requester_shift.get("start_time"),
                    end_time=requester_shift.get("end_time"),
                    ends_next_day=_shifts_authority.ends_next_day_for(requester_shift.get("start_time"), requester_shift.get("end_time")),
                    exclude_shift_id=str((target_shift or {}).get("shift_id") or "") or None,
                )
                if conflicts:
                    return {"ok": False, "error": "target_shift_conflict", "swap": json_safe(swap), "conflicts": json_safe(conflicts)}
                # Also ensure requester won't collide with target's existing window after swap.
                if target_shift:
                    requester_conflicts = shift_conflicts(
                        cur,
                        company_code=company,
                        employee_key=str(requester.get("employee_key")),
                        shift_date=target_shift.get("shift_date"),
                        start_time=target_shift.get("start_time"),
                        end_time=target_shift.get("end_time"),
                        ends_next_day=_shifts_authority.ends_next_day_for(target_shift.get("start_time"), target_shift.get("end_time")),
                        exclude_shift_id=str(requester_shift.get("shift_id") or "") or None,
                    )
                    if requester_conflicts:
                        return {"ok": False, "error": "requester_shift_conflict", "swap": json_safe(swap), "conflicts": json_safe(requester_conflicts)}
                cur.execute(
                    """
                    UPDATE shift_assignments
                    SET employee_key=%s, employee_phone=%s, employee_name=%s,
                        notes=COALESCE(notes,'') || CASE WHEN COALESCE(notes,'')='' THEN '' ELSE ' | ' END || %s,
                        metadata=metadata || %s,
                        updated_at=now()
                    WHERE shift_id=%s AND company_code=%s AND status='scheduled'
                    RETURNING *
                    """,
                    (
                        target.get("employee_key"),
                        digits(target.get("phone")),
                        target.get("name"),
                        "Assigned by approved shift swap",
                        Json({"approved_shift_swap_id": str(swap.get("swap_id"))}),
                        requester_shift.get("shift_id"),
                        company,
                    ),
                )
                updated = cur.fetchone()
                if updated:
                    updated_shift = dict(updated)
                    updated_shifts.append(updated_shift)
                    record_shift_event(cur, shift=updated_shift, company_code=company, event_type="shift_swap_assigned", payload={"swap": swap, "previous_shift": requester_shift, "new_shift": updated_shift}, created_by_phone=created_by_phone)
                    if _shifts_w2_applies(company, updated_shift):
                        _shifts_w2.record_assignment_version(
                            cur,
                            company_code=company,
                            shift=updated_shift,
                            reason_code="reassigned_swap",
                            actor_phone=created_by_phone,
                            previous_employee_key=requester_shift.get("employee_key"),
                            lineage={
                                "swap_id": str(swap.get("swap_id")),
                                "from_employee_key": requester_shift.get("employee_key"),
                                "to_employee_key": target.get("employee_key"),
                            },
                        )
                if target_shift:
                    cur.execute(
                        """
                        UPDATE shift_assignments
                        SET employee_key=%s, employee_phone=%s, employee_name=%s,
                            notes=COALESCE(notes,'') || CASE WHEN COALESCE(notes,'')='' THEN '' ELSE ' | ' END || %s,
                            metadata=metadata || %s,
                            updated_at=now()
                        WHERE shift_id=%s AND company_code=%s AND status='scheduled'
                        RETURNING *
                        """,
                        (
                            requester.get("employee_key"),
                            digits(requester.get("phone")),
                            requester.get("name"),
                            "Assigned by approved shift swap",
                            Json({"approved_shift_swap_id": str(swap.get("swap_id"))}),
                            target_shift.get("shift_id"),
                            company,
                        ),
                    )
                    updated = cur.fetchone()
                    if updated:
                        updated_shift = dict(updated)
                        updated_shifts.append(updated_shift)
                        record_shift_event(cur, shift=updated_shift, company_code=company, event_type="shift_swap_assigned", payload={"swap": swap, "previous_shift": target_shift, "new_shift": updated_shift}, created_by_phone=created_by_phone)
                        if _shifts_w2_applies(company, updated_shift):
                            _shifts_w2.record_assignment_version(
                                cur,
                                company_code=company,
                                shift=updated_shift,
                                reason_code="reassigned_swap",
                                actor_phone=created_by_phone,
                                previous_employee_key=target_shift.get("employee_key"),
                                lineage={
                                    "swap_id": str(swap.get("swap_id")),
                                    "from_employee_key": target_shift.get("employee_key"),
                                    "to_employee_key": requester.get("employee_key"),
                                },
                            )
            # Concurrent decide: only one winner on status='requested'
            cur.execute(
                """
                UPDATE shift_swap_requests
                SET status=%s, decision_note=%s, decided_by_phone=%s, decided_at=now(), updated_at=now()
                WHERE swap_id=%s AND company_code=%s AND status='requested'
                RETURNING *
                """,
                (status_value, str(action.get("decision_note") or "").strip() or None, digits(created_by_phone), swap.get("swap_id"), company),
            )
            decided_row = cur.fetchone()
            if not decided_row:
                cur.execute(
                    "SELECT * FROM shift_swap_requests WHERE swap_id=%s AND company_code=%s LIMIT 1",
                    (swap.get("swap_id"), company),
                )
                current = cur.fetchone()
                if current and str(dict(current).get("status")) == status_value:
                    return {"ok": True, "idempotent": True, "swap": json_safe(dict(current)), "updated_shifts": []}
                return {"ok": False, "error": "stale_swap_decision", "swap": json_safe(dict(current) if current else swap)}
            decided = dict(decided_row)
            record_shift_swap_event(cur, swap=decided, company_code=company, event_type=status_value, payload={"action": action, "swap": decided, "updated_shifts": updated_shifts}, created_by_phone=created_by_phone)
        conn.commit()
    notify_text = "approved" if decision == "approved" else "not approved"
    requester_notification = send_custom_employee_message(requester, account_id, f"Your shift swap request for {format_shift_date(decided.get('shift_date'))} was {notify_text}.")
    target_notification = send_custom_employee_message(target, account_id, f"A shift swap involving you for {format_shift_date(decided.get('shift_date'))} was {notify_text}.") if target else {"ok": True, "skipped": True}
    return {"ok": True, "swap": json_safe(decided), "updated_shifts": json_safe(updated_shifts), "requester_notification": json_safe(requester_notification), "target_notification": json_safe(target_notification)}


def approve_shift_swap(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None, account_id: str | None = None) -> dict[str, Any]:
    return decide_shift_swap(action, company_code=company_code, created_by_phone=created_by_phone, account_id=account_id, decision="approved")


def reject_shift_swap(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None, account_id: str | None = None) -> dict[str, Any]:
    return decide_shift_swap(action, company_code=company_code, created_by_phone=created_by_phone, account_id=account_id, decision="rejected")


def list_shift_swaps(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    status_filter = normalize_text(action.get("status") or "")
    statuses: tuple[str, ...] = tuple()
    if status_filter in {"requested", "approved", "rejected", "cancelled"}:
        statuses = (status_filter,)
    rows = resolve_shift_swaps(action, company_code=company, statuses=statuses)
    start_date, end_date = shift_query_window(action)
    return {"ok": True, "company_code": company, "start_date": start_date.isoformat(), "end_date": end_date.isoformat(), "swaps": json_safe(rows), "count": len(rows), "status_filter": status_filter}


def upsert_attendance_record(
    cur: Any,
    *,
    company: str,
    employee: dict[str, Any],
    shift: dict[str, Any] | None,
    attendance_date: date,
    status: str,
    check_in_at: datetime | None = None,
    check_out_at: datetime | None = None,
    notes: str | None = None,
    source_text: str | None = None,
    created_by_phone: str | None = None,
    action: dict[str, Any] | None = None,
) -> dict[str, Any]:
    late_minutes = attendance_minutes_late(check_in_at, shift) if check_in_at else 0
    early_leave_minutes = attendance_minutes_early_leave(check_out_at, shift) if check_out_at else 0
    if status == "present" and late_minutes:
        status = "late"
    cur.execute(
        """
        SELECT *
        FROM attendance_records
        WHERE company_code=%s
          AND employee_key=%s
          AND attendance_date=%s
          AND ((shift_id IS NULL AND %s IS NULL) OR shift_id=%s)
        ORDER BY updated_at DESC
        LIMIT 1
        """,
        (company, employee.get("employee_key"), attendance_date, shift.get("shift_id") if shift else None, shift.get("shift_id") if shift else None),
    )
    existing = cur.fetchone()
    if existing:
        existing = dict(existing)
        merged_check_in = check_in_at or existing.get("check_in_at")
        merged_check_out = check_out_at or existing.get("check_out_at")
        merged_late = attendance_minutes_late(merged_check_in, shift) if merged_check_in else int(existing.get("late_minutes") or 0)
        merged_early = attendance_minutes_early_leave(merged_check_out, shift) if merged_check_out else int(existing.get("early_leave_minutes") or 0)
        merged_status = status
        if merged_status == "present" and merged_late:
            merged_status = "late"
        cur.execute(
            """
            UPDATE attendance_records
            SET check_in_at=COALESCE(%s, check_in_at),
                check_out_at=COALESCE(%s, check_out_at),
                status=%s,
                late_minutes=%s,
                early_leave_minutes=%s,
                notes=COALESCE(%s, notes),
                source_text=COALESCE(%s, source_text),
                metadata=metadata || %s,
                updated_at=now()
            WHERE attendance_id=%s
            RETURNING *
            """,
            (
                check_in_at,
                check_out_at,
                merged_status,
                merged_late,
                merged_early,
                notes,
                source_text,
                Json({"last_action": json_safe(action or {})}),
                existing.get("attendance_id"),
            ),
        )
    else:
        cur.execute(
            """
            INSERT INTO attendance_records (
              company_code, employee_key, employee_phone, employee_name, shift_id,
              attendance_date, scheduled_start, scheduled_end, check_in_at, check_out_at,
              status, late_minutes, early_leave_minutes, notes, source_text, metadata, created_by_phone
            )
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            RETURNING *
            """,
            (
                company,
                employee.get("employee_key"),
                digits(employee.get("phone")),
                employee.get("name"),
                shift.get("shift_id") if shift else None,
                attendance_date,
                shift.get("start_time") if shift else None,
                shift.get("end_time") if shift else None,
                check_in_at,
                check_out_at,
                status,
                late_minutes,
                early_leave_minutes,
                notes,
                source_text,
                Json({"source": "whatsapp", "action": json_safe(action or {})}),
                digits(created_by_phone),
            ),
        )
    return dict(cur.fetchone())


def _authority_source_event_id(action: dict[str, Any] | None, *, prefix: str, employee_key: str, attendance_date: date) -> str:
    action = action or {}
    explicit = action.get("source_event_id") or action.get("idempotency_key") or action.get("event_id")
    if explicit:
        return str(explicit)
    # Stable-enough fallback for dark WhatsApp retries within the same logical action payload.
    digest = str(action.get("prompt_text") or action.get("query") or action.get("time") or "")
    return f"{prefix}:{employee_key}:{attendance_date.isoformat()}:{digest}"


def _mirror_authority_compat_to_records(
    cur: Any,
    *,
    company: str,
    employee: dict[str, Any],
    shift: dict[str, Any] | None,
    attendance_date: date,
    compat: dict[str, Any],
    created_by_phone: str | None,
    action: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Compatibility read-model mirror. Authority remains the punch/projection engine."""
    meta = compat.get("metadata") if isinstance(compat.get("metadata"), dict) else {}
    return upsert_attendance_record(
        cur,
        company=company,
        employee=employee,
        shift=shift,
        attendance_date=attendance_date,
        status=str(compat.get("status") or "pending"),
        check_in_at=compat.get("check_in_at") if isinstance(compat.get("check_in_at"), datetime) else (
            datetime.fromisoformat(str(compat["check_in_at"]).replace("Z", "+00:00")) if compat.get("check_in_at") else None
        ),
        check_out_at=compat.get("check_out_at") if isinstance(compat.get("check_out_at"), datetime) else (
            datetime.fromisoformat(str(compat["check_out_at"]).replace("Z", "+00:00")) if compat.get("check_out_at") else None
        ),
        notes=compat.get("notes"),
        source_text=str((action or {}).get("prompt_text") or (action or {}).get("query") or ""),
        created_by_phone=created_by_phone,
        action={**(action or {}), "authority_mirror": True, "projection_version": meta.get("projection_version"), "exception_state": meta.get("exception_state")},
    )


def check_in_employee(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    employee = resolve_attendance_employee(action, company_code=company, required=True)
    if not employee:
        return {"ok": False, "error": "employee_not_found", "action": action}
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "employee": json_safe(employee), "action": action}
    if str(employee.get("company_code") or company).upper() != company:
        return {"ok": False, "error": "employee_company_mismatch", "employee": json_safe(employee), "company_code": company}
    attendance_date = attendance_date_from_action(action)
    check_in_at = attendance_timestamp_from_action(action, attendance_date)
    with db_connect() as conn:
        with conn.cursor() as cur:
            shift = active_shift_for_attendance(cur, company_code=company, employee_key=str(employee.get("employee_key")), attendance_date=attendance_date, shift_id=action.get("shift_id"))
            if not shift:
                return {"ok": False, "error": "no_scheduled_shift", "employee": json_safe(employee), "attendance_date": attendance_date.isoformat(), "action": action}
            if attendance_authority_enabled_for_company(company):
                svc = _attendance_authority.get_authority_service(company)
                authority = svc.ingest_punch(
                    company_code=company,
                    employee=employee,
                    punched_at=check_in_at,
                    direction="in",
                    source=str(action.get("attendance_source") or "whatsapp"),
                    source_event_id=_authority_source_event_id(action, prefix="check_in", employee_key=str(employee.get("employee_key")), attendance_date=attendance_date),
                    shift=shift,
                    work_date=attendance_date,
                    created_by_phone=created_by_phone,
                    metadata={"action_type": "check_in_employee"},
                )
                if not authority.get("ok"):
                    return {**authority, "employee": json_safe(employee), "action": action}
                attendance = _mirror_authority_compat_to_records(
                    cur,
                    company=company,
                    employee=employee,
                    shift=shift,
                    attendance_date=attendance_date,
                    compat=authority.get("compat") or {},
                    created_by_phone=created_by_phone,
                    action=action,
                )
                event_type = "checked_in_late" if int(attendance.get("late_minutes") or 0) > 0 else "checked_in"
                record_attendance_event(cur, attendance=attendance, company_code=company, event_type=event_type, payload={"action": action, "attendance": attendance, "shift": shift, "authority": authority}, created_by_phone=created_by_phone)
                conn.commit()
                return {"ok": True, "employee": json_safe(employee), "shift": json_safe(shift), "attendance": json_safe(attendance), "authority": json_safe(authority)}
            attendance = upsert_attendance_record(
                cur,
                company=company,
                employee=employee,
                shift=shift,
                attendance_date=attendance_date,
                status="present",
                check_in_at=check_in_at,
                source_text=str(action.get("prompt_text") or action.get("query") or ""),
                created_by_phone=created_by_phone,
                action=action,
            )
            event_type = "checked_in_late" if int(attendance.get("late_minutes") or 0) > 0 else "checked_in"
            record_attendance_event(cur, attendance=attendance, company_code=company, event_type=event_type, payload={"action": action, "attendance": attendance, "shift": shift}, created_by_phone=created_by_phone)
        conn.commit()
    return {"ok": True, "employee": json_safe(employee), "shift": json_safe(shift), "attendance": json_safe(attendance)}


def check_out_employee(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    employee = resolve_attendance_employee(action, company_code=company, required=True)
    if not employee:
        return {"ok": False, "error": "employee_not_found", "action": action}
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "employee": json_safe(employee), "action": action}
    attendance_date = attendance_date_from_action(action)
    check_out_at = attendance_timestamp_from_action(action, attendance_date)
    with db_connect() as conn:
        with conn.cursor() as cur:
            shift = active_shift_for_attendance(cur, company_code=company, employee_key=str(employee.get("employee_key")), attendance_date=attendance_date, shift_id=action.get("shift_id"))
            if attendance_authority_enabled_for_company(company):
                # Overnight: if no shift on action date, try previous calendar day.
                work_date = attendance_date
                if not shift:
                    prev = attendance_date - timedelta(days=1)
                    shift = active_shift_for_attendance(cur, company_code=company, employee_key=str(employee.get("employee_key")), attendance_date=prev, shift_id=action.get("shift_id"))
                    if shift:
                        work_date = prev
                        # Rebuild checkout timestamp on correct calendar when only time was provided.
                        if action.get("time") or action.get("check_time") or action.get("check_out_time"):
                            check_out_at = attendance_timestamp_from_action(action, attendance_date)
                if not shift:
                    cur.execute(
                        """
                        SELECT *
                        FROM attendance_records
                        WHERE company_code=%s AND employee_key=%s AND attendance_date=%s
                        ORDER BY check_in_at DESC NULLS LAST, updated_at DESC
                        LIMIT 1
                        """,
                        (company, employee.get("employee_key"), attendance_date),
                    )
                    existing = cur.fetchone()
                    if not existing:
                        return {"ok": False, "error": "no_attendance_record", "employee": json_safe(employee), "attendance_date": attendance_date.isoformat(), "action": action}
                svc = _attendance_authority.get_authority_service(company)
                authority = svc.ingest_punch(
                    company_code=company,
                    employee=employee,
                    punched_at=check_out_at,
                    direction="out",
                    source=str(action.get("attendance_source") or "whatsapp"),
                    source_event_id=_authority_source_event_id(action, prefix="check_out", employee_key=str(employee.get("employee_key")), attendance_date=work_date if shift else attendance_date),
                    shift=shift,
                    work_date=work_date if shift else attendance_date,
                    created_by_phone=created_by_phone,
                    metadata={"action_type": "check_out_employee"},
                )
                if not authority.get("ok"):
                    return {**authority, "employee": json_safe(employee), "action": action}
                mirror_date = work_date if shift else attendance_date
                attendance = _mirror_authority_compat_to_records(
                    cur,
                    company=company,
                    employee=employee,
                    shift=shift,
                    attendance_date=mirror_date,
                    compat=authority.get("compat") or {},
                    created_by_phone=created_by_phone,
                    action=action,
                )
                record_attendance_event(cur, attendance=attendance, company_code=company, event_type="checked_out", payload={"action": action, "attendance": attendance, "shift": shift, "authority": authority}, created_by_phone=created_by_phone)
                conn.commit()
                return {"ok": True, "employee": json_safe(employee), "shift": json_safe(shift), "attendance": json_safe(attendance), "authority": json_safe(authority)}
            cur.execute(
                """
                SELECT *
                FROM attendance_records
                WHERE company_code=%s AND employee_key=%s AND attendance_date=%s
                ORDER BY check_in_at DESC NULLS LAST, updated_at DESC
                LIMIT 1
                """,
                (company, employee.get("employee_key"), attendance_date),
            )
            existing = cur.fetchone()
            if not existing and not shift:
                return {"ok": False, "error": "no_attendance_record", "employee": json_safe(employee), "attendance_date": attendance_date.isoformat(), "action": action}
            attendance = upsert_attendance_record(
                cur,
                company=company,
                employee=employee,
                shift=shift or (dict(existing) if existing else None),
                attendance_date=attendance_date,
                status="completed",
                check_out_at=check_out_at,
                source_text=str(action.get("prompt_text") or action.get("query") or ""),
                created_by_phone=created_by_phone,
                action=action,
            )
            record_attendance_event(cur, attendance=attendance, company_code=company, event_type="checked_out", payload={"action": action, "attendance": attendance, "shift": shift}, created_by_phone=created_by_phone)
        conn.commit()
    return {"ok": True, "employee": json_safe(employee), "shift": json_safe(shift), "attendance": json_safe(attendance)}


def mark_attendance_absent(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    employee = resolve_attendance_employee(action, company_code=company, required=True)
    if not employee:
        return {"ok": False, "error": "employee_not_found", "action": action}
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "employee": json_safe(employee), "action": action}
    attendance_date = attendance_date_from_action(action)
    notes = str(action.get("notes") or "").strip() or None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM leave_requests
                WHERE company_code=%s
                  AND employee_key=%s
                  AND status='approved'
                  AND start_date <= %s
                  AND end_date >= %s
                ORDER BY updated_at DESC
                LIMIT 1
                """,
                (company, employee.get("employee_key"), attendance_date, attendance_date),
            )
            approved_leave = cur.fetchone()
            if approved_leave:
                return {"ok": False, "error": "approved_leave_exists", "employee": json_safe(employee), "attendance_date": attendance_date.isoformat(), "leave": json_safe(dict(approved_leave)), "action": action}
            shift = active_shift_for_attendance(cur, company_code=company, employee_key=str(employee.get("employee_key")), attendance_date=attendance_date, shift_id=action.get("shift_id"))
            if not shift and not action.get("allow_without_shift"):
                return {"ok": False, "error": "no_scheduled_shift", "needs_confirmation": True, "employee": json_safe(employee), "attendance_date": attendance_date.isoformat(), "action": action}
            if attendance_authority_enabled_for_company(company):
                svc = _attendance_authority.get_authority_service(company)
                authority = svc.mark_absent(
                    company_code=company,
                    employee=employee,
                    work_date=attendance_date,
                    shift=shift,
                    source=str(action.get("attendance_source") or ("absence_scan" if "Auto no-show" in str(notes or "") else "hr")),
                    source_event_id=_authority_source_event_id(action, prefix="absent", employee_key=str(employee.get("employee_key")), attendance_date=attendance_date),
                    created_by_phone=created_by_phone,
                    notes=notes,
                )
                if not authority.get("ok"):
                    return {**authority, "employee": json_safe(employee), "action": action}
                attendance = _mirror_authority_compat_to_records(
                    cur,
                    company=company,
                    employee=employee,
                    shift=shift,
                    attendance_date=attendance_date,
                    compat=authority.get("compat") or projection_to_compat_safe(authority.get("projection")),
                    created_by_phone=created_by_phone,
                    action=action,
                )
                record_attendance_event(cur, attendance=attendance, company_code=company, event_type="marked_absent", payload={"action": action, "attendance": attendance, "shift": shift, "authority": authority}, created_by_phone=created_by_phone)
                conn.commit()
                return {"ok": True, "employee": json_safe(employee), "shift": json_safe(shift), "attendance": json_safe(attendance), "authority": json_safe(authority)}
            attendance = upsert_attendance_record(
                cur,
                company=company,
                employee=employee,
                shift=shift,
                attendance_date=attendance_date,
                status="absent",
                notes=notes,
                source_text=str(action.get("prompt_text") or action.get("query") or ""),
                created_by_phone=created_by_phone,
                action=action,
            )
            record_attendance_event(cur, attendance=attendance, company_code=company, event_type="marked_absent", payload={"action": action, "attendance": attendance, "shift": shift}, created_by_phone=created_by_phone)
        conn.commit()
    return {"ok": True, "employee": json_safe(employee), "shift": json_safe(shift), "attendance": json_safe(attendance)}


def projection_to_compat_safe(proj: dict[str, Any] | None) -> dict[str, Any]:
    if not proj:
        return {}
    return _attendance_authority.projection_to_compat_record(proj)


def correct_attendance_record(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    employee = resolve_attendance_employee(action, company_code=company, required=True)
    if not employee:
        return {"ok": False, "error": "employee_not_found", "action": action}
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "employee": json_safe(employee), "action": action}
    attendance_date = attendance_date_from_action(action)
    status = normalize_text(action.get("status") or "")
    if status not in {"present", "late", "absent", "completed"}:
        text = normalize_text(action.get("prompt_text") or action.get("query") or "")
        if "absent" in text:
            status = "absent"
        elif "late" in text:
            status = "late"
        elif "check out" in text or "checked out" in text:
            status = "completed"
        else:
            status = "present"
    with db_connect() as conn:
        with conn.cursor() as cur:
            shift = active_shift_for_attendance(cur, company_code=company, employee_key=str(employee.get("employee_key")), attendance_date=attendance_date, shift_id=action.get("shift_id"))
            if not shift and not action.get("allow_without_shift"):
                return {"ok": False, "error": "no_scheduled_shift", "needs_confirmation": True, "employee": json_safe(employee), "attendance_date": attendance_date.isoformat(), "action": action}
            if attendance_authority_enabled_for_company(company):
                svc = _attendance_authority.get_authority_service(company)
                decision = normalize_text(action.get("decision") or action.get("correction_decision") or "")
                correction_id = action.get("correction_id")
                actor = digits(created_by_phone or action.get("viewer_phone"))
                actor_is_manager = bool(action.get("viewer_phone") or action.get("actor_is_manager"))
                if correction_id and decision in {"approved", "rejected", "disputed"}:
                    reviewed = svc.review_correction(
                        company_code=company,
                        correction_id=str(correction_id),
                        decision=decision,
                        decided_by_phone=actor,
                        decision_note=str(action.get("decision_note") or action.get("notes") or "") or None,
                        dispute_reason=str(action.get("dispute_reason") or "") or None,
                        employee=employee,
                        shift=shift,
                    )
                    if not reviewed.get("ok"):
                        return {**reviewed, "employee": json_safe(employee), "action": action}
                    if reviewed.get("compat"):
                        attendance = _mirror_authority_compat_to_records(
                            cur, company=company, employee=employee, shift=shift, attendance_date=attendance_date,
                            compat=reviewed["compat"], created_by_phone=created_by_phone, action=action,
                        )
                    else:
                        attendance = None
                    record_attendance_event(cur, attendance=attendance or {"attendance_id": None}, company_code=company, event_type=f"correction_{decision}", payload={"action": action, "review": reviewed}, created_by_phone=created_by_phone)
                    conn.commit()
                    return {"ok": True, "employee": json_safe(employee), "shift": json_safe(shift), "attendance": json_safe(attendance), "correction": json_safe(reviewed.get("correction")), "authority": json_safe(reviewed)}
                check_time = attendance_timestamp_from_action(action, attendance_date) if action.get("time") else None
                changes: dict[str, Any] = {"status": status}
                if status in {"present", "late"} and check_time:
                    changes["check_in_at"] = check_time.isoformat()
                if status == "completed" and check_time:
                    changes["check_out_at"] = check_time.isoformat()
                if action.get("check_in_at"):
                    changes["check_in_at"] = action.get("check_in_at")
                if action.get("check_out_at"):
                    changes["check_out_at"] = action.get("check_out_at")
                requested = svc.request_correction(
                    company_code=company,
                    employee=employee,
                    work_date=attendance_date,
                    requested_by_phone=actor,
                    changes=changes,
                    shift=shift,
                    actor_is_manager=actor_is_manager,
                )
                if not requested.get("ok"):
                    return {**requested, "employee": json_safe(employee), "action": action}
                # Optional dark auto-approve only when explicitly requested (still creates versioned history).
                if action.get("auto_approve_correction"):
                    reviewed = svc.review_correction(
                        company_code=company,
                        correction_id=str(requested["correction"]["correction_id"]),
                        decision="approved",
                        decided_by_phone=actor,
                        decision_note="auto_approve_correction",
                        employee=employee,
                        shift=shift,
                    )
                    attendance = None
                    if reviewed.get("compat"):
                        attendance = _mirror_authority_compat_to_records(
                            cur, company=company, employee=employee, shift=shift, attendance_date=attendance_date,
                            compat=reviewed["compat"], created_by_phone=created_by_phone, action=action,
                        )
                    conn.commit()
                    return {"ok": True, "employee": json_safe(employee), "shift": json_safe(shift), "attendance": json_safe(attendance), "correction": json_safe(requested.get("correction")), "authority": json_safe(reviewed)}
                conn.commit()
                return {"ok": True, "employee": json_safe(employee), "shift": json_safe(shift), "attendance": None, "correction": json_safe(requested.get("correction")), "pending_review": True}
            check_time = attendance_timestamp_from_action(action, attendance_date) if action.get("time") else None
            attendance = upsert_attendance_record(
                cur,
                company=company,
                employee=employee,
                shift=shift,
                attendance_date=attendance_date,
                status=status,
                check_in_at=check_time if status in {"present", "late"} else None,
                check_out_at=check_time if status == "completed" else None,
                notes=str(action.get("notes") or action.get("prompt_text") or "").strip() or None,
                source_text=str(action.get("prompt_text") or action.get("query") or ""),
                created_by_phone=created_by_phone,
                action=action,
            )
            record_attendance_event(cur, attendance=attendance, company_code=company, event_type="corrected", payload={"action": action, "attendance": attendance, "shift": shift}, created_by_phone=created_by_phone)
        conn.commit()
    return {"ok": True, "employee": json_safe(employee), "shift": json_safe(shift), "attendance": json_safe(attendance)}

def attendance_row_is_exception(row: dict[str, Any] | None) -> bool:
    """Canonical exception gate shared by web/mobile list filters.

    Present / completed / approved_leave / void with no late/early signal are
    never exceptions. Late minutes, early leave, absence, incomplete punches,
    and pending review states are.
    """
    data = row if isinstance(row, dict) else {}
    status = str(data.get("status") or "").strip().lower()
    if status in {"approved_leave", "void"}:
        return False
    if int(data.get("late_minutes") or 0) > 0 or status == "late":
        return True
    if int(data.get("early_leave_minutes") or 0) > 0:
        return True
    if status in {"absent", "incomplete", "pending"}:
        return True
    check_in = data.get("check_in_at")
    check_out = data.get("check_out_at")
    scheduled = data.get("scheduled_start") or data.get("scheduled_end")
    if scheduled and not check_in and status not in {"present", "completed"}:
        return True
    if check_in and not check_out and status not in {"present", "completed", "late"}:
        return True
    return False


def attendance_exception_kind(row: dict[str, Any] | None) -> str | None:
    """Ops-aligned exception kind for mobile/web shared vocabulary."""
    if not attendance_row_is_exception(row):
        return None
    data = row if isinstance(row, dict) else {}
    status = str(data.get("status") or "").strip().lower()
    late = int(data.get("late_minutes") or 0)
    early = int(data.get("early_leave_minutes") or 0)
    check_in = data.get("check_in_at")
    check_out = data.get("check_out_at")
    if status == "absent":
        return "absence"
    if late > 0 or status == "late":
        return "lateness"
    if early > 0:
        return "early_leave"
    if not check_in:
        return "missing_check_in"
    if check_in and not check_out:
        return "missing_check_out"
    if status in {"incomplete", "pending"}:
        return "incomplete_session"
    return "incomplete_session"


def list_attendance(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    start_date, end_date = shift_query_window(action)
    scope = org_scope_for_action(action, company)
    employee = resolve_attendance_employee(action, company_code=company, required=False)
    if employee and action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "action": action, "scope": json_safe(scope)}
    text = normalize_text(action.get("prompt_text") or action.get("query") or "")
    status_filter = normalize_text(action.get("status") or "")
    if not status_filter:
        if "late" in text:
            status_filter = "late"
        elif "absent" in text or "no show" in text:
            status_filter = "absent"
        elif "checked out" in text:
            status_filter = "completed"
        elif "checked in" in text or "present" in text or "who is here" in text:
            status_filter = "present"
    row_limit, offset = _paginate_params(action, default_limit=100, max_limit=5000)

    # Wave 1: when authority is on, prefer projection compatibility reads (legacy shape).
    if attendance_authority_enabled_for_company(company):
        svc = _attendance_authority.get_authority_service(company)
        scoped_keys = None
        if action.get("viewer_phone") and scope and scope.get("mode") not in {None, "company", "all"}:
            # Fall through to SQL mirror for scoped manager lists (compat rows stamped on write).
            pass
        else:
            rows = svc.list_compat_attendance(
                company_code=company,
                start_date=start_date,
                end_date=end_date,
                employee_key=str(employee.get("employee_key")) if employee else None,
            )
            if status_filter in {"present", "late", "absent", "completed", "pending", "exceptions"}:
                if status_filter == "present":
                    rows = [r for r in rows if str(r.get("status") or "") in {"present", "late", "completed"}]
                elif status_filter == "late":
                    rows = [r for r in rows if int(r.get("late_minutes") or 0) > 0]
                elif status_filter == "exceptions":
                    rows = [r for r in rows if attendance_row_is_exception(r)]
                else:
                    rows = [r for r in rows if str(r.get("status") or "") == status_filter]
            total_count = len(rows)
            page = rows[offset : offset + row_limit]
            for row in page:
                if isinstance(row, dict):
                    _attendance_authority.attach_attendance_life_contract(row)
            return {
                "ok": True,
                "company_code": company,
                "start_date": start_date.isoformat(),
                "end_date": end_date.isoformat(),
                "employee": json_safe(employee),
                "status_filter": status_filter or None,
                "attendance": json_safe(page),
                "scope": json_safe(scope),
                "total_count": total_count,
                "has_more": (offset + len(page)) < total_count,
                "limit": row_limit,
                "offset": offset,
                "authority": _attendance_authority.AUTHORITY_VERSION,
            }

    params: list[Any] = [company, start_date, end_date]
    where = ["ar.company_code=%s", "ar.attendance_date BETWEEN %s AND %s"]
    if employee:
        where.append("ar.employee_key=%s")
        params.append(employee.get("employee_key"))
    if status_filter in {"present", "late", "absent", "completed", "pending", "exceptions"}:
        if status_filter == "present":
            where.append("status IN ('present','late','completed')")
        elif status_filter == "late":
            where.append("late_minutes > 0")
        elif status_filter == "exceptions":
            where.append(
                """(
                    lower(coalesce(ar.status,'')) IN ('late','absent','incomplete','pending')
                    OR coalesce(ar.late_minutes,0) > 0
                    OR coalesce(ar.early_leave_minutes,0) > 0
                    OR (
                        ar.scheduled_start IS NOT NULL
                        AND ar.check_in_at IS NULL
                        AND lower(coalesce(ar.status,'')) NOT IN ('approved_leave','void','present','completed')
                    )
                    OR (
                        ar.check_in_at IS NOT NULL
                        AND ar.check_out_at IS NULL
                        AND lower(coalesce(ar.status,'')) IN ('incomplete','pending','')
                    )
                )"""
            )
        else:
            where.append("status=%s")
            params.append(status_filter)
    scope_clause, scope_params = employee_scope_sql("ar", scope)
    if scope_clause:
        where.append(scope_clause.removeprefix("AND "))
        params.extend(scope_params)
    # Pagination. Default limit=100 keeps every existing WhatsApp/Assistant/export
    # caller identical; the dashboard passes limit/offset to page through a busy
    # window instead of silently dropping records past the cap. COUNT(*) OVER()
    # rides the same scan for an accurate total + has_more. The employee_key PK-ish
    # tiebreaker makes the sort a total order so LIMIT/OFFSET pages don't shuffle
    # rows sharing a date/name (which would duplicate or skip records across pages).
    params.extend([row_limit, offset])
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT ar.*, COUNT(*) OVER() AS _total_count
                FROM attendance_records ar
                WHERE {' AND '.join(where)}
                ORDER BY ar.attendance_date DESC, ar.scheduled_start NULLS LAST, ar.employee_name NULLS LAST, ar.employee_key
                LIMIT %s OFFSET %s
                """,
                params,
            )
            rows = [dict(row) for row in cur.fetchall()]
    total_count = int(rows[0]["_total_count"]) if rows else 0
    for row in rows:
        row.pop("_total_count", None)
        _attendance_authority.attach_attendance_life_contract(row)
    has_more = (offset + len(rows)) < total_count
    return {
        "ok": True,
        "company_code": company,
        "start_date": start_date.isoformat(),
        "end_date": end_date.isoformat(),
        "employee": json_safe(employee),
        "status_filter": status_filter or None,
        "attendance": json_safe(rows),
        "scope": json_safe(scope),
        "total_count": total_count,
        "has_more": has_more,
        "limit": row_limit,
        "offset": offset,
    }


def format_attendance_time(value: Any) -> str:
    if not value:
        return ""
    try:
        dt = value if isinstance(value, datetime) else datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=KUWAIT_TZ)
        return dt.astimezone(KUWAIT_TZ).strftime("%H:%M")
    except Exception:
        return str(value)


def format_attendance_mutation_reply(result: dict[str, Any], action_type: str) -> str:
    if not result.get("ok"):
        employee = result.get("employee") if isinstance(result.get("employee"), dict) else {}
        name = employee.get("name") or "that employee"
        error = result.get("error")
        if error == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if error == "employee_not_found":
            return "I need the employee name or phone before changing attendance."
        if error == "employee_company_mismatch":
            return "That employee does not belong to this company."
        if error == "no_scheduled_shift" and result.get("needs_confirmation"):
            return f"I found {name}, but I do not see a scheduled shift for {format_shift_date(result.get('attendance_date'))}. Should I record it anyway?"
        if error == "no_scheduled_shift":
            return f"I found {name}, but I do not see a scheduled shift for {format_shift_date(result.get('attendance_date'))}."
        if error == "no_attendance_record":
            return f"I found {name}, but I do not see a check-in record for {format_shift_date(result.get('attendance_date'))}."
        if error == "approved_leave_exists":
            return f"I found approved leave for {name} on {format_shift_date(result.get('attendance_date'))}, so I will not mark them absent."
        return "I could not update attendance safely."
    employee = result.get("employee") if isinstance(result.get("employee"), dict) else {}
    attendance = result.get("attendance") if isinstance(result.get("attendance"), dict) else {}
    name = employee.get("name") or attendance.get("employee_name") or "Employee"
    date_text = format_shift_date(attendance.get("attendance_date"))
    if action_type == "check_in_employee":
        reply = f"Checked in {name} for {date_text} at {format_attendance_time(attendance.get('check_in_at'))}."
        late = int(attendance.get("late_minutes") or 0)
        if late:
            reply += f" They are {late} minutes late."
        return reply
    if action_type == "check_out_employee":
        reply = f"Checked out {name} for {date_text} at {format_attendance_time(attendance.get('check_out_at'))}."
        early = int(attendance.get("early_leave_minutes") or 0)
        if early:
            reply += f" They left {early} minutes early."
        return reply
    if action_type == "mark_attendance_absent":
        return f"Marked {name} absent for {date_text}."
    return f"Updated {name}'s attendance for {date_text} to {display_status(attendance.get('status'))}."


def format_list_attendance_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok") and result.get("error") == "employee_outside_manager_scope":
        return "That employee is outside your manager scope."
    rows = result.get("attendance") if isinstance(result.get("attendance"), list) else []
    if not rows:
        if employee_view:
            return "I do not see an attendance record for you in that period."
        status = result.get("status_filter")
        if status:
            return f"No {display_status(status).lower()} attendance records found for that period."
        return "No attendance records found for that period."
    title = "Your attendance:" if employee_view else f"Attendance ({format_shift_date_range(result.get('start_date'), result.get('end_date'))}):"
    lines = [title]
    for row in rows[:20]:
        name = "" if employee_view else f"{row.get('employee_name') or row.get('employee_phone')} - "
        parts = [display_status(row.get("status"))]
        if row.get("check_in_at"):
            parts.append(f"in {format_attendance_time(row.get('check_in_at'))}")
        if row.get("check_out_at"):
            parts.append(f"out {format_attendance_time(row.get('check_out_at'))}")
        if int(row.get("late_minutes") or 0):
            parts.append(f"{row.get('late_minutes')} min late")
        lines.append(f"- {format_shift_date(row.get('attendance_date'))}: {name}{', '.join(parts)}")
    if len(rows) > 20:
        lines.append(f"And {len(rows) - 20} more records.")
    return "\n".join(lines)


def format_leave_mutation_reply(result: dict[str, Any], action_type: str, *, employee_view: bool = False) -> str:
    if not result.get("ok"):
        error = result.get("error")
        if error == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if error == "employee_not_found":
            return "I need the employee name or phone before changing leave."
        if error == "employee_company_mismatch":
            return "That employee does not belong to this company."
        if error == "overlapping_leave_exists":
            return "There is already an active leave request for that period."
        if error == "leave_shift_conflicts" and result.get("needs_confirmation"):
            leave = result.get("leave") if isinstance(result.get("leave"), dict) else {}
            conflicts = result.get("shift_conflicts") if isinstance(result.get("shift_conflicts"), list) else []
            name = leave.get("employee_name") or "that employee"
            return f"{name} has {len(conflicts)} scheduled shift{'s' if len(conflicts) != 1 else ''} during this leave. Approve anyway?"
        if error == "leave_request_not_found":
            return "I could not find one exact pending leave request to change."
        return "I could not update leave safely."
    leave = result.get("leave") if isinstance(result.get("leave"), dict) else {}
    name = "your" if employee_view else f"{leave.get('employee_name') or 'Employee'}'s"
    date_text = format_shift_date_range(leave.get("start_date"), leave.get("end_date"))
    if action_type == "request_leave":
        conflicts = result.get("shift_conflicts") if isinstance(result.get("shift_conflicts"), list) else []
        suffix = f" I found {len(conflicts)} scheduled shift{'s' if len(conflicts) != 1 else ''} in that period, so HR should review before approving." if conflicts else ""
        return f"Leave request created for {name} {format_leave_type_for_sentence(leave.get('leave_type'))} on {date_text}.{suffix}"
    if action_type == "approve_leave_request":
        return f"Approved {name} leave for {date_text}."
    if action_type == "reject_leave_request":
        return f"Rejected {name} leave request for {date_text}."
    if action_type == "cancel_leave_request":
        return f"Cancelled {name} leave request for {date_text}."
    return f"Updated {name} leave for {date_text}."


def format_leave_type_for_sentence(value: Any) -> str:
    raw = normalize_text(value)
    if raw == "sick":
        return "sick leave"
    if raw in {"time_off", "time off"}:
        return "time off"
    return display_status(value).lower()


def format_list_leave_requests_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok") and result.get("error") == "employee_outside_manager_scope":
        return "That employee is outside your manager scope."
    rows = result.get("leave_requests") if isinstance(result.get("leave_requests"), list) else []
    if not rows:
        if employee_view:
            return "I do not see leave requests for you in that period."
        return "No leave requests found for that period."
    title = "Your leave requests:" if employee_view else f"Leave ({format_shift_date_range(result.get('start_date'), result.get('end_date'))}):"
    lines = [title]
    for row in rows[:20]:
        name = "" if employee_view else f"{row.get('employee_name') or row.get('employee_phone')} - "
        conflict_text = ""
        if int(row.get("shift_conflict_count") or 0):
            conflict_text = f", {row.get('shift_conflict_count')} shift conflict(s)"
        lines.append(
            f"- {format_shift_date_range(row.get('start_date'), row.get('end_date'))}: {name}{display_status(row.get('leave_type'))}, {display_status(row.get('status'))}{conflict_text}"
        )
    if len(rows) > 20:
        lines.append(f"And {len(rows) - 20} more leave requests.")
    return "\n".join(lines)


def normalize_posthire_result(result: dict[str, Any], *, action_type: str, reply: str | None = None) -> dict[str, Any]:
    """Shape a legacy post-hire executor result into the registry result contract.

    Post-hire executors (leave, attendance, shifts, payroll, ...) return
    {"ok": bool, ...} dicts with domain payloads. The registry/tool-call layer
    expects action_type/success/status/message and a safe_user_message that the
    orchestrator can surface to the user verbatim. This keeps every original key
    (leave, leave_requests, shift_conflicts, employee_notification,
    error, ...) so downstream renderers and audit retain full detail.

    `reply` is normally produced by the matching format_*_reply helper and becomes
    the user-facing safe message. needs_confirmation results map to a
    needs_confirmation status rather than a hard failure.
    """

    data = dict(result) if isinstance(result, dict) else {}
    ok = bool(data.get("ok"))
    if ok:
        status = "completed"
    elif data.get("needs_confirmation"):
        status = "needs_confirmation"
    else:
        status = "failed"
    safe = str(reply or data.get("safe_user_message") or data.get("message") or "").strip()
    if not safe:
        safe = "Done." if ok else "I could not complete that action."
    data["action_type"] = action_type
    data["success"] = ok
    data["status"] = status
    data["message"] = safe
    data["safe_user_message"] = safe
    return json_safe(data)


def format_payroll_hours_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if result.get("error") == "employee_not_found":
            return "I could not find your employee record for payroll hours." if employee_view else "I need the exact employee name or phone before calculating payroll hours for one person."
        return "I could not calculate payroll hours safely."
    rows = result.get("summaries") if isinstance(result.get("summaries"), list) else []
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
    if not rows:
        return f"I do not see payroll hours for you in {period}." if employee_view else f"No payroll hours found for {period}."
    lines = [
        f"Your provisional payroll hours ({period}):" if employee_view else f"Provisional payroll hours ({period}):",
        "Approved timesheets remain the money authority.",
    ]
    for row in rows[:12]:
        name = "" if employee_view else f"{row.get('employee_name') or row.get('employee_phone') or 'Employee'}: "
        pieces = [
            f"worked {decimal_hours(row.get('worked_minutes'))}h",
            f"scheduled {decimal_hours(row.get('scheduled_minutes'))}h",
        ]
        if int(row.get("approved_leave_minutes") or 0):
            pieces.append(f"approved leave {decimal_hours(row.get('approved_leave_minutes'))}h")
        if int(row.get("absent_minutes") or 0):
            pieces.append(f"absent {decimal_hours(row.get('absent_minutes'))}h")
        if int(row.get("overtime_minutes") or 0):
            pieces.append(f"overtime {decimal_hours(row.get('overtime_minutes'))}h")
        if int(row.get("late_minutes") or 0):
            pieces.append(f"{row.get('late_minutes')} min late")
        lines.append(f"- {name}{', '.join(pieces)} ({row.get('payroll_status') or 'Ready'})")
    if len(rows) > 12 and not employee_view:
        lines.append(f"And {len(rows) - 12} more employees.")
    return "\n".join(lines)


def format_workforce_analytics_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That analytics view is outside your manager scope."
        return "I could not generate workforce analytics safely."
    insights = result.get("insights") if isinstance(result.get("insights"), list) else []
    attention = result.get("attention") if isinstance(result.get("attention"), list) else []
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
    metric = analytics_metric_from_text(result.get("metric") or "")
    counts = result.get("counts") if isinstance(result.get("counts"), dict) else {}
    pending_review = int(counts.get("pending_leave") or 0) + int(counts.get("pending_availability") or 0) + int(counts.get("pending_swaps") or 0)
    lines = [f"Workforce analytics ({period}):"]
    lines.append(
        f"- Absences: {counts.get('absent_records', 0)} | Late records: {counts.get('late_records', 0)} | Pending review: {pending_review}"
    )
    if attention and metric in {"general", "review", ""}:
        lines.append("Needs attention:")
        for item in attention[:5]:
            lines.append(f"- [{item.get('severity')}] {item.get('reason') or item.get('reason_en')}")
    priority_metrics = {
        "late": {"Top lateness", "Late records"},
        "absence": {"Top absence", "Absences", "Branch absences"},
        "overtime": {"Hours above schedule"},
        "branch": {"Branch absences"},
        "coverage": {"Pending review"},
        "attendance_quality": {"Late records", "Absences"},
        "review": {"Pending review", "Top lateness", "Top absence", "Hours above schedule"},
    }.get(metric, set())
    selected = [
        item
        for item in insights
        if not item.get("demoted") and (not priority_metrics or item.get("metric") in priority_metrics)
    ]
    if not selected:
        selected = [item for item in insights if not item.get("demoted")]
    for item in selected[:8]:
        lines.append(f"- {item.get('metric')}: {item.get('subject')} - {item.get('value')} ({item.get('detail')})")
    if len(selected) > 8:
        lines.append(f"And {len(selected) - 8} more insight rows.")
    sources = result.get("sources") if isinstance(result.get("sources"), dict) else {}
    unavailable = sources.get("unavailable_source_keys") if isinstance(sources.get("unavailable_source_keys"), list) else []
    if unavailable:
        lines.append(f"Unavailable sources: {', '.join(str(x) for x in unavailable)}.")
    return "\n".join(lines)


def timesheet_hours_parts(row: dict[str, Any]) -> str:
    pieces = [
        f"worked {decimal_hours(row.get('worked_minutes'))}h",
        f"scheduled {decimal_hours(row.get('scheduled_minutes'))}h",
    ]
    if int(row.get("approved_leave_minutes") or 0):
        pieces.append(f"approved leave {decimal_hours(row.get('approved_leave_minutes'))}h")
    if int(row.get("absent_minutes") or 0):
        pieces.append(f"absent {decimal_hours(row.get('absent_minutes'))}h")
    if int(row.get("overtime_minutes") or 0):
        pieces.append(f"overtime {decimal_hours(row.get('overtime_minutes'))}h")
    if int(row.get("late_minutes") or 0):
        pieces.append(f"{row.get('late_minutes')} min late")
    return ", ".join(pieces)


def format_create_timesheet_review_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if result.get("error") == "employee_not_found":
            return "I need the exact employee name or phone before preparing that timesheet."
        return "I could not prepare timesheets safely."
    rows = result.get("timesheets") if isinstance(result.get("timesheets"), list) else []
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
    if not rows:
        skipped = result.get("skipped_approved") if isinstance(result.get("skipped_approved"), list) else []
        if skipped:
            return f"Those timesheets for {period} are already approved, so I did not overwrite them."
        return f"No payroll hours found to prepare timesheets for {period}."
    lines = [f"Prepared {len(rows)} draft timesheet{'s' if len(rows) != 1 else ''} for {period}:"]
    for row in rows[:10]:
        lines.append(f"- {row.get('employee_name') or row.get('employee_phone')}: {timesheet_hours_parts(row)} ({row.get('payroll_status') or 'Ready'})")
    if len(rows) > 10:
        lines.append(f"And {len(rows) - 10} more timesheets.")
    skipped = result.get("skipped_approved") if isinstance(result.get("skipped_approved"), list) else []
    if skipped:
        lines.append(f"Skipped {len(skipped)} already-approved timesheet{'s' if len(skipped) != 1 else ''}.")
    lines.append("Review these, then approve or reject the timesheets for that period.")
    return "\n".join(lines)


def format_timesheet_decision_reply(result: dict[str, Any], decision: str) -> str:
    if not result.get("ok"):
        if result.get("error") == "missing_period":
            return "Which timesheet period should I change? Send a period like this week, this month, or a date range."
        if result.get("error") == "timesheet_not_found":
            return "I could not find draft timesheets for that period. Prepare the timesheets first, then approve or reject them."
        return "I could not update timesheets safely."
    rows = result.get("timesheets") if isinstance(result.get("timesheets"), list) else []
    if not rows:
        return "I did not find draft timesheets to update."
    label = "Approved" if decision == "approved" else "Rejected"
    period = format_shift_date_range(rows[0].get("period_start"), rows[0].get("period_end"))
    lines = [f"{label} {len(rows)} timesheet{'s' if len(rows) != 1 else ''} for {period}:"]
    for row in rows[:10]:
        lines.append(f"- {row.get('employee_name') or row.get('employee_phone')}: {timesheet_hours_parts(row)}")
    if len(rows) > 10:
        lines.append(f"And {len(rows) - 10} more timesheets.")
    return "\n".join(lines)


def format_list_timesheets_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if result.get("error") == "employee_not_found":
            return "I could not find your employee record for timesheets." if employee_view else "I need the exact employee name or phone before showing that employee's timesheets."
        return "I could not list timesheets safely."
    rows = result.get("timesheets") if isinstance(result.get("timesheets"), list) else []
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
    if not rows:
        return f"I do not see a timesheet for you in {period}." if employee_view else f"No timesheets found for {period}."
    status = result.get("status_filter")
    title_status = f" {display_status(status).lower()}" if status else ""
    lines = [f"Your timesheets{title_status} ({period}):" if employee_view else f"Timesheets{title_status} ({period}):"]
    for row in rows[:12]:
        name = "" if employee_view else f"{row.get('employee_name') or row.get('employee_phone')}: "
        if employee_view and str(row.get("status") or "") == "draft":
            lines.append("- Draft, HR review pending.")
        elif employee_view and str(row.get("status") or "") == "rejected":
            lines.append("- Rejected. Please contact HR if you have questions.")
        else:
            lines.append(f"- {name}{display_status(row.get('status'))}, {timesheet_hours_parts(row)} ({row.get('payroll_status') or 'Ready'})")
    if len(rows) > 12 and not employee_view:
        lines.append(f"And {len(rows) - 12} more timesheets.")
    return "\n".join(lines)


def format_policy_bool(value: Any) -> str:
    return "on" if bool(value) else "off"


def format_show_payroll_policy_reply(result: dict[str, Any]) -> str:
    policy = result.get("policy") if isinstance(result.get("policy"), dict) else {}
    rate = policy.get("default_hourly_rate_kwd")
    rate_text = "not configured" if rate is None else f"{float(rate):.3f} KWD/hour"
    return "\n".join(
        [
            "Current payroll policy:",
            f"- Pay type: {display_status(policy.get('employee_pay_type'))}",
            f"- Leave: {display_status(policy.get('leave_policy'))}",
            f"- Overtime: {display_status(policy.get('overtime_policy'))}",
            f"- Absence deduction: {format_policy_bool(policy.get('absence_deduction_enabled'))}",
            f"- Late deduction: {format_policy_bool(policy.get('late_deduction_enabled'))}",
            f"- Early leave deduction: {format_policy_bool(policy.get('early_leave_deduction_enabled'))}",
            f"- Default hourly rate: {rate_text}",
            "- Payment processing: disabled",
        ]
    )


def format_set_payroll_policy_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        if result.get("error") == "no_policy_updates":
            return "Which payroll policy should I update? For example: set overtime policy to review only, make leave unpaid, or enable absence deductions."
        return "I could not update payroll policy safely."
    updates = result.get("updates") if isinstance(result.get("updates"), dict) else {}
    lines = ["Payroll policy updated:"]
    for key, value in updates.items():
        label = display_status(key)
        if isinstance(value, bool):
            lines.append(f"- {label}: {format_policy_bool(value)}")
        elif key.endswith("_kwd") and value is not None:
            lines.append(f"- {label}: {float(value):.3f} KWD")
        elif key.endswith("_minutes"):
            lines.append(f"- {label}: {decimal_hours(value)}h")
        else:
            lines.append(f"- {label}: {display_status(value)}")
    lines.append("Payment processing is still disabled; this only affects previews.")
    return "\n".join(lines)


def format_preview_payroll_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if result.get("error") == "employee_not_found":
            return "I need the exact employee name or phone before previewing payroll for one person."
        return "I could not preview payroll safely."
    rows = result.get("preview_rows") if isinstance(result.get("preview_rows"), list) else []
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
    if not rows:
        return f"No approved timesheets found for {period}. Approve timesheets first, then preview payroll."
    lines = [f"Payroll preview ({period}):"]
    for row in rows[:12]:
        amount = row.get("estimated_amount_kwd")
        amount_text = f", est. {float(amount):.3f} KWD" if amount is not None else f", amount {display_status(row.get('amount_status')).lower()}"
        flags = row.get("policy_flags") if isinstance(row.get("policy_flags"), list) else []
        flag_text = f", {', '.join(flags)}" if flags else ""
        lines.append(
            f"- {row.get('employee_name') or row.get('employee_phone')}: payable {decimal_hours(row.get('payable_minutes'))}h, deductions {decimal_hours(row.get('deduction_minutes'))}h{amount_text}{flag_text}"
        )
    if len(rows) > 12:
        lines.append(f"And {len(rows) - 12} more employees.")
    lines.append("No payment has been processed.")
    return "\n".join(lines)


def format_export_payroll_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        if result.get("error") == "missing_period":
            return "Which payroll period should I export? Send a period like this week, this month, or a date range."
        if result.get("error") == "employee_not_found":
            return "I need the exact employee name or phone before exporting payroll for one person."
        if result.get("error") == "no_approved_timesheets":
            period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
            return f"No approved timesheets found for {period}. Approve timesheets first, then export payroll."
        return "I could not export payroll safely."
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
    totals = result.get("totals") if isinstance(result.get("totals"), dict) else {}
    export_id = str(result.get("export_id") or "")
    short_id = export_id[:8] if export_id else "created"
    lines = [
        f"Payroll export locked for {period}.",
        f"- Export ID: {short_id}",
        f"- Employees: {int(result.get('row_count') or 0)}",
        f"- Payable hours: {decimal_hours(totals.get('payable_minutes'))}h",
        f"- Deduction hours: {decimal_hours(totals.get('deduction_minutes'))}h",
        f"- Overtime review: {decimal_hours(totals.get('overtime_review_minutes'))}h",
    ]
    amount = totals.get("estimated_amount_kwd")
    if amount is not None:
        lines.append(f"- Estimated amount: {float(amount):.3f} KWD")
    lines.append("No payment has been processed and no bank file was created.")
    return "\n".join(lines)


def format_list_payroll_exports_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        return "I could not list payroll exports safely."
    rows = result.get("exports") if isinstance(result.get("exports"), list) else []
    if not rows:
        period = format_shift_date_range(result.get("start_date"), result.get("end_date")) if result.get("start_date") else ""
        return f"No payroll exports found for {period}." if period else "No payroll exports found yet."
    lines = ["Payroll exports:"]
    for row in rows[:10]:
        period = format_shift_date_range(row.get("period_start"), row.get("period_end"))
        totals = row.get("totals") if isinstance(row.get("totals"), dict) else {}
        export_id = str(row.get("export_id") or "")
        lines.append(f"- {export_id[:8]}: {period}, {int(row.get('row_count') or 0)} employee(s), payable {decimal_hours(totals.get('payable_minutes'))}h")
    if len(rows) > 10:
        lines.append(f"And {len(rows) - 10} more exports.")
    lines.append("Exports are records only; no payment has been processed.")
    return "\n".join(lines)


def notify_attendance_exception(result: dict[str, Any], *, account_id: str | None, event_type: str) -> dict[str, Any]:
    employee = result.get("employee") if isinstance(result.get("employee"), dict) else {}
    attendance = result.get("attendance") if isinstance(result.get("attendance"), dict) else {}
    company = attendance.get("company_code") or employee.get("company_code") or result.get("company_code")
    name = employee.get("name") or attendance.get("employee_name") or "Employee"
    date_text = format_shift_date(attendance.get("attendance_date"))
    if event_type == "late_check_in":
        message = f"{name} checked in late for {date_text}: {attendance.get('late_minutes')} minutes late."
    elif event_type == "marked_absent":
        message = f"{name} was marked absent for {date_text}."
    else:
        message = f"Attendance exception for {name} on {date_text}: {display_status(attendance.get('status'))}."
    notification = notify_hr_admins(
        company_code=company,
        account_id=account_id,
        message=message,
        subject_type="attendance",
        subject_key=str(attendance.get("attendance_id") or ""),
    )
    with db_connect() as conn:
        with conn.cursor() as cur:
            record_attendance_event(
                cur,
                attendance=attendance,
                company_code=require_company_code(company),
                event_type=f"{event_type}_hr_notified" if notification.get("ok") else f"{event_type}_hr_notification_failed",
                payload={"message": message, "notification": notification},
                created_by_phone=None,
            )
        conn.commit()
    return notification


def format_shift_time(value: Any) -> str:
    text = str(value)
    return text[:5]


def format_shift_date(value: Any) -> str:
    if hasattr(value, "strftime"):
        day = value.date() if isinstance(value, datetime) else value
        return f"{day.strftime('%A')}, {day.day} {day.strftime('%B %Y')}"
    parsed = parse_iso_date(value)
    return f"{parsed.strftime('%A')}, {parsed.day} {parsed.strftime('%B %Y')}" if parsed else str(value)


def format_shift_date_range(start_date: Any, end_date: Any) -> str:
    start_text = format_shift_date(start_date)
    end_text = format_shift_date(end_date)
    return start_text if start_text == end_text else f"{start_text} to {end_text}"


_DELIVERY_STATUS_TEXT = {
    "delivered_whatsapp": "notified on WhatsApp",
    "delivered_template": "notified on WhatsApp",
    "sent_email_fallback": "sent by email (WhatsApp wasn’t reachable)",
    "needs_hr_action": "couldn’t be delivered — added to your follow-up list",
    "pending": "queued for delivery",
    "failed": "couldn’t be delivered",
    "suppressed": "not sent",
}


def notification_status_text(notification: dict[str, Any]) -> str:
    # Outbound delivery layer (Phase C+): report the HR-readable final status and
    # never the technical reason (that lives in last_error / attempt_reasons).
    delivery_status = notification.get("delivery_status")
    if delivery_status and delivery_status in _DELIVERY_STATUS_TEXT:
        return _DELIVERY_STATUS_TEXT[delivery_status]
    if notification.get("ok"):
        return "notified"
    send = notification.get("send") if isinstance(notification.get("send"), dict) else {}
    inner = send.get("send") if isinstance(send.get("send"), dict) else send
    error = inner.get("error") if isinstance(inner, dict) else None
    if error == "conversation_closed":
        return "WhatsApp conversation is not active"
    if error == "conversation_inactive":
        return "WhatsApp conversation is not active"
    if error == "missing_candidate_conversation_id":
        return "WhatsApp conversation is not active"
    if error == "no_usable_conversation_id":
        return "WhatsApp conversation is not active"
    return "notification failed"


def format_create_shift_reply(result: dict[str, Any]) -> str:
    if result.get("bulk"):
        results = result.get("results") if isinstance(result.get("results"), list) else []
        lines = [f"Bulk shift scheduling complete: {result.get('completed_count', 0)}/{result.get('requested_count', len(results))} employees scheduled."]
        for item in results[:8]:
            if not isinstance(item, dict):
                continue
            employee = item.get("employee") if isinstance(item.get("employee"), dict) else {}
            name = employee.get("name") or employee.get("phone") or "Employee"
            created_count = len(item.get("created") if isinstance(item.get("created"), list) else [])
            conflict_count = len(item.get("conflicts") if isinstance(item.get("conflicts"), list) else [])
            if item.get("ok"):
                note = f"{name}: {created_count} shift{'s' if created_count != 1 else ''}"
                notification = item.get("employee_notification") if isinstance(item.get("employee_notification"), dict) else {}
                if notification:
                    note += f", {notification_status_text(notification)}"
                lines.append(f"- {note}")
            elif conflict_count:
                lines.append(f"- {name}: skipped due to {conflict_count} conflict{'s' if conflict_count != 1 else ''}")
            else:
                lines.append(f"- {name}: failed ({item.get('error') or 'unknown error'})")
        unresolved = result.get("unresolved") if isinstance(result.get("unresolved"), list) else []
        if unresolved:
            lines.append(f"{len(unresolved)} employee reference{'s' if len(unresolved) != 1 else ''} could not be resolved.")
        if len(results) > 8:
            lines.append(f"And {len(results) - 8} more results.")
        return "\n".join(lines)
    if not result.get("ok"):
        error = result.get("error")
        if error == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if error == "employee_not_found":
            return "I could not find that employee. Please use the employee name or phone number."
        if error == "missing_shift_time":
            return "I need a clear shift time, like 9 to 5 or 09:00 to 17:00."
        if error == "invalid_shift_time_range":
            return "That shift time range is invalid. Please use a same-day start and end time."
        if result.get("conflicts"):
            conflict = result["conflicts"][0]
            return f"I found a conflict for {conflict.get('employee_name') or 'the employee'} on {format_shift_date(conflict.get('shift_date'))} from {format_shift_time(conflict.get('start_time'))} to {format_shift_time(conflict.get('end_time'))}."
        return "I could not create that shift."
    employee = result.get("employee") or {}
    created = result.get("created") or []
    lines = [f"Scheduled {employee.get('name') or employee.get('phone')} for {len(created)} shift{'s' if len(created) != 1 else ''}:"]
    for shift in created[:8]:
        extra = []
        if shift.get("location"):
            extra.append(str(shift.get("location")))
        if shift.get("role"):
            extra.append(str(shift.get("role")))
        suffix = f" ({', '.join(extra)})" if extra else ""
        lines.append(f"- {format_shift_date(shift.get('shift_date'))}: {format_shift_time(shift.get('start_time'))}-{format_shift_time(shift.get('end_time'))}{suffix}")
    conflicts = result.get("conflicts") or []
    if conflicts:
        lines.append(f"Skipped {len(conflicts)} conflicting shift{'s' if len(conflicts) != 1 else ''}.")
    notification = result.get("employee_notification") if isinstance(result.get("employee_notification"), dict) else {}
    if notification:
        if notification.get("ok"):
            lines.append(f"{employee.get('name') or 'The employee'} was notified.")
        else:
            lines.append(f"{employee.get('name') or 'The employee'} was scheduled, but {notification_status_text(notification)}.")
    return "\n".join(lines)


