def notify_employee_shift_created(
    *,
    result: dict[str, Any],
    account_id: str | None,
    created_by_phone: str | None,
) -> dict[str, Any]:
    if result.get("bulk"):
        notifications: list[dict[str, Any]] = []
        for item in result.get("results") if isinstance(result.get("results"), list) else []:
            if isinstance(item, dict) and item.get("ok"):
                notification = notify_employee_shift_created(result=item, account_id=account_id, created_by_phone=created_by_phone)
                item["employee_notification"] = notification
                notifications.append(notification)
        return {"ok": any(item.get("ok") for item in notifications), "notifications": notifications}
    employee = result.get("employee") if isinstance(result.get("employee"), dict) else {}
    created = result.get("created") if isinstance(result.get("created"), list) else []
    if not employee or not created:
        return {"ok": False, "error": "missing_employee_or_shift"}
    message = shift_creation_employee_message(created)
    # Phase E: route shift assignment through the delivery layer when enabled
    # (template -> email -> needs-follow-up). Default off keeps direct WhatsApp.
    if outbound_flow_enabled("shift"):
        first = created[0] if created else {}
        send_result = deliver_employee_notification(
            employee,
            flow="shift",
            template_key="shift_assigned",
            text=message,
            email_subject="Your shift schedule",
            account_id=account_id,
            company_code=require_company_code(first.get("company_code") or employee.get("company_code")),
            variables={
                "shift_date": format_shift_date(first.get("shift_date")),
                "shift_time": format_shift_time(first.get("start_time")),
                "location": first.get("location") or "",
            },
        )
    else:
        send_result = send_custom_employee_message(employee, account_id, message)
    with db_connect() as conn:
        with conn.cursor() as cur:
            for shift in created:
                record_shift_event(
                    cur,
                    shift=shift,
                    company_code=require_company_code(shift.get("company_code") or employee.get("company_code")),
                    event_type="employee_notified" if send_result.get("ok") else "employee_notification_failed",
                    payload={"message": message, "send": send_result, "shift_id": shift.get("shift_id")},
                    created_by_phone=created_by_phone,
                )
        conn.commit()
    return {"ok": bool(send_result.get("ok")), "message": message, "send": send_result}


def notify_employee_shift_cancelled(
    *,
    result: dict[str, Any],
    account_id: str | None,
    created_by_phone: str | None,
) -> dict[str, Any]:
    if result.get("bulk"):
        notifications: list[dict[str, Any]] = []
        for item in result.get("results") if isinstance(result.get("results"), list) else []:
            if isinstance(item, dict) and item.get("ok"):
                notification = notify_employee_shift_cancelled(result=item, account_id=account_id, created_by_phone=created_by_phone)
                item["employee_notification"] = notification
                notifications.append(notification)
        return {"ok": any(item.get("ok") for item in notifications), "notifications": notifications}
    employee = result.get("employee") if isinstance(result.get("employee"), dict) else {}
    cancelled = result.get("cancelled") if isinstance(result.get("cancelled"), list) else []
    if not employee or not cancelled:
        return {"ok": False, "error": "missing_employee_or_shift"}
    message = shift_cancellation_employee_message(cancelled)
    if outbound_flow_enabled("shift"):
        first = cancelled[0] if cancelled else {}
        send_result = deliver_employee_notification(
            employee,
            flow="shift",
            template_key="shift_cancelled",
            text=message,
            email_subject="A shift was cancelled",
            account_id=account_id,
            company_code=require_company_code(first.get("company_code") or employee.get("company_code")),
            variables={"shift_date": format_shift_date(first.get("shift_date"))},
        )
    else:
        send_result = send_custom_employee_message(employee, account_id, message)
    with db_connect() as conn:
        with conn.cursor() as cur:
            for shift in cancelled:
                record_shift_event(
                    cur,
                    shift=shift,
                    company_code=require_company_code(shift.get("company_code") or employee.get("company_code")),
                    event_type="employee_cancellation_notified" if send_result.get("ok") else "employee_cancellation_notification_failed",
                    payload={"message": message, "send": send_result, "shift_id": shift.get("shift_id")},
                    created_by_phone=created_by_phone,
                )
        conn.commit()
    return {"ok": bool(send_result.get("ok")), "message": message, "send": send_result}


def format_list_shifts_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok") and result.get("error") == "employee_outside_manager_scope":
        return "That employee is outside your manager scope."
    shifts = result.get("shifts") if isinstance(result.get("shifts"), list) else []
    if not shifts:
        if employee_view:
            return "You do not have any scheduled shifts for that period."
        return "No scheduled shifts found for that period."
    title = "Your shifts:" if employee_view else f"Scheduled shifts ({format_shift_date_range(result.get('start_date'), result.get('end_date'))}):"
    lines = [title]
    for shift in shifts[:20]:
        name = "" if employee_view else f"{shift.get('employee_name') or shift.get('employee_phone')} — "
        extra = []
        if shift.get("location"):
            extra.append(str(shift.get("location")))
        if shift.get("role"):
            extra.append(str(shift.get("role")))
        suffix = f" ({', '.join(extra)})" if extra else ""
        lines.append(f"- {format_shift_date(shift.get('shift_date'))}: {name}{format_shift_time(shift.get('start_time'))}-{format_shift_time(shift.get('end_time'))}{suffix}")
    if len(shifts) > 20:
        lines.append(f"And {len(shifts) - 20} more shifts.")
    return "\n".join(lines)


def format_cancel_shift_reply(result: dict[str, Any]) -> str:
    if result.get("bulk"):
        results = result.get("results") if isinstance(result.get("results"), list) else []
        lines = [f"Bulk shift cancellation complete: {result.get('completed_count', 0)}/{result.get('requested_count', len(results))} employees had shifts cancelled."]
        for item in results[:8]:
            if not isinstance(item, dict):
                continue
            employee = item.get("employee") if isinstance(item.get("employee"), dict) else {}
            name = employee.get("name") or employee.get("phone") or "Employee"
            cancelled_count = len(item.get("cancelled") if isinstance(item.get("cancelled"), list) else [])
            if item.get("ok"):
                note = f"{name}: {cancelled_count} shift{'s' if cancelled_count != 1 else ''}"
                notification = item.get("employee_notification") if isinstance(item.get("employee_notification"), dict) else {}
                if notification:
                    note += f", {notification_status_text(notification)}"
                lines.append(f"- {note}")
            else:
                lines.append(f"- {name}: no scheduled shifts found")
        unresolved = result.get("unresolved") if isinstance(result.get("unresolved"), list) else []
        if unresolved:
            lines.append(f"{len(unresolved)} employee reference{'s' if len(unresolved) != 1 else ''} could not be resolved.")
        if len(results) > 8:
            lines.append(f"And {len(results) - 8} more results.")
        return "\n".join(lines)
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if result.get("error") == "employee_not_found":
            return "I could not find that employee to cancel shifts."
        return "I could not find scheduled shifts to cancel for that employee and period."
    employee = result.get("employee") or {}
    count = len(result.get("cancelled") or [])
    reply = f"Cancelled {count} shift{'s' if count != 1 else ''} for {employee.get('name') or employee.get('phone')}."
    notification = result.get("employee_notification") if isinstance(result.get("employee_notification"), dict) else {}
    if notification:
        if notification.get("ok"):
            reply += f" {employee.get('name') or 'The employee'} was notified."
        else:
            reply += f" {employee.get('name') or 'The employee'} was cancelled, but {notification_status_text(notification)}."
    return reply


def format_request_availability_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok"):
        error = result.get("error")
        if error == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if error == "employee_not_found":
            return "I need the employee name or phone before recording availability."
        if error == "employee_company_mismatch":
            return "That employee does not belong to this company."
        return "I could not record availability safely."
    availability = result.get("availability") if isinstance(result.get("availability"), dict) else {}
    employee = result.get("employee") if isinstance(result.get("employee"), dict) else {}
    name = "your" if employee_view else f"{employee.get('name') or availability.get('employee_name') or 'Employee'}'s"
    date_text = format_shift_date_range(availability.get("start_date"), availability.get("end_date"))
    status = str(availability.get("status") or "requested")
    kind = display_status(availability.get("availability_type")).lower() or "availability"
    if employee_view:
        suffix = " HR has been notified." if status == "requested" else ""
        return f"I recorded your {kind} availability for {date_text}.{suffix}"
    return f"Recorded {name} {kind} availability for {date_text} ({display_status(status)})."


def format_list_availability_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok") and result.get("error") == "employee_outside_manager_scope":
        return "That employee is outside your manager scope."
    rows = result.get("availability") if isinstance(result.get("availability"), list) else []
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
