def is_employee_payroll_command(text: str) -> bool:
    normalized = normalize_text(text)
    if not normalized:
        return False
    if re.search(r"\b(export payroll|payroll export|policy|rate|salary|bank file|transfer|pay me|payment)\b", normalized):
        return True
    return bool(
        re.search(r"\b(my\s+)?(payroll|hours|worked|scheduled hours|overtime|late minutes|early leave|timesheets?|time sheets?|pay period)\b", normalized)
        or re.search(r"\bhow many hours\b", normalized)
    )


def handle_employee_payroll_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    employee = find_employee_by_phone(request.sender_phone)
    if not employee or not is_employee_payroll_command(request.raw_text):
        return None
    if not company_has_module(employee.get("company_code"), "payroll"):
        return {"error": "module_disabled", "company_code": employee.get("company_code"), "required_module": "payroll", "employee_key": employee.get("employee_key")}
    normalized = normalize_text(request.raw_text)
    if re.search(r"\b(export payroll|payroll export|policy|rate|salary|bank file|transfer|pay me|payment)\b", normalized):
        return {
            "reply": "I can show your own payroll hours and timesheet status. Salary amounts, payroll exports, bank files, and payments are handled by HR.",
            "employee_key": employee.get("employee_key"),
            "intent": "employee_payroll_boundary",
            "turn_focus": "employee_payroll",
            "result": {"ok": False, "error": "employee_payroll_boundary", "employee_key": employee.get("employee_key")},
        }
    company = employee.get("company_code")
    if re.search(r"\b(timesheets?|time sheets?|approved payroll|draft payroll|payroll approval)\b", normalized):
        action = infer_timesheet_action(request.raw_text, request=request) or {
            "action_type": "list_timesheets",
            "subject_type": "timesheet",
            "subject_phone": employee.get("phone"),
            "prompt_text": request.raw_text,
            "query": request.raw_text,
        }
        action["action_type"] = "list_timesheets"
        action["subject_phone"] = employee.get("phone")
        result = list_timesheets(action, company_code=company)
        return {"reply": format_list_timesheets_reply(result, employee_view=True), "employee_key": employee.get("employee_key"), "result": result, "intent": "list_timesheets", "turn_focus": "employee_payroll"}
    action = infer_payroll_action(request.raw_text, request=request) or {
        "action_type": "list_payroll_hours",
        "subject_type": "payroll",
        "subject_phone": employee.get("phone"),
        "prompt_text": request.raw_text,
        "query": request.raw_text,
    }
    action["subject_phone"] = employee.get("phone")
    result = list_payroll_hours(action, company_code=company)
    return {"reply": format_payroll_hours_reply(result, employee_view=True), "employee_key": employee.get("employee_key"), "result": result, "intent": "list_payroll_hours", "turn_focus": "employee_payroll"}


def run_shift_reminder_scan(*, account_id: str | None, dry_run: bool = True, limit: int = 50, hours_ahead: int = 2) -> dict[str, Any]:
    if _shifts_w2.shifts_wave2_enabled():
        return _run_shift_reminder_scan_wave2(account_id=account_id, dry_run=dry_run, limit=limit, hours_ahead=hours_ahead)
    now_local = datetime.now(KUWAIT_TZ).replace(tzinfo=None)
    until_local = now_local + timedelta(hours=max(1, min(hours_ahead, 24)))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT s.*, e.phone, e.name, e.email
                FROM shift_assignments s
                LEFT JOIN employees e ON e.employee_key=s.employee_key
                WHERE s.status='scheduled'
                  AND s.reminder_sent_at IS NULL
                  AND (s.shift_date + s.start_time) BETWEEN %s AND %s
                ORDER BY s.shift_date, s.start_time
                LIMIT %s
                """,
                (now_local, until_local, max(1, min(limit, 200))),
            )
            rows = [dict(row) for row in cur.fetchall()]
    results: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for shift in rows:
        if not company_has_module(shift.get("company_code"), "shifts"):
            skipped.append({"shift_id": str(shift.get("shift_id")), "company_code": shift.get("company_code"), "reason": "shifts_module_disabled"})
            continue
        try:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    import tenant_control_queue_gate as _tc_qg

                    company = str(shift.get("company_code") or "").upper()
                    work_ref = str(shift.get("shift_id"))
                    queued_epoch = _tc_qg.persist_work_epoch(
                        cur,
                        company_code=company,
                        work_kind="shift_reminder",
                        work_ref=work_ref,
                        module_key="shifts",
                    )
                    allowed, decision = _tc_qg.gate_or_skip(
                        cur,
                        company_code=company,
                        module_key="shifts",
                        work_kind="shift_reminder",
                        work_ref=work_ref,
                        queued_epoch=queued_epoch,
                        surface="timers",
                    )
                    conn.commit()
                    if not allowed:
                        skipped.append({
                            "shift_id": work_ref,
                            "company_code": company,
                            "reason": decision.reason_code,
                            "correlation_id": decision.audit_correlation_id,
                        })
                        continue
        except Exception:
            pass
        message = f"Reminder: your shift is on {format_shift_date(shift.get('shift_date'))} from {format_shift_time(shift.get('start_time'))} to {format_shift_time(shift.get('end_time'))}."
        entry = {"shift_id": str(shift.get("shift_id")), "employee_key": shift.get("employee_key"), "phone": shift.get("phone") or shift.get("employee_phone"), "message": message, "dry_run": dry_run}
        if not dry_run:
            employee = {"phone": shift.get("phone") or shift.get("employee_phone"), "email": shift.get("email"), "name": shift.get("name") or shift.get("employee_name"), "employee_key": shift.get("employee_key"), "company_code": shift.get("company_code")}
            if outbound_flow_enabled("shift"):
                send_result = deliver_employee_notification(
                    employee,
                    flow="shift",
                    template_key="shift_reminder",
                    text=message,
                    email_subject="Shift reminder",
                    account_id=account_id,
                    company_code=require_company_code(shift.get("company_code")),
                    variables={
                        "shift_date": format_shift_date(shift.get("shift_date")),
                        "shift_time": format_shift_time(shift.get("start_time")),
                    },
                )
            else:
                send_result = send_custom_employee_message(employee, account_id, message)
            entry["send"] = send_result
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute("UPDATE shift_assignments SET reminder_sent_at=now(), updated_at=now() WHERE shift_id=%s", (shift.get("shift_id"),))
                    record_shift_event(cur, shift=shift, company_code=str(shift.get("company_code") or ""), event_type=("reminder_sent" if send_result.get("ok") else "reminder_attempt_failed"), payload=entry, created_by_phone=None)
                conn.commit()
        results.append(entry)
    return {"ok": True, "dry_run": dry_run, "count": len(results), "skipped_count": len(skipped), "results": results, "skipped": skipped}


def _run_shift_reminder_scan_wave2(*, account_id: str | None, dry_run: bool = True, limit: int = 50, hours_ahead: int = 2) -> dict[str, Any]:
    """Durable queue: claim → send → sent|failed|terminal_failed. No duplicate sent rows."""
    results: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    terminal: list[dict[str, Any]] = []
    if not _shifts_w2.jobs_enabled():
        return {"ok": False, "error": "shifts_wave2_jobs_disabled", "killed": True, **_shifts_w2.honesty_payload()}
    # Ensure due scheduled shifts have queue rows (idempotent enqueue)
    now_local = datetime.now(KUWAIT_TZ).replace(tzinfo=None)
    until_local = now_local + timedelta(hours=max(1, min(hours_ahead, 24)))
    with db_connect() as conn:
        with conn.cursor() as cur:
            if not _shifts_w2.try_job_lock(cur, _shifts_w2.JOB_LOCK_REMINDER_DRAIN):
                return {"ok": False, "error": "job_lock_held", "job": "reminder_drain", **_shifts_w2.honesty_payload()}
            try:
                _shifts_w2.ensure_shifts_integrity_wave2_schema(cur)
                cur.execute(
                    """
                    SELECT s.* FROM shift_assignments s
                    WHERE s.status='scheduled'
                      AND (s.shift_date + s.start_time) BETWEEN %s AND %s
                    ORDER BY s.shift_date, s.start_time
                    LIMIT %s
                    """,
                    (now_local, until_local, max(1, min(limit * 2, 400))),
                )
                for row in cur.fetchall():
                    shift = dict(row)
                    if not company_has_module(shift.get("company_code"), "shifts"):
                        continue
                    if not _shifts_w2_applies(shift.get("company_code"), shift):
                        continue
                    _shifts_w2.enqueue_shift_reminder(
                        cur, company_code=str(shift.get("company_code")), shift=shift, hours_before=hours_ahead
                    )
                if dry_run:
                    cur.execute(
                        """
                        SELECT * FROM shift_reminder_queue
                        WHERE status IN ('pending','failed')
                          AND COALESCE(next_attempt_at, planned_send_at) <= now()
                        ORDER BY planned_send_at LIMIT %s
                        """,
                        (max(1, min(limit, 200)),),
                    )
                    due = _shifts_w2.filter_reminders_synthetic_only([dict(r) for r in cur.fetchall()])
                    terminal = _shifts_w2.filter_reminders_synthetic_only(
                        _shifts_w2.list_terminal_reminder_failures(cur, company_code="WATHEFNI")
                    )
                    conn.commit()
                    return {
                        "ok": True,
                        "dry_run": True,
                        "count": len(due),
                        "results": [{"reminder_id": str(r.get("reminder_id")), "shift_id": str(r.get("shift_id")), "status": r.get("status")} for r in due],
                        "skipped": skipped,
                        "terminal_failures": terminal,
                        **_shifts_w2.honesty_payload(),
                    }
                claimed_raw = _shifts_w2.claim_due_reminders(cur, limit=limit)
                claimed = []
                for rem in claimed_raw:
                    if _shifts_w2_applies(
                        rem.get("company_code"),
                        employee_key=rem.get("employee_key"),
                    ):
                        claimed.append(rem)
                    else:
                        # Release non-synthetic claims under synthetic-only posture
                        cur.execute(
                            """
                            UPDATE shift_reminder_queue
                            SET status='pending', claimed_at=NULL,
                                attempt_count=GREATEST(attempt_count-1, 0), updated_at=now()
                            WHERE reminder_id=%s AND status='claimed'
                            """,
                            (rem.get("reminder_id"),),
                        )
                conn.commit()
            finally:
                _shifts_w2.release_job_lock(cur, _shifts_w2.JOB_LOCK_REMINDER_DRAIN)
    for rem in claimed:
        company = require_company_code(rem.get("company_code"))
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT s.*, e.phone, e.name, e.email FROM shift_assignments s LEFT JOIN employees e ON e.employee_key=s.employee_key WHERE s.shift_id=%s", (rem.get("shift_id"),))
                shift_row = cur.fetchone()
                if not shift_row or str(dict(shift_row).get("status")) != "scheduled":
                    _shifts_w2.complete_reminder_send(cur, reminder=rem, ok=False, error="shift_not_scheduled")
                    conn.commit()
                    skipped.append({"reminder_id": str(rem.get("reminder_id")), "reason": "shift_not_scheduled"})
                    continue
                shift = dict(shift_row)
                # Idempotent: already sent for this window
                cur.execute(
                    """
                    SELECT 1 FROM shift_reminder_queue
                    WHERE company_code=%s AND shift_id=%s AND status='sent'
                      AND idempotency_key=%s LIMIT 1
                    """,
                    (company, rem.get("shift_id"), rem.get("idempotency_key")),
                )
                if cur.fetchone() and str(rem.get("status")) != "claimed":
                    conn.commit()
                    continue
                message = f"Reminder: your shift is on {format_shift_date(shift.get('shift_date'))} from {format_shift_time(shift.get('start_time'))} to {format_shift_time(shift.get('end_time'))}."
                employee = {"phone": shift.get("phone") or shift.get("employee_phone"), "email": shift.get("email"), "name": shift.get("name") or shift.get("employee_name"), "employee_key": shift.get("employee_key"), "company_code": company}
                try:
                    if outbound_flow_enabled("shift"):
                        send_result = deliver_employee_notification(
                            employee,
                            flow="shift",
                            template_key="shift_reminder",
                            text=message,
                            email_subject="Shift reminder",
                            account_id=account_id,
                            company_code=company,
                            variables={"shift_date": format_shift_date(shift.get("shift_date")), "shift_time": format_shift_time(shift.get("start_time"))},
                        )
                    else:
                        send_result = send_custom_employee_message(employee, account_id, message)
                except Exception as exc:
                    send_result = {"ok": False, "error": str(exc)}
                integ = _shifts_w2.get_integrity_settings(cur, company)
                completed = _shifts_w2.complete_reminder_send(
                    cur,
                    reminder=rem,
                    ok=bool(send_result.get("ok")),
                    error=None if send_result.get("ok") else str(send_result.get("error") or "send_failed"),
                    delivery_ref=str(send_result.get("message_id") or send_result.get("id") or "") or None,
                    backoff_seconds=int(integ.get("reminder_backoff_seconds") or 300),
                )
                record_shift_event(
                    cur,
                    shift=shift,
                    company_code=company,
                    event_type=("reminder_sent" if send_result.get("ok") else "reminder_attempt_failed"),
                    payload={"reminder": completed, "send": send_result},
                    created_by_phone=None,
                )
                conn.commit()
                entry = {"reminder_id": str(rem.get("reminder_id")), "shift_id": str(shift.get("shift_id")), "status": completed.get("status"), "send": send_result}
                results.append(entry)
                if completed.get("status") == "terminal_failed":
                    terminal.append(entry)
    with db_connect() as conn:
        with conn.cursor() as cur:
            vis = _shifts_w2.list_terminal_reminder_failures(cur, company_code="WATHEFNI", limit=50)
    return {
        "ok": True,
        "dry_run": False,
        "count": len(results),
        "skipped_count": len(skipped),
        "results": results,
        "skipped": skipped,
        "terminal_failures": vis,
        **_shifts_w2.honesty_payload(),
    }



def run_attendance_absence_scan(*, account_id: str | None, dry_run: bool = True, limit: int = 50, grace_minutes: int = 30) -> dict[str, Any]:
    now_local = datetime.now(KUWAIT_TZ).replace(tzinfo=None)
    cutoff = now_local - timedelta(minutes=max(1, min(grace_minutes, 240)))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT s.*, e.phone, e.name, lr.leave_id AS approved_leave_id
                FROM shift_assignments s
                LEFT JOIN employees e ON e.employee_key=s.employee_key
                LEFT JOIN attendance_records ar
                  ON ar.shift_id=s.shift_id
                 AND ar.employee_key=s.employee_key
                 AND ar.company_code=s.company_code
                LEFT JOIN leave_requests lr
                  ON lr.company_code=s.company_code
                 AND lr.employee_key=s.employee_key
                 AND lr.status='approved'
                 AND lr.start_date <= s.shift_date
                 AND lr.end_date >= s.shift_date
                WHERE s.status='scheduled'
                  AND (s.shift_date + s.start_time) < %s
                  AND ar.attendance_id IS NULL
                ORDER BY s.shift_date, s.start_time
                LIMIT %s
                """,
                (cutoff, max(1, min(limit, 200))),
            )
            rows = [dict(row) for row in cur.fetchall()]
    results: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for shift in rows:
        company = require_company_code(shift.get("company_code"))
        if not company_has_module(company, "attendance"):
            skipped.append({"shift_id": str(shift.get("shift_id")), "company_code": company, "reason": "attendance_module_disabled"})
            continue
        employee = {"employee_key": shift.get("employee_key"), "phone": shift.get("phone") or shift.get("employee_phone"), "name": shift.get("name") or shift.get("employee_name"), "company_code": company}
        action = {"action_type": "mark_attendance_absent", "subject_phone": employee.get("phone"), "date": shift_sheet_cell(shift.get("shift_date")), "shift_id": str(shift.get("shift_id")), "allow_without_shift": False, "notes": "Auto no-show scan"}
        entry = {"shift_id": str(shift.get("shift_id")), "employee": employee, "dry_run": dry_run}
        if shift.get("approved_leave_id"):
            entry["approved_leave_id"] = str(shift.get("approved_leave_id"))
            if not dry_run:
                with db_connect() as conn:
                    with conn.cursor() as cur:
                        attendance = upsert_attendance_record(
                            cur,
                            company=company,
                            employee=employee,
                            shift=shift,
                            attendance_date=parse_shift_date_value(shift.get("shift_date")) or kuwait_today(),
                            status="approved_leave",
                            notes="Approved leave",
                            source_text="Auto no-show scan",
                            created_by_phone=None,
                            action={"action_type": "attendance_approved_leave_scan", "leave_id": str(shift.get("approved_leave_id"))},
                        )
                        record_attendance_event(cur, attendance=attendance, company_code=company, event_type="approved_leave", payload={"attendance": attendance, "shift": shift, "leave_id": str(shift.get("approved_leave_id"))}, created_by_phone=None)
                    conn.commit()
                entry["result"] = {"ok": True, "attendance": json_safe(attendance)}
            results.append(entry)
            continue
        if not dry_run:
            result = mark_attendance_absent(action, company_code=company, created_by_phone=None)
            if result.get("ok"):
                result["hr_notification"] = notify_attendance_exception(result, account_id=account_id, event_type="marked_absent")
            entry["result"] = result
        results.append(entry)
    return {"ok": True, "dry_run": dry_run, "count": len(results), "skipped_count": len(skipped), "results": results, "skipped": skipped}




def find_next_required_onboarding_item(employee_key: str, *, company_code: str | None = None) -> dict[str, Any] | None:
    """Next required pending checklist item. Skips bank_details (ESS-only collection)."""
    items = load_onboarding_items(employee_key=employee_key, company_code=company_code)
    for item in items:
        if item.get("required") is not True:
            continue
        if str(item.get("item_id") or "") == "bank_details":
            continue  # encrypted ESS bank workflow — not WhatsApp/checklist plaintext
        import onboarding_completion_contract as _completion

        if str(item.get("status") or "").lower() in set(_completion.EMPLOYEE_ACTION_STATUSES):
            return item
    return None


def recompute_employee_onboarding_counts(
    cur: Any, employee_key: str, *, actor: str | None = None
) -> dict[str, Any] | None:
    """Single writer for employee-level onboarding completion.

    Delegates to the canonical contract, which also mirrors the legacy
    employees.* columns so no surface can disagree.
    """
    import onboarding_completion_contract as _completion

    try:
        return _completion.recompute(cur, employee_key=employee_key, actor=actor)
    except Exception:
        logger.exception("onboarding completion recompute failed employee=%s", employee_key)
        # Legacy fallback keeps counts moving if the contract table is unavailable.
        satisfied = _completion.sql_satisfied_list()
        closed = _completion.sql_closed_list()
        cur.execute(
            f"""
            SELECT
              COUNT(*) FILTER (
                WHERE required IS TRUE AND lower(coalesce(status,'')) NOT IN ({closed})
              ) AS pending,
              COUNT(*) FILTER (
                WHERE required IS TRUE AND lower(coalesce(status,'')) IN ({satisfied})
              ) AS complete
            FROM onboarding_items
            WHERE employee_key=%s
            """,
            (employee_key,),
        )
        row = cur.fetchone() or {}
        pending = int(row.get("pending") or 0)
        complete = int(row.get("complete") or 0)
        status = "completed" if pending == 0 and complete > 0 else "in_progress"
        # updated_at intentionally untouched: see the note in the contract's
        # legacy mirror about ESS optimistic concurrency.
        cur.execute(
            "SELECT company_code FROM employees WHERE employee_key=%s LIMIT 1",
            (employee_key,),
        )
        company = str((cur.fetchone() or {}).get("company_code") or "")
        cur.execute(
            """
            UPDATE employees
            SET documents_pending=%s, documents_complete=%s, onboarding_status=%s
            WHERE employee_key=%s AND company_code=%s
            """,
            (pending, complete, status, employee_key, company),
        )
        return None


def safe_storage_name(value: str | None, default: str = "document") -> str:
    name = re.sub(r"[^A-Za-z0-9._-]+", "-", value or "").strip("-._")
    return name[:120] or default


def sha256_file(path: Path) -> str | None:
    try:
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()
    except Exception:
        return None


def storage_env_value(env_values: dict[str, str], company_code: str, key: str) -> str | None:
    company_key = f"{company_code.upper()}_{key}"
    return env_values.get(company_key) or env_values.get(f"WATHEFNI_{key}") or env_values.get(key)


def document_storage_config(company_code: str | None) -> dict[str, Any]:
    company = require_company_code(company_code)
    env_values = planner_env()
    config_path = WORKSPACE / "data" / "companies" / company / "document-storage.json"
    file_config = read_json(config_path, {}) if config_path.exists() else {}
    drive_folder_id = (
        storage_env_value(env_values, company, "DOCUMENT_DRIVE_FOLDER_ID")
        or storage_env_value(env_values, company, "DRIVE_FOLDER_ID")
        or file_config.get("drive_folder_id")
        or file_config.get("parent_folder_id")
    )
    configured_provider = (
        storage_env_value(env_values, company, "DOCUMENT_STORAGE_PROVIDER")
        or file_config.get("provider")
        or "local"
    )
    fallback_provider = (
        storage_env_value(env_values, company, "DOCUMENT_STORAGE_FALLBACK_PROVIDER")
        or file_config.get("fallback_provider")
        or "local"
    )
    return {
        "company_code": company,
        "provider": str(configured_provider or "local").strip().lower(),
        "fallback_provider": str(fallback_provider or "local").strip().lower(),
        "drive_folder_id": str(drive_folder_id).strip() if drive_folder_id else None,
        "local_root": str(file_config.get("local_root") or (WORKSPACE / "data" / "companies" / company / "employees")),
    }


def run_gog_wathefni(args: list[str], timeout: int = 90) -> dict[str, Any]:
    env_vars = os.environ.copy()
    env_vars.update(openclaw_env())
    proc = subprocess.run(["gog-wathefni", *args, "--json", "--no-input"], text=True, capture_output=True, timeout=timeout, env=env_vars)
    output = (proc.stdout or "").strip()
    parsed: Any = None
    if output:
        try:
            parsed = json.loads(output)
        except Exception:
            parsed = output
    return {
        "ok": proc.returncode == 0,
        "returncode": proc.returncode,
        "stdout": output[-2000:],
        "stderr": (proc.stderr or "")[-2000:],
        "json": parsed,
    }


def parse_drive_upload_result(result: dict[str, Any]) -> dict[str, Any]:
    payload = result.get("json")
    if not isinstance(payload, dict):
        return {}
    file_obj = payload.get("file") if isinstance(payload.get("file"), dict) else payload
    return {
        "external_file_id": file_obj.get("id") or file_obj.get("fileId"),
        "storage_url": file_obj.get("webViewLink") or file_obj.get("webContentLink") or file_obj.get("url"),
        "raw": payload,
    }


def store_document_local(
    *,
    employee: dict[str, Any],
    item_id: str,
    source_path: Path,
    mime_type: str,
    checksum: str | None,
    config: dict[str, Any],
    operation_trace: str | None = None,
) -> dict[str, Any]:
    phone = digits(employee.get("phone")) or "unknown-phone"
    company = require_company_code(config.get("company_code") or employee.get("company_code"))
    ext = source_path.suffix or mimetypes.guess_extension(mime_type) or ".bin"
    trace_suffix = f"-{safe_storage_name(operation_trace)[:32]}" if operation_trace else ""
    file_name = f"{safe_storage_name(item_id)}-{(checksum or uuid.uuid4().hex)[:12]}{trace_suffix}{ext}"
    destination_dir = Path(str(config.get("local_root") or "")) / phone / "documents" / safe_storage_name(item_id)
    destination_dir.mkdir(parents=True, exist_ok=True)
    destination_path = destination_dir / file_name
    if source_path.resolve() != destination_path.resolve():
        shutil.copy2(source_path, destination_path)
    try:
        object_key = str(destination_path.relative_to(WORKSPACE))
    except Exception:
        object_key = str(destination_path)
    return {
        "ok": True,
        "provider": "local",
        "storage_status": "stored",
        "storage_object_key": object_key,
        "storage_url": f"local://{object_key}",
        "external_file_id": None,
        "drive_file_id": None,
        "drive_url": None,
        "content_sha256": checksum,
        "mime_type": mime_type,
        "stored_at": now_iso(),
        "metadata": {"company_code": company, "local_path": str(destination_path)},
    }


def store_document_google_drive(
    *,
    employee: dict[str, Any],
    item_id: str,
    source_path: Path,
    mime_type: str,
    checksum: str | None,
    config: dict[str, Any],
    operation_trace: str | None = None,
) -> dict[str, Any]:
    folder_id = config.get("drive_folder_id")
    if not folder_id:
        return {"ok": False, "provider": "google_drive", "storage_status": "failed", "storage_error": "missing_drive_folder_id"}
    phone = digits(employee.get("phone")) or "unknown-phone"
    company = require_company_code(config.get("company_code") or employee.get("company_code"))
    ext = source_path.suffix or mimetypes.guess_extension(mime_type) or ".bin"
    trace_suffix = f"-{safe_storage_name(operation_trace)[:32]}" if operation_trace else ""
    upload_name = f"{company}-{phone}-{safe_storage_name(item_id)}-{(checksum or uuid.uuid4().hex)[:12]}{trace_suffix}{ext}"
    result = run_gog_wathefni(
        [
            "drive",
            "upload",
            str(source_path),
            "--name",
            upload_name,
            "--parent",
            str(folder_id),
            "--mime-type",
            mime_type,
        ],
        timeout=120,
    )
    if not result.get("ok"):
        return {
            "ok": False,
            "provider": "google_drive",
            "storage_status": "failed",
            "storage_error": result.get("stderr") or result.get("stdout") or "drive_upload_failed",
            "raw": result,
        }
    parsed = parse_drive_upload_result(result)
    external_file_id = parsed.get("external_file_id")
    storage_url = parsed.get("storage_url")
    return {
        "ok": bool(external_file_id or storage_url),
        "provider": "google_drive",
        "storage_status": "stored",
        "storage_object_key": external_file_id,
        "storage_url": storage_url,
        "external_file_id": external_file_id,
        "drive_file_id": external_file_id,
        "drive_url": storage_url,
        "content_sha256": checksum,
        "mime_type": mime_type,
        "stored_at": now_iso(),
        "metadata": {"drive": parsed.get("raw"), "upload_name": upload_name},
    }


def store_onboarding_document(
    *,
    employee: dict[str, Any],
    item_id: str,
    media: dict[str, Any] | None,
    operation_trace: str | None = None,
) -> dict[str, Any]:
    if not has_current_media_upload(media):
        return {"ok": True, "provider": "metadata_only", "storage_status": "not_required", "metadata": {}}
    source = Path(str((media or {}).get("path") or ""))
    if not source.exists() or not source.is_file():
        return {"ok": False, "provider": "local", "storage_status": "failed", "storage_error": "missing_local_media_file"}
    mime_type = str((media or {}).get("type") or (media or {}).get("mime_type") or "").strip()
    if "/" not in mime_type:
        mime_type = mimetypes.guess_type(source.name)[0] or "application/octet-stream"
    checksum = sha256_file(source)
    config = document_storage_config(employee.get("company_code"))
    provider = str(config.get("provider") or "local")
    if provider == "google_drive":
        primary = store_document_google_drive(
            employee=employee,
            item_id=item_id,
            source_path=source,
            mime_type=mime_type,
            checksum=checksum,
            config=config,
            operation_trace=operation_trace,
        )
        if primary.get("ok"):
            return primary
        if config.get("fallback_provider") == "local":
            fallback = store_document_local(
                employee=employee,
                item_id=item_id,
                source_path=source,
                mime_type=mime_type,
                checksum=checksum,
                config=config,
                operation_trace=operation_trace,
            )
            fallback["storage_status"] = "stored_with_fallback"
            fallback["primary_provider"] = "google_drive"
            fallback["storage_error"] = primary.get("storage_error")
            return fallback
        return primary
    return store_document_local(
        employee=employee,
        item_id=item_id,
        source_path=source,
        mime_type=mime_type,
        checksum=checksum,
        config=config,
        operation_trace=operation_trace,
    )


_DOCUMENT_STORAGE_MAX_ATTEMPTS = 8
_DOCUMENT_STORAGE_BACKOFF_SECONDS = (60, 300, 900, 3600, 21600, 86400, 86400, 86400)
_DOCUMENT_STORAGE_TERMINAL = {"canonical_committed", "compensated", "storage_failed", "manual_review"}


def prepare_document_storage_operation(
    *,
    employee: dict[str, Any],
    item_id: str,
) -> dict[str, Any]:
    company = str(employee.get("company_code") or "").strip().upper()
    employee_key = str(employee.get("employee_key") or "").strip()
    operation_id = str(uuid.uuid4())
    trace_key = operation_id.replace("-", "")
    config = document_storage_config(company)
    provider = str(config.get("provider") or "local")
    provider_scope = (
        str(config.get("drive_folder_id") or "")
        if provider == "google_drive"
        else str(Path(str(config.get("local_root") or "")).resolve())
    )
    metadata = {
        "planned_provider": provider,
        "fallback_provider": config.get("fallback_provider"),
        "planned_drive_folder_id": config.get("drive_folder_id"),
        "planned_local_root": str(Path(str(config.get("local_root") or "")).resolve()),
    }
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO document_storage_operations (
                    operation_id, company_code, employee_key, item_id, provider,
                    provider_scope, trace_key, status, next_attempt_at, metadata
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,'prepared',now() + interval '5 minutes',%s)
                RETURNING *
                """,
                (
                    operation_id,
                    company,
                    employee_key,
                    str(item_id),
                    provider,
                    provider_scope or None,
                    trace_key,
                    Json(metadata),
                ),
            )
            row = dict(cur.fetchone())
        conn.commit()
    return row


def update_document_storage_operation_after_store(
    operation_id: str,
    *,
    storage_result: dict[str, Any],
    config: dict[str, Any],
) -> dict[str, Any]:
    provider = str(storage_result.get("provider") or config.get("provider") or "local")
    provider_scope = (
        str(config.get("drive_folder_id") or "")
        if provider == "google_drive"
        else str(Path(str(config.get("local_root") or "")).resolve())
    )
    ok = bool(storage_result.get("ok")) and str(storage_result.get("storage_status") or "") != "failed"
    status = "stored" if ok else "storage_failed"
    failure = None if ok else str(storage_result.get("storage_error") or "storage_failed")[:500]
    metadata = {
        "storage_status": storage_result.get("storage_status"),
        "primary_provider": storage_result.get("primary_provider"),
        "upload_name": (storage_result.get("metadata") or {}).get("upload_name"),
    }
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE document_storage_operations
                SET provider=%s, provider_scope=%s, storage_object_key=%s,
                    external_file_id=%s, content_sha256=%s, status=%s,
                    failure_reason=%s, metadata=metadata || %s::jsonb,
                    stored_at=CASE WHEN %s THEN now() ELSE stored_at END,
                    next_attempt_at=CASE WHEN %s THEN now() + interval '5 minutes' ELSE NULL END,
                    updated_at=now()
                WHERE operation_id=%s AND status='prepared'
                RETURNING *
                """,
                (
                    provider,
                    provider_scope or None,
                    storage_result.get("storage_object_key"),
                    storage_result.get("external_file_id"),
                    storage_result.get("content_sha256"),
                    status,
                    failure,
                    Json(metadata),
                    ok,
                    ok,
                    operation_id,
                ),
            )
            row = cur.fetchone()
            if not row:
                raise RuntimeError("document_storage_operation_not_prepared")
            result = dict(row)
        conn.commit()
    return result


def document_storage_operation(operation_id: str) -> dict[str, Any] | None:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM document_storage_operations WHERE operation_id=%s", (operation_id,))
            row = cur.fetchone()
    return dict(row) if row else None


def document_storage_canonical_references(cur: Any, operation: dict[str, Any]) -> list[dict[str, Any]]:
    company = str(operation.get("company_code") or "").upper()
    provider = str(operation.get("provider") or "")
    object_key = str(operation.get("storage_object_key") or "")
    external_id = str(operation.get("external_file_id") or "")
    if not object_key and not external_id:
        return []
    refs: list[dict[str, Any]] = []
    object_params = (provider, object_key, object_key, external_id, external_id)
    direct_queries = (
        (
            "onboarding_items",
            """
            SELECT e.company_code
            FROM onboarding_items oi
            JOIN employees e ON e.employee_key=oi.employee_key
            WHERE COALESCE(oi.storage_provider,'')=%s
              AND ((%s <> '' AND COALESCE(oi.storage_object_key,'')=%s)
                   OR (%s <> '' AND COALESCE(oi.external_file_id,'')=%s))
            LIMIT 5
            """,
        ),
        (
            "employee_documents",
            """
            SELECT company_code
            FROM employee_documents
            WHERE COALESCE(storage_provider,'')=%s
              AND ((%s <> '' AND COALESCE(storage_object_key,'')=%s)
                   OR (%s <> '' AND COALESCE(external_file_id,'')=%s))
            LIMIT 5
            """,
        ),
        (
            "file_registry",
            """
            SELECT company_code
            FROM file_registry
            WHERE COALESCE(storage_provider,'')=%s
              AND ((%s <> '' AND COALESCE(storage_object_key,'')=%s)
                   OR (%s <> '' AND COALESCE(external_file_id,'')=%s))
            LIMIT 5
            """,
        ),
    )
    for table, query in direct_queries:
        cur.execute(query, object_params)
        for row in cur.fetchall() or []:
            refs.append({"table": table, "company_code": row.get("company_code"), "expected_company": company})
    needle = external_id or object_key
    if needle:
        cur.execute(
            """
            SELECT company_code
            FROM compliance_documents
            WHERE raw_json::text LIKE %s
            LIMIT 5
            """,
            (f"%{needle}%",),
        )
        for row in cur.fetchall() or []:
            refs.append({"table": "compliance_documents", "company_code": row.get("company_code"), "expected_company": company})
    return refs


def _document_storage_drive_file(result: dict[str, Any]) -> dict[str, Any]:
    payload = result.get("json")
    if not isinstance(payload, dict):
        return {}
    candidate = payload.get("file") if isinstance(payload.get("file"), dict) else payload
    return dict(candidate) if isinstance(candidate, dict) else {}


def _document_storage_already_missing(result: dict[str, Any]) -> bool:
    text = f"{result.get('stderr') or ''} {result.get('stdout') or ''}".lower()
    return any(marker in text for marker in ("not found", "404", "file not found"))


def delete_document_storage_object(operation: dict[str, Any]) -> dict[str, Any]:
    provider = str(operation.get("provider") or "")
    company = str(operation.get("company_code") or "").upper()
    trace = str(operation.get("trace_key") or "")
    object_key = str(operation.get("storage_object_key") or "")
    recorded_scope = str(operation.get("provider_scope") or "")
    config = document_storage_config(company)
    if provider == "local":
        current_scope = Path(str(config.get("local_root") or "")).resolve()
        recorded_root = Path("/")
        try:
            recorded_root = Path(recorded_scope).resolve()
            object_path = Path(object_key)
            object_path = object_path.resolve() if object_path.is_absolute() else (WORKSPACE / object_path).resolve()
            in_scope = object_path.is_relative_to(recorded_root) and object_path.is_relative_to(current_scope)
        except Exception:
            in_scope = False
            object_path = Path("/")
        item_component = safe_storage_name(str(operation.get("item_id") or ""))
        if recorded_root != current_scope or not in_scope or trace not in object_path.name or item_component not in object_path.parts:
            return {"ok": False, "outcome": "ownership_mismatch", "terminal": True}
        if not object_path.exists():
            return {"ok": True, "outcome": "already_missing"}
        try:
            object_path.unlink()
            return {"ok": True, "outcome": "deleted"}
        except FileNotFoundError:
            return {"ok": True, "outcome": "already_missing"}
        except Exception as exc:
            return {"ok": False, "outcome": "delete_failed", "error": type(exc).__name__}
    if provider == "google_drive":
        current_scope = str(config.get("drive_folder_id") or "")
        if not object_key or not recorded_scope or recorded_scope != current_scope:
            return {"ok": False, "outcome": "ownership_mismatch", "terminal": True}
        inspected = run_gog_wathefni(["drive", "get", object_key], timeout=45)
        if not inspected.get("ok"):
            if _document_storage_already_missing(inspected):
                return {"ok": True, "outcome": "already_missing"}
            return {"ok": False, "outcome": "inspect_unknown", "error": "drive_get_failed"}
        file_obj = _document_storage_drive_file(inspected)
        parents = file_obj.get("parents") if isinstance(file_obj.get("parents"), list) else []
        name = str(file_obj.get("name") or "")
        if (
            str(file_obj.get("id") or file_obj.get("fileId") or "") != object_key
            or recorded_scope not in parents
            or trace not in name
            or company not in name.upper()
            or safe_storage_name(str(operation.get("item_id") or "")) not in name
        ):
            return {"ok": False, "outcome": "ownership_mismatch", "terminal": True}
        deleted = run_gog_wathefni(["drive", "delete", object_key, "--permanent", "--force"], timeout=60)
        if deleted.get("ok") or _document_storage_already_missing(deleted):
            return {"ok": True, "outcome": "deleted" if deleted.get("ok") else "already_missing"}
        return {"ok": False, "outcome": "delete_unknown", "error": "drive_delete_failed"}
    return {"ok": False, "outcome": "unsupported_provider", "terminal": True}


def _document_storage_next_attempt(attempt_count: int) -> datetime:
    index = min(max(attempt_count - 1, 0), len(_DOCUMENT_STORAGE_BACKOFF_SECONDS) - 1)
    return now_utc() + timedelta(seconds=_DOCUMENT_STORAGE_BACKOFF_SECONDS[index])


def _record_document_storage_operator_event(operation: dict[str, Any], outcome: str) -> None:
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO action_results (
                        action_type, status, result, final_reply, company_code,
                        actor_user_id, actor_role
                    )
                    VALUES ('document_storage_reconciliation',%s,%s,%s,%s,'system:document-storage-reconcile','system')
                    """,
                    (
                        "failed" if outcome == "manual_review" else "completed",
                        Json(
                            {
                                "operation_id": str(operation.get("operation_id")),
                                "company_code": operation.get("company_code"),
                                "employee_key": operation.get("employee_key"),
                                "item_id": operation.get("item_id"),
                                "provider": operation.get("provider"),
                                "outcome": outcome,
                            }
                        ),
                        f"Document storage reconciliation {outcome}.",
                        operation.get("company_code"),
                    ),
                )
            conn.commit()
    except Exception:
        logger.warning("document storage operator audit failed", exc_info=True)


def recover_prepared_document_storage_operation(operation: dict[str, Any]) -> dict[str, Any]:
    trace = str(operation.get("trace_key") or "")
    company = str(operation.get("company_code") or "").upper()
    metadata = operation.get("metadata") if isinstance(operation.get("metadata"), dict) else {}
    candidates: list[dict[str, Any]] = []
    local_root = Path(str(metadata.get("planned_local_root") or ""))
    if local_root.is_dir():
        matches = [path for path in local_root.rglob(f"*{trace}*") if path.is_file()]
        if len(matches) == 1:
            path = matches[0]
            candidates.append(
                {
                    "provider": "local",
                    "provider_scope": str(local_root.resolve()),
                    "storage_object_key": storage_object_key_for_path(path),
                    "external_file_id": None,
                }
            )
        elif len(matches) > 1:
            return {"ok": False, "outcome": "ambiguous_trace", "terminal": True}
    drive_folder = str(metadata.get("planned_drive_folder_id") or "")
    if drive_folder:
        searched = run_gog_wathefni(["drive", "search", trace], timeout=45)
        if not searched.get("ok"):
            return {"ok": False, "outcome": "recovery_unknown", "terminal": False}
        payload = searched.get("json")
        files = []
        if isinstance(payload, dict):
            files = payload.get("files") or payload.get("items") or []
        if isinstance(files, list):
            drive_matches = [
                item
                for item in files
                if isinstance(item, dict)
                and trace in str(item.get("name") or "")
                and drive_folder in (item.get("parents") or [])
            ]
            if len(drive_matches) == 1:
                drive_file = drive_matches[0]
                file_id = drive_file.get("id") or drive_file.get("fileId")
                candidates.append(
                    {
                        "provider": "google_drive",
                        "provider_scope": drive_folder,
                        "storage_object_key": file_id,
                        "external_file_id": file_id,
                    }
                )
            elif len(drive_matches) > 1:
                return {"ok": False, "outcome": "ambiguous_trace", "terminal": True}
    if not candidates:
        return {"ok": True, "outcome": "already_missing"}
    if len(candidates) != 1:
        return {"ok": False, "outcome": "ambiguous_trace", "terminal": True}
    candidate = candidates[0]
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE document_storage_operations
                SET provider=%s, provider_scope=%s, storage_object_key=%s,
                    external_file_id=%s, status='stored', stored_at=COALESCE(stored_at,now()),
                    next_attempt_at=now(), updated_at=now()
                WHERE operation_id=%s AND status='prepared'
                RETURNING *
                """,
                (
                    candidate["provider"],
                    candidate["provider_scope"],
                    candidate["storage_object_key"],
                    candidate["external_file_id"],
                    operation["operation_id"],
                ),
            )
            row = cur.fetchone()
        conn.commit()
    return {"ok": True, "outcome": "recovered", "operation": dict(row) if row else operation}


def reconcile_document_storage_operation(operation_id: str, *, lease_owner: str | None = None) -> dict[str, Any]:
    worker = str(lease_owner or f"pid-{os.getpid()}")[:120]
    operation: dict[str, Any] | None = None
    try:
        operation = document_storage_operation(operation_id)
        if not operation:
            return {"ok": True, "outcome": "operation_missing"}
        if operation.get("status") in _DOCUMENT_STORAGE_TERMINAL:
            return {"ok": True, "outcome": operation.get("status")}
        if operation.get("status") == "prepared":
            recovered = recover_prepared_document_storage_operation(operation)
            if recovered.get("terminal"):
                with db_connect() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """
                            UPDATE document_storage_operations
                            SET status='manual_review', failure_reason=%s, next_attempt_at=NULL, updated_at=now()
                            WHERE operation_id=%s AND status='prepared'
                            RETURNING *
                            """,
                            (recovered.get("outcome"), operation_id),
                        )
                        row = cur.fetchone()
                    conn.commit()
                if row:
                    _record_document_storage_operator_event(dict(row), "manual_review")
                return {"ok": False, **recovered}
            if not recovered.get("ok"):
                recovery_attempt = int(operation.get("attempt_count") or 0) + 1
                recovery_terminal = recovery_attempt >= _DOCUMENT_STORAGE_MAX_ATTEMPTS
                with db_connect() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """
                            UPDATE document_storage_operations
                            SET status=%s, failure_reason=%s, attempt_count=%s,
                                next_attempt_at=%s, updated_at=now()
                            WHERE operation_id=%s AND status='prepared'
                            RETURNING *
                            """,
                            (
                                "manual_review" if recovery_terminal else "prepared",
                                recovered.get("outcome"),
                                recovery_attempt,
                                None if recovery_terminal else _document_storage_next_attempt(recovery_attempt),
                                operation_id,
                            ),
                        )
                        row = cur.fetchone()
                    conn.commit()
                if recovery_terminal and row:
                    _record_document_storage_operator_event(dict(row), "manual_review")
                return {"ok": False, **recovered}
            if recovered.get("outcome") == "already_missing":
                with db_connect() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """
                            UPDATE document_storage_operations
                            SET status='compensated', compensated_at=now(), next_attempt_at=NULL, updated_at=now()
                            WHERE operation_id=%s AND status='prepared'
                            """,
                            (operation_id,),
                        )
                    conn.commit()
                return {"ok": True, "outcome": "already_missing"}
            operation = recovered.get("operation") or document_storage_operation(operation_id)
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT * FROM document_storage_operations WHERE operation_id=%s FOR UPDATE",
                    (operation_id,),
                )
                locked = cur.fetchone()
                if not locked:
                    return {"ok": True, "outcome": "operation_missing"}
                operation = dict(locked)
                if operation.get("status") in _DOCUMENT_STORAGE_TERMINAL:
                    return {"ok": True, "outcome": operation.get("status")}
                lease_expires = operation.get("lease_expires_at")
                if operation.get("status") == "deleting" and lease_expires and lease_expires > now_utc():
                    return {"ok": False, "outcome": "leased"}
                refs = document_storage_canonical_references(cur, operation)
                if refs:
                    cur.execute(
                        """
                        UPDATE document_storage_operations
                        SET status='canonical_committed', canonical_committed_at=COALESCE(canonical_committed_at,now()),
                            failure_reason=NULL, next_attempt_at=NULL, lease_owner=NULL, lease_expires_at=NULL, updated_at=now()
                        WHERE operation_id=%s
                        """,
                        (operation_id,),
                    )
                    conn.commit()
                    return {"ok": True, "outcome": "canonical_reference_found", "references": refs}
                attempt_count = int(operation.get("attempt_count") or 0) + 1
                cur.execute(
                    """
                    UPDATE document_storage_operations
                    SET status='deleting', attempt_count=%s, lease_owner=%s,
                        lease_expires_at=now() + interval '5 minutes', updated_at=now()
                    WHERE operation_id=%s
                    RETURNING *
                    """,
                    (attempt_count, worker, operation_id),
                )
                operation = dict(cur.fetchone())
            conn.commit()
        deletion = delete_document_storage_object(operation)
        with db_connect() as conn:
            with conn.cursor() as cur:
                if deletion.get("ok"):
                    cur.execute(
                        """
                        UPDATE document_storage_operations
                        SET status='compensated', failure_reason=NULL, compensated_at=now(),
                            next_attempt_at=NULL, lease_owner=NULL, lease_expires_at=NULL, updated_at=now()
                        WHERE operation_id=%s AND status='deleting'
                        RETURNING *
                        """,
                        (operation_id,),
                    )
                else:
                    terminal = bool(deletion.get("terminal")) or int(operation.get("attempt_count") or 0) >= _DOCUMENT_STORAGE_MAX_ATTEMPTS
                    next_attempt = None if terminal else _document_storage_next_attempt(int(operation.get("attempt_count") or 0))
                    cur.execute(
                        """
                        UPDATE document_storage_operations
                        SET status=%s, failure_reason=%s, next_attempt_at=%s,
                            lease_owner=NULL, lease_expires_at=NULL, updated_at=now()
                        WHERE operation_id=%s AND status='deleting'
                        RETURNING *
                        """,
                        (
                            "manual_review" if terminal else "compensation_pending",
                            str(deletion.get("outcome") or "delete_failed")[:500],
                            next_attempt,
                            operation_id,
                        ),
                    )
                row = cur.fetchone()
            conn.commit()
        updated = dict(row) if row else (document_storage_operation(operation_id) or operation)
        if updated.get("status") == "manual_review":
            _record_document_storage_operator_event(updated, "manual_review")
        return {"ok": bool(deletion.get("ok")), **deletion, "status": updated.get("status"), "attempt_count": updated.get("attempt_count")}
    except Exception as exc:
        logger.warning("document storage reconciliation failed for %s", operation_id, exc_info=True)
        return {"ok": False, "outcome": "reconciliation_error", "error": type(exc).__name__}


def mark_document_storage_compensation_pending(operation_id: str, reason: str) -> None:
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE document_storage_operations
                    SET status='compensation_pending', failure_reason=%s,
                        next_attempt_at=now(), lease_owner=NULL, lease_expires_at=NULL, updated_at=now()
                    WHERE operation_id=%s
                      AND status IN ('stored','deleting','compensation_pending')
                    """,
                    (str(reason or "canonical_transaction_failed")[:500], operation_id),
                )
            conn.commit()
    except Exception:
        logger.error("could not mark document storage compensation pending", exc_info=True)


def run_document_storage_reconciliation(limit: int = 50, *, company_code: str | None = None) -> dict[str, Any]:
    params: list[Any] = []
    company_sql = ""
    if company_code:
        company_sql = " AND company_code=%s"
        params.append(str(company_code).upper())
    params.append(max(1, min(int(limit), 200)))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT operation_id
                FROM document_storage_operations
                WHERE status IN ('prepared','stored','compensation_pending','deleting')
                  AND (next_attempt_at IS NULL OR next_attempt_at <= now()
                       OR (status='deleting' AND lease_expires_at <= now()))
                  {company_sql}
                ORDER BY next_attempt_at NULLS FIRST, created_at
                LIMIT %s
                """,
                tuple(params),
            )
            operation_ids = [str(row["operation_id"]) for row in cur.fetchall() or []]
    results = [reconcile_document_storage_operation(item, lease_owner=f"sweep-{os.getpid()}") for item in operation_ids]
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                DELETE FROM document_storage_operations
                WHERE status IN ('canonical_committed','compensated')
                  AND updated_at < now() - interval '90 days'
                """
            )
            pruned = int(cur.rowcount or 0)
        conn.commit()
    return {
        "ok": all(result.get("ok") or result.get("outcome") == "leased" for result in results),
        "processed": len(results),
        "pruned": pruned,
        "results": results,
    }


def source_file_details(path_value: str | None, mime_value: str | None = None) -> tuple[Path | None, str | None, str | None, int | None]:
    if not path_value:
        return None, None, None, None
    source = Path(str(path_value))
    if not source.exists() or not source.is_file():
        return source, None, None, None
    mime_type = str(mime_value or "").strip()
    if "/" not in mime_type:
        mime_type = mimetypes.guess_type(source.name)[0] or "application/octet-stream"
    checksum = sha256_file(source)
    try:
        size_bytes = source.stat().st_size
    except Exception:
        size_bytes = None
    return source, mime_type, checksum, size_bytes


def storage_object_key_for_path(path: Path) -> str:
    try:
        return str(path.relative_to(WORKSPACE))
    except Exception:
        return str(path)


def store_subject_file_local(
    *,
    company_code: str,
    subject_type: str,
    subject_key: str,
    file_kind: str,
    source_path: Path,
    mime_type: str,
    checksum: str | None,
) -> dict[str, Any]:
    ext = source_path.suffix or mimetypes.guess_extension(mime_type) or ".bin"
    file_name = f"{safe_storage_name(file_kind)}-{(checksum or uuid.uuid4().hex)[:12]}{ext}"
    destination_dir = (
        WORKSPACE
        / "data"
        / "companies"
        / company_code.upper()
        / "files"
        / safe_storage_name(subject_type)
        / safe_storage_name(subject_key)
        / safe_storage_name(file_kind)
    )
    destination_dir.mkdir(parents=True, exist_ok=True)
    destination_path = destination_dir / file_name
    if source_path.resolve() != destination_path.resolve():
        shutil.copy2(source_path, destination_path)
    object_key = storage_object_key_for_path(destination_path)
    try:
        size_bytes = destination_path.stat().st_size
    except Exception:
        size_bytes = None
    return {
        "ok": True,
        "provider": "local",
        "storage_status": "stored",
        "storage_object_key": object_key,
        "storage_url": f"local://{object_key}",
        "external_file_id": None,
        "content_sha256": checksum,
        "mime_type": mime_type,
        "size_bytes": size_bytes,
        "stored_at": now_iso(),
        "metadata": {"local_path": str(destination_path)},
    }


def store_subject_file_google_drive(
    *,
    company_code: str,
    owner_phone: str | None,
    subject_key: str,
    file_kind: str,
    source_path: Path,
    mime_type: str,
    checksum: str | None,
    config: dict[str, Any],
) -> dict[str, Any]:
    folder_id = config.get("drive_folder_id")
    if not folder_id:
        return {"ok": False, "provider": "google_drive", "storage_status": "failed", "storage_error": "missing_drive_folder_id"}
    ext = source_path.suffix or mimetypes.guess_extension(mime_type) or ".bin"
    upload_name = f"{company_code.upper()}-{safe_storage_name(owner_phone or 'unknown')}-{safe_storage_name(subject_key)}-{safe_storage_name(file_kind)}-{(checksum or uuid.uuid4().hex)[:12]}{ext}"
    result = run_gog_wathefni(
        [
            "drive",
            "upload",
            str(source_path),
            "--name",
            upload_name,
            "--parent",
            str(folder_id),
            "--mime-type",
            mime_type,
        ],
        timeout=120,
    )
    if not result.get("ok"):
        return {
            "ok": False,
            "provider": "google_drive",
            "storage_status": "failed",
            "storage_error": result.get("stderr") or result.get("stdout") or "drive_upload_failed",
            "raw": result,
        }
    parsed = parse_drive_upload_result(result)
    external_file_id = parsed.get("external_file_id")
    storage_url = parsed.get("storage_url")
    return {
        "ok": bool(external_file_id or storage_url),
        "provider": "google_drive",
        "storage_status": "stored",
        "storage_object_key": external_file_id,
        "storage_url": storage_url,
        "external_file_id": external_file_id,
        "content_sha256": checksum,
        "mime_type": mime_type,
        "size_bytes": source_path.stat().st_size if source_path.exists() else None,
        "stored_at": now_iso(),
        "metadata": {"drive": parsed.get("raw"), "upload_name": upload_name},
    }


def store_subject_file(
    *,
    company_code: str,
    owner_phone: str | None,
    subject_type: str,
    subject_key: str,
    file_kind: str,
    source_path: Path,
    mime_type: str,
    checksum: str | None,
) -> dict[str, Any]:
    config = document_storage_config(company_code)
    provider = str(config.get("provider") or "local")
    if provider == "google_drive":
        primary = store_subject_file_google_drive(
            company_code=company_code,
            owner_phone=owner_phone,
            subject_key=subject_key,
            file_kind=file_kind,
            source_path=source_path,
            mime_type=mime_type,
            checksum=checksum,
            config=config,
        )
        if primary.get("ok"):
            return primary
        if config.get("fallback_provider") == "local":
            fallback = store_subject_file_local(
                company_code=company_code,
                subject_type=subject_type,
                subject_key=subject_key,
                file_kind=file_kind,
                source_path=source_path,
                mime_type=mime_type,
                checksum=checksum,
            )
            fallback["storage_status"] = "stored_with_fallback"
            fallback["primary_provider"] = "google_drive"
            fallback["storage_error"] = primary.get("storage_error")
            return fallback
        return primary
    return store_subject_file_local(
        company_code=company_code,
        subject_type=subject_type,
        subject_key=subject_key,
        file_kind=file_kind,
        source_path=source_path,
        mime_type=mime_type,
        checksum=checksum,
    )


def upsert_file_registry(
    cur: Any,
    *,
    company_code: str,
    owner_phone: str | None,
    subject_type: str,
    subject_key: str,
    file_kind: str,
    document_type: str | None,
    original_filename: str | None,
    source_path: str | None,
    local_path: str | None,
    storage_result: dict[str, Any],
    metadata: dict[str, Any] | None = None,
) -> None:
    checksum = storage_result.get("content_sha256")
    cur.execute(
        """
        SELECT file_id
        FROM file_registry
        WHERE subject_type=%s
          AND subject_key=%s
          AND file_kind=%s
          AND COALESCE(document_type,'')=COALESCE(%s,'')
          AND COALESCE(content_sha256,'')=COALESCE(%s,'')
        ORDER BY updated_at DESC
        LIMIT 1
        """,
        (subject_type, subject_key, file_kind, document_type, checksum),
    )
    existing = cur.fetchone()
    row_metadata = metadata or {}
    provider = storage_result.get("provider") or "local"
    status = storage_result.get("storage_status") or ("stored" if storage_result.get("ok") else "failed")
    if existing:
        cur.execute(
            """
            UPDATE file_registry
            SET company_code=%s, owner_phone=%s, original_filename=%s, source_path=%s,
                local_path=%s, storage_provider=%s, storage_object_key=%s,
                external_file_id=%s, storage_url=%s, content_sha256=%s, mime_type=%s,
                size_bytes=%s, storage_status=%s, storage_error=%s, metadata=%s,
                raw_json=%s, stored_at=CASE WHEN %s IS NOT NULL THEN now() ELSE stored_at END,
                updated_at=now()
            WHERE file_id=%s
            """,
            (
                company_code,
                owner_phone,
                original_filename,
                source_path,
                local_path,
                provider,
                storage_result.get("storage_object_key"),
                storage_result.get("external_file_id"),
                storage_result.get("storage_url"),
                checksum,
                storage_result.get("mime_type"),
                storage_result.get("size_bytes"),
                status,
                storage_result.get("storage_error"),
                Json(row_metadata),
                Json({"storage": storage_result, "metadata": row_metadata}),
                provider,
                existing["file_id"],
            ),
        )
    else:
        cur.execute(
            """
            INSERT INTO file_registry (
                company_code, owner_phone, subject_type, subject_key, file_kind,
                document_type, original_filename, source_path, local_path,
                storage_provider, storage_object_key, external_file_id, storage_url,
                content_sha256, mime_type, size_bytes, storage_status, storage_error,
                metadata, raw_json, stored_at
            )
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,CASE WHEN %s IS NOT NULL THEN now() ELSE NULL END)
            """,
            (
                company_code,
                owner_phone,
                subject_type,
                subject_key,
                file_kind,
                document_type,
                original_filename,
                source_path,
                local_path,
                provider,
                storage_result.get("storage_object_key"),
                storage_result.get("external_file_id"),
                storage_result.get("storage_url"),
                checksum,
                storage_result.get("mime_type"),
                storage_result.get("size_bytes"),
                status,
                storage_result.get("storage_error"),
                Json(row_metadata),
                Json({"storage": storage_result, "metadata": row_metadata}),
                provider,
            ),
        )


def onboarding_item_row(cur: Any, employee_key: str, item_id: str) -> dict[str, Any]:
    cur.execute(
        """
        SELECT item_id, label, item_type, document_type
        FROM onboarding_items
        WHERE employee_key=%s AND item_id=%s
        LIMIT 1
        """,
        (employee_key, item_id),
    )
    row = cur.fetchone()
    return dict(row) if row else {"item_id": item_id, "document_type": item_id, "label": item_id}


def record_employee_document_receipt(
    cur: Any,
    *,
    employee: dict[str, Any],
    item_id: str,
    value: str,
    media: dict[str, Any] | None,
    storage_result: dict[str, Any],
    extraction: dict[str, Any] | None = None,
    skip_governed_version: bool = False,
) -> None:
    employee_key = employee["employee_key"]
    item = onboarding_item_row(cur, employee_key, item_id)
    document_type = str(item.get("document_type") or item.get("item_id") or item_id)
    filename = Path(str((media or {}).get("path") or "")).name if has_current_media_upload(media) else None
    metadata = {
        "item_id": item_id,
        "label": item.get("label"),
        "value": value,
        "storage": storage_result,
        "received_at": now_iso(),
    }
    extraction = extraction if isinstance(extraction, dict) else extract_compliance_document_metadata(
        document_type=document_type,
        text=value,
        media=media,
        company_code=employee.get("company_code"),
        subject_key=employee.get("employee_key"),
    )
    if extraction:
        metadata["extraction"] = json_safe(extraction)
    expiry_date = extraction.get("expiry_date_parsed") if isinstance(extraction, dict) else None
    issued_date = extraction.get("issued_date_parsed") if isinstance(extraction, dict) else None
    document_number = str(extraction.get("document_number") or "").strip() if isinstance(extraction, dict) else ""
    extraction_status = str(extraction.get("extraction_status") or "").strip() if isinstance(extraction, dict) else None
    extraction_error = str(extraction.get("extraction_error") or "").strip() if isinstance(extraction, dict) and extraction.get("extraction_error") else None
    extraction_confidence = extraction.get("confidence") if isinstance(extraction, dict) else None
    drive_file_id = storage_result.get("drive_file_id") or (storage_result.get("external_file_id") if storage_result.get("provider") == "google_drive" else None)
    drive_url = storage_result.get("drive_url") or (storage_result.get("storage_url") if storage_result.get("provider") == "google_drive" else None)
    fields = (
        employee_key,
        digits(employee.get("phone")),
        require_company_code(employee.get("company_code")),
        item_id,
        document_type,
        filename,
        (media or {}).get("path"),
        drive_file_id,
        drive_url,
        "received",
        Json(metadata),
        Json(metadata),
        now_utc().date(),
        storage_result.get("provider"),
        storage_result.get("storage_object_key"),
        storage_result.get("external_file_id"),
        storage_result.get("storage_url"),
        storage_result.get("content_sha256"),
        storage_result.get("mime_type"),
        storage_result.get("storage_status"),
        storage_result.get("storage_error"),
        document_number or None,
        issued_date,
        expiry_date,
        extraction_status,
        extraction_error,
        extraction_confidence,
    )
    cur.execute(
        """
        SELECT document_id
        FROM employee_documents
        WHERE employee_key=%s AND document_type=%s
        ORDER BY updated_at DESC
        LIMIT 1
        """,
        (employee_key, document_type),
    )
    existing = cur.fetchone()
    if existing:
        cur.execute(
            """
            UPDATE employee_documents
            SET phone=%s, company_code=%s, item_id=%s, filename=%s, local_path=%s,
                drive_file_id=%s, drive_url=%s, status=%s, metadata=%s, raw_json=%s,
                received_at=%s, storage_provider=%s, storage_object_key=%s,
                external_file_id=%s, storage_url=%s, content_sha256=%s, mime_type=%s,
                storage_status=%s, storage_error=%s, document_number=%s,
                issued_at=COALESCE(%s, issued_at), expiry_date=COALESCE(%s, expiry_date),
                extraction_status=%s, extraction_error=%s, extraction_confidence=%s,
                extracted_at=CASE WHEN %s IS NOT NULL THEN now() ELSE extracted_at END,
                stored_at=CASE WHEN %s IS NOT NULL THEN now() ELSE stored_at END,
                updated_at=now()
            WHERE document_id=%s
            """,
            (
                fields[1], fields[2], fields[3], fields[5], fields[6],
                fields[7], fields[8], fields[9], fields[10], fields[11],
                fields[12], fields[13], fields[14], fields[15], fields[16],
                fields[17], fields[18], fields[19], fields[20], fields[21],
                fields[22], fields[23], fields[24], fields[25], fields[26],
                fields[24], fields[13],
                existing["document_id"],
            ),
        )
    else:
        cur.execute(
            """
            INSERT INTO employee_documents (
                employee_key, phone, company_code, item_id, document_type, filename,
                local_path, drive_file_id, drive_url, status, metadata, raw_json, received_at,
                storage_provider, storage_object_key, external_file_id, storage_url,
                content_sha256, mime_type, storage_status, storage_error, document_number,
                issued_at, expiry_date, extraction_status, extraction_error, extraction_confidence,
                extracted_at, stored_at
            )
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,CASE WHEN %s IS NOT NULL THEN now() ELSE NULL END,CASE WHEN %s IS NOT NULL THEN now() ELSE NULL END)
            """,
            (*fields, fields[24], fields[13]),
        )
    # Kuwait pilot: dual-write via canonical map (residence + work_permit included).
    # Historical residency_iqama rows stay non-destructively compatible.
    import kuwait_pilot_document_journey as _kw_doc_journey

    ocr_proposal = None
    if isinstance(extraction, dict) and extraction:
        identity_check = extraction.get("identity_check") if isinstance(extraction.get("identity_check"), dict) else None
        hr_warnings = extraction.get("hr_warnings") if isinstance(extraction.get("hr_warnings"), list) else None
        ocr_proposal = {
            "document_number": document_number or None,
            "issue_date": str(issued_date) if issued_date else extraction.get("issued_date") or extraction.get("issue_date"),
            "expiry_date": str(expiry_date) if expiry_date else extraction.get("expiry_date"),
            "name": extraction.get("full_name") or extraction.get("name"),
            "full_name": extraction.get("full_name"),
            "full_name_en": extraction.get("full_name_en"),
            "full_name_ar": extraction.get("full_name_ar"),
            "nationality": extraction.get("nationality"),
            "date_of_birth": extraction.get("date_of_birth"),
            "side": extraction.get("side"),
            "employer_or_sponsor": extraction.get("employer_or_sponsor"),
            "document_type": extraction.get("document_type") or extraction.get("detected_item"),
            "confidence": extraction.get("confidence"),
            "extraction_status": extraction_status,
            "identity_check": identity_check,
            "hr_warnings": hr_warnings,
            "authoritative": False,
        }
        # Drop empty keys so HR summary stays compact.
        ocr_proposal = {k: v for k, v in ocr_proposal.items() if v not in (None, "", {}, [])}
    if _kw_doc_journey.should_dual_write_compliance(document_type):
        _kw_doc_journey.dual_write_compliance_from_upload(
            cur,
            employee=employee,
            document_type=document_type,
            label=item.get("label") or _kw_doc_journey.document_label(document_type),
            metadata=metadata,
            document_number=document_number or None,
            issued_date=issued_date,
            expiry_date=expiry_date,
            extraction_status=extraction_status,
            extraction_error=extraction_error,
            extraction_confidence=extraction_confidence,
            ocr_proposal=ocr_proposal,
            notes=value,
        )
    storage_metadata = storage_result.get("metadata") if isinstance(storage_result.get("metadata"), dict) else {}
    upsert_file_registry(
        cur,
        company_code=require_company_code(employee.get("company_code")),
        owner_phone=digits(employee.get("phone")),
        subject_type="employee",
        subject_key=employee_key,
        file_kind="onboarding_document",
        document_type=document_type,
        original_filename=filename,
        source_path=(media or {}).get("path"),
        local_path=storage_metadata.get("local_path") or (media or {}).get("path"),
        storage_result=storage_result,
        metadata={
            "item_id": item_id,
            "label": item.get("label"),
            "employee_key": employee_key,
            "value": value,
        },
    )
    # Governed version for renew/review history (pending until HR reviews).
    # Dual-side Civil ID manages its own draft attempt / parts — skip here.
    if skip_governed_version:
        return
    try:
        _kw_doc_journey.ensure_document_journey_schema(cur)
        file_id = None
        checksum = storage_result.get("content_sha256")
        if checksum:
            cur.execute(
                """
                SELECT file_id FROM file_registry
                WHERE subject_type='employee' AND subject_key=%s
                  AND COALESCE(content_sha256,'')=COALESCE(%s,'')
                ORDER BY updated_at DESC NULLS LAST LIMIT 1
                """,
                (employee_key, checksum),
            )
            frow = cur.fetchone()
            file_id = str(frow["file_id"]) if frow else None
        _kw_doc_journey.register_upload_version(
            cur,
            sys.modules[__name__],
            company_code=require_company_code(employee.get("company_code")),
            employee_key=employee_key,
            document_type=document_type,
            file_id=file_id,
            file_sha256=checksum,
            filename=filename,
            mime_type=storage_result.get("mime_type"),
            issue_date=issued_date,
            expiry_date=expiry_date,
            document_number=document_number or None,
            ocr_proposal=ocr_proposal,
            uploaded_by=digits(employee.get("phone")),
            upload_source="employee_or_hr_upload",
            actor_user_id=digits(employee.get("phone")),
        )
    except Exception:
        logger.exception(
            "governed document version registration failed employee=%s type=%s",
            employee_key,
            document_type,
        )


def find_candidate_application_for_file(
    phone: str | None,
    *,
    conversation_id: str | None = None,
    company_code: str | None = None,
    account_id: str | None = None,
) -> dict[str, Any] | None:
    """Resolve the application that should receive a candidate CV upload.

    When WATHEFNI_CANONICAL_LIFECYCLE is on, resolution is conversation-bound and
    fails closed on ambiguity. Legacy path keeps the historical phone LIMIT 1 heuristic.
    """
    if canonical_lifecycle_enabled():
        import recruiting_lifecycle as _rl

        resolved = _rl.resolve_conversation_application(
            sys.modules[__name__],
            phone=phone,
            conversation_id=conversation_id,
            company_code=company_code,
            account_id=account_id,
            allow_single_eligible=True,
        )
        if not resolved.get("ok"):
            return None
        app = resolved.get("application")
        if resolved.get("requires_bind") and conversation_id and isinstance(app, dict):
            _rl.bind_conversation_application(
                sys.modules[__name__],
                company_code=str(app.get("company_code") or company_code or ""),
                conversation_id=str(conversation_id),
                phone=str(app.get("phone") or phone or ""),
                app_key=str(app.get("app_key") or ""),
                account_id=account_id,
                bound_reason="single_eligible",
            )
        return app if isinstance(app, dict) else None
    target = digits(phone)
    if not target:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM applications
                WHERE phone=%s
                ORDER BY
                  CASE
                    WHEN status IN ('awaiting_cv','cv_received','cv_processing','screening','screening_complete','ready_for_review')
                      OR current_step IN ('cv_request','cv_upload','screening','screening_complete','cv_processing','ready_for_review') THEN 0
                    WHEN status IN ('review_pending','shortlisted') THEN 1
                    ELSE 2
                  END,
                  updated_at DESC NULLS LAST,
                  ingested_at DESC NULLS LAST
                LIMIT 1
                """,
                (target,),
            )
            row = cur.fetchone()
            return dict(row) if row else None


def register_candidate_cv_file(
    cur: Any,
    *,
    application: dict[str, Any],
    media: dict[str, Any],
    file_kind: str = "candidate_cv",
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    source, mime_type, checksum, size_bytes = source_file_details(media.get("path"), media.get("type") or media.get("mime_type"))
    if not source or not source.exists() or not mime_type:
        return {"ok": False, "storage_status": "failed", "storage_error": "missing_candidate_cv_media_file"}
    company_code = str(application.get("company_code") or "").strip().upper()
    phone = digits(application.get("phone"))
    app_key = str(application.get("app_key") or "").strip()
    if not company_code or not app_key:
        return {"ok": False, "storage_status": "failed", "storage_error": "tenant_scope_required"}
    raw_json = dict(application.get("raw_json") or {})
    prior_cv = dict(raw_json.get("cv") or {})
    is_replacement = bool(prior_cv.get("filename") or prior_cv.get("storage"))
    storage_result = store_subject_file(
        company_code=company_code,
        owner_phone=phone,
        subject_type="application",
        subject_key=app_key,
        file_kind=file_kind,
        source_path=source,
        mime_type=mime_type,
        checksum=checksum,
    )
    storage_result["size_bytes"] = storage_result.get("size_bytes") or size_bytes
    original_filename = Path(str(media.get("path") or "")).name
    storage_metadata = storage_result.get("metadata") if isinstance(storage_result.get("metadata"), dict) else {}
    checksum = storage_result.get("content_sha256") or checksum
    if storage_result.get("ok") and checksum:
        cur.execute(
            """
            SELECT fr.file_id::text,
                   cd.document_id::text,
                   cd.extraction_status
            FROM file_registry fr
            LEFT JOIN candidate_documents cd
              ON cd.app_key=fr.subject_key
             AND cd.document_type='cv'
             AND cd.raw_json->'storage'->>'sha256'=fr.content_sha256
            WHERE fr.company_code=%s
              AND fr.subject_type='application'
              AND fr.subject_key=%s
              AND fr.file_kind=%s
              AND fr.content_sha256=%s
            ORDER BY cd.updated_at DESC NULLS LAST, fr.updated_at DESC
            LIMIT 1
            """,
            (company_code, app_key, file_kind, checksum),
        )
        duplicate = cur.fetchone()
        if duplicate:
            return {
                "ok": True,
                "duplicate": True,
                "already_validated": str(duplicate.get("extraction_status") or "") == "ok",
                "app_key": app_key,
                "document_id": str(duplicate.get("document_id") or "") or None,
                "file_id": str(duplicate.get("file_id") or "") or None,
                "storage": storage_result,
                "is_replacement": is_replacement,
            }
    registry_metadata = {
        "phone": phone,
        "app_key": app_key,
        "company_code": company_code,
        "position_code": application.get("position_code"),
        "source": "candidate_whatsapp_media",
        "latest": False,
        "validation_status": "pending",
        "versioned_at": now_iso(),
        "content_sha256": checksum,
        "is_replacement": is_replacement,
        **(metadata or {}),
    }
    upsert_file_registry(
        cur,
        company_code=company_code,
        owner_phone=phone,
        subject_type="application",
        subject_key=app_key,
        file_kind=file_kind,
        document_type="cv",
        original_filename=original_filename,
        source_path=str(source),
        local_path=storage_metadata.get("local_path") or str(source),
        storage_result=storage_result,
        metadata=registry_metadata,
    )
    cv_json = dict(raw_json.get("cv") or {})
    cv_storage = {
        "provider": storage_result.get("provider"),
        "object_key": storage_result.get("storage_object_key"),
        "external_file_id": storage_result.get("external_file_id"),
        "url": storage_result.get("storage_url"),
        "sha256": storage_result.get("content_sha256"),
        "mime_type": storage_result.get("mime_type"),
        "size_bytes": storage_result.get("size_bytes"),
        "status": storage_result.get("storage_status"),
        "stored_at": storage_result.get("stored_at") or now_iso(),
    }
    previous_versions = cv_json.get("previous_versions") if isinstance(cv_json.get("previous_versions"), list) else []
    if cv_json.get("filename") or cv_json.get("storage"):
        previous_versions = [
            *previous_versions,
            {
                "filename": cv_json.get("filename"),
                "storage": cv_json.get("storage"),
                "received_at": cv_json.get("received_at") or cv_json.get("storage", {}).get("stored_at") if isinstance(cv_json.get("storage"), dict) else None,
                "superseded_at": now_iso(),
            },
        ][-10:]
    cv_json["storage"] = cv_storage
    cv_json["previous_versions"] = previous_versions
    cv_json["latest"] = True
    cv_json["versioned_at"] = registry_metadata["versioned_at"]
    cv_json["path"] = str(source)
    cv_json["filename"] = original_filename
    cv_json["source"] = "whatsapp_document"
    cv_json["is_replacement"] = is_replacement
    if is_replacement:
        raw_json["cv_pending"] = cv_json
    else:
        raw_json["cv"] = cv_json
    if str((metadata or {}).get("candidate_locale") or "").strip():
        raw_json["candidate_locale"] = _candidate_messages.normalize_locale((metadata or {}).get("candidate_locale"))
    sync_json = dict(raw_json.get("sync") or {})
    sync_json["file_registry"] = {"status": "ok" if storage_result.get("ok") else "failed", "updated_at": now_iso()}
    raw_json["sync"] = sync_json
    received_ok = bool(storage_result.get("ok"))
    if received_ok:
        raw_json["cv_received"] = True
        if not is_replacement:
            raw_json["status"] = "cv_processing"
            raw_json["current_step"] = "cv_processing"
        cv_json["processing"] = {
            "file_received": True,
            "file_stored": bool(storage_result.get("ok")),
            "text_extracted": False,
            "profile_parsed": False,
            "semantic_indexed": False,
            "screening_prefill_ready": False,
            "screening_questions_sent": False,
            "status": "pending_async_processing",
            "updated_at": now_iso(),
        }
        if is_replacement:
            raw_json["cv_pending"] = cv_json
        else:
            raw_json["cv"] = cv_json
    cur.execute(
        """
        UPDATE applications
        SET raw_json=%s,
            cv_received=CASE WHEN %s THEN true ELSE cv_received END,
            cv_received_at=CASE WHEN %s THEN COALESCE(cv_received_at, CURRENT_DATE) ELSE cv_received_at END,
            drive_sync_status=CASE WHEN %s='google_drive' AND %s THEN 'ok' ELSE drive_sync_status END,
            updated_at=now()
        WHERE app_key=%s AND company_code=%s
        """,
        (
            Json(raw_json),
            received_ok,
            received_ok,
            storage_result.get("provider"),
            received_ok,
            app_key,
            company_code,
        ),
    )
    document_id = None
    try:
        doc_payload = {
            **cv_json,
            "received_at": now_iso(),
            "storage": cv_storage,
        }
        cur.execute(
            """
            INSERT INTO candidate_documents
            (app_key, phone, document_type, filename, local_path, source, extraction_status,
             extraction_method, extraction_chars, drive_file_id, drive_url, metadata, raw_json, received_at)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,CURRENT_DATE)
            RETURNING document_id::text
            """,
            (
                app_key,
                phone,
                "cv",
                original_filename,
                storage_metadata.get("local_path") or str(source),
                cv_json.get("source") or "whatsapp_document",
                ("awaiting_confirmation" if is_replacement and received_ok else ("pending_extraction" if received_ok else "failed")),
                None,
                None,
                storage_result.get("external_file_id"),
                storage_result.get("storage_url"),
                Json(registry_metadata),
                Json(doc_payload),
            ),
        )
        inserted_doc = cur.fetchone()
        document_id = str((inserted_doc or {}).get("document_id") or "") or None
    except Exception:
        # Older deployments may not have candidate_documents; canonical application
        # truth above is still the authority used by HR chat.
        pass
    # WAVE3: additive job-WhatsApp adapter dual-write after live attach.
    if received_ok and str(cv_json.get("source") or "").startswith("whatsapp"):
        cur.execute("SAVEPOINT unified_inbound_cv_whatsapp_job")
        try:
            import inbound_cv_adapters as _inbound_cv_adapters

            meta = metadata if isinstance(metadata, dict) else {}
            provider_message_id = str(
                meta.get("provider_message_id")
                or meta.get("message_id")
                or media.get("message_id")
                or f"{app_key}:{checksum}"
            )
            _inbound_cv_adapters.adapt_whatsapp_job(
                cur,
                company_code=company_code,
                provider_message_id=provider_message_id,
                phone=phone,
                account_id=str(meta.get("account_id") or "") or None,
                conversation_id=str(meta.get("conversation_id") or "") or None,
                pending_id=str(meta.get("pending_id") or "") or None,
                document_id=document_id,
                content_sha256=str(checksum or "") or None,
                filename=original_filename,
                app_key=app_key,
                apply_code=str(application.get("apply_code") or "") or None,
                human_confirmed=True,
                mime_or_suffix=str(mime_type or original_filename or ""),
                needs_ocr=False,
            )
        except Exception:
            cur.execute("ROLLBACK TO SAVEPOINT unified_inbound_cv_whatsapp_job")
            logger.exception("unified_inbound_cv_whatsapp_job_failed")
        finally:
            cur.execute("RELEASE SAVEPOINT unified_inbound_cv_whatsapp_job")
    job_id = None
    if received_ok and document_id and not is_replacement:
        try:
            job_id = ensure_application_cv_extraction_job(
                cur,
                company_code=company_code,
                document_id=str(document_id),
                app_key=app_key,
                source_channel=str(cv_json.get("source") or "whatsapp_document"),
                priority=80,
            )
        except Exception:
            logger.exception(
                "canonical_cv_enqueue_failed app_key=%s document_id=%s",
                app_key,
                document_id,
            )
            # Fail closed: do not leave pending_async without a durable job.
            cv_json = dict((raw_json.get("cv") if isinstance(raw_json.get("cv"), dict) else {}) or {})
            processing = dict(cv_json.get("processing") or {})
            processing.update(
                {
                    "status": "failed",
                    "error": "canonical_enqueue_failed",
                    "updated_at": now_iso(),
                }
            )
            cv_json["processing"] = processing
            raw_json["cv"] = cv_json
            cur.execute(
                "UPDATE applications SET raw_json=%s, updated_at=now() WHERE app_key=%s AND company_code=%s",
                (Json(raw_json), app_key, company_code),
            )
            job_id = None
    return {
        "ok": bool(storage_result.get("ok")),
        "app_key": app_key,
        "document_id": document_id,
        "intake_job_id": job_id,
        "storage": storage_result,
        "is_replacement": is_replacement,
    }


def ensure_application_cv_extraction_job(
    cur: Any,
    *,
    company_code: str,
    document_id: str,
    app_key: str | None = None,
    intake_document_id: str | None = None,
    source_channel: str | None = None,
    priority: int = 100,
    job_context: dict[str, Any] | None = None,
) -> str | None:
    """Enqueue (or keep) the canonical durable cv_extraction job for a candidate document.

    Idempotent on candidate-document:{id}:extract. Does not create a second processing path.
    """
    doc_id = str(document_id or "").strip()
    company = str(company_code or "").strip().upper()
    if not doc_id or not company:
        return None
    config = durable_email_ingress_config()
    context = dict(job_context or {})
    context.pop("candidate_document_id", None)
    context.pop("app_key", None)
    context.pop("intake_document_id", None)
    context.pop("source_channel", None)
    idempotency_key = f"candidate-document:{doc_id}:extract"
    cur.execute(
        """
        SELECT job_id::text AS job_id, status
        FROM intake_processing_jobs
        WHERE company_code=%s AND idempotency_key=%s
        LIMIT 1
        """,
        (company, idempotency_key),
    )
    existing = cur.fetchone()
    if existing:
        status = str(existing.get("status") or "")
        if status in {"pending", "running", "retrying", "waiting_quota", "waiting_budget", "completed"}:
            return str(existing["job_id"])
        if status in {"cancelled", "dead_letter"}:
            cur.execute(
                """
                UPDATE intake_processing_jobs
                SET status='pending', available_at=now(), lease_owner=NULL, lease_expires_at=NULL,
                    last_error_code=NULL, last_error_detail=NULL, completed_at=NULL, updated_at=now(),
                    payload=COALESCE(payload,'{}'::jsonb) || %s::jsonb
                WHERE job_id=%s::uuid
                RETURNING job_id::text
                """,
                (
                    Json(
                        {
                            **context,
                            "candidate_document_id": doc_id,
                            "app_key": app_key,
                            "intake_document_id": intake_document_id,
                            "source_channel": source_channel,
                            "revived_from": status,
                        }
                    ),
                    existing["job_id"],
                ),
            )
            revived = cur.fetchone()
            return str((revived or {}).get("job_id") or existing["job_id"])
    payload = {
        **context,
        "candidate_document_id": doc_id,
        "app_key": app_key,
        "source_channel": source_channel or ("email_inbound" if intake_document_id else "application_attach"),
    }
    if intake_document_id:
        payload["intake_document_id"] = str(intake_document_id)
    return _durable_email_ingress.enqueue_job(
        cur,
        company_code=company,
        job_type="cv_extraction",
        subject_type="candidate_document",
        subject_id=doc_id,
        idempotency_key=idempotency_key,
        payload=payload,
        priority=priority,
        max_attempts=config.max_attempts,
    )


# --- Bulk CV import: shared import core -------------------------------------
# Imported candidates use a company-scoped surrogate identity so that imports are
# never deduplicated across companies and never reuse a real candidate row from a
# different tenant. The real phone/email/name are preserved inside raw_json/profile.
def import_surrogate_phone(company_code: str, *, email: str | None = None, checksum: str | None = None) -> str:
    company = str(company_code or "").strip().upper()
    seed = (str(email or "").strip().lower()) or (str(checksum or "").strip().lower()) or uuid.uuid4().hex
    token = hashlib.sha1(f"{company}:{seed}".encode("utf-8")).hexdigest()[:16]
    return f"imp-{company.lower()}-{token}"


def import_app_key(surrogate_phone: str, company_code: str, position_code: str | None) -> str:
    company = str(company_code or "").strip().upper()
    pos = str(position_code or "").strip().upper() or "IMPORT"
    return f"{surrogate_phone}-{company}-{pos}"


def register_imported_cv(
    cur: Any,
    *,
    company_code: str,
    batch_id: str,
    source_path: Path,
    original_filename: str,
    mime_type: str | None = None,
    checksum: str | None = None,
    size_bytes: int | None = None,
    candidate_name: str | None = None,
    candidate_email: str | None = None,
    candidate_phone: str | None = None,
    position_code: str | None = None,
    position_title: str | None = None,
    source: str = "bulk_upload",
    role_suggestion: dict[str, Any] | None = None,
    source_ref: str | None = None,
    auto_admit: bool = False,
    admit_reason: str | None = None,
    identity_resolution: dict[str, Any] | None = None,
    extraction_policy: str = "enqueue",
    extraction_job_context: dict[str, Any] | None = None,
    extraction_priority: int | None = None,
) -> dict[str, Any]:
    company = str(company_code or "").strip().upper()
    if not company:
        # Fail closed: an import with no tenant would create an unowned
        # candidate hub row and an unscoped application.
        return {"ok": False, "status": "failed", "error": "company_code_required"}
    resolved_source, resolved_mime, resolved_checksum, resolved_size = source_file_details(str(source_path), mime_type)
    if not resolved_source or not resolved_source.exists() or not resolved_mime:
        return {"ok": False, "status": "failed", "error": "unreadable_or_unsupported_file"}
    checksum = checksum or resolved_checksum
    size_bytes = size_bytes or resolved_size
    email = (str(candidate_email).strip().lower() if candidate_email else None) or None
    held_review_materialization = bool(
        isinstance(identity_resolution, dict)
        and identity_resolution.get("held_review_materialization")
    )
    governed_identity = bool(identity_resolution) and not held_review_materialization
    if held_review_materialization:
        # Wave D6A: durable CV reached identity but cannot bind yet. Materialize a
        # Held application with explicit identity-review terminal metadata. Never
        # auto-admit; never reuse a conflicting candidate phone.
        # Surrogate MUST be checksum-scoped — email-only seeds would collapse a
        # conflict Held app onto the legitimate email-keyed import application.
        surrogate_phone = import_surrogate_phone(
            company, email=None, checksum=checksum
        )
        auto_admit = False
    elif governed_identity:
        if (
            str(identity_resolution.get("outcome") or "")
            not in _inbound_cv_authority.ACCEPTED_IDENTITY_OUTCOMES
            or not identity_resolution.get("ownership_confirmed")
        ):
            return {
                "ok": False,
                "status": "failed",
                "error": "identity_binding_not_authorized",
            }
        surrogate_phone = str(
            identity_resolution.get("selected_candidate_phone") or ""
        ).strip()
        if not surrogate_phone:
            return {
                "ok": False,
                "status": "failed",
                "error": "identity_candidate_key_missing",
            }
    else:
        surrogate_phone = import_surrogate_phone(
            company, email=email, checksum=checksum
        )
    position_code = (str(position_code).strip() if position_code else "") or ""
    app_key = (
        str((identity_resolution or {}).get("selected_app_key") or "").strip()
        if governed_identity
        else ""
    ) or import_app_key(surrogate_phone, company, position_code)
    # Tiered intake: an explicit role signal (position_code) + company auto-admit
    # setting places the candidate directly into Candidates (review_pending). Anything
    # else is held in the Intake queue (import_review with a role guess, else needs_role).
    auto_admitted = bool(auto_admit and position_code and not governed_identity)
    if auto_admitted:
        held_status = "review_pending"
        current_step = "review"
    else:
        held_status = "import_review" if position_code else "needs_role"
        current_step = "import_review"

    cur.execute(
        """
        INSERT INTO candidates (phone, name, email, current_status, active_company_code, active_position_code, profile, raw_json, data_source)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,'production')
        ON CONFLICT (phone) DO UPDATE
          SET name=COALESCE(NULLIF(candidates.name,''), EXCLUDED.name),
              email=COALESCE(NULLIF(candidates.email,''), EXCLUDED.email),
              active_company_code=COALESCE(candidates.active_company_code, EXCLUDED.active_company_code),
              updated_at=now()
        """,
        (
            surrogate_phone,
            candidate_name or None,
            email,
            held_status,
            company,
            position_code or None,
            Json(json_safe({
                "identity_source": (
                    "governed_inbound_cv"
                    if governed_identity
                    else (
                        "held_identity_review"
                        if held_review_materialization
                        else "bulk_import"
                    )
                ),
                "import_batch_id": batch_id,
                "contact": {"phone": candidate_phone or None, "email": email, "name": candidate_name or None},
                "identity_resolution_id": (
                    (identity_resolution or {}).get("resolution_id")
                ),
                "identity_review_warning": bool(held_review_materialization),
                "identity_terminal_reason": (
                    (identity_resolution or {}).get("held_terminal_reason")
                    if held_review_materialization
                    else None
                ),
            })),
            Json(json_safe({
                "identity_source": (
                    "governed_inbound_cv"
                    if governed_identity
                    else (
                        "held_identity_review"
                        if held_review_materialization
                        else "bulk_import"
                    )
                ),
                "import_batch_id": batch_id,
                "identity_resolution_id": (
                    (identity_resolution or {}).get("resolution_id")
                ),
                "identity_review_warning": bool(held_review_materialization),
            })),
        ),
    )

    cur.execute(
        """
        SELECT EXISTS (
          SELECT 1 FROM candidate_documents
          WHERE app_key=%s
            AND COALESCE((metadata->>'latest')::boolean,false)=true
        ) AS has_current_cv
        """,
        (app_key,),
    )
    has_current_cv = bool((cur.fetchone() or {}).get("has_current_cv"))

    storage_result = store_subject_file(
        company_code=company,
        owner_phone=surrogate_phone,
        subject_type="application",
        subject_key=app_key,
        file_kind="candidate_cv",
        source_path=resolved_source,
        mime_type=resolved_mime,
        checksum=checksum,
    )
    storage_result["size_bytes"] = storage_result.get("size_bytes") or size_bytes
    if not storage_result.get("ok"):
        return {"ok": False, "status": "failed", "error": storage_result.get("storage_error") or "storage_failed", "app_key": app_key}
    storage_metadata = storage_result.get("metadata") if isinstance(storage_result.get("metadata"), dict) else {}

    registry_metadata = {
        "company_code": company,
        "app_key": app_key,
        "source": "bulk_import",
        "import_batch_id": batch_id,
        "original_filename": original_filename,
        "candidate_email": email,
        "candidate_name": candidate_name or None,
        "latest": not governed_identity,
        "versioned_at": now_iso(),
        "is_replacement": bool(governed_identity),
        "had_prior_current_cv": has_current_cv,
        "identity_resolution_id": (
            (identity_resolution or {}).get("resolution_id")
        ),
        "intake_document_id": (
            (identity_resolution or {}).get("intake_document_id")
        ),
        "identity_outcome": (identity_resolution or {}).get("outcome"),
    }
    upsert_file_registry(
        cur,
        company_code=company,
        owner_phone=surrogate_phone,
        subject_type="application",
        subject_key=app_key,
        file_kind="candidate_cv",
        document_type="cv",
        original_filename=original_filename,
        source_path=str(resolved_source),
        local_path=storage_metadata.get("local_path") or str(resolved_source),
        storage_result=storage_result,
        metadata=registry_metadata,
    )
    cur.execute(
        """
        SELECT file_id::text AS file_id
        FROM file_registry
        WHERE subject_type='application' AND subject_key=%s AND file_kind='candidate_cv'
        ORDER BY updated_at DESC LIMIT 1
        """,
        (app_key,),
    )
    file_row = cur.fetchone()
    file_id = (file_row or {}).get("file_id")

    cv_storage = {
        "provider": storage_result.get("provider"),
        "object_key": storage_result.get("storage_object_key"),
        "external_file_id": storage_result.get("external_file_id"),
        "url": storage_result.get("storage_url"),
        "sha256": storage_result.get("content_sha256"),
        "mime_type": storage_result.get("mime_type"),
        "size_bytes": storage_result.get("size_bytes"),
        "status": storage_result.get("storage_status"),
        "stored_at": storage_result.get("stored_at") or now_iso(),
    }
    cv_json = {
        "filename": original_filename,
        "path": storage_metadata.get("local_path") or str(resolved_source),
        "source": "bulk_import",
        "latest": not governed_identity,
        "versioned_at": registry_metadata["versioned_at"],
        "is_replacement": bool(governed_identity),
        "identity_resolution_id": (
            (identity_resolution or {}).get("resolution_id")
        ),
        "intake_document_id": (
            (identity_resolution or {}).get("intake_document_id")
        ),
        "storage": cv_storage,
        "processing": {
            "file_received": True,
            "file_stored": True,
            "text_extracted": False,
            "profile_parsed": False,
            "semantic_indexed": False,
            "status": "pending_async_processing",
            "updated_at": now_iso(),
        },
    }
    app_raw = {
        ("cv_pending" if governed_identity else "cv"): cv_json,
        "cv_received": True,
        "data_source": "production",
        "candidate_name": candidate_name or None,
        "import": {
            "held": not auto_admitted,
            "auto_admitted": auto_admitted,
            "admit_reason": admit_reason if auto_admitted else None,
            "batch_id": batch_id,
            "source": source or "bulk_upload",
            "source_ref": source_ref or original_filename,
            "original_filename": original_filename,
            "needs_role": held_status == "needs_role",
            "role_suggestion": role_suggestion or None,
            "imported_at": now_iso(),
            "identity_resolution_id": (
                (identity_resolution or {}).get("resolution_id")
            ),
            "identity_review_warning": bool(held_review_materialization),
            "identity_outcome": (identity_resolution or {}).get("outcome"),
            "identity_terminal_reason": (
                (identity_resolution or {}).get("held_terminal_reason")
                if held_review_materialization
                else None
            ),
            "held_materialization": (
                "blocked_identity" if held_review_materialization else None
            ),
        },
    }
    cur.execute(
        """
        INSERT INTO applications
            (app_key, phone, company_code, position_code, position_title, status, current_step,
             cv_received, cv_received_at, screening_status, raw_json, data_source, data_source_detail,
             import_batch_id, source_ref, ingested_at, created_at, updated_at)
        VALUES (%s,%s,%s,%s,%s,%s,%s,true,CURRENT_DATE,'not_started',%s,'production',%s,%s,%s,now(),CURRENT_DATE,CURRENT_DATE)
        ON CONFLICT (app_key) DO UPDATE
          SET raw_json=COALESCE(applications.raw_json,'{}'::jsonb) || EXCLUDED.raw_json,
              position_title=COALESCE(applications.position_title, EXCLUDED.position_title),
              cv_received=true,
              cv_received_at=COALESCE(applications.cv_received_at, CURRENT_DATE),
              import_batch_id=COALESCE(applications.import_batch_id, EXCLUDED.import_batch_id),
              source_ref=COALESCE(applications.source_ref, EXCLUDED.source_ref),
              updated_at=CURRENT_DATE
        """,
        (
            app_key,
            surrogate_phone,
            company,
            position_code,
            position_title or None,
            held_status,
            current_step,
            Json(json_safe(app_raw)),
            f"bulk_import:{batch_id}",
            batch_id,
            source_ref or original_filename,
        ),
    )
    try:
        import prehire_ownership as _own

        _own.apply_application_owner_inherit(
            cur,
            company_code=company,
            app_key=app_key,
            position_code=position_code,
            actor_user_id=None,
            reason="inherit_from_job_recruiter_on_import",
        )
    except Exception:
        pass

    document_id = None
    try:
        doc_payload = {**cv_json, "received_at": now_iso(), "storage": cv_storage}
        cur.execute(
            """
            INSERT INTO candidate_documents
                (app_key, phone, document_type, filename, local_path, source, extraction_status,
                 drive_file_id, drive_url, metadata, raw_json, received_at)
            VALUES (%s,%s,'cv',%s,%s,'bulk_import','pending_extraction',%s,%s,%s,%s,CURRENT_DATE)
            RETURNING document_id::text
            """,
            (
                app_key,
                surrogate_phone,
                original_filename,
                storage_metadata.get("local_path") or str(resolved_source),
                storage_result.get("external_file_id"),
                storage_result.get("storage_url"),
                Json(registry_metadata),
                Json(doc_payload),
            ),
        )
        doc_row = cur.fetchone()
        document_id = (doc_row or {}).get("document_id")
        if governed_identity:
            _inbound_cv_authority.record_candidate_identity_keys(
                cur,
                company_code=company,
                candidate_phone=surrogate_phone,
                resolution=identity_resolution or {},
            )
    except Exception:
        pass

    extraction_policy = str(extraction_policy or "enqueue").strip().lower()
    if extraction_policy not in {"enqueue", "defer"}:
        raise ValueError(f"invalid_extraction_policy:{extraction_policy}")
    job_id = None
    extraction_deferred = False
    if document_id and extraction_policy == "enqueue":
        try:
            job_id = ensure_application_cv_extraction_job(
                cur,
                company_code=company,
                document_id=str(document_id),
                app_key=app_key,
                intake_document_id=(
                    str((identity_resolution or {}).get("intake_document_id") or "") or None
                ),
                source_channel=str(source or "bulk_import"),
                priority=int(extraction_priority if extraction_priority is not None else (50 if position_code else 100)),
                job_context=extraction_job_context,
            )
        except Exception:
            logger.exception(
                "canonical_cv_enqueue_failed app_key=%s document_id=%s",
                app_key,
                document_id,
            )
            processing = dict(cv_json.get("processing") or {})
            processing.update(
                {
                    "status": "failed",
                    "error": "canonical_enqueue_failed",
                    "updated_at": now_iso(),
                }
            )
            cv_json["processing"] = processing
            app_raw["cv" if not governed_identity else "cv_pending"] = cv_json
            cur.execute(
                "UPDATE applications SET raw_json=%s, updated_at=now() WHERE app_key=%s AND company_code=%s",
                (Json(json_safe(app_raw)), app_key, company),
            )
            job_id = None
    elif document_id:
        extraction_deferred = True
        cur.execute(
            """
            UPDATE candidate_documents
            SET extraction_status='deferred_migration',
                raw_json=COALESCE(raw_json,'{}'::jsonb) || %s::jsonb
            WHERE document_id=%s::uuid
            """,
            (
                Json(
                    {
                        "processing": {
                            "status": "deferred_migration",
                            "reason": "synthetic_migration_qualification",
                            "updated_at": now_iso(),
                        }
                    }
                ),
                document_id,
            ),
        )

    return {
        "ok": True,
        "status": held_status,
        "auto_admitted": auto_admitted,
        "admit_reason": admit_reason if auto_admitted else None,
        "app_key": app_key,
        "surrogate_phone": surrogate_phone,
        "file_id": file_id,
        "document_id": document_id,
        "intake_job_id": job_id,
        "extraction_deferred": extraction_deferred,
        "checksum": checksum,
        "size_bytes": size_bytes,
        "mime_type": resolved_mime,
        "position_code": position_code or None,
    }


def handle_candidate_file_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    media = request.media or {}
    if not has_current_media_upload(media):
        return None
    media_type = str(media.get("type") or media.get("mime_type") or "").lower()
    allowed_media = {
        "application/pdf",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    }
    if not (media_type.startswith("image/") or media_type in allowed_media):
        return {
            "ok": False,
            "error": "unsupported_candidate_cv_media",
            **candidate_message_result("cv_invalid", request=request),
        }
    caption_application = None
    caption_apply = parse_apply_code_text(request.raw_text)
    if caption_apply:
        resolved_caption_role = resolve_public_role_by_apply_code(caption_apply["apply_code"])
        caption_role = (
            resolved_caption_role.get("role")
            if isinstance(resolved_caption_role.get("role"), dict)
            else None
        )
        if not resolved_caption_role.get("ok") or not caption_role:
            held = hold_candidate_pending_media(request)
            unavailable = candidate_job_unavailable_message(
                request,
                str(resolved_caption_role.get("error") or ""),
            )
            return {
                "ok": False,
                "error": resolved_caption_role.get("error") or "apply_code_not_found",
                "reply": unavailable["text"],
                "pending_media": held,
                "application_created": False,
            }
        caption_application = active_same_role_application(request, caption_role)
        if not caption_application:
            held = hold_candidate_pending_media(request)
            preview = candidate_job_preview_stub(request, caption_role)
            context = upsert_candidate_job_context(
                request,
                role=caption_role,
                preview_locale=preview["locale"],
                preview_template_version=preview["template_version"],
            )
            delivery = None
            if _jobs_stage_b.stage_b_enabled():
                delivery = _jobs_stage_b.deliver_and_stamp_job_preview(
                    sys.modules[__name__],
                    request=request,
                    context=context,
                    preview_text=preview["text"],
                    company_code=str(caption_role.get("company_code") or ""),
                )
                refreshed = active_candidate_job_context(request)
                if refreshed:
                    context = refreshed
            held_message = candidate_message_payload(
                "cv_held_for_job_context",
                request=request,
                locale=preview["locale"],
                role=caption_role.get("title_ar")
                if preview["locale"] == "ar"
                else caption_role.get("title_en")
                or caption_role.get("title")
                or caption_role.get("position_code")
                or "the role",
            )
            reply_text = f"{preview['text']}\n\n{held_message['text']}"
            if delivery and delivery.get("suppress_reply"):
                # Preview already live-sent; still send held note via channel.
                reply_text = held_message["text"]
            return {
                "ok": True,
                "reply": reply_text,
                "pending_media": held,
                "job_context": context,
                "preview_delivery": delivery,
                "role": caption_role,
                "application_created": False,
                "intent": "candidate_cv_caption_job_context_bound",
            }
    job_context = None if caption_application else active_candidate_job_context(request)
    if job_context:
        held = hold_candidate_pending_media(request)
        resolved_role = resolve_public_role_by_apply_code(str(job_context.get("apply_code") or ""))
        role = resolved_role.get("role") if isinstance(resolved_role.get("role"), dict) else None
        if not resolved_role.get("ok") or not role:
            unavailable = candidate_job_unavailable_message(request, str(resolved_role.get("error") or ""))
            return {
                "ok": False,
                "error": resolved_role.get("error") or "job_not_accepting",
                "reply": unavailable["text"],
                "pending_media": held,
                "job_context": job_context,
            }
        locale = _candidate_messages.normalize_locale(job_context.get("preview_locale"))
        title = (
            role.get("title_ar")
            if locale == "ar"
            else role.get("title_en")
            or role.get("title")
            or role.get("position_code")
            or "the role"
        )
        # Stage B: CV after preview_sent_at counts as apply intent → convert
        # only for the dedicated public canary job.
        if job_context.get("preview_sent_at") and _jobs_stage_b.stage_b_convert_allowed_for_job(
            position_code=str(job_context.get("position_code") or ""),
            apply_code=str(job_context.get("apply_code") or ""),
        ):
            provider_id = ""
            if isinstance(request.metadata, dict):
                provider_id = str(
                    request.metadata.get("provider_message_id")
                    or request.metadata.get("message_id")
                    or ""
                )
            pending_id = str(held.get("pending_id") or "")
            idem = f"{_jobs_stage_b.CONVERT_CV_PREFIX}{job_context.get('context_id')}:{pending_id or provider_id or 'cv'}"
            converted = _jobs_stage_b.convert_job_context_to_application(
                sys.modules[__name__],
                request,
                trigger="qualifying_cv",
                idempotency_key=idem,
                media=media,
            )
            if converted.get("ok"):
                application = converted.get("application") if isinstance(converted.get("application"), dict) else None
                if converted.get("existing_application"):
                    return {
                        "ok": True,
                        **candidate_message_result(
                            "job_context_existing_application",
                            request=request,
                            application=application,
                            locale=locale,
                            role=title,
                        ),
                        "application": application,
                        "application_created": False,
                        "job_context": converted.get("job_context"),
                        "convert": converted,
                        "pending_media": held,
                        "cv_counts_as_apply_intent": True,
                        "intent": "candidate_cv_qualifying_existing",
                    }
                cv_attach = converted.get("cv_attach") if isinstance(converted.get("cv_attach"), dict) else None
                if cv_attach and cv_attach.get("ok"):
                    return {
                        "ok": True,
                        **candidate_message_result(
                            "file_received_checking",
                            request=request,
                            application=application,
                            locale=locale,
                        ),
                        "application": application,
                        "application_created": bool(converted.get("application_created")),
                        "job_context": converted.get("job_context"),
                        "convert": converted,
                        "cv_counts_as_apply_intent": True,
                        "intent": "candidate_cv_qualifying_converted",
                    }
                return {
                    "ok": True,
                    **candidate_message_result(
                        "role_resolved_cv_request",
                        request=request,
                        application=application,
                        locale=locale,
                        role=title,
                    ),
                    "application": application,
                    "application_created": bool(converted.get("application_created")),
                    "job_context": converted.get("job_context"),
                    "convert": converted,
                    "cv_counts_as_apply_intent": True,
                    "intent": "candidate_cv_qualifying_converted_no_attach",
                }
            # Convert failed after hold — keep Stage A hold reply for safety.
        return {
            "ok": True,
            **candidate_message_result("cv_held_for_job_context", request=request, locale=locale, role=title),
            "pending_media": held,
            "job_context": job_context,
            "role": role,
            "application_created": False,
            "cv_counts_as_apply_intent": bool(job_context.get("preview_sent_at")),
            "intent": "candidate_cv_held_for_job_context",
        }
    if caption_application:
        application = caption_application
    elif canonical_lifecycle_enabled():
        import recruiting_lifecycle as _rl

        resolved = _rl.resolve_conversation_application(
            sys.modules[__name__],
            phone=request.sender_phone,
            conversation_id=request.conversation_id,
            company_code=request_company_code(request, default=None),
            account_id=request.account_id,
            allow_single_eligible=True,
        )
        if not resolved.get("ok"):
            error = str(resolved.get("error") or "ambiguous_applications")
            held = hold_candidate_pending_media(request)
            return {
                "ok": True,
                "error": error,
                **candidate_message_result("cv_held_needs_role", request=request),
                "matches": resolved.get("matches") or [],
                "pending_media": held,
                "application_created": False,
            }
        application = resolved.get("application")
        if not isinstance(application, dict):
            return None
        if resolved.get("requires_bind") and request.conversation_id:
            binding = _rl.bind_conversation_application(
                sys.modules[__name__],
                company_code=str(application.get("company_code") or ""),
                conversation_id=str(request.conversation_id),
                phone=str(application.get("phone") or request.sender_phone or ""),
                app_key=str(application.get("app_key") or ""),
                account_id=request.account_id,
                bound_reason="single_eligible",
            )
            if not binding.get("ok"):
                return {
                    "ok": False,
                    "error": binding.get("error") or "application_binding_failed",
                    **candidate_message_result("ambiguous_application", request=request),
                }
    else:
        return {
            "ok": False,
            "error": "canonical_lifecycle_disabled",
            **candidate_message_result("cv_held_needs_role", request=request),
        }
    if not application:
        held = hold_candidate_pending_media(request)
        return {
            "ok": True,
            "error": "no_active_application",
            **candidate_message_result("cv_held_needs_role", request=request),
            "pending_media": held,
            "application_created": False,
        }
    if not company_has_module(application.get("company_code"), "pre_hiring"):
        return {
            "ok": False,
            "error": "module_disabled",
            "company_code": application.get("company_code"),
            "required_module": "pre_hiring",
        }
    locale = candidate_message_payload("file_received_checking", request=request, application=application)["locale"]
    with db_connect() as conn:
        with conn.cursor() as cur:
            result = register_candidate_cv_file(
                cur,
                application=application,
                media=media,
                metadata={
                    "conversation_id": request.conversation_id,
                    "account_id": request.account_id,
                    "raw_text": request.raw_text,
                    "candidate_locale": locale,
                },
            )
        conn.commit()
    if result.get("ok"):
        if result.get("duplicate") and result.get("already_validated"):
            template_key = "cv_updated_accepted" if result.get("is_replacement") else "cv_accepted"
            result.update(candidate_message_result(template_key, request=request, application=application, locale=locale))
            return result
        import recruiting_lifecycle as _rl

        if result.get("is_replacement"):
            if not request.conversation_id or not result.get("document_id"):
                return {
                    **result,
                    "ok": False,
                    "error": "replacement_confirmation_unavailable",
                    "reply": "I stored the file safely, but I could not prepare CV replacement confirmation. Your current CV remains unchanged.",
                }
            target_payload = {
                "document_id": str(result["document_id"]),
                "content_sha256": (result.get("storage") or {}).get("content_sha256"),
            }
            minted = _rl.mint_candidate_action_confirmation(
                sys.modules[__name__],
                company_code=str(application.get("company_code") or ""),
                app_key=str(application.get("app_key") or ""),
                action="replace_cv",
                observed_stage=str(application.get("status") or ""),
                observed_version=int(application.get("lifecycle_version") or 0),
                target_payload=target_payload,
                actor_user_id=None,
                actor_phone=request.sender_phone,
                actor_type="candidate",
                channel="whatsapp",
                permissions=set(),
                idempotency_key=f"replace-cv:{application.get('company_code')}:{application.get('app_key')}:{result['document_id']}",
            )
            if not minted.get("ok"):
                return {
                    **result,
                    "ok": False,
                    "error": minted.get("error") or "replacement_confirmation_unavailable",
                    "reply": "I stored the file safely, but your current CV remains unchanged.",
                }
            confirmation = minted["confirmation"]
            pending = {
                "type": "replace_cv",
                "status": "pending",
                "app_key": application.get("app_key"),
                "company_code": application.get("company_code"),
                "confirmation_id": confirmation.get("confirmation_id"),
                "confirmation_token": confirmation.get("confirmation_token"),
                "observed_stage": confirmation.get("observed_stage"),
                "observed_version": confirmation.get("observed_version"),
                "target_payload": target_payload,
                "requested_at": now_iso(),
            }
            state = _rl.update_candidate_conversation_state(
                sys.modules[__name__],
                company_code=str(application.get("company_code") or ""),
                conversation_id=str(request.conversation_id),
                phone=str(application.get("phone") or request.sender_phone),
                app_key=str(application.get("app_key") or ""),
                updates={"pending_candidate_action": pending},
            )
            if not state.get("ok"):
                return {**result, "ok": False, "error": state.get("error") or "replacement_confirmation_unavailable"}
            result.update(
                {
                    "status": "needs_confirmation",
                    "intent": "candidate_cv_replacement_confirmation_required",
                    "reply": (
                        "وصلتني السيرة الجديدة. أرسل «تأكيد» لاستبدال السيرة الحالية، أو «إلغاء» للاحتفاظ بالحالية."
                        if locale == "ar"
                        else "I received the new CV. Reply CONFIRM to replace your current CV, or CANCEL to keep the current one."
                    ),
                }
            )
            return result
        _rl.mark_cv_received(
            sys.modules[__name__],
            application=application,
            channel="whatsapp",
            conversation_id=request.conversation_id,
        )
        result.update(candidate_message_result("file_received_checking", request=request, application=application, locale=locale))
    else:
        result.update(candidate_message_result("cv_invalid", request=request, application=application, locale=locale))
    return result


def extract_pdf_text_best_effort(path: Path) -> tuple[str, str, str | None]:
    """Best-effort PDF text extraction without making receipt depend on parsing.

    Prefer `pdftotext` when installed. Clean digital PDFs stay local. Scanned /
    image-only / corrupt pages are routed by `extract_candidate_cv_document`.
    """
    result = _cv_extraction.extract_cv_document(path, mime_type="application/pdf")
    # When Mistral is disabled and OCR is required, still return local text + error
    # so callers preserve prior scanned-PDF failure behavior.
    if result.method.startswith("pdftotext") or result.method == "pdftotext":
        if result.quality_ok:
            return result.text, "pdftotext", None
        if result.error == "ocr_required_mistral_disabled":
            return result.text, "pdftotext", result.error
        return result.text, "pdftotext", result.error or "no_text_extracted"
    if result.quality_ok and result.text:
        return result.text, result.method, None
    # Literal fallback for environments without poppler (dev only).
    pdftotext = shutil.which("pdftotext")
    if not pdftotext:
        try:
            raw = path.read_bytes()
            strings = []
            for match in re.finditer(rb"\(([^()]{3,500})\)", raw):
                text = match.group(1).decode("latin-1", errors="ignore")
                text = text.replace("\\n", "\n").replace("\\r", "\n").replace("\\t", " ")
                if re.search(r"[A-Za-z\u0600-\u06FF]", text):
                    strings.append(text)
            extracted = "\n".join(strings).strip()
            if extracted and _cv_extraction.cv_text_quality_ok(extracted):
                return extracted, "pdf-literal-fallback", None
            return "", "pdf-literal-fallback", "no_text_extracted"
        except Exception as exc:
            return "", "pdf-literal-fallback", str(exc)
    return result.text, result.method, result.error


def _cv_db_execute_factory(cur: Any) -> Any:
    def _execute(sql: str, params: tuple[Any, ...] | None = None, fetchone: bool = False) -> Any:
        cur.execute(sql, params or ())
        if fetchone:
            return cur.fetchone()
        return None

    return _execute


def _gpt_vision_rescue_adapter(path: Path, mime_type: str) -> tuple[str, _cv_extraction.EngineCallMeta]:
    """Retired: never calls GPT. Kept as a hard no-op guard if still wired."""

    _cv_extraction.record_blocked_cv_gpt_rescue_attempt()
    meta = _cv_extraction.EngineCallMeta(
        stage="vision_rescue",
        tier="gpt_vision_rescue",
        provider="none",
        actual_request_model="retired",
        error="cv_gpt_vision_rescue_retired",
        quality_ok=False,
        retention="none_sent",
    )
    return "", meta


def extract_candidate_cv_document(
    path_value: str | None,
    mime_type: str | None = None,
    *,
    company_code: str | None = None,
    document_id: str | None = None,
    app_key: str | None = None,
    cur: Any | None = None,
) -> _cv_extraction.ExtractionResult:
    path = Path(str(path_value or ""))
    if not path.exists() or not path.is_file():
        return _cv_extraction.ExtractionResult(text="", method="missing-file", error="file_not_found")
    guessed = str(mime_type or mimetypes.guess_type(path.name)[0] or "").lower()
    suffix = path.suffix.lower()
    if guessed.startswith("text/") or suffix in {".txt", ".md", ".csv"}:
        try:
            text = path.read_text(errors="ignore").strip()
            result = _cv_extraction.ExtractionResult(
                text=text,
                method="text",
                quality_ok=_cv_extraction.cv_text_quality_ok(text),
                error=None if text else "no_text_extracted",
                content_sha256=_cv_extraction.sha256_bytes(path.read_bytes()) if path.exists() else None,
            )
        except Exception as exc:
            result = _cv_extraction.ExtractionResult(text="", method="text", error=str(exc))
        # AnyDoc office authority/shadow — format-specific; CSV MD-only never replaces text.
        try:
            import anydoc_office_authority as _anydoc_office_authority

            result = _anydoc_office_authority.maybe_run_and_attach(
                result,
                path,
                mime_type=guessed or mime_type,
                company_code=company_code,
            )
        except Exception:
            logging.getLogger("wathefni.anydoc_office_authority").exception(
                "anydoc_office_authority_hook_fail_open"
            )
        return result
    if guessed in {"application/vnd.openxmlformats-officedocument.wordprocessingml.document"} or suffix == ".docx":
        # Local-first DOCX v2: structure/provenance locally; Mistral only for
        # embedded text-candidate images. Ordinary DOCX text never calls OCR.
        # AnyDoc may become primary local normalization when authority flag is on
        # and quality gates pass; existing DOCX parser remains immediate fallback.
        db_execute = _cv_db_execute_factory(cur) if cur is not None else None
        result = _cv_docx.extract_docx_document(
            path,
            company_code=company_code,
            document_id=document_id,
            app_key=app_key,
            db_execute=db_execute,
        )
        try:
            import anydoc_office_authority as _anydoc_office_authority

            result = _anydoc_office_authority.maybe_run_and_attach(
                result,
                path,
                mime_type=guessed or mime_type,
                company_code=company_code,
            )
        except Exception:
            logging.getLogger("wathefni.anydoc_office_authority").exception(
                "anydoc_office_authority_hook_fail_open"
            )
        return result
    db_execute = _cv_db_execute_factory(cur) if cur is not None else None
    # vision_rescue intentionally omitted — CV GPT rescue retired.
    result = _cv_extraction.extract_cv_document(
        path,
        mime_type=guessed or mime_type,
        company_code=company_code,
        document_id=document_id,
        app_key=app_key,
        db_execute=db_execute,
        vision_rescue=None,
    )
    # Office authority (pptx/odt/ods/xlsx) + shadow-only legacy; PDF/images denied inside.
    try:
        import anydoc_office_authority as _anydoc_office_authority

        result = _anydoc_office_authority.maybe_run_and_attach(
            result,
            path,
            mime_type=guessed or mime_type,
            company_code=company_code,
        )
    except Exception:
        logging.getLogger("wathefni.anydoc_office_authority").exception(
            "anydoc_office_authority_hook_fail_open"
        )
    return result


def extract_candidate_cv_text_from_path(path_value: str | None, mime_type: str | None = None) -> tuple[str, str, str | None]:
    result = extract_candidate_cv_document(path_value, mime_type)
    if result.quality_ok and result.text:
        return result.text, result.method, None
    if result.text and not result.error:
        return result.text, result.method, None
    return result.text, result.method, result.error or ("no_text_extracted" if not result.text else "low_quality_text")


def extract_image_cv_text_with_vision(path: Path, mime_type: str) -> tuple[str, str, str | None]:
    """Retired CV GPT vision entrypoint — never calls OpenAI/planner."""

    _cv_extraction.record_blocked_cv_gpt_rescue_attempt()
    return "", "gpt_vision_rescue", "cv_gpt_vision_rescue_retired"


def cv_text_quality_ok(text: str | None) -> bool:
    return _cv_extraction.cv_text_quality_ok(text)


def candidate_name_is_generic_heading(value: Any) -> bool:
    normalized = re.sub(r"[\W_]+", " ", str(value or "").strip().lower(), flags=re.UNICODE)
    normalized = re.sub(r"\s+", " ", normalized).strip()
    generic = {
        "cv",
        "resume",
        "curriculum vitae",
        "professional resume",
        "professional profile",
        "personal profile",
        "personal information",
        "candidate profile",
        "السيرة الذاتية",
        "سيرة ذاتية",
        "الملف الشخصي",
        "المعلومات الشخصية",
        "بيانات شخصية",
    }
    return not normalized or normalized in generic


def parse_candidate_profile_from_cv_text(text: str, *, fallback_name: str | None = None, fallback_phone: str | None = None) -> dict[str, Any]:
    contacts = _cv_extraction.deterministic_contact_profile(text)
    normalized = _cv_extraction.normalize_cv_text_for_contacts(text)
    lines = [line.strip() for line in str(text or "").splitlines() if line.strip()]
    email = contacts.get("email") or _extract_email_from_text(normalized)
    phone = contacts.get("phone") or None
    if not phone:
        phone_match = re.search(r"(?:\+?965)?\s?([569]\d{7})\b", normalized or "")
        phone = digits(phone_match.group(0)) if phone_match else digits(fallback_phone)
    name = fallback_name if not candidate_name_is_generic_heading(fallback_name) else None
    if lines:
        first = lines[0]
        # Allow bilingual names (Arabic and/or Latin letters), still reject emails/phones.
        if (
            2 <= len(first.split()) <= 6
            and not _extract_email_from_text(first)
            and not re.search(r"\d", _cv_extraction.normalize_digits(first))
            and re.search(r"[A-Za-z\u0600-\u06FF]", first)
            and not candidate_name_is_generic_heading(first)
        ):
            name = first
    skills: list[str] = []
    skill_capture = False
    for line in lines:
        lower = line.lower()
        if any(marker in lower for marker in ("key skills", "skills", "technical skills")) or any(
            marker in line for marker in ("المهارات", "مهارات")
        ):
            skill_capture = True
            continue
        if skill_capture and (
            any(marker in lower for marker in ("experience", "education", "languages", "professional summary"))
            or any(marker in line for marker in ("الخبرة", "الخبرات", "التعليم", "اللغات", "الملخص"))
        ):
            break
        if skill_capture:
            item = re.sub(r"^[•\\-\\*\\d\\.\\s]+", "", line).strip()
            if item and len(item) <= 80:
                skills.append(item)
    profile = {
        "name": name,
        "email": email,
        "phone": phone or None,
        "skills": skills[:20],
        "summary": " ".join(lines[:4])[:800] if lines else None,
        "urls": contacts.get("urls") or [],
        "dates": contacts.get("dates") or [],
        "headings": contacts.get("headings") or [],
        "parsed_at": now_iso(),
        "parser": "regex_cv_profile_v1+deterministic_contacts_v1",
        "field_provenance": contacts.get("field_provenance") or {},
    }
    return profile


def extract_structured_candidate_profile_from_cv_text(text: str, *, application: dict[str, Any]) -> dict[str, Any] | None:
    provider = planner_provider_config()
    if not provider or not text.strip():
        return None
    system = (
        "You extract structured candidate profile facts from one CV. "
        "Return JSON only. Do not invent. Use null/empty arrays when not visible. "
        "Keep evidence short and quote/paraphrase only visible CV facts. "
        "Support Arabic and bilingual CVs; preserve original name spelling."
    )
    payload = {
        "role": application.get("position_title") or application.get("position_code"),
        "cv_text": text[:12000],
        "json_schema": {
            "name": "string|null",
            "email": "string|null",
            "phone": "string|null",
            "summary": "short string|null",
            "skills": ["string"],
            "tools": ["string"],
            "experience_years": "number|null",
            "education": "string|null",
            "languages": ["string"],
            "role_relevant_experience": "short string|null",
            "confidence": "number 0..1",
            "evidence": ["short string"],
        },
    }
    if provider.get("api") == "openai-responses":
        body = {
            "model": provider["model"],
            "temperature": 0,
            "input": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    else:
        body = {
            "model": provider["model"],
            "temperature": 0,
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception:
        return None
    result = extract_json_object(extract_model_text(parsed))
    if not isinstance(result, dict):
        return None
    try:
        confidence = float(result.get("confidence") or 0)
    except Exception:
        confidence = 0.0
    result["confidence"] = confidence
    result["parser"] = "llm_cv_profile_v1"
    result["parsed_at"] = now_iso()
    result["actual_request_model"] = provider.get("model")
    result["provider"] = provider.get("provider")
    return result


def merge_candidate_profiles(regex_profile: dict[str, Any], llm_profile: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(llm_profile, dict) or float(llm_profile.get("confidence") or 0) < 0.55:
        return regex_profile
    merged = dict(regex_profile)
    for key in ("name", "email", "phone", "summary", "education", "experience_years", "role_relevant_experience"):
        if llm_profile.get(key) not in (None, "", [], {}):
            merged[key] = llm_profile.get(key)
    for key in ("skills", "tools", "languages", "evidence"):
        if isinstance(llm_profile.get(key), list) and llm_profile[key]:
            merged[key] = llm_profile[key]
    merged["llm_profile"] = llm_profile
    merged["parser"] = "llm_cv_profile_v1+regex_fallback"
    merged["parsed_at"] = now_iso()
    return merged


def merge_candidate_profiles_with_authority(
    existing_profile: dict[str, Any] | None,
    regex_profile: dict[str, Any],
    llm_profile: dict[str, Any] | None,
) -> dict[str, Any]:
    merged = merge_candidate_profiles(regex_profile, llm_profile)
    merged = _cv_extraction.preserve_human_fields(existing_profile, merged)
    if candidate_name_is_generic_heading(merged.get("name")):
        merged["name"] = None
    return merged


def screening_questions_for_application(application: dict[str, Any]) -> list[dict[str, Any]]:
    company_code = str(application.get("company_code") or "").strip().upper()
    if not company_code:
        return []
    position_code = str(application.get("position_code") or "")
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT metadata, raw_json FROM positions WHERE company_code=%s AND position_code=%s LIMIT 1",
                (company_code, position_code),
            )
            row = cur.fetchone()
    if row:
        metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
        raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
        for source in (metadata, raw_json):
            questions = source.get("screening_questions") if isinstance(source, dict) else None
            if isinstance(questions, list) and questions:
                return [q for q in questions if isinstance(q, dict)]
    role = str(application.get("position_title") or application.get("position_code") or "this role")
    return [
        {"key": "visa_status", "question": "What is your current visa or residency status in Kuwait?", "required": True},
        {"key": "salary_expectation", "question": "What is your expected monthly salary in KD?", "required": True},
        {"key": "availability", "question": "When can you start?", "required": True},
        {"key": "relevant_experience", "question": f"Briefly describe your relevant experience for {role}.", "required": True},
        {"key": "tools", "question": "Which tools, software, or systems are you strongest with?", "required": False},
    ]


def prefill_screening_answers_from_profile(profile: dict[str, Any], questions: list[dict[str, Any]]) -> tuple[dict[str, Any], dict[str, str], dict[str, Any]]:
    answers: dict[str, Any] = {}
    sources: dict[str, str] = {}
    evidence: dict[str, Any] = {}
    haystack = " ".join(str(v) for v in profile.values() if isinstance(v, (str, int, float))).lower()
    for question in questions:
        key = str(question.get("key") or "")
        if question.get("allow_cv_prefill") is not True:
            continue
        qtext = str(question.get("question") or "").lower()
        value = None
        if key in {"experience_years", "finance_experience_years"} and profile.get("experience_years") not in (None, ""):
            value = str(profile.get("experience_years"))
        elif key in {"tools", "finance_tools", "stack", "channels"}:
            tools = profile.get("tools") if isinstance(profile.get("tools"), list) else profile.get("skills")
            if isinstance(tools, list) and tools:
                value = ", ".join(str(item) for item in tools[:8])
        elif key in {"relevant_experience", "campaign_examples"} or "experience" in qtext:
            value = profile.get("role_relevant_experience") or profile.get("summary")
        elif key == "visa_status":
            # Only prefill very explicit citizenship/residency evidence.
            if "kuwaiti" in haystack or "كويتي" in haystack:
                value = "Kuwaiti"
        if value:
            answers[key] = value
            sources[key] = "cv_prefill"
            evidence[key] = {"value": value, "profile_parser": profile.get("parser"), "confidence": profile.get("confidence")}
    return answers, sources, evidence


def update_cv_processing_flags(raw_json: dict[str, Any], **updates: Any) -> dict[str, Any]:
    raw = dict(raw_json or {})
    cv = dict(raw.get("cv") or {})
    processing = dict(cv.get("processing") or {})
    processing.update({key: value for key, value in updates.items() if value is not None})
    processing["updated_at"] = now_iso()
    cv["processing"] = processing
    raw["cv"] = cv
    return raw


def upsert_application_semantic_document(
    cur: Any,
    *,
    application: dict[str, Any],
    content: str,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    app_key = str(application.get("app_key") or "")
    if not app_key or not content.strip():
        return {"ok": False, "error": "missing_app_key_or_content"}
    company_code = str(application.get("company_code") or "").strip().upper()
    if not company_code:
        return {"ok": False, "error": "tenant_scope_required"}
    position_code = str(application.get("position_code") or "")
    phone = digits(application.get("phone"))
    title = str(application.get("position_title") or position_code or "Application CV")
    content_hash = hashlib.sha256(content.encode("utf-8")).hexdigest()
    cfg = embedding_provider_config()
    embedding = None
    provider = None
    model = None
    dimensions = None
    if cfg:
        # Voyage document embeddings use input_type=document. Keep separate from
        # query embeddings so ranking remains semantically meaningful.
        body = {"input": [content[:12000]], "model": cfg["model"], "input_type": "document"}
        req = urllib.request.Request(
            cfg["url"],
            data=json.dumps(body).encode("utf-8"),
            headers={"Authorization": f"Bearer {cfg['api_key']}", "Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(req, timeout=18) as resp:
                parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
            data = parsed.get("data") if isinstance(parsed, dict) else None
            raw_embedding = data[0].get("embedding") if isinstance(data, list) and data and isinstance(data[0], dict) else None
            if isinstance(raw_embedding, list):
                embedding = [float(value) for value in raw_embedding]
                provider = cfg["provider"]
                model = cfg["model"]
                dimensions = len(embedding)
        except Exception:
            embedding = None
    # Local/test environments often have no embedding provider. Persist the
    # extracted CV text index row with an explicit provider marker so extraction
    # can complete (NOT NULL semantic_documents.provider).
    if not provider:
        provider = "none"
        model = model or "unembedded"
        dimensions = dimensions if dimensions is not None else 0
    semantic_id = f"application:{app_key}:cv"
    if embedding:
        cur.execute(
            """
            INSERT INTO semantic_documents
            (semantic_id, entity_type, entity_key, company_code, phone, app_key, position_code, title, content, content_hash, provider, model, dimensions, embedding, metadata, created_at, updated_at)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::vector,%s,now(),now())
            ON CONFLICT (semantic_id) DO UPDATE SET
              content=EXCLUDED.content,
              content_hash=EXCLUDED.content_hash,
              provider=EXCLUDED.provider,
              model=EXCLUDED.model,
              dimensions=EXCLUDED.dimensions,
              embedding=EXCLUDED.embedding,
              metadata=EXCLUDED.metadata,
              updated_at=now()
            """,
            (
                semantic_id,
                "application",
                app_key,
                company_code,
                phone,
                app_key,
                position_code,
                title,
                content,
                content_hash,
                provider,
                model,
                dimensions,
                pgvector_literal(embedding),
                Json(json_safe(metadata or {})),
            ),
        )
    else:
        cur.execute(
            """
            INSERT INTO semantic_documents
            (semantic_id, entity_type, entity_key, company_code, phone, app_key, position_code, title, content, content_hash, provider, model, dimensions, metadata, created_at, updated_at)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,now(),now())
            ON CONFLICT (semantic_id) DO UPDATE SET
              content=EXCLUDED.content,
              content_hash=EXCLUDED.content_hash,
              provider=EXCLUDED.provider,
              model=EXCLUDED.model,
              dimensions=EXCLUDED.dimensions,
              embedding=NULL,
              metadata=EXCLUDED.metadata,
              updated_at=now()
            """,
            (
                semantic_id,
                "application",
                app_key,
                company_code,
                phone,
                app_key,
                position_code,
                title,
                content,
                content_hash,
                provider,
                model,
                dimensions,
                Json(json_safe({**(metadata or {}), "embedding_status": "missing"})),
            ),
        )
    return {"ok": True, "semantic_id": semantic_id, "embedded": bool(embedding), "content_hash": content_hash}


def notify_candidate_cv_validation(
    application: dict[str, Any],
    *,
    document_id: str,
    accepted: bool,
) -> dict[str, Any]:
    try:
        assert_application_communication_allowed(application, kind="cv_validation")  # HELD_COMMUNICATION_AUTHORITY_STAGING_PATCH
    except CandidateCommunicationAuthorityError as exc:
        return {**exc.as_result(), "skipped": "held_or_non_live_application"}
    app_key = str(application.get("app_key") or "")
    company = str(application.get("company_code") or "").upper()
    phone = digits(application.get("phone"))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_documents
                SET metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                    updated_at=now()
                WHERE document_id=%s
                  AND COALESCE(metadata->'candidate_validation_notification'->>'attempted_at','')=''
                RETURNING metadata
                """,
                (
                    Json({"candidate_validation_notification": {"attempted_at": now_iso(), "status": "sending"}}),
                    document_id,
                ),
            )
            reserved = cur.fetchone()
        conn.commit()
    if not reserved:
        return {"ok": True, "idempotent": True, "skipped": "candidate_validation_already_notified"}
    metadata = reserved.get("metadata") if isinstance(reserved.get("metadata"), dict) else {}
    locale = str(metadata.get("candidate_locale") or "")
    is_replacement = bool(metadata.get("is_replacement"))
    template_key = "cv_invalid"
    if accepted:
        template_key = "cv_updated_accepted" if is_replacement else "cv_accepted"
    template = candidate_message_payload(template_key, application=application, locale=locale)
    result = send_octopus_whatsapp(
        account_id=metadata.get("account_id"),
        phone=phone,
        text=template["text"],
        subject_type="candidate",
        subject_key=app_key,
        message_kind=template["template_key"],
        company_code=company,
        audience="candidate",
    )
    notification = {
        **template,
        "attempted_at": now_iso(),
        "status": "dry_run" if result.get("dry_run") else "sent" if result.get("ok") else "failed",
        "send_result": json_safe(result),
    }
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_documents
                SET metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                    updated_at=now()
                WHERE document_id=%s
                """,
                (Json({"candidate_validation_notification": notification}), document_id),
            )
        conn.commit()
    return {"ok": bool(result.get("ok")), "template": template, "send": json_safe(result)}


def process_candidate_cv_document(document_id: str, *, dry_run: bool = False, send_screening: bool = False) -> dict[str, Any]:
    # Candidate screening is deliberately not auto-sent from CV validation.
    send_screening = False
    lease_owner = f"cv-worker-{os.getpid()}-{uuid.uuid4().hex[:8]}"
    lease_key: str | None = None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT cd.*, cd.raw_json AS document_raw_json, cd.metadata AS document_metadata,
                       a.*, c.name AS candidate_name, c.email AS candidate_email,
                       c.profile AS candidate_profile, c.raw_json AS candidate_raw_json,
                       intake_authority.document_id::text AS authority_intake_document_id,
                       intake_authority.content_sha256 AS authority_content_sha256,
                       import_authority.source AS authority_import_source
                FROM candidate_documents cd
                JOIN applications a ON a.app_key=cd.app_key
                LEFT JOIN candidates c ON c.phone=a.phone
                LEFT JOIN LATERAL (
                  SELECT d.document_id, d.content_sha256
                  FROM intake_documents d
                  WHERE d.company_code=a.company_code
                    AND d.candidate_document_id=cd.document_id
                  ORDER BY d.created_at DESC
                  LIMIT 1
                ) intake_authority ON true
                LEFT JOIN LATERAL (
                  SELECT b.source
                  FROM import_items i
                  JOIN import_batches b ON b.batch_id=i.batch_id
                  WHERE i.document_id=cd.document_id
                  ORDER BY i.created_at DESC
                  LIMIT 1
                ) import_authority ON true
                WHERE cd.document_id=%s
                """,
                (document_id,),
            )
            row = cur.fetchone()
            if not row:
                return {"ok": False, "error": "document_not_found", "document_id": document_id}
            item = dict(row)
            app = {key: item.get(key) for key in (
                "app_key", "phone", "company_code", "position_code", "apply_code", "position_title", "company_name",
                "status", "current_step", "cv_received", "cv_received_at", "screening_status", "raw_json",
            )}
            raw_json = app.get("raw_json") if isinstance(app.get("raw_json"), dict) else {}
            document_raw_json = item.get("document_raw_json") if isinstance(item.get("document_raw_json"), dict) else {}
            document_metadata = item.get("document_metadata") if isinstance(item.get("document_metadata"), dict) else {}
            document_cv = document_raw_json if "storage" in document_raw_json else {}
            is_replacement = bool(document_metadata.get("is_replacement") or document_cv.get("is_replacement"))
            # Imported candidates (held in the Intake queue OR auto-admitted into
            # Candidates) get their CV extracted and indexed, but are NEVER auto-messaged.
            # HR drives all outreach manually. Held imports also never auto-advance status.
            held_import = str(app.get("status") or "").strip().lower() in HELD_IMPORT_STATUSES
            imported_app = isinstance(raw_json.get("import"), dict)
            if held_import or imported_app:
                send_screening = False
            local_path = item.get("local_path") or document_cv.get("path") or ((raw_json.get("cv") or {}).get("path") if isinstance(raw_json.get("cv"), dict) else None)
            company_code = str(app.get("company_code") or "").strip().upper()
            if not company_code:
                return {"ok": False, "error": "tenant_scope_required", "document_id": document_id}
            governed_intake_document_id = str(
                item.get("authority_intake_document_id")
                or document_metadata.get("intake_document_id")
                or document_cv.get("intake_document_id")
                or ""
            )
            identity_resolution_id = str(
                document_metadata.get("identity_resolution_id")
                or document_cv.get("identity_resolution_id")
                or ""
            )
            is_governed_inbound = bool(
                item.get("authority_intake_document_id")
                or governed_intake_document_id
                or identity_resolution_id
                or str(item.get("authority_import_source") or "").lower()
                in {"email", "email_inbound"}
            )
            if is_governed_inbound:
                if not governed_intake_document_id or not identity_resolution_id:
                    return {
                        "ok": False,
                        "error": "inbound_email_authority_provenance_missing",
                        "document_id": document_id,
                    }
                document_storage = (
                    document_cv.get("storage")
                    if isinstance(document_cv.get("storage"), dict)
                    else {}
                )
                content_sha = str(
                    item.get("authority_content_sha256")
                    or document_storage.get("sha256")
                    or ""
                )
                if not _inbound_cv_authority.binding_is_authorized(
                    cur,
                    company_code=company_code,
                    intake_document_id=governed_intake_document_id,
                    content_sha256=content_sha,
                    candidate_phone=str(app.get("phone") or "") or None,
                    app_key=str(app.get("app_key") or "") or None,
                ):
                    # Held identity-review / conflict apps are scan-clean but not
                    # ownership-bound. Allow extraction into the Held surrogate.
                    if not _inbound_cv_authority.held_review_extraction_authorized(
                        cur,
                        company_code=company_code,
                        intake_document_id=governed_intake_document_id,
                        content_sha256=content_sha,
                        intake_metadata=document_metadata,
                        held_application=held_import,
                    ):
                        return {
                            "ok": False,
                            "error": "document_current_authority_not_proven",
                            "document_id": document_id,
                        }
            db_exec = _cv_db_execute_factory(cur)
            lease = _cv_extraction.acquire_extraction_lease(
                db_exec,
                company_code=company_code,
                document_id=str(document_id),
                stage="cv_extract",
                owner=lease_owner,
            )
            conn.commit()
            if not lease.get("acquired"):
                return {
                    "ok": False,
                    "error": "lease_not_acquired",
                    "document_id": document_id,
                    "lease": json_safe(lease),
                }
            lease_key = str(lease.get("lease_key") or "")
            try:
                mime = None
                if isinstance(document_cv, dict) and document_cv:
                    storage = document_cv.get("storage")
                    if isinstance(storage, dict):
                        mime = storage.get("mime_type")
                if not mime and isinstance(raw_json.get("cv"), dict):
                    storage = raw_json.get("cv", {}).get("storage")
                    if isinstance(storage, dict):
                        mime = storage.get("mime_type")
                extraction = extract_candidate_cv_document(
                    local_path,
                    mime,
                    company_code=company_code,
                    document_id=str(document_id),
                    app_key=str(app.get("app_key") or ""),
                    cur=cur,
                )
                conn.commit()
                text, method, error = extraction.text, extraction.method, extraction.error
                if dry_run:
                    return {
                        "ok": bool(text and extraction.quality_ok),
                        "document_id": document_id,
                        "method": method,
                        "chars": len(text),
                        "error": error,
                        "extraction_meta": {
                            k: v
                            for k, v in extraction.to_dict().items()
                            if k not in {"blocks"}  # keep dry-run payload smaller; never log full text
                        },
                    }
                text_path = None
                if text and (extraction.quality_ok or (text and method.startswith("pdftotext") and not error)):
                    # Accept quality_ok text; also accept strong local digital extracts.
                    if not extraction.quality_ok and not _cv_extraction.cv_text_quality_ok(text):
                        text = ""
                if text and _cv_extraction.cv_text_quality_ok(text):
                    text_dir = WORKSPACE / "data" / "candidates" / digits(app.get("phone")) / "cv-text"
                    text_dir.mkdir(parents=True, exist_ok=True)
                    text_path = text_dir / f"{safe_storage_name(str(app.get('app_key')))}.txt"
                    text_path.write_text(text, encoding="utf-8")
                    regex_profile = parse_candidate_profile_from_cv_text(text, fallback_name=item.get("candidate_name"), fallback_phone=app.get("phone"))
                    llm_profile = extract_structured_candidate_profile_from_cv_text(text, application=app)
                    application_profile = merge_candidate_profiles(regex_profile, llm_profile)
                    candidate_profile = item.get("candidate_profile") if isinstance(item.get("candidate_profile"), dict) else {}
                    profile = merge_candidate_profiles_with_authority(candidate_profile, regex_profile, llm_profile)
                    screening_questions = screening_questions_for_application(app)
                    prefill_answers, prefill_sources, prefill_evidence = prefill_screening_answers_from_profile(profile, screening_questions)
                    source_sha = (
                        (document_cv.get("storage") or {}).get("sha256")
                        if isinstance(document_cv.get("storage"), dict)
                        else None
                    )
                    evidence_materialization = _candidate_cv_evidence.materialize_extracted_cv(
                        cur,
                        db_execute=db_exec,
                        application=app,
                        document_id=str(document_id),
                        local_path=str(local_path or ""),
                        source_content_sha256=source_sha,
                        extracted_text=text,
                        extraction_method=method,
                        extraction_metadata={
                            "source": "cv_worker",
                            "extraction_stage": (extraction.metadata or {}).get("stage"),
                            "extraction_tier": (extraction.metadata or {}).get("tier"),
                            "extraction_provider": (extraction.metadata or {}).get("provider"),
                            "actual_request_model": (extraction.metadata or {}).get("actual_request_model"),
                            "provider_response_model": (extraction.metadata or {}).get("provider_response_model"),
                            "cache_hit": extraction.cache_hit,
                        },
                        semantic_upsert=upsert_application_semantic_document,
                        actor="cv_worker",
                    )
                    semantic = evidence_materialization["semantic"]
                    application_facts = _candidate_cv_facts.extract_application_cv_facts(
                        text,
                        structured_profile=application_profile,
                    )
                    facts_snapshot = _candidate_cv_facts.materialize_facts(
                        cur,
                        evidence_id=str(evidence_materialization["evidence"]["evidence_id"]),
                        company_code=company_code,
                        app_key=str(app.get("app_key") or ""),
                        document_id=str(document_id),
                        source_content_sha256=str(
                            evidence_materialization["evidence"].get("source_content_sha256")
                            or source_sha
                            or ""
                        ),
                        extracted_text_hash=str(
                            evidence_materialization["evidence"].get("extracted_text_hash")
                            or _candidate_cv_facts.text_hash(text)
                        ),
                        facts=application_facts,
                        actor="cv_worker",
                        provenance={
                            "profile_parser": application_profile.get("parser"),
                            "extraction_method": method,
                        },
                    )
                    # CV Extraction V2 (Mistral Document AI) — same durable pipeline, no second intake path.
                    # Publishes to canonical profile-facts only when WATHEFNI_CV_PROFILE_FACTS_V2=true.
                    v2_run = None
                    if _cv_extraction_v2.v2_enabled():
                        try:
                            v2_run = _cv_extraction_v2.run_v2_extraction(
                                local_path=local_path,
                                mime_type=mime,
                                extracted_text=text,
                                blocks=list(getattr(extraction, "blocks", None) or []),
                                prefer_reuse_text=False,
                            )
                            _cv_extraction_v2.materialize_v2(
                                cur,
                                company_code=company_code,
                                app_key=str(app.get("app_key") or ""),
                                document_id=str(document_id),
                                evidence_id=str(evidence_materialization["evidence"]["evidence_id"]),
                                source_content_sha256=str(
                                    evidence_materialization["evidence"].get("source_content_sha256")
                                    or source_sha
                                    or ""
                                ),
                                extracted_text_hash=str(
                                    evidence_materialization["evidence"].get("extracted_text_hash")
                                    or _candidate_cv_facts.text_hash(text)
                                ),
                                run_result=v2_run,
                                publish_to_profile=_cv_extraction_v2.profile_facts_v2_published(),
                            )
                        except Exception as v2_exc:
                            logger.warning(
                                "cv_extraction_v2_failed document_id=%s error=%s",
                                document_id,
                                type(v2_exc).__name__,
                            )
                    # Local Hybrid PDF Engine Wave 1 — staging alternate-path canary only.
                    # Never authoritative. Never replaces Poppler text / V2 current / Ranking.
                    try:
                        import local_hybrid_pdf_engine_canary as _hybrid_canary

                        if (
                            _hybrid_canary.canary_enabled()
                            and local_path
                            and str(Path(str(local_path)).suffix).lower() == ".pdf"
                        ):
                            canary_db = _cv_db_execute_factory(cur)
                            canary_result = _hybrid_canary.run_cv_hybrid_alternate_canary(
                                path=Path(str(local_path)),
                                mime_type=mime,
                                company_code=company_code,
                                authoritative_extraction=extraction,
                                authoritative_v2=v2_run,
                                document_id=str(document_id) if document_id else None,
                                app_key=str(app.get("app_key") or "") or None,
                                db_execute=canary_db,
                            )
                            if isinstance(extraction.metadata, dict):
                                extraction.metadata["local_hybrid_pdf_engine_canary"] = {
                                    "contract": canary_result.get("contract"),
                                    "ok": canary_result.get("ok"),
                                    "acceptance": canary_result.get("acceptance"),
                                    "hybrid_authoritative": False,
                                }
                    except Exception:  # noqa: BLE001 — fail-open
                        logger.exception("local_hybrid_pdf_engine_canary_fail_open")
                    existing_apps = candidate_profile.get("applications") if isinstance(candidate_profile.get("applications"), list) else []
                    updated_apps: list[dict[str, Any]] = []
                    found_app = False
                    for existing_app in existing_apps:
                        if not isinstance(existing_app, dict):
                            continue
                        if str(existing_app.get("app_key") or "") == str(app.get("app_key") or ""):
                            found_app = True
                            updated_apps.append({
                                **existing_app,
                                "status": "screening",
                                "current_step": "screening",
                                "cv_received": True,
                                "screening_status": "pending",
                                "updated_at": now_iso(),
                            })
                        else:
                            updated_apps.append(existing_app)
                    if not found_app:
                        updated_apps.append({
                            "app_key": app.get("app_key"),
                            "company_code": app.get("company_code"),
                            "position_code": app.get("position_code"),
                            "apply_code": app.get("apply_code"),
                            "status": app.get("status"),
                            "current_step": app.get("current_step"),
                            "cv_received": True,
                            "screening_status": "pending",
                            "updated_at": now_iso(),
                        })
                    merged_profile = {
                        **candidate_profile,
                        **{k: v for k, v in profile.items() if v not in (None, "", [], {})},
                        "applications": updated_apps,
                        "current_status": app.get("status"),
                        "current_status_derived": True,
                        "current_status_authority": "applications.status",
                        "active_company_code": app.get("company_code"),
                        "active_position_code": app.get("position_code"),
                        "active_application": {
                            "app_key": app.get("app_key"),
                            "apply_code": app.get("apply_code"),
                            "company_code": app.get("company_code"),
                            "position_code": app.get("position_code"),
                            "updated_at": now_iso(),
                        },
                    }
                    cur.execute(
                        """
                        UPDATE candidates
                        SET name=COALESCE(NULLIF(%s,''), name),
                            email=COALESCE(NULLIF(%s,''), email),
                            profile=%s,
                            raw_json=COALESCE(raw_json,'{}'::jsonb) || %s::jsonb,
                            updated_at=now()
                        WHERE phone=%s
                        """,
                        (
                            profile.get("name"),
                            profile.get("email"),
                            Json(json_safe(merged_profile)),
                            Json(json_safe({"profile_parse": profile})),
                            digits(app.get("phone")),
                        ),
                    )
                    current_screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
                    current_answers = current_screening.get("answers") if isinstance(current_screening.get("answers"), dict) else {}
                    current_sources = current_screening.get("answer_sources") if isinstance(current_screening.get("answer_sources"), dict) else {}
                    current_evidence = current_screening.get("answer_evidence") if isinstance(current_screening.get("answer_evidence"), dict) else {}
                    merged_answers = {**prefill_answers, **current_answers}
                    merged_sources = {**prefill_sources, **current_sources}
                    merged_evidence = {**prefill_evidence, **current_evidence}
                    required_keys = [str(q.get("key") or "") for q in screening_questions if q.get("required") is True and q.get("key")]
                    pending_keys = [key for key in required_keys if not str(merged_answers.get(key) or "").strip()]
                    screening_status = "complete" if not pending_keys and required_keys else "pending"
                    processing_raw = dict(raw_json)
                    if document_cv:
                        processing_raw["cv"] = document_cv
                    processing_raw.pop("cv_pending", None)
                    next_raw = update_cv_processing_flags(
                        processing_raw,
                        file_received=True,
                        file_stored=True,
                        text_extracted=True,
                        profile_parsed=True,
                        semantic_indexed=bool(semantic.get("ok")),
                        facts_materialized=True,
                        facts_status=facts_snapshot.get("status"),
                        facts_contract_version=_candidate_cv_facts.CV_FACTS_CONTRACT_VERSION,
                        screening_prefill_ready=True,
                        screening_prefill_count=len(prefill_answers),
                        status="processed",
                        extraction_method=method,
                        extraction_chars=len(text),
                        extraction_stage=(extraction.metadata or {}).get("stage"),
                        extraction_tier=(extraction.metadata or {}).get("tier"),
                        extraction_provider=(extraction.metadata or {}).get("provider"),
                        actual_request_model=(extraction.metadata or {}).get("actual_request_model"),
                        provider_response_model=(extraction.metadata or {}).get("provider_response_model"),
                        cache_hit=extraction.cache_hit,
                        billable_pages=(extraction.metadata or {}).get("billable_pages"),
                        estimated_cost_usd=(extraction.metadata or {}).get("estimated_cost_usd"),
                    )
                    next_raw["screening"] = {
                        **current_screening,
                        "status": screening_status,
                        "answers": merged_answers,
                        "answer_sources": merged_sources,
                        "answer_evidence": merged_evidence,
                        "questions": screening_questions,
                        "pending_keys": pending_keys,
                        "completed_at": now_iso() if screening_status == "complete" else current_screening.get("completed_at"),
                    }
                    cur.execute(
                        """
                        UPDATE applications
                        SET raw_json=%s,
                            cv_received=true,
                            cv_received_at=COALESCE(cv_received_at, CURRENT_DATE),
                            screening_status=%s,
                            screening_completed_at=CASE WHEN %s='complete' THEN COALESCE(screening_completed_at, CURRENT_DATE) ELSE screening_completed_at END,
                            updated_at=now()
                        WHERE app_key=%s AND company_code=%s
                        RETURNING *
                        """,
                        (
                            Json(json_safe(next_raw)),
                            screening_status,
                            screening_status,
                            app.get("app_key"),
                            company_code,
                        ),
                    )
                    refreshed_after_cv = cur.fetchone()
                    cur.execute(
                        """
                        UPDATE candidate_documents
                        SET metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                            updated_at=now()
                        WHERE app_key=%s AND document_type='cv' AND document_id<>%s
                        """,
                        (
                            Json({"latest": False, "superseded_at": now_iso(), "superseded_by_document_id": str(document_id)}),
                            app.get("app_key"),
                            document_id,
                        ),
                    )
                    cur.execute(
                        """
                        UPDATE file_registry
                        SET metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                            updated_at=now()
                        WHERE company_code=%s
                          AND subject_type='application'
                          AND subject_key=%s
                          AND file_kind='candidate_cv'
                        """,
                        (Json({"latest": False}), company_code, app.get("app_key")),
                    )
                    current_sha = source_sha
                    if current_sha:
                        cur.execute(
                            """
                            UPDATE file_registry
                            SET metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                                updated_at=now()
                            WHERE company_code=%s AND subject_key=%s AND content_sha256=%s
                            """,
                            (Json({"latest": True, "validation_status": "accepted"}), company_code, app.get("app_key"), current_sha),
                        )
                    cur.execute(
                        """
                        UPDATE candidate_documents
                        SET text_path=%s,
                            extraction_status=%s,
                            extraction_method=%s,
                            extraction_chars=%s,
                            metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                            updated_at=now()
                        WHERE document_id=%s
                        """,
                        (
                            str(text_path),
                            "ok",
                            method,
                            len(text),
                            Json(
                                json_safe(
                                    {
                                        "semantic": semantic,
                                        "profile": profile,
                                        "application_profile": application_profile,
                                        "facts": application_facts,
                                        "facts_id": str(facts_snapshot.get("facts_id") or ""),
                                        "latest": True,
                                        "validation_status": "accepted",
                                        "validated_at": now_iso(),
                                        "extraction": {
                                            k: v
                                            for k, v in extraction.to_dict().items()
                                            if k != "blocks"
                                        },
                                    }
                                )
                            ),
                            document_id,
                        ),
                    )
                    # TALENT_POOL_AUTO_EMAIL_CLASSIFICATION_CANARY
                    cur.execute("SAVEPOINT talent_pool_auto_email_enqueue")
                    try:
                        auto_classification = _talent_pool_auto_email.record_extraction_and_enqueue(
                            cur,
                            company_code=company_code,
                            app_key=str(app.get("app_key") or ""),
                            document_id=str(document_id),
                            extracted_text=text,
                            extraction_method=method,
                            evidence=dict(evidence_materialization["evidence"]),
                            facts_snapshot=dict(facts_snapshot),
                            provenance={
                                "source": "canonical_cv_extraction_completion",
                                "held_import": bool(held_import),
                                "import_batch_id": item.get("batch_id"),
                            },
                        )
                    except Exception:
                        cur.execute("ROLLBACK TO SAVEPOINT talent_pool_auto_email_enqueue")
                        logger.exception("talent_pool_auto_email_enqueue_failed")
                        auto_classification = {"eligible": False, "reason": "enqueue_failed"}
                    finally:
                        cur.execute("RELEASE SAVEPOINT talent_pool_auto_email_enqueue")
                    # WAVE2: additive cv_version_id dual-write (default OFF; no reader cutover).
                    cur.execute("SAVEPOINT unified_cv_version_dual_write")
                    try:
                        import inbound_cv_processing as _inbound_cv_processing

                        evidence_row = dict(evidence_materialization.get("evidence") or {})
                        _inbound_cv_processing.dual_write_cv_version(
                            cur,
                            company_code=company_code,
                            content_sha256=str(
                                evidence_row.get("source_content_sha256") or source_sha or ""
                            ),
                            legacy_document_id=str(document_id),
                            legacy_app_key=str(app.get("app_key") or "") or None,
                            legacy_text_version_id=(
                                str(auto_classification.get("version_id") or "")
                                if isinstance(auto_classification, dict)
                                and auto_classification.get("version_id")
                                else None
                            ),
                            extracted_text_hash=str(evidence_row.get("extracted_text_hash") or "")
                            or None,
                            extraction_method=method,
                            evidence_id=str(evidence_row.get("evidence_id") or "") or None,
                            facts_id=str(facts_snapshot.get("facts_id") or "") or None,
                            provenance={
                                "source": "canonical_cv_extraction_completion",
                                "classification_eligible": bool(
                                    isinstance(auto_classification, dict)
                                    and auto_classification.get("eligible")
                                ),
                            },
                        )
                    except Exception:
                        cur.execute("ROLLBACK TO SAVEPOINT unified_cv_version_dual_write")
                        logger.exception("unified_cv_version_dual_write_failed")
                    finally:
                        cur.execute("RELEASE SAVEPOINT unified_cv_version_dual_write")
                    conn.commit()
                    ranking_stale = None
                    try:
                        position_for_rank = str(app.get("position_code") or "").strip()
                        if company_code and position_for_rank:
                            ranking_stale = {
                                "marked": _candidate_ranking.mark_runs_stale(
                                    sys.modules[__name__],
                                    company_code=str(company_code),
                                    position_code=position_for_rank,
                                    reason="canonical_cv_evidence_updated",
                                )
                            }
                    except Exception:
                        logger.exception("ranking_stale_after_cv_failed")
                        ranking_stale = {"marked": 0, "error": "ranking_stale_failed"}
                    lifecycle_result = None
                    if not held_import and refreshed_after_cv:
                        import recruiting_lifecycle as _rl

                        try:
                            lifecycle_result = _rl.mark_cv_ready_for_review(
                                sys.modules[__name__],
                                application=dict(refreshed_after_cv),
                                cv_version=str(document_id),
                                document_id=str(document_id),
                            )
                            transitioned = lifecycle_result.get("application") if isinstance(lifecycle_result, dict) else None
                            if isinstance(transitioned, dict):
                                refreshed_after_cv = transitioned
                        except Exception:
                            logger.exception("canonical CV lifecycle transition failed")
                            return {
                                "ok": False,
                                "error": "cv_lifecycle_transition_failed",
                                "document_id": document_id,
                                "app_key": app.get("app_key"),
                            }
                    screening_result = None
                    if send_screening:
                        ctx = _action_registry.ExecutionContext(
                            request=WhatsAppTurnRequest(
                                account_id=None,
                                conversation_id=None,
                                sender_phone="system",
                                sender_role="system",
                                raw_text="send screening questions",
                                metadata={"source": "cv_processing_worker", "document_id": document_id},
                            ),
                            action={"action_type": "send_screening_questions", "app_key": app.get("app_key")},
                            state={},
                            graph_state={},
                            intent={},
                            legacy=sys.modules[__name__],
                        )
                        screening_result = _action_registry.execute("send_screening_questions", ctx)
                        with db_connect() as flag_conn:
                            with flag_conn.cursor() as flag_cur:
                                flag_cur.execute("SELECT raw_json FROM applications WHERE app_key=%s", (app.get("app_key"),))
                                flag_row = flag_cur.fetchone()
                                latest_raw = flag_row.get("raw_json") if flag_row and isinstance(flag_row.get("raw_json"), dict) else next_raw
                                latest_raw = update_cv_processing_flags(
                                    latest_raw,
                                    screening_questions_sent=bool((screening_result or {}).get("success")),
                                    screening_questions_sent_at=now_iso() if bool((screening_result or {}).get("success")) else None,
                                )
                                flag_cur.execute("UPDATE applications SET raw_json=%s WHERE app_key=%s", (Json(json_safe(latest_raw)), app.get("app_key")))
                            flag_conn.commit()
                    candidate_notification = None
                    if not imported_app:
                        candidate_notification = notify_candidate_cv_validation(
                            dict(refreshed_after_cv) if refreshed_after_cv else app,
                            document_id=str(document_id),
                            accepted=True,
                        )
                    return {
                        "ok": True,
                        "document_id": document_id,
                        "app_key": app.get("app_key"),
                        "chars": len(text),
                        "method": method,
                        "semantic": semantic,
                        "cv_evidence": json_safe(evidence_materialization.get("evidence")),
                        "screening": json_safe(screening_result),
                        "candidate_notification": json_safe(candidate_notification),
                        "ranking_stale": json_safe(ranking_stale),
                        "extraction_meta": {
                            "stage": (extraction.metadata or {}).get("stage"),
                            "tier": (extraction.metadata or {}).get("tier"),
                            "provider": (extraction.metadata or {}).get("provider"),
                            "actual_request_model": (extraction.metadata or {}).get("actual_request_model"),
                            "provider_response_model": (extraction.metadata or {}).get("provider_response_model"),
                            "cache_hit": extraction.cache_hit,
                            "billable_pages": (extraction.metadata or {}).get("billable_pages"),
                            "estimated_cost_usd": (extraction.metadata or {}).get("estimated_cost_usd"),
                        },
                    }
                if is_replacement:
                    next_raw = dict(raw_json)
                    next_raw.pop("cv_pending", None)
                    next_raw["cv_replacement_failed"] = {
                        "document_id": str(document_id),
                        "failed_at": now_iso(),
                        "reason": error or "no_text_extracted",
                        "filename": document_cv.get("filename"),
                    }
                else:
                    failure_raw = dict(raw_json)
                    if document_cv:
                        failure_raw["cv"] = document_cv
                    next_raw = update_cv_processing_flags(
                        failure_raw,
                        file_received=True,
                        file_stored=True,
                        text_extracted=False,
                        profile_parsed=False,
                        semantic_indexed=False,
                        screening_prefill_ready=False,
                        status="failed",
                        failed_reason=error or "no_text_extracted",
                        extraction_method=method,
                        extraction_stage=(extraction.metadata or {}).get("stage"),
                        extraction_tier=(extraction.metadata or {}).get("tier"),
                        extraction_provider=(extraction.metadata or {}).get("provider"),
                        actual_request_model=(extraction.metadata or {}).get("actual_request_model"),
                        provider_response_model=(extraction.metadata or {}).get("provider_response_model"),
                    )
                cur.execute("UPDATE applications SET raw_json=%s, updated_at=COALESCE(updated_at, CURRENT_DATE) WHERE app_key=%s", (Json(json_safe(next_raw)), app.get("app_key")))
                cur.execute(
                    """
                    UPDATE candidate_documents
                    SET extraction_status=%s,
                        extraction_method=%s,
                        metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                        updated_at=now()
                    WHERE document_id=%s
                    """,
                    (
                        "failed",
                        method,
                        Json(
                            json_safe(
                                {
                                    "extraction_error": error or "no_text_extracted",
                                    "latest": False,
                                    "validation_status": "rejected",
                                    "validated_at": now_iso(),
                                    "extraction_meta": {
                                        k: v
                                        for k, v in extraction.to_dict().items()
                                        if k != "blocks"
                                    },
                                }
                            )
                        ),
                        document_id,
                    ),
                )
                failed_sha = ((document_cv.get("storage") or {}).get("sha256") if isinstance(document_cv.get("storage"), dict) else None)
                if failed_sha:
                    cur.execute(
                        """
                        UPDATE file_registry
                        SET metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                            updated_at=now()
                        WHERE company_code=%s AND subject_key=%s AND content_sha256=%s
                        """,
                        (Json({"latest": False, "validation_status": "rejected"}), company_code, app.get("app_key"), failed_sha),
                    )
                if not is_replacement:
                    failed_file = _candidate_cv_evidence.resolve_managed_file(
                        cur,
                        company_code=company_code,
                        app_key=str(app.get("app_key") or ""),
                        document_id=str(document_id),
                        source_content_sha256=failed_sha,
                        local_path=str(local_path or ""),
                    )
                    _candidate_cv_evidence.materialize_failure(
                        cur,
                        company_code=company_code,
                        app_key=str(app.get("app_key") or ""),
                        document_id=str(document_id),
                        file_id=str((failed_file or {}).get("file_id") or ""),
                        source_content_sha256=failed_sha,
                        reason=str(error or "cv_extraction_failed"),
                        actor="cv_worker",
                        provenance={"extraction_method": method},
                    )
                conn.commit()
                failure_transition = None
                if not held_import and not is_replacement:
                    import recruiting_lifecycle as _rl

                    failure_transition = _rl.transition_application(
                        sys.modules[__name__],
                        app_key=str(app.get("app_key") or ""),
                        company_code=company_code,
                        to_stage="awaiting_cv",
                        trigger="cv_processing_failed",
                        actor_type="system",
                        channel="system",
                        human_confirmed=False,
                        expected_from_stage="cv_processing",
                        idempotency_key=f"cv-failed:{company_code}:{app.get('app_key')}:{document_id}",
                        metadata={"document_id": document_id, "reason": error or "no_text_extracted"},
                    )
                screening_result = None
                if send_screening:
                    ctx = _action_registry.ExecutionContext(
                        request=WhatsAppTurnRequest(
                            account_id=None,
                            conversation_id=None,
                            sender_phone="system",
                            sender_role="system",
                            raw_text="send fallback screening questions",
                            metadata={"source": "cv_processing_worker", "document_id": document_id, "parse_failed": True},
                        ),
                        action={"action_type": "send_screening_questions", "app_key": app.get("app_key")},
                        state={},
                        graph_state={},
                        intent={},
                        legacy=sys.modules[__name__],
                    )
                    screening_result = _action_registry.execute("send_screening_questions", ctx)
                    with db_connect() as flag_conn:
                        with flag_conn.cursor() as flag_cur:
                            flag_cur.execute("SELECT raw_json FROM applications WHERE app_key=%s", (app.get("app_key"),))
                            flag_row = flag_cur.fetchone()
                            latest_raw = flag_row.get("raw_json") if flag_row and isinstance(flag_row.get("raw_json"), dict) else next_raw
                            latest_raw = update_cv_processing_flags(
                                latest_raw,
                                screening_questions_sent=bool((screening_result or {}).get("success")),
                                screening_questions_sent_at=now_iso() if bool((screening_result or {}).get("success")) else None,
                            )
                            flag_cur.execute("UPDATE applications SET raw_json=%s WHERE app_key=%s", (Json(json_safe(latest_raw)), app.get("app_key")))
                        flag_conn.commit()
                candidate_notification = None
                if not imported_app:
                    candidate_notification = notify_candidate_cv_validation(
                        app,
                        document_id=str(document_id),
                        accepted=False,
                    )
                return {
                    "ok": False,
                    "document_id": document_id,
                    "app_key": app.get("app_key"),
                    "method": method,
                    "error": error,
                    "lifecycle": json_safe(failure_transition),
                    "screening": json_safe(screening_result),
                    "candidate_notification": json_safe(candidate_notification),
                }
            finally:
                if lease_key:
                    try:
                        with db_connect() as release_conn:
                            with release_conn.cursor() as release_cur:
                                _cv_extraction.release_extraction_lease(
                                    _cv_db_execute_factory(release_cur),
                                    lease_key=lease_key,
                                    owner=lease_owner,
                                )
                            release_conn.commit()
                    except Exception:
                        logger.warning("cv_extraction_lease_release_failed document_id=%s", document_id)


def run_candidate_cv_processing_worker(*, dry_run: bool = True, limit: int = 10, force: bool = False, send_screening: bool = False) -> dict[str, Any]:
    ensure_schema()
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT document_id::text
                FROM candidate_documents
                WHERE document_type='cv'
                  AND (%s OR extraction_status IS NULL OR extraction_status IN ('pending_extraction','stored'))
                ORDER BY updated_at ASC NULLS FIRST, created_at ASC
                LIMIT %s
                """,
                (force, limit),
            )
            document_ids = [row["document_id"] for row in cur.fetchall()]
    results = [process_candidate_cv_document(document_id, dry_run=dry_run, send_screening=send_screening) for document_id in document_ids]
    return {"dry_run": dry_run, "limit": limit, "force": force, "processed": len(results), "results": json_safe(results)}


def is_candidate_cv_truth_question(text: str) -> bool:
    normalized = normalize_text(text)
    if not normalized:
        return False
    return bool(
        re.search(r"\b(cv|resume|file|document|application)\b", normalized)
        and re.search(r"\b(already|sent|uploaded|submitted|received|receive|got|have you|did you|why|again|status)\b", normalized)
    )


def candidate_cv_truth(application: dict[str, Any]) -> dict[str, Any]:
    raw_json = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
    cv_json = raw_json.get("cv") if isinstance(raw_json.get("cv"), dict) else {}
    app_key = str(application.get("app_key") or "")
    file_count = 0
    latest_file: dict[str, Any] | None = None
    if app_key:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT storage_status, storage_url, original_filename, created_at, updated_at
                    FROM file_registry
                    WHERE subject_type='application'
                      AND subject_key=%s
                      AND document_type='cv'
                    ORDER BY updated_at DESC, created_at DESC
                    LIMIT 1
                    """,
                    (app_key,),
                )
                row = cur.fetchone()
                latest_file = dict(row) if row else None
                cur.execute(
                    """
                    SELECT COUNT(*) AS count
                    FROM file_registry
                    WHERE subject_type='application'
                      AND subject_key=%s
                      AND document_type='cv'
                      AND storage_status IN ('stored','ok','uploaded')
                    """,
                    (app_key,),
                )
                file_count = int((cur.fetchone() or {}).get("count") or 0)
    storage = cv_json.get("storage") if isinstance(cv_json.get("storage"), dict) else {}
    cv_received = bool(application.get("cv_received") is True or cv_json or file_count > 0)
    storage_ok = bool(file_count > 0 or storage.get("status") in {"stored", "ok", "uploaded"} or storage.get("provider"))
    return {
        "cv_received": cv_received,
        "storage_ok": storage_ok,
        "status": application.get("status"),
        "current_step": application.get("current_step"),
        "app_key": app_key,
        "position_code": application.get("position_code"),
        "latest_file": json_safe(latest_file or {}),
        "cv": json_safe(cv_json),
    }


def handle_candidate_truth_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    if not is_candidate_cv_truth_question(request.raw_text):
        return None
    application = find_candidate_application_for_file(request.sender_phone)
    if not application:
        return None
    if not company_has_module(application.get("company_code"), "pre_hiring"):
        return {"reply": candidate_safe_module_unavailable_reply(), "application": json_safe(application), "module_disabled": "pre_hiring"}
    truth = candidate_cv_truth(application)
    if truth.get("cv_received") and truth.get("storage_ok"):
        reply = "Yes, I have your CV saved. OctoHR will review it and follow up with the next step."
    elif truth.get("cv_received"):
        reply = "I can see CV information on your application, but I do not see a safely stored file yet. Please resend your CV as a PDF, Word document, or clear image."
    else:
        reply = "I do not see a CV saved for your application yet. Please send your CV here as a PDF, Word document, or clear image."
    return {"reply": reply, "application": json_safe(application), "truth": truth}


CANDIDATE_FORBIDDEN_POLICY_PATTERNS: list[tuple[str, str]] = [
    ("hiring_promise", r"\b(you('| a)?re hired|you are hired|you will get the job|guaranteed|we will hire you|job is yours)\b"),
    ("decision_claim", r"\b(you('| a)?re shortlisted|you are shortlisted|you have been shortlisted|you('| a)?re rejected|you are rejected)\b"),
    ("ranking_or_score", r"\b(score|ranking|ranked|percentile|top candidate|best candidate|strong candidate|weak candidate|strong fit|weak fit)\b"),
    ("comparison", r"\b(other candidates|other applicants|better than|worse than|compared to|among applicants)\b"),
    ("internal_notes", r"\b(internal notes?|recruiter notes?|hr notes?|hr likes|internal score|embedding|semantic score)\b"),
    ("salary_offer", r"\b(we can offer|salary approved|offer you\s+\d|your offer is|we will pay)\b"),
]


def apply_candidate_reply_policy(reply: str | None, *, request: WhatsAppTurnRequest, result: dict[str, Any] | None) -> dict[str, Any]:
    text = str(reply or "").strip()
    if not text:
        return {"reply": text, "policy_applied": False, "violations": []}
    normalized = normalize_text(text)
    violations: list[str] = []
    for label, pattern in CANDIDATE_FORBIDDEN_POLICY_PATTERNS:
        if re.search(pattern, normalized, re.I):
            violations.append(label)
    if not violations:
        return {"reply": text, "policy_applied": False, "violations": []}
    if "salary_offer" in violations:
        safe = "I can’t negotiate or confirm salary decisions here. I can help with your application status, missing information, or next steps."
    elif "ranking_or_score" in violations or "comparison" in violations or "internal_notes" in violations:
        safe = "I can’t share hiring review details here. I can help with your application status, missing information, or next steps."
    else:
        safe = "Thanks — your application is in progress. OctoHR will review your information and follow up with the next step."
    return {"reply": safe, "policy_applied": True, "violations": violations, "original_reply": text}


def candidate_active_application(phone: str | None) -> dict[str, Any] | None:
    return find_candidate_application_for_file(phone)


def resolve_candidate_request_application(request: WhatsAppTurnRequest) -> dict[str, Any]:
    if not canonical_lifecycle_enabled():
        return {"ok": False, "error": "canonical_lifecycle_disabled"}
    import recruiting_lifecycle as _rl

    resolved = _rl.resolve_conversation_application(
        sys.modules[__name__],
        phone=request.sender_phone,
        conversation_id=request.conversation_id,
        company_code=request_company_code(request, default=None),
        account_id=request.account_id,
        allow_single_eligible=True,
    )
    application = resolved.get("application") if isinstance(resolved.get("application"), dict) else None
    if resolved.get("ok") and application and resolved.get("requires_bind"):
        if not request.conversation_id:
            return {"ok": False, "error": "conversation_id_required", "application": None}
        binding = _rl.bind_conversation_application(
            sys.modules[__name__],
            company_code=str(application.get("company_code") or ""),
            conversation_id=str(request.conversation_id),
            phone=str(application.get("phone") or request.sender_phone or ""),
            app_key=str(application.get("app_key") or ""),
            account_id=request.account_id,
            bound_reason="candidate_explicit_action",
        )
        if not binding.get("ok"):
            return {"ok": False, "error": binding.get("error") or "application_binding_failed", "application": None}
        resolved["binding"] = binding.get("binding")
        resolved["requires_bind"] = False
    return resolved


def candidate_resolution_failure_message(request: WhatsAppTurnRequest, resolution: dict[str, Any]) -> dict[str, Any]:
    error = str(resolution.get("error") or "")
    template_key = "no_active_application" if error in {"no_eligible_application", "missing_phone"} else "ambiguous_application"
    return {
        "ok": False,
        "error": error or "application_resolution_failed",
        **candidate_message_result(template_key, request=request),
        "matches": resolution.get("matches") or [],
    }


def is_candidate_status_intent(text: str | None) -> bool:
    normalized = normalize_text(text)
    raw = str(text or "")
    return bool(
        re.search(r"\b(status|application status|where.*application|where.*cv|did you receive|received.*cv)\b", normalized)
        or re.search(r"(حالة طلبي|حالة الطلب|وين وصل|أين وصل|اين وصل|وش صار|استلمت.*سير|وصلت.*سير)", raw)
    )


def is_candidate_cv_replace_intent(text: str | None) -> bool:
    normalized = normalize_text(text)
    raw = str(text or "")
    english = bool(
        re.search(r"\b(update|change|replace|resend|send another|forgot|new cv|latest cv)\b", normalized)
        and re.search(r"\b(cv|resume|file|document)\b", normalized)
    )
    arabic = bool(
        re.search(r"(تحديث|أحدث|احدث|تغيير|استبدال|بدل|جديدة|إعادة|اعادة)", raw)
        and re.search(r"(السيرة|سيرتي|ملف)", raw)
    )
    return english or arabic


def is_candidate_withdraw_intent(text: str | None) -> bool:
    normalized = normalize_text(text)
    raw = str(text or "")
    return bool(
        re.search(r"\b(withdraw|withdrawal|cancel my application|remove my application)\b", normalized)
        or re.search(r"(سحب طلبي|سحب الطلب|انسحاب|أنسحب|الغاء طلبي|إلغاء طلبي|إلغاء الطلب|الغاء الطلب)", raw)
    )


def is_candidate_hr_handoff_intent(text: str | None) -> bool:
    normalized = normalize_text(text)
    raw = str(text or "")
    return bool(
        re.search(r"\b(speak|talk|chat|contact).*\b(hr|human|recruiter|person)\b", normalized)
        or re.search(r"\b(hr|human|recruiter).*\b(speak|talk|chat|contact)\b", normalized)
        or re.search(r"(أتكلم|اتكلم|أتحدث|اتحدث|أبي أكلم|ابي اكلم|تواصل).*(الموارد البشرية|موارد بشرية|الموظف|المسؤول|شخص)", raw)
        or re.search(r"(الموارد البشرية|موارد بشرية).*(أتكلم|اتكلم|أتحدث|اتحدث|تواصل)", raw)
    )


def candidate_pending_action(request: WhatsAppTurnRequest) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    if not request.conversation_id:
        return None, None
    import recruiting_lifecycle as _rl

    resolution = resolve_candidate_request_application(request)
    application = resolution.get("application") if isinstance(resolution.get("application"), dict) else None
    if not resolution.get("ok") or not application:
        return application, None
    binding = _rl.candidate_conversation_binding(
        sys.modules[__name__],
        company_code=str(application.get("company_code") or ""),
        conversation_id=request.conversation_id,
        phone=request.sender_phone,
    )
    metadata = binding.get("metadata") if binding and isinstance(binding.get("metadata"), dict) else {}
    pending = metadata.get("pending_candidate_action") if isinstance(metadata.get("pending_candidate_action"), dict) else None
    return application, pending


def handle_candidate_withdrawal_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    raw = str(request.raw_text or "")
    normalized = normalize_text(raw)
    application, pending = candidate_pending_action(request)
    confirm = normalized in {"confirm", "yes", "yes withdraw", "withdraw now"} or bool(
        re.fullmatch(r"\s*(تأكيد|نعم|اسحب|اسحب الطلب)\s*", raw)
    )
    cancel = normalized in {"cancel", "no", "keep it", "do not withdraw"} or bool(
        re.fullmatch(r"\s*(إلغاء|الغاء|لا|خله|خليه)\s*", raw)
    )
    if pending and pending.get("type") == "replace_cv" and pending.get("status") == "pending":
        if not application:
            return {"ok": False, "error": "pending_application_missing"}
        import recruiting_lifecycle as _rl

        payload = pending.get("target_payload") if isinstance(pending.get("target_payload"), dict) else {}
        document_id = str(payload.get("document_id") or "")
        if cancel:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        UPDATE candidate_documents
                        SET extraction_status='cancelled',
                            metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                            updated_at=now()
                        WHERE document_id=%s AND app_key=%s AND extraction_status='awaiting_confirmation'
                        """,
                        (Json({"replacement_cancelled_at": now_iso()}), document_id, application.get("app_key")),
                    )
                    cur.execute(
                        "UPDATE applications SET raw_json=COALESCE(raw_json,'{}'::jsonb) - 'cv_pending' WHERE company_code=%s AND app_key=%s",
                        (application.get("company_code"), application.get("app_key")),
                    )
                    cur.execute(
                        """
                        UPDATE candidate_action_confirmations
                        SET status='cancelled', result=%s, updated_at=now()
                        WHERE confirmation_id=%s AND company_code=%s AND status='pending'
                        """,
                        (
                            Json({"ok": True, "cancelled": True, "document_id": document_id}),
                            pending.get("confirmation_id"),
                            application.get("company_code"),
                        ),
                    )
                conn.commit()
            outcome = {"ok": True, "cancelled": True}
        elif confirm:
            def activate_replacement(cur: Any, current_app: dict[str, Any]) -> dict[str, Any]:
                cur.execute(
                    """
                    UPDATE candidate_documents
                    SET extraction_status='pending_extraction',
                        metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                        updated_at=now()
                    WHERE document_id=%s AND app_key=%s AND extraction_status='awaiting_confirmation'
                    RETURNING document_id
                    """,
                    (
                        Json({"replacement_confirmed_at": now_iso()}),
                        document_id,
                        current_app.get("app_key"),
                    ),
                )
                return {"ok": bool(cur.fetchone()), "document_id": document_id}

            outcome = _rl.consume_candidate_action_confirmation(
                sys.modules[__name__],
                company_code=str(application.get("company_code") or ""),
                app_key=str(application.get("app_key") or ""),
                action="replace_cv",
                confirmation_id=str(pending.get("confirmation_id") or ""),
                confirmation_token=str(pending.get("confirmation_token") or ""),
                target_payload=payload,
                actor_user_id=None,
                actor_phone=request.sender_phone,
                operation=activate_replacement,
            )
            if not outcome.get("ok"):
                return {"ok": False, "error": outcome.get("error"), "reply": "This CV replacement confirmation is no longer valid. Please send the CV again."}
        else:
            return {
                "ok": False,
                "status": "needs_confirmation",
                "intent": "candidate_cv_replacement_confirmation_required",
                "reply": "Reply CONFIRM to replace your current CV, or CANCEL to keep the current one.",
            }
        _rl.update_candidate_conversation_state(
            sys.modules[__name__],
            company_code=str(application.get("company_code") or ""),
            conversation_id=str(request.conversation_id or ""),
            phone=str(application.get("phone") or request.sender_phone),
            app_key=str(application.get("app_key") or ""),
            updates={
                "pending_candidate_action": {
                    **pending,
                    "status": "cancelled" if cancel else "completed",
                    "resolved_at": now_iso(),
                }
            },
        )
        return {
            "ok": True,
            "intent": "candidate_cv_replacement_cancelled" if cancel else "candidate_cv_replacement_confirmed",
            "reply": (
                "Your current CV was kept."
                if cancel
                else "Confirmed. I’ll validate the new CV now; your current CV remains authoritative until validation succeeds."
            ),
            "outcome": json_safe(outcome),
        }
    if pending and pending.get("type") == "withdraw" and pending.get("status") == "pending":
        if not application:
            return {**candidate_message_result("no_active_application", request=request), "error": "pending_application_missing"}
        import recruiting_lifecycle as _rl

        if cancel:
            _rl.update_candidate_conversation_state(
                sys.modules[__name__],
                company_code=str(application.get("company_code") or ""),
                conversation_id=str(request.conversation_id or ""),
                phone=str(application.get("phone") or request.sender_phone),
                app_key=str(application.get("app_key") or ""),
                updates={"pending_candidate_action": {**pending, "status": "cancelled", "resolved_at": now_iso()}},
            )
            locale = candidate_message_payload(
                "application_status",
                request=request,
                application=application,
                role="",
                status="",
            )["locale"]
            return {
                **candidate_message_result(
                    "application_status",
                    request=request,
                    application=application,
                    locale=locale,
                    role=application.get("position_title") or application.get("position_code") or "the role",
                    status=_candidate_messages.status_label(application.get("status"), locale),
                ),
                "intent": "candidate_withdrawal_cancelled",
            }
        if not confirm:
            return {
                **candidate_message_result(
                    "withdrawal_confirm_prompt",
                    request=request,
                    application=application,
                    role=application.get("position_title") or application.get("position_code") or "the role",
                ),
                "intent": "candidate_withdrawal_confirmation_required",
            }
        provider_message_id = _whatsapp_provider_message_id(request)
        confirmation_payload = pending.get("target_payload") if isinstance(pending.get("target_payload"), dict) else {}
        transition = _rl.transition_application(
            sys.modules[__name__],
            app_key=str(application.get("app_key") or ""),
            company_code=str(application.get("company_code") or ""),
            to_stage="withdrawn",
            trigger="candidate_withdrawal_confirmed",
            actor_type="candidate",
            actor_phone=request.sender_phone,
            channel="whatsapp",
            confirmation_id=str(pending.get("confirmation_id") or "") or None,
            confirmation_token=str(pending.get("confirmation_token") or "") or None,
            confirmation_action="withdraw",
            confirmation_payload=confirmation_payload,
            idempotency_key=f"candidate-withdraw:{provider_message_id}" if provider_message_id else None,
            human_confirmed=True,
            expected_from_stage=str(pending.get("observed_stage") or "") or None,
            expected_version=pending.get("observed_version"),
            metadata={
                **confirmation_payload,
                "conversation_id": request.conversation_id,
                "account_id": request.account_id,
            },
        )
        if not transition.get("ok"):
            return {
                "ok": False,
                "error": transition.get("error") or "withdrawal_failed",
                **candidate_message_result("no_active_application", request=request, application=application),
                "transition": json_safe(transition),
            }
        _rl.update_candidate_conversation_state(
            sys.modules[__name__],
            company_code=str(application.get("company_code") or ""),
            conversation_id=str(request.conversation_id or ""),
            phone=str(application.get("phone") or request.sender_phone),
            app_key=str(application.get("app_key") or ""),
            updates={"pending_candidate_action": {**pending, "status": "completed", "resolved_at": now_iso()}},
        )
        return {
            "ok": True,
            **candidate_message_result(
                "withdrawal_confirmation",
                request=request,
                application=application,
                role=application.get("position_title") or application.get("position_code") or "the role",
            ),
            "intent": "candidate_withdrawal_confirmed",
            "transition": json_safe(transition),
        }
    if not is_candidate_withdraw_intent(raw):
        return None
    resolution = resolve_candidate_request_application(request)
    application = resolution.get("application") if isinstance(resolution.get("application"), dict) else None
    if not resolution.get("ok") or not application:
        return candidate_resolution_failure_message(request, resolution)
    import recruiting_lifecycle as _rl

    confirmation_payload = {"reason_code": "candidate_requested", "source": "candidate"}
    minted = _rl.mint_candidate_action_confirmation(
        sys.modules[__name__],
        company_code=str(application.get("company_code") or ""),
        app_key=str(application.get("app_key") or ""),
        action="withdraw",
        observed_stage=str(application.get("status") or ""),
        observed_version=int(application.get("lifecycle_version") or 0),
        target_payload=confirmation_payload,
        actor_user_id=None,
        actor_phone=request.sender_phone,
        actor_type="candidate",
        channel="whatsapp",
        permissions=set(),
        idempotency_key=f"candidate-withdraw-prepare:{request.conversation_id}:{application.get('app_key')}:{application.get('lifecycle_version') or 0}",
    )
    if not minted.get("ok"):
        return candidate_resolution_failure_message(request, {"error": minted.get("error")})
    confirmation = minted["confirmation"]
    pending = {
        "type": "withdraw",
        "status": "pending",
        "app_key": application.get("app_key"),
        "company_code": application.get("company_code"),
        "requested_at": now_iso(),
        "confirmation_id": confirmation.get("confirmation_id"),
        "confirmation_token": confirmation.get("confirmation_token"),
        "observed_stage": confirmation.get("observed_stage"),
        "observed_version": confirmation.get("observed_version"),
        "target_payload": confirmation_payload,
    }
    state = _rl.update_candidate_conversation_state(
        sys.modules[__name__],
        company_code=str(application.get("company_code") or ""),
        conversation_id=str(request.conversation_id or ""),
        phone=str(application.get("phone") or request.sender_phone),
        app_key=str(application.get("app_key") or ""),
        updates={"pending_candidate_action": pending},
    )
    if not state.get("ok"):
        return candidate_resolution_failure_message(request, {"error": state.get("error")})
    return {
        "ok": True,
        **candidate_message_result(
            "withdrawal_confirm_prompt",
            request=request,
            application=application,
            role=application.get("position_title") or application.get("position_code") or "the role",
        ),
        "intent": "candidate_withdrawal_confirmation_required",
    }


def handle_candidate_hr_handoff_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}) or not is_candidate_hr_handoff_intent(request.raw_text):
        return None
    resolution = resolve_candidate_request_application(request)
    application = resolution.get("application") if isinstance(resolution.get("application"), dict) else None
    if not resolution.get("ok") or not application:
        return candidate_resolution_failure_message(request, resolution)
    import recruiting_lifecycle as _rl

    locale = candidate_message_payload("hr_handoff_confirmation", request=request, application=application)["locale"]
    handoff = _rl.request_candidate_handoff(
        sys.modules[__name__],
        application=application,
        conversation_id=str(request.conversation_id or ""),
        account_id=request.account_id,
        locale=locale,
    )
    if not handoff.get("ok"):
        return {
            "ok": False,
            "error": handoff.get("error") or "handoff_failed",
            **candidate_message_result("ambiguous_application", request=request, application=application, locale=locale),
        }
    return {
        "ok": True,
        **candidate_message_result("hr_handoff_confirmation", request=request, application=application, locale=locale),
        "intent": "candidate_hr_handoff",
        "handoff": json_safe(handoff),
    }


def handle_candidate_automation_pause_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if not request.conversation_id:
        return None
    resolution = resolve_candidate_request_application(request)
    application = resolution.get("application") if isinstance(resolution.get("application"), dict) else None
    binding = resolution.get("binding") if isinstance(resolution.get("binding"), dict) else {}
    metadata = binding.get("metadata") if isinstance(binding.get("metadata"), dict) else {}
    if not application or metadata.get("automation_paused") is not True:
        return None
    return {
        "ok": True,
        **candidate_message_result("hr_handoff_confirmation", request=request, application=application),
        "intent": "candidate_automation_paused",
        "handoff_task_id": metadata.get("handoff_task_id"),
    }


def candidate_missing_or_next_reply(application: dict[str, Any]) -> str:
    raw_json = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    processing = (raw_json.get("cv") or {}).get("processing") if isinstance(raw_json.get("cv"), dict) else {}
    title = application.get("position_title") or application.get("position_code") or "this role"
    if not application.get("cv_received"):
        return f"Your application for {title} is started. Next step: please send your CV as a PDF, DOCX, or clear image."
    if isinstance(processing, dict) and processing.get("status") in {"pending_async_processing", "processing"}:
        return "I received your CV and I’m still processing it. I’ll continue with the next step once it’s ready."
    pending_keys = screening.get("pending_keys") if isinstance(screening.get("pending_keys"), list) else []
    questions = screening.get("questions") if isinstance(screening.get("questions"), list) else []
    if pending_keys:
        next_question = format_next_screening_question([q for q in questions if isinstance(q, dict)], [str(item) for item in pending_keys])
        return f"Your CV is received. Next step: please answer this quick application question:\n\n{next_question}"
    if str(application.get("screening_status") or screening.get("status") or "").lower() in {"complete", "completed"}:
        return "Your application is complete for review. OctoHR will review it and follow up with the next step."
    return "Your application is in progress. I can help with your CV, quick application questions, or application status."


def public_candidate_roles(company_code: str | None, *, limit: int = 5) -> list[dict[str, Any]]:
    company = str(company_code or "").strip().upper()
    if not company:
        return []
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM positions
                WHERE company_code=%s
                  AND status='open'
                  AND visibility='public'
                ORDER BY updated_at DESC NULLS LAST, created_at DESC
                LIMIT %s
                """,
                (company, min(200, max(1, int(limit)))),
            )
            roles: list[dict[str, Any]] = []
            for row in cur.fetchall():
                item = dict(row)
                _prehire_jobs.attach_company_display_name(cur, item)
                vacancy = _prehire_jobs.vacancy_counts(
                    cur,
                    company=company,
                    position_code=str(item.get("position_code") or ""),
                    approved_headcount=item.get("vacancies"),
                )
                try:
                    _prehire_jobs.assert_job_accepts_applications(
                        item,
                        vacancy=vacancy,
                        access_mode="discovery",
                    )
                except _prehire_jobs.JobsError:
                    continue
                roles.append(json_safe(_prehire_jobs.serialize_job(item, vacancy=vacancy, include_salary=False)))
            return roles


def public_candidate_welcome_reply(company_code: str | None = None, *, locale: str = "en") -> str:
    del company_code
    return _candidate_messages.render("welcome", locale)["text"]


def role_interest_from_text(text: str | None) -> str | None:
    normalized = normalize_text(text)
    raw = str(text or "")
    if not re.search(r"\b(apply|application|interested|job|role|position)\b", normalized) and not re.search(
        r"(أقدم|اقدم|تقديم|وظيفة|الوظيفة|دور|منصب|مهتم)",
        raw,
    ):
        return None
    cleaned = re.sub(r"\b(i|want|wanna|wana|would like|to|apply|application|for|job|role|position|at|wathefni|here is my cv|cv|resume|please|pls)\b", " ", normalized)
    cleaned = re.sub(r"(أريد|اريد|أرغب|ارغب|أن|ان|أتقدم|اتقدم|أقدم|اقدم|للتقديم|تقديم|على|وظيفة|الوظيفة|منصب|مهتم|في|لوظيفة)", " ", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    return cleaned or None


def public_role_matches(query: str | None, *, company_code: str | None = None) -> list[dict[str, Any]]:
    if not query or not str(company_code or "").strip():
        return []
    roles = public_candidate_roles(company_code, limit=50)
    terms = [term for term in normalize_text(query).split() if len(term) >= 2]
    scored = []
    for role in roles:
        haystack = normalize_text(f"{role.get('title') or ''} {role.get('position_code') or ''}".replace("_", " "))
        score = sum(1 for term in terms if term in haystack)
        if score:
            scored.append((score, role))
    scored.sort(key=lambda item: item[0], reverse=True)
    if not scored:
        return []
    best_score = scored[0][0]
    return [role for score, role in scored if score == best_score][:5]


def parse_apply_code_text(text: str | None) -> dict[str, str] | None:
    apply_code = _prehire_jobs.extract_apply_code(text)
    if not apply_code:
        return None
    return {"apply_code": apply_code}


def resolve_public_role_by_apply_code(
    apply_code: str | None,
    *,
    verified_company_code: str | None = None,
) -> dict[str, Any]:
    parsed = parse_apply_code_text(apply_code)
    if not parsed:
        return {"ok": False, "error": "apply_code_not_found", "role": None}
    with db_connect() as conn:
        with conn.cursor() as cur:
            company = str(verified_company_code or "").strip().upper()
            if company:
                cur.execute(
                    """
                    SELECT *
                    FROM positions
                    WHERE upper(apply_code)=%s AND company_code=%s
                    LIMIT 2
                    """,
                    (parsed["apply_code"], company),
                )
            else:
                cur.execute(
                    "SELECT * FROM positions WHERE upper(apply_code)=%s LIMIT 2",
                    (parsed["apply_code"],),
                )
            rows = [dict(row) for row in cur.fetchall()]
            if not rows:
                return {"ok": False, "error": "apply_code_not_found", "role": None}
            if len(rows) != 1:
                return {"ok": False, "error": "apply_code_ambiguous", "role": None}
            item = rows[0]
            _prehire_jobs.attach_company_display_name(cur, item)
            vacancy = _prehire_jobs.vacancy_counts(
                cur,
                company=str(item.get("company_code") or ""),
                position_code=str(item.get("position_code") or ""),
                approved_headcount=item.get("vacancies"),
            )
            try:
                eligibility = _prehire_jobs.assert_job_accepts_applications(
                    item,
                    vacancy=vacancy,
                    access_mode="exact_token",
                )
            except _prehire_jobs.JobsError as exc:
                return {
                    "ok": False,
                    "error": exc.code,
                    "details": exc.details,
                    "role": None,
                }
            role = _prehire_jobs.serialize_job(item, vacancy=vacancy, include_salary=False)
            role["eligibility"] = eligibility
            return {"ok": True, "error": None, "role": json_safe(role)}


def public_role_by_apply_code(apply_code: str | None) -> dict[str, Any] | None:
    resolved = resolve_public_role_by_apply_code(apply_code)
    return resolved.get("role") if resolved.get("ok") and isinstance(resolved.get("role"), dict) else None


def active_candidate_job_context(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    phone = digits(request.sender_phone)
