def hold_candidate_pending_media(request: WhatsAppTurnRequest) -> dict[str, Any]:
    phone = digits(request.sender_phone)
    media = request.media or {}
    if not phone or not has_current_media_upload(media):
        raise _prehire_jobs.JobsError(
            "invalid_pending_candidate_media",
            "The candidate file could not be held safely.",
            http_status=409,
        )
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_pending_media
                SET status='expired', updated_at=now()
                WHERE phone=%s
                  AND COALESCE(account_id, '')=COALESCE(%s, '')
                  AND (%s IS NULL OR conversation_id=%s)
                  AND status='pending'
                """,
                (phone, request.account_id, request.conversation_id, request.conversation_id),
            )
            cur.execute(
                """
                INSERT INTO candidate_pending_media
                (phone,account_id,conversation_id,media,raw_text,status,expires_at)
                VALUES (%s,%s,%s,%s,%s,'pending',now() + interval '2 hours')
                RETURNING pending_id::text,status,created_at,expires_at
                """,
                (
                    phone,
                    request.account_id,
                    request.conversation_id,
                    Json(json_safe(media)),
                    str(request.raw_text or "")[:1000],
                ),
            )
            row = dict(cur.fetchone())
            # WAVE3: additive unsolicited WhatsApp adapter dual-write.
            cur.execute("SAVEPOINT unified_inbound_cv_whatsapp_unsolicited")
            try:
                import inbound_cv_adapters as _inbound_cv_adapters

                media_meta = media if isinstance(media, dict) else {}
                request_metadata = request.metadata if isinstance(request.metadata, dict) else {}
                provider_message_id = str(
                    media_meta.get("message_id")
                    or media_meta.get("provider_message_id")
                    or request_metadata.get("message_id")
                    or row.get("pending_id")
                    or ""
                )
                company_code = str(
                    request_metadata.get("company_code")
                    or request_company_code(request, default=None)
                    or ""
                ).strip().upper()
                if not company_code:
                    raise _data_safety.MissingCompanyCode("whatsapp_unsolicited_cv")
                _inbound_cv_adapters.adapt_whatsapp_unsolicited(
                    cur,
                    company_code=company_code,
                    provider_message_id=provider_message_id,
                    phone=phone,
                    account_id=request.account_id,
                    conversation_id=request.conversation_id,
                    pending_id=str(row.get("pending_id") or "") or None,
                    filename=Path(str(media_meta.get("path") or media_meta.get("filename") or "whatsapp-cv")).name,
                    mime_or_suffix=str(media_meta.get("type") or media_meta.get("mime_type") or ""),
                    needs_ocr=True,
                )
            except Exception:
                cur.execute("ROLLBACK TO SAVEPOINT unified_inbound_cv_whatsapp_unsolicited")
                logger.exception("unified_inbound_cv_whatsapp_unsolicited_failed")
            finally:
                cur.execute("RELEASE SAVEPOINT unified_inbound_cv_whatsapp_unsolicited")
        conn.commit()
    return json_safe(row)


def upsert_candidate_job_context(
    request: WhatsAppTurnRequest,
    *,
    role: dict[str, Any],
    preview_locale: str,
    preview_template_version: str,
) -> dict[str, Any]:
    phone = digits(request.sender_phone)
    company = str(role.get("company_code") or "").strip().upper()
    position = str(role.get("position_code") or "").strip()
    apply_code = str(role.get("apply_code") or "").strip().upper()
    if not phone or not company or not position or not apply_code:
        raise _prehire_jobs.JobsError(
            "invalid_job_context",
            "The job context could not be bound safely.",
            http_status=409,
        )
    expires_at = _prehire_jobs.job_context_expires_at(role)
    data_source, data_source_detail = data_source_from_request(request)
    request_metadata = request.metadata if isinstance(request.metadata, dict) else {}
    source_channel = str(
        request_metadata.get("source_channel")
        or request_metadata.get("provider")
        or request_metadata.get("channel")
        or ""
    ).strip() or None
    source_ref_token = str(
        request_metadata.get("source_ref_token")
        or request_metadata.get("ref_token")
        or ""
    ).strip() or None
    source_campaign = str(request_metadata.get("source_campaign") or "").strip() or None
    metadata = {
        "data_source_detail": data_source_detail,
        "bound_reason": "exact_apply_code",
    }
    with db_connect() as conn:
        with conn.cursor() as cur:
            lock_key = "|".join((phone, str(request.account_id or ""), str(request.conversation_id or "")))
            cur.execute("SELECT pg_advisory_xact_lock(hashtextextended(%s, 0))", (lock_key,))
            cur.execute(
                """
                UPDATE candidate_job_contexts
                SET status='expired', updated_at=now()
                WHERE phone=%s
                  AND COALESCE(account_id, '')=COALESCE(%s, '')
                  AND (%s IS NULL OR conversation_id=%s)
                  AND status='awaiting_apply_confirmation'
                  AND (company_code<>%s OR position_code<>%s)
                """,
                (
                    phone,
                    request.account_id,
                    request.conversation_id,
                    request.conversation_id,
                    company,
                    position,
                ),
            )
            cur.execute(
                """
                SELECT context_id
                FROM candidate_job_contexts
                WHERE phone=%s
                  AND COALESCE(account_id, '')=COALESCE(%s, '')
                  AND (%s IS NULL OR conversation_id=%s)
                  AND company_code=%s
                  AND position_code=%s
                  AND status='awaiting_apply_confirmation'
                ORDER BY updated_at DESC
                LIMIT 1
                FOR UPDATE
                """,
                (
                    phone,
                    request.account_id,
                    request.conversation_id,
                    request.conversation_id,
                    company,
                    position,
                ),
            )
            existing = cur.fetchone()
            if existing:
                cur.execute(
                    """
                    UPDATE candidate_job_contexts
                    SET job_id=%s,
                        apply_code=%s,
                        preview_rendered_at=now(),
                        preview_locale=%s,
                        preview_template_version=%s,
                        metadata=COALESCE(metadata, '{}'::jsonb) || %s::jsonb,
                        data_source=%s,
                        source_channel=%s,
                        source_ref_token=%s,
                        source_campaign=%s,
                        updated_at=now(),
                        expires_at=%s
                    WHERE context_id=%s
                    RETURNING *
                    """,
                    (
                        role.get("job_id"),
                        apply_code,
                        preview_locale,
                        preview_template_version,
                        Json(json_safe(metadata)),
                        data_source,
                        source_channel,
                        source_ref_token,
                        source_campaign,
                        expires_at,
                        existing.get("context_id"),
                    ),
                )
            else:
                cur.execute(
                    """
                    INSERT INTO candidate_job_contexts
                    (phone,account_id,conversation_id,company_code,position_code,job_id,apply_code,
                     status,preview_rendered_at,preview_locale,preview_template_version,metadata,data_source,
                     source_channel,source_ref_token,source_campaign,expires_at)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,'awaiting_apply_confirmation',now(),%s,%s,%s,%s,%s,%s,%s,%s)
                    RETURNING *
                    """,
                    (
                        phone,
                        request.account_id,
                        request.conversation_id,
                        company,
                        position,
                        role.get("job_id"),
                        apply_code,
                        preview_locale,
                        preview_template_version,
                        Json(json_safe(metadata)),
                        data_source,
                        source_channel,
                        source_ref_token,
                        source_campaign,
                        expires_at,
                    ),
                )
            row = dict(cur.fetchone())
        conn.commit()
    return json_safe(row)


