def start_public_candidate_application(request: WhatsAppTurnRequest, role: dict[str, Any]) -> dict[str, Any] | None:
    phone = digits(request.sender_phone)
    company = str(role.get("company_code") or "").strip().upper()
    position = str(role.get("position_code") or "").strip()
    if not phone or not position:
        return None
    result = run_workspace_tool(
        [
            str(WORKSPACE / "tools" / "db" / "update_state.py"),
            "--env",
            str(ENV_PATH),
            "start-application",
            "--phone",
            phone,
            "--company",
            company,
            "--position",
            position,
        ],
        timeout=75,
    )
    app_key = f"{phone}-{company}-{position}"
    data_source, data_source_detail = data_source_from_request(request)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE applications
                SET data_source=%s,
                    data_source_detail=%s,
                    raw_json=COALESCE(raw_json,'{}'::jsonb) || %s::jsonb
                WHERE app_key=%s AND company_code=%s
                """,
                (
                    data_source,
                    data_source_detail,
                    Json(
                        json_safe(
                            {
                                "data_source": data_source,
                                "data_source_detail": data_source_detail,
                                "source_conversation_id": request.conversation_id,
                                "candidate_locale": _candidate_messages.infer_locale(
                                    request.raw_text,
                                    preferred=(request.metadata or {}).get("locale")
                                    if isinstance(request.metadata, dict)
                                    else None,
                                ),
                            }
                        )
                    ),
                    app_key,
                ),
            )
            cur.execute(
                """
                SELECT a.*, c.name AS candidate_name, c.email AS candidate_email
                FROM applications a
                LEFT JOIN candidates c ON c.phone=a.phone
                WHERE a.app_key=%s
                LIMIT 1
                """,
                (app_key,),
            )
            row = cur.fetchone()
    if not row:
        return None
    app_row = json_safe(dict(row))
    if canonical_lifecycle_enabled() and request.conversation_id:
        import recruiting_lifecycle as _rl

        binding = _rl.bind_conversation_application(
            sys.modules[__name__],
            company_code=str(app_row.get("company_code") or company),
            conversation_id=str(request.conversation_id),
            phone=str(app_row.get("phone") or request.sender_phone),
            app_key=str(app_row.get("app_key") or app_key),
            account_id=request.account_id,
            bound_reason="explicit_apply",
            metadata={"candidate_locale": (app_row.get("raw_json") or {}).get("candidate_locale")},
        )
        if not binding.get("ok"):
            app_row["binding_error"] = binding.get("error") or "application_binding_failed"
        else:
            app_row["conversation_binding"] = binding.get("binding")
    app_row["start_result"] = json_safe(result)
    return app_row


def attach_public_pending_cv_to_application(request: WhatsAppTurnRequest, application: dict[str, Any], session: dict[str, Any] | None) -> dict[str, Any] | None:
    pending_media = (session or {}).get("pending_media") if isinstance((session or {}).get("pending_media"), dict) else {}
    media = pending_media.get("media") if isinstance(pending_media.get("media"), dict) else {}
    if not media or not has_current_media_upload(media):
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            result = register_candidate_cv_file(
                cur,
                application=application,
                media=media,
                metadata={
                    "conversation_id": request.conversation_id,
                    "raw_text": pending_media.get("raw_text") or request.raw_text,
                    "source": "public_candidate_pending_cv",
                    "public_session_id": (session or {}).get("session_id"),
                    "account_id": request.account_id,
                    "candidate_locale": _candidate_messages.infer_locale(
                        pending_media.get("raw_text") or request.raw_text,
                        preferred=((session or {}).get("metadata") or {}).get("candidate_locale")
                        if isinstance((session or {}).get("metadata"), dict)
                        else None,
                    ),
                },
            )
        conn.commit()
    if result.get("ok") and not result.get("duplicate"):
        import recruiting_lifecycle as _rl

        result["lifecycle"] = _rl.mark_cv_received(
            sys.modules[__name__],
            application=application,
            channel="whatsapp",
            conversation_id=request.conversation_id,
        )
    return result


def load_public_candidate_options(request: WhatsAppTurnRequest) -> list[dict[str, Any]]:
    session = active_public_candidate_session(request)
    if session and isinstance(session.get("shown_role_options"), list) and session["shown_role_options"]:
        return [role for role in session["shown_role_options"] if isinstance(role, dict)]
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT payload
                FROM memory_snapshots
                WHERE scope=%s
                  AND payload->>'phone'=%s
                  AND COALESCE(payload->>'account_id', 'default')=COALESCE(%s, 'default')
                  AND (%s IS NULL OR payload->>'conversation_id'=%s)
                  AND COALESCE(payload->>'expires_at','') > %s
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (
                    PUBLIC_CANDIDATE_SCOPE,
                    digits(request.sender_phone),
                    request.account_id,
                    request.conversation_id,
                    request.conversation_id,
                    now_iso(),
                ),
            )
            row = cur.fetchone()
    payload = row.get("payload") if row and isinstance(row.get("payload"), dict) else {}
    roles = payload.get("roles") if isinstance(payload.get("roles"), list) else []
    return [role for role in roles if isinstance(role, dict)]


def parse_public_role_selection_deterministic(text: str | None, roles: list[dict[str, Any]]) -> int | None:
    normalized = normalize_text(text)
    ordinal_map = {
        "second": 2,
        "2": 2,
        "two": 2,
        "third": 3,
        "3": 3,
        "three": 3,
        "fourth": 4,
        "4": 4,
        "fifth": 5,
        "5": 5,
        "first": 1,
        "1": 1,
        "one": 1,
    }
    for key, idx in ordinal_map.items():
        if re.search(rf"\b{re.escape(key)}\b", normalized) and 1 <= idx <= len(roles):
            return idx
    for idx, role in enumerate(roles, 1):
        title = normalize_text(str(role.get("title") or role.get("position_code") or "").replace("_", " "))
        code = normalize_text(str(role.get("position_code") or "").replace("_", " "))
        if title and title in normalized:
            return idx
        if code and code in normalized:
            return idx
    return None


def parse_public_role_selection_with_gpt(text: str, roles: list[dict[str, Any]]) -> int | None:
    provider = planner_provider_config()
    if not provider or not text.strip() or not roles:
        return None
    payload = {
        "candidate_message": text,
        "options": [
            {
                "index": idx,
                "title": role.get("title"),
                "position_code": role.get("position_code"),
                "apply_code": role.get("apply_code"),
            }
            for idx, role in enumerate(roles, 1)
        ],
        "json_schema": {
            "selected_index": "integer|null",
            "confidence": "number 0..1",
            "reason": "short string",
        },
    }
    system = "Map the candidate's reply to one of the listed public job options. Return JSON only. Do not invent an option."
    if provider.get("api") == "openai-responses":
        body = {"model": provider["model"], "temperature": 0, "input": [{"role": "system", "content": system}, {"role": "user", "content": json.dumps(payload, ensure_ascii=False)}]}
    else:
        body = {"model": provider["model"], "temperature": 0, "messages": [{"role": "system", "content": system}, {"role": "user", "content": json.dumps(payload, ensure_ascii=False)}]}
    try:
        req = urllib.request.Request(
            provider["url"],
            data=json.dumps(body).encode("utf-8"),
            headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=12) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
        result = extract_json_object(extract_model_text(parsed))
        if not isinstance(result, dict):
            return None
        idx = int(result.get("selected_index") or 0)
        confidence = float(result.get("confidence") or 0)
        if confidence >= 0.55 and 1 <= idx <= len(roles):
            return idx
    except Exception:
        return None
    return None


def handle_public_candidate_role_selection_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    roles = load_public_candidate_options(request)
    if not roles:
        return None
    selected = parse_public_role_selection_deterministic(request.raw_text, roles)
    if selected is None:
        selected = parse_public_role_selection_with_gpt(request.raw_text or "", roles)
    if selected is None or not (1 <= selected <= len(roles)):
        return None
    role = roles[selected - 1]
    preview = candidate_job_preview_stub(request, role)
    context = upsert_candidate_job_context(
        request,
        role=role,
        preview_locale=preview["locale"],
        preview_template_version=preview["template_version"],
    )
    session = upsert_public_candidate_session(
        request,
        roles=roles,
        selected_position_code=str(role.get("position_code") or ""),
        metadata={"selected_role": role},
        company_code=str(role.get("company_code") or ""),
    )
    reply_text = preview["text"]
    delivery = None
    if _jobs_stage_b.stage_b_enabled():
        delivery = _jobs_stage_b.deliver_and_stamp_job_preview(
            sys.modules[__name__],
            request=request,
            context=context,
            preview_text=preview["text"],
            company_code=str(role.get("company_code") or ""),
        )
        if delivery.get("suppress_reply"):
            reply_text = None
        refreshed = active_candidate_job_context(request)
        if refreshed:
            context = refreshed
    return {
        "reply": reply_text,
        "role": role,
        "session": session,
        "job_context": context,
        "preview_delivery": delivery,
        "application_created": False,
        "intent": "public_candidate_job_context_bound",
        "turn_focus": "public_candidate",
    }


def handle_public_candidate_apply_code_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    parsed = parse_apply_code_text(request.raw_text)
    if not parsed:
        return None
    resolved = resolve_public_role_by_apply_code(parsed["apply_code"])
    role = resolved.get("role") if isinstance(resolved.get("role"), dict) else None
    if not resolved.get("ok") or not role:
        message = candidate_job_unavailable_message(request, str(resolved.get("error") or ""))
        return {
            "reply": message["text"],
            "error": resolved.get("error") or "apply_code_not_found",
            "eligibility": resolved.get("details"),
            "intent": "public_candidate_apply_code_not_found",
            "turn_focus": "public_candidate",
        }
    existing_application = active_same_role_application(request, role)
    if existing_application:
        payload = candidate_message_payload(
            "job_context_existing_application",
            request=request,
            application=existing_application,
            role=role.get("title_en") or role.get("title") or role.get("position_code") or "the role",
        )
        return {
            "reply": payload["text"],
            "role": role,
            "application": existing_application,
            "application_created": False,
            "intent": "public_candidate_existing_application",
            "turn_focus": "public_candidate",
        }
    preview = candidate_job_preview_stub(request, role)
    context = upsert_candidate_job_context(
        request,
        role=role,
        preview_locale=preview["locale"],
        preview_template_version=preview["template_version"],
    )
    session = upsert_public_candidate_session(
        request,
        roles=[role],
        selected_position_code=str(role.get("position_code") or ""),
        metadata={"source": "apply_code", "apply_code": parsed["apply_code"]},
        company_code=str(role.get("company_code") or ""),
    )
    delivery = None
    reply_text = preview["text"]
    if _jobs_stage_b.stage_b_enabled():
        delivery = _jobs_stage_b.deliver_and_stamp_job_preview(
            sys.modules[__name__],
            request=request,
            context=context,
            preview_text=preview["text"],
            company_code=str(role.get("company_code") or ""),
        )
        if delivery.get("suppress_reply"):
            reply_text = None
        # Refresh context after stamp
        refreshed = active_candidate_job_context(request)
        if refreshed:
            context = refreshed
    return {
        "reply": reply_text,
        "role": role,
        "session": session,
        "job_context": context,
        "preview_delivery": delivery,
        "application": None,
        "application_created": False,
        "intent": "public_candidate_apply_code_context_bound",
        "turn_focus": "public_candidate",
    }


def handle_candidate_apply_confirm_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    """Stage B: explicit ready-to-apply confirmation while a unique context is bound."""
    if has_current_media_upload(request.media or {}):
        return None
    if not _jobs_stage_b.parse_apply_confirm(request.raw_text):
        return None
    if not _jobs_stage_b.stage_b_enabled():
        return None
    context = active_candidate_job_context(request)
    if not context:
        return None
    # Public canary job gate: Stage B convert only for dedicated position/APPLY code.
    if not _jobs_stage_b.stage_b_convert_allowed_for_job(
        position_code=str(context.get("position_code") or ""),
        apply_code=str(context.get("apply_code") or ""),
    ):
        # Non-canary contexts stay Stage A (no convert). Do not claim success.
        return None
    if not context.get("preview_sent_at"):
        # Deterministic nudge — do not convert without delivery truth.
        locale = _candidate_messages.normalize_locale(context.get("preview_locale"))
        return {
            **candidate_message_result(
                "apply_confirm_needed",
                request=request,
                locale=locale,
                role=context.get("position_code") or "the role",
            ),
            "job_context": context,
            "application_created": False,
            "intent": "candidate_apply_confirm_awaiting_preview_sent",
            "turn_focus": "public_candidate",
        }
    provider_id = ""
    if isinstance(request.metadata, dict):
        provider_id = str(
            request.metadata.get("provider_message_id")
            or request.metadata.get("message_id")
            or request.metadata.get("wamid")
            or ""
        )
    idem = f"{_jobs_stage_b.CONVERT_CONFIRM_PREFIX}{context.get('context_id')}:{provider_id or 'confirm'}"
    converted = _jobs_stage_b.convert_job_context_to_application(
        sys.modules[__name__],
        request,
        trigger="apply_confirm",
        idempotency_key=idem,
    )
    if not converted.get("ok"):
        error = str(converted.get("error") or "convert_failed")
        if error in {
            "job_paused",
            "job_closed",
            "job_deadline_passed",
            "job_vacancies_exhausted",
            "job_visibility_denied",
            "job_content_incomplete",
            "job_not_accepting",
            "apply_code_not_found",
        }:
            unavailable = candidate_job_unavailable_message(request, error)
            return {
                "reply": unavailable["text"],
                "error": error,
                "application_created": False,
                "intent": "candidate_apply_confirm_rejected",
                "turn_focus": "public_candidate",
            }
        if error == "stage_b_rate_limited":
            return {
                "reply": (
                    "Please wait before starting another application. "
                    "If you already applied for this role, ask for your status or send your CV."
                ),
                "error": error,
                "application_created": False,
                "intent": "candidate_apply_confirm_rate_limited",
                "turn_focus": "public_candidate",
            }
        return {
            **candidate_message_result("no_active_application", request=request),
            "error": error,
            "application_created": False,
            "intent": "candidate_apply_confirm_rejected",
            "turn_focus": "public_candidate",
        }
    application = converted.get("application") if isinstance(converted.get("application"), dict) else None
    role = converted.get("role") if isinstance(converted.get("role"), dict) else {}
    locale = _candidate_messages.normalize_locale((application or {}).get("raw_json", {}).get("candidate_locale") if application else context.get("preview_locale"))
    title = (
        role.get("title_ar")
        if locale == "ar" and role.get("title_ar")
        else role.get("title_en")
        or role.get("title")
        or role.get("position_code")
        or "the role"
    )
    if converted.get("existing_application"):
        return {
            **candidate_message_result(
                "job_context_existing_application",
                request=request,
                application=application,
                locale=locale,
                role=title,
            ),
            "application": application,
            "application_created": False,
            "job_context": converted.get("job_context"),
            "convert": converted,
            "intent": "candidate_apply_confirm_existing",
            "turn_focus": "public_candidate",
        }
    cv_attach = converted.get("cv_attach") if isinstance(converted.get("cv_attach"), dict) else None
    if cv_attach and cv_attach.get("ok"):
        return {
            **candidate_message_result(
                "file_received_checking",
                request=request,
                application=application,
                locale=locale,
            ),
            "application": application,
            "application_created": bool(converted.get("application_created")),
            "job_context": converted.get("job_context"),
            "convert": converted,
            "intent": "candidate_apply_confirm_converted_with_cv",
            "turn_focus": "public_candidate",
        }
    return {
        **candidate_message_result(
            "role_resolved_cv_request",
            request=request,
            application=application,
            locale=locale,
            role=title,
        ),
        "application": application,
        "application_created": bool(converted.get("application_created")),
        "job_context": converted.get("job_context"),
        "convert": converted,
        "intent": "candidate_apply_confirm_converted",
        "turn_focus": "public_candidate",
    }


def handle_public_candidate_apply_interest_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    pending_media = None
    if has_current_media_upload(request.media or {}):
        pending_media = {
            "media": request.media or {},
            "raw_text": request.raw_text,
            "received_at": now_iso(),
        }
    query = role_interest_from_text(request.raw_text)
    if not query and not pending_media:
        return None
    company = request_company_code(request, default=None)
    if not query and pending_media:
        roles = public_candidate_roles(company, limit=5) if company else []
        if company:
            upsert_public_candidate_session(
                request,
                roles=roles,
                pending_media=pending_media,
                metadata={"source": "pending_cv_without_role"},
                company_code=company,
            )
        return {
            **candidate_message_result("no_active_application", request=request),
            "roles": roles,
            "intent": "public_candidate_pending_cv_needs_role",
            "turn_focus": "public_candidate",
        }
    matches = public_role_matches(query, company_code=company)
    if not matches:
        if pending_media:
            if company:
                upsert_public_candidate_session(
                    request,
                    pending_media=pending_media,
                    metadata={"source": "pending_cv_no_role_match", "query": query},
                    company_code=company,
                )
        return {
            **candidate_message_result("welcome", request=request),
            "intent": "public_candidate_apply_help",
            "turn_focus": "public_candidate",
        }
    if len(matches) == 1:
        role = matches[0]
        session = upsert_public_candidate_session(
            request,
            roles=matches,
            selected_position_code=str(role.get("position_code") or ""),
            pending_media=pending_media,
            metadata={"source": "single_role_match", "query": query},
            company_code=str(role.get("company_code") or ""),
        )
        preview = candidate_job_preview_stub(request, role)
        context = upsert_candidate_job_context(
            request,
            role=role,
            preview_locale=preview["locale"],
            preview_template_version=preview["template_version"],
        )
        reply_text = preview["text"]
        delivery = None
        if _jobs_stage_b.stage_b_enabled():
            delivery = _jobs_stage_b.deliver_and_stamp_job_preview(
                sys.modules[__name__],
                request=request,
                context=context,
                preview_text=preview["text"],
                company_code=str(role.get("company_code") or ""),
            )
            if delivery.get("suppress_reply"):
                reply_text = None
            refreshed = active_candidate_job_context(request)
            if refreshed:
                context = refreshed
        return {
            "reply": reply_text,
            "role": role,
            "session": session,
            "job_context": context,
            "preview_delivery": delivery,
            "application": None,
            "application_created": False,
            "intent": "public_candidate_role_context_bound",
            "turn_focus": "public_candidate",
        }
    upsert_public_candidate_session(
        request,
        roles=matches,
        pending_media=pending_media,
        metadata={"source": "role_options", "query": query},
        company_code=company,
    )
    return {
        **candidate_message_result("ambiguous_application", request=request),
        "roles": matches,
        "intent": "public_candidate_role_options",
        "turn_focus": "public_candidate",
    }


