def active_candidate_screening_application(phone: str | None) -> dict[str, Any] | None:
    target = digits(phone)
    if not target:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT a.*, c.name AS candidate_name, c.email AS candidate_email
                FROM applications a
                LEFT JOIN candidates c ON c.phone=a.phone
                WHERE a.phone=%s
                  AND (a.current_step='screening' OR a.screening_status='pending' OR a.raw_json->'screening'->>'status'='pending')
                ORDER BY a.updated_at DESC NULLS LAST, a.ingested_at DESC NULLS LAST
                LIMIT 1
                """,
                (target,),
            )
            row = cur.fetchone()
            return dict(row) if row else None


def screening_questions_from_raw(application: dict[str, Any]) -> list[dict[str, Any]]:
    raw_json = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    questions = screening.get("questions") if isinstance(screening.get("questions"), list) else None
    if questions:
        return [q for q in questions if isinstance(q, dict)]
    return screening_questions_for_application(application)


def parse_screening_reply_answers(text: str, questions: list[dict[str, Any]], pending_keys: list[str]) -> dict[str, str]:
    raw = str(text or "").strip()
    if not raw:
        return {}
    by_index: dict[int, str] = {}
    matches = list(re.finditer(r"(?:^|\n)\s*(\d{1,2})[\).\:-]\s*(.+?)(?=(?:\n\s*\d{1,2}[\).\:-]\s*)|\Z)", raw, re.S))
    for match in matches:
        try:
            idx = int(match.group(1))
        except Exception:
            continue
        value = re.sub(r"\s+", " ", match.group(2)).strip()
        if value:
            by_index[idx] = value
    answers: dict[str, str] = {}
    if by_index:
        for idx, value in by_index.items():
            if 1 <= idx <= len(questions):
                key = str(questions[idx - 1].get("key") or f"q{idx}")
                answers[key] = value
        return answers
    # If the candidate replies naturally, bind to the next missing question.
    if pending_keys:
        answers[pending_keys[0]] = raw
    return answers


def parse_screening_reply_with_gpt(
    text: str,
    *,
    questions: list[dict[str, Any]],
    pending_keys: list[str],
    existing_answers: dict[str, Any],
) -> dict[str, Any] | None:
    provider = planner_provider_config()
    if not provider or not text.strip() or not questions:
        return None
    allowed_keys = [str(q.get("key") or f"q{idx}") for idx, q in enumerate(questions, 1)]
    payload = {
        "candidate_reply": text,
        "questions": [
            {
                "key": str(q.get("key") or f"q{idx}"),
                "question": q.get("question") or q.get("text") or q.get("key"),
                "required": bool(q.get("required")),
            }
            for idx, q in enumerate(questions, 1)
        ],
        "pending_keys": pending_keys,
        "existing_answers": existing_answers,
        "rules": [
            "Return JSON only.",
            "Only use keys from questions.",
            "Extract multiple answers if present, even if out of order.",
            "If the candidate corrects an earlier answer, put it in corrections.",
            "If the candidate asks a question instead of answering, set candidate_question.",
            "Do not infer HR decisions or scores.",
        ],
        "json_schema": {
            "answers": {"question_key": "answer string"},
            "corrections": {"question_key": "corrected answer string"},
            "candidate_question": "string|null",
            "unsupported_request": "string|null",
            "confidence": "number 0..1",
            "reason": "short string",
        },
    }
    system = "You parse candidate screening replies into structured answers for an HR application. Do not invent. Return JSON only."
    if provider.get("api") == "openai-responses":
        body = {
            "model": provider["model"],
            "temperature": 0,
            "input": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    else:
        body = {
            "model": provider["model"],
            "temperature": 0,
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=16) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception:
        return None
    result = extract_json_object(extract_model_text(parsed))
    if not isinstance(result, dict):
        return None
    try:
        confidence = float(result.get("confidence") or 0)
    except Exception:
        confidence = 0.0
    answers = result.get("answers") if isinstance(result.get("answers"), dict) else {}
    corrections = result.get("corrections") if isinstance(result.get("corrections"), dict) else {}
    clean_answers = {str(k): str(v).strip() for k, v in answers.items() if str(k) in allowed_keys and str(v).strip()}
    clean_corrections = {str(k): str(v).strip() for k, v in corrections.items() if str(k) in allowed_keys and str(v).strip()}
    if confidence < 0.80 and not clean_answers and not clean_corrections and not result.get("candidate_question"):
        return None
    return {
        "answers": clean_answers,
        "corrections": clean_corrections,
        "candidate_question": str(result.get("candidate_question") or "").strip() or None,
        "unsupported_request": str(result.get("unsupported_request") or "").strip() or None,
        "confidence": confidence,
        "reason": result.get("reason"),
        "parser": "gpt_screening_reply_v1",
    }


def format_next_screening_question(questions: list[dict[str, Any]], pending_keys: list[str]) -> str:
    if not pending_keys:
        return ""
    key = pending_keys[0]
    for question in questions:
        if str(question.get("key") or "") == key:
            return str(question.get("question") or question.get("text") or key)
    return key


def application_has_pending_screening(application: dict[str, Any] | None) -> bool:
    if not isinstance(application, dict):
        return False
    raw_json = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    status = str(screening.get("status") or application.get("screening_status") or application.get("current_step") or "").lower()
    if status in {"complete", "completed"}:
        return False
    questions = screening_questions_from_raw(application)
    existing_answers = screening.get("answers") if isinstance(screening.get("answers"), dict) else {}
    required_keys = [str(q.get("key") or f"q{idx}") for idx, q in enumerate(questions, 1) if q.get("required") is True]
    missing = [key for key in required_keys if not str(existing_answers.get(key) or "").strip()]
    return bool(missing) or status in {"pending", "screening"} or str(application.get("current_step") or "").lower() == "screening"


def resolve_bound_screening_application(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    """Exact company/conversation/application binding for screening answers."""
    if not request.conversation_id or not str(request.raw_text or "").strip():
        return None
    resolution = resolve_candidate_request_application(request)
    if not resolution.get("ok"):
        return None
    application = resolution.get("application") if isinstance(resolution.get("application"), dict) else None
    if not application or not application_has_pending_screening(application):
        return None
    binding = resolution.get("binding") if isinstance(resolution.get("binding"), dict) else {}
    bound_app_key = str(binding.get("app_key") or "")
    app_key = str(application.get("app_key") or "")
    if bound_app_key and app_key and bound_app_key != app_key:
        return None
    company = str(application.get("company_code") or "").strip().upper()
    if company and active_company_code() and company != str(active_company_code() or "").strip().upper():
        # Missing request scope cannot authorize a tenant mismatch.
        request_company = request_company_code(request)
        if not request_company or str(request_company).strip().upper() != company:
            return None
    return application


def persist_candidate_locale(
    request: WhatsAppTurnRequest,
    *,
    application: dict[str, Any] | None,
    locale: str | None,
) -> None:
    loc = _candidate_messages.normalize_locale(locale)
    if not application or not application.get("app_key"):
        return
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE applications
                    SET raw_json = COALESCE(raw_json, '{}'::jsonb) || %s::jsonb,
                        updated_at = now()
                    WHERE app_key=%s
                    """,
                    (
                        Json(
                            {
                                "candidate_locale": loc,
                                "candidate_communication": {"locale": loc, "updated_at": now_iso()},
                            }
                        ),
                        application.get("app_key"),
                    ),
                )
            conn.commit()
    except Exception:
        return
    if request.conversation_id:
        try:
            import recruiting_lifecycle as _rl

            _rl.update_candidate_conversation_state(
                sys.modules[__name__],
                company_code=str(application.get("company_code") or ""),
                conversation_id=str(request.conversation_id),
                phone=str(application.get("phone") or request.sender_phone),
                app_key=str(application.get("app_key") or ""),
                updates={"candidate_locale": loc},
            )
        except Exception:
            return


def store_candidate_clarification_state(
    request: WhatsAppTurnRequest,
    *,
    router_result: dict[str, Any],
) -> dict[str, Any]:
    resolution = resolve_candidate_request_application(request)
    application = resolution.get("application") if isinstance(resolution.get("application"), dict) else None
    if not application or not request.conversation_id:
        return {"ok": False, "error": "no_binding_for_clarification"}
    import recruiting_lifecycle as _rl

    pending = {
        "type": "intent_clarification",
        "status": "pending",
        "created_at": now_iso(),
        "prompt_version": router_result.get("prompt_version"),
        "schema_version": router_result.get("schema_version"),
        "model": router_result.get("model"),
        "confidence": router_result.get("confidence"),
        "intent_hint": router_result.get("intent"),
        "clarification_reason": router_result.get("clarification_reason"),
        "secondary_intents": router_result.get("secondary_intents") or [],
        "raw_text": str(request.raw_text or "")[:500],
    }
    return _rl.update_candidate_conversation_state(
        sys.modules[__name__],
        company_code=str(application.get("company_code") or ""),
        conversation_id=str(request.conversation_id),
        phone=str(application.get("phone") or request.sender_phone),
        app_key=str(application.get("app_key") or ""),
        updates={"pending_candidate_action": pending, "candidate_locale": router_result.get("language")},
    )


def execute_candidate_semantic_intent(
    request: WhatsAppTurnRequest,
    *,
    intent: str,
    router_result: dict[str, Any],
) -> dict[str, Any] | None:
    """Backend authority actions for accepted Luna intents. Model never mutates directly."""
    locale = _candidate_messages.normalize_locale(router_result.get("language"))
    if intent == "apply_role":
        role_text = str(router_result.get("role_text") or request.raw_text or "").strip()
        if not role_text:
            return None
        patched = request.model_copy(update={"raw_text": role_text}) if hasattr(request, "model_copy") else request
        if not hasattr(request, "model_copy"):
            # Pydantic v1 fallback
            patched = WhatsAppTurnRequest(**{**request.model_dump(), "raw_text": role_text})
        result = handle_public_candidate_apply_interest_turn(patched) or handle_public_candidate_role_selection_turn(patched)
        if result:
            result["semantic_router"] = json_safe(router_result)
            result["locale"] = locale
            return result
        return {
            **candidate_message_result("welcome", request=request, locale=locale),
            "intent": "apply_role_unresolved",
            "semantic_router": json_safe(router_result),
        }
    if intent == "replace_cv":
        resolution = resolve_candidate_request_application(request)
        application = resolution.get("application") if isinstance(resolution.get("application"), dict) else None
        if not resolution.get("ok") or not application:
            return candidate_resolution_failure_message(request, resolution)
        persist_candidate_locale(request, application=application, locale=locale)
        return {
            **candidate_message_result("cv_replacement_requested", request=request, application=application, locale=locale),
            "application": json_safe(application),
            "intent": "candidate_cv_update_request",
            "turn_focus": "candidate_cv_update",
            "semantic_router": json_safe(router_result),
        }
    if intent == "cv_received":
        application = find_candidate_application_for_file(request.sender_phone)
        if not application:
            resolution = resolve_candidate_request_application(request)
            if not resolution.get("ok"):
                return candidate_resolution_failure_message(request, resolution)
            application = resolution.get("application")
        if not application:
            return candidate_message_result("no_active_application", request=request, locale=locale)
        persist_candidate_locale(request, application=application, locale=locale)
        truth = candidate_cv_truth(application)
        if truth.get("cv_received") and truth.get("storage_ok"):
            reply = candidate_message_payload("cv_accepted", request=request, application=application, locale=locale)["text"]
        elif truth.get("cv_received"):
            reply = candidate_message_payload("cv_invalid", request=request, application=application, locale=locale)["text"]
        else:
            reply = candidate_message_payload("no_active_application", request=request, application=application, locale=locale)["text"]
            # Prefer a clearer "not received yet" when application exists but CV missing.
            if locale == "ar":
                reply = "ما شفت سيرة ذاتية محفوظة لطلبك بعد. أرسل سيرتك كملف PDF أو DOCX أو صورة واضحة."
            else:
                reply = "I do not see a CV saved for your application yet. Please send your CV as a PDF, DOCX, or clear image."
        return {
            "reply": reply,
            "application": json_safe(application),
            "truth": truth,
            "intent": "candidate_cv_received_inquiry",
            "semantic_router": json_safe(router_result),
        }
    if intent == "status":
        resolution = resolve_candidate_request_application(request)
        application = resolution.get("application") if isinstance(resolution.get("application"), dict) else None
        if not resolution.get("ok") or not application:
            return candidate_resolution_failure_message(request, resolution)
        persist_candidate_locale(request, application=application, locale=locale)
        return {
            **candidate_message_result(
                "application_status",
                request=request,
                application=application,
                locale=locale,
                role=application.get("position_title") or application.get("position_code") or "the role",
                status=_candidate_messages.status_label(application.get("status"), locale),
            ),
            "application": json_safe(application),
            "intent": "candidate_application_status",
            "turn_focus": "candidate_status",
            "semantic_router": json_safe(router_result),
        }
    if intent in {"withdraw", "confirm_withdraw", "cancel_withdraw"}:
        # Reuse withdrawal authority path. Pending confirmations stay deterministic-first;
        # Luna only reaches here when those did not already resolve.
        if intent == "confirm_withdraw":
            patched_text = "CONFIRM"
        elif intent == "cancel_withdraw":
            patched_text = "CANCEL"
        else:
            patched_text = "I want to withdraw my application"
        if hasattr(request, "model_copy"):
            patched = request.model_copy(update={"raw_text": patched_text})
        else:
            patched = WhatsAppTurnRequest(**{**request.model_dump(), "raw_text": patched_text})
        # For initial withdraw, force the intent branch by calling the handler after
        # temporarily satisfying the withdraw detector via English canonical text.
        result = handle_candidate_withdrawal_turn(patched)
        if result:
            result["semantic_router"] = json_safe(router_result)
            return result
        return None
    if intent == "hr_handoff":
        resolution = resolve_candidate_request_application(request)
        application = resolution.get("application") if isinstance(resolution.get("application"), dict) else None
        if not resolution.get("ok") or not application:
            return candidate_resolution_failure_message(request, resolution)
        import recruiting_lifecycle as _rl

        persist_candidate_locale(request, application=application, locale=locale)
        handoff = _rl.request_candidate_handoff(
            sys.modules[__name__],
            application=application,
            conversation_id=str(request.conversation_id or ""),
            account_id=request.account_id,
            locale=locale,
        )
        if not handoff.get("ok"):
            return {
                "ok": False,
                "error": handoff.get("error") or "handoff_failed",
                **candidate_message_result("ambiguous_application", request=request, application=application, locale=locale),
                "semantic_router": json_safe(router_result),
            }
        return {
            "ok": True,
            **candidate_message_result("hr_handoff_confirmation", request=request, application=application, locale=locale),
            "intent": "candidate_hr_handoff",
            "handoff": json_safe(handoff),
            "semantic_router": json_safe(router_result),
        }
    if intent in {"assessment", "interview", "offer"}:
        return execute_candidate_stage_inquiry(request, intent=intent, router_result=router_result, locale=locale)
    return None


def execute_candidate_stage_inquiry(
    request: WhatsAppTurnRequest,
    *,
    intent: str,
    router_result: dict[str, Any],
    locale: str,
) -> dict[str, Any]:
    """Read-only stage inquiries. Never issues new secure tokens or mutates lifecycle."""
    resolution = resolve_candidate_request_application(request)
    application = resolution.get("application") if isinstance(resolution.get("application"), dict) else None
    if not resolution.get("ok") or not application:
        return {
            **candidate_resolution_failure_message(request, resolution),
            "semantic_router": json_safe(router_result),
        }
    persist_candidate_locale(request, application=application, locale=locale)
    raw = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
    role = application.get("position_title") or application.get("position_code") or "the role"
    if intent == "assessment":
        assessment = raw.get("assessment") if isinstance(raw.get("assessment"), dict) else {}
        link = str(assessment.get("secure_link") or assessment.get("link") or "").strip()
        if link:
            return {
                **candidate_message_result(
                    "assessment_invitation",
                    request=request,
                    application=application,
                    locale=locale,
                    role=role,
                    link=link,
                ),
                "intent": "candidate_assessment_inquiry",
                "mutation_attempt": False,
                "semantic_router": json_safe(router_result),
            }
        return {
            **candidate_message_result("assessment_inquiry_none", request=request, application=application, locale=locale),
            "intent": "candidate_assessment_inquiry",
            "mutation_attempt": False,
            "semantic_router": json_safe(router_result),
        }
    if intent == "interview":
        interview = raw.get("interview") if isinstance(raw.get("interview"), dict) else {}
        link = str(interview.get("secure_link") or interview.get("link") or "").strip() or ""
        details = str(interview.get("details") or interview.get("summary") or "").strip()
        if link or details:
            return {
                **candidate_message_result(
                    "interview_invitation",
                    request=request,
                    application=application,
                    locale=locale,
                    role=role,
                    details=details or ("Details are available in your secure link." if locale == "en" else "التفاصيل متاحة في الرابط الآمن."),
                    link=link,
                ),
                "intent": "candidate_interview_inquiry",
                "mutation_attempt": False,
                "semantic_router": json_safe(router_result),
            }
        return {
            **candidate_message_result("interview_inquiry_none", request=request, application=application, locale=locale),
            "intent": "candidate_interview_inquiry",
            "mutation_attempt": False,
            "semantic_router": json_safe(router_result),
        }
    offer = raw.get("offer") if isinstance(raw.get("offer"), dict) else {}
    link = str(offer.get("secure_link") or offer.get("link") or "").strip()
    if link:
        return {
            **candidate_message_result(
                "offer_invitation",
                request=request,
                application=application,
                locale=locale,
                role=role,
                link=link,
            ),
            "intent": "candidate_offer_inquiry",
            "mutation_attempt": False,
            "semantic_router": json_safe(router_result),
        }
    return {
        **candidate_message_result("offer_inquiry_none", request=request, application=application, locale=locale),
        "intent": "candidate_offer_inquiry",
        "mutation_attempt": False,
        "semantic_router": json_safe(router_result),
    }


def handle_candidate_semantic_router_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    """Luna NL router after deterministic APPLY/media/pending/token paths."""
    if has_current_media_upload(request.media or {}):
        return None
    text = str(request.raw_text or "").strip()
    if not text:
        return None
    # APPLY codes and active public option ordinals stay deterministic-first.
    if parse_apply_code_text(text):
        return None
    application, pending = candidate_pending_action(request)
    if pending and pending.get("status") == "pending" and pending.get("type") == "replace_cv":
        return handle_candidate_withdrawal_turn(request)
    if pending and pending.get("status") == "pending" and pending.get("type") in {"withdraw", "intent_clarification"}:
        # Pending confirmations / clarifications: only continue with Luna when the
        # deterministic pending withdraw path did not already claim the turn.
        if pending.get("type") == "withdraw":
            return None
    provider = candidate_semantic_provider_config()
    context = {
        "has_active_application": bool(candidate_active_application(request.sender_phone)),
        "pending_action_type": (pending or {}).get("type") if isinstance(pending, dict) else None,
        "conversation_id": request.conversation_id,
        "account_id": request.account_id,
    }
    router_result = _candidate_semantic_router.classify_candidate_intent(
        text,
        provider=provider,
        context=context,
    )
    telemetry_provider = {
        **(provider or {}),
        "model": _candidate_semantic_router.MODEL_ID,
    }
    record_llm_call(
        call_name="candidate_semantic_router_v1",
        provider=telemetry_provider,
        prompt_mode=_candidate_semantic_router.PROMPT_VERSION,
        prompt_docs_loaded=False,
        prompt_hash=_candidate_semantic_router.SCHEMA_VERSION,
        estimated_input_tokens=router_result.get("input_tokens"),
        latency_ms=router_result.get("latency_ms"),
        status="ok" if router_result.get("ok") else "error",
        parsed={
            "id": router_result.get("response_id"),
            "usage": {
                "input_tokens": router_result.get("input_tokens"),
                "output_tokens": router_result.get("output_tokens"),
                "total_tokens": router_result.get("total_tokens"),
                "input_tokens_details": {"cached_tokens": router_result.get("cached_tokens")},
            },
        },
        error=router_result.get("error"),
        metadata={
            "prompt_version": _candidate_semantic_router.PROMPT_VERSION,
            "schema_version": _candidate_semantic_router.SCHEMA_VERSION,
            "catalog_version": _candidate_semantic_router.CATALOG_VERSION,
            "confidence": router_result.get("confidence"),
            "intent": router_result.get("intent"),
            "accepted_intent": router_result.get("accepted_intent"),
            "needs_clarification": router_result.get("needs_clarification"),
            "language": router_result.get("language"),
            "estimated_cost_usd": router_result.get("estimated_cost_usd"),
            "threshold": _candidate_semantic_router.CONFIDENCE_THRESHOLD,
            "secondary_intents": router_result.get("secondary_intents"),
            "mutation_attempt": False,
        },
    )
    locale = _candidate_messages.normalize_locale(router_result.get("language") or _candidate_messages.infer_locale(text))
    if application:
        persist_candidate_locale(request, application=application, locale=locale)

    if not _candidate_semantic_router.should_accept(router_result):
        store_candidate_clarification_state(request, router_result=router_result)
        return {
            **candidate_message_result("intent_clarification", request=request, application=application, locale=locale),
            "intent": "candidate_intent_clarification",
            "turn_focus": "candidate_clarification",
            "semantic_router": json_safe(router_result),
            "mutation_attempt": False,
        }

    accepted = str(router_result.get("accepted_intent") or "")
    executed = execute_candidate_semantic_intent(request, intent=accepted, router_result=router_result)
    if executed:
        executed.setdefault("mutation_attempt", False)
        executed["semantic_router"] = json_safe(router_result)
        return executed
    store_candidate_clarification_state(request, router_result=router_result)
    return {
        **candidate_message_result("intent_clarification", request=request, application=application, locale=locale),
        "intent": "candidate_intent_clarification",
        "turn_focus": "candidate_clarification",
        "semantic_router": json_safe(router_result),
        "mutation_attempt": False,
    }


def handle_candidate_screening_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    application = resolve_bound_screening_application(request)
    if not application:
        return None
    if not company_has_module(application.get("company_code"), "pre_hiring"):
        return {"reply": candidate_safe_module_unavailable_reply(), "application": json_safe(application), "module_disabled": "pre_hiring"}
    raw_json = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    if str(screening.get("status") or application.get("screening_status") or "").lower() in {"complete", "completed"}:
        return None
    questions = screening_questions_from_raw(application)
    existing_answers = screening.get("answers") if isinstance(screening.get("answers"), dict) else {}
    required_keys = [str(q.get("key") or f"q{idx}") for idx, q in enumerate(questions, 1) if q.get("required") is True]
    missing_before = [key for key in required_keys if not str(existing_answers.get(key) or "").strip()]
    if not missing_before:
        return None
    screening_binding = {
        "company_code": application.get("company_code"),
        "conversation_id": request.conversation_id,
        "app_key": application.get("app_key"),
    }
    normalized = normalize_text(request.raw_text)
    if normalized in {"hi", "hello", "hey", "salam", "thanks", "thank you", "ok", "okay"}:
        next_question = format_next_screening_question(questions, missing_before)
        return {
            "reply": f"Thanks. Please answer this quick application question:\n\n{next_question}",
            "application": json_safe(application),
            "questions": json_safe(questions),
            "pending_keys": missing_before,
            "intent": "await_screening_answer",
            "turn_focus": "candidate_screening",
            "screening_binding": screening_binding,
        }
    parsed_structured = parse_screening_reply_with_gpt(
        request.raw_text,
        questions=questions,
        pending_keys=missing_before,
        existing_answers=existing_answers,
    )
    parsed_answers: dict[str, str] = {}
    parsed_corrections: dict[str, str] = {}
    parser_name = "deterministic_screening_reply_v1"
    parser_confidence = None
    if parsed_structured:
        parsed_answers = dict(parsed_structured.get("answers") or {})
        parsed_corrections = dict(parsed_structured.get("corrections") or {})
        parser_name = str(parsed_structured.get("parser") or "gpt_screening_reply_v1")
        parser_confidence = parsed_structured.get("confidence")
        if parsed_structured.get("candidate_question") and not parsed_answers and not parsed_corrections:
            next_question = format_next_screening_question(questions, missing_before)
            return {
                "reply": f"I can help with the application process, but I can’t share hiring decisions here.\n\nPlease also answer this quick application question:\n{next_question}",
                "application": json_safe(application),
                "candidate_question": parsed_structured.get("candidate_question"),
                "pending_keys": missing_before,
                "intent": "candidate_screening_question",
                "turn_focus": "candidate_screening",
                "screening_binding": screening_binding,
            }
    if not parsed_answers and not parsed_corrections:
        parsed_answers = parse_screening_reply_answers(request.raw_text, questions, missing_before)
    if not parsed_answers and not parsed_corrections:
        next_question = format_next_screening_question(questions, missing_before)
        return {
            "reply": f"Please answer this quick application question:\n\n{next_question}",
            "application": json_safe(application),
            "questions": json_safe(questions),
            "pending_keys": missing_before,
            "intent": "await_screening_answer",
            "turn_focus": "candidate_screening",
            "screening_binding": screening_binding,
        }
    answers = {**existing_answers, **parsed_answers, **parsed_corrections}
    answer_sources = screening.get("answer_sources") if isinstance(screening.get("answer_sources"), dict) else {}
    answer_evidence = screening.get("answer_evidence") if isinstance(screening.get("answer_evidence"), dict) else {}
    for key, value in {**parsed_answers, **parsed_corrections}.items():
        answer_sources[key] = "candidate_reply"
        answer_evidence[key] = {
            "reply_text": request.raw_text,
            "captured_at": now_iso(),
            "value": value,
            "parser": parser_name,
            "confidence": parser_confidence,
            "correction": key in parsed_corrections,
        }
    missing_after = [key for key in required_keys if not str(answers.get(key) or "").strip()]
    status = "complete" if not missing_after else "pending"
    screening_next = {
        **screening,
        "status": status,
        "answers": answers,
        "answer_sources": answer_sources,
        "answer_evidence": answer_evidence,
        "questions": questions,
        "pending_keys": missing_after,
        "last_answered_at": now_iso(),
        "completed_at": now_iso() if status == "complete" else screening.get("completed_at"),
    }
    raw_next = {**raw_json, "screening": screening_next}
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE applications
                SET raw_json=%s,
                    screening_status=%s,
                    screening_completed_at=CASE WHEN %s='complete' THEN COALESCE(screening_completed_at, CURRENT_DATE) ELSE screening_completed_at END,
                    updated_at=now()
                WHERE app_key=%s
                  AND company_code=%s
                """,
                (
                    Json(json_safe(raw_next)),
                    status,
                    status,
                    application.get("app_key"),
                    application.get("company_code"),
                ),
            )
        conn.commit()
    lifecycle_application = application
    if status == "complete":
        import recruiting_lifecycle as _rl

        lifecycle_result = _rl.mark_cv_ready_for_review(
            sys.modules[__name__],
            application=application,
            cv_version=str((screening_next.get("completed_at") or "")),
        )
        if not lifecycle_result.get("ok"):
            return {
                "reply": "I saved your answers, but the application could not be moved to review. HR has been notified.",
                "error": lifecycle_result.get("error"),
                "application": json_safe(application),
                "screening_status": status,
                "intent": "handle_candidate_screening_answer",
            }
        if isinstance(lifecycle_result.get("application"), dict):
            lifecycle_application = lifecycle_result["application"]
        reply = "Thanks — I’ve saved your screening answers. Your application is now complete for review."
    else:
        next_question = format_next_screening_question(questions, missing_after)
        reply = f"Thanks, I saved that.\n\nNext question:\n{next_question}"
    return {
        "reply": reply,
        "application": json_safe({**lifecycle_application, "raw_json": raw_next, "screening_status": status}),
        "captured_answers": json_safe(parsed_answers),
        "captured_corrections": json_safe(parsed_corrections),
        "parser": parser_name,
        "parser_confidence": parser_confidence,
        "pending_keys": missing_after,
        "screening_status": status,
        "intent": "handle_candidate_screening_answer",
        "turn_focus": "candidate_screening",
        "screening_binding": screening_binding,
    }


def non_hr_truth_response(
    *,
    handler_key: str,
    intent: str,
    turn_focus: str,
    result: dict[str, Any],
) -> dict[str, Any]:
    return {
        "authoritative": True,
        "reply": result.get("reply"),
        "handler_key": handler_key,
        "intent": intent,
        "turn_focus": turn_focus,
        "final_reply_source": f"{handler_key}_handler",
        "result": json_safe(result),
        "truth_response": {
            "handler_key": handler_key,
            "intent": intent,
            "turn_focus": turn_focus,
            "has_backend_truth": True,
        },
    }


def handle_non_hr_conversational_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    ordered_handlers = [
        ("employee_shift_objection", "handle_employee_shift_objection", "employee_shift", handle_employee_shift_objection_turn),
        ("employee_leave", "handle_employee_leave", "employee_leave", handle_employee_leave_turn),
        ("employee_attendance", "handle_employee_attendance", "employee_attendance", handle_employee_attendance_turn),
        ("employee_payroll", "handle_employee_payroll", "employee_payroll", handle_employee_payroll_turn),
        ("employee_shift", "answer_employee_shift_status", "employee_shift", handle_employee_shift_turn),
        ("candidate_withdrawal", "candidate_withdrawal", "candidate_withdrawal", handle_candidate_withdrawal_turn),
        ("candidate_handoff", "candidate_hr_handoff", "candidate_handoff", handle_candidate_hr_handoff_turn),
        ("candidate_cv_update", "candidate_cv_update_request", "candidate_cv_update", handle_candidate_cv_update_request_turn),
        ("candidate_status", "candidate_application_status", "candidate_status", handle_candidate_application_status_turn),
        ("candidate_handoff_pause", "candidate_automation_paused", "candidate_handoff", handle_candidate_automation_pause_turn),
        ("candidate_file", "handle_candidate_file", "candidate_file", handle_candidate_file_turn),
        ("candidate_apply_confirm", "candidate_apply_confirm", "public_candidate", handle_candidate_apply_confirm_turn),
        ("candidate_assessment", "handle_candidate_assessment", "candidate_assessment", handle_candidate_assessment_turn),
        ("public_candidate_apply_code", "public_candidate_apply_code_started", "public_candidate", handle_public_candidate_apply_code_turn),
        ("public_candidate_selection", "public_candidate_role_selected", "public_candidate", handle_public_candidate_role_selection_turn),
        ("public_candidate_apply", "public_candidate_apply_help", "public_candidate", handle_public_candidate_apply_interest_turn),
        ("candidate_screening", "handle_candidate_screening_answer", "candidate_screening", handle_candidate_screening_turn),
        ("candidate_process", "candidate_process_question", "candidate_process", handle_candidate_process_faq_turn),
        ("candidate_truth", "answer_candidate_cv_status", "candidate_cv_status", handle_candidate_truth_turn),
        ("employee_onboarding", "handle_employee_onboarding_reply", "employee_onboarding", handle_employee_onboarding_turn),
        ("candidate_semantic_router", "candidate_semantic_router", "candidate_semantic", handle_candidate_semantic_router_turn),
        ("candidate_casual", "candidate_casual", "candidate_casual", handle_candidate_casual_turn),
        ("candidate_fallback", "candidate_safe_fallback", "candidate_fallback", handle_candidate_safe_fallback_turn),
    ]
    for handler_key, intent, turn_focus, handler in ordered_handlers:
        result = handler(request)
        if not result:
            continue
        if result.get("reply"):
            if handler_key.startswith(("candidate_", "public_candidate_")):
                result = _candidate_c2_module().strip_collaboration_fields_from_candidate_payload(result)
                result = _candidate_c3_module().strip_identity_fields_from_candidate_payload(result)
                guarded = apply_candidate_reply_policy(str(result.get("reply") or ""), request=request, result=result)
                result = {**result, "reply": guarded.get("reply"), "candidate_policy": guarded}
            return non_hr_truth_response(
                handler_key=handler_key,
                intent=str(result.get("intent") or intent),
                turn_focus=str(result.get("turn_focus") or turn_focus),
                result=result,
            )
        if result.get("error") == "module_disabled":
            module = str(result.get("required_module") or handler_key)
            result["reply"] = module_disabled_reply(result.get("company_code"), module)
            return non_hr_truth_response(handler_key=handler_key, intent=intent, turn_focus="module_disabled", result=result)
    return None


def plan_employee_onboarding_reply(
    *,
    employee: dict[str, Any],
    text: str,
    media: dict[str, Any] | None,
    next_item: dict[str, Any] | None,
) -> dict[str, Any] | None:
    system = (
        "You classify employee onboarding replies for OctoHR. "
        "Call classify_employee_onboarding_reply when the reply contains a name, bank/IBAN details, a document/photo indication, or any onboarding item. "
        "Use current_pending_item for ambiguous document/photo media. "
        "For Civil ID, passport, personal photo, medical, or education certificates, text-only messages are not receipts; require current-message media. "
        "Repeated instructions such as 'please send Civil ID, passport, personal photo' are not employee submissions. Do not invent values."
    )
    user_payload = {
        "employee": {
            "employee_key": employee.get("employee_key"),
            "name": employee.get("name"),
            "phone": employee.get("phone"),
            "onboarding_status": employee.get("onboarding_status"),
        },
        "reply_text": text,
        "media": media or {},
        "current_pending_item": next_item or {},
        "valid_items": ["bank_details", "civil_id", "passport", "personal_photo", "medical", "education_cert"],
    }
    call = call_single_tool_agent(system=system, user_payload=user_payload, tools=EMPLOYEE_REPLY_TOOL_DEFINITIONS)
    if not call or call.get("tool") != "classify_employee_onboarding_reply":
        return None
    args = call.get("args") if isinstance(call.get("args"), dict) else {}
    try:
        confidence = float(args.get("confidence", 0))
    except Exception:
        confidence = 0.0
    if confidence < 0.55:
        return None
    reply_type = str(args.get("reply_type") or "unknown")
    item_id = str(args.get("item_id") or "unknown")
    value = str(args.get("value") or text or "").strip()
    if reply_type == "name" and value:
        return {"reply_type": "name", "value": value, "reason": args.get("reason"), "confidence": confidence}
    if reply_type == "onboarding_item" and item_id in {"bank_details", "civil_id", "passport", "personal_photo", "medical", "education_cert"}:
        return {"reply_type": "onboarding_item", "item_id": item_id, "value": value, "reason": args.get("reason"), "confidence": confidence}
    return None


MEDIA_REQUIRED_ONBOARDING_ITEMS = {"civil_id", "passport", "personal_photo", "medical", "medical_check", "education_cert", "employment_contract"}
IDENTITY_REQUIRED_ONBOARDING_ITEMS = {"civil_id", "passport"}
SHARED_STRUCTURED_ONBOARDING_ITEMS = {"civil_id", "passport", "medical", "medical_check", "education_cert", "employment_contract", "residence", "residency", "work_permit"}


def has_current_media_upload(media: dict[str, Any] | None) -> bool:
    if not isinstance(media, dict):
        return False
    media_path = str(media.get("path") or media.get("url") or "").strip()
    media_type = str(media.get("type") or media.get("mime_type") or "").strip().lower()
    return bool(media_path and media_type)


def is_onboarding_instruction_echo(text: str | None) -> bool:
    normalized = normalize_text(text)
    if not normalized:
        return False
    instruction_markers = [
        "confirm your full name",
        "should appear in our records",
        "also please send",
        "please send civil id",
        "please send passport",
        "civil id front and back",
        "passport photo page",
        "personal photo",
    ]
    hits = sum(1 for marker in instruction_markers if marker in normalized)
    return hits >= 2 and ("please send" in normalized or "confirm your full name" in normalized)


def text_has_iban(text: str | None) -> bool:
    compact = re.sub(r"[^a-z0-9]+", "", normalize_text(text))
    return bool(re.search(r"kw\d{2}[a-z0-9]{10,}", compact))


KUWAIT_BANKS = {
    "NBOK": {"canonical": "National Bank of Kuwait", "aliases": ["nbk", "national bank of kuwait", "بنك الكويت الوطني"]},
    "GULB": {"canonical": "Gulf Bank", "aliases": ["gulf bank", "بنك الخليج"]},
    "CBKU": {"canonical": "Commercial Bank of Kuwait", "aliases": ["cbk", "commercial bank of kuwait", "البنك التجاري الكويتي"]},
    "ABKK": {"canonical": "Al Ahli Bank of Kuwait", "aliases": ["abk", "al ahli bank of kuwait", "ahli bank of kuwait", "البنك الاهلي الكويتي", "البنك الأهلي الكويتي"]},
    "BRGN": {"canonical": "Burgan Bank", "aliases": ["burgan", "burgan bank", "بنك برقان"]},
    "AUBK": {"canonical": "Ahli United Bank", "aliases": ["aub", "ahli united bank", "al ahli united bank", "البنك الاهلي المتحد", "البنك الأهلي المتحد"]},
    "KFHU": {"canonical": "Kuwait Finance House", "aliases": ["kfh", "kuwait finance house", "بيت التمويل الكويتي"]},
    "BBYN": {"canonical": "Boubyan Bank", "aliases": ["boubyan", "boubyan bank", "بنك بوبيان"]},
    "KIBK": {"canonical": "Kuwait International Bank", "aliases": ["kib", "kuwait international bank", "بنك الكويت الدولي"]},
    "WARB": {"canonical": "Warba Bank", "aliases": ["warba", "warba bank", "بنك وربة"]},
    "IBKU": {"canonical": "Industrial Bank of Kuwait", "aliases": ["ibk", "industrial bank of kuwait", "بنك الكويت الصناعي"]},
}


def extract_kuwait_iban(text: str | None) -> str | None:
    compact = re.sub(r"[^A-Za-z0-9]+", "", text or "").upper()
    match = re.search(r"KW\d{2}[A-Z]{4}[A-Z0-9]{22}", compact)
    return match.group(0) if match else None


def iban_mod97_valid(iban: str) -> bool:
    rearranged = iban[4:] + iban[:4]
    converted = ""
    for ch in rearranged:
        if ch.isdigit():
            converted += ch
        elif "A" <= ch <= "Z":
            converted += str(ord(ch) - 55)
        else:
            return False
    remainder = 0
    for ch in converted:
        remainder = (remainder * 10 + int(ch)) % 97
    return remainder == 1


def mentioned_kuwait_bank_codes(text: str | None) -> set[str]:
    normalized = normalize_text(text)
    compact = re.sub(r"[^a-z0-9]+", "", normalized)
    codes: set[str] = set()
    for code, info in KUWAIT_BANKS.items():
        if code.lower() in compact:
            codes.add(code)
            continue
        for alias in info["aliases"]:
            alias_norm = normalize_text(alias)
            if alias_norm and alias_norm in normalized:
                codes.add(code)
                break
    return codes


def validate_kuwait_bank_details(text: str | None) -> dict[str, Any]:
    iban = extract_kuwait_iban(text)
    if not iban:
        return {"ok": False, "error": "missing_or_invalid_kuwait_iban_format"}
    bank_code = iban[4:8]
    bank = KUWAIT_BANKS.get(bank_code)
    if not bank:
        return {"ok": False, "error": "unknown_kuwait_bank_code", "iban": iban, "bank_code": bank_code}
    if not iban_mod97_valid(iban):
        return {"ok": False, "error": "invalid_iban_checksum", "iban": iban, "bank_code": bank_code, "bank_name": bank["canonical"]}
    mentioned_codes = mentioned_kuwait_bank_codes(text)
    if not mentioned_codes:
        return {"ok": False, "error": "missing_bank_name", "iban": iban, "bank_code": bank_code, "bank_name": bank["canonical"]}
    if bank_code not in mentioned_codes:
        mentioned_names = [KUWAIT_BANKS[code]["canonical"] for code in sorted(mentioned_codes)]
        return {
            "ok": False,
            "error": "bank_name_mismatch",
            "iban": iban,
            "bank_code": bank_code,
            "bank_name": bank["canonical"],
            "mentioned_banks": mentioned_names,
        }
    return {"ok": True, "iban": iban, "bank_code": bank_code, "bank_name": bank["canonical"]}


def text_has_bank_detail_answer(text: str | None) -> bool:
    normalized = normalize_text(text)
    if text_has_iban(normalized):
        return True
    if is_onboarding_instruction_echo(normalized):
        return False
    return bool(
        re.search(r"\b(bank|iban|account|salary|kfh|nbk|gulf bank|بنك|ايبان|آيبان)\b", normalized)
        and re.search(r"\d", normalized)
    )


def normalized_name_tokens(value: str | None) -> set[str]:
    normalized = normalize_text(value)
    tokens = re.findall(r"[\w\u0600-\u06FF]+", normalized)
    return {token for token in tokens if len(token) >= 3 and not token.isdigit()}


def document_name_match(expected_name: str | None, document_name: str | None) -> dict[str, Any]:
    expected_tokens = normalized_name_tokens(expected_name)
    document_tokens = normalized_name_tokens(document_name)
    expected_compact = " ".join(sorted(expected_tokens))
    document_compact = " ".join(sorted(document_tokens))
    if not expected_tokens or not document_tokens:
        return {
            "status": "unverified",
            "match": False,
            "token_score": 0,
            "sequence_score": 0,
            "reason": "missing_employee_or_document_name",
        }
    overlap = expected_tokens & document_tokens
    token_score = len(overlap) / max(1, len(expected_tokens))
    sequence_score = SequenceMatcher(None, expected_compact, document_compact).ratio()
    matched = token_score >= 0.5 or sequence_score >= 0.72
    if matched:
        status = "matched"
    elif not overlap:
        status = "mismatch"
    else:
        status = "unverified"
    return {
        "status": status,
        "match": matched,
        "expected_name": expected_name,
        "document_name": document_name,
        "overlap_tokens": sorted(overlap),
        "token_score": round(token_score, 3),
        "sequence_score": round(sequence_score, 3),
    }


def media_data_uri(media: dict[str, Any] | None) -> str | None:
    if not isinstance(media, dict):
        return None
    media_path = str(media.get("path") or media.get("local_path") or media.get("source_path") or media.get("url") or "").strip()
    if not media_path or media_path.startswith(("http://", "https://", "data:")):
        return media_path if media_path.startswith("data:") else None
    path = Path(media_path)
    try:
        if not path.exists() or not path.is_file() or path.stat().st_size > 8 * 1024 * 1024:
            return None
        mime_type = str(media.get("type") or media.get("mime_type") or "").strip().lower()
        if "/" not in mime_type:
            mime_type = mimetypes.guess_type(path.name)[0] or "image/jpeg"
        encoded = base64.b64encode(path.read_bytes()).decode("ascii")
        return f"data:{mime_type};base64,{encoded}"
    except Exception:
        return None


def extract_model_text(parsed: dict[str, Any]) -> str:
    output_text = parsed.get("output_text")
    if isinstance(output_text, str) and output_text.strip():
        return output_text
    chunks: list[str] = []
    for item in parsed.get("output") or []:
        for content in item.get("content") or []:
            if isinstance(content, dict):
                text = content.get("text") or content.get("output_text")
                if isinstance(text, str):
                    chunks.append(text)
    if chunks:
        return "\n".join(chunks)
    message = ((parsed.get("choices") or [{}])[0].get("message") or {})
    content = message.get("content")
    return content if isinstance(content, str) else ""


