def parse_iso_date(value: Any) -> date | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    raw = raw.replace("/", "-")
    for fmt in ("%Y-%m-%d", "%d-%m-%Y", "%d-%m-%y", "%Y.%m.%d", "%d.%m.%Y"):
        try:
            parsed = datetime.strptime(raw, fmt).date()
            if parsed.year < 100:
                parsed = parsed.replace(year=parsed.year + 2000)
            return parsed
        except Exception:
            pass
    try:
        return datetime.fromisoformat(raw[:10]).date()
    except Exception:
        return None


def extract_compliance_document_metadata(
    *,
    document_type: str,
    text: str,
    media: dict[str, Any] | None,
    company_code: str | None = None,
    subject_key: str | None = None,
    channel: str = "shared",
) -> dict[str, Any] | None:
    """Shared omnichannel extraction. Identity delegates; contracts/education use Kuwait/GCC Mistral.

    Never calls GPT. Fields remain non-authoritative until HR confirms.
    """

    from kuwait_gcc_document_intelligence.intake import (
        canonical_document_type,
        extraction_for_receipt,
        is_shared_intake_type,
        shared_channel_extraction,
    )

    canon = canonical_document_type(document_type)
    from kuwait_gcc_document_intelligence.schemas import STORAGE_ONLY_TYPES as _STORAGE

    if not is_shared_intake_type(canon) and canon not in _STORAGE:
        return None
    result = shared_channel_extraction(
        document_type=canon,
        media=media,
        company_code=company_code,
        subject_key=subject_key,
        channel=channel,
        mode="extract",
        text=text,
    )
    return extraction_for_receipt(result)


def validate_onboarding_item_receipt(
    item_id: str | None,
    text: str,
    media: dict[str, Any] | None,
    *,
    company_code: str | None = None,
    subject_key: str | None = None,
) -> tuple[bool, str | None]:
    item = str(item_id or "").strip()
    if not item:
        return False, "missing_item"
    if item in MEDIA_REQUIRED_ONBOARDING_ITEMS:
        if not has_current_media_upload(media):
            return False, "missing_media"
        verification = verify_onboarding_media_item(
            item,
            text,
            media,
            company_code=company_code,
            subject_key=subject_key,
        )
        if not verification:
            return False, "media_unverified"
        try:
            confidence = float(verification.get("confidence", 0))
        except Exception:
            confidence = 0.0
        detected_item = str(verification.get("detected_item") or "").strip()
        if str(verification.get("extraction_status") or "") == "needs_review" and confidence < 0.65:
            return False, "needs_review"
        if verification.get("matches_expected_item") is True and detected_item == item and confidence >= 0.65:
            return True, None
        if detected_item == "instruction_screenshot":
            return False, "instruction_screenshot"
        return False, "wrong_media_item"
    if item == "bank_details" or onboarding_plaintext_bank_forbidden(item, text):
        # Wave 1 freeze: do not accept new plaintext bank/IBAN via onboarding.
        return False, "bank_via_ess_required"
    return True, None


def validate_onboarding_document_identity(
    *,
    employee: dict[str, Any],
    item_id: str,
    text: str,
    media: dict[str, Any] | None,
) -> tuple[bool, str | None, dict[str, Any] | None]:
    from kuwait_gcc_document_intelligence.intake import canonical_document_type

    canon = canonical_document_type(item_id)
    # Identity name-match gate remains for civil_id/passport only.
    if item_id not in IDENTITY_REQUIRED_ONBOARDING_ITEMS and canon not in {"education_cert", "employment_contract", "medical", "residence", "work_permit"}:
        return True, None, None
    extraction = extract_compliance_document_metadata(
        document_type=canon,
        text=text,
        media=media,
        company_code=employee.get("company_code"),
        subject_key=employee.get("employee_key"),
        channel="whatsapp_onboarding",
    )
    if canon in {"education_cert", "employment_contract", "medical", "residence", "work_permit"}:
        # Structure fields; do not require name match for these classes.
        if not isinstance(extraction, dict):
            return False, "needs_review", extraction
        status = str(extraction.get("extraction_status") or "").strip()
        if status == "needs_review":
            return False, "needs_review", extraction
        if status in {"extracted", "low_confidence", "mismatch", "storage_only"}:
            # mismatch still recorded for HR; accept receipt with proposal
            return True, None, extraction
        return False, "needs_review", extraction
    if item_id not in IDENTITY_REQUIRED_ONBOARDING_ITEMS:
        return True, None, extraction
    if not isinstance(extraction, dict):
        return False, "identity_unverified", extraction
    status = str(extraction.get("extraction_status") or "").strip()
    try:
        confidence = float(extraction.get("confidence", 0))
    except Exception:
        confidence = 0.0
    if status == "needs_review":
        return False, "needs_review", extraction
    if status not in {"extracted", "low_confidence"} or confidence < 0.55:
        return False, "identity_unverified", extraction
    identity = document_name_match(str(employee.get("name") or ""), str(extraction.get("full_name") or ""))
    extraction["identity_check"] = identity
    if identity.get("match") is True:
        return True, None, extraction
    if identity.get("status") == "mismatch":
        return False, "identity_mismatch", extraction
    return False, "identity_unverified", extraction


def pending_media_onboarding_items(employee_key: str) -> list[str]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT item_id
                FROM onboarding_items
                WHERE employee_key=%s
                  AND required IS TRUE
                  AND status IN ('missing','pending','requested')
                  AND item_id = ANY(%s)
                ORDER BY created_at ASC
                """,
                (employee_key, list(MEDIA_REQUIRED_ONBOARDING_ITEMS)),
            )
            return [str(row["item_id"]) for row in cur.fetchall()]


def detect_onboarding_reply_item(
    text: str,
    media: dict[str, Any] | None,
    employee_key: str,
    *,
    company_code: str | None = None,
) -> str | None:
    normalized = normalize_text(text)
    # Bank/IBAN answers are frozen out of onboarding plaintext collection (ESS only).
    if text_has_bank_detail_answer(normalized) or text_has_iban(normalized):
        return None
    if has_current_media_upload(media):
        allowed_items = pending_media_onboarding_items(employee_key)
        classification = classify_onboarding_media_upload(
            text,
            media,
            allowed_items,
            company_code=company_code,
            subject_key=employee_key,
        )
        if not classification:
            return None
        try:
            confidence = float(classification.get("confidence", 0))
        except Exception:
            confidence = 0.0
        detected_item = str(classification.get("detected_item") or "").strip()
        if detected_item == "bank_details":
            return None
        if detected_item in allowed_items and confidence >= 0.75:
            return detected_item
        return None
    return None


def looks_like_name_answer(text: str) -> bool:
    value = (text or "").strip()
    normalized = normalize_text(value)
    if not value or len(value) > 80:
        return False
    if normalized in {"hi", "hello", "hey", "ok", "yes", "no", "thanks", "thank you"}:
        return False
    if re.search(r"\b(already|sent|send|submitted|uploaded|cv|resume|application|bank|iban|civil|passport|photo|document|docs|id|account|shift|schedule)\b", normalized):
        return False
    words = [w for w in re.split(r"\s+", value) if w]
    return 2 <= len(words) <= 5 and any(ch.isalpha() for ch in value)


def update_employee_name_from_reply(cur: Any, employee: dict[str, Any], name: str) -> None:
    employee_key = employee["employee_key"]
    phone = employee.get("phone")
    raw_json = dict(employee.get("raw_json") or {})
    profile = dict(employee.get("profile") or {})
    raw_json["name"] = name
    profile["name"] = name
    cur.execute(
        """
        UPDATE employees
        SET name=%s, raw_json=%s, profile=%s, updated_at=now()
        WHERE employee_key=%s AND company_code=%s
        """,
        (name, Json(raw_json), Json(profile), employee_key, employee.get("company_code")),
    )
    if phone:
        cur.execute("UPDATE candidates SET name=%s WHERE phone=%s AND (name IS NULL OR name='' OR name=%s)", (name, phone, employee.get("name") or ""))


def mentioned_onboarding_item_id(text: str, next_item: dict[str, Any] | None = None) -> str | None:
    normalized = normalize_text(text)
    if re.search(r"\b(iban|bank|account)\b", normalized):
        return "bank_details"
    if re.search(r"\b(civil\s*id|civil|id card|بطاقة)\b", normalized):
        return "civil_id"
    if re.search(r"\bpassport\b", normalized):
        return "passport"
    if re.search(r"\b(personal\s+photo|photo|picture|selfie)\b", normalized):
        return "personal_photo"
    if re.search(r"\bmedical|fitness\b", normalized):
        return "medical"
    if re.search(r"\b(education|certificate|degree|diploma)\b", normalized):
        return "education_cert"
    if next_item and re.search(r"\b(it|this|that|same thing|already|again)\b", normalized):
        return str(next_item.get("item_id") or "")
    return None


def is_onboarding_item_status_or_objection(text: str) -> bool:
    normalized = normalize_text(text)
    if not normalized:
        return False
    return bool(
        re.search(r"\b(already|sent|send|submitted|uploaded|gave|provided|did|done|again|why|receive|received|have you|dont you|don't you)\b", normalized)
        and re.search(r"\b(iban|bank|account|civil|id|passport|photo|picture|medical|certificate|document|docs|it|this|that)\b", normalized)
    )


def onboarding_item_record(employee_key: str, item_id: str | None, *, company_code: str | None = None) -> dict[str, Any] | None:
    if not item_id:
        return None
    company = str(company_code or "").strip().upper() or None
    items = load_onboarding_items(employee_key=employee_key, company_code=company)
    for item in items:
        if str(item.get("item_id") or "") == str(item_id):
            return item
    return None


def onboarding_item_truth_reply(
    *,
    employee: dict[str, Any],
    text: str,
    next_item: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not is_onboarding_item_status_or_objection(text):
        return None
    item_id = mentioned_onboarding_item_id(text, next_item)
    item = onboarding_item_record(
        str(employee.get("employee_key") or ""),
        item_id,
        company_code=str(employee.get("company_code") or "").strip().upper() or None,
    )
    if not item:
        return None
    name = employee.get("name") or "there"
    label = item_display_label(item)
    status = str(item.get("status") or "").lower()
    if status in {"received", "complete", "completed", "verified"}:
        return {
            "reply": f"Yes {name}, I have your {label} marked as received. HR will review it.",
            "item_id": item_id,
            "status": status,
            "reason": "already_received",
        }
    if item_id == "bank_details":
        reply = (
            f"Bank and IBAN setup uses the encrypted Employee Self-Service bank workflow, {name}. "
            "I cannot collect bank details as plaintext in onboarding chat."
        )
    elif item_id in MEDIA_REQUIRED_ONBOARDING_ITEMS:
        reply = f"I do not see a verified {label} saved for you yet, {name}. Please resend a clear photo/file of your {label} so I can mark it received."
    else:
        reply = f"I do not see {label} marked as received yet, {name}. Please resend it here so I can verify it."
    return {
        "reply": reply,
        "item_id": item_id,
        "status": status,
        "reason": "not_verified_yet",
    }


def handle_employee_onboarding_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    employee = find_employee_by_phone(request.sender_phone)
    if not employee:
        return None
    if not company_has_module(employee.get("company_code"), "onboarding"):
        return {
            "reply": module_disabled_reply(employee.get("company_code"), "onboarding"),
            "updates": [],
            "employee_key": employee.get("employee_key"),
            "module_disabled": "onboarding",
        }
    text = (request.raw_text or "").strip()
    media = request.media or {}
    employee_key = employee["employee_key"]
    updates: list[str] = []
    received_item_ids: list[str] = []
    rejected_item_id: str | None = None
    rejected_reason: str | None = None
    storage_result: dict[str, Any] = {}
    accepted_extraction: dict[str, Any] | None = None
    next_item_before = find_next_required_onboarding_item(employee_key)
    planned_reply = plan_employee_onboarding_reply(
        employee=employee,
        text=text,
        media=media,
        next_item=next_item_before,
    )
    with db_connect() as conn:
        with conn.cursor() as cur:
            if planned_reply and planned_reply.get("reply_type") == "name" and not is_onboarding_instruction_echo(text):
                name_value = str(planned_reply.get("value") or text).strip()
                if looks_like_name_answer(name_value) and looks_like_name_answer(text):
                    update_employee_name_from_reply(cur, employee, name_value)
                    employee["name"] = name_value
                    updates.append("name")
            elif (not planned_reply or planned_reply.get("reply_type") != "onboarding_item") and looks_like_name_answer(text):
                update_employee_name_from_reply(cur, employee, text)
                employee["name"] = text
                updates.append("name")

            item_id = None
            value = text or str(media.get("path") or media.get("url") or "received")
            if planned_reply and planned_reply.get("reply_type") == "onboarding_item":
                candidate_item_id = str(planned_reply.get("item_id") or "")
                valid_receipt, receipt_reason = validate_onboarding_item_receipt(
                    candidate_item_id,
                    text,
                    media,
                    company_code=employee.get("company_code"),
                    subject_key=employee_key,
                )
                if valid_receipt:
                    identity_ok, identity_reason, identity_extraction = validate_onboarding_document_identity(
                        employee=employee,
                        item_id=candidate_item_id,
                        text=text,
                        media=media,
                    )
                    if identity_ok:
                        item_id = candidate_item_id
                        value = str(planned_reply.get("value") or value)
                        accepted_extraction = identity_extraction
                    else:
                        rejected_item_id = candidate_item_id
                        rejected_reason = identity_reason
                else:
                    rejected_item_id = candidate_item_id
                    rejected_reason = receipt_reason
            if not item_id:
                candidate_item_id = detect_onboarding_reply_item(
                    text,
                    media,
                    employee_key,
                    company_code=employee.get("company_code"),
                )
                valid_receipt, receipt_reason = validate_onboarding_item_receipt(
                    candidate_item_id,
                    text,
                    media,
                    company_code=employee.get("company_code"),
                    subject_key=employee_key,
                )
                if valid_receipt:
                    identity_ok, identity_reason, identity_extraction = validate_onboarding_document_identity(
                        employee=employee,
                        item_id=str(candidate_item_id or ""),
                        text=text,
                        media=media,
                    )
                    if identity_ok:
                        item_id = candidate_item_id
                        accepted_extraction = identity_extraction
                    else:
                        rejected_item_id = candidate_item_id
                        rejected_reason = identity_reason
                elif candidate_item_id:
                    rejected_item_id = candidate_item_id
                    rejected_reason = receipt_reason
                elif has_current_media_upload(media):
                    rejected_item_id = "uploaded_media"
                    rejected_reason = "unrecognized_media"
            if item_id:
                storage_result = store_onboarding_document(employee=employee, item_id=item_id, media=media)
                if not storage_result.get("ok"):
                    rejected_item_id = item_id
                    rejected_reason = "storage_failed"
                    item_id = None
                if item_id == "bank_details" or onboarding_plaintext_bank_forbidden(item_id, value):
                    # Fail closed — never persist new plaintext IBAN/bank via onboarding.
                    rejected_item_id = item_id or "bank_details"
                    rejected_reason = "bank_via_ess_required"
                    item_id = None
            if item_id:
                cur.execute(
                    """
                    UPDATE onboarding_items
                    SET status='received',
                        value=%s,
                        local_path=COALESCE(%s, local_path),
                        drive_file_id=COALESCE(%s, drive_file_id),
                        drive_url=COALESCE(%s, drive_url),
                        storage_provider=%s,
                        storage_object_key=%s,
                        external_file_id=%s,
                        storage_url=%s,
                        content_sha256=%s,
                        mime_type=%s,
                        storage_status=%s,
                        storage_error=%s,
                        stored_at=CASE WHEN %s IS NOT NULL THEN now() ELSE stored_at END,
                        raw_json=jsonb_set(
                            jsonb_set(
                                jsonb_set(COALESCE(raw_json,'{}'::jsonb), '{received_at}', to_jsonb(%s::text), true),
                                '{validation_status}',
                                to_jsonb(%s::text),
                                true
                            ),
                            '{validation}',
                            %s::jsonb,
                            true
                        ),
                        updated_at=now()
                    WHERE employee_key=%s AND item_id=%s
                    """,
                    (
                        value,
                        media.get("path"),
                        storage_result.get("drive_file_id"),
                        storage_result.get("drive_url"),
                        storage_result.get("provider"),
                        storage_result.get("storage_object_key"),
                        storage_result.get("external_file_id"),
                        storage_result.get("storage_url"),
                        storage_result.get("content_sha256"),
                        storage_result.get("mime_type"),
                        storage_result.get("storage_status"),
                        storage_result.get("storage_error"),
                        storage_result.get("provider"),
                        now_iso(),
                        "not_required",
                        json.dumps({}, ensure_ascii=False),
                        employee_key,
                        item_id,
                    ),
                )
                record_employee_document_receipt(cur, employee=employee, item_id=item_id, value=value, media=media, storage_result=storage_result, extraction=accepted_extraction)
                updates.append(item_id)
                received_item_ids.append(item_id)
            if updates:
                recompute_employee_onboarding_counts(cur, employee_key)
        conn.commit()
    company_for_read = str(employee.get("company_code") or "").strip().upper() or None
    next_item = find_next_required_onboarding_item(employee_key, company_code=company_for_read)
    hr_notification: dict[str, Any] = {}
    if received_item_ids:
        if next_item:
            hr_notification = notify_hr_onboarding_received(employee=employee, item_id=received_item_ids[-1], account_id=request.account_id)
        else:
            hr_notification = notify_hr_onboarding_completed(employee=employee, account_id=request.account_id)
    name = employee.get("name") or "there"
    truth_reply = onboarding_item_truth_reply(employee=employee, text=text, next_item=next_item_before)
    if updates:
        if next_item:
            reply = f"Got it, {name}. Next, please send {next_item.get('label') or next_item.get('item_id')}."
        else:
            reply = f"Got it, {name}. I received all required onboarding items. HR will review them."
    elif truth_reply:
        reply = truth_reply["reply"]
    elif rejected_item_id and rejected_reason == "missing_media":
        label = (next_item_before or {}).get("label") if (next_item_before or {}).get("item_id") == rejected_item_id else rejected_item_id
        reply = f"Please send the actual {label or rejected_item_id} file/photo so I can mark it received."
    elif rejected_item_id and rejected_reason in {"media_unverified", "instruction_screenshot", "wrong_media_item"}:
        label = (next_item_before or {}).get("label") if (next_item_before or {}).get("item_id") == rejected_item_id else rejected_item_id
        reply = f"Please send a clear photo/file of {label or rejected_item_id}. I cannot mark that upload as received."
    elif rejected_item_id and rejected_reason == "bank_via_ess_required":
        reply = (
            "Bank and IBAN must be set through the encrypted Employee Self-Service bank workflow. "
            "I cannot collect bank details as plaintext in onboarding."
        )
    elif rejected_item_id and rejected_reason == "missing_bank_details":
        reply = (
            "Bank and IBAN must be set through the encrypted Employee Self-Service bank workflow. "
            "I cannot collect bank details as plaintext in onboarding."
        )
    elif rejected_item_id and rejected_reason in {"missing_or_invalid_kuwait_iban_format", "unknown_kuwait_bank_code", "invalid_iban_checksum", "missing_bank_name", "bank_name_mismatch"}:
        reply = (
            "Bank and IBAN must be set through the encrypted Employee Self-Service bank workflow. "
            "I cannot collect or verify bank details as plaintext in onboarding."
        )
    elif rejected_item_id and rejected_reason == "unrecognized_media":
        reply = "I cannot mark that image as an onboarding document. Please send a clear Civil ID, passport photo page, or personal photo."
    elif rejected_item_id and rejected_reason == "identity_mismatch":
        label = item_display_label(rejected_item_id)
        reply = f"I can see this is a {label}, but the name on it does not match {name}. Please send your own {label}."
    elif rejected_item_id and rejected_reason == "identity_unverified":
        label = item_display_label(rejected_item_id)
        reply = f"I can see this may be a {label}, but I cannot clearly confirm the name matches {name}. Please send a clearer photo of your own {label}."
    elif rejected_item_id and rejected_reason == "storage_failed":
        reply = "I received the file, but I could not archive it safely yet. HR will review it."
    else:
        if next_item:
            reply = f"Hi {name}. Please send {next_item.get('label') or next_item.get('item_id')} so HR can continue your onboarding."
        else:
            reply = f"Hi {name}. HR has your onboarding items and will review them."
    return {"reply": reply, "updates": updates, "employee_key": employee_key, "hr_notification": hr_notification, "planned_reply": planned_reply, "storage": storage_result, "truth_reply": truth_reply, "rejected_item_id": rejected_item_id, "rejected_reason": rejected_reason}


def refresh_conversation_link_from_inbound(request: WhatsAppTurnRequest) -> dict[str, Any]:
    phone = digits(request.sender_phone)
    conversation_id = str(request.conversation_id or "").strip()
    account_id = request.account_id or "default"
    if isinstance(request.metadata, dict) and request.metadata.get("smoke"):
        return {"refreshed": False, "reason": "smoke_turn"}
    if not phone or not conversation_id or is_hr_phone(phone):
        return {"refreshed": False, "reason": "not_candidate_or_missing_identity"}
    scoped_company = request_company_code(request, default=None)
    if not scoped_company:
        return {"refreshed": False, "reason": "tenant_scope_required"}

    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT e.employee_key, e.company_code, e.app_key, e.name, e.phone,
                       a.position_code, a.raw_json AS application_json
                FROM employees e
                LEFT JOIN applications a ON a.app_key = e.app_key
                WHERE e.phone=%s AND e.company_code=%s
                ORDER BY e.updated_at DESC
                LIMIT 1
                """,
                (phone, scoped_company),
            )
            subject = cur.fetchone()
            if not subject:
                cur.execute(
                    """
                    SELECT NULL::text AS employee_key, a.company_code, a.app_key,
                           COALESCE(NULLIF(c.name, ''), a.raw_json->>'candidate_name', a.raw_json->>'name') AS name,
                           a.phone, a.position_code, a.raw_json AS application_json
                    FROM applications a
                    LEFT JOIN candidates c ON c.phone = a.phone
                    WHERE a.phone=%s AND a.company_code=%s
                    ORDER BY
                      CASE WHEN a.status IN ('hired','shortlisted') THEN 0 ELSE 1 END,
                      a.updated_at DESC NULLS LAST,
                      a.ingested_at DESC NULLS LAST
                    LIMIT 1
                    """,
                    (phone, scoped_company),
                )
                subject = cur.fetchone()
            if not subject:
                return {"refreshed": False, "reason": "unknown_phone", "phone": phone}

            subject = dict(subject)
            app_json = subject.get("application_json") or {}
            company_code = subject.get("company_code") or app_json.get("company_code")
            if not company_code or str(company_code).upper() != str(scoped_company).upper():
                return {"refreshed": False, "reason": "tenant_scope_mismatch"}
            position_code = subject.get("position_code") or app_json.get("position_code")
            apply_code = app_json.get("apply_code") or (f"APPLY-{company_code}-{position_code}" if position_code else None)
            raw_json = {
                "account_id": account_id,
                "conversation_id": conversation_id,
                "company_code": company_code,
                "position_code": position_code,
                "apply_code": apply_code,
                "phone": phone,
                "source": "inbound_refresh",
                "updated_at": now_iso(),
            }
            cur.execute(
                """
                UPDATE conversation_links
                SET conversation_id=%s,
                    company_code=COALESCE(%s, company_code),
                    position_code=COALESCE(%s, position_code),
                    apply_code=COALESCE(%s, apply_code),
                    raw_json=%s,
                    updated_at=now()
                WHERE phone=%s AND account_id=%s
                """,
                (conversation_id, company_code, position_code, apply_code, Json(raw_json), phone, account_id),
            )
            updated = cur.rowcount
            if updated == 0:
                cur.execute(
                    """
                    INSERT INTO conversation_links
                    (link_key, phone, account_id, conversation_id, company_code, position_code, apply_code, raw_json, updated_at)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,now())
                    """,
                    (
                        f"{account_id}:{conversation_id}",
                        phone,
                        account_id,
                        conversation_id,
                        company_code,
                        position_code,
                        apply_code,
                        Json(raw_json),
                    ),
                )
                updated = 1
        conn.commit()
    record_octopus_conversation_health(
        phone=phone,
        account_id=account_id,
        conversation_id=conversation_id,
        source="inbound_refresh",
        status="healthy",
        payload={"company_code": company_code, "position_code": position_code, "apply_code": apply_code},
        seen=True,
    )
    return {
        "refreshed": bool(updated),
        "phone": phone,
        "conversation_id": conversation_id,
        "account_id": account_id,
        "updated_rows": updated,
    }


def find_conversation_link(phone: str, account_id: str | None = None) -> dict[str, Any] | None:
    with db_connect() as conn:
        with conn.cursor() as cur:
            if account_id:
                cur.execute(
                    """
                    SELECT * FROM conversation_links
                    WHERE phone=%s AND account_id=%s
                    ORDER BY updated_at DESC
                    LIMIT 1
                    """,
                    (digits(phone), account_id),
                )
            else:
                cur.execute(
                    """
                    SELECT * FROM conversation_links
                    WHERE phone=%s
                    ORDER BY updated_at DESC
                    LIMIT 1
                    """,
                    (digits(phone),),
                )
            row = cur.fetchone()
            return dict(row) if row else None


def octopus_health_status_for_error(error: str | None) -> str:
    if error == "conversation_closed":
        return "closed"
    if error == "conversation_inactive":
        return "stale"
    if error:
        return "rejected"
    return "unknown"


def record_octopus_conversation_health(
    *,
    phone: str | None,
    account_id: str | None,
    conversation_id: str | None,
    source: str,
    status: str = "unknown",
    error: str | None = None,
    payload: dict[str, Any] | None = None,
    seen: bool = False,
    success: bool = False,
    failure: bool = False,
) -> None:
    phone_digits = digits(phone)
    conversation = str(conversation_id or "").strip()
    if not phone_digits or not conversation:
        return
    account = account_id or "default"
    now = now_utc()
    raw_json = {
        "source": source,
        "status": status,
        "error": error,
        "updated_at": now_iso(),
        "payload": json_safe(payload or {}),
    }
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO octopus_conversation_health
                (account_id, phone, conversation_id, source, status, last_seen_at, last_success_at,
                 last_failure_at, last_error, success_count, failure_count, raw_json, updated_at)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,now())
                ON CONFLICT (account_id, phone, conversation_id) DO UPDATE SET
                  source=EXCLUDED.source,
                  status=EXCLUDED.status,
                  last_seen_at=COALESCE(EXCLUDED.last_seen_at, octopus_conversation_health.last_seen_at),
                  last_success_at=COALESCE(EXCLUDED.last_success_at, octopus_conversation_health.last_success_at),
                  last_failure_at=COALESCE(EXCLUDED.last_failure_at, octopus_conversation_health.last_failure_at),
                  last_error=CASE WHEN EXCLUDED.status='healthy' THEN NULL ELSE COALESCE(EXCLUDED.last_error, octopus_conversation_health.last_error) END,
                  success_count=octopus_conversation_health.success_count + EXCLUDED.success_count,
                  failure_count=octopus_conversation_health.failure_count + EXCLUDED.failure_count,
                  raw_json=octopus_conversation_health.raw_json || EXCLUDED.raw_json,
                  updated_at=now()
                """,
                (
                    account,
                    phone_digits,
                    conversation,
                    source,
                    status,
                    now if seen else None,
                    now if success else None,
                    now if failure else None,
                    error,
                    1 if success else 0,
                    1 if failure else 0,
                    Json(raw_json),
                ),
            )
        conn.commit()


def healthy_octopus_conversation_ids(phone: str, account_id: str | None = None, limit: int = 5) -> list[str]:
    phone_digits = digits(phone)
    if not phone_digits:
        return []
    params: list[Any] = [phone_digits]
    account_filter = ""
    if account_id:
        account_filter = "AND account_id=%s"
        params.append(account_id)
    params.append(max(1, min(limit, 10)))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT conversation_id
                FROM octopus_conversation_health
                WHERE phone=%s
                  {account_filter}
                  AND status IN ('healthy', 'unknown')
                ORDER BY
                  CASE status WHEN 'healthy' THEN 0 ELSE 1 END,
                  COALESCE(last_success_at, last_seen_at, updated_at) DESC,
                  failure_count ASC
                LIMIT %s
                """,
                params,
            )
            return [str(row.get("conversation_id")) for row in cur.fetchall() if row.get("conversation_id")]


def unhealthy_octopus_conversation_ids(phone: str, account_id: str | None = None) -> set[str]:
    phone_digits = digits(phone)
    if not phone_digits:
        return set()
    params: list[Any] = [phone_digits]
    account_filter = ""
    if account_id:
        account_filter = "AND account_id=%s"
        params.append(account_id)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT conversation_id
                FROM octopus_conversation_health
                WHERE phone=%s
                  {account_filter}
                  AND status IN ('closed', 'stale', 'rejected')
                """,
                params,
            )
            return {str(row.get("conversation_id")) for row in cur.fetchall() if row.get("conversation_id")}


def recent_successful_conversation_ids(phone: str, account_id: str | None = None, limit: int = 5) -> list[str]:
    phone_digits = digits(phone)
    if not phone_digits:
        return []
    params: list[Any] = [phone_digits]
    account_filter = ""
    if account_id:
        account_filter = "AND account_id=%s"
        params.append(account_id)
    params.append(max(1, min(limit, 10)))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT target_conversation_id, MAX(created_at) AS last_sent_at
                FROM outbound_delivery_events
                WHERE target_phone=%s
                  {account_filter}
                  AND status='sent'
                  AND target_conversation_id IS NOT NULL
                GROUP BY target_conversation_id
                ORDER BY last_sent_at DESC
                LIMIT %s
                """,
                params,
            )
            return [str(row.get("target_conversation_id")) for row in cur.fetchall() if row.get("target_conversation_id")]


def update_conversation_link_id(phone: str, account_id: str | None, conversation_id: str) -> None:
    phone_digits = digits(phone)
    if not phone_digits or not conversation_id:
        return
    account = account_id or "default"
    raw_json = {
        "account_id": account,
        "conversation_id": str(conversation_id),
        "phone": phone_digits,
        "source": "successful_outbound_refresh",
        "updated_at": now_iso(),
    }
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE conversation_links
                SET conversation_id=%s, raw_json=COALESCE(raw_json, '{}'::jsonb) || %s::jsonb, updated_at=now()
                WHERE phone=%s AND account_id=%s
                """,
                (str(conversation_id), Json(raw_json), phone_digits, account),
            )
            if cur.rowcount == 0:
                cur.execute(
                    """
                    INSERT INTO conversation_links (link_key, phone, account_id, conversation_id, raw_json, updated_at)
                    VALUES (%s,%s,%s,%s,%s,now())
                    """,
                    (f"{account}:outbound:{phone_digits}", phone_digits, account, str(conversation_id), Json(raw_json)),
                )
        conn.commit()
    record_octopus_conversation_health(
        phone=phone_digits,
        account_id=account,
        conversation_id=conversation_id,
        source="successful_outbound_refresh",
        status="healthy",
        success=True,
    )


def outbound_conversation_candidates(phone: str, account_id: str | None = None) -> list[str]:
    candidates: list[str] = []
    candidates.extend(healthy_octopus_conversation_ids(phone, account_id))
    candidates.extend(recent_successful_conversation_ids(phone, account_id))
    link = find_conversation_link(phone, account_id)
    if link and link.get("conversation_id"):
        candidates.append(str(link.get("conversation_id")))
    unhealthy = unhealthy_octopus_conversation_ids(phone, account_id)
    seen: set[str] = set()
    out: list[str] = []
    for candidate in candidates:
        text = str(candidate or "").strip()
        if text in unhealthy:
            continue
        if text and text not in seen:
            seen.add(text)
            out.append(text)
    return out


def unique_conversation_candidates(candidates: list[Any]) -> list[str]:
    seen: set[str] = set()
    out: list[str] = []
    for candidate in candidates:
        text = str(candidate or "").strip()
        if not text or text in seen:
            continue
        seen.add(text)
        out.append(text)
    return out


def candidate_contact(app: dict[str, Any]) -> dict[str, str | None]:
    return {
        "phone": digits(app.get("phone")),
        "name": app.get("candidate_name") or app.get("name"),
        "email": app.get("candidate_email") or app.get("email"),
        "position_title": app.get("position_title") or app.get("position_code"),
    }


def run_workspace_tool(
    args: list[str],
    timeout: int = 60,
) -> dict[str, Any]:
    # Workspace tools historically default to the production env file and load
    # it with ``setdefault``. Always replace the child environment from the
    # already-validated backend binding; ambient inheritance is forbidden.
    binding = runtime_binding()
    tool_env = binding.child_environment(os.environ)
    proc = subprocess.run(
        args,
        cwd=WORKSPACE,
        text=True,
        capture_output=True,
        timeout=timeout,
        env=tool_env,
    )
    output = (proc.stdout or "").strip()
    parsed: Any = None
    if output:
        try:
            parsed = json.loads(output)
        except Exception:
            parsed = output
    return {
        "ok": proc.returncode == 0,
        "returncode": proc.returncode,
        "stdout": output[-2000:],
        "stderr": (proc.stderr or "")[-2000:],
        "json": parsed,
    }


def run_gog(args: list[str], timeout: int = 60) -> dict[str, Any]:
    env_vars = os.environ.copy()
    env_vars.update(openclaw_env())
    proc = subprocess.run(["gog", *args, "--json"], text=True, capture_output=True, timeout=timeout, env=env_vars)
    output = (proc.stdout or "").strip()
    parsed: Any = None
    if output:
        try:
            parsed = json.loads(output)
        except Exception:
            parsed = output
    return {
        "ok": proc.returncode == 0,
        "returncode": proc.returncode,
        "stdout": output[-2000:],
        "stderr": (proc.stderr or "")[-2000:],
        "json": parsed,
    }


def valid_whatsapp_recipient(phone: Any) -> bool:
    normalized = digits(phone)
    return bool(re.fullmatch(r"\d{8,15}", normalized))


def invalid_whatsapp_recipient_result(
    *,
    account_id: str | None,
    phone: Any,
    text: str,
    subject_type: str | None,
    subject_key: str | None,
    message_kind: str,
    channel: str = "octopus",
    company_code: str | None = None,
) -> dict[str, Any]:
    result = {
        "ok": False,
        "error": "invalid_recipient",
        "phone": digits(phone),
        "dry_run": delivery_is_dry_run(),
    }
    record_outbound_delivery_event(
        account_id=account_id,
        target_phone=str(phone or ""),
        target_conversation_id=None,
        status="failed",
        message_text=text,
        last_error="invalid_recipient",
        payload={"send_result": result, "recipient_validation": "failed"},
        subject_type=subject_type,
        subject_key=subject_key,
        message_kind=message_kind,
        channel=channel,
        company_code=company_code,
    )
    return result


def send_octopus_whatsapp(
    *,
    account_id: str | None,
    phone: str,
    text: str,
    subject_type: str | None = None,
    subject_key: str | None = None,
    message_kind: str = "text",
    company_code: str | None = None,
    audience: str | None = None,
    force_live: bool = False,
    audit_text: str | None = None,
) -> dict[str, Any]:
    # Optional company_code enables Phase 7D account selection. When omitted (all
    # legacy callers) or when WATHEFNI_COMPANY_CHANNEL_ACCOUNTS is OFF, routing is
    # unchanged: use the caller-supplied account_id / shared default.
    # force_live: Stage B canary may override staging dry_run for allowlisted
    # preview delivery so preview_sent_at reflects a real Octopus accept.
    persisted_message_text = text if audit_text is None else str(audit_text)
    def audit_payload(result: dict[str, Any], **extra: Any) -> dict[str, Any]:
        if audit_text is None:
            return {"send_result": result, **extra}
        safe_keys = {
            "ok",
            "dry_run",
            "status",
            "error",
            "channel",
            "conversation_id",
            "event_id",
            "outbound_event_id",
            "external_message_id",
            "provider_message_id",
            "simulated",
        }
        safe_result = {key: result.get(key) for key in safe_keys if key in result}
        return {
            "send_result": safe_result,
            "sensitive_request_redacted": True,
            **extra,
        }
    if not valid_whatsapp_recipient(phone):
        return invalid_whatsapp_recipient_result(
            account_id=account_id,
            phone=phone,
            text=persisted_message_text,
            subject_type=subject_type,
            subject_key=subject_key,
            message_kind=message_kind,
            company_code=company_code,
        )
    route_meta: dict[str, Any] | None = None
    if company_code is not None:
        route_meta = resolve_company_outbound_whatsapp_route(
            company_code=company_code,
            audience=audience,
            shared_account_id=account_id or _channel_account_routing.SHARED_ACCOUNT_ID,
        )
        account_id = route_meta.get("account_id") or account_id or _channel_account_routing.SHARED_ACCOUNT_ID
    if delivery_is_dry_run() and not force_live:
        result = {
            "ok": True,
            "dry_run": True,
            "status": 200,
            "phone": digits(phone),
            "simulated": True,
            "account_id": account_id or _channel_account_routing.SHARED_ACCOUNT_ID,
        }
        if route_meta is not None:
            result["channel_route"] = route_meta
        record_outbound_delivery_event(
            account_id=account_id,
            target_phone=phone,
            target_conversation_id=None,
            status="dry_run",
            message_text=persisted_message_text,
            last_error=None,
            payload=audit_payload(result, dry_run=True, channel_route=route_meta),
            subject_type=subject_type,
            subject_key=subject_key,
            message_kind=message_kind,
            company_code=company_code,
        )
        return result
    channel = octopus_channel_config()
    account_cfg = ((channel.get("accounts") or {}).get(account_id or "default") or {})
    base_url = account_cfg.get("baseUrl") or channel.get("baseUrl") or "https://app.ai-octopus.com"
    token = account_cfg.get("bearerToken") or channel.get("bearerToken")
    if not token:
        return {"ok": False, "error": "missing_ai_octopus_bearer_token"}
    conversation_ids = outbound_conversation_candidates(phone, account_id)
    if not conversation_ids:
        unhealthy_ids = sorted(unhealthy_octopus_conversation_ids(phone, account_id))
        error = "no_usable_conversation_id" if unhealthy_ids else "missing_candidate_conversation_id"
        result = {"ok": False, "error": error, "phone": digits(phone), "unhealthy_conversation_ids": unhealthy_ids}
        record_outbound_delivery_event(
            account_id=account_id,
            target_phone=phone,
            target_conversation_id=None,
            status="failed",
            message_text=persisted_message_text,
            last_error=error,
            payload=audit_payload(result),
            subject_type=subject_type,
            subject_key=subject_key,
            message_kind=message_kind,
            company_code=company_code,
        )
        return result

    last_result: dict[str, Any] | None = None
    retryable_errors = {"conversation_inactive"}
    for conversation_id in conversation_ids:
        payload = {
            "messaging_product": "whatsapp",
            "conversation_id": int(conversation_id) if str(conversation_id).isdigit() else str(conversation_id),
            "to": digits(phone),
            "type": "text",
            "recipient_type": "individual",
            "text": {"body": text},
        }
        req = urllib.request.Request(
            f"{base_url.rstrip('/')}/client/conversation/reply",
            data=json.dumps(payload).encode("utf-8"),
            headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                body = resp.read().decode("utf-8", errors="replace")
                try:
                    parsed = json.loads(body)
                except Exception:
                    parsed = body
                api_ok = 200 <= resp.status < 300 and not (isinstance(parsed, dict) and parsed.get("success") is False)
                error = None
                if not api_ok:
                    raw_error = parsed.get("errors", {}).get("message") if isinstance(parsed, dict) else None
                    if raw_error == "Conversation is closed":
                        error = "conversation_closed"
                    elif raw_error == "Invalid conversation_id provided":
                        error = "conversation_inactive"
                    else:
                        error = "ai_octopus_send_rejected"
                result = {
                    "ok": api_ok,
                    "status": resp.status,
                    "json": parsed,
                    "conversation_id": conversation_id,
                    "error": error,
                }
                record_outbound_delivery_event(
                    account_id=account_id,
                    target_phone=phone,
                    target_conversation_id=str(conversation_id),
                    status="sent" if api_ok else "failed",
                    message_text=persisted_message_text,
                    last_error=error,
                    payload=audit_payload(result),
                    subject_type=subject_type,
                    subject_key=subject_key,
                    message_kind=message_kind,
                    company_code=company_code,
                )
                if api_ok:
                    update_conversation_link_id(phone, account_id, str(conversation_id))
                    return result
                record_octopus_conversation_health(
                    phone=phone,
                    account_id=account_id,
                    conversation_id=str(conversation_id),
                    source="outbound_failure",
                    status=octopus_health_status_for_error(error),
                    error=error,
                    payload=audit_payload(result),
                    failure=True,
                )
                last_result = result
                if error not in retryable_errors:
                    return result
                continue
        except urllib.error.HTTPError as exc:
            body = exc.read().decode("utf-8", errors="replace")
            result = {"ok": False, "status": exc.code, "error": body[-1000:], "conversation_id": conversation_id}
            record_octopus_conversation_health(
                phone=phone,
                account_id=account_id,
                conversation_id=str(conversation_id),
                source="outbound_http_error",
                status="rejected",
                error=result["error"],
                payload=audit_payload(result),
                failure=True,
            )
            record_outbound_delivery_event(
                account_id=account_id,
                target_phone=phone,
                target_conversation_id=str(conversation_id),
                status="failed",
                message_text=persisted_message_text,
                last_error=result["error"],
                payload=audit_payload(result),
                subject_type=subject_type,
                subject_key=subject_key,
                message_kind=message_kind,
                company_code=company_code,
            )
            last_result = result
            return result
        except Exception as exc:
            result = {"ok": False, "error": str(exc), "conversation_id": conversation_id}
            record_outbound_delivery_event(
                account_id=account_id,
                target_phone=phone,
                target_conversation_id=str(conversation_id),
                status="failed",
                message_text=persisted_message_text,
                last_error=result["error"],
                payload=audit_payload(result),
                subject_type=subject_type,
                subject_key=subject_key,
                company_code=company_code,
            )
            last_result = result
            return result
    if last_result is not None:
        return last_result
    result = {"ok": False, "error": "no_usable_conversation_id", "phone": digits(phone), "conversation_ids": conversation_ids}
    record_outbound_delivery_event(
        account_id=account_id,
        target_phone=phone,
        target_conversation_id=None,
        status="failed",
        message_text=persisted_message_text,
        last_error=result["error"],
        payload=audit_payload(result),
        subject_type=subject_type,
        subject_key=subject_key,
        message_kind=message_kind,
        company_code=company_code,
    )
    return result


def send_company_whatsapp_message(
    company_code: str,
    phone: str,
    text: str,
    *,
    account_id: str | None = None,
    subject_key: str | None = None,
    message_kind: str = "text",
    metadata: dict[str, Any] | None = None,
    audit_text: str | None = None,
) -> dict[str, Any]:
    app_key = str(subject_key or "").strip()
    company = str(company_code or "").strip().upper()
    if app_key and company:
        application = find_application_by_key(app_key, company_code=company)
        try:
            assert_application_communication_allowed(application, kind="whatsapp" if message_kind != "employment_offer" else "offer", expected_company_code=company)  # HELD_COMMUNICATION_AUTHORITY_STAGING_PATCH
        except CandidateCommunicationAuthorityError as exc:
            return {**exc.as_result(), "send": {"ok": False, "error": exc.code}}
    result = send_octopus_whatsapp(
        account_id=account_id,
        phone=phone,
        text=text,
        subject_type="candidate",
        subject_key=subject_key,
        message_kind=message_kind,
        company_code=company_code,
        audience="candidate",
        audit_text=audit_text,
    )
    if metadata:
        result["metadata"] = json_safe(metadata)
    return result


def octopus_send_template(
    *,
    account_id: str | None,
    phone: str,
    template_key: str,
    locale: str = "en",
    variables: dict[str, Any] | None = None,
    fallback_text: str | None = None,
    subject_type: str | None = None,
    subject_key: str | None = None,
    message_kind: str = "template",
    company_code: str | None = None,
) -> dict[str, Any]:
    """Provider-abstracted WhatsApp approved-template (HSM) send.

    Wathefni -> Outbound Delivery Layer -> Octopus -> 360dialog. The business
    flows never talk to Meta/360dialog directly; they pass a Wathefni template
    *key* and we resolve the approved provider template via message_template_map.

    Until a key is mapped + approved (and WATHEFNI_OUTBOUND_TEMPLATES is on) this
    returns a short reason ("template_disabled" / "template_unmapped" /
    "template_provider_unconfigured") so the layer falls through to email / HR
    task. It never silently succeeds.
    """
    if not valid_whatsapp_recipient(phone):
        return invalid_whatsapp_recipient_result(
            account_id=account_id,
            phone=phone,
            text=fallback_text or f"[template:{template_key}]",
            subject_type=subject_type,
            subject_key=subject_key,
            message_kind=message_kind,
            channel="whatsapp_template",
            company_code=company_code,
        )
    variables = variables or {}
    if not outbound_templates_enabled():
        return {"ok": False, "error": "template_disabled", "template_key": template_key}

    mapping = lookup_template_mapping(template_key, locale=locale, company_code=company_code)
    if not mapping or str(mapping.get("status") or "").lower() != "approved":
        return {"ok": False, "error": "template_unmapped", "template_key": template_key}

    provider_name = mapping.get("provider_template_name")
    if delivery_is_dry_run():
        result = {
            "ok": True,
            "dry_run": True,
            "channel": "whatsapp_template",
            "template_key": template_key,
            "provider_template_name": provider_name,
            "phone": digits(phone),
            "simulated": True,
        }
        record_outbound_delivery_event(
            account_id=account_id,
            target_phone=phone,
            target_conversation_id=None,
            status="dry_run",
            message_text=fallback_text or f"[template:{template_key}]",
            last_error=None,
            payload={"send_result": result, "dry_run": True, "template_key": template_key},
            subject_type=subject_type,
            subject_key=subject_key,
            channel="whatsapp_template",
            message_kind=message_kind,
            company_code=company_code,
        )
        return result

    # Live template send path. The concrete Octopus template endpoint contract is
    # not finalised yet (Phase F), so when it is unconfigured we report a clear
    # reason rather than guessing an API shape. The layer then falls through.
    channel = octopus_channel_config()
    account_cfg = ((channel.get("accounts") or {}).get(account_id or "default") or {})
    template_url = account_cfg.get("templateUrl") or channel.get("templateUrl")
    token = account_cfg.get("bearerToken") or channel.get("bearerToken")
    if not (template_url and token):
        return {"ok": False, "error": "template_provider_unconfigured", "template_key": template_key}

    payload = {
        "messaging_product": "whatsapp",
        "to": digits(phone),
        "type": "template",
        "template": {
            "name": provider_name,
            "language": {"code": mapping.get("provider_language") or locale},
            "variables": variables,
        },
    }
    if mapping.get("provider_namespace"):
        payload["template"]["namespace"] = mapping["provider_namespace"]
    req = urllib.request.Request(
        template_url,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            body = resp.read().decode("utf-8", errors="replace")
            try:
                parsed = json.loads(body)
            except Exception:
                parsed = body
            api_ok = 200 <= resp.status < 300 and not (isinstance(parsed, dict) and parsed.get("success") is False)
            error = None if api_ok else "template_send_rejected"
            result = {"ok": api_ok, "status": resp.status, "json": parsed, "channel": "whatsapp_template", "error": error, "template_key": template_key}
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")[-500:]
        result = {"ok": False, "status": exc.code, "error": f"template_http_{exc.code}", "detail": detail, "template_key": template_key}
    except Exception as exc:
        result = {"ok": False, "error": f"template_error:{type(exc).__name__}", "template_key": template_key}
    record_outbound_delivery_event(
        account_id=account_id,
        target_phone=phone,
        target_conversation_id=None,
        status="sent" if result.get("ok") else "failed",
        message_text=fallback_text or f"[template:{template_key}]",
        last_error=result.get("error"),
        payload={"send_result": result, "template_key": template_key},
        subject_type=subject_type,
        subject_key=subject_key,
        channel="whatsapp_template",
        message_kind=message_kind,
        company_code=company_code,
    )
    return result


def lookup_template_mapping(template_key: str, *, locale: str = "en", company_code: str | None = None) -> dict[str, Any] | None:
    """Resolve a Wathefni template key to an approved provider template. Prefers a
    company-specific override, then the global default; prefers the requested
    locale, then English. Returns None when nothing usable is mapped."""
    company = str(company_code or "").strip().upper() or None
    with db_connect() as conn:
        with conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute(
                """
                SELECT provider_template_name, provider_namespace, status, locale,
                       (metadata->>'provider_language') AS provider_language,
                       company_code
                FROM message_template_map
                WHERE template_key = %s
                  AND provider = 'octopus'
                  AND (company_code = %s OR company_code IS NULL)
                  AND locale IN (%s, 'en')
                ORDER BY (company_code IS NOT NULL) DESC,
                         (locale = %s) DESC
                LIMIT 1
                """,
                (template_key, company, locale, locale),
            )
            row = cur.fetchone()
    return dict(row) if row else None


def send_octopus_whatsapp_image(
    *,
    account_id: str | None,
    phone: str,
    image_url: str,
    caption: str | None = None,
    subject_type: str | None = None,
    subject_key: str | None = None,
    conversation_id: str | None = None,
    company_code: str | None = None,
) -> dict[str, Any]:
    if not valid_whatsapp_recipient(phone):
        return invalid_whatsapp_recipient_result(
            account_id=account_id,
            phone=phone,
            text=caption or "",
            subject_type=subject_type,
            subject_key=subject_key,
            message_kind="image",
            company_code=company_code,
        )
    if delivery_is_dry_run():
        result = {"ok": True, "dry_run": True, "status": 200, "phone": digits(phone), "simulated": True, "media_url": image_url}
        record_outbound_delivery_event(
            account_id=account_id,
            target_phone=phone,
            target_conversation_id=None,
            status="dry_run",
            message_text=caption or "",
            last_error=None,
            payload={"send_result": result, "dry_run": True, "media_kind": "image", "media_url": image_url},
            subject_type=subject_type,
            subject_key=subject_key,
            company_code=company_code,
        )
        return result
    channel = octopus_channel_config()
    account_cfg = ((channel.get("accounts") or {}).get(account_id or "default") or {})
    base_url = account_cfg.get("baseUrl") or channel.get("baseUrl") or "https://app.ai-octopus.com"
    token = account_cfg.get("bearerToken") or channel.get("bearerToken")
    if not token:
        return {"ok": False, "error": "missing_ai_octopus_bearer_token"}
    candidates = []
    if conversation_id:
        candidates.append(str(conversation_id))
    candidates.extend(outbound_conversation_candidates(phone, account_id))
    conversation_ids = unique_conversation_candidates(candidates)
    if not conversation_ids:
        return {"ok": False, "error": "missing_conversation_id", "phone": digits(phone)}
    last_result: dict[str, Any] | None = None
    for cid in conversation_ids:
        payload = {
            "messaging_product": "whatsapp",
            "conversation_id": int(cid) if str(cid).isdigit() else str(cid),
            "to": digits(phone),
            "type": "image",
            "recipient_type": "individual",
            "image": {"link": image_url, "caption": caption or ""},
        }
        req = urllib.request.Request(
            f"{base_url.rstrip('/')}/client/conversation/reply",
            data=json.dumps(payload).encode("utf-8"),
            headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                body = resp.read().decode("utf-8", errors="replace")
                try:
                    parsed = json.loads(body)
                except Exception:
                    parsed = body
                ok = 200 <= resp.status < 300 and not (isinstance(parsed, dict) and parsed.get("success") is False)
                result = {"ok": ok, "status": resp.status, "json": parsed, "conversation_id": cid, "media_url": image_url}
                record_outbound_delivery_event(
                    account_id=account_id,
                    target_phone=phone,
                    target_conversation_id=str(cid),
                    status="sent" if ok else "failed",
                    message_text=caption or "",
                    last_error=None if ok else "ai_octopus_send_rejected",
                    payload={"send_result": result, "media_kind": "image", "media_url": image_url},
                    subject_type=subject_type,
                    subject_key=subject_key,
                    company_code=company_code,
                )
                if ok:
                    update_conversation_link_id(phone, account_id, str(cid))
                    return result
                last_result = result
        except Exception as exc:
            result = {"ok": False, "error": str(exc), "conversation_id": cid, "media_url": image_url}
            record_outbound_delivery_event(
                account_id=account_id,
                target_phone=phone,
                target_conversation_id=str(cid),
                status="failed",
                message_text=caption or "",
                last_error=str(exc)[:500],
                payload={"send_result": result, "media_kind": "image", "media_url": image_url},
                subject_type=subject_type,
                subject_key=subject_key,
                company_code=company_code,
            )
            last_result = result
    return last_result or {"ok": False, "error": "send_image_failed", "media_url": image_url}


def _resolve_outbound_delivery_company_code(
    *,
    company_code: str | None,
    payload: dict[str, Any] | None,
    subject_key: str | None,
) -> str:
    """Require a tenant for every new outbound_delivery_events row.

    Resolution order:
      1) explicit company_code
      2) payload.company_code / memory_scope.company_id
      3) active request company scope
      4) unambiguous applications.app_key -> company_code (exactly one)
    Raises ValueError('company_code_required') when ownership cannot be determined.
    """
    company = normalize_company_code(company_code)
    if not company and isinstance(payload, dict):
        memory_scope = payload.get("memory_scope") if isinstance(payload.get("memory_scope"), dict) else {}
        company = normalize_company_code(
            payload.get("company_code") or memory_scope.get("company_id") or memory_scope.get("company_code")
        )
    if not company:
        company = active_company_code()
    if not company and subject_key:
        try:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT array_agg(DISTINCT company_code) AS companies
                        FROM applications
                        WHERE app_key=%s
                        """,
                        (str(subject_key),),
                    )
                    row = cur.fetchone() or {}
            companies = [
                str(c).strip().upper()
                for c in (row.get("companies") or [])
                if str(c or "").strip()
            ]
            if len(companies) == 1:
                company = companies[0]
        except Exception:
            logger.exception(
                "failed resolving outbound delivery company_code from subject_key=%s",
                subject_key,
            )
    if not company:
        raise ValueError("company_code_required")
    return company


def record_outbound_delivery_event(
    *,
    account_id: str | None,
    target_phone: str | None,
    target_conversation_id: str | None,
    status: str,
    message_text: str,
    last_error: str | None,
    payload: dict[str, Any],
    subject_type: str | None = None,
    subject_key: str | None = None,
    channel: str = "octopus",
    message_kind: str = "text",
    company_code: str | None = None,
    actor_user_id: str | None = None,
    actor_email: str | None = None,
    actor_phone: str | None = None,
    actor_role: str | None = None,
    sender_mode: str | None = None,
    visible_from: str | None = None,
    visible_reply_to: str | None = None,
    provider: str | None = None,
    purpose: str | None = None,
    provider_accept_status: str | None = None,
    external_message_id: str | None = None,
) -> None:
    delivery_id = f"orchestrator-{uuid.uuid4()}"
    sent_at = now_utc() if status in {"sent", "accepted"} else None
    failed_at = now_utc() if status == "failed" else None
    company = _resolve_outbound_delivery_company_code(
        company_code=company_code,
        payload=payload if isinstance(payload, dict) else None,
        subject_key=subject_key,
    )
    payload_scope = payload.get("memory_scope") if isinstance(payload, dict) and isinstance(payload.get("memory_scope"), dict) else {}
    actor_email = normalize_email(actor_email or (payload.get("actor_email") if isinstance(payload, dict) else None) or payload_scope.get("actor_email"))
    if isinstance(payload, dict):
        sender_mode = sender_mode or payload.get("sender_mode")
        visible_from = visible_from or payload.get("visible_from")
        visible_reply_to = visible_reply_to or payload.get("visible_reply_to")
        provider = provider or payload.get("provider")
        purpose = purpose or payload.get("purpose")
        provider_accept_status = provider_accept_status or payload.get("provider_accept_status")
        external_message_id = external_message_id or payload.get("message_id") or payload.get("external_message_id")
        # Persist resolved ownership on the audit payload for later forensics.
        if not payload.get("company_code"):
            payload = {**payload, "company_code": company}
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO outbound_delivery_events
                (delivery_id, channel, account_id, target_phone, target_conversation_id, message_kind,
                 subject_type, subject_key, status, message_text, last_error, payload, sent_at, failed_at,
                 company_code, actor_user_id, actor_email, actor_phone, actor_role,
                 sender_mode, visible_from, visible_reply_to, provider, purpose, provider_accept_status,
                 external_message_id)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                """,
                (
                    delivery_id,
                    channel,
                    account_id,
                    digits(target_phone),
                    str(target_conversation_id) if target_conversation_id else None,
                    message_kind,
                    subject_type,
                    subject_key,
                    status,
                    message_text,
                    last_error,
                    Json(json_safe(payload)),
                    sent_at,
                    failed_at,
                    company,
                    actor_user_id,
                    actor_email,
                    digits(actor_phone),
                    actor_role,
                    sender_mode,
                    visible_from,
                    visible_reply_to,
                    provider,
                    purpose,
                    provider_accept_status,
                    str(external_message_id) if external_message_id else None,
                ),
            )
        conn.commit()


def update_application_status(
    app: dict[str, Any],
    status: str,
    *,
    trigger: str = "legacy_update",
    human_confirmed: bool = False,
    actor_type: str = "human",
    actor_user_id: str | None = None,
    actor_phone: str | None = None,
    channel: str | None = None,
    expected_from_stage: str | None = None,
    expected_version: int | None = None,
    idempotency_key: str | None = None,
    permissions: set[str] | list[str] | None = None,
    confirmation_token: str | None = None,
    confirmation_id: str | None = None,
    confirmation_action: str | None = None,
    confirmation_payload: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Mandatory single authority for every application lifecycle mutation."""
    import recruiting_lifecycle as _rl

    company = str(app.get("company_code") or "").strip().upper()
    if not company:
        return {"ok": False, "error": "tenant_scope_required"}
    return _rl.transition_application(
        sys.modules[__name__],
        app_key=str(app.get("app_key") or ""),
        company_code=company,
        to_stage=status,
        trigger=trigger,
        expected_from_stage=expected_from_stage,
        expected_version=expected_version,
        actor_type=actor_type,
        actor_user_id=actor_user_id,
        actor_phone=actor_phone,
        channel=channel,
        confirmation_token=confirmation_token,
        confirmation_id=confirmation_id,
        confirmation_action=confirmation_action,
        confirmation_payload=confirmation_payload,
        human_confirmed=human_confirmed,
        idempotency_key=idempotency_key,
        permissions=permissions,
        metadata=metadata,
        run_hire_side_effects=False,
    )


def transition_hire(app: dict[str, Any]) -> dict[str, Any]:
    args = [
        str(WORKSPACE / "tools" / "db" / "posthire_state.py"),
        "--env",
        str(ENV_PATH),
        "transition-hire",
        "--app-key",
        str(app["app_key"]),
    ]
    if runtime_binding().application_environment != "production":
        args.append("--no-sheet-sync")
    result = run_workspace_tool(args, timeout=90)
    # Best-effort, idempotent top-up: the external tool seeds a small subset; this
    # fills in the rest of the company template without touching what it created.
    # No-op when the flag is off; failures never change the hire result.
    if result.get("ok") and onboarding_seed_enabled():
        try:
            employee = find_employee_by_phone(app.get("phone"), company_code=app.get("company_code"))
            if employee:
                with db_connect() as conn:
                    with conn.cursor() as cur:
                        seed_onboarding_items(cur, employee)
                    conn.commit()
        except Exception:
            logger.warning("onboarding top-up seeding after hire failed", exc_info=True)
    return result


def notify_candidate(app: dict[str, Any], account_id: str | None, message: str | None = None) -> dict[str, Any]:
    try:
        assert_application_communication_allowed(app, kind="notify")  # HELD_COMMUNICATION_AUTHORITY_STAGING_PATCH
    except CandidateCommunicationAuthorityError as exc:
        return {**exc.as_result(), "candidate": candidate_contact(app) if isinstance(app, dict) else {}}
    contact = candidate_contact(app)
    name = contact.get("name") or "there"
    body = message or f"Hi {name}, you have been shortlisted. OctoHR will contact you with the next step."
    company = str((app or {}).get("company_code") or "").strip().upper()
    # Fail-closed: Assistant/send path requires company WhatsApp candidate audience configured.
    if company:
        try:
            import assistant_channel_readiness as acr

            if not acr.whatsapp_candidate_ready(sys.modules[__name__], company):
                return {
                    "ok": False,
                    "error": "whatsapp_not_configured",
                    "message": body,
                    "candidate": contact,
                    "send": {"ok": False, "error": "whatsapp_not_configured"},
                }
        except Exception:
            pass
    result = send_octopus_whatsapp(
        account_id=account_id,
        phone=contact["phone"] or "",
        text=body,
        subject_type="candidate",
        subject_key=app.get("app_key"),
        company_code=company or None,
        audience="candidate",
    )
    return {"ok": result.get("ok", False), "send": result, "message": body, "candidate": contact}


