def seed_assessment_item_bank() -> None:
    sections = [
        {"key": "numerical_reasoning", "label": "Numerical reasoning"},
        {"key": "verbal_reasoning", "label": "Verbal reasoning"},
        {"key": "logical_reasoning", "label": "Logical reasoning"},
        {"key": "competency_judgment", "label": "Workplace judgment and competency indicators"},
    ]
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO assessment_batteries
                (battery_key, company_code, name, version, sections, raw_json, updated_at)
                VALUES (%s,'GLOBAL','OctoHR Ability Assessment','v1',%s,%s,now())
                ON CONFLICT (battery_key) DO UPDATE SET
                  name=EXCLUDED.name,
                  version=EXCLUDED.version,
                  sections=EXCLUDED.sections,
                  raw_json=EXCLUDED.raw_json,
                  updated_at=now()
                """,
                (
                    ASSESSMENT_BATTERY_KEY,
                    Json(sections),
                    Json({
                        "source": "orchestrator_seed",
                        "scoring": "deterministic_official_score_json",
                        "framework": NBK_COMPETENCY_FRAMEWORK,
                        "role_profiles": NBK_ROLE_PROFILES,
                    }),
                ),
            )
            for section in ABILITY_SECTIONS:
                cur.execute(
                    """
                    INSERT INTO assessment_norm_groups
                    (norm_key, company_code, battery_key, section, sample_size, percentiles, source, raw_json, updated_at)
                    VALUES (%s,'GLOBAL',%s,%s,0,%s,'internal_synthetic_until_client_benchmark',%s,now())
                    ON CONFLICT (norm_key) DO UPDATE SET
                      battery_key=EXCLUDED.battery_key,
                      section=EXCLUDED.section,
                      source=EXCLUDED.source,
                      raw_json=EXCLUDED.raw_json,
                      updated_at=now()
                    """,
                    (
                        f"{ASSESSMENT_BATTERY_KEY}:{section}:synthetic_v1",
                        ASSESSMENT_BATTERY_KEY,
                        section,
                        Json({"p10": 10, "p25": 25, "p50": 50, "p75": 75, "p90": 90}),
                        Json({
                            "status": "placeholder_until_client_benchmark",
                            "minimum_recommended_sample": 200,
                            "note": "Replace with company or role-specific empirical percentiles after enough completed attempts.",
                        }),
                    ),
                )
            for item in ASSESSMENT_ITEM_BANK:
                cur.execute(
                    """
                    INSERT INTO assessment_items
                    (item_id, battery_key, section, item_order, prompt_text, choices, answer_key, scoring, difficulty, raw_json, updated_at)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,now())
                    ON CONFLICT (item_id) DO UPDATE SET
                      battery_key=EXCLUDED.battery_key,
                      section=EXCLUDED.section,
                      item_order=EXCLUDED.item_order,
                      prompt_text=EXCLUDED.prompt_text,
                      choices=EXCLUDED.choices,
                      answer_key=EXCLUDED.answer_key,
                      scoring=EXCLUDED.scoring,
                      difficulty=EXCLUDED.difficulty,
                      raw_json=EXCLUDED.raw_json,
                      updated_at=now()
                    """,
                    (
                        item["item_id"],
                        ASSESSMENT_BATTERY_KEY,
                        item["section"],
                        int(item["item_order"]),
                        item["prompt_text"],
                        Json(item["choices"]),
                        item.get("answer_key"),
                        Json(item.get("scoring") or {"type": "answer_key", "correct": 1, "incorrect": 0, "max_score": 1}),
                        item.get("difficulty"),
                        Json(json_safe(item)),
                    ),
                )
        conn.commit()


def active_assessment_battery(company_code: str | None) -> dict[str, Any] | None:
    company = require_company_code(company_code)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM assessment_batteries
                WHERE is_active IS TRUE
                  AND company_code IN (%s, 'GLOBAL')
                ORDER BY CASE WHEN company_code=%s THEN 0 ELSE 1 END, updated_at DESC
                LIMIT 1
                """,
                (company, company),
            )
            row = cur.fetchone()
            return dict(row) if row else None


def _battery_approved_for_use_beta(battery: dict[str, Any] | None) -> bool:
    if not battery:
        return False
    raw = battery.get("raw_json") if isinstance(battery.get("raw_json"), dict) else {}
    return bool(
        raw.get("approved_for_use_beta") is True
        or str(raw.get("approved_for_use_status") or "") == "approved_for_use_beta"
    )


def resolve_assessment_battery(
    company_code: str | None,
    *,
    battery_key: str | None = None,
) -> dict[str, Any] | None:
    """Resolve the battery for a send.

    Explicit battery_key may select a company beta battery that is approved for
    use but intentionally not the default active battery. Without battery_key,
    preserve the existing active-battery default (GLOBAL ability for WATHEFNI).
    """
    company = require_company_code(company_code)
    selected = str(battery_key or "").strip()
    if not selected:
        return active_assessment_battery(company)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM assessment_batteries
                WHERE battery_key=%s
                  AND company_code IN (%s, 'GLOBAL')
                  AND retired_at IS NULL
                ORDER BY CASE WHEN company_code=%s THEN 0 ELSE 1 END, updated_at DESC
                LIMIT 1
                """,
                (selected, company, company),
            )
            row = cur.fetchone()
            if not row:
                return None
            battery = dict(row)
            if battery.get("is_active") is True or _battery_approved_for_use_beta(battery):
                return battery
            return None


def list_selectable_assessment_batteries(company_code: str | None) -> list[dict[str, Any]]:
    company = require_company_code(company_code)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM assessment_batteries
                WHERE retired_at IS NULL
                  AND company_code IN (%s, 'GLOBAL')
                  AND (
                    is_active IS TRUE
                    OR COALESCE(raw_json->>'approved_for_use_beta','') = 'true'
                    OR COALESCE(raw_json->>'approved_for_use_status','') = 'approved_for_use_beta'
                  )
                ORDER BY CASE WHEN company_code=%s THEN 0 ELSE 1 END,
                         CASE WHEN is_active IS TRUE THEN 0 ELSE 1 END,
                         name, battery_key
                """,
                (company, company),
            )
            return [dict(row) for row in cur.fetchall()]


def assessment_items_for_battery(battery_key: str) -> list[dict[str, Any]]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM assessment_items
                WHERE battery_key=%s
                ORDER BY item_order ASC
                """,
                (battery_key,),
            )
            return [dict(row) for row in cur.fetchall()]


def assessment_choice_lines(item: dict[str, Any]) -> list[str]:
    choices = item.get("choices") if isinstance(item.get("choices"), list) else []
    return [f"{choice.get('key')}. {choice.get('text')}" for choice in choices if choice.get("key") and choice.get("text")]


def format_assessment_question(attempt: dict[str, Any], item: dict[str, Any]) -> str:
    number = int(attempt.get("current_item_index") or 0) + 1
    total = int(attempt.get("total_items") or len(ASSESSMENT_ITEM_BANK))
    lines = [
        f"Question {number}/{total}",
        str(item.get("prompt_text") or "").strip(),
        *assessment_choice_lines(item),
        "Reply with A, B, C, or D.",
    ]
    return "\n".join(line for line in lines if line)


def parse_assessment_answer(text: str | None, item: dict[str, Any]) -> str | None:
    normalized = re.sub(r"\s+", " ", (text or "").strip())
    if not normalized:
        return None
    letter_match = re.match(r"^([A-Da-d])(?:[\).:\s]|$)", normalized)
    if letter_match:
        return letter_match.group(1).upper()
    choices = item.get("choices") if isinstance(item.get("choices"), list) else []
    lowered = normalized.lower()
    for choice in choices:
        if lowered == str(choice.get("text") or "").strip().lower():
            return str(choice.get("key") or "").upper() or None
    return None


def assessment_band(percent: float) -> str:
    if percent >= 80:
        return "strong"
    if percent >= 60:
        return "qualified"
    if percent >= 40:
        return "needs_review"
    return "low"


def clamp_number(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))


def percentile_cutoff(values: list[float], percentile: int) -> float:
    cleaned = sorted(float(value) for value in values if value is not None)
    if not cleaned:
        return 0.0
    if len(cleaned) == 1:
        return round(cleaned[0], 1)
    position = (len(cleaned) - 1) * (percentile / 100.0)
    lower = int(position)
    upper = min(lower + 1, len(cleaned) - 1)
    weight = position - lower
    return round(cleaned[lower] + ((cleaned[upper] - cleaned[lower]) * weight), 1)


def percentile_rank_from_cutoffs(percent: float, cutoffs: dict[str, Any]) -> int:
    points: list[tuple[int, float]] = []
    for key, value in cutoffs.items():
        match = re.match(r"^p(\d{1,2})$", str(key))
        if not match:
            continue
        points.append((int(match.group(1)), float(value or 0)))
    points = sorted(points, key=lambda item: item[1])
    if not points:
        return int(round(clamp_number(percent, 1, 99)))
    if percent <= points[0][1]:
        return int(clamp_number(points[0][0], 1, 99))
    for (left_rank, left_score), (right_rank, right_score) in zip(points, points[1:]):
        if percent <= right_score:
            if right_score == left_score:
                return int(clamp_number(right_rank, 1, 99))
            ratio = (percent - left_score) / (right_score - left_score)
            return int(round(clamp_number(left_rank + ((right_rank - left_rank) * ratio), 1, 99)))
    return int(clamp_number(points[-1][0], 1, 99))


def ability_norm_scores(percent: float, norm_group: dict[str, Any] | None = None) -> dict[str, Any]:
    sample_size = int((norm_group or {}).get("sample_size") or 0)
    source = str((norm_group or {}).get("source") or "")
    percentiles = (norm_group or {}).get("percentiles") if isinstance((norm_group or {}).get("percentiles"), dict) else {}
    if sample_size >= 200 and source.startswith("empirical_") and percentiles:
        percentile = percentile_rank_from_cutoffs(percent, percentiles)
        norm_source = source
        norm_version = str((norm_group or {}).get("norm_key") or ASSESSMENT_NORM_VERSION)
    else:
        percentile = int(round(clamp_number(percent, 1, 99)))
        norm_source = "internal_synthetic_until_client_benchmark"
        norm_version = ASSESSMENT_NORM_VERSION
    t_score = int(round(clamp_number(30 + (percent / 100.0) * 40, 20, 80)))
    sten = int(round(clamp_number(1 + (percent / 100.0) * 9, 1, 10)))
    return {
        "percentile": percentile,
        "t_score": t_score,
        "sten": sten,
        "band": assessment_band(percent),
        "norm_version": norm_version,
        "norm_source": norm_source,
        "norm_sample_size": sample_size,
    }


def competency_band(score_1_to_5: float) -> str:
    if score_1_to_5 >= 4.25:
        return "strength"
    if score_1_to_5 >= 3.25:
        return "proficient"
    if score_1_to_5 >= 2.5:
        return "mixed"
    return "development"


def competency_color(score_1_to_5: float) -> str:
    band = competency_band(score_1_to_5)
    return {"strength": "green", "proficient": "blue", "mixed": "amber", "development": "red"}[band]


def role_profile_for_attempt(attempt: dict[str, Any]) -> tuple[str, dict[str, Any], str]:
    haystack = normalize_text(f"{attempt.get('position_title') or ''} {attempt.get('position_code') or ''}")
    for key, profile in NBK_ROLE_PROFILES.items():
        if key == "general":
            continue
        aliases = profile.get("aliases") if isinstance(profile.get("aliases"), list) else []
        if any(normalize_text(alias) and normalize_text(alias) in haystack for alias in aliases):
            return key, profile, "specialized_role_profile"
    return "general", NBK_ROLE_PROFILES["general"], "general_profile_fallback"


def weighted_average(values: dict[str, float], weights: dict[str, float], *, default: float = 0.0) -> float:
    total_weight = 0.0
    total = 0.0
    for key, weight in weights.items():
        numeric = values.get(key)
        if numeric is None:
            continue
        total += float(numeric) * float(weight)
        total_weight += float(weight)
    return round(total / total_weight, 1) if total_weight else default


def fit_band(percent: float) -> str:
    if percent >= 75:
        return "high"
    if percent >= 55:
        return "medium"
    return "low"


def item_scoring(item: dict[str, Any]) -> dict[str, Any]:
    scoring = item.get("scoring") if isinstance(item.get("scoring"), dict) else {}
    raw_json = item.get("raw_json") if isinstance(item.get("raw_json"), dict) else {}
    raw_scoring = raw_json.get("scoring") if isinstance(raw_json.get("scoring"), dict) else {}
    return {**raw_scoring, **scoring}


def item_max_score(item: dict[str, Any]) -> float:
    scoring = item_scoring(item)
    if scoring.get("type") == "competency_keyed":
        return float(scoring.get("max_score") or 5)
    return float(scoring.get("max_score") or 1)


def selected_item_score(item: dict[str, Any], selected_key: str) -> tuple[float, bool | None]:
    scoring = item_scoring(item)
    selected = str(selected_key or "").upper()
    answer_key = str(item.get("answer_key") or "").upper()
    if scoring.get("type") == "competency_keyed":
        choice_scores = scoring.get("choice_scores") if isinstance(scoring.get("choice_scores"), dict) else {}
        return float(choice_scores.get(selected) or 0), None
    is_correct = bool(selected and selected == answer_key)
    return (1.0 if is_correct else 0.0), is_correct


def assessment_norm_lookup(company_code: str | None, battery_key: str | None) -> dict[str, dict[str, Any]]:
    company = require_company_code(company_code)
    battery = str(battery_key or ASSESSMENT_BATTERY_KEY)
    lookup: dict[str, dict[str, Any]] = {}
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT norm_key, company_code, battery_key, section, sample_size, percentiles, source, is_active, raw_json, updated_at
                FROM assessment_norm_groups
                WHERE battery_key=%s
                  AND company_code IN (%s, 'GLOBAL')
                  AND is_active IS TRUE
                ORDER BY CASE WHEN company_code=%s THEN 0 ELSE 1 END,
                         sample_size DESC,
                         updated_at DESC
                """,
                (battery, company, company),
            )
            for row in cur.fetchall():
                item = json_safe(dict(row))
                section = str(item.get("section") or "")
                if section and section not in lookup:
                    lookup[section] = item
    return lookup


def assessment_norm_version(norm_lookup: dict[str, dict[str, Any]] | None = None) -> str:
    empirical = [
        str(group.get("norm_key"))
        for group in (norm_lookup or {}).values()
        if int(group.get("sample_size") or 0) >= 200 and str(group.get("source") or "").startswith("empirical_")
    ]
    return ",".join(sorted(empirical)) if empirical else ASSESSMENT_NORM_VERSION


def assessment_report_summary(percent: float, band: str) -> str:
    if band == "strong":
        return "Strong ability-assessment result. Candidate answered most items correctly."
    if band == "qualified":
        return "Qualified ability-assessment result. Candidate is in the qualified score band."
    if band == "needs_review":
        return "Borderline ability-assessment result. Review alongside CV, screening, and role fit."
    return "Low ability-assessment result. Review carefully before moving forward."


def deterministic_interview_probes(job_match: dict[str, Any], competency_scores: dict[str, dict[str, Any]]) -> list[dict[str, str]]:
    probes: list[dict[str, str]] = []
    for strength in job_match.get("strengths") or []:
        probes.append({
            "type": "strength_probe",
            "competency": str(strength),
            "question": f"Tell me about a time you used {strength} to improve a customer or operational outcome.",
        })
    for area in job_match.get("development_areas") or []:
        probes.append({
            "type": "development_probe",
            "competency": str(area),
            "question": f"Describe a situation where {area} was difficult for you. What did you do to improve the result?",
        })
    if not probes:
        for key, value in sorted(competency_scores.items(), key=lambda item: float(item[1].get("score") or 0), reverse=True)[:3]:
            probes.append({
                "type": "evidence_probe",
                "competency": key.replace("_", " "),
                "question": f"Give an example that shows your {key.replace('_', ' ')} in a work setting.",
            })
    return probes[:6]


def build_report_sections(
    *,
    ability_scores: dict[str, Any],
    competency_scores: dict[str, dict[str, Any]],
    job_match: dict[str, Any],
    norm_version: str,
) -> dict[str, Any]:
    grouped_competencies: list[dict[str, Any]] = []
    for group in NBK_COMPETENCY_FRAMEWORK["groups"]:
        entries = []
        for competency in group.get("competencies") or []:
            score = competency_scores.get(competency)
            if score:
                entries.append({"key": competency, **score})
        if entries:
            grouped_competencies.append({"key": group.get("key"), "label": group.get("label"), "competencies": entries})
    return {
        "verify_ability": {
            "title": "Ability Assessment",
            "style": "verify_ability_style",
            "norm_version": norm_version,
            "sections": ability_scores,
            "interpretation": "Percentile, T-score, and sten are generated from OctoHR's internal synthetic norm table until client benchmark data is available.",
        },
        "competency_profile": {
            "title": "Competency Profile",
            "style": "competency_profile_style",
            "framework_version": NBK_COMPETENCY_FRAMEWORK["version"],
            "groups": grouped_competencies,
        },
        "mass_assessment": {
            "title": "Mass Assessment Summary",
            "style": "mass_assessment_style",
            "role_profile": job_match.get("role_profile_label"),
            "job_match_percent": job_match.get("job_match_percent"),
            "fit_band": job_match.get("fit_band"),
            "strengths": job_match.get("strengths") or [],
            "development_areas": job_match.get("development_areas") or [],
            "match_confidence": job_match.get("match_confidence"),
        },
        "interview_probes": deterministic_interview_probes(job_match, competency_scores),
    }


def validate_assessment_item_bank(items: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    items = items or ASSESSMENT_ITEM_BANK
    errors: list[str] = []
    item_ids: set[str] = set()
    known_competencies = set(NBK_COMPETENCY_FRAMEWORK["competencies"].keys())
    for item in items:
        item_id = str(item.get("item_id") or "").strip()
        if not item_id:
            errors.append("missing_item_id")
            continue
        if item_id in item_ids:
            errors.append(f"duplicate_item_id:{item_id}")
        item_ids.add(item_id)
        choices = item.get("choices") if isinstance(item.get("choices"), list) else []
        choice_keys = {str(choice.get("key") or "").upper() for choice in choices}
        if not {"A", "B", "C", "D"}.issubset(choice_keys):
            errors.append(f"{item_id}:missing_choice_keys")
        scoring = item.get("scoring") if isinstance(item.get("scoring"), dict) else {}
        if scoring.get("type") == "competency_keyed":
            choice_scores = scoring.get("choice_scores") if isinstance(scoring.get("choice_scores"), dict) else {}
            if not all(key in choice_scores for key in ["A", "B", "C", "D"]):
                errors.append(f"{item_id}:missing_competency_choice_scores")
            competencies = scoring.get("competencies") if isinstance(scoring.get("competencies"), dict) else {}
            if not competencies:
                errors.append(f"{item_id}:missing_competency_mapping")
            for competency in competencies:
                if competency not in known_competencies:
                    errors.append(f"{item_id}:unknown_competency:{competency}")
        elif str(item.get("answer_key") or "").upper() not in choice_keys:
            errors.append(f"{item_id}:invalid_answer_key")
    for role_key, role in NBK_ROLE_PROFILES.items():
        ability_weights = role.get("ability_weights") if isinstance(role.get("ability_weights"), dict) else {}
        competency_weights = role.get("competency_weights") if isinstance(role.get("competency_weights"), dict) else {}
        for section in ability_weights:
            if section not in ABILITY_SECTIONS:
                errors.append(f"{role_key}:unknown_ability_weight:{section}")
        for competency in competency_weights:
            if competency not in known_competencies:
                errors.append(f"{role_key}:unknown_competency_weight:{competency}")
    return {"ok": not errors, "error_count": len(errors), "errors": errors}


def build_assessment_report_json(
    *,
    attempt: dict[str, Any],
    items: list[dict[str, Any]],
    responses: list[dict[str, Any]],
    norm_lookup: dict[str, dict[str, Any]] | None = None,
) -> dict[str, Any]:
    item_by_id = {str(item.get("item_id")): item for item in items}
    max_score = float(sum(item_max_score(item) for item in items) or len(responses) or 1)
    raw_score = float(sum(float(response.get("score_numeric") or 0) for response in responses))
    percent = round((raw_score / max_score) * 100, 1) if max_score else 0.0
    band = assessment_band(percent)
    section_totals: dict[str, dict[str, float]] = {}
    for item in items:
        section = str(item.get("section") or "general")
        section_totals.setdefault(section, {"raw": 0.0, "max": 0.0, "percent": 0.0})
        section_totals[section]["max"] += item_max_score(item)
    competency_totals: dict[str, dict[str, float]] = {}
    for response in responses:
        item = item_by_id.get(str(response.get("item_id"))) or {}
        section = str(item.get("section") or "general")
        section_totals.setdefault(section, {"raw": 0.0, "max": 0.0, "percent": 0.0})
        section_totals[section]["raw"] += float(response.get("score_numeric") or 0)
        scoring = item_scoring(item)
        competencies = scoring.get("competencies") if isinstance(scoring.get("competencies"), dict) else {}
        max_item_score = item_max_score(item) or 1.0
        selected_score = float(response.get("score_numeric") or 0)
        score_1_to_5 = 1 + (selected_score / max_item_score) * 4
        for competency, weight in competencies.items():
            key = str(competency)
            numeric_weight = float(weight or 0)
            competency_totals.setdefault(key, {"weighted": 0.0, "weight": 0.0})
            competency_totals[key]["weighted"] += score_1_to_5 * numeric_weight
            competency_totals[key]["weight"] += numeric_weight
    for section in section_totals.values():
        section["percent"] = round((section["raw"] / section["max"]) * 100, 1) if section.get("max") else 0.0
    for section_key, section in section_totals.items():
        section.update(ability_norm_scores(float(section["percent"]), (norm_lookup or {}).get(section_key)))
    ability_scores = {key: value for key, value in section_totals.items() if key in ABILITY_SECTIONS}
    ability_percent_values = {key: float(value.get("percent") or 0) for key, value in ability_scores.items()}
    competency_scores: dict[str, dict[str, Any]] = {}
    for key, value in competency_totals.items():
        score_1_to_5 = round(value["weighted"] / value["weight"], 2) if value.get("weight") else 0.0
        competency_scores[key] = {
            "score": score_1_to_5,
            "band": competency_band(score_1_to_5),
            "color": competency_color(score_1_to_5),
            "label": NBK_COMPETENCY_FRAMEWORK["competencies"].get(key, key.replace("_", " ").title()),
        }
    role_key, role_profile, match_confidence = role_profile_for_attempt(attempt)
    competency_percent_values = {key: round(((value.get("score") or 0) - 1) / 4 * 100, 1) for key, value in competency_scores.items()}
    ability_fit = weighted_average(ability_percent_values, role_profile.get("ability_weights") or {}, default=percent)
    competency_fit = weighted_average(competency_percent_values, role_profile.get("competency_weights") or {}, default=percent)
    job_match_percent = round((ability_fit * 0.55) + (competency_fit * 0.45), 1)
    strengths = [
        key.replace("_", " ")
        for key, value in sorted(competency_percent_values.items(), key=lambda item: item[1], reverse=True)
        if value >= 70
    ][:4]
    development_areas = [
        key.replace("_", " ")
        for key, value in sorted(competency_percent_values.items(), key=lambda item: item[1])
        if value < 55
    ][:4]
    job_match = {
        "role_profile_key": role_key,
        "role_profile_label": role_profile.get("label"),
        "match_confidence": match_confidence,
        "ability_fit_percent": ability_fit,
        "competency_fit_percent": competency_fit,
        "job_match_percent": job_match_percent,
        "fit_band": fit_band(job_match_percent),
        "ability_weights": role_profile.get("ability_weights"),
        "competency_weights": role_profile.get("competency_weights"),
        "strengths": strengths,
        "development_areas": development_areas,
    }
    report_sections = build_report_sections(
        ability_scores=ability_scores,
        competency_scores=competency_scores,
        job_match=job_match,
        norm_version=assessment_norm_version(norm_lookup),
    )
    return {
        "attempt_id": str(attempt.get("attempt_id")),
        "app_key": attempt.get("app_key"),
        "candidate_name": attempt.get("candidate_name"),
        "position_title": attempt.get("position_title"),
        "raw_score": raw_score,
        "max_score": max_score,
        "percent": percent,
        "band": band,
        "section_scores": section_totals,
        "ability_scores": ability_scores,
        "competency_profile": {
            "framework_version": NBK_COMPETENCY_FRAMEWORK["version"],
            "scores": competency_scores,
        },
        "job_match": job_match,
        "report_sections": report_sections,
        "report_types": ["verify_ability_style", "competency_profile_style", "mass_assessment_style"],
        "summary": assessment_report_summary(percent, band),
        "scoring": "deterministic_official_score_json",
        "norm_version": assessment_norm_version(norm_lookup),
        "guardrails": {
            "ai_may_summarize": True,
            "ai_may_change_scores": False,
            "content_policy": "original_wathefni_items_no_shl_proprietary_text",
        },
    }


def assessment_section_samples(company: str, battery_key: str) -> dict[str, list[float]]:
    samples: dict[str, list[float]] = {section: [] for section in ABILITY_SECTIONS}
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT s.section_scores
                FROM assessment_scores s
                JOIN assessment_attempts aa ON aa.attempt_id=s.attempt_id
                WHERE aa.company_code=%s
                  AND aa.battery_key=%s
                  AND aa.status='completed'
                """,
                (company, battery_key),
            )
            for row in cur.fetchall():
                section_scores = row.get("section_scores") if isinstance(row.get("section_scores"), dict) else {}
                for section in ABILITY_SECTIONS:
                    score = section_scores.get(section) if isinstance(section_scores.get(section), dict) else {}
                    if score.get("percent") is not None:
                        samples.setdefault(section, []).append(float(score.get("percent") or 0))
    return samples


def build_empirical_norm_groups(company: str, battery_key: str, *, minimum_sample: int = 200) -> list[dict[str, Any]]:
    samples_by_section = assessment_section_samples(company, battery_key)
    groups: list[dict[str, Any]] = []
    for section in sorted(ABILITY_SECTIONS):
        samples = samples_by_section.get(section) or []
        sample_size = len(samples)
        percentiles = {f"p{rank}": percentile_cutoff(samples, rank) for rank in [1, 5, 10, 25, 50, 75, 90, 95, 99]} if samples else {}
        groups.append({
            "norm_key": f"{battery_key}:{company.lower()}:{section}:empirical_v1",
            "company_code": company,
            "battery_key": battery_key,
            "section": section,
            "sample_size": sample_size,
            "percentiles": percentiles,
            "source": "empirical_company_completed_attempts",
            "is_active": sample_size >= minimum_sample,
            "raw_json": {
                "minimum_recommended_sample": minimum_sample,
                "status": "ready" if sample_size >= minimum_sample else "needs_more_completed_attempts",
                "generated_at": datetime.now(timezone.utc).isoformat(),
            },
        })
    return groups


def recalculate_assessment_norm_groups(
    company: str,
    *,
    battery_key: str | None = None,
    persist: bool = False,
    minimum_sample: int = 200,
) -> dict[str, Any]:
    battery = active_assessment_battery(company)
    selected_battery = str(battery_key or (battery or {}).get("battery_key") or ASSESSMENT_BATTERY_KEY)
    groups = build_empirical_norm_groups(company, selected_battery, minimum_sample=minimum_sample)
    ready_groups = [group for group in groups if group.get("is_active")]
    if persist:
        with db_connect() as conn:
            with conn.cursor() as cur:
                for group in groups:
                    cur.execute(
                        """
                        INSERT INTO assessment_norm_groups
                        (norm_key, company_code, battery_key, section, sample_size, percentiles, source, is_active, raw_json, updated_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,now())
                        ON CONFLICT (norm_key) DO UPDATE SET
                          sample_size=EXCLUDED.sample_size,
                          percentiles=EXCLUDED.percentiles,
                          source=EXCLUDED.source,
                          is_active=EXCLUDED.is_active,
                          raw_json=EXCLUDED.raw_json,
                          updated_at=now()
                        """,
                        (
                            group["norm_key"],
                            group["company_code"],
                            group["battery_key"],
                            group["section"],
                            group["sample_size"],
                            Json(json_safe(group["percentiles"])),
                            group["source"],
                            bool(group["is_active"]),
                            Json(json_safe(group["raw_json"])),
                        ),
                    )
            conn.commit()
    return {
        "ok": True,
        "company_code": company,
        "battery_key": selected_battery,
        "persisted": persist,
        "minimum_sample": minimum_sample,
        "status": "empirical_ready" if len(ready_groups) == len(ABILITY_SECTIONS) else "needs_more_completed_attempts",
        "groups": json_safe(groups),
    }


def update_application_assessment_snapshot(
    app_key: str,
    company_code: str,
    snapshot: dict[str, Any],
) -> None:
    company = str(company_code or "").strip().upper()
    if not app_key or not company:
        raise ValueError("assessment_snapshot_requires_tenant_binding")
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT raw_json FROM applications WHERE app_key=%s AND company_code=%s FOR UPDATE",
                (app_key, company),
            )
            row = cur.fetchone()
            if not row:
                return
            raw_json = dict(row.get("raw_json")) if isinstance(row.get("raw_json"), dict) else {}
            raw_json["assessment"] = json_safe(snapshot)
            cur.execute(
                """
                UPDATE applications
                SET raw_json=%s, updated_at=COALESCE(updated_at, CURRENT_DATE)
                WHERE app_key=%s AND company_code=%s
                """,
                (Json(json_safe(raw_json)), app_key, company),
            )
        conn.commit()


def latest_assessment_attempt_for_app(app_key: str, company_code: str | None = None) -> dict[str, Any] | None:
    params: list[Any] = [app_key]
    company_filter = ""
    if company_code:
        company_filter = "AND company_code=%s"
        params.append(company_code)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT *
                FROM assessment_attempts
                WHERE app_key=%s {company_filter}
                ORDER BY created_at DESC
                LIMIT 1
                """,
                tuple(params),
            )
            row = cur.fetchone()
            return dict(row) if row else None


def open_assessment_attempts_for_phone(
    phone: str | None,
    company_code: str | None,
) -> list[dict[str, Any]]:
    phone_digits = digits(phone)
    company = normalize_company_code(company_code)
    if not phone_digits or not company:
        return []
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM assessment_attempts
                WHERE phone=%s AND company_code=%s
                  AND status IN ('pending','in_progress')
                ORDER BY updated_at DESC, created_at DESC
                """,
                (phone_digits, company),
            )
            return [dict(row) for row in cur.fetchall()]


def active_assessment_attempt_for_phone(
    phone: str | None,
    company_code: str | None,
) -> dict[str, Any] | None:
    attempts = open_assessment_attempts_for_phone(phone, company_code)
    return attempts[0] if attempts else None


