def video_interview_public_base_url() -> str:
    return (
        os.environ.get("PUBLIC_CANDIDATE_BASE_URL")
        or os.environ.get("PUBLIC_APP_BASE_URL")
        or os.environ.get("WATHEFNI_VIDEO_INTERVIEW_PUBLIC_BASE_URL")
        or os.environ.get("WATHEFNI_PUBLIC_CANDIDATE_BASE_URL")
        or os.environ.get("WATHEFNI_PUBLIC_BASE_URL")
        or os.environ.get("WATHEFNI_APP_BASE_URL")
        or "https://api.octo-hr.com"
    ).rstrip("/")


def assessment_link_secret() -> bytes:
    """Active assessment link signing key.

    R2: dedicated secret only. Raises LinkSecretUnavailable rather than falling
    back to a committed constant, a dashboard token, or the database URL.
    """
    return _link_secrets.signing_secret("assessment")


def video_interview_link_secret() -> bytes:
    """Active video-interview link signing key. Fails closed (see above)."""
    return _link_secrets.signing_secret("video_interview")


def link_signing_available(purpose: str) -> bool:
    return _link_secrets.available(purpose)


def link_signing_unavailable_error(purpose: str) -> HTTPException:
    return HTTPException(
        status_code=503,
        detail={
            "error": "link_signing_unavailable",
            "message": "This link capability is temporarily unavailable.",
            "purpose": purpose,
        },
    )


def b64url_encode(value: bytes) -> str:
    return base64.urlsafe_b64encode(value).decode("ascii").rstrip("=")


def b64url_decode(value: str) -> bytes:
    padded = value + ("=" * (-len(value) % 4))
    return base64.urlsafe_b64decode(padded.encode("ascii"))


def sign_assessment_token(attempt_id: str, expires_at: int) -> str:
    payload = f"{attempt_id}:{expires_at}"
    signature = hmac.new(assessment_link_secret(), payload.encode("utf-8"), hashlib.sha256).digest()
    return b64url_encode(f"{payload}:".encode("utf-8") + signature)


def _verify_link_signature(purpose: str, subject_id: str, token: str | None) -> bool:
    """Constant-time verification against the active key, then retired keys.

    Retired keys come from `<VAR>_PREVIOUS` and exist only to keep already-issued
    links working through a rotation. The removed dev-secret constants are on the
    banned list, so links minted under the old fallback cannot verify here.
    """
    if not token:
        return False
    try:
        decoded = b64url_decode(str(token))
        prefix, signature = decoded[:-32], decoded[-32:]
        payload = prefix.decode("utf-8").rstrip(":")
        token_subject, expires_text = payload.rsplit(":", 1)
        expires_at = int(expires_text)
    except Exception:
        return False
    if not _link_secrets.compare_text(str(subject_id), str(token_subject)):
        return False
    if expires_at < int(time_module.time()):
        return False
    try:
        candidates = _link_secrets.verification_secrets(purpose)
    except _link_secrets.LinkSecretUnavailable:
        return False
    matched = False
    for secret in candidates:
        expected = hmac.new(secret, payload.encode("utf-8"), hashlib.sha256).digest()
        # No early exit: every candidate is compared so timing does not reveal
        # which key matched or how many keys are configured.
        matched = _link_secrets.compare(expected, signature) or matched
    return matched


def verify_assessment_token(attempt_id: str, token: str | None) -> bool:
    return _verify_link_signature("assessment", attempt_id, token)


def assessment_public_link(attempt_id: str, raw_token: str) -> str:
    if not raw_token:
        raise ValueError("assessment_public_link_requires_raw_token")
    return f"{assessment_public_base_url()}/assessment/{attempt_id}?token={urllib.parse.quote(raw_token)}"


def sign_video_interview_token(interview_id: str, expires_at: int) -> str:
    payload = f"{interview_id}:{expires_at}"
    signature = hmac.new(video_interview_link_secret(), payload.encode("utf-8"), hashlib.sha256).digest()
    return b64url_encode(f"{payload}:".encode("utf-8") + signature)


def verify_video_interview_token(interview_id: str, token: str | None) -> bool:
    return _verify_link_signature("video_interview", interview_id, token)


def video_interview_public_link(interview_id: str, *, ttl_days: int = 14) -> tuple[str, datetime]:
    if not link_signing_available("video_interview"):
        raise link_signing_unavailable_error("video_interview")
    ttl_seconds = max(1, ttl_days) * 24 * 60 * 60
    expires_at_epoch = int(time_module.time() + ttl_seconds)
    expires_at = datetime.fromtimestamp(expires_at_epoch, tz=timezone.utc)
    token = sign_video_interview_token(str(interview_id), expires_at_epoch)
    return f"{video_interview_public_base_url()}/video-interview/{interview_id}?token={urllib.parse.quote(token)}", expires_at


def assessment_attempt_by_id(attempt_id: str, company_code: str) -> dict[str, Any] | None:
    company = str(company_code or "").strip().upper()
    if not company:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM assessment_attempts WHERE attempt_id=%s AND company_code=%s LIMIT 1",
                (attempt_id, company),
            )
            row = cur.fetchone()
    return dict(row) if row else None


def public_assessment_item_payload(item: dict[str, Any] | None) -> dict[str, Any] | None:
    if not item:
        return None
    choices = item.get("choices") if isinstance(item.get("choices"), list) else []
    return {
        "item_id": item.get("item_id"),
        "item_order": item.get("item_order"),
        "section": item.get("section"),
        "prompt_text": item.get("prompt_text"),
        "choices": [{"key": choice.get("key"), "text": choice.get("text")} for choice in choices if isinstance(choice, dict)],
    }


def assessment_authority_http_error(exc: Exception) -> HTTPException:
    import assessment_lifecycle as _assessment_lifecycle

    if isinstance(exc, _assessment_lifecycle.AssessmentAuthorityError):
        return HTTPException(status_code=exc.status_code, detail=exc.as_detail())
    return HTTPException(status_code=409, detail={"error": "assessment_authority_error", "message": str(exc)})


def public_assessment_state(attempt_id: str, token: str | None, *, start: bool = False) -> dict[str, Any]:
    import assessment_lifecycle as _assessment_lifecycle
    import assessment_service as _assessment_service

    expired = False
    started = False
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                attempt, token_row = _assessment_service.validate_take_token(
                    cur,
                    attempt_id=attempt_id,
                    raw_token=token,
                    for_update=start,
                )
                if not company_has_module(attempt.get("company_code"), "assessments"):
                    raise HTTPException(
                        status_code=403,
                        detail={
                            "error": "module_disabled",
                            "message": "This link is no longer available. Please contact the hiring team if you need a new link.",
                        },
                    )
                attempt = _assessment_service.expire_attempt_if_due(cur, attempt)
                expired = attempt.get("status") == "expired"
                if not expired and start and attempt.get("status") == "pending":
                    cur.execute(
                        """
                        UPDATE assessment_attempts
                        SET status='in_progress', started_at=COALESCE(started_at,now()),
                            progress_version=progress_version+1, updated_at=now()
                        WHERE attempt_id=%s AND company_code=%s AND status='pending'
                        RETURNING *
                        """,
                        (attempt_id, attempt.get("company_code")),
                    )
                    updated = cur.fetchone()
                    if updated:
                        attempt = dict(updated)
                        started = True
                        _assessment_lifecycle.record_event(
                            cur,
                            attempt_id=attempt_id,
                            company_code=str(attempt.get("company_code")),
                            event_type="started",
                            actor_type="candidate",
                            from_status="pending",
                            to_status="in_progress",
                        )
                    cur.execute(
                        "UPDATE assessment_tokens SET used_at=COALESCE(used_at,now()) WHERE token_id=%s",
                        (token_row.get("token_id"),),
                    )
                version = _assessment_service.content_version_by_id(
                    cur,
                    str(attempt.get("assessment_version_id") or ""),
                    company_code=str(attempt.get("company_code") or ""),
                )
                if not version:
                    raise _assessment_lifecycle.AssessmentAuthorityError(
                        "assessment_version_missing",
                        "This attempt is not pinned to an assessment version.",
                    )
                item = _assessment_service.version_item_at(
                    version,
                    int(attempt.get("current_item_index") or 0),
                )
            conn.commit()
    except HTTPException:
        raise
    except Exception as exc:
        raise assessment_authority_http_error(exc) from exc
    if expired:
        raise HTTPException(
            status_code=409,
            detail=assessment_error_envelope("attempt_expired"),
        )
    if started:
        update_application_assessment_snapshot(
            str(attempt.get("app_key") or ""),
            str(attempt.get("company_code") or ""),
            {
                "attempt_id": str(attempt.get("attempt_id")),
                "assessment_version_id": str(attempt.get("assessment_version_id")),
                "status": "in_progress",
                "delivery_status": attempt.get("delivery_status"),
                "review_status": attempt.get("review_status"),
                "battery_key": attempt.get("battery_key"),
                "started_at": json_safe(attempt.get("started_at")),
            },
        )
    answered = int(attempt.get("current_item_index") or 0)
    total = int(attempt.get("total_items") or 0)
    raw = attempt.get("raw_json") if isinstance(attempt.get("raw_json"), dict) else {}
    locale = str(raw.get("locale") or "en").strip().lower()
    if locale not in {"en", "ar"}:
        locale = "en"
    status = str(attempt.get("status") or "")
    needs_begin = status == "pending" and not start
    return {
        "ok": True,
        "attempt": {
            "attempt_id": str(attempt.get("attempt_id")),
            "status": attempt.get("status"),
            "candidate_name": attempt.get("candidate_name"),
            "position_title": attempt.get("position_title"),
            "current_item_index": answered,
            "total_items": total,
            "percent_complete": round((answered / total) * 100, 1) if total else 0,
            "progress_version": int(attempt.get("progress_version") or 0),
            "expires_at": json_safe(attempt.get("expires_at")),
            "locale": locale,
        },
        "locale": locale,
        "dir": "rtl" if locale == "ar" else "ltr",
        "needs_begin": needs_begin,
        "item": None if needs_begin else public_assessment_item_payload(item),
        "completed": False,
    }


def create_or_resume_assessment_attempt(
    app: dict[str, Any],
    *,
    source: str,
    requested_by: str | None = None,
    battery_key: str | None = None,
    expires_days: int | None = None,
    locale: str | None = None,
) -> dict[str, Any]:
    import assessment_lifecycle as _assessment_lifecycle
    import assessment_service as _assessment_service

    company = str(app.get("company_code") or "").strip().upper()
    app_key = str(app.get("app_key") or "").strip()
    contact = candidate_contact(app)
    phone = digits(contact.get("phone"))
    if not company:
        return {"ok": False, "error": "tenant_scope_required"}
    # Defence in depth: every caller is already entitled, but the module owns its
    # own writes so a new caller cannot create attempts for a disabled tenant.
    if not company_has_module(company, "assessments"):
        return {"ok": False, "error": "module_disabled", "required_module": "assessments"}
    if not app_key or not phone:
        return {"ok": False, "error": "missing_candidate_contact", "candidate": contact}
    battery = resolve_assessment_battery(company, battery_key=battery_key)
    if not battery:
        return {
            "ok": False,
            "error": "missing_active_assessment_battery" if not battery_key else "assessment_battery_not_selectable",
            "candidate": contact,
            "battery_key": battery_key,
        }
    seed = hashlib.sha256(f"{app_key}:{battery['battery_key']}:v1".encode("utf-8")).hexdigest()[:16]
    created = False
    ttl_days = _assessment_lifecycle.DEFAULT_ATTEMPT_TTL_DAYS
    if expires_days is not None:
        try:
            ttl_days = max(1, min(60, int(expires_days)))
        except (TypeError, ValueError):
            ttl_days = _assessment_lifecycle.DEFAULT_ATTEMPT_TTL_DAYS
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT app_key, company_code, phone
                FROM applications
                WHERE app_key=%s AND company_code=%s
                FOR SHARE
                """,
                (app_key, company),
            )
            bound_app = cur.fetchone()
            if not bound_app:
                return {"ok": False, "error": "tenant_application_binding_failed", "candidate": contact}
            if digits(bound_app.get("phone")) != phone:
                return {"ok": False, "error": "tenant_candidate_binding_failed", "candidate": contact}
            cur.execute(
                """
                SELECT *
                FROM assessment_attempts
                WHERE company_code=%s AND app_key=%s
                  AND status IN ('pending','in_progress')
                ORDER BY created_at DESC
                LIMIT 1
                FOR UPDATE
                """,
                (company, app_key),
            )
            existing_row = cur.fetchone()
            existing = dict(existing_row) if existing_row else None
            if existing:
                existing = _assessment_service.expire_attempt_if_due(cur, existing)
            if existing and existing.get("status") in _assessment_lifecycle.OPEN_ATTEMPT_STATUSES:
                attempt = existing
                resumed = True
            else:
                cur.execute(
                    """
                    SELECT *
                    FROM assessment_content_versions
                    WHERE battery_key=%s AND company_code IN (%s,'GLOBAL')
                    ORDER BY CASE WHEN company_code=%s THEN 0 ELSE 1 END,
                             content_version DESC, created_at DESC
                    LIMIT 1
                    """,
                    (battery["battery_key"], company, company),
                )
                version_row = cur.fetchone()
                version = dict(version_row) if version_row else _assessment_service.freeze_current_content_version(
                    cur,
                    company_code=company,
                    battery_key=str(battery["battery_key"]),
                    created_by_user_id=requested_by,
                )
                items = _assessment_service.version_items(version)
                expires_at = datetime.now(timezone.utc) + timedelta(days=ttl_days)
                battery_raw = battery.get("raw_json") if isinstance(battery.get("raw_json"), dict) else {}
                attempt_locale = str(locale or battery_raw.get("locale") or "en").strip().lower()
                if attempt_locale not in {"en", "ar"}:
                    attempt_locale = "en"
                cur.execute(
                    """
                    INSERT INTO assessment_attempts
                    (company_code, app_key, phone, candidate_name, position_code, position_title,
                     battery_key, assessment_version_id, status, current_item_index, total_items,
                     random_seed, expires_at, raw_json)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,'pending',0,%s,%s,%s,%s)
                    ON CONFLICT (company_code, app_key)
                      WHERE status IN ('pending','in_progress')
                    DO NOTHING
                    RETURNING *
                    """,
                    (
                        company,
                        app_key,
                        phone,
                        contact.get("name"),
                        app.get("position_code"),
                        app.get("position_title") or app.get("position_code"),
                        battery["battery_key"],
                        version["assessment_version_id"],
                        len(items),
                        seed,
                        expires_at,
                        Json(
                            {
                                "source": source,
                                "requested_by": requested_by,
                                "candidate": contact,
                                "locale": attempt_locale,
                                "approved_for_use_status": battery_raw.get("approved_for_use_status"),
                                "scores_are_supporting_evidence_only": True,
                                "expires_days": ttl_days,
                            }
                        ),
                    ),
                )
                inserted = cur.fetchone()
                if inserted:
                    attempt = dict(inserted)
                    resumed = False
                    created = True
                    _assessment_lifecycle.record_event(
                        cur,
                        attempt_id=str(attempt["attempt_id"]),
                        company_code=company,
                        event_type="created",
                        actor_type="human" if requested_by else "system",
                        actor_user_id=requested_by,
                        to_status="pending",
                        payload={
                            "source": source,
                            "assessment_version_id": str(version["assessment_version_id"]),
                            "content_sha256": version.get("content_sha256"),
                        },
                    )
                else:
                    cur.execute(
                        """
                        SELECT * FROM assessment_attempts
                        WHERE company_code=%s AND app_key=%s
                          AND status IN ('pending','in_progress')
                        LIMIT 1
                        """,
                        (company, app_key),
                    )
                    attempt = dict(cur.fetchone())
                    resumed = True
        conn.commit()
    if created:
        update_application_assessment_snapshot(
            app_key,
            company,
            {
                "attempt_id": str(attempt.get("attempt_id")),
                "assessment_version_id": str(attempt.get("assessment_version_id")),
                "status": "pending",
                "delivery_status": attempt.get("delivery_status"),
                "review_status": attempt.get("review_status"),
                "battery_key": attempt.get("battery_key"),
                "expires_at": json_safe(attempt.get("expires_at")),
                "sent_at": None,
            },
        )
    return {"ok": True, "attempt": json_safe(attempt), "candidate": contact, "resumed": resumed}


def assessment_next_item(attempt: dict[str, Any]) -> dict[str, Any] | None:
    import assessment_service as _assessment_service

    version_id = str(attempt.get("assessment_version_id") or "")
    company = str(attempt.get("company_code") or "")
    if not version_id or not company:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            version = _assessment_service.content_version_by_id(cur, version_id, company_code=company)
    return _assessment_service.version_item_at(version, int(attempt.get("current_item_index") or 0))


def start_assessment_attempt(attempt_id: str, company_code: str, token: str) -> dict[str, Any] | None:
    state = public_assessment_state(attempt_id, token, start=True)
    return assessment_attempt_by_id(attempt_id, company_code) if state.get("ok") else None


def _complete_assessment_locked(
    cur: Any,
    attempt: dict[str, Any],
    version: dict[str, Any],
) -> dict[str, Any]:
    import assessment_lifecycle as _assessment_lifecycle
    import assessment_service as _assessment_service

    attempt_id = str(attempt.get("attempt_id"))
    company = str(attempt.get("company_code") or "").upper()
    if attempt.get("status") == "completed":
        cur.execute("SELECT * FROM assessment_scores WHERE attempt_id=%s", (attempt_id,))
        score = dict(cur.fetchone() or {})
        cur.execute("SELECT * FROM assessment_reports WHERE attempt_id=%s", (attempt_id,))
        report_row = dict(cur.fetchone() or {})
        return {
            "attempt": attempt,
            "score": score,
            "report": report_row,
            "report_json": report_row.get("report_json") or score.get("score_json") or {},
        }
    if attempt.get("status") != "in_progress":
        raise _assessment_lifecycle.AssessmentAuthorityError(
            f"attempt_{attempt.get('status')}",
            "Only an in-progress assessment can be completed.",
        )
    items = _assessment_service.version_items(version)
    cur.execute(
        "SELECT * FROM assessment_responses WHERE attempt_id=%s ORDER BY item_order ASC",
        (attempt_id,),
    )
    responses = [dict(row) for row in cur.fetchall()]
    if len(responses) != len(items) or int(attempt.get("current_item_index") or 0) != len(items):
        raise _assessment_lifecycle.AssessmentAuthorityError(
            "assessment_incomplete",
            "All version-pinned items must be answered before completion.",
        )
    report = build_assessment_report_json(
        attempt=attempt,
        items=items,
        responses=responses,
        norm_lookup=_assessment_service.version_norm_lookup(version),
    )
    raw_score = float(report["raw_score"])
    max_score = float(report["max_score"])
    percent = float(report["percent"])
    band = str(report["band"])
    section_totals = report["section_scores"]
    report_digest = _assessment_lifecycle.content_digest({"report": report})
    cur.execute(
        """
        INSERT INTO assessment_scores
          (attempt_id, raw_score, max_score, percent, band, section_scores,
           norm_version, score_json, assessment_version_id, immutable)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,TRUE)
        ON CONFLICT (attempt_id) DO NOTHING
        RETURNING *
        """,
        (
            attempt_id,
            raw_score,
            max_score,
            percent,
            band,
            Json(json_safe(section_totals)),
            version.get("norm_version"),
            Json(json_safe(report)),
            version.get("assessment_version_id"),
        ),
    )
    score_row = cur.fetchone()
    if score_row:
        score = dict(score_row)
    else:
        cur.execute("SELECT * FROM assessment_scores WHERE attempt_id=%s", (attempt_id,))
        score = dict(cur.fetchone() or {})
        existing_digest = _assessment_lifecycle.content_digest({"report": score.get("score_json") or {}})
        if existing_digest != report_digest or not score.get("immutable"):
            raise _assessment_lifecycle.AssessmentAuthorityError(
                "immutable_score_conflict",
                "An immutable score already exists with different evidence.",
            )
    cur.execute(
        """
        INSERT INTO assessment_reports
          (attempt_id, report_json, assessment_version_id, immutable)
        VALUES (%s,%s,%s,TRUE)
        ON CONFLICT (attempt_id) DO NOTHING
        RETURNING *
        """,
        (attempt_id, Json(json_safe(report)), version.get("assessment_version_id")),
    )
    report_row_result = cur.fetchone()
    if report_row_result:
        report_row = dict(report_row_result)
    else:
        cur.execute("SELECT * FROM assessment_reports WHERE attempt_id=%s", (attempt_id,))
        report_row = dict(cur.fetchone() or {})
        existing_digest = _assessment_lifecycle.content_digest({"report": report_row.get("report_json") or {}})
        if existing_digest != report_digest or not report_row.get("immutable"):
            raise _assessment_lifecycle.AssessmentAuthorityError(
                "immutable_report_conflict",
                "An immutable report already exists with different evidence.",
            )
    cur.execute(
        """
        UPDATE assessment_attempts
        SET status='completed', completed_at=COALESCE(completed_at,now()), updated_at=now()
        WHERE attempt_id=%s AND company_code=%s AND status='in_progress'
        RETURNING *
        """,
        (attempt_id, company),
    )
    completed_row = cur.fetchone()
    if not completed_row:
        raise _assessment_lifecycle.AssessmentAuthorityError(
            "completion_race",
            "Assessment completion state changed concurrently.",
        )
    completed_attempt = dict(completed_row)
    _assessment_lifecycle.revoke_active_tokens(
        cur,
        attempt_id=attempt_id,
        company_code=company,
        reason="attempt_completed",
        actor_type="candidate",
    )
    _assessment_lifecycle.record_event(
        cur,
        attempt_id=attempt_id,
        company_code=company,
        event_type="completed",
        actor_type="candidate",
        from_status="in_progress",
        to_status="completed",
        payload={
            "assessment_version_id": str(version.get("assessment_version_id")),
            "report_sha256": report_digest,
            "percent": percent,
        },
    )
    return {
        "attempt": completed_attempt,
        "score": score,
        "report": report_row,
        "report_json": report,
    }


def record_assessment_response(
    *,
    attempt_id: str,
    company_code: str,
    raw_token: str,
    item_id: str,
    response_text: str | None,
    selected_key: str,
    progress_version: int | None = None,
) -> dict[str, Any]:
    import assessment_lifecycle as _assessment_lifecycle
    import assessment_service as _assessment_service

    company = str(company_code or "").upper()
    selected = str(selected_key or "").upper()
    expired = False
    completed: dict[str, Any] | None = None
    idempotent = False
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                attempt, _token = _assessment_service.validate_take_token(
                    cur,
                    attempt_id=attempt_id,
                    raw_token=raw_token,
                    company_code=company,
                    for_update=True,
                )
                attempt = _assessment_service.expire_attempt_if_due(cur, attempt)
                expired = attempt.get("status") == "expired"
                if not expired:
                    if attempt.get("status") == "pending":
                        cur.execute(
                            """
                            UPDATE assessment_attempts
                            SET status='in_progress', started_at=COALESCE(started_at,now()),
                                progress_version=progress_version+1, updated_at=now()
                            WHERE attempt_id=%s AND company_code=%s AND status='pending'
                            RETURNING *
                            """,
                            (attempt_id, company),
                        )
                        attempt = dict(cur.fetchone())
                        _assessment_lifecycle.record_event(
                            cur,
                            attempt_id=attempt_id,
                            company_code=company,
                            event_type="started",
                            actor_type="candidate",
                            from_status="pending",
                            to_status="in_progress",
                        )
                    version = _assessment_service.content_version_by_id(
                        cur,
                        str(attempt.get("assessment_version_id") or ""),
                        company_code=company,
                    )
                    if not version:
                        raise _assessment_lifecycle.AssessmentAuthorityError(
                            "assessment_version_missing",
                            "This attempt is not pinned to an assessment version.",
                        )
                    cur.execute(
                        """
                        SELECT * FROM assessment_responses
                        WHERE attempt_id=%s AND item_id=%s
                        """,
                        (attempt_id, item_id),
                    )
                    existing_response = cur.fetchone()
                    if existing_response:
                        response = dict(existing_response)
                        if str(response.get("selected_key") or "").upper() != selected:
                            raise _assessment_lifecycle.AssessmentAuthorityError(
                                "idempotency_conflict",
                                "This item was already answered with different content.",
                            )
                        idempotent = True
                    else:
                        expected_index = int(attempt.get("current_item_index") or 0)
                        item = _assessment_service.version_item_at(version, expected_index)
                        if not item or str(item.get("item_id")) != str(item_id):
                            raise _assessment_lifecycle.AssessmentAuthorityError(
                                "stale_progress",
                                "The submitted item is not the next expected item.",
                                extra={
                                    "expected_item_id": str((item or {}).get("item_id") or ""),
                                    "progress_version": int(attempt.get("progress_version") or 0),
                                },
                            )
                        if progress_version is not None and progress_version != int(attempt.get("progress_version") or 0):
                            raise _assessment_lifecycle.AssessmentAuthorityError(
                                "stale_progress",
                                "Assessment progress changed before this answer was submitted.",
                                extra={"progress_version": int(attempt.get("progress_version") or 0)},
                            )
                        valid_keys = {
                            str(choice.get("key") or "").upper()
                            for choice in (item.get("choices") or [])
                            if isinstance(choice, dict)
                        }
                        if selected not in valid_keys:
                            raise _assessment_lifecycle.AssessmentAuthorityError(
                                "invalid_assessment_answer",
                                "Selected answer is not valid for this item.",
                                status_code=422,
                            )
                        score, is_correct = selected_item_score(item, selected)
                        scoring = item_scoring(item)
                        cur.execute(
                            """
                            INSERT INTO assessment_responses
                              (attempt_id, company_code, assessment_version_id,
                               item_id, item_content_version, item_order, response_text,
                               selected_key, answer_key_snapshot, scoring_snapshot,
                               is_correct, score_numeric, is_final, raw_json)
                            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,TRUE,%s)
                            ON CONFLICT (attempt_id, item_id) DO NOTHING
                            RETURNING *
                            """,
                            (
                                attempt_id,
                                company,
                                version.get("assessment_version_id"),
                                item.get("item_id"),
                                int(item.get("content_version") or version.get("content_version") or 1),
                                int(item.get("item_order") or expected_index + 1),
                                response_text,
                                selected,
                                item.get("answer_key"),
                                Json(json_safe(scoring)),
                                is_correct,
                                score,
                                Json({
                                    "section": item.get("section"),
                                    "max_score": item_max_score(item),
                                    "competencies": scoring.get("competencies") if isinstance(scoring.get("competencies"), dict) else {},
                                }),
                            ),
                        )
                        inserted = cur.fetchone()
                        if not inserted:
                            cur.execute(
                                "SELECT * FROM assessment_responses WHERE attempt_id=%s AND item_id=%s",
                                (attempt_id, item_id),
                            )
                            response = dict(cur.fetchone())
                            idempotent = True
                        else:
                            response = dict(inserted)
                            cur.execute(
                                """
                                UPDATE assessment_attempts
                                SET current_item_index=current_item_index+1,
                                    progress_version=progress_version+1,
                                    updated_at=now()
                                WHERE attempt_id=%s AND company_code=%s
                                  AND status='in_progress' AND current_item_index=%s
                                RETURNING *
                                """,
                                (attempt_id, company, expected_index),
                            )
                            updated = cur.fetchone()
                            if not updated:
                                raise _assessment_lifecycle.AssessmentAuthorityError(
                                    "concurrent_progress_conflict",
                                    "Assessment progress changed concurrently.",
                                )
                            attempt = dict(updated)
                            _assessment_lifecycle.record_event(
                                cur,
                                attempt_id=attempt_id,
                                company_code=company,
                                event_type="answered",
                                actor_type="candidate",
                                payload={
                                    "item_id": str(item.get("item_id")),
                                    "item_order": int(item.get("item_order") or 0),
                                    "progress_version": int(attempt.get("progress_version") or 0),
                                },
                            )
                    if int(attempt.get("current_item_index") or 0) == int(attempt.get("total_items") or 0):
                        completed = _complete_assessment_locked(cur, attempt, version)
                        attempt = completed["attempt"]
            conn.commit()
    except Exception as exc:
        raise assessment_authority_http_error(exc) from exc
    if expired:
        raise HTTPException(status_code=409, detail=assessment_error_envelope("attempt_expired"))
    result = {
        "response": json_safe(response),
        "attempt": json_safe(attempt),
        "idempotent": idempotent,
        "completed": bool(completed),
    }
    if completed:
        result.update({
            "score": json_safe(completed["score"]),
            "report": json_safe(completed["report"]),
            "report_json": json_safe(completed["report_json"]),
        })
    snapshot: dict[str, Any] = {
        "attempt_id": attempt_id,
        "assessment_version_id": str(attempt.get("assessment_version_id")),
        "status": attempt.get("status"),
        "delivery_status": attempt.get("delivery_status"),
        "review_status": attempt.get("review_status"),
        "battery_key": attempt.get("battery_key"),
        "expires_at": json_safe(attempt.get("expires_at")),
        "started_at": json_safe(attempt.get("started_at")),
    }
    if completed:
        report_json = completed["report_json"]
        snapshot.update({
            "raw_score": report_json.get("raw_score"),
            "max_score": report_json.get("max_score"),
            "percent": report_json.get("percent"),
            "band": report_json.get("band"),
            "section_scores": report_json.get("section_scores"),
            "ability_scores": report_json.get("ability_scores"),
            "competency_profile": report_json.get("competency_profile"),
            "job_match": report_json.get("job_match"),
            "summary": report_json.get("summary"),
            "completed_at": json_safe(attempt.get("completed_at")),
        })
    update_application_assessment_snapshot(
        str(attempt.get("app_key") or ""),
        company,
        snapshot,
    )
    return result


def complete_assessment_attempt(attempt: dict[str, Any]) -> dict[str, Any]:
    import assessment_lifecycle as _assessment_lifecycle
    import assessment_service as _assessment_service

    attempt_id = str(attempt.get("attempt_id") or "")
    company = str(attempt.get("company_code") or "").upper()
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM assessment_attempts WHERE attempt_id=%s AND company_code=%s FOR UPDATE",
                (attempt_id, company),
            )
            locked = cur.fetchone()
            if not locked:
                raise assessment_authority_http_error(
                    _assessment_lifecycle.AssessmentAuthorityError(
                        "assessment_attempt_not_found",
                        "Assessment attempt was not found for this tenant.",
                        status_code=404,
                    )
                )
            locked_attempt = dict(locked)
            version = _assessment_service.content_version_by_id(
                cur,
                str(locked_attempt.get("assessment_version_id") or ""),
                company_code=company,
            )
            if not version:
                raise assessment_authority_http_error(
                    _assessment_lifecycle.AssessmentAuthorityError(
                        "assessment_version_missing",
                        "This attempt is not pinned to an assessment version.",
                    )
                )
            completed = _complete_assessment_locked(cur, locked_attempt, version)
        conn.commit()
    return json_safe(completed)


def cancel_assessment_attempt(
    attempt: dict[str, Any],
    *,
    reason: str,
    actor_type: str,
    actor_user_id: str | None = None,
) -> dict[str, Any]:
    import assessment_lifecycle as _assessment_lifecycle
    import assessment_service as _assessment_service

    attempt_id = str(attempt.get("attempt_id") or "")
    company = str(attempt.get("company_code") or "").upper()
    expired = False
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM assessment_attempts WHERE attempt_id=%s AND company_code=%s FOR UPDATE",
                (attempt_id, company),
            )
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail={"error": "assessment_attempt_not_found"})
            locked = _assessment_service.expire_attempt_if_due(cur, dict(row))
            expired = locked.get("status") == "expired"
            if not expired:
                if locked.get("status") not in _assessment_lifecycle.OPEN_ATTEMPT_STATUSES:
                    raise HTTPException(
                        status_code=409,
                        detail={"error": f"attempt_{locked.get('status')}"},
                    )
                cur.execute(
                    """
                    UPDATE assessment_attempts
                    SET status='cancelled', cancelled_at=COALESCE(cancelled_at,now()),
                        cancel_reason=%s, updated_at=now()
                    WHERE attempt_id=%s AND company_code=%s
                      AND status IN ('pending','in_progress')
                    RETURNING *
                    """,
                    (reason, attempt_id, company),
                )
                cancelled = dict(cur.fetchone())
                _assessment_lifecycle.revoke_active_tokens(
                    cur,
                    attempt_id=attempt_id,
                    company_code=company,
                    reason="attempt_cancelled",
                    actor_type=actor_type,
                    actor_user_id=actor_user_id,
                )
                _assessment_lifecycle.record_event(
                    cur,
                    attempt_id=attempt_id,
                    company_code=company,
                    event_type="cancelled",
                    actor_type=actor_type,
                    actor_user_id=actor_user_id,
                    from_status=str(locked.get("status")),
                    to_status="cancelled",
                    payload={"reason": reason},
                )
            else:
                cancelled = locked
        conn.commit()
    if expired:
        raise HTTPException(status_code=409, detail=assessment_error_envelope("attempt_expired"))
    update_application_assessment_snapshot(
        str(cancelled.get("app_key") or ""),
        company,
        {
            "attempt_id": attempt_id,
            "assessment_version_id": str(cancelled.get("assessment_version_id")),
            "status": "cancelled",
            "delivery_status": cancelled.get("delivery_status"),
            "review_status": cancelled.get("review_status"),
            "battery_key": cancelled.get("battery_key"),
            "cancelled_at": json_safe(cancelled.get("cancelled_at")),
            "cancel_reason": cancelled.get("cancel_reason"),
        },
    )
    return json_safe(cancelled)


def handle_candidate_assessment_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    import assessment_lifecycle as _assessment_lifecycle
    import assessment_service as _assessment_service

    if has_current_media_upload(request.media or {}):
        return None
    company = active_company_code()
    open_attempts = open_assessment_attempts_for_phone(request.sender_phone, company)
    if not open_attempts:
        return None
    text = (request.raw_text or "").strip()
    normalized = normalize_text(text)
    attempt: dict[str, Any] | None = None
    if len(open_attempts) > 1:
        choice = None
        if normalized.isdigit():
            choice = int(normalized)
        else:
            role_match = next(
                (
                    item
                    for item in open_attempts
                    if normalize_text(str(item.get("position_title") or item.get("position_code") or "")) == normalized
                ),
                None,
            )
            if role_match:
                attempt = role_match
        if choice is not None and 1 <= choice <= len(open_attempts):
            attempt = open_attempts[choice - 1]
        if attempt is None:
            lines = []
            for index, item in enumerate(open_attempts, start=1):
                role = str(item.get("position_title") or item.get("position_code") or f"Role {index}").strip()
                lines.append(f"{index}. {role}")
            return {
                "reply": (
                    "You have more than one open assessment. Reply with the number for the role you want to continue:\n"
                    + "\n".join(lines)
                ),
                "attempts": json_safe(open_attempts),
                "intent": "assessment_role_clarification",
                "turn_focus": "candidate_assessment",
                "needs_clarification": True,
            }
    else:
        attempt = open_attempts[0]
    if not attempt:
        return None
    if not company_has_module(attempt.get("company_code"), "assessments"):
        return {
            "reply": candidate_safe_module_unavailable_reply(),
            "attempt": json_safe(attempt),
            "module_disabled": "assessments",
        }
    if normalized in {"cancel", "stop", "exit"}:
        cancelled = cancel_assessment_attempt(
            attempt,
            reason="candidate_cancelled_via_whatsapp",
            actor_type="candidate",
        )
        return {
            "reply": "Assessment cancelled. OctoHR can send it again if needed.",
            "attempt": cancelled,
            "intent": "cancel_assessment",
            "turn_focus": "candidate_assessment",
        }
    expired = False
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM assessment_attempts WHERE attempt_id=%s AND company_code=%s FOR UPDATE",
                (attempt.get("attempt_id"), company),
            )
            locked = dict(cur.fetchone())
            locked = _assessment_service.expire_attempt_if_due(cur, locked, actor_type="system")
            expired = locked.get("status") == "expired"
            if not expired:
                token_expiry = min(
                    locked.get("expires_at") or (datetime.now(timezone.utc) + timedelta(days=14)),
                    datetime.now(timezone.utc) + timedelta(days=14),
                )
                raw_token, token_row = _assessment_lifecycle.issue_token(
                    cur,
                    attempt_id=str(locked.get("attempt_id")),
                    company_code=str(company),
                    expires_at=token_expiry,
                )
                invitation = _assessment_service.create_invitation(
                    cur,
                    attempt_id=str(locked.get("attempt_id")),
                    company_code=str(company),
                    app_key=str(locked.get("app_key")),
                    channel="whatsapp",
                    token_id=str(token_row.get("token_id")),
                    message_kind="assessment_reminder",
                    status="sent",
                    metadata={
                        "source": "candidate_whatsapp_status",
                        "account_id": request.account_id,
                        "conversation_id": request.conversation_id,
                    },
                )
                cur.execute(
                    "UPDATE assessment_invitations SET sent_at=now(), updated_at=now() WHERE invitation_id=%s",
                    (invitation.get("invitation_id"),),
                )
                cur.execute(
                    "UPDATE assessment_attempts SET delivery_status='sent', updated_at=now() WHERE attempt_id=%s RETURNING *",
                    (locked.get("attempt_id"),),
                )
                attempt = dict(cur.fetchone())
                _assessment_lifecycle.record_event(
                    cur,
                    attempt_id=str(attempt.get("attempt_id")),
                    company_code=str(company),
                    event_type="delivery_updated",
                    actor_type="candidate",
                    payload={"channel": "whatsapp", "status": "sent", "message_kind": "assessment_reminder"},
                )
                link = assessment_public_link(str(attempt.get("attempt_id")), raw_token)
        conn.commit()
    if expired:
        return {
            "reply": "This assessment has expired. Please contact OctoHR for a new invitation.",
            "attempt": json_safe(locked),
            "intent": "assessment_expired",
            "turn_focus": "candidate_assessment",
        }
    answered = int(attempt.get("current_item_index") or 0)
    total = int(attempt.get("total_items") or 0)
    return {
        "reply": (
            f"Continue your assessment in your browser ({answered}/{total} answered):\n{link}\n\n"
            "WhatsApp does not accept assessment answers. Reply CANCEL if you want to cancel the attempt."
        ),
        "attempt": json_safe(attempt),
        "intent": "assessment_browser_link",
        "turn_focus": "candidate_assessment",
    }


def deliver_assessment_invitation(
    app: dict[str, Any],
    attempt: dict[str, Any],
    account_id: str | None,
    *,
    note: str | None,
    message_kind: str,
    requested_by: str | None,
) -> dict[str, Any]:
    try:
        assert_application_communication_allowed(app, kind="assessment_resend" if message_kind == "assessment_resend" else "assessment")  # HELD_COMMUNICATION_AUTHORITY_STAGING_PATCH
    except CandidateCommunicationAuthorityError as exc:
        return exc.as_result()
    import assessment_lifecycle as _assessment_lifecycle
    import assessment_service as _assessment_service

    company = str(attempt.get("company_code") or app.get("company_code") or "").upper()
    attempt_id = str(attempt.get("attempt_id") or "")
    app_key = str(attempt.get("app_key") or app.get("app_key") or "")
    invitation_rows: dict[str, dict[str, Any]] = {}
    expired = False
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM assessment_attempts WHERE attempt_id=%s AND company_code=%s FOR UPDATE",
                (attempt_id, company),
            )
            row = cur.fetchone()
            if not row:
                return {"ok": False, "error": "tenant_attempt_binding_failed"}
            locked = _assessment_service.expire_attempt_if_due(cur, dict(row))
            expired = locked.get("status") == "expired"
            if not expired:
                if locked.get("status") not in _assessment_lifecycle.OPEN_ATTEMPT_STATUSES:
                    return {"ok": False, "error": f"attempt_{locked.get('status')}"}
                if message_kind == "assessment_resend":
                    _assessment_lifecycle.revoke_active_tokens(
                        cur,
                        attempt_id=attempt_id,
                        company_code=company,
                        reason="assessment_resent",
                        actor_type="human",
                        actor_user_id=requested_by,
                    )
                token_expiry = min(
                    locked.get("expires_at") or (datetime.now(timezone.utc) + timedelta(days=14)),
                    datetime.now(timezone.utc) + timedelta(days=14),
                )
                raw_token, token_row = _assessment_lifecycle.issue_token(
                    cur,
                    attempt_id=attempt_id,
                    company_code=company,
                    expires_at=token_expiry,
                    actor_user_id=requested_by,
                )
                for channel in ("email", "whatsapp"):
                    invitation_rows[channel] = _assessment_service.create_invitation(
                        cur,
                        attempt_id=attempt_id,
                        company_code=company,
                        app_key=app_key,
                        channel=channel,
                        token_id=str(token_row.get("token_id")),
                        message_kind=message_kind,
                        metadata={"account_id": account_id},
                    )
                _assessment_lifecycle.record_event(
                    cur,
                    attempt_id=attempt_id,
                    company_code=company,
                    event_type="resent" if message_kind == "assessment_resend" else "invited",
                    actor_type="human",
                    actor_user_id=requested_by,
                    payload={
                        "message_kind": message_kind,
                        "token_id": str(token_row.get("token_id")),
                        "channels": ["email", "whatsapp"],
                    },
                )
                link = assessment_public_link(attempt_id, raw_token)
                attempt = locked
        conn.commit()
    if expired:
        return {"ok": False, **assessment_error_envelope("attempt_expired"), "attempt": json_safe(locked)}
    contact = candidate_contact(app)
    title = contact.get("position_title") or "the role"
    candidate_template = candidate_message_payload(
        "assessment_invitation",
        application=app,
        role=title,
        link=link,
    )
    body = candidate_template["text"]
    delivery = candidate_communication_router(
        app,
        account_id=account_id,
        kind="assessment",
        message=body,
        action={
            "purpose": "assessment",
            "email_subject": "Application Assessment",
            "message_text": body,
            "send_both": True,
            "assessment_link": link,
            "candidate_template": candidate_template,
            "note": str(note or "").strip() or None,
        },
    )
    import outbound_send_result as _osr
    send_result = _osr.build_send_result(
        kind="assessment",
        recipient=contact,
        delivery=delivery,
        ok=bool(delivery.get("ok")),
    )
    channel_attempts = {
        str(row.get("channel")): row
        for row in (delivery.get("attempts") or [])
        if isinstance(row, dict) and row.get("channel")
    }
    dry_run = delivery_is_dry_run()
    statuses: list[str] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            for channel, invitation in invitation_rows.items():
                delivery_attempt = channel_attempts.get(channel) or {}
                if dry_run:
                    status = "intentionally_skipped"
                else:
                    # Provider accept is not candidate delivery confirmation.
                    status = "sent" if delivery_attempt.get("ok") else "failed"
                statuses.append(status)
                result_payload = delivery_attempt.get("result") if isinstance(delivery_attempt.get("result"), dict) else {}
                outbound_event_id = (
                    result_payload.get("event_id")
                    or (result_payload.get("send") or {}).get("event_id")
                    if isinstance(result_payload, dict)
                    else None
                )
                _assessment_service.update_invitation_delivery(
                    cur,
                    invitation_id=str(invitation.get("invitation_id")),
                    company_code=company,
                    status=status,
                    outbound_event_id=str(outbound_event_id) if outbound_event_id else None,
                    last_error=str(delivery_attempt.get("error") or "") or None,
                    metadata={"delivery_result": json_safe(delivery_attempt)},
                )
            if "sent" in statuses or "send_accepted" in statuses:
                aggregate_status = "sent"
            elif "intentionally_skipped" in statuses:
                aggregate_status = "intentionally_skipped"
            elif "queued" in statuses:
                aggregate_status = "queued"
            else:
                aggregate_status = "failed"
            cur.execute(
                """
                UPDATE assessment_attempts
                SET delivery_status=%s, updated_at=now()
                WHERE attempt_id=%s AND company_code=%s
                RETURNING *
                """,
                (aggregate_status, attempt_id, company),
            )
            attempt = dict(cur.fetchone())
            _assessment_lifecycle.record_event(
                cur,
                attempt_id=attempt_id,
                company_code=company,
                event_type="delivery_updated",
                actor_type="system",
                payload={"status": aggregate_status, "channels": statuses, "message_kind": message_kind},
            )
        conn.commit()
    update_application_assessment_snapshot(
        app_key,
        company,
        {
            "attempt_id": attempt_id,
            "assessment_version_id": str(attempt.get("assessment_version_id")),
            "status": attempt.get("status"),
            "delivery_status": attempt.get("delivery_status"),
            "review_status": attempt.get("review_status"),
            "battery_key": attempt.get("battery_key"),
            "expires_at": json_safe(attempt.get("expires_at")),
            "sent_at": now_iso(),
        },
    )
    aggregate = str(attempt.get("delivery_status") or "")
    if send_result["state"] != "partially_sent":
        send_result["state"] = {
            "send_accepted": "sent",
            "sent": "sent",
            "delivered": "sent",
            "queued": "queued",
            "intentionally_skipped": "queued",
            "failed": "failed",
        }.get(aggregate, send_result["state"])
    send_result["ok"] = send_result["state"] in {"sent", "partially_sent", "queued"}
    return {
        "ok": bool(delivery.get("ok")) or dry_run or send_result["ok"],
        "send": delivery,
        "delivery": delivery,
        "delivery_status": attempt.get("delivery_status"),
        "message": body,
        "candidate_template": candidate_template,
        "assessment_link": link,
        "candidate": contact,
        "attempt": json_safe(attempt),
        "invitations": json_safe(list(invitation_rows.values())),
        "send_result": json_safe(send_result),
    }


def send_assessment(
    app: dict[str, Any],
    account_id: str | None,
    *,
    note: str | None = None,
    requested_by: str | None = None,
    battery_key: str | None = None,
    expires_days: int | None = None,
    locale: str | None = None,
) -> dict[str, Any]:
    app_status = str(app.get("status") or "").strip().lower()
    if app_status in {"hired", "rejected", "withdrawn", "closed"}:
        return {
            "ok": False,
            "error": "terminal_application",
            "status": app_status,
            "safe_user_message": f"Cannot send an assessment for an application that is already {app_status}.",
        }
    selected_battery_key = str(battery_key or "").strip() or None
    selected_locale = str(locale or "").strip().lower() or None
    if selected_locale and not selected_battery_key:
        locale_map = {
            "en": "wathefni_gawj_v1_en_beta",
            "ar": "wathefni_gawj_v1_ar_beta",
        }
        selected_battery_key = locale_map.get(selected_locale)
    attempt_result = create_or_resume_assessment_attempt(
        app,
        source="dashboard_or_hr_action",
        requested_by=requested_by,
        battery_key=selected_battery_key,
        expires_days=expires_days,
        locale=selected_locale,
    )
    if not attempt_result.get("ok"):
        return attempt_result
    attempt = attempt_result.get("attempt") if isinstance(attempt_result.get("attempt"), dict) else {}
    result = deliver_assessment_invitation(
        app,
        attempt,
        account_id,
        note=note,
        message_kind="assessment_resend" if attempt_result.get("resumed") else "assessment_invite",
        requested_by=requested_by,
    )
    result["resumed"] = attempt_result.get("resumed", False)
    return result


def resend_assessment(
    app: dict[str, Any],
    attempt: dict[str, Any],
    account_id: str | None,
    *,
    note: str | None = None,
    requested_by: str | None = None,
) -> dict[str, Any]:
    current_status = str(attempt.get("status") or "").strip().lower()
    if current_status == "completed":
        return {"ok": False, **assessment_error_envelope("already_sent"), "safe_user_message": "This assessment is already completed and cannot be resent."}
    if current_status == "expired":
        # Expired attempts need a replacement flow, not delivery on the dead attempt.
        return send_assessment(
            app,
            account_id,
            note=note,
            requested_by=requested_by,
        )
    return deliver_assessment_invitation(
        app,
        attempt,
        account_id,
        note=note,
        message_kind="assessment_resend",
        requested_by=requested_by,
    )


DOCUMENT_LABELS = {
    "civil_id": "Civil ID front and back",
    "passport": "passport photo page",
    "personal_photo": "personal photo",
    "bank_details": "bank setup via Employee Self-Service (encrypted)",
    "work_permit": "work permit",
    "employment_contract": "signed employment contract",
}


def missing_employee_documents(employee: dict[str, Any]) -> list[str]:
    employee_key = employee.get("employee_key")
    if not employee_key:
        return []
    company = str(employee.get("company_code") or "").strip().upper() or None
    items = load_onboarding_items(employee_key=str(employee_key), company_code=company)
    out: list[str] = []
    for item in items:
        if item.get("required") is not True:
            continue
        if str(item.get("item_id") or "") == "bank_details":
            continue
        import onboarding_completion_contract as _completion

        if str(item.get("status") or "").lower() in set(_completion.EMPLOYEE_ACTION_STATUSES):
            out.append(str(item.get("document_type") or item.get("item_id") or ""))
    return [x for x in out if x]


def onboarding_company_for_employee(employee_key: str, *, cur: Any | None = None) -> str | None:
    """Resolve the owning company for an employee from the employee hub.

    Used so onboarding reads can stay tenant-scoped when a caller forgot to pass
    a company, instead of silently running unscoped.
    """
    key = str(employee_key or "").strip()
    if not key:
        return None

    def _fetch(active_cur: Any) -> str | None:
        active_cur.execute("SELECT company_code FROM employees WHERE employee_key=%s LIMIT 1", (key,))
        row = active_cur.fetchone()
        if not row:
            return None
        return str(row["company_code"] or "").strip().upper() or None

    if cur is not None:
        return _fetch(cur)
    with db_connect() as conn:
        with conn.cursor() as active_cur:
            return _fetch(active_cur)


def load_onboarding_items(
    *,
    employee_key: str,
    company_code: str | None = None,
    cur: Any | None = None,
) -> list[dict[str, Any]]:
    """Single authority for checklist reads (list/detail/app/profile/summary).

    Always joins `employees` AND always filters by company. When the caller does
    not supply a company we resolve it from the employee hub rather than dropping
    the filter; an employee we cannot attribute to a tenant yields no items.
    Masks bank/IBAN plaintext in `value` (ESS owns bank data).
    """
    key = str(employee_key or "").strip()
    if not key:
        return []
    company = str(company_code or "").strip().upper() or None
    if not company:
        company = onboarding_company_for_employee(key, cur=cur)
    if not company:
        return []

    def _fetch(active_cur: Any) -> list[dict[str, Any]]:
        sql_full = """
                SELECT oi.item_id, oi.label, oi.item_type, oi.required, oi.document_type, oi.status, oi.value,
                       oi.storage_provider, oi.storage_status, oi.storage_url, oi.drive_url,
                       oi.reminder_count, oi.last_reminded_at, oi.escalated_at, oi.updated_at,
                       oi.category, oi.owner, oi.sort_order, oi.row_version, oi.due_date, oi.depends_on,
                       oi.collection_mode, oi.authority, oi.template_version, e.company_code,
                       oi.employee_key,
                       oi.rejection_reason, oi.completed_at, oi.lifecycle_meta
                FROM onboarding_items oi
                JOIN employees e ON e.employee_key = oi.employee_key
                WHERE oi.employee_key=%s {company_clause}
                ORDER BY oi.required DESC NULLS LAST, oi.sort_order ASC NULLS LAST, oi.created_at ASC
                """
        sql_legacy = """
                SELECT oi.item_id, oi.label, oi.item_type, oi.required, oi.document_type, oi.status, oi.value,
                       oi.storage_provider, oi.storage_status, oi.storage_url, oi.drive_url,
                       oi.reminder_count, oi.last_reminded_at, oi.escalated_at, oi.updated_at,
                       oi.category, oi.owner, oi.sort_order, oi.row_version, oi.due_date, oi.depends_on,
                       oi.collection_mode, oi.authority, oi.template_version, e.company_code,
                       oi.employee_key
                FROM onboarding_items oi
                JOIN employees e ON e.employee_key = oi.employee_key
                WHERE oi.employee_key=%s {company_clause}
                ORDER BY oi.required DESC NULLS LAST, oi.sort_order ASC NULLS LAST, oi.created_at ASC
                """
        # Company is guaranteed non-empty by the caller guard above, so the
        # tenant clause is unconditional. `oi.company_code` is checked too once
        # the row carries it, so a mis-stamped row cannot ride the join across.
        clause = "AND e.company_code=%s AND COALESCE(oi.company_code, e.company_code)=%s"
        params: tuple[Any, ...] = (key, company, company)
        # Pre-column databases have no oi.company_code; the join filter alone
        # still enforces tenant there.
        legacy_clause = "AND e.company_code=%s"
        legacy_params: tuple[Any, ...] = (key, company)
        try:
            active_cur.execute(sql_full.format(company_clause=clause), params)
            rows = [dict(r) for r in (active_cur.fetchall() or [])]
        except Exception:
            active_cur.connection.rollback()
            active_cur.execute(sql_legacy.format(company_clause=legacy_clause), legacy_params)
            rows = [dict(r) for r in (active_cur.fetchall() or [])]
        return [mask_onboarding_item_for_read(row) for row in rows]

    if cur is not None:
        return _fetch(cur)
    with db_connect() as conn:
        with conn.cursor() as active_cur:
            out = _fetch(active_cur)
        conn.commit()
    return out


def mask_onboarding_item_for_read(item: dict[str, Any]) -> dict[str, Any]:
    """Never surface plaintext IBAN/bank payloads from checklist value."""
    row = dict(item)
    item_id = str(row.get("item_id") or row.get("document_type") or "").strip().lower()
    raw_value = str(row.get("value") or "")
    if item_id == "bank_details" or (raw_value and text_has_iban(raw_value)):
        if raw_value:
            row["value"] = None
            row["value_redacted"] = True
        row["bank_collection"] = "ess_encrypted"
    return json_safe(row)


def onboarding_plaintext_bank_forbidden(item_id: str | None, value: str | None = None) -> bool:
    """Wave 1 freeze: block new plaintext bank/IBAN collection via onboarding."""
    iid = str(item_id or "").strip().lower()
    if iid == "bank_details":
        return True
    if value and text_has_iban(value):
        return True
    return False


def employee_onboarding_items(
    employee_key: str,
    *,
    company_code: str | None = None,
) -> list[dict[str, Any]]:
    """Canonical checklist read — returns onboarding_items rows only (tenant-safe)."""
    return load_onboarding_items(employee_key=employee_key, company_code=company_code)


def is_item_complete(item: dict[str, Any]) -> bool:
    status = str(item.get("status") or "").lower()
    if status in {"accepted", "complete", "completed", "verified", "approved", "reviewed", "waived"}:
        return True
    # Legacy ambiguous receipt: only count as complete when Wave 2A lifecycle is OFF
    # for this tenant/employee (otherwise received maps to processing / not final).
    if status == "received":
        try:
            import onboarding_lifecycle_wave2a as _lc

            if _lc.lifecycle_enabled(
                company_code=str(item.get("company_code") or "") or None,
                employee_key=str(item.get("employee_key") or "") or None,
            ):
                return False
        except Exception:
            pass
        return True
    return False


def onboarding_item_counts_from_rows(items: list[dict[str, Any]]) -> dict[str, int]:
    """Counts must match SQL used by onboarding_counts_by_employee / recompute."""
    required = [item for item in items if item.get("required") is True]
    received = [item for item in required if is_item_complete(item)]
    closed = {"waived", "cancelled_onboarding", "abandoned_employment_ended", "retired_legacy"}
    pending = [
        item
        for item in required
        if not is_item_complete(item) and str(item.get("status") or "").lower() not in closed
    ]
    return {
        "required_total": len(required),
        "received_count": len(received),
        "pending_count": len(pending),
    }


def item_display_label(item: dict[str, Any] | str) -> str:
    if isinstance(item, dict):
        key = str(item.get("document_type") or item.get("item_id") or "")
        label = str(item.get("label") or "").strip()
        return label or DOCUMENT_LABELS.get(key, key.replace("_", " ") if key else "item")
    return DOCUMENT_LABELS.get(str(item), str(item).replace("_", " "))


def employee_onboarding_summary(
    employee: dict[str, Any],
    *,
    company_code: str | None = None,
) -> dict[str, Any]:
    company = str(company_code or employee.get("company_code") or "").strip().upper() or None
    key = str(employee.get("employee_key") or "")
    items = load_onboarding_items(employee_key=key, company_code=company)
    counts = onboarding_item_counts_from_rows(items)
    required = [item for item in items if item.get("required") is True]
    received = [item for item in required if is_item_complete(item)]
    pending = [
        item
        for item in required
        if not is_item_complete(item)
        and str(item.get("status") or "").lower()
        not in {"waived", "cancelled_onboarding", "abandoned_employment_ended", "retired_legacy"}
    ]
    # Enrich open items with dependency blockers for HR UX.
    import onboarding_completion_contract as _completion
    import onboarding_lifecycle_wave2a as _lc_own

    by_id = {str(i.get("item_id")): i for i in items if i.get("item_id")}
    for item in items:
        blockers = _onboarding_wave2.dependency_blockers(item, by_id)
        if blockers:
            item["blocked_by"] = blockers
            item["blocked_reason"] = "Complete prerequisites first: " + ", ".join(blockers)
        # Owner group for UX rails
        item["owner_group"] = onboarding_owner_group(item)
        # Who must act now, which is not always who owns the rail.
        item["responsible_party"] = _lc_own.responsible_party(item)
    assignment = None
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                assignment = _onboarding_wave2.get_assignment(cur, key)
            conn.commit()
    except Exception:
        assignment = None
    planned = None
    if assignment and assignment.get("planned_start_date"):
        planned = assignment.get("planned_start_date")
    elif employee.get("start_date"):
        planned = employee.get("start_date")
    overdue = []
    today = kuwait_today()
    for item in pending:
        due = item.get("due_date")
        if due is None:
            continue
        due_d = due if hasattr(due, "isoformat") else None
        try:
            if due_d is None:
                from datetime import date as _date

                due_d = _date.fromisoformat(str(due)[:10])
            if due_d < today:
                overdue.append(item)
        except Exception:
            pass
    # Selected from every item, not just `pending`, and by the contract's own
    # rule: the queue, the drawer and the app must name the same one item.
    next_item = _completion.select_next_item(items)

    # Canonical completion — the single value every surface must render.
    completion = _completion.compute_completion(
        items,
        previously_completed=bool((assignment or {}).get("completed_at")),
        assignment_status=(assignment or {}).get("status"),
    )
    completion["next_action"] = _completion.next_action(completion)

    migration_overlay = None
    try:
        import employee_migration_onboarding as _omo

        migration_overlay = _omo.projection_overlay(
            company=require_company_code(company or employee.get("company_code")),
            employee_key=key,
            locale="en",
        )
        if migration_overlay and migration_overlay.get("settled") and not migration_overlay.get("native_superseded"):
            completion = {
                **completion,
                "state": "completed",
                "is_complete": True,
                "reason": f"migration_{migration_overlay.get('disposition')}",
                "migration": migration_overlay,
                "suppress_checklist": True,
                "suppress_reminders": True,
                "open_count": 0,
                "required_total": 0,
                "satisfied_count": 0,
            }
            completion["next_action"] = _completion.next_action(completion)
            counts = {"required_total": 0, "received_count": 0, "pending_count": 0}
            pending = []
            overdue = []
            next_item = None
    except Exception:
        migration_overlay = None

    return {
        "employee_key": employee.get("employee_key"),
        "name": employee.get("name"),
        "phone": employee.get("phone"),
        "company_code": company or employee.get("company_code"),
        "status": (assignment or {}).get("status") or employee.get("onboarding_status"),
        "completion": completion,
        "completion_state": completion["state"],
        "onboarding_migration": migration_overlay,
        "planned_start_date": planned.isoformat() if hasattr(planned, "isoformat") else planned,
        "template_version": employee.get("onboarding_template_version")
        or (assignment or {}).get("template_version"),
        "required_total": counts["required_total"],
        "received_count": counts["received_count"],
        "pending_count": counts["pending_count"],
        "overdue_count": len(overdue),
        "next_owner": ((next_item or {}).get("responsible_party") or (next_item or {}).get("owner")) if next_item else None,
        "next_owner_group": (
            _RESPONSIBLE_TO_OWNER_GROUP.get(str((next_item or {}).get("responsible_party") or ""))
            or onboarding_owner_group(next_item)
        ) if next_item else None,
        "next_item_label": item_display_label(next_item) if next_item else None,
        # Surfaced for queue primary-action derivation (existing columns only).
        "next_item_status": (next_item or {}).get("status") if next_item else None,
        "next_item_storage_status": (next_item or {}).get("storage_status") if next_item else None,
        "items": items,
        "received": received,
        "pending": pending,
        "received_labels": [item_display_label(item) for item in received],
        "pending_labels": [item_display_label(item) for item in pending],
        "bank_collection": {
            "mode": "ess_encrypted",
            "plaintext_forbidden": True,
            "message": "Bank and IBAN setup uses encrypted Employee Self-Service — not onboarding plaintext.",
        },
    }


def onboarding_owner_group(item: dict[str, Any] | None) -> str:
    """Map checklist rows to Employee / HR / IT / Payroll / Compliance rails."""
    if not item:
        return "hr"
    authority = str(item.get("authority") or "").lower()
    category = str(item.get("category") or "").lower()
    owner = str(item.get("owner") or "").lower()
    item_id = str(item.get("item_id") or "").lower()
    if authority == "ess" or category == "payroll_bank" or item_id in {"bank_details", "salary_transfer_details", "payroll_status", "salary_allowances_confirmed"}:
        return "payroll"
    if authority == "compliance_mirror" or category == "compliance_gov":
        return "compliance"
    if item_id in {
        "account_access_created",
        "attendance_device_id",
        "access_card_issued",
        "asset_handover",
        "app_invite_sent",
    }:
        return "it"
    if owner == "employee":
        return "employee"
    if owner == "system":
        return "compliance" if "expiry" in item_id else "hr"
    return "hr"


# `onboarding_owner_group` names the data rail that owns an item (bank lives on
# the payroll rail). Who must act next is a different question, so the queue maps
# canonical responsibility instead.
_RESPONSIBLE_TO_OWNER_GROUP = {
    "employee": "employee",
    "hr": "hr",
    "compliance": "compliance",
    "payroll": "payroll",
    "system": "hr",
}


def onboarding_queue_enrichment(company_code: str, employee_keys: list[str]) -> dict[str, dict[str, Any]]:
    """Batch planned start / overdue / next-owner for the onboarding queue."""
    if not employee_keys:
        return {}
    today = kuwait_today()
    out: dict[str, dict[str, Any]] = {k: {} for k in employee_keys}
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT employee_key, planned_start_date, status, template_version
                FROM employee_onboarding_assignments
                WHERE company_code=%s AND employee_key = ANY(%s)
                """,
                (company_code, list(employee_keys)),
            )
            for row in cur.fetchall() or []:
                key = str(row["employee_key"])
                planned = row.get("planned_start_date")
                out[key]["planned_start_date"] = planned.isoformat() if hasattr(planned, "isoformat") else planned
                out[key]["assignment_status"] = row.get("status")
                out[key]["template_version"] = row.get("template_version")
            # Bank ESS owns `bank_details`; align it before reading so the queue
            # cannot show a state the drawer and employee app disagree with.
            try:
                import employee_bank_ess as _bank_sync

                _bank_sync.ensure_bank_ess_schema(cur)
                for key in employee_keys:
                    _bank_sync.reconcile_onboarding_bank_item(
                        cur, company_code=company_code, employee_key=key
                    )
            except Exception:
                logger.exception("onboarding queue bank reconcile failed company=%s", company_code)
            cur.execute(
                """
                SELECT employee_key, item_id, label, owner, authority, category, status, storage_status,
                       required, due_date, depends_on, collection_mode, lifecycle_meta
                FROM onboarding_items
                WHERE employee_key = ANY(%s)
                ORDER BY required DESC NULLS LAST, sort_order ASC NULLS LAST, created_at ASC
                """,
                (list(employee_keys),),
            )
            by_emp: dict[str, list[dict[str, Any]]] = {}
            for row in cur.fetchall() or []:
                by_emp.setdefault(str(row["employee_key"]), []).append(dict(row))
            completion_rows: dict[str, dict[str, Any]] = {}
            try:
                cur.execute(
                    """
                    SELECT employee_key, first_completed_at
                    FROM employee_onboarding_completion
                    WHERE company_code=%s AND employee_key = ANY(%s)
                    """,
                    (str(company_code or "").upper(), list(employee_keys)),
                )
                for row in cur.fetchall() or []:
                    completion_rows[str(row["employee_key"])] = dict(row)
            except Exception:
                completion_rows = {}
        conn.commit()
    import onboarding_completion_contract as _completion
    import onboarding_lifecycle_wave2a as _lc

    closed = set(_completion.CLOSED_STATUSES)
    for key, items in by_emp.items():
        by_id = {str(i["item_id"]): i for i in items}
        overdue = 0
        for item in items:
            st = str(item.get("status") or "").lower()
            blockers = _onboarding_wave2.dependency_blockers(item, by_id)
            item["blocked_by"] = blockers or []
            item["responsible_party"] = _lc.responsible_party(item)
            if not item.get("required") or st in closed:
                continue
            due = item.get("due_date")
            try:
                if due is not None:
                    due_d = due if hasattr(due, "toordinal") else __import__("datetime").date.fromisoformat(str(due)[:10])
                    if due_d < today:
                        overdue += 1
            except Exception:
                pass

        next_item = _completion.select_next_item(items)

        out.setdefault(key, {})
        out[key]["overdue_count"] = overdue
        snapshot = _completion.compute_completion(
            items,
            previously_completed=bool((completion_rows.get(key) or {}).get("first_completed_at")),
            assignment_status=out[key].get("assignment_status"),
        )
        out[key]["completion_state"] = snapshot["state"]
        out[key]["completion_next_action"] = _completion.next_action(snapshot)
        out[key]["satisfied_count"] = snapshot["satisfied_count"]
        out[key]["open_count"] = snapshot["open_count"]
        if next_item:
            # Canonical ownership, not the raw template `owner` column or the data
            # rail: a bank change sent back for correction is waiting on the
            # employee, even though Bank ESS/payroll owns the rail.
            responsible = str(next_item.get("responsible_party") or "")
            out[key]["next_owner"] = responsible or next_item.get("owner")
            out[key]["next_owner_group"] = _RESPONSIBLE_TO_OWNER_GROUP.get(
                responsible
            ) or onboarding_owner_group(next_item)
            out[key]["next_item_label"] = next_item.get("label") or next_item.get("item_id")
            out[key]["next_item_status"] = next_item.get("status")
            out[key]["next_item_storage_status"] = next_item.get("storage_status")
    return out


ONBOARDING_HR_MARK_STATES = {"accepted", "waived", "received"}


def mark_onboarding_item(action: dict[str, Any], *, company_code: str | None, created_by_phone: str | None) -> dict[str, Any]:
    """HR-side resolution of a single onboarding checklist item.

    Wave 2A (lifecycle flag on for employee):
      * accepted — HR confirms the item (never writes ambiguous legacy ``received``)
      * waived   — HR waives the requirement
    Legacy (flag off):
      * received / waived via mark_item_wave2
    Always recomputes the employee's onboarding rollup. Gated upstream by the
    WATHEFNI_ONBOARDING_HR_MUTATE flag + onboarding.manage + confirmation.
    """
    company = require_company_code(company_code)
    employee = find_employee_by_key(action.get("employee_key"), company_code=company) or resolve_employee_for_direct_action(action, allow_latest=False)
    if not employee:
        return {"ok": False, "error": "employee_not_found", "safe_user_message": "I need the employee before I can update a checklist item."}
    if str(employee.get("company_code") or company).upper() != company:
        # The fallback resolver is not company-bound; refuse rather than write
        # a checklist item that belongs to another tenant.
        return {"ok": False, "error": "employee_company_mismatch", "safe_user_message": "I could not find that employee in this workspace."}
    gate = onboarding_mutation_gate_error(employee)
    if gate is not None:
        return gate
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "safe_user_message": "That employee is outside your manager scope."}
    item_id = str(action.get("item_id") or "").strip()
    if not item_id:
        return {"ok": False, "error": "needs_clarification", "safe_user_message": "Which checklist item should I update?"}
    new_status = normalize_text(action.get("item_status") or "accepted") or "accepted"
    if new_status not in ONBOARDING_HR_MARK_STATES:
        new_status = "accepted"
    employee_key = str(employee.get("employee_key") or "")
    import onboarding_lifecycle_wave2a as _lc

    lifecycle_on = _lc.lifecycle_enabled(company_code=company, employee_key=employee_key)
    # Never persist ambiguous legacy received under Wave 2A.
    if lifecycle_on and new_status == "received":
        new_status = "accepted"
    if item_id == "bank_details" and action.get("value") and onboarding_plaintext_bank_forbidden(item_id, str(action.get("value"))):
        return {
            "ok": False,
            "error": "bank_via_ess_required",
            "safe_user_message": "Bank and IBAN must be set through encrypted Employee Self-Service.",
        }
    expected_version = action.get("expected_row_version")
    if expected_version is not None:
        try:
            expected_version = int(expected_version)
        except Exception:
            expected_version = None
    with db_connect() as conn:
        with conn.cursor() as cur:
            if lifecycle_on:
                _lc.ensure_lifecycle_schema(cur)
                cur.execute(
                    """
                    SELECT oi.*, e.onboarding_status AS emp_onboarding_status
                    FROM onboarding_items oi
                    JOIN employees e ON e.employee_key = oi.employee_key
                    WHERE oi.employee_key=%s AND oi.item_id=%s AND e.company_code=%s
                    LIMIT 1
                    """,
                    (employee_key, item_id, company),
                )
                row = cur.fetchone()
                if not row:
                    conn.rollback()
                    return {"ok": False, "error": "item_not_found", "safe_user_message": "I could not find that checklist item."}
                item = dict(row)
                if str(item.get("emp_onboarding_status") or "") in {"cancelled_onboarding", "abandoned_employment_ended"}:
                    conn.rollback()
                    return {"ok": False, "error": "onboarding_terminal", "safe_user_message": "Onboarding is closed for this employee."}
                if expected_version is not None and int(item.get("row_version") or 1) != expected_version:
                    conn.rollback()
                    return {"ok": False, "error": "stale_item_version", "item": item, "safe_user_message": "That checklist item was updated elsewhere. Refresh and try again."}
                if new_status == "accepted":
                    cur.execute(
                        "SELECT item_id, status, required FROM onboarding_items WHERE employee_key=%s AND company_code=%s",
                        (employee_key, company),
                    )
                    catalog = {str(r["item_id"]): dict(r) for r in (cur.fetchall() or [])}
                    blockers = _onboarding_wave2.dependency_blockers(item, catalog)
                    if blockers:
                        conn.rollback()
                        return {"ok": False, "error": "dependency_unsatisfied", "blockers": blockers, "safe_user_message": f"Complete prerequisites first: {', '.join(blockers)}."}
                    try:
                        import onboarding_civil_id_dual_side as _dual

                        if _dual.dual_side_applies(
                            company_code=company, employee_key=employee_key, item_id=item_id
                        ):
                            _dual.ensure_dual_side_schema(cur)
                            doc_lane = str(item.get("document_type") or item_id)
                            if item_id == _dual.CANARY_ITEM:
                                doc_lane = _dual.CANARY_ITEM
                            cur.execute(
                                """
                                SELECT * FROM governed_document_versions
                                WHERE company_code=%s AND employee_key=%s AND document_type=%s
                                ORDER BY
                                  CASE review_status
                                    WHEN 'pending_hr_review' THEN 0
                                    WHEN 'draft_parts' THEN 1
                                    ELSE 2
                                  END,
                                  version_no DESC
                                LIMIT 1
                                """,
                                (company, employee_key, doc_lane),
                            )
                            ver = cur.fetchone()
                            if ver:
                                _dual.assert_version_approvable(cur, dict(ver))
                    except Exception as exc:
                        if getattr(exc, "code", None):
                            conn.rollback()
                            return {
                                "ok": False,
                                "error": str(getattr(exc, "code")),
                                "safe_user_message": str(
                                    getattr(exc, "message_en", None)
                                    or getattr(exc, "message", None)
                                    or "Both Civil ID sides are required before approval."
                                ),
                            }
                        raise
                target = _lc.STATE_WAIVED if new_status == "waived" else _lc.STATE_ACCEPTED
                meta_patch = {"source": "hr_mark", "actor": "dashboard"}
                if new_status == "waived":
                    cur.execute(
                        """
                        UPDATE onboarding_items
                        SET required=FALSE, row_version=row_version+1
                        WHERE employee_key=%s AND item_id=%s
                          AND COALESCE(company_code, %s)=%s
                        """,
                        (employee_key, item_id, company, company),
                    )
                else:
                    cur.execute(
                        """
                        UPDATE onboarding_items
                        SET row_version=row_version+1
                        WHERE employee_key=%s AND item_id=%s
                          AND COALESCE(company_code, %s)=%s
                        """,
                        (employee_key, item_id, company, company),
                    )
                _lc.set_item_lifecycle(
                    cur,
                    employee_key=employee_key,
                    item_id=item_id,
                    new_status=target,
                    clear_rejection=True,
                    meta_patch=meta_patch,
                )
                cur.execute(
                    "SELECT * FROM onboarding_items WHERE employee_key=%s AND item_id=%s LIMIT 1",
                    (employee_key, item_id),
                )
                after = dict(cur.fetchone() or {})
                event_id = _onboarding_wave2.record_onboarding_audit(
                    cur,
                    company_code=company,
                    employee_key=employee_key,
                    item_id=item_id,
                    event_type=f"onboarding_item_{target}",
                    actor_phone=created_by_phone or action.get("viewer_phone"),
                    actor_user_id=action.get("actor_user_id"),
                    before=item,
                    after=after,
                )
                result = {"ok": True, "item": after, "audit_event_id": event_id}
            else:
                # Legacy path — still uses received/waived writers for non-canary tenants.
                legacy_status = "waived" if new_status == "waived" else "received"
                result = _onboarding_wave2.mark_item_wave2(
                    cur,
                    employee_key=employee_key,
                    company_code=company,
                    item_id=item_id,
                    new_status=legacy_status,
                    expected_row_version=expected_version,
                    actor_phone=created_by_phone or action.get("viewer_phone"),
                    actor_user_id=action.get("actor_user_id"),
                )
                if not result.get("ok"):
                    conn.rollback()
                    err = result.get("error")
                    if err == "stale_item_version":
                        return {**result, "safe_user_message": "That checklist item was updated elsewhere. Refresh and try again."}
                    if err == "dependency_unsatisfied":
                        return {**result, "safe_user_message": f"Complete prerequisites first: {', '.join(result.get('blockers') or [])}."}
                    if err == "onboarding_terminal":
                        return {**result, "safe_user_message": "Onboarding is closed for this employee."}
                    if err == "item_not_found":
                        return {**result, "safe_user_message": "I could not find that checklist item."}
                    return {**result, "safe_user_message": "Could not update that checklist item."}
                new_status = legacy_status
            recompute_employee_onboarding_counts(cur, employee_key)
            cur.execute(
                "SELECT onboarding_status FROM employees WHERE employee_key=%s AND company_code=%s LIMIT 1",
                (employee_key, company),
            )
            st = str((cur.fetchone() or {}).get("onboarding_status") or "")
            if st == "completed":
                asg = _onboarding_wave2.get_assignment(cur, employee_key)
                if asg and str(asg.get("status")) != "completed":
                    cur.execute(
                        """
                        UPDATE employee_onboarding_assignments
                        SET status='completed', completed_at=now(), version=version+1, updated_at=now()
                        WHERE employee_key=%s
                        """,
                        (employee_key,),
                    )
                    _onboarding_wave2.record_onboarding_audit(
                        cur,
                        company_code=company,
                        employee_key=employee_key,
                        event_type="onboarding_completed",
                        actor_phone=created_by_phone or action.get("viewer_phone"),
                        after={"onboarding_status": "completed"},
                    )
        conn.commit()
    item = json_safe(dict(result.get("item") or {}))
    label = item_display_label({"document_type": item.get("document_type"), "label": item.get("label"), "item_id": item.get("item_id")})
    return {
        "ok": True,
        "employee": json_safe(posthire_employee_card(employee)),
        "item": item,
        "item_label": label,
        "item_status": new_status if lifecycle_on else new_status,
        "audit_event_id": result.get("audit_event_id"),
    }


def cancel_employee_onboarding(
    action: dict[str, Any],
    *,
    company_code: str | None,
    created_by_phone: str | None = None,
) -> dict[str, Any]:
    company = require_company_code(company_code)
    employee = find_employee_by_key(action.get("employee_key"), company_code=company)
    if not employee:
        return {"ok": False, "error": "employee_not_found"}
    gate = onboarding_mutation_gate_error(employee)
    if gate is not None:
        return gate
    if action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope"}
    expected = action.get("expected_version")
    try:
        expected_i = int(expected) if expected is not None else None
    except Exception:
        expected_i = None
    with db_connect() as conn:
        with conn.cursor() as cur:
            result = _onboarding_wave2.cancel_onboarding(
                cur,
                employee,
                reason=str(action.get("reason") or "") or None,
                expected_version=expected_i,
                actor_phone=created_by_phone or action.get("viewer_phone"),
            )
            if not result.get("ok"):
                conn.rollback()
                return result
        conn.commit()
    return result


