def required_module_for_action(action_type: str | None) -> str | None:
    return ACTION_REQUIRED_MODULES.get(str(action_type or ""))


def operational_module_for_action(action_type: str | None) -> str:
    action = str(action_type or "")
    if action == "retry_last_failed_action":
        return "RETRY"
    if action in SHARED_COMMUNICATION_ACTIONS:
        return "COMMUNICATIONS"
    module = required_module_for_action(action)
    if module:
        return module.upper()
    if action.startswith("answer_"):
        return "STATUS"
    if "reminder" in action or "message" in action or "notify" in action:
        return "COMMUNICATION"
    return "OPERATIONS"


def operational_wording_enabled() -> bool:
    return os.environ.get("WATHEFNI_OPERATIONAL_WORDING_ENABLED", "true").strip().lower() not in {"0", "false", "off", "no"}


def walk_operational_values(value: Any, key_path: str = "") -> list[tuple[str, Any]]:
    out: list[tuple[str, Any]] = []
    if isinstance(value, dict):
        for key, item in value.items():
            path = f"{key_path}.{key}" if key_path else str(key)
            out.extend(walk_operational_values(item, path))
    elif isinstance(value, list):
        for idx, item in enumerate(value[:20]):
            out.extend(walk_operational_values(item, f"{key_path}[{idx}]"))
    else:
        out.append((key_path, value))
    return out


def unique_limited(values: list[str], limit: int = 6) -> list[str]:
    seen: set[str] = set()
    out: list[str] = []
    for value in values:
        cleaned = re.sub(r"\s+", " ", str(value or "")).strip()
        key = normalize_text(cleaned)
        if not cleaned or key in seen:
            continue
        seen.add(key)
        out.append(cleaned)
        if len(out) >= limit:
            break
    return out


def operational_fact_bundle(action_type: str, status: str, result_payload: dict[str, Any], template_reply: str) -> dict[str, Any]:
    names: list[str] = []
    dates: list[str] = []
    statuses: list[str] = []
    emails: list[str] = []
    module = operational_module_for_action(action_type)
    for path, value in walk_operational_values(result_payload):
        lower_path = path.lower()
        leaf = re.sub(r"\[\d+\]", "", lower_path).split(".")[-1]
        if any(part in lower_path for part in ("metadata", "raw_json", "source_text", "operational_wording")):
            continue
        if value is None:
            continue
        if isinstance(value, str):
            if leaf in {"name", "employee_name", "candidate_name"} and len(value) <= 120:
                names.append(value)
            if module == "PRE_HIRING" and "email" in lower_path and "@" in value:
                emails.append(value)
            if leaf == "status" and len(value) <= 80 and not lower_path.startswith("employee."):
                statuses.append(value)
            if leaf in {"attendance_date", "shift_date"} and parse_iso_date(value):
                dates.append(value)
            elif lower_path in {"start_date", "end_date", "leave.start_date", "leave.end_date", "attendance.start_date", "attendance.end_date"} and parse_iso_date(value):
                dates.append(value)
        elif isinstance(value, date) and not isinstance(value, datetime):
            if leaf in {"attendance_date", "shift_date", "start_date", "end_date"}:
                dates.append(value.isoformat())
    template_dates = re.findall(r"\b\d{4}-\d{2}-\d{2}\b", template_reply or "")
    dates.extend(template_dates)
    if status:
        statuses.append(status)
    if action_type == "mark_attendance_absent" and isinstance(result_payload, dict) and result_payload.get("error") == "approved_leave_exists":
        statuses.extend(["approved leave", "absent"])
    return {
        "module": module,
        "action_type": action_type,
        "status": status,
        "names": unique_limited(names, limit=5),
        "dates": unique_limited(dates, limit=4),
        "statuses": unique_limited(statuses, limit=5),
        "emails": unique_limited(emails, limit=4),
        "backend_reply": template_reply,
        "grounded_payload": compact_grounded_payload(result_payload),
    }


def compact_grounded_payload(value: Any, *, depth: int = 0) -> Any:
    if depth > 4:
        return None
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, str):
        text = value.strip()
        return text[:1200] + "..." if len(text) > 1200 else text
    if isinstance(value, list):
        return [compact_grounded_payload(item, depth=depth + 1) for item in value[:8]]
    if isinstance(value, dict):
        out: dict[str, Any] = {}
        for key, item in value.items():
            key_text = str(key)
            lowered = key_text.lower()
            if lowered in {"raw_json", "metadata", "provider_payload", "operational_wording"}:
                continue
            if any(marker in lowered for marker in {"api_key", "token", "secret", "password"}):
                continue
            out[key_text] = compact_grounded_payload(item, depth=depth + 1)
            if len(out) >= 40:
                break
        return out
    return str(value)[:500]


def normalized_for_verify(value: str | None) -> str:
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9@\u0600-\u06ff]+", " ", normalize_text(value))).strip()


def date_fact_variants(value: str) -> list[str]:
    parsed = parse_iso_date(value)
    if parsed:
        return unique_limited([
            value,
            format_shift_date(parsed),
            f"{parsed.day} {parsed.strftime('%B %Y')}",
            f"{parsed.day} {parsed.strftime('%b %Y')}",
        ], limit=6)
    return [value]


def reply_contains_any(reply: str, variants: list[str]) -> bool:
    normalized_reply = normalized_for_verify(reply)
    for variant in variants:
        normalized_variant = normalized_for_verify(variant)
        if normalized_variant and normalized_variant in normalized_reply:
            return True
    return False


def verify_operational_wording(reply: str, facts: dict[str, Any]) -> tuple[bool, str]:
    text = str(reply or "").strip()
    if not text or len(text) > 2800:
        return False, "empty_or_too_long"
    action_type = str(facts.get("action_type") or "")
    for name in facts.get("names") if isinstance(facts.get("names"), list) else []:
        if not reply_contains_any(text, [str(name)]):
            return False, f"missing_name:{name}"
    for date_value in facts.get("dates") if isinstance(facts.get("dates"), list) else []:
        if not reply_contains_any(text, date_fact_variants(str(date_value))):
            return False, f"missing_date:{date_value}"
    if action_type == "mark_attendance_absent" and "approved_leave" in normalized_for_verify(json.dumps(facts, ensure_ascii=False)).replace(" ", "_"):
        if not reply_contains_any(text, ["approved leave", "approved sick leave"]):
            return False, "missing_approved_leave"
        if not reply_contains_any(text, ["absent", "mark them absent", "mark him absent"]):
            return False, "missing_absent_action"
    allowed_emails = {normalize_text(item) for item in (facts.get("emails") if isinstance(facts.get("emails"), list) else [])}
    for email in re.findall(r"[\w.+-]+@[\w.-]+\.[a-zA-Z]{2,}", text):
        if normalize_text(email) not in allowed_emails:
            return False, "unexpected_email"
    if action_type not in {"answer_candidate_email_lookup", "prepare_candidate_email", "schedule_candidate_meeting", "send_email", "notify_candidate", "send_assessment", "schedule_interview", "rank_candidates"}:
        stale_markers = ["full stack", "candidate with that email", "azizalmulla16@gmail.com"]
        lowered = normalize_text(text)
        if any(marker in lowered for marker in stale_markers):
            return False, "stale_candidate_context"
    return True, "ok"


def extract_text_from_llm_response(parsed: dict[str, Any], provider: dict[str, str]) -> str:
    if provider.get("api") == "openai-responses":
        output_text = parsed.get("output_text")
        if isinstance(output_text, str) and output_text.strip():
            return output_text.strip()
        parts: list[str] = []
        for item in parsed.get("output") or []:
            for content in item.get("content") or []:
                if isinstance(content, dict) and content.get("type") in {"output_text", "text"}:
                    text = content.get("text")
                    if isinstance(text, str):
                        parts.append(text)
        return "\n".join(parts).strip()
    return str((((parsed.get("choices") or [{}])[0].get("message") or {}).get("content") or "")).strip()


def recent_assistant_replies(turn_id: str | None, limit: int = 3) -> list[str]:
    if not turn_id:
        return []
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT ar.final_reply
                    FROM action_results ar
                    JOIN hr_turns current_turn ON current_turn.turn_id=%s
                    JOIN hr_turns turn ON turn.turn_id=ar.turn_id
                    WHERE ar.final_reply IS NOT NULL
                      AND btrim(ar.final_reply) <> ''
                      AND turn.sender_phone=current_turn.sender_phone
                      AND (current_turn.account_id IS NULL OR turn.account_id=current_turn.account_id)
                      AND (current_turn.conversation_id IS NULL OR turn.conversation_id=current_turn.conversation_id)
                      AND ar.turn_id <> %s
                    ORDER BY ar.created_at DESC
                    LIMIT %s
                    """,
                    (turn_id, turn_id, max(1, min(limit, 5))),
                )
                return [str(row["final_reply"]) for row in cur.fetchall() if row.get("final_reply")]
    except Exception:
        return []


def call_operational_wording_llm(*, user_text: str, facts: dict[str, Any], turn_id: str | None = None, timeout: int = 8) -> str | None:
    provider = planner_provider_config()
    if not provider:
        return None
    system = openclaw_augmented_system_prompt(OPERATIONAL_WORDING_BASE_SYSTEM, prompt_name="style_layer", context_mode="concise")
    requested_language = detect_user_language(user_text)
    payload = {
        "current_user_message": user_text,
        "requested_language": language_label(requested_language),
        "recent_assistant_replies": recent_assistant_replies(turn_id),
        "structured_facts": facts,
        "backend_reply": facts.get("backend_reply"),
        "grounded_payload": facts.get("grounded_payload"),
        "style": "warm operator, professional but not stiff, Kuwaiti-friendly when natural, concise but not robotic",
    }
    if provider.get("api") == "openai-responses":
        body = {
            "model": provider["model"],
            "temperature": 0.2,
            "input": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    else:
        body = {
            "model": provider["model"],
            "temperature": 0.2,
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    start = time_module.monotonic()
    estimated_tokens = estimate_tokens_from_payload(body)
    prompt_hash = stable_text_hash(system)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception as exc:
        record_llm_call(
            turn_id=turn_id,
            call_name="style_layer",
            provider=provider,
            prompt_mode="concise",
            prompt_docs_loaded=True,
            prompt_hash=prompt_hash,
            estimated_input_tokens=estimated_tokens,
            latency_ms=int((time_module.monotonic() - start) * 1000),
            status="error",
            error=str(exc),
            metadata={"action_type": facts.get("action_type"), "status": facts.get("status")},
        )
        return None
    record_llm_call(
        turn_id=turn_id,
        call_name="style_layer",
        provider=provider,
        prompt_mode="concise",
        prompt_docs_loaded=True,
        prompt_hash=prompt_hash,
        estimated_input_tokens=estimated_tokens,
        latency_ms=int((time_module.monotonic() - start) * 1000),
        status="ok",
        parsed=parsed,
        metadata={"action_type": facts.get("action_type"), "status": facts.get("status")},
    )
    return extract_text_from_llm_response(parsed, provider) or None


def compose_operational_reply(
    *,
    action_type: str,
    status: str,
    result_payload: dict[str, Any],
    template_reply: str,
    user_text: str | None,
    turn_id: str | None = None,
) -> tuple[str, dict[str, Any]]:
    facts = operational_fact_bundle(action_type, status, result_payload, template_reply)
    if not operational_wording_enabled():
        return template_reply, {"enabled": False, "used": False, "facts": facts}
    candidate = call_operational_wording_llm(user_text=user_text or "", facts=facts, turn_id=turn_id)
    if not candidate:
        return template_reply, {"enabled": True, "used": False, "reason": "llm_unavailable", "facts": facts}
    ok, reason = verify_operational_wording(candidate, facts)
    if not ok:
        return template_reply, {"enabled": True, "used": False, "reason": reason, "candidate_reply": candidate, "facts": facts}
    return candidate, {"enabled": True, "used": True, "reason": "verified", "facts": facts}


def wathefni_style_context(action_type: str | None) -> str:
    action = str(action_type or "")
    if action in {"candidate_cv_evaluation", "rank_candidates"}:
        return "candidate_cv_evaluation"
    if action == "compare_candidates":
        return "candidate_comparison"
    if action == "workforce_analytics":
        return "workforce_analytics"
    if action == "check_assessment_config":
        return "assessment_config"
    return "general"


def friendly_success_correction_reply(action_type: str, target: str | None) -> str:
    name = target or "the target"
    action = str(action_type or "")
    if action == "send_email":
        return f"Actually, the email was sent successfully to {name}."
    if action in {"notify_candidate", "send_assessment", "send_custom_employee_message", "send_onboarding_reminder"}:
        return f"Actually, the message was sent successfully to {name}."
    if action in {"approve_leave_request", "reject_leave_request", "approve_shift_swap", "reject_shift_swap"}:
        return f"Actually, that decision was completed successfully for {name}."
    if action == "export_payroll":
        return "Actually, the payroll export completed successfully."
    return f"Actually, the {action.replace('_', ' ') or 'action'} completed successfully for {name}."


