def persist_fallback_turn(
    state: GraphState,
    *,
    intent: str,
    turn_focus: str,
    final_reply_source: str,
    payload: dict[str, Any] | None = None,
) -> None:
    turn_id = state.get("turn_id")
    if not turn_id:
        return
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE hr_turns
                SET intent=%s, turn_focus=%s, final_reply_source=%s
                WHERE turn_id::text=%s
                """,
                (intent, turn_focus, final_reply_source, turn_id),
            )
            updated = cur.rowcount
            if updated and payload is not None:
                cur.execute(
                    "INSERT INTO memory_snapshots (turn_id, scope, payload) VALUES (%s,%s,%s)",
                    (turn_id, turn_focus, Json(json_safe(payload))),
                )
        conn.commit()


def fallback(state: GraphState) -> GraphState:
    candidate_action = candidate_mutation_action_type_from_text(state["request"].raw_text)
    if candidate_action:
        template_reply = candidate_mutation_clarification(candidate_action)
        intent = "blocked_candidate_mutation_fallback"
        turn_focus = "candidate_mutation_clarification"
        final_reply_source = "blocked_candidate_mutation_fallback"
        reply, wording = style_backend_reply(state, action_type=intent, status="needs_clarification", template_reply=template_reply, result_payload={"candidate_action": candidate_action})
        persist_fallback_turn(state, intent=intent, turn_focus=turn_focus, final_reply_source=final_reply_source, payload={"reply": reply, "candidate_action": candidate_action, "operational_wording": json_safe(wording)})
        turn_scratch = {**(state.get("turn_scratch") or {}), "reply_text": reply, "fallback_text": reply}
        return {
            **state,
            "turn_scratch": turn_scratch,
            "authoritative": True,
            "reply_text": reply,
            "intent": intent,
            "turn_focus": turn_focus,
            "final_reply_source": final_reply_source,
        }
    if is_operational_truth_question(state["request"].raw_text):
        template_reply = safe_fallback_reply("operational")
        intent = "blocked_operational_fallback"
        turn_focus = "operational_fallback_blocked"
        final_reply_source = "blocked_operational_fallback"
        reply, wording = style_backend_reply(state, action_type=intent, status="blocked", template_reply=template_reply, result_payload={"kind": "operational"})
        persist_fallback_turn(state, intent=intent, turn_focus=turn_focus, final_reply_source=final_reply_source, payload={"reply": reply, "kind": "operational", "operational_wording": json_safe(wording)})
        turn_scratch = {**(state.get("turn_scratch") or {}), "reply_text": reply, "fallback_text": reply}
        return {
            **state,
            "turn_scratch": turn_scratch,
            "authoritative": True,
            "reply_text": reply,
            "intent": intent,
            "turn_focus": turn_focus,
            "final_reply_source": final_reply_source,
        }
    if is_domain_routing_question(state["request"].raw_text):
        template_reply = safe_fallback_reply("domain")
        intent = "blocked_domain_fallback"
        turn_focus = "domain_fallback_blocked"
        final_reply_source = "blocked_domain_fallback"
        reply, wording = style_backend_reply(state, action_type=intent, status="blocked", template_reply=template_reply, result_payload={"kind": "domain"})
        persist_fallback_turn(state, intent=intent, turn_focus=turn_focus, final_reply_source=final_reply_source, payload={"reply": reply, "kind": "domain", "operational_wording": json_safe(wording)})
        turn_scratch = {**(state.get("turn_scratch") or {}), "reply_text": reply, "fallback_text": reply}
        return {
            **state,
            "turn_scratch": turn_scratch,
            "authoritative": True,
            "reply_text": reply,
            "intent": intent,
            "turn_focus": turn_focus,
            "final_reply_source": final_reply_source,
        }
    template_reply = safe_fallback_reply("neutral_help")
    intent = "answer_neutral_help_fallback"
    turn_focus = "neutral_help_fallback"
    final_reply_source = "backend_neutral_help_fallback"
    reply, wording = style_backend_reply(state, action_type=intent, status="completed", template_reply=template_reply, result_payload={"kind": "neutral_help"})
    persist_fallback_turn(state, intent=intent, turn_focus=turn_focus, final_reply_source=final_reply_source, payload={"reply": reply, "kind": "neutral_help", "operational_wording": json_safe(wording)})
    turn_scratch = {**(state.get("turn_scratch") or {}), "reply_text": reply, "fallback_text": reply}
    return {
        **state,
        "turn_scratch": turn_scratch,
        "authoritative": True,
        "reply_text": reply,
        "intent": intent,
        "turn_focus": turn_focus,
        "final_reply_source": final_reply_source,
    }


def onboarding_employee_action_sql(column: str = "status") -> str:
    """Canonical "employee owes an action" SQL predicate for reminder paths."""
    import onboarding_completion_contract as _completion

    return f"lower(coalesce({column},'')) IN ({_completion.sql_employee_action_list()})"


def pending_onboarding_reminder_candidates(
    *,
    company_code: str | None = None,
    limit: int = 25,
    min_hours_since_last: int = 24,
) -> list[dict[str, Any]]:
    """Tenant-safe reminder candidates. Fail closed without company_code."""
    company = str(company_code or "").strip().upper()
    if not company:
        return []
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT e.*, COUNT(i.item_id) AS pending_items,
                       MIN(i.created_at) AS oldest_pending_at,
                       MAX(i.reminder_count) AS max_reminder_count
                FROM employees e
                JOIN onboarding_items i ON i.employee_key=e.employee_key
                WHERE e.company_code=%s
                  AND i.required IS TRUE
                  AND i.item_id <> 'bank_details'
                  AND {onboarding_employee_action_sql('i.status')}
                  AND (i.last_reminded_at IS NULL OR i.last_reminded_at < now() - (%s || ' hours')::interval)
                GROUP BY e.employee_key
                ORDER BY oldest_pending_at ASC
                LIMIT %s
                """,
                (company, max(1, min_hours_since_last), max(1, min(limit, 100))),
            )
            return [dict(row) for row in cur.fetchall()]


def mark_onboarding_reminder_attempted(employee_key: str, *, company_code: str | None = None) -> dict[str, Any]:
    """Stamp last_reminded_at without bumping reminder_count, so a *failed* reminder
    is throttled by the same cooldown as a successful one. This stops a delivery
    failure (closed WhatsApp + no email) from re-firing the onboarding reminder
    every hour, while still allowing a legitimate retry after the cooldown."""
    company = str(company_code or "").strip().upper() or None
    with db_connect() as conn:
        with conn.cursor() as cur:
            if company:
                cur.execute(
                    f"""
                    UPDATE onboarding_items i
                    SET last_reminded_at=now(),
                        updated_at=now()
                    FROM employees e
                    WHERE i.employee_key=e.employee_key
                      AND e.company_code=%s
                      AND i.employee_key=%s
                      AND i.required IS TRUE
                      AND i.item_id <> 'bank_details'
                      AND {onboarding_employee_action_sql('i.status')}
                    RETURNING i.item_id
                    """,
                    (company, employee_key),
                )
            else:
                cur.execute(
                    f"""
                    UPDATE onboarding_items
                    SET last_reminded_at=now(),
                        updated_at=now()
                    WHERE employee_key=%s
                      AND required IS TRUE
                      AND item_id <> 'bank_details'
                      AND {onboarding_employee_action_sql()}
                    RETURNING item_id
                    """,
                    (employee_key,),
                )
            rows = cur.fetchall()
        conn.commit()
    return {"updated": len(rows)}


def mark_onboarding_reminder_sent(employee_key: str, *, company_code: str | None = None) -> dict[str, Any]:
    company = str(company_code or "").strip().upper() or None
    with db_connect() as conn:
        with conn.cursor() as cur:
            if company:
                cur.execute(
                    f"""
                    UPDATE onboarding_items i
                    SET reminder_count=reminder_count + 1,
                        last_reminded_at=now(),
                        updated_at=now()
                    FROM employees e
                    WHERE i.employee_key=e.employee_key
                      AND e.company_code=%s
                      AND i.employee_key=%s
                      AND i.required IS TRUE
                      AND i.item_id <> 'bank_details'
                      AND {onboarding_employee_action_sql('i.status')}
                    RETURNING i.item_id, i.label, i.document_type, i.reminder_count
                    """,
                    (company, employee_key),
                )
            else:
                cur.execute(
                    f"""
                    UPDATE onboarding_items
                    SET reminder_count=reminder_count + 1,
                        last_reminded_at=now(),
                        updated_at=now()
                    WHERE employee_key=%s
                      AND required IS TRUE
                      AND item_id <> 'bank_details'
                      AND {onboarding_employee_action_sql()}
                    RETURNING item_id, label, document_type, reminder_count
                    """,
                    (employee_key,),
                )
            rows = [dict(row) for row in cur.fetchall()]
        conn.commit()
    return {"updated": len(rows), "items": json_safe(rows)}


def maybe_escalate_onboarding_reminder(employee: dict[str, Any], account_id: str | None, reminder_items: list[dict[str, Any]]) -> dict[str, Any] | None:
    if not reminder_items:
        return None
    max_count = max(int(item.get("reminder_count") or 0) for item in reminder_items)
    if max_count < 3:
        return None
    labels = [item_display_label(item) for item in reminder_items]
    message = f"{employee.get('name') or employee.get('phone')} still has pending onboarding items after {max_count} reminders: {format_inline_list(labels)}."
    notification = notify_hr_admins(
        company_code=employee.get("company_code"),
        account_id=account_id,
        message=message,
        subject_type="employee",
        subject_key=employee.get("employee_key"),
    )
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                UPDATE onboarding_items
                SET escalated_at=COALESCE(escalated_at, now()), updated_at=now()
                WHERE employee_key=%s
                  AND required IS TRUE
                  AND {onboarding_employee_action_sql()}
                  AND reminder_count >= 3
                """,
                (employee.get("employee_key"),),
            )
        conn.commit()
    return notification


def notify_hr_onboarding_reminder_failures(
    *,
    company_code: str | None,
    account_id: str | None,
    failures: list[dict[str, Any]],
) -> dict[str, Any] | None:
    if not failures:
        return None
    sample_names = [
        str(item.get("name") or item.get("phone") or "employee")
        for item in failures[:4]
    ]
    extra = len(failures) - len(sample_names)
    suffix = f" and {extra} more" if extra > 0 else ""
    message = (
        f"{len(failures)} onboarding reminder{'s' if len(failures) != 1 else ''} failed. "
        f"Review WhatsApp delivery for {format_inline_list(sample_names)}{suffix}."
    )
    return notify_hr_admins(
        company_code=company_code,
        account_id=account_id,
        message=message,
        subject_type="onboarding_reminder_failures",
        subject_key=str(company_code or "unknown"),
    )


def _onboarding_reminder_company_codes(*, company_code: str | None = None) -> list[str]:
    """Companies to scan for reminders. Explicit company wins; else module-enabled tenants only."""
    explicit = str(company_code or "").strip().upper()
    if explicit:
        return [explicit]
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT DISTINCT e.company_code
                FROM employees e
                WHERE e.company_code IS NOT NULL AND e.company_code <> ''
                ORDER BY e.company_code
                """
            )
            codes = [str(row["company_code"]).strip().upper() for row in (cur.fetchall() or []) if row.get("company_code")]
    return [c for c in codes if company_has_module(c, "onboarding")]


def run_onboarding_reminder_scan(
    *,
    account_id: str | None,
    dry_run: bool = True,
    limit: int = 25,
    min_hours_since_last: int = 24,
    company_code: str | None = None,
) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    failures_by_company: dict[str, list[dict[str, Any]]] = {}
    scanned_companies: list[str] = []
    remaining = max(1, min(limit, 100))
    for company in _onboarding_reminder_company_codes(company_code=company_code):
        if remaining <= 0:
            break
        scanned_companies.append(company)
        candidates = pending_onboarding_reminder_candidates(
            company_code=company,
            limit=remaining,
            min_hours_since_last=min_hours_since_last,
        )
        for employee in candidates:
            if remaining <= 0:
                break
            if not company_has_module(employee.get("company_code"), "onboarding"):
                skipped.append({
                    "employee_key": employee.get("employee_key"),
                    "company_code": employee.get("company_code"),
                    "reason": "onboarding_module_disabled",
                })
                continue
            if not company_module_automation_enabled(employee.get("company_code"), "onboarding"):
                skipped.append({
                    "employee_key": employee.get("employee_key"),
                    "company_code": employee.get("company_code"),
                    "reason": "onboarding_automation_disabled",
                })
                continue
            try:
                with db_connect() as conn:
                    with conn.cursor() as cur:
                        import tenant_control_queue_gate as _tc_qg

                        emp_company = str(employee.get("company_code") or "").upper()
                        work_ref = str(employee.get("employee_key") or "")
                        queued_epoch = _tc_qg.persist_work_epoch(
                            cur,
                            company_code=emp_company,
                            work_kind="onboarding_reminder",
                            work_ref=work_ref,
                            module_key="onboarding",
                        )
                        allowed, decision = _tc_qg.gate_or_skip(
                            cur,
                            company_code=emp_company,
                            module_key="onboarding",
                            work_kind="onboarding_reminder",
                            work_ref=work_ref,
                            queued_epoch=queued_epoch,
                            surface="timers",
                        )
                        conn.commit()
                        if not allowed:
                            skipped.append({
                                "employee_key": work_ref,
                                "company_code": emp_company,
                                "reason": decision.reason_code,
                                "held": True,
                            })
                            continue
            except Exception:
                pass
            body, missing = onboarding_reminder_message(employee)
            entry: dict[str, Any] = {
                "employee_key": employee.get("employee_key"),
                "name": employee.get("name"),
                "phone": employee.get("phone"),
                "company_code": company,
                "missing": missing,
                "message": body,
                "dry_run": dry_run,
            }
            emp_company = str(employee.get("company_code") or company).upper()
            if not dry_run:
                send_result = send_onboarding_reminder(employee, account_id)
                entry["send"] = send_result
                if send_result.get("ok"):
                    reminder_update = mark_onboarding_reminder_sent(
                        str(employee.get("employee_key")),
                        company_code=emp_company,
                    )
                    entry["reminder_update"] = reminder_update
                    escalation = maybe_escalate_onboarding_reminder(employee, account_id, reminder_update.get("items") or [])
                    if escalation:
                        entry["escalation"] = escalation
                elif send_result.get("throttled"):
                    entry["throttled"] = True
                    entry["reminder_update"] = mark_onboarding_reminder_attempted(
                        str(employee.get("employee_key")),
                        company_code=emp_company,
                    )
                else:
                    entry["reminder_update"] = mark_onboarding_reminder_attempted(
                        str(employee.get("employee_key")),
                        company_code=emp_company,
                    )
                    failures_by_company.setdefault(emp_company, []).append(entry)
            results.append(entry)
            remaining -= 1
    failure_notifications = []
    if not dry_run:
        for company, failures in failures_by_company.items():
            notification = notify_hr_onboarding_reminder_failures(company_code=company, account_id=account_id, failures=failures)
            if notification:
                failure_notifications.append(notification)
    return {
        "ok": True,
        "dry_run": dry_run,
        "count": len(results),
        "skipped_count": len(skipped),
        "results": results,
        "skipped": skipped,
        "failure_notifications": failure_notifications,
        "scanned_companies": scanned_companies,
        "tenant_safe": True,
    }


COMPLIANCE_WARNING_DAYS = {
    "civil_id": 30,
    "passport": 60,
    "residency": 30,
    "residence": 30,
    "residency_iqama": 30,
    "work_permit": 30,
    "medical": 30,
}


def compliance_scan_rows(limit: int = 100) -> list[dict[str, Any]]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT c.*, e.name, e.phone, e.company_code
                FROM compliance_documents c
                LEFT JOIN employees e ON e.employee_key=c.employee_key
                WHERE c.status IN ('received','valid','expiring_soon','expired','missing_expiry')
                   OR c.expiry_date IS NOT NULL
                ORDER BY c.updated_at DESC
                LIMIT %s
                """,
                (max(1, min(limit, 500)),),
            )
            return [dict(row) for row in cur.fetchall()]


def classify_compliance_row(row: dict[str, Any], *, company_warning_days: dict[str, Any] | None = None) -> dict[str, Any]:
    document_type = str(row.get("document_type") or "")
    warning_days = None
    if row.get("warning_days") is not None:
        try:
            warning_days = int(row.get("warning_days"))
        except Exception:
            warning_days = None
    if warning_days is None and isinstance(company_warning_days, dict):
        raw = company_warning_days.get(document_type)
        if raw is None and document_type in {"residency", "residency_iqama"}:
            raw = company_warning_days.get("residence")
        if raw is not None:
            try:
                warning_days = int(raw)
            except Exception:
                warning_days = None
    if warning_days is None:
        warning_days = int(COMPLIANCE_WARNING_DAYS.get(document_type, 30))
    # Reminders only after HR confirmation (approve_version → renewal_status=reviewed).
    renewal_status = str(row.get("renewal_status") or "").strip().lower()
    status = str(row.get("status") or "").strip().lower()
    hr_confirmed = renewal_status == "reviewed"
    expiry = row.get("expiry_date")
    if isinstance(expiry, str):
        expiry = parse_iso_date(expiry)
    if not hr_confirmed:
        # OCR may have proposed an expiry, but never alert until HR confirms.
        return {
            "status": "pending_hr_review",
            "severity": "info",
            "days_until_expiry": None,
            "warning_days": warning_days,
            "reminder_eligible": False,
        }
    if not expiry:
        if status == "received":
            return {"status": "missing_expiry", "severity": "needs_review", "days_until_expiry": None, "warning_days": warning_days, "reminder_eligible": False}
        return {"status": status or "missing", "severity": "info", "days_until_expiry": None, "warning_days": warning_days, "reminder_eligible": False}
    days_until = (expiry - now_utc().date()).days
    if days_until < 0:
        return {"status": "expired", "severity": "critical", "days_until_expiry": days_until, "warning_days": warning_days, "reminder_eligible": True}
    if days_until <= warning_days:
        return {"status": "expiring_soon", "severity": "warning", "days_until_expiry": days_until, "warning_days": warning_days, "reminder_eligible": True}
    return {"status": "valid", "severity": "ok", "days_until_expiry": days_until, "warning_days": warning_days, "reminder_eligible": False}


def compliance_alert_due(row: dict[str, Any], classification: dict[str, Any], cooldown_hours: int = 24) -> bool:
    if classification.get("reminder_eligible") is False:
        return False
    if classification.get("severity") not in {"critical", "warning", "needs_review"}:
        return False
    last_alerted = row.get("last_alerted_at")
    if not last_alerted:
        return True
    if isinstance(last_alerted, str):
        try:
            last_alerted = datetime.fromisoformat(last_alerted.replace("Z", "+00:00"))
        except Exception:
            return True
    if not isinstance(last_alerted, datetime):
        return True
    if last_alerted.tzinfo is None:
        last_alerted = last_alerted.replace(tzinfo=timezone.utc)
    return last_alerted < now_utc() - timedelta(hours=max(1, cooldown_hours))


def compliance_alert_message(row: dict[str, Any], classification: dict[str, Any]) -> str:
    name = row.get("name") or row.get("phone") or row.get("employee_key")
    label = row.get("label") or item_display_label(str(row.get("document_type") or "document"))
    status = classification.get("status")
    days = classification.get("days_until_expiry")
    if status == "expired":
        return f"{name}'s {label} is expired by {abs(int(days or 0))} days. Please start renewal."
    if status == "expiring_soon":
        return f"{name}'s {label} expires in {int(days or 0)} days. Please start renewal."
    if status == "missing_expiry":
        return f"{name}'s {label} was received, but I could not read an expiry date. HR should review it."
    return f"{name}'s {label} compliance status is {status}."


def run_compliance_scan(*, account_id: str | None, dry_run: bool = True, limit: int = 100, alert_cooldown_hours: int = 24) -> dict[str, Any]:
    rows = compliance_scan_rows(limit=limit)
    results: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    # Group due compliance alerts per company so HR gets ONE digest per run instead
    # of a separate WhatsApp/notification per document (low-noise reminder summary).
    grouped_alerts: dict[str, list[dict[str, Any]]] = {}
    for row in rows:
        if not company_has_module(row.get("company_code"), "compliance"):
            skipped.append({
                "employee_key": row.get("employee_key"),
                "company_code": row.get("company_code"),
                "document_type": row.get("document_type"),
                "reason": "compliance_module_disabled",
            })
            continue
        if not company_module_automation_enabled(row.get("company_code"), "compliance"):
            skipped.append({
                "employee_key": row.get("employee_key"),
                "company_code": row.get("company_code"),
                "document_type": row.get("document_type"),
                "reason": "compliance_automation_disabled",
            })
            continue
        try:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    import tenant_control_queue_gate as _tc_qg

                    company = str(row.get("company_code") or "").upper()
                    work_ref = f"{row.get('employee_key')}:{row.get('document_type')}"
                    queued_epoch = _tc_qg.persist_work_epoch(
                        cur,
                        company_code=company,
                        work_kind="compliance_scan",
                        work_ref=work_ref,
                        module_key="compliance",
                    )
                    allowed, decision = _tc_qg.gate_or_skip(
                        cur,
                        company_code=company,
                        module_key="compliance",
                        work_kind="compliance_scan",
                        work_ref=work_ref,
                        queued_epoch=queued_epoch,
                        surface="timers",
                    )
                    conn.commit()
                    if not allowed:
                        skipped.append({
                            "employee_key": row.get("employee_key"),
                            "company_code": company,
                            "document_type": row.get("document_type"),
                            "reason": decision.reason_code,
                            "held": True,
                        })
                        continue
        except Exception:
            pass
        classification = classify_compliance_row(row)
        due = compliance_alert_due(row, classification, cooldown_hours=alert_cooldown_hours)
        entry = {
            "employee_key": row.get("employee_key"),
            "name": row.get("name"),
            "document_type": row.get("document_type"),
            "classification": classification,
            "alert_due": due,
            "dry_run": dry_run,
        }
        if not dry_run:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        UPDATE compliance_documents
                        SET status=%s,
                            severity=%s,
                            warning_days=COALESCE(warning_days, %s),
                            days_until_expiry=%s,
                            last_checked_at=now(),
                            updated_at=now()
                        WHERE employee_key=%s AND document_type=%s
                        """,
                        (
                            classification.get("status"),
                            classification.get("severity"),
                            classification.get("warning_days"),
                            classification.get("days_until_expiry"),
                            row.get("employee_key"),
                            row.get("document_type"),
                        ),
                    )
                conn.commit()
        if due:
            # Defer the send: collect per company, then emit one grouped digest
            # below so HR is pinged once per company per run, not once per document.
            # Collected in dry-run too (visibility only); the actual send + cooldown
            # stamp stay gated on `not dry_run`.
            company = require_company_code(row.get("company_code"))
            grouped_alerts.setdefault(company, []).append(
                {"row": row, "classification": classification, "entry": entry}
            )
            entry["alert_grouped"] = True
        results.append(entry)
    # One grouped HR reminder per company (instead of one per document). Stamp the
    # cooldown on every included document only when the digest is actually sent.
    grouped_notifications: dict[str, Any] = {}
    if not dry_run:
        for company, items in grouped_alerts.items():
            lines = [compliance_alert_message(it["row"], it["classification"]) for it in items]
            shown = lines[:10]
            body_lines = [f"{len(items)} compliance document(s) need attention:"]
            body_lines += [f"• {line}" for line in shown]
            if len(items) > len(shown):
                body_lines.append(f"• …and {len(items) - len(shown)} more")
            body = "\n".join(body_lines)
            notification = notify_hr_admins(
                company_code=company,
                account_id=account_id,
                message=body,
                subject_type="company",
                subject_key=company,
            )
            grouped_notifications[company] = {"ok": bool(notification.get("ok")), "documents": len(items)}
            for it in items:
                it["entry"]["notification"] = {"ok": bool(notification.get("ok")), "grouped": True}
            if notification.get("ok"):
                with db_connect() as conn:
                    with conn.cursor() as cur:
                        for it in items:
                            cur.execute(
                                """
                                UPDATE compliance_documents
                                SET last_alerted_at=now(), reminder_count=reminder_count + 1, last_reminded=CURRENT_DATE, updated_at=now()
                                WHERE employee_key=%s AND document_type=%s
                                """,
                                (it["row"].get("employee_key"), it["row"].get("document_type")),
                            )
                    conn.commit()
    grouped_documents = {company: len(items) for company, items in grouped_alerts.items()}
    return {"ok": True, "dry_run": dry_run, "count": len(results), "skipped_count": len(skipped), "results": results, "skipped": skipped, "grouped_notifications": grouped_notifications, "grouped_companies": len(grouped_alerts), "grouped_documents": grouped_documents}


# --- Compliance dashboard (read) -------------------------------------------
# HR-friendly Kuwait/GCC document names and status labels. The dashboard never
# shows raw backend values (missing_expiry, critical, extraction_status, …);
# everything below maps the worker/classifier output into language HR can act on.
COMPLIANCE_DOC_LABELS = {
    "civil_id": "Civil ID",
    "passport": "Passport",
    "residency": "Residence",
    "residence": "Residence",
    "residency_iqama": "Residence (legacy id)",
    "work_permit": "Work permit",
    "employment_contract": "Employment contract",
    "medical": "Medical certificate",
    "education_cert": "Education certificate",
}
COMPLIANCE_DOC_LABELS_AR = {
    "civil_id": "البطاقة المدنية",
    "passport": "جواز السفر",
    "residency": "الإقامة",
    "residence": "الإقامة",
    "residency_iqama": "الإقامة (معرّف قديم)",
    "work_permit": "إذن العمل",
    "employment_contract": "عقد العمل",
    "medical": "الشهادة الطبية",
    "education_cert": "الشهادة التعليمية",
}
# Five HR-facing buckets. Order matters: it is the order HR should work through.
COMPLIANCE_BUCKETS = ("expired", "expiring_soon", "missing", "needs_review", "valid")
COMPLIANCE_STATUS_LABELS = {
    "expired": "Expired",
    "expiring_soon": "Expiring soon",
    "missing": "Missing",
    "needs_review": "Pending HR review",
    "valid": "HR reviewed",
    "pending_hr_review": "Pending HR review",
    "hr_reviewed": "HR reviewed",
    "rejected_reupload": "Rejected — re-upload required",
}
COMPLIANCE_STATUS_TONE = {
    "expired": "danger",
    "expiring_soon": "warning",
    "missing": "warning",
    "needs_review": "warning",
    "valid": "success",
}


def compliance_bucket_for(classified_status: str | None) -> str:
    """Collapse the classifier's status into one of the five HR buckets, so the
    dashboard groups documents exactly the way the worker classifies them."""
    status = str(classified_status or "").lower()
    if status == "expired":
        return "expired"
    if status == "expiring_soon":
        return "expiring_soon"
    # pending_hr_review = classifier waiting on HR confirm (renewal_status ≠ reviewed).
    # missing_expiry / explicit needs_review stay in the review queue — never collapse
    # them into "missing" or mobile/Home Document Reviews go empty while DB truth is reviewable.
    if status in {"pending_hr_review", "needs_review", "missing_expiry"}:
        return "needs_review"
    if status == "valid":
        return "valid"
    # Everything else (missing/unknown) is missing.
    return "missing"


def compliance_document_friendly_label(document_type: str | None, fallback_label: str | None = None) -> str:
    doc = str(document_type or "").lower()
    if doc in COMPLIANCE_DOC_LABELS:
        return COMPLIANCE_DOC_LABELS[doc]
    label = str(fallback_label or "").strip()
    if label:
        return label
    if doc:
        return item_display_label(doc)
    return "Other Document"


def compliance_next_action(bucket: str, name: str, expiry_label: str | None) -> str:
    if bucket == "expired":
        return f"Start renewal and follow up with {name}."
    if bucket == "expiring_soon":
        return f"Remind {name} to renew{f' before {expiry_label}' if expiry_label else ''}."
    if bucket == "missing":
        return f"Request this document from {name}."
    if bucket == "needs_review":
        return "Review the document — the expiry date could not be read."
    return "No action needed."


def dashboard_compliance_payload(
    company: str,
    viewer_phone: str | None = None,
    *,
    dashboard_user_id: str | None = None,
    actor_role: str | None = None,
    search: str | None = None,
    bucket_filter: str | None = None,
    offset: int = 0,
    limit: int | None = None,
) -> dict[str, Any]:
    """Company-scoped compliance read for the dashboard.

    Reuses the worker's classifier (classify_compliance_row) so status/severity
    definitions stay identical to the background scan, then maps everything into
    HR-friendly labels and the five buckets HR works through. Company scoping is
    enforced by only looking at compliance documents for this company's employees.
    When viewer_phone is a scoped manager, the employee set is further narrowed to
    their branch/team/direct scope (inert for unscoped owners/HR).

    `summary` counts are ALWAYS computed over the full classified set (using the
    same classifier — no duplicated logic), so the bucket chips stay accurate.
    Optional `bucket`/`search`/`offset`/`limit` filter and page the returned
    `documents` list so the dashboard isn't shipped tens of thousands of rows at
    once. Pagination is opt-in: when `limit` is None the full (optionally filtered)
    list is returned, preserving every existing caller's behavior.
    """
    employees = company_employees(company)
    allowed_keys = manager_scope_employee_keys(
        company,
        viewer_phone,
        dashboard_user_id=dashboard_user_id,
        actor_role=actor_role,
    )
    if allowed_keys is not None:
        employees = [e for e in employees if str(e.get("employee_key")) in allowed_keys]
    cards: dict[str, dict[str, Any]] = {}
    employee_rows_by_key: dict[str, dict[str, Any]] = {}
    for row in employees:
        card = posthire_employee_card(row)
        key = str(card.get("employee_key") or "")
        if key:
            cards[key] = card
            employee_rows_by_key[key] = row
    employee_keys = list(cards.keys())
    documents: list[dict[str, Any]] = []
    counts = {bucket: 0 for bucket in COMPLIANCE_BUCKETS}
    if employee_keys:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT cd.employee_key, cd.document_type, cd.label, cd.status,
                           cd.expiry_date, cd.days_until_expiry, cd.warning_days,
                           cd.last_checked_at, cd.last_alerted_at, cd.last_reminded,
                           cd.reminder_count, cd.extraction_confidence, cd.updated_at,
                           cd.renewal_status
                    FROM compliance_documents cd
                    WHERE cd.employee_key = ANY(%s)
                    ORDER BY cd.updated_at DESC NULLS LAST
                    """,
                    (employee_keys,),
                )
                rows = [dict(r) for r in cur.fetchall()]
                # Bulk-resolve the stored file (file_registry) per (employee, type)
                # so each compliance row can carry a View/Download file_id without
                # an N+1 fan-out. Latest stored file wins.
                # Include residence family aliases so legacy residency_iqama files map.
                cur.execute(
                    """
                    SELECT DISTINCT ON (subject_key, document_type) subject_key, document_type, file_id
                    FROM file_registry
                    WHERE company_code=%s AND subject_type='employee' AND subject_key = ANY(%s)
                      AND file_kind = ANY(%s) AND storage_status IN ('stored','stored_with_fallback')
                    ORDER BY subject_key, document_type, updated_at DESC NULLS LAST
                    """,
                    (company, employee_keys, list(_EMPLOYEE_DOCUMENT_FILE_KINDS)),
                )
                file_ids = {(str(r["subject_key"]), str(r["document_type"] or "")): str(r["file_id"]) for r in cur.fetchall()}
                company_warning_days: dict[str, Any] = {}
                try:
                    import setup_console_modules_phase3b as _p3b

                    pol = _p3b.get_documents_company_policy(cur, company)
                    company_warning_days = dict(((pol.get("optional") or {}).get("warning_days") or {}))
                except Exception:
                    company_warning_days = {}
        for row in rows:
            card = cards.get(str(row.get("employee_key") or ""), {})
            classification = classify_compliance_row(row, company_warning_days=company_warning_days)
            expiry = row.get("expiry_date")
            expiry_iso = expiry.isoformat() if hasattr(expiry, "isoformat") else (str(expiry) if expiry else None)
            expiry_label = shift_sheet_cell(expiry) if expiry else None
            days_until = classification.get("days_until_expiry")
            last_reminded = row.get("last_alerted_at") or row.get("last_reminded")
            confidence = row.get("extraction_confidence")
            emp_key = str(row.get("employee_key") or "")
            doc_type = str(row.get("document_type") or "")
            # Resolve file across residence vocabulary aliases without renaming stored rows.
            file_id = file_ids.get((emp_key, doc_type))
            if not file_id and doc_type in {"residence", "residency", "residency_iqama"}:
                for alias in ("residence", "residency", "residency_iqama"):
                    file_id = file_ids.get((emp_key, alias))
                    if file_id:
                        break
            classified_status = classification.get("status")
            bucket = compliance_bucket_for(classified_status)
            raw_status = str(row.get("status") or "").strip().lower()
            # Reviewable truth for needs_review: explicit DB needs_review / received,
            # missing_expiry, or pending_hr_review with a stored file. Do not reopen
            # stored-valid rows that lack renewal_status into the mobile review queue.
            if classified_status == "pending_hr_review":
                if raw_status in {"needs_review", "received"} or file_id:
                    bucket = "needs_review"
                elif raw_status == "valid":
                    bucket = "valid"
                else:
                    bucket = "missing"
            elif raw_status == "needs_review":
                bucket = "needs_review"
            counts[bucket] += 1
            documents.append({
                "employee_key": row.get("employee_key"),
                "employee_name": card.get("name") or "Unnamed employee",
                "department": card.get("department") or "",
                "document_type": row.get("document_type"),
                "document_label": compliance_document_friendly_label(row.get("document_type"), row.get("label")),
                "status": bucket,
                "status_label": COMPLIANCE_STATUS_LABELS[bucket],
                "tone": COMPLIANCE_STATUS_TONE[bucket],
                "expiry_date": expiry_iso,
                "days_until_expiry": days_until,
                "last_checked_at": row.get("last_checked_at"),
                "last_reminded_at": last_reminded,
                "reminder_count": int(row.get("reminder_count") or 0),
                "confidence": round(float(confidence), 2) if confidence is not None else None,
                "next_action": compliance_next_action(bucket, card.get("name") or "the employee", expiry_label),
                "file_id": file_id,
            })
    needs_attention = counts["expired"] + counts["expiring_soon"] + counts["missing"] + counts["needs_review"]
    summary = {
        **counts,
        "needs_attention": needs_attention,
        "total_documents": len(documents),
        "employees_checked": len({d["employee_key"] for d in documents}),
        "employees_total": len(employee_keys),
    }
    # Filter the classified list (bucket + free-text search) then page it. Summary
    # above stays over the FULL set so the chips/banner are always accurate.
    working = documents
    bucket_key = (bucket_filter or "").strip().lower()
    if bucket_key and bucket_key in COMPLIANCE_BUCKETS:
        working = [d for d in working if d["status"] == bucket_key]
    term = (search or "").strip().lower()
    if term:
        working = [
            d for d in working
            if term in str(d.get("employee_name") or "").lower()
            or term in str(d.get("document_label") or "").lower()
            or term in str(d.get("document_type") or "").lower()
            or term in str(d.get("department") or "").lower()
        ]
    filtered_total = len(working)
    if limit is None:
        page_docs = working
        eff_offset, eff_limit, has_more = 0, None, False
    else:
        eff_limit = max(1, min(int(limit), 500))
        eff_offset = max(0, int(offset or 0))
        page_docs = working[eff_offset:eff_offset + eff_limit]
        has_more = (eff_offset + len(page_docs)) < filtered_total

    # Wave 1 Findings Contract — ranked attention over the FULL classified set
    # (not the paged slice) so severity ranking stays accurate under pagination.
    import compliance_findings_wave1 as _compliance_w1

    enabled_modules: set[str] = set()
    try:
        enabled_modules = set(configured_company_modules(company) or [])
        for key in ("compliance", "onboarding", "employees", "attendance", "leave", "shifts", "payroll", "analytics"):
            try:
                if company_has_module(company, key):
                    enabled_modules.add(key)
                else:
                    enabled_modules.discard(key)
            except Exception:
                pass
    except Exception:
        enabled_modules = {"compliance", "onboarding", "employees"}

    findings_pack = _compliance_w1.build_compliance_findings(
        documents=documents,
        employee_rows_by_key=employee_rows_by_key,
        enabled_modules=enabled_modules,
    )
    page_docs = [_compliance_w1.enrich_document_row(d) for d in page_docs]

    return {
        "company_code": company,
        "summary": summary,
        "documents": page_docs,
        "doc_upload_enabled": doc_upload_enabled(),
        "filtered_total": filtered_total,
        "offset": eff_offset,
        "limit": eff_limit,
        "has_more": has_more,
        # Wave 1 Findings Contract (additive)
        "findings": findings_pack.get("findings") or [],
        "findings_summary": findings_pack.get("findings_summary") or {},
        "as_of": findings_pack.get("as_of"),
        "timezone": findings_pack.get("timezone") or "Asia/Kuwait",
        "kuwait_date": findings_pack.get("kuwait_date"),
        "window": findings_pack.get("window"),
        "freshness": findings_pack.get("freshness"),
        "definitions": findings_pack.get("definitions") or [],
        "sources": findings_pack.get("sources"),
        "honesty": findings_pack.get("honesty"),
        "authority": findings_pack.get("authority"),
        "contract": _compliance_w1.COMPLIANCE_WAVE1_CONTRACT,
        "contract_version": _compliance_w1.COMPLIANCE_WAVE1_VERSION,
    }


# === Assistant HR read tools (onboarding / compliance / documents) ===========
# Read-only query power for the Wathefni Assistant (WhatsApp + dashboard). These
# reuse the EXACT dashboard data sources so the Assistant and the dashboard pages
# always agree, are manager-scoped via viewer_phone, and return METADATA ONLY —
# never file ids, storage urls, local paths, or document bytes. Dark-launched
# behind assistant_hr_reads_enabled() (the tools aren't even offered to the LLM
# until the flag is on).

_ASSISTANT_DOC_TYPE_ALIASES: dict[str, tuple[str, ...]] = {
    "civil_id": ("civil id", "civilid", "civil card", "cid"),
    "passport": ("passport",),
    "medical": ("medical", "medical fitness", "health certificate", "fitness"),
    "education_cert": ("education", "educational", "certificate", "certificates", "degree", "diploma", "qualification"),
    "bank_details": ("bank", "iban", "bank account", "bank details"),
    "personal_photo": ("personal photo", "photo", "picture"),
    "residency": ("residency", "iqama", "work permit", "residence permit"),
}


def _normalize_document_type_filter(text: str | None) -> str | None:
    raw = normalize_text(str(text or ""))
    if not raw:
        return None
    slug = re.sub(r"[\s-]+", "_", raw)
    if slug in _ASSISTANT_DOC_TYPE_ALIASES:
        return slug
    for canonical, aliases in _ASSISTANT_DOC_TYPE_ALIASES.items():
        if any(alias in raw for alias in aliases):
            return canonical
    return None


def _normalize_compliance_status_filter(value: str | None) -> str | None:
    raw = normalize_text(str(value or ""))
    if not raw:
        return None
    if "expired" in raw:
        return "expired"
    if "expiring" in raw or "expire" in raw or "expiry" in raw or "soon" in raw:
        return "expiring_soon"
    if "review" in raw:
        return "needs_review"
    if "missing" in raw or "not uploaded" in raw or ("no " in raw and "upload" in raw) or "without" in raw:
        return "missing"
    if "valid" in raw or "up to date" in raw:
        return "valid"
    slug = re.sub(r"[\s-]+", "_", raw)
    if slug in COMPLIANCE_BUCKETS:
        return slug
    return None


def _normalize_onboarding_status_filter(value: str | None) -> str | None:
    raw = normalize_text(str(value or ""))
    if not raw:
        return None
    if "in progress" in raw or "in_progress" in raw or "ongoing" in raw:
        return "in_progress"
    if "not started" in raw or "not_started" in raw or "nothing started" in raw:
        return "not_started"
    if ("complete" in raw or "completed" in raw or "finished" in raw or "done" in raw):
        if "not " in raw or "haven" in raw or "incomplete" in raw or "still" in raw or "yet" in raw:
            return None
        return "complete"
    return None


def _assistant_expiry_in_current_month(expiry: Any) -> bool:
    if not expiry:
        return False
    try:
        parsed = datetime.strptime(str(expiry)[:10], "%Y-%m-%d").date()
    except Exception:
        return False
    today = now_utc().date()
    return parsed.year == today.year and parsed.month == today.month


def list_compliance_documents(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    """Assistant read: compliance documents (expired / expiring / missing / needs
    review), optionally filtered by document type, timeframe, or one employee.
    Reuses dashboard_compliance_payload (same source of truth, manager-scoped via
    viewer_phone). Metadata only — no file ids/urls/paths."""
    company = require_company_code(company_code)
    viewer_phone = action.get("viewer_phone")
    payload = dashboard_compliance_payload(company, viewer_phone=viewer_phone)
    documents = payload.get("documents") or []

    text = normalize_text(action.get("prompt_text") or action.get("query") or "")
    status_filter = _normalize_compliance_status_filter(action.get("status") or action.get("bucket") or text)
    doc_filter = _normalize_document_type_filter(action.get("document_type") or action.get("item") or text)
    timeframe_raw = normalize_text(action.get("timeframe") or "")
    this_month = ("month" in timeframe_raw) or ("this month" in text)

    employee = None
    if any(action.get(k) for k in ("employee_name", "employee_phone", "subject_name", "subject_phone", "employee_key")):
        employee = resolve_employee_for_direct_action({**action, "company_code": company}, allow_latest=False)
        if employee and viewer_phone and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=viewer_phone):
            return {"ok": False, "error": "employee_outside_manager_scope", "safe_user_message": "That employee is outside your manager scope."}

    rows: list[dict[str, Any]] = []
    for d in documents:
        if status_filter and d.get("status") != status_filter:
            continue
        if doc_filter and _normalize_document_type_filter(d.get("document_type")) != doc_filter:
            continue
        if employee and str(d.get("employee_key")) != str(employee.get("employee_key")):
            continue
        if this_month and not _assistant_expiry_in_current_month(d.get("expiry_date")):
            continue
        rows.append({
            "employee_name": d.get("employee_name"),
            "department": d.get("department"),
            "document_type": d.get("document_type"),
            "document_label": d.get("document_label"),
            "status": d.get("status"),
            "status_label": d.get("status_label"),
            "expiry_date": d.get("expiry_date"),
            "days_until_expiry": d.get("days_until_expiry"),
        })

    return {
        "ok": True,
        "data": {
            "count": len(rows),
            "rows": rows,
            "filters": {
                "status": status_filter,
                "document_type": doc_filter,
                "this_month": this_month,
                "employee": (employee or {}).get("name"),
            },
        },
        "count": len(rows),
        "rows": rows,
    }


def list_onboarding_status(action: dict[str, Any], *, company_code: str | None) -> dict[str, Any]:
    """Assistant read: onboarding completion + outstanding items. Modes:
    - missing_document: employees missing a specific item (e.g. civil_id, passport)
    - pending_items: employees with any pending onboarding item
    - completion: employees by onboarding status (default: not yet complete)
    Manager-scoped via viewer_phone; metadata only."""
    company = require_company_code(company_code)
    viewer_phone = action.get("viewer_phone")
    allowed_keys = manager_scope_employee_keys(company, viewer_phone)  # None => unrestricted

    text = normalize_text(action.get("prompt_text") or action.get("query") or "")
    doc_filter = _normalize_document_type_filter(action.get("document_type") or action.get("item") or text)
    status_filter = _normalize_onboarding_status_filter(action.get("status") or text)
    pending_only = bool(action.get("pending_only")) or "pending item" in text or "pending onboarding item" in text or "outstanding item" in text

    employees = company_employees(company)
    if allowed_keys is not None:
        employees = [e for e in employees if str(e.get("employee_key")) in allowed_keys]
    cards = {str(e.get("employee_key")): posthire_employee_card(e) for e in employees}
    keys = list(cards.keys())
    import onboarding_completion_contract as _completion

    done_states = set(_completion.SATISFIED_STATUSES)

    rows: list[dict[str, Any]] = []

    if doc_filter:
        mode = "missing_document"
        have_item: set[str] = set()
        submitted: set[str] = set()
        if keys:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT employee_key, status FROM onboarding_items "
                        "WHERE employee_key = ANY(%s) AND (item_id=%s OR document_type=%s)",
                        (keys, doc_filter, doc_filter),
                    )
                    for r in cur.fetchall():
                        k = str(r["employee_key"])
                        have_item.add(k)
                        if str(r.get("status") or "").lower() in done_states:
                            submitted.add(k)
        for k in keys:
            if k in have_item and k not in submitted:
                c = cards[k]
                rows.append({"employee_name": c["name"], "department": c["department"], "onboarding_status": c["onboarding_status"]})
    elif pending_only:
        mode = "pending_items"
        pending_map: dict[str, list[str]] = {}
        if keys:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT employee_key, COALESCE(NULLIF(label,''), NULLIF(document_type,''), item_id) AS label "
                        "FROM onboarding_items WHERE employee_key = ANY(%s) AND lower(status)='pending' "
                        "ORDER BY employee_key, required DESC NULLS LAST",
                        (keys,),
                    )
                    for r in cur.fetchall():
                        pending_map.setdefault(str(r["employee_key"]), []).append(str(r.get("label") or ""))
        for k, items in pending_map.items():
            c = cards.get(k) or {}
            rows.append({"employee_name": c.get("name"), "department": c.get("department"), "pending_items": items, "pending_count": len(items)})
    else:
        mode = "completion"
        complete_states = {"complete", "completed", "done"}
        for k in keys:
            c = cards[k]
            st = normalize_text(c["onboarding_status"]) or "not_started"
            is_complete = st in complete_states
            if status_filter == "complete" and not is_complete:
                continue
            if status_filter == "in_progress" and st != "in_progress":
                continue
            if status_filter == "not_started" and st != "not_started":
                continue
            if status_filter is None and is_complete:
                continue
            rows.append({"employee_name": c["name"], "department": c["department"], "onboarding_status": c["onboarding_status"]})

    return {
        "ok": True,
        "mode": mode,
        "data": {
            "count": len(rows),
            "rows": rows,
            "mode": mode,
            "filters": {"document_type": doc_filter, "status": status_filter, "pending_only": pending_only},
        },
        "count": len(rows),
        "rows": rows,
    }


def format_list_compliance_documents_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        return result.get("safe_user_message") or "I could not read compliance documents safely."
    data = result.get("data") or {}
    rows = data.get("rows") or []
    filters = data.get("filters") or {}
    status = filters.get("status")
    noun = {
        "expired": "expired document",
        "expiring_soon": "document expiring soon",
        "missing": "missing document",
        "needs_review": "document needing HR review",
        "valid": "valid document",
    }.get(status, "compliance document")
    if filters.get("this_month") and status in (None, "expiring_soon"):
        noun = "document expiring this month"
    if not rows:
        doc = filters.get("document_type")
        if doc and status == "missing":
            return f"No employees are missing {compliance_document_friendly_label(doc)}."
        if filters.get("this_month") and status in (None, "expiring_soon"):
            return "No documents are expiring this month."
        empty = {
            "expired": "No expired documents found.",
            "expiring_soon": "No documents are expiring soon.",
            "missing": "No missing documents found.",
            "needs_review": "No documents need HR review.",
            "valid": "No valid documents found.",
        }
        return empty.get(status, "No compliance documents found.")
    n = len(rows)
    lines = [f"{n} {noun}{'s' if n != 1 else ''}:"]
    for r in rows[:10]:
        label = r.get("document_label") or compliance_document_friendly_label(r.get("document_type"))
        piece = f"• {r.get('employee_name') or 'Employee'} — {label}"
        if r.get("status") in ("expired", "expiring_soon") and r.get("expiry_date"):
            piece += f" ({(r.get('status_label') or '').strip()} {str(r.get('expiry_date'))[:10]})".replace("  ", " ")
        elif status is None and r.get("status_label"):
            piece += f" ({r.get('status_label')})"
        lines.append(piece)
    if n > 10:
        lines.append(f"+{n - 10} more")
    return "\n".join(lines)


def format_list_onboarding_status_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        return result.get("safe_user_message") or "I could not read onboarding status safely."
    data = result.get("data") or {}
    rows = data.get("rows") or []
    mode = data.get("mode")
    filters = data.get("filters") or {}
    n = len(rows)
    if mode == "missing_document":
        doc_label = compliance_document_friendly_label(filters.get("document_type"))
        if not rows:
            return f"Everyone has submitted {doc_label}."
        lines = [f"{n} employee{'s' if n != 1 else ''} missing {doc_label}:"]
        for r in rows[:10]:
            dept = f" — {r.get('department')}" if r.get("department") else ""
            lines.append(f"• {r.get('employee_name') or 'Employee'}{dept}")
        if n > 10:
            lines.append(f"+{n - 10} more")
        return "\n".join(lines)
    if mode == "pending_items":
        if not rows:
            return "No employees have pending onboarding items."
        lines = [f"{n} employee{'s' if n != 1 else ''} with pending onboarding items:"]
        for r in rows[:10]:
            items = list(r.get("pending_items") or [])
            shown = ", ".join(items[:4]) + ("…" if len(items) > 4 else "")
            lines.append(f"• {r.get('employee_name') or 'Employee'} — {shown}")
        if n > 10:
            lines.append(f"+{n - 10} more")
        return "\n".join(lines)
    # completion
    if not rows:
        return "Everyone has completed onboarding."
    sf = filters.get("status")
    if sf == "complete":
        header = f"{n} employee{'s' if n != 1 else ''} have completed onboarding:"
    elif sf in ("in_progress", "not_started"):
        header = f"{n} employee{'s' if n != 1 else ''} are {sf.replace('_', ' ')}:"
    else:
        header = f"{n} employee{'s' if n != 1 else ''} have not completed onboarding:"
    lines = [header]
    for r in rows[:10]:
        lines.append(f"• {r.get('employee_name') or 'Employee'} — {r.get('onboarding_status')}")
    if n > 10:
        lines.append(f"+{n - 10} more")
    return "\n".join(lines)


# --- Compliance V1.1 actions (send reminder / mark reviewed) ----------------
# Buckets that represent an outstanding obligation HR can act on. "valid" is
# excluded — nothing to chase.
COMPLIANCE_OUTSTANDING_BUCKETS = ("expired", "expiring_soon", "missing", "needs_review")


def compliance_outstanding_docs(employee_key: str, document_type: str | None = None) -> list[dict[str, Any]]:
    """Compliance documents for one employee, tagged with their HR bucket using
    the same classifier the dashboard/worker use. When document_type is given the
    result is restricted to that document."""
    if not employee_key:
        return []
    sql = """
        SELECT employee_key, document_type, label, status, expiry_date,
               days_until_expiry, warning_days, last_alerted_at, last_reminded,
               reminder_count, renewal_status
        FROM compliance_documents
        WHERE employee_key=%s
    """
    params: list[Any] = [employee_key]
    if document_type:
        sql += " AND document_type=%s"
        params.append(document_type)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(sql, tuple(params))
            rows = [dict(r) for r in cur.fetchall()]
    tagged: list[dict[str, Any]] = []
    for row in rows:
        classification = classify_compliance_row(row)
        row["_bucket"] = compliance_bucket_for(classification.get("status"))
        row["_label"] = compliance_document_friendly_label(row.get("document_type"), row.get("label"))
        # Fresh days-until-expiry from the classifier (the stored column can be
        # stale); same definition the compliance dashboard uses.
        row["_days_until_expiry"] = classification.get("days_until_expiry")
        tagged.append(row)
    return tagged


def compliance_reminder_message(employee: dict[str, Any], docs: list[dict[str, Any]]) -> str:
    """HR-safe, employee-facing reminder. Never exposes raw statuses/codes."""
    name = employee.get("name") or "there"
    seen: list[str] = []
    for doc in docs:
        label = doc.get("_label")
        if label and label not in seen:
            seen.append(label)
    if not seen:
        return f"Hi {name}, your documents are up to date. Thank you."
    if len(seen) == 1:
        return f"Hi {name}, please send an up-to-date copy of your {seen[0]} so HR can keep your records current."
    return (
        f"Hi {name}, please send up-to-date copies of these documents so HR can keep your "
        f"records current: {format_inline_list(seen)}."
    )


def mark_compliance_reminded(employee_key: str, document_type: str | None) -> dict[str, Any]:
    sql = """
        UPDATE compliance_documents
        SET last_alerted_at=now(), last_reminded=CURRENT_DATE,
            reminder_count=COALESCE(reminder_count, 0) + 1, updated_at=now()
        WHERE employee_key=%s
    """
    params: list[Any] = [employee_key]
    if document_type:
        sql += " AND document_type=%s"
        params.append(document_type)
    sql += " RETURNING document_type, reminder_count"
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(sql, tuple(params))
            rows = [dict(r) for r in cur.fetchall()]
        conn.commit()
    return {"updated": len(rows), "documents": json_safe(rows)}


def send_compliance_reminder(employee: dict[str, Any], document_type: str | None, account_id: str | None) -> dict[str, Any]:
    """Nudge an employee (WhatsApp) about outstanding compliance documents.

    Mirrors send_onboarding_reminder: builds an HR-safe message, sends through the
    standard employee delivery path, and on a successful send bumps reminder
    bookkeeping so the worker's cooldown and the dashboard stay consistent.
    """
    employee_key = str(employee.get("employee_key") or "")
    docs = compliance_outstanding_docs(employee_key, document_type)
    if document_type and not docs:
        return {"ok": False, "error": "document_not_found", "safe_user_message": "I could not find that document for this employee."}
    outstanding = [d for d in docs if d.get("_bucket") in COMPLIANCE_OUTSTANDING_BUCKETS]
    if not outstanding:
        name = employee.get("name") or "This employee"
        return {"ok": False, "error": "nothing_outstanding", "safe_user_message": f"{name} has no missing or expiring documents to remind about."}
    body = compliance_reminder_message(employee, outstanding)
    # Phase D: route compliance reminders through the delivery layer when enabled.
    # Compliance is critical + metadata-only (the body lists document types, so the
    # stored preview is a generic label, never the full text). Reminder bookkeeping
    # is bumped only when the employee was actually reached on some channel.
    if outbound_flow_enabled("compliance"):
        primary_label = next((d.get("_label") for d in outstanding if d.get("_label")), None)
        expiry_date = ""
        # Prefer the expiring template when every outstanding row is expiry-driven.
        expiry_buckets = {"expired", "expiring_soon"}
        all_expiry = bool(outstanding) and all(str(d.get("_bucket") or "") in expiry_buckets for d in outstanding)
        template_key = "compliance_document_expiring" if all_expiry else "compliance_document_required"
        if all_expiry:
            first = outstanding[0]
            expiry_date = str(first.get("expiry_date") or first.get("_expiry_date") or "")[:10]
        variables = {"document_type": primary_label or "document"}
        if expiry_date:
            variables["expiry_date"] = expiry_date
        notification = deliver_employee_notification(
            employee,
            flow="compliance",
            template_key=template_key,
            text=body,
            email_subject="A document HR needs from you" if not all_expiry else "A document is expiring soon",
            account_id=account_id,
            variables=variables,
            extra={"documents": json_safe(outstanding)},
        )
        notification["reminder_update"] = mark_compliance_reminded(employee_key, document_type) if notification.get("ok") else {}
        return notification
    result = send_octopus_whatsapp(
        account_id=account_id,
        phone=employee.get("phone") or "",
        text=body,
        subject_type="employee",
        subject_key=employee.get("employee_key"),
        message_kind="compliance_reminder",
    )
    reminder_update: dict[str, Any] = {}
    if result.get("ok"):
        reminder_update = mark_compliance_reminded(employee_key, document_type)
    return {
        "ok": result.get("ok", False),
        "send": result,
        "message": body,
        "employee": json_safe(employee),
        "reminder_update": reminder_update,
        "documents": json_safe(outstanding),
    }


def mark_compliance_reviewed(employee: dict[str, Any], document_type: str, note: str | None = None) -> dict[str, Any]:
    """Mark a document as HR reviewed (not government verified). Clears pending
    review; expiry-bearing docs are still re-derived by the classifier."""
    employee_key = str(employee.get("employee_key") or "")
    company = require_company_code(employee.get("company_code"))
    if not document_type:
        return {"ok": False, "error": "document_type_required", "safe_user_message": "Tell me which document to mark as reviewed."}
    # Prefer governed journey approve when a pending version exists.
    try:
        import kuwait_pilot_document_journey as _kw_doc_journey

        approved = _kw_doc_journey.approve_version(
            sys.modules[__name__],
            company_code=company,
            employee_key=employee_key,
            document_type=document_type,
            actor_user_id="legacy_mark_reviewed",
            permissions={_kw_doc_journey.DOCUMENT_REVIEW_MANAGE},
            reason=note,
            confirm_ocr=False,
        )
        return {
            "ok": True,
            "reviewed": [json_safe(approved)],
            "document_label": compliance_document_friendly_label(document_type),
            "employee": json_safe(employee),
            "legitimacy": "hr_reviewed_only_not_government_verified",
        }
    except Exception:
        pass
    with db_connect() as conn:
        with conn.cursor() as cur:
            if note:
                cur.execute(
                    """
                    UPDATE compliance_documents
                    SET status='valid', renewal_status='reviewed', notes=%s,
                        last_checked_at=now(), updated_at=now()
                    WHERE employee_key=%s AND document_type = ANY(%s)
                    RETURNING document_type, label, status, renewal_status
                    """,
                    (note, employee_key, list({document_type, "residence", "residency", "residency_iqama"}) if document_type in {"residence", "residency", "residency_iqama"} else [document_type]),
                )
            else:
                cur.execute(
                    """
                    UPDATE compliance_documents
                    SET status='valid', renewal_status='reviewed',
                        last_checked_at=now(), updated_at=now()
                    WHERE employee_key=%s AND document_type = ANY(%s)
                    RETURNING document_type, label, status, renewal_status
                    """,
                    (employee_key, list({document_type, "residence", "residency", "residency_iqama"}) if document_type in {"residence", "residency", "residency_iqama"} else [document_type]),
                )
            rows = [dict(r) for r in cur.fetchall()]
        conn.commit()
    if not rows:
        return {"ok": False, "error": "document_not_found", "safe_user_message": "I could not find that document to review."}
    return {
        "ok": True,
        "reviewed": json_safe(rows),
        "document_label": compliance_document_friendly_label(document_type, rows[0].get("label")),
        "employee": json_safe(employee),
        "legitimacy": "hr_reviewed_only_not_government_verified",
    }


def extraction_field_values(extraction: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(extraction, dict):
        return {
            "document_number": None,
            "issued_date": None,
            "expiry_date": None,
            "status": None,
            "error": None,
            "confidence": None,
        }
    try:
        confidence = float(extraction.get("confidence")) if extraction.get("confidence") is not None else None
    except Exception:
        confidence = None
    return {
        "document_number": str(extraction.get("document_number") or "").strip() or None,
        "issued_date": extraction.get("issued_date_parsed") or parse_iso_date(extraction.get("issued_date")),
        "expiry_date": extraction.get("expiry_date_parsed") or parse_iso_date(extraction.get("expiry_date")),
        "status": str(extraction.get("extraction_status") or "").strip() or None,
        "error": str(extraction.get("extraction_error") or "").strip() or None,
        "confidence": confidence,
    }


def apply_document_extraction(
    cur: Any,
    *,
    employee_key: str,
    document_type: str,
    document_id: str | None,
    extraction: dict[str, Any],
) -> None:
    values = extraction_field_values(extraction)
    extraction_json = Json(json_safe(extraction))
    if document_id:
        cur.execute(
            """
            UPDATE employee_documents
            SET metadata=jsonb_set(metadata, '{extraction}', %s::jsonb, true),
                document_number=COALESCE(%s, document_number),
                issued_at=COALESCE(%s, issued_at),
                expiry_date=COALESCE(%s, expiry_date),
                extraction_status=%s,
                extraction_error=%s,
                extraction_confidence=%s,
                extracted_at=now(),
                updated_at=now()
            WHERE document_id=%s
            """,
            (
                extraction_json,
                values["document_number"],
                values["issued_date"],
                values["expiry_date"],
                values["status"],
                values["error"],
                values["confidence"],
                document_id,
            ),
        )
    cur.execute(
        """
        UPDATE compliance_documents
        SET raw_json=jsonb_set(raw_json, '{extraction}', %s::jsonb, true),
            document_number=COALESCE(%s, document_number),
            issued_date=COALESCE(%s, issued_date),
            expiry_date=COALESCE(%s, expiry_date),
            days_until_expiry=CASE WHEN %s::date IS NULL THEN days_until_expiry ELSE (%s::date - CURRENT_DATE) END,
            extraction_status=%s,
            extraction_error=%s,
            extraction_confidence=%s,
            extracted_at=now(),
            updated_at=now()
        WHERE employee_key=%s AND document_type=%s
        """,
        (
            extraction_json,
            values["document_number"],
            values["issued_date"],
            values["expiry_date"],
            values["expiry_date"],
            values["expiry_date"],
            values["status"],
            values["error"],
            values["confidence"],
            employee_key,
            document_type,
        ),
    )


def run_document_extraction_backfill(*, dry_run: bool = True, limit: int = 25, force: bool = False) -> dict[str, Any]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT document_id, employee_key, phone, company_code, document_type, filename, local_path, mime_type, extraction_status
                FROM employee_documents
                WHERE document_type IN (
                    'civil_id','passport','medical','residency','residence','work_permit',
                    'education_cert','employment_contract','contract_amendment'
                  )
                  AND local_path IS NOT NULL
                  AND (%s OR extraction_status IS NULL OR extraction_status IN ('failed','low_confidence'))
                ORDER BY updated_at DESC
                LIMIT %s
                """,
                (force, max(1, min(limit, 100))),
            )
            rows = [dict(row) for row in cur.fetchall()]
    results: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for row in rows:
        company_code = row.get("company_code")
        if not (company_has_module(company_code, "onboarding") or company_has_module(company_code, "compliance")):
            skipped.append({
                "document_id": row.get("document_id"),
                "employee_key": row.get("employee_key"),
                "company_code": company_code,
                "document_type": row.get("document_type"),
                "reason": "posthire_modules_disabled",
            })
            continue
        media = {
            "local_path": row.get("local_path"),
            "mime_type": row.get("mime_type") or mimetypes.guess_type(str(row.get("local_path") or ""))[0] or "image/jpeg",
            "filename": row.get("filename"),
        }
        extraction = extract_compliance_document_metadata(
            document_type=str(row.get("document_type") or ""),
            text=str(row.get("filename") or ""),
            media=media,
            company_code=company_code,
            subject_key=str(row.get("employee_key") or "") or None,
            channel="compliance_backfill",
        )
        entry = {
            "document_id": row.get("document_id"),
            "employee_key": row.get("employee_key"),
            "document_type": row.get("document_type"),
            "extraction": json_safe(extraction),
            "dry_run": dry_run,
        }
        if extraction and not dry_run:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    apply_document_extraction(
                        cur,
                        employee_key=str(row.get("employee_key") or ""),
                        document_type=str(row.get("document_type") or ""),
                        document_id=str(row.get("document_id") or ""),
                        extraction=extraction,
                    )
                conn.commit()
        results.append(entry)
    return {"ok": True, "dry_run": dry_run, "count": len(results), "skipped_count": len(skipped), "results": results, "skipped": skipped}


def internal_configured_token() -> str | None:
    value = os.environ.get("WATHEFNI_INTERNAL_TOKEN")
    value = str(value or "").strip()
    return value or None


def require_internal_access(
    authorization: str | None = Header(default=None),
    x_internal_token: str | None = Header(default=None, alias="X-Internal-Token"),
) -> dict[str, Any]:
    """Fail-closed gate for internal/operator-only orchestrator routes (audit,
    debug, and worker triggers). These are not part of the client dashboard and
    must never be reachable without the shared internal secret. Denies when the
    secret is unconfigured so a missing env var can never leave a route open."""
    configured = internal_configured_token()
    provided = bearer_token(authorization) or str(x_internal_token or "").strip()
    if not configured or not provided or not hmac.compare_digest(provided, configured):
        raise HTTPException(
            status_code=401,
            detail={"error": "internal_auth_failed", "message": "Internal access was rejected."},
        )
    return {"is_internal": True}


def require_internal_principal(
    authorization: str | None = Header(default=None),
    x_internal_token: str | None = Header(default=None, alias="X-Internal-Token"),
) -> dict[str, Any]:
    """Resolve an internal caller to a principal with a real scope.

    R2: the shared platform token is no longer the only internal identity. A
    company-scoped token (WATHEFNI_INTERNAL_TENANT_TOKENS) resolves to a tenant
    principal that cannot read or write another company, which is what makes the
    cross-tenant negative tests provable rather than aspirational.
    """
    provided = bearer_token(authorization) or str(x_internal_token or "").strip()
    principal = _internal_authority.resolve_principal(provided)
    if principal is None:
        raise HTTPException(
            status_code=401,
            detail={"error": "internal_auth_failed", "message": "Internal access was rejected."},
        )
    return principal


app = FastAPI(title="OctoHR API")

# Authenticated surface reads carry per-actor business state. Without an explicit
# directive an OS-level HTTP cache may reuse a response the app cannot invalidate,
# which is exactly how a mounted screen goes stale after another surface writes.
# Streaming endpoints set their own directives and are left alone.
_NO_STORE_PREFIXES = ("/dashboard/", "/app/")
_NO_STORE_SKIP = ("/stream", "/events", "/sse")


@app.middleware("http")
async def _no_store_on_authenticated_surface_reads(request: Request, call_next):
    response = await call_next(request)
    path = request.url.path
    if (
        path.startswith(_NO_STORE_PREFIXES)
        and not any(part in path for part in _NO_STORE_SKIP)
        and "Cache-Control" not in response.headers
    ):
        response.headers["Cache-Control"] = "no-store"
    return response


@app.on_event("startup")
def on_startup() -> None:
    assert_legacy_dashboard_auth_safe_at_startup()
    assert_runtime_environment_binding()
    ensure_schema()


@app.get("/health")
def health():
    """Liveness only. Auth flags and schema apply stay off this public probe."""
    return {
        "status": "ok",
        "runtime": "toolcall_fastapi",
        "liveness": True,
        "environment_binding": runtime_environment_readiness(),
        "permission_authority": "backend_current_required",
    }


@app.get("/ready")
def ready():
    """Readiness: environment, schema, migrations, and trusted authority."""
    ensure_schema()
    legacy_on = legacy_dashboard_token_auth_enabled()
    link_signing = _link_secrets.status()
    delivery = _observability.delivery_snapshot(sys.modules[__name__])
    migrations = delivery.get("migrations") or {}
    ready_ok = bool(migrations.get("ok", True))
    payload = {
        "status": "ready" if ready_ok else "not_ready",
        "environment_binding": runtime_environment_readiness(),
        "permission_authority": "backend_current_required",
        "legacy_dashboard_token_auth": legacy_on,
        "trusted_authority_enforced": not legacy_on,
        # R2: a missing dedicated signing secret degrades the public link
        # capabilities rather than silently signing with a fallback key.
        "link_signing": link_signing,
        "public_link_capabilities_available": bool(link_signing.get("ok")),
        "delivery": delivery,
    }
    if ready_ok:
        return payload
    return JSONResponse(status_code=503, content=payload)


