@app.get("/orchestrator/debug/llm-usage")
def orchestrator_debug_llm_usage(hours: int = Query(default=24, ge=1, le=168), _internal: dict[str, Any] = Depends(require_internal_access)):
    ensure_schema()
    hours = max(1, min(hours, 168))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT count(*) AS calls,
                       count(DISTINCT turn_id) FILTER (WHERE turn_id IS NOT NULL) AS turns_with_llm,
                       COALESCE(sum(input_tokens), 0) AS input_tokens,
                       COALESCE(sum(output_tokens), 0) AS output_tokens,
                       COALESCE(sum(cached_tokens), 0) AS cached_tokens,
                       COALESCE(sum(total_tokens), 0) AS total_tokens,
                       COALESCE(sum(estimated_input_tokens), 0) AS estimated_input_tokens,
                       COALESCE(avg(latency_ms), 0) AS avg_latency_ms
                FROM llm_call_logs
                WHERE created_at > now() - (%s || ' hours')::interval
                """,
                (hours,),
            )
            totals = dict(cur.fetchone() or {})
            cur.execute(
                """
                SELECT call_name, model, prompt_mode, status, count(*) AS calls,
                       COALESCE(sum(input_tokens), 0) AS input_tokens,
                       COALESCE(sum(output_tokens), 0) AS output_tokens,
                       COALESCE(sum(cached_tokens), 0) AS cached_tokens,
                       COALESCE(sum(total_tokens), 0) AS total_tokens,
                       COALESCE(sum(estimated_input_tokens), 0) AS estimated_input_tokens,
                       COALESCE(avg(latency_ms), 0) AS avg_latency_ms
                FROM llm_call_logs
                WHERE created_at > now() - (%s || ' hours')::interval
                GROUP BY call_name, model, prompt_mode, status
                ORDER BY calls DESC
                """,
                (hours,),
            )
            by_call = [dict(row) for row in cur.fetchall()]
            cur.execute(
                """
                SELECT ht.intent, ht.turn_focus, count(DISTINCT ht.turn_id) AS turns, count(l.call_id) AS llm_calls,
                       COALESCE(sum(l.total_tokens), 0) AS total_tokens,
                       COALESCE(sum(l.estimated_input_tokens), 0) AS estimated_input_tokens
                FROM hr_turns ht
                LEFT JOIN llm_call_logs l ON l.turn_id=ht.turn_id
                WHERE ht.created_at > now() - (%s || ' hours')::interval
                GROUP BY ht.intent, ht.turn_focus
                ORDER BY llm_calls DESC, turns DESC
                LIMIT 30
                """,
                (hours,),
            )
            by_route = [dict(row) for row in cur.fetchall()]
    return {"hours": hours, "totals": json_safe(totals), "by_call": json_safe(by_call), "by_route": json_safe(by_route)}


