def assistant_dashboard_context(context: dict[str, Any] = Depends(dashboard_context)) -> dict[str, Any]:
    """Platform Assistant session gate — workspace/module-aware, not pre_hiring-only.

    Any authenticated dashboard actor whose company has at least one
    Assistant-capable module enabled and who holds a matching permission may
    open chat/capabilities. Individual tools still re-check module + RBAC +
    manager scope + channel readiness at execute time.
    """
    company = str(context.get("company_code") or "").strip().upper()
    if not company:
        raise HTTPException(
            status_code=403,
            detail={"error": "assistant_unavailable", "message": "Company context is required for Assistant."},
        )
    modules = configured_company_modules(company)
    if not (modules & ASSISTANT_OFFERABLE_MODULES):
        raise HTTPException(
            status_code=403,
            detail={
                "error": "assistant_unavailable",
                "message": "No Assistant-capable modules are enabled for this company.",
                "company_code": company,
            },
        )
    perms = context_permissions(context)
    if not (perms & ASSISTANT_OFFERABLE_PERMISSIONS):
        raise HTTPException(
            status_code=403,
            detail={
                "error": "permission_denied",
                "message": "You do not have permission to use OctoHR Assistant.",
                "role": context.get("actor_role"),
            },
        )
    return context


def workspace_dashboard_context(context: dict[str, Any] = Depends(dashboard_context)) -> dict[str, Any]:
    """Core workspace authorization, independent of product modules when the
    Phase 3 boot is enabled. With the flag off it preserves the historical
    pre_hiring gate exactly for an instant, behavior-safe rollback."""
    if not workspace_boot_enabled():
        return prehire_dashboard_context(context)
    return context


def require_workspace_permission(context: dict[str, Any], permission: str) -> dict[str, Any]:
    if not workspace_boot_enabled():
        return require_entitlement(context, "pre_hiring", permission)
    if not dashboard_context_has_permission(context, permission):
        raise HTTPException(
            status_code=403,
            detail={
                "error": "permission_denied",
                "message": "You do not have access to do that.",
                "required_permission": permission,
                "role": context.get("actor_role"),
            },
        )
    return context


def assessments_dashboard_context(context: dict[str, Any] = Depends(prehire_dashboard_context)) -> dict[str, Any]:
    return require_entitlement(context, "assessments", "prehire.read")


@app.post("/dashboard/auth/login")
def dashboard_auth_login(request: DashboardLoginRequest, http_request: Request):
    """HR web sign-in.

    R2 ordering matters: credentials are proven first, and only then do we report
    company or account state. Checking company lifecycle up front turned this
    endpoint into a tenant/email oracle. Every rejected attempt returns the same
    401 regardless of whether the company, the email, or the password was wrong.
    """
    ensure_schema()
    company = str(request.company_code or "").strip().upper()
    email = normalize_email(request.email)
    route = "/dashboard/auth/login"
    source = _rate_limit.client_source(http_request)
    dimensions = {"source": source, "identity": f"{company}|{email}"}

    _rate_limit.guard(_security_host(), "dashboard_login", route=route, dimensions=dimensions, company_code=company or None)

    def _rejected() -> HTTPException:
        _rate_limit.record_failure(
            _security_host(),
            "dashboard_login",
            route=route,
            dimensions=dimensions,
            company_code=company or None,
            denial_class="dashboard_auth_failed",
        )
        return HTTPException(
            status_code=401,
            detail={"error": "dashboard_auth_failed", "message": "Access needs to be verified."},
        )

    user = dashboard_user_by_email(company, email) if company and email else None
    if user and dashboard_password_ok(request.password, user.get("password_hash")):
        # Credentials proven — post-authentication state may now be disclosed.
        require_active_company(company)
        if normalize_dashboard_user_status(user.get("status")) != "active":
            raise HTTPException(status_code=403, detail={"error": "account_inactive", "message": "Your account is not active."})
        token, expires_at = create_dashboard_session(user)
        _rate_limit.reset(_security_host(), "dashboard_login", dimensions=dimensions)
        return dashboard_auth_response(user, token, expires_at)

    configured = dashboard_configured_token()
    if (
        request.token
        and configured
        and hmac.compare_digest(str(request.token).strip(), configured)
        and legacy_dashboard_token_auth_enabled()
    ):
        phone = digits(request.hr_phone)
        legacy_company = require_company_code(company or hr_company_code(phone))
        require_active_company(legacy_company)
        seeded = dashboard_seed_user_from_hr_phone(legacy_company, phone)
        if seeded:
            if dashboard_user_public(seeded)["status"] != "active":
                raise HTTPException(status_code=403, detail={"error": "account_inactive", "message": "Your account is not active."})
            token, expires_at = create_dashboard_session(seeded)
            _rate_limit.reset(_security_host(), "dashboard_login", dimensions=dimensions)
            return dashboard_auth_response(seeded, token, expires_at)

    raise _rejected()


@app.get("/dashboard/auth/me")
def dashboard_auth_me(context: dict[str, Any] = Depends(dashboard_context)):
    company = context["company_code"]
    return {
        "company_code": company,
        "enabled_modules": sorted(configured_company_modules(company)),
        "access": context.get("access"),
        "user": dashboard_user_public(context.get("hr_user")),
    }


@app.get("/dashboard/bootstrap")
def dashboard_workspace_bootstrap(context: dict[str, Any] = Depends(dashboard_context)):
    """Module-agnostic workspace bootstrap.

    This is the only universal dashboard boot payload. Product data remains on
    its module-gated endpoints. Kept behind WATHEFNI_WORKSPACE_BOOT while the
    frontend and post-hire-only tenant path are dark-launched.
    """
    if not workspace_boot_enabled():
        raise HTTPException(status_code=404, detail={"error": "not_found", "message": "Not found."})
    company = context["company_code"]
    configured = configured_company_modules(company)
    effective = effective_company_modules(company)
    timezone_name = str(get_company_settings(company).get("timezone") or "Asia/Kuwait").strip() or "Asia/Kuwait"
    import prehire_visibility as _pv

    policy = company_prehire_visibility_policy(company)
    plan = _pv.resolve_visibility_plan(
        policy=policy,
        role=dashboard_context_role_key(context),
        surface="detail",
    )
    import action_inbox_wave1 as _inbox

    hr_user = context.get("hr_user") if isinstance(context.get("hr_user"), dict) else {}
    action_inbox_nav = _inbox.nav_offerable_for_viewer(
        company_code=company,
        phone=context.get("hr_phone") or context.get("actor_phone") or hr_user.get("phone"),
        user_id=context.get("actor_user_id") or hr_user.get("user_id"),
        email=context.get("actor_email") or hr_user.get("email"),
    )
    return {
        "company_code": company,
        "configured_modules": sorted(configured),
        "effective_modules": sorted(effective),
        # Compatibility name used by existing dashboard module helpers.
        "enabled_modules": sorted(effective),
        "module_catalog": dashboard_module_catalog_payload(company),
        "access": context.get("access"),
        "user": dashboard_user_public(context.get("hr_user")),
        "timezone": timezone_name,
        "prehire_visibility_policy": policy,
        **_pv.visibility_meta(plan),
        "action_inbox": {
            "offerable": bool(action_inbox_nav),
            "wave_enabled": _inbox.action_inbox_wave1_enabled_for_company(company),
            "viewer_allowlisted": bool(action_inbox_nav),
            "real_canary_enabled": bool(_inbox.real_viewer_allowlist())
            and bool(_inbox.real_subject_allowlist()),
            "exclude_payroll": _inbox.exclude_payroll_stream(),
        },
    }


@app.post("/dashboard/auth/logout")
def dashboard_auth_logout(authorization: str | None = Header(default=None), x_dashboard_token: str | None = Header(default=None, alias="X-Dashboard-Token")):
    token = bearer_token(authorization) or str(x_dashboard_token or "").strip()
    if token:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute("UPDATE dashboard_user_sessions SET status='revoked' WHERE token_hash=%s", (dashboard_token_hash(token),))
            conn.commit()
    return {"ok": True}


