@app.post("/dashboard/team/invites/accept")
def dashboard_team_accept_invite(request: DashboardAcceptInviteRequest):
    ensure_schema()
    if len(str(request.password or "")) < 8:
        raise HTTPException(status_code=422, detail={"error": "password_too_short", "message": "Password must be at least 8 characters."})
    token_hash = dashboard_token_hash(request.invite_token)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM dashboard_user_invites
                WHERE token_hash=%s AND status='pending' AND expires_at > now()
                LIMIT 1
                """,
                (token_hash,),
            )
            invite = cur.fetchone()
            if not invite:
                raise HTTPException(status_code=404, detail={"error": "invite_not_found", "message": "This invite is no longer available."})
            company = str(invite["company_code"]).upper()
            require_active_company(company)
            email = normalize_email(invite["email"])
            role = dashboard_role_key(invite["role"])
            cur.execute(
                """
                INSERT INTO dashboard_users (company_code, email, name, phone, role, status, password_hash, invited_by_user_id, invited_at, accepted_at, updated_at)
                VALUES (%s,%s,%s,%s,%s,'active',%s,%s,%s,now(),now())
                ON CONFLICT (company_code, email)
                DO UPDATE SET name=EXCLUDED.name,
                              phone=COALESCE(EXCLUDED.phone, dashboard_users.phone),
                              role=EXCLUDED.role,
                              status='active',
                              password_hash=EXCLUDED.password_hash,
                              accepted_at=now(),
                              updated_at=now()
                RETURNING *
                """,
                (
                    company,
                    email,
                    str(request.name or "").strip(),
                    digits(request.phone) or None,
                    role,
                    dashboard_password_hash(request.password),
                    invite.get("invited_by_user_id"),
                    invite.get("created_at"),
                ),
            )
            user = dict(cur.fetchone() or {})
            metadata = user.get("metadata") if isinstance(user.get("metadata"), dict) else {}
            if str(metadata.get("source") or "") == "legacy_hr_phone_bootstrap":
                cur.execute(
                    """
                    UPDATE dashboard_users
                    SET metadata=COALESCE(metadata, '{}'::jsonb) || %s,
                        updated_at=now()
                    WHERE company_code=%s AND user_id=%s
                    RETURNING *
                    """,
                    (
                        Json(
                            {
                                "source": "workspace",
                                "promoted_from": "legacy_hr_phone_bootstrap",
                                "promoted_via": "team_invite_accept",
                                "promoted_at": now_utc().isoformat(),
                                "review_reference": f"invite:{invite.get('invite_id')}",
                            }
                        ),
                        company,
                        user.get("user_id"),
                    ),
                )
                user = dict(cur.fetchone() or user)
            cur.execute(
                "UPDATE dashboard_user_invites SET status='accepted', accepted_by_user_id=%s, accepted_at=now() WHERE invite_id=%s",
                (user.get("user_id"), invite.get("invite_id")),
            )
            if user.get("phone"):
                cur.execute(
                    """
                    INSERT INTO dashboard_whatsapp_identities (company_code, user_id, phone, status, updated_at)
                    VALUES (%s,%s,%s,'active',now())
                    ON CONFLICT (company_code, phone)
                    DO UPDATE SET user_id=EXCLUDED.user_id, status='active', updated_at=now()
                    """,
                    (company, user.get("user_id"), digits(user.get("phone"))),
                )
            if dashboard_role_key(user.get("role")) == "owner":
                import setup_owner_bootstrap as _owner_boot

                bootstrap = _owner_boot.apply_owner_bootstrap_grants(
                    cur,
                    company_code=company,
                    user_id=str(user.get("user_id") or ""),
                    granted_by_user_id=str(user.get("user_id") or ""),
                )
                write_admin_audit(
                    cur,
                    {
                        "company_code": company,
                        "actor_user_id": user.get("user_id"),
                        "actor_email": user.get("email"),
                        "actor_role": user.get("role"),
                        "hr_user": user,
                    },
                    "setup_owner_bootstrap_grants",
                    summary=f"Applied {_owner_boot.BUNDLE_VERSION} grants on owner invite accept.",
                    target_type="team_member",
                    target=str(user.get("email") or user.get("user_id") or ""),
                    details={
                        "company_code": company,
                        "user_id": str(user.get("user_id") or ""),
                        "bundle_version": _owner_boot.BUNDLE_VERSION,
                        "granted": bootstrap.get("granted"),
                        "already_present": bootstrap.get("already_present"),
                        "source": "invite_accept",
                    },
                )
        conn.commit()
    token, expires_at = create_dashboard_session(user)
    return dashboard_auth_response(user, token, expires_at)


@app.get("/dashboard/team")
def dashboard_team_list(context: dict[str, Any] = Depends(workspace_dashboard_context)):
    """Team directory with Wave 6 privacy tiers.

    Admin (users.manage or authorized HR admin with settings.manage): full team
    contacts + (for users.manage only) permission matrices and invites.
    Collaboration: name + role + status only — no peer emails/phones/permissions.
    """
    import prehire_team_directory as _td

    company = context["company_code"]
    actor_user_id = str(context.get("actor_user_id") or (context.get("hr_user") or {}).get("user_id") or "")
    can_manage_users = dashboard_context_has_permission(context, "users.manage")
    can_manage_settings = dashboard_context_has_permission(context, "settings.manage")
    view = _td.resolve_directory_view(
        can_manage_users=can_manage_users,
        can_manage_settings=can_manage_settings,
        actor_role=dashboard_context_role_key(context),
    )
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT user_id, company_code, email, name, phone, role, status, last_active_at, invited_at, accepted_at, created_at, metadata
                FROM dashboard_users
                WHERE company_code=%s
                ORDER BY
                  CASE status WHEN 'active' THEN 0 WHEN 'invited' THEN 1 ELSE 2 END,
                  lower(name), email
                LIMIT 500
                """,
                (company,),
            )
            raw_users = [dict(row) for row in cur.fetchall()]
            invites: list[dict[str, Any]] = []
            if can_manage_users:
                cur.execute(
                    """
                    SELECT invite_id, company_code, email, role, status, expires_at, created_at
                    FROM dashboard_user_invites
                    WHERE company_code=%s AND status='pending' AND expires_at > now()
                    ORDER BY created_at DESC
                    LIMIT 100
                    """,
                    (company,),
                )
                invites = [json_safe(dict(row)) for row in cur.fetchall()]
            # Which of these users currently have an ACTIVE WhatsApp identity in
            # THIS company. Company-scoped + status='active' so a disabled/relinked
            # row never counts. Used only to show a calm "linked / not linked"
            # badge — no phone numbers are exposed by this.
            cur.execute(
                "SELECT DISTINCT user_id FROM dashboard_whatsapp_identities WHERE company_code=%s AND status='active'",
                (company,),
            )
            linked_user_ids = {str(row["user_id"]) for row in cur.fetchall() if row.get("user_id")}

    users: list[dict[str, Any]] = []
    for row in raw_users:
        public = dashboard_user_public(row)
        public["whatsapp_linked"] = str(public.get("user_id") or "") in linked_user_ids
        projected = _td.project_team_member(
            {**public, "_effective_permissions": public.get("permissions")},
            view=view,
            actor_user_id=actor_user_id,
            include_permissions=can_manage_users,
            role_label_resolver=lambda role: ROLE_LABELS.get(role, role.replace("_", " ").title()),
        )
        users.append(json_safe(projected))

    payload: dict[str, Any] = {
        "company_code": company,
        "users": users,
        "invites": invites if can_manage_users else [],
        "directory_view": view,
        "can_manage_team": can_manage_users,
    }
    if can_manage_users:
        payload["role_capabilities"] = {role: hr_role_permissions(role) for role in ROLE_PERMISSIONS}
    return payload


@app.get("/dashboard/team/people")
def dashboard_team_people_picker(
    purpose: str = "recruiter",
    q: str | None = None,
    limit: int = 50,
    context: dict[str, Any] = Depends(workspace_dashboard_context),
):
    """Searchable privacy-safe people picker for ownership / assignment surfaces."""
    import prehire_team_directory as _td

    try:
        purpose_key = _td.normalize_picker_purpose(purpose)
    except ValueError as exc:
        raise HTTPException(
            status_code=422,
            detail={"error": "invalid_picker_purpose", "message": "Unknown people picker purpose."},
        ) from exc
    # Assignment pickers require pre-hire (or post-hire for approver) workspace access.
    company = context["company_code"]
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT user_id, company_code, email, name, phone, role, status
                FROM dashboard_users
                WHERE company_code=%s AND status='active'
                ORDER BY lower(COALESCE(NULLIF(name, ''), email)), email
                LIMIT 500
                """,
                (company,),
            )
            rows = [dict(row) for row in cur.fetchall()]
    people = _td.filter_users_for_picker(
        rows,
        purpose=purpose_key,
        query=q,
        role_label_resolver=lambda role: ROLE_LABELS.get(role, role.replace("_", " ").title()),
        limit=limit,
    )
    return {
        "company_code": company,
        "purpose": purpose_key,
        "q": (q or "").strip() or None,
        "people": people,
        "unassigned_allowed": purpose_key in {_td.PURPOSE_RECRUITER, _td.PURPOSE_HIRING_MANAGER, _td.PURPOSE_TASK_OWNER},
        "directory_view": _td.VIEW_COLLABORATION,
    }


@app.post("/dashboard/team/invites")
def dashboard_team_invite_user(request: DashboardInviteUserRequest, context: dict[str, Any] = Depends(workspace_dashboard_context)):
    require_workspace_permission(context, "users.manage")
    company = context["company_code"]
    email = normalize_email(request.email)
    role = dashboard_role_key(request.role)
    if not email or "@" not in email:
        raise HTTPException(status_code=422, detail={"error": "invalid_email", "message": "Enter a valid email address."})
    if not dashboard_role_allowed(request.role):
        raise HTTPException(status_code=422, detail={"error": "invalid_role", "message": "You do not have permission to do this action."})
    # Phase 4: cannot grant a role whose preset exceeds the actor's effective permissions.
    import setup_console_admin_phase4 as _p4

    actor_perms = context_permissions(context)
    allowed, deny_reason = _p4.role_grant_allowed(actor_permissions=actor_perms, target_role=request.role, legacy=sys.modules[__name__])
    if not allowed:
        raise HTTPException(
            status_code=403,
            detail={
                "error": deny_reason or "privilege_escalation_denied",
                "message": "You can only assign roles within your own access level.",
                "message_ar": "يمكنك تعيين الأدوار ضمن مستوى وصولك فقط.",
            },
        )
    invite_token = secrets.token_urlsafe(32)
    expires_at = now_utc() + timedelta(days=14)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO dashboard_users (company_code, email, name, phone, role, status, invited_by_user_id, invited_at, updated_at)
                VALUES (%s,%s,%s,%s,%s,'invited',%s,now(),now())
                ON CONFLICT (company_code, email)
                DO UPDATE SET role=EXCLUDED.role,
                              name=CASE WHEN dashboard_users.name='' THEN EXCLUDED.name ELSE dashboard_users.name END,
                              phone=COALESCE(EXCLUDED.phone, dashboard_users.phone),
                              status=CASE WHEN dashboard_users.status='disabled' THEN dashboard_users.status ELSE dashboard_users.status END,
                              invited_at=COALESCE(dashboard_users.invited_at, now()),
                              updated_at=now()
                RETURNING *
                """,
                (company, email, str(request.name or "").strip(), digits(request.phone) or None, role, context.get("actor_user_id")),
            )
            user = dict(cur.fetchone() or {})
            cur.execute(
                "UPDATE dashboard_user_invites SET status='superseded' WHERE company_code=%s AND email=%s AND status='pending'",
                (company, email),
            )
            cur.execute(
                """
                INSERT INTO dashboard_user_invites (company_code, email, role, token_hash, invited_by_user_id, expires_at, metadata)
                VALUES (%s,%s,%s,%s,%s,%s,%s)
                RETURNING invite_id, company_code, email, role, status, expires_at, created_at
                """,
                (
                    company,
                    email,
                    role,
                    dashboard_token_hash(invite_token),
                    context.get("actor_user_id"),
                    expires_at,
                    Json({}),
                ),
            )
            invite = dict(cur.fetchone() or {})
            if dashboard_role_key(role) == "owner":
                import setup_owner_bootstrap as _owner_boot

                bootstrap = _owner_boot.apply_owner_bootstrap_grants(
                    cur,
                    company_code=company,
                    user_id=str(user.get("user_id") or ""),
                    granted_by_user_id=str(context.get("actor_user_id") or user.get("user_id") or ""),
                )
                write_admin_audit(
                    cur,
                    context,
                    "setup_owner_bootstrap_grants",
                    summary=f"Applied {_owner_boot.BUNDLE_VERSION} grants for invited owner {email}.",
                    target_type="team_member",
                    target=email,
                    details={
                        "company_code": company,
                        "email": email,
                        "user_id": str(user.get("user_id") or ""),
                        "bundle_version": _owner_boot.BUNDLE_VERSION,
                        "granted": bootstrap.get("granted"),
                        "already_present": bootstrap.get("already_present"),
                        "source": "team_invite",
                    },
                )
        conn.commit()
    record_admin_audit(
        context,
        "team_member_invited",
        summary=f"Invited {email} as {role}.",
        target_type="team_member",
        target=email,
        details={"email": email, "role": role, "phase": "setup_console_phase4"},
    )
    return {"ok": True, "user": dashboard_user_public(user), "invite": json_safe(invite), "invite_token": invite_token}


@app.patch("/dashboard/team/users/{user_id}")
def dashboard_team_update_user(user_id: str, request: DashboardTeamUserUpdateRequest, context: dict[str, Any] = Depends(workspace_dashboard_context)):
    require_workspace_permission(context, "users.manage")
    company = context["company_code"]
    updates: list[str] = []
    params: list[Any] = []
    import setup_console_admin_phase4 as _p4

    if request.role is not None:
        if not dashboard_role_allowed(request.role):
            raise HTTPException(status_code=422, detail={"error": "invalid_role", "message": "You do not have permission to do this action."})
        actor_perms = context_permissions(context)
        allowed, deny_reason = _p4.role_grant_allowed(actor_permissions=actor_perms, target_role=request.role, legacy=sys.modules[__name__])
        if not allowed:
            raise HTTPException(
                status_code=403,
                detail={
                    "error": deny_reason or "privilege_escalation_denied",
                    "message": "You can only assign roles within your own access level.",
                    "message_ar": "يمكنك تعيين الأدوار ضمن مستوى وصولك فقط.",
                },
            )
        updates.append("role=%s")
        params.append(dashboard_role_key(request.role))
    if request.status is not None:
        status = normalize_dashboard_user_status(request.status, default="")
        if status not in {"active", "invited", "disabled"}:
            raise HTTPException(status_code=422, detail={"error": "invalid_status", "message": "You do not have permission to do this action."})
        updates.append("status=%s")
        params.append(status)
        if status == "disabled":
            updates.append("disabled_at=now()")
    if request.name is not None:
        updates.append("name=%s")
        params.append(str(request.name or "").strip())
    if request.phone is not None:
        updates.append("phone=%s")
        params.append(digits(request.phone) or None)
    if not updates:
        raise HTTPException(status_code=422, detail={"error": "no_update", "message": "No team member update was provided."})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM dashboard_users WHERE user_id=%s AND company_code=%s FOR UPDATE",
                (user_id, company),
            )
            existing = cur.fetchone()
            if not existing:
                raise HTTPException(status_code=404, detail={"error": "user_not_found", "message": "Team member was not found."})
            existing_user = dict(existing)
            orphan = _p4.assert_last_owner_safe(
                cur,
                company_code=company,
                target_user=existing_user,
                new_role=request.role,
                new_status=request.status,
                legacy=sys.modules[__name__],
            )
            if orphan:
                raise HTTPException(status_code=409, detail=orphan)
            removes_recruiting_eligibility = (
                normalize_dashboard_user_status(request.status, default="") == "disabled"
                if request.status is not None
                else False
            ) or (
                request.role is not None
                and dashboard_role_key(request.role) not in {"owner", "hr_manager", "recruiter", "hiring_manager"}
            )
            if removes_recruiting_eligibility:
                cur.execute(
                    """
                    SELECT count(*) AS count
                    FROM applications
                    WHERE company_code=%s AND owner_user_id=%s
                      AND lower(COALESCE(status,'')) NOT IN ('hired','rejected','withdrawn')
                    """,
                    (company, user_id),
                )
                owned_active = int((cur.fetchone() or {}).get("count") or 0)
                if owned_active:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "error": "candidate_owner_reassignment_required",
                            "message": "Reassign or explicitly unassign this recruiter's active applications first.",
                            "owned_active_applications": owned_active,
                        },
                    )
            cur.execute(
                f"""
                UPDATE dashboard_users
                SET {', '.join(updates)}, updated_at=now()
                WHERE user_id=%s AND company_code=%s
                RETURNING *
                """,
                (*params, user_id, company),
            )
            user = cur.fetchone()
            if not user:
                raise HTTPException(status_code=404, detail={"error": "user_not_found", "message": "Team member was not found."})
            if request.status == "disabled":
                cur.execute("UPDATE dashboard_user_sessions SET status='revoked' WHERE user_id=%s", (user_id,))
                cur.execute("UPDATE dashboard_whatsapp_identities SET status='disabled', updated_at=now() WHERE user_id=%s", (user_id,))
                _operator_mobile.revoke_user_operator_mobile_sessions(cur, user_id, reason="operator_disabled")
        conn.commit()
    member = dict(user)
    new_role = dashboard_role_key(request.role) if request.role is not None else None
    new_status = normalize_dashboard_user_status(request.status, default="") if request.status is not None else None
    changes: list[str] = []
    if new_role is not None:
        changes.append(f"role → {new_role}")
    if new_status is not None:
        changes.append(f"status → {new_status}")
    if request.name is not None:
        changes.append("name")
    if request.phone is not None:
        changes.append("phone")
    audit_action = (
        "team_member_deactivated" if new_status == "disabled"
        else "team_member_reactivated" if new_status == "active"
        else "team_member_role_changed" if new_role is not None
        else "team_member_updated"
    )
    target_label = str(member.get("email") or user_id)
    record_admin_audit(
        context,
        audit_action,
        summary=f"Updated {target_label}: {', '.join(changes) or 'no changes'}.",
        target_type="team_member",
        target=target_label,
        details={"user_id": user_id, "role": new_role, "status": new_status, "changes": changes, "phase": "setup_console_phase4"},
    )
    return {"ok": True, "user": dashboard_user_public(member)}


@app.post("/dashboard/team/whatsapp-link")
def dashboard_team_link_whatsapp(request: DashboardWhatsAppLinkRequest, context: dict[str, Any] = Depends(workspace_dashboard_context)):
    phone = digits(request.phone)
    if not phone:
        raise HTTPException(status_code=422, detail={"error": "phone_required", "message": "Enter a valid WhatsApp phone."})
    company = context["company_code"]
    user_id = context.get("actor_user_id")
    with db_connect() as conn:
        with conn.cursor() as cur:
            # Anti-hijack: a WhatsApp identity may only be (re)linked by the account
            # that already owns it. Without this, any authenticated user could
            # reassign a phone that is actively linked to a different colleague to
            # themselves and steal attribution for WhatsApp-driven HR actions.
            cur.execute(
                "SELECT user_id FROM dashboard_whatsapp_identities WHERE company_code=%s AND phone=%s AND status='active'",
                (company, phone),
            )
            existing = cur.fetchone()
            if existing and existing.get("user_id") and existing.get("user_id") != user_id:
                raise HTTPException(
                    status_code=409,
                    detail={"error": "whatsapp_already_linked", "message": "That WhatsApp number is already linked to another account in this company."},
                )
            cur.execute(
                """
                INSERT INTO dashboard_whatsapp_identities (company_code, user_id, phone, status, updated_at)
                VALUES (%s,%s,%s,'active',now())
                ON CONFLICT (company_code, phone)
                DO UPDATE SET user_id=EXCLUDED.user_id, status='active', updated_at=now()
                """,
                (company, user_id, phone),
            )
            cur.execute("UPDATE dashboard_users SET phone=%s, updated_at=now() WHERE user_id=%s AND company_code=%s", (phone, user_id, company))
        conn.commit()
    record_admin_audit(
        context,
        "team_whatsapp_linked",
        summary=f"Linked WhatsApp {phone} to this account.",
        target_type="whatsapp_identity",
        target=phone,
        details={"phone": phone, "user_id": user_id},
    )
    return {"ok": True, "phone": phone}


# ---------------------------------------------------------------------------
# Org & Managers (V1a) — client-facing org structure + manager scopes.
#
# Behind WATHEFNI_ORG_HIERARCHY. Owner/Admin only (users.manage). Writes the
# same tables the scope engine already reads, so a manager defined here is
# immediately enforced by every manager_scope_allows_employee gate. With the
# flag off (or no org rows), the whole company behaves exactly as today.
# ---------------------------------------------------------------------------


def _org_admin_context(context: dict[str, Any]) -> str:
    if not org_hierarchy_enabled():
        raise HTTPException(status_code=404, detail={"error": "not_found", "message": "Not found"})
    require_workspace_permission(context, "users.manage")
    return context["company_code"]


def _org_error_http(result: dict[str, Any]) -> None:
    if not result.get("ok"):
        raise HTTPException(status_code=422, detail={"error": result.get("error") or "org_update_failed", "message": "Could not save this org change.", **{k: v for k, v in result.items() if k == "missing"}})


@app.get("/dashboard/org")
def dashboard_org_overview(context: dict[str, Any] = Depends(workspace_dashboard_context)):
    company = _org_admin_context(context)
    return {"ok": True, **org_overview(company)}


@app.post("/dashboard/org/branches")
def dashboard_org_create_branch(request: OrgBranchRequest, context: dict[str, Any] = Depends(workspace_dashboard_context)):
    company = _org_admin_context(context)
    result = upsert_org_branch(company, name=request.name, branch_key=request.branch_key, is_active=request.is_active)
    _org_error_http(result)
    record_admin_audit(context, "org_branch_saved", summary=f"Saved branch {request.name}.", target_type="org_branch", target=str(result.get("branch", {}).get("branch_key") or request.name), details={"name": request.name})
    return result


