    return {
        "ok": True,
        "phase": "setup_console_operator_auth",
        "phone": superadmin.get("actor_phone"),
        "email": superadmin.get("actor_email") or "",
        "auth_source": superadmin.get("auth_source"),
        "is_platform_admin": True,
    }


