@app.get("/dashboard/superadmin/whatsapp-suppressions")
def setup_console_list_whatsapp_suppressions(superadmin: dict[str, Any] = Depends(superadmin_context)):
    """Operator view of active WhatsApp opt-outs (global by phone). Platform-admin
    only — suppression is global, so it is never exposed to a single company's HR."""
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT phone, scope, source, reason, context_company_code, created_by, created_at, updated_at
                FROM whatsapp_suppressions
                WHERE active IS TRUE
                ORDER BY updated_at DESC
                LIMIT 500
                """
            )
            rows = [dict(r) for r in cur.fetchall()]
    return json_safe({"ok": True, "count": len(rows), "suppressions": rows})


@app.post("/dashboard/superadmin/whatsapp-suppressions")
def setup_console_suppress_whatsapp(request: WhatsAppSuppressionRequest, superadmin: dict[str, Any] = Depends(superadmin_context)):
    """Manual operator suppression (e.g. an employee asked HR to stop). Audited via
    the row's source='operator' + created_by."""
    result = suppress_whatsapp(
        request.phone,
        scope=("all" if str(request.scope or "").strip().lower() == "all" else "whatsapp"),
        reason=(str(request.reason or "").strip() or "operator_suppress"),
        source="operator",
        created_by=str(superadmin.get("actor_phone") or "operator"),
    )
    if not result.get("ok"):
        raise HTTPException(status_code=422, detail={"error": "missing_phone", "message": "Provide a valid phone number."})
    return {"ok": True, "phone": result.get("phone"), "scope": result.get("scope")}


@app.post("/dashboard/superadmin/whatsapp-suppressions/unsuppress")
def setup_console_unsuppress_whatsapp(request: WhatsAppSuppressionRequest, superadmin: dict[str, Any] = Depends(superadmin_context)):
    """Operator unsuppress (re-enable proactive WhatsApp for a phone). Audited: the
    row is kept (active=false) and stamped with the operator who re-enabled it."""
    result = unsuppress_whatsapp(request.phone, by=str(superadmin.get("actor_phone") or "operator"))
    if not result.get("ok"):
        raise HTTPException(status_code=404, detail={"error": "not_suppressed", "message": "No active suppression for that phone."})
    return {"ok": True, "phone": result.get("phone")}


@app.get("/dashboard/superadmin/setup/companies")
def setup_console_list_companies(
    q: str | None = Query(default=None),
    limit: int = Query(default=50, ge=1, le=100),
    offset: int = Query(default=0, ge=0),
    include_inactive: bool = Query(default=False),
    superadmin: dict[str, Any] = Depends(superadmin_context),
):
    term = str(q or "").strip()
    pattern = f"%{term}%"
    include_inactive = include_inactive if isinstance(include_inactive, bool) else False
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT count(*) AS n
                FROM companies
                WHERE (%s OR COALESCE(status,'active')='active')
                  AND (%s='' OR company_code ILIKE %s OR name ILIKE %s)
                """,
                (include_inactive, term, pattern, pattern),
            )
            total_count = int((cur.fetchone() or {}).get("n") or 0)
            cur.execute(
                """
                SELECT company_code
                FROM companies
                WHERE (%s OR COALESCE(status,'active')='active')
                  AND (%s='' OR company_code ILIKE %s OR name ILIKE %s)
                ORDER BY lower(name), company_code
                LIMIT %s OFFSET %s
                """,
                (include_inactive, term, pattern, pattern, limit, offset),
            )
            codes = [str(r["company_code"]) for r in cur.fetchall()]
    return {
        "companies": [setup_console_company_readiness(code) for code in codes],
        "total_count": total_count,
        "limit": limit,
        "offset": offset,
        "include_inactive": include_inactive,
        "has_more": offset + len(codes) < total_count,
    }


@app.get("/dashboard/superadmin/setup/companies/{company_code}")
def setup_console_company_detail(company_code: str, superadmin: dict[str, Any] = Depends(superadmin_context)):
    company = _setup_normalize_company_code(company_code)
    if not _setup_company_exists(company):
        raise HTTPException(status_code=404, detail={"error": "company_not_found", "message": "That company does not exist yet."})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT user_id, company_code, email, name, phone, role, status, last_active_at, invited_at, accepted_at, created_at, metadata
                FROM dashboard_users WHERE company_code=%s
                ORDER BY CASE status WHEN 'active' THEN 0 WHEN 'invited' THEN 1 ELSE 2 END, lower(name), email
                LIMIT 500
                """,
                (company,),
            )
            users = [dashboard_user_public(dict(row)) for row in cur.fetchall()]
    import setup_console_effective_state as _eff

    raw_modules = dashboard_module_catalog_payload(company)
    http_registered_by_key = {
        str(item.get("key") or ""): setup_module_http_registered(str(item.get("key") or ""))
        for item in raw_modules
    }
    principal_permitted_by_key = {
        str(item.get("key") or ""): setup_company_principal_permits_module(company, str(item.get("key") or ""), users)
        for item in raw_modules
    }
    available_modules = _eff.annotate_setup_catalog(
        company,
        raw_modules,
        principal_permitted_by_key=principal_permitted_by_key,
        http_registered_by_key=http_registered_by_key,
    )
    configured = [item["key"] for item in available_modules if item.get("configured")]
    return {
        "readiness": setup_console_company_readiness(company),
        "available_modules": available_modules,
        "module_bundles": module_bundles_payload(),
        "module_guidance": setup_console_module_guidance(company, configured),
        "users": users,
        "channel_policy": setup_console_channel_policy(company),
        "channel_account": setup_console_channel_account(company),
        "email_admin": _setup_email_admin_snapshot(company),
        "effective_state_honesty": _eff.honesty_payload(),
        "last_module_change": setup_console_last_module_change(company),
    }


def setup_console_last_module_change(company_code: str) -> dict[str, Any] | None:
    """Latest setup_modules_updated row from the existing action_results audit sink."""
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT created_at, actor_email, actor_phone, actor_role, final_reply, result
                    FROM action_results
                    WHERE company_code=%s AND action_type=%s
                    ORDER BY created_at DESC
                    LIMIT 1
                    """,
                    (company_code, "setup_modules_updated"),
                )
                row = cur.fetchone()
    except Exception:
        logger.warning("setup console last module change lookup failed", exc_info=True)
        return None
    if not row:
        return None
    body = dict(row)
    result = body.get("result") if isinstance(body.get("result"), dict) else {}
    details = result.get("details") if isinstance(result.get("details"), dict) else {}
    created = body.get("created_at")
    return json_safe(
        {
            "at": created.isoformat() if hasattr(created, "isoformat") else created,
            "actor_email": body.get("actor_email"),
            "actor_phone": body.get("actor_phone"),
            "actor_role": body.get("actor_role"),
            "summary": body.get("final_reply"),
            "modules": details.get("modules"),
        }
    )


