@app.patch("/dashboard/superadmin/setup/companies/{company_code}/lifecycle")
def setup_console_set_company_lifecycle(
    company_code: str,
    request: SetupCompanyLifecycleRequest,
    superadmin: dict[str, Any] = Depends(superadmin_context),
):
    company = _setup_normalize_company_code(company_code)
    desired = str(request.status or "").strip().lower()
    reason = str(request.reason or "").strip()
    if desired not in COMPANY_LIFECYCLE_STATES:
        raise HTTPException(
            status_code=422,
            detail={"error": "company_status_invalid", "message": "Choose active, disabled, or archived."},
        )
    if not reason:
        raise HTTPException(
            status_code=422,
            detail={"error": "lifecycle_reason_required", "message": "Enter a reason for this lifecycle change."},
        )
    if company == "WATHEFNI" and desired != "active":
        raise HTTPException(
            status_code=409,
            detail={
                "error": "protected_company",
                "message": "WATHEFNI cannot be disabled or archived through this control.",
            },
        )

    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT status FROM companies WHERE company_code=%s FOR UPDATE",
                (company,),
            )
            row = cur.fetchone()
            if not row:
                raise HTTPException(
                    status_code=404,
                    detail={"error": "company_not_found", "message": "That company does not exist yet."},
                )
            previous = str(row.get("status") or "active").strip().lower()
            if previous not in COMPANY_LIFECYCLE_STATES:
                previous = "active"
            if previous == desired:
                raise HTTPException(
                    status_code=409,
                    detail={
                        "error": "company_status_unchanged",
                        "message": f"{company} is already {desired}.",
                    },
                )

            cur.execute(
                """
                UPDATE companies
                SET status=%s,
                    lifecycle_reason=%s,
                    disabled_at=CASE
                      WHEN %s='disabled' THEN now()
                      WHEN %s='archived' THEN COALESCE(disabled_at, now())
                      ELSE NULL
                    END,
                    archived_at=CASE WHEN %s='archived' THEN now() ELSE NULL END,
                    updated_at=now()
                WHERE company_code=%s
                """,
                (desired, reason, desired, desired, desired, company),
            )

            revoked_sessions = 0
            superseded_invites = 0
            employee_app_invalidated = {
                "revoked_employee_app_sessions": 0,
                "superseded_employee_app_invites": 0,
            }
            if desired in {"disabled", "archived"}:
                cur.execute(
                    "UPDATE dashboard_user_sessions SET status='revoked' "
                    "WHERE company_code=%s AND status='active'",
                    (company,),
                )
                revoked_sessions = cur.rowcount
                revoked_sessions += _operator_mobile.revoke_company_operator_mobile_sessions(
                    cur,
                    company,
                    reason=f"company_{desired}",
                )
                cur.execute(
                    "UPDATE dashboard_user_invites SET status='superseded' "
                    "WHERE company_code=%s AND status='pending'",
                    (company,),
                )
                superseded_invites = cur.rowcount
                employee_app_invalidated = invalidate_company_employee_app_credentials(
                    cur,
                    company,
                    reason=f"company_{desired}",
                )

            action_type = {
                "active": "setup_company_reactivated",
                "disabled": "setup_company_disabled",
                "archived": "setup_company_archived",
            }[desired]
            write_admin_audit(
                cur,
                _setup_audit_context(superadmin, company),
                action_type,
                summary=f"Changed {company} lifecycle from {previous} to {desired}.",
                target_type="company",
                target=company,
                details={
                    "company_code": company,
                    "previous_status": previous,
                    "new_status": desired,
                    "reason": reason,
                    "revoked_sessions": revoked_sessions,
                    "superseded_invites": superseded_invites,
                    **employee_app_invalidated,
                },
            )
        conn.commit()

    return {
        "ok": True,
        "company_code": company,
        "previous_status": previous,
        "status": desired,
        "revoked_sessions": revoked_sessions,
        "superseded_invites": superseded_invites,
        **employee_app_invalidated,
        "readiness": setup_console_company_readiness(company),
    }


@app.post("/dashboard/superadmin/setup/companies")
def setup_console_create_company(request: SetupCompanyCreateRequest, superadmin: dict[str, Any] = Depends(superadmin_context)):
    company = _setup_normalize_company_code(request.company_code)
    provided_name = str(request.name or "").strip()
    insert_name = provided_name or company.title()
    try:
        country = _company_setup.normalize_country(request.country, default=_company_setup.DEFAULT_COUNTRY)
        if country not in _company_setup.GCC_PROFILE_DEFAULTS and (not request.timezone or not request.currency):
            raise ValueError("non_gcc_profile_requires_timezone_currency")
        timezone_value = _company_setup.normalize_timezone(request.timezone, country=country)
        currency = _company_setup.normalize_currency(request.currency, country=country)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail={"error": str(exc), "message": "Check the company country, timezone, and ISO currency."}) from None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO companies (company_code, name, country, metadata, raw_json, created_at, updated_at)
                VALUES (%s,%s,%s,%s,%s,now(),now())
                ON CONFLICT (company_code)
                DO UPDATE SET name = COALESCE(NULLIF(%s,''), companies.name), updated_at = now()
                RETURNING (xmax = 0) AS created
                """,
                (company, insert_name, country, Json({}), Json({}), provided_name),
            )
            created = bool((cur.fetchone() or {}).get("created"))
            if created:
                cur.execute(
                    """
                    INSERT INTO company_settings (company_code, settings)
                    VALUES (%s,%s)
                    ON CONFLICT (company_code) DO NOTHING
                    """,
                    (company, Json({"timezone": timezone_value, "currency": currency})),
                )
        conn.commit()
    record_admin_audit(
        _setup_audit_context(superadmin, company),
        "setup_company_created" if created else "setup_company_selected",
        summary=(f"Created company {company}." if created else f"Selected existing company {company}.") + (f" Name: {provided_name}." if provided_name else ""),
        target_type="company",
        target=company,
        details={"company_code": company, "name": provided_name or insert_name, "country": country, "timezone": timezone_value, "currency": currency, "created": created},
    )
    return {"ok": True, "created": created, "readiness": setup_console_company_readiness(company)}


@app.patch("/dashboard/superadmin/setup/companies/{company_code}/profile")
def setup_console_set_profile(
    company_code: str,
    request: SetupCompanyProfileRequest,
    superadmin: dict[str, Any] = Depends(superadmin_context),
):
    company = _setup_normalize_company_code(company_code)
    if not _setup_company_exists(company):
        raise HTTPException(status_code=404, detail={"error": "company_not_found", "message": "That company does not exist yet."})
    current = company_profile_payload(company)
    try:
        country = _company_setup.normalize_country(request.country, default=str(current.get("country") or _company_setup.DEFAULT_COUNTRY))
        if country not in _company_setup.GCC_PROFILE_DEFAULTS and not (
            request.timezone or current.get("timezone")
        ):
            raise ValueError("non_gcc_profile_requires_timezone")
        if country not in _company_setup.GCC_PROFILE_DEFAULTS and not (
            request.currency or current.get("currency")
        ):
            raise ValueError("non_gcc_profile_requires_currency")
        timezone_value = _company_setup.normalize_timezone(request.timezone or current.get("timezone"), country=country)
        currency = _company_setup.normalize_currency(request.currency or current.get("currency"), country=country)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail={"error": str(exc), "message": "Check the company country, timezone, and ISO currency."}) from None
    name = str(request.name if request.name is not None else current.get("name") or "").strip()
    if not name:
        raise HTTPException(status_code=422, detail={"error": "name_required", "message": "Enter the client-facing company name."})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE companies SET name=%s, country=%s, updated_at=now() WHERE company_code=%s",
                (name, country, company),
            )
            cur.execute(
                """
                INSERT INTO company_settings (company_code, settings)
                VALUES (%s,%s)
                ON CONFLICT (company_code) DO UPDATE
                  SET settings=company_settings.settings || EXCLUDED.settings,
                      updated_at=now()
                """,
                (company, Json({"timezone": timezone_value, "currency": currency})),
            )
            write_admin_audit(
                cur,
                _setup_audit_context(superadmin, company),
                "setup_company_profile_updated",
                summary=f"Updated the company profile for {company}.",
                target_type="company",
                target=company,
                details={"company_code": company, "name": name, "country": country, "timezone": timezone_value, "currency": currency},
            )
        conn.commit()
    return {"ok": True, "profile": company_profile_payload(company), "readiness": setup_console_company_readiness(company)}


@app.patch("/dashboard/superadmin/setup/companies/{company_code}/modules")
def setup_console_set_modules(company_code: str, request: SetupModulesRequest, superadmin: dict[str, Any] = Depends(superadmin_context)):
    company = _setup_normalize_company_code(company_code)
    if not _setup_company_exists(company):
        raise HTTPException(status_code=404, detail={"error": "company_not_found", "message": "That company does not exist yet."})
    requested: list[str] = []
    invalid: list[str] = []
    import capability_readiness as _cap_ready

    for module in request.modules or []:
        key = normalize_module_key(module)
        blocked = _cap_ready.unreleased_catalog_enable_block(key) or _cap_ready.unreleased_catalog_enable_block(str(module))
        if blocked:
            raise HTTPException(status_code=409, detail=blocked)
        if key in SETUP_CONSOLE_MODULES:
            requested.append(key)
        else:
            invalid.append(str(module))
    if invalid:
        raise HTTPException(status_code=422, detail={"error": "unknown_module", "message": f"Unknown module(s): {', '.join(invalid)}."})
    requested = sorted(set(requested))
    currently_enabled = sorted(configured_company_modules(company))
    # Priority 0: never let Setup Console bulk-save strip protected live interviews.
    requested = protect_setup_module_selection(requested, currently_enabled)
    dual_write_validation = _tenant_control.validate_module_publish(
        requested,
        currently_enabled=currently_enabled,
    )
    if dual_write_validation.get("blocks_publish"):
        raise HTTPException(
            status_code=422,
            detail={
                "error": "commercial_dependency_blocks_publish",
                "message": " ".join(
                    item.get("message") or ""
                    for item in (dual_write_validation.get("commercial_gaps") or [])
                ) or "Commercial dependency missing.",
                "commercial_gaps": dual_write_validation.get("commercial_gaps") or [],
                "module_gaps": dual_write_validation.get("module_gaps") or [],
                "suggested_modules": expand_module_dependencies(requested),
            },
        )
    dependency_gaps = missing_module_dependencies(requested)
    if dependency_gaps:
        raise HTTPException(
            status_code=422,
            detail={
                "error": "missing_module_dependency",
                "message": " ".join(item["message"] for item in dependency_gaps),
                "missing_dependencies": dependency_gaps,
                "suggested_modules": expand_module_dependencies(requested),
            },
        )
    profile = company_profile_payload(company)
    if "payroll" in requested and not profile.get("currency"):
        raise HTTPException(status_code=422, detail={"error": "company_currency_required", "message": "Complete the company currency before enabling Payroll."})
    import setup_console_effective_state as _eff_modules

    unusable_enables: list[dict[str, Any]] = []
    for key in requested:
        if key in currently_enabled:
            continue
        annotated = _eff_modules.annotate_catalog_module(
            key,
            {
                "key": key,
                "configured": False,
                "platform_available": module_platform_available(key),
            },
            company_code=company,
            http_registered=setup_module_http_registered(key),
        )
        if key != "employee_app" and not annotated.get("can_enable"):
            unusable_enables.append(
                {
                    "module": key,
                    "effective_state": (annotated.get("effective_state") or {}).get("effective_state"),
                    "blockers": (annotated.get("effective_state") or {}).get("blockers") or annotated.get("blockers") or [],
                }
            )
    if unusable_enables:
        raise HTTPException(
            status_code=409,
            detail={
                "error": "cannot_enable_unusable",
                "message": "A selected module cannot become usable in this deployment, so it was not enabled.",
                "modules": unusable_enables,
            },
        )
    existing_tz = profile.get("timezone") or _company_setup.DEFAULT_TIMEZONE
    payroll_defaults = default_payroll_policy(company) if "payroll" in requested else None
    employee_app_invalidated = {
        "revoked_employee_app_sessions": 0,
        "superseded_employee_app_invites": 0,
    }
    dual_write_result: dict[str, Any] = {"ok": True, "skipped": True}
    with db_connect() as conn:
        with conn.cursor() as cur:
            # Serialize module changes with activation/refresh, which take a shared
            # lock on this company row before issuing or rotating credentials.
            cur.execute(
                "SELECT status FROM companies WHERE company_code=%s FOR UPDATE",
                (company,),
            )
            if not cur.fetchone():
                raise HTTPException(status_code=404, detail={"error": "company_not_found", "message": "That company does not exist yet."})
            cur.execute(
                "SELECT enabled FROM company_modules WHERE company_code=%s AND module_key='employee_app' LIMIT 1",
                (company,),
            )
            employee_app_row = cur.fetchone()
            employee_app_was_enabled = bool(employee_app_row and employee_app_row.get("enabled"))
            for key in requested:
                settings = {"timezone": existing_tz, "reminder_hours_before": 2} if key == "shifts" else {}
                cur.execute(
                    """
                    INSERT INTO company_modules (company_code, module_key, enabled, source, settings, updated_at)
                    VALUES (%s,%s,true,'setup_console',%s,now())
                    ON CONFLICT (company_code, module_key)
                    DO UPDATE SET enabled=true, source='setup_console', updated_at=now()
                    """,
                    (company, key, Json(settings)),
                )
            cur.execute(
                "UPDATE company_modules SET enabled=false, source='setup_console', updated_at=now() "
                "WHERE company_code=%s AND enabled IS TRUE AND module_key <> ALL(%s)",
                (company, requested),
            )
            if employee_app_was_enabled and "employee_app" not in requested:
                employee_app_invalidated = invalidate_company_employee_app_credentials(
                    cur,
                    company,
                    reason="employee_app_module_removed",
                )
            if ("performance" in requested) != ("performance" in currently_enabled):
                import performance_surfaces as _perf_surfaces

                _perf_surfaces.sync_catalog_entitlement(
                    cur,
                    company_code=company,
                    actor_phone=str((superadmin or {}).get("phone") or "setup"),
                    enabled="performance" in requested,
                    reason="setup catalog performance entitlement",
                )
            if ("talent" in requested) != ("talent" in currently_enabled):
                import talent_surfaces as _talent_surfaces

                _talent_surfaces.sync_catalog_entitlement(
                    cur,
                    company_code=company,
                    actor_phone=str((superadmin or {}).get("phone") or "setup"),
                    enabled="talent" in requested,
                    reason="setup catalog talent entitlement",
                )
            if ("learning" in requested) != ("learning" in currently_enabled):
                import learning_surfaces as _learning_surfaces

                _learning_surfaces.sync_catalog_entitlement(
                    cur,
                    company_code=company,
                    actor_phone=str((superadmin or {}).get("phone") or "setup"),
                    enabled="learning" in requested,
                    reason="setup catalog learning entitlement",
                )
            if ("benefits" in requested) != ("benefits" in currently_enabled):
                import benefits_surfaces as _benefits_surfaces

                _benefits_surfaces.sync_catalog_entitlement(
                    cur,
                    company_code=company,
                    actor_phone=str((superadmin or {}).get("phone") or "setup"),
                    enabled="benefits" in requested,
                    reason="setup catalog benefits entitlement",
                )
            if ("employee_relations" in requested) != ("employee_relations" in currently_enabled):
                import employee_relations_surfaces as _er_surfaces

                _er_surfaces.sync_catalog_entitlement(
                    cur,
                    company_code=company,
                    actor_phone=str((superadmin or {}).get("phone") or "setup"),
                    enabled="employee_relations" in requested,
                    reason="setup catalog employee relations entitlement",
                )
            if ("engagement" in requested) != ("engagement" in currently_enabled):
                import engagement_surfaces as _eg_surfaces

                _eg_surfaces.sync_catalog_entitlement(
                    cur,
                    company_code=company,
                    actor_phone=str((superadmin or {}).get("phone") or "setup"),
                    enabled="engagement" in requested,
                    reason="setup catalog engagement entitlement",
                )
            if ("comp_planning" in requested) != ("comp_planning" in currently_enabled):
                import compensation_surfaces as _cp_surfaces

                _cp_surfaces.sync_catalog_entitlement(
                    cur,
                    company_code=company,
                    actor_phone=str((superadmin or {}).get("phone") or "setup"),
                    enabled="comp_planning" in requested,
                    reason="setup catalog compensation planning entitlement",
                )
            if ("workforce_planning" in requested) != ("workforce_planning" in currently_enabled):
                import workforce_planning_surfaces as _wfp_surfaces

                _wfp_surfaces.sync_catalog_entitlement(
                    cur,
                    company_code=company,
                    actor_phone=str((superadmin or {}).get("phone") or "setup"),
                    enabled="workforce_planning" in requested,
                    reason="setup catalog workforce planning entitlement",
                )
            if payroll_defaults is not None:
                cur.execute(
                    """
                    INSERT INTO payroll_policies (company_code, settings, updated_at)
                    VALUES (%s,%s,now())
                    ON CONFLICT (company_code) DO NOTHING
                    """,
                    (company, Json(payroll_defaults)),
                )
            # Additive dual-write into tenant control-plane (shadow; non-authoritative).
            try:
                dual_write_result = _tenant_control.dual_write_module_save(
                    cur,
                    company_code=company,
                    requested_modules=requested,
                    currently_enabled=currently_enabled,
                    actor=str((superadmin or {}).get("email") or (superadmin or {}).get("user_id") or "setup_console"),
                )
                if not dual_write_result.get("ok") and not dual_write_result.get("skipped"):
                    raise HTTPException(
                        status_code=422,
                        detail={
                            "error": dual_write_result.get("error") or "dual_write_failed",
                            "validation": dual_write_result.get("validation") or {},
                        },
                    )
            except HTTPException:
                raise
            except Exception as exc:
                # Dual-write must not silently succeed while control-plane write fails;
                # fail the mutation so operators retry with a consistent state.
                raise HTTPException(
                    status_code=500,
                    detail={
                        "error": "tenant_control_dual_write_failed",
                        "message": "Module save could not persist control-plane audit state.",
                        "detail": str(exc)[:300],
                    },
                ) from exc
        conn.commit()
    record_admin_audit(
        _setup_audit_context(superadmin, company),
        "setup_modules_updated",
        summary=f"Enabled modules for {company}: {', '.join(requested) or 'none'}.",
        target_type="company",
        target=company,
        details={
            "company_code": company,
            "modules": requested,
            "protected_retained": dual_write_result.get("protected_retained") or dual_write_validation.get("protected_retained") or [],
            "control_plane_version": dual_write_result.get("version_number"),
            **employee_app_invalidated,
        },
    )
    return {
        "ok": True,
        "modules": requested,
        "protected_retained": dual_write_result.get("protected_retained") or dual_write_validation.get("protected_retained") or [],
        "control_plane": {
            "dual_write": (not dual_write_result.get("skipped")),
            "version_number": dual_write_result.get("version_number"),
            "rollback_target": dual_write_result.get("rollback_target"),
        },
        **employee_app_invalidated,
        "readiness": setup_console_company_readiness(company),
    }


