@app.patch("/dashboard/superadmin/setup/companies/{company_code}/employee-app-access")
def setup_console_employee_app_access_patch(
    company_code: str,
    body: SetupEmployeeAppAccessPolicyPatch,
    superadmin: dict[str, Any] = Depends(superadmin_context),
):
    """Company-level who-can-use policy. Module on/off remains PATCH .../modules."""
    company = _setup_normalize_company_code(company_code)
    if not _setup_company_exists(company):
        raise HTTPException(status_code=404, detail={"error": "company_not_found", "message": "That company does not exist yet."})
    import employee_app_access as _access

    context = {
        "company_code": company,
        "actor_user_id": f"setup:{superadmin.get('phone') or 'operator'}",
        "user_id": f"setup:{superadmin.get('phone') or 'operator'}",
        "hr_phone": superadmin.get("phone"),
    }
    if body.apply_reconcile:
        if not body.ux_mode:
            raise HTTPException(status_code=422, detail={"error": "ux_mode_required", "message": "Choose who should have access."})
        try:
            return json_safe(
                _access.apply_access_policy(
                    sys.modules[__name__],
                    context,
                    ux_mode=body.ux_mode,
                    selected_departments=body.selected_departments,
                    selected_department_org_unit_ids=body.selected_department_org_unit_ids,
                    selected_employee_keys=body.selected_employee_keys,
                    confirm_large_impact=bool(body.confirm_large_impact),
                    reason=str(body.reason or "Setup Console access policy apply").strip(),
                )
            )
        except HTTPException:
            raise
        except Exception as exc:
            # apply raises HTTPException via legacy; rewrap if needed
            if hasattr(exc, "status_code"):
                raise
            raise HTTPException(status_code=400, detail={"error": "apply_failed", "message": str(exc)[:300]}) from exc

    return json_safe(
        _access.set_company_app_access_policy(
            sys.modules[__name__],
            context,
            module_enabled=None,
            access_mode=body.access_mode,
            selected_departments=body.selected_departments,
            selected_department_org_unit_ids=body.selected_department_org_unit_ids,
            selected_employee_keys=body.selected_employee_keys,
            selection_scope=body.selection_scope,
            ux_mode=body.ux_mode,
            sync_invites=bool(body.sync_invites),
            source="setup_console",
            allow_module_toggle=False,
        )
    )


