def bounded_limit(value: int, *, default: int = 50, maximum: int = 200) -> int:
    try:
        parsed = int(value)
    except Exception:
        parsed = default
    return max(1, min(parsed, maximum))


def dashboard_candidate_name(row: dict[str, Any]) -> str | None:
    name = candidate_name_from_row(row)
    return None if name == "Unknown" else name


def _application_intake_source(row: dict[str, Any], raw_json: dict[str, Any]) -> str:
    intake = raw_json.get("intake") if isinstance(raw_json.get("intake"), dict) else {}
    import_meta = raw_json.get("import") if isinstance(raw_json.get("import"), dict) else {}
    source = str(
        intake.get("source")
        or import_meta.get("source")
        or raw_json.get("intake_source")
        or raw_json.get("source")
        or row.get("data_source")
        or ""
    ).strip().lower()
    if any(token in source for token in ("whatsapp", "apply_code", "qr")):
        return "whatsapp"
    if any(token in source for token in ("bulk", "spreadsheet", "csv", "import")):
        return "bulk_import"
    if any(token in source for token in ("email", "mailbox")):
        return "email"
    if any(token in source for token in ("manual", "dashboard", "operator")):
        return "manual"
    if source in {"", "production", "staging", "test", "legacy", "unknown"}:
        return "unknown"
    return source or "unknown"


def _application_ui_contract(
    row: dict[str, Any],
    *,
    include_assessment: bool,
    permissions: set[str] | list[str] | None,
) -> dict[str, Any]:
    import recruiting_lifecycle as _rl

    raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
    cv = raw_json.get("cv") if isinstance(raw_json.get("cv"), dict) else {}
    cv_processing = cv.get("processing") if isinstance(cv.get("processing"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    communication = row.get("communication_json") if isinstance(row.get("communication_json"), dict) else {}
    review_task = row.get("review_task_json") if isinstance(row.get("review_task_json"), dict) else {}
    lifecycle_event = row.get("lifecycle_event_json") if isinstance(row.get("lifecycle_event_json"), dict) else {}
    raw_status = str(row.get("status") or "")
    canonical_stage = _rl.normalize_stage(raw_status) or raw_status
    communication_status = _rl.normalize_communication_status(
        communication.get("status") or (dashboard_delivery_status(communication) if communication else None)
    )
    cv_received = bool(row.get("cv_received") is True or cv)
    cv_status = str(
        cv_processing.get("status")
        or cv.get("processing_status")
        or ((cv.get("storage") or {}).get("status") if isinstance(cv.get("storage"), dict) else "")
        or ("received" if cv_received else "not_received")
    ).strip().lower()
    screening_status = str(row.get("screening_status") or screening.get("status") or "not_started").strip().lower()

    automatic_activity: list[str] = []
    if cv_received:
        automatic_activity.append("cv_received")
    if canonical_stage not in {"", "awaiting_cv", "cv_processing"}:
        automatic_activity.append("cv_processed")
    if screening_status not in {"", "not_started", "pending"}:
        automatic_activity.append("screening_updated")
    if review_task:
        automatic_activity.append("review_task_created")

    waiting_for_hr: list[str] = []
    if canonical_stage == "ready_for_review":
        waiting_for_hr.append("review_candidate")
    elif canonical_stage == "shortlisted":
        waiting_for_hr.append("schedule_interview")
    elif canonical_stage == "interview":
        interview = row.get("interview_json") if isinstance(row.get("interview_json"), dict) else {}
        if interview.get("status") == "completed" and interview.get("feedback_status") != "feedback_complete":
            waiting_for_hr.append("record_interview_notes")
        elif interview.get("status") == "completed":
            waiting_for_hr.append("decide_after_interview")
    if communication_status == "failed":
        waiting_for_hr.append("resolve_communication")
    elif canonical_stage in {"shortlisted", "interview", "hired", "rejected"} and communication_status != "sent":
        waiting_for_hr.append("inform_candidate")

    held_status = str(raw_status or "").strip().lower() in HELD_IMPORT_STATUSES
    allowed_actions: list[str] = []
    assessment_cohort: str | None = None
    assessment_allowed_actions: list[str] = []
    if permissions is not None:
        perms = {str(value) for value in permissions}
        if held_status:
            # UNIFIED_CANDIDATES_PRODUCTION_DARK_PATCH: held rows never advertise lifecycle/outreach/ranking.
            import unified_candidates as _unified_candidates

            allowed_actions = _unified_candidates.held_allowed_actions(perms, cv_received=cv_received)
            waiting_for_hr = ["review_held_intake"]
            automatic_activity = [item for item in automatic_activity if item in {"cv_received", "cv_processed"}]
            communication_status = "intentionally_skipped"
        else:
            allowed_actions = _rl.allowed_actions_for_stage(canonical_stage, perms)
            if cv_received and "prehire.read" in perms:
                allowed_actions.extend(["preview_cv", "download_cv"])
            if "candidate.manage" in perms:
                allowed_actions.extend(["notify", "generate_evaluation"])
            if include_assessment and cv_received and "assessment.manage" in perms:
                import assessment_cohorts as _assessment_cohorts

                assess_blob = row.get("assessment_json") if isinstance(row.get("assessment_json"), dict) else {}
                if not assess_blob:
                    assess_blob = raw_json.get("assessment") if isinstance(raw_json.get("assessment"), dict) else {}
                assessment_cohort = _assessment_cohorts.classify_attempt_state(
                    assessment_status=assess_blob.get("status") or assess_blob.get("assessment_status"),
                    delivery_status=assess_blob.get("delivery_status") or assess_blob.get("assessment_delivery_status"),
                    application_status=raw_status,
                )
                assessment_allowed_actions = _assessment_cohorts.allowed_actions_for_cohort(
                    assessment_cohort, can_manage=True
                )
                for action_name in assessment_allowed_actions:
                    allowed_actions.append(action_name)
                if not assessment_cohort and "send_assessment" not in allowed_actions:
                    if str(raw_status or "").strip().lower() in set(_assessment_cohorts.ASSESSMENT_ELIGIBLE_STATUSES):
                        allowed_actions.append("send_assessment")
            if cv_received and "interview.manage" in perms:
                allowed_actions.append("send_video_interview")
            allowed_actions = list(dict.fromkeys(allowed_actions))
    elif include_assessment and cv_received:
        import assessment_cohorts as _assessment_cohorts

        assess_blob = row.get("assessment_json") if isinstance(row.get("assessment_json"), dict) else {}
        if not assess_blob:
            assess_blob = raw_json.get("assessment") if isinstance(raw_json.get("assessment"), dict) else {}
        assessment_cohort = _assessment_cohorts.classify_attempt_state(
            assessment_status=assess_blob.get("status") or assess_blob.get("assessment_status"),
            delivery_status=assess_blob.get("delivery_status") or assess_blob.get("assessment_delivery_status"),
            application_status=raw_status,
        )

    stage_changed_at = lifecycle_event.get("created_at")
    sent_at = communication.get("sent_at")
    stage_changed_without_contact = (
        (not held_status)
        and canonical_stage in {"shortlisted", "interview", "hired", "rejected"}
        and (
            communication_status != "sent"
            or (
                stage_changed_at is not None
                and sent_at is not None
                and str(sent_at) < str(stage_changed_at)
            )
        )
    )
    return {
        "canonical_stage": canonical_stage,
        "status_label": _rl.stage_label(canonical_stage),
        "intake_source": _application_intake_source(row, raw_json),
        "cv_processing": {
            "status": cv_status,
            "received": cv_received,
            "automatic": True,
        },
        "screening": {
            "status": screening_status,
            "automatic": bool(screening),
        },
        "communication": {
            "status": communication_status,
            "message_kind": communication.get("message_kind"),
            "channel": communication.get("channel") or communication.get("notification_channel"),
            "sent_at": json_safe(sent_at),
            "failed_at": json_safe(communication.get("failed_at")),
            "last_error": communication.get("last_error"),
            "stage_changed_without_contact": stage_changed_without_contact,
        },
        "automatic_activity": automatic_activity,
        "waiting_for_hr": waiting_for_hr,
        "allowed_actions": allowed_actions,
        "assessment_cohort": assessment_cohort,
        "assessment_allowed_actions": assessment_allowed_actions,
    }



def prehire_application_summary(
    row: dict[str, Any],
    *,
    include_raw: bool = False,
    include_assessment: bool = True,
    permissions: set[str] | list[str] | None = None,
) -> dict[str, Any]:
    raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
    candidate_raw = row.get("candidate_raw_json") if isinstance(row.get("candidate_raw_json"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    profile = row.get("candidate_profile") if isinstance(row.get("candidate_profile"), dict) else {}
    cv = raw_json.get("cv") if isinstance(raw_json.get("cv"), dict) else {}
    cv_storage = cv.get("storage") if isinstance(cv.get("storage"), dict) else {}
    assessment = row.get("assessment_json") if isinstance(row.get("assessment_json"), dict) else (raw_json.get("assessment") if isinstance(raw_json.get("assessment"), dict) else {})
    latest_interview = row.get("interview_json") if isinstance(row.get("interview_json"), dict) else None
    interview = candidate_interview_summary(latest_interview) if latest_interview else (raw_json.get("interview") if isinstance(raw_json.get("interview"), dict) else {})
    payload = {
        "app_key": row.get("app_key"),
        "company_code": row.get("company_code"),
        "phone": row.get("phone"),
        "candidate": {
            "name": dashboard_candidate_name(row),
            "email": row.get("candidate_email") or candidate_raw.get("email"),
            "profile": json_safe(profile) if include_raw else None,
        },
        "position": {
            "code": row.get("position_code"),
            "title": row.get("position_title") or row.get("position_code"),
        },
        "status": row.get("status"),
        "lifecycle_version": int(row.get("lifecycle_version") or 0),
        "owner_user_id": str(row.get("owner_user_id")) if row.get("owner_user_id") else None,
        "owner_assigned_at": json_safe(row.get("owner_assigned_at")),
        "owner_assigned_by_user_id": str(row.get("owner_assigned_by_user_id")) if row.get("owner_assigned_by_user_id") else None,
        "ownership_version": int(row.get("ownership_version") or 0),
        "owner": {
            "user_id": str(row.get("owner_user_id")),
            "name": row.get("owner_name") or "",
            "email": row.get("owner_email") or "",
            "role": row.get("owner_role") or "",
            "status": row.get("owner_status") or "",
        } if row.get("owner_user_id") else None,
        "open_task_count": int(row.get("open_task_count") or 0),
        "overdue_task_count": int(row.get("overdue_task_count") or 0),
        "tags": json_safe(row.get("tags_json") or []),
        "current_step": row.get("current_step"),
        "screening_status": row.get("screening_status") or screening.get("status"),
        "data_source": row.get("data_source") or raw_json.get("data_source") or PRODUCTION_DATA_SOURCE,
        "lead_quality": application_lead_quality(row),
        "cv": {
            "received": bool(row.get("cv_received") is True or cv),
            "storage_status": ((cv.get("storage") or {}).get("status") if isinstance(cv.get("storage"), dict) else None),
            "filename": cv.get("filename"),
            "mime_type": cv_storage.get("mime_type"),
            "size_bytes": cv_storage.get("size_bytes"),
            "preview_available": bool(cv_storage.get("url") or cv.get("path")),
        },
        "ingested_at": json_safe(row.get("ingested_at")),
        "updated_at": json_safe(row.get("updated_at")),
    }
    if include_assessment:
        payload["assessment"] = json_safe(assessment) if assessment else None
    payload["interview"] = json_safe(interview) if interview else None
    payload.update(
        _application_ui_contract(
            row,
            include_assessment=include_assessment,
            permissions=permissions,
        )
    )
    rank_evaluation = row.get("rank_evaluation_json") if isinstance(row.get("rank_evaluation_json"), dict) else None
    if rank_evaluation:
        payload["ranking"] = rank_evaluation
    if include_raw:
        payload["raw_json"] = json_safe(raw_json)
        payload["candidate_raw_json"] = json_safe(candidate_raw)
    else:
        payload["candidate"] = {key: value for key, value in payload["candidate"].items() if value is not None}
    return payload


def dashboard_delivery_status(row: dict[str, Any]) -> str:
    status = str(row.get("status") or "").strip().lower()
    error = str(row.get("last_error") or "").strip().lower()
    if status == "sent":
        return "sent"
    if error == "conversation_closed":
        return "blocked_closed_conversation"
    if error == "conversation_inactive":
        return "stale_conversation"
    if error in {"missing_candidate_conversation_id", "no_usable_conversation_id"}:
        return "no_usable_conversation"
    if status == "failed":
        return "failed"
    return status or "unknown"


def dashboard_apply_whatsapp_number() -> str:
    return _prehire_jobs.apply_whatsapp_number()


def dashboard_apply_link(apply_code: str | None) -> str | None:
    return _prehire_jobs.apply_link(apply_code)


def dashboard_position_summary(row: dict[str, Any]) -> dict[str, Any]:
    """Serialize a positions inventory row via the Jobs authority module."""
    vacancy = {
        "vacancies": row.get("vacancies"),
        "filled_vacancies": row.get("filled_vacancies"),
        "remaining_vacancies": row.get("remaining_vacancies"),
    }
    payload = _prehire_jobs.serialize_job(row, vacancy=vacancy, include_salary=True)
    # Preserve inventory aliases used by Overview / pickers / legacy UI.
    payload["position_title"] = payload.get("title") or payload.get("position_code")
    payload["stage_counts"] = json_safe(row.get("stage_counts") or [])
    payload["recent_applicants"] = json_safe(row.get("recent_applicants") or [])
    payload["notifications"] = json_safe(row.get("notifications") or [])
    payload["latest_applicant"] = row.get("latest_candidate_name") or row.get("latest_phone") or payload.get("latest_applicant")
    payload["latest_applicant_app_key"] = row.get("latest_applicant_app_key") or payload.get("latest_applicant_app_key")
    payload["latest_application_at"] = json_safe(row.get("latest_application_at") or payload.get("latest_application_at"))
    payload["application_count"] = int(row.get("application_count") or payload.get("application_count") or 0)
    payload["active_count"] = int(row.get("active_count") or payload.get("active_count") or 0)
    return payload


def _dashboard_prehire_positions_query(
    company: str,
    *,
    limit: int = 200,
    offset: int = 0,
    search: str | None = None,
    status: str | None = None,
    department: str | None = None,
    location: str | None = None,
    recruiter_user_id: str | None = None,
    hiring_manager_user_id: str | None = None,
    deadline: str | None = None,
    has_remaining_vacancies: bool | None = None,
    cursor: str | None = None,
    visibility_sql: str | None = None,
    visibility_params: list[Any] | None = None,
) -> tuple[list[dict[str, Any]], int]:
    """Canonical Jobs inventory: `positions` is the sole authority for whether a
    job opening exists. Application aggregates are LEFT JOINed for counts only —
    orphan/imported applications never synthesize a parent job row.

    `status` may be draft/open/paused/closed/all. `search` is title/code ILIKE.
    Optional filters: department, location, recruiter, hiring manager, deadline
    window (overdue|upcoming|none), remaining vacancies.
    Offset pagination is primary; optional `cursor` is `updated_at|position_code`
    for stable continuation when the first page shifts.
    """
    import jobs_queue_contract as _jobs_contract

    term = (search or "").strip()
    like = f"%{_ilike_escape(term)}%" if term else ""
    status_filter = _jobs_contract.coerce_job_status_filter(status)
    dept_filter = str(department or "").strip()
    loc_filter = str(location or "").strip()
    recruiter_filter = str(recruiter_user_id or "").strip()
    hm_filter = str(hiring_manager_user_id or "").strip()
    deadline_filter = str(deadline or "").strip().lower()
    if deadline_filter not in {"overdue", "upcoming", "none", ""}:
        deadline_filter = ""
    remaining_only = bool(has_remaining_vacancies) if has_remaining_vacancies is not None else False
    cursor_updated_at = None
    cursor_code = ""
    if cursor and "|" in str(cursor):
        parts = str(cursor).split("|", 1)
        cursor_updated_at = parts[0].strip() or None
        cursor_code = parts[1].strip() if len(parts) > 1 else ""
    vis_sql = str(visibility_sql or "").strip()
    vis_params = list(visibility_params or [])
    visibility_clause = f" AND ({vis_sql})" if vis_sql else ""
    active_pipeline_sql = _jobs_contract.active_pipeline_status_filter_sql("status")
    effective_status_sql = _jobs_contract.effective_job_status_sql("p.status")
    prod_cv_sql = _jobs_contract.APPLICATIONS_PRODUCTION_CV_SQL
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                WITH app_stats AS (
                  SELECT
                    company_code,
                    position_code,
                    COALESCE(MAX(position_title), position_code) AS position_title,
                    COUNT(*) AS application_count,
                    COUNT(*) FILTER (WHERE {active_pipeline_sql}) AS active_count,
                    COUNT(*) FILTER (WHERE LOWER(COALESCE(status, '')) = 'hired') AS filled_vacancies,
                    MAX(updated_at) AS latest_application_at
                  FROM applications
                  WHERE company_code=%s
                    AND NULLIF(TRIM(COALESCE(position_code, '')), '') IS NOT NULL
                    AND {prod_cv_sql}
                  GROUP BY company_code, position_code
                ),
                latest AS (
                  SELECT DISTINCT ON (a.company_code, a.position_code)
                    a.company_code,
                    a.position_code,
                    a.app_key AS latest_applicant_app_key,
                    a.phone AS latest_phone,
                    COALESCE(NULLIF(c.name, ''), a.raw_json->>'candidate_name', a.raw_json->>'name') AS latest_candidate_name
                  FROM applications a
                  LEFT JOIN candidates c ON c.phone=a.phone
                  WHERE a.company_code=%s
                    AND NULLIF(TRIM(COALESCE(a.position_code, '')), '') IS NOT NULL
                    AND COALESCE(a.data_source, a.raw_json->>'data_source', 'production')='production'
                    AND (a.cv_received IS TRUE OR jsonb_typeof(a.raw_json->'cv') = 'object')
                  ORDER BY a.company_code, a.position_code, a.ingested_at DESC NULLS LAST, a.updated_at DESC NULLS LAST
                ),
                combined AS (
                  SELECT
                    p.*,
                    NULLIF(TRIM(c.name), '') AS company_display_name,
                    COALESCE(p.title, p.position_code) AS position_title,
                    {effective_status_sql} AS effective_status,
                    COALESCE(s.application_count, 0) AS application_count,
                    COALESCE(s.active_count, 0) AS active_count,
                    COALESCE(s.filled_vacancies, 0) AS filled_vacancies,
                    CASE
                      WHEN p.vacancies IS NULL THEN NULL
                      ELSE GREATEST(0, p.vacancies - COALESCE(s.filled_vacancies, 0))
                    END AS remaining_vacancies,
                    s.latest_application_at,
                    l.latest_applicant_app_key,
                    l.latest_phone,
                    l.latest_candidate_name
                  FROM positions p
                  LEFT JOIN companies c ON c.company_code=p.company_code
                  LEFT JOIN app_stats s ON s.company_code=p.company_code AND s.position_code=p.position_code
                  LEFT JOIN latest l ON l.company_code=p.company_code AND l.position_code=p.position_code
                  WHERE p.company_code=%s
                    AND NULLIF(TRIM(COALESCE(p.position_code, '')), '') IS NOT NULL
                )
                SELECT *, COUNT(*) OVER() AS total_count
                FROM combined
                WHERE (%s = '' OR position_title ILIKE %s OR position_code ILIKE %s OR COALESCE(title_ar, '') ILIKE %s)
                  AND (%s = '' OR effective_status = %s)
                  AND (%s = '' OR LOWER(COALESCE(department, '')) = LOWER(%s))
                  AND (%s = '' OR LOWER(COALESCE(location, '')) = LOWER(%s))
                  AND (%s = '' OR CAST(recruiter_user_id AS text) = %s)
                  AND (%s = '' OR CAST(hiring_manager_user_id AS text) = %s)
                  AND (
                    %s = ''
                    OR (%s = 'none' AND application_deadline IS NULL)
                    OR (%s = 'overdue' AND application_deadline IS NOT NULL AND application_deadline < CURRENT_DATE)
                    OR (%s = 'upcoming' AND application_deadline IS NOT NULL AND application_deadline >= CURRENT_DATE)
                  )
                  AND (%s = FALSE OR (remaining_vacancies IS NOT NULL AND remaining_vacancies > 0))
                  AND (
                    %s IS NULL
                    OR updated_at < %s::timestamptz
                    OR (updated_at = %s::timestamptz AND position_code > %s)
                  )
                  {visibility_clause}
                ORDER BY COALESCE(updated_at, latest_application_at) DESC NULLS LAST, position_code ASC
                LIMIT %s OFFSET %s
                """,
                (
                    company,
                    company,
                    company,
                    term,
                    like,
                    like,
                    like,
                    status_filter,
                    status_filter,
                    dept_filter,
                    dept_filter,
                    loc_filter,
                    loc_filter,
                    recruiter_filter,
                    recruiter_filter,
                    hm_filter,
                    hm_filter,
                    deadline_filter,
                    deadline_filter,
                    deadline_filter,
                    deadline_filter,
                    remaining_only,
                    cursor_updated_at,
                    cursor_updated_at,
                    cursor_updated_at,
                    cursor_code,
                    *vis_params,
                    limit,
                    offset if not cursor_updated_at else 0,
                ),
            )
            rows = [dict(row) for row in cur.fetchall()]
            total_count = int(rows[0]["total_count"]) if rows else 0
            codes = [str(row.get("position_code") or "") for row in rows if row.get("position_code")]
            stage_counts: dict[str, list[dict[str, Any]]] = {}
            recent: dict[str, list[dict[str, Any]]] = {}
            notifications: dict[str, list[dict[str, Any]]] = {}
            if codes:
                cur.execute(
                    """
                    SELECT position_code, status, COUNT(*) AS count
                    FROM applications
                    WHERE company_code=%s AND position_code = ANY(%s)
                      AND COALESCE(data_source, raw_json->>'data_source', 'production')='production'
                      AND (cv_received IS TRUE OR jsonb_typeof(raw_json->'cv') = 'object')
                    GROUP BY position_code, status
                    """,
                    (company, codes),
                )
                for row in cur.fetchall():
                    stage_counts.setdefault(str(row.get("position_code") or ""), []).append({"status": row.get("status"), "count": int(row.get("count") or 0)})
                cur.execute(
                    """
                    SELECT *
                    FROM (
                      SELECT
                        a.position_code,
                        a.app_key,
                        a.phone,
                        COALESCE(NULLIF(c.name, ''), a.raw_json->>'candidate_name', a.raw_json->>'name') AS candidate_name,
                        c.email AS candidate_email,
                        a.status,
                        a.ingested_at,
                        a.updated_at,
                        ROW_NUMBER() OVER (PARTITION BY a.position_code ORDER BY a.ingested_at DESC NULLS LAST, a.updated_at DESC NULLS LAST) AS rn
                      FROM applications a
                      LEFT JOIN candidates c ON c.phone=a.phone
                      WHERE a.company_code=%s AND a.position_code = ANY(%s)
                        AND COALESCE(a.data_source, a.raw_json->>'data_source', 'production')='production'
                        AND (a.cv_received IS TRUE OR jsonb_typeof(a.raw_json->'cv') = 'object')
                    ) recent
                    WHERE rn <= 5
                    ORDER BY position_code, rn
                    """,
                    (company, codes),
                )
                for row in cur.fetchall():
                    item = json_safe(dict(row))
                    recent.setdefault(str(row.get("position_code") or ""), []).append(item)
                cur.execute(
                    """
                    SELECT *
                    FROM (
                      SELECT
                        a.position_code,
                        ode.delivery_id,
                        ode.target_phone,
                        ode.status,
                        ode.last_error,
                        ode.created_at,
                        ROW_NUMBER() OVER (PARTITION BY a.position_code ORDER BY ode.created_at DESC) AS rn
                      FROM outbound_delivery_events ode
                      JOIN applications a ON a.app_key=ode.subject_key
                      WHERE a.company_code=%s AND a.position_code = ANY(%s)
                        AND COALESCE(a.data_source, a.raw_json->>'data_source', 'production')='production'
                        AND (a.cv_received IS TRUE OR jsonb_typeof(a.raw_json->'cv') = 'object')
                    ) events
                    WHERE rn <= 5
                    ORDER BY position_code, rn
                    """,
                    (company, codes),
                )
                for row in cur.fetchall():
                    item = json_safe(dict(row))
                    notifications.setdefault(str(row.get("position_code") or ""), []).append(item)
            import prehire_team_directory as _td

            owner_ids = []
            for row in rows:
                owner_ids.append(row.get("recruiter_user_id"))
                owner_ids.append(row.get("hiring_manager_user_id"))
            owner_names = _td.ownership_display_names(cur, company=company, user_ids=owner_ids)
    enriched = []
    for row in rows:
        code = str(row.get("position_code") or "")
        metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
        raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
        if not row.get("description"):
            row["description"] = metadata.get("description") or raw_json.get("description")
        if not row.get("requirements"):
            row["requirements"] = metadata.get("requirements") or raw_json.get("requirements")
        rid = str(row.get("recruiter_user_id") or "")
        hid = str(row.get("hiring_manager_user_id") or "")
        row["recruiter_name"] = owner_names.get(rid) if rid else None
        row["hiring_manager_name"] = owner_names.get(hid) if hid else None
        row["stage_counts"] = stage_counts.get(code, [])
        row["recent_applicants"] = recent.get(code, [])
        row["notifications"] = notifications.get(code, [])
        enriched.append(dashboard_position_summary(row))
    return enriched, total_count


def dashboard_prehire_positions_payload(
    company: str,
    *,
    limit: int = 200,
    offset: int = 0,
    search: str | None = None,
    status: str | None = None,
    department: str | None = None,
    location: str | None = None,
    recruiter_user_id: str | None = None,
    hiring_manager_user_id: str | None = None,
    deadline: str | None = None,
    has_remaining_vacancies: bool | None = None,
    cursor: str | None = None,
) -> list[dict[str, Any]]:
    rows, _ = _dashboard_prehire_positions_query(
        company,
        limit=limit,
        offset=offset,
        search=search,
        status=status,
        department=department,
        location=location,
        recruiter_user_id=recruiter_user_id,
        hiring_manager_user_id=hiring_manager_user_id,
        deadline=deadline,
        has_remaining_vacancies=has_remaining_vacancies,
        cursor=cursor,
    )
    return rows


