def _audit_category(action_type: str | None) -> str:
    return AUDIT_CATEGORY_BY_ACTION.get(str(action_type or ""), "Other")


def _audit_target_display(payload: dict[str, Any]) -> str | None:
    """Pull a human, NON-sensitive target name from the stored payload. Never
    returns emails/keys that look like identifiers or anything secret."""
    data = payload if isinstance(payload, dict) else {}

    def _clean(val: Any) -> str | None:
        if not isinstance(val, str):
            return None
        cleaned = val.strip()
        # Only surface readable names — skip emails, tokens, and long opaque ids.
        if cleaned and "@" not in cleaned and len(cleaned) <= 80 and not re.fullmatch(r"[0-9a-f]{16,}", cleaned):
            return cleaned
        return None

    details = data.get("details") if isinstance(data.get("details"), dict) else {}
    for key in ("employee_name", "candidate_name", "target_name", "display_name", "subject_name", "name"):
        out = _clean(details.get(key))
        if out:
            return out
    normalized = data.get("normalized_action_result") if isinstance(data.get("normalized_action_result"), dict) else {}
    for key in ("target_label", "subject_label", "display", "employee_name", "candidate_name"):
        out = _clean(normalized.get(key))
        if out:
            return out
    action = data.get("action") if isinstance(data.get("action"), dict) else {}
    return _clean(action.get("target")) or _clean(normalized.get("target_id"))


def _audit_item(row: dict[str, Any], users_by_id: dict[str, Any], users_by_email: dict[str, Any]) -> dict[str, Any]:
    payload = row.get("result") if isinstance(row.get("result"), dict) else {}
    requested = payload.get("requested_by") if isinstance(payload.get("requested_by"), dict) else {}
    action_type = str(row.get("action_type") or "")
    uid = str(row.get("actor_user_id") or "").strip()
    email = normalize_email(row.get("actor_email"))
    phone = digits(row.get("actor_phone")) or None
    user = users_by_id.get(uid) or (users_by_email.get(email) if email else None) or {}
    name = str(requested.get("name") or "").strip() or str(user.get("name") or "").strip()
    role_key = normalize_hr_role(row.get("actor_role") or user.get("role") or requested.get("role"))
    role_label = ROLE_LABELS.get(role_key, "")
    actor_display = name or email or (f"+{phone}" if phone else "") or role_label or "A team member"

    target = _audit_target_display(payload)
    verb = AUDIT_ACTION_LABELS.get(action_type)
    stored_summary = str(payload.get("summary") or "").strip()
    if verb:
        summary = f"{actor_display} {verb}" + (f" · {target}" if target else "")
    elif stored_summary:
        summary = stored_summary if actor_display and actor_display in stored_summary else (f"{actor_display}: {stored_summary}" if actor_display else stored_summary)
    else:
        humanized = re.sub(r"[_\s]+", " ", action_type).strip() or "performed an action"
        summary = f"{actor_display} {humanized}" + (f" · {target}" if target else "")

    created = row.get("created_at")
    return {
        "id": str(row.get("result_id") or ""),
        "at": created.isoformat() if hasattr(created, "isoformat") else (str(created) if created else None),
        "actor": {
            "name": name or None,
            "email": email or None,
            "phone": phone,
            "role": role_key,
            "role_label": role_label or None,
            "display": actor_display,
        },
        "action_type": action_type,
        "category": _audit_category(action_type),
        "summary": summary,
        "target": target,
        "status": str(row.get("status") or "") or None,
        "sensitive": action_type in AUDIT_SENSITIVE_ACTIONS,
    }


@app.get("/dashboard/activity")
def dashboard_company_activity(
    start_date: str | None = Query(default=None),
    end_date: str | None = Query(default=None),
    actor: str | None = Query(default=None),
    category: str | None = Query(default=None),
    action_type: str | None = Query(default=None),
    q: str | None = Query(default=None),
    limit: int = Query(default=50, ge=1, le=200),
    offset: int = Query(default=0, ge=0),
    format: str | None = Query(default=None),
    context: dict[str, Any] = Depends(dashboard_context),
):
    # Permission-only gate (audit spans every module): Owner + HR Manager only.
    require_entitlement(context, None, "audit.read")
    company = context["company_code"]

    where = [
        "company_code = %s",
        "left(action_type, 6) <> 'setup_'",
        "left(action_type, 5) <> 'list_'",
        "left(action_type, 7) <> 'answer_'",
        "left(action_type, 4) <> 'get_'",
    ]
    params: list[Any] = [company]
    if AUDIT_HIDDEN_ACTIONS:
        where.append("action_type <> ALL(%s)")
        params.append(list(AUDIT_HIDDEN_ACTIONS))

    start = _coerce_employee_start_date(start_date) if start_date else None
    end = _coerce_employee_start_date(end_date) if end_date else None
    if start:
        where.append("created_at >= %s")
        params.append(datetime(start.year, start.month, start.day, tzinfo=timezone.utc))
    if end:
        where.append("created_at < %s")
        params.append(datetime(end.year, end.month, end.day, tzinfo=timezone.utc) + timedelta(days=1))

    if category and category not in ("", "all"):
        if category == "Other":
            where.append("action_type <> ALL(%s)")
            params.append(list(AUDIT_CATEGORY_BY_ACTION.keys()))
        else:
            cat_actions = [a for a, c in AUDIT_CATEGORY_BY_ACTION.items() if c == category]
            where.append("action_type = ANY(%s)")
            params.append(cat_actions or ["__none__"])

    if action_type:
        where.append("action_type = %s")
        params.append(str(action_type).strip())

    if actor and actor.strip():
        token = actor.strip()
        where.append("(actor_user_id = %s OR actor_email ILIKE %s OR actor_phone LIKE %s)")
        params += [token, f"%{token}%", f"%{digits(token) or token}%"]

    if q and q.strip():
        like = f"%{q.strip()}%"
        where.append("(action_type ILIKE %s OR coalesce(result->>'summary','') ILIKE %s OR coalesce(actor_email,'') ILIKE %s)")
        params += [like, like, like]

    where_sql = " AND ".join(where)
    is_csv = str(format or "").lower() == "csv"
    page_limit = 5000 if is_csv else limit
    page_offset = 0 if is_csv else offset

    users_by_id: dict[str, Any] = {}
    users_by_email: dict[str, Any] = {}
    actors: list[dict[str, Any]] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT user_id, name, email, phone, role, status FROM dashboard_users WHERE company_code=%s ORDER BY lower(name), email",
                (company,),
            )
            for raw in cur.fetchall():
                u = dict(raw)
                uid = str(u.get("user_id") or "").strip()
                em = normalize_email(u.get("email"))
                if uid:
                    users_by_id[uid] = u
                if em:
                    users_by_email[em] = u
                actors.append({
                    "user_id": uid or None,
                    "name": str(u.get("name") or "").strip() or None,
                    "email": em or None,
                    "role_label": ROLE_LABELS.get(normalize_hr_role(u.get("role")), None),
                })
            cur.execute(f"SELECT count(*) AS n FROM action_results WHERE {where_sql}", params)
            total = int((cur.fetchone() or {}).get("n") or 0)
            cur.execute(
                f"SELECT result_id, action_type, status, result, created_at, "
                f"actor_user_id, actor_email, actor_phone, actor_role "
                f"FROM action_results WHERE {where_sql} ORDER BY created_at DESC LIMIT %s OFFSET %s",
                params + [page_limit, page_offset],
            )
            rows = [dict(r) for r in cur.fetchall()]

    items = [_audit_item(r, users_by_id, users_by_email) for r in rows]

    if is_csv:
        def csv_rows():
            for it in items:
                yield [
                    it.get("at") or "",
                    it["actor"]["display"],
                    it["actor"].get("role_label") or "",
                    it["category"],
                    it["summary"],
                    it.get("status") or "",
                ]
        return csv_stream_response(
            f"activity-{company}.csv",
            ["When", "Who", "Role", "Category", "Activity", "Status"],
            csv_rows(),
        )

    return {
        "company_code": company,
        "total": total,
        "limit": limit,
        "offset": offset,
        "count": len(items),
        "has_more": offset + len(items) < total,
        "categories": AUDIT_CATEGORIES,
        "actors": actors,
        "items": items,
    }


INTERVIEW_STATUSES = {"scheduled", "completed", "no_show", "rescheduled", "cancelled"}
INTERVIEW_FEEDBACK_STATUSES = {"notes_pending", "feedback_complete"}


def normalize_interview_status(value: str | None, *, default: str = "scheduled") -> str:
    normalized = re.sub(r"[\s-]+", "_", str(value or "").strip().lower())
    aliases = {"no_show": "no_show", "noshow": "no_show", "canceled": "cancelled", "cancelled": "cancelled"}
    normalized = aliases.get(normalized, normalized)
    return normalized if normalized in INTERVIEW_STATUSES else default


def normalize_interview_feedback_status(value: str | None, *, default: str = "notes_pending") -> str:
    normalized = re.sub(r"[\s-]+", "_", str(value or "").strip().lower())
    return normalized if normalized in INTERVIEW_FEEDBACK_STATUSES else default


def parse_datetime_or_none(value: Any) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(text)
    except Exception:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone(timedelta(hours=3)))
    return parsed


def deep_first_value(value: Any, keys: set[str]) -> Any:
    if isinstance(value, dict):
        for key, item in value.items():
            if key in keys and item:
                return item
        for item in value.values():
            found = deep_first_value(item, keys)
            if found:
                return found
    elif isinstance(value, list):
        for item in value:
            found = deep_first_value(item, keys)
            if found:
                return found
    return None


def interview_meet_link_from_calendar(result: dict[str, Any] | None) -> str | None:
    if not isinstance(result, dict):
        return None
    direct = deep_first_value(result, {"hangoutLink", "meet_link", "google_meet_link"})
    if direct:
        return str(direct)
    entry_points = deep_first_value(result, {"entryPoints"})
    if isinstance(entry_points, list):
        for entry in entry_points:
            if isinstance(entry, dict) and entry.get("entryPointType") == "video" and entry.get("uri"):
                return str(entry["uri"])
    return None


def interview_calendar_event_id(result: dict[str, Any] | None) -> str | None:
    if not isinstance(result, dict):
        return None
    event = deep_first_value(result, {"event"})
    if isinstance(event, dict) and event.get("id"):
        return str(event["id"])
    value = deep_first_value(result, {"event_id", "calendar_event_id", "htmlLink"})
    return str(value) if value else None


def update_application_interview_snapshot(app_key: str, interview: dict[str, Any]) -> None:
    if not app_key:
        return
    company_code = str(interview.get("company_code") or "").strip().upper()
    snapshot = {
        "interview_id": str(interview.get("interview_id") or ""),
        "status": interview.get("status"),
        "feedback_status": interview.get("feedback_status"),
        "interview_type": interview.get("interview_type"),
        "async_status": interview.get("async_status"),
        "scheduled_start": json_safe(interview.get("scheduled_start")),
        "scheduled_end": json_safe(interview.get("scheduled_end")),
        "meet_link": interview.get("meet_link"),
        "calendar_event_id": interview.get("calendar_event_id"),
        "calendar_invite_sent": bool(interview.get("calendar_invite_sent")),
        "candidate_invited": bool(interview.get("candidate_invited")),
        "candidate_notified": bool(interview.get("candidate_notified")),
        "notification_channel": interview.get("notification_channel"),
        "sent_subject": interview.get("sent_subject"),
        "sent_body": interview.get("sent_body"),
        "invite_sent_at": json_safe(interview.get("invite_sent_at")),
        "consent_accepted_at": json_safe(interview.get("consent_accepted_at")),
        "completed_at": json_safe(interview.get("completed_at")),
        "summary": (interview.get("ai_summary") or {}).get("summary") if isinstance(interview.get("ai_summary"), dict) else None,
        "ai_summary": json_safe(interview.get("ai_summary")) if isinstance(interview.get("ai_summary"), dict) else {},
        "updated_at": now_iso(),
    }
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE applications
                SET raw_json=jsonb_set(COALESCE(raw_json, '{}'::jsonb), '{interview}', %s::jsonb, true),
                    updated_at=CURRENT_DATE
                WHERE app_key=%s
                  AND (%s='' OR company_code=%s)
                """,
                (Json(json_safe(snapshot)), app_key, company_code, company_code),
            )
        conn.commit()


def candidate_interview_summary(row: dict[str, Any]) -> dict[str, Any]:
    import recruiting_lifecycle as _rl
    import interview_lifecycle as _il

    ai_summary = row.get("ai_summary") if isinstance(row.get("ai_summary"), dict) else {}
    application_stage = _rl.normalize_stage(row.get("application_status")) or str(
        row.get("application_status") or ""
    )
    truth = _il.communication_truth(row)
    communication_status = truth["communication_status"]
    notes_status = _il.derive_notes_status(row)
    candidate_confirmation = truth["candidate_confirmation"]
    next_human_action = _il.next_human_action(row, truth)
    human_feedback = _il.normalize_feedback_status(row.get("human_feedback_status") or row.get("feedback_status"))
    summary = {
        "interview_id": str(row.get("interview_id") or ""),
        "company_code": row.get("company_code"),
        "app_key": row.get("app_key"),
        "phone": row.get("phone"),
        "candidate_name": row.get("candidate_name"),
        "candidate_email": row.get("candidate_email"),
        "position_code": row.get("position_code"),
        "position_title": row.get("position_title"),
        "application_stage": application_stage,
        "application_stage_label": _rl.stage_label(application_stage) if application_stage else None,
        "interview_type": row.get("interview_type") or ("async_video" if row.get("source") == "async_video" else "live"),
        "status": row.get("status"),
        "feedback_status": row.get("feedback_status"),
        "human_feedback_status": human_feedback,
        "async_status": row.get("async_status"),
        "scheduled_start": json_safe(row.get("scheduled_start")),
        "scheduled_end": json_safe(row.get("scheduled_end")),
        "timezone": row.get("timezone"),
        "duration_minutes": row.get("duration_minutes"),
        "meeting_type": row.get("meeting_type"),
        "location": row.get("location"),
        "meet_link": row.get("meet_link"),
        "calendar_event_id": row.get("calendar_event_id"),
        "calendar_invite_sent": bool(row.get("calendar_invite_sent")),
        "candidate_invited": bool(row.get("candidate_invited")),
        "candidate_notified": bool(row.get("candidate_notified")),
        "provider_key": row.get("provider_key") or "none",
        "provider_sync_status": truth["provider_sync_status"],
        "provider_sync_error": row.get("provider_sync_error"),
        "provider_accepted": truth["provider_accepted"],
        "channel_send_status": truth["channel_send_status"],
        "rsvp_status": truth["rsvp_status"],
        "delivered": truth["delivered"],
        "failed": truth["failed"],
        "communication_status": communication_status,
        "invitation_status": truth["invitation_status"],
        "candidate_confirmation": candidate_confirmation,
        "notification_channel": row.get("notification_channel"),
        "sent_subject": row.get("sent_subject"),
        "sent_body": row.get("sent_body"),
        "invite_sent_at": json_safe(row.get("invite_sent_at")),
        "notes": row.get("notes"),
        "notes_status": notes_status,
        "transcript": row.get("transcript"),
        "ai_summary": json_safe(ai_summary),
        "public_link_expires_at": json_safe(row.get("public_link_expires_at")),
        "consent_accepted_at": json_safe(row.get("consent_accepted_at")),
        "completed_at": json_safe(row.get("completed_at")),
        "async_video_config": json_safe(row.get("async_video_config")) if isinstance(row.get("async_video_config"), dict) else {},
        "question_count": json_safe(row.get("question_count")),
        "response_count": json_safe(row.get("response_count")),
        "source": row.get("source"),
        "created_by_phone": row.get("created_by_phone"),
        "updated_by_phone": row.get("updated_by_phone"),
        "created_at": json_safe(row.get("created_at")),
        "updated_at": json_safe(row.get("updated_at")),
        "next_human_action": next_human_action,
        "retention_expires_at": json_safe(row.get("retention_expires_at")),
        "retention_purged_at": json_safe(row.get("retention_purged_at")),
    }
    if summary.get("interview_type") == "async_video" or row.get("source") == "async_video":
        interview_id = summary["interview_id"]
        readiness = async_video_interview_transcript_readiness(interview_id)
        responses = async_video_interview_responses(interview_id)
        questions = async_video_interview_questions(interview_id)
        summary["response_mode"] = video_interview_response_mode(row)
        summary["video_questions"] = [public_video_question_payload(item) for item in questions]
        summary["video_processing"] = readiness
        summary["video_answers"] = [hr_video_response_payload(item) for item in responses]
        summary["video_review_status"] = async_video_interview_review_status(row, readiness=readiness, responses=responses)
    return summary


def fetch_candidate_interview(interview_id: str, company_code: str) -> dict[str, Any] | None:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM candidate_interviews
                WHERE interview_id=%s AND company_code=%s
                LIMIT 1
                """,
                (interview_id, company_code),
            )
            row = cur.fetchone()
    return dict(row) if row else None


def latest_candidate_interview_for_app(app_key: str, company_code: str) -> dict[str, Any] | None:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM candidate_interviews
                WHERE app_key=%s AND company_code=%s
                ORDER BY scheduled_start DESC NULLS LAST, updated_at DESC
                LIMIT 1
                """,
                (app_key, company_code),
            )
            row = cur.fetchone()
    return dict(row) if row else None


def latest_candidate_interview_for_candidate(application: dict[str, Any], company_code: str) -> dict[str, Any] | None:
    app_key = str(application.get("app_key") or "").strip()
    interview = latest_candidate_interview_for_app(app_key, company_code) if app_key else None
    if interview:
        return interview
    phone = digits(application.get("phone"))
    email = str(application.get("candidate_email") or "").strip().lower()
    if not phone and not email:
        return None
    params: list[Any] = [company_code]
    where = ["company_code=%s"]
    if phone:
        where.append("phone=%s")
        params.append(phone)
    if email:
        where.append("LOWER(candidate_email)=%s")
        params.append(email)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT *
                FROM candidate_interviews
                WHERE {' AND '.join([where[0], '(' + ' OR '.join(where[1:]) + ')'])}
                ORDER BY scheduled_start DESC NULLS LAST, updated_at DESC
                LIMIT 1
                """,
                params,
            )
            row = cur.fetchone()
    return dict(row) if row else None


def interview_time_label(interview: dict[str, Any]) -> str:
    raw = interview.get("scheduled_start")
    parsed = parse_datetime_or_none(raw)
    if parsed:
        kuwait = parsed.astimezone(KUWAIT_TZ)
        hour = kuwait.strftime("%I").lstrip("0") or "0"
        return f"{kuwait.strftime('%A')}, {kuwait.strftime('%B')} {kuwait.day} at {hour}:{kuwait.strftime('%M %p')} Kuwait time"
    return str(raw or "").strip()


def compose_interview_invite_message(application: dict[str, Any], interview: dict[str, Any]) -> str:
    role = interview.get("position_title") or application.get("position_title") or application.get("position_code") or "the role"
    time_label = interview_time_label(interview)
    meet_link = str(interview.get("meet_link") or "").strip()
    details = time_label or "HR will share the confirmed time and joining details."
    if not meet_link and (interview.get("calendar_event_id") or interview.get("calendar_invite_sent")):
        details = f"{details} The calendar invitation contains the joining details."
    template_key = "interview_update" if interview.get("candidate_notified") or interview.get("invite_sent_at") else "interview_invitation"
    return candidate_message_payload(
        template_key,
        application=application,
        role=role,
        details=details,
        link=meet_link,
    )["text"]


def update_interview_invite_delivery(interview_id: str, delivery: dict[str, Any], *, subject: str, body: str) -> None:
    successful_channels = delivery.get("successful_channels") if isinstance(delivery.get("successful_channels"), list) else []
    channel = ", ".join(str(item) for item in successful_channels if item) or None
    ok = bool(successful_channels)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_interviews
                SET candidate_notified=%s,
                    notification_channel=COALESCE(%s, notification_channel),
                    sent_subject=COALESCE(%s, sent_subject),
                    sent_body=COALESCE(%s, sent_body),
                    invite_sent_at=CASE WHEN %s THEN COALESCE(invite_sent_at, now()) ELSE invite_sent_at END,
                    updated_at=now()
                WHERE interview_id=%s
                """,
                (ok, channel, subject, body, ok, interview_id),
            )
        conn.commit()


def interview_delivery_events(app_key: str, *, since: Any = None, limit: int = 20) -> list[dict[str, Any]]:
    params: list[Any] = [app_key]
    since_sql = ""
    parsed_since = parse_datetime_or_none(since)
    if parsed_since:
        since_sql = "AND created_at >= %s"
        params.append(parsed_since)
    params.append(max(1, min(limit, 100)))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT delivery_id, channel, message_kind, status, message_text, last_error,
                       payload, created_at, sent_at, failed_at
                FROM outbound_delivery_events
                WHERE subject_type='candidate'
                  AND subject_key=%s
                  {since_sql}
                  AND (
                    message_text ILIKE '%%interview%%'
                    OR message_text ILIKE '%%meeting%%'
                    OR message_text ILIKE '%%Google Meet%%'
                    OR payload::text ILIKE '%%interview%%'
                  )
                ORDER BY created_at DESC
                LIMIT %s
                """,
                params,
            )
            return [dict(row) for row in cur.fetchall()]


def send_interview_invite(
    application: dict[str, Any],
    *,
    account_id: str | None,
    interview_id: str | None = None,
    preferred_channel: str | None = None,
    explicit: bool = False,
) -> dict[str, Any]:
    try:
        assert_application_communication_allowed(application, kind="interview_invite")  # HELD_COMMUNICATION_AUTHORITY_STAGING_PATCH
    except CandidateCommunicationAuthorityError as exc:
        return exc.as_result()
    company = str(application.get("company_code") or "").strip().upper()
    if not company:
        return {"ok": False, "error": "tenant_scope_required"}
    app_key = str(application.get("app_key") or "").strip()
    interview = fetch_candidate_interview(interview_id, company) if interview_id else latest_candidate_interview_for_app(app_key, company)
    if interview and app_key and str(interview.get("app_key") or "") != app_key:
        interview = None
    if interview and str(interview.get("status") or "").lower() not in {"scheduled", "rescheduled"}:
        interview = None
    if not interview:
        name = application.get("candidate_name") or application.get("phone") or "this candidate"
        safe_message = (
            f"No scheduled interview exists for {name}'s current application yet. "
            "You can schedule one first, or send an AI video interview link instead."
        )
        return {"ok": False, "error": "interview_not_found_for_app_key", "safe_user_message": safe_message, "message": safe_message, "application": json_safe(application)}
    try:
        import tenant_email_authority as _tea

        skip, skip_reason = _tea.should_skip_interview_email_for_calendar(
            sys.modules[__name__],
            company_code=company,
            interview=interview,
            explicit=bool(explicit),
        )
    except Exception:
        skip, skip_reason = False, None
    if skip:
        safe_message = (
            "A calendar invitation was already sent to the candidate, so OctoHR did not send a second interview email. "
            "Turn on “Also send an email with calendar invitations” in Settings, or use Send email explicitly."
        )
        return {
            "ok": True,
            "skipped": True,
            "skip_reason": skip_reason or "calendar_invite_already_sent",
            "safe_user_message": safe_message,
            "message": safe_message,
            "interview": candidate_interview_summary(interview),
            "delivery": {"ok": True, "skipped": True, "successful_channels": [], "last_successful_channel": None},
            "notification_channel": interview.get("notification_channel") or "calendar_email",
            "candidate_notified": bool(interview.get("candidate_notified") or interview.get("calendar_invite_sent")),
            "calendar_invite_sent": bool(interview.get("calendar_invite_sent")),
        }
    subject = "Interview Invitation - OctoHR"
    body = compose_interview_invite_message(application, interview)
    if "join the meeting" in normalize_text(body) and not interview.get("meet_link") and "calendar invite" not in normalize_text(body):
        return {"ok": False, "error": "missing_meet_link_for_joining_copy", "interview": candidate_interview_summary(interview)}
    action = {
        "purpose": "interview_invite",
        "message_text": body,
        "email_subject": subject,
        "preferred_channel": preferred_channel or "email",
        "interview_id": str(interview.get("interview_id") or ""),
        "send_both": preferred_channel == "whatsapp",
    }
    delivery = candidate_communication_router(
        application,
        account_id=account_id,
        kind="interview_invite",
        message=body,
        action=action,
    )
    update_interview_invite_delivery(str(interview["interview_id"]), delivery, subject=subject, body=body)
    refreshed = fetch_candidate_interview(str(interview["interview_id"]), company) or interview
    event_type = "invite_sent" if delivery.get("ok") else "invite_failed"
    record_interview_event(str(interview["interview_id"]), company, str(application.get("app_key") or ""), event_type, {"delivery": json_safe(delivery), "subject": subject, "body": body}, None)
    safe_user_message = None if delivery.get("ok") else communication_delivery_failure_message(
        delivery,
        subject_label=f"{interview.get('candidate_name') or application.get('candidate_name') or 'the candidate'}'s interview invite",
    )
    return {
        "ok": bool(delivery.get("ok")),
        "interview": candidate_interview_summary(refreshed),
        "delivery": json_safe(delivery),
        "notification_channel": delivery.get("last_successful_channel"),
        "sent_subject": subject,
        "sent_body": body,
        "google_meet_link": refreshed.get("meet_link"),
        "candidate_notified": bool(delivery.get("ok")),
        "safe_user_message": safe_user_message,
        "message": safe_user_message,
    }


def interview_invite_status(application: dict[str, Any]) -> dict[str, Any]:
    company = str(application.get("company_code") or "").strip().upper()
    if not company:
        return {"ok": False, "error": "tenant_scope_required"}
    interview = latest_candidate_interview_for_candidate(application, company)
    if not interview:
        return {"ok": False, "error": "interview_not_found", "message": "I do not see a scheduled interview for this candidate yet.", "application": json_safe(application)}
    events = interview_delivery_events(str(application.get("app_key") or ""), since=interview.get("created_at"))
    sent_events = [event for event in events if event.get("status") == "sent"]
    calendar_invited = bool(interview.get("calendar_invite_sent") or (interview.get("calendar_event_id") and interview.get("candidate_email")))
    candidate_notified = bool(interview.get("candidate_notified") or sent_events or calendar_invited)
    channels = []
    if calendar_invited:
        channels.append("calendar_email")
    channels.extend(str(event.get("channel")) for event in sent_events if event.get("channel"))
    channels = list(dict.fromkeys(channels))
    meet_link = interview.get("meet_link")
    if candidate_notified:
        channel_text = ", ".join(channels) if channels else "candidate invite"
        message = f"Yes — {interview.get('candidate_name') or 'the candidate'} has an interview invite via {channel_text}."
        if meet_link:
            message += f" Google Meet: {meet_link}"
        else:
            message += " The Google Calendar invite contains the joining details."
    else:
        message = f"No separate candidate notification is recorded yet for {interview.get('candidate_name') or 'the candidate'}."
    return {
        "ok": True,
        "message": message,
        "interview": candidate_interview_summary(interview),
        "delivery_events": json_safe(events),
        "calendar_invite_sent": calendar_invited,
        "candidate_invited": calendar_invited,
        "candidate_notified": candidate_notified,
        "notification_channels": channels,
        "google_meet_link": meet_link,
    }


def record_interview_event(
    interview_id: str,
    company_code: str,
    app_key: str,
    event_type: str,
    payload: dict[str, Any],
    created_by_phone: str | None = None,
    *,
    actor_context: dict[str, Any] | None = None,
    action: str | None = None,
    target_type: str | None = None,
    target: str | None = None,
) -> None:
    actor = actor_context if isinstance(actor_context, dict) else {}
    company = str(company_code or actor.get("company_code") or "").upper()
    audit_payload = {
        **json_safe(payload or {}),
        "audit": {
            "company_id": company,
            "company_code": company,
            "actor_user_id": actor.get("actor_user_id"),
            "actor_role": actor.get("actor_role"),
            "actor_phone": actor.get("actor_phone") or created_by_phone,
            "app_key": app_key,
            "interview_id": interview_id,
            "action": action or event_type,
            "target": target or interview_id,
            "target_type": target_type or "interview",
            "timestamp": now_iso(),
        },
    }
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO candidate_interview_events (
                  interview_id, company_code, company_id, app_key, event_type, action, target_type, target,
                  payload, actor_user_id, actor_phone, actor_role, created_by_phone
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                """,
                (
                    interview_id,
                    company,
                    company,
                    app_key,
                    event_type,
                    action or event_type,
                    target_type or "interview",
                    target or interview_id,
                    Json(audit_payload),
                    actor.get("actor_user_id"),
                    actor.get("actor_phone") or created_by_phone,
                    actor.get("actor_role"),
                    created_by_phone or actor.get("actor_phone"),
                ),
            )
        conn.commit()


def create_candidate_interview_from_schedule(
    application: dict[str, Any],
    schedule_result: dict[str, Any],
    *,
    created_by_phone: str | None = None,
    source: str = "schedule_interview",
) -> dict[str, Any] | None:
    if not application or not schedule_result:
        return None
    company = str(application.get("company_code") or "").strip().upper()
    if not company:
        return None
    app_key = str(application.get("app_key") or "").strip()
    if not app_key:
        return None
    start = parse_datetime_or_none(schedule_result.get("start"))
    end = parse_datetime_or_none(schedule_result.get("end"))
    calendar = schedule_result.get("result") if isinstance(schedule_result.get("result"), dict) else schedule_result.get("calendar")
    if not isinstance(calendar, dict):
        calendar = schedule_result
    calendar_event_id = interview_calendar_event_id(calendar)
    meet_link = interview_meet_link_from_calendar(schedule_result) or interview_meet_link_from_calendar(calendar)
    candidate_email = application.get("candidate_email")
    calendar_invite_sent = bool(calendar_event_id and candidate_email)
    sent_subject = str(schedule_result.get("summary") or f"OctoHR interview with {application.get('candidate_name') or 'candidate'}")
    sent_body = (
        f"Google Calendar invite sent to {candidate_email}. Google Meet: {meet_link}"
        if meet_link
        else f"Google Calendar invite sent to {candidate_email}. The calendar invite contains the joining details."
    )
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_interviews
                SET status='rescheduled',
                    updated_by_phone=%s,
                    updated_at=now()
                WHERE company_code=%s
                  AND app_key=%s
                  AND status='scheduled'
                  AND (%s IS NULL OR calendar_event_id IS DISTINCT FROM %s)
                """,
                (created_by_phone, company, app_key, calendar_event_id, calendar_event_id),
            )
            cur.execute(
                """
                INSERT INTO candidate_interviews (
                  company_code, app_key, phone, candidate_name, candidate_email, position_code, position_title,
                  status, feedback_status, scheduled_start, scheduled_end, timezone, meeting_type, meet_link,
                  calendar_event_id, calendar_payload, calendar_invite_sent, candidate_invited, candidate_notified,
                  notification_channel, sent_subject, sent_body, invite_sent_at, source, created_by_phone, updated_by_phone
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,'scheduled','notes_pending',%s,%s,'Asia/Kuwait','google_meet',%s,%s,%s,%s,%s,%s,%s,%s,%s,CASE WHEN %s THEN now() ELSE NULL END,%s,%s,%s)
                ON CONFLICT (calendar_event_id) WHERE calendar_event_id IS NOT NULL
                DO UPDATE SET
                  scheduled_start=EXCLUDED.scheduled_start,
                  scheduled_end=EXCLUDED.scheduled_end,
                  meet_link=COALESCE(EXCLUDED.meet_link, candidate_interviews.meet_link),
                  calendar_payload=EXCLUDED.calendar_payload,
                  calendar_invite_sent=EXCLUDED.calendar_invite_sent,
                  candidate_invited=EXCLUDED.candidate_invited,
                  candidate_notified=(candidate_interviews.candidate_notified OR EXCLUDED.candidate_notified),
                  notification_channel=COALESCE(candidate_interviews.notification_channel, EXCLUDED.notification_channel),
                  sent_subject=COALESCE(candidate_interviews.sent_subject, EXCLUDED.sent_subject),
                  sent_body=COALESCE(candidate_interviews.sent_body, EXCLUDED.sent_body),
                  invite_sent_at=COALESCE(candidate_interviews.invite_sent_at, EXCLUDED.invite_sent_at),
                  status='scheduled',
                  feedback_status=COALESCE(NULLIF(candidate_interviews.feedback_status, ''), 'notes_pending'),
                  updated_by_phone=EXCLUDED.updated_by_phone,
                  updated_at=now()
                RETURNING *
                """,
                (
                    company,
                    app_key,
                    application.get("phone"),
                    application.get("candidate_name"),
                    candidate_email,
                    application.get("position_code"),
                    application.get("position_title"),
                    start,
                    end,
                    meet_link,
                    calendar_event_id,
                    Json(json_safe(calendar)),
                    calendar_invite_sent,
                    calendar_invite_sent,
                    calendar_invite_sent,
                    "calendar_email" if calendar_invite_sent else None,
                    sent_subject if calendar_invite_sent else None,
                    sent_body if calendar_invite_sent else None,
                    calendar_invite_sent,
                    source,
                    created_by_phone,
                    created_by_phone,
                ),
            )
            row = dict(cur.fetchone() or {})
        conn.commit()
    if row:
        record_interview_event(str(row["interview_id"]), company, app_key, "scheduled", {"schedule_result": json_safe(schedule_result)}, created_by_phone)
        update_application_interview_snapshot(app_key, row)
    return candidate_interview_summary(row) if row else None


VIDEO_INTERVIEW_RESPONSE_MODES = {"single_video", "per_question_video"}
DEFAULT_VIDEO_INTERVIEW_RESPONSE_MODE = "single_video"
DEFAULT_SINGLE_VIDEO_INTERVIEW_QUESTIONS = (
    "Please introduce yourself and tell us briefly about your background.",
    "Why are you interested in this role?",
    "What experience, skills, or strengths make you a good fit for this position?",
    "When would you be available to start, and is there anything else you would like the hiring team to know?",
)


def video_interview_response_mode(interview: dict[str, Any] | None) -> str:
    config = (interview or {}).get("async_video_config") if isinstance((interview or {}).get("async_video_config"), dict) else {}
    mode = str(config.get("response_mode") or DEFAULT_VIDEO_INTERVIEW_RESPONSE_MODE).strip()
    return mode if mode in VIDEO_INTERVIEW_RESPONSE_MODES else DEFAULT_VIDEO_INTERVIEW_RESPONSE_MODE


def normalize_video_interview_questions(application: dict[str, Any], requested: list[Any] | None = None) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    if requested:
        for index, item in enumerate(requested, start=1):
            data = item.model_dump() if hasattr(item, "model_dump") else item.dict() if hasattr(item, "dict") else (item if isinstance(item, dict) else {})
            prompt = re.sub(r"\s+", " ", str(data.get("prompt_text") or "").strip())
            if not prompt:
                continue
            items.append(
                {
                    "question_order": index,
                    "question_key": f"custom_{index}_{stable_text_hash(prompt)}",
                    "prompt_text": prompt[:1000],
                    "competency": str(data.get("competency") or "role_fit")[:120],
                    "max_duration_seconds": max(30, min(int(data.get("max_duration_seconds") or 120), 600)),
                    "required": bool(data.get("required", True)),
                    "source": "hr_custom",
                }
            )
    if not items:
        items = [
            {
                "question_order": index,
                "question_key": f"standard_v1_{index}",
                "prompt_text": prompt,
                "competency": ["background", "motivation", "role_fit", "availability"][index - 1],
                "max_duration_seconds": 240,
                "required": True,
                "source": "standard_v1_single_video",
            }
            for index, prompt in enumerate(DEFAULT_SINGLE_VIDEO_INTERVIEW_QUESTIONS, start=1)
        ]
    return items[:6]


def async_video_interview_questions(interview_id: str) -> list[dict[str, Any]]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM candidate_video_interview_questions
                WHERE interview_id=%s
                ORDER BY question_order
                """,
                (interview_id,),
            )
            return [dict(row) for row in cur.fetchall()]


def async_video_interview_responses(interview_id: str) -> list[dict[str, Any]]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT r.*, q.prompt_text, q.required, q.competency
                FROM candidate_video_interview_responses r
                LEFT JOIN candidate_video_interview_questions q ON q.question_id=r.question_id
                WHERE r.interview_id=%s
                ORDER BY r.question_order
                """,
                (interview_id,),
            )
            return [dict(row) for row in cur.fetchall()]


def public_video_question_payload(row: dict[str, Any]) -> dict[str, Any]:
    return {
        "question_id": str(row.get("question_id") or ""),
        "question_order": int(row.get("question_order") or 0),
        "question_key": row.get("question_key"),
        "prompt_text": row.get("prompt_text"),
        "competency": row.get("competency"),
        "max_duration_seconds": int(row.get("max_duration_seconds") or 120),
        "required": bool(row.get("required", True)),
    }


def public_video_response_payload(row: dict[str, Any]) -> dict[str, Any]:
    return {
        "response_id": str(row.get("response_id") or ""),
        "question_id": str(row.get("question_id") or ""),
        "question_order": int(row.get("question_order") or 0),
        "has_video": bool(row.get("video_file_id") or row.get("local_path") or row.get("storage_url")),
        "has_transcript": bool(str(row.get("transcript_text") or row.get("response_text") or "").strip()),
        "duration_seconds": json_safe(row.get("duration_seconds")),
        "retake_count": int(row.get("retake_count") or 0),
        "submitted_at": json_safe(row.get("submitted_at")),
    }


def hr_video_response_payload(row: dict[str, Any]) -> dict[str, Any]:
    response_id = str(row.get("response_id") or "")
    interview_id = str(row.get("interview_id") or "")
    transcript_status = str(row.get("transcript_status") or ("completed" if row.get("transcript_text") else "pending"))
    raw = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
    response_mode = str(raw.get("response_mode") or "").strip() or None
    question_text = row.get("prompt_text")
    if response_mode == "single_video":
        question_text = "One video answer covering all questions"
    return {
        "response_id": response_id,
        "question_id": str(row.get("question_id") or ""),
        "question_order": int(row.get("question_order") or 0),
        "question_text": question_text,
        "response_mode": response_mode,
        "covered_questions": json_safe(raw.get("questions") or []),
        "competency": row.get("competency"),
        "required": bool(row.get("required", True)),
        "has_video": bool(row.get("video_file_id") or row.get("local_path") or row.get("storage_url")),
        "video_url": f"/dashboard/prehire/interviews/{interview_id}/responses/{response_id}/video" if response_id and interview_id and (row.get("video_file_id") or row.get("local_path")) else None,
        "transcript_status": transcript_status,
        "transcript_text": row.get("transcript_text") if transcript_status == "completed" else None,
        "transcript_model": row.get("transcript_model"),
        "transcript_language": row.get("transcript_language"),
        "transcript_error": row.get("transcript_error") if transcript_status == "failed" else None,
        "transcribed_at": json_safe(row.get("transcribed_at")),
        "duration_seconds": json_safe(row.get("duration_seconds")),
        "size_bytes": json_safe(row.get("size_bytes")),
        "submitted_at": json_safe(row.get("submitted_at")),
    }


def async_video_interview_public_state(interview: dict[str, Any]) -> dict[str, Any]:
    questions = async_video_interview_questions(str(interview.get("interview_id") or ""))
    responses = async_video_interview_responses(str(interview.get("interview_id") or ""))
    response_mode = video_interview_response_mode(interview)
    response_question_ids = {str(row.get("question_id")) for row in responses}
    required_question_ids = {str(row.get("question_id")) for row in questions if row.get("required", True)}
    single_video_submitted = bool(responses) if response_mode == "single_video" else False
    missing_required = [] if single_video_submitted else sorted(required_question_ids - response_question_ids)
    return {
        "ok": True,
        "interview": {
            "interview_id": str(interview.get("interview_id") or ""),
            "status": interview.get("status"),
            "async_status": interview.get("async_status") or "pending",
            "response_mode": response_mode,
            "candidate_name": interview.get("candidate_name"),
            "position_title": interview.get("position_title") or interview.get("position_code"),
            "question_count": len(questions),
            "response_count": len(responses),
            "consent_required": not bool(interview.get("consent_accepted_at")),
            "consent_accepted_at": json_safe(interview.get("consent_accepted_at")),
            "completed_at": json_safe(interview.get("completed_at")),
            "retake_policy": (interview.get("async_video_config") or {}).get("retake_policy") if isinstance(interview.get("async_video_config"), dict) else {},
            "privacy_notice": "Your video answers are recorded for OctoHR screening review. AI may summarize your answers, but HR remains the decision-maker.",
        },
        "questions": [public_video_question_payload(row) for row in questions],
        "responses": [public_video_response_payload(row) for row in responses],
        "missing_required_question_ids": missing_required,
        "completed": (interview.get("async_status") == "completed" or interview.get("status") == "completed"),
    }


def candidate_video_actor_context(interview: dict[str, Any]) -> dict[str, Any]:
    phone = digits(interview.get("phone"))
    return {
        "company_code": str(interview.get("company_code") or "").upper(),
        "actor_user_id": phone or str(interview.get("app_key") or ""),
        "actor_phone": phone,
        "actor_role": "candidate",
    }


def fetch_public_async_video_interview(interview_id: str, token: str | None, *, start: bool = False) -> dict[str, Any]:
    if not link_signing_available("video_interview"):
        raise link_signing_unavailable_error("video_interview")
    if not verify_video_interview_token(interview_id, token):
        raise HTTPException(status_code=403, detail={"error": "invalid_or_expired_video_interview_link"})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM candidate_interviews WHERE interview_id=%s LIMIT 1", (interview_id,))
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail={"error": "video_interview_not_found"})
            interview = dict(row)
            if str(interview.get("interview_type") or "") != "async_video" and str(interview.get("source") or "") != "async_video":
                raise HTTPException(status_code=404, detail={"error": "video_interview_not_found"})
            if not company_has_module(interview.get("company_code"), "video_interviews"):
                raise HTTPException(
                    status_code=403,
                    detail={
                        "error": "module_disabled",
                        "message": "This link is no longer available. Please contact the hiring team if you need a new link.",
                    },
                )
            expires_at = parse_datetime_or_none(interview.get("public_link_expires_at"))
            if expires_at and expires_at < now_utc():
                raise HTTPException(status_code=403, detail={"error": "video_interview_link_expired"})
            if interview.get("status") == "cancelled":
                raise HTTPException(status_code=410, detail={"error": "video_interview_cancelled"})
            if start and str(interview.get("async_status") or "pending") in {"pending", "link_sent"}:
                cur.execute(
                    """
                    UPDATE candidate_interviews
                    SET async_status='opened', updated_at=now()
                    WHERE interview_id=%s
                    RETURNING *
                    """,
                    (interview_id,),
                )
                interview = dict(cur.fetchone() or interview)
                conn.commit()
    if start and str(row.get("async_status") or "pending") in {"pending", "link_sent"}:
        record_interview_event(
            str(interview.get("interview_id") or ""),
            str(interview.get("company_code") or ""),
            str(interview.get("app_key") or ""),
            "video_link_opened",
            {"source": "public_video_interview"},
            created_by_phone=digits(interview.get("phone")),
            actor_context=candidate_video_actor_context(interview),
            action="video_interview_opened",
            target_type="interview",
            target=str(interview.get("interview_id") or ""),
        )
    return interview


def video_file_extension(filename: str | None, mime_type: str | None) -> str:
    suffix = Path(str(filename or "")).suffix.lower()
    if suffix and re.fullmatch(r"\.[a-z0-9]{2,8}", suffix):
        return suffix
    guessed = mimetypes.guess_extension(str(mime_type or "").split(";")[0].strip())
    return guessed if guessed in {".mp4", ".webm", ".mov", ".m4v", ".ogg"} else ".webm"


def decode_video_payload(video_base64: str | None) -> bytes | None:
    if not video_base64:
        return None
    raw = str(video_base64).strip()
    if "," in raw and raw.lower().startswith("data:"):
        raw = raw.split(",", 1)[1]
    try:
        data = base64.b64decode(raw, validate=True)
    except Exception:
        raise HTTPException(status_code=422, detail={"error": "invalid_video_payload"})
    max_bytes = int(os.environ.get("WATHEFNI_VIDEO_INTERVIEW_MAX_UPLOAD_BYTES", "75000000") or "75000000")
    if len(data) > max_bytes:
        raise HTTPException(status_code=413, detail={"error": "video_payload_too_large", "max_bytes": max_bytes})
    return data


def enforce_video_payload_size(video_bytes: bytes | None) -> None:
    if not video_bytes:
        return
    max_bytes = int(os.environ.get("WATHEFNI_VIDEO_INTERVIEW_MAX_UPLOAD_BYTES", "75000000") or "75000000")
    if len(video_bytes) > max_bytes:
        raise HTTPException(status_code=413, detail={"error": "video_payload_too_large", "max_bytes": max_bytes})


def parse_video_interview_multipart(content_type: str, body: bytes) -> tuple[dict[str, Any], bytes | None]:
    raw = f"Content-Type: {content_type}\r\nMIME-Version: 1.0\r\n\r\n".encode("utf-8") + body
    message = BytesParser(policy=policy.default).parsebytes(raw)
    if not message.is_multipart():
        raise HTTPException(status_code=422, detail={"error": "invalid_video_upload"})
    fields: dict[str, Any] = {}
    video_bytes: bytes | None = None
    for part in message.iter_parts():
        disposition = part.get("Content-Disposition", "")
        name = part.get_param("name", header="content-disposition")
        if not name:
            continue
        filename = part.get_filename()
        payload = part.get_payload(decode=True) or b""
        if filename or name in {"video", "file", "answer_video"}:
            video_bytes = payload
            fields["video_filename"] = filename or fields.get("video_filename") or "video-answer.webm"
            fields["mime_type"] = part.get_content_type() or fields.get("mime_type") or "video/webm"
            continue
        text = payload.decode(part.get_content_charset() or "utf-8", errors="replace")
        fields[name] = text
        if "filename=" in disposition and not fields.get("video_filename"):
            fields["video_filename"] = filename
    enforce_video_payload_size(video_bytes)
    if isinstance(fields.get("metadata"), str) and str(fields["metadata"]).strip():
        try:
            fields["metadata"] = json.loads(str(fields["metadata"]))
        except Exception:
            fields["metadata"] = {}
    if isinstance(fields.get("duration_seconds"), str) and str(fields["duration_seconds"]).strip():
        try:
            fields["duration_seconds"] = int(float(str(fields["duration_seconds"])))
        except Exception:
            fields["duration_seconds"] = None
    return fields, video_bytes


async def parse_public_video_interview_response_request(request: Request) -> tuple[PublicVideoInterviewResponse, bytes | None]:
    content_type = str(request.headers.get("content-type") or "")
    if "multipart/form-data" in content_type.lower():
        fields, video_bytes = parse_video_interview_multipart(content_type, await request.body())
        return PublicVideoInterviewResponse(**fields), video_bytes
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    response = PublicVideoInterviewResponse(**(payload if isinstance(payload, dict) else {}))
    return response, decode_video_payload(response.video_base64)


def store_video_interview_file(
    *,
    interview: dict[str, Any],
    question: dict[str, Any],
    video_bytes: bytes,
    filename: str | None,
    mime_type: str | None,
) -> dict[str, Any]:
    company = str(interview.get("company_code") or "").strip().upper()
    if not company:
        return {"ok": False, "error": "tenant_scope_required"}
    interview_id = str(interview.get("interview_id") or "")
    question_id = str(question.get("question_id") or "")
    extension = video_file_extension(filename, mime_type)
    object_key = f"video-interviews/{interview_id}/{question_id}-{uuid.uuid4().hex}{extension}"
    path = company_root(company) / object_key
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(video_bytes)
    checksum = hashlib.sha256(video_bytes).hexdigest()
    size = len(video_bytes)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO file_registry (
                  company_code, owner_phone, subject_type, subject_key, file_kind, document_type,
                  original_filename, local_path, storage_provider, storage_object_key, content_sha256,
                  mime_type, size_bytes, storage_status, metadata, stored_at
                )
                VALUES (%s,%s,'candidate_interview',%s,'video_interview_response','video_interview_response',
                        %s,%s,'local',%s,%s,%s,%s,'stored',%s,now())
                RETURNING file_id
                """,
                (
                    company,
                    digits(interview.get("phone")),
                    interview_id,
                    filename or f"video-answer{extension}",
                    str(path),
                    object_key,
                    checksum,
                    mime_type or mimetypes.guess_type(str(path))[0] or "video/webm",
                    size,
                    Json({"question_id": question_id, "app_key": interview.get("app_key"), "source": "async_video_interview"}),
                ),
            )
            row = dict(cur.fetchone() or {})
        conn.commit()
    return {
        "file_id": str(row.get("file_id") or ""),
        "local_path": str(path),
        "storage_provider": "local",
        "storage_object_key": object_key,
        "mime_type": mime_type or mimetypes.guess_type(str(path))[0] or "video/webm",
        "size_bytes": size,
        "content_sha256": checksum,
        "original_filename": filename or f"video-answer{extension}",
    }


def complete_async_video_interview(interview: dict[str, Any]) -> dict[str, Any]:
    interview_id = str(interview.get("interview_id") or "")
    questions = async_video_interview_questions(interview_id)
    responses = async_video_interview_responses(interview_id)
    response_mode = video_interview_response_mode(interview)
    by_question = {str(row.get("question_id")): row for row in responses}
    if response_mode == "single_video":
        missing_required = [] if responses else [str(row.get("question_id")) for row in questions if row.get("required", True)]
    else:
        missing_required = [str(row.get("question_id")) for row in questions if row.get("required", True) and str(row.get("question_id")) not in by_question]
    if missing_required:
        raise HTTPException(status_code=422, detail={"error": "required_video_answers_missing", "question_ids": missing_required})
    transcript_lines: list[str] = []
    if response_mode == "single_video":
        response = responses[0] if responses else {}
        answer = str(response.get("transcript_text") or response.get("response_text") or "").strip()
        if not answer and (response.get("video_file_id") or response.get("local_path")):
            answer = "One video answer submitted. Transcript pending."
        question_list = "\n".join(f"{index}. {question.get('prompt_text')}" for index, question in enumerate(questions, start=1))
        transcript_lines.append(f"Questions:\n{question_list}\n\nCandidate video answer:\n{answer or 'No answer text available yet.'}")
    else:
        for question in questions:
            response = by_question.get(str(question.get("question_id"))) or {}
            answer = str(response.get("transcript_text") or response.get("response_text") or "").strip()
            if not answer and (response.get("video_file_id") or response.get("local_path")):
                answer = "Video answer submitted. Transcript pending."
            transcript_lines.append(f"Q: {question.get('prompt_text')}\nA: {answer or 'No answer text available yet.'}")
    transcript = "\n\n".join(transcript_lines).strip()
    summary = deterministic_interview_summary("Async video interview completed.", transcript)
    summary.update(
        {
            "summary": "Async video interview completed. HR should review the video answers and transcript evidence.",
            "communication_notes": ["Candidate submitted asynchronous recorded answers."],
            "role_fit_evidence": ["Video interview completed and linked to this application."],
            "missing_evidence": ["AI transcription/evaluation pipeline may still need to enrich this summary."],
            "follow_up_questions": summary.get("follow_up_questions") or [],
            "follow_up_points": summary.get("follow_up_points") or [],
            "recommended_next_step": "Review the completed video interview before deciding the next hiring step.",
            "recommendation": "Review the completed video interview before deciding the next hiring step.",
            "source": "async_video_stage1_structured_summary",
        }
    )
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_interviews
                SET status='completed',
                    async_status='completed',
                    transcript=%s,
                    ai_summary=%s,
                    completed_at=COALESCE(completed_at, now()),
                    updated_at=now()
                WHERE interview_id=%s
                RETURNING *
                """,
                (transcript, Json(json_safe(summary)), interview_id),
            )
            row = dict(cur.fetchone() or {})
        conn.commit()
    if row:
        record_interview_event(
            interview_id,
            str(row.get("company_code") or ""),
            str(row.get("app_key") or ""),
            "video_completed",
            {"response_count": len(responses), "question_count": len(questions), "response_mode": response_mode},
            created_by_phone=digits(row.get("phone")),
            actor_context=candidate_video_actor_context(row),
            action="video_interview_completed",
            target_type="interview",
            target=interview_id,
        )
        update_application_interview_snapshot(str(row.get("app_key") or ""), row)
    return row


def video_transcription_provider_config() -> dict[str, str] | None:
    env_values = planner_env()
    cfg = openclaw_config()
    providers = ((cfg.get("models") or {}).get("providers") or {}) if isinstance(cfg, dict) else {}
    openai_provider = providers.get("openai") or providers.get("openai-sse") or {}
    api_key = (
        env_values.get("WATHEFNI_TRANSCRIPTION_API_KEY")
        or env_values.get("OPENAI_API_KEY")
        or env_values.get("WATHEFNI_TOOL_AGENT_API_KEY")
        or env_values.get("WATHEFNI_PLANNER_API_KEY")
        or openai_provider.get("apiKey")
    )
    if not api_key:
        return None
    base_url = env_values.get("WATHEFNI_TRANSCRIPTION_BASE_URL") or "https://api.openai.com/v1"
    model = env_values.get("WATHEFNI_TRANSCRIPTION_MODEL") or "gpt-4o-transcribe"
    return {"api_key": api_key, "url": f"{base_url.rstrip('/')}/audio/transcriptions", "model": model, "provider": "openai"}


def extract_video_audio(video_path: Path) -> Path:
    if not video_path.exists() or not video_path.is_file():
        raise FileNotFoundError(f"video file unavailable: {video_path}")
    tmp = tempfile.NamedTemporaryFile(prefix="wathefni-video-audio-", suffix=".mp3", delete=False)
    tmp_path = Path(tmp.name)
    tmp.close()
    command = [
        os.environ.get("WATHEFNI_FFMPEG_BIN", "ffmpeg"),
        "-y",
        "-i",
        str(video_path),
        "-vn",
        "-ac",
        "1",
        "-ar",
        "16000",
        "-b:a",
        "64k",
        str(tmp_path),
    ]
    proc = subprocess.run(command, text=True, capture_output=True, timeout=180)
    if proc.returncode != 0 or not tmp_path.exists() or tmp_path.stat().st_size == 0:
        try:
            tmp_path.unlink()
        except FileNotFoundError:
            pass
        raise RuntimeError((proc.stderr or proc.stdout or "audio extraction failed")[-1200:])
    return tmp_path


def multipart_form_body(fields: dict[str, str], files: list[dict[str, Any]]) -> tuple[str, bytes]:
    boundary = f"----wathefni-{uuid.uuid4().hex}"
    chunks: list[bytes] = []
    for key, value in fields.items():
        chunks.append(f"--{boundary}\r\n".encode("utf-8"))
        chunks.append(f'Content-Disposition: form-data; name="{key}"\r\n\r\n'.encode("utf-8"))
        chunks.append(str(value).encode("utf-8"))
        chunks.append(b"\r\n")
    for file_item in files:
        filename = str(file_item.get("filename") or "audio.mp3")
        content_type = str(file_item.get("content_type") or "audio/mpeg")
        payload = file_item.get("content") if isinstance(file_item.get("content"), bytes) else b""
        field_name = str(file_item.get("field_name") or "file")
        chunks.append(f"--{boundary}\r\n".encode("utf-8"))
        chunks.append(
            f'Content-Disposition: form-data; name="{field_name}"; filename="{filename}"\r\n'
            f"Content-Type: {content_type}\r\n\r\n"
            .encode("utf-8")
        )
        chunks.append(payload)
        chunks.append(b"\r\n")
    chunks.append(f"--{boundary}--\r\n".encode("utf-8"))
    return f"multipart/form-data; boundary={boundary}", b"".join(chunks)


def transcribe_audio_file(audio_path: Path, *, response_id: str, interview_id: str) -> dict[str, Any]:
    provider = video_transcription_provider_config()
    if not provider:
        raise RuntimeError("transcription_provider_unavailable")
    content_type, body = multipart_form_body(
        {
            "model": provider["model"],
            "response_format": "json",
        },
        [{"field_name": "file", "filename": audio_path.name, "content_type": "audio/mpeg", "content": audio_path.read_bytes()}],
    )
    req = urllib.request.Request(
        provider["url"],
        data=body,
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": content_type},
        method="POST",
    )
    start = time_module.monotonic()
    try:
        with urllib.request.urlopen(req, timeout=240) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except urllib.error.HTTPError as exc:
        body_text = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(body_text[-1200:]) from exc
    record_llm_call(
        call_name="video_interview_transcription",
        provider={k: v for k, v in provider.items() if k != "api_key"},
        prompt_mode="audio_transcription",
        prompt_docs_loaded=False,
        prompt_hash=stable_text_hash("gpt-4o-transcribe"),
        estimated_input_tokens=None,
        latency_ms=int((time_module.monotonic() - start) * 1000),
        status="ok",
        parsed=parsed,
        metadata={"response_id": response_id, "interview_id": interview_id},
    )
    text = str(parsed.get("text") or "").strip()
    if not text:
        raise RuntimeError("empty_transcript")
    return {
        "text": text,
        "model": provider["model"],
        "language": parsed.get("language"),
        "metadata": {key: value for key, value in parsed.items() if key not in {"text"}},
    }


def pending_video_transcript_responses(limit: int = 5, *, include_failed: bool = False) -> list[dict[str, Any]]:
    statuses = ["pending", "processing"]
    if include_failed:
        statuses.append("failed")
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT r.*, q.prompt_text, q.required, q.competency,
                       ci.candidate_name, ci.position_code, ci.position_title, ci.status AS interview_status
                FROM candidate_video_interview_responses r
                JOIN candidate_video_interview_questions q ON q.question_id=r.question_id
                JOIN candidate_interviews ci ON ci.interview_id=r.interview_id
                WHERE ci.interview_type='async_video'
                  AND (ci.status='completed' OR ci.async_status='completed')
                  AND r.video_file_id IS NOT NULL
                  AND COALESCE(r.transcript_status, 'pending') = ANY(%s)
                  AND COALESCE(r.local_path, '') <> ''
                ORDER BY r.submitted_at ASC
                LIMIT %s
                """,
                (statuses, max(1, min(int(limit or 5), 25))),
            )
            return [dict(row) for row in cur.fetchall()]


def mark_video_response_transcript_status(response_id: str, status: str, *, error: str | None = None) -> None:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_video_interview_responses
                SET transcript_status=%s,
                    transcript_error=%s,
                    updated_at=now()
                WHERE response_id=%s
                """,
                (status, error[:1000] if error else None, response_id),
            )
        conn.commit()


def save_video_response_transcript(response: dict[str, Any], transcript: dict[str, Any]) -> None:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_video_interview_responses
                SET transcript_status='completed',
                    transcript_text=%s,
                    transcript_model=%s,
                    transcript_language=%s,
                    transcript_metadata=%s,
                    transcript_error=NULL,
                    transcribed_at=now(),
                    updated_at=now()
                WHERE response_id=%s
                """,
                (
                    transcript.get("text"),
                    transcript.get("model"),
                    transcript.get("language"),
                    Json(json_safe(transcript.get("metadata") or {})),
                    str(response.get("response_id")),
                ),
            )
        conn.commit()


def process_video_response_transcript(response: dict[str, Any]) -> dict[str, Any]:
    response_id = str(response.get("response_id") or "")
    interview_id = str(response.get("interview_id") or "")
    path = Path(str(response.get("local_path") or ""))
    audio_path: Path | None = None
    mark_video_response_transcript_status(response_id, "processing")
    try:
        audio_path = extract_video_audio(path)
        transcript = transcribe_audio_file(audio_path, response_id=response_id, interview_id=interview_id)
        save_video_response_transcript(response, transcript)
        record_interview_event(
            interview_id,
            str(response.get("company_code") or ""),
            str(response.get("app_key") or ""),
            "video_transcript_completed",
            {"response_id": response_id, "question_id": str(response.get("question_id") or ""), "model": transcript.get("model")},
            actor_context={
                "company_code": str(response.get("company_code") or ""),
                "actor_user_id": "system:video-interview-worker",
                "actor_phone": None,
                "actor_role": "system_worker",
            },
            action="video_interview_transcribed",
            target_type="response",
            target=response_id,
        )
        maybe_generate_async_video_interview_summary(interview_id)
        return {"ok": True, "response_id": response_id, "interview_id": interview_id, "status": "completed"}
    except Exception as exc:
        error = str(exc)[:1000]
        mark_video_response_transcript_status(response_id, "failed", error=error)
        record_interview_event(
            interview_id,
            str(response.get("company_code") or ""),
            str(response.get("app_key") or ""),
            "video_transcript_failed",
            {"response_id": response_id, "question_id": str(response.get("question_id") or ""), "error": error},
            actor_context={
                "company_code": str(response.get("company_code") or ""),
                "actor_user_id": "system:video-interview-worker",
                "actor_phone": None,
                "actor_role": "system_worker",
            },
            action="video_interview_transcription_failed",
            target_type="response",
            target=response_id,
        )
        return {"ok": False, "response_id": response_id, "interview_id": interview_id, "status": "failed", "error": error}
    finally:
        if audio_path:
            try:
                audio_path.unlink()
            except FileNotFoundError:
                pass


def async_video_interview_transcript_readiness(interview_id: str) -> dict[str, Any]:
    questions = async_video_interview_questions(interview_id)
    responses = async_video_interview_responses(interview_id)
    interview: dict[str, Any] = {}
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT async_video_config FROM candidate_interviews WHERE interview_id=%s LIMIT 1", (interview_id,))
            interview = dict(cur.fetchone() or {})
    if video_interview_response_mode(interview) == "single_video":
        response = responses[0] if responses else {}
        status = str(response.get("transcript_status") or "pending")
        missing = [] if response else [str(row.get("question_id")) for row in questions if row.get("required", True)]
        completed = [str(response.get("response_id") or "")] if status == "completed" and str(response.get("transcript_text") or "").strip() else []
        failed = [str(response.get("response_id") or "")] if response and status == "failed" else []
        pending = [str(response.get("response_id") or "")] if response and not completed and not failed else []
        return {
            "ready": bool(response) and not pending and not failed and bool(completed),
            "missing_question_ids": missing,
            "pending_response_ids": pending,
            "failed_response_ids": failed,
            "completed_response_ids": completed,
            "required_count": 1,
            "response_mode": "single_video",
            "question_count": len([row for row in questions if row.get("required", True)]),
        }
    by_question = {str(row.get("question_id")): row for row in responses}
    required = [row for row in questions if row.get("required", True)]
    missing = [str(row.get("question_id")) for row in required if str(row.get("question_id")) not in by_question]
    pending = []
    failed = []
    completed = []
    for question in required:
        response = by_question.get(str(question.get("question_id"))) or {}
        status = str(response.get("transcript_status") or "pending")
        if status == "completed" and str(response.get("transcript_text") or "").strip():
            completed.append(str(response.get("response_id") or ""))
        elif status == "failed":
            failed.append(str(response.get("response_id") or ""))
        else:
            pending.append(str(response.get("response_id") or response.get("question_id") or ""))
    return {
        "ready": bool(required) and not missing and not pending and not failed,
        "missing_question_ids": missing,
        "pending_response_ids": pending,
        "failed_response_ids": failed,
        "completed_response_ids": completed,
        "required_count": len(required),
        "response_mode": "per_question_video",
        "question_count": len(required),
    }


def async_video_interview_review_status(
    interview: dict[str, Any],
    *,
    readiness: dict[str, Any] | None = None,
    responses: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    status = str(interview.get("status") or "").strip().lower()
    async_status = str(interview.get("async_status") or "").strip().lower()
    ai_summary = interview.get("ai_summary") if isinstance(interview.get("ai_summary"), dict) else {}
    readiness = readiness if isinstance(readiness, dict) else async_video_interview_transcript_readiness(str(interview.get("interview_id") or ""))
    responses = responses if isinstance(responses, list) else async_video_interview_responses(str(interview.get("interview_id") or ""))
    response_count = len(responses)
    required_count = int(readiness.get("required_count") or 0)
    failed_count = len(readiness.get("failed_response_ids") or [])
    pending_count = len(readiness.get("pending_response_ids") or [])
    missing_count = len(readiness.get("missing_question_ids") or [])
    summary_ready = bool(str(ai_summary.get("summary") or ai_summary.get("overall_summary") or "").strip())
    completed = status == "completed" or async_status == "completed" or bool(interview.get("completed_at"))
    consented = bool(interview.get("consent_accepted_at"))
    if status == "cancelled":
        state = "cancelled"
        label = "Cancelled"
        description = "This video interview is no longer active."
        tone = "muted"
    elif completed and failed_count:
        state = "transcription_failed"
        label = "Needs retry"
        description = "One or more answers could not be transcribed. HR can still review the original videos."
        tone = "danger"
    elif completed and (pending_count or missing_count):
        state = "processing"
        label = "Processing"
        description = "Video answers were submitted. Transcripts and AI summary are processing in the background."
        tone = "warning"
    elif completed and readiness.get("ready") and summary_ready:
        state = "ready_for_review"
        label = "Ready for review"
        description = "Video answers, transcripts, and AI summary are ready for HR review."
        tone = "success"
    elif completed and readiness.get("ready"):
        state = "summary_pending"
        label = "Summary pending"
        description = "Transcripts are ready. AI summary is being prepared."
        tone = "warning"
    elif response_count:
        state = "submitted"
        label = "Submitted"
        description = "The candidate submitted video answers. Completion is being finalized."
        tone = "warning"
    elif consented or async_status == "in_progress":
        state = "started"
        label = "Started"
        description = "The candidate opened the link and accepted the recording notice."
        tone = "warning"
    else:
        state = "link_sent" if async_status in {"link_sent", "pending", ""} else async_status
        label = "Link sent"
        description = "The video interview link has been sent. Waiting for the candidate to submit answers."
        tone = "default"
    return {
        "state": state,
        "label": label,
        "description": description,
        "tone": tone,
        "response_count": response_count,
        "required_count": required_count,
        "failed_count": failed_count,
        "pending_count": pending_count,
        "missing_count": missing_count,
        "summary_ready": summary_ready,
    }


def sanitize_async_video_summary(value: Any) -> dict[str, Any]:
    data = value if isinstance(value, dict) else {}
    overall = str(data.get("overall_summary") or data.get("summary") or "").strip()[:1200]
    next_step = str(data.get("recommended_next_step") or "Review the transcript and original video answers before deciding the next step.").strip()[:400]
    def list_value(*keys: str) -> list[str]:
        for key in keys:
            items = data.get(key)
            if isinstance(items, list):
                cleaned = [str(item).strip()[:500] for item in items if str(item).strip()]
                if cleaned:
                    return cleaned[:8]
        return []
    return {
        "overall_summary": overall or "Video interview transcripts are ready for HR review.",
        "summary": overall or "Video interview transcripts are ready for HR review.",
        "communication_notes": list_value("communication_notes"),
        "role_fit_evidence": list_value("role_fit_evidence"),
        "strengths": list_value("strengths"),
        "gaps_or_risks": list_value("gaps_or_risks", "concerns", "risks"),
        "concerns": list_value("gaps_or_risks", "concerns", "risks"),
        "missing_evidence": list_value("missing_evidence"),
        "suggested_follow_up_questions": list_value("suggested_follow_up_questions", "follow_up_questions", "follow_up_points"),
        "follow_up_questions": list_value("suggested_follow_up_questions", "follow_up_questions", "follow_up_points"),
        "follow_up_points": list_value("suggested_follow_up_questions", "follow_up_questions", "follow_up_points"),
        "recommended_next_step": next_step,
        "recommendation": next_step,
        "hr_decision_maker_note": "This AI summary is decision support only. HR remains the decision-maker.",
        "decision_policy": "AI summary is decision support only. HR remains the decision-maker.",
        "source": "async_video_transcript_summary",
    }


def generate_async_video_interview_summary(interview: dict[str, Any], responses: list[dict[str, Any]], application: dict[str, Any] | None) -> dict[str, Any]:
    provider = planner_provider_config()
    response_mode = video_interview_response_mode(interview)
    questions = async_video_interview_questions(str(interview.get("interview_id") or ""))
    if response_mode == "single_video":
        response = responses[0] if responses else {}
        evidence = [
            {
                "response_mode": "single_video",
                "instructions": "Candidate was asked to answer all listed questions in one video.",
                "questions": [public_video_question_payload(item) for item in questions],
                "transcript": response.get("transcript_text"),
                "transcript_note": "Transcript is AI-generated evidence and may contain errors. Original video remains source evidence.",
            }
        ]
    else:
        evidence = [
            {
                "response_mode": "per_question_video",
                "question": item.get("prompt_text"),
                "competency": item.get("competency"),
                "transcript": item.get("transcript_text"),
                "transcript_note": "Transcript is AI-generated evidence and may contain errors. Original video remains source evidence.",
            }
            for item in responses
        ]
    fallback = sanitize_async_video_summary(
        {
            "overall_summary": "The candidate completed the async video interview. Transcripts are ready for HR review.",
            "communication_notes": ["Review the candidate's recorded video alongside the transcript."],
            "role_fit_evidence": ["The video interview questions were answered and transcribed."],
            "missing_evidence": ["AI summary should be verified against the original video evidence."],
            "recommended_next_step": "Review the video answers, transcripts, and application profile before deciding the next step.",
        }
    )
    if not provider:
        return fallback
    system = (
        "You summarize asynchronous video interview transcripts for OctoHR. Return JSON only. "
        "Use only provided evidence. Transcripts may contain errors; note where HR should verify original video. "
        "Do not make or imply a final hiring decision."
    )
    payload = {
        "candidate": {
            "name": interview.get("candidate_name"),
            "position": interview.get("position_title") or interview.get("position_code"),
            "application_status": (application or {}).get("status") if isinstance(application, dict) else None,
        },
        "video_interview": evidence,
        "response_mode": response_mode,
        "required_output": {
            "overall_summary": "short HR-friendly summary",
            "communication_notes": ["communication observations grounded in transcript"],
            "role_fit_evidence": ["evidence related to the role"],
            "strengths": ["specific strengths"],
            "gaps_or_risks": ["risks or weak evidence HR should verify"],
            "missing_evidence": ["evidence not shown in the video answers"],
            "suggested_follow_up_questions": ["questions HR can ask next"],
            "recommended_next_step": "review-oriented next step, not a hiring decision",
            "hr_decision_maker_note": "explicit note that HR remains the decision-maker",
        },
        "rules": [
            "Do not invent facts beyond transcripts.",
            "Do not score the candidate.",
            "Do not make a final hiring decision.",
            "Original video remains source evidence; transcript is support.",
        ],
    }
    if provider.get("api") == "openai-responses":
        body = {
            "model": provider["model"],
            "temperature": 0.2,
            "input": [{"role": "system", "content": system}, {"role": "user", "content": json.dumps(payload, ensure_ascii=False)}],
        }
    else:
        body = {
            "model": os.environ.get("WATHEFNI_VIDEO_INTERVIEW_SUMMARY_MODEL") or provider["model"],
            "temperature": 0.2,
            "response_format": {"type": "json_object"},
            "messages": [{"role": "system", "content": system}, {"role": "user", "content": json.dumps(payload, ensure_ascii=False)}],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    start = time_module.monotonic()
    try:
        with urllib.request.urlopen(req, timeout=45) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception as exc:
        return {**fallback, "summary_error": str(exc)[:300]}
    record_llm_call(
        call_name="async_video_interview_summary",
        provider=provider,
        prompt_mode="async_video_interview",
        prompt_docs_loaded=False,
        prompt_hash=stable_text_hash(system),
        estimated_input_tokens=estimate_tokens_from_payload(body),
        latency_ms=int((time_module.monotonic() - start) * 1000),
        status="ok",
        parsed=parsed,
        metadata={"interview_id": str(interview.get("interview_id") or ""), "app_key": interview.get("app_key")},
    )
    return sanitize_async_video_summary(extract_json_object(extract_model_text(parsed)))


def maybe_generate_async_video_interview_summary(interview_id: str) -> dict[str, Any]:
    readiness = async_video_interview_transcript_readiness(interview_id)
    if not readiness.get("ready"):
        return {"ok": False, "status": "not_ready", "readiness": readiness}
    interview = fetch_candidate_interview(interview_id, "")
    if not interview:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT * FROM candidate_interviews WHERE interview_id=%s LIMIT 1", (interview_id,))
                row = cur.fetchone()
                interview = dict(row) if row else None
    if not interview:
        return {"ok": False, "status": "interview_not_found"}
    if str(interview.get("status") or "") != "completed" and str(interview.get("async_status") or "") != "completed":
        return {"ok": False, "status": "interview_not_completed", "readiness": readiness}
    responses = async_video_interview_responses(interview_id)
    application = find_application_by_key(str(interview.get("app_key") or ""), company_code=str(interview.get("company_code") or ""))
    summary = generate_async_video_interview_summary(interview, responses, application)
    transcript = "\n\n".join(
        [
            "Questions:\n"
            + "\n".join(f"{index}. {question.get('prompt_text')}" for index, question in enumerate(async_video_interview_questions(interview_id), start=1))
            + "\n\nCandidate video answer:\n"
            + str((responses[0] if responses else {}).get("transcript_text") or "Transcript unavailable.")
        ]
        if video_interview_response_mode(interview) == "single_video"
        else [
            f"Q: {item.get('prompt_text')}\nA: {item.get('transcript_text') or 'Transcript unavailable.'}"
            for item in responses
        ]
    )
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_interviews
                SET ai_summary=%s,
                    transcript=%s,
                    updated_at=now()
                WHERE interview_id=%s
                RETURNING *
                """,
                (Json(json_safe(summary)), transcript, interview_id),
            )
            row = dict(cur.fetchone() or {})
        conn.commit()
    if row:
        record_interview_event(
            interview_id,
            str(row.get("company_code") or ""),
            str(row.get("app_key") or ""),
            "video_ai_summary_completed",
            {"response_count": len(responses), "summary_source": summary.get("source")},
            actor_context={
                "company_code": str(row.get("company_code") or ""),
                "actor_user_id": "system:video-interview-worker",
                "actor_phone": None,
                "actor_role": "system_worker",
            },
            action="video_interview_summary_generated",
            target_type="interview",
            target=interview_id,
        )
        update_application_interview_snapshot(str(row.get("app_key") or ""), row)
    return {"ok": True, "status": "summary_completed", "interview": candidate_interview_summary(row)}


def process_pending_video_interview_transcripts(limit: int = 5, *, include_failed: bool = False) -> dict[str, Any]:
    ensure_schema()
    try:
        import interview_service as _interview_service

        reclaimed = _interview_service.reclaim_stale_transcriptions()
    except Exception:
        reclaimed = {"ok": False, "count": 0, "reclaimed_response_ids": []}
    responses = pending_video_transcript_responses(limit, include_failed=include_failed)
    # Skip in-lease processing rows; stale processing was reclaimed above.
    results = []
    held = 0
    for response in responses:
        if str(response.get("transcript_status") or "pending") == "processing":
            continue
        try:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    import tenant_control_queue_gate as _tc_qg

                    company = str(response.get("company_code") or "").upper()
                    work_ref = str(response.get("response_id") or response.get("interview_id") or "")
                    queued_epoch = _tc_qg.load_work_epoch(
                        cur,
                        company_code=company,
                        work_kind="video_transcription",
                        work_ref=work_ref,
                    )
                    if queued_epoch is None:
                        queued_epoch = _tc_qg.persist_work_epoch(
                            cur,
                            company_code=company,
                            work_kind="video_transcription",
                            work_ref=work_ref,
                            module_key="video_interviews",
                        )
                    allowed, decision = _tc_qg.gate_or_skip(
                        cur,
                        company_code=company,
                        module_key="video_interviews",
                        work_kind="video_transcription",
                        work_ref=work_ref,
                        queued_epoch=int(queued_epoch),
                    )
                    conn.commit()
                    if not allowed:
                        held += 1
                        results.append({
                            "ok": False,
                            "held": True,
                            "reason": decision.reason_code,
                            "correlation_id": decision.audit_correlation_id,
                            "response_id": work_ref,
                        })
                        continue
        except Exception:
            pass
        results.append(process_video_response_transcript(response))
    return {
        "ok": all(item.get("ok") for item in results) if results else True,
        "count": len(results),
        "held": held,
        "results": json_safe(results),
        "reclaimed": json_safe(reclaimed),
    }


def create_or_resume_async_video_interview(
    application: dict[str, Any],
    request: DashboardVideoInterviewRequest,
    *,
    actor_context: dict[str, Any],
) -> dict[str, Any]:
    company = str(application.get("company_code") or "").strip().upper()
    if not company:
        raise HTTPException(status_code=422, detail={"error": "tenant_scope_required"})
    # Defence in depth: every caller is already entitled, but the module owns its
    # own writes so a new caller cannot create interviews for a disabled tenant.
    if not company_has_module(company, "video_interviews"):
        raise HTTPException(
            status_code=403,
            detail={
                "error": "module_disabled",
                "required_module": "video_interviews",
                "message": "This module is not enabled for this company.",
            },
        )
    app_key = str(application.get("app_key") or "").strip()
    contact = candidate_contact(application)
    if not app_key:
        raise HTTPException(status_code=422, detail={"error": "missing_application_key"})
    ttl_days = max(1, min(int(request.link_ttl_days or 14), 60))
    retake_policy = {"enabled": bool(request.retake_enabled), "max_retakes": max(0, min(int(request.max_retakes or 0), 5))}
    response_mode = str(request.response_mode or DEFAULT_VIDEO_INTERVIEW_RESPONSE_MODE).strip()
    if response_mode not in VIDEO_INTERVIEW_RESPONSE_MODES:
        response_mode = DEFAULT_VIDEO_INTERVIEW_RESPONSE_MODE
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM candidate_interviews
                WHERE company_code=%s
                  AND app_key=%s
                  AND interview_type='async_video'
                  AND COALESCE(async_status, '') NOT IN ('completed','cancelled')
                  AND status <> 'cancelled'
                ORDER BY updated_at DESC
                LIMIT 1
                """,
                (company, app_key),
            )
            existing = cur.fetchone()
            if existing:
                interview = dict(existing)
                link, expires_at = video_interview_public_link(str(interview["interview_id"]), ttl_days=ttl_days)
                cur.execute(
                    """
                    UPDATE candidate_interviews
                    SET public_link_expires_at=%s,
                        async_video_config=jsonb_set(
                          jsonb_set(COALESCE(async_video_config, '{}'::jsonb), '{retake_policy}', %s::jsonb, true),
                          '{response_mode}', %s::jsonb, true
                        ),
                        updated_by_phone=%s,
                        updated_at=now()
                    WHERE interview_id=%s
                    RETURNING *
                    """,
                    (expires_at, Json(retake_policy), Json(response_mode), actor_context.get("actor_phone"), str(interview["interview_id"])),
                )
                interview = dict(cur.fetchone() or interview)
                conn.commit()
                return {"interview": interview, "public_link": link, "resumed": True}
            link_seed = str(uuid.uuid4())
            link, expires_at = video_interview_public_link(link_seed, ttl_days=ttl_days)
            questions = normalize_video_interview_questions(application, request.questions)
            config = {
                "mode": "async_video",
                "response_mode": response_mode,
                "retake_policy": retake_policy,
                "question_source": "hr_custom" if request.questions else "standard_v1",
                "privacy_notice_version": "v1",
                "created_by": actor_context,
            }
            cur.execute(
                """
                INSERT INTO candidate_interviews (
                  interview_id, company_code, company_id, app_key, phone, candidate_name, candidate_email,
                  position_code, position_title, interview_type, status, feedback_status, async_status,
                  timezone, meeting_type, public_link_expires_at, async_video_config, source, created_by_phone, updated_by_phone
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,'async_video','scheduled','notes_pending','pending',
                        'Asia/Kuwait','async_video',%s,%s,'async_video',%s,%s)
                RETURNING *
                """,
                (
                    link_seed,
                    company,
                    company,
                    app_key,
                    contact.get("phone"),
                    contact.get("name"),
                    contact.get("email"),
                    application.get("position_code"),
                    application.get("position_title") or application.get("position_code"),
                    expires_at,
                    Json(json_safe(config)),
                    actor_context.get("actor_phone"),
                    actor_context.get("actor_phone"),
                ),
            )
            interview = dict(cur.fetchone())
            for question in questions:
                cur.execute(
                    """
                    INSERT INTO candidate_video_interview_questions (
                      interview_id, company_code, company_id, app_key, question_order, question_key,
                      prompt_text, competency, max_duration_seconds, required, raw_json
                    )
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    """,
                    (
                        str(interview["interview_id"]),
                        company,
                        company,
                        app_key,
                        question["question_order"],
                        question["question_key"],
                        question["prompt_text"],
                        question.get("competency"),
                        question["max_duration_seconds"],
                        question["required"],
                        Json(json_safe(question)),
                    ),
                )
        conn.commit()
    public_link, expires_at = video_interview_public_link(str(interview["interview_id"]), ttl_days=ttl_days)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_interviews
                SET public_link_expires_at=%s
                WHERE interview_id=%s
                RETURNING *
                """,
                (expires_at, str(interview["interview_id"])),
            )
            interview = dict(cur.fetchone() or interview)
        conn.commit()
    record_interview_event(
        str(interview["interview_id"]),
        company,
        app_key,
        "video_created",
        {"question_count": len(questions), "retake_policy": retake_policy, "response_mode": response_mode},
        created_by_phone=actor_context.get("actor_phone"),
        actor_context=actor_context,
        action="send_video_interview",
        target_type="application",
        target=app_key,
    )
    update_application_interview_snapshot(app_key, interview)
    return {"interview": interview, "public_link": public_link, "resumed": False}


def compose_async_video_interview_invite(application: dict[str, Any], interview: dict[str, Any], public_link: str, *, note: str | None = None) -> str:
    del note
    role = interview.get("position_title") or application.get("position_title") or application.get("position_code") or "the role"
    return candidate_message_payload(
        "interview_invitation",
        application=application,
        role=role,
        details="Complete the short video interview when you are ready.",
        link=public_link,
    )["text"]


def send_async_video_interview_invite(
    application: dict[str, Any],
    interview: dict[str, Any],
    public_link: str,
    *,
    account_id: str | None,
    preferred_channel: str | None = None,
    actor_context: dict[str, Any] | None = None,
    note: str | None = None,
) -> dict[str, Any]:
    try:
        assert_application_communication_allowed(application, kind="video_interview")  # HELD_COMMUNICATION_AUTHORITY_STAGING_PATCH
    except CandidateCommunicationAuthorityError as exc:
        return exc.as_result()
    subject = "Video Interview Invitation"
    body = compose_async_video_interview_invite(application, interview, public_link, note=note)
    action = {
        "purpose": "video_interview_invite",
        "message_text": body,
        "email_subject": subject,
        "preferred_channel": preferred_channel or "email",
        "interview_id": str(interview.get("interview_id") or ""),
        "send_both": preferred_channel == "whatsapp",
    }
    delivery = candidate_communication_router(
        application,
        account_id=account_id,
        kind="interview_invite",
        message=body,
        action=action,
    )
    update_interview_invite_delivery(str(interview["interview_id"]), delivery, subject=subject, body=body)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_interviews
                SET async_status=CASE WHEN %s THEN 'link_sent' ELSE COALESCE(async_status, 'pending') END,
                    updated_at=now()
                WHERE interview_id=%s
                RETURNING *
                """,
                (bool(delivery.get("ok")), str(interview["interview_id"])),
            )
            refreshed = dict(cur.fetchone() or interview)
        conn.commit()
    event_type = "video_invite_sent" if delivery.get("ok") else "video_invite_failed"
    record_interview_event(
        str(interview["interview_id"]),
        str(interview.get("company_code") or ""),
        str(application.get("app_key") or ""),
        event_type,
        {"delivery": json_safe(delivery), "subject": subject, "body": body, "public_link": public_link},
        created_by_phone=(actor_context or {}).get("actor_phone"),
        actor_context=actor_context,
        action="send_video_interview",
        target_type="application",
        target=str(application.get("app_key") or ""),
    )
    update_application_interview_snapshot(str(application.get("app_key") or ""), refreshed)
    return {
        "ok": bool(delivery.get("ok")),
        "interview": candidate_interview_summary(refreshed),
        "delivery": json_safe(delivery),
        "public_link": public_link,
        "sent_subject": subject,
        "sent_body": body,
    }


# Live interviewing (scheduling, panels, feedback, agenda, calendar sync) belongs to
# the `interviews` module; recorded-answer interviews belong to `video_interviews`.
# Both kinds share candidate_interviews and several dashboard surfaces, so a shared
# surface entitles against whichever module owns the specific record.
INTERVIEW_SURFACE_MODULES = ("interviews", "video_interviews")
ASYNC_VIDEO_INTERVIEW_MARKERS = frozenset({"async_video"})


def interview_record_module(interview: dict[str, Any] | None) -> str:
    row = interview if isinstance(interview, dict) else {}
    for field in ("interview_type", "source"):
        if str(row.get(field) or "").strip().lower() in ASYNC_VIDEO_INTERVIEW_MARKERS:
            return "video_interviews"
    return "interviews"


def enabled_interview_modules(company_code: str | None) -> dict[str, bool]:
    modules = configured_company_modules(company_code)
    return {key: key in modules for key in INTERVIEW_SURFACE_MODULES}


def require_interview_surface(context: dict[str, Any], permission: str) -> dict[str, bool]:
    """Entitle a surface that serves both interview kinds.

    Denies with module_disabled only when neither module is enabled. Callers must
    still narrow their rows to the kinds that remain enabled.
    """
    enabled = enabled_interview_modules(context.get("company_code"))
    gate = next((key for key in INTERVIEW_SURFACE_MODULES if enabled[key]), INTERVIEW_SURFACE_MODULES[0])
    require_entitlement(context, gate, permission)
    return enabled


def require_interview_record(context: dict[str, Any], interview_id: str, permission: str) -> dict[str, Any]:
    """Load a company-scoped interview and entitle against the module that owns it."""
    require_interview_surface(context, permission)
    interview = fetch_candidate_interview(interview_id, context["company_code"])
    if not interview:
        raise HTTPException(status_code=404, detail={"error": "interview_not_found"})
    require_entitlement(context, interview_record_module(interview), permission)
    require_interview_assignment_scope(
        context,
        company_code=str(context["company_code"]),
        interview_id=str(interview_id),
    )
    # Wave 2 ownership scope for recruiter/HM (Interviewer already gated above).
    app_key = str(interview.get("app_key") or "").strip()
    if app_key:
        application = find_application_by_key(app_key, company_code=context["company_code"])
        if application:
            require_prehire_application_visibility(context, application)
    return interview


def require_interview_feedback_submission(context: dict[str, Any], submission_id: str, permission: str) -> dict[str, Any]:
    """Same record-scoped gate, resolved through a feedback submission."""
    require_interview_surface(context, permission)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT interview_id FROM interview_feedback_submissions WHERE submission_id=%s AND company_code=%s LIMIT 1",
                (submission_id, context["company_code"]),
            )
            row = cur.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail={"error": "feedback_not_found"})
    return require_interview_record(context, str(row["interview_id"]), permission)


def dashboard_interviews_payload(
    company: str,
    *,
    include_live: bool = True,
    include_async_video: bool = True,
    status: str | None = None,
    q: str | None = None,
    role: str | None = None,
    date_filter: str | None = None,
    interviewer: str | None = None,
    limit: int = 100,
    offset: int = 0,
    permissions: set[str] | list[str] | None = None,
    context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    import interview_queue_contract as iqc

    assignment_sql, assignment_params = interview_assignment_scope_sql(context)
    vis_sql, vis_params = prehire_visibility_assignment_sql(context, surface="detail", kind="interviews")
    scope_where, scope_params = iqc.build_shared_scope(
        company,
        include_live=include_live,
        include_async_video=include_async_video,
        assignment_sql=assignment_sql or None,
        assignment_params=assignment_params,
        visibility_sql=vis_sql or None,
        visibility_params=vis_params,
    )
    scope_sql = " AND ".join(scope_where)

    where = list(scope_where)
    params: list[Any] = list(scope_params)
    tab_sql, tab_params = iqc.list_tab_predicate(status)
    if tab_sql:
        where.append(tab_sql)
        params.extend(tab_params)
    search = str(q or "").strip()
    if search:
        like = f"%{search}%"
        where.append(
            "("
            "ci.candidate_name ILIKE %s OR ci.candidate_email ILIKE %s OR ci.phone ILIKE %s "
            "OR ci.app_key ILIKE %s OR ci.position_code ILIKE %s OR ci.position_title ILIKE %s"
            ")"
        )
        params.extend([like, like, like, like, like, like])
    role_filter = str(role or "").strip()
    if role_filter:
        like = f"%{role_filter}%"
        where.append("(ci.position_code ILIKE %s OR ci.position_title ILIKE %s)")
        params.extend([like, like])
    date_value = str(date_filter or "").strip()
    if date_value:
        # Compare on company IANA local date, not DB session/UTC date.
        import interview_lifecycle as _il

        tz_name = _il.company_timezone_name(sys.modules[__name__], company)
        where.append("(ci.scheduled_start AT TIME ZONE %s)::date = %s::date")
        params.extend([tz_name, date_value])
    interviewer_filter = str(interviewer or "").strip()
    if interviewer_filter:
        like = f"%{interviewer_filter}%"
        where.append(
            """
            EXISTS (
              SELECT 1 FROM candidate_interview_assignments a
              WHERE a.interview_id=ci.interview_id
                AND a.company_code=ci.company_code
                AND (
                  a.assignee_email ILIKE %s
                  OR a.assignee_name ILIKE %s
                  OR a.assignee_user_id ILIKE %s
                  OR a.assignee_phone ILIKE %s
                )
            )
            """
        )
        params.extend([like, like, like, like])
    where_sql = " AND ".join(where)
    limit_value = bounded_limit(limit)
    offset_value = max(0, int(offset or 0))
    feedback_complete_sql = iqc.sql_feedback_complete_expr()
    needs_feedback_sql = iqc.sql_status_predicate("needs_feedback")
    video_sql = iqc.sql_status_predicate("video_interviews")
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT COUNT(*) AS count
                FROM candidate_interviews ci
                WHERE {where_sql}
                """,
                params,
            )
            total = int((cur.fetchone() or {}).get("count") or 0)
            cur.execute(
                f"""
                SELECT ci.*,
                       (
                         SELECT a.status
                         FROM applications a
                         WHERE a.company_code=ci.company_code AND a.app_key=ci.app_key
                         LIMIT 1
                       ) AS application_status
                FROM candidate_interviews ci
                WHERE {where_sql}
                ORDER BY
                  CASE ci.status
                    WHEN 'scheduled' THEN 0
                    WHEN 'rescheduled' THEN 1
                    WHEN 'completed' THEN 2
                    WHEN 'no_show' THEN 3
                    WHEN 'cancelled' THEN 4
                    ELSE 9
                  END,
                  ci.scheduled_start DESC NULLS LAST,
                  ci.updated_at DESC
                LIMIT %s OFFSET %s
                """,
                [*params, limit_value, offset_value],
            )
            interviews = [candidate_interview_summary(dict(row)) for row in cur.fetchall()]
            if permissions is not None:
                perms = {str(value) for value in permissions}
                can_manage = "interview.manage" in perms
                actor_role = dashboard_context_role_key(context) if context else ""
                import interview_presentation as _ip
                for interview in interviews:
                    allowed_actions: list[str] = []
                    if can_manage:
                        status_value = str(interview.get("status") or "")
                        if status_value in {"scheduled", "rescheduled"}:
                            allowed_actions.extend(["mark_completed", "mark_no_show", "cancel_interview"])
                        if interview.get("notes_status") != "complete":
                            allowed_actions.append("write_notes")
                        allowed_actions.append("open_candidate")
                    interview["allowed_actions"] = narrow_interview_allowed_actions_for_role(actor_role, allowed_actions)
                    assignment_names: list[str] = []
                    try:
                        with db_connect() as assign_conn:
                            with assign_conn.cursor() as assign_cur:
                                assign_cur.execute(
                                    """
                                    SELECT COALESCE(assignee_name, assignee_email, assignee_user_id) AS label
                                    FROM candidate_interview_assignments
                                    WHERE interview_id=%s AND company_code=%s
                                    ORDER BY created_at ASC NULLS LAST
                                    LIMIT 6
                                    """,
                                    (interview.get("interview_id"), company),
                                )
                                assignment_names = [str(r.get("label")) for r in assign_cur.fetchall() if r.get("label")]
                    except Exception:
                        assignment_names = []
                    interview["interviewer_assignments"] = assignment_names
                    feedback_submission = None
                    try:
                        with db_connect() as fb_conn:
                            with fb_conn.cursor() as fb_cur:
                                fb_cur.execute(
                                    """
                                    SELECT submission_id, status, submitted_at, updated_at
                                    FROM interview_feedback_submissions
                                    WHERE interview_id=%s AND company_code=%s
                                    ORDER BY updated_at DESC NULLS LAST
                                    LIMIT 1
                                    """,
                                    (interview.get("interview_id"), company),
                                )
                                row = fb_cur.fetchone()
                                feedback_submission = dict(row) if row else None
                    except Exception:
                        feedback_submission = None
                    if feedback_submission:
                        interview["feedback_submission"] = feedback_submission
                    presentation = _ip.build_interview_presentation(
                        interview,
                        can_manage=can_manage,
                        legacy_next_action=interview.get("next_human_action"),
                        assignments=assignment_names,
                    )
                    presentation["allowed_actions"] = narrow_interview_allowed_actions_for_role(
                        actor_role,
                        presentation.get("allowed_actions") or [],
                    )
                    interview["feedback"] = presentation.get("feedback")
                    interview["feedback_state"] = (presentation.get("feedback") or {}).get("state")
                    interview["needs_feedback"] = bool((presentation.get("feedback") or {}).get("needs_feedback"))
                    interview["presentation"] = presentation
                    interview["next_human_action"] = presentation.get("next_human_action") or interview.get("next_human_action")
                    interview["allowed_actions"] = presentation.get("allowed_actions") or interview.get("allowed_actions")
            # Tab badge counts share the list's tenant/visibility/assignment/kind scope.
            cur.execute(
                f"""
                SELECT status, COUNT(*) AS count
                FROM candidate_interviews ci
                WHERE {scope_sql}
                GROUP BY status
                ORDER BY count DESC, status
                """,
                scope_params,
            )
            status_counts = [json_safe(dict(row)) for row in cur.fetchall()]
            cur.execute(
                f"""
                SELECT
                  COUNT(*) FILTER (WHERE {needs_feedback_sql}) AS notes_pending,
                  COUNT(*) FILTER (
                    WHERE ci.status='completed' AND ({feedback_complete_sql})
                  ) AS feedback_complete
                FROM candidate_interviews ci
                WHERE {scope_sql}
                """,
                scope_params,
            )
            fb_row = cur.fetchone() or {}
            notes_pending = int(fb_row.get("notes_pending") or 0)
            feedback_complete = int(fb_row.get("feedback_complete") or 0)
            feedback_counts = [
                {"feedback_status": "notes_pending", "count": notes_pending},
                {"feedback_status": "feedback_complete", "count": feedback_complete},
            ]
            canonical_feedback_counts = [
                {"feedback_state": "needs_feedback", "count": notes_pending},
                {"feedback_state": "complete", "count": feedback_complete},
            ]
            cur.execute(
                f"""
                SELECT COUNT(*) AS count
                FROM candidate_interviews ci
                WHERE {scope_sql}
                  AND ({video_sql})
                """,
                scope_params,
            )
            video_count = int((cur.fetchone() or {}).get("count") or 0) if include_async_video else 0
    return {
        "company_code": company,
        "total": total,
        "limit": limit_value,
        "offset": offset_value,
        "status_counts": status_counts,
        "feedback_counts": feedback_counts,
        "canonical_feedback_counts": canonical_feedback_counts,
        "video_count": video_count,
        "interviews": interviews,
        "interviews_enabled": include_live,
        "video_interviews_enabled": include_async_video,
    }


def deterministic_interview_summary(notes: str, transcript: str | None = None) -> dict[str, Any]:
    text = re.sub(r"\s+", " ", f"{notes or ''} {transcript or ''}").strip()
    short = text[:280].strip()
    return {
        "summary": short or "Interview notes were saved.",
        "strengths": [],
        "concerns": [],
        "communication_notes": [],
        "role_fit_evidence": [],
        "missing_evidence": ["Human review is required before relying on this interview evidence."],
        "follow_up_points": [],
        "follow_up_questions": [],
        "recommendation": "HR review required",
        "recommended_next_step": "HR review required",
        "decision_policy": "AI summary is decision support only. HR remains the decision-maker.",
        "hr_decision_note": "This is decision support only. HR remains the decision-maker.",
        "source": "deterministic_fallback",
    }


def generate_interview_ai_summary(notes: str, transcript: str | None, application: dict[str, Any], interview: dict[str, Any]) -> dict[str, Any]:
    fallback = deterministic_interview_summary(notes, transcript)
    provider = planner_provider_config()
    if not provider:
        return fallback
    system = (
        "You summarize OctoHR interview notes. Return JSON only with keys: "
        "summary, strengths, concerns, communication_notes, role_fit_evidence, missing_evidence, "
        "follow_up_questions, recommended_next_step, decision_policy. "
        "Do not make the hiring decision. Keep HR as the decision-maker. Do not invent facts beyond the notes/transcript."
    )
    prompt = json.dumps(
        {
            "candidate": {
                "name": application.get("candidate_name"),
                "email": application.get("candidate_email"),
                "phone": application.get("phone"),
                "position": application.get("position_title") or application.get("position_code"),
            },
            "interview": {
                "status": interview.get("status"),
                "scheduled_start": json_safe(interview.get("scheduled_start")),
            },
            "notes": notes,
            "transcript": transcript or "",
        },
        ensure_ascii=False,
    )
    if provider.get("api") == "openai-responses":
        body = {
            "model": provider["model"],
            "temperature": 0.2,
            "input": [{"role": "system", "content": system}, {"role": "user", "content": prompt}],
        }
    else:
        body = {
            "model": provider["model"],
            "temperature": 0.2,
            "messages": [{"role": "system", "content": system}, {"role": "user", "content": prompt}],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    start = time_module.monotonic()
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception as exc:
        return {**fallback, "source": "deterministic_fallback", "ai_error": str(exc)[:300]}
    record_llm_call(
        call_name="interview_notes_summary",
        provider=provider,
        prompt_mode="concise",
        prompt_docs_loaded=False,
        prompt_hash=stable_text_hash(system),
        estimated_input_tokens=estimate_tokens_from_payload(body),
        latency_ms=int((time_module.monotonic() - start) * 1000),
        status="ok",
        parsed=parsed,
        metadata={"app_key": application.get("app_key"), "interview_id": str(interview.get("interview_id") or "")},
    )
    result = extract_json_object(extract_model_text(parsed))
    if not isinstance(result, dict):
        return fallback
    follow_up_questions = result.get("follow_up_questions")
    if not isinstance(follow_up_questions, list):
        follow_up_questions = result.get("follow_up_points") if isinstance(result.get("follow_up_points"), list) else []
    recommended_next_step = str(result.get("recommended_next_step") or result.get("recommendation") or "HR review required")[:300]
    return {
        "summary": str(result.get("summary") or fallback["summary"])[:1200],
        "strengths": json_safe(result.get("strengths") if isinstance(result.get("strengths"), list) else []),
        "concerns": json_safe(result.get("concerns") if isinstance(result.get("concerns"), list) else []),
        "communication_notes": json_safe(result.get("communication_notes") if isinstance(result.get("communication_notes"), list) else []),
        "role_fit_evidence": json_safe(result.get("role_fit_evidence") if isinstance(result.get("role_fit_evidence"), list) else []),
        "missing_evidence": json_safe(result.get("missing_evidence") if isinstance(result.get("missing_evidence"), list) else []),
        "follow_up_points": json_safe(follow_up_questions),
        "follow_up_questions": json_safe(follow_up_questions),
        "recommendation": recommended_next_step,
        "recommended_next_step": recommended_next_step,
        "decision_policy": "AI summary is decision support only. HR remains the decision-maker.",
        "hr_decision_note": "This is decision support only. HR remains the decision-maker.",
        "source": "llm",
    }


def dashboard_chat_candidate_card(candidate: dict[str, Any]) -> dict[str, Any] | None:
    if not isinstance(candidate, dict):
        return None
    application = candidate.get("application") if isinstance(candidate.get("application"), dict) else {}
    candidate_obj = candidate.get("candidate") if isinstance(candidate.get("candidate"), dict) else {}
    app_key = candidate.get("app_key") or candidate.get("candidate_app_key") or application.get("app_key")
    name = candidate.get("name") or candidate.get("candidate_name") or candidate_obj.get("name")
    phone = candidate.get("phone") or application.get("phone")
    position = candidate.get("position") or candidate.get("position_title") or candidate.get("position_code")
    if not position and isinstance(application.get("position"), dict):
        position = application["position"].get("title") or application["position"].get("code")
    status = candidate.get("status") or application.get("status")
    safe_ranking_card = _ranking_presentation.compact_chat_artifact(candidate)
    if safe_ranking_card:
        score = safe_ranking_card["score"]
        reasons = safe_ranking_card["reasons"]
        position = safe_ranking_card.get("position") or position
    else:
        score = candidate.get("score")
        if score is None:
            score = candidate.get("ranking_score")
        reasons = candidate.get("reasons") or candidate.get("evidence") or []
    if not any([app_key, name, phone]):
        return None
    return {
        "app_key": app_key,
        "name": name or phone or "Candidate",
        "phone": phone,
        "position": position,
        "status": status,
        "score": json_safe(score),
        "reasons": json_safe(reasons[:3] if isinstance(reasons, list) else []),
        "presentation": json_safe(safe_ranking_card.get("presentation")) if safe_ranking_card else None,
    }


def dashboard_chat_artifacts(
    orchestrator_result: dict[str, Any],
    request: DashboardChatRequest,
    *,
    company_code: str | None = None,
) -> dict[str, Any]:
    audit = orchestrator_result.get("audit") if isinstance(orchestrator_result.get("audit"), dict) else {}
    outputs = audit.get("tool_outputs") if isinstance(audit.get("tool_outputs"), list) else []
    cards: list[dict[str, Any]] = []
    navigation: list[dict[str, Any]] = []
    confirmation: dict[str, Any] | None = None
    workflow_card: dict[str, Any] | None = None
    # A navigation chip must never advertise a page the tenant cannot open.
    # Interviews serves both interview kinds, so either module keeps it reachable.
    # Assessments is a single module — when it is off, no Assessments chip or link.
    interviews_page_reachable = True
    assessments_page_reachable = True
    reports_page_reachable = True
    if company_code:
        enabled = configured_company_modules(company_code)
        interviews_page_reachable = bool({"interviews", "video_interviews"} & enabled)
        assessments_page_reachable = "assessments" in enabled
    for output in outputs:
        result = output.get("result") if isinstance(output.get("result"), dict) else {}
        if isinstance(result.get("workflow_card"), dict):
            workflow_card = json_safe(result.get("workflow_card"))
        if output.get("status") == "needs_confirmation":
            preview = result.get("confirmation_preview") if isinstance(result.get("confirmation_preview"), dict) else {}
            summary = result.get("confirmation_text") or preview.get("confirmation_text") or result.get("message")
            ranking_preview = bool(
                preview.get("label") == "Calculate Ranking"
                or result.get("mint_recalculate_pending")
                or result.get("error") in {"ranking_run_required", "ranking_recalculate_confirmation_required"}
                or (isinstance(result.get("filters"), dict) and result["filters"].get("auto_recalculate_preview"))
            )
            steps = result.get("steps") if isinstance(result.get("steps"), list) else []
            confirmation = {
                "pending_action_id": output.get("pending_action_id"),
                "label": "Calculate Ranking" if ranking_preview else (preview.get("label") or "Confirm"),
                "summary": summary if isinstance(summary, str) else None,
                "is_active": True,
                "status": "pending",
                "preview": json_safe(preview) if preview else None,
                "steps": json_safe(steps),
                "channels": json_safe(result.get("invite_channel") or (workflow_card or {}).get("channels")),
                "people": json_safe((workflow_card or {}).get("people") or []),
                "missing_fields": json_safe(result.get("missing_fields") or []),
                "blocked_steps": json_safe(result.get("blocked_steps") or []),
                "workflow_card": workflow_card,
            }
            if workflow_card and workflow_card.get("kind") == "workflow_preview":
                confirmation["label"] = confirmation.get("label") or "Confirm workflow"
        if str(result.get("status") or "").lower() == "partial" and isinstance(result.get("workflow_card"), dict):
            workflow_card = {
                **json_safe(result.get("workflow_card")),
                "kind": "workflow_result",
                "status": "partial",
            }
        candidates = result.get("candidates") if isinstance(result.get("candidates"), list) else []
        for candidate in candidates[:5]:
            card = dashboard_chat_candidate_card(candidate)
            if card:
                cards.append(card)
        for key in ("application", "candidate", "candidate_context", "selected_application"):
            value = result.get(key) if isinstance(result.get(key), dict) else None
            card = dashboard_chat_candidate_card(value or {})
            if card:
                cards.append(card)
        matches = result.get("matches") if isinstance(result.get("matches"), list) else []
        for match in matches[:5]:
            card = dashboard_chat_candidate_card(match)
            if card:
                cards.append(card)
        tool = str(output.get("tool") or "")
        if tool == "rank_candidates":
            position = (result.get("filters") or {}).get("position") if isinstance(result.get("filters"), dict) else None
            navigation.append({"type": "page", "page": "ranking", "label": "Open Ranking", "position_code": position})
        if tool == "list_job_openings":
            cont = result.get("continuation") if isinstance(result.get("continuation"), dict) else {}
            if cont.get("label") and cont.get("prompt"):
                navigation.append(
                    {
                        "type": "assistant_prompt",
                        "label": cont.get("label") or "Show more roles",
                        "prompt": cont.get("prompt") or "Show more roles",
                        "offset": cont.get("offset"),
                    }
                )
        if tool == "get_reports_metrics" and reports_page_reachable:
            navigation.append({"type": "page", "page": "reports", "label": "Open Reports"})
        if assessments_page_reachable and tool in {"send_assessment", "execute_candidate_workflow"} and (
            tool == "send_assessment" or "send_assessment" in json.dumps(result.get("steps") or result.get("completed_steps") or [], default=str)
        ):
            navigation.append({"type": "page", "page": "assessments", "label": "Open Assessments"})
        if (
            interviews_page_reachable
            and tool in {"schedule_interview", "reschedule_interview", "cancel_interview", "execute_candidate_workflow"}
            and (
                result.get("interview")
                or result.get("artifacts")
                or tool in {"schedule_interview", "reschedule_interview", "cancel_interview"}
                or "schedule_interview" in json.dumps(result, default=str)
            )
        ):
            navigation.append({"type": "page", "page": "interviews", "label": "Open Interviews"})
    # Policy short-circuit may attach a navigation hint without tool outputs.
    hint = orchestrator_result.get("navigation_hint")
    if isinstance(hint, dict) and hint.get("page"):
        navigation.append(hint)
    # Navigation must come from grounded tool/policy results only — no wording heuristics.
    deduped_cards: list[dict[str, Any]] = []
    seen_cards: set[str] = set()
    for card in cards:
        key = str(card.get("app_key") or card.get("phone") or card.get("name"))
        if key and key not in seen_cards:
            seen_cards.add(key)
            deduped_cards.append(card)
    deduped_nav: list[dict[str, Any]] = []
    seen_nav: set[str] = set()
    for item in navigation:
        key = json.dumps(item, sort_keys=True, default=str)
        if key not in seen_nav:
            seen_nav.add(key)
            deduped_nav.append(item)
    return {
        "candidate_cards": deduped_cards[:6],
        "navigation": deduped_nav[:6],
        "confirmation": confirmation,
        "workflow_card": workflow_card,
    }


def dashboard_chat_actor_id(context: dict[str, Any]) -> str:
    return str(context.get("actor_user_id") or digits(context.get("hr_phone")) or "dashboard").strip() or "dashboard"


def dashboard_chat_conversation_id(context: dict[str, Any], conversation_id: str | None = None) -> str:
    raw = str(conversation_id or "").strip()
    if raw:
        return re.sub(r"[^a-zA-Z0-9_.:@-]+", "_", raw)[:180]
    company = require_company_code(context.get("company_code"))
    actor = dashboard_chat_actor_id(context)
    return f"dashboard:{company}:{actor}:ai_recruiter:{uuid.uuid4().hex[:12]}"


def dashboard_chat_session_title(message: str, response: DashboardChatResponse | None = None) -> str:
    text = normalize_text(message)
    cards = response.candidate_cards if response else []
    name = None
    position = None
    if cards:
        first = cards[0] if isinstance(cards[0], dict) else {}
        name = str(first.get("name") or first.get("phone") or "").strip() or None
        position = str(first.get("position") or "").strip() or None
    if "video" in text and name:
        return f"Sent video interview to {name}"
    if "assessment" in text and name:
        return f"Sent assessment to {name}"
    if "shortlist" in text:
        return f"Shortlisted {position or 'candidates'}"
    if any(word in text for word in ("compare", "rank", "ranking")):
        return f"Compared top {position or 'candidates'}"
    if name:
        return f"Reviewed {name}"
    cleaned = re.sub(r"\s+", " ", str(message or "").strip())
    if not cleaned:
        return "AI Recruiter chat"
    cleaned = re.sub(r"\b(app_key|action_result|execute_[a-z_]+|send_video_interview|send_assessment)\b", "", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\s+", " ", cleaned).strip(" -_:")
    return (cleaned[:56].rstrip() + "…") if len(cleaned) > 58 else cleaned or "AI Recruiter chat"


def dashboard_chat_session_scope(context: dict[str, Any]) -> dict[str, Any]:
    company = require_company_code(context.get("company_code"))
    actor_user_id = dashboard_chat_actor_id(context)
    return {
        "company_code": company,
        "actor_user_id": actor_user_id,
        "actor_phone": digits(context.get("hr_phone")) or digits((context.get("hr_user") or {}).get("phone")),
        "actor_role": str(context.get("actor_role") or (context.get("access") or {}).get("role") or ""),
        "channel": "dashboard",
        "module": "ai_recruiter",
    }


def upsert_dashboard_chat_session(
    cur: Any,
    context: dict[str, Any],
    conversation_id: str,
    *,
    title: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    scope = dashboard_chat_session_scope(context)
    cur.execute(
        """
        INSERT INTO dashboard_chat_sessions
          (conversation_id, company_code, actor_user_id, actor_phone, actor_role, channel, module, title, metadata)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)
        ON CONFLICT (conversation_id) DO UPDATE SET
          title=CASE
            WHEN dashboard_chat_sessions.title='AI Recruiter chat' AND EXCLUDED.title <> 'AI Recruiter chat' THEN EXCLUDED.title
            ELSE dashboard_chat_sessions.title
          END,
          metadata=dashboard_chat_sessions.metadata || EXCLUDED.metadata,
          updated_at=now(),
          last_message_at=now()
        RETURNING *
        """,
        (
            conversation_id,
            scope["company_code"],
            scope["actor_user_id"],
            scope["actor_phone"],
            scope["actor_role"],
            scope["channel"],
            scope["module"],
            title or "AI Recruiter chat",
            Json(json_safe(metadata or {})),
        ),
    )
    return json_safe(dict(cur.fetchone()))


def record_dashboard_chat_message(
    cur: Any,
    context: dict[str, Any],
    conversation_id: str,
    role: str,
    text: str,
    payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    scope = dashboard_chat_session_scope(context)
    cur.execute(
        """
        INSERT INTO dashboard_chat_messages
          (conversation_id, company_code, actor_user_id, role, text, payload)
        VALUES (%s,%s,%s,%s,%s,%s)
        RETURNING *
        """,
        (
            conversation_id,
            scope["company_code"],
            scope["actor_user_id"],
            role,
            text or "",
            Json(json_safe(payload or {})),
        ),
    )
    row = cur.fetchone()
    cur.execute(
        """
        UPDATE dashboard_chat_sessions
        SET updated_at=now(), last_message_at=now()
        WHERE conversation_id=%s
        """,
        (conversation_id,),
    )
    return json_safe(dict(row or {}))


def dashboard_chat_session_allowed(cur: Any, context: dict[str, Any], conversation_id: str) -> dict[str, Any] | None:
    scope = dashboard_chat_session_scope(context)
    cur.execute(
        """
        SELECT *
        FROM dashboard_chat_sessions
        WHERE conversation_id=%s
          AND company_code=%s
          AND actor_user_id=%s
          AND channel='dashboard'
          AND module='ai_recruiter'
        """,
        (conversation_id, scope["company_code"], scope["actor_user_id"]),
    )
    row = cur.fetchone()
    return json_safe(dict(row)) if row else None


def active_dashboard_confirmation(cur: Any, confirmation: dict[str, Any] | None) -> dict[str, Any] | None:
    if not confirmation:
        return None
    pending_id = confirmation.get("pending_action_id")
    if not pending_id:
        return {**confirmation, "is_active": False, "status": "inactive", "label": "Confirmation inactive"}
    cur.execute(
        """
        SELECT action_id, status, expires_at
        FROM pending_actions
        WHERE action_id=%s
        """,
        (pending_id,),
    )
    row = cur.fetchone()
    if not row or row.get("status") != "pending" or (row.get("expires_at") and row["expires_at"] <= now_utc()):
        return {**confirmation, "is_active": False, "status": "expired", "label": "Confirmation expired"}
    return {**confirmation, "is_active": True, "status": "pending"}


def cancel_dashboard_chat_pending_confirmations(context: dict[str, Any], conversation_id: str | None) -> int:
    if not conversation_id:
        return 0
    scope = dashboard_chat_session_scope(context)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE pending_actions
                SET status='cancelled', resolved_at=now(), metadata=metadata || %s
                WHERE conversation_id=%s
                  AND company_code=%s
                  AND actor_user_id=%s
                  AND status='pending'
                """,
                (
                    Json({"cancelled_by": "dashboard_new_chat", "cancelled_at": now_iso()}),
                    conversation_id,
                    scope["company_code"],
                    scope["actor_user_id"],
                ),
            )
            cancelled = cur.rowcount
            cur.execute(
                """
                UPDATE pending_operations
                SET status='cancelled', resolved_at=now()
                WHERE conversation_id=%s
                  AND admin_phone=%s
                  AND status='pending'
                """,
                (conversation_id, scope["actor_phone"]),
            )
        conn.commit()
    return int(cancelled or 0)


def dashboard_application_or_404(
    app_key: str,
    company_code: str,
    context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    application = find_application_by_key(app_key, company_code=company_code)
    if not application:
        raise HTTPException(status_code=404, detail={"error": "application_not_found"})
    if context is not None:
        require_prehire_application_visibility(context, application)
    return application


def dashboard_candidate_cv_metadata(application: dict[str, Any]) -> dict[str, Any] | None:
    app_key = str(application.get("app_key") or "").strip()
    company_code = str(application.get("company_code") or "").upper()
    if not app_key:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM file_registry
                WHERE company_code=%s
                  AND subject_type='application'
                  AND subject_key=%s
                  AND document_type='cv'
                ORDER BY updated_at DESC
                LIMIT 1
                """,
                (company_code, app_key),
            )
            row = cur.fetchone()
    if row:
        return json_safe(dict(row))

    raw_json = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
    cv = raw_json.get("cv") if isinstance(raw_json.get("cv"), dict) else {}
    storage = cv.get("storage") if isinstance(cv.get("storage"), dict) else {}
    if not cv and not storage:
        return None
    return json_safe(
        {
            "company_code": company_code,
            "subject_type": "application",
            "subject_key": app_key,
            "file_kind": "candidate_cv",
            "document_type": "cv",
            "original_filename": cv.get("filename"),
            "source_path": cv.get("path"),
            "local_path": cv.get("path"),
            "storage_provider": storage.get("provider"),
            "storage_object_key": storage.get("object_key"),
            "external_file_id": storage.get("external_file_id"),
            "storage_url": storage.get("url"),
            "mime_type": storage.get("mime_type"),
            "size_bytes": storage.get("size_bytes"),
            "storage_status": storage.get("status"),
        }
    )


def dashboard_candidate_cv_preview_metadata(application: dict[str, Any]) -> dict[str, Any] | None:
    app_key = str(application.get("app_key") or "").strip()
    company_code = str(application.get("company_code") or "").upper()
    if not app_key:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM file_registry
                WHERE company_code=%s
                  AND subject_type='application'
                  AND subject_key=%s
                  AND file_kind='candidate_cv_preview'
                  AND document_type='cv_preview'
                  AND storage_status IN ('stored','ok','uploaded')
                ORDER BY updated_at DESC, created_at DESC
                LIMIT 1
                """,
                (company_code, app_key),
            )
            row = cur.fetchone()
    return json_safe(dict(row)) if row else None


def dashboard_candidate_cv_path(cv: dict[str, Any]) -> Path | None:
    for key in ("local_path", "source_path"):
        path_value = str(cv.get(key) or "").strip()
        if not path_value:
            continue
        path = Path(path_value)
        if path.exists() and path.is_file():
            return path
    return None


def office_converter_command() -> str | None:
    configured = os.environ.get("WATHEFNI_OFFICE_CONVERTER")
    candidates = [configured] if configured else []
    candidates.extend(["soffice", "libreoffice"])
    for candidate in candidates:
        if candidate and shutil.which(candidate):
            return candidate
    return None


def register_candidate_cv_preview(
    *,
    application: dict[str, Any],
    original_cv: dict[str, Any],
    preview_path: Path,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    company_code = str(application.get("company_code") or "").strip().upper()
    if not company_code:
        return {"ok": False, "error": "tenant_scope_required"}
    phone = digits(application.get("phone"))
    app_key = str(application.get("app_key") or f"{phone}-{company_code}-APPLICATION")
    checksum = sha256_file(preview_path)
    storage_result = store_subject_file(
        company_code=company_code,
        owner_phone=phone,
        subject_type="application",
        subject_key=app_key,
        file_kind="candidate_cv_preview",
        source_path=preview_path,
        mime_type="application/pdf",
        checksum=checksum,
    )
    storage_metadata = storage_result.get("metadata") if isinstance(storage_result.get("metadata"), dict) else {}
    registry_metadata = {
        "phone": phone,
        "app_key": app_key,
        "company_code": company_code,
        "position_code": application.get("position_code"),
        "source": "generated_cv_preview",
        "original_file_kind": original_cv.get("file_kind"),
        "original_document_type": original_cv.get("document_type"),
        "original_filename": original_cv.get("original_filename"),
        **(metadata or {}),
    }
    with db_connect() as conn:
        with conn.cursor() as cur:
            upsert_file_registry(
                cur,
                company_code=company_code,
                owner_phone=phone,
                subject_type="application",
                subject_key=app_key,
                file_kind="candidate_cv_preview",
                document_type="cv_preview",
                original_filename=f"{Path(str(original_cv.get('original_filename') or app_key)).stem}.pdf",
                source_path=str(preview_path),
                local_path=storage_metadata.get("local_path") or str(preview_path),
                storage_result=storage_result,
                metadata=registry_metadata,
            )
        conn.commit()
    return {"ok": bool(storage_result.get("ok")), "storage": storage_result}


def generate_candidate_cv_pdf_preview(application: dict[str, Any], cv: dict[str, Any]) -> dict[str, Any]:
    company_code = str(application.get("company_code") or "").strip().upper()
    if not company_code:
        return {"ok": False, "status": "failed", "error": "tenant_scope_required"}
    source_path = dashboard_candidate_cv_path(cv)
    if not source_path:
        return {"ok": False, "status": "failed", "error": "candidate_cv_file_unavailable"}

    source_mime = str(cv.get("mime_type") or mimetypes.guess_type(source_path.name)[0] or "")
    if source_mime == "application/pdf":
        return register_candidate_cv_preview(
            application=application,
            original_cv=cv,
            preview_path=source_path,
            metadata={"conversion": "source_pdf_reused"},
        )

    converter = office_converter_command()
    if not converter:
        return {"ok": False, "status": "failed", "error": "office_converter_unavailable"}

    app_key = str(application.get("app_key") or "application")
    work_dir = (
        WORKSPACE
        / "data"
        / "companies"
        / company_code
        / "tmp"
        / "cv-previews"
        / safe_storage_name(app_key)
    )
    work_dir.mkdir(parents=True, exist_ok=True)
    result = subprocess.run(
        [converter, "--headless", "--convert-to", "pdf", "--outdir", str(work_dir), str(source_path)],
        capture_output=True,
        text=True,
        timeout=90,
    )
    generated = work_dir / f"{source_path.stem}.pdf"
    if result.returncode != 0 or not generated.exists():
        return {
            "ok": False,
            "status": "failed",
            "error": "pdf_preview_conversion_failed",
            "stderr": result.stderr[-1000:],
            "stdout": result.stdout[-1000:],
        }
    return register_candidate_cv_preview(
        application=application,
        original_cv=cv,
        preview_path=generated,
        metadata={"conversion": "libreoffice_headless", "converter": converter},
    )


def docx_text_preview(path: Path) -> str:
    """Local-only DOCX preview (headers/footers/tables/textboxes). Never calls OCR."""
    try:
        blocks, _images, meta = _cv_docx.parse_docx_local(Path(path))
        if meta.get("corrupted"):
            return ""
        return _cv_docx.blocks_to_text(blocks)
    except Exception:
        return ""


def cv_preview_html(*, app_key: str, filename: str, mime_type: str, body: str, note: str | None = None) -> HTMLResponse:
    safe_title = html.escape(filename or f"{app_key} CV")
    safe_body = html.escape(body or "No preview text could be extracted from this CV.")
    safe_note = html.escape(note or "")
    note_html = f"<p class=\"note\">{safe_note}</p>" if safe_note else ""
    return HTMLResponse(
        f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{safe_title}</title>
  <style>
    :root {{ font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #09090b; background: #fafafa; }}
    body {{ margin: 0; }}
    main {{ max-width: 920px; margin: 0 auto; padding: 32px 24px 56px; }}
    header {{ border-bottom: 1px solid #e4e4e7; margin-bottom: 24px; padding-bottom: 18px; }}
    h1 {{ font-size: 24px; margin: 0 0 8px; letter-spacing: -0.02em; }}
    .meta, .note {{ color: #71717a; font-size: 14px; line-height: 1.6; }}
    .doc {{ background: #fff; border: 1px solid #e4e4e7; border-radius: 16px; box-shadow: 0 1px 2px rgba(9,9,11,.05); padding: 28px; white-space: pre-wrap; line-height: 1.75; font-size: 15px; }}
  </style>
</head>
<body>
  <main>
    <header>
      <h1>{safe_title}</h1>
      <div class="meta">{html.escape(mime_type)}</div>
      {note_html}
    </header>
    <section class="doc">{safe_body}</section>
  </main>
</body>
</html>"""
    )


def workspace_tool_json(result: dict[str, Any]) -> dict[str, Any]:
    payload = result.get("json") if isinstance(result, dict) else None
    return payload if isinstance(payload, dict) else {}


def workspace_tool_operation_ok(result: dict[str, Any]) -> bool:
    payload = workspace_tool_json(result)
    return bool(result.get("ok") and payload.get("ok", True))


def dashboard_prehire_mutation_response(
    *,
    action_type: str,
    status: str,
    reply: str,
    result_payload: dict[str, Any],
    app_key: str,
    company_code: str,
    permissions: set[str] | list[str] | None = None,
) -> dict[str, Any]:
    audit = dashboard_record_action_result(action_type, status, result_payload, reply)
    refreshed = find_application_by_key(app_key, company_code=company_code)
    # Mutation responses must use the same permission-aware UI contract as list/detail.
    # Omitting permissions previously returned allowed_actions=[] and wiped the drawer menu.
    application = prehire_application_summary(
        refreshed,
        include_raw=True,
        include_assessment=company_has_module(company_code, "assessments"),
        permissions=list(permissions or []),
    ) if refreshed else None
    return {
        "ok": status == "completed",
        "company_code": company_code,
        "action_type": action_type,
        "status": status,
        "reply": reply,
        "result": json_safe(result_payload),
        "audit": audit,
        "application": application,
    }


def _unified_applications_payload(
    rows,
    *,
    include_assessment,
    permissions,
    use_unified,
    include_match_reasons,
    search,
    _uc,
    prehire_application_summary,
):
    out = []
    for row in rows:
        summary = prehire_application_summary(
            row,
            include_assessment=include_assessment,
            permissions=permissions,
        )
        if use_unified:
            gov = row.get("governance_json") if isinstance(row.get("governance_json"), dict) else None
            summary = _uc.enrich_application_summary(summary, row, gov=gov, permissions=permissions)
        projection = row.get("_classification_projection") if isinstance(row.get("_classification_projection"), dict) else None  # TALENT_POOL_CLASSIFICATION_COMPLETE_UI_PATCH: merge classification projection
        if projection:
            summary.update(projection)
            if include_match_reasons and search:
                snapshot = _uc.extract_facts_snapshot(row)
                effective = _uc.effective_facts_from_events(snapshot, [])
                summary["match_reasons"] = _uc.search_match_reasons(
                    query=search,
                    row=row,
                    effective_facts=effective,
                    semantic_similarity=None,
                )
                summary["record_state_label"] = _uc.record_state_label(
                    summary.get("record_state") or _uc.RECORD_ACTIVE
                )
        out.append(summary)
    return out


def _prehire_application_status_values(status: str | None) -> list[str]:
    """Parse list Stage filter: single status or comma-separated display-bucket aliases."""
    raw = str(status or "").strip()
    if not raw:
        return []
    return [part.strip().lower() for part in raw.split(",") if part.strip()]


def _append_prehire_application_status_filter(
    where: list[str],
    params: list[Any],
    status: str | None,
    *,
    column: str = "a.status",
) -> None:
    statuses = _prehire_application_status_values(status)
    if not statuses:
        return
    if len(statuses) == 1:
        where.append(f"{column}=%s")
        params.append(statuses[0])
    else:
        where.append(f"{column} = ANY(%s)")
        params.append(statuses)


def prehire_applications_query(

    *,
    company_code: str,
    status: str | None,
    position: str | None,
    search: str | None,
    limit: int,
    offset: int,
    cv_status: str | None = None,
    assessment_status: str | None = None,
    interview_status: str | None = None,
    follow_up: str | None = None,
    review_status: str | None = None,
    overview_cohort: str | None = None,
    activity_from: str | None = None,
    activity_to: str | None = None,
    sort: str | None = None,
    include_assessment: bool = True,
    permissions: set[str] | list[str] | None = None,
    owner_scope: str | None = None,
    owner_user_id: str | None = None,
    actor_user_id: str | None = None,
    tag_id: str | None = None,
    cursor: str | None = None,
    view: str | None = None,
    source_channel: str | None = None,
    recruiter_owner: str | None = None,
    cv_processing_state: str | None = None,
    received_from: str | None = None,
    received_to: str | None = None,
    has_grounded_email: str | None = None,
    has_grounded_phone: str | None = None,
    fact_completeness: str | None = None,
    department_intake_tag: str | None = None,
    include_match_reasons: bool = False,
    classification_filters: dict[str, Any] | None = None,  # TALENT_POOL_CLASSIFICATION_COMPLETE_UI_PATCH
    visibility_sql: str | None = None,
    visibility_params: list[Any] | None = None,
) -> dict[str, Any]:
    import unified_candidates as _uc  # UNIFIED_CANDIDATES_PRODUCTION_DARK_PATCH
    import talent_pool_classification as _tpc  # TALENT_POOL_CLASSIFICATION_COMPLETE_UI_PATCH

    cv_filter = str(cv_status or "").strip().lower()
    view_key = str(view or "").strip().lower()
    unified_on = _uc.feature_enabled_for_company(company_code)
    classification_ui = False  # TALENT_POOL_CLASSIFICATION_COMPLETE_UI_PATCH
    parsed_classification = None  # TALENT_POOL_CLASSIFICATION_COMPLETE_UI_PATCH
    try:
        classification_ui = bool(
            _tpc.feature_enabled_for_company(company_code)
            and (_tpc.feature_ui_enabled() or _tpc.feature_schema_enabled())
        )
        if classification_ui and classification_filters:
            parsed_classification = _tpc.parse_classification_filter_query(classification_filters)
    except Exception:
        classification_ui = False
        parsed_classification = None
    use_unified = unified_on and (
        bool(view_key)
        or any(
            [
                source_channel,
                recruiter_owner,
                cv_processing_state,
                received_from,
                received_to,
                has_grounded_email,
                has_grounded_phone,
                fact_completeness,
                department_intake_tag,
                bool(parsed_classification and parsed_classification.get("active")),
            ]
        )
    )
    if use_unified:
        view_key = view_key or _uc.VIEW_ALL
        view_sql, view_params = _uc.view_predicate_sql(view_key, "a", "gov")
        where = ["a.company_code=%s", view_sql]
        params: list[Any] = [company_code, *view_params]
    else:
        base_predicate = production_application_predicate("a") if cv_filter in {"all", "incomplete", "missing", "no_cv"} else reviewable_application_predicate("a")
        where = ["a.company_code=%s", base_predicate]
        params = [company_code]
        view_key = ""
    vis_sql = str(visibility_sql or "").strip()
    if vis_sql:
        where.append(f"({vis_sql})")
        params.extend(list(visibility_params or []))
    _append_prehire_application_status_filter(where, params, status, column="a.status")
    cohort = str(overview_cohort or "").strip().lower()
    # role_active uses exact position_code so ACCOUNTING does not swallow ACCOUNTING_EXCEL.
    if position and cohort == "role_active":
        where.append("a.position_code=%s")
        params.append(position)
    elif position:
        where.append("(a.position_code ILIKE %s OR a.position_title ILIKE %s)")
        params.extend([f"%{position}%", f"%{position.replace('_', ' ')}%"])
    if search:
        if use_unified:
            where.append(
                "("
                "a.app_key ILIKE %s OR c.name ILIKE %s OR c.email ILIKE %s "
                "OR a.position_code ILIKE %s OR a.position_title ILIKE %s "
                "OR (a.phone NOT ILIKE 'imp-%%' AND a.phone ILIKE %s) "
                "OR COALESCE(a.raw_json->>'candidate_email', a.raw_json->>'email', '') ILIKE %s "
                "OR COALESCE(a.raw_json->>'candidate_phone', '') ILIKE %s "
                "OR COALESCE(sd.content, '') ILIKE %s "
                "OR COALESCE(c.profile::text, '') ILIKE %s"
                ")"
            )
            like = f"%{search}%"
            params.extend([like, like, like, like, like, like, like, like, like, like])
        else:
            where.append(
                "(a.app_key ILIKE %s OR a.phone ILIKE %s OR c.name ILIKE %s OR c.email ILIKE %s "
                "OR a.position_code ILIKE %s OR a.position_title ILIKE %s)"
            )
            like = f"%{search}%"
            params.extend([like, like, like, like, like, like])
    if cv_filter in {"with_cv", "received"}:
        where.append("(a.cv_received IS TRUE OR jsonb_typeof(a.raw_json->'cv') = 'object')")
    elif cv_filter in {"incomplete", "missing", "no_cv"}:
        where.append("NOT (a.cv_received IS TRUE OR jsonb_typeof(a.raw_json->'cv') = 'object')")
    if assessment_status:
        if assessment_status == "none":
            where.append("COALESCE(latest_assessment.assessment_status, a.raw_json->'assessment'->>'status', '') = ''")
        elif assessment_status == "awaiting":
            # Canonical with prehire_overview.assessment_pending / Overview card.
            where.append(
                _prehire_overview.assessment_pending_predicate(
                    "a",
                    assessment_status_expr="COALESCE(latest_assessment.assessment_status, a.raw_json->'assessment'->>'status', '')",
                    assessment_delivery_status_expr="COALESCE(latest_assessment.assessment_delivery_status, a.raw_json->'assessment'->>'delivery_status', '')",
                )
            )
        else:
            where.append("COALESCE(latest_assessment.assessment_status, a.raw_json->'assessment'->>'status')=%s")
            params.append(assessment_status)
    if interview_status:
        if interview_status == "none":
            where.append("latest_interview.interview_status IS NULL")
        else:
            where.append("latest_interview.interview_status=%s")
            params.append(interview_status)
    if str(follow_up or "").strip().lower() in {"1", "true", "yes", "needed"}:
        # Canonical with prehire_overview.follow_up_needed / Overview follow-up card.
        where.append(_prehire_overview.follow_up_needed_exists("a"))
    if str(review_status or "").strip().lower() in {"ready", "ready_for_review", "needed"}:
        # Canonical with prehire_overview.ready_for_review / Overview review card.
        where.append(_prehire_overview.ready_for_review_predicate("a"))
    if cohort in {"interview_scheduling_debt", "interview_debt"}:
        # Exact Overview interview scheduling debt (not Interviews tab status).
        where.append(
            _prehire_overview.interview_scheduling_debt_predicate(
                "a",
                interview_status_expr="latest_interview.interview_status",
            )
        )
    elif cohort in {"role_active", "active_role"}:
        where.append(_prehire_overview.role_active_predicate("a"))
    elif cohort in {"follow_up_needed", "follow_up"} and str(follow_up or "").strip().lower() not in {
        "1",
        "true",
        "yes",
        "needed",
    }:
        where.append(_prehire_overview.follow_up_needed_exists("a"))
    elif cohort in {"ready_for_review", "ready"} and str(review_status or "").strip().lower() not in {
        "ready",
        "ready_for_review",
        "needed",
    }:
        where.append(_prehire_overview.ready_for_review_predicate("a"))
    elif cohort.startswith("assessment_") or cohort in {
        "awaiting",
        "ready_to_send",
        "first_send",
        "resend",
        "resend_needed",
        "delivery_failed",
        "attention",
        "assessment_pending",
    }:
        import assessment_cohorts as _assessment_cohorts

        # Skip if assessment_status=awaiting already applied the attention predicate.
        if not (
            str(assessment_status or "").strip().lower() == "awaiting"
            and _assessment_cohorts.normalize_cohort_key(cohort) == _assessment_cohorts.COHORT_ATTENTION
        ):
            where.append(
                _assessment_cohorts.cohort_predicate(
                    cohort,
                    "a",
                    status_expr="COALESCE(latest_assessment.assessment_status, a.raw_json->'assessment'->>'status', '')",
                    delivery_expr="COALESCE(latest_assessment.assessment_delivery_status, a.raw_json->'assessment'->>'delivery_status', '')",
                )
            )
    if activity_from:
        where.append("COALESCE(a.updated_at, a.ingested_at) >= %s::date")
        params.append(activity_from)
    if activity_to:
        where.append("COALESCE(a.updated_at, a.ingested_at) < (%s::date + interval '1 day')")
        params.append(activity_to)
    if received_from:
        where.append("a.ingested_at >= %s::date")
        params.append(received_from)
    if received_to:
        where.append("a.ingested_at < (%s::date + interval '1 day')")
        params.append(received_to)
    if source_channel:
        where.append(
            "LOWER(COALESCE(a.raw_json->'intake'->>'source', a.raw_json->'import'->>'source', a.raw_json->>'intake_source', a.data_source, '')) ILIKE %s"
        )
        params.append(f"%{source_channel.strip().lower()}%")
    if recruiter_owner:
        if str(recruiter_owner).strip().lower() in {"unassigned", "none", "-"}:
            where.append("COALESCE(gov.recruiter_owner_user_id, a.owner_user_id::text, '') = ''")
        else:
            where.append("COALESCE(gov.recruiter_owner_user_id, a.owner_user_id::text, '') = %s")
            params.append(str(recruiter_owner).strip())
    if cv_processing_state:
        bucket = str(cv_processing_state).strip().lower()
        if bucket == "ready":
            where.append(
                "(COALESCE(a.raw_json->'cv'->'processing'->>'profile_parsed','') IN ('true','1') "
                "OR jsonb_typeof(c.profile) = 'object')"
            )
        elif bucket == "partial":
            where.append(
                "(COALESCE(a.raw_json->'cv'->'processing'->>'status','') ILIKE ANY(ARRAY['partial','incomplete','processing']) "
                "OR COALESCE(a.raw_json->'cv'->'processing'->>'text_extracted','') IN ('true','1'))"
            )
        elif bucket == "failed":
            where.append("COALESCE(a.raw_json->'cv'->'processing'->>'status','') ILIKE ANY(ARRAY['failed','error','dead_letter'])")
    if has_grounded_email and str(has_grounded_email).strip().lower() in {"1", "true", "yes"}:
        where.append("COALESCE(c.email, a.raw_json->>'candidate_email', a.raw_json->>'email', '') <> ''")
    if has_grounded_phone and str(has_grounded_phone).strip().lower() in {"1", "true", "yes"}:
        where.append(
            "("
            "(a.phone IS NOT NULL AND a.phone NOT ILIKE 'imp-%%') "
            "OR COALESCE(a.raw_json->>'candidate_phone','') <> ''"
            ")"
        )
    if department_intake_tag:
        where.append("COALESCE(gov.department_intake_tag, '') ILIKE %s")
        params.append(f"%{department_intake_tag.strip()}%")
    sort_key = str(sort or "newest").strip().lower()
    order_sql = {
        "newest": "COALESCE(a.ingested_at,a.updated_at) DESC NULLS LAST, a.app_key DESC",
        "last_activity": "COALESCE(a.updated_at, a.ingested_at) DESC NULLS LAST, a.app_key DESC",
        "ready_for_review": "CASE WHEN a.status IN ('screening_complete','review_pending','ready_for_review') THEN 0 ELSE 1 END, COALESCE(a.updated_at, a.ingested_at) DESC NULLS LAST, a.app_key DESC",
        "assessment_complete": "CASE WHEN COALESCE(latest_assessment.assessment_status, a.raw_json->'assessment'->>'status')='completed' THEN 0 ELSE 1 END, COALESCE(a.updated_at, a.ingested_at) DESC NULLS LAST, a.app_key DESC",
        "ranking_score": "latest_eval.ranking_score DESC NULLS LAST, COALESCE(a.updated_at, a.ingested_at) DESC NULLS LAST, a.app_key DESC",
    }.get(sort_key, "COALESCE(a.ingested_at,a.updated_at) DESC NULLS LAST, a.app_key DESC")
    # Preserve one shared authority for rows and counts. Recruiter ownership is
    # distinct from role/intake assignment (`needs_role`, `import_review`).
    base_where = list(where)
    base_params = list(params)
    ownership_where = list(base_where)
    ownership_params = list(base_params)
    scope = str(owner_scope or "all").strip().lower()
    if scope not in {"all", "mine", "unassigned", "assigned"}:
        scope = "all"
    owner_filter = str(owner_user_id or "").strip()
    actor_filter = str(actor_user_id or "").strip()
    if scope == "mine":
        if not actor_filter:
            raise HTTPException(status_code=401, detail={"error": "dashboard_user_identity_required"})
        where.append("a.owner_user_id::text=%s")
        params.append(actor_filter)
    elif scope == "unassigned":
        where.append("a.owner_user_id IS NULL")
    elif scope == "assigned":
        where.append("a.owner_user_id IS NOT NULL")
    if owner_filter:
        where.append("a.owner_user_id::text=%s")
        params.append(owner_filter)
    tag_filter = str(tag_id or "").strip()
    if tag_filter:
        tag_predicate = (
            "EXISTS (SELECT 1 FROM application_tags atf "
            "WHERE atf.company_code=a.company_code AND atf.app_key=a.app_key "
            "AND atf.tag_id::text=%s)"
        )
        where.append(tag_predicate)
        params.append(tag_filter)
        ownership_where.append(tag_predicate)
        ownership_params.append(tag_filter)
    if classification_ui and parsed_classification and parsed_classification.get("active"):  # TALENT_POOL_CLASSIFICATION_COMPLETE_UI_PATCH: classification EXISTS filter
        try:
            class_sql, class_params = _tpc.classification_filter_sql(
                company_code=company_code,
                filters=parsed_classification,
                applications_alias="a",
            )
            if class_sql and class_sql.strip() != "TRUE":
                where.append(f"({class_sql})")
                params.extend(class_params)
        except Exception:
            pass
    count_where_sql = " AND ".join(where)
    count_params = list(params)
    cursor_at = ""
    cursor_key = ""
    if cursor:
        if "|" not in str(cursor):
            raise HTTPException(status_code=400, detail={"error": "cursor_invalid"})
        if sort_key != "newest":
            raise HTTPException(status_code=400, detail={"error": "cursor_sort_unsupported"})
        if offset:
            raise HTTPException(status_code=400, detail={"error": "cursor_offset_conflict"})
        cursor_at, cursor_key = str(cursor).split("|", 1)
        cursor_at, cursor_key = cursor_at.strip(), cursor_key.strip()
        if cursor_at and cursor_key:
            where.append(
                "(COALESCE(a.ingested_at,a.updated_at), a.app_key) < (%s::timestamptz,%s)"
            )
            params.extend([cursor_at, cursor_key])
    where_sql = " AND ".join(where)
    ownership_where_sql = " AND ".join(ownership_where)
    joins_sql = """
                LEFT JOIN candidates c ON c.phone=a.phone
                LEFT JOIN dashboard_users owner_user
                  ON owner_user.company_code=a.company_code
                 AND owner_user.user_id=a.owner_user_id
                LEFT JOIN candidate_record_governance gov
                  ON gov.company_code=a.company_code AND gov.app_key=a.app_key
                LEFT JOIN semantic_documents sd
                  ON sd.entity_type='application' AND sd.entity_key=a.app_key
                LEFT JOIN LATERAL (
                  SELECT
                    aa.status AS assessment_status,
                    aa.delivery_status AS assessment_delivery_status,
                    to_jsonb(aa) || jsonb_build_object('percent', s.percent, 'band', s.band, 'completed_at', aa.completed_at) AS assessment_json
                  FROM assessment_attempts aa
                  LEFT JOIN assessment_scores s ON s.attempt_id=aa.attempt_id
                  WHERE aa.company_code=a.company_code AND aa.app_key=a.app_key
                  ORDER BY aa.updated_at DESC, aa.created_at DESC
                  LIMIT 1
                ) latest_assessment ON TRUE
                LEFT JOIN LATERAL (
                  SELECT ci.status AS interview_status, to_jsonb(ci) AS interview_json
                  FROM candidate_interviews ci
                  WHERE ci.company_code=a.company_code AND ci.app_key=a.app_key
                  ORDER BY ci.scheduled_start DESC NULLS LAST, ci.updated_at DESC
                  LIMIT 1
                ) latest_interview ON TRUE
                LEFT JOIN LATERAL (
                  SELECT
                    cre.deterministic_score AS ranking_score,
                    jsonb_build_object(
                      'score', cre.deterministic_score,
                      'score_breakdown', cre.score_breakdown,
                      'role_profile', cre.role_profile,
                      'gpt_evaluation', cre.gpt_evaluation,
                      'evidence_digest', cre.evidence_digest,
                      'evaluation_audit', jsonb_build_object('model', cre.model, 'source', cre.source, 'created_at', cre.created_at)
                    ) AS rank_evaluation_json
                  FROM candidate_rank_evaluations cre
                  WHERE cre.company_code=a.company_code AND cre.app_key=a.app_key
                  ORDER BY CASE cre.source WHEN 'profile_evaluation' THEN 0 ELSE 1 END, cre.created_at DESC
                  LIMIT 1
                ) latest_eval ON TRUE
                LEFT JOIN LATERAL (
                  SELECT to_jsonb(ode) AS communication_json
                  FROM outbound_delivery_events ode
                  WHERE ode.subject_key=a.app_key
                    AND (ode.company_code=a.company_code OR ode.company_code IS NULL)
                  ORDER BY ode.created_at DESC
                  LIMIT 1
                ) latest_delivery ON TRUE
                LEFT JOIN LATERAL (
                  SELECT to_jsonb(ht) AS review_task_json
                  FROM hr_tasks ht
                  WHERE ht.company_code=a.company_code
                    AND ht.task_type='candidate_ready_for_review'
                    AND ht.metadata->>'app_key'=a.app_key
                  ORDER BY ht.created_at DESC
                  LIMIT 1
                ) latest_review_task ON TRUE
                LEFT JOIN LATERAL (
                  SELECT to_jsonb(ale) AS lifecycle_event_json
                  FROM application_lifecycle_events ale
                  WHERE ale.company_code=a.company_code AND ale.app_key=a.app_key
                  ORDER BY ale.created_at DESC
                  LIMIT 1
                ) latest_lifecycle_event ON TRUE
                LEFT JOIN LATERAL (
                  SELECT count(*) FILTER (WHERE t.status='open') AS open_task_count,
                         count(*) FILTER (WHERE t.status='open' AND t.due_at < now()) AS overdue_task_count
                  FROM application_recruiter_tasks t
                  WHERE t.company_code=a.company_code AND t.app_key=a.app_key
                ) c2_tasks ON TRUE
                LEFT JOIN LATERAL (
                  SELECT COALESCE(
                    jsonb_agg(
                      jsonb_build_object(
                        'tag_id', td.tag_id,
                        'company_code', td.company_code,
                        'label', td.name,
                        'label_ar', td.label_ar,
                        'color', td.color,
                        'active', td.is_active
                      )
                      ORDER BY td.canonical_name
                    ),
                    '[]'::jsonb
                  ) AS tags_json
                  FROM application_tags atg
                  JOIN candidate_tag_dictionary td
                    ON td.company_code=atg.company_code AND td.tag_id=atg.tag_id
                  WHERE atg.company_code=a.company_code AND atg.app_key=a.app_key
                ) c2_tags ON TRUE
    """
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT COUNT(*) AS count
                FROM applications a
                {joins_sql}
                WHERE {count_where_sql}
                """,
                count_params,
            )
            total = int((cur.fetchone() or {}).get("count") or 0)
            cur.execute(
                f"""
                SELECT
                  count(*) AS all_count,
                  count(*) FILTER (WHERE a.owner_user_id::text=%s) AS mine_count,
                  count(*) FILTER (WHERE a.owner_user_id IS NULL) AS unassigned_count,
                  count(*) FILTER (WHERE a.owner_user_id IS NOT NULL) AS assigned_count
                FROM applications a
                {joins_sql}
                WHERE {ownership_where_sql}
                """,
                [actor_filter, *ownership_params],
            )
            ownership_row = dict(cur.fetchone() or {})
            cur.execute(
                f"""
                SELECT a.*, c.name AS candidate_name, c.email AS candidate_email,
                       c.profile AS candidate_profile, c.raw_json AS candidate_raw_json,
                       latest_assessment.assessment_json,
                       latest_interview.interview_json,
                       latest_eval.rank_evaluation_json,
                       latest_delivery.communication_json,
                       latest_review_task.review_task_json,
                       latest_lifecycle_event.lifecycle_event_json,
                       owner_user.name AS owner_name,
                       owner_user.email AS owner_email,
                       owner_user.role AS owner_role,
                       owner_user.status AS owner_status,
                       COALESCE(c2_tasks.open_task_count,0) AS open_task_count,
                       COALESCE(c2_tasks.overdue_task_count,0) AS overdue_task_count,
                       c2_tags.tags_json,
                       to_jsonb(gov.*) AS governance_json,
                       sd.content AS semantic_content
                FROM applications a
                {joins_sql}
                WHERE {where_sql}
                ORDER BY {order_sql}
                LIMIT %s OFFSET %s
                """,
                [*params, limit, offset],
            )
            rows = [dict(row) for row in cur.fetchall()]
            classification_by_app = {}  # TALENT_POOL_CLASSIFICATION_COMPLETE_UI_PATCH: bulk classification projection
            if classification_ui and rows:
                try:
                    app_keys = [str(r.get("app_key") or "") for r in rows if r.get("app_key")]
                    classification_by_app = _tpc.bulk_load_classification_rows(
                        cur,
                        company_code=company_code,
                        app_keys=app_keys,
                    )
                    for row in rows:
                        key = str(row.get("app_key") or "")
                        projection = (classification_by_app.get(key) or {}).get("projection") or {}
                        row["_classification_projection"] = projection
                except Exception:
                    for row in rows:
                        row["_classification_projection"] = {}
            cur.execute(
                """
                SELECT user_id, name, email, role, status
                FROM dashboard_users
                WHERE company_code=%s
                  AND status='active'
                  AND role IN ('owner','hr_admin','hr_manager','recruiter','hiring_manager')
                ORDER BY lower(name), lower(email), user_id
                """,
                (company_code,),
            )
            recruiters = []
            for source_user in cur.fetchall():
                user = dict(source_user)
                if "candidates.read" not in dashboard_effective_permissions_for_user(user, cur=cur):
                    continue
                recruiters.append(json_safe(user))
    next_cursor = None
    if len(rows) == limit and rows:
        last = rows[-1]
        stamp = last.get("ingested_at") or last.get("updated_at")
        if stamp:
            next_cursor = f"{json_safe(stamp)}|{last.get('app_key')}"
    return {
        "total": total,
        "limit": limit,
        "offset": offset,
        "next_cursor": next_cursor,
        "ownership_counts": {
            "all": int(ownership_row.get("all_count") or 0),
            "mine": int(ownership_row.get("mine_count") or 0),
            "unassigned": int(ownership_row.get("unassigned_count") or 0),
            "assigned": int(ownership_row.get("assigned_count") or 0),
        },
        "recruiters": recruiters,
        "view": view_key or None,
        "unified_candidates": use_unified,
        "classification_filters": parsed_classification if classification_ui else None,  # TALENT_POOL_CLASSIFICATION_COMPLETE_UI_PATCH
        "applications": _unified_applications_payload(
            rows,
            include_assessment=include_assessment,
            permissions=permissions,
            use_unified=use_unified,
            include_match_reasons=include_match_reasons,
            search=search,
            _uc=_uc,
            prehire_application_summary=prehire_application_summary,
        ),
    }


ASSESSMENT_ERROR_MESSAGES = {
    "attempt_expired": ("This assessment link has expired.", "Send a new invitation to let the candidate continue."),
    "assessment_attempt_not_found": ("This assessment could not be found.", "Refresh the list and try again."),
    "assessment_resend_failed": ("The assessment could not be resent.", "Review the candidate contact details and try again."),
    "assessment_not_completed": ("This assessment is not completed yet.", "Wait for the candidate to finish before reviewing."),
    "terminal_application": ("This application is already closed.", "Assessments cannot be sent for a closed application."),
    "already_sent": ("An assessment invitation is already active.", "Resend only if the candidate needs a new link."),
    "delivery_failed": ("The invitation could not be delivered.", "Check the candidate email/WhatsApp and retry."),
    "report_not_ready": ("The report is not ready yet.", "Wait for scoring to finish before opening the report."),
    "stale_attempt": ("This assessment changed.", "Refresh and use the latest invitation."),
    "duplicate_request": ("This request was already processed.", "Refresh to see the current state."),
    "permission_denied": ("You do not have permission to do this action.", "Ask an admin for assessment access."),
    "module_disabled": ("Assessments are not enabled for this company.", "Enable assessments to send invitations."),
}


def assessment_error_envelope(code: str, *, locale: str = "en") -> dict[str, Any]:
    """Canonical error envelope so raw keys are never shown directly to HR."""
    normalized = str(code or "assessment_error").strip() or "assessment_error"
    message, next_step = ASSESSMENT_ERROR_MESSAGES.get(
        normalized,
        ("The assessment action could not be completed.", "Try again or refresh the page."),
    )
    return {
        "error": normalized,
        "message": message,
        "next_step": next_step,
        "safe_user_message": f"{message} {next_step}",
    }


def assessment_attempt_summary(row: dict[str, Any]) -> dict[str, Any]:
    total_items = int(row.get("total_items") or 0)
    answered_count = int(row.get("answered_count") or 0)
    percent_complete = round((answered_count / total_items) * 100, 1) if total_items else 0.0
    report = row.get("report_json") if isinstance(row.get("report_json"), dict) else {}
    section_scores = row.get("section_scores") if isinstance(row.get("section_scores"), dict) else report.get("section_scores", {})
    return {
        "attempt_id": str(row.get("attempt_id")),
        "company_code": row.get("company_code"),
        "app_key": row.get("app_key"),
        "phone": row.get("phone"),
        "candidate_name": row.get("candidate_name") or row.get("candidate_db_name"),
        "candidate_email": row.get("candidate_email"),
        "position_code": row.get("position_code"),
        "position_title": row.get("position_title") or row.get("position_code"),
        "application_status": row.get("application_status"),
        "battery_key": row.get("battery_key"),
        "assessment_version_id": str(row.get("assessment_version_id")) if row.get("assessment_version_id") else None,
        "status": row.get("status"),
        "delivery_status": row.get("delivery_status"),
        "delivery_status_label": prehire_report_status_label(row.get("delivery_status")),
        "review_status": row.get("review_status"),
        "current_item_index": int(row.get("current_item_index") or 0),
        "progress_version": int(row.get("progress_version") or 0),
        "total_items": total_items,
        "answered_count": answered_count,
        "percent_complete": percent_complete,
        "raw_score": json_safe(row.get("raw_score")),
        "max_score": json_safe(row.get("max_score")),
        "percent": json_safe(row.get("percent")),
        "band": row.get("band"),
        "section_scores": json_safe(section_scores or {}),
        "ability_scores": json_safe(report.get("ability_scores") if isinstance(report, dict) else {}),
        "competency_profile": json_safe(report.get("competency_profile") if isinstance(report, dict) else {}),
        "job_match": json_safe(report.get("job_match") if isinstance(report, dict) else {}),
        "summary": report.get("summary") if isinstance(report, dict) else None,
        "report_json": json_safe(report) if report else None,
        "created_at": json_safe(row.get("created_at")),
        "expires_at": json_safe(row.get("expires_at")),
        "started_at": json_safe(row.get("started_at")),
        "completed_at": json_safe(row.get("completed_at")),
        "cancelled_at": json_safe(row.get("cancelled_at")),
        "cancel_reason": row.get("cancel_reason"),
        "expired_at": json_safe(row.get("expired_at")),
        "reviewed_at": json_safe(row.get("reviewed_at")),
        "reviewed_by_user_id": row.get("reviewed_by_user_id"),
        "review_notes": row.get("review_notes"),
        "updated_at": json_safe(row.get("updated_at")),
        "version": int(row.get("version") or 0) or None,
    }


def fetch_dashboard_assessment_report_payload(company: str, attempt_id: str) -> dict[str, Any]:
    import assessment_service as _assessment_service

    version: dict[str, Any] | None = None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                WITH response_counts AS (
                  SELECT attempt_id, COUNT(*) AS answered_count
                  FROM assessment_responses
                  GROUP BY attempt_id
                )
                SELECT
                  aa.*,
                  a.status AS application_status,
                  c.name AS candidate_db_name,
                  c.email AS candidate_email,
                  COALESCE(rc.answered_count, 0) AS answered_count,
                  s.raw_score,
                  s.max_score,
                  s.percent,
                  s.band,
                  s.section_scores,
                  s.score_json,
                  r.report_json
                FROM assessment_attempts aa
                LEFT JOIN applications a ON a.app_key=aa.app_key AND a.company_code=aa.company_code
                LEFT JOIN candidates c ON c.phone=aa.phone
                LEFT JOIN response_counts rc ON rc.attempt_id=aa.attempt_id
                LEFT JOIN assessment_scores s ON s.attempt_id=aa.attempt_id
                LEFT JOIN assessment_reports r ON r.attempt_id=aa.attempt_id
                WHERE aa.attempt_id=%s AND aa.company_code=%s
                LIMIT 1
                """,
                (attempt_id, company),
            )
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail={"error": "assessment_attempt_not_found"})
            attempt = assessment_attempt_summary(dict(row))
            if attempt.get("assessment_version_id"):
                version = _assessment_service.content_version_by_id(
                    cur,
                    str(attempt["assessment_version_id"]),
                    company_code=company,
                )
            cur.execute(
                """
                SELECT
                  ar.item_id,
                  ar.item_order,
                  ar.selected_key,
                  ar.is_correct,
                  ar.score_numeric,
                  ar.created_at,
                  ar.answer_key_snapshot,
                  ar.scoring_snapshot,
                  ar.item_content_version
                FROM assessment_responses ar
                WHERE ar.attempt_id=%s AND ar.company_code=%s
                ORDER BY ar.item_order ASC
                """,
                (attempt_id, company),
            )
            responses = [json_safe(dict(item)) for item in cur.fetchall()]
    frozen_items = {
        str(item.get("item_id")): item
        for item in _assessment_service.version_items(version)
    }
    responses = [
        {
            **(frozen_items.get(str(response.get("item_id"))) or {}),
            **response,
        }
        for response in responses
    ]
    report = attempt.get("report_json") if isinstance(attempt.get("report_json"), dict) else {}
    if attempt.get("status") == "completed" and responses and not report.get("report_sections"):
        if not version:
            raise HTTPException(
                status_code=409,
                detail={"error": "assessment_version_missing", "message": "Immutable assessment evidence is unavailable."},
            )
        report = build_assessment_report_json(
            attempt=attempt,
            items=_assessment_service.version_items(version),
            responses=responses,
            norm_lookup=_assessment_service.version_norm_lookup(version),
        )
        attempt["report_json"] = json_safe(report)
    import assessment_report_presentation as _arp
    presentation = _arp.build_assessment_report_presentation(
        attempt=attempt,
        report=attempt.get("report_json") if isinstance(attempt.get("report_json"), dict) else {},
    )
    return {
        "company_code": company,
        "ok": True,
        "attempt": attempt,
        "report": attempt.get("report_json") or {},
        "report_presentation": presentation,
        "responses": responses,
    }


def assessment_report_html(payload: dict[str, Any]) -> HTMLResponse:
    attempt = payload.get("attempt") if isinstance(payload.get("attempt"), dict) else {}
    report = payload.get("report") if isinstance(payload.get("report"), dict) else {}
    job_match = report.get("job_match") if isinstance(report.get("job_match"), dict) else {}
    sections = report.get("report_sections") if isinstance(report.get("report_sections"), dict) else {}
    ability = sections.get("verify_ability", {}).get("sections", {}) if isinstance(sections.get("verify_ability"), dict) else {}
    competency_groups = sections.get("competency_profile", {}).get("groups", []) if isinstance(sections.get("competency_profile"), dict) else []
    probes = sections.get("interview_probes") if isinstance(sections.get("interview_probes"), list) else []

    def esc(value: Any) -> str:
        return html.escape(str(value if value is not None else ""))

    ability_rows = "".join(
        f"<tr><td>{esc(key.replace('_', ' ').title())}</td><td>{esc(score.get('percent'))}%</td><td>{esc(score.get('percentile'))}</td><td>{esc(score.get('t_score'))}</td><td>{esc(score.get('sten'))}</td><td>{esc(score.get('band'))}</td></tr>"
        for key, score in ability.items()
        if isinstance(score, dict)
    )
    competency_rows = ""
    for group in competency_groups:
        for competency in (group.get("competencies", []) if isinstance(group, dict) else []):
            competency_rows += (
                f"<tr><td>{esc(group.get('label'))}</td><td>{esc(competency.get('key', '').replace('_', ' ').title())}</td>"
                f"<td>{esc(competency.get('score'))}</td><td>{esc(competency.get('band'))}</td></tr>"
            )
    probe_items = "".join(f"<li><strong>{esc(item.get('competency'))}</strong>: {esc(item.get('question'))}</li>" for item in probes if isinstance(item, dict))
    return HTMLResponse(
        f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Assessment Report - {esc(attempt.get('candidate_name') or attempt.get('phone') or attempt.get('attempt_id'))}</title>
  <style>
    :root {{ font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #09090b; background: #fafafa; }}
    body {{ margin: 0; }}
    main {{ max-width: 1040px; margin: 0 auto; padding: 32px 24px 56px; }}
    header {{ border-bottom: 1px solid #e4e4e7; margin-bottom: 24px; padding-bottom: 18px; }}
    h1 {{ font-size: 28px; margin: 0 0 8px; letter-spacing: -0.03em; }}
    h2 {{ font-size: 18px; margin: 0 0 12px; }}
    .muted {{ color: #71717a; }}
    .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px; }}
    .card {{ background: #fff; border: 1px solid #e4e4e7; border-radius: 16px; padding: 18px; margin: 16px 0; box-shadow: 0 1px 2px rgba(9,9,11,.05); }}
    .metric {{ font-size: 26px; font-weight: 750; }}
    table {{ width: 100%; border-collapse: collapse; font-size: 14px; }}
    th, td {{ text-align: left; border-bottom: 1px solid #e4e4e7; padding: 10px; vertical-align: top; }}
    th {{ color: #71717a; font-size: 12px; text-transform: uppercase; letter-spacing: .06em; }}
    li {{ margin: 8px 0; }}
  </style>
</head>
<body>
  <main>
    <header>
      <div class="muted">OctoHR Assessment Report / Official deterministic score JSON</div>
      <h1>{esc(attempt.get('candidate_name') or attempt.get('phone') or 'Candidate')}</h1>
      <div class="muted">{esc(attempt.get('position_title') or attempt.get('position_code') or 'Role')} / {esc(job_match.get('role_profile_label') or 'General Role')}</div>
    </header>
    <section class="grid">
      <div class="card"><div class="muted">Overall score</div><div class="metric">{esc(report.get('percent'))}%</div><div>{esc(report.get('band'))}</div></div>
      <div class="card"><div class="muted">Job match</div><div class="metric">{esc(job_match.get('job_match_percent'))}%</div><div>{esc(job_match.get('fit_band'))}</div></div>
      <div class="card"><div class="muted">Ability fit</div><div class="metric">{esc(job_match.get('ability_fit_percent'))}%</div></div>
      <div class="card"><div class="muted">Competency fit</div><div class="metric">{esc(job_match.get('competency_fit_percent'))}%</div></div>
    </section>
    <section class="card">
      <h2>Ability Scores</h2>
      <table><thead><tr><th>Section</th><th>Score</th><th>Percentile</th><th>T-score</th><th>Sten</th><th>Band</th></tr></thead><tbody>{ability_rows}</tbody></table>
    </section>
    <section class="card">
      <h2>Competency Profile</h2>
      <table><thead><tr><th>Group</th><th>Competency</th><th>Score 1-5</th><th>Band</th></tr></thead><tbody>{competency_rows}</tbody></table>
    </section>
    <section class="card">
      <h2>Strengths and Development</h2>
      <p><strong>Strengths:</strong> {esc(', '.join(job_match.get('strengths') or []) or 'Not enough evidence yet')}</p>
      <p><strong>Development areas:</strong> {esc(', '.join(job_match.get('development_areas') or []) or 'Not enough evidence yet')}</p>
    </section>
    <section class="card">
      <h2>Structured Interview Probes</h2>
      <ul>{probe_items}</ul>
    </section>
    <section class="card muted">
      Scores are deterministic and auditable. AI may summarize this report, but must not change scores, bands, role-match logic, or norm version.
    </section>
  </main>
</body>
</html>"""
    )


def dashboard_assessments_payload(
    company: str,
    *,
    status: str | None = None,
    position: str | None = None,
    limit: int = 100,
    offset: int = 0,
    needs_review: bool = False,
    visibility_sql: str | None = None,
    visibility_params: list[Any] | None = None,
    summary_visibility_sql: str | None = None,
    summary_visibility_params: list[Any] | None = None,
) -> dict[str, Any]:
    """Attempts list + attempt-axis totals under one shared visibility scope.

    Attempt status_counts / average / needs_review / report-ready use the same
    detail/user-visible scope as the opened Attempts list (never a wider
    company-wide summary that opens into a smaller list).
    """
    import assessments_queue_contract as _aqc
    import assessment_cohorts as _ac

    # Prefer explicit summary scope; default to the list/detail scope.
    sum_vis = str(
        summary_visibility_sql if summary_visibility_sql is not None else (visibility_sql or "")
    ).strip()
    sum_vis_params = list(
        summary_visibility_params
        if summary_visibility_params is not None
        else (visibility_params or [])
    )
    list_vis = str(visibility_sql or "").strip()
    list_vis_params = list(visibility_params or [])

    where = ["aa.company_code=%s", reviewable_application_predicate("a")]
    params: list[Any] = [company]
    if status:
        where.append("aa.status=%s")
        params.append(status)
    if needs_review:
        where.append(_aqc.needs_review_predicate("aa"))
    if position:
        where.append("(aa.position_code ILIKE %s OR aa.position_title ILIKE %s)")
        params.extend([f"%{position}%", f"%{position.replace('_', ' ')}%"])
    if list_vis:
        where.append(f"({list_vis})")
        params.extend(list_vis_params)
    where_sql = " AND ".join(where)

    # Attempt-axis summary shares the same visibility as the list.
    summary_where = ["aa.company_code=%s", reviewable_application_predicate("a")]
    summary_params: list[Any] = [company]
    if sum_vis:
        summary_where.append(f"({sum_vis})")
        summary_params.extend(sum_vis_params)
    summary_where_sql = " AND ".join(summary_where)

    limit_value = bounded_limit(limit)
    offset_value = max(0, int(offset or 0))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT aa.status, COUNT(*) AS count
                FROM assessment_attempts aa
                LEFT JOIN applications a ON a.app_key=aa.app_key AND a.company_code=aa.company_code
                WHERE {summary_where_sql}
                GROUP BY aa.status
                ORDER BY count DESC, aa.status
                """,
                summary_params,
            )
            status_counts = [json_safe(dict(row)) for row in cur.fetchall()]
            # Attempts tab total = every historical attempt under scope.
            total_all_attempts = sum(int(row["count"]) for row in status_counts)

            cur.execute(
                f"""
                SELECT AVG(s.percent) AS average_percent
                FROM assessment_attempts aa
                LEFT JOIN applications a ON a.app_key=aa.app_key AND a.company_code=aa.company_code
                LEFT JOIN assessment_scores s ON s.attempt_id=aa.attempt_id
                WHERE {summary_where_sql} AND aa.status='completed' AND s.percent IS NOT NULL
                """,
                summary_params,
            )
            avg_row = cur.fetchone() or {}
            raw_average = avg_row.get("average_percent")
            average_percent = round(float(raw_average), 1) if raw_average is not None else None

            # assessments.review.* — full scoped totals (not page-local).
            cur.execute(
                f"""
                SELECT COUNT(*) AS count
                FROM assessment_attempts aa
                LEFT JOIN applications a ON a.app_key=aa.app_key AND a.company_code=aa.company_code
                WHERE {summary_where_sql} AND {_aqc.needs_review_predicate("aa")}
                """,
                summary_params,
            )
            needs_review_count = int((cur.fetchone() or {}).get("count") or 0)
            cur.execute(
                f"""
                SELECT COUNT(*) AS count
                FROM assessment_attempts aa
                LEFT JOIN applications a ON a.app_key=aa.app_key AND a.company_code=aa.company_code
                WHERE {summary_where_sql} AND {_aqc.report_ready_predicate("aa")}
                """,
                summary_params,
            )
            report_ready_count = int((cur.fetchone() or {}).get("count") or 0)

            # Opened list total under the active list filters (status / needs_review).
            cur.execute(
                f"""
                SELECT COUNT(*) AS count
                FROM assessment_attempts aa
                LEFT JOIN applications a ON a.app_key=aa.app_key AND a.company_code=aa.company_code
                WHERE {where_sql}
                """,
                params,
            )
            list_total = int((cur.fetchone() or {}).get("count") or 0)

            cur.execute(
                f"""
                WITH response_counts AS (
                  SELECT attempt_id, COUNT(*) AS answered_count
                  FROM assessment_responses
                  GROUP BY attempt_id
                )
                SELECT
                  aa.*,
                  a.status AS application_status,
                  c.name AS candidate_db_name,
                  c.email AS candidate_email,
                  COALESCE(rc.answered_count, 0) AS answered_count,
                  s.raw_score,
                  s.max_score,
                  s.percent,
                  s.band,
                  s.section_scores,
                  r.report_json
                FROM assessment_attempts aa
                LEFT JOIN applications a ON a.app_key=aa.app_key AND a.company_code=aa.company_code
                LEFT JOIN candidates c ON c.phone=aa.phone
                LEFT JOIN response_counts rc ON rc.attempt_id=aa.attempt_id
                LEFT JOIN assessment_scores s ON s.attempt_id=aa.attempt_id
                LEFT JOIN assessment_reports r ON r.attempt_id=aa.attempt_id
                WHERE {where_sql}
                ORDER BY aa.updated_at DESC, aa.created_at DESC, aa.attempt_id
                LIMIT %s OFFSET %s
                """,
                [*params, limit_value, offset_value],
            )
            attempts = [assessment_attempt_summary(dict(row)) for row in cur.fetchall()]

    import assessment_presentation as _ap

    presented = []
    for attempt in attempts:
        presentation = _ap.build_assessment_presentation(attempt=attempt, can_manage=True)
        attempt["presentation"] = presentation
        attempt["needs_review"] = presentation.get("needs_review")
        presented.append(attempt)

    cohorts_payload = _ac.compute_assessment_cohorts(
        company=company,
        db_connect=db_connect,
        assessments_enabled=True,
        visibility_sql=list_vis or None,
        visibility_params=list_vis_params or None,
    )

    return {
        "company_code": company,
        "ok": True,
        "total": list_total,
        "attempts_total": total_all_attempts,
        "limit": limit_value,
        "offset": offset_value,
        "status_counts": status_counts,
        "average_percent": average_percent,
        "attempts": presented,
        "needs_review_count": needs_review_count,
        "report_ready_count": report_ready_count,
        "cohorts": cohorts_payload,
        "filter": {
            "status": status or None,
            "needs_review": bool(needs_review),
            "position": position or None,
        },
    }


def dashboard_assessment_config_payload(company: str) -> dict[str, Any]:
    battery = active_assessment_battery(company)
    selectable = list_selectable_assessment_batteries(company)
    battery_key = str((battery or {}).get("battery_key") or ASSESSMENT_BATTERY_KEY)
    validation = validate_assessment_item_bank()
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT section, difficulty, COUNT(*) AS count
                FROM assessment_items
                WHERE battery_key=%s
                GROUP BY section, difficulty
                ORDER BY section, difficulty
                """,
                (battery_key,),
            )
            item_counts = [json_safe(dict(row)) for row in cur.fetchall()]
            cur.execute(
                """
                SELECT norm_key, company_code, battery_key, section, sample_size, source, is_active, updated_at, raw_json
                FROM assessment_norm_groups
                WHERE battery_key=%s AND company_code IN (%s, 'GLOBAL') AND is_active IS TRUE
                ORDER BY CASE WHEN company_code=%s THEN 0 ELSE 1 END, section, updated_at DESC
                """,
                (battery_key, company, company),
            )
            norm_groups = [json_safe(dict(row)) for row in cur.fetchall()]
    section_totals: dict[str, int] = {}
    difficulty_totals: dict[str, int] = {}
    for row in item_counts:
        section = str(row.get("section") or "unknown")
        difficulty = str(row.get("difficulty") or "unknown")
        count = int(row.get("count") or 0)
        section_totals[section] = section_totals.get(section, 0) + count
        difficulty_totals[difficulty] = difficulty_totals.get(difficulty, 0) + count
    available_batteries = []
    for row in selectable:
        raw = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
        available_batteries.append(
            {
                "battery_key": row.get("battery_key"),
                "company_code": row.get("company_code"),
                "name": row.get("name"),
                "version": row.get("version"),
                "is_active": row.get("is_active"),
                "locale": raw.get("locale"),
                "approved_for_use_status": raw.get("approved_for_use_status")
                or ("approved_for_use_beta" if raw.get("approved_for_use_beta") else ("active" if row.get("is_active") else None)),
                "scores_are_supporting_evidence_only": bool(raw.get("scores_are_supporting_evidence_only")),
                "selectable_for_hr_send": bool(raw.get("selectable_for_hr_send") or row.get("is_active")),
                "assessment_version_id": raw.get("frozen_assessment_version_id"),
                "content_sha256": raw.get("frozen_content_sha256"),
            }
        )
    return {
        "company_code": company,
        "ok": True,
        "battery": json_safe(battery) if battery else None,
        "available_batteries": available_batteries,
        "item_bank": {
            "total_items": sum(section_totals.values()),
            "section_totals": section_totals,
            "difficulty_totals": difficulty_totals,
            "validation": validation,
            "content_policy": "original_wathefni_items_no_shl_proprietary_text",
        },
        "framework": NBK_COMPETENCY_FRAMEWORK,
        "role_profiles": json_safe(NBK_ROLE_PROFILES),
        "norms": {
            "active_norm_version": ASSESSMENT_NORM_VERSION,
            "groups": norm_groups,
            "status": "empirical_ready" if any(int(group.get("sample_size") or 0) >= 200 for group in norm_groups) else "synthetic_until_client_benchmark",
            "minimum_recommended_sample": 200,
        },
        "guardrails": {
            "deterministic_scoring": True,
            "ai_may_change_scores": False,
            "unknown_jobs_use_general_profile_until_profiled": True,
            "beta_scores_supporting_evidence_only": True,
            "no_automatic_hiring_actions": True,
        },
    }


