@app.get("/dashboard/prehire/chat/sessions/{conversation_id}")
def dashboard_prehire_chat_session_detail(conversation_id: str, context: dict[str, Any] = Depends(assistant_dashboard_context)):
    ensure_schema()
    conversation_id = dashboard_chat_conversation_id(context, conversation_id)
    with db_connect() as conn:
        with conn.cursor() as cur:
            session = dashboard_chat_session_allowed(cur, context, conversation_id)
            if not session:
                raise HTTPException(status_code=404, detail={"error": "chat_session_not_found"})
            cur.execute(
                """
                SELECT message_id, role, text, payload, created_at
                FROM dashboard_chat_messages
                WHERE conversation_id=%s
                ORDER BY created_at ASC
                LIMIT 200
                """,
                (conversation_id,),
            )
            messages = []
            for row in cur.fetchall():
                item = json_safe(dict(row))
                payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
                confirmation = active_dashboard_confirmation(cur, payload.get("confirmation") if isinstance(payload.get("confirmation"), dict) else None)
                payload = {**payload, "confirmation": confirmation}
                item["payload"] = payload
                messages.append(item)
    return {"session": session, "messages": messages}


