@app.post("/dashboard/prehire/chat/stream")
def dashboard_prehire_chat_stream(
    request: DashboardChatRequest,
    http_request: Request,
    context: dict[str, Any] = Depends(assistant_dashboard_context),
):
    import queue
    import threading

    progress_q: queue.Queue = queue.Queue()
    cancel_event = threading.Event()
    done_holder: dict[str, Any] = {}

    def on_progress(event: dict[str, Any]) -> None:
        progress_q.put(event)

    def worker() -> None:
        try:
            # Attach progress/cancel into the turn via a thin wrapper around the response builder.
            ensure_schema()
            company = context["company_code"]
            hr_phone = digits(context.get("hr_phone")) or digits((context.get("hr_user") or {}).get("phone")) or "dashboard"
            conversation_id = dashboard_chat_conversation_id(context, request.conversation_id)
            with db_connect() as conn:
                with conn.cursor() as cur:
                    upsert_dashboard_chat_session(
                        cur,
                        context,
                        conversation_id,
                        metadata={"page": request.page, "selected_app_key": request.selected_app_key},
                    )
                    record_dashboard_chat_message(
                        cur,
                        context,
                        conversation_id,
                        "user",
                        request.message,
                        {"page": request.page, "selected_app_key": request.selected_app_key},
                    )
                conn.commit()
            turn_request = WhatsAppTurnRequest(
                account_id="default",
                conversation_id=conversation_id,
                sender_phone=hr_phone,
                sender_role="hr_admin",
                raw_text=request.message,
                metadata={
                    "channel": "web_dashboard",
                    "dashboard": True,
                    DASHBOARD_TURN_AUTHORITY_KEY: _DASHBOARD_TURN_AUTHORITY_NONCE,
                    "company_code": company,
                    "page": request.page,
                    "selected_app_key": request.selected_app_key,
                    "admin_user": context.get("hr_user"),
                    "access": context.get("access"),
                    "permissions": context.get("permissions") or [],
                    "assistant_entry": "toolcall_orchestrator",
                    "legacy_regex_inference_enabled": LEGACY_REGEX_INFERENCE_ENABLED,
                    "legacy_path_inactive": not LEGACY_REGEX_INFERENCE_ENABLED,
                    "on_progress": on_progress,
                    "cancel_event": cancel_event,
                    "locale": getattr(request, "locale", None),
                },
            )
            from tool_call_orchestrator import handle_toolcall_whatsapp_turn

            result = handle_toolcall_whatsapp_turn(turn_request)
            artifacts = dashboard_chat_artifacts(result, request, company_code=context.get("company_code"))
            audit = result.get("audit") if isinstance(result.get("audit"), dict) else {}
            response = DashboardChatResponse(
                reply_text=str(result.get("reply_text") or "I could not produce a dashboard reply."),
                intent=result.get("intent"),
                turn_id=str(audit.get("turn_id") or ""),
                candidate_cards=artifacts["candidate_cards"],
                navigation=artifacts["navigation"],
                confirmation=artifacts["confirmation"],
                workflow_card=artifacts.get("workflow_card"),
                session={"conversation_id": conversation_id},
                audit={
                    "memory_scope": audit.get("memory_scope"),
                    "turn_id": audit.get("turn_id"),
                    "tool_output_count": len(audit.get("tool_outputs") or []) if isinstance(audit.get("tool_outputs"), list) else 0,
                    "correlation_id": audit.get("correlation_id"),
                    "capability_offerable": (audit.get("capability_catalog") or {}).get("offerable")
                    if isinstance(audit.get("capability_catalog"), dict)
                    else None,
                },
            )
            title = dashboard_chat_session_title(request.message, response)
            with db_connect() as conn:
                with conn.cursor() as cur:
                    session = upsert_dashboard_chat_session(
                        cur,
                        context,
                        conversation_id,
                        title=title,
                        metadata={
                            "page": request.page,
                            "selected_app_key": request.selected_app_key,
                            "last_intent": response.intent,
                            "last_turn_id": response.turn_id,
                        },
                    )
                    record_dashboard_chat_message(
                        cur,
                        context,
                        conversation_id,
                        "assistant",
                        response.reply_text,
                        {
                            "candidate_cards": response.candidate_cards,
                            "navigation": response.navigation,
                            "confirmation": response.confirmation,
                            "workflow_card": response.workflow_card,
                            "intent": response.intent,
                            "turn_id": response.turn_id,
                        },
                    )
                conn.commit()
            response.session = {
                "conversation_id": conversation_id,
                "title": session.get("title") or title,
                "updated_at": session.get("updated_at"),
            }
            done_holder["response"] = response
        except Exception as exc:
            done_holder["error"] = exc
        finally:
            progress_q.put(None)

    def generate():
        yield dashboard_chat_stream_event({"type": "typing", "phase": "planning"})
        thread = threading.Thread(target=worker, daemon=True)
        thread.start()
        while True:
            if http_request is not None:
                try:
                    # Starlette Request.is_disconnected is async; best-effort sync probe via scope.
                    if getattr(http_request, "is_disconnected", None) and False:
                        pass
                except Exception:
                    pass
            try:
                item = progress_q.get(timeout=0.4)
            except queue.Empty:
                if cancel_event.is_set():
                    break
                # Client disconnect: Starlette exposes receive; we mark cancel when thread still running
                # and the generator is being closed (GeneratorExit handled below).
                continue
            if item is None:
                break
            if isinstance(item, dict):
                yield dashboard_chat_stream_event(item if item.get("type") else {"type": "progress", **item})
        thread.join(timeout=5)
        if done_holder.get("error"):
            yield dashboard_chat_stream_event(
                {
                    "type": "error",
                    "message": "I hit an issue while answering. Try again in a moment.",
                    "detail": str(done_holder["error"])[:300],
                }
            )
            return
        response = done_holder.get("response")
        if response is None:
            yield dashboard_chat_stream_event(
                {
                    "type": "error",
                    "message": "Stopped before a reply was ready.",
                }
            )
            return
        # Emit final reply once — no fake token drip. Progress events already streamed live states.
        text = response.reply_text or ""
        if text:
            yield dashboard_chat_stream_event({"type": "delta", "text": text})
        yield dashboard_chat_stream_event(
            {
                "type": "done",
                "message": response.model_dump() if hasattr(response, "model_dump") else response.dict(),
            }
        )

    def guarded_generate():
        try:
            yield from generate()
        except GeneratorExit:
            cancel_event.set()
            raise

    return StreamingResponse(
        guarded_generate(),
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )


@app.get("/dashboard/prehire/applications/{app_key}")
def dashboard_prehire_application_detail(app_key: str, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    company = context["company_code"]
    application = find_application_by_key(app_key, company_code=company)
    if not application:
        raise HTTPException(status_code=404, detail={"error": "application_not_found"})
    require_prehire_application_visibility(context, application)
    app_payload = prehire_application_summary(
        application,
        include_raw=True,
        include_assessment=company_has_module(company, "assessments"),
        permissions=context.get("permissions") or [],
    )
    latest_evaluation = latest_application_rank_evaluation(company, app_key)
    if latest_evaluation:
        app_payload["ranking"] = latest_evaluation
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT file_id, file_kind, document_type, original_filename, storage_provider,
                       storage_url, storage_status, storage_error, stored_at, updated_at
                FROM file_registry
                WHERE company_code=%s
                  AND subject_type='application'
                  AND subject_key=%s
                ORDER BY updated_at DESC, created_at DESC
                LIMIT 25
                """,
                (company, app_key),
            )
            files = [json_safe(dict(row)) for row in cur.fetchall()]
            cur.execute(
                """
                SELECT delivery_id, account_id, target_phone, target_conversation_id, subject_type,
                       subject_key, status, last_error, sent_at, failed_at, created_at, updated_at
                FROM outbound_delivery_events
                WHERE subject_key=%s
                  AND (company_code=%s OR company_code IS NULL)
                ORDER BY created_at DESC
                LIMIT 25
                """,
                (app_key, company),
            )
            deliveries = []
            for row in cur.fetchall():
                item = json_safe(dict(row))
                item["dashboard_status"] = dashboard_delivery_status(dict(row))
                deliveries.append(item)
    return {
        "company_code": company,
        "application": app_payload,
        "cv_truth": candidate_cv_truth(application),
        "files": files,
        "notifications": deliveries,
    }


@app.post("/dashboard/prehire/applications/{app_key}/evaluation")
def dashboard_prehire_application_evaluation(
    app_key: str,
    force: bool = False,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "pre_hiring", "candidate.manage")
    company = context["company_code"]
    application = dashboard_application_or_404(app_key, company, context)
    if str(application.get("status") or "") in HELD_IMPORT_STATUSES:
        raise HTTPException(
            status_code=409,
            detail={
                "error": "held_record_evaluation_forbidden",
                "message": "Talent Pool held records cannot be ranked or evaluated until linked to a Job.",
            },
        )
    # UNIFIED_VERIFIED_JOB_BINDING_GATE_WAVE4
    try:
        import inbound_cv_wave4 as _inbound_cv_wave4
        import verified_job_binding_gate as _vjbg

        if _vjbg.gate_enabled():
            _gate = _inbound_cv_wave4.check_downstream_action(
                None,
                company_code=company,
                app_key=app_key,
                action="ranking",
                application=application,
            )
            if _vjbg.enforce_enabled() and not _gate.get("allowed", True):
                raise HTTPException(
                    status_code=409,
                    detail={
                        "error": "verified_job_binding_required",
                        "message": "Ranking requires a verified Job binding.",
                        "gate": _gate,
                    },
                )
    except HTTPException:
        raise
    except Exception:
        pass
    candidate = generate_application_profile_evaluation(app_key, company, force=force)
    ranking_payload = {
        "score": candidate.get("score"),
        "score_breakdown": candidate.get("score_breakdown"),
        "confidence": candidate.get("confidence"),
        "evidence": candidate.get("evidence"),
        "reasons": candidate.get("reasons"),
        "role_profile": candidate.get("role_profile"),
        "gpt_evaluation": candidate.get("gpt_evaluation"),
        "evidence_digest": candidate.get("evidence_digest"),
        "evaluation_audit": candidate.get("evaluation_audit"),
    }
    app_row = application_rank_row(app_key, company) or application
    app_payload = prehire_application_summary(
        app_row,
        include_raw=True,
        include_assessment=company_has_module(company, "assessments"),
        permissions=context.get("permissions") or [],
    )
    app_payload["ranking"] = json_safe(ranking_payload)
    reply = "AI evaluation generated for this candidate and role."
    dashboard_record_action_result(
        "candidate_profile_evaluation",
        "completed",
        {
            "app_key": app_key,
            "ranking": json_safe(ranking_payload),
            "action": {"type": "candidate_profile_evaluation", "target_type": "application", "target": app_key},
            "source": "dashboard",
            "company_code": company,
            "requested_by": context.get("hr_user"),
        },
        reply,
    )
    return {
        "company_code": company,
        "ok": True,
        "action_type": "candidate_profile_evaluation",
        "status": "completed",
        "reply": reply,
        "application": app_payload,
        "result": {"ranking": json_safe(ranking_payload)},
    }


@app.get("/dashboard/prehire/applications/{app_key}/cv")
def dashboard_prehire_application_cv(app_key: str, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    company = context["company_code"]
    application = dashboard_application_or_404(app_key, company, context)
    cv = dashboard_candidate_cv_metadata(application)
    if not cv:
        record_admin_audit(
            context,
            "candidate_cv_download",
            summary="Candidate CV download denied — not found.",
            target_type="application",
            target=app_key,
            details={"outcome": "not_found"},
            status="failed",
        )
        raise HTTPException(status_code=404, detail={"error": "candidate_cv_not_found"})

    filename = str(cv.get("original_filename") or f"{app_key}-cv").strip()
    mime_type = str(cv.get("mime_type") or mimetypes.guess_type(filename)[0] or "application/octet-stream")
    storage_url = str(cv.get("storage_url") or "").strip()
    if storage_url and not storage_url.startswith("local://"):
        record_admin_audit(
            context,
            "candidate_cv_download",
            summary="Downloaded candidate CV (external provider).",
            target_type="application",
            target=app_key,
            details={
                "outcome": "ok",
                "delivery": "external_url",
                "mime_type": mime_type,
                "storage_provider": cv.get("storage_provider"),
            },
        )
        return {
            "type": "external_url",
            "url": storage_url,
            "filename": filename,
            "mime_type": mime_type,
            "storage_provider": cv.get("storage_provider"),
        }

    path = dashboard_candidate_cv_path(cv)
    if path:
        record_admin_audit(
            context,
            "candidate_cv_download",
            summary="Downloaded candidate CV.",
            target_type="application",
            target=app_key,
            details={"outcome": "ok", "delivery": "file", "mime_type": mime_type},
        )
        return FileResponse(path, media_type=mime_type, filename=filename)

    record_admin_audit(
        context,
        "candidate_cv_download",
        summary="Candidate CV download denied — file unavailable.",
        target_type="application",
        target=app_key,
        details={"outcome": "unavailable"},
        status="failed",
    )
    raise HTTPException(status_code=404, detail={"error": "candidate_cv_file_unavailable"})


@app.get("/dashboard/prehire/applications/{app_key}/cv/preview")
def dashboard_prehire_application_cv_preview(app_key: str, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    company = context["company_code"]
    application = dashboard_application_or_404(app_key, company, context)
    cv = dashboard_candidate_cv_metadata(application)
    if not cv:
        record_admin_audit(
            context,
            "candidate_cv_preview",
            summary="Candidate CV preview denied — not found.",
            target_type="application",
            target=app_key,
            details={"outcome": "not_found"},
            status="failed",
        )
        raise HTTPException(status_code=404, detail={"error": "candidate_cv_not_found"})

    filename = str(cv.get("original_filename") or f"{app_key}-cv").strip()
    mime_type = str(cv.get("mime_type") or mimetypes.guess_type(filename)[0] or "application/octet-stream")
    storage_url = str(cv.get("storage_url") or "").strip()
    if storage_url and not storage_url.startswith("local://"):
        record_admin_audit(
            context,
            "candidate_cv_view",
            summary="Viewed candidate CV (external provider).",
            target_type="application",
            target=app_key,
            details={
                "outcome": "ok",
                "delivery": "external_url",
                "mime_type": mime_type,
                "storage_provider": cv.get("storage_provider"),
            },
        )
        return {
            "type": "external_url",
            "url": storage_url,
            "filename": filename,
            "mime_type": mime_type,
            "storage_provider": cv.get("storage_provider"),
        }

    preview = dashboard_candidate_cv_preview_metadata(application)
    preview_path = dashboard_candidate_cv_path(preview or {}) if preview else None
    if preview and preview_path:
        record_admin_audit(
            context,
            "candidate_cv_preview",
            summary="Previewed candidate CV.",
            target_type="application",
            target=app_key,
            details={"outcome": "ok", "delivery": "preview_file", "mime_type": "application/pdf"},
        )
        return FileResponse(preview_path, media_type="application/pdf")

    path = dashboard_candidate_cv_path(cv)
    if not path:
        record_admin_audit(
            context,
            "candidate_cv_preview",
            summary="Candidate CV preview denied — file unavailable.",
            target_type="application",
            target=app_key,
            details={"outcome": "unavailable"},
            status="failed",
        )
        raise HTTPException(status_code=404, detail={"error": "candidate_cv_file_unavailable"})

    if mime_type.startswith("image/") or mime_type == "application/pdf":
        record_admin_audit(
            context,
            "candidate_cv_view",
            summary="Viewed candidate CV.",
            target_type="application",
            target=app_key,
            details={"outcome": "ok", "delivery": "file", "mime_type": mime_type},
        )
        return FileResponse(path, media_type=mime_type)

    generated = generate_candidate_cv_pdf_preview(application, cv)
    if generated.get("ok"):
        preview = dashboard_candidate_cv_preview_metadata(application)
        preview_path = dashboard_candidate_cv_path(preview or {}) if preview else None
        if preview_path:
            record_admin_audit(
                context,
                "candidate_cv_preview",
                summary="Previewed candidate CV.",
                target_type="application",
                target=app_key,
                details={"outcome": "ok", "delivery": "generated_preview", "mime_type": "application/pdf"},
            )
            return FileResponse(preview_path, media_type="application/pdf")

    if mime_type == "text/plain":
        try:
            text = path.read_text(errors="replace")
        except Exception:
            text = ""
        record_admin_audit(
            context,
            "candidate_cv_preview",
            summary="Previewed candidate CV (text fallback).",
            target_type="application",
            target=app_key,
            details={"outcome": "ok", "delivery": "text_fallback", "mime_type": mime_type},
        )
        return cv_preview_html(app_key=app_key, filename=filename, mime_type=mime_type, body=text)

    if mime_type == "application/vnd.openxmlformats-officedocument.wordprocessingml.document" or path.suffix.lower() == ".docx":
        text = docx_text_preview(path)
        record_admin_audit(
            context,
            "candidate_cv_preview",
            summary="Previewed candidate CV (docx fallback).",
            target_type="application",
            target=app_key,
            details={"outcome": "ok", "delivery": "docx_fallback", "mime_type": mime_type},
        )
        return cv_preview_html(
            app_key=app_key,
            filename=filename,
            mime_type=mime_type,
            body=text,
            note="PDF preview generation is not available yet, so this is a text fallback. Download the original if formatting matters.",
        )

    record_admin_audit(
        context,
        "candidate_cv_preview",
        summary="Candidate CV preview fallback shown.",
        target_type="application",
        target=app_key,
        details={"outcome": "ok", "delivery": "unsupported_fallback", "mime_type": mime_type},
    )
    return cv_preview_html(
        app_key=app_key,
        filename=filename,
        mime_type=mime_type,
        body=f"PDF preview generation failed: {generated.get('error') or 'unsupported file type'}. Download the original CV to view it.",
    )


@app.get("/dashboard/calendar/events")
def dashboard_calendar_events_list(
    start: str = Query(..., min_length=1),
    end: str = Query(..., min_length=1),
    scope: str = Query(default="mine"),
    org_scope_id: str | None = Query(default=None),
    event_type: str | None = Query(default=None),
    status: str | None = Query(default=None),
    mine_only: bool = Query(default=False),
    context: dict[str, Any] = Depends(dashboard_context),
):
    require_entitlement(context, "calendar", "calendar.read")
    import calendar_projections as cal_proj

    actor = _calendar_actor(context)
    types = [t.strip() for t in str(event_type or "").split(",") if t.strip()] or None
    statuses = [s.strip() for s in str(status or "").split(",") if s.strip()] or None
    try:
        result = cal_proj.project_events(
            sys.modules[__name__],
            company_code=actor["company_code"],
            actor_user_id=actor["actor_user_id"],
            actor_role=actor["actor_role"],
            permissions=actor["permissions"],
            scope=scope,
            start=start,
            end=end,
            org_scope_id=org_scope_id,
            event_types=types,
            statuses=statuses,
            mine_only=bool(mine_only),
        )
    except Exception as exc:
        raise _calendar_error(exc) from exc
    import calendar_populated_preview as cal_preview
    import calendar_posthire_projections as cal_proj_ph

    result = cal_preview.merge_into_list_result(
        result,
        company_code=actor["company_code"],
        start=start,
        end=end,
        event_types=types,
        statuses=statuses,
    )
    result = cal_proj_ph.merge_into_list_result(
        sys.modules[__name__],
        result,
        company_code=actor["company_code"],
        permissions=actor["permissions"],
        start=start,
        end=end,
        event_types=types,
        statuses=statuses,
    )
    return {"ok": True, "company_code": actor["company_code"], **result}


