@app.get("/dashboard/calendar/events/{event_id}")
def dashboard_calendar_event_detail(
    event_id: str,
    context: dict[str, Any] = Depends(dashboard_context),
):
    require_entitlement(context, "calendar", "calendar.read")
    import calendar_projections as cal_proj
    import calendar_populated_preview as cal_preview
    import calendar_posthire_projections as cal_proj_ph

    actor = _calendar_actor(context)
    if cal_preview.is_preview_event_id(event_id):
        if not cal_preview.preview_enabled_for_company(actor["company_code"]):
            raise HTTPException(
                status_code=404,
                detail={
                    "error": "event_not_found",
                    "message": "This calendar event was not found. Refresh and try again.",
                },
            )
        preview = cal_preview.get_preview_event(event_id)
        if not preview:
            raise HTTPException(
                status_code=404,
                detail={
                    "error": "event_not_found",
                    "message": "This calendar event was not found. Refresh and try again.",
                },
            )
        return {"ok": True, "company_code": actor["company_code"], "event": preview}
    if cal_proj_ph.is_projection_event_id(event_id):
        projected = cal_proj_ph.get_projection_event(
            sys.modules[__name__],
            company_code=actor["company_code"],
            permissions=actor["permissions"],
            event_id=event_id,
        )
        if not projected:
            raise HTTPException(
                status_code=404,
                detail={
                    "error": "event_not_found",
                    "message": "This calendar event was not found. Refresh and try again.",
                },
            )
        return {"ok": True, "company_code": actor["company_code"], "event": projected}
    try:
        event = cal_proj.project_event_detail(
            sys.modules[__name__],
            company_code=actor["company_code"],
            event_id=event_id,
            actor_user_id=actor["actor_user_id"],
            actor_role=actor["actor_role"],
            permissions=actor["permissions"],
        )
    except Exception as exc:
        raise _calendar_error(exc) from exc
    return {"ok": True, "company_code": actor["company_code"], "event": event}


