# --- Inbound email intake: routing + processing + Postmark webhook ----------
def _split_email_address(addr: str | None) -> tuple[str, str]:
    parsed = _parse_email_address(addr) or str(addr or "").strip().lower()
    if "@" in parsed:
        local, _, domain = parsed.partition("@")
        return local, domain
    return parsed, ""


def _parse_email_date(value: str | None):
    if not value:
        return None
    try:
        from email.utils import parsedate_to_datetime

        return parsedate_to_datetime(value)
    except Exception:
        return None


def _postmark_spam_score(payload: dict[str, Any]) -> tuple[float | None, bool]:
    score: float | None = None
    flagged = False
    for header in payload.get("Headers") or []:
        name = str(header.get("Name") or "").lower()
        value = str(header.get("Value") or "")
        if name == "x-spam-score":
            try:
                score = float(value.strip())
            except ValueError:
                pass
        elif name == "x-spam-status" and value.strip().lower().startswith("yes"):
            flagged = True
    return score, flagged


def resolve_intake_address(cur: Any, recipient: str | None, mailbox_hash: str | None) -> dict[str, Any] | None:
    """Map an inbound recipient (envelope address) to a company intake row.
    Tries exact local+domain, then base local (domain-agnostic), then the
    Postmark mailbox hash as a slug. company_code comes only from this table.
    Tenant enablement is checked after resolve so non-allowlisted companies
    never receive durable intake even if a stale address row exists."""
    local, domain = _split_email_address(recipient)
    base = local.split("+", 1)[0]
    attempts: list[tuple[str, str]] = [(base, domain), (base, "")]
    if mailbox_hash:
        attempts += [(mailbox_hash.lower(), domain), (mailbox_hash.lower(), "")]
    for cand_local, cand_domain in attempts:
        if not cand_local:
            continue
        cur.execute(
            "SELECT *, intake_id::text AS intake_id FROM intake_addresses "
            "WHERE status='active' AND lower(local_part)=%s AND lower(coalesce(domain,''))=%s LIMIT 1",
            (cand_local, cand_domain),
        )
        row = cur.fetchone()
        if row:
            resolved = dict(row)
            if not company_inbound_email_enabled(resolved.get("company_code")):
                return None
            return resolved
    return None


def privacy_mailbox_address() -> str:
    return (os.environ.get("WATHEFNI_PRIVACY_MAILBOX") or "privacy@octo-hr.com").strip().lower()


def privacy_mailbox_aliases() -> set[str]:
    """Canonical privacy mailbox plus the legacy inbound-compatible alias."""
    return {privacy_mailbox_address(), "privacy@wathefni.ai"}


def privacy_mailbox_monitor_recipients() -> list[str]:
    raw = (os.environ.get("WATHEFNI_PRIVACY_MAILBOX_MONITORS") or "").strip()
    if raw:
        return [normalize_email(part) for part in raw.split(",") if normalize_email(part)]
    # Default Phase 8C monitors: support primary + backup (no employee PII).
    return [
        "h.almulla@almulla-media.com",
        "azizalmulla16@gmail.com",
    ]


def _privacy_recipient_match(recipient: str | None) -> bool:
    value = normalize_email(recipient)
    if not value:
        return False
    raw = str(recipient or "").lower()
    for target in privacy_mailbox_aliases():
        if value == target or f"<{target}>" in raw:
            return True
        local, domain = target.split("@", 1)
        if value.endswith(f"+{local}@{domain}"):
            return True
    return False


def _extract_privacy_test_token(subject: str | None, text_body: str | None) -> str | None:
    blob = f"{subject or ''}\n{text_body or ''}"
    match = re.search(r"PHASE8C-PRIVACY-TEST-[A-Z0-9-]{6,64}", blob, re.I)
    return match.group(0).upper() if match else None


def process_privacy_mailbox_inbound(payload: dict[str, Any]) -> dict[str, Any]:
    """Handle role-based privacy@ inbound separately from CV intake."""
    ensure_schema()
    provider = "postmark"
    provider_message_id = str(payload.get("MessageID") or "").strip() or None
    from_full = payload.get("FromFull") or {}
    from_address = (from_full.get("Email") if isinstance(from_full, dict) else None) or _parse_email_address(payload.get("From"))
    recipient = str(payload.get("OriginalRecipient") or "").strip()
    if not recipient:
        to_full = payload.get("ToFull") or []
        if isinstance(to_full, list) and to_full:
            recipient = str((to_full[0] or {}).get("Email") or "")
    if not recipient:
        recipient = str(payload.get("To") or "")
    subject = str(payload.get("Subject") or "").strip() or None
    text_body = str(payload.get("TextBody") or payload.get("StrippedTextReply") or "")
    html_body = str(payload.get("HtmlBody") or "")
    body_for_token = text_body or re.sub(r"<[^>]+>", " ", html_body)
    test_token = _extract_privacy_test_token(subject, body_for_token)
    # Never persist full bodies for this mailbox; keep a short non-sensitive excerpt.
    excerpt = re.sub(r"\s+", " ", body_for_token).strip()[:240]
    lowered = excerpt.lower()
    sensitive_markers = ("civil id", "iban", "passport", "bank detail", "personal photo", "employee key", "activation code")
    sensitive = any(marker in lowered for marker in sensitive_markers)
    if sensitive:
        excerpt = "[redacted: potential sensitive content]"

    with db_connect() as conn:
        with conn.cursor() as cur:
            if provider_message_id:
                cur.execute(
                    """
                    INSERT INTO privacy_mailbox_events
                      (direction, provider, provider_message_id, from_address, to_address,
                       subject, test_token, sensitive_content, body_excerpt, metadata)
                    VALUES ('inbound',%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    ON CONFLICT (provider, provider_message_id) WHERE provider_message_id IS NOT NULL
                    DO NOTHING
                    RETURNING event_id::text
                    """,
                    (
                        provider,
                        provider_message_id,
                        from_address,
                        normalize_email(recipient) or privacy_mailbox_address(),
                        subject,
                        test_token,
                        sensitive,
                        None if sensitive else excerpt,
                        Json(
                            {
                                "mailbox": privacy_mailbox_address(),
                                "has_test_token": bool(test_token),
                                "attachment_count": len(payload.get("Attachments") or []),
                            }
                        ),
                    ),
                )
                inserted = cur.fetchone()
                if not inserted:
                    conn.commit()
                    return {"ok": True, "privacy_mailbox": True, "duplicate": True, "test_token": test_token}
                event_id = inserted["event_id"]
            else:
                cur.execute(
                    """
                    INSERT INTO privacy_mailbox_events
                      (direction, provider, from_address, to_address, subject, test_token,
                       sensitive_content, body_excerpt, metadata)
                    VALUES ('inbound',%s,%s,%s,%s,%s,%s,%s,%s)
                    RETURNING event_id::text
                    """,
                    (
                        provider,
                        from_address,
                        normalize_email(recipient) or privacy_mailbox_address(),
                        subject,
                        test_token,
                        sensitive,
                        None if sensitive else excerpt,
                        Json({"mailbox": privacy_mailbox_address(), "has_test_token": bool(test_token)}),
                    ),
                )
                event_id = cur.fetchone()["event_id"]
        conn.commit()

    forwards: list[dict[str, Any]] = []
    if not sensitive:
        forward_subject = f"[OctoHR privacy] {subject or '(no subject)'}"
        forward_body = (
            "OctoHR privacy mailbox inbound copy (non-sensitive metadata forward).\n\n"
            f"Mailbox: {privacy_mailbox_address()}\n"
            f"From: {from_address or ''}\n"
            f"Subject: {subject or ''}\n"
            f"Test token: {test_token or '(none)'}\n"
            f"Event: {event_id}\n\n"
            "If this is a mailbox monitoring test, reply to privacy@octo-hr.com with:\n"
            f"RECEIVED {test_token or 'PHASE8C-PRIVACY-TEST'}\n"
        )
        for monitor in privacy_mailbox_monitor_recipients():
            result = send_email_via_postmark(
                to=monitor,
                subject=forward_subject,
                body=forward_body,
                reply_to=privacy_mailbox_address(),
            )
            forwards.append({"to": monitor, "ok": bool(result.get("ok")), "message_id": result.get("message_id"), "error": result.get("error")})
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        INSERT INTO privacy_mailbox_events
                          (direction, provider, provider_message_id, from_address, to_address,
                           subject, test_token, sensitive_content, body_excerpt, metadata)
                        VALUES ('outbound_forward',%s,%s,%s,%s,%s,%s,false,%s,%s)
                        """,
                        (
                            "postmark",
                            result.get("message_id"),
                            privacy_mailbox_address(),
                            monitor,
                            forward_subject,
                            test_token,
                            "forwarded inbound privacy mailbox notice",
                            Json({"source_event_id": event_id, "ok": bool(result.get("ok")), "error": result.get("error")}),
                        ),
                    )
                conn.commit()

    return {
        "ok": True,
        "privacy_mailbox": True,
        "event_id": event_id,
        "test_token": test_token,
        "sensitive_content": sensitive,
        "forwards": forwards,
    }




def durable_email_ingress_config() -> _durable_email_ingress.IngressConfig:
    return _durable_email_ingress.IngressConfig.from_env(WORKSPACE)


def process_postmark_inbound(
    payload: dict[str, Any],
    *,
    payload_size_bytes: int | None = None,
    failpoint: Any | None = None,
    quarantine_store: _durable_email_ingress.LocalQuarantineStore | None = None,
) -> dict[str, Any]:
    """Durably accept one Postmark message; never import or OCR in-request."""
    recipient_guess = str(payload.get("OriginalRecipient") or payload.get("To") or "")
    to_full = payload.get("ToFull") or []
    if isinstance(to_full, list):
        for item in to_full:
            if isinstance(item, dict) and _privacy_recipient_match(item.get("Email")):
                return process_privacy_mailbox_inbound(payload)
    if _privacy_recipient_match(recipient_guess):
        return process_privacy_mailbox_inbound(payload)

    def _tenant_quota_resolver(company_code: str) -> dict[str, int]:
        import inbound_intake_product as _iip

        return _iip.tenant_inbound_quotas(get_company_settings(company_code))

    def _tenant_policy_resolver(company_code: str) -> dict[str, Any]:
        import inbound_enterprise_hardening as _ieh

        settings = get_company_settings(company_code)
        resolved = _ieh.effective_limits(
            company_code,
            settings=settings,
            base_config=durable_email_ingress_config(),
        )
        return {
            "limits": dict(resolved.get("limits") or {}),
            "per_tenant_concurrency": resolved.get("per_tenant_concurrency"),
            "kill_switch": bool(resolved.get("kill_switch")),
            "settings": settings,
            "plan": resolved.get("plan"),
            "soft_warning_pct": resolved.get("soft_warning_pct"),
            "admin_override_active": resolved.get("admin_override_active"),
        }

    return _durable_email_ingress.durably_receive_postmark(
        payload,
        db_connect=db_connect,
        resolve_intake_address=resolve_intake_address,
        config=durable_email_ingress_config(),
        store=quarantine_store,
        payload_size_bytes=payload_size_bytes,
        failpoint=failpoint,
        tenant_quota_resolver=_tenant_quota_resolver,
        tenant_policy_resolver=_tenant_policy_resolver,
    )


def _enqueue_held_intake_materialization(
    cur: Any,
    *,
    company: str,
    document_id: str,
    resolution_id: str | None,
    priority: int,
    max_attempts: int,
    terminal_reason: str,
) -> None:
    """Queue Held materialization for non-accepted identity outcomes.

    Successful durable CVs must never finish as completed jobs with no Held row
    and no auditable terminal reason surfaced in Held Intake.
    """
    _durable_email_ingress.enqueue_job(
        cur,
        company_code=company,
        job_type="held_intake_materialization",
        subject_type="intake_document",
        subject_id=document_id,
        idempotency_key=f"document:{document_id}:held-materialize",
        payload={
            "document_id": document_id,
            "resolution_id": resolution_id,
            "terminal_reason": terminal_reason,
        },
        priority=int(priority or 100),
        max_attempts=int(max_attempts or 5),
    )


def _soft_contact_from_cv_bytes(
    data: bytes,
    *,
    fallback_name: str | None = None,
) -> dict[str, Any]:
    """Best-effort contact scrape when structured extract/OCR is empty or low-quality.

    Synthetic and text-layer PDFs often embed emails in content streams even when
    pdftotext/OCR cannot produce full CV text. Used only as a soft identity path.
    """
    if not data:
        return {}
    try:
        text = data.decode("latin-1", errors="ignore")
    except Exception:
        return {}
    # Prefer explicit "Email …" labels; fall back to first plausible address.
    labeled = re.search(
        r"(?i)\b(?:e-?mail|email)\s*[:\-]?\s*(" + EMAIL_RE.pattern + r")",
        text,
    )
    email = ""
    if labeled:
        email = normalize_email(labeled.group(1))
    if not email or not EMAIL_RE.fullmatch(email):
        match = EMAIL_RE.search(text)
        email = normalize_email(match.group(0)) if match else ""
    if email and not EMAIL_RE.fullmatch(email):
        email = ""
    phone = None
    phone_match = re.search(
        r"(?i)\b(?:phone|mobile|tel|whatsapp)\s*[:\-]?\s*(\+?\d[\d\s().-]{7,}\d)",
        text,
    )
    if phone_match:
        phone = digits(phone_match.group(1)) or None
        if phone and len(phone) < 8:
            phone = None
    name = fallback_name
    # Prefer a human name line appearing before the email label in the stream.
    name_match = re.search(
        r"(?i)\(([A-Za-z][A-Za-z0-9 .'-]{2,60})\)\s*Tj.*?Email\s+" + EMAIL_RE.pattern,
        text,
        flags=re.DOTALL,
    )
    if name_match:
        candidate_name = " ".join(name_match.group(1).split())
        if candidate_name and not EMAIL_RE.search(candidate_name):
            name = candidate_name
    if email or phone:
        return {"full_name": name, "email": email or None, "phone": phone}
    return {}


def _resolve_clean_intake_document_identity(job: dict[str, Any]) -> dict[str, Any]:
    company = str(job.get("company_code") or "").strip().upper()
    payload = job.get("payload") if isinstance(job.get("payload"), dict) else {}
    document_id = str(payload.get("document_id") or job.get("subject_id") or "")
    config = durable_email_ingress_config()
    quarantine = _durable_email_ingress.LocalQuarantineStore(config.quarantine_root)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT d.*, d.document_id::text AS document_id,
                       d.inbound_id::text AS inbound_id,
                       s.sender_address, s.provider_message_id,
                       s.envelope_recipient
                FROM intake_documents d
                JOIN intake_submissions s
                  ON s.submission_id=d.submission_id
                 AND s.company_code=d.company_code
                WHERE d.company_code=%s AND d.document_id=%s
                FOR UPDATE OF d
                """,
                (company, document_id),
            )
            row = cur.fetchone()
            if not row:
                raise _durable_email_ingress.RetryableJobError(
                    "intake_document_missing"
                )
            document = dict(row)
            existing = _inbound_cv_authority.latest_identity_resolution(
                cur, company_code=company, intake_document_id=document_id
            )
            if existing:
                outcome_existing = str(existing.get("outcome") or "")
                already_prepared = bool(document.get("app_key")) or bool(
                    (document.get("metadata") or {}).get("preparation_status")
                    or (document.get("metadata") or {}).get("held_materialization_status")
                )
                held_enqueued = False
                if (
                    outcome_existing not in _inbound_cv_authority.ACCEPTED_IDENTITY_OUTCOMES
                    and not already_prepared
                ):
                    reasons = existing.get("reason_codes") or []
                    terminal = (
                        reasons[0]
                        if isinstance(reasons, list) and reasons
                        else f"identity_{outcome_existing or 'blocked'}"
                    )
                    _enqueue_held_intake_materialization(
                        cur,
                        company=company,
                        document_id=document_id,
                        resolution_id=str(existing.get("resolution_id") or "") or None,
                        priority=int(job.get("priority") or 100),
                        max_attempts=config.max_attempts,
                        terminal_reason=str(terminal),
                    )
                    held_enqueued = True
                conn.commit()
                return {
                    "document_id": document_id,
                    "outcome": existing.get("outcome"),
                    "resolution_id": existing.get("resolution_id"),
                    "idempotent": True,
                    "held_materialization_enqueued": held_enqueued,
                }
            content_sha = str(document.get("content_sha256") or "")
            if not _inbound_cv_authority.scan_is_authoritatively_clean(
                cur,
                company_code=company,
                intake_document_id=document_id,
                content_sha256=content_sha,
            ):
                raise _durable_email_ingress.RetryableJobError(
                    "durable_clean_scan_authority_missing"
                )
            source_path = quarantine.verify(
                str(document.get("quarantine_key") or ""),
                content_sha,
                int(document.get("size_bytes") or 0),
            )
            extraction = extract_candidate_cv_document(
                str(source_path),
                document.get("detected_mime") or document.get("claimed_mime"),
                company_code=company,
                document_id=f"intake:{document_id}",
                app_key=f"intake:{document_id}",
                cur=cur,
            )
            extracted_text = str(extraction.text or "").strip()
            extraction_ok = bool(extracted_text and extraction.quality_ok)
            fallback_name = _parse_candidate_name_from_filename(
                str(document.get("original_filename") or "")
            )
            identity: dict[str, Any] = {}
            contact_only = False
            if extracted_text:
                parsed = parse_candidate_profile_from_cv_text(
                    extracted_text,
                    fallback_name=fallback_name,
                )
                identity = {
                    "full_name": parsed.get("name") or fallback_name,
                    "email": parsed.get("email"),
                    "phone": parsed.get("phone"),
                }
            # Soft scrape fills missing contact/name when pdftotext quality fails OR
            # when text parse got email but dropped name/phone (D6B conflict gate).
            needs_soft = (not (identity.get("email") or identity.get("phone"))) or (
                not identity.get("full_name") or not identity.get("phone")
            )
            if needs_soft:
                soft = _soft_contact_from_cv_bytes(
                    source_path.read_bytes(),
                    fallback_name=fallback_name,
                )
                if soft.get("email") or soft.get("phone") or soft.get("full_name"):
                    identity = {
                        "full_name": identity.get("full_name")
                        or soft.get("full_name")
                        or fallback_name,
                        "email": identity.get("email") or soft.get("email"),
                        "phone": identity.get("phone") or soft.get("phone"),
                    }
            if not identity.get("full_name") and fallback_name:
                identity["full_name"] = fallback_name
            if not extraction_ok and (identity.get("email") or identity.get("phone")):
                # Soft path: short/synthetic CVs that still expose contact keys
                # may resolve to new_candidate; otherwise they materialize Held.
                contact_only = True
            extraction_status = (
                "completed"
                if extraction_ok
                else ("contact_only" if contact_only else "failed")
            )
            _inbound_cv_authority.record_identity_extraction(
                cur,
                company_code=company,
                inbound_id=str(document.get("inbound_id")),
                intake_document_id=document_id,
                content_sha256=content_sha,
                extraction_status=extraction_status,
                extraction_method=extraction.method,
                extracted_text=extracted_text or None,
                extracted_identity=identity,
                document_identity_evidence={
                    "provider_message_id": document.get("provider_message_id"),
                    "envelope_recipient": document.get("envelope_recipient"),
                    "original_filename": document.get("original_filename"),
                    "content_sha256": content_sha,
                    "quality_ok": bool(extraction.quality_ok),
                    "contact_only": bool(contact_only),
                    "cache_hit": bool(extraction.cache_hit),
                    "method": extraction.method,
                },
                error_code=None
                if extraction_ok or contact_only
                else (extraction.error or "identity_extraction_low_quality"),
            )
            if extraction_ok or contact_only:
                resolution = _inbound_cv_authority.resolve_identity(
                    cur,
                    company_code=company,
                    inbound_id=str(document.get("inbound_id")),
                    intake_document_id=document_id,
                    content_sha256=content_sha,
                    sender_email=document.get("sender_address"),
                    extracted_identity=identity,
                )
            else:
                resolution = _inbound_cv_authority.record_identity_failure(
                    cur,
                    company_code=company,
                    inbound_id=str(document.get("inbound_id")),
                    intake_document_id=document_id,
                    content_sha256=content_sha,
                    sender_email=document.get("sender_address"),
                    reason_code=extraction.error or "identity_extraction_low_quality",
                )
            outcome = str(resolution.get("outcome") or "")
            cur.execute(
                """
                UPDATE intake_documents
                SET metadata=COALESCE(metadata,'{}'::jsonb) || %s,
                    updated_at=now()
                WHERE company_code=%s AND document_id=%s
                """,
                (
                    Json(
                        {
                            "identity_resolution_id": resolution.get(
                                "resolution_id"
                            ),
                            "identity_outcome": outcome,
                            "identity_resolved_at": now_iso(),
                            "identity_contact_only": bool(contact_only),
                        }
                    ),
                    company,
                    document_id,
                ),
            )
            accepted_enqueued = False
            held_enqueued = False
            terminal_reason = ""
            if outcome in _inbound_cv_authority.ACCEPTED_IDENTITY_OUTCOMES:
                _durable_email_ingress.enqueue_job(
                    cur,
                    company_code=company,
                    job_type="accepted_intake_preparation",
                    subject_type="intake_document",
                    subject_id=document_id,
                    idempotency_key=f"document:{document_id}:accepted-prepare",
                    payload={
                        "document_id": document_id,
                        "resolution_id": resolution.get("resolution_id"),
                    },
                    priority=int(job.get("priority") or 100),
                    max_attempts=config.max_attempts,
                )
                accepted_enqueued = True
            else:
                reasons = resolution.get("reason_codes") or []
                terminal_reason = str(
                    reasons[0]
                    if isinstance(reasons, list) and reasons
                    else (
                        extraction.error
                        or f"identity_{outcome or 'blocked'}"
                    )
                )
                cur.execute(
                    """
                    UPDATE intake_submissions
                    SET status='identity_review_required', updated_at=now()
                    WHERE company_code=%s AND submission_id=%s
                    """,
                    (company, document.get("submission_id")),
                )
                _enqueue_held_intake_materialization(
                    cur,
                    company=company,
                    document_id=document_id,
                    resolution_id=str(resolution.get("resolution_id") or "") or None,
                    priority=int(job.get("priority") or 100),
                    max_attempts=config.max_attempts,
                    terminal_reason=terminal_reason,
                )
                held_enqueued = True
        conn.commit()
    return {
        "document_id": document_id,
        "outcome": outcome,
        "resolution_id": resolution.get("resolution_id"),
        "candidate_mutation": False,
        "accepted_preparation_enqueued": accepted_enqueued,
        "held_materialization_enqueued": held_enqueued,
        "terminal_reason": terminal_reason or None,
        "contact_only": bool(contact_only),
    }


def _materialize_held_intake_from_blocked_identity(job: dict[str, Any]) -> dict[str, Any]:
    """Create a Held application for non-accepted identity outcomes.

    Preserves quarantine/scan authority and never auto-admits. Explicit admit
    remains required. Dedup still applies via content checksum.
    """
    company = str(job.get("company_code") or "").strip().upper()
    payload = job.get("payload") if isinstance(job.get("payload"), dict) else {}
    document_id = str(payload.get("document_id") or job.get("subject_id") or "")
    terminal_reason = str(payload.get("terminal_reason") or "identity_review_required")
    config = durable_email_ingress_config()
    quarantine = _durable_email_ingress.LocalQuarantineStore(config.quarantine_root)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT d.*, d.document_id::text AS document_id,
                       d.submission_id::text AS submission_id,
                       s.inbound_id::text AS inbound_id, s.intake_id::text AS intake_id,
                       s.provider_message_id, s.envelope_recipient, s.sender_address,
                       s.subject, s.received_at, s.route_snapshot,
                       s.accepted_attachment_count,
                       s.import_batch_id::text AS import_batch_id
                FROM intake_documents d
                JOIN intake_submissions s
                  ON s.submission_id=d.submission_id AND s.company_code=d.company_code
                WHERE d.company_code=%s AND d.document_id=%s
                FOR UPDATE OF d, s
                """,
                (company, document_id),
            )
            row = cur.fetchone()
            if not row:
                raise _durable_email_ingress.RetryableJobError("intake_document_missing")
            document = dict(row)
            meta = document.get("metadata") if isinstance(document.get("metadata"), dict) else {}
            if document.get("app_key") or meta.get("held_materialization_status") or meta.get("preparation_status"):
                conn.commit()
                return {
                    "document_id": document_id,
                    "status": meta.get("held_materialization_status")
                    or meta.get("preparation_status")
                    or "imported",
                    "app_key": document.get("app_key"),
                    "idempotent": True,
                    "terminal_reason": terminal_reason,
                }
            if document.get("safety_state") != "clean":
                raise _durable_email_ingress.RetryableJobError("document_not_clean")
            resolution = _inbound_cv_authority.latest_identity_resolution(
                cur, company_code=company, intake_document_id=document_id
            )
            if not resolution:
                raise _durable_email_ingress.RetryableJobError(
                    "identity_resolution_missing_for_held_materialization"
                )
            outcome = str(resolution.get("outcome") or "")
            if outcome in _inbound_cv_authority.ACCEPTED_IDENTITY_OUTCOMES:
                _durable_email_ingress.enqueue_job(
                    cur,
                    company_code=company,
                    job_type="accepted_intake_preparation",
                    subject_type="intake_document",
                    subject_id=document_id,
                    idempotency_key=f"document:{document_id}:accepted-prepare",
                    payload={
                        "document_id": document_id,
                        "resolution_id": resolution.get("resolution_id"),
                    },
                    priority=int(job.get("priority") or 100),
                    max_attempts=config.max_attempts,
                )
                conn.commit()
                return {
                    "document_id": document_id,
                    "status": "redirected_to_accepted_preparation",
                    "outcome": outcome,
                }
            cur.execute(
                "SELECT pg_advisory_xact_lock(hashtext(%s))",
                (f"{company}:{document.get('content_sha256')}",),
            )
            source_path = quarantine.verify(
                str(document.get("quarantine_key") or ""),
                str(document.get("content_sha256") or ""),
                int(document.get("size_bytes") or 0),
            )
            batch_id = document.get("import_batch_id")
            if not batch_id:
                cur.execute(
                    """
                    INSERT INTO import_batches
                      (company_code, source, status, total_files, intake_id, options)
                    VALUES (%s,'email_inbound','processing',%s,%s,%s)
                    RETURNING batch_id::text
                    """,
                    (
                        company,
                        int(document.get("accepted_attachment_count") or 1),
                        document.get("intake_id"),
                        Json(
                            {
                                "provider": "postmark",
                                "intake_submission_id": document.get("submission_id"),
                                "durable_email_ingress": True,
                                "held_identity_review": True,
                            }
                        ),
                    ),
                )
                batch_id = cur.fetchone()["batch_id"]
                cur.execute(
                    """
                    UPDATE intake_submissions SET import_batch_id=%s, updated_at=now()
                    WHERE company_code=%s AND submission_id=%s
                    """,
                    (batch_id, company, document.get("submission_id")),
                )
            data = source_path.read_bytes()
            route = document.get("route_snapshot") if isinstance(document.get("route_snapshot"), dict) else {}
            company_positions = _import_load_company_positions(cur, company)
            held_resolution = {
                **dict(resolution),
                "held_review_materialization": True,
                "held_terminal_reason": terminal_reason,
                "intake_document_id": document_id,
            }
            item_record = _import_process_one_file(
                cur,
                company=company,
                batch_id=str(batch_id),
                source="email_inbound",
                company_positions=company_positions,
                filename=str(document.get("original_filename") or "attachment"),
                data=data,
                folder_hint=None,
                meta={},
                seen_checksums={},
                default_position_code=(route.get("position_code") or None),
                default_position_title=(route.get("position_title") or None),
                auto_admit_enabled=False,
                identity_resolution=held_resolution,
            )
            provenance = {
                "source_message_id": document.get("provider_message_id"),
                "source_sender": document.get("sender_address"),
                "source_received_at": document.get("received_at"),
                "source_subject": document.get("subject"),
                "source_label": document.get("envelope_recipient"),
                "identity_terminal_reason": terminal_reason,
            }
            item_record["item_id"] = _import_insert_item(
                cur,
                batch_id=str(batch_id),
                company=company,
                item_record=item_record,
                provenance=provenance,
            )
            preparation_status = str(item_record.get("status") or "failed")
            app_key = item_record.get("app_key") or item_record.get("duplicate_of_app_key")
            if preparation_status not in {"needs_role", "import_review", "duplicate"} and not app_key:
                # Fail the job audibly — never complete silently without Held/terminal.
                raise _durable_email_ingress.RetryableJobError(
                    f"held_materialization_failed:{item_record.get('error') or preparation_status}"
                )
            cur.execute(
                """
                UPDATE intake_documents
                SET app_key=%s, file_id=%s, candidate_document_id=%s,
                    metadata=COALESCE(metadata,'{}'::jsonb) || %s,
                    updated_at=now()
                WHERE company_code=%s AND document_id=%s
                """,
                (
                    app_key,
                    item_record.get("file_id"),
                    item_record.get("document_id"),
                    Json(
                        {
                            "held_materialization_status": preparation_status,
                            "held_terminal_reason": terminal_reason,
                            "identity_outcome": outcome,
                            "import_item_id": item_record.get("item_id"),
                            "held_materialized_at": now_iso(),
                        }
                    ),
                    company,
                    document_id,
                ),
            )
            cur.execute(
                """
                UPDATE intake_submissions
                SET status='held_identity_review', updated_at=now()
                WHERE company_code=%s AND submission_id=%s
                """,
                (company, document.get("submission_id")),
            )
        conn.commit()
    return {
        "document_id": document_id,
        "status": preparation_status,
        "app_key": app_key,
        "terminal_reason": terminal_reason,
        "outcome": outcome,
        "held_materialized": True,
        "candidate_mutation": preparation_status in {"needs_role", "import_review"},
    }


def _prepare_accepted_intake_document(job: dict[str, Any]) -> dict[str, Any]:

    company = str(job.get("company_code") or "").strip().upper()
    payload = job.get("payload") if isinstance(job.get("payload"), dict) else {}
    document_id = str(payload.get("document_id") or job.get("subject_id") or "")
    config = durable_email_ingress_config()
    quarantine = _durable_email_ingress.LocalQuarantineStore(config.quarantine_root)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT d.*, d.document_id::text AS document_id,
                       d.submission_id::text AS submission_id,
                       s.inbound_id::text AS inbound_id, s.intake_id::text AS intake_id,
                       s.provider_message_id, s.envelope_recipient, s.sender_address,
                       s.subject, s.received_at, s.route_snapshot,
                       s.accepted_attachment_count,
                       s.import_batch_id::text AS import_batch_id
                FROM intake_documents d
                JOIN intake_submissions s
                  ON s.submission_id=d.submission_id AND s.company_code=d.company_code
                WHERE d.company_code=%s AND d.document_id=%s
                FOR UPDATE OF d, s
                """,
                (company, document_id),
            )
            row = cur.fetchone()
            if not row:
                raise _durable_email_ingress.RetryableJobError("intake_document_missing")
            document = dict(row)
            if document.get("app_key") or (document.get("metadata") or {}).get("preparation_status"):
                conn.commit()
                return {
                    "document_id": document_id,
                    "status": (document.get("metadata") or {}).get("preparation_status") or "imported",
                    "app_key": document.get("app_key"),
                    "idempotent": True,
                }
            if document.get("safety_state") != "clean":
                raise _durable_email_ingress.RetryableJobError("document_not_clean")
            resolution = _inbound_cv_authority.latest_identity_resolution(
                cur, company_code=company, intake_document_id=document_id
            )
            if not resolution or not _inbound_cv_authority.binding_is_authorized(
                cur,
                company_code=company,
                intake_document_id=document_id,
                content_sha256=str(document.get("content_sha256") or ""),
                candidate_phone=str(
                    (resolution or {}).get("selected_candidate_phone") or ""
                )
                or None,
                app_key=str((resolution or {}).get("selected_app_key") or "")
                or None,
            ):
                raise _durable_email_ingress.RetryableJobError(
                    "identity_binding_authority_missing"
                )
            cur.execute(
                "SELECT pg_advisory_xact_lock(hashtext(%s))",
                (f"{company}:{document.get('content_sha256')}",),
            )
            source_path = quarantine.verify(
                str(document.get("quarantine_key") or ""),
                str(document.get("content_sha256") or ""),
                int(document.get("size_bytes") or 0),
            )
            batch_id = document.get("import_batch_id")
            if not batch_id:
                cur.execute(
                    """
                    INSERT INTO import_batches
                      (company_code, source, status, total_files, intake_id, options)
                    VALUES (%s,'email_inbound','processing',%s,%s,%s)
                    RETURNING batch_id::text
                    """,
                    (
                        company,
                        int(document.get("accepted_attachment_count") or 1),
                        document.get("intake_id"),
                        Json(
                            {
                                "provider": "postmark",
                                "intake_submission_id": document.get("submission_id"),
                                "durable_email_ingress": True,
                            }
                        ),
                    ),
                )
                batch_id = cur.fetchone()["batch_id"]
                cur.execute(
                    """
                    UPDATE intake_submissions SET import_batch_id=%s, updated_at=now()
                    WHERE company_code=%s AND submission_id=%s
                    """,
                    (batch_id, company, document.get("submission_id")),
                )
            data = source_path.read_bytes()
            route = document.get("route_snapshot") if isinstance(document.get("route_snapshot"), dict) else {}
            company_positions = _import_load_company_positions(cur, company)
            item_record = _import_process_one_file(
                cur,
                company=company,
                batch_id=str(batch_id),
                source="email_inbound",
                company_positions=company_positions,
                filename=str(document.get("original_filename") or "attachment"),
                data=data,
                folder_hint=None,
                # Sender email is source provenance, never the candidate key.
                meta={},
                seen_checksums={},
                default_position_code=(route.get("position_code") or None),
                default_position_title=(route.get("position_title") or None),
                auto_admit_enabled=company_auto_admit_imports(company),
                identity_resolution=resolution,
            )
            provenance = {
                "source_message_id": document.get("provider_message_id"),
                "source_sender": document.get("sender_address"),
                "source_received_at": document.get("received_at"),
                "source_subject": document.get("subject"),
                "source_label": document.get("envelope_recipient"),
            }
            item_record["item_id"] = _import_insert_item(
                cur,
                batch_id=str(batch_id),
                company=company,
                item_record=item_record,
                provenance=provenance,
            )
            preparation_status = str(item_record.get("status") or "failed")
            cur.execute(
                """
                UPDATE intake_documents
                SET app_key=%s, file_id=%s, candidate_document_id=%s,
                    metadata=COALESCE(metadata,'{}'::jsonb) || %s,
                    updated_at=now()
                WHERE company_code=%s AND document_id=%s
                """,
                (
                    item_record.get("app_key") or item_record.get("duplicate_of_app_key"),
                    item_record.get("file_id"),
                    item_record.get("document_id"),
                    Json(
                        {
                            "preparation_status": preparation_status,
                            "import_item_id": item_record.get("item_id"),
                            "prepared_at": now_iso(),
                        }
                    ),
                    company,
                    document_id,
                ),
            )
            if item_record.get("document_id"):
                _durable_email_ingress.enqueue_job(
                    cur,
                    company_code=company,
                    job_type="cv_extraction",
                    subject_type="candidate_document",
                    subject_id=str(item_record["document_id"]),
                    idempotency_key=f"candidate-document:{item_record['document_id']}:extract",
                    payload={
                        "candidate_document_id": str(item_record["document_id"]),
                        "intake_document_id": document_id,
                    },
                    priority=50 if route.get("position_code") else 100,
                    max_attempts=config.max_attempts,
                )
            cur.execute(
                """
                SELECT count(*) FILTER (WHERE status='imported') AS imported,
                       count(*) FILTER (WHERE status='duplicate') AS duplicate,
                       count(*) FILTER (WHERE status='failed') AS failed
                FROM import_items WHERE batch_id=%s
                """,
                (batch_id,),
            )
            counts = dict(cur.fetchone() or {})
            cur.execute(
                """
                SELECT count(*) AS pending
                FROM intake_documents
                WHERE company_code=%s AND submission_id=%s AND safety_state='clean'
                  AND NOT (metadata ? 'preparation_status')
                  AND document_id<>%s
                """,
                (company, document.get("submission_id"), document_id),
            )
            pending = int((cur.fetchone() or {}).get("pending") or 0)
            cur.execute(
                """
                SELECT count(*) AS needs_role
                FROM import_items i
                JOIN applications a ON a.app_key=i.app_key AND a.company_code=i.company_code
                WHERE i.batch_id=%s AND a.status='needs_role'
                """,
                (batch_id,),
            )
            needs_role = int((cur.fetchone() or {}).get("needs_role") or 0)
            batch_status = "completed" if pending == 0 else "processing"
            cur.execute(
                """
                UPDATE import_batches
                SET status=%s, imported_count=%s, duplicate_count=%s,
                    failed_count=%s, needs_role_count=%s, updated_at=now()
                WHERE batch_id=%s
                """,
                (
                    batch_status,
                    int(counts.get("imported") or 0),
                    int(counts.get("duplicate") or 0),
                    int(counts.get("failed") or 0),
                    needs_role,
                    batch_id,
                ),
            )
            cur.execute(
                """
                UPDATE intake_submissions
                SET status=%s, updated_at=now()
                WHERE company_code=%s AND submission_id=%s
                """,
                ("accepted" if pending == 0 else "accepted_processing", company, document.get("submission_id")),
            )
            cur.execute(
                """
                UPDATE inbound_messages
                SET status=%s, batch_id=%s, updated_at=now()
                WHERE inbound_id=%s
                """,
                ("processed" if pending == 0 else "processing", batch_id, document.get("inbound_id")),
            )
        conn.commit()
    return {
        "document_id": document_id,
        "status": preparation_status,
        "app_key": item_record.get("app_key"),
        "duplicate_of_app_key": item_record.get("duplicate_of_app_key"),
        "candidate_document_id": item_record.get("document_id"),
        "batch_id": batch_id,
    }


def process_durable_email_ingress_job(job: dict[str, Any]) -> dict[str, Any]:
    job_type = str(job.get("job_type") or "")
    company = str(job.get("company_code") or "").strip().upper()
    payload = job.get("payload") if isinstance(job.get("payload"), dict) else {}
    config = durable_email_ingress_config()

    def _observe(status: str, result: dict[str, Any] | None = None, *, error_code: str | None = None, error_detail: str | None = None) -> None:
        # Additive Wave 2 stage ledger. Never changes live email outcomes.
        try:
            import inbound_cv_processing as _inbound_cv_processing

            if not _inbound_cv_processing.stage_ledger_enabled():
                return
            with db_connect() as obs_conn:
                with obs_conn.cursor() as obs_cur:
                    _inbound_cv_processing.ensure_schema(obs_cur)
                    _inbound_cv_processing.observe_email_job_stage(
                        obs_cur,
                        job=job,
                        status=status,
                        result=result,
                        error_code=error_code,
                        error_detail=error_detail,
                    )
                obs_conn.commit()
        except Exception:
            logger.exception("unified_cv_processing_stage_observe_failed")

    if job_type == "intake_validation":
        result = _durable_email_ingress.validate_submission(
            db_connect=db_connect,
            submission_id=str(payload.get("submission_id") or job.get("subject_id") or ""),
            company_code=company,
            config=config,
        )
        _observe("completed", result if isinstance(result, dict) else None)
        return result
    if job_type == "file_safety_scan":
        result = _durable_email_ingress.scan_document(
            db_connect=db_connect,
            document_id=str(payload.get("document_id") or job.get("subject_id") or ""),
            company_code=company,
            config=config,
        )
        _observe("completed", result if isinstance(result, dict) else None)
        return result
    if job_type == "cv_identity_resolution":
        result = _resolve_clean_intake_document_identity(job)
        _observe("completed", result if isinstance(result, dict) else None)
        return result
    if job_type == "accepted_intake_preparation":
        result = _prepare_accepted_intake_document(job)
        _observe("completed", result if isinstance(result, dict) else None)
        return result
    if job_type == "held_intake_materialization":
        result = _materialize_held_intake_from_blocked_identity(job)
        _observe("completed", result if isinstance(result, dict) else None)
        return result
    if job_type == "cv_extraction":
        candidate_document_id = str(
            payload.get("candidate_document_id") or job.get("subject_id") or ""
        )
        intake_document_id = str(payload.get("intake_document_id") or "")
        if intake_document_id:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT content_sha256, app_key, safety_state,
                               candidate_document_id::text AS candidate_document_id,
                               metadata
                        FROM intake_documents
                        WHERE company_code=%s AND document_id=%s
                        """,
                        (company, intake_document_id),
                    )
                    safety_row = cur.fetchone()
                    if not safety_row:
                        raise _durable_email_ingress.RetryableJobError(
                            "intake_document_missing"
                        )
                    safety_row = dict(safety_row)
                    if str(safety_row.get("safety_state") or "") != "clean":
                        raise _durable_email_ingress.RetryableJobError(
                            "intake_document_not_clean"
                        )
                    if str(safety_row.get("candidate_document_id") or "") != candidate_document_id:
                        raise _durable_email_ingress.RetryableJobError(
                            "intake_candidate_document_mismatch"
                        )
                    content_sha = str(safety_row.get("content_sha256") or "")
                    if not _inbound_cv_authority.scan_is_authoritatively_clean(
                        cur,
                        company_code=company,
                        intake_document_id=intake_document_id,
                        content_sha256=content_sha,
                    ):
                        raise _durable_email_ingress.RetryableJobError(
                            "durable_clean_scan_authority_missing"
                        )
                    meta = (
                        safety_row.get("metadata")
                        if isinstance(safety_row.get("metadata"), dict)
                        else {}
                    )
                    if _inbound_cv_authority.held_review_extraction_authorized(
                        cur,
                        company_code=company,
                        intake_document_id=intake_document_id,
                        content_sha256=content_sha,
                        intake_metadata=meta,
                    ):
                        # Wave D6B: Held identity-review apps are scan-clean but are
                        # intentionally NOT ownership-bound. Do not mislabel that as
                        # intake_document_not_clean, and do allow soft extraction.
                        extraction_authorized = True
                        authorization_mode = "held_identity_review_scan_clean"
                    else:
                        extraction_authorized = bool(
                            _inbound_cv_authority.binding_is_authorized(
                                cur,
                                company_code=company,
                                intake_document_id=intake_document_id,
                                content_sha256=content_sha,
                                app_key=str(safety_row.get("app_key") or "") or None,
                            )
                        )
                        authorization_mode = "accepted_identity_binding"
            if not extraction_authorized:
                raise _durable_email_ingress.RetryableJobError(
                    "identity_binding_not_authorized"
                )
        else:
            # Application-attached CVs (WhatsApp / manual / bulk) share the same
            # durable queue without a second worker. Require a live candidate document.
            authorization_mode = "application_attach"
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT d.document_id::text AS document_id, a.company_code
                        FROM candidate_documents d
                        JOIN applications a ON a.app_key=d.app_key
                        WHERE d.document_id=%s::uuid AND a.company_code=%s
                        LIMIT 1
                        """,
                        (candidate_document_id, company),
                    )
                    if not cur.fetchone():
                        raise _durable_email_ingress.RetryableJobError(
                            "candidate_document_missing"
                        )
        result = process_candidate_cv_document(
            candidate_document_id,
            dry_run=False,
            send_screening=False,
        )
        if not result.get("ok"):
            error_code = str(result.get("error") or "cv_extraction_failed")
            # Terminal quality/OCR failures must not retry forever once Held exists.
            # Soft-complete so the job leaves pending/retrying while preserving D6A
            # Held review semantics for weak/unreadable CVs.
            terminal_soft_fail = error_code in {
                "low_quality_text",
                "ocr_required_mistral_disabled",
                "no_text_extracted",
                "empty_text",
                "pdftotext_missing",
                "identity_extraction_low_quality",
                # Orphaned / missing workspace bytes must not retry forever.
                "file_not_found",
            }
            if terminal_soft_fail:
                soft = {
                    "ok": True,
                    "status": "extraction_soft_failed",
                    "terminal": True,
                    "error": error_code,
                    "authorization_mode": authorization_mode,
                    "document_id": result.get("document_id") or candidate_document_id,
                    "app_key": result.get("app_key") or payload.get("app_key"),
                    "method": result.get("method"),
                }
                _observe("completed", soft)
                return json_safe(soft)
            _observe(
                "retrying",
                result if isinstance(result, dict) else None,
                error_code="cv_extraction_failed",
                error_detail=error_code,
            )
            raise _durable_email_ingress.RetryableJobError(
                "cv_extraction_failed",
                error_code,
            )
        if isinstance(result, dict):
            result = {**result, "authorization_mode": authorization_mode}
        _observe("completed", result if isinstance(result, dict) else None)
        return json_safe(result)
    if job_type in {"profile_structuring", "embedding"}:
        # The current frozen CV worker performs these after extraction. The queue
        # contract reserves independent types for a later, separately qualified split.
        result = {"status": "handled_by_cv_extraction_worker", "job_type": job_type}
        _observe("skipped", result)
        return result
    if job_type == "sender_acknowledgment":
        return {"status": "disabled", "reason": "sender_ack_not_approved"}
    if job_type == "retention_privacy":
        import inbound_enterprise_hardening as _ieh
        import inbound_retention_policy as _irp
        from intake_quarantine_storage import build_quarantine_storage_from_env

        company = str(job.get("company_code") or "").strip().upper()
        dry_run = not _ieh.retention_execute_enabled()
        storage = build_quarantine_storage_from_env(WORKSPACE)
        with db_connect() as conn:
            with conn.cursor() as cur:
                _irp.ensure_schema(cur)
                result = _irp.execute_cleanup(
                    cur,
                    company_code=company,
                    storage=storage,
                    actor="retention_privacy_worker",
                    dry_run=dry_run,
                    limit=int((job.get("payload") or {}).get("limit") or 200),
                )
            conn.commit()
        _observe("completed" if not dry_run else "dry_run", result if isinstance(result, dict) else None)
        return json_safe({**result, "status": "dry_run" if dry_run else "executed"})
    raise _durable_email_ingress.RetryableJobError("unsupported_intake_job_type")


def run_durable_email_ingress_worker(
    *,
    limit: int = 10,
    worker_id: str | None = None,
    job_types: list[str] | None = None,
) -> dict[str, Any]:
    ensure_schema()
    worker = worker_id or f"email-ingress-{os.getpid()}-{uuid.uuid4().hex[:8]}"

    def _tenant_policy_resolver(company_code: str) -> dict[str, Any]:
        import inbound_enterprise_hardening as _ieh

        settings = get_company_settings(company_code)
        resolved = _ieh.effective_limits(
            company_code,
            settings=settings,
            base_config=durable_email_ingress_config(),
        )
        return {
            "limits": dict(resolved.get("limits") or {}),
            "kill_switch": bool(resolved.get("kill_switch")),
            "per_tenant_concurrency": resolved.get("per_tenant_concurrency"),
            "settings": settings,
        }

    return _durable_email_ingress.run_worker_once(
        db_connect=db_connect,
        handler=process_durable_email_ingress_job,
        worker_id=worker,
        config=durable_email_ingress_config(),
        limit=limit,
        allowed_job_types=job_types,
        tenant_policy_resolver=_tenant_policy_resolver,
    )


def _verify_postmark_token(authorization: str | None, token: str | None, secret: str) -> bool:
    if not secret:
        return False
    provided = (token or "").strip()
    if not provided and authorization and authorization.lower().startswith("basic "):
        try:
            decoded = base64.b64decode(authorization.split(" ", 1)[1]).decode("utf-8")
            provided = decoded.split(":", 1)[1] if ":" in decoded else decoded
        except Exception:
            provided = ""
    return bool(provided) and hmac.compare_digest(provided, secret)


def _verify_postmark_secret(authorization: str | None, token: str | None) -> bool:
    return _verify_postmark_token(authorization, token, inbound_postmark_secret())


@app.post("/webhook/postmark/inbound")
async def webhook_postmark_inbound(
    request: Request,
    authorization: str | None = Header(default=None),
    token: str | None = Query(default=None),
    env: str | None = Query(default=None),
    x_wathefni_inbound_env: str | None = Header(default=None, alias="X-Wathefni-Inbound-Env"),
):
    ensure_schema()
    # Fail closed: require the shared secret (Basic Auth password or ?token=).
    if not inbound_postmark_secret():
        raise HTTPException(status_code=503, detail={"error": "inbound_not_configured"})
    if not _verify_postmark_secret(authorization, token):
        raise HTTPException(status_code=401, detail={"error": "unauthorized"})
    if not inbound_email_enabled():
        # Never acknowledge a provider delivery that cannot enter the durable ledger.
        raise HTTPException(status_code=503, detail={"error": "inbound_disabled"})
    config = durable_email_ingress_config()
    body = bytearray()
    try:
        async for chunk in request.stream():
            body.extend(chunk)
            if len(body) > config.max_webhook_body_bytes:
                raise HTTPException(
                    status_code=413,
                    detail={"error": "inbound_body_too_large"},
                )
        payload = json.loads(bytes(body))
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=400, detail={"error": "invalid_json"})
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail={"error": "invalid_payload"})
    import inbound_enterprise_hardening as _ieh

    env_ok, env_code = _ieh.verify_postmark_inbound_environment(
        header_env=x_wathefni_inbound_env,
        query_env=env,
        payload=payload,
    )
    if not env_ok:
        try:
            record_admin_audit(
                {
                    "company_code": "PLATFORM",
                    "actor_user_id": "postmark_webhook",
                    "actor_email": None,
                },
                "inbound_postmark_env_rejected",
                summary=f"Rejected inbound webhook for Postmark env isolation ({env_code}).",
                target_type="inbound_webhook",
                target=str(payload.get("MessageID") or "")[:80],
                details={"error": env_code},
            )
        except Exception:
            pass
        raise HTTPException(status_code=401, detail={"error": env_code or "inbound_env_mismatch"})
    try:
        result = process_postmark_inbound(payload, payload_size_bytes=len(body))
    except _durable_email_ingress.IngressError as exc:
        # Pre-durability failures must remain non-2xx so Postmark retries.
        raise HTTPException(
            status_code=exc.http_status,
            detail={"error": exc.code},
        ) from exc
    except Exception as exc:
        logger.exception("durable Postmark ingress failed before acknowledgement")
        raise HTTPException(
            status_code=503,
            detail={"error": "inbound_durability_unavailable"},
        ) from exc
    return {"ok": True, **result}


def process_postmark_outbound_status(payload: dict[str, Any]) -> dict[str, Any]:
    """Record a Postmark delivery/bounce/complaint webhook as a delivery event.

    Best-effort links back to the original send (via the stored message_id) so the
    audit row is company/subject scoped. Opens and other record types are ignored.
    """
    record_type = str(payload.get("RecordType") or "").strip().lower()
    message_id = str(payload.get("MessageID") or "").strip()
    recipient = str(payload.get("Recipient") or payload.get("Email") or "").strip().lower() or None
    status_map = {"delivery": "delivered", "bounce": "bounced", "spamcomplaint": "complaint"}
    status = status_map.get(record_type)
    if not status:
        return {"ignored": record_type or "unknown"}
    last_error = None
    if status == "bounced":
        last_error = str(payload.get("Description") or payload.get("Details") or payload.get("Type") or "bounced")[:500]
    elif status == "complaint":
        last_error = "spam_complaint"
    company = subject_type = subject_key = None
    if message_id:
        try:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT company_code, subject_type, subject_key FROM outbound_delivery_events "
                        "WHERE channel='email' AND payload->>'message_id'=%s ORDER BY created_at ASC LIMIT 1",
                        (message_id,),
                    )
                    row = cur.fetchone()
            if row:
                company = row.get("company_code")
                subject_type = row.get("subject_type")
                subject_key = row.get("subject_key")
        except Exception:
            pass
    try:
        record_outbound_delivery_event(
            account_id=None,
            target_phone=None,
            target_conversation_id=None,
            status=status,
            message_text="",
            last_error=last_error,
            payload={"postmark_status": json_safe(payload), "message_id": message_id, "recipient_email": recipient, "provider": "postmark"},
            subject_type=subject_type or "candidate",
            subject_key=subject_key,
            channel="email",
            message_kind="email_status",
            company_code=company,
        )
    except ValueError as exc:
        if str(exc) != "company_code_required":
            raise
        return {
            "status": status,
            "message_id": message_id,
            "skipped": "company_code_required",
        }
    return {"status": status, "message_id": message_id}


@app.post("/webhook/postmark/outbound")
async def webhook_postmark_outbound(
    request: Request,
    authorization: str | None = Header(default=None),
    token: str | None = Query(default=None),
):
    ensure_schema()
    secret = outbound_postmark_secret()
    if not secret:
        raise HTTPException(status_code=503, detail={"error": "outbound_webhook_not_configured"})
    if not _verify_postmark_token(authorization, token, secret):
        raise HTTPException(status_code=401, detail={"error": "unauthorized"})
    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail={"error": "invalid_json"})
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail={"error": "invalid_payload"})
    try:
        result = process_postmark_outbound_status(payload)
    except Exception:
        return {"ok": False, "error": "outbound_status_processing_failed"}
    return {"ok": True, **result}


# --- Inbound intake address management (Settings -> Communications) ----------
def intake_address_public(row: dict[str, Any], *, health: dict[str, Any] | None = None) -> dict[str, Any]:
    import inbound_intake_product as _iip

    domain = row.get("domain") or _iip.inbound_domain()
    payload = {
        "intake_id": row.get("intake_id"),
        "company_code": row.get("company_code"),
        "address": f"{row.get('local_part')}@{domain}",
        "local_part": row.get("local_part"),
        "domain": row.get("domain"),
        "position_code": row.get("position_code"),
        "position_title": row.get("position_title"),
        "label": row.get("label"),
        "status": row.get("status"),
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
        "role_bound": bool(row.get("position_code")),
        "hold_policy": "role_bound" if row.get("position_code") else "needs_role",
    }
    if health is not None:
        payload["health"] = health
    return json_safe(payload)


def _load_company_intake_rows(cur: Any, company: str, *, include_disabled: bool = True) -> list[dict[str, Any]]:
    import inbound_intake_product as _iip

    if include_disabled:
        cur.execute(
            "SELECT *, intake_id::text AS intake_id FROM intake_addresses WHERE company_code=%s ORDER BY created_at DESC",
            (company,),
        )
    else:
        cur.execute(
            "SELECT *, intake_id::text AS intake_id FROM intake_addresses WHERE company_code=%s AND status='active' ORDER BY created_at DESC",
            (company,),
        )
    rows = [dict(r) for r in cur.fetchall()]
    out: list[dict[str, Any]] = []
    for row in rows:
        health = _iip.fetch_intake_health(cur, company_code=company, intake_id=str(row.get("intake_id") or ""))
        out.append(intake_address_public(row, health=health))
    return out


def _intake_feature_payload(company: str) -> dict[str, Any]:
    import inbound_enterprise_hardening as _ieh
    import inbound_intake_product as _iip

    settings = get_company_settings(company)
    health: dict[str, Any] = {}
    usage: dict[str, Any] = {}
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                health = _iip.fetch_intake_health(cur, company_code=company)
                usage = _ieh.usage_visibility(
                    cur,
                    company_code=company,
                    settings=settings,
                    base_config=durable_email_ingress_config(),
                )
            conn.commit()
    except Exception:
        health = _iip.intake_health_from_row({})
        usage = {}
    return _iip.feature_status_public(
        global_enabled=inbound_email_enabled(),
        company_code=company,
        company_settings=settings,
        config=durable_email_ingress_config(),
        health=health,
        enterprise=usage,
    )


@app.get("/dashboard/prehire/integrations/intake")
def dashboard_intake_list(context: dict[str, Any] = Depends(prehire_dashboard_context)):
    require_entitlement(context, "pre_hiring", "settings.manage")
    company = context["company_code"]
    feature = _intake_feature_payload(company)
    rows: list[dict[str, Any]] = []
    if feature.get("enabled"):
        with db_connect() as conn:
            with conn.cursor() as cur:
                rows = _load_company_intake_rows(cur, company)
            conn.commit()
    import inbound_intake_product as _iip

    primary = next((r.get("address") for r in rows if r.get("status") == "active"), None)
    setup = _iip.setup_instructions(primary_address=primary)
    return {
        "company_code": company,
        "feature": feature,
        "addresses": rows,
        **setup,
    }


@app.get("/dashboard/prehire/integrations/intake/{intake_id}")
def dashboard_intake_inspect(intake_id: str, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    require_entitlement(context, "pre_hiring", "settings.manage")
    company = context["company_code"]
    require_company_inbound_email(company)
    import inbound_intake_product as _iip

    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT *, intake_id::text AS intake_id FROM intake_addresses WHERE company_code=%s AND intake_id=%s LIMIT 1",
                (company, intake_id),
            )
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail={"error": "intake_not_found"})
            health = _iip.fetch_intake_health(cur, company_code=company, intake_id=intake_id)
        conn.commit()
    return {
        "company_code": company,
        "feature": _intake_feature_payload(company),
        "address": intake_address_public(dict(row), health=health),
        **_iip.setup_instructions(primary_address=f"{row.get('local_part')}@{row.get('domain') or _iip.inbound_domain()}"),
    }


@app.post("/dashboard/prehire/integrations/intake")
def dashboard_intake_create(request: dict[str, Any] | None = None, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    require_entitlement(context, "pre_hiring", "settings.manage")
    company = context["company_code"]
    require_company_inbound_email(company)
    import inbound_intake_product as _iip

    body = request or {}
    local_part = re.sub(r"[^a-z0-9._-]", "", str(body.get("local_part") or "").strip().lower())
    if not local_part:
        local_part = _iip.suggest_local_part(company)
    domain = str(body.get("domain") or _iip.inbound_domain()).strip().lower() or None
    position_code = str(body.get("position_code") or "").strip() or None
    position_title = str(body.get("position_title") or "").strip() or None
    label = str(body.get("label") or "").strip() or None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM intake_addresses WHERE status='active' AND lower(local_part)=%s AND lower(coalesce(domain,''))=%s LIMIT 1",
                (local_part, (domain or "")),
            )
            if cur.fetchone():
                raise HTTPException(status_code=409, detail={"error": "address_taken", "message": "That intake address is already in use."})
            try:
                cur.execute(
                    """
                    INSERT INTO intake_addresses (company_code, local_part, domain, position_code, position_title, label, created_by_user_id, created_by_email)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s)
                    RETURNING *, intake_id::text AS intake_id
                    """,
                    (company, local_part, domain, position_code, position_title, label, context.get("actor_user_id"), context.get("actor_email")),
                )
                row = dict(cur.fetchone())
            except psycopg2.IntegrityError:
                conn.rollback()
                raise HTTPException(
                    status_code=409,
                    detail={"error": "address_taken", "message": "That intake address was claimed concurrently. Retry with a new local part."},
                )
            health = _iip.fetch_intake_health(cur, company_code=company, intake_id=str(row.get("intake_id") or ""))
        conn.commit()
    record_admin_audit(
        context,
        "intake_address_created",
        summary=f"Created intake address {local_part}@{domain or ''}.",
        target_type="intake_address",
        target=str(row.get("intake_id") or ""),
        details={"local_part": local_part, "domain": domain, "position_code": position_code},
    )
    return {"ok": True, "address": intake_address_public(row, health=health)}


def _disable_intake_address(cur: Any, *, company: str, intake_id: str) -> dict[str, Any] | None:
    cur.execute(
        """
        UPDATE intake_addresses
        SET status='disabled', updated_at=now(),
            metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('disabled_at', now()::text)
        WHERE company_code=%s AND intake_id=%s AND status='active'
        RETURNING *, intake_id::text AS intake_id
        """,
        (company, intake_id),
    )
    row = cur.fetchone()
    return dict(row) if row else None


@app.post("/dashboard/prehire/integrations/intake/{intake_id}/disable")
def dashboard_intake_disable(intake_id: str, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    require_entitlement(context, "pre_hiring", "settings.manage")
    company = context["company_code"]
    require_company_inbound_email(company)
    import inbound_intake_product as _iip

    with db_connect() as conn:
        with conn.cursor() as cur:
            row = _disable_intake_address(cur, company=company, intake_id=intake_id)
            if not row:
                cur.execute(
                    "SELECT *, intake_id::text AS intake_id FROM intake_addresses WHERE company_code=%s AND intake_id=%s LIMIT 1",
                    (company, intake_id),
                )
                existing = cur.fetchone()
                if not existing:
                    raise HTTPException(status_code=404, detail={"error": "intake_not_found"})
                row = dict(existing)
            health = _iip.fetch_intake_health(cur, company_code=company, intake_id=intake_id)
        conn.commit()
    record_admin_audit(
        context,
        "intake_address_disabled",
        summary="Disabled an intake address.",
        target_type="intake_address",
        target=intake_id,
    )
    return {"ok": True, "address": intake_address_public(row, health=health)}


@app.post("/dashboard/prehire/integrations/intake/{intake_id}/rotate")
def dashboard_intake_rotate(intake_id: str, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    require_entitlement(context, "pre_hiring", "settings.manage")
    company = context["company_code"]
    require_company_inbound_email(company)
    import inbound_intake_product as _iip

    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT *, intake_id::text AS intake_id FROM intake_addresses WHERE company_code=%s AND intake_id=%s LIMIT 1",
                (company, intake_id),
            )
            existing = cur.fetchone()
            if not existing:
                raise HTTPException(status_code=404, detail={"error": "intake_not_found"})
            old = dict(existing)
            if old.get("status") != "active":
                raise HTTPException(status_code=409, detail={"error": "intake_not_active", "message": "Only an active address can be rotated."})
            disabled = _disable_intake_address(cur, company=company, intake_id=intake_id)
            if not disabled:
                raise HTTPException(status_code=409, detail={"error": "intake_disable_failed"})
            domain = old.get("domain") or _iip.inbound_domain()
            new_local = None
            for _ in range(8):
                candidate = _iip.suggest_local_part(company)
                cur.execute(
                    "SELECT 1 FROM intake_addresses WHERE status='active' AND lower(local_part)=%s AND lower(coalesce(domain,''))=%s LIMIT 1",
                    (candidate, domain or ""),
                )
                if not cur.fetchone():
                    new_local = candidate
                    break
            if not new_local:
                raise HTTPException(status_code=500, detail={"error": "intake_rotate_exhausted"})
            try:
                cur.execute(
                    """
                    INSERT INTO intake_addresses (company_code, local_part, domain, position_code, position_title, label, created_by_user_id, created_by_email, metadata)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    RETURNING *, intake_id::text AS intake_id
                    """,
                    (
                        company,
                        new_local,
                        domain,
                        old.get("position_code"),
                        old.get("position_title"),
                        old.get("label"),
                        context.get("actor_user_id"),
                        context.get("actor_email"),
                        Json({"rotated_from": intake_id}),
                    ),
                )
                created = dict(cur.fetchone())
            except psycopg2.IntegrityError:
                # Concurrent rotate race — retry with a fresh local part once more.
                conn.rollback()
                raise HTTPException(
                    status_code=409,
                    detail={"error": "intake_rotate_conflict", "message": "Address rotation raced with another create. Retry rotate."},
                )
            old_health = _iip.fetch_intake_health(cur, company_code=company, intake_id=intake_id)
            new_health = _iip.fetch_intake_health(cur, company_code=company, intake_id=str(created.get("intake_id") or ""))
        conn.commit()
    record_admin_audit(
        context,
        "intake_address_rotated",
        summary=f"Rotated intake address to {new_local}@{domain}.",
        target_type="intake_address",
        target=str(created.get("intake_id") or ""),
        details={"previous_intake_id": intake_id, "local_part": new_local, "domain": domain},
    )
    return {
        "ok": True,
        "previous": intake_address_public(disabled, health=old_health),
        "address": intake_address_public(created, health=new_health),
    }


