@app.post("/dashboard/prehire/integrations/inbound/admin-override")
def dashboard_inbound_admin_override(request: dict[str, Any] | None = None, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    """Raise limits immediately for hiring campaigns (allowlisted tenants only)."""
    require_entitlement(context, "pre_hiring", "settings.manage")
    company = context["company_code"]
    import inbound_enterprise_hardening as _ieh
    import inbound_intake_product as _iip

    if not _iip.company_on_inbound_allowlist(company):
        raise HTTPException(status_code=403, detail={"error": "inbound_tenant_not_allowlisted"})
    body = request or {}
    actor = str(context.get("actor_email") or context.get("actor_user_id") or "admin")
    override = _ieh.build_admin_override(
        actor=actor,
        quota_overrides=body.get("quota_overrides") if isinstance(body.get("quota_overrides"), dict) else None,
        burst_enabled=bool(body.get("burst_enabled", True)),
        burst_pct=int(body["burst_pct"]) if body.get("burst_pct") is not None else None,
        hours=int(body["hours"]) if body.get("hours") is not None else None,
        reason=str(body.get("reason") or "hiring_campaign_capacity"),
        per_tenant_concurrency=int(body["per_tenant_concurrency"]) if body.get("per_tenant_concurrency") is not None else None,
    )
    merged = _ieh.merge_enterprise_settings(get_company_settings(company), {"admin_override": override})
    set_company_setting(company, "inbound_enterprise", merged.get("inbound_enterprise"))
    record_admin_audit(
        context,
        "inbound_admin_override_raised",
        summary="Raised inbound capacity via admin override.",
        target_type="company",
        target=company,
        details={"override": override},
    )
    return {"ok": True, "company_code": company, "admin_override": override, "feature": _intake_feature_payload(company)}


