@app.post("/dashboard/prehire/integrations/inbound/plan")
def dashboard_inbound_plan_update(request: dict[str, Any] | None = None, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    require_entitlement(context, "pre_hiring", "settings.manage")
    company = context["company_code"]
    import inbound_enterprise_hardening as _ieh
    import inbound_intake_product as _iip

    if not _iip.company_on_inbound_allowlist(company):
        raise HTTPException(status_code=403, detail={"error": "inbound_tenant_not_allowlisted"})
    body = request or {}
    plan = str(body.get("plan") or "").strip().lower()
    if plan and plan not in _ieh.PLAN_CATALOG:
        raise HTTPException(status_code=400, detail={"error": "invalid_plan"})
    patch: dict[str, Any] = {}
    if plan:
        patch["plan"] = plan
    if "soft_warning_pct" in body:
        patch["soft_warning_pct"] = body.get("soft_warning_pct")
    if "kill_switch" in body:
        patch["kill_switch"] = bool(body.get("kill_switch"))
    if "quota_overrides" in body and isinstance(body.get("quota_overrides"), dict):
        patch["quota_overrides"] = body.get("quota_overrides")
    merged = _ieh.merge_enterprise_settings(get_company_settings(company), patch)
    set_company_setting(company, "inbound_enterprise", merged.get("inbound_enterprise"))
    # Prefer precise audit types: kill-switch-only patches vs plan/quota changes.
    if set(patch.keys()) == {"kill_switch"}:
        action = "inbound_tenant_kill_switch"
    else:
        action = "inbound_plan_updated"
    record_admin_audit(
        context,
        action,
        summary="Updated inbound enterprise plan / kill switch.",
        target_type="company",
        target=company,
        details=patch,
    )
    if "kill_switch" in patch and action == "inbound_plan_updated":
        record_admin_audit(
            context,
            "inbound_tenant_kill_switch",
            summary="Updated inbound tenant kill switch with plan change.",
            target_type="company",
            target=company,
            details={"kill_switch": bool(patch.get("kill_switch"))},
        )
    return {"ok": True, "company_code": company, "inbound_enterprise": merged.get("inbound_enterprise"), "feature": _intake_feature_payload(company)}


