@app.put("/dashboard/prehire/integrations/email")
def dashboard_email_settings_put(request: dict[str, Any] | None = None, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    require_entitlement(context, "pre_hiring", "settings.manage")
    company = context["company_code"]
    body = request or {}
    import inbound_intake_product as _iip
    import tenant_email_authority as tea

    patch: dict[str, Any] = {}
    if "outbound_mode" in body or "current_sender" in body:
        patch["outbound_mode"] = body.get("outbound_mode") or body.get("current_sender")
    for key in ("display_name", "reply_to", "from_address", "public_forward_address"):
        if key in body:
            patch[key] = body.get(key)
    if "interview_email_when_calendar_sent" in body:
        patch["interview_email_when_calendar_sent"] = bool(body.get("interview_email_when_calendar_sent"))
    if "allow_wathefni_emergency_fallback" in body:
        patch["allow_wathefni_emergency_fallback"] = bool(body.get("allow_wathefni_emergency_fallback"))
    try:
        tea.upsert_email_settings(
            sys.modules[__name__],
            company,
            patch,
            updated_by_user_id=str(context.get("actor_user_id") or "") or None,
            allow_unready_mode=False,
        )
    except tea.TenantEmailError as exc:
        raise HTTPException(status_code=exc.http_status, detail=exc.as_http_detail()) from exc

    # Tenant inbound flag / quotas (allowlisted companies only; never opens external GA).
    if "inbound_forwarding_enabled" in body or "inbound_quotas" in body:
        if not _iip.company_on_inbound_allowlist(company):
            raise HTTPException(
                status_code=403,
                detail={"error": "inbound_tenant_not_allowlisted", "message": "Inbound flags are limited to OctoHR and test tenants."},
            )
        if "inbound_forwarding_enabled" in body:
            set_company_setting(company, "inbound_forwarding_enabled", bool(body.get("inbound_forwarding_enabled")))
        if "inbound_quotas" in body and isinstance(body.get("inbound_quotas"), dict):
            set_company_setting(company, "inbound_quotas", _iip.tenant_inbound_quotas({"inbound_quotas": body.get("inbound_quotas")}))

    record_admin_audit(
        context,
        "email_settings_updated",
        summary="Updated email sending settings.",
        target_type="company_email_settings",
        target=company,
        details={"keys": sorted(list(patch.keys()) + [k for k in ("inbound_forwarding_enabled", "inbound_quotas") if k in body])},
    )
    intake_rows: list[dict[str, Any]] = []
    feature = _intake_feature_payload(company)
    if feature.get("enabled") or feature.get("allowlisted"):
        with db_connect() as conn:
            with conn.cursor() as cur:
                intake_rows = _load_company_intake_rows(cur, company)
            conn.commit()
    primary = next((r.get("address") for r in intake_rows if r.get("status") == "active"), None)
    setup = _iip.setup_instructions(primary_address=primary)
    return tea.public_email_sending_view(
        sys.modules[__name__],
        company,
        intake_addresses=intake_rows,
        intake_feature=feature,
        intake_setup=setup,
    )


@app.post("/dashboard/prehire/integrations/email/action")
def dashboard_email_settings_action(request: dict[str, Any] | None = None, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    """Primary action: connect | verify | test — company-facing, no internal details."""
    require_entitlement(context, "pre_hiring", "settings.manage")
    company = context["company_code"]
    body = request or {}
    action = str(body.get("action") or "").strip().lower()
    import tenant_email_authority as tea

    if action == "verify":
        domain = str(body.get("domain") or "").strip().lower()
        if not domain:
            settings = tea.get_email_settings(sys.modules[__name__], company)
            domain = tea._email_host(settings.get("from_address")) or tea._email_host(settings.get("public_forward_address"))
        if not domain:
            raise HTTPException(status_code=400, detail={"error": "domain_required", "message": "Enter your company domain to verify."})
        try:
            row = tea.create_or_link_domain(sys.modules[__name__], company, domain)
        except tea.TenantEmailError as exc:
            raise HTTPException(status_code=exc.http_status, detail=exc.as_http_detail()) from exc
        record_admin_audit(context, "email_domain_verify_started", summary=f"Started domain verification for {domain}.", target_type="company_email_domain", target=str(row.get("domain_id") or domain))
        return {
            "ok": True,
            "action": "verify",
            "status": row.get("verification_status"),
            "message": "Add the DNS records your IT team received, then check again.",
            "dns_records": tea.dns_records_public(row),
            "view": tea.public_email_sending_view(sys.modules[__name__], company),
        }
    if action == "test":
        # Dry connectivity check — does not email candidates.
        resolved = tea.resolve_outbound_sender(sys.modules[__name__], company, purpose="settings_test")
        ready = bool(resolved.get("activatable") and resolved.get("from_address"))
        return {
            "ok": ready,
            "action": "test",
            "status": "ready" if ready else "setup_required",
            "message": "Email sending looks ready." if ready else "Email sending still needs setup.",
            "view": tea.public_email_sending_view(sys.modules[__name__], company),
        }
    if action == "connect":
        return {
            "ok": False,
            "action": "connect",
            "status": "setup_required",
            "message": "Ask OctoHR support to connect your Microsoft mailbox. This is not self-serve yet.",
            "view": tea.public_email_sending_view(sys.modules[__name__], company),
        }
    raise HTTPException(status_code=400, detail={"error": "invalid_action", "message": "Choose Connect, Verify, or Test."})


@app.post("/dashboard/prehire/import/upload")
async def dashboard_prehire_import_upload(
    files: list[UploadFile] = File(default=[]),
    metadata_file: UploadFile | None = File(default=None),
    position_code: str | None = Form(default=None),
    position_title: str | None = Form(default=None),
    source: str | None = Form(default="bulk_upload"),
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "pre_hiring", "candidate.import")
    company = context["company_code"]
    source = (source or "bulk_upload").strip().lower()
    if source not in IMPORT_SOURCES:
        source = "bulk_upload"
    if not files:
        raise HTTPException(status_code=400, detail={"error": "no_files", "message": "Attach at least one CV file or a ZIP archive."})
    if len(files) > IMPORT_MAX_FILES:
        raise HTTPException(status_code=400, detail={"error": "too_many_files", "message": f"Import up to {IMPORT_MAX_FILES} files at a time."})

    uploaded: list[tuple[str, bytes]] = []
    total = 0
    for upload in files:
        data = await upload.read()
        total += len(data)
        if total > IMPORT_MAX_TOTAL_BYTES:
            raise HTTPException(status_code=400, detail={"error": "upload_too_large", "message": "Total upload exceeds the size limit."})
        uploaded.append((upload.filename or "file", data))

    metadata_rows: dict[str, dict[str, str]] = {}
    if metadata_file is not None and metadata_file.filename:
        meta_suffix = Path(metadata_file.filename).suffix.lower()
        if meta_suffix not in IMPORT_METADATA_EXTENSIONS:
            raise HTTPException(status_code=400, detail={"error": "unsupported_metadata", "message": "Metadata must be a .csv or .xlsx file."})
        try:
            metadata_rows = parse_import_metadata_file(metadata_file.filename, await metadata_file.read())
        except Exception as exc:
            raise HTTPException(status_code=400, detail={"error": "metadata_parse_failed", "message": f"Could not read the metadata file: {exc}"})

    result = process_bulk_cv_import(
        company_code=company,
        created_by_user_id=context.get("actor_user_id"),
        created_by_email=context.get("actor_email"),
        uploaded_files=uploaded,
        metadata_rows=metadata_rows,
        default_position_code=(position_code or "").strip() or None,
        default_position_title=(position_title or "").strip() or None,
        source=source,
    )
    return {"ok": True, **result}


