@app.get("/dashboard/prehire/import/intake")
def dashboard_prehire_import_intake(
    limit: int = Query(default=500, ge=1, le=2000),
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    """Intake workspace: uncertain/needs-review imports grouped by suggested role.

    Only candidates still held in the Intake queue (needs_role / import_review) appear
    here. Auto-admitted candidates are already in Candidates and are excluded.
    """
    require_entitlement(context, "pre_hiring", "candidate.import")
    company = context["company_code"]
    held = ",".join("'%s'" % s for s in INTAKE_REVIEW_STATUSES)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT a.app_key, a.status, a.position_code, a.position_title,
                       a.import_batch_id::text AS import_batch_id,
                       a.raw_json->'import'->>'original_filename' AS original_filename,
                       a.raw_json->'import'->>'source' AS import_source,
                       a.raw_json->'import'->'role_suggestion'->>'suggested_code' AS suggested_code,
                       a.raw_json->'import'->'role_suggestion'->>'suggested_title' AS suggested_title,
                       (a.raw_json->'import'->'role_suggestion'->>'confidence')::float AS suggestion_confidence,
                       a.raw_json->'import'->'role_suggestion'->>'source' AS suggestion_source,
                       COALESCE((a.raw_json->'import'->>'identity_review_warning')::boolean, false) AS identity_review_warning,
                       a.raw_json->'import'->>'identity_terminal_reason' AS identity_terminal_reason,
                       a.raw_json->'import'->>'identity_outcome' AS identity_outcome,
                       c.name AS candidate_name, c.email AS candidate_email, a.ingested_at
                FROM applications a
                LEFT JOIN candidates c ON c.phone=a.phone
                WHERE a.company_code=%s AND a.status IN ({held})
                ORDER BY a.ingested_at DESC NULLS LAST
                LIMIT %s
                """,
                (company, int(limit)),
            )
            rows = [dict(r) for r in cur.fetchall()]
            cur.execute(
                "SELECT COUNT(*) AS c FROM applications WHERE company_code=%s "
                "AND status NOT IN ('needs_role','import_review','import_archived') "
                "AND raw_json->'import'->>'auto_admitted' = 'true'",
                (company,),
            )
            auto_admitted_total = int((cur.fetchone() or {}).get("c") or 0)

    groups: dict[str, dict[str, Any]] = {}
    for r in rows:
        # An explicit role held for review (auto-admit off) groups by its assigned role;
        # otherwise group by the suggested role; otherwise it is unclear / needs a role.
        role_code = (r.get("position_code") or "").strip() or (r.get("suggested_code") or "").strip()
        role_title = (r.get("position_title") or "").strip() or (r.get("suggested_title") or "").strip()
        if r.get("position_code"):
            kind, confidence = "explicit_review", "high"
        elif r.get("suggested_code"):
            kind, confidence = "suggested", _intake_confidence_label(r.get("suggestion_confidence"))
        else:
            kind, confidence = "unclear", "none"
        key = role_code.upper() if role_code else "__unclear__"
        grp = groups.get(key)
        if grp is None:
            grp = {
                "key": key,
                "kind": kind,
                "role_code": role_code or None,
                "role_title": role_title or None,
                "confidence": confidence,
                "count": 0,
                "app_keys": [],
                "items": [],
            }
            groups[key] = grp
        grp["count"] += 1
        grp["app_keys"].append(r.get("app_key"))
        grp["items"].append({
            "app_key": r.get("app_key"),
            "candidate_name": r.get("candidate_name"),
            "candidate_email": r.get("candidate_email"),
            "original_filename": r.get("original_filename"),
            "import_source": r.get("import_source"),
            "status": r.get("status"),
            "identity_review_warning": bool(r.get("identity_review_warning")),
            "identity_terminal_reason": r.get("identity_terminal_reason"),
            "identity_outcome": r.get("identity_outcome"),
            "suggested_code": r.get("suggested_code"),
            "suggested_title": r.get("suggested_title"),
            "suggestion_confidence": r.get("suggestion_confidence"),
            "suggestion_source": r.get("suggestion_source"),
        })

    def _sort_key(g: dict[str, Any]) -> tuple:
        order = {"explicit_review": 0, "suggested": 1, "unclear": 2}
        conf = {"high": 0, "medium": 1, "low": 2, "none": 3}
        return (order.get(g["kind"], 9), conf.get(g["confidence"], 9), -g["count"])

    grouped = sorted(groups.values(), key=_sort_key)
    return {
        "company_code": company,
        "total": len(rows),
        "auto_admit_explicit_imports": company_auto_admit_imports(company),
        "auto_admitted_total": auto_admitted_total,
        "groups": json_safe(grouped),
    }


@app.post("/dashboard/prehire/import/items/bulk")
def dashboard_prehire_import_bulk(
    request: dict[str, Any],
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    """Bulk Intake actions: confirm (use suggested/assigned role), assign (set one role),
    or archive (drop noise). All company-scoped and limited to held Intake candidates."""
    require_entitlement(context, "pre_hiring", "candidate.import")
    company = context["company_code"]
    action = str((request or {}).get("action") or "").strip().lower()
    app_keys = [str(k).strip() for k in ((request or {}).get("app_keys") or []) if str(k).strip()]
    position_code = str((request or {}).get("position_code") or "").strip()
    position_title = str((request or {}).get("position_title") or "").strip()
    if action not in ("confirm", "assign", "archive"):
        raise HTTPException(status_code=400, detail={"error": "invalid_action"})
    if not app_keys:
        raise HTTPException(status_code=400, detail={"error": "app_keys_required"})
    if len(app_keys) > 1000:
        raise HTTPException(status_code=400, detail={"error": "too_many_items", "message": "Select at most 1000 at a time."})
    actor = context.get("actor_email")
    summary = {"updated": 0, "skipped": 0, "archived": 0, "promoted": 0}
    promotions: list[dict[str, Any]] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            for app_key in app_keys:
                cur.execute(
                    """
                    SELECT app_key, status, position_code, position_title, phone,
                           raw_json->'import'->'role_suggestion'->>'suggested_code' AS suggested_code,
                           raw_json->'import'->'role_suggestion'->>'suggested_title' AS suggested_title
                    FROM applications WHERE app_key=%s AND company_code=%s LIMIT 1
                    """,
                    (app_key, company),
                )
                row = cur.fetchone()
                if not row or str(row.get("status") or "") not in INTAKE_REVIEW_STATUSES:
                    summary["skipped"] += 1
                    continue
                if action == "archive":
                    cur.execute(
                        """
                        UPDATE applications
                        SET status='import_archived',
                            raw_json=COALESCE(raw_json,'{}'::jsonb) || jsonb_build_object(
                                'import', COALESCE(raw_json->'import','{}'::jsonb) || jsonb_build_object(
                                    'archived', true, 'archived_by', %s, 'archived_at', %s
                                )
                            ),
                            updated_at=CURRENT_DATE
                        WHERE app_key=%s AND company_code=%s
                        """,
                        (actor, now_iso(), app_key, company),
                    )
                    summary["updated"] += 1
                    summary["archived"] += 1
                    continue
                if action == "assign":
                    eff_code = position_code or str(row.get("position_code") or "").strip() or str(row.get("suggested_code") or "").strip()
                    eff_title = position_title or str(row.get("position_title") or "").strip() or str(row.get("suggested_title") or "").strip()
                else:  # confirm: trust the existing assigned/suggested role
                    eff_code = str(row.get("position_code") or "").strip() or str(row.get("suggested_code") or "").strip()
                    eff_title = str(row.get("position_title") or "").strip() or str(row.get("suggested_title") or "").strip()
                if not eff_code:
                    summary["skipped"] += 1
                    continue
                cur.execute(
                    """
                    UPDATE applications
                    SET position_code=%s, position_title=%s,
                        raw_json=COALESCE(raw_json,'{}'::jsonb) || jsonb_build_object(
                            'import', COALESCE(raw_json->'import','{}'::jsonb) || jsonb_build_object(
                                'needs_role', false, 'promoted', true, 'promoted_at', %s,
                                'role_assigned_by', %s, 'promoted_via', %s
                            )
                        ),
                        updated_at=CURRENT_DATE
                    WHERE app_key=%s AND company_code=%s
                    """,
                    (eff_code, eff_title or None, now_iso(), actor, "bulk_" + action, app_key, company),
                )
                cur.execute(
                    "UPDATE candidates SET active_position_code=%s, updated_at=now() WHERE phone=%s",
                    (eff_code, row.get("phone")),
                )
                cur.execute(
                    "UPDATE import_items SET position_code=%s, position_title=%s, updated_at=now() WHERE app_key=%s AND company_code=%s",
                    (eff_code, eff_title or None, app_key, company),
                )
                promotions.append({**dict(row), "app_key": app_key, "position_code": eff_code, "position_title": eff_title})
        conn.commit()
    for promotion in promotions:
        lifecycle_result = update_application_status(
            {**promotion, "company_code": company},
            "ready_for_review",
            trigger="intake_admit",
            actor_type="system",
            actor_user_id=str(context.get("actor_user_id") or "") or None,
            channel="web",
            human_confirmed=False,
            idempotency_key=f"intake-admit:{company}:{promotion['app_key']}:{promotion['position_code']}",
            metadata={"position_code": promotion["position_code"], "import_admit": True, "bulk": True},
        )
        if lifecycle_result.get("ok"):
            summary["updated"] += 1
            summary["promoted"] += 1
        else:
            summary["skipped"] += 1
    record_admin_audit(
        context,
        "import_bulk_action",
        summary=f"Bulk {action}: {summary['updated']} updated, {summary['archived']} archived, {summary['skipped']} skipped.",
        target_type="import_batch",
        target=None,
        details={"action": action, "counts": dict(summary), "app_key_count": len(app_keys)},
    )
    return {"ok": True, "company_code": company, "action": action, **summary}


@app.get("/dashboard/prehire/import/batches/{batch_id}/report.csv")
def dashboard_prehire_import_report(batch_id: str, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    require_entitlement(context, "pre_hiring", "candidate.import")
    company = context["company_code"]
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM import_batches WHERE batch_id=%s AND company_code=%s LIMIT 1",
                (batch_id, company),
            )
            if not cur.fetchone():
                raise HTTPException(status_code=404, detail={"error": "import_batch_not_found"})
            cur.execute(
                """
                SELECT original_filename, status, candidate_name, candidate_email, position_code,
                       app_key, duplicate_of_app_key, error
                FROM import_items WHERE batch_id=%s ORDER BY status, original_filename
                """,
                (batch_id,),
            )
            rows = cur.fetchall()
    buffer = io.StringIO()
    writer = csv.writer(buffer)
    writer.writerow(["filename", "status", "candidate_name", "candidate_email", "position_code", "app_key", "duplicate_of", "error"])
    for r in rows:
        writer.writerow([
            r.get("original_filename") or "", r.get("status") or "", r.get("candidate_name") or "",
            r.get("candidate_email") or "", r.get("position_code") or "", r.get("app_key") or "",
            r.get("duplicate_of_app_key") or "", r.get("error") or "",
        ])
    return StreamingResponse(
        io.BytesIO(buffer.getvalue().encode("utf-8")),
        media_type="text/csv",
        headers={"Content-Disposition": f"attachment; filename=import-{batch_id}.csv"},
    )


@app.post("/dashboard/prehire/applications/{app_key}/confirmations")
def dashboard_prepare_candidate_confirmation(
    app_key: str,
    body: DashboardCandidateConfirmationRequest,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    import recruiting_lifecycle as _rl

    company = str(context.get("company_code") or "").strip().upper()
    if not company:
        raise HTTPException(status_code=403, detail={"error": "tenant_scope_required"})
    required = _rl.HUMAN_DECISION_ACTIONS.get(body.action, {}).get("permission") or "candidate.manage"
    require_entitlement(context, "pre_hiring", required)
    application = dashboard_application_or_404(app_key, company, context)
    actor_user_id = str(
        context.get("actor_user_id")
        or context.get("permission_subject_user_id")
        or (context.get("hr_user") or {}).get("user_id")
        or ""
    ).strip() or None
    target_payload = json_safe(body.target_payload)
    hire_operation = None
    if body.action == "hire":
        import hire_operations as _hire_operations

        prepared = _hire_operations.prepare_hire_operation(
            sys.modules[__name__],
            company_code=company,
            app_key=app_key,
            idempotency_key=body.idempotency_key,
            expected_from_stage=body.observed_stage,
            expected_version=body.observed_version,
            actor_user_id=actor_user_id,
            actor_phone=digits(context.get("hr_phone")),
            channel="web",
            structured_reason=target_payload,
        )
        if not prepared.get("ok"):
            raise HTTPException(status_code=409, detail=prepared)
        hire_operation = prepared["operation"]
        target_payload = {
            **target_payload,
            "operation_id": hire_operation["operation_id"],
            "hiring_reference": hire_operation["operation_id"],
        }
    result = _rl.mint_candidate_action_confirmation(
        sys.modules[__name__],
        company_code=company,
        app_key=app_key,
        action=body.action,
        observed_stage=body.observed_stage,
        observed_version=body.observed_version,
        target_payload=target_payload,
        actor_user_id=actor_user_id,
        actor_phone=digits(context.get("hr_phone")),
        actor_type="human",
        channel="web",
        permissions=set(context.get("permissions") or []),
        idempotency_key=f"candidate-confirm:{body.idempotency_key}",
    )
    if not result.get("ok"):
        status_code = 409 if result.get("error") in {"stale_state", "transition_not_allowed", "idempotency_conflict"} else 422
        raise HTTPException(status_code=status_code, detail=result)
    return {"ok": True, **result, "hire_operation": hire_operation, "application": json_safe(application)}


@app.post("/dashboard/prehire/applications/{app_key}/shortlist")
def dashboard_prehire_shortlist(
    app_key: str,
    body: DashboardCandidateDecisionRequest,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "pre_hiring", "candidate.manage")
    company = context["company_code"]
    application = dashboard_application_or_404(app_key, company, context)
    update_result = update_application_status(
        application,
        "shortlisted",
        trigger="dashboard_shortlist",
        human_confirmed=True,
        actor_type="human",
        actor_user_id=str(
            context.get("actor_user_id")
            or context.get("permission_subject_user_id")
            or (context.get("hr_user") or {}).get("user_id")
            or ""
        ) or None,
        actor_phone=digits(context.get("hr_phone")),
        channel="web",
        permissions=set(context.get("permissions") or []),
        expected_from_stage=body.observed_stage,
        expected_version=body.observed_version,
        confirmation_id=body.confirmation_id,
        confirmation_token=body.confirmation_token,
        confirmation_action="shortlist",
        confirmation_payload=body.target_payload,
        idempotency_key=f"web-shortlist:{company}:{app_key}:{body.confirmation_id}",
        metadata=body.target_payload,
    )
    update_ok = bool(update_result.get("ok"))
    status = "completed" if update_ok else "failed"
    name = application.get("candidate_name") or application.get("phone") or "the candidate"
    if update_ok:
        reply = f"{name} is shortlisted."
    else:
        reply = f"I could not shortlist {name}."
        if update_result.get("error") == "stale_state":
            reply = "This candidate’s status changed. Refresh and try again."
        elif update_result.get("error") == "transition_not_allowed":
            reply = f"{name} cannot be shortlisted from the current stage."
        elif update_result.get("error") == "confirmation_required":
            reply = "Confirmation is required before shortlisting."
    result_payload = {
        "application": json_safe(application),
        "update": update_result,
        "action": {"type": "shortlist_candidate", "target_type": "application", "target": app_key},
        "source": "dashboard",
        "company_code": company,
        "requested_by": context.get("hr_user"),
    }
    return dashboard_prehire_mutation_response(
        action_type="shortlist_candidate",
        status=status,
        reply=reply,
        result_payload=result_payload,
        app_key=app_key,
        company_code=company,
        permissions=context.get("permissions") or [],
    )


