@app.post("/dashboard/prehire/applications/{app_key}/hire")
def dashboard_prehire_hire(
    app_key: str,
    body: DashboardHireRequest,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "pre_hiring", "candidate.decide")
    company = context["company_code"]
    application = dashboard_application_or_404(app_key, company, context)
    payload = body
    hire_override = bool(payload.hire_override)
    override_reason = payload.override_reason
    if hire_override and not payload.confirm:
        raise HTTPException(
            status_code=422,
            detail={"error": "override_confirm_required", "message": "Confirm hire override explicitly."},
        )
    import offer_service as _offer_service
    import offer_lifecycle as _offers

    operation_id = str(payload.target_payload.get("operation_id") or "").strip()
    if not operation_id:
        raise HTTPException(status_code=422, detail={"error": "hiring_reference_required"})
    try:
        offer_gate = _offer_service.enforce_hire_gate(
            sys.modules[__name__],
            company_code=company,
            app_key=app_key,
            permissions=set(context.get("permissions") or []),
            hire_override=hire_override,
            override_reason=str(override_reason or "") or None,
            actor_user_id=str(context.get("actor_user_id") or "") or None,
            actor_subject=str(
                context.get("actor_user_id")
                or context.get("permission_subject_user_id")
                or (context.get("hr_user") or {}).get("user_id")
                or ""
            )
            or None,
            actor_type="human",
            confirmation_token=str(payload.confirmation_id or "") or None,
            confirmed=bool(payload.confirm) if hire_override else False,
            expected_from_stage=str(application.get("status") or "") or None,
            idempotency_key=f"web-hire-override:{company}:{app_key}:{payload.confirmation_token or payload.confirm}",
        )
    except _offers.OfferAuthorityError as exc:
        raise HTTPException(status_code=exc.status_code, detail=exc.as_detail()) from exc
    import hire_operations as _hire_operations

    try:
        hire_result = _hire_operations.execute_hire_operation(
            sys.modules[__name__],
            operation_id=operation_id,
            confirmation_id=payload.confirmation_id,
            confirmation_token=payload.confirmation_token,
            permissions=set(context.get("permissions") or []),
        )
    except Exception as exc:
        if offer_gate.get("override"):
            _offer_service.record_hire_override_outcome(
                sys.modules[__name__],
                audit_id=offer_gate.get("audit_id"),
                hire_result={"ok": False, "error": type(exc).__name__},
                hire_operation_id=operation_id,
            )
        raise
    if offer_gate.get("override"):
        _offer_service.record_hire_override_outcome(
            sys.modules[__name__],
            audit_id=offer_gate.get("audit_id"),
            hire_result=hire_result,
            hire_operation_id=operation_id,
        )
    update_result = hire_result.get("transition") if isinstance(hire_result.get("transition"), dict) else hire_result
    posthire_result = update_result.get("side_effect") if isinstance(update_result, dict) else None
    ok = bool(hire_result.get("ok"))
    status = "completed" if ok else "failed"
    name = application.get("candidate_name") or application.get("phone") or "the candidate"
    reply = f"{name} is hired and employee setup is done." if ok else f"I could not complete hiring for {name}."
    if not ok and update_result.get("error") == "stale_state":
        reply = "This candidate’s status changed. Refresh and try again."
    elif not ok and update_result.get("error") == "transition_not_allowed":
        reply = f"{name} cannot be hired from the current stage."
    result_payload = {
        "application": json_safe(application),
        "update": update_result,
        "posthire": posthire_result,
        "hire_operation": hire_result,
        "action": {"type": "hire_candidate", "target_type": "application", "target": app_key},
        "source": "dashboard",
        "company_code": company,
        "requested_by": context.get("hr_user"),
        "hire_override": hire_override,
    }
    return dashboard_prehire_mutation_response(
        action_type="hire_candidate",
        status=status,
        reply=reply,
        result_payload=result_payload,
        app_key=app_key,
        company_code=company,
        permissions=context.get("permissions") or [],
    )


@app.post("/dashboard/prehire/applications/{app_key}/notify")
def dashboard_prehire_notify(
    app_key: str,
    request: DashboardCandidateMessage | None = None,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "pre_hiring", "candidate.manage")
    company = context["company_code"]
    application = dashboard_application_or_404(app_key, company, context)
    require_live_candidate_communication(
        application,
        kind="notify",
        expected_company_code=company,
    )  # HELD_COMMUNICATION_AUTHORITY_PRODUCTION_COMPAT
    payload = request or DashboardCandidateMessage()
    if _prehire_registry_enabled("notify_candidate"):
        extra = {"message_text": payload.message} if payload.message else {}
        return run_prehire_registry_action(context, "notify_candidate", extra, app_key=app_key)
    result = notify_candidate(application, payload.account_id or "default", payload.message)
    status = "completed" if result.get("ok") else "failed"
    name = application.get("candidate_name") or application.get("phone") or "the candidate"
    send_error = (result.get("send") or {}).get("error") if isinstance(result.get("send"), dict) else None
    if result.get("ok"):
        reply = f"{name} was notified."
    elif send_error == "conversation_closed":
        reply = f"I found {name}, but WhatsApp conversation is not active."
    else:
        reply = f"I could not notify {name}."
    result_payload = {
        **result,
        "application": json_safe(application),
        "action": {"type": "notify_candidate", "target_type": "application", "target": app_key},
        "source": "dashboard",
        "company_code": company,
        "requested_by": context.get("hr_user"),
    }
    return dashboard_prehire_mutation_response(
        action_type="notify_candidate",
        status=status,
        reply=reply,
        result_payload=result_payload,
        app_key=app_key,
        company_code=company,
        permissions=context.get("permissions") or [],
    )


@app.post("/dashboard/prehire/applications/{app_key}/assessment")
def dashboard_prehire_assessment(
    app_key: str,
    request: DashboardCandidateMessage | None = None,
    context: dict[str, Any] = Depends(assessments_dashboard_context),
):
    require_entitlement(context, "assessments", "assessment.manage")
    company = context["company_code"]
    application = dashboard_application_or_404(app_key, company, context)
    require_live_candidate_communication(
        application,
        kind="assessment",
        expected_company_code=company,
    )  # HELD_COMMUNICATION_AUTHORITY_PRODUCTION_COMPAT
    payload = request or DashboardCandidateMessage()
    selected_battery_key = str(payload.battery_key or "").strip() or None
    locale = str(payload.locale or "").strip().lower() or None
    if locale and not selected_battery_key:
        # Locale maps onto the Battery-1 beta pair when HR chooses EN/AR without an explicit key.
        locale_map = {
            "en": "wathefni_gawj_v1_en_beta",
            "ar": "wathefni_gawj_v1_ar_beta",
        }
        selected_battery_key = locale_map.get(locale)
    if _prehire_registry_enabled("send_assessment"):
        extra = {"message_text": payload.message} if payload.message else {}
        if selected_battery_key:
            extra["battery_key"] = selected_battery_key
        if locale:
            extra["locale"] = locale
        if payload.expires_days is not None:
            extra["expires_days"] = payload.expires_days
        actor_id = assessment_dashboard_actor_id(context)
        if actor_id:
            extra["requested_by"] = actor_id
            extra["actor_user_id"] = actor_id
        return run_prehire_registry_action(context, "send_assessment", extra, app_key=app_key)
    result = send_assessment(
        application,
        payload.account_id or "default",
        note=payload.message,
        requested_by=assessment_dashboard_actor_id(context),
        battery_key=selected_battery_key,
        expires_days=payload.expires_days,
        locale=locale,
    )
    status = "completed" if result.get("ok") else "failed"
    name = application.get("candidate_name") or application.get("phone") or "the candidate"
    send_error = (result.get("send") or {}).get("error") if isinstance(result.get("send"), dict) else None
    if result.get("ok"):
        reply = f"Assessment message sent to {name}."
    elif send_error == "conversation_closed":
        reply = f"I found {name}, but WhatsApp conversation is not active."
    else:
        reply = f"I could not send the assessment to {name}."
    result_payload = {
        **result,
        "application": json_safe(application),
        "action": {
            "type": "send_assessment",
            "target_type": "application",
            "target": app_key,
            "battery_key": selected_battery_key,
            "locale": locale,
            "expires_days": payload.expires_days,
        },
        "source": "dashboard",
        "company_code": company,
        "requested_by": context.get("hr_user"),
    }
    return dashboard_prehire_mutation_response(
        action_type="send_assessment",
        status=status,
        reply=reply,
        result_payload=result_payload,
        app_key=app_key,
        company_code=company,
        permissions=context.get("permissions") or [],
    )


@app.post("/dashboard/prehire/applications/{app_key}/video-interview")
def dashboard_prehire_video_interview(
    app_key: str,
    request: DashboardVideoInterviewRequest | None = None,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "video_interviews", "interview.manage")
    company = context["company_code"]
    application = dashboard_application_or_404(app_key, company, context)
    payload = request or DashboardVideoInterviewRequest()
    if payload.send_invite:
        require_live_candidate_communication(application, kind="video_interview", expected_company_code=company)  # HELD_COMMUNICATION_AUTHORITY_STAGING_PATCH
    # The registry executor always sends the invite; only route the
    # send-the-invite case through it. The prepare-link-only case
    # (send_invite=False) stays on the legacy path to preserve behavior.
    if payload.send_invite and _prehire_registry_enabled("send_video_interview"):
        extra: dict[str, Any] = {}
        if payload.preferred_channel:
            extra["preferred_channel"] = payload.preferred_channel
        if payload.message:
            extra["message_text"] = payload.message
        return run_prehire_registry_action(context, "send_video_interview", extra, app_key=app_key)
    actor = actor_context_for_hr_user(context.get("hr_user"), company_code=company, hr_phone=context.get("hr_phone"))
    created = create_or_resume_async_video_interview(application, payload, actor_context={**actor, "actor_role": context.get("actor_role") or actor.get("actor_role")})
    interview = created["interview"]
    public_link = created["public_link"]
    if payload.send_invite:
        result = send_async_video_interview_invite(
            application,
            interview,
            public_link,
            account_id=payload.account_id or "default",
            preferred_channel=payload.preferred_channel,
            actor_context={**actor, "actor_role": context.get("actor_role") or actor.get("actor_role")},
            note=payload.message,
        )
    else:
        result = {
            "ok": True,
            "interview": candidate_interview_summary(interview),
            "public_link": public_link,
            "delivery": {"skipped": True},
        }
    status = "completed" if result.get("ok") else "failed"
    name = application.get("candidate_name") or application.get("phone") or "the candidate"
    reply = f"AI video interview link prepared for {name}." if result.get("ok") else f"I prepared the AI video interview, but could not send the link to {name}."
    result_payload = {
        **result,
        "application": json_safe(application),
        "action": {"type": "send_video_interview", "target_type": "application", "target": app_key, "interview_id": str(interview.get("interview_id") or "")},
        "source": "dashboard",
        "company_code": company,
        "company_id": company,
        "actor_user_id": actor.get("actor_user_id"),
        "actor_phone": actor.get("actor_phone"),
        "actor_role": context.get("actor_role") or actor.get("actor_role"),
        "requested_by": context.get("hr_user"),
    }
    return dashboard_prehire_mutation_response(
        action_type="send_video_interview",
        status=status,
        reply=reply,
        result_payload=result_payload,
        app_key=app_key,
        company_code=company,
        permissions=context.get("permissions") or [],
    )


# ---------------------------------------------------------------------------
# Post-hire dashboard (Employees / Onboarding / Attendance / Leave / Shifts /
# Payroll / Analytics)
#
# These endpoints give the dashboard native module pages that are as safe as the
# AI Recruiter. Mutations do NOT call the legacy executors directly — they run
# through the SAME action-registry path the AI Recruiter uses
# (tool_call_orchestrator._execute_tool), so they inherit, unchanged:
#   * per-module entitlement + RBAC (TOOL_PERMISSION_MAP, require_entitlement)
#   * preflight + confirmation (pending_actions + action_hash)
#   * company-boundary enforcement (company comes from the authenticated session,
#     never from the client — client args are whitelisted to the registry spec)
#   * HR-safe result messages (normalize_posthire_result)
# Reads reuse the existing list_* query functions, gated by <module>.read.
# ---------------------------------------------------------------------------

def dashboard_context_has_permission(context: dict[str, Any], permission: str) -> bool:
    """Soft, fail-closed check against a backend-authoritative permission set."""
    requested = str(permission or "").strip()
    if not requested:
        return False
    perms = context_permissions(context)
    if "*:*" in perms:
        return True
    return requested in perms


def posthire_employee_card(row: dict[str, Any]) -> dict[str, Any]:
    data = row if isinstance(row, dict) else {}
    raw = data.get("raw_json") if isinstance(data.get("raw_json"), dict) else {}
    profile = data.get("profile") if isinstance(data.get("profile"), dict) else {}
    department = (
        data.get("department") or data.get("team") or profile.get("department")
        or profile.get("team") or raw.get("department") or raw.get("team") or ""
    )
    email = data.get("email") or profile.get("email") or raw.get("email") or ""
    status = normalize_text(data.get("onboarding_status") or raw.get("onboarding_status") or "not_started") or "not_started"
    # Lifecycle hub projection: active | left | pending_start (joining/future).
    # Absent/blank rows (legacy) still read as active. Never invent active over
    # an explicit pending_start.
    employment_status = normalize_text(data.get("employment_status") or "") or "active"
    return json_safe({
        "employee_key": str(data.get("employee_key") or ""),
        "name": data.get("name") or raw.get("name") or "Unnamed employee",
        "phone": data.get("phone") or "",
        "email": email,
        "position_title": data.get("position_title") or raw.get("position_title") or raw.get("role") or "",
        "department": department,
        "onboarding_status": status,
        "employment_status": employment_status,
        "start_date": data.get("start_date"),
        "updated_at": data.get("updated_at"),
    })


POSTHIRE_DASHBOARD_MODULES = POSTHIRE_MODULES
# Args the dashboard may pass through besides each action's declared registry
# fields. Everything else (company_code, actor_*, viewer_phone, ...) is dropped
# so the client can never widen scope or impersonate.
_POSTHIRE_EXTRA_ARG_KEYS = {"query"}


class PosthireActionRequest(BaseModel):
    action_type: str
    args: dict[str, Any] = Field(default_factory=dict)


def posthire_dashboard_conversation_id(context: dict[str, Any]) -> str:
    company = require_company_code(context.get("company_code"))
    actor = str(context.get("actor_user_id") or digits(context.get("hr_phone")) or "dashboard")
    return f"dashboard-posthire:{company}:{actor}"


def posthire_dashboard_scope(context: dict[str, Any], conversation_id: str) -> dict[str, Any]:
    permissions = sorted({str(p) for p in (context.get("permissions") or []) if str(p).strip()})
    access = context.get("access") if isinstance(context.get("access"), dict) else {}
    authority = str(
        context.get("permission_authority")
        or access.get("permission_authority")
        or ""
    ).strip()
    subject_user_id = str(
        context.get("permission_subject_user_id")
        or access.get("permission_subject_user_id")
        or context.get("actor_user_id")
        or ""
    ).strip()
    subject_company = str(
        context.get("permission_subject_company")
        or access.get("permission_subject_company")
        or context.get("company_code")
        or ""
    ).strip().upper()
    return {
        "company_id": context["company_code"],
        "account_id": context["company_code"],
        "admin_user_id": str(context.get("actor_user_id") or digits(context.get("hr_phone")) or "dashboard"),
        "actor_email": context.get("actor_email") or "",
        "conversation_id": conversation_id,
        # Stable per-surface session id. Required by the orchestrator's pending-
        # action lookup (_find_active_pending) so confirmation actions — like the
        # auto-confirmed Pre-Hiring buttons — resolve their saved plan instead of
        # raising KeyError('session_id').
        "session_id": conversation_id,
        "channel": "web_dashboard",
        "module": "pre_hiring",
        "role_scope": context.get("actor_role") or "viewer",
        "permissions": permissions,
        # HR-0: preserve trusted authority markers so tool-call entitlement checks
        # see the same backend_current grants as HTTP dashboard handlers.
        "permission_authority": authority,
        "permission_subject_user_id": subject_user_id,
        "permission_subject_company": subject_company,
        "hr_user": context.get("hr_user") if isinstance(context.get("hr_user"), dict) else None,
        "access": {
            "role": context.get("actor_role") or access.get("role") or "viewer",
            "permissions": permissions,
            "permission_authority": authority,
            "permission_subject_user_id": subject_user_id,
            "permission_subject_company": subject_company,
        },
    }


def posthire_whitelisted_args(action_type: str, args: dict[str, Any]) -> dict[str, Any]:
    """Keep only the fields the registry declares for this action (plus a small
    safe extra set). Blocks company_code/actor spoofing and stray keys."""
    import action_registry as _registry

    spec = _registry.spec_for(action_type)
    if not spec:
        return {}
    allowed = set(spec.required_fields) | set(spec.optional_fields) | _POSTHIRE_EXTRA_ARG_KEYS
    cleaned: dict[str, Any] = {}
    for key, value in (args or {}).items():
        if key in allowed and value not in (None, "", [], {}):
            cleaned[key] = value
    return cleaned


def posthire_action_module(action_type: str) -> str | None:
    import action_registry as _registry

    spec = _registry.spec_for(action_type)
    module = str(getattr(spec, "module", "") or "") if spec else ""
    return module or None


def run_dashboard_registry_action(
    context: dict[str, Any],
    action_type: str,
    args: dict[str, Any],
    *,
    allowed_modules: tuple[str, ...] | frozenset[str] | set[str],
    conversation_id: str,
    scope: dict[str, Any],
    audit_target_type: str = "employee",
) -> dict[str, Any]:
    """Execute a registry action on behalf of an authenticated dashboard user.

    This is the single, shared harness behind native dashboard buttons. It runs
    the SAME action-registry path the Wathefni Assistant uses
    (tool_call_orchestrator._execute_tool), so it inherits company-boundary
    enforcement, per-module entitlement + RBAC, preflight + confirmation
    (pending_actions + action_hash), HR-safe messaging, and audit — unchanged.

    The orchestrator decides whether the action needs confirmation; the dashboard
    preflights (first call) then re-sends the identical request to confirm
    (second call), exactly like the Assistant's two-turn confirmation.

    `allowed_modules` restricts which modules a given surface may invoke; the
    company always comes from the authenticated session (never the client), and
    client args are whitelisted to the registry spec so scope cannot widen.
    """
    import tool_call_orchestrator as _tco

    module = posthire_action_module(action_type)
    if not module or module not in allowed_modules:
        raise HTTPException(status_code=404, detail={"error": "unknown_action", "message": "That action is not available."})
    safe_args = posthire_whitelisted_args(action_type, args)
    company = context["company_code"]
    turn_request = WhatsAppTurnRequest(
        account_id=company,
        conversation_id=conversation_id,
        sender_phone=digits(context.get("hr_phone")) or "dashboard",
        sender_role="hr_admin",
        raw_text=f"[dashboard] {action_type}",
        metadata={
            "channel": "web_dashboard",
            "dashboard": True,
            DASHBOARD_TURN_AUTHORITY_KEY: _DASHBOARD_TURN_AUTHORITY_NONCE,
            "company_code": company,
            "permissions": scope["permissions"],
            "admin_user": context.get("hr_user"),
            "access": context.get("access"),
        },
    )
    token = set_active_company_code(company)
    try:
        outcome = _tco._execute_tool(action_type, safe_args, turn_request, {}, {}, scope)
    finally:
        reset_active_company_code(token)

    status = str(outcome.get("status") or "")
    result = outcome.get("result") if isinstance(outcome.get("result"), dict) else {}
    safe_message = str(result.get("safe_user_message") or result.get("message") or "").strip()

    if status == "needs_confirmation":
        plan = outcome.get("preflight_plan") if isinstance(outcome.get("preflight_plan"), dict) else {}
        confirm_text = str(plan.get("confirmation_text") or plan.get("message") or safe_message or "Please confirm this action.").strip()
        return {
            "ok": False,
            "status": "needs_confirmation",
            "message": confirm_text,
            "confirmation": {
                "text": confirm_text,
                "action_type": action_type,
                "args": safe_args,
                "action_hash": outcome.get("action_hash"),
            },
            "result": None,
        }

    if status in {"permission_denied", "module_disabled"}:
        # Never leak tool/permission/module internals to HR copy.
        message = "You do not have access to do that." if status == "permission_denied" else "This module is not enabled for your company."
        raise HTTPException(status_code=403, detail={"error": status, "message": message})

    if status in {"needs_clarification", "needs_candidate_reference"}:
        return {"ok": False, "status": "needs_clarification", "message": safe_message or "I need a little more detail to do that.", "confirmation": None, "result": json_safe(result)}

    if status == "mutations_disabled":
        # Assistant mutation kill should not hit web_dashboard; if it does, never
        # pretend success and never leave HR with opaque assistant-session copy.
        reply = (
            safe_message
            or str(outcome.get("message") or "").strip()
            or "This action could not run because a platform assistant safety switch is blocking shared actions."
        )
        if "assistant session" in reply.lower():
            reply = (
                "This dashboard action could not run because a platform assistant safety switch "
                "is blocking shared mutation tools. Ordinary HR workflows should not be affected — contact support."
            )
        try:
            dashboard_record_action_result(
                action_type,
                "failed",
                {
                    **(result or {}),
                    "action": {"type": action_type, "target_type": audit_target_type, "args": safe_args},
                    "source": "dashboard",
                    "company_code": company,
                    "status": "mutations_disabled",
                },
                reply,
            )
        except Exception:
            logger.warning("dashboard mutations_disabled audit failed for %s", action_type, exc_info=True)
        return {
            "ok": False,
            "status": "mutations_disabled",
            "message": reply,
            "confirmation": None,
            "result": json_safe(result),
        }

    # Terminal execution (completed / partial / failed) — audit it.
    final_status = "completed" if status == "completed" else ("partial" if status == "partial" else "failed")
    reply = safe_message or ("Done." if final_status == "completed" else "I could not complete that action.")
    audit_payload = {
        **(result or {}),
        "action": {"type": action_type, "target_type": audit_target_type, "args": safe_args},
        "source": "dashboard",
        "company_code": company,
        "company_id": company,
        "actor_user_id": context.get("actor_user_id"),
        "actor_email": context.get("actor_email"),
        "actor_phone": digits(context.get("hr_phone")) or None,
        "actor_role": context.get("actor_role"),
        "requested_by": context.get("hr_user"),
    }
    try:
        dashboard_record_action_result(action_type, final_status, audit_payload, reply)
    except Exception:
        logger.warning("dashboard registry action audit failed for %s", action_type, exc_info=True)
    return {
        "ok": final_status == "completed",
        "status": final_status,
        "message": reply,
        "confirmation": None,
        "result": json_safe(result),
    }


def run_posthire_dashboard_action(context: dict[str, Any], action_type: str, args: dict[str, Any]) -> dict[str, Any]:
    """Execute a post-hire registry action on behalf of a dashboard user.

    Thin wrapper over the shared dashboard registry harness, scoped to the
    post-hire modules. Behaviour is identical to before the harness was
    generalized.
    """
    if str(action_type or "").strip() == "set_payroll_policy":
        # Phase 2A — company payroll setup owned by Setup Console.
        raise HTTPException(
            status_code=422,
            detail={
                "error": "company_payroll_setup_owned_by_setup_console",
                "message": (
                    "Company payroll policy is configured in Setup Console. "
                    "Payroll workspace keeps runs, reviews, and previews."
                ),
                "setup_console_href": "/setup-console#classic-payroll-setup",
            },
        )
    conversation_id = posthire_dashboard_conversation_id(context)
    scope = posthire_dashboard_scope(context, conversation_id)
    return run_dashboard_registry_action(
        context,
        action_type,
        args,
        allowed_modules=POSTHIRE_DASHBOARD_MODULES,
        conversation_id=conversation_id,
        scope=scope,
        audit_target_type="employee",
    )


# Pre-Hiring candidate actions span three modules; an action is only allowed via
# this surface if its registry spec belongs to one of these.
PREHIRE_DASHBOARD_REGISTRY_MODULES = ("pre_hiring", "assessments", "interviews", "video_interviews")


def run_prehire_registry_action(
    context: dict[str, Any],
    action_type: str,
    args: dict[str, Any],
    *,
    app_key: str,
) -> dict[str, Any]:
    """Execute a Pre-Hiring candidate action through the shared registry path
    (the SAME path the Wathefni Assistant uses), behind WATHEFNI_PREHIRE_VIA_REGISTRY.

    Phase 2b/2c decision: the dashboard button click IS the confirmation, so the
    one explicit `needs_confirmation` round-trip is auto-confirmed here by
    re-sending the identical request once (the pending action resolves by
    company + admin + conversation + module + action_hash). This preserves the
    current one-click Pre-Hiring UX — no extra modal.

    The response is intentionally built with dashboard_prehire_mutation_response
    so the shape (ok / action_type / status / reply / result / audit / refreshed
    `application`) and the audit row are IDENTICAL to the legacy direct path.
    Audited as an application/candidate action, never as an employee action.
    """
    import tool_call_orchestrator as _tco

    module = posthire_action_module(action_type)
    if not module or module not in PREHIRE_DASHBOARD_REGISTRY_MODULES:
        raise HTTPException(status_code=404, detail={"error": "unknown_action", "message": "That action is not available."})

    company = context["company_code"]
    safe_args = posthire_whitelisted_args(action_type, {**(args or {}), "app_key": app_key})
    conversation_id = posthire_dashboard_conversation_id(context)
    scope = posthire_dashboard_scope(context, conversation_id)

    def _invoke() -> dict[str, Any]:
        turn_request = WhatsAppTurnRequest(
            account_id=company,
            conversation_id=conversation_id,
            sender_phone=digits(context.get("hr_phone")) or "dashboard",
            sender_role="hr_admin",
            raw_text=f"[dashboard] {action_type}",
            metadata={
                "channel": "web_dashboard",
                "dashboard": True,
                DASHBOARD_TURN_AUTHORITY_KEY: _DASHBOARD_TURN_AUTHORITY_NONCE,
                "company_code": company,
                "permissions": scope["permissions"],
                "admin_user": context.get("hr_user"),
                "access": context.get("access"),
            },
        )
        token = set_active_company_code(company)
        try:
            return _tco._execute_tool(action_type, safe_args, turn_request, {}, {}, scope)
        finally:
            reset_active_company_code(token)

    outcome = _invoke()
    status = str(outcome.get("status") or "")
    # Auto-confirm: re-send once so the saved pending action resolves and runs.
    if status == "needs_confirmation":
        outcome = _invoke()
        status = str(outcome.get("status") or "")

    if status in {"permission_denied", "module_disabled"}:
        message = "You do not have access to do that." if status == "permission_denied" else "This module is not enabled for your company."
        raise HTTPException(status_code=403, detail={"error": status, "message": message})

    result = outcome.get("result") if isinstance(outcome.get("result"), dict) else {}
    safe_message = str(result.get("safe_user_message") or result.get("message") or "").strip()

    if status == "completed":
        final_status = "completed"
    elif status == "partial":
        final_status = "partial"
    else:
        # needs_confirmation (still, after retry), needs_clarification,
        # candidate_not_found/ambiguous, failed, error -> surface as a safe failure
        # rather than leaving the UI waiting on a modal it does not render here.
        final_status = "failed"
    reply = safe_message or ("Done." if final_status == "completed" else "I could not complete that action.")

    result_payload = {
        **(result or {}),
        "action": {"type": action_type, "target_type": "application", "target": app_key},
        "source": "dashboard",
        "via": "registry",
        "company_code": company,
        "company_id": company,
        "actor_user_id": context.get("actor_user_id"),
        "actor_email": context.get("actor_email"),
        "actor_phone": digits(context.get("hr_phone")) or None,
        "actor_role": context.get("actor_role"),
        "requested_by": context.get("hr_user"),
    }
    return dashboard_prehire_mutation_response(
        action_type=action_type,
        status=final_status,
        reply=reply,
        result_payload=result_payload,
        app_key=app_key,
        company_code=company,
        permissions=context.get("permissions") or [],
    )


@app.post("/dashboard/posthire/action")
def dashboard_posthire_action(payload: PosthireActionRequest, context: dict[str, Any] = Depends(dashboard_context)):
    action_type = str(payload.action_type or "").strip()
    if not action_type:
        raise HTTPException(status_code=400, detail={"error": "missing_action", "message": "No action was provided."})
    return run_posthire_dashboard_action(context, action_type, payload.args or {})


def _posthire_read_context(context: dict[str, Any], module: str) -> str:
    """Gate a post-hire read on the module being enabled + the user holding
    <module>.read, returning the company code. Raises HTTP 403 otherwise."""
    require_entitlement(context, module, f"{module}.read")
    return context["company_code"]


def _posthire_window(days_back: int, days_forward: int) -> tuple[str, str]:
    today = kuwait_today()
    return (today - timedelta(days=days_back)).isoformat(), (today + timedelta(days=days_forward)).isoformat()


def _posthire_month_window() -> tuple[str, str]:
    """Current month-to-date — the default operational window for the analytics
    and payroll dashboards (a single day showed almost nothing)."""
    today = kuwait_today()
    return today.replace(day=1).isoformat(), today.isoformat()


def latest_timesheet_period(company_code: str | None) -> tuple[date, date] | None:
    """The most recent pay period that has timesheets, so the payroll dashboard
    opens on the latest run rather than an arbitrary single day."""
    company = require_company_code(company_code)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT period_start, period_end FROM payroll_timesheets WHERE company_code=%s "
                "ORDER BY period_start DESC, period_end DESC LIMIT 1",
                (company,),
            )
            row = cur.fetchone()
            if row and row.get("period_start") and row.get("period_end"):
                return row["period_start"], row["period_end"]
    return None


def employee_profile_accessible_modules(context: dict[str, Any], company: str) -> list[str]:
    """Post-hire modules whose section should appear on the 360 profile: enabled
    for the company AND readable by this user. Keeps the profile entitlement-aware
    so it never surfaces a module the company/user isn't allowed to see."""
    if not dashboard_context_has_permission(context, "employees.read"):
        return []
    return [
        module
        for module in POSTHIRE_PEOPLE_MODULES
        if company_has_module(company, module) and dashboard_context_has_permission(context, f"{module}.read")
    ]


# --- Employee Document Hub (read-only view/download) ------------------------
# HR can view/download the documents employees submitted (via WhatsApp onboarding
# uploads). The unified index is `file_registry` (subject_type='employee'); we
# never expose raw storage URLs for local files — they are proxied byte-for-byte
# through a tenant + RBAC + manager-scope gated endpoint. Additive: ingestion is
# unchanged.

# Document file_kinds that belong to an employee and are safe to surface to HR.
_EMPLOYEE_DOCUMENT_FILE_KINDS = ("onboarding_document", "compliance_document", "employee_document")


def employee_documents_for(company_code: str, employee_key: str) -> list[dict[str, Any]]:
    """Metadata list (never bytes) of an employee's stored documents, newest first."""
    company = require_company_code(company_code)
    out: list[dict[str, Any]] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT file_id, document_type, file_kind, original_filename, mime_type,
                       size_bytes, storage_provider, storage_status, stored_at, updated_at,
                       metadata
                FROM file_registry
                WHERE company_code=%s AND subject_type='employee' AND subject_key=%s
                  AND file_kind = ANY(%s)
                ORDER BY updated_at DESC NULLS LAST
                """,
                (company, employee_key, list(_EMPLOYEE_DOCUMENT_FILE_KINDS)),
            )
            for r in cur.fetchall():
                row = dict(r)
                meta = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
                stored = row.get("stored_at") or row.get("updated_at")
                out.append({
                    "file_id": str(row.get("file_id")),
                    "document_type": row.get("document_type"),
                    "label": meta.get("label") or compliance_document_friendly_label(row.get("document_type"), None),
                    "item_id": meta.get("item_id"),
                    "filename": row.get("original_filename"),
                    "mime_type": row.get("mime_type"),
                    "size_bytes": int(row.get("size_bytes")) if row.get("size_bytes") is not None else None,
                    "stored_at": stored.isoformat() if hasattr(stored, "isoformat") else stored,
                    "has_file": str(row.get("storage_status") or "") in {"stored", "stored_with_fallback"},
                })
    return out


def employee_document_index(company_code: str, employee_key: str) -> dict[str, str]:
    """Map of {item_id|document_type} -> file_id for an employee's stored docs
    (latest wins). Lets the onboarding checklist and compliance rows attach a
    View/Download link by either key without an extra round-trip per row."""
    index: dict[str, str] = {}
    for doc in employee_documents_for(company_code, employee_key):
        if not doc.get("has_file"):
            continue
        for key in (doc.get("item_id"), doc.get("document_type")):
            k = str(key or "").strip()
            if k and k not in index:
                index[k] = doc["file_id"]
    return index


def resolve_employee_document_file(company_code: str, file_id: str) -> dict[str, Any] | None:
    """Tenant-scoped fetch of one employee document row by file_id. Returns None
    when it does not exist for this company (callers must 404, never disclose
    cross-tenant existence)."""
    company = require_company_code(company_code)
    try:
        uuid.UUID(str(file_id))
    except (ValueError, TypeError):
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT file_id, company_code, subject_key, document_type, file_kind,
                       original_filename, mime_type, storage_provider, storage_object_key,
                       storage_url, local_path, source_path, storage_status
                FROM file_registry
                WHERE file_id=%s AND company_code=%s AND subject_type='employee'
                  AND file_kind = ANY(%s)
                LIMIT 1
                """,
                (str(file_id), company, list(_EMPLOYEE_DOCUMENT_FILE_KINDS)),
            )
            row = cur.fetchone()
            return dict(row) if row else None


def employee_document_local_path(doc: dict[str, Any]) -> Path | None:
    """Resolve a stored employee document to an on-disk file, refusing any path
    that escapes the workspace root (path-traversal guard)."""
    workspace_root = Path(WORKSPACE).resolve()
    for key in ("local_path", "source_path"):
        raw = str(doc.get(key) or "").strip()
        if not raw:
            continue
        try:
            candidate = Path(raw).resolve()
        except (OSError, RuntimeError):
            continue
        if not candidate.is_relative_to(workspace_root):
            continue
        if candidate.exists() and candidate.is_file():
            return candidate
    return None


_NEXT_ACTION_SEVERITY_WEIGHT = {"critical": 0, "high": 1, "medium": 2, "low": 3}
# Within an equal-severity tier, surface the more serious-by-nature module first.
# Severity (not module) is always the primary sort, so this only breaks ties.
_NEXT_ACTION_MODULE_PRIORITY = {
    "compliance": 0, "onboarding": 1, "leave": 2, "payroll": 3, "attendance": 4, "shifts": 5,
}
_NEXT_ACTIONS_VISIBLE_CAP = 5
# Minimum 14-day count before an attendance pattern is worth flagging (anti-noise).
_ATTENDANCE_PATTERN_MIN = 3


def _next_action_expiry_phrase(days: Any) -> str | None:
    """HR-friendly 'why' for a document by days-until-expiry (negative = overdue)."""
    try:
        d = int(days)
    except (TypeError, ValueError):
        return None
    if d < 0:
        n = abs(d)
        return f"Expired {n} day{'s' if n != 1 else ''} ago"
    if d == 0:
        return "Expires today"
    return f"Expires in {d} day{'s' if d != 1 else ''}"


def _next_action_date_ordinal(value: Any) -> float:
    """Days-since-epoch for an ISO date so older items sort first within a tier.
    Unparseable/empty dates sort last (large sentinel)."""
    s = str(value or "")[:10]
    try:
        y, m, d = (int(x) for x in s.split("-"))
        return float(date(y, m, d).toordinal())
    except Exception:
        return 9_999_999.0


def build_employee_next_actions(
    card: dict[str, Any], sections: dict[str, Any]
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Derive a ranked "what should HR do next for this employee, and why?" list
    purely from the per-module reads already loaded for the profile — no extra
    queries, no new data model.

    Ordering is severity-first (critical → low); ties break by module priority
    then a per-signal urgency key. Executable rows reuse ONLY existing whitelisted
    actions, and only for safe one-click nudges (compliance reminder / mark
    reviewed, onboarding reminder). Two-sided decisions (leave & payroll
    approvals) and judgment calls (attendance patterns, observe-only leave
    balances) are navigation-only — they point at the module card where the
    existing approve/reject controls already live. No file ids, URLs, storage
    paths, or raw document bytes ever appear here.
    """
    name = card.get("name") or "This employee"
    phone = card.get("phone") or ""
    emp_key = card.get("employee_key") or ""
    items: list[dict[str, Any]] = []

    def add(
        *, id: str, severity: str, module: str, title: str, reason: str,
        target_section: str, executable: bool = False, action_type: str | None = None,
        args: dict[str, Any] | None = None, action_label: str | None = None,
        requires_confirmation: bool = False, destructive: bool = False,
        source_at: Any = None, urgency: float = 0.0, meta: dict[str, Any] | None = None,
    ) -> None:
        entry: dict[str, Any] = {
            "id": id,
            "severity": severity,
            "module": module,
            "title": title,
            "reason": reason,
            "executable": bool(executable),
            "target": {"page": target_section, "section": target_section},
            "_sort": (
                _NEXT_ACTION_SEVERITY_WEIGHT.get(severity, 9),
                _NEXT_ACTION_MODULE_PRIORITY.get(module, 9),
                float(urgency),
            ),
        }
        if source_at is not None:
            entry["source_at"] = source_at
        if meta:
            entry["meta"] = meta
        if executable and action_type:
            entry["action_type"] = action_type
            entry["args"] = args or {}
            entry["action_label"] = action_label or "Run"
            entry["requires_confirmation"] = bool(requires_confirmation)
            entry["destructive"] = bool(destructive)
        items.append(entry)

    # ---- Compliance: expired / missing / expiring soon / needs review ----
    comp = sections.get("compliance")
    if isinstance(comp, dict):
        for doc in comp.get("documents") or []:
            bucket = doc.get("status")
            dtype = doc.get("document_type")
            dlabel = doc.get("document_label") or dtype or "document"
            days = doc.get("days_until_expiry")
            reminder_args = {"employee_name": name, "document_type": dtype}
            meta = {"document_type": dtype, "days_until_expiry": days}
            day_urgency = float(days) if isinstance(days, (int, float)) else 0.0
            if bucket == "expired":
                add(id=f"compliance:expired:{dtype}", severity="critical", module="compliance",
                    title=f"{dlabel} expired", reason=_next_action_expiry_phrase(days) or "Document has expired",
                    target_section="compliance", executable=True, action_type="compliance_send_reminder",
                    args=reminder_args, action_label="Send reminder", requires_confirmation=True,
                    source_at=doc.get("expiry_date"), urgency=day_urgency, meta=meta)
            elif bucket == "missing":
                add(id=f"compliance:missing:{dtype}", severity="high", module="compliance",
                    title=f"{dlabel} missing", reason="Required document not on file",
                    target_section="compliance", executable=True, action_type="compliance_send_reminder",
                    args=reminder_args, action_label="Send reminder", requires_confirmation=True,
                    urgency=-1.0, meta=meta)
            elif bucket == "expiring_soon":
                soon = isinstance(days, (int, float)) and int(days) <= 7
                add(id=f"compliance:expiring:{dtype}", severity="high" if soon else "medium", module="compliance",
                    title=f"{dlabel} expiring soon", reason=_next_action_expiry_phrase(days) or "Document is expiring soon",
                    target_section="compliance", executable=True, action_type="compliance_send_reminder",
                    args=reminder_args, action_label="Send reminder", requires_confirmation=True,
                    source_at=doc.get("expiry_date"), urgency=day_urgency, meta=meta)
            elif bucket == "needs_review":
                add(id=f"compliance:review:{dtype}", severity="high", module="compliance",
                    title=f"{dlabel} needs review", reason="Submitted document is waiting for HR review",
                    target_section="compliance", executable=True, action_type="compliance_mark_reviewed",
                    args=reminder_args, action_label="Mark reviewed", requires_confirmation=False,
                    urgency=0.0, meta=meta)

    # ---- Onboarding: incomplete (aggregate; safe one-click reminder) ----
    onb = sections.get("onboarding")
    if isinstance(onb, dict):
        outstanding = onb.get("outstanding") or []
        n = int(onb.get("outstanding_count") or 0)
        if n > 0:
            labels = [str(it.get("label")) for it in outstanding if it.get("label")][:3]
            preview = ", ".join(labels)
            reason = f"{n} required item{'s' if n != 1 else ''} still open"
            if preview:
                reason += f": {preview}"
            add(id="onboarding:incomplete", severity="medium", module="onboarding",
                title="Onboarding incomplete", reason=reason, target_section="onboarding",
                executable=True, action_type="send_onboarding_reminder",
                args={"employee_key": emp_key, "employee_name": name, "employee_phone": phone},
                action_label="Send reminder", requires_confirmation=True,
                urgency=float(-n), meta={"outstanding_count": n})

    # ---- Leave: pending decision (navigation) + observe-only negative balance ----
    lv = sections.get("leave")
    if isinstance(lv, dict):
        for r in lv.get("items") or []:
            if r.get("status") != "requested":
                continue
            sd, ed = r.get("start_date"), r.get("end_date")
            ltype = str(r.get("leave_type") or "leave").replace("_", " ").title()
            add(id=f"leave:pending:{sd}:{ed}", severity="high", module="leave",
                title="Leave request awaiting your decision", reason=f"{ltype} · {sd} → {ed}",
                target_section="leave", source_at=sd, urgency=_next_action_date_ordinal(sd),
                meta={"start_date": sd, "end_date": ed})
        for b in lv.get("balances") or []:
            try:
                bal = float(b.get("current_balance"))
            except (TypeError, ValueError):
                continue
            if bal < 0:
                bt = str(b.get("leave_type") or "leave").replace("_", " ")
                add(id=f"leave:balance:{b.get('leave_type')}", severity="low", module="leave",
                    title=f"Negative {bt} balance", reason=f"Balance is {bal:g} days — observe-only, not enforced",
                    target_section="leave", urgency=bal,
                    meta={"leave_type": b.get("leave_type"), "current_balance": bal})

    # ---- Payroll: timesheet in review/draft (navigation; two-sided decision) ----
    pay = sections.get("payroll")
    if isinstance(pay, dict):
        for ts in pay.get("items") or []:
            if str(ts.get("status") or "").lower() not in {"draft", "review", "in_review"}:
                continue
            ps, pe = ts.get("period_start"), ts.get("period_end")
            add(id=f"payroll:review:{ts.get('timesheet_id')}", severity="high", module="payroll",
                title="Timesheet awaiting approval", reason=f"Pay period {ps} → {pe}",
                target_section="payroll", source_at=ps, urgency=_next_action_date_ordinal(ps),
                meta={"timesheet_id": ts.get("timesheet_id"), "period_start": ps})

    # ---- Attendance: 14-day pattern (navigation; HR judgment) ----
    att = sections.get("attendance")
    if isinstance(att, dict):
        absent = int(att.get("absent") or 0)
        late = int(att.get("late") or 0)
        window = int(att.get("window_days") or 14)
        if absent >= _ATTENDANCE_PATTERN_MIN:
            add(id="attendance:absences", severity="medium", module="attendance",
                title="Repeated absences", reason=f"{absent} absences in the last {window} days",
                target_section="attendance", urgency=float(-absent), meta={"absent": absent, "window_days": window})
        if late >= _ATTENDANCE_PATTERN_MIN:
            add(id="attendance:lateness", severity="medium", module="attendance",
                title="Repeated lateness", reason=f"{late} late arrivals in the last {window} days",
                target_section="attendance", urgency=float(-late), meta={"late": late, "window_days": window})

    items.sort(key=lambda a: a["_sort"])
    by_severity = {"critical": 0, "high": 0, "medium": 0, "low": 0}
    for a in items:
        by_severity[a["severity"]] = by_severity.get(a["severity"], 0) + 1
        a.pop("_sort", None)
    summary = {
        "total": len(items),
        "by_severity": by_severity,
        "visible_cap": _NEXT_ACTIONS_VISIBLE_CAP,
    }
    return items, summary


def dashboard_employee_profile(context: dict[str, Any], employee_key: str) -> dict[str, Any]:
    """Unified, read-only employee profile (Employee 360).

    The employee is the post-hire hub; this composes the existing per-module reads
    around one person so HR sees everything at a glance and, crucially, what to do
    next. Tenant-scoped: the employee must belong to the session's company, and
    each section only appears if the company has that module and the user can read
    it. No mutations — purely an aggregated read.
    """
    company = context["company_code"]
    key = str(employee_key or "").strip()
    if not key:
        raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM employees WHERE company_code=%s AND employee_key=%s LIMIT 1",
                (company, key),
            )
            row = cur.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})
    employee = dict(row)
    # Manager scoping: a scoped manager may only open a profile for an employee in
    # their branch/team/direct scope. Inert for unscoped users (owners/HR).
    viewer_phone = context.get("hr_phone")
    if not context_manager_allows_employee(context, employee, company_code=company):
        raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})
    card = posthire_employee_card(employee)
    modules = employee_profile_accessible_modules(context, company)
    sections: dict[str, Any] = {}
    next_actions: list[dict[str, Any]] = []

    with db_connect() as conn:
        with conn.cursor() as cur:
            if "onboarding" in modules:
                items = load_onboarding_items(employee_key=key, company_code=company, cur=cur)
                counts = onboarding_item_counts_from_rows(items)
                import onboarding_completion_contract as _completion

                closed_states = set(_completion.CLOSED_STATUSES)
                outstanding = [
                    {
                        "item_id": it.get("item_id"),
                        "label": item_display_label(it),
                        "status": it.get("status"),
                        "row_version": it.get("row_version"),
                        "owner_group": onboarding_owner_group(it),
                        "required": True,
                    }
                    for it in items
                    if it.get("required")
                    and str(it.get("status") or "").lower() not in closed_states
                ]
                sections["onboarding"] = {
                    "status": card["onboarding_status"],
                    "outstanding_count": len(outstanding),
                    "complete_count": counts["received_count"],
                    "item_count": len(items),
                    "required_total": counts["required_total"],
                    "received_count": counts["received_count"],
                    "pending_count": counts["pending_count"],
                    "outstanding": outstanding[:8],
                    "bank_collection": "ess_encrypted",
                }
                if outstanding:
                    next_actions.append({
                        "module": "onboarding",
                        "label": f"{len(outstanding)} onboarding document{'s' if len(outstanding) != 1 else ''} still needed",
                        "page": "onboarding",
                    })

            if "compliance" in modules:
                docs = compliance_outstanding_docs(key)
                counts = {bucket: 0 for bucket in COMPLIANCE_BUCKETS}
                outstanding_docs: list[dict[str, Any]] = []
                for doc in docs:
                    bucket = doc.get("_bucket") or "valid"
                    counts[bucket] = counts.get(bucket, 0) + 1
                    if bucket in COMPLIANCE_OUTSTANDING_BUCKETS:
                        expiry = doc.get("expiry_date")
                        outstanding_docs.append({
                            "document_type": doc.get("document_type"),
                            "document_label": doc.get("_label"),
                            "status": bucket,
                            "status_label": COMPLIANCE_STATUS_LABELS.get(bucket, bucket),
                            "tone": COMPLIANCE_STATUS_TONE.get(bucket, "warning"),
                            "expiry_date": expiry.isoformat() if hasattr(expiry, "isoformat") else (str(expiry) if expiry else None),
                            # "Why" context so HR can act without leaving the page:
                            # how urgent (days) and whether we already nudged.
                            "days_until_expiry": doc.get("_days_until_expiry"),
                            "last_reminded_at": doc.get("last_alerted_at") or doc.get("last_reminded"),
                            "reminder_count": int(doc.get("reminder_count") or 0),
                        })
                needs_attention = sum(counts.get(b, 0) for b in COMPLIANCE_OUTSTANDING_BUCKETS)
                sections["compliance"] = {
                    **counts,
                    "needs_attention": needs_attention,
                    "total_documents": len(docs),
                    "documents": outstanding_docs[:8],
                }
                if needs_attention:
                    next_actions.append({
                        "module": "compliance",
                        "label": f"{needs_attention} document{'s' if needs_attention != 1 else ''} need attention",
                        "page": "compliance",
                    })

            if "attendance" in modules:
                cur.execute(
                    """
                    SELECT attendance_date, status, late_minutes, early_leave_minutes, check_in_at
                    FROM attendance_records
                    WHERE company_code=%s AND employee_key=%s
                    ORDER BY attendance_date DESC, created_at DESC
                    LIMIT 10
                    """,
                    (company, key),
                )
                recent = [dict(r) for r in cur.fetchall()]
                cur.execute(
                    """
                    SELECT
                      COUNT(*) FILTER (WHERE lower(status) IN ('present','completed')) AS present,
                      COUNT(*) FILTER (WHERE lower(status)='late' OR late_minutes > 0) AS late,
                      COUNT(*) FILTER (WHERE lower(status)='absent') AS absent
                    FROM attendance_records
                    WHERE company_code=%s AND employee_key=%s
                      AND attendance_date >= CURRENT_DATE - INTERVAL '14 days'
                    """,
                    (company, key),
                )
                summary = cur.fetchone() or {}
                sections["attendance"] = {
                    "window_days": 14,
                    "present": int(summary.get("present") or 0),
                    "late": int(summary.get("late") or 0),
                    "absent": int(summary.get("absent") or 0),
                    "recent": [
                        {
                            "date": (r.get("attendance_date").isoformat() if hasattr(r.get("attendance_date"), "isoformat") else r.get("attendance_date")),
                            "status": r.get("status"),
                            "late_minutes": int(r.get("late_minutes") or 0),
                        }
                        for r in recent
                    ],
                }

            if "leave" in modules:
                cur.execute(
                    """
                    SELECT leave_type, start_date, end_date, status
                    FROM leave_requests
                    WHERE company_code=%s AND employee_key=%s
                      AND (status='requested' OR (status='approved' AND end_date >= CURRENT_DATE))
                    ORDER BY (status='requested') DESC, start_date ASC
                    LIMIT 10
                    """,
                    (company, key),
                )
                leave_rows = [dict(r) for r in cur.fetchall()]
                # The row list above is a capped (LIMIT 10) preview for display.
                # The pending count must be a TRUE aggregate — deriving it from the
                # capped preview undercounts an employee with >10 pending requests
                # and makes the "awaiting a decision" badge lie at scale.
                cur.execute(
                    """
                    SELECT COUNT(*) AS pending_count
                    FROM leave_requests
                    WHERE company_code=%s AND employee_key=%s AND status='requested'
                    """,
                    (company, key),
                )
                pending_count = int((cur.fetchone() or {}).get("pending_count") or 0)
                sections["leave"] = {
                    "pending_count": pending_count,
                    "items": [
                        {
                            "leave_type": r.get("leave_type"),
                            "start_date": (r.get("start_date").isoformat() if hasattr(r.get("start_date"), "isoformat") else r.get("start_date")),
                            "end_date": (r.get("end_date").isoformat() if hasattr(r.get("end_date"), "isoformat") else r.get("end_date")),
                            "status": r.get("status"),
                        }
                        for r in leave_rows
                    ],
                }
                # Read-only leave balances (dark-launched, observe-only, preset
                # figures pending legal review — not enforced).
                if leave_balances_enabled():
                    sections["leave"]["balances_enabled"] = True
                    sections["leave"]["balances_enforced"] = False
                    sections["leave"]["legal_reviewed"] = False
                    sections["leave"]["balances_binding"] = False
                    sections["leave"]["observe_only"] = True
                    sections["leave"]["balances"] = leave_balances_for_employee(company, key)
                if pending_count:
                    next_actions.append({
                        "module": "leave",
                        "label": f"{pending_count} leave request{'s' if pending_count != 1 else ''} awaiting a decision",
                        "page": "leave",
                    })

            if "shifts" in modules:
                cur.execute(
                    """
                    SELECT shift_date, start_time, end_time, role, location, status
                    FROM shift_assignments
                    WHERE company_code=%s AND employee_key=%s AND shift_date >= CURRENT_DATE
                    ORDER BY shift_date ASC, start_time ASC
                    LIMIT 10
                    """,
                    (company, key),
                )
                shift_rows = [dict(r) for r in cur.fetchall()]
                # The rows above are a capped (LIMIT 10) preview. The count must be
                # a TRUE aggregate so an employee with >10 upcoming shifts isn't
                # shown as having only 10.
                cur.execute(
                    """
                    SELECT COUNT(*) AS upcoming_count
                    FROM shift_assignments
                    WHERE company_code=%s AND employee_key=%s AND shift_date >= CURRENT_DATE
                    """,
                    (company, key),
                )
                upcoming_count = int((cur.fetchone() or {}).get("upcoming_count") or 0)
                sections["shifts"] = {
                    "upcoming_count": upcoming_count,
                    "items": [
                        {
                            "date": (r.get("shift_date").isoformat() if hasattr(r.get("shift_date"), "isoformat") else r.get("shift_date")),
                            "start_time": str(r.get("start_time") or ""),
                            "end_time": str(r.get("end_time") or ""),
                            "role": r.get("role") or "",
                            "location": r.get("location") or "",
                            "status": r.get("status"),
                        }
                        for r in shift_rows
                    ],
                }

            if "payroll" in modules:
                cur.execute(
                    """
                    SELECT timesheet_id, period_start, period_end, status, worked_minutes, scheduled_minutes, overtime_minutes
                    FROM payroll_timesheets
                    WHERE company_code=%s AND employee_key=%s
                    ORDER BY period_start DESC
                    LIMIT 3
                    """,
                    (company, key),
                )
                ts_rows = [dict(r) for r in cur.fetchall()]
                sections["payroll"] = {
                    "items": [
                        {
                            "timesheet_id": str(r.get("timesheet_id") or "") or None,
                            "period_start": (r.get("period_start").isoformat() if hasattr(r.get("period_start"), "isoformat") else r.get("period_start")),
                            "period_end": (r.get("period_end").isoformat() if hasattr(r.get("period_end"), "isoformat") else r.get("period_end")),
                            "status": r.get("status"),
                            "worked_hours": round(float(r.get("worked_minutes") or 0) / 60.0, 1),
                            "overtime_hours": round(float(r.get("overtime_minutes") or 0) / 60.0, 1),
                        }
                        for r in ts_rows
                    ],
                }

    # Documents tab (read-only): submitted files HR can view/download. Visible
    # when the user can read onboarding or compliance for the company.
    if "onboarding" in modules or "compliance" in modules:
        documents = employee_documents_for(company, key)
        sections["documents"] = {"count": len(documents), "items": documents}

    # Ranked Next Actions engine (dark-launched). When ON, replace the legacy
    # flat list with the severity-ranked, actionable list derived from the same
    # sections above; when OFF, the profile keeps the legacy flat list so the
    # page stays fully backward-compatible.
    next_actions_enabled = employee_next_actions_enabled()
    next_actions_summary: dict[str, Any] | None = None
    if next_actions_enabled:
        next_actions, next_actions_summary = build_employee_next_actions(card, sections)

    return json_safe({
        "company_code": company,
        "employee": {
            **card,
            "hired_at": employee.get("created_at"),
            "documents_pending": employee.get("documents_pending"),
            "documents_complete": employee.get("documents_complete"),
        },
        "available_modules": modules,
        "sections": sections,
        "next_actions": next_actions,
        "next_actions_summary": next_actions_summary,
        "next_actions_enabled": next_actions_enabled,
        "doc_upload_enabled": doc_upload_enabled(),
        # Same gate the Onboarding page uses for mark-received/waive controls.
        "hr_mutate_enabled": onboarding_hr_mutate_enabled_for_company(
            str(employee.get("company_code") or context.get("company_code") or "")
        ),
    })


