@app.post("/dashboard/posthire/employees/import-mapping/suggest")
async def dashboard_posthire_import_mapping_suggest(
    file: UploadFile = File(...),
    source_system: str | None = Form(None),
    context: dict[str, Any] = Depends(dashboard_context),
):
    """Suggest or reuse mapping profile for uploaded file headers (P2 field model)."""
    company = require_employee_roster_admin(context)
    import employee_migration_foundation as _emf
    import employee_migration_field_model as _fm

    _emf.require_foundation(sys.modules[__name__], company)
    raw = await file.read()
    rows, parse_error = _emf.parse_employee_import_workbook(raw, file.filename or "import.csv")
    if parse_error:
        raise HTTPException(status_code=422, detail={"error": "unreadable_file", "message": parse_error})
    headers: list[str] = []
    if rows:
        headers = list((rows[0].get("source_payload") or {}).get("headers") or [])
    return json_safe(
        _fm.suggest_mapping_profile(
            sys.modules[__name__],
            context,
            headers=headers,
            source_system=source_system,
        )
    )


