def build_employee_app_feature_contract(
    effective_modules: set[str] | list[str] | tuple[str, ...],
    *,
    push_available: bool,
) -> dict[str, Any]:
    """Pure canonical employee feature projection.

    Company modules are an input to authority, never a client-side translation.
    The result includes every stable feature key so removals are deterministic.
    Bank ESS eligibility is employee-keyed and applied later by
    `apply_bank_ess_feature_contract`.
    """
    modules = {normalize_module_key(str(key)) for key in effective_modules}
    features: dict[str, dict[str, Any]] = {}
    for key, definition in _EMPLOYEE_APP_FEATURE_DEFINITIONS.items():
        dependency_mode = str(definition.get("dependency_mode") or "all")
        module_keys = tuple(str(item) for item in definition.get("module_keys") or ())
        if dependency_mode == "bank_ess":
            # Placeholder until apply_bank_ess_feature_contract runs with the employee key.
            entitled = False
            implemented = bool(definition.get("implemented", True))
            enabled = False
            reason = "bank_ess_pending_eligibility"
            actions: list[str] = []
        elif dependency_mode == "core":
            entitled = True
            implemented = bool(definition.get("implemented", True))
            enabled = entitled and implemented
            reason = None if enabled else ("feature_not_available" if not implemented else "module_disabled")
            actions = list(definition.get("actions") or ()) if enabled else []
        elif dependency_mode == "any":
            entitled = any(item in modules for item in module_keys)
            implemented = bool(definition.get("implemented", True))
            enabled = entitled and implemented
            reason = None
            if not entitled:
                reason = "module_disabled"
            elif not implemented:
                reason = "feature_not_available"
            actions = list(definition.get("actions") or ()) if enabled else []
        else:
            entitled = all(item in modules for item in module_keys)
            implemented = bool(definition.get("implemented", True))
            enabled = entitled and implemented
            reason = None
            if not entitled:
                reason = "module_disabled"
            elif not implemented:
                reason = "feature_not_available"
            actions = list(definition.get("actions") or ()) if enabled else []
        if key == "settings" and enabled and push_available:
            actions = list(actions)
            if "manage_push" not in actions:
                actions.append("manage_push")
        features[key] = {
            "enabled": enabled,
            "reason": reason,
            "dependency_mode": dependency_mode,
            "module_keys": list(module_keys),
            "actions": actions,
        }
    return {
        "version": _EMPLOYEE_APP_FEATURE_CONTRACT_VERSION,
        "enabled_features": [key for key, value in features.items() if value["enabled"]],
        "features": features,
    }


def apply_bank_ess_feature_contract(
    contract: dict[str, Any],
    *,
    company_code: str,
    employee_key: str,
) -> dict[str, Any]:
    """Stamp the canonical Bank ESS eligibility onto the feature contract."""
    import employee_bank_ess as _bank
    import employee_selfservice_wave5 as _w5

    eligibility = _bank.bank_ess_eligibility(
        company_code,
        employee_key,
        ess_v5_enabled=_w5.ess_v5_enabled(company_code),
    )
    definition = _EMPLOYEE_APP_FEATURE_DEFINITIONS.get("bank") or {}
    eligible = bool(eligibility.get("eligible"))
    reason = None if eligible else str(eligibility.get("reason") or "bank_ess_disabled")
    actions = list(definition.get("actions") or ()) if eligible else []
    features = dict(contract.get("features") or {})
    features["bank"] = {
        "enabled": eligible,
        "reason": reason,
        "dependency_mode": "bank_ess",
        "module_keys": [],
        "actions": actions,
        "eligibility": {
            "eligible": eligible,
            "reason": reason,
            "contract_version": eligibility.get("contract_version"),
        },
    }
    out = dict(contract)
    out["features"] = features
    out["enabled_features"] = [key for key, value in features.items() if value.get("enabled")]
    out["bank_ess"] = features["bank"]["eligibility"]
    return out


def employee_app_feature_contract_for_context(context: dict[str, Any]) -> dict[str, Any]:
    contract = build_employee_app_feature_contract(
        employee_app_effective_modules(context),
        push_available=push_notifications_enabled(),
    )
    contract = apply_bank_ess_feature_contract(
        contract,
        company_code=str(context.get("company_code") or ""),
        employee_key=str(context.get("employee_key") or ""),
    )
    # P5 — pending_start: only core + preboarding; never unlock post-hire ESS modules.
    employee = context.get("employee") if isinstance(context.get("employee"), dict) else {}
    if _employee_app_is_pending_start(employee) or context.get("access_mode") == "preboarding_only":
        allowed = {"home", "profile", "inbox", "settings", "preboarding"}
        features = contract.get("features") or {}
        for key, feature in list(features.items()):
            if key in allowed:
                continue
            features[key] = {
                **dict(feature or {}),
                "enabled": False,
                "actions": [],
                "reason": "preboarding_only_pending_start",
            }
        contract["features"] = features
        contract["access_mode"] = "preboarding_only"
    return contract


def employee_app_leave_types(company_code: str) -> list[str]:
    """Company-owned leave types with a compatibility fallback for unseeded V1 tenants."""
    company = str(company_code or "").strip().upper()
    values: list[str] = []
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT DISTINCT leave_type FROM leave_policies WHERE company_code=%s ORDER BY leave_type",
                    (company,),
                )
                values = [
                    _leave_authority.canonicalize_leave_type(row.get("leave_type") or "")
                    for row in cur.fetchall()
                    if normalize_text(row.get("leave_type") or "")
                ]
    except Exception:
        logger.warning("employee app leave type lookup failed company=%s", company, exc_info=True)
    # Prefer catalogue actives that are ledger-relevant for employee request UX
    out = []
    for t in values or list(_leave_authority.LEAVE_LEDGER_TYPES):
        if t not in out and t in _leave_authority.CANONICAL_LEAVE_TYPES and t != "other":
            out.append(t)
    return out or ["annual", "sick"]


def employee_app_effective_modules(context: dict[str, Any]) -> set[str]:
    company = str(context.get("company_code") or "").strip().upper()
    # Do not expose HR-only/candidate modules to the employee client.
    return {
        key
        for key in effective_company_modules(company)
        if key in MODULE_BY_KEY and MODULE_BY_KEY[key].audience == "employee"
    }


def employee_app_capability_payload(context: dict[str, Any]) -> dict[str, Any]:
    company = str(context.get("company_code") or "").strip().upper()
    employee_modules = employee_app_effective_modules(context)
    contract = employee_app_feature_contract_for_context(context)
    leave_enabled = bool((contract["features"].get("leave") or {}).get("enabled"))
    return {
        "account_state": "active",
        "app_state": "available",
        "effective_modules": sorted(employee_modules),
        # Compatibility alias. It now means effective employee-facing modules,
        # never raw configured modules.
        "enabled_modules": sorted(employee_modules),
        **contract,
        "leave": {
            "balances_enabled": leave_balances_enabled() and leave_enabled,
            "balances_enforced": False,
            "legal_reviewed": False,
            "balances_binding": False,
            "observe_only": True,
            "types": employee_app_leave_types(company) if leave_enabled else [],
        },
    }


def require_employee_app_feature(
    context: dict[str, Any],
    feature_key: str,
    *,
    action: str | None = None,
) -> dict[str, Any]:
    key = str(feature_key or "").strip()
    contract = employee_app_feature_contract_for_context(context)
    feature = (contract.get("features") or {}).get(key)
    allowed = bool(feature and feature.get("enabled"))
    if action:
        allowed = allowed and action in set(feature.get("actions") or ())
    if not allowed:
        reason = str((feature or {}).get("reason") or "feature_disabled")
        raise HTTPException(
            status_code=403,
            detail={
                "error": "employee_feature_disabled",
                "message": "This feature is not available for your account.",
                "feature": key,
                "reason": reason,
            },
        )
    return dict(feature)


def _employee_app_company_gate(
    cur: Any,
    company_code: str,
    *,
    lock_company: bool = True,
) -> tuple[bool, str | None]:
    """Current lifecycle + module gate, serialized with Setup Console changes."""
    company = str(company_code or "").strip().upper()
    lock_sql = " FOR SHARE" if lock_company else ""
    cur.execute(
        f"SELECT status FROM companies WHERE company_code=%s{lock_sql}",
        (company,),
    )
    row = cur.fetchone()
    status = str((row or {}).get("status") or "").strip().lower()
    if status != "active":
        return False, f"company_{status or 'unavailable'}"
    cur.execute(
        """
        SELECT 1 FROM company_modules
        WHERE company_code=%s AND module_key='employee_app' AND enabled IS TRUE
        LIMIT 1
        """,
        (company,),
    )
    if not cur.fetchone():
        return False, "employee_app_not_enabled_for_company"
    return True, None


