def _normalize_employee_device_platform(raw: str | None) -> str:
    value = str(raw or "").strip().lower()
    if value in {"ios", "iphone", "ipad"}:
        return "ios"
    if value in {"android"}:
        return "android"
    return "unknown"


def _employee_session_platform(metadata: Any) -> str:
    if isinstance(metadata, dict):
        return _normalize_employee_device_platform(metadata.get("platform"))
    return "unknown"


def _employee_device_security_public(*, platform: str, activated_at: Any, last_active_at: Any, status: str = "active") -> dict[str, Any]:
    """Calm current-device summary — never expose session ids, tokens, or revoke reasons."""
    return {
        "platform": _normalize_employee_device_platform(platform),
        "activated_at": activated_at,
        "last_active_at": last_active_at,
        "status": status,
    }


