def _app_code_generate() -> str:
    return "".join(secrets.choice("0123456789") for _ in range(_EMPLOYEE_APP_CODE_DIGITS))


def _app_code_hash(company_code: str | None, phone: str | None, code: str) -> str:
    # Code is digit-normalized so spaced OTP entry ("1 2 3 4 5 6") verifies the same
    # as compact form. Phone must match the invite/employee stored digits form.
    basis = f"{(company_code or '').upper()}:{digits(phone)}:{digits(code) or str(code or '').strip()}"
    return hashlib.sha256(basis.encode("utf-8")).hexdigest()


def _app_token_hash(token: str | None) -> str:
    return dashboard_token_hash(token)


def employee_app_public(employee: dict[str, Any], company_code: str) -> dict[str, Any]:
    """Lean, employee-self profile payload (no HR-only fields).

    `/app/me` stays on this compact contract. Richer Profile presentation uses
    `employee_app_profile_projection` via `/app/profile` — do not grow this shape
    into a second employee store.
    """
    card = posthire_employee_card(employee)
    profile = employee.get("profile") if isinstance(employee.get("profile"), dict) else {}
    locale = str(profile.get("locale") or profile.get("language") or "en").strip().lower() or "en"
    return {
        "employee_key": str(employee.get("employee_key") or ""),
        "company_code": company_code,
        "name": employee.get("name") or "",
        "phone": digits(employee.get("phone")) or "",
        "email": employee.get("email") or card.get("email") or "",
        "position_title": card.get("position_title") or employee.get("position_title") or "",
        "department": card.get("department") or "",
        "onboarding_status": card.get("onboarding_status") or "not_started",
        "locale": locale if locale in {"en", "ar"} else "en",
    }


def _employee_stored_manager_phone(employee: dict[str, Any]) -> str:
    """Manager phone only when already stored on the employee record — never invented."""
    profile = employee.get("profile") if isinstance(employee.get("profile"), dict) else {}
    raw = employee.get("raw_json") if isinstance(employee.get("raw_json"), dict) else {}
    for source in (employee, profile, raw):
        phone = digits(source.get("manager_phone") or source.get("reports_to") or source.get("manager"))
        if phone:
            return phone
    return ""


def _resolve_employee_manager_display(company_code: str, manager_phone: str) -> dict[str, Any] | None:
    """Resolve a stored manager phone to a display name in the same company, or None."""
    phone = digits(manager_phone)
    if not phone:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT name, phone, employee_key
                FROM employees
                WHERE company_code=%s AND regexp_replace(coalesce(phone,''), '\\D', '', 'g')=%s
                LIMIT 1
                """,
                ((company_code or "").upper(), phone),
            )
            row = cur.fetchone()
    if not row:
        # Phone is stored but the manager is not in this company's roster — show phone only.
        return {"name": "", "phone": phone, "employee_key": None}
    data = dict(row)
    return {
        "name": str(data.get("name") or ""),
        "phone": digits(data.get("phone")) or phone,
        "employee_key": str(data.get("employee_key") or "") or None,
    }


def employee_app_profile_projection(employee: dict[str, Any], company_code: str) -> dict[str, Any]:
    """Richer Profile read over the same employee row `/app/me` already uses.

    Personal / Employment sections are projections of canonical fields. Manager is
    included only when a manager phone is already stored on the employee; the name
    is resolved from the company roster when present, otherwise omitted values stay
    empty rather than guessed.
    """
    public = employee_app_public(employee, company_code)
    card = posthire_employee_card(employee)
    start = card.get("start_date") or employee.get("start_date") or employee.get("hire_date")
    if hasattr(start, "isoformat"):
        start = start.isoformat()
    start_s = str(start or "").strip()[:10] or None
    manager_phone = _employee_stored_manager_phone(employee)
    manager = _resolve_employee_manager_display(company_code, manager_phone) if manager_phone else None
    return {
        "employee": public,
        "personal": {
            "name": public.get("name") or "",
            "phone": public.get("phone") or "",
            "email": public.get("email") or "",
        },
        "employment": {
            "position_title": public.get("position_title") or "",
            "department": public.get("department") or "",
            "employee_key": public.get("employee_key") or "",
            "company_code": public.get("company_code") or "",
            "start_date": start_s,
            "employment_status": card.get("employment_status") or "active",
            "manager": manager,
        },
    }


def create_employee_app_invite(company_code: str, employee: dict[str, Any], *, created_by_phone: str | None = None, created_by_user_id: str | None = None) -> tuple[dict[str, Any], str]:
    """Create a single-use activation invite, superseding any prior pending one for
    this employee. Returns (invite_row, raw_code). Only the hash is persisted."""
    company = require_company_code(company_code)
    phone = digits(employee.get("phone"))
    employee_key = str(employee.get("employee_key") or "").strip()
    if not phone or not employee_key:
        raise EmployeeAppInviteDenied("employee_identity_invalid")
    code = _app_code_generate()
    expires = now_utc() + timedelta(hours=_EMPLOYEE_APP_INVITE_TTL_HOURS)
    with db_connect() as conn:
        with conn.cursor() as cur:
            allowed, reason = _employee_app_company_gate(cur, company)
            if not allowed:
                raise EmployeeAppInviteDenied(reason or "company_not_eligible")
            cur.execute(
                """
                SELECT * FROM employees
                WHERE company_code=%s AND employee_key=%s
                LIMIT 1 FOR SHARE
                """,
                (company, employee_key),
            )
            canonical_employee = dict(cur.fetchone() or {})
            if (
                not _employee_app_employee_eligible(canonical_employee)
                or digits(canonical_employee.get("phone")) != phone
            ):
                raise EmployeeAppInviteDenied("employee_not_eligible")
            # Employee App access eligibility (company ON + employee enabled / mode all).
            try:
                import employee_app_access as _access

                _access.ensure_access_schema(cur)
                cur.execute(
                    "SELECT app_access_enabled FROM employees WHERE company_code=%s AND employee_key=%s LIMIT 1",
                    (company, employee_key),
                )
                flag_row = cur.fetchone()
                if flag_row:
                    canonical_employee["app_access_enabled"] = bool(dict(flag_row).get("app_access_enabled"))
                eligible, reason = _access.is_employee_app_access_eligible(
                    sys.modules[__name__], company_code=company, employee=canonical_employee
                )
                if not eligible:
                    raise EmployeeAppInviteDenied(reason or "employee_app_access_not_enabled")
            except EmployeeAppInviteDenied:
                raise
            except Exception:
                logger.exception("app access gate failed for invite")
                raise EmployeeAppInviteDenied("employee_app_access_not_enabled")
            cur.execute(
                "UPDATE employee_app_invites SET status='superseded', idempotency_key=NULL, updated_at=now() WHERE company_code=%s AND employee_key=%s AND status='pending'",
                (company, employee_key),
            )
            cur.execute(
                """
                INSERT INTO employee_app_invites
                  (company_code, employee_key, phone, code_hash, status, created_by_phone, created_by_user_id, expires_at, last_sent_at)
                VALUES (%s,%s,%s,%s,'pending',%s,%s,%s, now())
                RETURNING *
                """,
                (company, employee_key, phone, _app_code_hash(company, phone, code), digits(created_by_phone) or None, str(created_by_user_id) if created_by_user_id else None, expires),
            )
            invite = dict(cur.fetchone())
        conn.commit()
    return invite, code


def deliver_app_activation_code(
    company_code: str,
    employee: dict[str, Any],
    code: str,
    *,
    invite_id: str | None = None,
) -> dict[str, Any]:
    """Deliver the activation code via the shared outbound ladder. metadata_only
    sensitivity keeps the code OUT of the stored message body; if no channel lands
    it raises a visible HR task (critical) so HR can hand the code over.

    After a successful insert, prior app_activation Inbox rows for this employee
    are marked inbox_hidden so only the newest code is employee-visible. Older
    rows remain stored for audit. Supersede runs after deliver so a failed send
    cannot hide the previous visible row.
    """
    company = require_company_code(company_code)
    emp_key = str(employee.get("employee_key") or "").strip()
    # Unique per invite/delivery so a new code always creates a new audit row.
    # Visibility of older rows is controlled by inbox_hidden, not by blocking insert.
    invite_token = str(invite_id or "").strip() or secrets.token_hex(8)
    dedupe = f"app_activation:{emp_key}:{invite_token}" if emp_key else None
    profile = employee.get("profile") if isinstance(employee.get("profile"), dict) else {}
    locale = str(
        employee.get("locale")
        or employee.get("language")
        or profile.get("locale")
        or profile.get("language")
        or "en"
    ).strip().lower()
    try:
        result = deliver_employee_notification(
            employee,
            flow="app_activation",
            template_key="app_activation",
            text=None,
            email_subject=_outbound_delivery.activation_email_subject(locale),
            company_code=company,
            locale=locale,
            variables={"code": code, "expiry_hours": _EMPLOYEE_APP_INVITE_TTL_HOURS},
            subject_key=employee.get("employee_key"),
            dedupe_key=dedupe,
            extra={"invite_id": str(invite_id)} if invite_id else None,
        )
    except Exception:
        logger.warning("app activation code delivery failed for %s", employee.get("employee_key"), exc_info=True)
        return {"ok": False, "delivery_status": "failed", "error": "delivery_failed"}
    if emp_key:
        keep = str(result.get("message_id") or "").strip() or None
        try:
            _supersede_prior_app_activation_inbox(
                company_code=company,
                employee_key=emp_key,
                keep_message_id=keep,
            )
        except Exception:
            logger.warning(
                "app activation inbox supersede failed for %s",
                emp_key,
                exc_info=True,
            )
    return result


def _supersede_prior_app_activation_inbox(
    *,
    company_code: str,
    employee_key: str,
    keep_message_id: str | None = None,
) -> int:
    """Hide older app_activation rows from the employee Inbox projection.

    Does not delete rows. Audit/delivery history stays in employee_messages;
    `/app/notifications` and Home unread omit `metadata.inbox_hidden` rows and,
    as a belt-and-suspenders rule, only the newest non-hidden app_activation.
    """
    company = require_company_code(company_code)
    key = str(employee_key or "").strip()
    if not key:
        return 0
    keep = str(keep_message_id or "").strip() or None
    patch = {
        "inbox_hidden": True,
        "inbox_hidden_reason": "superseded_by_newer_activation",
    }
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE employee_messages
                SET metadata = COALESCE(metadata, '{}'::jsonb) || %s::jsonb,
                    updated_at = now()
                WHERE company_code=%s
                  AND employee_key=%s
                  AND flow='app_activation'
                  AND COALESCE((metadata->>'inbox_hidden')::boolean, false) IS NOT TRUE
                  AND (%s::uuid IS NULL OR message_id <> %s::uuid)
                """,
                (Json(patch), company, key, keep, keep),
            )
            hidden = int(cur.rowcount or 0)
        conn.commit()
    return hidden


def _remediate_app_activation_inbox_projection(*, company_code: str, employee_key: str) -> dict[str, Any]:
    """Keep the newest app_activation visible; hide older duplicates for one employee."""
    company = require_company_code(company_code)
    key = str(employee_key or "").strip()
    if not key:
        return {"ok": False, "hidden": 0, "kept": None}
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT message_id
                FROM employee_messages
                WHERE company_code=%s AND employee_key=%s AND flow='app_activation'
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (company, key),
            )
            row = cur.fetchone()
    kept = str(row["message_id"]) if row else None
    hidden = _supersede_prior_app_activation_inbox(
        company_code=company,
        employee_key=key,
        keep_message_id=kept,
    )
    return {"ok": True, "hidden": hidden, "kept": kept}


def _create_employee_session_with_cursor(
    cur: Any,
    company_code: str,
    employee_key: str,
    phone: str | None,
    *,
    platform: str | None = None,
) -> dict[str, Any]:
    token = secrets.token_urlsafe(32)
    refresh = secrets.token_urlsafe(48)
    now = now_utc()
    expires = now + timedelta(days=_EMPLOYEE_APP_SESSION_TTL_DAYS)
    refresh_expires = now + timedelta(days=_EMPLOYEE_APP_REFRESH_TTL_DAYS)
    company = require_company_code(company_code)
    # Wave 5C: stamp ESS identity session_epoch so /app auth fails closed after revoke.
    ess_epoch = None
    try:
        cur.execute(
            """
            SELECT session_epoch FROM employee_ess_identity_bindings
            WHERE company_code=%s AND employee_key=%s AND status='active'
            LIMIT 1
            """,
            (company, str(employee_key)),
        )
        brow = cur.fetchone()
        if brow:
            ess_epoch = int(dict(brow).get("session_epoch") or 1)
    except Exception:
        ess_epoch = None
    meta = {"platform": _normalize_employee_device_platform(platform)}
    cur.execute(
        """
        INSERT INTO employee_sessions
          (company_code, employee_key, phone, token_hash, refresh_hash, expires_at, refresh_expires_at, ess_session_epoch, metadata)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)
        """,
        (
            company,
            str(employee_key),
            digits(phone),
            _app_token_hash(token),
            _app_token_hash(refresh),
            expires,
            refresh_expires,
            ess_epoch,
            Json(meta),
        ),
    )
    return {
        "token": token,
        "refresh_token": refresh,
        "expires_at": expires,
        "refresh_expires_at": refresh_expires,
        "ess_session_epoch": ess_epoch,
        "platform": meta["platform"],
    }


def create_employee_session(company_code: str, employee_key: str, phone: str | None, *, platform: str | None = None) -> dict[str, Any]:
    assert_employee_app_allowlisted(str(employee_key))
    with db_connect() as conn:
        with conn.cursor() as cur:
            session = _create_employee_session_with_cursor(cur, company_code, employee_key, phone, platform=platform)
        conn.commit()
    return session


def employee_by_session(token: str | None) -> dict[str, Any] | None:
    if not token:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM employee_sessions WHERE token_hash=%s AND status='active' AND expires_at > now() LIMIT 1",
                (_app_token_hash(token),),
            )
            row = cur.fetchone()
            if not row:
                return None
            sess = dict(row)
            # Wave 5C: reject stale /app sessions after ESS identity epoch bump.
            stamped = sess.get("ess_session_epoch")
            if stamped is not None:
                try:
                    cur.execute(
                        """
                        SELECT session_epoch FROM employee_ess_identity_bindings
                        WHERE company_code=%s AND employee_key=%s AND status='active'
                        LIMIT 1
                        """,
                        (str(sess.get("company_code") or "").upper(), str(sess.get("employee_key") or "")),
                    )
                    bind = cur.fetchone()
                    current = int(dict(bind).get("session_epoch") or 0) if bind else None
                    if current is None or int(stamped) != int(current):
                        cur.execute(
                            """
                            UPDATE employee_sessions
                            SET status='revoked', revoked_at=now(), revoked_reason='ess_session_epoch_stale'
                            WHERE session_id=%s AND status='active'
                            """,
                            (sess["session_id"],),
                        )
                        conn.commit()
                        return None
                except Exception:
                    # If ESS tables unavailable, fail closed only when stamped epoch exists and lookup fails hard.
                    pass
            cur.execute("UPDATE employee_sessions SET last_seen_at=now() WHERE session_id=%s", (sess["session_id"],))
        conn.commit()
    employee = find_employee_by_key(sess["employee_key"], company_code=sess["company_code"])
    if not employee:
        return None
    return {
        "session_id": str(sess["session_id"]),
        "company_code": str(sess["company_code"]).upper(),
        "employee_key": str(sess["employee_key"]),
        "employee": employee,
        "ess_session_epoch": sess.get("ess_session_epoch"),
    }


def employee_session_record(token: str | None) -> dict[str, Any] | None:
    """Resolve an opaque token's session row for authoritative denial reasons.

    This never authenticates a request; it is consulted only after the normal
    active-session lookup fails, so a revoked employee receives the correct
    account/company state instead of an undifferentiated expired-session error.
    """
    if not token:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT session_id, company_code, employee_key, status, expires_at,
                       revoked_reason
                FROM employee_sessions
                WHERE token_hash=%s
                LIMIT 1
                """,
                (_app_token_hash(token),),
            )
            row = cur.fetchone()
    return dict(row) if row else None


def rotate_employee_session(refresh_token: str | None) -> dict[str, Any] | None:
    if not refresh_token:
        return None
    presented_hash = _app_token_hash(refresh_token)
    with db_connect() as conn:
        with conn.cursor() as cur:
            # First resolve the owning company without mutation. Company transitions
            # lock that row exclusively; refresh holds it shared until commit.
            cur.execute(
                "SELECT session_id, company_code FROM employee_sessions WHERE refresh_hash=%s LIMIT 1",
                (presented_hash,),
            )
            initial = cur.fetchone()
            if not initial:
                return None
            allowed, _reason = _employee_app_company_gate(cur, str(initial["company_code"]))
            if not allowed:
                return None
            cur.execute(
                """
                SELECT * FROM employee_sessions
                WHERE session_id=%s AND refresh_hash=%s
                LIMIT 1 FOR UPDATE
                """,
                (initial["session_id"], presented_hash),
            )
            row = cur.fetchone()
            if not row:
                return None
            sess = dict(row)
            if (
                str(sess.get("status") or "") != "active"
                or not sess.get("refresh_expires_at")
                or sess["refresh_expires_at"] <= now_utc()
            ):
                return None
            cur.execute(
                """
                SELECT * FROM employees
                WHERE company_code=%s AND employee_key=%s
                LIMIT 1 FOR SHARE
                """,
                (sess["company_code"], sess["employee_key"]),
            )
            employee = dict(cur.fetchone() or {})
            allowed, access_reason = _employee_app_runtime_access(employee)
            if not allowed:
                # Refresh must not outlive eligibility. Kill the session in the same
                # transaction so the next request reports the definitive reason instead
                # of an ambiguous auth failure.
                cur.execute(
                    """
                    UPDATE employee_sessions
                    SET status='revoked', refresh_hash=NULL, revoked_at=now(), revoked_reason=%s,
                        expires_at=LEAST(expires_at, now()),
                        refresh_expires_at=LEAST(refresh_expires_at, now())
                    WHERE session_id=%s AND status='active'
                    """,
                    (
                        "employment_inactive"
                        if access_reason == _EMPLOYEE_APP_ACCESS_EMPLOYMENT
                        else "app_access_disabled",
                        sess["session_id"],
                    ),
                )
                conn.commit()
                return None
            now = now_utc()
            token = secrets.token_urlsafe(32)
            refresh = secrets.token_urlsafe(48)
            expires = now + timedelta(days=_EMPLOYEE_APP_SESSION_TTL_DAYS)
            refresh_expires = now + timedelta(days=_EMPLOYEE_APP_REFRESH_TTL_DAYS)
            cur.execute(
                "UPDATE employee_sessions SET token_hash=%s, refresh_hash=%s, expires_at=%s, refresh_expires_at=%s, last_seen_at=now() WHERE session_id=%s",
                (_app_token_hash(token), _app_token_hash(refresh), expires, refresh_expires, sess["session_id"]),
            )
        conn.commit()
    return {
        "token": token,
        "refresh_token": refresh,
        "expires_at": expires,
        "company_code": str(sess["company_code"]).upper(),
        "employee_key": str(sess["employee_key"]),
        "employee": employee,
    }


def revoke_employee_session_token(token: str | None) -> None:
    if not token:
        return
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE employee_sessions
                SET status='revoked', refresh_hash=NULL, revoked_at=now(), revoked_reason='logout',
                    expires_at=LEAST(expires_at, now()), refresh_expires_at=LEAST(refresh_expires_at, now())
                WHERE token_hash=%s AND status='active'
                """,
                (_app_token_hash(token),),
            )
        conn.commit()


def revoke_employee_app_access(company_code: str, employee_key: str, *, reason: str = "revoked") -> int:
    """Hard kill switch: revoke every active session and deactivate every push
    token for an employee. Called on logout-all and (critically) on offboarding so
    a terminated employee instantly loses app access."""
    company = require_company_code(company_code)
    revoked = 0
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE employee_sessions
                SET status='revoked', refresh_hash=NULL, revoked_at=now(), revoked_reason=%s,
                    expires_at=LEAST(expires_at, now()), refresh_expires_at=LEAST(refresh_expires_at, now())
                WHERE company_code=%s AND employee_key=%s AND status='active'
                """,
                (reason[:120], company, str(employee_key)),
            )
            revoked = cur.rowcount or 0
            cur.execute(
                "UPDATE employee_push_tokens SET active=FALSE, last_error=%s, updated_at=now() WHERE company_code=%s AND employee_key=%s AND active IS TRUE",
                (reason[:120], company, str(employee_key)),
            )
        conn.commit()
    return revoked


def employee_app_context(
    authorization: str | None = Header(default=None),
    x_app_token: str | None = Header(default=None, alias="X-App-Token"),
) -> dict[str, Any]:
    """Auth dependency for /app/* (the employee equivalent of dashboard_context).
    Resolves the verified employee session and returns an audit-compatible context
    whose identity is fixed to that one employee."""
    ensure_schema()
    token = bearer_token(authorization) or str(x_app_token or "").strip()
    sess = employee_by_session(token)
    if not sess:
        historical = employee_session_record(token)
        if historical:
            historical_company = str(historical.get("company_code") or "").strip().upper()
            lifecycle = company_lifecycle_status(historical_company)
            if lifecycle != "active":
                raise HTTPException(
                    status_code=403,
                    detail={
                        "error": f"company_{lifecycle}",
                        "message": "Your company workspace is not active.",
                    },
                )
            try:
                historical_has_module = company_has_module(historical_company, "employee_app")
            except Exception as exc:
                if _is_transient_db_error(exc):
                    raise HTTPException(
                        status_code=503,
                        detail={
                            "error": "employee_app_temporarily_unavailable",
                            "message": "The employee app is temporarily unavailable. Please try again.",
                        },
                    ) from exc
                raise
            if not historical_has_module:
                raise HTTPException(
                    status_code=403,
                    detail={
                        "error": "employee_app_not_enabled_for_company",
                        "message": "The app is not enabled for your company.",
                    },
                )
            historical_employee = find_employee_by_key(
                str(historical.get("employee_key") or ""),
                company_code=historical_company,
            )
            hist_allowed, _hist_reason = _employee_app_runtime_access(historical_employee)
            if (
                not hist_allowed
                or str(historical.get("revoked_reason") or "") in {"offboarded", "employment_inactive"}
            ):
                raise HTTPException(
                    status_code=403,
                    detail={"error": "account_inactive", "message": "Your account is not active."},
                )
            if str(historical.get("revoked_reason") or "") == "ess_session_epoch_stale":
                raise HTTPException(
                    status_code=401,
                    detail={"error": "stale_session_epoch", "message": "Please sign in again."},
                )
            # Phase 5 — HR revoke / new-device replacement. Distinct from soft failures and
            # natural expiry so the employee app can show calm "access was reset" copy.
            # `app_access_disabled` is the HR eligibility removal, which reads the same way
            # to the employee: sign in again once HR re-enables and re-invites.
            if str(historical.get("revoked_reason") or "") in {
                "hr_revoked",
                "reactivated_via_invite",
                "app_access_disabled",
            }:
                raise HTTPException(
                    status_code=401,
                    detail={
                        "error": "app_access_revoked",
                        "message": "Your app access was reset. Sign in again with a new activation code.",
                    },
                )
        raise HTTPException(status_code=401, detail={"error": "app_auth_failed", "message": "Please sign in again."})
    # Authenticate before exposing platform availability. An anonymous request
    # must fail closed as 401 even while the employee surface is dark-launched;
    # only a verified active session may learn that the product is unavailable.
    if not employee_app_enabled():
        raise HTTPException(status_code=503, detail={"error": "employee_app_disabled", "message": "The employee app is not available right now."})
    company = sess["company_code"]
    lifecycle = company_lifecycle_status(company)
    if lifecycle != "active":
        raise HTTPException(
            status_code=403,
            detail={
                "error": f"company_{lifecycle}",
                "message": "Your company workspace is not active.",
            },
        )
    try:
        has_employee_app = company_has_module(company, "employee_app")
    except Exception as exc:
        if _is_transient_db_error(exc):
            raise HTTPException(
                status_code=503,
                detail={
                    "error": "employee_app_temporarily_unavailable",
                    "message": "The employee app is temporarily unavailable. Please try again.",
                },
            ) from exc
        raise
    if not has_employee_app:
        raise HTTPException(status_code=403, detail={"error": "employee_app_not_enabled_for_company", "message": "The app is not enabled for your company."})
    assert_employee_app_allowlisted(str(sess.get("employee_key") or ""))
    employee = sess["employee"]
    allowed, access_reason = _employee_app_runtime_access(employee)
    if not allowed:
        # Defense in depth: offboarding and HR disable already revoke sessions, but
        # never serve an ineligible employee even if a stale session slipped through.
        if access_reason == _EMPLOYEE_APP_ACCESS_EMPLOYMENT:
            revoke_employee_app_access(company, sess["employee_key"], reason="employment_inactive")
            raise HTTPException(status_code=403, detail={"error": "account_inactive", "message": "Your account is not active."})
        revoke_employee_app_access(company, sess["employee_key"], reason="app_access_disabled")
        raise HTTPException(
            status_code=401,
            detail={
                "error": "app_access_revoked",
                "message": "Your app access was reset. Sign in again with a new activation code.",
            },
        )
    phone = digits(employee.get("phone"))
    return {
        "company_code": company,
        "employee_key": sess["employee_key"],
        "employee": employee,
        "phone": phone,
        "session_id": sess["session_id"],
        "ess_session_epoch": sess.get("ess_session_epoch"),
        "actor_employee_key": sess["employee_key"],
        # Audit-compatible keys so record_admin_audit attributes actions correctly.
        "actor_user_id": f"employee_app:{sess['employee_key']}",
        "actor_phone": phone,
        "actor_email": employee.get("email") or "",
        "actor_role": "employee",
        "hr_phone": "",
        "hr_user": {"role": "employee", "company_code": company, "phone": phone, "name": employee.get("name") or ""},
    }


