# --- /app auth ---------------------------------------------------------------

@app.post("/app/auth/activate")
def app_auth_activate(req: EmployeeAppActivateRequest):
    ensure_schema()
    if not employee_app_enabled():
        raise HTTPException(status_code=503, detail={"error": "employee_app_disabled", "message": "The employee app is not available right now."})
    phone = digits(req.phone)
    code = digits(req.code) or str(req.code or "").strip()
    # One generic failure for every "couldn't activate" case so we never disclose
    # whether a phone, company, employee, or invite exists.
    generic = HTTPException(status_code=401, detail={"error": "app_activation_failed", "message": "That code didn't work. Ask your HR team for a new one."})
    if not phone or not code:
        raise generic
    phone_aliases = employee_phone_alias_list(phone)
    if not phone_aliases:
        raise generic
    bootstrap_company = employee_company_code_for_phone(phone)
    if not bootstrap_company:
        raise generic
    session: dict[str, Any] | None = None
    employee: dict[str, Any] | None = None
    company = str(bootstrap_company).upper()
    replaced_previous_device = False
    with db_connect() as conn:
        with conn.cursor() as cur:
            allowed, _reason = _employee_app_company_gate(cur, company)
            if not allowed:
                raise generic
            # Kuwait local 8-digit input (app shows +965 chip separately) must match
            # invites stored as 965XXXXXXXX. Alias list covers both forms.
            cur.execute(
                """
                SELECT * FROM employee_app_invites
                WHERE company_code=%s AND phone = ANY(%s) AND status='pending'
                ORDER BY created_at DESC
                LIMIT 1 FOR UPDATE
                """,
                (company, phone_aliases),
            )
            invite = cur.fetchone()
            if not invite:
                raise generic
            invite = dict(invite)
            if not invite.get("expires_at") or invite["expires_at"] <= now_utc():
                raise generic
            if int(invite.get("attempts") or 0) >= _EMPLOYEE_APP_MAX_CODE_ATTEMPTS:
                cur.execute("UPDATE employee_app_invites SET status='locked', updated_at=now() WHERE invite_id=%s", (invite["invite_id"],))
                conn.commit()
                raise HTTPException(status_code=429, detail={"error": "too_many_attempts", "message": "Too many attempts. Ask your HR team for a new code."})
            # Hash was minted against the invite's stored phone digits — verify with that,
            # not the raw request form (99338566 vs 96599338566).
            invite_phone = digits(invite.get("phone")) or phone
            if not hmac.compare_digest(str(invite.get("code_hash") or ""), _app_code_hash(company, invite_phone, code)):
                cur.execute("UPDATE employee_app_invites SET attempts=attempts+1, updated_at=now() WHERE invite_id=%s", (invite["invite_id"],))
                conn.commit()
                raise generic
            canonical_company = str(invite.get("company_code") or "").strip().upper()
            invite_employee_key = str(invite.get("employee_key") or "").strip()
            if canonical_company != company or not invite_employee_key:
                raise generic
            # Lock the canonical employee row by key (phone aliases alone are not unique
            # enough under concurrent invites). Serializes double-submit.
            cur.execute(
                """
                SELECT * FROM employees
                WHERE company_code=%s AND employee_key=%s
                LIMIT 1 FOR UPDATE
                """,
                (canonical_company, invite_employee_key),
            )
            employee = dict(cur.fetchone() or {})
            employee_phone = digits(employee.get("phone"))
            # A pending invite is not standing authority: re-check eligibility at
            # redemption so access removed after issuance cannot still activate.
            access_allowed, _access_reason = _employee_app_runtime_access(employee)
            if (
                not access_allowed
                or str(employee.get("company_code") or "").strip().upper() != canonical_company
                or str(employee.get("employee_key") or "").strip() != invite_employee_key
                or (employee_phone and employee_phone not in phone_aliases and invite_phone not in phone_aliases)
            ):
                raise generic
            assert_employee_app_allowlisted(invite_employee_key)
            # A valid pending invite authorizes first activation OR new-device
            # reactivation: revoke any active sessions/tokens for this employee,
            # then mint a fresh session (never leave the account stuck on
            # already_activated after HR/QA reissue).
            cur.execute(
                """
                UPDATE employee_sessions
                SET status='revoked', refresh_hash=NULL, revoked_at=now(),
                    revoked_reason='reactivated_via_invite',
                    expires_at=LEAST(expires_at, now()),
                    refresh_expires_at=LEAST(refresh_expires_at, now())
                WHERE company_code=%s AND employee_key=%s AND status='active'
                """,
                (canonical_company, invite_employee_key),
            )
            replaced_previous_device = int(cur.rowcount or 0) > 0
            cur.execute(
                """
                UPDATE employee_push_tokens
                SET active=FALSE, last_error='reactivated_via_invite', updated_at=now()
                WHERE company_code=%s AND employee_key=%s AND active IS TRUE
                """,
                (canonical_company, invite_employee_key),
            )
            session_phone = employee_phone or invite_phone or phone
            session = _create_employee_session_with_cursor(
                cur,
                canonical_company,
                invite_employee_key,
                session_phone,
                platform=req.platform,
            )
            cur.execute(
                """
                UPDATE employee_app_invites
                SET status='redeemed', redeemed_at=now(), updated_at=now()
                WHERE invite_id=%s AND status='pending'
                """,
                (invite["invite_id"],),
            )
            if int(cur.rowcount or 0) != 1:
                raise generic
        conn.commit()
    if not session or not employee:
        raise generic
    logger.info("employee app activated company=%s employee=%s", company, employee.get("employee_key"))
    return json_safe({
        "ok": True,
        "token": session["token"],
        "refresh_token": session["refresh_token"],
        "expires_at": session["expires_at"],
        "employee": employee_app_public(employee, company),
        "replaced_previous_device": replaced_previous_device,
    })


@app.post("/app/auth/request-code")
def app_auth_request_code(req: EmployeeAppRequestCodeRequest):
    ensure_schema()
    if not employee_app_enabled():
        raise HTTPException(status_code=503, detail={"error": "employee_app_disabled", "message": "The employee app is not available right now."})
    phone = digits(req.phone)
    # Always generic so this endpoint never reveals whether a number is registered.
    generic = {"ok": True, "message": "If your number is registered, you'll receive a code shortly."}
    if not phone:
        return generic
    company = employee_company_code_for_phone(phone)
    if not company or not company_has_module(company, "employee_app"):
        return generic
    if company_lifecycle_status(company) != "active":
        return generic
    employee = find_employee_by_phone(phone, company_code=company)
    if not _employee_app_employee_eligible(employee):
        return generic
    # HR-provisioned model: only (re)issue a code if HR already invited this
    # employee at least once. No prior invite -> stay silent (no self-registration).
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT max(last_sent_at) AS last_sent, count(*) AS n FROM employee_app_invites WHERE company_code=%s AND employee_key=%s",
                (company, employee.get("employee_key")),
            )
            row = dict(cur.fetchone() or {})
    if int(row.get("n") or 0) == 0:
        return generic
    last_sent = row.get("last_sent")
    if last_sent and (now_utc() - last_sent).total_seconds() < _EMPLOYEE_APP_CODE_RESEND_COOLDOWN_SECONDS:
        return generic
    try:
        import employee_app_invitation as _inv

        _inv.issue_and_deliver_invitation(
            sys.modules[__name__],
            company_code=company,
            employee=employee,
            trigger_source=_inv.TRIGGER_REQUEST_CODE,
            force_new=True,
        )
    except Exception:
        logger.warning("request-code invitation delivery failed phone=%s", phone, exc_info=True)
    return generic


@app.post("/app/auth/refresh")
def app_auth_refresh(req: EmployeeAppRefreshRequest):
    ensure_schema()
    if not employee_app_enabled():
        raise HTTPException(status_code=503, detail={"error": "employee_app_disabled", "message": "The employee app is not available right now."})
    rotated = rotate_employee_session(req.refresh_token)
    if not rotated:
        raise HTTPException(status_code=401, detail={"error": "app_auth_failed", "message": "Please sign in again."})
    employee = rotated["employee"]
    return json_safe({
        "ok": True,
        "token": rotated["token"],
        "refresh_token": rotated["refresh_token"],
        "expires_at": rotated["expires_at"],
        "employee": employee_app_public(employee, rotated["company_code"]),
    })


@app.post("/app/auth/logout")
def app_auth_logout(authorization: str | None = Header(default=None), x_app_token: str | None = Header(default=None, alias="X-App-Token")):
    token = bearer_token(authorization) or str(x_app_token or "").strip()
    revoke_employee_session_token(token)
    return {"ok": True}


@app.get("/app/device-security")
def app_device_security(context: dict[str, Any] = Depends(employee_app_context)):
    """Phase 5 — current-device summary for Settings. No session ids or tokens."""
    session_id = str(context.get("session_id") or "").strip()
    if not session_id:
        raise HTTPException(status_code=401, detail={"error": "app_auth_failed", "message": "Please sign in again."})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT created_at, last_seen_at, status, metadata
                FROM employee_sessions
                WHERE session_id=%s AND company_code=%s AND employee_key=%s
                LIMIT 1
                """,
                (session_id, context["company_code"], context["employee_key"]),
            )
            row = cur.fetchone()
    if not row:
        raise HTTPException(status_code=401, detail={"error": "app_auth_failed", "message": "Please sign in again."})
    sess = dict(row)
    if str(sess.get("status") or "") != "active":
        raise HTTPException(status_code=401, detail={"error": "app_auth_failed", "message": "Please sign in again."})
    return json_safe({
        "ok": True,
        "device": _employee_device_security_public(
            platform=_employee_session_platform(sess.get("metadata")),
            activated_at=sess.get("created_at"),
            last_active_at=sess.get("last_seen_at"),
            status="active",
        ),
    })


