@app.get("/app/me")
def app_me(context: dict[str, Any] = Depends(employee_app_context)):
    company = context["company_code"]
    employee = context["employee"]
    profile = employee_app_public(employee, company)
    capabilities = employee_app_capability_payload(context)
    return json_safe({
        "ok": True,
        # Preserve the original flattened profile during the client transition.
        **profile,
        "employee": profile,
        "company_identity": mobile_company_identity(company),
        **capabilities,
        "leave_balances_enabled": capabilities["leave"]["balances_enabled"],
    })


@app.get("/app/profile")
def app_profile(context: dict[str, Any] = Depends(employee_app_context)):
    company = context["company_code"]
    employee = context["employee"]
    key = str(employee.get("employee_key") or "")
    # Bank ESS owns `bank_details`; align before reading so profile completion
    # cannot lag the checklist the employee just finished.
    try:
        import employee_bank_ess as _bank_sync

        with db_connect() as conn:
            with conn.cursor() as cur:
                _bank_sync.ensure_bank_ess_schema(cur)
                _bank_sync.reconcile_onboarding_bank_item(
                    cur, company_code=company, employee_key=key
                )
            conn.commit()
    except Exception:
        logger.exception("employee profile bank reconcile failed employee=%s", key)
    summary = employee_onboarding_summary(employee, company_code=company)
    completion = summary.get("completion") or {}
    projection = employee_app_profile_projection(employee, company)
    return json_safe({
        "ok": True,
        # Lean employee card kept for older clients; personal/employment are the
        # Profile surface's structured sections over the same canonical row.
        "employee": projection["employee"],
        "personal": projection["personal"],
        "employment": projection["employment"],
        "onboarding": {
            # Canonical contract first; legacy counts kept for older clients.
            "completion": completion,
            "completion_state": summary.get("completion_state"),
            "next_action": completion.get("next_action"),
            "satisfied_count": completion.get("satisfied_count"),
            "status": summary.get("status"),
            "required_total": summary.get("required_total"),
            "received_count": summary.get("received_count"),
            "pending_count": summary.get("pending_count"),
            "bank_collection": summary.get("bank_collection"),
        },
    })


# --- /app self-service reads -------------------------------------------------

# Shared employee reads. The module routes and the /app/home projection call these so
# there is exactly one query per fact; Home aggregates module output, it never re-derives.

def _employee_shift_rows(
    cur: Any,
    *,
    company_code: str,
    employee_key: str,
    date_from: date,
    date_to: date | None = None,
    limit: int = 50,
    detailed: bool = False,
) -> list[dict[str, Any]]:
    """Assigned, non-cancelled shifts in [date_from, date_to] (single day when date_to is None).

    `detailed` adds the schedule fields the Schedule surface pairs with attendance. The
    default projection is what `/app/shifts/*` has always returned.
    """
    columns = "shift_id, shift_date, start_time, end_time, status, role, location"
    if detailed:
        columns += ", timezone, notes"
    cur.execute(
        f"""
        SELECT {columns}
        FROM shift_assignments
        WHERE company_code=%s AND employee_key=%s AND shift_date >= %s AND shift_date <= %s
          AND status <> 'cancelled'
        ORDER BY shift_date, start_time NULLS LAST
        LIMIT %s
        """,
        (company_code, employee_key, date_from, date_to or date_from, limit),
    )
    return [dict(row) for row in cur.fetchall()]


def _employee_attendance_rows(
    cur: Any,
    *,
    company_code: str,
    employee_key: str,
    since: date,
    until: date | None = None,
    limit: int = 60,
    detailed: bool = False,
) -> list[dict[str, Any]]:
    """Recorded attendance from `since` (inclusive) onward, newest first.

    `detailed` adds the canonical record fields — scheduled window, check in/out,
    lateness, early leave and HR notes — that already exist on the record. Nothing is
    derived here: the Schedule surface presents these, it never recomputes them.
    """
    columns = "attendance_date, status"
    if detailed:
        columns += (
            ", attendance_id, shift_id, scheduled_start, scheduled_end,"
            " check_in_at, check_out_at, late_minutes, early_leave_minutes, notes"
        )
    cur.execute(
        f"""
        SELECT {columns}
        FROM attendance_records
        WHERE company_code=%s AND employee_key=%s AND attendance_date >= %s
          AND (%s::date IS NULL OR attendance_date <= %s)
        ORDER BY attendance_date DESC
        LIMIT %s
        """,
        (company_code, employee_key, since, until, until, limit),
    )
    return [dict(row) for row in cur.fetchall()]


def _employee_attendance_summary(rows: list[dict[str, Any]]) -> dict[str, int]:
    summary = {"present": 0, "late": 0, "absent": 0}
    for row in rows:
        status = normalize_text(row.get("status") or "")
        if status in summary:
            summary[status] += 1
    return summary


def _employee_leave_request_rows(
    cur: Any,
    *,
    company_code: str,
    employee_key: str,
    limit: int = 50,
) -> list[dict[str, Any]]:
    cur.execute(
        """
        SELECT leave_id, employee_key, employee_phone, start_date, end_date,
               leave_type, status, reason, requested_at, decided_at
        FROM leave_requests
        WHERE company_code=%s AND employee_key=%s
        ORDER BY start_date DESC
        LIMIT %s
        """,
        (company_code, employee_key, limit),
    )
    return [dict(row) for row in cur.fetchall()]


_LEAVE_HISTORY_MAX_LIMIT = 50
_LEAVE_HISTORY_DEFAULT_LIMIT = 30
# Filter allowlist only — does not invent statuses. Matches HR leave vocabulary +
# known terminal aliases already recognized by the employee Leave root partition.
_EMPLOYEE_LEAVE_FILTER_STATUSES = frozenset(
    {
        "requested",
        "approved",
        "rejected",
        "cancelled",
        "canceled",
        "completed",
        "denied",
        "withdrawn",
        "expired",
    }
)


def encode_leave_history_cursor(row: dict[str, Any]) -> str:
    """Opaque keyset cursor for leave history (start_date DESC, leave_id DESC)."""
    payload = {
        "v": 1,
        "d": str(row.get("start_date") or ""),
        "id": str(row.get("leave_id") or ""),
    }
    raw = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def decode_leave_history_cursor(token: str | None) -> dict[str, str] | None:
    text = str(token or "").strip()
    if not text:
        return None
    pad = "=" * (-len(text) % 4)
    try:
        payload = json.loads(base64.urlsafe_b64decode(text + pad).decode("utf-8"))
    except Exception as exc:  # noqa: BLE001
        raise ValueError("invalid_cursor") from exc
    if not isinstance(payload, dict) or int(payload.get("v") or 0) != 1:
        raise ValueError("invalid_cursor")
    day = str(payload.get("d") or "").strip()
    lid = str(payload.get("id") or "").strip()
    if not day or not lid:
        raise ValueError("invalid_cursor")
    _parse_kuwait_iso_date(day, field="cursor")
    return {"d": day, "id": lid}


def _employee_leave_request_entry(
    row: dict[str, Any],
    *,
    actor_phone: str | None,
    cancel_action_enabled: bool,
    as_of: date,
) -> dict[str, Any]:
    """Employee Leave read projection over canonical workflow state.

    Stored ``status`` remains untouched for audit/history.  Cancellation
    eligibility and temporal presentation come from the same Kuwait-local
    policy helper used by the mutation; the client is not a policy authority.
    """
    stored = {
        "leave_id": str(row.get("leave_id") or "") or None,
        "start_date": row.get("start_date"),
        "end_date": row.get("end_date"),
        "leave_type": row.get("leave_type"),
        "status": row.get("status"),
        "reason": row.get("reason"),
        "requested_at": row.get("requested_at"),
        "decided_at": row.get("decided_at"),
    }
    synthetic = _leave_authority.is_leave_synthetic_employee(
        row,
        employee_key=str(row.get("employee_key") or ""),
        phone=str(row.get("employee_phone") or ""),
    )
    policy = _leave_w4.cancel_policy_projection(
        row,
        actor_phone=actor_phone,
        is_self=True,
        is_synthetic_subject=synthetic,
        action_enabled=cancel_action_enabled,
        as_of=as_of,
    )
    return {**stored, **policy}


def _employee_leave_history_page(
    cur: Any,
    *,
    company_code: str,
    employee_key: str,
    limit: int = _LEAVE_HISTORY_DEFAULT_LIMIT,
    cursor: str | None = None,
    date_from: date | None = None,
    date_to: date | None = None,
    status: str | None = None,
    as_of: date | None = None,
) -> dict[str, Any]:
    """Keyset page of leave requests, newest start_date first.

    Ordering: ``start_date DESC, leave_id DESC``. Fetches ``limit + 1`` so
    ``has_more`` is honest. Optional status / date bounds filter without raising
    the silent `/app/leave` hard cap.
    """
    page_size = max(1, min(int(limit or _LEAVE_HISTORY_DEFAULT_LIMIT), _LEAVE_HISTORY_MAX_LIMIT))
    policy_day = as_of or datetime.now(tz=KUWAIT_TZ).date()
    decoded = decode_leave_history_cursor(cursor)
    params: list[Any] = [company_code, employee_key]
    clauses = ["company_code=%s", "employee_key=%s"]
    if status is not None:
        if status == "completed":
            clauses.append(
                "(lower(status)='completed' OR (lower(status)='approved' AND COALESCE(end_date,start_date) < %s))"
            )
            params.append(policy_day)
        elif status == "approved":
            clauses.append("lower(status)='approved' AND COALESCE(end_date,start_date) >= %s")
            params.append(policy_day)
        elif status in {"cancelled", "canceled"}:
            clauses.append("lower(status) IN ('cancelled','canceled')")
        elif status in {"rejected", "denied"}:
            clauses.append("lower(status) IN ('rejected','denied')")
        else:
            clauses.append("lower(status)=%s")
            params.append(status)
    if date_from is not None:
        clauses.append("start_date >= %s")
        params.append(date_from)
    if date_to is not None:
        clauses.append("start_date <= %s")
        params.append(date_to)
    if decoded:
        clauses.append(
            """(
              start_date < %s::date
              OR (start_date = %s::date AND leave_id::text < %s)
            )"""
        )
        params.extend([decoded["d"], decoded["d"], decoded["id"]])
    params.append(page_size + 1)
    cur.execute(
        f"""
        SELECT leave_id, employee_key, employee_phone, start_date, end_date,
               leave_type, status, reason, requested_at, decided_at
        FROM leave_requests
        WHERE {' AND '.join(clauses)}
        ORDER BY start_date DESC, leave_id::text DESC
        LIMIT %s
        """,
        tuple(params),
    )
    fetched = [dict(row) for row in cur.fetchall()]
    has_more = len(fetched) > page_size
    page_rows = fetched[:page_size]
    next_cursor = encode_leave_history_cursor(page_rows[-1]) if has_more and page_rows else None
    return {
        "requests": page_rows,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "limit": page_size,
    }


def _json_object(value: Any) -> dict[str, Any]:
    """Coerce a jsonb column that may arrive as dict or text into a plain dict."""
    if isinstance(value, dict):
        return value
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
        except Exception:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _employee_inbox_rows(
    cur: Any,
    *,
    company_code: str,
    employee_key: str,
    limit: int = 50,
) -> list[dict[str, Any]]:
    """Employee-visible Inbox projection over employee_messages.

    Rows marked ``metadata.inbox_hidden`` stay in the table for audit but are
    omitted here (and therefore from Home unread). For ``app_activation``, only
    the newest non-hidden row is projected so resends cannot flood Unread.
    """
    cur.execute(
        """
        SELECT m.message_id, m.flow, m.template_key, m.status, m.sensitivity,
               m.body_preview, m.created_at, m.metadata,
               (r.read_at IS NOT NULL) AS read
        FROM employee_messages m
        LEFT JOIN employee_notification_reads r
          ON r.employee_key = m.employee_key AND r.message_id = m.message_id
        WHERE m.company_code=%s
          AND m.employee_key=%s
          AND m.flow = ANY(%s)
          AND COALESCE((m.metadata->>'inbox_hidden')::boolean, false) IS NOT TRUE
          AND (
            m.flow IS DISTINCT FROM 'app_activation'
            OR m.message_id = (
              SELECT m2.message_id
              FROM employee_messages m2
              WHERE m2.company_code = m.company_code
                AND m2.employee_key = m.employee_key
                AND m2.flow = 'app_activation'
                AND COALESCE((m2.metadata->>'inbox_hidden')::boolean, false) IS NOT TRUE
              ORDER BY m2.created_at DESC
              LIMIT 1
            )
          )
        ORDER BY m.created_at DESC
        LIMIT %s
        """,
        (company_code, employee_key, list(_APP_INBOX_FLOWS), limit),
    )
    return [dict(row) for row in cur.fetchall()]


def _require_any_employee_app_feature(context: dict[str, Any], feature_keys: tuple[str, ...]) -> set[str]:
    """Admit a combined surface when at least one contributing feature is entitled.

    Returns the entitled subset so the surface can present exactly the authorities it
    has. Uses the same feature contract and the same 403 shape as
    `require_employee_app_feature` — a combined read is not a new entitlement.
    """
    contract = employee_app_feature_contract_for_context(context)
    features = contract.get("features") or {}
    entitled = {key for key in feature_keys if (features.get(key) or {}).get("enabled")}
    if not entitled:
        raise HTTPException(
            status_code=403,
            detail={
                "error": "employee_feature_disabled",
                "message": "This feature is not available for your account.",
                "feature": "+".join(feature_keys),
                "reason": str((features.get(feature_keys[0]) or {}).get("reason") or "feature_disabled"),
            },
        )
    return entitled


_HOME_MODULE_KEYS = ("shifts", "attendance", "leave", "onboarding", "documents", "payslips", "notifications")


def _module_read(
    states: dict[str, str],
    key: str,
    *,
    enabled: bool,
    read: Any,
    cur: Any = None,
    surface: str = "home",
) -> Any:
    """Run one owning-module read for an aggregate surface and record its own state.

    A module that is disabled, or whose read failed, must never reach the client as an
    empty business fact. On failure the module is reported as `error` with no value, and
    when `cur` is given the failure is rolled back to a savepoint so the remaining
    module reads still run on the same transaction.
    """
    if not enabled:
        states[key] = "disabled"
        return None
    savepoint = f"{surface}_{key}"
    if cur is not None:
        cur.execute(f"SAVEPOINT {savepoint}")
    try:
        value = read()
    except Exception:
        logger.exception("app %s module read failed module=%s", surface, key)
        if cur is not None:
            cur.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
        states[key] = "error"
        return None
    if cur is not None:
        cur.execute(f"RELEASE SAVEPOINT {savepoint}")
    states[key] = "ready"
    return value


def _home_document_renewal_detail(
    renewals: list[dict[str, Any]], *, locale: str
) -> dict[str, Any] | None:
    """The single most urgent renewal, for Home's task line.

    Read-only projection of rows the documents module already produced. It picks,
    it does not classify: `renewal_required` and `review_status` are the documents
    module's verdict, `expiry_date` and the label are its stored values, and
    nothing here computes a deadline or a number of days. Rows the module left
    undated sort last and contribute no date, so an expiry can never be inferred
    from a document that has none.
    """
    if not renewals:
        return None

    def sort_key(row: dict[str, Any]) -> tuple[int, str]:
        expiry = str(row.get("expiry_date") or "").strip()
        return (1, "") if not expiry else (0, expiry)

    soonest = sorted(renewals, key=sort_key)[0]
    label = str(soonest.get("label") or "").strip()
    if locale == "ar":
        label = str(soonest.get("label_ar") or "").strip() or label
    detail = {
        "document_type": str(soonest.get("document_type") or "").strip() or None,
        "label": label or None,
        "expiry_date": str(soonest.get("expiry_date") or "").strip() or None,
        "review_status": str(soonest.get("review_status") or "").strip() or None,
    }
    return detail if any(detail.values()) else None


@app.get("/app/home")
def app_home(
    locale: str | None = Query(default=None),
    context: dict[str, Any] = Depends(employee_app_context),
):
    """Self-scoped Home projection: today's summary, tasks, and per-module read state.

    Home aggregates what the owning modules already say. It does not decide entitlement
    (that stays in the feature contract), does not re-derive workflow rules, and does not
    invent a value for a module it could not read: every module carries
    `disabled | loading | error | ready` so the client can state facts only when true.
    Client routes are the client's business — the server emits task `kind`, never a path.
    """
    company = context["company_code"]
    key = context["employee_key"]
    employee = context["employee"]
    loc = "ar" if str(locale or "en").lower().startswith("ar") else "en"
    contract = employee_app_feature_contract_for_context(context)
    features = contract.get("features") or {}

    def enabled(feature_key: str) -> bool:
        return bool((features.get(feature_key) or {}).get("enabled"))

    today = kuwait_today()
    states: dict[str, str] = {}
    tasks: list[dict[str, Any]] = []

    today_shifts: list[dict[str, Any]] | None = None
    attendance_rows: list[dict[str, Any]] | None = None
    leave_rows: list[dict[str, Any]] | None = None
    payslip_rows: list[dict[str, Any]] | None = None
    inbox_rows: list[dict[str, Any]] | None = None

    with db_connect() as conn:
        with conn.cursor() as cur:
            today_shifts = _module_read(
                states,
                "shifts",
                enabled=enabled("shifts"),
                cur=cur,
                read=lambda: _employee_shift_rows(
                    cur, company_code=company, employee_key=key, date_from=today
                ),
            )
            attendance_rows = _module_read(
                states,
                "attendance",
                enabled=enabled("attendance"),
                cur=cur,
                read=lambda: _employee_attendance_rows(
                    cur, company_code=company, employee_key=key, since=today - timedelta(days=30)
                ),
            )
            leave_rows = _module_read(
                states,
                "leave",
                enabled=enabled("leave"),
                cur=cur,
                read=lambda: _employee_leave_request_rows(
                    cur, company_code=company, employee_key=key
                ),
            )
            payslip_rows = _module_read(
                states,
                "payslips",
                enabled=enabled("payslips") and _payroll_w3.payroll_wave3_enabled_for_company(company),
                cur=cur,
                read=lambda: _payroll_w3.list_employee_released_payslips(
                    cur, company_code=company, employee_key=key, limit=12
                ),
            )
            inbox_rows = _module_read(
                states,
                "notifications",
                enabled=True,
                cur=cur,
                read=lambda: _employee_inbox_rows(cur, company_code=company, employee_key=key),
            )
        conn.commit()

    # Documents and Onboarding own their own reads (their projections open their own
    # connections), so they are read outside the shared transaction.
    def _read_compliance() -> list[dict[str, Any]]:
        import kuwait_pilot_document_journey as _kw_doc_journey

        return _kw_doc_journey.list_employee_compliance_journey(
            sys.modules[__name__],
            company_code=company,
            employee_key=key,
            locale=loc,
        )

    compliance = _module_read(states, "documents", enabled=enabled("documents"), read=_read_compliance)
    onboarding = _module_read(
        states,
        "onboarding",
        enabled=enabled("onboarding"),
        read=lambda: employee_onboarding_summary(employee, company_code=company),
    )

    # --- tasks: each one is an owning module's own fact, counted, never re-decided ---

    onboarding_progress: dict[str, Any] | None = None
    if onboarding:
        completion = onboarding.get("completion") or {}
        next_action = completion.get("next_action") or {}
        outstanding = int(onboarding.get("pending_count") or 0)
        # Onboarding's own completion contract decides journey chrome; the client
        # must not re-derive "is it finished" from counts.
        onboarding_progress = {
            "state": completion.get("state"),
            "is_complete": bool(completion.get("is_complete")),
            "suppress_checklist": bool(completion.get("suppress_checklist")),
            "required_total": int(onboarding.get("required_total") or 0),
            "satisfied_count": int(onboarding.get("received_count") or 0),
            "pending_count": outstanding,
            "employee_action_required": str(next_action.get("party") or "") == "employee",
        }
        if onboarding_progress["employee_action_required"] and outstanding > 0:
            tasks.append({
                "kind": "onboarding_documents",
                "module": "onboarding",
                "count": outstanding,
                "severity": "action_required",
            })

    if compliance is not None:
        renewals = [row for row in compliance if row.get("renewal_required")]
        if renewals:
            task: dict[str, Any] = {
                "kind": "document_renewal",
                "module": "documents",
                "count": len(renewals),
                "severity": "action_required",
            }
            # "1 document needs renewing" does not tell an employee whether to act
            # today or next month. The compliance rows are already loaded here and
            # already carry the canonical expiry date and the localized label, so
            # the soonest one rides along. This decides nothing: `renewal_required`
            # still comes from the documents module, and no date is computed here.
            detail = _home_document_renewal_detail(renewals, locale=loc)
            if detail:
                task["detail"] = detail
            tasks.append(task)

    if leave_rows is not None:
        pending_leave = [row for row in leave_rows if normalize_text(row.get("status") or "") == "pending"]
        if pending_leave:
            tasks.append({
                "kind": "leave_pending",
                "module": "leave",
                "count": len(pending_leave),
                "severity": "informational",
            })

    if payslip_rows is not None and inbox_rows is not None:
        # "New payslip" is Payroll's released fact plus Inbox's unread fact; Home does
        # not invent a freshness window of its own.
        released_ids = {str(row.get("payslip_id")) for row in payslip_rows if row.get("payslip_id")}
        unread_payslips: set[str] = set()
        for row in inbox_rows:
            if str(row.get("flow") or "") != "payroll" or row.get("read"):
                continue
            meta = _json_object(row.get("metadata"))
            pid = str(meta.get("payslip_id") or "").strip()
            if pid:
                unread_payslips.add(pid)
        new_payslips = released_ids & unread_payslips
        if new_payslips:
            tasks.append({
                "kind": "payslip_released",
                "module": "payslips",
                "count": len(new_payslips),
                "severity": "informational",
            })

    unread = sum(1 for row in (inbox_rows or []) if not row.get("read"))

    # Today's attendance must be today's record, not simply the newest one in the window.
    attendance_today = None
    if attendance_rows is not None:
        attendance_today = next(
            (
                {"date": row.get("attendance_date"), "status": row.get("status")}
                for row in attendance_rows
                if row.get("attendance_date") == today
            ),
            None,
        )

    contributing = [states.get(k) for k in _HOME_MODULE_KEYS if states.get(k) not in (None, "disabled")]
    caught_up = not tasks and unread == 0 and all(state == "ready" for state in contributing)

    return json_safe({
        "ok": True,
        "locale": loc,
        "date": today,
        "modules": {k: states.get(k, "disabled") for k in _HOME_MODULE_KEYS},
        "today": {
            "shifts": today_shifts if today_shifts is not None else None,
            "shift_count": len(today_shifts) if today_shifts is not None else None,
            "attendance": attendance_today,
        },
        "attendance_window": (
            {"window_days": 30, "summary": _employee_attendance_summary(attendance_rows)}
            if attendance_rows is not None
            else None
        ),
        "onboarding": onboarding_progress,
        "tasks": tasks,
        "inbox": {"unread": unread},
        "caught_up": caught_up,
        "truth": {
            "module_state_is_authoritative": True,
            "no_value_for_unread_module": True,
            "tasks_from_owning_modules": True,
        },
    })


_WORKDAY_WINDOW_DAYS = 30


def _workday_shift_entry(shift: dict[str, Any]) -> dict[str, Any]:
    return {
        "shift_id": str(shift.get("shift_id") or "") or None,
        "date": shift.get("shift_date"),
        "start_time": shift.get("start_time"),
        "end_time": shift.get("end_time"),
        "status": shift.get("status"),
        "role": shift.get("role"),
        "location": shift.get("location"),
        "timezone": shift.get("timezone") or "Asia/Kuwait",
        "notes": shift.get("notes"),
    }


def _workday_attendance_entry(record: dict[str, Any]) -> dict[str, Any]:
    """Present the canonical record. No lateness, duration or exception is derived here."""
    return {
        "attendance_id": str(record.get("attendance_id") or "") or None,
        "shift_id": str(record.get("shift_id") or "") or None,
        "date": record.get("attendance_date"),
        "status": record.get("status"),
        "scheduled_start": record.get("scheduled_start"),
        "scheduled_end": record.get("scheduled_end"),
        "check_in_at": record.get("check_in_at"),
        "check_out_at": record.get("check_out_at"),
        "late_minutes": int(record.get("late_minutes") or 0),
        "early_leave_minutes": int(record.get("early_leave_minutes") or 0),
        "notes": record.get("notes"),
    }


def _workday_today_entries(
    shifts: list[dict[str, Any]] | None,
    records: list[dict[str, Any]] | None,
) -> list[dict[str, Any]]:
    """Pair today's expected schedule with today's recorded attendance.

    A record is paired to a shift only by the canonical `shift_id` the record already
    carries. Unpaired records are kept as their own entries rather than guessed onto a
    shift, and an unmatched shift keeps `recorded: None` so the client can say the
    record is missing instead of inventing one.
    """
    entries: list[dict[str, Any]] = []
    remaining = list(records or [])
    for shift in shifts or []:
        shift_id = str(shift.get("shift_id") or "")
        match = next((r for r in remaining if str(r.get("shift_id") or "") == shift_id), None)
        if match is not None:
            remaining.remove(match)
        entries.append(
            {
                "kind": "scheduled",
                "scheduled": _workday_shift_entry(shift),
                "recorded": _workday_attendance_entry(match) if match else None,
            }
        )
    for record in remaining:
        entries.append(
            {
                # Attendance HR recorded without a matching shift assignment.
                "kind": "recorded_only",
                "scheduled": None,
                "recorded": _workday_attendance_entry(record),
            }
        )
    return entries


@app.get("/app/workday")
def app_workday(
    locale: str | None = Query(default=None),
    context: dict[str, Any] = Depends(employee_app_context),
):
    """Read-only Schedule projection over the existing Shifts and Attendance authorities.

    Combines what those modules already own into one day-centred narrative: today's
    expected schedule beside today's recorded attendance, then upcoming schedule and
    recent records. It conditionally includes whichever authority the employee is
    entitled to, and an authority that is absent or unreadable stays explicitly
    unavailable rather than reading as "nothing scheduled" / "nothing recorded".

    This creates no authority. There is no employee clocking, no attendance correction,
    no payroll input and no new status vocabulary — every value is the owning module's
    own stored value.
    """
    company = context["company_code"]
    key = context["employee_key"]
    entitled = _require_any_employee_app_feature(context, ("shifts", "attendance"))
    loc = "ar" if str(locale or "en").lower().startswith("ar") else "en"
    today = kuwait_today()
    states: dict[str, str] = {}

    today_shifts: list[dict[str, Any]] | None = None
    upcoming_shifts: list[dict[str, Any]] | None = None
    window_records: list[dict[str, Any]] | None = None

    with db_connect() as conn:
        with conn.cursor() as cur:
            today_shifts = _module_read(
                states,
                "shifts",
                enabled="shifts" in entitled,
                cur=cur,
                surface="workday",
                read=lambda: _employee_shift_rows(
                    cur,
                    company_code=company,
                    employee_key=key,
                    date_from=today,
                    detailed=True,
                ),
            )
            if states.get("shifts") == "ready":
                upcoming_shifts = _module_read(
                    states,
                    "shifts_upcoming",
                    enabled=True,
                    cur=cur,
                    surface="workday",
                    read=lambda: _employee_shift_rows(
                        cur,
                        company_code=company,
                        employee_key=key,
                        date_from=today + timedelta(days=1),
                        date_to=today + timedelta(days=_WORKDAY_WINDOW_DAYS),
                        detailed=True,
                    ),
                )
            window_records = _module_read(
                states,
                "attendance",
                enabled="attendance" in entitled,
                cur=cur,
                surface="workday",
                read=lambda: _employee_attendance_rows(
                    cur,
                    company_code=company,
                    employee_key=key,
                    since=today - timedelta(days=_WORKDAY_WINDOW_DAYS),
                    detailed=True,
                ),
            )
        conn.commit()

    today_records = (
        [r for r in window_records if r.get("attendance_date") == today] if window_records is not None else None
    )
    recent_records = (
        [r for r in window_records if r.get("attendance_date") != today] if window_records is not None else None
    )

    shifts_state = states.get("shifts", "disabled")
    attendance_state = states.get("attendance", "disabled")
    # Today's narrative is only trustworthy for the authorities that were actually read.
    entries = _workday_today_entries(
        today_shifts if shifts_state == "ready" else None,
        today_records if attendance_state == "ready" else None,
    )

    return json_safe({
        "ok": True,
        "locale": loc,
        "date": today,
        "authority": {
            "shifts": shifts_state,
            "attendance": attendance_state,
            # Upcoming is the same Shifts authority read over a later window.
            "shifts_upcoming": states.get("shifts_upcoming", shifts_state),
        },
        "today": {
            "entries": entries,
            "scheduled_count": len(today_shifts) if shifts_state == "ready" else None,
            "recorded_count": len(today_records or []) if attendance_state == "ready" else None,
        },
        "upcoming": (
            [_workday_shift_entry(shift) for shift in upcoming_shifts]
            if upcoming_shifts is not None
            else None
        ),
        "recent": (
            [_workday_attendance_entry(record) for record in recent_records]
            if recent_records is not None
            else None
        ),
        "window": (
            {
                "days": _WORKDAY_WINDOW_DAYS,
                "summary": _employee_attendance_summary(window_records),
            }
            if window_records is not None
            else None
        ),
        # Employee-visible truth about what this surface is, and is not.
        "read_only": {
            "employee_clocking": False,
            "attendance_correction": False,
            "payroll_effect": False,
            "authority": "Schedule and attendance are recorded by your HR team.",
            "authority_ar": "يُسجّل فريق الموارد البشرية الجدول والحضور.",
        },
    })



_SCHEDULE_HISTORY_MAX_LIMIT = 50
_SCHEDULE_HISTORY_DEFAULT_LIMIT = 30


def _parse_kuwait_iso_date(value: str | None, *, field: str) -> date | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return date.fromisoformat(text[:10])
    except ValueError as exc:
        raise ValueError(f"invalid_{field}") from exc


def encode_schedule_history_cursor(row: dict[str, Any]) -> str:
    """Opaque keyset cursor for attendance history (date DESC, id DESC)."""
    payload = {
        "v": 1,
        "d": str(row.get("attendance_date") or ""),
        "id": str(row.get("attendance_id") or ""),
    }
    raw = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def decode_schedule_history_cursor(token: str | None) -> dict[str, str] | None:
    text = str(token or "").strip()
    if not text:
        return None
    pad = "=" * (-len(text) % 4)
    try:
        payload = json.loads(base64.urlsafe_b64decode(text + pad).decode("utf-8"))
    except Exception as exc:  # noqa: BLE001
        raise ValueError("invalid_cursor") from exc
    if not isinstance(payload, dict) or int(payload.get("v") or 0) != 1:
        raise ValueError("invalid_cursor")
    day = str(payload.get("d") or "").strip()
    aid = str(payload.get("id") or "").strip()
    if not day or not aid:
        raise ValueError("invalid_cursor")
    # Validate date shape early.
    _parse_kuwait_iso_date(day, field="cursor")
    return {"d": day, "id": aid}


def _employee_shifts_by_ids(
    cur: Any,
    *,
    company_code: str,
    employee_key: str,
    shift_ids: list[str],
) -> dict[str, dict[str, Any]]:
    """Canonical shift assignments for the given ids — never invents missing rows."""
    cleaned = [str(s).strip() for s in shift_ids if str(s or "").strip()]
    if not cleaned:
        return {}
    cur.execute(
        """
        SELECT shift_id, shift_date, start_time, end_time, status, role, location, timezone, notes
        FROM shift_assignments
        WHERE company_code=%s AND employee_key=%s AND shift_id = ANY(%s::uuid[])
        """,
        (company_code, employee_key, cleaned),
    )
    out: dict[str, dict[str, Any]] = {}
    for row in cur.fetchall():
        item = dict(row)
        sid = str(item.get("shift_id") or "")
        if sid:
            out[sid] = item
    return out


def _employee_attendance_history_page(
    cur: Any,
    *,
    company_code: str,
    employee_key: str,
    limit: int = _SCHEDULE_HISTORY_DEFAULT_LIMIT,
    cursor: str | None = None,
    date_from: date | None = None,
    date_to: date | None = None,
) -> dict[str, Any]:
    """Keyset page of recorded attendance, newest first.

    Ordering: ``attendance_date DESC, attendance_id DESC``. Fetches ``limit + 1``
    so ``has_more`` is honest. Optional ``date_from`` / ``date_to`` bound the
    window without loading an unbounded result set in one shot.
    """
    page_size = max(1, min(int(limit or _SCHEDULE_HISTORY_DEFAULT_LIMIT), _SCHEDULE_HISTORY_MAX_LIMIT))
    decoded = decode_schedule_history_cursor(cursor)
    params: list[Any] = [company_code, employee_key]
    clauses = ["company_code=%s", "employee_key=%s"]
    if date_from is not None:
        clauses.append("attendance_date >= %s")
        params.append(date_from)
    if date_to is not None:
        clauses.append("attendance_date <= %s")
        params.append(date_to)
    if decoded:
        clauses.append(
            """(
              attendance_date < %s::date
              OR (attendance_date = %s::date AND attendance_id::text < %s)
            )"""
        )
        params.extend([decoded["d"], decoded["d"], decoded["id"]])
    params.append(page_size + 1)
    cur.execute(
        f"""
        SELECT attendance_id, shift_id, attendance_date, status,
               scheduled_start, scheduled_end,
               check_in_at, check_out_at, late_minutes, early_leave_minutes, notes
        FROM attendance_records
        WHERE {' AND '.join(clauses)}
        ORDER BY attendance_date DESC, attendance_id::text DESC
        LIMIT %s
        """,
        tuple(params),
    )
    fetched = [dict(row) for row in cur.fetchall()]
    has_more = len(fetched) > page_size
    page_rows = fetched[:page_size]
    next_cursor = encode_schedule_history_cursor(page_rows[-1]) if has_more and page_rows else None
    return {
        "records": page_rows,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "limit": page_size,
    }


@app.get("/app/schedule/history")
def app_schedule_history(
    locale: str | None = Query(default=None),
    limit: int = Query(default=_SCHEDULE_HISTORY_DEFAULT_LIMIT, ge=1, le=_SCHEDULE_HISTORY_MAX_LIMIT),
    cursor: str | None = Query(default=None),
    date_from: str | None = Query(default=None),
    date_to: str | None = Query(default=None),
    context: dict[str, Any] = Depends(employee_app_context),
):
    """Paginated attendance history for Schedule — beyond the `/app/workday` ~30-day window.

    Returns recorded attendance facts newest-first. A paired ``scheduled`` object is
    included only when the record's canonical ``shift_id`` resolves to a real
    assignment for this employee — never invented from attendance timestamps alone.

    ``/app/workday`` is unchanged and remains the Schedule root projection.
    """
    company = context["company_code"]
    key = context["employee_key"]
    require_employee_app_feature(context, "attendance")
    # Direct (non-ASGI) calls leave FastAPI Query() defaults unbound — coerce to plain values.
    locale_s = locale if isinstance(locale, str) else None
    cursor_s = cursor if isinstance(cursor, str) else None
    date_from_s = date_from if isinstance(date_from, str) else None
    date_to_s = date_to if isinstance(date_to, str) else None
    page_limit = int(limit) if isinstance(limit, int) else _SCHEDULE_HISTORY_DEFAULT_LIMIT
    page_limit = max(1, min(page_limit, _SCHEDULE_HISTORY_MAX_LIMIT))
    loc = "ar" if str(locale_s or "en").lower().startswith("ar") else "en"
    today = kuwait_today()
    try:
        bound_from = _parse_kuwait_iso_date(date_from_s, field="date_from")
        bound_to = _parse_kuwait_iso_date(date_to_s, field="date_to")
        if bound_to is None:
            bound_to = today
        else:
            bound_to = min(bound_to, today)
        if bound_from is not None and bound_from > bound_to:
            raise ValueError("invalid_range")
        decoded_probe = decode_schedule_history_cursor(cursor_s)  # validate early
        _ = decoded_probe
    except ValueError as exc:
        code = str(exc) or "invalid_request"
        messages = {
            "invalid_cursor": "That page link is no longer valid. Refresh and try again.",
            "invalid_date_from": "That start date is not valid.",
            "invalid_date_to": "That end date is not valid.",
            "invalid_cursor_date": "That page link is no longer valid. Refresh and try again.",
            "invalid_range": "The start date must be on or before the end date.",
        }
        # normalize parse field names
        if code.startswith("invalid_") and code not in messages:
            if "date_from" in code:
                code = "invalid_date_from"
            elif "date_to" in code:
                code = "invalid_date_to"
            elif "cursor" in code:
                code = "invalid_cursor"
        raise HTTPException(
            status_code=400,
            detail={"error": code if code in messages else "invalid_request", "message": messages.get(code, "That request is not valid.")},
        ) from None

    entitled_shifts = False
    try:
        require_employee_app_feature(context, "shifts")
        entitled_shifts = True
    except HTTPException:
        entitled_shifts = False

    states: dict[str, str] = {"attendance": "ready", "shifts": "ready" if entitled_shifts else "disabled"}
    page: dict[str, Any] = {"records": [], "has_more": False, "next_cursor": None, "limit": page_limit}
    shift_map: dict[str, dict[str, Any]] = {}

    with db_connect() as conn:
        with conn.cursor() as cur:
            try:
                page = _employee_attendance_history_page(
                    cur,
                    company_code=company,
                    employee_key=key,
                    limit=page_limit,
                    cursor=cursor_s,
                    date_from=bound_from,
                    date_to=bound_to,
                )
            except Exception:
                logger.exception("schedule history attendance read failed employee=%s", key)
                states["attendance"] = "error"
                page = {"records": [], "has_more": False, "next_cursor": None, "limit": page_limit}
            if states["attendance"] == "ready" and entitled_shifts:
                try:
                    ids = [str(r.get("shift_id") or "") for r in (page.get("records") or []) if r.get("shift_id")]
                    shift_map = _employee_shifts_by_ids(
                        cur, company_code=company, employee_key=key, shift_ids=ids
                    )
                except Exception:
                    logger.exception("schedule history shift enrich failed employee=%s", key)
                    states["shifts"] = "error"
                    shift_map = {}
        conn.commit()

    items: list[dict[str, Any]] = []
    if states["attendance"] == "ready":
        for record in page.get("records") or []:
            sid = str(record.get("shift_id") or "")
            shift = shift_map.get(sid) if sid else None
            # Cancelled assignments are still canonical if present; omit only when missing.
            scheduled = _workday_shift_entry(shift) if shift else None
            items.append(
                {
                    "recorded": _workday_attendance_entry(record),
                    "scheduled": scheduled,
                }
            )

    return json_safe(
        {
            "ok": True,
            "locale": loc,
            "kind": "attendance_history",
            "authority": {
                "attendance": states["attendance"],
                "shifts": states["shifts"],
            },
            "records": items if states["attendance"] == "ready" else None,
            "count": len(items) if states["attendance"] == "ready" else None,
            "has_more": bool(page.get("has_more")) if states["attendance"] == "ready" else False,
            "next_cursor": page.get("next_cursor") if states["attendance"] == "ready" else None,
            "limit": int(page.get("limit") or page_limit),
            "ordering": "attendance_date_desc",
            "bounds": {
                "date_from": bound_from.isoformat() if bound_from else None,
                "date_to": bound_to.isoformat(),
            },
            "read_only": {
                "employee_clocking": False,
                "attendance_correction": False,
                "payroll_effect": False,
                "authority": "Schedule and attendance are recorded by your HR team.",
                "authority_ar": "يُسجّل فريق الموارد البشرية الجدول والحضور.",
            },
        }
    )


@app.get("/app/onboarding")
def app_onboarding(context: dict[str, Any] = Depends(employee_app_context)):
    company = context["company_code"]
    employee = context["employee"]
    key = context["employee_key"]
    feature = require_employee_app_feature(context, "onboarding")
    can_upload = "upload_document" in set(feature.get("actions") or ())
    import onboarding_completion_contract as _completion
    import onboarding_lifecycle_wave2a as _lc

    lifecycle_on = _lc.lifecycle_enabled(company_code=company, employee_key=key)
    # Bank ESS owns `bank_details`. Aligning before the checklist is read keeps the
    # employee app, HR drawer and HR queue on one state after every transition.
    try:
        import employee_bank_ess as _bank_sync

        with db_connect() as conn:
            with conn.cursor() as cur:
                _bank_sync.ensure_bank_ess_schema(cur)
                _bank_sync.reconcile_onboarding_bank_item(
                    cur, company_code=company, employee_key=key
                )
            conn.commit()
    except Exception:
        logger.exception("employee onboarding bank reconcile failed employee=%s", key)
    summary = employee_onboarding_summary(employee, company_code=company)
    index = employee_document_index(company, key)
    versions_by_type: dict[str, dict[str, Any]] = {}
    previously_completed = False
    with db_connect() as conn:
        with conn.cursor() as cur:
            if lifecycle_on:
                _lc.ensure_lifecycle_schema(cur)
            previously_completed = _completion.previously_completed_flag(
                cur, company_code=company, employee_key=key
            )
            try:
                import kuwait_pilot_document_journey as _kw_doc_journey
                import onboarding_civil_id_dual_side as _dual

                _kw_doc_journey.ensure_document_journey_schema(cur)
                if _dual.dual_side_enabled(company_code=company, employee_key=key):
                    _dual.ensure_dual_side_schema(cur)
                versions_by_type = _lc.load_latest_versions_by_type(
                    cur, company_code=company, employee_key=key
                )
                # Attach dual-side parts for Civil ID / canary lanes.
                for dtype, ver in list(versions_by_type.items()):
                    if not ver or not ver.get("version_id"):
                        continue
                    if str(ver.get("parts_schema") or "") == _dual.PARTS_SCHEMA or dtype in _dual.DUAL_SIDE_ITEMS:
                        ver["parts"] = _dual.load_parts(cur, str(ver["version_id"]))
            except Exception:
                logger.exception("onboarding version index failed employee=%s", key)
                versions_by_type = {}
        conn.commit()

    items = list(summary.get("items") or [])
    bank_ess = (employee_app_feature_contract_for_context(context).get("bank_ess") or {})
    bank_ess_eligible = bool(bank_ess.get("eligible"))
    projection = _lc.build_employee_projection(
        items,
        company_code=company,
        employee_key=key,
        file_index=index,
        versions_by_type=versions_by_type,
        can_upload=can_upload,
        lifecycle_on=lifecycle_on,
        previously_completed=previously_completed,
        bank_ess_eligible=bank_ess_eligible,
    )
    completion = projection.get("completion") or {}
    next_item = find_next_required_onboarding_item(key, company_code=company)
    migration = summary.get("onboarding_migration")
    if migration and migration.get("settled"):
        # Existing employees migrated as already onboarded / history / N/A: no fresh checklist.
        completion = summary.get("completion") or completion
        next_item = None
        return json_safe({
            "ok": True,
            "lifecycle_version": projection.get("lifecycle_version"),
            "completion": completion,
            "next_action": {"party": "none", "message_en": migration.get("employee_message"), "message_ar": migration.get("employee_message")},
            "status": employee.get("onboarding_status") or summary.get("status"),
            "required_total": 0,
            "received_count": 0,
            "pending_count": 0,
            "accepted_count": 0,
            "items": [],
            "groups": {"your_actions": [], "being_reviewed": [], "handled_by_others": [], "completed": []},
            "your_actions": [],
            "being_reviewed": [],
            "handled_by_others": [],
            "completed": [],
            "pending": [],
            "received": [],
            "next_item": None,
            "onboarding_migration": migration,
            "employee_message": migration.get("employee_message"),
            "bank_collection": summary.get("bank_collection"),
            "bank_ess": bank_ess,
            "can_upload": False,
        })
    return json_safe({
        "ok": True,
        "lifecycle_version": projection.get("lifecycle_version"),
        # Canonical contract state + the single next action, so the app never has
        # to infer completion from counts.
        "completion": completion,
        "next_action": completion.get("next_action"),
        "status": completion.get("legacy_onboarding_status") or summary.get("status"),
        "required_total": projection.get("required_total"),
        "received_count": projection.get("received_count"),
        "pending_count": projection.get("pending_count"),
        "accepted_count": projection.get("accepted_count"),
        "items": projection.get("items") or [],
        "groups": projection.get("groups") or {},
        "your_actions": projection.get("your_actions") or [],
        "being_reviewed": projection.get("being_reviewed") or [],
        "handled_by_others": projection.get("handled_by_others") or [],
        "completed": projection.get("completed") or [],
        # Legacy aliases for older clients during canary.
        "pending": projection.get("pending") or [],
        "received": projection.get("received") or [],
        "next_item": next_item,
        "onboarding_migration": migration,
        "bank_collection": summary.get("bank_collection"),
        # Same eligibility object as /app/me.features.bank / /app/bank gate.
        "bank_ess": bank_ess,
        "can_upload": can_upload,
    })


@app.get("/app/onboarding/items/{item_id}/versions")
def app_onboarding_item_versions(item_id: str, context: dict[str, Any] = Depends(employee_app_context)):
    """Append-only version history for one checklist document (self-scoped)."""
    company = context["company_code"]
    key = context["employee_key"]
    require_employee_app_feature(context, "onboarding")
    item = str(item_id or "").strip()
    if not item:
        raise HTTPException(status_code=404, detail={"error": "item_not_found", "message": "We couldn't find that checklist item."})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT oi.item_id, oi.document_type, oi.status, oi.rejection_reason
                FROM onboarding_items oi
                JOIN employees e ON e.employee_key = oi.employee_key
                WHERE oi.employee_key=%s AND oi.item_id=%s AND e.company_code=%s
                LIMIT 1
                """,
                (key, item, company),
            )
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail={"error": "item_not_found", "message": "We couldn't find that checklist item."})
            doc_type = str(row.get("document_type") or row.get("item_id") or item)
            import kuwait_pilot_document_journey as _kw_doc_journey

            ctype = _kw_doc_journey.canonical_compliance_type(doc_type)
            # Canary dual-side item keeps its own document_type lane (not remapped).
            if str(row.get("document_type") or row.get("item_id") or "") == "civil_id_dual_side_canary":
                ctype = "civil_id_dual_side_canary"
            _kw_doc_journey.ensure_document_journey_schema(cur)
            try:
                import onboarding_civil_id_dual_side as _dual

                if _dual.dual_side_applies(company_code=company, employee_key=key, item_id=item):
                    _dual.ensure_dual_side_schema(cur)
            except Exception:
                pass
            cur.execute(
                """
                SELECT version_id, version_no, file_id, filename, mime_type, review_status,
                       is_current, rejection_reason, created_at, reviewed_at, upload_source,
                       parts_schema, parts_complete
                FROM governed_document_versions
                WHERE company_code=%s AND employee_key=%s AND document_type=%s
                ORDER BY version_no DESC
                """,
                (company, key, ctype),
            )
            versions = []
            for v in cur.fetchall() or []:
                vd = dict(v)
                try:
                    import onboarding_civil_id_dual_side as _dual

                    if str(vd.get("parts_schema") or "") == _dual.PARTS_SCHEMA or item in _dual.DUAL_SIDE_ITEMS:
                        parts = _dual.load_parts(cur, str(vd.get("version_id") or ""))
                        vd["parts"] = _dual.parts_projection(parts)
                except Exception:
                    pass
                versions.append(vd)
        conn.commit()
    import onboarding_lifecycle_wave2a as _lc

    return json_safe({
        "ok": True,
        "item_id": item,
        "document_type": ctype,
        "status": _lc.normalize_status(row.get("status")) if _lc.lifecycle_enabled(company_code=company, employee_key=key) else row.get("status"),
        "rejection_reason": row.get("rejection_reason"),
        "versions": versions,
    })


