@app.get("/app/payslips/{payslip_id}/download")
def app_payslip_download(
    payslip_id: str,
    locale: str | None = Query(default=None),
    context: dict[str, Any] = Depends(employee_app_context),
):
    """Official PDF for released payslips with a sealed money authority. No public URLs."""
    company = context["company_code"]
    key = context["employee_key"]
    feature = require_employee_app_feature(context, "payslips")
    if not _payroll_w3.payroll_wave3_enabled_for_company(company):
        raise HTTPException(
            status_code=404,
            detail={"error": "feature_not_available", "message": "Payslips are not available for this company."},
        )
    if "download" not in set(feature.get("actions") or ()):
        raise HTTPException(
            status_code=403,
            detail={"error": "feature_action_denied", "message": "Download is not available."},
        )
    loc = "ar" if str(locale or "en").lower().startswith("ar") else "en"
    with db_connect() as conn:
        with conn.cursor() as cur:
            summary = _payroll_w3.employee_payslip_summary(
                cur,
                company_code=company,
                employee_key=key,
                payslip_id=payslip_id,
                locale=loc,
            )
            if not summary.get("ok"):
                raise HTTPException(
                    status_code=404,
                    detail={"error": "payslip_not_found", "message": "We couldn't find that payslip."},
                )
            payslip = summary.get("payslip") or {}
            if not payslip.get("official_document"):
                raise HTTPException(
                    status_code=422,
                    detail={
                        "error": "official_pdf_not_available",
                        "message": "An official PDF is not available for this payslip.",
                        "official_pdf_eligible": payslip.get("official_pdf_eligible"),
                        **_payroll_w3.honesty_payload(),
                    },
                )
            import payroll_payslip_official_pdf as _official_pdf

            rendered = _official_pdf.read_official_pdf(
                cur, company_code=company, payslip_id=payslip_id, locale=loc
            )
            if not rendered.get("ok") and rendered.get("error") == "official_pdf_not_generated":
                rendered = _official_pdf.ensure_official_pdf_for_payslip(
                    cur,
                    company_code=company,
                    payslip_id=payslip_id,
                    locale=loc,
                    company_name=company_display_name(company),
                    employee_name=str((context.get("employee") or {}).get("name") or key),
                    employee_id=key,
                )
                if rendered.get("ok"):
                    rendered = _official_pdf.read_official_pdf(
                        cur, company_code=company, payslip_id=payslip_id, locale=loc
                    )
            # Audit download
            if rendered.get("ok"):
                cur.execute(
                    """
                    INSERT INTO payroll_payslip_events (payslip_id, company_code, event_type, payload, created_by_phone)
                    VALUES (%s,%s,'official_pdf_downloaded',%s::jsonb,%s)
                    """,
                    (
                        payslip_id,
                        company,
                        json.dumps({"employee_key": key, "locale": loc, "sha256": rendered.get("sha256")}),
                        None,
                    ),
                )
        conn.commit()
    if not rendered.get("ok"):
        raise HTTPException(status_code=404, detail=json_safe(rendered))
    filename = str(rendered.get("filename") or f"payslip-{key}-{loc}.pdf")
    return Response(
        content=rendered.get("body") or b"",
        media_type="application/pdf",
        headers={
            "Content-Disposition": f'attachment; filename="{filename}"',
            "Cache-Control": "no-store",
            "X-Wathefni-Official-Document": "true",
            "X-Wathefni-Payslip-Id": str(payslip_id),
            "X-Content-Type-Options": "nosniff",
        },
    )


