@app.post("/app/leave/request")
def app_leave_request(body: EmployeeLeaveRequestBody, context: dict[str, Any] = Depends(employee_app_context)):
    company = context["company_code"]
    key = context["employee_key"]
    phone = context["phone"]
    require_employee_app_feature(context, "leave", action="request")
    leave_types = employee_app_leave_types(company)
    leave_type = normalize_text(body.leave_type or "").replace(" ", "_") or leave_types[0]
    if leave_type not in set(leave_types):
        raise HTTPException(
            status_code=422,
            detail={
                "error": "leave_type_not_available",
                "message": "Choose an available leave type.",
                "available_types": leave_types,
            },
        )
    token = set_active_company_code(company)
    try:
        action = {
            "subject_phone": phone,
            "start_date": body.start_date,
            "end_date": body.end_date,
            "leave_type": leave_type,
            "reason": (body.reason or "").strip() or None,
        }
        result = request_leave(
            action,
            company_code=company,
            created_by_phone=phone,
            origin_surface="employee_app",
        )
    finally:
        reset_active_company_code(token)
    if not result.get("ok"):
        # Self-scope guard: a self request can only ever resolve to the caller.
        raise HTTPException(status_code=400, detail={"error": result.get("error") or "leave_request_failed", "message": "We couldn't submit that leave request."})
    resolved_key = str(((result.get("employee") or {}).get("employee_key")) or "")
    if resolved_key and resolved_key != key:
        raise HTTPException(status_code=400, detail={"error": "leave_request_failed", "message": "We couldn't submit that leave request."})
    record_admin_audit(context, "employee_leave_requested", summary="Employee requested leave from the app.", target_type="employee", target=key, details={"leave_id": (result.get("leave") or {}).get("leave_id")})
    return json_safe({"ok": True, "leave": result.get("leave")})


@app.get("/app/leave/duration")
def app_leave_duration(
    start_date: str = Query(...),
    end_date: str = Query(...),
    leave_type: str | None = Query(default=None),
    context: dict[str, Any] = Depends(employee_app_context),
):
    """How many days a range would actually charge, before the employee submits.

    An employee picking 12–16 March is choosing five calendar days and asking for
    three. Only the server can answer that: the weekend is company policy and the
    public holidays are company data, neither of which the app has or should have.

    This holds no authority. It composes exactly the primitives the create path
    already uses — `get_leave_policy` for the rest days, `holiday_dates_for_range`
    for the calendar, `chargeable_leave_days` for the arithmetic — in the same
    order and with the same fallbacks, so it can only ever agree with what a
    submitted request would be charged. It writes nothing, reserves nothing, and
    decides nothing about eligibility: a range this endpoint prices may still be
    refused on submit for reasons it never looks at.

    Gated on the same `request` action as submitting, so company rest days and
    holidays are not readable by someone who cannot request leave.
    """
    company = context["company_code"]
    require_employee_app_feature(context, "leave", action="request")

    def _iso_date(value: str) -> date | None:
        try:
            return date.fromisoformat(str(value or "")[:10])
        except ValueError:
            return None

    start = _iso_date(start_date)
    end = _iso_date(end_date)
    # An unparseable or reversed range is the employee mid-edit, not an error
    # worth a red screen: report that there is no answer yet and show nothing.
    if not start or not end or end < start:
        return json_safe({"ok": True, "available": False, "reason": "invalid_range"})

    resolved_type = normalize_text(leave_type or "").replace(" ", "_") or None
    if resolved_type:
        available_types = set(employee_app_leave_types(company))
        if resolved_type not in available_types:
            return json_safe({"ok": True, "available": False, "reason": "leave_type_not_available"})

    try:
        policy = (get_leave_policy(company, resolved_type) if resolved_type else None) or {}
        weekend_days = policy.get("weekend_days") or ["fri", "sat"]
        holidays: set = set()
        excluded_holidays = False
        if policy.get("exclude_public_holidays", True) and _leave_policy_w2.leave_policy_wave2_enabled():
            try:
                with db_connect() as conn:
                    with conn.cursor() as cur:
                        holidays = _leave_policy_w2.holiday_dates_for_range(cur, company, start, end)
                excluded_holidays = True
            except Exception:
                # The holiday calendar is an exclusion, so failing to read it can
                # only overstate the charge. Say so rather than quietly pricing
                # a public holiday as a working day.
                holidays = set()
                excluded_holidays = False
        chargeable = chargeable_leave_days(
            start, end, weekend_days=weekend_days, holiday_dates=holidays
        )
    except Exception:
        return json_safe({"ok": True, "available": False, "reason": "not_computable"})

    return json_safe({
        "ok": True,
        "available": True,
        "start_date": start.isoformat(),
        "end_date": end.isoformat(),
        "leave_type": resolved_type,
        "chargeable_days": float(chargeable),
        "calendar_days": (end - start).days + 1,
        "basis": "working_days",
        "weekend_days": list(weekend_days),
        "excludes_public_holidays": excluded_holidays,
    })


@app.post("/app/leave/{leave_id}/cancel")
def app_leave_cancel(leave_id: str, context: dict[str, Any] = Depends(employee_app_context)):
    company = context["company_code"]
    key = context["employee_key"]
    phone = context["phone"]
    require_employee_app_feature(context, "leave", action="cancel")
    # Ownership guard FIRST: the leave must belong to the caller and be cancellable.
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM leave_requests WHERE leave_id=%s AND company_code=%s AND employee_key=%s AND status IN ('requested','approved') LIMIT 1",
                (leave_id, company, key),
            )
            owned = cur.fetchone() is not None
    if not owned:
        raise HTTPException(status_code=404, detail={"error": "leave_request_not_found", "message": "We couldn't find that leave request."})
    token = set_active_company_code(company)
    try:
        result = cancel_leave_request({"leave_id": leave_id, "subject_phone": phone}, company_code=company, created_by_phone=phone)
    finally:
        reset_active_company_code(token)
    if not result.get("ok"):
        raise HTTPException(status_code=400, detail={"error": result.get("error") or "leave_cancel_failed", "message": "We couldn't cancel that leave request."})
    record_admin_audit(context, "employee_leave_cancelled", summary="Employee cancelled leave from the app.", target_type="employee", target=key, details={"leave_id": leave_id})
    return json_safe({"ok": True, "leave": result.get("leave")})


def record_employee_upload_rejection_audit(
    context: dict[str, Any],
    *,
    item_id: str,
    rejection_code: str,
    declared_mime: str | None,
    extension: str,
    attempted_byte_size: int,
    event_id: str,
    capture_quality: dict[str, Any] | None = None,
    quality_issues: list[Any] | None = None,
    validation_decision: str | None = None,
    detected_item: str | None = None,
    validation_confidence: float | None = None,
) -> bool:
    """Best-effort metadata-only audit; validation remains fail-closed."""
    company = str(context.get("company_code") or "").upper()
    employee_key = str(context.get("employee_key") or "")
    employee = context.get("employee") if isinstance(context.get("employee"), dict) else {}
    safe_extension = re.sub(r"[^a-z0-9.]", "", str(extension or "").lower())[:16]
    safe_mime = str(declared_mime or "").split(";", 1)[0].strip().lower()[:120]
    payload: dict[str, Any] = {
        "event_id": str(event_id),
        "company_code": company,
        "employee_key": employee_key,
        "item_id": str(item_id)[:120],
        "actor_context": {
            "source": "employee_app",
            "route": "/app/onboarding/documents",
            "method": "POST",
        },
        "rejection_code": str(rejection_code)[:120],
        "declared_mime": safe_mime,
        "extension": safe_extension,
        "attempted_byte_size": max(0, int(attempted_byte_size)),
    }
    if isinstance(capture_quality, dict):
        # Persist metrics for crop/blur/glare audits (no image bytes).
        slim_cq: dict[str, Any] = {
            "status": capture_quality.get("status"),
            "reason": capture_quality.get("reason"),
            "signal_reason": capture_quality.get("signal_reason"),
            "engine": capture_quality.get("engine"),
            "metrics": capture_quality.get("metrics") if isinstance(capture_quality.get("metrics"), dict) else {},
        }
        payload["capture_quality"] = slim_cq
    if quality_issues:
        payload["quality_issues"] = [str(x)[:80] for x in list(quality_issues)[:12]]
    if validation_decision:
        payload["validation_decision"] = str(validation_decision)[:40]
    if detected_item:
        payload["detected_item"] = str(detected_item)[:80]
    if validation_confidence is not None:
        try:
            payload["validation_confidence"] = float(validation_confidence)
        except Exception:
            pass
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO action_results (
                        action_type, status, result, final_reply, company_code,
                        actor_user_id, actor_phone, actor_role
                    )
                    VALUES ('employee_document_upload_rejected','rejected',%s,
                            'Employee document upload rejected.',%s,%s,%s,'employee')
                    """,
                    (
                        Json(payload),
                        company,
                        f"employee:{employee_key}",
                        digits(employee.get("phone")) or None,
                    ),
                )
            conn.commit()
        return True
    except Exception:
        logger.error(
            "employee upload rejection audit unavailable event_id=%s category=document_validation",
            event_id,
            exc_info=True,
        )
        return False


def reject_employee_document_upload(
    context: dict[str, Any],
    *,
    item_id: str,
    rejection_code: str,
    declared_mime: str | None,
    extension: str,
    attempted_byte_size: int,
    status_code: int,
    api_error: str,
    message: str,
    detail_extra: dict[str, Any] | None = None,
) -> None:
    event_id = str(uuid.uuid4())
    extra = detail_extra if isinstance(detail_extra, dict) else {}
    cq = extra.get("capture_quality") if isinstance(extra.get("capture_quality"), dict) else None
    validation = extra.get("validation") if isinstance(extra.get("validation"), dict) else {}
    conf = validation.get("confidence")
    record_employee_upload_rejection_audit(
        context,
        item_id=item_id,
        rejection_code=rejection_code,
        declared_mime=declared_mime,
        extension=extension,
        attempted_byte_size=attempted_byte_size,
        event_id=event_id,
        capture_quality=cq,
        quality_issues=extra.get("quality_issues") if isinstance(extra.get("quality_issues"), list) else None,
        validation_decision=str(validation.get("decision") or "") or None,
        detected_item=str(extra.get("detected_item") or "") or None,
        validation_confidence=float(conf) if conf is not None else None,
    )
    detail: dict[str, Any] = {"error": api_error, "message": message}
    if isinstance(detail_extra, dict):
        for key, value in detail_extra.items():
            if key not in detail and value is not None:
                detail[key] = value
    raise HTTPException(status_code=status_code, detail=detail)


@app.post("/app/onboarding/documents")
async def app_onboarding_document_upload(
    file: UploadFile = File(...),
    item_id: str = Form(...),
    part: str | None = Form(None),
    context: dict[str, Any] = Depends(employee_app_context),
):
    company = context["company_code"]
    key = context["employee_key"]
    employee = context["employee"]
    require_employee_app_feature(context, "onboarding", action="upload_document")
    item = str(item_id or "").strip()
    if not item:
        raise HTTPException(status_code=400, detail={"error": "item_required", "message": "Pick the document you're uploading."})
    if onboarding_plaintext_bank_forbidden(item):
        raise HTTPException(
            status_code=400,
            detail={
                "error": "bank_via_ess_required",
                "message": "Bank and IBAN must be set through the encrypted Employee Self-Service bank workflow.",
                "bank_collection": "ess_encrypted",
            },
        )
    # Self-scope: the checklist item MUST already exist for THIS employee. This is
    # the ownership guard — an employee can only upload against their own items.
    import onboarding_lifecycle_wave2a as _lc
    import onboarding_civil_id_dual_side as _dual

    lifecycle_on = _lc.lifecycle_enabled(company_code=company, employee_key=key)
    dual_side = _dual.dual_side_applies(company_code=company, employee_key=key, item_id=item)
    dual_part: str | None = None
    dual_side_payload: dict[str, Any] | None = None
    if dual_side:
        try:
            dual_part = _dual.normalize_part(part)
        except _dual.DualSideError as exc:
            raise HTTPException(status_code=exc.status_code, detail=_dual.http_error_detail(exc)) from exc
    elif part:
        # Ignore stray part on non-dual items so older clients stay compatible.
        dual_part = None
    item_status_raw: str | None = None
    with db_connect() as conn:
        with conn.cursor() as cur:
            if lifecycle_on:
                _lc.ensure_lifecycle_schema(cur)
            cur.execute(
                """
                SELECT oi.status, oi.collection_mode, oi.item_type, oi.document_type, oi.authority
                FROM onboarding_items oi
                JOIN employees e ON e.employee_key = oi.employee_key
                WHERE oi.employee_key=%s AND oi.item_id=%s AND e.company_code=%s
                LIMIT 1
                """,
                (key, item, company),
            )
            existing_item = cur.fetchone()
            if not existing_item:
                raise HTTPException(status_code=404, detail={"error": "item_not_found", "message": "We couldn't find that document on your checklist."})
            item_status_raw = str(dict(existing_item).get("status") or "") or None
            if lifecycle_on:
                st = _lc.normalize_status(item_status_raw)
                if st in {_lc.STATE_ACCEPTED, _lc.STATE_WAIVED}:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "error": "item_already_accepted",
                            "message": "This document was already accepted. Contact HR if you need a correction.",
                        },
                    )
                if st == _lc.STATE_BLOCKED:
                    raise HTTPException(
                        status_code=409,
                        detail={"error": "upload_not_allowed", "message": "This item can't be uploaded right now."},
                    )
        conn.commit()

    filename = str(file.filename or "").strip() or "document"
    ext = Path(filename).suffix.lower()
    data = await file.read()

    # Wave 2A SHA contract:
    # 1) Same bytes + still pending_hr_review → idempotent replay (retry of same attempt).
    # 2) Same bytes after replacement_required (rejected version only) → NEW version.
    # 3) Under review with different bytes → 409 (no silent overwrite).
    if lifecycle_on and data:
        import hashlib as _hashlib
        import kuwait_pilot_document_journey as _kw_doc_journey

        digest = _hashlib.sha256(data).hexdigest()
        ctype = _kw_doc_journey.canonical_compliance_type(item)
        with db_connect() as conn:
            with conn.cursor() as cur:
                _kw_doc_journey.ensure_document_journey_schema(cur)
                cur.execute(
                    """
                    SELECT status FROM onboarding_items
                    WHERE employee_key=%s AND item_id=%s
                    LIMIT 1
                    """,
                    (key, item),
                )
                live = cur.fetchone() or {}
                st = _lc.normalize_status(dict(live).get("status") if live else item_status_raw)
                prior = _lc.find_idempotent_pending_version(
                    cur,
                    company_code=company,
                    employee_key=key,
                    document_type=ctype,
                    content_sha256=digest,
                )
                # Idempotent same-SHA short-circuit only while the item is already under review.
                # After reset-to-pending (or replacement), the same bytes must re-enter validation.
                if prior and st not in {_lc.STATE_SUBMITTED, _lc.STATE_PROCESSING}:
                    prior = None
                if prior:
                    cur.execute(
                        """
                        SELECT file_id FROM file_registry
                        WHERE company_code=%s AND subject_type='employee' AND subject_key=%s
                          AND content_sha256=%s
                        ORDER BY updated_at DESC NULLS LAST LIMIT 1
                        """,
                        (company, key, digest),
                    )
                    frow = cur.fetchone()
                    fid = str((frow or {}).get("file_id") or prior.get("file_id") or "") or None
                    _lc.apply_employee_document_submit(
                        cur,
                        employee_key=key,
                        item_id=item,
                        file_id=fid,
                        version_id=str(prior.get("version_id") or "") or None,
                        content_sha256=digest,
                    )
                    recompute_employee_onboarding_counts(cur, key)
                elif st in {_lc.STATE_SUBMITTED, _lc.STATE_PROCESSING}:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "error": "item_under_review",
                            "message": "This document is already with HR for review. You'll be able to replace it if they ask.",
                        },
                    )
                elif not _lc.upload_allowed_for_status(st):
                    raise HTTPException(
                        status_code=409,
                        detail={"error": "upload_not_allowed", "message": "This item can't be uploaded right now."},
                    )
                else:
                    prior = None
            conn.commit()
        if prior:
            return json_safe({
                "ok": True,
                "idempotent": True,
                "item_id": item,
                "file_id": str(prior.get("file_id") or "") or None,
                "version_id": str(prior.get("version_id") or "") or None,
                "status": _lc.STATE_PROCESSING,
                "storage_status": "stored",
            })
    elif lifecycle_on:
        # Empty body still must respect status gates.
        st = _lc.normalize_status(item_status_raw)
        if st in {_lc.STATE_SUBMITTED, _lc.STATE_PROCESSING}:
            raise HTTPException(
                status_code=409,
                detail={
                    "error": "item_under_review",
                    "message": "This document is already with HR for review. You'll be able to replace it if they ask.",
                },
            )
        if not _lc.upload_allowed_for_status(st):
            raise HTTPException(
                status_code=409,
                detail={"error": "upload_not_allowed", "message": "This item can't be uploaded right now."},
            )

    if ext not in _APP_DOC_EXTENSIONS:
        reject_employee_document_upload(
            context,
            item_id=item,
            rejection_code="unsupported_extension",
            declared_mime=file.content_type,
            extension=ext,
            attempted_byte_size=len(data),
            status_code=400,
            api_error="unsupported_file_type",
            message="Upload a PDF or an image.",
        )
    if not data:
        reject_employee_document_upload(
            context,
            item_id=item,
            rejection_code="empty_file",
            declared_mime=file.content_type,
            extension=ext,
            attempted_byte_size=0,
            status_code=400,
            api_error="empty_file",
            message="That file is empty.",
        )
    if len(data) > _APP_DOC_MAX_BYTES:
        reject_employee_document_upload(
            context,
            item_id=item,
            rejection_code="file_too_large",
            declared_mime=file.content_type,
            extension=ext,
            attempted_byte_size=len(data),
            status_code=400,
            api_error="file_too_large",
            message="Files must be 15 MB or smaller.",
        )

    try:
        mime_type = validate_employee_app_upload_type(
            extension=ext,
            declared_mime=file.content_type,
            data=data,
        )
    except EmployeeAppUploadTypeDenied as exc:
        reject_employee_document_upload(
            context,
            item_id=item,
            rejection_code=exc.reason,
            declared_mime=file.content_type,
            extension=ext,
            attempted_byte_size=len(data),
            status_code=415,
            api_error="mime_mismatch_or_invalid_content",
            message="The file content does not match an allowed PDF or image type.",
        )
    # The detector consumed only the in-memory bytes, never the submitted
    # filename. Rewind the upload defensively before reopening those validated
    # bytes into the server-owned temporary file used by storage.
    await file.seek(0)
    tmp_dir = tempfile.mkdtemp(prefix="app-doc-upload-")
    tmp_path = str(Path(tmp_dir) / safe_storage_name(filename))
    new_file_id: str | None = None
    operation: dict[str, Any] | None = None
    storage_result: dict[str, Any] | None = None
    validation_result: dict[str, Any] | None = None
    try:
        with open(tmp_path, "wb") as fh:
            fh.write(data)
        media = {"path": tmp_path, "type": mime_type}
        # Document Validation Parity (soft-gate canary): classify/verify before store.
        # Clear mismatches block with correction copy; uncertain → HR review after submit.
        # Wave 2A lifecycle transitions stay unchanged on allow/allow_uncertain.
        try:
            import onboarding_doc_validation_parity as _doc_val

            if _doc_val.validation_enabled(company_code=company, employee_key=key):
                locale_hdr = str(
                    (context.get("employee") or {}).get("preferred_locale")
                    or (context.get("access") or {}).get("locale")
                    or "en"
                )
                validation_result = _doc_val.evaluate_employee_upload(
                    employee=employee,
                    item_id=item,
                    media=media,
                    filename=filename,
                    size_bytes=len(data),
                    extension=ext,
                    locale=locale_hdr,
                    expected_part=dual_part,
                )
                if _doc_val.should_block(validation_result):
                    detail = _doc_val.http_error_detail(validation_result, locale=locale_hdr)
                    reject_employee_document_upload(
                        context,
                        item_id=item,
                        rejection_code=str(detail.get("reason") or "document_validation"),
                        declared_mime=file.content_type,
                        extension=ext,
                        attempted_byte_size=len(data),
                        status_code=422,
                        api_error=str(detail.get("error") or "document_validation_failed"),
                        message=str(detail.get("message") or "Please upload a clearer matching document."),
                        detail_extra=detail,
                    )
        except HTTPException:
            raise
        except Exception:
            logger.exception("onboarding doc validation parity failed; fail-open soft employee=%s item=%s", key, item)
            validation_result = None
        operation = prepare_document_storage_operation(employee=employee, item_id=item)
        config = document_storage_config(company)
        storage_result = store_onboarding_document(
            employee=employee,
            item_id=item,
            media=media,
            operation_trace=str(operation["trace_key"]),
        )
        update_document_storage_operation_after_store(
            str(operation["operation_id"]),
            storage_result=storage_result,
            config=config,
        )
        if not storage_result.get("ok") or str(storage_result.get("storage_status")) == "failed":
            raise HTTPException(status_code=502, detail={"error": "storage_failed", "message": "We couldn't store that document. Please try again."})
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT status
                    FROM document_storage_operations
                    WHERE operation_id=%s
                    FOR UPDATE
                    """,
                    (operation["operation_id"],),
                )
                operation_state = cur.fetchone()
                if not operation_state or operation_state.get("status") != "stored":
                    raise RuntimeError("document_storage_operation_not_stored")
                cur.execute(
                    """
                    UPDATE onboarding_items
                    SET value=%s,
                        local_path=COALESCE(%s, local_path),
                        drive_file_id=COALESCE(%s, drive_file_id),
                        drive_url=COALESCE(%s, drive_url),
                        storage_provider=%s, storage_object_key=%s, external_file_id=%s,
                        storage_url=%s, content_sha256=%s, mime_type=%s,
                        storage_status=%s, storage_error=%s,
                        stored_at=CASE WHEN %s IS NOT NULL THEN now() ELSE stored_at END,
                        updated_at=now()
                    WHERE employee_key=%s AND item_id=%s
                    """,
                    (
                        filename,
                        storage_result.get("metadata", {}).get("local_path") or tmp_path,
                        storage_result.get("drive_file_id"),
                        storage_result.get("drive_url"),
                        storage_result.get("provider"),
                        storage_result.get("storage_object_key"),
                        storage_result.get("external_file_id"),
                        storage_result.get("storage_url"),
                        storage_result.get("content_sha256"),
                        storage_result.get("mime_type"),
                        storage_result.get("storage_status"),
                        storage_result.get("storage_error"),
                        storage_result.get("provider"),
                        key,
                        item,
                    ),
                )
                extraction = extract_compliance_document_metadata(
                    document_type=item,
                    text=filename,
                    media=media,
                    company_code=company,
                    subject_key=key,
                    channel="ess_onboarding",
                ) or {
                    "extraction_status": "needs_review",
                    "extraction_error": "shared_extract_unavailable",
                    "authoritative": False,
                    "hr_confirmation_required": True,
                    "gpt_used": False,
                    "confidence": 0.0,
                }
                if validation_result:
                    import onboarding_doc_validation_parity as _doc_val

                    extraction = dict(extraction)
                    extraction["doc_validation"] = {
                        "gate": validation_result.get("gate"),
                        "decision": validation_result.get("decision"),
                        "reason": validation_result.get("reason"),
                        "hr_review_recommended": bool(
                            validation_result.get("hr_review_recommended")
                            or validation_result.get("decision") == "allow_uncertain"
                        ),
                        "route": validation_result.get("route"),
                        "gpt_used": False,
                    }
                    if validation_result.get("verification"):
                        extraction["verification"] = validation_result.get("verification")
                    if validation_result.get("identity_check"):
                        extraction["identity_check"] = validation_result.get("identity_check")
                    # Prefer richer extraction from identity path when present.
                    if isinstance(validation_result.get("extraction"), dict):
                        for k, v in validation_result["extraction"].items():
                            if k not in extraction or extraction.get(k) in (None, "", [], {}):
                                extraction[k] = v
                record_employee_document_receipt(
                    cur,
                    employee=employee,
                    item_id=item,
                    value=filename,
                    media=media,
                    storage_result=storage_result,
                    extraction=extraction,
                    skip_governed_version=bool(dual_side and dual_part),
                )
                cur.execute(
                    """
                    SELECT file_id FROM file_registry
                    WHERE company_code=%s AND subject_type='employee' AND subject_key=%s
                      AND file_kind='onboarding_document' AND content_sha256=%s
                    ORDER BY updated_at DESC NULLS LAST LIMIT 1
                    """,
                    (company, key, storage_result.get("content_sha256")),
                )
                row = cur.fetchone()
                new_file_id = str(row["file_id"]) if row else None
                dual_side_payload: dict[str, Any] | None = None
                # Lifecycle: dual-side attaches parts to one draft attempt; promote only when pair gate passes.
                if lifecycle_on and dual_side and dual_part:
                    try:
                        import kuwait_pilot_document_journey as _kw_doc_journey

                        doc_type_lane = str(
                            (existing_item and dict(existing_item).get("document_type"))
                            or item
                        )
                        # Keep disposable canary on its own governed lane.
                        if item == _dual.CANARY_ITEM:
                            doc_type_lane = _dual.CANARY_ITEM
                        else:
                            doc_type_lane = _kw_doc_journey.canonical_compliance_type(doc_type_lane)
                        st_now = _lc.normalize_status(item_status_raw)
                        force_new = st_now in {_lc.STATE_REPLACEMENT_REQUIRED, _lc.STATE_REJECTED}
                        # Only force a new attempt when no open draft exists (first side of a replacement).
                        open_draft = _dual.find_open_draft(
                            cur,
                            company_code=company,
                            employee_key=key,
                            document_type=doc_type_lane,
                        )
                        if force_new and open_draft:
                            force_new = False
                        elif force_new and not open_draft:
                            force_new = True
                        draft = _dual.ensure_draft_attempt(
                            cur,
                            sys.modules[__name__],
                            company_code=company,
                            employee_key=key,
                            document_type=doc_type_lane,
                            uploaded_by=digits(employee.get("phone")),
                            force_new=force_new,
                        )
                        side_meta = {
                            "detected_side": (validation_result or {}).get("detected_side"),
                            "hr_warning": bool(
                                (validation_result or {}).get("side_uncertain")
                                or (validation_result or {}).get("hr_review_recommended")
                            ),
                        }
                        if not side_meta["detected_side"] and isinstance(extraction, dict):
                            side_meta["detected_side"] = _dual._side_value(
                                extraction,
                                (validation_result or {}).get("verification")
                                if isinstance((validation_result or {}).get("verification"), dict)
                                else None,
                            )
                        attach = _dual.attach_part(
                            cur,
                            sys.modules[__name__],
                            version_id=str(draft["version_id"]),
                            part_key=dual_part,
                            file_id=new_file_id,
                            file_sha256=storage_result.get("content_sha256"),
                            filename=filename,
                            mime_type=storage_result.get("mime_type"),
                            detected_side=side_meta.get("detected_side"),
                            ocr_proposal=extraction if isinstance(extraction, dict) else {},
                            doc_validation=(
                                {
                                    "gate": (validation_result or {}).get("gate"),
                                    "decision": (validation_result or {}).get("decision"),
                                    "reason": (validation_result or {}).get("reason"),
                                    "hr_review_recommended": bool(
                                        (validation_result or {}).get("hr_review_recommended")
                                        or (validation_result or {}).get("decision") == "allow_uncertain"
                                    ),
                                }
                                if validation_result
                                else {}
                            ),
                            hr_warning=bool(side_meta.get("hr_warning")),
                            uploaded_by=digits(employee.get("phone")),
                        )
                        parts = attach["parts"]
                        proj = _dual.parts_projection(parts)
                        pair = _dual.evaluate_pair_gate(parts)
                        final_status = _lc.STATE_IN_PROGRESS
                        version_id = str(draft["version_id"])
                        if pair.get("ok"):
                            promoted = _dual.promote_draft_to_hr_review(
                                cur,
                                sys.modules[__name__],
                                version=draft,
                                parts=parts,
                                pair_result=pair,
                                actor_user_id=digits(employee.get("phone")),
                            )
                            version_id = str(promoted.get("version_id") or version_id)
                            _lc.apply_employee_document_submit(
                                cur,
                                employee_key=key,
                                item_id=item,
                                file_id=new_file_id,
                                version_id=version_id,
                                content_sha256=storage_result.get("content_sha256"),
                                validation_meta={
                                    "civil_id_parts": proj,
                                    "doc_validation": {
                                        "gate": (validation_result or {}).get("gate"),
                                        "decision": (validation_result or {}).get("decision"),
                                        "reason": (validation_result or {}).get("reason"),
                                        "hr_review_recommended": bool(
                                            pair.get("hr_review_recommended")
                                            or (validation_result or {}).get("hr_review_recommended")
                                            or (validation_result or {}).get("decision") == "allow_uncertain"
                                        ),
                                        "gpt_used": False,
                                    },
                                },
                            )
                            final_status = _lc.STATE_PROCESSING
                        else:
                            _lc.set_item_lifecycle(
                                cur,
                                employee_key=key,
                                item_id=item,
                                new_status=_lc.STATE_IN_PROGRESS,
                                clear_rejection=True,
                                meta_patch={
                                    "phase": "draft_parts",
                                    "civil_id_parts": proj,
                                    "last_submit_file_id": new_file_id,
                                    "last_submit_version_id": version_id,
                                    "last_submit_sha256": storage_result.get("content_sha256"),
                                    "awaiting": "employee_parts",
                                },
                            )
                        dual_side_payload = {
                            "part": dual_part,
                            "attempt_id": version_id,
                            "parts": proj,
                            "parts_complete": bool(pair.get("ok")),
                            "status": final_status,
                            "pair_gate": {
                                "ok": bool(pair.get("ok")),
                                "reason": pair.get("reason"),
                                "hr_review_recommended": bool(pair.get("hr_review_recommended")),
                                "hr_warnings": list(pair.get("hr_warnings") or []),
                            },
                        }
                    except _dual.DualSideError as exc:
                        raise HTTPException(
                            status_code=exc.status_code,
                            detail=_dual.http_error_detail(exc),
                        ) from exc
                elif lifecycle_on:
                    version_id = None
                    try:
                        import kuwait_pilot_document_journey as _kw_doc_journey

                        ctype = _kw_doc_journey.canonical_compliance_type(item)
                        cur.execute(
                            """
                            SELECT version_id FROM governed_document_versions
                            WHERE company_code=%s AND employee_key=%s AND document_type=%s
                            ORDER BY version_no DESC LIMIT 1
                            """,
                            (company, key, ctype),
                        )
                        vrow = cur.fetchone()
                        version_id = str(vrow["version_id"]) if vrow else None
                    except Exception:
                        version_id = None
                    _lc.apply_employee_document_submit(
                        cur,
                        employee_key=key,
                        item_id=item,
                        file_id=new_file_id,
                        version_id=version_id,
                        content_sha256=storage_result.get("content_sha256"),
                        validation_meta=(
                            {
                                "doc_validation": {
                                    "gate": validation_result.get("gate"),
                                    "decision": validation_result.get("decision"),
                                    "reason": validation_result.get("reason"),
                                    "hr_review_recommended": bool(
                                        validation_result.get("hr_review_recommended")
                                        or validation_result.get("decision") == "allow_uncertain"
                                    ),
                                    "gpt_used": False,
                                }
                            }
                            if validation_result
                            else None
                        ),
                    )
                else:
                    cur.execute(
                        "UPDATE onboarding_items SET status='received', updated_at=now() "
                        "WHERE employee_key=%s AND item_id=%s AND company_code=%s",
                        (key, item, company),
                    )
                recompute_employee_onboarding_counts(cur, key)
                cur.execute(
                    """
                    UPDATE document_storage_operations
                    SET status='canonical_committed', canonical_committed_at=now(),
                        failure_reason=NULL, next_attempt_at=NULL,
                        lease_owner=NULL, lease_expires_at=NULL, updated_at=now()
                    WHERE operation_id=%s AND status='stored'
                    """,
                    (operation["operation_id"],),
                )
                if cur.rowcount != 1:
                    raise RuntimeError("document_storage_operation_commit_conflict")
            conn.commit()
    except Exception as exc:
        if operation:
            try:
                operation_id = str(operation["operation_id"])
                current = document_storage_operation(operation_id)
                if current and current.get("status") == "prepared":
                    reconcile_document_storage_operation(operation_id, lease_owner=f"request-{os.getpid()}")
                elif current and current.get("status") not in _DOCUMENT_STORAGE_TERMINAL:
                    mark_document_storage_compensation_pending(operation_id, type(exc).__name__)
                    reconcile_document_storage_operation(operation_id, lease_owner=f"request-{os.getpid()}")
            except Exception:
                logger.error(
                    "immediate document compensation unavailable operation_id=%s",
                    operation.get("operation_id"),
                    exc_info=True,
                )
        raise
    finally:
        shutil.rmtree(tmp_dir, ignore_errors=True)

    record_admin_audit(context, "employee_document_uploaded", summary=f"Employee uploaded a document for item {item}.", target_type="employee", target=key, details={"item_id": item, "file_id": new_file_id, "mime_type": mime_type, "size_bytes": len(data), "part": dual_part})
    payload = {
        "ok": True,
        "item_id": item,
        "file_id": new_file_id,
        "storage_status": storage_result.get("storage_status"),
    }
    if dual_side_payload:
        payload.update(dual_side_payload)
    elif lifecycle_on:
        payload["status"] = _lc.STATE_PROCESSING
        payload["lifecycle_version"] = "2a"
    if lifecycle_on and "lifecycle_version" not in payload:
        payload["lifecycle_version"] = "2a"
    if validation_result:
        payload["validation"] = {
            "gate": validation_result.get("gate"),
            "decision": validation_result.get("decision"),
            "reason": validation_result.get("reason"),
            "hr_review_recommended": bool(
                validation_result.get("hr_review_recommended")
                or validation_result.get("decision") == "allow_uncertain"
            ),
            "message": validation_result.get("message"),
            "message_en": validation_result.get("message_en"),
            "message_ar": validation_result.get("message_ar"),
            "gpt_used": False,
        }
    return json_safe(payload)


# ---------------------------------------------------------------------------
# Bank ESS (employee self-service)
#
# The employee proposes; HR and payroll verify; only an applied request becomes
# payroll-effective. Employees never see their own full account number back
# (masked by default, no self-unmask), and no endpoint here returns ciphertext.
# ---------------------------------------------------------------------------
def _bank_evidence_path(storage_ref: str, *, company_code: str | None = None) -> Path:
    """Private on-disk location for bank evidence. Never web-served."""
    config = document_storage_config(company_code)
    root = Path(str(config.get("local_root") or "")) / "private" / "bank-evidence"
    safe = "/".join(safe_storage_name(part) for part in str(storage_ref).split("/") if part)
    return root / safe


def _store_bank_evidence_bytes(
    storage_ref: str, payload: bytes, *, company_code: str | None = None
) -> None:
    target = _bank_evidence_path(storage_ref, company_code=company_code)
    target.parent.mkdir(parents=True, exist_ok=True)
    with open(target, "wb") as fh:
        fh.write(payload)
    try:
        os.chmod(target, 0o600)
    except Exception:
        pass


def purge_bank_evidence_bytes(
    *,
    company_code: str | None = None,
    employee_keys: list[str] | None = None,
    limit: int = 500,
    include_orphans: bool = True,
) -> dict[str, Any]:
    """Destroy private evidence blobs for expired/soft-deleted rows.

    Deleting the row is not enough — the blob is the sensitive artifact, so the
    file is unlinked first and the row is only stamped purged once it is gone.
    `include_orphans` also removes blobs whose row no longer exists at all, so a
    row deleted outside this path cannot leave readable bank evidence on disk.
    """
    import employee_bank_ess as _bank

    unlinked = 0
    missing = 0
    orphans = 0
    purged_ids: list[str] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            _bank.ensure_bank_ess_schema(cur)
            rows = _bank.purgeable_evidence(
                cur, company_code=company_code, employee_keys=employee_keys, limit=limit
            )
            for row in rows:
                ref = str(row.get("storage_ref") or "")
                if not ref:
                    continue
                target = _bank_evidence_path(ref, company_code=row.get("company_code"))
                try:
                    if target.exists():
                        target.unlink()
                        unlinked += 1
                    else:
                        missing += 1
                except Exception:
                    logger.exception("bank evidence purge failed ref=%s", ref)
                    continue
                purged_ids.append(str(row.get("evidence_id")))
            stamped = _bank.mark_evidence_purged(cur, purged_ids)

            if include_orphans:
                cur.execute("SELECT storage_ref FROM employee_bank_evidence")
                known = {str(r["storage_ref"]) for r in (cur.fetchall() or [])}
                root = _bank_evidence_path("", company_code=company_code)
                for path in sorted(root.rglob("*")) if root.exists() else []:
                    if not path.is_file():
                        continue
                    try:
                        ref = str(path.relative_to(root))
                    except Exception:
                        continue
                    if ref in known:
                        continue
                    if employee_keys and not any(k in ref for k in employee_keys):
                        continue
                    try:
                        path.unlink()
                        orphans += 1
                    except Exception:
                        logger.exception("bank evidence orphan purge failed ref=%s", ref)
        conn.commit()
    return {
        "candidates": len(rows),
        "files_unlinked": unlinked,
        "files_already_absent": missing,
        "orphan_files_unlinked": orphans,
        "rows_stamped_purged": stamped,
    }


def _bank_ess_context(context: dict[str, Any]) -> tuple[str, str, dict[str, Any]]:
    company = context["company_code"]
    key = context["employee_key"]
    import employee_bank_ess as _bank
    import employee_selfservice_wave5 as _w5

    eligibility = _bank.bank_ess_eligibility(
        company,
        key,
        ess_v5_enabled=_w5.ess_v5_enabled(company),
    )
    if not eligibility.get("eligible"):
        reason = str(eligibility.get("reason") or "bank_ess_disabled")
        message = {
            "bank_ess_disabled": "Bank self-service is not available for your company yet.",
            "bank_ess_not_allowlisted": "Bank self-service is not enabled for your account yet.",
            "ess_v5_disabled": "Employee self-service is not available for your company yet.",
        }.get(reason, "Bank self-service is not available yet.")
        raise HTTPException(
            status_code=403,
            detail={"error": reason, "message": message},
        )
    # ESS context is pinned to this one employee: no cross-employee reach.
    ess_context = {
        "company_code": company,
        "actor_employee_key": key,
        "actor_user_id": None,
        "permissions": ["employees.ess.request"],
        "role": "employee",
    }
    return company, key, ess_context


