@app.post("/app/bank/requests")
def app_bank_submit(
    body: EmployeeBankSubmitBody,
    context: dict[str, Any] = Depends(employee_app_context),
):
    """Create a bank change request (draft or submitted for review)."""
    company, key, ess_context = _bank_ess_context(context)
    import employee_bank_ess as _bank
    import employee_selfservice_wave5 as _w5

    proposed = {
        f: getattr(body, f, None)
        for f in _bank.PROPOSABLE_FIELDS
        if getattr(body, f, None) not in (None, "")
    }
    if not proposed.get("iban") and not proposed.get("account_number"):
        raise HTTPException(
            status_code=422,
            detail={
                "error": "account_identifier_required",
                "message": "Enter your IBAN or account number.",
            },
        )
    result = _w5.create_request(
        sys.modules[__name__],
        ess_context,
        employee_key=key,
        request_type="bank_detail_change",
        proposed_values=proposed,
        idempotency_key=str(body.idempotency_key or ""),
        requester_kind="employee",
        comment=body.comment,
        draft=bool(body.draft),
    )
    request_id = str(((result or {}).get("request") or {}).get("request_id") or "")
    if request_id and body.evidence_ids:
        with db_connect() as conn:
            with conn.cursor() as cur:
                _bank.ensure_bank_ess_schema(cur)
                # Link (or re-link after withdraw/reject) private evidence to this
                # request. Never steal another employee's files.
                cur.execute(
                    """
                    UPDATE employee_bank_evidence e
                    SET request_id=%s
                    WHERE e.company_code=%s AND e.employee_key=%s
                      AND e.evidence_id::text = ANY(%s)
                      AND e.deleted_at IS NULL
                      AND (
                        e.request_id IS NULL
                        OR e.request_id = %s::uuid
                        OR NOT EXISTS (
                          SELECT 1 FROM employee_ess_requests r
                          WHERE r.request_id = e.request_id
                            AND r.employee_key = e.employee_key
                            AND r.state = ANY(%s)
                        )
                      )
                    """,
                    (
                        request_id,
                        company,
                        key,
                        [str(e) for e in body.evidence_ids],
                        request_id,
                        list(_bank.ACTIVE_REQUEST_STATES),
                    ),
                )
            conn.commit()
    with db_connect() as conn:
        with conn.cursor() as cur:
            status = _bank.employee_bank_status(
                cur, company_code=company, employee_key=key, can_unmask=False
            )
        conn.commit()
    return json_safe({
        "ok": True,
        "idempotent": bool(result.get("idempotent")),
        "replaced": bool(result.get("replaced")),
        "bank": status,
    })


