@app.post("/app/bank/evidence")
async def app_bank_evidence_upload(
    file: UploadFile = File(...),
    request_id: str | None = Form(None),
    context: dict[str, Any] = Depends(employee_app_context),
):
    """Upload supporting evidence (e.g. an IBAN letter) to private storage."""
    company, key, _ = _bank_ess_context(context)
    import employee_bank_ess as _bank

    allowed = {"application/pdf", "image/jpeg", "image/png", "image/heic", "image/webp"}
    mime = str(file.content_type or "").split(";")[0].strip().lower()
    if mime not in allowed:
        raise HTTPException(
            status_code=422,
            detail={
                "error": "unsupported_evidence_type",
                "message": "Upload a PDF or a photo of your bank letter.",
                "allowed": sorted(allowed),
            },
        )
    payload = await file.read()
    max_bytes = 10 * 1024 * 1024
    if len(payload) > max_bytes:
        raise HTTPException(
            status_code=413,
            detail={"error": "evidence_too_large", "message": "Keep the file under 10 MB."},
        )
    if not payload:
        raise HTTPException(
            status_code=422, detail={"error": "evidence_empty", "message": "The file is empty."}
        )
    digest = hashlib.sha256(payload).hexdigest()
    with db_connect() as conn:
        with conn.cursor() as cur:
            _bank.ensure_bank_ess_schema(cur)
            record = _bank.register_evidence(
                cur,
                company_code=company,
                employee_key=key,
                request_id=request_id or None,
                filename=safe_storage_name(file.filename, "bank-evidence"),
                mime_type=mime,
                byte_size=len(payload),
                content_sha256=digest,
                uploaded_by_employee_key=key,
            )
        conn.commit()
    storage_ref = str(record.get("storage_ref") or "")
    try:
        _store_bank_evidence_bytes(storage_ref, payload, company_code=company)
    except Exception:
        logger.exception("bank evidence storage write failed ref=%s", storage_ref)
        raise HTTPException(
            status_code=503,
            detail={
                "error": "evidence_storage_unavailable",
                "message": "We couldn't save that file. Please try again.",
            },
        )

    extraction_out: dict[str, Any] = {
        "status": "disabled",
        "needs_manual_fallback": True,
        "authoritative": False,
        "proposed": {},
    }
    if _bank.bank_ocr_enabled(company_code=company):
        try:
            path = _bank_evidence_path(storage_ref, company_code=company)
            raw = _bank.extract_bank_certificate_from_path(
                path=str(path),
                company_code=company,
                employee_key=key,
                mime_type=mime,
            )
            with db_connect() as conn:
                with conn.cursor() as cur:
                    _bank.ensure_bank_ess_schema(cur)
                    stored = _bank.store_evidence_extraction(
                        cur,
                        company_code=company,
                        employee_key=key,
                        evidence_id=str(record.get("evidence_id")),
                        extraction=raw,
                    )
                conn.commit()
            extraction_out = _bank.sanitize_bank_extraction(raw)
            extraction_out["evidence_id"] = stored.get("evidence_id") or record.get("evidence_id")
        except Exception:
            logger.exception("bank certificate OCR failed evidence=%s", record.get("evidence_id"))
            extraction_out = {
                "status": "failed",
                "needs_manual_fallback": True,
                "authoritative": False,
                "proposed": {},
                "unreadable_reason": "extraction_failed",
                "warnings": ["extraction_failed"],
            }
            try:
                with db_connect() as conn:
                    with conn.cursor() as cur:
                        _bank.ensure_bank_ess_schema(cur)
                        _bank.store_evidence_extraction(
                            cur,
                            company_code=company,
                            employee_key=key,
                            evidence_id=str(record.get("evidence_id")),
                            extraction=extraction_out,
                        )
                    conn.commit()
            except Exception:
                pass

    # storage_ref is deliberately not returned: evidence is fetched through an
    # authorized endpoint, never a shareable URL.
    return json_safe(
        {
            "ok": True,
            "evidence_id": record.get("evidence_id"),
            "filename": record.get("filename"),
            "retention_until": record.get("retention_until"),
            "extraction": extraction_out,
            # Convenience for mobile confirm/correct prefill.
            "proposed_fields": extraction_out.get("proposed") or {},
            "needs_manual_fallback": bool(extraction_out.get("needs_manual_fallback")),
        }
    )


def _load_bank_evidence_row(
    *, company_code: str, employee_key: str, evidence_id: str
) -> dict[str, Any]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT evidence_id, storage_ref, filename, mime_type, deleted_at
                FROM employee_bank_evidence
                WHERE company_code=%s AND employee_key=%s AND evidence_id=%s
                LIMIT 1
                """,
                (str(company_code).upper(), employee_key, evidence_id),
            )
            row = cur.fetchone()
        conn.commit()
    if not row or dict(row).get("deleted_at"):
        raise HTTPException(
            status_code=404,
            detail={"error": "evidence_not_found", "message": "That file is no longer available."},
        )
    return dict(row)


def _bank_evidence_response(row: dict[str, Any], *, company_code: str) -> FileResponse:
    path = _bank_evidence_path(str(row.get("storage_ref") or ""), company_code=company_code)
    if not path.exists():
        raise HTTPException(
            status_code=404,
            detail={"error": "evidence_missing", "message": "That file is no longer available."},
        )
    return FileResponse(
        str(path),
        media_type=str(row.get("mime_type") or "application/octet-stream"),
        filename=str(row.get("filename") or "bank-evidence"),
        headers={"Cache-Control": "no-store, private"},
    )


@app.get("/app/bank/evidence/{evidence_id}")
def app_bank_evidence_download(
    evidence_id: str,
    context: dict[str, Any] = Depends(employee_app_context),
):
    """Self-scoped evidence fetch. No shareable URL is ever issued."""
    company, key, _ = _bank_ess_context(context)
    row = _load_bank_evidence_row(
        company_code=company, employee_key=key, evidence_id=evidence_id
    )
    return _bank_evidence_response(row, company_code=company)


@app.post("/app/push/register")
def app_push_register(body: EmployeePushRegisterBody, context: dict[str, Any] = Depends(employee_app_context)):
    company = context["company_code"]
    key = context["employee_key"]
    require_employee_app_feature(context, "settings", action="manage_push")
    token = str(body.push_token or "").strip()
    if not token:
        raise HTTPException(status_code=400, detail={"error": "push_token_required", "message": "A push token is required."})
    platform = (body.platform or "").strip().lower()[:20] or None
    device_id = (body.device_id or "").strip()[:128] or None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO employee_push_tokens (company_code, employee_key, push_token, platform, device_id, active)
                VALUES (%s,%s,%s,%s,%s,TRUE)
                ON CONFLICT (company_code, push_token) DO UPDATE
                SET employee_key=EXCLUDED.employee_key, platform=EXCLUDED.platform,
                    device_id=EXCLUDED.device_id, active=TRUE, last_error=NULL,
                    last_seen_at=now(), updated_at=now()
                """,
                (company, key, token, platform, device_id),
            )
        conn.commit()
    return {"ok": True}


@app.post("/app/push/unregister")
def app_push_unregister(body: EmployeePushUnregisterBody, context: dict[str, Any] = Depends(employee_app_context)):
    company = context["company_code"]
    key = context["employee_key"]
    token = str(body.push_token or "").strip()
    with db_connect() as conn:
        with conn.cursor() as cur:
            if token:
                cur.execute(
                    "UPDATE employee_push_tokens SET active=FALSE, updated_at=now() WHERE company_code=%s AND employee_key=%s AND push_token=%s",
                    (company, key, token),
                )
            else:
                cur.execute(
                    "UPDATE employee_push_tokens SET active=FALSE, updated_at=now() WHERE company_code=%s AND employee_key=%s AND active IS TRUE",
                    (company, key),
                )
        conn.commit()
    return {"ok": True}


def create_employee_account_deletion_request(
    *,
    company_code: str,
    employee_key: str,
    employee: dict[str, Any],
    reason: str | None,
    channel: Literal["employee_app", "public_web"],
    audit_context: dict[str, Any],
) -> dict[str, Any]:
    """Canonical employee-account deletion-request write authority.

    Both the authenticated app and the public store-policy web resource converge
    here. This creates an idempotent HR task; it never destroys statutory
    employment records, consumes an activation code, or creates an app session.
    """
    company = str(company_code or "").strip().upper()
    key = str(employee_key or "").strip()
    clean_reason = str(reason or "").strip()[:500] or None
    created = False
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT pg_advisory_xact_lock(hashtextextended(%s, 0))",
                (f"account-deletion:{company}:{key}",),
            )
            cur.execute(
                """
                SELECT task_id
                  FROM hr_tasks
                 WHERE company_code=%s
                   AND employee_key=%s
                   AND task_type='account_deletion_request'
                   AND status='open'
                 ORDER BY created_at DESC
                 LIMIT 1
                """,
                (company, key),
            )
            row = cur.fetchone()
            if not row:
                cur.execute(
                    """
                    INSERT INTO hr_tasks
                      (company_code, employee_key, task_type, source, title, detail, priority, metadata)
                    VALUES (%s,%s,'account_deletion_request','employee_app',%s,%s,'normal',%s)
                    RETURNING task_id
                    """,
                    (
                        company,
                        key,
                        f"Account deletion requested by {employee.get('name') or 'an employee'}",
                        clean_reason or (
                            "Employee requested account/data deletion from the public OctoHR web form."
                            if channel == "public_web"
                            else "Employee requested account/data deletion from the mobile app."
                        ),
                        Json({"requested_at": now_iso(), "channel": channel}),
                    ),
                )
                row = cur.fetchone()
                created = True
        conn.commit()
    if created:
        record_admin_audit(
            audit_context,
            "employee_account_deletion_requested",
            summary="Employee requested account deletion.",
            target_type="employee",
            target=key,
            details={"reason_provided": bool(clean_reason), "channel": channel},
        )
    return {
        "ok": True,
        "idempotent": not created,
        "task_id": str(row["task_id"]) if row else None,
        "message": "Your request has been sent to your HR team.",
    }


@app.post("/app/account/request-deletion")
def app_account_request_deletion(body: EmployeeDeletionRequestBody, context: dict[str, Any] = Depends(employee_app_context)):
    # Store policy requirement: an in-app account-deletion path. The employer is the
    # data controller, so this raises a visible HR task for handling rather than
    # self-destructing employment records.
    require_employee_app_feature(context, "settings", action="request_deletion")
    return create_employee_account_deletion_request(
        company_code=context["company_code"],
        employee_key=context["employee_key"],
        employee=context["employee"],
        reason=body.reason,
        channel="employee_app",
        audit_context=context,
    )


_PUBLIC_ACCOUNT_DELETION_ORIGINS = {
    "https://octo-hr.com",
    "https://www.octo-hr.com",
}
_PUBLIC_ACCOUNT_DELETION_GENERIC = {
    "ok": True,
    "message": (
        "If the details match an OctoHR employee account, the deletion request "
        "has been sent to the employer's HR team."
    ),
}


def _public_account_deletion_cors(request: Request) -> dict[str, str]:
    origin = str(request.headers.get("origin") or "").strip()
    if origin and origin not in _PUBLIC_ACCOUNT_DELETION_ORIGINS:
        raise HTTPException(
            status_code=403,
            detail={"error": "origin_not_allowed", "message": "This request origin is not allowed."},
        )
    headers = {
        "Cache-Control": "no-store",
        "Vary": "Origin",
    }
    if origin:
        headers.update(
            {
                "Access-Control-Allow-Origin": origin,
                "Access-Control-Allow-Methods": "POST, OPTIONS",
                "Access-Control-Allow-Headers": "Content-Type",
            }
        )
    return headers


@app.options("/public/account-deletion/request")
def public_account_deletion_preflight(http_request: Request):
    return Response(status_code=204, headers=_public_account_deletion_cors(http_request))


@app.post("/public/account-deletion/request")
def public_account_deletion_request(body: PublicEmployeeDeletionRequestBody, http_request: Request):
    """Public, tenant-pinned adapter onto the canonical deletion-request task.

    Responses deliberately do not reveal whether a company, email, phone, or
    employee account exists. A matching Employee-app account creates the
    same HR task as the in-app action; a non-match returns identical public copy.
    """
    # Keep this adapter self-contained when it is composed into the production
    # compatibility app, whose import prelude intentionally differs from the
    # tracked authority module.
    from fastapi.responses import JSONResponse as PublicDeleteJSONResponse
    import security_rate_limit as public_delete_rate_limit
    import sys as public_delete_sys

    headers = _public_account_deletion_cors(http_request)
    if body.confirmed is not True:
        raise HTTPException(
            status_code=400,
            detail={"error": "confirmation_required", "message": "Please confirm the deletion request."},
            headers=headers,
        )
    raw_company = str(body.company_code or "").strip().upper()
    company = raw_company if re.fullmatch(r"[A-Z0-9_-]{2,64}", raw_company) else ""
    identity = str(body.identity or "").strip().lower()
    identity_phone = digits(identity)
    identity_digest = public_delete_rate_limit.principal_digest(f"{company}|{identity}")
    public_delete_rate_limit.consume(
        public_delete_sys.modules[__name__],
        "public_account_deletion",
        route="/public/account-deletion/request",
        dimensions={
            "source": public_delete_rate_limit.client_source(http_request),
            "identity": identity_digest,
        },
        company_code=company or None,
    )

    employee: dict[str, Any] | None = None
    if company and ("@" in identity or identity_phone):
        try:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    # Deletion intake must remain available after employment,
                    # company suspension, or Employee-module disablement. Those
                    # lifecycle gates govern product access, not privacy rights.
                    cur.execute("SELECT 1 FROM companies WHERE company_code=%s LIMIT 1", (company,))
                    if cur.fetchone():
                        cur.execute(
                            """
                            SELECT *
                              FROM employees
                             WHERE company_code=%s
                               AND (
                                 lower(trim(coalesce(email, '')))=%s
                                 OR (%s <> '' AND regexp_replace(coalesce(phone, ''), '[^0-9]', '', 'g')=%s)
                               )
                             ORDER BY employee_key
                             LIMIT 2
                            """,
                            (company, identity, identity_phone, identity_phone),
                        )
                        matches = [dict(row) for row in cur.fetchall()]
                        if len(matches) == 1:
                            candidate = matches[0]
                            cur.execute(
                                """
                                SELECT EXISTS (
                                  SELECT 1 FROM employee_app_invites
                                   WHERE company_code=%s AND employee_key=%s
                                  UNION ALL
                                  SELECT 1 FROM employee_sessions
                                   WHERE company_code=%s AND employee_key=%s
                                ) AS has_account
                                """,
                                (company, candidate["employee_key"], company, candidate["employee_key"]),
                            )
                            if bool((cur.fetchone() or {}).get("has_account")):
                                employee = candidate
        except HTTPException:
            raise
        except Exception as exc:
            logger.error("public account deletion lookup unavailable: %s", type(exc).__name__)
            raise HTTPException(
                status_code=503,
                detail={
                    "error": "account_deletion_temporarily_unavailable",
                    "message": "The deletion request service is temporarily unavailable. Please try again.",
                },
                headers=headers,
            ) from exc

    if employee:
        try:
            create_employee_account_deletion_request(
                company_code=company,
                employee_key=str(employee.get("employee_key") or ""),
                employee=employee,
                reason=body.reason,
                channel="public_web",
                audit_context={
                    "company_code": company,
                    "actor_role": "employee_public_request",
                    "requested_by": "public_account_deletion_form",
                },
            )
        except Exception as exc:
            logger.error("public account deletion task creation unavailable: %s", type(exc).__name__)
            raise HTTPException(
                status_code=503,
                detail={
                    "error": "account_deletion_temporarily_unavailable",
                    "message": "The deletion request service is temporarily unavailable. Please try again.",
                },
                headers=headers,
            ) from exc
    return PublicDeleteJSONResponse(_PUBLIC_ACCOUNT_DELETION_GENERIC, headers=headers)


# --- Dashboard side: HR provisions an app invite ----------------------------

class DashboardEmployeeAppInviteRequest(BaseModel):
    delivery_mode: Literal["hr_task_only"]
    idempotency_key: str = Field(min_length=8, max_length=128)
    reason: str = Field(min_length=3, max_length=500)
    supersede_invite_id: str | None = Field(default=None, max_length=64)


def create_hr_task_only_employee_app_invite(
    context: dict[str, Any],
    employee_key: str,
    request: DashboardEmployeeAppInviteRequest,
) -> tuple[dict[str, Any], str]:
    """Create one invite + metadata-only HR task + audit in one transaction.

    The raw code exists only in this stack frame and the caller's response.
    Replaying an idempotency key never rediscloses it.
    """
    company = str(context.get("company_code") or "").upper()
    requester_user_id = str(context.get("actor_user_id") or "").strip()
    idempotency_key = request.idempotency_key.strip()
    reason_text = request.reason.strip()
    requested_supersede = str(request.supersede_invite_id or "").strip()
    invite_id = str(uuid.uuid4())
    code = _app_code_generate()
    expires = now_utc() + timedelta(hours=_EMPLOYEE_APP_INVITE_TTL_HOURS)

    with db_connect() as conn:
        try:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT * FROM dashboard_users WHERE company_code=%s AND user_id=%s FOR SHARE",
                    (company, requester_user_id),
                )
                requester = dict(cur.fetchone() or {})
                permissions = dashboard_effective_permissions_for_user(requester, cur=cur) if requester else []
                if (
                    not _normal_dashboard_operator(requester)
                    or "employees.manage" not in permissions
                    or "onboarding.manage" not in permissions
                ):
                    raise HTTPException(status_code=403, detail={"error": "permission_denied", "message": "You do not have access to do that."})

                allowed, denied_reason = _employee_app_company_gate(cur, company)
                if not allowed:
                    raise EmployeeAppInviteDenied(denied_reason or "company_not_eligible")
                cur.execute(
                    "SELECT * FROM employees WHERE company_code=%s AND employee_key=%s FOR UPDATE",
                    (company, str(employee_key)),
                )
                employee = dict(cur.fetchone() or {})
                if not employee:
                    raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})
                phone = digits(employee.get("phone"))
                if not phone:
                    raise HTTPException(status_code=400, detail={"error": "employee_phone_missing", "message": "This employee needs a phone number before they can be invited."})
                if not _employee_app_employee_eligible(employee):
                    raise EmployeeAppInviteDenied("employee_not_eligible")
                try:
                    import employee_app_access as _access

                    _access.ensure_access_schema(cur)
                    cur.execute(
                        "SELECT app_access_enabled FROM employees WHERE company_code=%s AND employee_key=%s LIMIT 1",
                        (company, str(employee_key)),
                    )
                    flag_row = cur.fetchone()
                    if flag_row:
                        employee["app_access_enabled"] = bool(dict(flag_row).get("app_access_enabled"))
                    eligible, reason = _access.is_employee_app_access_eligible(
                        sys.modules[__name__], company_code=company, employee=employee
                    )
                    if not eligible:
                        raise EmployeeAppInviteDenied(reason or "employee_app_access_not_enabled")
                except EmployeeAppInviteDenied:
                    raise
                except Exception:
                    logger.exception("handoff access gate failed")
                    raise EmployeeAppInviteDenied("employee_app_access_not_enabled")

                cur.execute(
                    "SELECT pg_advisory_xact_lock(hashtextextended(%s, 0))",
                    (f"employee-app-handoff:{company}:{employee_key}",),
                )
                cur.execute(
                    "SELECT invite_id FROM employee_app_invites WHERE company_code=%s AND idempotency_key=%s LIMIT 1",
                    (company, idempotency_key),
                )
                disclosed = cur.fetchone()
                if disclosed:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "error": "activation_code_already_disclosed",
                            "message": "This response cannot be replayed. Supersede the invite and issue a new code if the original response was lost.",
                            "invite_id": str(disclosed["invite_id"]),
                        },
                    )
                cur.execute(
                    """
                    SELECT invite_id
                    FROM employee_app_invites
                    WHERE company_code=%s AND employee_key=%s AND status='pending'
                    ORDER BY created_at DESC
                    FOR UPDATE
                    """,
                    (company, str(employee_key)),
                )
                pending_ids = [str(row["invite_id"]) for row in cur.fetchall()]
                if pending_ids and requested_supersede not in pending_ids:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "error": "pending_activation_invite_exists",
                            "message": "A pending activation handoff already exists. Explicitly supersede it to issue a new code.",
                            "pending_invite_id": pending_ids[0],
                        },
                    )
                if requested_supersede and requested_supersede not in pending_ids:
                    raise HTTPException(
                        status_code=409,
                        detail={"error": "supersede_invite_mismatch", "message": "The invite selected for supersession is no longer pending."},
                    )
                if requested_supersede:
                    cur.execute(
                        """
                        UPDATE employee_app_invites
                        SET status='superseded', idempotency_key=NULL, superseded_by_invite_id=%s, updated_at=now()
                        WHERE company_code=%s AND employee_key=%s AND invite_id=%s AND status='pending'
                        """,
                        (invite_id, company, str(employee_key), requested_supersede),
                    )

                cur.execute(
                    """
                    INSERT INTO employee_app_invites
                      (invite_id, company_code, employee_key, phone, code_hash, status,
                       created_by_phone, created_by_user_id, expires_at, last_sent_at,
                       delivery_mode, idempotency_key, code_disclosed_at, metadata)
                    VALUES (%s,%s,%s,%s,%s,'pending',%s,%s,%s,now(),
                            'hr_task_only',%s,now(),%s)
                    RETURNING *
                    """,
                    (
                        invite_id,
                        company,
                        str(employee_key),
                        phone,
                        _app_code_hash(company, phone, code),
                        digits(context.get("hr_phone")) or None,
                        requester_user_id,
                        expires,
                        idempotency_key,
                        Json({"delivery_mode": "hr_task_only", "external_delivery": False}),
                    ),
                )
                invite = dict(cur.fetchone())
                cur.execute(
                    """
                    INSERT INTO hr_tasks
                      (company_code, employee_key, task_type, source, title, detail,
                       status, priority, related_invite_id, assigned_to_user_id, metadata)
                    VALUES (%s,%s,'app_activation_handoff','employee_app',
                            'Complete secure Employee App activation handoff',
                            'Use the one-time code shown only in the secure dashboard response. If it was lost, supersede this invite and reissue.',
                            'open','high',%s,%s,%s)
                    RETURNING task_id
                    """,
                    (
                        company,
                        str(employee_key),
                        invite_id,
                        requester_user_id,
                        Json({
                            "invite_id": invite_id,
                            "delivery_mode": "hr_task_only",
                            "contains_activation_secret": False,
                        }),
                    ),
                )
                task_id = str(cur.fetchone()["task_id"])
                cur.execute(
                    "UPDATE employee_app_invites SET handoff_task_id=%s WHERE invite_id=%s",
                    (task_id, invite_id),
                )
                audit = write_admin_audit(
                    cur,
                    _permission_operator_context(requester, permissions),
                    "app_invite_created_hr_task_only",
                    summary="Created a secure HR-only Employee App activation handoff.",
                    target_type="employee",
                    target=str(employee_key),
                    details={
                        "invite_id": invite_id,
                        "task_id": task_id,
                        "delivery_mode": "hr_task_only",
                        "external_delivery": False,
                        "reason": reason_text,
                        "superseded_invite_id": requested_supersede or None,
                    },
                )
            conn.commit()
        except Exception:
            conn.rollback()
            raise
    return {
        "invite_id": invite_id,
        "task_id": task_id,
        "audit_result_id": str(audit["result_id"]),
        "employee_key": str(employee_key),
        "expires_at": invite["expires_at"],
        "delivery_mode": "hr_task_only",
    }, code


@app.post("/dashboard/posthire/employees/{employee_key}/app-invite")
def dashboard_posthire_app_invite(
    employee_key: str,
    request: DashboardEmployeeAppInviteRequest,
    response: Response,
    context: dict[str, Any] = Depends(dashboard_context),
):
    require_entitlement(context, "onboarding", "onboarding.manage")
    require_employee_roster_admin(context, "employees.manage")
    company = context["company_code"]
    require_active_company(company)
    if not employee_app_enabled():
        raise HTTPException(status_code=403, detail={"error": "feature_disabled", "message": "The employee app is not enabled."})
    if not company_has_module(company, "employee_app"):
        raise HTTPException(status_code=403, detail={"error": "employee_app_not_enabled_for_company", "message": "The employee app module is not enabled for your company."})
    employee = find_employee_by_key(employee_key, company_code=company)
    if not employee:
        raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})
    viewer_phone = context.get("hr_phone")
    if not context_manager_allows_employee(context, employee, company_code=company):
        raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})
    if not digits(employee.get("phone")):
        raise HTTPException(status_code=400, detail={"error": "employee_phone_missing", "message": "This employee needs a phone number before they can be invited."})
    try:
        handoff, code = create_hr_task_only_employee_app_invite(context, employee_key, request)
    except EmployeeAppInviteDenied as exc:
        if exc.reason.startswith("company_"):
            raise HTTPException(status_code=403, detail={"error": exc.reason, "message": "This company workspace is not active."}) from None
        raise HTTPException(status_code=403, detail={"error": "employee_app_invite_denied", "message": "This employee cannot be invited right now."}) from None
    response.headers["Cache-Control"] = "no-store"
    response.headers["Pragma"] = "no-cache"
    return json_safe({
        "ok": True,
        **handoff,
        "activation_code": code,
    })


def _dashboard_employee_app_access_summary(company: str, employee_key: str) -> dict[str, Any]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT created_at, last_seen_at, metadata
                FROM employee_sessions
                WHERE company_code=%s AND employee_key=%s AND status='active' AND expires_at > now()
                ORDER BY last_seen_at DESC NULLS LAST
                LIMIT 1
                """,
                (company, str(employee_key)),
            )
            row = cur.fetchone()
    if not row:
        return {"active": False, "platform": None, "activated_at": None, "last_active_at": None}
    sess = dict(row)
    return {
        "active": True,
        "platform": _employee_session_platform(sess.get("metadata")),
        "activated_at": sess.get("created_at"),
        "last_active_at": sess.get("last_seen_at"),
    }


