class DashboardEmployeeAppAccessPolicyPatch(BaseModel):
    module_enabled: bool | None = None
    access_mode: Literal["all", "selected"] | None = None
    selected_departments: list[str] | None = None
    sync_invites: bool = False


@app.patch("/dashboard/posthire/app-access/policy")
def dashboard_posthire_app_access_policy_patch(
    body: DashboardEmployeeAppAccessPolicyPatch,
    context: dict[str, Any] = Depends(dashboard_context),
):
    require_employee_roster_admin(context, "employees.manage")
    require_active_company(context["company_code"])
    if not employee_app_enabled():
        raise HTTPException(status_code=403, detail={"error": "feature_disabled", "message": "The employee app is not enabled."})
    # Phase 1: company-level Employee App policy (module + who-can-use) is Setup Console-owned.
    # PostHire retains per-employee eligibility / invites / revoke only.
    if (
        body.module_enabled is not None
        or body.access_mode is not None
        or body.selected_departments is not None
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "error": "company_app_access_owned_by_setup_console",
                "message": (
                    "Company Employee App policy is configured in Setup Console. "
                    "Use Employees for per-person access once the app is on."
                ),
                "setup_console_href": "/setup-console#classic-app-access",
            },
        )
    import employee_app_access as _access

    # sync_invites-only remains allowed as an operational re-sync hook without policy mutation.
    return json_safe(
        _access.set_company_app_access_policy(
            sys.modules[__name__],
            context,
            module_enabled=None,
            access_mode=None,
            selected_departments=None,
            sync_invites=bool(body.sync_invites),
            source="posthire_dashboard",
            allow_module_toggle=False,
        )
    )


@app.post("/dashboard/posthire/employees/{employee_key}/app-access/revoke")
def dashboard_posthire_app_access_revoke(
    employee_key: str,
    request: DashboardEmployeeAppAccessRevokeRequest,
    context: dict[str, Any] = Depends(dashboard_context),
):
    """Phase 5 — HR revoke for lost/compromised phones. Idempotent + audited."""
    require_employee_roster_admin(context, "employees.manage")
    company = context["company_code"]
    require_active_company(company)
    if not employee_app_enabled():
        raise HTTPException(status_code=403, detail={"error": "feature_disabled", "message": "The employee app is not enabled."})
    employee = find_employee_by_key(employee_key, company_code=company)
    if not employee or not context_manager_allows_employee(context, employee, company_code=company):
        raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})

    idempotency_key = request.idempotency_key.strip()
    reason_text = request.reason.strip()
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT result_id, result
                FROM action_results
                WHERE company_code=%s
                  AND action_type='employee_app_access_revoked'
                  AND result->'details'->>'idempotency_key' = %s
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (company, idempotency_key),
            )
            prior = cur.fetchone()
            if prior:
                prior_row = dict(prior)
                prior_details = (prior_row.get("result") or {}).get("details") if isinstance(prior_row.get("result"), dict) else {}
                return json_safe({
                    "ok": True,
                    "employee_key": str(employee_key),
                    "sessions_revoked": int((prior_details or {}).get("sessions_revoked") or 0),
                    "reused": True,
                    "audit_result_id": str(prior_row.get("result_id")),
                    "access": _dashboard_employee_app_access_summary(company, employee_key),
                })

            cur.execute(
                "SELECT pg_advisory_xact_lock(hashtextextended(%s, 0))",
                (f"employee-app-access-revoke:{company}:{employee_key}",),
            )
            # Re-check idempotency under lock.
            cur.execute(
                """
                SELECT result_id, result
                FROM action_results
                WHERE company_code=%s
                  AND action_type='employee_app_access_revoked'
                  AND result->'details'->>'idempotency_key' = %s
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (company, idempotency_key),
            )
            prior = cur.fetchone()
            if prior:
                prior_row = dict(prior)
                prior_details = (prior_row.get("result") or {}).get("details") if isinstance(prior_row.get("result"), dict) else {}
                conn.commit()
                return json_safe({
                    "ok": True,
                    "employee_key": str(employee_key),
                    "sessions_revoked": int((prior_details or {}).get("sessions_revoked") or 0),
                    "reused": True,
                    "audit_result_id": str(prior_row.get("result_id")),
                    "access": _dashboard_employee_app_access_summary(company, employee_key),
                })

            cur.execute(
                """
                UPDATE employee_sessions
                SET status='revoked', refresh_hash=NULL, revoked_at=now(), revoked_reason='hr_revoked',
                    expires_at=LEAST(expires_at, now()), refresh_expires_at=LEAST(refresh_expires_at, now())
                WHERE company_code=%s AND employee_key=%s AND status='active'
                """,
                (company, str(employee_key)),
            )
            sessions_revoked = int(cur.rowcount or 0)
            cur.execute(
                "UPDATE employee_push_tokens SET active=FALSE, last_error=%s, updated_at=now() WHERE company_code=%s AND employee_key=%s AND active IS TRUE",
                ("hr_revoked", company, str(employee_key)),
            )
            # Pending activation codes must not survive revoke — employee needs Re-invite.
            cur.execute(
                """
                UPDATE employee_app_invites
                SET status='superseded', idempotency_key=NULL, updated_at=now()
                WHERE company_code=%s AND employee_key=%s AND status='pending'
                """,
                (company, str(employee_key)),
            )
            pending_invites_superseded = int(cur.rowcount or 0)
            # Defense in depth: bump ESS epoch when a binding exists (no-op if none).
            try:
                cur.execute(
                    """
                    UPDATE employee_ess_identity_bindings
                    SET session_epoch=session_epoch+1,
                        metadata=metadata || %s::jsonb
                    WHERE company_code=%s AND employee_key=%s AND status='active'
                    """,
                    (json.dumps({"last_revoke_reason": "hr_revoked", "at": now_utc().isoformat()}), company, str(employee_key)),
                )
            except Exception:
                pass
            audit = write_admin_audit(
                cur,
                context,
                "employee_app_access_revoked",
                summary="Revoked employee app access for a lost or compromised device.",
                target_type="employee",
                target=str(employee_key),
                details={
                    "idempotency_key": idempotency_key,
                    "reason": reason_text,
                    "sessions_revoked": sessions_revoked,
                    "pending_invites_superseded": pending_invites_superseded,
                    "revoked_reason": "hr_revoked",
                },
            )
        conn.commit()
    return json_safe({
        "ok": True,
        "employee_key": str(employee_key),
        "sessions_revoked": sessions_revoked,
        "reused": False,
        "audit_result_id": str(audit["result_id"]),
        "access": _dashboard_employee_app_access_summary(company, employee_key),
    })


