@app.get("/dashboard/posthire/employees")
def dashboard_posthire_employees(
    offset: int = 0,
    limit: int = 100,
    search: str = "",
    context: dict[str, Any] = Depends(dashboard_context),
):
    # Employees directory is the shared people view; visible when the company has
    # any post-hire module and the user can read it.
    company = context["company_code"]
    if not dashboard_context_has_permission(context, "employees.read"):
        raise HTTPException(status_code=403, detail={"error": "permission_denied", "message": "You do not have access to do that."})
    readable = [m for m in POSTHIRE_PEOPLE_MODULES if company_has_module(company, m) and dashboard_context_has_permission(context, f"{m}.read")]
    if not readable:
        raise HTTPException(status_code=403, detail={"error": "module_disabled", "message": "This module is not enabled for your company."})
    # Page the directory so a company with a large workforce isn't silently
    # truncated. Manager scope is applied in SQL, so total_count/has_more are
    # accurate for the viewer (owners see everyone; managers see their people).
    # `search` filters the paged rows/total in SQL; the headline stats stay
    # workforce-wide so the stat cards don't jump around as HR types.
    limit = max(1, min(int(limit or 100), 500))
    offset = max(0, int(offset or 0))
    page = list_employees_page(
        company,
        viewer_phone=context.get("hr_phone"),
        dashboard_user_id=context.get("actor_user_id"),
        actor_role=context.get("actor_role"),
        search=search,
        limit=limit,
        offset=offset,
    )
    employees = [posthire_employee_card(row) for row in page["rows"]]
    stats = employee_directory_stats(
        company,
        viewer_phone=context.get("hr_phone"),
        dashboard_user_id=context.get("actor_user_id"),
        actor_role=context.get("actor_role"),
    )
    return {
        "company_code": company,
        "count": len(employees),
        "employees": employees,
        "total_count": page["total_count"],
        "limit": page["limit"],
        "offset": page["offset"],
        "has_more": page["has_more"],
        "active_count": stats["active_count"],
        "left_count": stats["left_count"],
        "onboarding_count": stats["onboarding_count"],
        "department_count": stats["department_count"],
    }


# --- Employee roster management (Add employee / Import employees) -------------
# A company that buys only a post-hire module must be able to load its existing
# workforce WITHOUT the pre-hiring pipeline. These endpoints INSERT directly into
# the `employees` hub (app_key left NULL), consistent with the orchestrator's
# other direct writes (e.g. start_onboarding). No external workspace script and
# no pre-hiring dependency. Onboarding stays 'not_started' and NO welcome message
# is sent — these are existing staff, not new hires.
# Seeded as 'missing' so a newly added employee shows up on the Compliance page
# with a clear checklist. Only seeded when the company has the compliance module.
# Sends nothing (compliance reminders are always a manual HR action).
DEFAULT_COMPLIANCE_SEED_TYPES = ("civil_id", "passport")

# Import header normalization: map common CSV/XLSX column names to our fields.
EMPLOYEE_IMPORT_HEADER_ALIASES = {
    "name": "name", "full_name": "name", "employee_name": "name", "fullname": "name",
    "phone": "phone", "mobile": "phone", "whatsapp": "phone", "phone_number": "phone",
    "whatsapp_number": "phone", "mobile_number": "phone", "contact": "phone",
    "email": "email", "email_address": "email", "e_mail": "email", "mail": "email",
    "email_id": "email", "work_email": "email", "personal_email": "email",
    "job_title": "position_title", "title": "position_title", "position": "position_title",
    "position_title": "position_title", "role": "position_title", "designation": "position_title",
    "department": "department", "team": "department", "dept": "department", "division": "department",
    "start_date": "start_date", "hire_date": "start_date", "joining_date": "start_date", "start": "start_date",
    "external_employee_id": "external_employee_id", "external_id": "external_employee_id",
    "employee_id": "external_employee_id", "emp_id": "external_employee_id",
    "source_employee_id": "external_employee_id", "ats_id": "external_employee_id",
    "payroll_id": "payroll_id", "payroll_employee_id": "payroll_id", "pay_id": "payroll_id",
    "source_system": "source_system", "source": "source_system", "system": "source_system", "hris": "source_system",
    "manager_phone": "manager_phone", "manager": "manager_phone", "manager_mobile": "manager_phone",
    "reports_to": "manager_phone", "reports_to_phone": "manager_phone",
    "line_manager": "manager_phone", "line_manager_phone": "manager_phone",
}
EMPLOYEE_IMPORT_MAX_ROWS = 1000
EMPLOYEE_IMPORT_MAX_BYTES = 5 * 1024 * 1024


def _normalize_import_header(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", "_", str(value or "").strip().lower()).strip("_")


def canonical_employee_phone(value: str | None) -> str:
    """Canonicalize a phone to the form the workforce already stores (965-prefixed
    for Kuwait local numbers), so a manually added employee maps to the SAME
    employee_key as a pipeline-hired one and de-dupes via the primary key. Mirrors
    the 8-digit <-> 965 rule in phone_identity_candidates; other formats unchanged."""
    raw = digits(value)
    if len(raw) == 8:
        return f"965{raw}"
    return raw


def _coerce_employee_start_date(value: Any) -> date | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return date.fromisoformat(text[:10])
    except Exception:
        return None


def _seed_employee_compliance_documents(
    cur: Any,
    company_code: str,
    employee_key: str,
    *,
    employee_category: str | None = None,
) -> int:
    """Seed compliance_documents using category-aware types.

    Wave 1 integrity: Art.18 expatriates get canonical `residence` + `work_permit`
    (never Saudi iqama). Kuwaiti nationals get Civil ID only for KW. When category
    is omitted, resolve from employee_identity when present.
    """
    seeded = 0
    category = employee_category
    if not category:
        try:
            cur.execute(
                """
                SELECT employee_category FROM employee_identity
                WHERE company_code=%s AND employee_key=%s
                LIMIT 1
                """,
                ((company_code or "").upper(), employee_key),
            )
            idrow = cur.fetchone()
            if idrow:
                category = str(idrow.get("employee_category") or "") or None
        except Exception:
            category = employee_category
    try:
        import kuwait_first_client_foundation as _kw_foundation

        types = _kw_foundation.compliance_seed_types_for_category(category, country_code="KW")
    except Exception:
        types = DEFAULT_COMPLIANCE_SEED_TYPES
    # Never seed legacy residency_iqama for new rows — canonical residence only.
    types = tuple(
        ("residence" if t in {"residency", "residency_iqama"} else t) for t in types
    )
    labels = dict(COMPLIANCE_DOC_LABELS)
    labels.setdefault("residence", "Residence")
    labels.setdefault("work_permit", "Work permit")
    for doc_type in types:
        cur.execute(
            """
            INSERT INTO compliance_documents (employee_key, document_type, label, status, warning_days, company_code, updated_at)
            VALUES (%s,%s,%s,'missing',%s,%s, now())
            ON CONFLICT (employee_key, document_type) DO NOTHING
            """,
            (
                employee_key,
                doc_type,
                labels.get(doc_type),
                COMPLIANCE_WARNING_DAYS.get(doc_type) or COMPLIANCE_WARNING_DAYS.get("residence", 30),
                company_code,
            ),
        )
        seeded += cur.rowcount or 0
    return seeded


def create_company_employee(
    company_code: str,
    *,
    name: str | None,
    phone: str | None,
    email: str | None = None,
    position_title: str | None = None,
    department: str | None = None,
    start_date: str | None = None,
    seed_compliance: bool = False,
    start_onboarding: bool = False,
) -> dict[str, Any]:
    """Create a single employee directly in the hub (no pre-hiring pipeline).

    Returns {status: 'created'|'exists'|'failed', ...}. The key is deterministic
    ({COMPANY}-{canonical phone}) so the same person in the same company self-dedupes
    via the primary key — an existing (possibly hired) employee is never overwritten.

    Wave 1 also rejects alias collisions application-side (local 8 ↔ 965…) before
    insert, without requiring a production UNIQUE(company_code, phone) constraint.
    """
    company = (company_code or "").upper()
    phone_digits = canonical_employee_phone(phone)
    clean_name = str(name or "").strip()
    if not phone_digits:
        return {"status": "failed", "reason": "A WhatsApp phone number is required."}
    if not clean_name:
        return {"status": "failed", "reason": "A full name is required."}
    employee_key = f"{company}-{phone_digits}"
    dept = str(department or "").strip()
    title = str(position_title or "").strip() or None
    profile: dict[str, Any] = {}
    if dept:
        profile["department"] = dept
    raw_meta: dict[str, Any] = {"source": "dashboard_roster"}
    if dept:
        raw_meta["department"] = dept
    with db_connect() as conn:
        with conn.cursor() as cur:
            # Alias-aware pre-check: an existing local-8 row must block a 965 create
            # (and vice versa) even when the deterministic keys differ.
            alias_hit = find_employee_by_phone_aliases(phone_digits, company_code=company, cur=cur)
            if alias_hit:
                matched_key = str(alias_hit.get("employee_key") or "")
                collision = matched_key != employee_key or str(alias_hit.get("phone") or "") != phone_digits
                conn.commit()
                return {
                    "status": "exists",
                    "employee_key": matched_key or employee_key,
                    "employee": posthire_employee_card(alias_hit),
                    "identity_collision": collision,
                    "attempted_phone": phone_digits,
                    "attempted_employee_key": employee_key,
                    "matched_phone": alias_hit.get("phone"),
                }
            cur.execute(
                """
                INSERT INTO employees (employee_key, phone, company_code, name, email, position_title, start_date, profile, raw_json, updated_at)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s, now())
                ON CONFLICT (employee_key) DO NOTHING
                RETURNING *
                """,
                (
                    employee_key, phone_digits, company, clean_name,
                    str(email or "").strip() or None, title,
                    _coerce_employee_start_date(start_date),
                    Json(profile), Json(raw_meta),
                ),
            )
            row = cur.fetchone()
            if not row:
                cur.execute(
                    "SELECT * FROM employees WHERE employee_key=%s AND company_code=%s LIMIT 1",
                    (employee_key, company),
                )
                existing = cur.fetchone()
                conn.commit()
                return {
                    "status": "exists",
                    "employee_key": employee_key,
                    "employee": posthire_employee_card(dict(existing)) if existing else None,
                    "identity_collision": False,
                }
            employee = dict(row)
            seeded = _seed_employee_compliance_documents(cur, company, employee_key) if seed_compliance else 0
            # Opt-in: only when the caller asks AND the flag is on, so we never
            # leave an employee marked in_progress with an empty checklist.
            onboarding_seeded = 0
            if start_onboarding and onboarding_seed_enabled():
                onboarding_seeded = seed_onboarding_items(cur, employee)
                # Opting in at creation is an explicit launch, so record it on the
                # assignment. The completion contract reads that to tell a launched
                # onboarding (waiting on someone) from one never started.
                try:
                    import onboarding_wave2 as _onb2

                    _onb2.upsert_assignment(
                        cur,
                        employee_key=employee_key,
                        company_code=company,
                        status="in_progress",
                        metadata={"launched_by": "roster_create_opt_in"},
                    )
                except Exception:
                    logger.exception(
                        "onboarding assignment launch stamp failed employee=%s", employee_key
                    )
                recompute_employee_onboarding_counts(
                    cur, employee_key, actor="roster_create_opt_in"
                )
                cur.execute(
                    "SELECT onboarding_status FROM employees WHERE employee_key=%s AND company_code=%s",
                    (employee_key, company),
                )
                employee["onboarding_status"] = (
                    dict(cur.fetchone() or {}).get("onboarding_status") or "in_progress"
                )
            conn.commit()
    # Wave 2 shadow authority (opt-in). Hub row remains API compatibility source.
    try:
        import employee_authority_wave2 as _e360_authority

        if _e360_authority.authority_v2_enabled(company):
            _e360_authority.sync_authority_from_hub_employee(
                sys.modules[__name__],
                {**employee, "department": dept or None},
                hire_source="dashboard_roster",
            )
    except Exception:
        pass
    # Invitation/delivery: create alone never auto-invites.
    # Phase 2B durable policy may enable + invite for dashboard roster creates under Everyone/Department.
    invitation_result: dict[str, Any] | None = {
        "ok": False,
        "skipped": True,
        "reason": "create_does_not_auto_invite",
    }
    access_reconcile: dict[str, Any] | None = None
    try:
        import employee_app_access as _access

        access_reconcile = _access.reconcile_employee_app_access(
            sys.modules[__name__],
            {
                "company_code": company,
                "actor_user_id": "system:roster_create",
                "user_id": "system:roster_create",
            },
            employee_key=employee_key,
            allow_invite=True,
            trigger="roster_create",
        )
        if access_reconcile.get("desired") and access_reconcile.get("changed"):
            invitation_result = ((access_reconcile.get("result") or {}).get("invitation")) or {
                "ok": True,
                "trigger": "policy_reconcile_roster_create",
            }
    except Exception:
        logger.exception("employee app access reconcile on create failed employee=%s", employee_key)
    return {
        "status": "created",
        "employee_key": employee_key,
        "employee": posthire_employee_card(employee),
        "compliance_seeded": seeded,
        "onboarding_seeded": onboarding_seeded,
        "app_invitation": invitation_result,
        "app_access_enabled": bool((access_reconcile or {}).get("desired")),
        "app_access_reconcile": access_reconcile,
    }


EMPLOYEE_EDITABLE_FIELDS = {"name", "phone", "email", "position_title", "department", "start_date"}


def update_company_employee(
    company_code: str,
    employee_key: str,
    *,
    fields: dict[str, Any],
    expected_updated_at: datetime | None = None,
) -> dict[str, Any]:
    """Edit an existing employee's core fields in place. The employee_key (the
    history anchor that child tables hang off) is NEVER changed — editing the
    phone updates the `phone` column only, so attendance/leave/shifts/payroll/
    compliance history stays linked. Returns {status, ...}.

    When `expected_updated_at` is provided (HTTP edits), the update is optimistic:
    a mismatched version returns `conflict` instead of silently overwriting.
    """
    company = (company_code or "").upper()
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM employees WHERE employee_key=%s AND company_code=%s LIMIT 1", (employee_key, company))
            row = cur.fetchone()
            if not row:
                return {"status": "not_found"}
            current = dict(row)
            if expected_updated_at is not None and current.get("updated_at") != expected_updated_at:
                return {
                    "status": "conflict",
                    "reason": "This employee changed after the edit form was opened.",
                    "employee": posthire_employee_card(current),
                }

            updates: dict[str, Any] = {}
            if "name" in fields:
                clean = str(fields.get("name") or "").strip()
                if not clean:
                    return {"status": "failed", "reason": "A full name is required."}
                updates["name"] = clean
            if "phone" in fields:
                new_phone = canonical_employee_phone(fields.get("phone"))
                if not new_phone:
                    return {"status": "failed", "reason": "A valid WhatsApp phone number is required."}
                if new_phone != str(current.get("phone") or ""):
                    alias_hit = find_employee_by_phone_aliases(
                        new_phone,
                        company_code=company,
                        exclude_employee_key=employee_key,
                        cur=cur,
                    )
                    if alias_hit:
                        return {"status": "duplicate", "reason": "Another employee already uses this phone number."}
                updates["phone"] = new_phone
            if "email" in fields:
                updates["email"] = str(fields.get("email") or "").strip() or None
            if "position_title" in fields:
                updates["position_title"] = str(fields.get("position_title") or "").strip() or None
            if "start_date" in fields:
                updates["start_date"] = _coerce_employee_start_date(fields.get("start_date"))

            # Department lives in the profile JSON (not a column).
            profile = current.get("profile") if isinstance(current.get("profile"), dict) else {}
            old_department = str(profile.get("department") or "").strip()
            department_changed = False
            if "department" in fields:
                dept = str(fields.get("department") or "").strip()
                department_changed = dept != old_department
                profile = {**profile}
                if dept:
                    profile["department"] = dept
                else:
                    profile.pop("department", None)
                updates["profile"] = Json(profile)

            if not updates:
                return {"status": "noop", "employee": posthire_employee_card(current)}

            set_clause = ", ".join(f"{col}=%s" for col in updates) + ", updated_at=now()"
            params = list(updates.values()) + [employee_key, company]
            where_version = ""
            if expected_updated_at is not None:
                where_version = " AND updated_at=%s"
                params.append(expected_updated_at)
            cur.execute(
                f"UPDATE employees SET {set_clause} WHERE employee_key=%s AND company_code=%s{where_version} RETURNING *",
                params,
            )
            updated_row = cur.fetchone()
            if not updated_row:
                cur.execute(
                    "SELECT * FROM employees WHERE employee_key=%s AND company_code=%s LIMIT 1",
                    (employee_key, company),
                )
                latest = cur.fetchone()
                conn.commit()
                return {
                    "status": "conflict",
                    "reason": "This employee changed after the edit form was opened.",
                    "employee": posthire_employee_card(dict(latest)) if latest else None,
                }
            updated = dict(updated_row)
        conn.commit()
    try:
        import employee_authority_wave2 as _e360_authority

        if _e360_authority.authority_v2_enabled(company):
            _e360_authority.sync_authority_from_hub_employee(
                sys.modules[__name__],
                updated,
                hire_source="employee_edit",
            )
    except Exception:
        pass
    access_reconcile: dict[str, Any] | None = None
    # Only reconcile when the canonical department string actually changed.
    # Email/name/phone-only saves still send department in the form payload and must
    # not wipe per-employee eligibility that was granted outside an empty selected list.
    if department_changed:
        try:
            import employee_app_access as _access

            access_reconcile = _access.reconcile_employee_app_access(
                sys.modules[__name__],
                {
                    "company_code": company,
                    "actor_user_id": "system:employee_edit",
                    "user_id": "system:employee_edit",
                },
                employee_key=employee_key,
                allow_invite=True,
                trigger="department_edit",
            )
        except Exception:
            logger.exception("employee app access reconcile on department edit failed employee=%s", employee_key)
    result = {"status": "updated", "employee_key": employee_key, "employee": posthire_employee_card(updated)}
    if access_reconcile is not None:
        result["app_access_reconcile"] = access_reconcile
    return result


def set_employee_employment_status(company_code: str, employee_key: str, status: str) -> dict[str, Any]:
    """Mark an employee active or left. Never deletes — history is preserved and
    the row stays searchable. Returns {status, ...}."""
    company = (company_code or "").upper()
    target = str(status or "").strip().lower()
    if target not in {"active", "left"}:
        return {"status": "invalid_status"}
    with db_connect() as conn:
        try:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT employee_key FROM employees WHERE employee_key=%s AND company_code=%s FOR UPDATE",
                    (employee_key, company),
                )
                if not cur.fetchone():
                    return {"status": "not_found"}
                cur.execute(
                    "UPDATE employees SET employment_status=%s, updated_at=now() WHERE employee_key=%s AND company_code=%s RETURNING *",
                    (target, employee_key, company),
                )
                updated = dict(cur.fetchone())
                if target == "left":
                    cur.execute(
                        """
                        UPDATE employee_sessions
                        SET status='revoked', refresh_hash=NULL, revoked_at=now(),
                            revoked_reason='offboarded',
                            expires_at=LEAST(expires_at, now()),
                            refresh_expires_at=LEAST(refresh_expires_at, now())
                        WHERE company_code=%s AND employee_key=%s AND status='active'
                        """,
                        (company, employee_key),
                    )
                    cur.execute(
                        "UPDATE employee_push_tokens SET active=false, updated_at=now() WHERE company_code=%s AND employee_key=%s AND active IS TRUE",
                        (company, employee_key),
                    )
            conn.commit()
        except Exception:
            conn.rollback()
            raise
    return {"status": "ok", "employment_status": target, "employee_key": employee_key, "employee": posthire_employee_card(updated)}


def require_employee_roster_admin(context: dict[str, Any], permission: str = "employees.manage") -> str:
    """Gate for roster management: company must have at least one post-hire people
    module enabled (module-agnostic, so an attendance-only or compliance-only
    company qualifies) and the current backend user must hold the requested
    explicit employee authority."""
    company = context["company_code"]
    if not any(company_has_module(company, m) for m in POSTHIRE_PEOPLE_MODULES):
        raise HTTPException(status_code=403, detail={"error": "module_disabled", "message": "This module is not enabled for your company."})
    if not dashboard_context_has_permission(context, permission):
        raise HTTPException(status_code=403, detail={"error": "permission_denied", "message": "You do not have access to do that."})
    return company


def employee_status_canary_companies() -> set[str]:
    if "WATHEFNI_EMPLOYEE_STATUS_CANARY_COMPANIES" in os.environ:
        raw = (os.environ.get("WATHEFNI_EMPLOYEE_STATUS_CANARY_COMPANIES") or "").strip()
    else:
        raw = "WATHEFNI"
    return {part.strip().upper() for part in raw.split(",") if part.strip()}


def employee_status_canary_envs() -> set[str]:
    # Production is intentionally excluded by default. Ops must explicitly add it
    # for WATHEFNI-only internal canary in a live environment.
    if "WATHEFNI_EMPLOYEE_STATUS_CANARY_ENVS" in os.environ:
        raw = (os.environ.get("WATHEFNI_EMPLOYEE_STATUS_CANARY_ENVS") or "").strip()
    else:
        raw = "local,dev,development,staging,stage,test,pytest,harness"
    return {part.strip().lower() for part in raw.split(",") if part.strip()}


def employee_status_runtime_env() -> str:
    return (os.environ.get("WATHEFNI_ENV") or os.environ.get("ENV") or "local").strip().lower() or "local"


def employee_status_canary_allowed(company_code: str | None) -> bool:
    """Fail-closed allowlist for self_approved_internal_canary.

    Default: company WATHEFNI only, and only non-production runtime envs.
    Empty company/env allowlists deny every request.
    """
    companies = employee_status_canary_companies()
    envs = employee_status_canary_envs()
    if not companies or not envs:
        return False
    company = str(company_code or "").strip().upper()
    return bool(company) and company in companies and employee_status_runtime_env() in envs


def require_employee_mutation_scope(
    context: dict[str, Any],
    employee_key: str,
    *,
    company_code: str | None = None,
    action: str,
) -> dict[str, Any]:
    """Load the target employee and deny out-of-scope mutations with the same
    404 surface used for reads. Records a denied audit for scope breaches."""
    company = str(company_code or context.get("company_code") or "").upper()
    employee = find_employee_by_key(employee_key, company_code=company)
    if not employee:
        raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})
    if context_manager_allows_employee(context, employee, company_code=company):
        return employee
    record_admin_audit(
        context,
        "employee_mutation_denied",
        summary=f"Denied out-of-scope employee mutation ({action}).",
        target_type="employee",
        target=str(employee_key),
        details={
            "action": action,
            "reason": "manager_scope",
            "employee_key": str(employee.get("employee_key") or employee_key),
            "company_code": company,
        },
        status="denied",
    )
    raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})


class DashboardEmployeeCreate(BaseModel):
    name: str
    phone: str
    email: str | None = None
    position_title: str | None = None
    department: str | None = None
    start_date: str | None = None
    start_onboarding: bool = False


@app.post("/dashboard/posthire/employees")
def dashboard_posthire_create_employee(request: DashboardEmployeeCreate, context: dict[str, Any] = Depends(dashboard_context)):
    company = require_employee_roster_admin(context)
    seed = company_has_module(company, "compliance")
    result = create_company_employee(
        company,
        name=request.name,
        phone=request.phone,
        email=request.email,
        position_title=request.position_title,
        department=request.department,
        start_date=request.start_date,
        seed_compliance=seed,
        start_onboarding=request.start_onboarding,
    )
    if result["status"] == "failed":
        raise HTTPException(status_code=422, detail={"error": "invalid_employee", "message": result["reason"]})
    if result["status"] == "exists":
        if result.get("identity_collision"):
            record_admin_audit(
                context,
                "employee_identity_collision",
                summary="Blocked employee create due to phone identity collision.",
                target_type="employee",
                target=str(result.get("employee_key") or ""),
                details={
                    "attempted_phone": result.get("attempted_phone"),
                    "attempted_employee_key": result.get("attempted_employee_key"),
                    "matched_phone": result.get("matched_phone"),
                    "matched_employee_key": result.get("employee_key"),
                    "source": "dashboard_roster_create",
                },
                status="denied",
            )
        return {"ok": False, "status": "exists", "employee": result.get("employee"), "message": "An employee with this phone number already exists."}
    record_admin_audit(
        context,
        "employee_created",
        summary=f"Added employee {request.name}.",
        target_type="employee",
        target=result["employee_key"],
        details={
            "phone": canonical_employee_phone(request.phone),
            "compliance_seeded": result.get("compliance_seeded", 0),
            "onboarding_seeded": result.get("onboarding_seeded", 0),
        },
    )
    return {"ok": True, "status": "created", "employee": result.get("employee")}


class DashboardEmployeeUpdate(BaseModel):
    name: str | None = None
    phone: str | None = None
    email: str | None = None
    position_title: str | None = None
    department: str | None = None
    start_date: str | None = None
    expected_updated_at: datetime


@app.patch("/dashboard/posthire/employees/{employee_key}")
def dashboard_posthire_update_employee(
    employee_key: str,
    request: DashboardEmployeeUpdate,
    context: dict[str, Any] = Depends(dashboard_context),
):
    company = require_employee_roster_admin(context)
    require_employee_mutation_scope(context, employee_key, company_code=company, action="employee_update")
    # Only fields the caller actually sent are touched (PATCH semantics), so an
    # edit of just the title can never blank the phone/name.
    provided = request.model_dump(exclude_unset=True) if hasattr(request, "model_dump") else request.dict(exclude_unset=True)
    fields = {k: v for k, v in provided.items() if k in EMPLOYEE_EDITABLE_FIELDS}
    if not fields:
        raise HTTPException(status_code=422, detail={"error": "no_fields", "message": "Nothing to update."})
    result = update_company_employee(
        company,
        employee_key,
        fields=fields,
        expected_updated_at=request.expected_updated_at,
    )
    if result["status"] == "not_found":
        raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})
    if result["status"] == "conflict":
        raise HTTPException(
            status_code=409,
            detail={
                "error": "employee_version_conflict",
                "message": result.get("reason") or "This employee changed after the edit form was opened.",
                "employee": result.get("employee"),
            },
        )
    if result["status"] == "duplicate":
        record_admin_audit(
            context,
            "employee_identity_collision",
            summary="Blocked employee phone edit due to identity collision.",
            target_type="employee",
            target=str(employee_key),
            details={"action": "employee_update", "fields": sorted(fields.keys()), "reason": "phone_alias_collision"},
            status="denied",
        )
        return {"ok": False, "status": "duplicate", "message": result["reason"]}
    if result["status"] == "failed":
        raise HTTPException(status_code=422, detail={"error": "invalid_employee", "message": result["reason"]})
    record_admin_audit(
        context,
        "employee_updated",
        summary=f"Updated employee {result.get('employee', {}).get('name') or employee_key}.",
        target_type="employee",
        target=employee_key,
        details={"fields": sorted(fields.keys())},
    )
    return {"ok": True, "status": "updated", "employee": result.get("employee")}


class DashboardEmployeeStatus(BaseModel):
    status: Literal["active", "left"]
    reason: str = Field(min_length=3, max_length=500)
    idempotency_key: str = Field(min_length=8, max_length=128)
    expected_status: Literal["active", "left"]
    expected_updated_at: datetime
    approver_user_id: str = Field(min_length=1, max_length=64)
    approval_reference: str = Field(min_length=3, max_length=200)
    approval_mode: Literal["separate_approval", "self_approved_internal_canary"]


def _canonical_employee_status(value: Any) -> str:
    normalized = str(value or "").strip().lower()
    return "left" if normalized == "left" else "active"


def _employee_status_request_hash(
    company_code: str,
    employee_key: str,
    request: DashboardEmployeeStatus,
    requester_user_id: str,
    approver_user_id: str,
) -> str:
    payload = {
        "company_code": str(company_code or "").upper(),
        "employee_key": str(employee_key),
        "status": request.status,
        "reason": request.reason.strip(),
        "idempotency_key": request.idempotency_key.strip(),
        "expected_status": request.expected_status,
        "expected_updated_at": request.expected_updated_at.isoformat(),
        "requester_user_id": requester_user_id,
        "approver_user_id": approver_user_id,
        "approval_reference": request.approval_reference.strip(),
        "approval_mode": request.approval_mode,
    }
    return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()


def _employee_status_change_response(change: dict[str, Any], employee: dict[str, Any] | None = None) -> dict[str, Any]:
    verification_status = str(change.get("verification_status") or "pending")
    verified = verification_status == "verified"
    return {
        "ok": True,
        "committed": True,
        "verified": verified,
        "status": "updated" if verified else "committed_verification_pending",
        "operator_verification_required": not verified,
        "result_id": str(change.get("action_result_id") or ""),
        "change_id": str(change.get("change_id") or ""),
        "idempotency_key": str(change.get("idempotency_key") or ""),
        "employment_status": str(change.get("requested_status") or ""),
        "previous_status": str(change.get("previous_status") or ""),
        "previous_updated_at": change.get("previous_updated_at"),
        "resulting_updated_at": change.get("resulting_updated_at"),
        "changed_fields": list(change.get("changed_fields") or []),
        "verification_status": verification_status,
        "employee": posthire_employee_card(employee) if employee else None,
    }


def _verify_committed_employee_status_change(
    company_code: str,
    idempotency_key: str,
    fallback_change: dict[str, Any],
) -> dict[str, Any]:
    company = str(company_code or "").upper()
    key = str(idempotency_key or "")
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT * FROM employee_status_changes WHERE company_code=%s AND idempotency_key=%s LIMIT 1",
                    (company, key),
                )
                change = dict(cur.fetchone() or fallback_change)
                if str(change.get("verification_status") or "") == "verified":
                    cur.execute(
                        "SELECT * FROM employees WHERE company_code=%s AND employee_key=%s LIMIT 1",
                        (company, change["employee_key"]),
                    )
                    return _employee_status_change_response(change, dict(cur.fetchone() or {}))
                cur.execute(
                    "SELECT * FROM employees WHERE company_code=%s AND employee_key=%s LIMIT 1",
                    (company, change["employee_key"]),
                )
                employee = dict(cur.fetchone() or {})
                verified = bool(employee)
                verified = verified and _canonical_employee_status(employee.get("employment_status")) == change["requested_status"]
                verified = verified and employee.get("updated_at") == change.get("resulting_updated_at")
                if change["requested_status"] == "left":
                    cur.execute(
                        "SELECT count(*) AS n FROM employee_sessions WHERE company_code=%s AND employee_key=%s AND status='active' AND expires_at > now()",
                        (company, change["employee_key"]),
                    )
                    verified = verified and int(cur.fetchone()["n"]) == 0
                if verified:
                    cur.execute(
                        """
                        UPDATE employee_status_changes
                        SET verification_status='verified', verification_error=NULL, verified_at=now()
                        WHERE change_id=%s
                        RETURNING *
                        """,
                        (change["change_id"],),
                    )
                    change = dict(cur.fetchone())
                else:
                    cur.execute(
                        """
                        UPDATE employee_status_changes
                        SET verification_status='pending',
                            verification_error='independent_readback_mismatch'
                        WHERE change_id=%s
                        RETURNING *
                        """,
                        (change["change_id"],),
                    )
                    change = dict(cur.fetchone())
            conn.commit()
        if not verified:
            logger.error(
                "employee status change committed but verification is pending result_id=%s",
                change.get("action_result_id"),
            )
        return _employee_status_change_response(change, employee)
    except Exception:
        logger.error(
            "employee status change committed but independent verification could not complete result_id=%s",
            fallback_change.get("action_result_id"),
            exc_info=True,
        )
        return _employee_status_change_response({**fallback_change, "verification_status": "pending"})


def transition_employee_employment_status(
    context: dict[str, Any],
    employee_key: str,
    request: DashboardEmployeeStatus,
) -> dict[str, Any]:
    company = str(context.get("company_code") or "").upper()
    requester_user_id = str(context.get("actor_user_id") or "").strip()
    requested_approver = str(request.approver_user_id or "").strip()
    approver_user_id = requester_user_id if requested_approver == "self" else requested_approver
    idempotency_key = request.idempotency_key.strip()
    request_hash = _employee_status_request_hash(
        company,
        employee_key,
        request,
        requester_user_id,
        approver_user_id,
    )
    committed_change: dict[str, Any]

    with db_connect() as conn:
        try:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT * FROM dashboard_users WHERE company_code=%s AND user_id=%s FOR SHARE",
                    (company, requester_user_id),
                )
                requester = dict(cur.fetchone() or {})
                requester_permissions = dashboard_effective_permissions_for_user(requester, cur=cur) if requester else []
                if not _normal_dashboard_operator(requester) or "employees.manage" not in requester_permissions:
                    raise HTTPException(status_code=403, detail={"error": "permission_denied", "message": "You do not have access to do that."})

                if approver_user_id == requester_user_id:
                    approver = requester
                    approver_permissions = requester_permissions
                    if request.approval_mode != "self_approved_internal_canary":
                        raise HTTPException(status_code=422, detail={"error": "invalid_approval_mode", "message": "Self-approval is limited to the approved internal canary."})
                    if not employee_status_canary_allowed(company):
                        raise HTTPException(
                            status_code=403,
                            detail={
                                "error": "canary_not_allowed",
                                "message": "Self-approved internal canary is not enabled for this company or environment.",
                                "company_code": company,
                                "environment": employee_status_runtime_env(),
                            },
                        )
                else:
                    if request.approval_mode != "separate_approval":
                        raise HTTPException(status_code=422, detail={"error": "invalid_approval_mode", "message": "This approval must name a separate approver."})
                    cur.execute(
                        "SELECT * FROM dashboard_users WHERE company_code=%s AND user_id=%s FOR SHARE",
                        (company, approver_user_id),
                    )
                    approver = dict(cur.fetchone() or {})
                    approver_permissions = dashboard_effective_permissions_for_user(approver, cur=cur) if approver else []
                if not _normal_dashboard_operator(approver) or "employees.status.approve" not in approver_permissions:
                    raise HTTPException(status_code=403, detail={"error": "approver_permission_denied", "message": "The approver is not authorized for employee status changes."})

                cur.execute(
                    "SELECT pg_advisory_xact_lock(hashtextextended(%s, 0))",
                    (f"employee-status:{company}:{idempotency_key}",),
                )
                cur.execute(
                    "SELECT * FROM employee_status_changes WHERE company_code=%s AND idempotency_key=%s FOR UPDATE",
                    (company, idempotency_key),
                )
                existing = cur.fetchone()
                if existing:
                    committed_change = dict(existing)
                    if committed_change["request_hash"] != request_hash:
                        raise HTTPException(status_code=409, detail={"error": "idempotency_conflict", "message": "This request key was already used for a different status change."})
                else:
                    cur.execute(
                        "SELECT * FROM employees WHERE company_code=%s AND employee_key=%s FOR UPDATE",
                        (company, str(employee_key)),
                    )
                    before = dict(cur.fetchone() or {})
                    if not before:
                        raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})
                    previous_status = _canonical_employee_status(before.get("employment_status"))
                    if previous_status != request.expected_status or before.get("updated_at") != request.expected_updated_at:
                        raise HTTPException(status_code=409, detail={"error": "employee_version_conflict", "message": "This employee changed after the status form was opened."})
                    if previous_status == request.status and str(before.get("employment_status") or "").strip().lower() == request.status:
                        raise HTTPException(status_code=409, detail={"error": "employee_status_unchanged", "message": "This employee already has that status."})

                    cur.execute(
                        """
                        UPDATE employees
                        SET employment_status=%s, updated_at=clock_timestamp()
                        WHERE company_code=%s AND employee_key=%s
                        RETURNING *
                        """,
                        (request.status, company, str(employee_key)),
                    )
                    after = dict(cur.fetchone())
                    changed_fields = sorted(
                        key for key in set(before) | set(after)
                        if before.get(key) != after.get(key)
                    )
                    if set(changed_fields) != {"employment_status", "updated_at"}:
                        raise RuntimeError("employee_status_changed_unapproved_fields")
                    if _canonical_employee_status(after.get("employment_status")) != request.status:
                        raise RuntimeError("employee_status_transaction_validation_failed")

                    if request.status == "left":
                        cur.execute(
                            """
                            UPDATE employee_sessions
                            SET status='revoked', refresh_hash=NULL, revoked_at=now(),
                                revoked_reason='offboarded',
                                expires_at=LEAST(expires_at, now()),
                                refresh_expires_at=LEAST(refresh_expires_at, now())
                            WHERE company_code=%s AND employee_key=%s AND status='active'
                            """,
                            (company, str(employee_key)),
                        )
                        cur.execute(
                            "UPDATE employee_push_tokens SET active=false, updated_at=now() WHERE company_code=%s AND employee_key=%s AND active IS TRUE",
                            (company, str(employee_key)),
                        )

                    audit = write_admin_audit(
                        cur,
                        _permission_operator_context(requester, requester_permissions),
                        "employee_marked_left" if request.status == "left" else "employee_reactivated",
                        summary="Changed an employee's authoritative employment status.",
                        target_type="employee",
                        target=str(employee_key),
                        details={
                            "previous_status": previous_status,
                            "requested_status": request.status,
                            "requester_user_id": requester_user_id,
                            "approver_user_id": approver_user_id,
                            "reason": request.reason.strip(),
                            "approval_reference": request.approval_reference.strip(),
                            "approval_mode": request.approval_mode,
                            "changed_fields": changed_fields,
                            "idempotency_key": idempotency_key,
                        },
                    )
                    cur.execute(
                        """
                        INSERT INTO employee_status_changes
                          (company_code, employee_key, idempotency_key, request_hash,
                           previous_status, requested_status, previous_updated_at,
                           resulting_updated_at, requester_user_id, approver_user_id,
                           reason, approval_reference, approval_mode, changed_fields,
                           action_result_id, operation_status, verification_status)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                                'committed','pending')
                        RETURNING *
                        """,
                        (
                            company,
                            str(employee_key),
                            idempotency_key,
                            request_hash,
                            previous_status,
                            request.status,
                            before["updated_at"],
                            after["updated_at"],
                            requester_user_id,
                            approver_user_id,
                            request.reason.strip(),
                            request.approval_reference.strip(),
                            request.approval_mode,
                            Json(changed_fields),
                            audit["result_id"],
                        ),
                    )
                    committed_change = dict(cur.fetchone())
            conn.commit()
        except Exception:
            conn.rollback()
            raise

    return _verify_committed_employee_status_change(company, idempotency_key, committed_change)


@app.post("/dashboard/posthire/employees/{employee_key}/status")
def dashboard_posthire_set_employee_status(
    employee_key: str,
    request: DashboardEmployeeStatus,
    context: dict[str, Any] = Depends(dashboard_context),
):
    company = require_employee_roster_admin(context, "employees.manage")
    require_employee_mutation_scope(context, employee_key, company_code=company, action="employee_status")
    if request.approval_mode == "self_approved_internal_canary" and not employee_status_canary_allowed(company):
        record_admin_audit(
            context,
            "employee_mutation_denied",
            summary="Denied employee status canary outside allowlisted company/environment.",
            target_type="employee",
            target=str(employee_key),
            details={
                "action": "employee_status",
                "reason": "canary_not_allowed",
                "approval_mode": request.approval_mode,
                "company_code": company,
                "environment": employee_status_runtime_env(),
            },
            status="denied",
        )
        raise HTTPException(
            status_code=403,
            detail={
                "error": "canary_not_allowed",
                "message": "Self-approved internal canary is not enabled for this company or environment. Use the two-person approval request flow.",
                "company_code": company,
                "environment": employee_status_runtime_env(),
            },
        )
    if request.approval_mode == "separate_approval":
        raise HTTPException(
            status_code=422,
            detail={
                "error": "use_status_approval_request",
                "message": "Separate approval must use the pending status-approval request flow, not direct status commit.",
            },
        )
    return transition_employee_employment_status(context, employee_key, request)


