class DashboardEmployeeEssRequestCreate(BaseModel):
    employee_key: str
    request_type: str
    proposed_values: dict[str, Any] = Field(default_factory=dict)
    idempotency_key: str = Field(min_length=8, max_length=200)
    requester_kind: str = "employee"
