def _require_bank_read(context: dict[str, Any], employee_key: str) -> tuple[str, bool]:
    """HR-side bank access: read permission + tenant/manager scope."""
    company = str(context.get("company_code") or "").upper()
    import employee_bank_ess as _bank

    if not _bank.bank_ess_enabled(company):
        raise HTTPException(status_code=403, detail={"error": "bank_ess_disabled"})
    can_read = (
        dashboard_context_has_permission(context, "employees.read")
        or dashboard_context_has_permission(context, "employees.manage")
    )
    if not can_read:
        raise HTTPException(status_code=403, detail={"error": "bank_review_denied"})
    # Employee must exist inside the caller's tenant, else 404 (no existence leak).
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM employees WHERE company_code=%s AND employee_key=%s LIMIT 1",
                (company, employee_key),
            )
            found = cur.fetchone()
        conn.commit()
    if not found:
        raise HTTPException(status_code=404, detail={"error": "employee_not_found"})
    can_unmask = (
        dashboard_context_has_permission(context, "employees.ess.unmask")
        or dashboard_context_has_permission(context, "employees.manage")
    )
    return company, bool(can_unmask)


