@app.get("/dashboard/posthire/employees/{employee_key}/onboarding-completion")
def dashboard_employee_onboarding_completion(
    employee_key: str,
    locale: str = "en",
    context: dict[str, Any] = Depends(dashboard_context),
):
    """Canonical onboarding completion state + transition history."""
    company = str(context.get("company_code") or "").upper()
    if not (
        dashboard_context_has_permission(context, "employees.read")
        or dashboard_context_has_permission(context, "employees.manage")
    ):
        raise HTTPException(status_code=403, detail={"error": "onboarding_read_denied"})
    import onboarding_completion_contract as _completion

    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM employees WHERE company_code=%s AND employee_key=%s LIMIT 1",
                (company, employee_key),
            )
            if not cur.fetchone():
                raise HTTPException(status_code=404, detail={"error": "employee_not_found"})
            _completion.ensure_completion_schema(cur)
            snapshot = _completion.recompute(cur, employee_key=employee_key, company_code=company)
            snapshot["next_action"] = _completion.next_action(snapshot, locale=locale)
            snapshot["history"] = _completion.completion_history(
                cur, employee_key=employee_key, company_code=company
            )
        conn.commit()
    return json_safe(snapshot)


