LEAVE_HISTORY_STATUSES = set(_leave_authority.LEAVE_HISTORY_STATUSES_W1)


def _leave_balances_for_rows(company: str, *row_lists: list[dict[str, Any]]) -> dict[str, Any]:
    """Read-only leave balances (dark-launched) for the employees in the given
    rows. Observe-only presets pending legal review; never enforced."""
    if not leave_balances_enabled():
        return {}
    keys = {str(r.get("employee_key")) for rows in row_lists for r in rows if r.get("employee_key")}
    return {k: leave_balances_for_employee(company, k) for k in keys}


def _leave_honesty_payload() -> dict[str, Any]:
    base = _leave_authority.honesty_balance_flags()
    base["wave4_enabled"] = _leave_w4.leave_wave4_enabled()
    base["real_decision_gate"] = _leave_w4.leave_real_decision_gate_enabled()
    base["leave_wave4_version"] = _leave_w4.LEAVE_WAVE4_VERSION
    return base


def _enrich_leave_rows_for_ui(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if not _leave_w4.leave_wave4_enabled():
        return rows
    return [_leave_w4.enrich_leave_row_for_ui(r, as_of=kuwait_today()) for r in rows]


@app.get("/dashboard/posthire/leave")
def dashboard_posthire_leave(
    view: str = Query("active"),
    status: str | None = Query(None),
    section: str | None = Query(None),
    offset: int = Query(0),
    limit: int = Query(50),
    context: dict[str, Any] = Depends(dashboard_context),
):
    company = _posthire_read_context(context, "leave")
    viewer_phone = context.get("hr_phone")

    holiday_status: dict[str, Any] = {}
    if _leave_w4.leave_wave4_enabled():
        try:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    _leave_w4.ensure_leave_wave4_schema(cur)
                    holiday_status = _leave_w4.holiday_year_status_payload(cur, year=kuwait_today().year)
                conn.commit()
        except Exception:
            holiday_status = {"status": "unknown", "fail_closed_if_enforced": True, "enforced": False}

    # History view: decided/past leave over a wide window. Same source of truth,
    # same manager scope; HR keeps pending/upcoming as the default focus. Paged so
    # a company with a long history isn't silently truncated — rows arrive
    # recent-first from SQL, so "load more" appends older pages in order.
    if str(view).strip().lower() == "history":
        hist_start, hist_end = _posthire_window(180, 30)
        status_norm = str(status or "").strip().lower()
        result = list_leave_requests(
            {
                "company_code": company,
                "status": status_norm if status_norm in LEAVE_HISTORY_STATUSES else "",
                "start_date": hist_start,
                "end_date": hist_end,
                "viewer_phone": viewer_phone,
                "order": "recent",
                "limit": limit,
                "offset": offset,
                "history": True,
            },
            company_code=company,
        )
        rows = _enrich_leave_rows_for_ui(result.get("leave_requests") or [])
        return json_safe({
            "company_code": company,
            "view": "history",
            "history": rows,
            "status_filter": status_norm if status_norm in LEAVE_HISTORY_STATUSES else None,
            "balances_enabled": leave_balances_enabled(),
            "holiday_year": holiday_status,
            **_leave_honesty_payload(),
            "history_total": result.get("total_count", len(rows)),
            "history_has_more": result.get("has_more", False),
            "offset": result.get("offset", offset),
            "limit": result.get("limit", limit),
        })

    start, end = _posthire_window(7, 60)
    section_norm = str(section or "").strip().lower()

    # Load-more for a single active-view section (pending or upcoming) so each
    # list pages independently without disturbing the other.
    if section_norm in ("pending", "upcoming"):
        status_for = "requested" if section_norm == "pending" else "approved"
        res = list_leave_requests(
            {"company_code": company, "status": status_for, "start_date": start, "end_date": end, "viewer_phone": viewer_phone, "limit": limit, "offset": offset},
            company_code=company,
        )
        rows = _enrich_leave_rows_for_ui(res.get("leave_requests") or [])
        return json_safe({
            "company_code": company,
            "view": "active",
            "section": section_norm,
            section_norm: rows,
            "balances_enabled": leave_balances_enabled(),
            "holiday_year": holiday_status,
            **_leave_honesty_payload(),
            "balances": _leave_balances_for_rows(company, rows),
            f"{section_norm}_total": res.get("total_count", len(rows)),
            f"{section_norm}_has_more": res.get("has_more", False),
            "offset": res.get("offset", offset),
            "limit": res.get("limit", limit),
        })

    # Initial active load: first page of each section.
    pending = list_leave_requests({"company_code": company, "status": "requested", "start_date": start, "end_date": end, "viewer_phone": viewer_phone, "limit": limit}, company_code=company)
    upcoming = list_leave_requests({"company_code": company, "status": "approved", "start_date": start, "end_date": end, "viewer_phone": viewer_phone, "limit": limit}, company_code=company)
    pending_rows = _enrich_leave_rows_for_ui(pending.get("leave_requests") or [])
    upcoming_rows = _enrich_leave_rows_for_ui(upcoming.get("leave_requests") or [])
    payload = {
        "company_code": company,
        "view": "active",
        "pending": pending_rows,
        "upcoming": upcoming_rows,
        "balances_enabled": leave_balances_enabled(),
        "holiday_year": holiday_status,
        **_leave_honesty_payload(),
        "balances": _leave_balances_for_rows(company, pending_rows, upcoming_rows),
        "pending_total": pending.get("total_count", len(pending_rows)),
        "pending_has_more": pending.get("has_more", False),
        "upcoming_total": upcoming.get("total_count", len(upcoming_rows)),
        "upcoming_has_more": upcoming.get("has_more", False),
        "limit": limit,
    }
    return json_safe(payload)


@app.get("/dashboard/posthire/shifts")
def dashboard_posthire_shifts(
    week: int = Query(0),
    offset: int = Query(0),
    limit: int = Query(100),
    employee: str | None = Query(None),
    branch_key: str | None = Query(None),
    site_key: str | None = Query(None),
    team_key: str | None = Query(None),
    role: str | None = Query(None),
    view: str = Query("week"),
    context: dict[str, Any] = Depends(dashboard_context),
):
    company = _posthire_read_context(context, "shifts")
    # week is a 7-day window offset from today (0 = current week, +/- for nav).
    # view=day uses a single day inside that week (offset days within week via `week` still).
    week = max(-26, min(26, int(week or 0)))
    base = kuwait_today() + timedelta(days=7 * week)
    if str(view or "week").lower() == "day":
        start, end = base.isoformat(), base.isoformat()
    else:
        start, end = base.isoformat(), (base + timedelta(days=6)).isoformat()
    viewer_phone = context.get("hr_phone")
    # Pass explicit start/end (no relative "query") so the window honors the offset.
    # limit/offset let the calendar page through a busy week instead of silently
    # dropping shifts past the 100th row; swaps are naturally small and unpaged.
    shifts = list_shifts(
        {"company_code": company, "start_date": start, "end_date": end, "viewer_phone": viewer_phone, "limit": limit, "offset": offset},
        company_code=company,
    )
    swaps = list_shift_swaps({"company_code": company, "status": "requested", "viewer_phone": viewer_phone, "limit": 200}, company_code=company)
    shift_rows = list(shifts.get("shifts") or [])
    # Client-side filters mirrored server-side for scoped managers / busy tenants.
    emp_q = str(employee or "").strip().lower()
    if emp_q:
        shift_rows = [
            s for s in shift_rows
            if emp_q in str(s.get("employee_name") or "").lower()
            or emp_q in str(s.get("employee_key") or "").lower()
            or emp_q in str(s.get("employee_phone") or "")
        ]
    if branch_key:
        shift_rows = [s for s in shift_rows if str(s.get("branch_key") or "") == str(branch_key)]
    if site_key:
        shift_rows = [s for s in shift_rows if str(s.get("site_key") or "") == str(site_key)]
    if team_key:
        shift_rows = [s for s in shift_rows if str(s.get("team_key") or "") == str(team_key)]
    if role:
        shift_rows = [s for s in shift_rows if str(s.get("role") or s.get("position_key") or "") == str(role)]

    availability_rows: list[dict[str, Any]] = []
    recon_flags: list[dict[str, Any]] = []
    terminal_reminders: list[dict[str, Any]] = []
    wave3_on = _shifts_w3.shifts_wave3_enabled_for_company(company)
    if wave3_on:
        with db_connect() as conn:
            with conn.cursor() as cur:
                if _shifts_w2.shifts_wave2_enabled_for_company(company):
                    _shifts_w2.ensure_shifts_integrity_wave2_schema(cur)
                    cur.execute(
                        """
                        SELECT * FROM employee_availability_requests
                        WHERE company_code=%s AND status='requested'
                        ORDER BY created_at DESC NULLS LAST
                        LIMIT 100
                        """,
                        (company,),
                    )
                    availability_rows = [dict(r) for r in cur.fetchall()]
                    cur.execute(
                        """
                        SELECT * FROM shift_reconciliation_flags
                        WHERE company_code=%s AND status='open'
                        ORDER BY created_at DESC
                        LIMIT 100
                        """,
                        (company,),
                    )
                    recon_flags = [dict(r) for r in cur.fetchall()]
                    terminal_reminders = _shifts_w2.filter_reminders_synthetic_only(
                        _shifts_w2.list_terminal_reminder_failures(cur, company_code=company, limit=50)
                    ) if not _shifts_w3.real_reminders_enabled() else _shifts_w2.list_terminal_reminder_failures(
                        cur, company_code=company, limit=50
                    )
                # Scope availability/recon to manager when scoped
                allowed = context_manager_employee_keys(context, company)
                if allowed is not None:
                    availability_rows = [a for a in availability_rows if str(a.get("employee_key") or "") in allowed]
                    recon_flags = [f for f in recon_flags if str(f.get("employee_key") or "") in allowed]
        shift_rows = [_shifts_w3.enrich_shift_row_for_ui(s, open_flags=recon_flags) for s in shift_rows]

    actor = viewer_phone
    return json_safe({
        "company_code": company,
        "shifts": shift_rows,
        "swaps": swaps.get("swaps") or [],
        "availability": availability_rows,
        "reconciliation_flags": recon_flags,
        "terminal_reminders": terminal_reminders,
        "start_date": start,
        "end_date": end,
        "week": week,
        "view": "day" if str(view or "").lower() == "day" else "week",
        "total_count": shifts.get("total_count", len(shift_rows)),
        "limit": shifts.get("limit", limit),
        "offset": shifts.get("offset", offset),
        "has_more": shifts.get("has_more", False),
        "wave3": {
            "enabled": wave3_on,
            "version": _shifts_w3.SHIFTS_WAVE3_VERSION,
            "actor_hr_allowlisted": _shifts_w3.actor_is_hr_allowlisted(actor),
            "actor_manager_allowlisted": _shifts_w3.actor_is_manager_allowlisted(actor),
            "real_mutation_gate": _shifts_w3.real_mutation_gate_enabled(),
            "can_mutate_real": (
                (not _shifts_w3.real_mutation_gate_enabled())
                or _shifts_w3.actor_allowlisted_for_real_mutation(actor)
            ),
            "permission_matrix": _shifts_w3.permission_matrix(),
            **_shifts_w3.honesty_payload(),
        } if wave3_on else {"enabled": False},
        "wave4": {
            "enabled": _shifts_templates_w4.shifts_wave4_enabled_for_company(company),
            "version": _shifts_templates_w4.SHIFTS_WAVE4_VERSION,
            **_shifts_templates_w4.honesty_payload(),
        },
        "wave5": {
            "enabled": _shifts_publish_w5.shifts_wave5_enabled_for_company(company),
            "version": _shifts_publish_w5.SHIFTS_WAVE5_VERSION,
            "permission_matrix": _shifts_publish_w5.permission_matrix(),
            **_shifts_publish_w5.honesty_payload(),
        },
        "wave6": {
            "enabled": _shifts_enterprise_w6.shifts_wave6_enabled_for_company(company),
            "version": _shifts_enterprise_w6.SHIFTS_WAVE6_VERSION,
            "permission_matrix": _shifts_enterprise_w6.permission_matrix(),
            **_shifts_enterprise_w6.honesty_payload(),
        },
        "notifications_wave6b": {
            "enabled": _shifts_notify_w6b.shifts_notifications_wave6b_enabled_for_company(company),
            "version": _shifts_notify_w6b.SHIFTS_NOTIFICATIONS_WAVE6B_VERSION,
            **_shifts_notify_w6b.honesty_payload(),
        },
        "controlled_wave6c": {
            "enabled": _shifts_controlled_w6c.shifts_wave6c_enabled_for_company(company),
            "version": _shifts_controlled_w6c.SHIFTS_WAVE6C_VERSION,
            "permission_matrix": _shifts_controlled_w6c.permission_matrix(),
            **_shifts_controlled_w6c.honesty_payload(),
        },
    })


def shifts_wave6c_sender_factory(cur: Any) -> Any:
    """Bind Wave 6C controlled delivery to the real production transports.

    `app` writes an inbox row that /app/notifications already renders; it never leaves the
    platform, so real_sent stays false. `email` is the one approved external channel and
    goes through the same Postmark/Gmail path every other employee-facing email uses.
    Channels that Wave 6C has not qualified report `unsupported` rather than silently
    falling through to some other transport.
    """

    def _send(*, channel: str, company_code: str, employee_key: str, event: dict[str, Any], recipient_ref: str | None = None) -> dict[str, Any]:
        ch = str(channel).lower()
        payload = event.get("payload") or {}
        if isinstance(payload, str):
            try:
                payload = json.loads(payload)
            except Exception:
                payload = {}
        event_type = str(event.get("event_type") or "shift_notification")
        headline = str(payload.get("headline") or payload.get("summary") or event_type.replace("_", " ").title())
        body = str(payload.get("body") or payload.get("message") or headline)
        correlation = f"w6c|{ch}|{uuid.uuid4().hex[:12]}"

        if ch == "app":
            message_id = str(uuid.uuid4())
            cur.execute(
                """
                INSERT INTO employee_messages
                  (message_id, company_code, employee_key, flow, template_key, criticality,
                   sensitivity, locale, status, body_preview, dedupe_key, metadata)
                VALUES (%s,%s,%s,'shift',%s,'standard','preview','en','pending',%s,%s,%s)
                """,
                (
                    message_id,
                    str(company_code).upper(),
                    str(employee_key),
                    f"shift_{event_type}",
                    headline[:280],
                    f"w6c:{event.get('dedupe_key')}",
                    Json({
                        "outbound_mode": "inbox_only",
                        "shift_notification_event_id": str(event.get("event_id")),
                        "wave": "6C",
                    }),
                ),
            )
            return {
                "ok": True,
                "status": "delivered",
                "provider": "wathefni_inbox",
                "provider_message_id": message_id,
                "correlation_id": correlation,
                "real_sent": False,
                "receipt": {"surface": "app_notifications", "message_id": message_id},
            }

        if ch == "email":
            recipient = (recipient_ref or "").strip()
            if not recipient:
                cur.execute(
                    "SELECT email FROM employees WHERE company_code=%s AND employee_key=%s LIMIT 1",
                    (str(company_code).upper(), str(employee_key)),
                )
                row = cur.fetchone()
                recipient = str((row or {}).get("email") if isinstance(row, dict) else (row[0] if row else "") or "").strip()
            if not recipient:
                return {
                    "ok": False,
                    "status": "failed",
                    "error_code": "no_recipient_email",
                    "error_detail": "No consented email destination for recipient.",
                    "provider": "email",
                    "correlation_id": correlation,
                    "real_sent": False,
                }
            result = send_outbound_email(
                to=recipient,
                subject=f"[OctoHR] {headline}",
                body=body,
                company_code=str(company_code).upper(),
                subject_type="employee",
                subject_key=str(employee_key),
                message_kind="email",
                purpose="shift_notification",
            )
            sent_for_real = bool(result.get("ok")) and not bool(result.get("dry_run"))
            return {
                "ok": bool(result.get("ok")),
                "status": "delivered" if result.get("ok") else "failed",
                "provider": str(result.get("provider") or "email"),
                "provider_message_id": result.get("message_id") or result.get("MessageID"),
                "correlation_id": correlation,
                "error_code": None if result.get("ok") else str(result.get("error") or "email_failed"),
                "error_detail": None if result.get("ok") else json.dumps(json_safe(result))[:500],
                "real_sent": sent_for_real,
                "receipt": json_safe(result),
            }

        return {
            "ok": False,
            "status": "unsupported",
            "error_code": "channel_not_qualified",
            "error_detail": f"Wave 6C has not qualified channel {ch}.",
            "provider": "none",
            "correlation_id": correlation,
            "real_sent": False,
        }

    return _send


class ShiftCreateRequest(BaseModel):
    """Canonical dashboard create body for Shifts Wave 3B+ (composer / roster)."""

    employee_name: str | None = None
    employee_key: str | None = None
    employee_phone: str | None = None
    shift_date: str
    start_time: str
    end_time: str
    site_key: str | None = None
    branch_key: str | None = None
    team_key: str | None = None
    role: str | None = None
    location: str | None = None
    assignment_type: str | None = None
    reason: str | None = None
    acknowledge_availability: bool = False
    ack_availability_conflict: bool = False
    allow_leave_conflicts: bool = False
    confirm_overlap: bool = False


@app.post("/dashboard/posthire/shifts")
def dashboard_posthire_create_shift(
    request: ShiftCreateRequest,
    context: dict[str, Any] = Depends(dashboard_context),
):
    """Canonical create path for the Calendar-aligned Shifts composer.

    Replaces ad-hoc POST /dashboard/posthire/actions (plural, unsupported).
    Uses the same domain authority as create_shift_assignment + Wave 3 gates.
    """
    require_entitlement(context, "shifts", "shifts.manage")
    company = context["company_code"]
    actor_phone = context.get("hr_phone")
    shift_date = _coerce_employee_start_date(request.shift_date)
    start_clock = _parse_clock(request.start_time)
    end_clock = _parse_clock(request.end_time)
    if not shift_date or not start_clock or not end_clock:
        raise HTTPException(
            status_code=422,
            detail={"error": "invalid_shift", "message": "Enter a valid date, start time, and end time."},
        )
    action: dict[str, Any] = {
        "employee_name": request.employee_name,
        "employee_key": request.employee_key,
        "employee_phone": request.employee_phone,
        "date": shift_date.isoformat() if hasattr(shift_date, "isoformat") else str(shift_date),
        "shift_date": shift_date.isoformat() if hasattr(shift_date, "isoformat") else str(shift_date),
        "start_time": start_clock,
        "end_time": end_clock,
        "site_key": request.site_key,
        "branch_key": request.branch_key,
        "team_key": request.team_key,
        "role": request.role,
        "location": request.location,
        "assignment_type": request.assignment_type,
        "reason": request.reason,
        "reason_note": request.reason,
        "acknowledge_availability": request.acknowledge_availability or request.ack_availability_conflict,
        "ack_availability_conflict": request.acknowledge_availability or request.ack_availability_conflict,
        "allow_leave_conflicts": request.allow_leave_conflicts,
        "confirm_overlap": request.confirm_overlap,
        "viewer_phone": actor_phone,
        "source_text": "dashboard_shifts_composer",
    }
    # Resolve employee early for scope + synthetic gate + audit reason rules.
    employees = resolve_shift_employees(action, company_code=company, required=True)
    if not employees:
        resolution = action.get("_employee_resolution") if isinstance(action.get("_employee_resolution"), dict) else {}
        if resolution.get("status") == "ambiguous":
            raise HTTPException(
                status_code=409,
                detail={
                    "error": "ambiguous_employee",
                    "message": "Multiple employees match. Choose a more specific name or key.",
                    "choices": resolution.get("choices") or [],
                },
            )
        raise HTTPException(status_code=404, detail={"error": "employee_not_found", "message": "We couldn't find that employee."})
    employee = employees[0]
    allowed = context_manager_employee_keys(context, company)
    if allowed is not None and str(employee.get("employee_key")) not in allowed:
        raise HTTPException(status_code=403, detail={"error": "out_of_scope", "message": "That employee is outside the team you manage."})
    synth = _shifts_subject_is_synthetic(employee, employee_key=employee.get("employee_key"), phone=employee.get("phone"))
    denied = _shifts_w3.real_mutation_denied(actor_phone=actor_phone, is_synthetic_subject=synth, company_code=company)
    if denied:
        raise HTTPException(status_code=403, detail=denied)
    if _shifts_w3.shifts_wave3_enabled_for_company(company) and not synth:
        reason_denied = _shifts_w3.require_audit_reason(request.reason)
        if reason_denied:
            raise HTTPException(status_code=422, detail=reason_denied)

    result = create_shift_assignment(action, company_code=company, created_by_phone=actor_phone)
    if not result.get("ok"):
        err = str(result.get("error") or "create_failed")
        status = 409
        if err in {"employee_not_found", "missing_shift_date", "invalid_shift_time_range", "invalid_break_minutes"}:
            status = 422
        if err in {"shifts_real_mutation_not_allowlisted", "permission_denied", "out_of_scope", "employee_outside_manager_scope"}:
            status = 403
        if result.get("needs_confirmation") or err in {
            "availability_conflict_requires_ack",
            "leave_conflict_requires_ack",
            "seasonal_policy_requires_ack",
        }:
            status = 409
        raise HTTPException(status_code=status, detail=json_safe(result))

    created_rows = list(result.get("created") or [])
    shift = created_rows[0] if created_rows else (result.get("shift") if isinstance(result.get("shift"), dict) else None)
    if shift and _shifts_w3.shifts_wave3_enabled_for_company(company):
        shift = _shifts_w3.enrich_shift_row_for_ui(shift)
    name = (employee.get("name") if employee else None) or (shift or {}).get("employee_name") or "The employee"
    record_admin_audit(
        context,
        "shift_created",
        summary=f"Scheduled a shift for {name} on {action.get('shift_date')}.",
        target_type="employee",
        target=employee.get("employee_key") if employee else None,
        details={
            "shift_id": str((shift or {}).get("shift_id") or ""),
            "shift_date": str(action.get("shift_date")),
            "start_time": start_clock,
            "end_time": end_clock,
            "reason": request.reason,
            "source": "dashboard_posthire_create_shift",
        },
    )
    return json_safe(
        {
            "ok": True,
            "status": "created",
            "message": f"{name}'s shift was scheduled.",
            "shift": shift,
            "created": created_rows,
            "warnings": result.get("warnings") or result.get("wave2_warnings") or [],
            "wave3": _shifts_w3.honesty_payload() if _shifts_w3.shifts_wave3_enabled_for_company(company) else {},
        }
    )


def _parse_clock(value: Any) -> str | None:
    text = str(value or "").strip()
    if not text:
        return None
    for fmt in ("%H:%M", "%H:%M:%S"):
        try:
            return datetime.strptime(text, fmt).strftime("%H:%M")
        except ValueError:
            continue
    return None


def _dashboard_scheduled_shift_or_error(company_code: str, shift_id: str, context: dict[str, Any]) -> dict[str, Any]:
    """Resolve a scheduled shift by id, company-scoped AND manager-scoped. Raises
    404 (unknown/other tenant), 403 (outside the viewer's managed team), or 409
    (no longer scheduled) so cancel/reschedule can never touch the wrong row."""
    try:
        uuid.UUID(str(shift_id))
    except (ValueError, AttributeError, TypeError):
        raise HTTPException(status_code=404, detail={"error": "shift_not_found", "message": "We couldn't find that shift."})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM shift_assignments WHERE shift_id=%s AND company_code=%s LIMIT 1", (str(shift_id), company_code))
            row = cur.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail={"error": "shift_not_found", "message": "We couldn't find that shift."})
    shift = dict(row)
    allowed = context_manager_employee_keys(context, company_code)
    if allowed is not None and str(shift.get("employee_key")) not in allowed:
        raise HTTPException(status_code=403, detail={"error": "out_of_scope", "message": "That shift is outside the team you manage."})
    if str(shift.get("status")) != "scheduled":
        raise HTTPException(status_code=409, detail={"error": "not_scheduled", "message": "That shift is no longer active."})
    return shift


def _employee_for_shift(shift: dict[str, Any], company_code: str) -> dict[str, Any]:
    return find_employee_by_key(shift.get("employee_key"), company_code=company_code) or {
        "employee_key": shift.get("employee_key"),
        "name": shift.get("employee_name"),
        "phone": shift.get("employee_phone"),
    }


class ShiftCancelRequest(BaseModel):
    expected_updated_at: str | None = None
    reason: str | None = None
    reason_code: str | None = "cancelled"


@app.post("/dashboard/posthire/shifts/{shift_id}/cancel")
def dashboard_posthire_cancel_shift(
    shift_id: str,
    request: ShiftCancelRequest = ShiftCancelRequest(),
    context: dict[str, Any] = Depends(dashboard_context),
):
    require_entitlement(context, "shifts", "shifts.manage")
    company = context["company_code"]
    current = _dashboard_scheduled_shift_or_error(company, shift_id, context)
    actor_phone = context.get("hr_phone")
    emp = _employee_for_shift(current, company)
    synth = _shifts_subject_is_synthetic(emp, employee_key=current.get("employee_key"), phone=current.get("employee_phone"))
    denied = _shifts_w3.real_mutation_denied(actor_phone=actor_phone, is_synthetic_subject=synth, company_code=company)
    if denied:
        raise HTTPException(status_code=403, detail=denied)
    body = request
    if _shifts_w3.shifts_wave3_enabled_for_company(company) and not synth:
        reason_denied = _shifts_w3.require_audit_reason(body.reason)
        if reason_denied:
            raise HTTPException(status_code=422, detail=reason_denied)
        if not str(body.expected_updated_at or "").strip():
            raise HTTPException(status_code=422, detail={"error": "expected_updated_at_required", "message": "Refresh the shift and confirm the current version before cancelling."})
        current_updated = current.get("updated_at")
        current_iso = current_updated.isoformat() if hasattr(current_updated, "isoformat") else str(current_updated or "")
        expected = str(body.expected_updated_at).strip()
        accepted = {current_iso, current_iso.replace("+00:00", "Z"), current_iso.replace("Z", "+00:00"), current_iso.replace("+00:00", "")}
        if expected not in accepted:
            raise HTTPException(status_code=409, detail={"error": "stale_state", "message": "That shift changed. Refresh and try again."})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE shift_assignments
                SET status='cancelled', updated_at=now(),
                    schedule_reason_code=COALESCE(%s, schedule_reason_code)
                WHERE shift_id=%s AND company_code=%s AND status='scheduled'
                RETURNING *
                """,
                (str(body.reason_code or "cancelled"), str(shift_id), company),
            )
            row = cur.fetchone()
            if not row:
                conn.commit()
                raise HTTPException(status_code=409, detail={"error": "not_scheduled", "message": "That shift is no longer active."})
            cancelled = dict(row)
            _shifts_templates_w4.mark_assignment_detached(cur, company_code=company, shift_id=cancelled.get("shift_id"))
            record_shift_event(
                cur,
                shift=cancelled,
                company_code=company,
                event_type="cancelled",
                payload={"shift": cancelled, "source": "dashboard", "reason": body.reason, "reason_code": body.reason_code},
                created_by_phone=actor_phone,
            )
            if _shifts_w2_applies(company, emp):
                _shifts_w2.ensure_shifts_integrity_wave2_schema(cur)
                _shifts_w2.record_assignment_version(
                    cur,
                    company_code=company,
                    shift=cancelled,
                    reason_code=str(body.reason_code or "cancelled"),
                    actor_phone=actor_phone,
                    reason_note=body.reason,
                )
        conn.commit()
    employee = _employee_for_shift(cancelled, company)
    notified = False
    try:
        notification = notify_employee_shift_cancelled(result={"employee": employee, "cancelled": [cancelled]}, account_id=company, created_by_phone=actor_phone)
        notified = bool(notification.get("ok"))
    except Exception:
        logger.warning("dashboard shift cancel notification failed", exc_info=True)
    record_admin_audit(
        context,
        "shift_cancelled",
        summary=f"Cancelled {cancelled.get('employee_name') or 'an employee'}'s shift on {cancelled.get('shift_date')}.",
        target_type="employee",
        target=cancelled.get("employee_key"),
        details={"shift_id": str(shift_id), "shift_date": str(cancelled.get("shift_date")), "reason": body.reason},
    )
    name = cancelled.get("employee_name") or "The employee"
    return json_safe({"ok": True, "status": "cancelled", "message": f"{name}'s shift was cancelled.", "shift": cancelled, "notified": notified})


class ShiftRescheduleRequest(BaseModel):
    shift_date: str
    start_time: str
    end_time: str
    expected_updated_at: str
    confirm_overlap: bool = False
    allow_leave_conflicts: bool = False
    acknowledge_availability: bool = False
    reason: str | None = None
    reason_code: str | None = "rescheduled"


@app.post("/dashboard/posthire/shifts/{shift_id}/reschedule")
def dashboard_posthire_reschedule_shift(shift_id: str, request: ShiftRescheduleRequest, context: dict[str, Any] = Depends(dashboard_context)):
    require_entitlement(context, "shifts", "shifts.manage")
    company = context["company_code"]
    new_date = _coerce_employee_start_date(request.shift_date)
    start_clock = _parse_clock(request.start_time)
    end_clock = _parse_clock(request.end_time)
    if not new_date or not start_clock or not end_clock:
        raise HTTPException(status_code=422, detail={"error": "invalid_shift", "message": "Enter a valid date, start time, and end time."})
    ends_next = False
    current = _dashboard_scheduled_shift_or_error(company, shift_id, context)
    emp_preview = find_employee_by_key(current.get("employee_key"), company_code=company) or _employee_for_shift(current, company)
    actor_phone = context.get("hr_phone")
    synth = _shifts_subject_is_synthetic(emp_preview, employee_key=current.get("employee_key"), phone=current.get("employee_phone"))
    denied = _shifts_w3.real_mutation_denied(actor_phone=actor_phone, is_synthetic_subject=synth, company_code=company)
    if denied:
        raise HTTPException(status_code=403, detail=denied)
    if _shifts_w3.shifts_wave3_enabled_for_company(company) and not synth:
        reason_denied = _shifts_w3.require_audit_reason(request.reason)
        if reason_denied:
            raise HTTPException(status_code=422, detail=reason_denied)
    wave1_subject = _shifts_authority.shifts_authority_applies_to(company, emp_preview)
    if end_clock <= start_clock:
        overnight_allowed = (
            _shifts_authority.shifts_wave1_enabled()
            and _shifts_authority.allow_overnight()
            and wave1_subject
        )
        if not overnight_allowed:
            raise HTTPException(status_code=422, detail={"error": "invalid_shift", "message": "The end time must be after the start time."})
        ends_next = True
    if not str(request.expected_updated_at or "").strip():
        raise HTTPException(status_code=422, detail={"error": "expected_updated_at_required", "message": "Refresh the shift and confirm the current version before rescheduling."})
    current_updated = current.get("updated_at")
    current_iso = current_updated.isoformat() if hasattr(current_updated, "isoformat") else str(current_updated or "")
    expected = str(request.expected_updated_at).strip()
    accepted = {
        current_iso,
        current_iso.replace("+00:00", "Z"),
        current_iso.replace("Z", "+00:00"),
        current_iso.replace("+00:00", ""),
    }
    if expected not in accepted:
        raise HTTPException(status_code=409, detail={"error": "stale_state", "message": "That shift changed. Refresh and try again."})
    with db_connect() as conn:
        with conn.cursor() as cur:
            if _shifts_authority.shifts_wave1_enabled():
                _shifts_authority.ensure_shifts_authority_wave1_schema(cur)
                settings = _shifts_authority.get_shift_authority_settings(cur, company)
                if ends_next and not settings.get("allow_overnight", True):
                    raise HTTPException(status_code=422, detail={"error": "overnight_not_allowed", "message": "Overnight shifts are disabled for this company."})
                emp = emp_preview
                if wave1_subject:
                    life_denied = _shifts_authority.evaluate_assignment_lifecycle(
                        cur,
                        company_code=company,
                        employee=emp,
                        settings=settings,
                        shift_date=new_date,
                        start_time=start_clock,
                        end_time=end_clock,
                        ends_next_day=ends_next,
                        operation="reschedule",
                        action={"allow_leave_conflicts": request.allow_leave_conflicts},
                    )
                    if life_denied:
                        raise HTTPException(status_code=409, detail=life_denied)
                    leaves = _shifts_authority.approved_leave_on_date(
                        cur, company_code=company, employee_key=str(current.get("employee_key")), shift_date=new_date
                    )
                    leave_denied = _shifts_authority.leave_conflict_denied(
                        mode=str(settings.get("leave_conflict_mode") or "require_ack"),
                        leaves=leaves,
                        action={"allow_leave_conflicts": request.allow_leave_conflicts},
                    )
                    if leave_denied:
                        raise HTTPException(status_code=409, detail=leave_denied)
            if _shifts_w2_applies(company, current):
                _shifts_w2.ensure_shifts_integrity_wave2_schema(cur)
                integ = _shifts_w2.get_integrity_settings(cur, company)
                avail_hits = _shifts_w2.approved_unavailability_overlaps(
                    cur,
                    company_code=company,
                    employee_key=str(current.get("employee_key")),
                    shift_date=new_date,
                    start_time=start_clock,
                    end_time=end_clock,
                    ends_next_day=ends_next,
                )
                avail_denied = _shifts_w2.availability_conflict_denied(
                    mode=str(integ.get("availability_conflict_mode") or "require_ack"),
                    conflicts=avail_hits,
                    action={
                        "ack_availability_conflict": request.acknowledge_availability or request.allow_leave_conflicts,
                        "allow_availability_conflicts": request.acknowledge_availability,
                    },
                )
                if avail_denied:
                    raise HTTPException(status_code=409, detail=avail_denied)
                seasonal = _shifts_w2.evaluate_seasonal_policies(
                    cur,
                    company_code=company,
                    shift_date=new_date,
                    start_time=start_clock,
                    end_time=end_clock,
                    site_key=current.get("site_key"),
                    branch_key=current.get("branch_key"),
                    ends_next_day=ends_next,
                )
                if seasonal.get("denied"):
                    raise HTTPException(status_code=409, detail=seasonal["denied"])
            conflicts = shift_conflicts(
                cur,
                company_code=company,
                employee_key=str(current.get("employee_key")),
                shift_date=new_date,
                start_time=start_clock,
                end_time=end_clock,
                ends_next_day=ends_next,
                exclude_shift_id=str(shift_id),
            )
            if conflicts:
                raise HTTPException(
                    status_code=409,
                    detail={
                        "error": "shift_overlap",
                        "message": "That reschedule overlaps another scheduled shift.",
                        "conflicts": json_safe(conflicts),
                    },
                )
            # Concurrency: one winner — match expected updated_at on the row
            if _shifts_authority.shifts_wave1_enabled():
                cur.execute(
                    """
                    UPDATE shift_assignments
                    SET shift_date=%s, start_time=%s, end_time=%s, ends_next_day=%s,
                        updated_at=now(), row_version=COALESCE(row_version,1)+1
                    WHERE shift_id=%s AND company_code=%s AND status='scheduled'
                      AND updated_at = %s::timestamptz
                    RETURNING *
                    """,
                    (new_date, start_clock, end_clock, ends_next, str(shift_id), company, current_updated),
                )
            else:
                cur.execute(
                    "UPDATE shift_assignments SET shift_date=%s, start_time=%s, end_time=%s, updated_at=now() WHERE shift_id=%s AND company_code=%s AND status='scheduled' RETURNING *",
                    (new_date, start_clock, end_clock, str(shift_id), company),
                )
            row = cur.fetchone()
            if not row:
                conn.commit()
                raise HTTPException(status_code=409, detail={"error": "stale_state", "message": "That shift changed. Refresh and try again."})
            updated = dict(row)
            _shifts_templates_w4.mark_assignment_detached(cur, company_code=company, shift_id=updated.get("shift_id"))
            record_shift_event(cur, shift=updated, company_code=company, event_type="rescheduled", payload={"shift": updated, "source": "dashboard", "previous": current}, created_by_phone=actor_phone)
            if _shifts_w2_applies(company, updated):
                _shifts_w2.record_assignment_version(
                    cur,
                    company_code=company,
                    shift=updated,
                    reason_code="rescheduled",
                    actor_phone=actor_phone,
                    lineage={"previous": _shifts_w2._snapshot(current)},
                )
                _shifts_w2.cancel_pending_reminders_for_shift(cur, company_code=company, shift_id=str(shift_id))
                # Clear stamp so a new reminder can be delivered for the new window
                cur.execute(
                    "UPDATE shift_assignments SET reminder_sent_at=NULL WHERE shift_id=%s AND company_code=%s",
                    (str(shift_id), company),
                )
                updated["reminder_sent_at"] = None
                _shifts_w2.enqueue_shift_reminder(cur, company_code=company, shift=updated)
        conn.commit()
    employee = _employee_for_shift(updated, company)
    notified = False
    try:
        # Reuse the "shift scheduled" notice — it carries the new date/time, which
        # is exactly what the employee needs to see after a reschedule.
        notification = notify_employee_shift_created(result={"employee": employee, "created": [updated]}, account_id=company, created_by_phone=actor_phone)
        notified = bool(notification.get("ok"))
    except Exception:
        logger.warning("dashboard shift reschedule notification failed", exc_info=True)
    record_admin_audit(
        context,
        "shift_rescheduled",
        summary=f"Rescheduled {updated.get('employee_name') or 'an employee'}'s shift to {updated.get('shift_date')} {start_clock}-{end_clock}.",
        target_type="employee",
        target=updated.get("employee_key"),
        details={"shift_id": str(shift_id), "shift_date": str(updated.get("shift_date")), "start_time": start_clock, "end_time": end_clock, "ends_next_day": ends_next},
    )
    name = updated.get("employee_name") or "The employee"
    return json_safe({"ok": True, "status": "rescheduled", "message": f"{name}'s shift was moved to {updated.get('shift_date')}.", "shift": updated, "notified": notified})


@app.get("/dashboard/posthire/shifts/{shift_id}/history")
def dashboard_posthire_shift_history(shift_id: str, context: dict[str, Any] = Depends(dashboard_context)):
    company = _posthire_read_context(context, "shifts")
    try:
        uuid.UUID(str(shift_id))
    except (ValueError, AttributeError, TypeError):
        raise HTTPException(status_code=404, detail={"error": "shift_not_found"})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM shift_assignments WHERE shift_id=%s AND company_code=%s LIMIT 1", (str(shift_id), company))
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail={"error": "shift_not_found"})
            shift = dict(row)
            allowed = context_manager_employee_keys(context, company)
            if allowed is not None and str(shift.get("employee_key")) not in allowed:
                raise HTTPException(status_code=403, detail={"error": "out_of_scope"})
            versions: list[dict[str, Any]] = []
            events: list[dict[str, Any]] = []
            if _shifts_w2.shifts_wave2_enabled_for_company(company):
                _shifts_w2.ensure_shifts_integrity_wave2_schema(cur)
                versions = _shifts_w2.list_assignment_versions(cur, company_code=company, shift_id=str(shift_id))
            cur.execute(
                """
                SELECT * FROM shift_events
                WHERE company_code=%s AND shift_id=%s
                ORDER BY created_at ASC
                LIMIT 200
                """,
                (company, str(shift_id)),
            )
            events = [dict(r) for r in cur.fetchall()]
    return json_safe({
        "ok": True,
        "shift": _shifts_w3.enrich_shift_row_for_ui(shift) if _shifts_w3.shifts_wave3_enabled_for_company(company) else shift,
        "versions": versions,
        "events": events,
        "wave3": _shifts_w3.honesty_payload() if _shifts_w3.shifts_wave3_enabled_for_company(company) else {},
    })


# --- Shifts Wave 4: templates + recurring schedules (planning → L0 materialize) ---

class ShiftTemplateUpsertRequest(BaseModel):
    name: str | None = None
    start_time: str | None = None
    end_time: str | None = None
    break_minutes: int | None = None
    role: str | None = None
    site_key: str | None = None
    branch_key: str | None = None
    team_key: str | None = None
    position_key: str | None = None
    location: str | None = None
    timezone: str | None = None
    notes: str | None = None


class ShiftRecurrenceUpsertRequest(BaseModel):
    name: str | None = None
    template_id: str | None = None
    alternate_template_id: str | None = None
    cycle_type: str | None = None
    weekdays: list[int] | None = None
    on_days: int | None = None
    off_days: int | None = None
    cycle_anchor_date: str | None = None
    effective_start: str | None = None
    effective_end: str | None = None
    horizon_days: int | None = None
    target_type: str | None = None
    target_key: str | None = None


class ShiftRecurrenceExceptionRequest(BaseModel):
    exception_date: str
    kind: str  # skip | one_off_override
    override_template_id: str | None = None
    override_start_time: str | None = None
    override_end_time: str | None = None
    notes: str | None = None


class ShiftRecurrencePreviewRequest(BaseModel):
    acknowledge_availability: bool = False
    allow_leave_conflicts: bool = False
    acknowledge_seasonal: bool = False


def _wave4_require(context: dict[str, Any]) -> str:
    require_entitlement(context, "shifts", "shifts.manage")
    company = context["company_code"]
    if not _shifts_templates_w4.shifts_wave4_enabled_for_company(company):
        raise HTTPException(status_code=404, detail={"error": "shifts_wave4_disabled", **_shifts_templates_w4.honesty_payload()})
    return company


def _wave4_regen_reschedule(action: dict[str, Any], *, company_code: str, created_by_phone: str | None) -> dict[str, Any]:
    """Reschedule generated future rows without detaching (regen path)."""
    company = (company_code or "").upper()
    shift_id = str(action.get("shift_id") or "")
    new_date = _coerce_employee_start_date(action.get("shift_date") or action.get("date"))
    start_clock = _parse_clock(action.get("start_time"))
    end_clock = _parse_clock(action.get("end_time"))
    if not shift_id or not new_date or not start_clock or not end_clock:
        return {"ok": False, "error": "invalid_regen_reschedule"}
    ends_next = _shifts_authority.ends_next_day_for(start_clock, end_clock)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM shift_assignments WHERE company_code=%s AND shift_id=%s AND status='scheduled'",
                (company, shift_id),
            )
            current = cur.fetchone()
            if not current:
                return {"ok": False, "error": "shift_not_found"}
            current = dict(current)
            cur.execute(
                """
                UPDATE shift_assignments
                SET shift_date=%s, start_time=%s, end_time=%s, ends_next_day=%s,
                    updated_at=now(), row_version=COALESCE(row_version,1)+1,
                    regen_detached=false
                WHERE shift_id=%s AND company_code=%s AND status='scheduled'
                RETURNING *
                """,
                (new_date, start_clock, end_clock, ends_next, shift_id, company),
            )
            row = cur.fetchone()
            if not row:
                return {"ok": False, "error": "update_failed"}
            updated = dict(row)
            record_shift_event(
                cur,
                shift=updated,
                company_code=company,
                event_type="rescheduled",
                payload={"shift": updated, "source": "wave4_regen", "previous": current, "reason": action.get("reason")},
                created_by_phone=created_by_phone,
            )
        conn.commit()
    return {"ok": True, "shift": json_safe(updated)}


