def dashboard_posthire_preview_shift_recurrence(
    recurrence_id: str, request: ShiftRecurrencePreviewRequest = ShiftRecurrencePreviewRequest(), context: dict[str, Any] = Depends(dashboard_context)
):
    company = _wave4_require(context)
    acks = {
        "acknowledge_availability": request.acknowledge_availability,
        "ack_availability_conflict": request.acknowledge_availability,
        "allow_leave_conflicts": request.allow_leave_conflicts,
        "acknowledge_seasonal": request.acknowledge_seasonal,
        "ack_seasonal": request.acknowledge_seasonal,
    }

    def overlap_checker(planned: dict[str, Any]):
        return shift_conflicts(
            company_code=company,
            employee_key=str(planned.get("employee_key")),
            shift_date=_coerce_employee_start_date(planned.get("shift_date")),
            start_time=_parse_clock(planned.get("start_time")),
            end_time=_parse_clock(planned.get("end_time")),
            ends_next_day=bool(planned.get("ends_next_day")),
        )

    with db_connect() as conn:
        with conn.cursor() as cur:
            result = _shifts_templates_w4.preview_recurrence(
                cur,
                company_code=company,
                recurrence_id=recurrence_id,
                action_acks=acks,
                overlap_checker=overlap_checker,
            )
    if not result.get("ok"):
        raise HTTPException(status_code=404 if result.get("error") == "recurrence_not_found" else 422, detail=json_safe(result))
    # Drop full classified list from HTTP response (keep samples + counts)
    result.pop("classified", None)
    return json_safe(result)


@app.post("/dashboard/posthire/shifts/recurrences/{recurrence_id}/materialize")
def dashboard_posthire_materialize_shift_recurrence(
    recurrence_id: str, request: ShiftRecurrencePreviewRequest = ShiftRecurrencePreviewRequest(), context: dict[str, Any] = Depends(dashboard_context)
):
    company = _wave4_require(context)
    actor = context.get("hr_phone")
    acks = {
        "acknowledge_availability": request.acknowledge_availability,
        "ack_availability_conflict": request.acknowledge_availability,
        "allow_leave_conflicts": request.allow_leave_conflicts,
        "acknowledge_seasonal": request.acknowledge_seasonal,
        "ack_seasonal": request.acknowledge_seasonal,
    }

    def overlap_checker(planned: dict[str, Any]):
        return shift_conflicts(
            company_code=company,
            employee_key=str(planned.get("employee_key")),
            shift_date=_coerce_employee_start_date(planned.get("shift_date")),
            start_time=_parse_clock(planned.get("start_time")),
            end_time=_parse_clock(planned.get("end_time")),
            ends_next_day=bool(planned.get("ends_next_day")),
        )

    with db_connect() as conn:
        with conn.cursor() as cur:
            result = _shifts_templates_w4.materialize_recurrence(
                cur,
                company_code=company,
                recurrence_id=recurrence_id,
                create_fn=create_shift_assignment,
                reschedule_fn=_wave4_regen_reschedule,
                action_acks=acks,
                overlap_checker=overlap_checker,
                actor_phone=actor,
            )
        conn.commit()
    if not result.get("ok"):
        status = 409 if result.get("error") == "materialize_lock_held" else 422
        raise HTTPException(status_code=status, detail=json_safe(result))
    record_admin_audit(
        context,
        "shift_recurrence_materialized",
        summary=f"Materialized recurrence {recurrence_id}.",
        target_type="shift_recurrence",
        target=recurrence_id,
        details={"results": (result.get("results") or {})},
    )
    return json_safe(result)


