@app.post("/dashboard/posthire/shifts/schedule-versions/{version_id}/publish")
def dashboard_posthire_schedule_publish(
    version_id: str, request: ShiftSchedulePublishRequest, context: dict[str, Any] = Depends(dashboard_context)
):
    company = _wave5_require(context)
    with db_connect() as conn:
        with conn.cursor() as cur:
            if _shifts_enterprise_w6.shifts_wave6_enabled_for_company(company):
                _shifts_enterprise_w6.ensure_shifts_enterprise_wave6_schema(cur)
                compliance = _shifts_enterprise_w6.evaluate_compliance_for_version(
                    cur, company_code=company, version_id=version_id
                )
                if compliance.get("blocks_publish"):
                    raise HTTPException(
                        status_code=422,
                        detail=json_safe({"ok": False, "error": "compliance_block", "compliance": compliance}),
                    )
            result = _shifts_publish_w5.publish_version(
                cur,
                company_code=company,
                version_id=version_id,
                create_fn=create_shift_assignment,
                actor_phone=context.get("hr_phone"),
                expected_row_version=request.expected_row_version,
                publish_idempotency_key=request.publish_idempotency_key,
                action_acks=_wave5_acks(request),
            )
        conn.commit()
    if not result.get("ok"):
        status = 409 if result.get("error") in {"publish_lock_held", "stale_period", "publish_idempotency_conflict"} else 422
        raise HTTPException(status_code=status, detail=json_safe(result))
    record_admin_audit(
        context,
        "shift_schedule_published",
        summary=f"Published schedule version {version_id}.",
        target_type="shift_schedule_version",
        target=version_id,
        details={"results": (result.get("results") or {})},
    )
    return json_safe(result)


