@app.post("/dashboard/posthire/shifts/rotations/assignments/{assignment_id}/preview")
def dashboard_posthire_preview_rotation(
    assignment_id: str, request: ShiftRotationPreviewRequest, context: dict[str, Any] = Depends(dashboard_context)
):
    company = _wave6_require(context)
    from datetime import date as _date

    def _d(v: str | None):
        if not v:
            return None
        try:
            return _date.fromisoformat(str(v)[:10])
        except Exception:
            return None

    with db_connect() as conn:
        with conn.cursor() as cur:
            result = _shifts_enterprise_w6.preview_rotation(
                cur,
                company_code=company,
                assignment_id=assignment_id,
                window_start=_d(request.window_start),
                window_end=_d(request.window_end),
                sample_limit=request.sample_limit,
            )
    if not result.get("ok"):
        raise HTTPException(status_code=422, detail=json_safe(result))
    return json_safe(result)


