@app.post("/dashboard/posthire/payroll/external/exports")
def dashboard_payroll_external_create_export(
    request: PayrollExternalExportRequest,
    context: dict[str, Any] = Depends(dashboard_context),
):
    company = _payroll_w2a_require(context, "payroll.export")
    allowed = _payroll_w2a_scope_keys(context, company)
    with db_connect() as conn:
        with conn.cursor() as cur:
            assembled = _payroll_w2a.assemble_period_export_inputs(
                cur,
                company_code=company,
                period_start=request.period_start,
                period_end=request.period_end,
                period_id=request.period_id,
                allowed_employee_keys=allowed,
            )
            if not assembled.get("employees"):
                raise HTTPException(
                    status_code=422,
                    detail=json_safe(
                        {
                            "ok": False,
                            "error": "no_in_scope_employees",
                            "message": "No approved contracts in scope for this period.",
                            **_payroll_w2a.honesty_payload(),
                        }
                    ),
                )
            result = _payroll_w2a.create_external_export(
                cur,
                company_code=company,
                period=assembled["period"],
                employees=assembled["employees"],
                contracts=assembled["contracts"],
                shifts=assembled.get("shifts") or [],
                attendance=assembled.get("attendance") or [],
                leave_classifications=assembled.get("leave_classifications") or [],
                actor_phone=context.get("hr_phone"),
                reason=request.reason,
            )
        conn.commit()
    if not result.get("ok"):
        raise HTTPException(status_code=422, detail=json_safe(result))
    record_admin_audit(
        context,
        "payroll_external_export_created",
        summary=f"Generated external payroll input export for {request.period_start}–{request.period_end}.",
        target_type="payroll_adapter_export_run",
        target=str((result.get("export_run") or {}).get("export_run_id") or ""),
        details={
            "fingerprint_changed": result.get("fingerprint_changed"),
            "idempotent": result.get("idempotent"),
            "money_authority": "external",
        },
    )
    # Never return authoritative money claim
    result["authoritative_in_wathefni"] = False
    return json_safe(result)


