@app.post("/dashboard/posthire/payroll/external/exports/{export_run_id}/import")
async def dashboard_payroll_external_import(
    export_run_id: str,
    file: UploadFile = File(...),
    reason: str = Form(...),
    expected_input_fingerprint: str | None = Form(None),
    replace: bool = Form(False),
    context: dict[str, Any] = Depends(dashboard_context),
):
    company = _payroll_w2a_require(context, "payroll.manage")
    raw = await file.read()
    try:
        csv_text = raw.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise HTTPException(
            status_code=422,
            detail=json_safe({"ok": False, "error": "invalid_encoding", **_payroll_w2a.honesty_payload()}),
        )
    with db_connect() as conn:
        with conn.cursor() as cur:
            if replace:
                result = _payroll_w2a.replace_import_results(
                    cur,
                    company_code=company,
                    export_run_id=export_run_id,
                    csv_text=csv_text,
                    actor_phone=context.get("hr_phone"),
                    reason=reason,
                    expected_input_fingerprint=expected_input_fingerprint,
                )
            else:
                result = _payroll_w2a.import_external_results(
                    cur,
                    company_code=company,
                    export_run_id=export_run_id,
                    csv_text=csv_text,
                    actor_phone=context.get("hr_phone"),
                    reason=reason,
                    expected_input_fingerprint=expected_input_fingerprint,
                )
        conn.commit()
    # Quarantine / fingerprint failures are surfaced, never silent authority
    result["authoritative_in_wathefni"] = False
    result["money_authority"] = "external"
    if not result.get("ok"):
        status = 409 if result.get("error") == "input_fingerprint_changed" else 422
        raise HTTPException(status_code=status, detail=json_safe(result))
    record_admin_audit(
        context,
        "payroll_external_import_uploaded",
        summary=f"{'Replaced' if replace else 'Uploaded'} external payroll result for export {export_run_id}.",
        target_type="payroll_adapter_import_run",
        target=str((result.get("import_run") or {}).get("import_run_id") or ""),
        details={
            "idempotent": result.get("idempotent"),
            "replace": bool(replace),
            "authoritative_in_wathefni": False,
        },
    )
    return json_safe(result)


