@app.post("/dashboard/posthire/payroll/external/exports/{export_run_id}/rollback")
def dashboard_payroll_external_rollback(
    export_run_id: str,
    request: PayrollExternalReasonRequest,
    context: dict[str, Any] = Depends(dashboard_context),
):
    # Rollback requires approve (or manage) + audit reason — SOD-friendly
    if not (
        dashboard_context_has_permission(context, "payroll.approve")
        or dashboard_context_has_permission(context, "payroll.manage")
    ):
        raise HTTPException(status_code=403, detail={"error": "permission_denied", "permission": "payroll.approve"})
    company = _payroll_w2a_require(context, "payroll.read")
    # re-check entitlement with manage if approve missing — already checked soft above
    require_entitlement(
        context,
        "payroll",
        "payroll.approve" if dashboard_context_has_permission(context, "payroll.approve") else "payroll.manage",
    )
    with db_connect() as conn:
        with conn.cursor() as cur:
            result = _payroll_w2a.rollback_export_run(
                cur,
                company_code=company,
                export_run_id=export_run_id,
                actor_phone=context.get("hr_phone"),
                reason=request.reason,
                expected_row_version=request.expected_row_version,
            )
        conn.commit()
    if not result.get("ok"):
        status = 409 if result.get("error") == "stale_row_version_or_bad_status" else 422
        raise HTTPException(status_code=status, detail=json_safe(result))
    record_admin_audit(
        context,
        "payroll_external_export_rolled_back",
        summary=f"Rolled back external payroll export {export_run_id}.",
        target_type="payroll_adapter_export_run",
        target=export_run_id,
        details={"reason": request.reason},
    )
    result["authoritative_in_wathefni"] = False
    return json_safe(result)


