@app.post("/dashboard/posthire/payroll/preview")
def dashboard_payroll_native_preview_calculate(
    request: PayrollNativePreviewRequest,
    context: dict[str, Any] = Depends(dashboard_context),
):
    company = _payroll_w2b_require(context, "payroll.manage")
    with db_connect() as conn:
        with conn.cursor() as cur:
            contracts = list(request.contracts or [])
            if not contracts:
                # Load approved contracts overlapping period (read-only Wave 1)
                for emp in request.employees or []:
                    key = str(emp.get("employee_key") or "")
                    if not key:
                        continue
                    overlapping = _payroll_w1.list_overlapping_approved(
                        cur,
                        company_code=company,
                        employee_key=key,
                        effective_from=_payroll_w2b.parse_date(request.period_start) or date.today(),
                        effective_to=_payroll_w2b.parse_date(request.period_end),
                    )
                    for row in overlapping:
                        full = _payroll_w1.get_contract(cur, company_code=company, contract_id=str(row.get("contract_id")))
                        if full:
                            contracts.append(full)
            result = _payroll_w2b.calculate_native_preview(
                cur,
                company_code=company,
                period_start=request.period_start,
                period_end=request.period_end,
                period_id=request.period_id,
                employees=request.employees,
                contracts=contracts,
                unpaid_leaves=request.unpaid_leaves,
                adjustments=request.adjustments,
                requested_unsupported=request.requested_unsupported,
                actor_phone=context.get("hr_phone"),
                reason=request.reason,
            )
        conn.commit()
    result["authoritative"] = False
    if not result.get("ok") and not result.get("idempotent"):
        raise HTTPException(status_code=422, detail=json_safe(result))
    record_admin_audit(
        context,
        "payroll_native_preview_calculated",
        summary=f"Calculated native payroll preview for {request.period_start}–{request.period_end}.",
        target_type="payroll_preview_run",
        target=str((result.get("preview_run") or {}).get("preview_run_id") or ""),
        details={"authoritative": False, "idempotent": result.get("idempotent")},
    )
    return json_safe(result)


