@app.get("/dashboard/posthire/payroll/payslips/{payslip_id}")
def dashboard_payroll_payslip_detail(payslip_id: str, context: dict[str, Any] = Depends(dashboard_context)):
    company = _payroll_w3_require(context, "payroll.read")
    allowed = _payroll_w3_scope_keys(context, company)
    with db_connect() as conn:
        with conn.cursor() as cur:
            doc = _payroll_w3.get_payslip(cur, company_code=company, payslip_id=payslip_id)
            if not doc:
                raise HTTPException(status_code=404, detail={"error": "payslip_not_found"})
            key = str(doc.get("employee_key") or "")
            if allowed is not None and key not in allowed:
                raise HTTPException(status_code=403, detail={"error": "employee_outside_manager_scope"})
            lines = _payroll_w3.list_payslip_lines(cur, company_code=company, payslip_id=payslip_id)
            events = _payroll_w3.list_payslip_events(cur, company_code=company, payslip_id=payslip_id, limit=40)
            history = _payroll_w3.list_payslip_history(
                cur, company_code=company, employee_key=key, allowed_employee_keys=allowed, limit=40
            )
    return json_safe(
        {
            "ok": True,
            "payslip": doc,
            "lines": lines,
            "events": events,
            "history": history,
            **_payroll_w3.honesty_payload(),
        }
    )


@app.get("/dashboard/posthire/payroll/payslips/{payslip_id}/download")
def dashboard_payroll_payslip_download(
    payslip_id: str,
    locale: str = Query("en"),
    context: dict[str, Any] = Depends(dashboard_context),
):
    company = _payroll_w3_require(context, "payroll.read")
    allowed = _payroll_w3_scope_keys(context, company)
    with db_connect() as conn:
        with conn.cursor() as cur:
            result = _payroll_w3.download_payslip_document(
                cur,
                company_code=company,
                payslip_id=payslip_id,
                locale=locale,
                allowed_employee_keys=allowed,
            )
    if not result.get("ok"):
        code = 403 if result.get("error") == "employee_outside_manager_scope" else 404
        raise HTTPException(status_code=code, detail=json_safe(result))
    from fastapi.responses import Response

    body = str(result.get("body") or "")
    filename = str(result.get("filename") or "payslip.txt")
    return Response(
        content=body.encode("utf-8"),
        media_type="text/plain; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


