@app.post("/dashboard/posthire/payroll/payslips/{payslip_id}/release")
def dashboard_payroll_payslip_release(
    payslip_id: str,
    request: PayrollPayslipReasonRequest,
    context: dict[str, Any] = Depends(dashboard_context),
):
    """Explicit employee visibility release. Never inferred from period status."""
    company = _payroll_w3_require(context, "payroll.manage")
    allowed = _payroll_w3_scope_keys(context, company)
    push_notify: dict[str, Any] | None = None
    with db_connect() as conn:
        with conn.cursor() as cur:
            result = _payroll_w3.release_payslip_to_employee(
                cur,
                company_code=company,
                payslip_id=payslip_id,
                actor_phone=context.get("hr_phone"),
                reason=request.reason,
                allowed_employee_keys=allowed,
            )
            if result.get("ok") and result.get("notify_employee") and not result.get("idempotent"):
                payslip = result.get("payslip") or {}
                emp_key = str(payslip.get("employee_key") or "")
                period = f"{payslip.get('period_start')} → {payslip.get('period_end')}"
                dedupe = f"payslip_ready:{payslip_id}"
                cur.execute(
                    "SELECT 1 FROM employee_messages WHERE company_code=%s AND dedupe_key=%s LIMIT 1",
                    (company, dedupe),
                )
                if not cur.fetchone():
                    message_id = str(uuid.uuid4())
                    body_en = f"Your payslip for {period} is ready to view in the app."
                    body_ar = f"كشف راتبك لفترة {period} جاهز للعرض في التطبيق."
                    cur.execute(
                        """
                        INSERT INTO employee_messages
                          (message_id, company_code, employee_key, flow, template_key, criticality,
                           sensitivity, locale, status, body_preview, dedupe_key, metadata)
                        VALUES (%s,%s,%s,'payroll','payslip_ready','standard','preview','en','delivered',%s,%s,%s::jsonb)
                        """,
                        (
                            message_id,
                            company,
                            emp_key,
                            body_en[:280],
                            dedupe,
                            json.dumps(
                                {
                                    "deep_link": {"path": "/payslips", "payslip_id": str(payslip_id)},
                                    "payslip_id": str(payslip_id),
                                    "period": period,
                                    "body_ar": body_ar,
                                }
                            ),
                        ),
                    )
                    push_notify = {
                        "employee_key": emp_key,
                        "period": period,
                        "payslip_id": str(payslip_id),
                        "dedupe": dedupe,
                    }
        conn.commit()
    if push_notify and push_notify.get("employee_key"):
        try:
            import employee_push_tray as _push_tray

            title, body = _push_tray.tray_copy(
                "payslip_ready",
                variables={"period": push_notify["period"]},
            )
            send_outbound_push(
                company_code=company,
                employee_key=push_notify["employee_key"],
                title=title,
                body=body,
                flow="payroll",
                subject_type="employee",
                subject_key=push_notify["employee_key"],
                message_kind="payslip_ready",
                template_key="payslip_ready",
                dedupe_key=push_notify["dedupe"],
                deep_link={"path": "/payslips", "payslip_id": push_notify["payslip_id"]},
                variables={"period": push_notify["period"], "payslip_id": push_notify["payslip_id"]},
            )
        except Exception:
            logger.warning("payslip push failed for %s", push_notify.get("employee_key"), exc_info=True)
    if not result.get("ok"):
        raise HTTPException(status_code=422, detail=json_safe(result))
    record_admin_audit(
        context,
        "payroll_payslip_released_to_employee",
        summary=f"Released payslip {payslip_id} to employee app.",
        target_type="payroll_payslip",
        target=payslip_id,
        details={"idempotent": result.get("idempotent"), "employee_facing_state": result.get("employee_facing_state")},
    )
    return json_safe(result)


