def _action_inbox_gate(context: dict[str, Any]) -> str:
    """Allow inbox when wave on, source readable, and viewer allowlisted (fail-closed)."""
    import action_inbox_wave1 as _inbox

    company = context["company_code"]
    if not _inbox.action_inbox_wave1_enabled_for_company(company):
        raise HTTPException(
            status_code=403,
            detail={
                "error": "action_inbox_disabled",
                "message": "Action Inbox is disabled for this workspace.",
            },
        )
    if not _inbox.viewer_is_allowlisted(
        phone=context.get("hr_phone") or context.get("actor_phone"),
        user_id=context.get("actor_user_id"),
        email=context.get("actor_email")
        or ((context.get("hr_user") or {}).get("email") if isinstance(context.get("hr_user"), dict) else None),
    ):
        raise HTTPException(
            status_code=403,
            detail={
                "error": "action_inbox_viewer_denied",
                "message": "Action Inbox is not enabled for this account.",
            },
        )
    readable = False
    for module, perm in (
        ("analytics", "analytics.read"),
        ("compliance", "compliance.read"),
        ("onboarding", "onboarding.read"),
        ("attendance", "attendance.read"),
        ("leave", "leave.read"),
        ("shifts", "shifts.read"),
        ("payroll", "payroll.read"),
    ):
        try:
            if company_has_module(company, module) and dashboard_context_has_permission(context, perm):
                readable = True
                break
        except Exception:
            continue
    if not readable and dashboard_context_has_permission(context, "employees.read"):
        readable = True
    if not readable:
        raise HTTPException(
            status_code=403,
            detail={
                "error": "permission_denied",
                "message": "Action Inbox requires read access to a post-hire source module.",
            },
        )
    return company


def _inbox_e360_next_actions(
    company: str,
    context: dict[str, Any],
    *,
    compliance_documents: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Build Employees 360 next-actions for inbox using the same builder as profiles."""
    import action_inbox_wave1 as _inbox
    import compliance_findings_wave1 as _cf

    viewer_phone = context.get("hr_phone")
    dashboard_user_id = context.get("actor_user_id")
    actor_role = context.get("actor_role")
    employees = company_employees(company)
    allowed_keys = manager_scope_employee_keys(
        company,
        viewer_phone,
        dashboard_user_id=dashboard_user_id,
        actor_role=actor_role,
    )
    if allowed_keys is not None:
        employees = [e for e in employees if str(e.get("employee_key")) in allowed_keys]
    # Phase 0 subject allowlist — empty means soft-kill (no E360 rows).
    subject_allow = _inbox.real_subject_allowlist()
    if not subject_allow:
        return [], {
            "available": True,
            "employee_count": 0,
            "scanned": 0,
            "phase0_subject_soft_kill": True,
        }
    employees = [e for e in employees if str(e.get("employee_key") or "").upper() in subject_allow]
    cards: dict[str, dict[str, Any]] = {}
    rows_by_key: dict[str, dict[str, Any]] = {}
    for row in employees:
        card = posthire_employee_card(row)
        key = str(card.get("employee_key") or "")
        if key:
            cards[key] = card
            rows_by_key[key] = row

    modules = set(employee_profile_accessible_modules(context, company))
    docs_by_emp: dict[str, list[dict[str, Any]]] = {}
    for doc in compliance_documents or []:
        key = str(doc.get("employee_key") or "")
        if key and key.upper() not in subject_allow:
            continue
        if key and str(doc.get("status") or "") in COMPLIANCE_OUTSTANDING_BUCKETS:
            docs_by_emp.setdefault(key, []).append(doc)

    interest: set[str] = set(docs_by_emp.keys())
    onboarding_by_emp: dict[str, dict[str, Any]] = {}
    leave_by_emp: dict[str, list[dict[str, Any]]] = {}
    attendance_by_emp: dict[str, dict[str, Any]] = {}
    payroll_by_emp: dict[str, list[dict[str, Any]]] = {}
    employee_keys = list(cards.keys())
    if not employee_keys:
        return [], {"available": False, "employee_count": 0, "scanned": 0}

    with db_connect() as conn:
        with conn.cursor() as cur:
            if "onboarding" in modules:
                import onboarding_completion_contract as _completion

                _open = _completion.sql_open_predicate("oi.status")
                cur.execute(
                    f"""
                    SELECT oi.employee_key, COUNT(*) FILTER (
                      WHERE oi.required IS TRUE AND {_open}
                    ) AS outstanding_count
                    FROM onboarding_items oi
                    JOIN employees e ON e.employee_key = oi.employee_key
                    WHERE e.company_code=%s AND oi.employee_key = ANY(%s)
                    GROUP BY oi.employee_key
                    HAVING COUNT(*) FILTER (
                      WHERE oi.required IS TRUE AND {_open}
                    ) > 0
                    """,
                    (company, employee_keys),
                )
                for row in cur.fetchall():
                    key = str(row.get("employee_key") or "")
                    n = int(row.get("outstanding_count") or 0)
                    if key and n:
                        onboarding_by_emp[key] = {
                            "outstanding_count": n,
                            "outstanding": [{"label": "required item"}] * min(n, 3),
                        }
                        interest.add(key)

            if "leave" in modules:
                cur.execute(
                    """
                    SELECT employee_key, start_date, end_date, leave_type, status
                    FROM leave_requests
                    WHERE company_code=%s AND employee_key = ANY(%s) AND lower(status)='requested'
                    ORDER BY start_date NULLS LAST
                    LIMIT 500
                    """,
                    (company, employee_keys),
                )
                for row in cur.fetchall():
                    key = str(row.get("employee_key") or "")
                    if not key:
                        continue
                    leave_by_emp.setdefault(key, []).append(
                        {
                            "status": "requested",
                            "start_date": row.get("start_date").isoformat()
                            if hasattr(row.get("start_date"), "isoformat")
                            else row.get("start_date"),
                            "end_date": row.get("end_date").isoformat()
                            if hasattr(row.get("end_date"), "isoformat")
                            else row.get("end_date"),
                            "leave_type": row.get("leave_type"),
                        }
                    )
                    interest.add(key)

            if "attendance" in modules:
                cur.execute(
                    """
                    SELECT employee_key,
                      COUNT(*) FILTER (WHERE lower(status)='absent') AS absent,
                      COUNT(*) FILTER (WHERE lower(status)='late' OR late_minutes > 0) AS late
                    FROM attendance_records
                    WHERE company_code=%s AND employee_key = ANY(%s)
                      AND attendance_date >= CURRENT_DATE - INTERVAL '14 days'
                    GROUP BY employee_key
                    """,
                    (company, employee_keys),
                )
                for row in cur.fetchall():
                    key = str(row.get("employee_key") or "")
                    absent = int(row.get("absent") or 0)
                    late = int(row.get("late") or 0)
                    if key and (absent >= _ATTENDANCE_PATTERN_MIN or late >= _ATTENDANCE_PATTERN_MIN):
                        attendance_by_emp[key] = {"window_days": 14, "absent": absent, "late": late}
                        interest.add(key)

            if "payroll" in modules:
                cur.execute(
                    """
                    SELECT employee_key, timesheet_id, period_start, period_end, status
                    FROM payroll_timesheets
                    WHERE company_code=%s AND employee_key = ANY(%s)
                      AND lower(status) IN ('draft','review','in_review')
                    ORDER BY period_start DESC NULLS LAST
                    LIMIT 300
                    """,
                    (company, employee_keys),
                )
                for row in cur.fetchall():
                    key = str(row.get("employee_key") or "")
                    if not key:
                        continue
                    payroll_by_emp.setdefault(key, []).append(
                        {
                            "timesheet_id": row.get("timesheet_id"),
                            "period_start": row.get("period_start").isoformat()
                            if hasattr(row.get("period_start"), "isoformat")
                            else row.get("period_start"),
                            "period_end": row.get("period_end").isoformat()
                            if hasattr(row.get("period_end"), "isoformat")
                            else row.get("period_end"),
                            "status": row.get("status"),
                        }
                    )
                    interest.add(key)

    ordered = [k for k in employee_keys if k in interest][:80]
    out: list[dict[str, Any]] = []
    for key in ordered:
        card = cards.get(key) or {"employee_key": key, "name": "Employee", "phone": ""}
        sections: dict[str, Any] = {}
        if "compliance" in modules and key in docs_by_emp:
            docs = docs_by_emp[key]
            counts = {b: 0 for b in COMPLIANCE_BUCKETS}
            for d in docs:
                st = str(d.get("status") or "missing")
                counts[st] = counts.get(st, 0) + 1
            sections["compliance"] = {**counts, "needs_attention": len(docs), "documents": docs}
        if "onboarding" in modules and key in onboarding_by_emp:
            sections["onboarding"] = onboarding_by_emp[key]
        if "leave" in modules and key in leave_by_emp:
            sections["leave"] = {"items": leave_by_emp[key], "balances": []}
        if "attendance" in modules and key in attendance_by_emp:
            sections["attendance"] = attendance_by_emp[key]
        if "payroll" in modules and key in payroll_by_emp:
            sections["payroll"] = {"items": payroll_by_emp[key]}
        if not sections:
            continue
        actions, _summary = build_employee_next_actions(card, sections)
        loc, team = _cf.location_team_from_employee(rows_by_key.get(key), card)
        team = team or card.get("department") or None
        for action in actions:
            out.append(
                _inbox.normalize_e360_next_action(
                    action,
                    employee_key=key,
                    employee_name=card.get("name"),
                    team=team,
                    location=loc,
                )
            )
    return out, {
        "available": bool(modules),
        "modules": sorted(modules),
        "employee_count": len(employee_keys),
        "scanned": len(ordered),
        "actions": len(out),
    }


def dashboard_action_inbox_payload(context: dict[str, Any]) -> dict[str, Any]:
    """Unified Action Inbox — read-only composition across frozen sources."""
    import action_inbox_wave1 as _inbox

    company = _action_inbox_gate(context)
    # Gate already enforced viewer allowlist + wave enabled.
    viewer_phone = context.get("hr_phone")
    dashboard_user_id = context.get("actor_user_id")
    actor_role = context.get("actor_role")

    can_analytics = False
    can_compliance = False
    try:
        can_analytics = company_has_module(company, "analytics") and dashboard_context_has_permission(
            context, "analytics.read"
        )
    except Exception:
        can_analytics = False
    try:
        can_compliance = company_has_module(company, "compliance") and dashboard_context_has_permission(
            context, "compliance.read"
        )
    except Exception:
        can_compliance = False

    attention: list[dict[str, Any]] = []
    analytics_error: str | None = None
    if can_analytics:
        start_iso, end_iso = _posthire_month_window()
        analytics = workforce_analytics(
            {
                "company_code": company,
                "start_date": start_iso,
                "end_date": end_iso,
                "query": "workforce overview",
                "viewer_phone": viewer_phone,
                "viewer_user_id": dashboard_user_id,
                "dashboard_user_id": dashboard_user_id,
                "actor_role": actor_role,
                "viewer_role": actor_role,
            },
            company_code=company,
        )
        if analytics.get("ok") is False:
            analytics_error = str(analytics.get("error") or "analytics_unavailable")
        else:
            attention = list(analytics.get("attention") or [])

    findings: list[dict[str, Any]] = []
    compliance_docs: list[dict[str, Any]] = []
    compliance_error: str | None = None
    if can_compliance:
        try:
            compliance = dashboard_compliance_payload(
                company,
                viewer_phone=viewer_phone,
                dashboard_user_id=dashboard_user_id,
                actor_role=actor_role,
                limit=None,
            )
            findings = list(compliance.get("findings") or [])
            compliance_docs = list(compliance.get("documents") or [])
        except Exception as exc:
            compliance_error = f"{type(exc).__name__}:{exc}"

    e360_actions, e360_meta = _inbox_e360_next_actions(
        company, context, compliance_documents=compliance_docs
    )

    # Module-Aware Shell Wave 0: never-purchased / unentitled sources are omitted.
    # `partial` / unavailable_source_keys only cover entitled sources that fail.
    can_employees = False
    try:
        can_employees = bool(employee_profile_accessible_modules(context, company))
    except Exception:
        can_employees = False
    if not can_employees:
        # Soft-admin people spine: any people module + employees.read (or admin).
        try:
            people_on = any(
                company_has_module(company, m)
                for m in ("onboarding", "compliance", "attendance", "leave", "shifts", "payroll")
            )
            can_employees = people_on and (
                dashboard_context_has_permission(context, "employees.read")
                or dashboard_context_has_permission(context, "settings.manage")
                or dashboard_context_has_permission(context, "users.manage")
            )
        except Exception:
            can_employees = False

    sources_meta: dict[str, Any] = {}
    unavailable_entitled: list[str] = []
    if can_analytics:
        sources_meta["analytics"] = {
            "available": not bool(analytics_error),
            "status": "error" if analytics_error else "live",
            "count": len(attention),
            "error": analytics_error,
            "note_en": "Analytics Attention (read-only).",
            "note_ar": "انتباه التحليلات (قراءة فقط).",
        }
        if analytics_error:
            unavailable_entitled.append("analytics")
    if can_compliance:
        sources_meta["compliance"] = {
            "available": not bool(compliance_error),
            "status": "error" if compliance_error else "live",
            "count": len(findings),
            "error": compliance_error,
            "note_en": "Compliance Findings (document only; never government verified).",
            "note_ar": "نتائج الامتثال (مستندات فقط؛ ليست تحققاً حكومياً).",
        }
        if compliance_error:
            unavailable_entitled.append("compliance")
    if can_employees:
        emp_live = bool(e360_meta.get("available"))
        sources_meta["employees"] = {
            "available": emp_live,
            "status": "live" if emp_live else "unavailable",
            "count": len(e360_actions),
            "scanned": e360_meta.get("scanned"),
            "note_en": "Employees 360 next actions (composed; Compliance duplicates removed).",
            "note_ar": "إجراءات ملف 360 (مركّبة؛ تُزال تكرارات الامتثال).",
        }
        if not emp_live:
            unavailable_entitled.append("employees")
    sources_meta["partial"] = bool(unavailable_entitled)
    sources_meta["unavailable_source_keys"] = unavailable_entitled
    sources_meta["omitted_unentitled_keys"] = [
        key
        for key, entitled in (
            ("analytics", can_analytics),
            ("compliance", can_compliance),
            ("employees", can_employees),
        )
        if not entitled
    ]

    pack = _inbox.build_action_inbox(
        analytics_attention=attention,
        compliance_findings=findings,
        e360_next_actions=e360_actions,
        sources_meta=sources_meta,
    )
    return {"company_code": company, "ok": True, **pack}


@app.get("/dashboard/posthire/action-inbox")
def dashboard_posthire_action_inbox(context: dict[str, Any] = Depends(dashboard_context)):
    return json_safe(dashboard_action_inbox_payload(context))


@app.post("/orchestrator/whatsapp-turn", response_model=OrchestratorResponse)
def whatsapp_turn(
    request: WhatsAppTurnRequest,
    _internal: dict[str, Any] = Depends(require_internal_access),
):
    ensure_schema()
    # Nothing arriving over HTTP may claim in-process dashboard session authority.
    strip_claimed_dashboard_authority(getattr(request, "metadata", None))
    inbound_claim = claim_whatsapp_inbound(request)
    metadata = request.metadata if isinstance(request.metadata, dict) else {}
    if (
        not inbound_claim.get("dedupe_available")
        and str(metadata.get("channel") or "") != "web_dashboard"
        and metadata.get("smoke") is not True
    ):
        return OrchestratorResponse(
            authoritative=True,
            reply_text=None,
            final_reply_source="provider_message_id_required",
            intent="ingress_rejected",
            turn_focus="ingress_dedupe",
            audit={"ingress_dedupe": {"dedupe_available": False, "error": "provider_message_id_required"}},
        )
    if inbound_claim.get("duplicate"):
        existing = inbound_claim.get("existing") if isinstance(inbound_claim.get("existing"), dict) else {}
        if not inbound_claim.get("identity_match"):
            return OrchestratorResponse(
                authoritative=True,
                reply_text=None,
                final_reply_source="whatsapp_duplicate_identity_mismatch",
                intent="duplicate_rejected",
                turn_focus="ingress_dedupe",
                audit={"ingress_dedupe": {"duplicate": True, "identity_match": False}},
            )
        stored = existing.get("response_json") if isinstance(existing.get("response_json"), dict) else None
        if stored:
            stored_audit = stored.get("audit") if isinstance(stored.get("audit"), dict) else {}
            stored["audit"] = {**stored_audit, "ingress_dedupe": {"duplicate": True, "replayed": True}}
            return OrchestratorResponse(**stored)
        return OrchestratorResponse(
            authoritative=True,
            reply_text=None,
            final_reply_source="whatsapp_duplicate_inflight",
            intent="duplicate_ignored",
            turn_focus="ingress_dedupe",
            audit={"ingress_dedupe": {"duplicate": True, "status": existing.get("status")}},
        )
    if request.sender_role != "hr_admin" and not is_hr_phone(request.sender_phone) and not canonical_lifecycle_enabled():
        blocked = OrchestratorResponse(
            authoritative=True,
            reply_text="OctoHR candidate intake is temporarily unavailable. Please contact HR.",
            final_reply_source="canonical_lifecycle_required",
            intent="candidate_intake_disabled",
            turn_focus="candidate_safety",
            audit={"canonical_lifecycle_enabled": False},
        )
        complete_whatsapp_inbound(inbound_claim, blocked, error="canonical_lifecycle_disabled")
        return blocked
    token = set_active_company_code(request_company_code(request))
    try:
        response = _whatsapp_turn_impl(request)
        complete_whatsapp_inbound(inbound_claim, response)
        return response
    except Exception as exc:
        failure = OrchestratorResponse(
            authoritative=True,
            reply_text="I hit an OctoHR backend issue before I could safely answer. Please try again in a moment.",
            final_reply_source="whatsapp_turn_error",
            intent="orchestrator_error",
            turn_focus="ingress",
            audit={"ingress_dedupe": {"claimed": bool(inbound_claim.get("claimed"))}},
        )
        complete_whatsapp_inbound(inbound_claim, failure, error=str(exc))
        return failure
    finally:
        reset_active_company_code(token)


def _whatsapp_turn_impl(request: WhatsAppTurnRequest):
    link_refresh = refresh_conversation_link_from_inbound(request)
    hr_link_refresh = refresh_hr_conversation_link_from_inbound(request)
    # Honour clear opt-out replies (STOP / unsubscribe / إلغاء الاشتراك ...) before
    # any routing, so a suppressed employee stops getting proactive WhatsApp.
    opt_out = maybe_handle_employee_opt_out(request)
    if opt_out is not None:
        return OrchestratorResponse(
            authoritative=True,
            reply_text=opt_out["reply"],
            final_reply_source="whatsapp_opt_out",
            intent="whatsapp_opt_out",
            turn_focus="opt_out",
            audit={
                "conversation_link_refresh": link_refresh,
                "hr_conversation_link_refresh": hr_link_refresh,
                "whatsapp_opt_out": {"company_code": opt_out.get("company_code")},
            },
        )
    if request.sender_role != "hr_admin" and not is_hr_phone(request.sender_phone):
        non_hr_response = handle_non_hr_conversational_turn(request)
        if non_hr_response:
            return OrchestratorResponse(
                authoritative=True,
                reply_text=non_hr_response.get("reply"),
                final_reply_source=str(non_hr_response.get("final_reply_source") or "non_hr_truth_handler"),
                intent=str(non_hr_response.get("intent") or "handle_non_hr_truth"),
                turn_focus=str(non_hr_response.get("turn_focus") or "non_hr_truth"),
                audit={
                    "conversation_link_refresh": link_refresh,
                    "hr_conversation_link_refresh": hr_link_refresh,
                    "non_hr_truth": non_hr_response,
                },
            )
        return OrchestratorResponse(
            authoritative=False,
            final_reply_source="not_hr",
            audit={"conversation_link_refresh": link_refresh, "hr_conversation_link_refresh": hr_link_refresh, "non_hr_truth": None},
        )
    try:
        from tool_call_orchestrator import handle_toolcall_whatsapp_turn

        result = handle_toolcall_whatsapp_turn(request)
        result["audit"] = {
            **(result.get("audit") or {}),
            "conversation_link_refresh": link_refresh,
            "hr_conversation_link_refresh": hr_link_refresh,
            "toolcall_orchestrator_enabled": True,
            "toolcall_orchestrator_primary": True,
        }
        return OrchestratorResponse(
            authoritative=bool(result.get("authoritative")),
            reply_text=result.get("reply_text"),
            final_reply_source=result.get("final_reply_source") or "toolcall_orchestrator",
            intent=result.get("intent"),
            turn_focus=result.get("turn_focus"),
            pending_action_id=str(result.get("pending_action", {}).get("action_id")) if result.get("pending_action") else None,
            audit=result.get("audit") or {},
        )
    except Exception as exc:
        print(f"toolcall_orchestrator_error: {exc}", flush=True)
        return OrchestratorResponse(
            authoritative=True,
            reply_text="I hit an OctoHR backend issue before I could safely answer. Please try again in a moment.",
            final_reply_source="toolcall_orchestrator_error",
            intent="orchestrator_error",
            turn_focus="toolcall_error",
            audit={
                "conversation_link_refresh": link_refresh,
                "hr_conversation_link_refresh": hr_link_refresh,
                "toolcall_orchestrator_enabled": True,
                "toolcall_orchestrator_primary": True,
                "toolcall_orchestrator_error": str(exc)[:500],
            },
        )

