class EmployeeDocEmailAttachment(BaseModel):
    filename: str
    content_base64: str
    mime_type: str | None = None
    expected_item: str | None = None


class EmployeeDocEmailIntakeRequest(BaseModel):
    company_code: str | None = None
    message_id: str
    sender: str | None = None
    subject: str | None = None
    recipient: str | None = None
    trusted_employee_key: str | None = None
    trusted_phone: str | None = None
    trusted_email: str | None = None
    attachments: list[EmployeeDocEmailAttachment]
    auto_attach: bool = True


@app.post("/orchestrator/posthire/documents/email-intake")
def posthire_documents_email_intake(
    request: EmployeeDocEmailIntakeRequest,
    principal: dict[str, Any] = Depends(require_internal_principal),
):
    """Inbound employee/compliance email attachments via shared processor (not CV path).

    Uncertain tenant/employee/type matches → durable review queue; never weak auto-link.

    R2: the tenant is derived from an authenticated routing source — a tenant
    principal, or the destination mailbox the message was delivered to. A
    `company_code` in the request body is descriptive only; if it disagrees with
    the routing authority the request is rejected rather than silently trusted.
    """
    import base64

    from kuwait_gcc_document_intelligence.email_intake import process_email_attachment

    ensure_schema()
    results: list[dict[str, Any]] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            company_code = _internal_authority.resolve_intake_company(
                _security_host(),
                cur,
                principal,
                route="/orchestrator/posthire/documents/email-intake",
                recipient=request.recipient,
                claimed=request.company_code,
            )
            for att in request.attachments or []:
                try:
                    raw = base64.b64decode(att.content_base64)
                except Exception:
                    results.append({"ok": False, "error": "invalid_base64", "filename": att.filename, "gpt_used": False})
                    continue
                results.append(
                    process_email_attachment(
                        cur=cur,
                        company_code=company_code,
                        message_id=request.message_id,
                        attachment_name=att.filename,
                        attachment_bytes=raw,
                        attachment_mime=att.mime_type,
                        sender=request.sender,
                        subject=request.subject,
                        recipient=request.recipient,
                        expected_item=att.expected_item,
                        trusted_employee_key=request.trusted_employee_key,
                        trusted_phone=request.trusted_phone,
                        trusted_email=request.trusted_email,
                        auto_attach=bool(request.auto_attach),
                    )
                )
        conn.commit()
    return {
        "ok": True,
        "company_code": company_code,
        "count": len(results),
        "results": results,
        "gpt_used": False,
        "shared_processor": "kuwait_gcc_document_intelligence",
    }


