# local-only: internal_intake_job_replay (from checkout L51266-51283)
@app.post("/orchestrator/debug/intake-jobs/{job_id}/replay")
def internal_intake_job_replay(
    job_id: str,
    company_code: str | None = Query(default=None),
    principal: dict[str, Any] = Depends(require_internal_principal),
):
    """Class A (tenant-scoped): replays one company's dead-letter job."""
    company_code = _internal_authority.authorize_company(
        _security_host(),
        principal,
        company_code,
        route="/orchestrator/debug/intake-jobs/{job_id}/replay",
    )
    try:
        result = _durable_email_ingress.replay_dead_letter(
            db_connect=db_connect,
            company_code=company_code,
            job_id=job_id,
            actor="internal_operator",
        )
    except _durable_email_ingress.IngressValidationError as exc:
        raise HTTPException(
            status_code=404 if exc.code == "intake_job_not_found" else 409,
            detail={"error": exc.code},
        ) from exc
    try:
        record_admin_audit(
            {
                "company_code": str(company_code or "").strip().upper(),
                "actor_user_id": "internal_operator",
            },
            "inbound_outage_replay",
            summary=f"Replayed dead-letter intake job {job_id}.",
            target_type="intake_job",
            target=job_id,
            details=result,
        )
    except Exception:
        pass
    return result


@app.post("/orchestrator/debug/intake-outage-replay")
def internal_intake_outage_replay(
    http_request: Request,
    company_code: str | None = Query(default=None),
    limit: int = Query(default=50),
    principal: dict[str, Any] = Depends(require_internal_principal),
    x_operator_id: str | None = Header(default=None, alias="X-Operator-Id"),
    x_break_glass_token: str | None = Header(default=None, alias="X-Break-Glass-Token"),
):
    """Sweep ClamAV/OCR outage dead-letters and requeue for replay.

    Class A when a company is named, Class B (break-glass) when it is not: an
    unscoped call touches every tenant's queue at once.
    """
    import inbound_enterprise_hardening as _ieh

    route = "/orchestrator/debug/intake-outage-replay"
    company = str(company_code or "").strip().upper() or None
    if _internal_authority.is_tenant_principal(principal) or company:
        company = _internal_authority.authorize_company(_security_host(), principal, company, route=route)
    else:
        _internal_authority.require_break_glass(
            _security_host(),
            principal,
            route=route,
            operation="intake_outage_replay_all_tenants",
            operator_id=x_operator_id,
            break_glass_token=x_break_glass_token,
            source=_rate_limit.client_source(http_request),
            target_company=None,
            destructive=False,
            detail={"limit": limit},
        )
    replayed: list[dict[str, Any]] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            rows = _ieh.list_outage_dead_letters(cur, company_code=company, limit=limit)
        conn.commit()
    for row in rows:
        try:
            result = _durable_email_ingress.replay_dead_letter(
                db_connect=db_connect,
                company_code=str(row.get("company_code") or ""),
                job_id=str(row.get("job_id") or ""),
                actor="outage_replay_sweep",
            )
            replayed.append({**result, "last_error_code": row.get("last_error_code")})
        except Exception as exc:
            replayed.append(
                {
                    "job_id": row.get("job_id"),
                    "company_code": row.get("company_code"),
                    "error": type(exc).__name__,
                }
            )
    try:
        record_admin_audit(
            {
                "company_code": company or "PLATFORM",
                "actor_user_id": "outage_replay_sweep",
            },
            "inbound_outage_replay",
            summary=f"Outage dead-letter sweep replayed {len(replayed)} jobs.",
            target_type="intake_jobs",
            target=company or "*",
            details={"count": len(replayed), "jobs": [r.get("job_id") for r in replayed]},
        )
    except Exception:
        pass
    return {"ok": True, "matched": len(rows), "replayed": replayed}

